CREATE OR REPLACE package body pk_pivot
as
  procedure formatparam(var_data in varchar2, var_type in number, out_decode in out varchar2, out_col in out varchar2);


  function pivotsql(p_query in varchar2, p_rowfields in varchar2, p_columnfield in varchar2, p_function in varchar2, p_functionfield in varchar2
, p_page in number default 1 )
    return varchar2
  as
    l_max_cols        number;
    l_query           long;
    l_columnnames     array_varchar2 := array_varchar2();
    l_cursor          refcursor;
    tmp               long;
    --dbms_sql types:
    l_thecursor       integer default dbms_sql.open_cursor ;                                                                           --get col types
    l_colcnt          number default 0 ;
    l_desctbl         dbms_sql.desc_tab;
    col_num           number;
    l_columnfieldtype number;
    --decode names
    o_decode          varchar2(50);
    o_col             varchar2(50);
    l_cols_per_page   number := 50;
    l_begcol          number;
    l_endcol          number;
  begin
    --check params
    if instr(p_columnfield, ',') > 0
    then
      raise_application_error(-20001, 'Can use only 1 columnfield');
    elsif upper(p_function) not in ('SUM', 'AVG', 'COUNT', 'MIN', 'MAX')
    then
      raise_application_error(-20001, 'Can use only standard aggregate functions');
    end if;


    /* analyse query */
    dbms_sql.parse(l_thecursor, p_query, dbms_sql.native);
    /* get described columns for analysed query */
    dbms_sql.describe_columns(l_thecursor, l_colcnt, l_desctbl);

    /* Tom Kyte:
    * Following loop could simply be for j in 1..col_cnt loop.


    Here we are simply illustrating some of the PL/SQL table
    features.
    */
    col_num := l_desctbl.first;

    loop
      exit when (col_num is null);

      --find column field type
      if l_desctbl(col_num).col_name = upper(p_columnfield)
      then
        l_columnfieldtype := l_desctbl(col_num).col_type;
      --dbms_output.put_line('Col#:'||col_num||' Name:'||l_descTbl(col_num).col_name||' Type:'||l_descTbl(col_num).col_type);
      end if;

      col_num := l_desctbl.next(col_num);
    end loop;

    --return 'test ok';

    -- figure out the column names we must support for horizontal cross
    if (p_columnfield is not null)
    then
      tmp :=
           'SELECT DISTINCT '
        || p_columnfield
        || ' FROM ('
        || p_query
        || ') ORDER BY '
        || p_columnfield;

      -- dbms_output.put_line('columns cursor:'||tmp);
      open l_cursor for tmp;

      loop
        l_columnnames.extend;

        fetch l_cursor into l_columnnames(l_columnnames.count);

        --dbms_output.put_line('l_columnnames:'||l_columnnames(l_columnnames.COUNT));
        exit when l_cursor%notfound;
      end loop;

      close l_cursor;
    -- execute immediate 'SELECT DISTINCT ' || p_columnfield || ' FROM (' || p_query || ')' bulk collect into l_columnnames ;

    else
      raise_application_error(-20001, 'Cannot figure out max cols');
    end if;

    -- Now, construct the query that can answer the question for us...
    l_query :=
      'SELECT '
      || p_rowfields;


    l_begcol :=
      l_cols_per_page
      * (p_page
         - 1)
      + 1;
    l_endcol :=
      l_cols_per_page
      * p_page;


    if l_begcol > l_columnnames.count
                  - 1
    then
      l_begcol :=
        l_columnnames.count
        - 1;
    end if;


    if l_endcol > l_columnnames.count
                  - 1
    then
      l_endcol :=
        l_columnnames.count
        - 1;
    end if;


    --for i in 1 .. l_columnnames.count-1 loop
    for i in l_begcol .. l_endcol
    loop
      formatparam(l_columnnames(i), l_columnfieldtype, o_decode, o_col);                                                               --format params
      l_query :=
           l_query
        || ','
        || p_function
        || '(DECODE('
        || p_columnfield
        || ','
        || o_decode
        || ','
        || p_functionfield
        || ',null)) as "'
        || o_col
        || '" ';                                                                                                             --" РїС—Р…РїС—Р…РїС—Р… РїС—Р…РїС—Р…РїС—Р…РїС—Р…РїС—Р… РїС—Р… РїС—Р…РїС—Р…РїС—Р…РїС—Р…РїС—Р…РїС—Р…РїС—Р…РїС—Р…РїС—Р…
    end loop;

    l_query :=
         l_query
      || ' FROM ('
      || p_query
      || ')';


    l_query :=
         l_query
      || ' GROUP BY '
      || p_rowfields
      || ' ORDER BY '
      || p_rowfields;


    /* close cursor */
    dbms_sql.close_cursor(l_thecursor);


    return l_query;
  exception
    when others
    then
      /* close cursor */
      dbms_sql.close_cursor(l_thecursor);
      raise_application_error(-20001, 'Error in PivotSQL:'
                                      || sqlerrm);
  end;

  --=========================


  procedure formatparam(var_data in varchar2, var_type in number, out_decode in out varchar2, out_col in out varchar2)
  --format parameter based on its type - for PivotSQL
  --get parameter and its type
  -- return strings for decode function and column name
  /* dbms_sql.describe_columns types:
  DATE Type:12
  Varchar2 Type:1
  Number Type:2
  */
  is
  begin
    if var_data is null
    then
      out_decode := 'NULL';
      out_col := '==NULL==';
    elsif var_type = 1
    then                                                                                                                                   -- Varchar2
      out_decode :=
           ''''
        || var_data
        || '''';                                                                                                                          --add quotes
      out_col := substr(var_data, 1, 30);
    elsif var_type = 2
    then                                                                                                                                      --Number
      out_decode := var_data;                                                                                                             --do nothing
      out_col := substr(var_data, 1, 30);
    elsif var_type = 12
    then                                                                                                                                        --DATE
      out_decode :=
           'to_date('''
        || var_data
        || ''')';                                                                                                            --format as internal date
      out_col := to_char(to_date(var_data), 'YYYY-MM-DD');
    else
      out_decode :=
        '== UNDEFINED TYPE:'
        || var_type;
      out_col := '== UNDEFINED TYPE';
    end if;
  exception
    when others
    then
      raise_application_error(-20001, 'Error in FormatParam:'
                                      || sqlerrm);
  end;
end;
/


CREATE OR REPLACE package body PRIHOD is
  function prihod_is_closed(ord_id int) return int is
    cond1 number;
  begin
    select nvl(condition, 0) into cond1 from RRL_PRIHOD_NAKLAD where id = ord_id;
    if cond1 >= 2 then return 1; end if;
    return 0;
  exception
    when no_data_found then return -1;
  end;

  function close_price_control(prih_id int) return int is
    cond1 number;
    prooved1 number;
    vehicle1 varchar2(50);
  begin
    select nvl(condition, 0), nvl(prooved, 0), vechile_number
      into cond1, prooved1, vehicle1
      from RRL_PRIHOD_NAKLAD
     where id = prih_id;

    if cond1 >= 2 then return 3; end if;
    if prooved1 >= 1 then return 2; end if;
    if vehicle1 is null then return -4; end if;

    update RRL_PRIHOD_NAKLAD
       set prooved = 1,
           priority1 = nvl(priority1, 10),
           checking_time = nvl(checking_time, sysdate)
     where id = prih_id;
    return 1;
  exception
    when no_data_found then return -1;
  end;

  function set_brak_perc_new(puid1 varchar2, new_perc number, reason_id int) return int is
    old_perc number;
    reason_name varchar2(255);
    hist_id number;
  begin
    select nvl(defect_perc, 0) into old_perc from RRL_PALLETS where uid_pallet = puid1;
    begin
      select name into reason_name from RRL_PALL_TRASH_REASON where id = reason_id;
    exception
      when no_data_found then reason_name := to_char(reason_id);
    end;

    update RRL_PALLETS
       set defect_perc = new_perc,
           reason_id = reason_id
     where uid_pallet = puid1;

    select RRL_PALLETS_HIST_SQ.nextval into hist_id from dual;
    insert into RRL_PALLETS_HIST (ID, PUID, TYPE, DEF_PERC_BEFORE, DEF_PERC_AFTRER, DEF_PERC_REASON, EVENT_TIME)
    values (hist_id, puid1, 'DEFECT_PERCENT', old_perc, new_perc, reason_name, sysdate);

    return 1;
  exception
    when no_data_found then return -1;
    when others then return 0;
  end;

  function set_dock(prih_id int, h_dock varchar2) return int is
  begin
    update RRL_PRIHOD_NAKLAD
       set dock = h_dock,
           invite_time = nvl(invite_time, sysdate)
     where id = prih_id
       and nvl(condition, 0) < 2;
    if sql%rowcount = 0 then return 0; end if;
    return 1;
  end;

  function set_ware_id(prih_id int, new_ware_id int) return int is
  begin
    update RRL_PRIHOD_NAKLAD
       set ware_id = new_ware_id
     where id = prih_id
       and nvl(condition, 0) < 2;
    if sql%rowcount = 0 then return 0; end if;
    return 1;
  end;

  function set_priority(prih_id int, new_priority_id int, new_user_id varchar2) return int is
  begin
    update RRL_PRIHOD_NAKLAD
       set priority1 = new_priority_id
     where id = prih_id
       and nvl(condition, 0) < 2;
    if sql%rowcount = 0 then return 0; end if;
    return 1;
  end;

  function set_prihod_kpp(prihod_id int, kpp_n varchar2) return int is
  begin
    update RRL_PRIHOD_NAKLAD
       set ohrana_kpp = kpp_n,
           invite_time = sysdate
     where id = prihod_id
       and nvl(condition, 0) < 2;
    if sql%rowcount = 0 then return 0; end if;
    return 1;
  end;

  function is_prihod_fresh(prihod_id int) return varchar2 is
    invite1 date;
  begin
    select invite_time into invite1 from RRL_PRIHOD_NAKLAD where RRL_PRIHOD_NAKLAD.id = is_prihod_fresh.prihod_id;
    if invite1 is null then return '0'; end if;
    if invite1 >= sysdate - (10 / 1440) then
      return unistr('\0432\044B\0437\043E\0432');
    end if;
    return '1';
  exception
    when no_data_found then return '0';
  end;

  function prihod_pall_count(prihod_naklad_id int) return int is
    cnt int;
  begin
    select count(*) into cnt from RRL_PALLETS where PRIHOD_NAKLAD_ID = prihod_naklad_id;
    return cnt;
  end;

  function get_brak_reason(reason_id int) return varchar2 is
    reason_name varchar2(255);
  begin
    select name into reason_name from RRL_PALL_TRASH_REASON where id = reason_id;
    return reason_name;
  exception
    when no_data_found then return null;
  end;

  function order_zakaz_number(prihod_naklad_id int) return varchar2 is
    zakaz varchar2(255);
  begin
    select zakaz_number into zakaz from RRL_PRIHOD_NAKLAD where id = prihod_naklad_id;
    return zakaz;
  exception
    when no_data_found then return null;
  end;
end PRIHOD;
/


CREATE OR REPLACE package body REMAINS is
  function create_snapshot(type2 int) return int is
    id1 int;
  begin
    select RRL_REMAIN_SNAPSHOT_SQ.nextval into id1 from dual;
    insert into RRL_REMAIN_SNAPSHOT (ID, TYPE1, CREATE_TIME, SNAP_SHOT_TIME, CLOSED)
    values (id1, type2, systimestamp, systimestamp, 0);
    return id1;
  end;
  function add_row_2_snapshot(snap_shot_id1 int, cell1 varchar, articul1 varchar2) return int is
    tmp int;
    ware_id1 int;
    id1 int;
    snap_time1 date;
    cursor sss is
      select rm.uid_poleta, rm.remain
        from rrl_remains rm
        join rrl_pallets pts on pts.uid_pallet = rm.uid_poleta
       where rm.cell = cell1
         and pts.articul = articul1;
  begin
    if cell1 is null or articul1 is null then
      return -1;
    end if;
    select closed, snap_shot_time into tmp, snap_time1
      from RRL_REMAIN_SNAPSHOT where ID = snap_shot_id1;
    if tmp = 1 then
      return -1;
    end if;
    begin
      select ID into id1 from RRL_REMAIN_SNAPSHOT_ROWS
       where ARTICUL = articul1 and CELL = cell1 and SNAP_SHOT_ID = snap_shot_id1;
      return id1;
    exception when no_data_found then null;
    end;
    select ware_id into ware_id1 from rrl_cells where cell = cell1;
    for s in sss loop
      select RRL_REMAIN_SNAPSHOT_ROWS_SQ.nextval into id1 from dual;
      insert into RRL_REMAIN_SNAPSHOT_ROWS (ID, ARTICUL, CELL, PALLET_UID, REMAIN, WARE_ID, CONDITION, SNAP_SHOT_ID, SNAP_TIME)
      values (id1, articul1, cell1, s.uid_poleta, s.remain, ware_id1, 0, snap_shot_id1, snap_time1);
    end loop;
    return 1;
  exception
    when no_data_found then return -2;
  end;
  function close_snapshot(snap_shot_id1 int) return int is
    time_shot date;
  begin
    time_shot := systimestamp;
    update RRL_REMAIN_SNAPSHOT set CLOSED = 1, SNAP_SHOT_TIME = time_shot where ID = snap_shot_id1;
    return 1;
  end;
  function remains_free(articul1 varchar2) return number is
    tmp number;
  begin
    select nvl(sum(rem.remain), 0) into tmp
      from rrl_remains rem
      join rrl_cells cel on rem.cell = cel.cell
      join rrl_pallets pts on rem.uid_poleta = pts.uid_pallet
     where cel.blocked_for_remains = 0
       and pts.articul = articul1
       and rem.remain > 0
       and nvl(cel.otbor, 0) = 0;
    return tmp;
  exception when others then return 0; end;
  function remains_in_otbor(articul1 varchar2) return number is
    tmp number;
  begin
    select nvl(sum(rem.remain), 0) into tmp
      from rrl_remains rem
      join rrl_cells cel on rem.cell = cel.cell
      join rrl_pallets pts on rem.uid_poleta = pts.uid_pallet
     where pts.articul = articul1
       and rem.remain > 0
       and nvl(cel.otbor, 0) = 1;
    return tmp;
  exception when others then return 0; end;
  function remains_in_otbor_all(articul1 varchar2) return number is
  begin
    return remains_in_otbor(articul1);
  end;
  function remains_free_all(articul1 varchar2) return number is
    tmp number;
  begin
    select nvl(sum(rem.remain), 0) into tmp
      from rrl_remains rem
      join rrl_pallets pts on rem.uid_poleta = pts.uid_pallet
     where pts.articul = articul1
       and rem.remain > 0;
    return tmp;
  exception when others then return 0; end;
  function remains_partion_in_cell(pallet_uid1 varchar2, cell3 varchar2) return number is
    tmp number;
  begin
    select nvl(sum(remain), 0) into tmp
      from rrl_remains
     where uid_poleta = pallet_uid1
       and cell = cell3
       and remain > 0;
    return tmp;
  exception when others then return 0; end;
  function remains_partion_in_otbor(pallet_uid1 varchar2) return number is
    tmp number;
  begin
    select nvl(sum(rm.remain), 0) into tmp
      from rrl_remains rm
      join rrl_cells cl on rm.cell = cl.cell
     where rm.uid_poleta = pallet_uid1
       and rm.remain > 0
       and nvl(cl.otbor, 0) = 1;
    return tmp;
  exception when others then return 0; end;
  function remains_except_part_in_otb(pallet_uid1 varchar2) return number is
    tmp number;
  begin
    select nvl(sum(rm.remain), 0) into tmp
      from rrl_remains rm
      join rrl_cells cl on rm.cell = cl.cell
      join rrl_pallets p on rm.uid_poleta = p.uid_pallet
      join rrl_pallets src on src.uid_pallet = pallet_uid1
     where p.articul = src.articul
       and rm.uid_poleta <> pallet_uid1
       and rm.remain > 0
       and nvl(cl.otbor, 0) = 1;
    return tmp;
  exception when others then return 0; end;
