function revision_cell_kor( cell1 varchar2 , revision_id1 int , count2 number , user_id3 varchar2 ) return varchar2 is
rem5  varchar2(1024);
rem4  varchar2(255);
revision_row_id2 int;
condition2 int;
begin 

      begin  
         select rev.condition into condition2 from rrl_revizion rev where rev.id= revision_id1;
         if( condition2=2 ) then
             return unistr('\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026 \0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026');
         end if;
         exception 
           when no_data_found then return unistr('\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026 \0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026');
      end;  
  
      begin  
           select id  into revision_row_id2 from RABAEV.RRL_REVISION_ROW where cell=cell1 and REVISION_ID = revision_id1  and rownum<=1 ;  
           exception 
             when no_data_found then revision_row_id2:=add_row_2_revizion(cell1 , revision_id1 ) ;
      end;  
      
      
    rem4 := RABAEV.RRL_REVIZION_CELL_KOR( CELL1  ,    count2 ,    user_id3 )  ;
    
    rem5 :=concat( concat( unistr(' \0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026=') , to_char(count2) ) , concat( unistr('\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026. \0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026=') , to_char( sysdate )  ));
    update RABAEV.RRL_REVISION_ROW set remark1= concat (remark1 , concat(rem5, rem4) )   , 
      count_kor=count2
     where id=revision_row_id2 ;
     return rem4;
      

end;



