function  RRL_REVIZION_CELL_PALL( 
   articul1 varchar2, CELL1 varchar2 , count_pal int , revision_row_id1 int , 
    user_id1 varchar2 ) return varchar2

 


is
new_event_uid int;
tmp varchar2 (250);
count_pal_fixed int;
counter_invent_p int;
/*cursor rema_in_p  is 
  select sum(rm.REMAIN) as RM1 , count( DISTINCT rm.UID_POLETA ) kk , 
  rm.UID_POLETA 
  from rrl_remains rm , rrl_pallets pal 
  where rm.CELL='INVENT_P' and pal.UID_PALLET=rm.UID_POLETA
    and    pal.ARTICUL=articul1  and rm.REMAIN>0
  order by    pal.EXPIRY_DATE asc; */


rows_cnt int;
cursor rema is select  rm.REMAIN   , rm.UID_POLETA 
  from rrl_remains rm , rrl_pallets pal 
  where rm.CELL=CELL1 and pal.UID_PALLET=rm.UID_POLETA and  pal.ARTICUL=articul1 
    and  rm.REMAIN  >0 
  order by pal.EXPIRY_DATE desc;

cursor rema_invent_p  is select  rm.REMAIN   , rm.UID_POLETA 
  from rrl_remains rm , rrl_pallets pal 
  where rm.CELL='INVENT_P' and pal.UID_PALLET=rm.UID_POLETA and  pal.ARTICUL=articul1 
    and  rm.REMAIN  >0 
  order by pal.EXPIRY_DATE desc;

begin
count_pal_fixed:=0;
rows_cnt:=0;


for rrow in rema loop
  rows_cnt:=rows_cnt+1;
    count_pal_fixed:=count_pal_fixed+1;
    if(count_pal_fixed>count_pal) then 
        tmp := RABAEV.RRL_INTERNAL_MOVE2(
            rrow.UID_POLETA ,  'INVENT_P' ,
            rrow.remain , user_id1 );
     end if;
end loop;

if( count_pal_fixed>count_pal  ) then
tmp:= concat( unistr('\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026 ') , concat( to_char( count_pal_fixed-count_pal ) , unistr(' \0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026')));
end if;

if( count_pal_fixed < count_pal  ) then
tmp:= concat( unistr('\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026 ') , concat( to_char(count_pal- count_pal_fixed ) , unistr(' \0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026')));
counter_invent_p:=0;
      for rrow2 in rema_invent_p loop 
          counter_invent_p:=counter_invent_p+1;    
          if(  counter_invent_p<=count_pal-count_pal_fixed ) then
          
           SELECT RABAEV.RRL_EVENT_ID_SQ.NEXTVAL INTO new_event_uid  FROM dual;
           
           insert into rrl_events ( ID_EVENT  ,  cell_from ,cell_to , date_event ,count_event,
           type_event,uid_poleta,user_id ) 
           values (new_event_uid, 'INVENT_P' , CELL1 , systimestamp , 
           rrow2.remain ,2 ,rrow2.uid_poleta, user_id1 );
          
          end if;
      end loop;
end if;

if( count_pal_fixed = count_pal  ) then
 tmp:= 'ok';
end if;
 
update RRL_REVISION_ROW set REMARK1 = tmp , NUM_OF_PALL=count_pal  where id=revision_row_id1;
commit;
return tmp;

exception 
       when no_data_found then  return 'neok';
       when others then raise;


END;



function  RRL_REVIZION_CLEAR_MINUS( revision_id1 int , user_id1 varchar2 ) return int is
 new_event_uid int;
 cell4 varchar2(255);
 tmp varchar2(255);
 articul5 varchar2(255);
 
 cursor cells1  is select distinct rr.cell , rr.articul1 from rrl_revision_row rr 
 where rr.revision_id=revision_id1 ;

 cursor min_rem is select rem1.cell , rem1.uid_poleta , rem1.remain 
        from rrl_remains rem1 , rrl_pallets pts where pts.uid_pallet=rem1.uid_poleta and
        pts.articul = articul5 and  rem1.cell=cell4 and rem1.remain<0;

begin

    for cell3 in cells1 loop
    cell4:=cell3.cell;    
    articul5:=cell3.articul1;
        for rrow in min_rem loop   
           SELECT RABAEV.RRL_EVENT_ID_SQ.NEXTVAL INTO new_event_uid  FROM dual;           
           insert into rrl_events ( ID_EVENT  ,  cell_from ,cell_to , date_event ,count_event,
           type_event,uid_poleta,user_id ) 
           values (new_event_uid , CELL4 , 'INVENT_P'  , systimestamp , 
           rrow.remain ,2 ,rrow.uid_poleta, user_id1 );
        end loop;
        
    end loop;
    commit;
return 1;
end;

function  RRL_REVIZION_CELL_SHT( 
   articul1 varchar2, CELL1 varchar2 , count_sht number , revision_row_id1 int , 
    user_id1 varchar2 ) return varchar2

 


is
new_event_uid int;
tmp varchar2 (250);
counter_invent_p number;
to_spis number;



cursor rema is select  rm.REMAIN   , rm.UID_POLETA 
  from rrl_remains rm , rrl_pallets pal 
  where rm.CELL=CELL1 and pal.UID_PALLET=rm.UID_POLETA and  pal.ARTICUL=articul1 
    and  rm.REMAIN  >0 
  order by pal.EXPIRY_DATE desc;

cursor rema_invent_p  is select  rm.REMAIN   , rm.UID_POLETA 
  from rrl_remains rm , rrl_pallets pal 
  where rm.CELL='INVENT_P' and pal.UID_PALLET=rm.UID_POLETA and  pal.ARTICUL=articul1 
    and  rm.REMAIN  >0 
  order by pal.EXPIRY_DATE desc;

count_sht_rem number;
how_many_return number;

begin


count_sht_rem:= 0;
to_spis:=0;


for rrow in rema loop



     count_sht_rem:=count_sht_rem+rrow.remain;
    if( count_sht_rem>count_sht ) then
        if( count_sht_rem-count_sht>rrow.remain ) then
                   tmp := RABAEV.RRL_INTERNAL_MOVE2(
                      rrow.UID_POLETA ,  'INVENT_P' ,
                      rrow.remain , user_id1 );
            else
                   tmp := RABAEV.RRL_INTERNAL_MOVE2(
                      rrow.UID_POLETA ,  'INVENT_P' ,
                      count_sht_rem-count_sht , user_id1 );
        end if;
    end if;
   
              
end loop;


if( count_sht_rem=count_sht  ) then
    tmp:= 'ok';
end if;


if( count_sht_rem-count_sht>0  ) then
tmp:= concat( unistr('\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026 ') , concat( to_char( count_sht_rem-count_sht ) , unistr(' \0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026')));
end if;

if( count_sht_rem-count_sht<0  ) then
tmp:= concat( unistr('\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026 ') , concat( to_char( -count_sht_rem+count_sht ) , unistr(' \0420\0457\0421\2014\0420\2026\0420\0457\0421\2014\0420\2026')));
counter_invent_p:=0;
how_many_return:=-count_sht_rem+count_sht;

      for rrow2 in rema_invent_p loop 
          counter_invent_p:=counter_invent_p+rrow2.remain;
          if( how_many_return>0 ) then        
              if( rrow2.remain>how_many_return ) then
                  to_spis:=how_many_return;
                  how_many_return:=0;
              else
                  to_spis:=rrow2.remain;
                  how_many_return:=how_many_return-rrow2.remain;
              end if;

           SELECT RABAEV.RRL_EVENT_ID_SQ.NEXTVAL INTO new_event_uid  FROM dual;           
           insert into rrl_events ( ID_EVENT  ,  cell_from ,cell_to , date_event ,count_event,
           type_event,uid_poleta,user_id ) 
           values (new_event_uid, 'INVENT_P' , CELL1 , systimestamp , 
          /* rrow2.remain */ to_spis ,2 ,rrow2.uid_poleta, user_id1 );

          end if;
      end loop;
      
end if;


 
update RRL_REVISION_ROW set REMARK1 = tmp , count1=count_sht  where id=revision_row_id1;
commit;
return tmp;

exception 
       when no_data_found then  return 'neok';
       when others then raise;


END;



function CreateNaklad_2_revizion( rev_id1 int ) return int is
         rev_naklad_id1 int;
         ret int;
         ware_id3 int;
begin

  select r.rev_naklad_id , ware_id into rev_naklad_id1 , ware_id3 from rrl_revizion r where id= rev_id1;
  if( not rev_naklad_id1 is null ) and (  rev_naklad_id1 >0 ) then
      return rev_naklad_id1;
  end if;

  ret:=ADD_RRL_PRIH_NAKLAD2( NAKLAD_NUMBER => concat( 'INV_' , to_char(rev_id1) ) , 
                         DATE_OF_NAKLAD => sysdate ,DATE_OF_ACCEPT => sysdate,
                         POSTAVSHIK_NAME => 'INV', 
                         SM_NAKLAD_NUMBER => concat( 'INV_' , to_char(rev_id1) ) ,
                         ZAKAZ_NUMBER1 => concat( 'INV_' , to_char(rev_id1) ) ,
                         ware_id1 => ware_id3 );
               
  if( ret>0 ) then
      update RABAEV.RRL_PRIHOD_NAKLAD set condition=2 where id=ret;
      update  rrl_revizion set rev_naklad_id=ret where id= rev_id1;
  end if;
            
  return ret;
exception
  when no_data_found then return -1;
  when others then return -2;
end;




FUNCTION  RRL_INV_CREATE_LINE5 
( 
    cell1 varchar2 ,
    articul2 varchar2,
    count1 NUMBER ,
    expiury_date date ,
    fasovka_id1 int ,
    brak_perc1 number ,
    pall_weight1 number , 
    pall_n int ,
    tn_weight1 number ,
    count_kor1 number ,
    user_id2 varchar2 , 
    NAKLAD_ID int
)
    RETURN varchar2 IS 
    price Number;
    ret2 varchar2(255);
    event_id int;
    pallet_name varchar2(255);


BEGIN

pallet_name:= CONCAT( Concat( Concat( Concat('P_' , articul2 ) , '_G3_') , cell1) , concat( '_' ,to_char(pall_n) ) ) ;
pallet_name:=replace(pallet_name , unistr('\0420\0457\0421\2014\0420\2026') ,'T' );
begin
        insert into RABAEV.RRL_PALLETS
        (
          UID_PALLET       ,
          ARTICUL           ,
          CREATION_DATE     ,
          EXPIRY_DATE       ,
          UNIT_COUNT        ,
          PRICE             ,
          PRIHOD_NAKLAD_ID  
        )values
        (
            pallet_name , 
            articul2 ,
            sysdate ,
            expiury_date ,
            count1 , 
            1,
            NAKLAD_ID
        );
        exception
          when others then return 'EXISTS';
end;


 select RRL_EVENT_ID_SQ.NEXTVAL into event_id from dual;
 event_id:=event_id+1;
        
insert into RABAEV.RRL_EVENTS
            (  ID_EVENT ,  
            CELL_FROM , 
            CELL_TO    ,    
            DATE_EVENT  ,  
            DATE_OF_ORDER,   
            COUNT_EVENT   , 
            TYPE_EVENT  ,  
            UID_POLETA    ,
            USER_ID  ,  
            PRIHOD_NAKL_ID ) values (
          event_id ,
          'IN_ACCEPT',
          CELL1 ,
          expiury_date , 
          expiury_date , 
          count1 , 
          1 ,
          pallet_name ,
          user_id2 ,
          NAKLAD_ID 
            );
    
    ret2:=RABAEV.RRL_PRIHODPALLET_CHANGE(PALLET_UID1 => pallet_name ,art => articul2 ,
        UNIT_COUNT1 => count1 ,DEFECT_PERC1 => brak_perc1 ,COUNT_KOR1 => count_kor1 ,
        WEIGHT_BRUTTO1 => pall_weight1 , WEIGHT_TN1 => tn_weight1 ,MOD_ID1 => fasovka_id1 );

return pallet_name;

END ;



FUNCTION  close_revision( rev_id int ) return int is
  tmp int;
begin
  
  tmp:= REVIZION_SP_OLD.rev_create_snap_shot_after( rev_id );
  update rrl_revizion rev set rev.condition=2 where rev.id=rev_id;
  
  return 1;
end;




function rev_create_snap_shot_before( rev_id int ) return int is
    snap_id1 int;
    tmp int;
    cursor sss is select rs.cell , rs.articul1  
     from rrl_revision_row rs where rs.revision_id = rev_id ;
begin
 
  select rv.SNAPSHOT_BEFORE into snap_id1 
         from rrl_revizion rv where id= rev_id;
  if( snap_id1 is null ) then
  update rrl_revizion set condition=1 where ID= rev_id;
  
      snap_id1 := REMAINS.create_snapshot(type2 => 1);
      update rrl_revizion set SNAPSHOT_BEFORE=snap_id1 where  id= rev_id;
      for s in sss loop
          tmp:=REMAINS.add_row_2_snapshot(snap_shot_id1 => snap_id1 ,cell1 => s.cell ,articul1 => s.articul1);
      end loop;
      
      return snap_id1;
  else
      return snap_id1;
  end if;
return snap_id1;
end;



function rev_create_snap_shot_after( rev_id int ) return int is
    snap_id1 int;
    tmp int;
    cursor sss is select rs.cell , rs.articul1  
     from rrl_revision_row rs where rs.revision_id = rev_id ;
begin
 
  select rv.SNAPSHOT_AFTER into snap_id1 
         from rrl_revizion rv where id= rev_id;
  if( snap_id1 is null ) then
      snap_id1 := REMAINS.create_snapshot(type2 => 2);
      update rrl_revizion set SNAPSHOT_AFTER=snap_id1 where  id= rev_id;
      for s in sss loop
          tmp:=REMAINS.add_row_2_snapshot(snap_shot_id1 => snap_id1 ,cell1 => s.cell ,articul1 => s.articul1);
      end loop;
      
      return snap_id1;
  else
      return snap_id1;
  end if;
return snap_id1;
end;


function remain_before( rev_id int ,articul1 varchar2 , cell1 varchar2  ) return number is
 snap_before int;
 snap_after int;
ret number;
begin

    select rr.snapshot_before , rr.snapshot_after 
    into snap_before ,  snap_after
     from rrl_revizion rr 
    where rr.id=rev_id;
    
    
  select sum(rsr.remain) into ret from rrl_remain_snapshot_rows rsr where rsr.snap_shot_id = snap_before and 
  rsr.articul = articul1 and rsr.cell=cell1 ;
return ret;
exception     
       when no_data_found then return null;
       when others then return -9999;
end;


function remain_after( rev_id int ,articul1 varchar2 , cell1 varchar2  ) return number is
 snap_before int;
 snap_after int;
ret number;
begin

    select rr.snapshot_before , rr.snapshot_after 
    into snap_before ,  snap_after
     from rrl_revizion rr 
    where rr.id=rev_id;

  select sum(rsr.remain) into ret from rrl_remain_snapshot_rows rsr where rsr.snap_shot_id = snap_after and 
  rsr.articul = articul1 and rsr.cell=cell1 ;
return ret;
exception     
       when no_data_found then return null;
       when others then return -9999;
end;



begin
null;
end REVIZION_SP_OLD;
/


CREATE OR REPLACE package body RRL_API_AUDIT_API as
  function start_call(
    p_request_id             varchar2,
    p_replay_of_call_id      number default null,
    p_replay_run_id          varchar2 default null,
    p_method                 varchar2,
    p_path                   varchar2,
    p_query_string           varchar2 default null,
    p_url                    varchar2 default null,
    p_client_ip              varchar2 default null,
    p_user_agent             varchar2 default null,
    p_request_headers_json   clob default null,
    p_request_body           clob default null,
    p_request_body_sha256    varchar2 default null,
    p_request_body_truncated number default 0,
    p_replayable             number default 1,
    p_local_log_path         varchar2 default null
  ) return number is
    v_id number;
  begin
    begin
      select API_CALL_ID
        into v_id
        from RRL_API_CALL_LOG
       where REQUEST_ID = p_request_id;
      return v_id;
    exception
      when no_data_found then null;
    end;

    select RRL_API_CALL_LOG_SQ.nextval into v_id from dual;

    insert into RRL_API_CALL_LOG (
      API_CALL_ID, REQUEST_ID, REPLAY_OF_CALL_ID, REPLAY_RUN_ID,
      METHOD, PATH, QUERY_STRING, URL, CLIENT_IP, USER_AGENT,
      REQUEST_HEADERS_JSON, REQUEST_BODY, REQUEST_BODY_SHA256,
      REQUEST_BODY_TRUNCATED, STATUS, REPLAYABLE, LOCAL_LOG_PATH, STARTED_AT, CREATED_AT
    ) values (
      v_id, p_request_id, p_replay_of_call_id, p_replay_run_id,
      upper(p_method), substr(p_path, 1, 1000), substr(p_query_string, 1, 4000), substr(p_url, 1, 4000),
      substr(p_client_ip, 1, 100), substr(p_user_agent, 1, 1000),
      p_request_headers_json, p_request_body, p_request_body_sha256,
      nvl(p_request_body_truncated, 0), 'STARTED', nvl(p_replayable, 1), p_local_log_path, sysdate, sysdate
    );

    return v_id;
  end start_call;

  procedure finish_call(
    p_api_call_id            number,
    p_response_status        number default null,
    p_response_headers_json  clob default null,
    p_response_body          clob default null,
    p_response_body_truncated number default 0,
    p_error_text             varchar2 default null,
    p_status                 varchar2 default 'DONE',
    p_duration_ms            number default null,
    p_local_log_path         varchar2 default null
  ) is
  begin
    update RRL_API_CALL_LOG
       set RESPONSE_STATUS = p_response_status,
           RESPONSE_HEADERS_JSON = p_response_headers_json,
           RESPONSE_BODY = p_response_body,
           RESPONSE_BODY_TRUNCATED = nvl(p_response_body_truncated, 0),
           ERROR_TEXT = substr(p_error_text, 1, 4000),
           STATUS = nvl(p_status, 'DONE'),
           FINISHED_AT = sysdate,
           DURATION_MS = p_duration_ms,
           LOCAL_LOG_PATH = nvl(p_local_log_path, LOCAL_LOG_PATH)
     where API_CALL_ID = p_api_call_id;
  end finish_call;

  procedure mark_replay_result(
    p_source_call_id         number,
    p_replay_call_id         number default null,
    p_error_text             varchar2 default null
  ) is
  begin
    update RRL_API_CALL_LOG
       set REPLAY_COUNT = nvl(REPLAY_COUNT, 0) + 1,
           LAST_REPLAY_AT = sysdate,
           LAST_REPLAY_CALL_ID = nvl(p_replay_call_id, LAST_REPLAY_CALL_ID),
           LAST_REPLAY_ERROR = substr(p_error_text, 1, 4000)
     where API_CALL_ID = p_source_call_id;
  end mark_replay_result;
end RRL_API_AUDIT_API;
/


CREATE OR REPLACE package body RRL_BOM_API as
  procedure write_audit(
    p_bom_id       number,
    p_action_type  varchar2,
    p_old_status   varchar2 default null,
    p_new_status   varchar2 default null,
    p_message      varchar2 default null,
    p_payload_json clob default null,
    p_created_by   varchar2 default null
  ) is
    v_id number;
    v_trace_id number;
  begin
    select RRL_BOM_AUDIT_SQ.nextval into v_id from dual;

    insert into RRL_BOM_AUDIT (
      BOM_AUDIT_ID, BOM_ID, ACTION_TYPE, OLD_STATUS, NEW_STATUS,
      MESSAGE, PAYLOAD_JSON, CREATED_AT, CREATED_BY
    ) values (
      v_id, p_bom_id, substr(upper(p_action_type), 1, 50),
      substr(p_old_status, 1, 30), substr(p_new_status, 1, 30),
      substr(p_message, 1, 1000), p_payload_json, sysdate, substr(p_created_by, 1, 50)
    );

    begin
      v_trace_id := RRL_TRACEABILITY_API.add_trace_event(
        p_event_type => p_action_type,
        p_entity_type => 'BOM',
        p_entity_id => to_char(p_bom_id),
        p_source_system => 'WMS_API',
        p_payload_json => p_payload_json,
        p_created_by => p_created_by
      );
    exception
      when others then
        null;
    end;
  end write_audit;

  procedure assert_draft(p_bom_id number) is
    v_status RRL_BOM.STATUS%type;
  begin
    select STATUS into v_status
      from RRL_BOM
     where BOM_ID = p_bom_id;

    if v_status <> 'DRAFT' then
      raise_application_error(-20090, 'BOM can be edited only in DRAFT status.');
    end if;
  exception
    when no_data_found then
      raise_application_error(-20091, 'BOM not found.');
  end assert_draft;

  procedure assert_primary_available(p_bom_id number) is
    v_target_articul RRL_BOM.TARGET_ARTICUL%type;
    v_target_mod_id RRL_BOM.TARGET_MOD_ID%type;
    v_ware_id RRL_BOM.WARE_ID%type;
    v_production_line RRL_BOM.PRODUCTION_LINE%type;
    v_valid_from RRL_BOM.VALID_FROM%type;
    v_valid_to RRL_BOM.VALID_TO%type;
    v_count number;
  begin
    select TARGET_ARTICUL, TARGET_MOD_ID, WARE_ID, PRODUCTION_LINE, VALID_FROM, VALID_TO
      into v_target_articul, v_target_mod_id, v_ware_id, v_production_line, v_valid_from, v_valid_to
      from RRL_BOM
     where BOM_ID = p_bom_id;

    select count(*)
      into v_count
      from RRL_BOM b
     where b.BOM_ID <> p_bom_id
       and b.TARGET_ARTICUL = v_target_articul
       and nvl(b.TARGET_MOD_ID, -1) = nvl(v_target_mod_id, -1)
       and nvl(b.WARE_ID, -1) = nvl(v_ware_id, -1)
       and nvl(upper(b.PRODUCTION_LINE), '~') = nvl(upper(v_production_line), '~')
       and b.IS_PRIMARY = 1
       and b.STATUS in ('APPROVED', 'ACTIVE')
       and nvl(b.VALID_TO, date '2999-12-31') >= v_valid_from
       and nvl(v_valid_to, date '2999-12-31') >= b.VALID_FROM;

    if v_count > 0 then
      raise_application_error(-20092, 'Another primary BOM already exists for this product and period.');
    end if;
  end assert_primary_available;

  procedure validate_period(p_valid_from date, p_valid_to date) is
  begin
    if p_valid_from is null then
      raise_application_error(-20093, 'BOM valid_from is required.');
    end if;
    if p_valid_to is not null and p_valid_to < p_valid_from then
      raise_application_error(-20094, 'BOM valid_to cannot be earlier than valid_from.');
    end if;
  end validate_period;

  procedure validate_line(
    p_component_type varchar2,
    p_component_articul varchar2,
    p_component_name varchar2,
    p_qty_per_base number
  ) is
    v_type varchar2(30) := upper(nvl(p_component_type, 'RAW'));
  begin
    if v_type not in ('RAW', 'SEMIFINISHED', 'PACKAGING', 'ADDITIVE', 'SERVICE') then
      raise_application_error(-20095, 'Unsupported BOM component type.');
    end if;

    if p_component_articul is null and p_component_name is null then
      raise_application_error(-20096, 'BOM line component articul or name is required.');
    end if;

    if v_type <> 'SERVICE' and nvl(p_qty_per_base, 0) <= 0 then
      raise_application_error(-20097, 'BOM material line qty_per_base must be greater than zero.');
    end if;
  end validate_line;

  function create_bom(
    p_bom_code         varchar2,
    p_bom_name         varchar2 default null,
    p_target_articul   varchar2,
    p_target_mod_id    number default null,
    p_target_gtin      varchar2 default null,
    p_bom_kind         varchar2 default 'FINISHED_GOODS',
    p_base_qty         number,
    p_base_unit_code   varchar2 default 'KG',
    p_is_primary       number default 0,
    p_valid_from       date,
    p_valid_to         date default null,
    p_ware_id          number default null,
    p_production_line  varchar2 default null,
    p_comment_text     varchar2 default null,
    p_created_by       varchar2 default null
  ) return number is
    v_id number;
    v_code varchar2(100) := upper(trim(p_bom_code));
  begin
    if v_code is null then
      raise_application_error(-20098, 'BOM code is required.');
    end if;
    if p_target_articul is null then
      raise_application_error(-20099, 'Target articul is required.');
    end if;
    if nvl(p_base_qty, 0) <= 0 then
      raise_application_error(-20100, 'BOM base quantity must be greater than zero.');
    end if;
    validate_period(p_valid_from, p_valid_to);

    begin
      select BOM_ID into v_id
        from RRL_BOM
       where BOM_CODE = v_code;
      return v_id;
    exception
      when no_data_found then null;
    end;

    select RRL_BOM_SQ.nextval into v_id from dual;

    insert into RRL_BOM (
      BOM_ID, BOM_CODE, BOM_NAME, TARGET_ARTICUL, TARGET_MOD_ID, TARGET_GTIN,
      BOM_KIND, BASE_QTY, BASE_UNIT_CODE, IS_PRIMARY, STATUS, VALID_FROM,
      VALID_TO, WARE_ID, PRODUCTION_LINE, VERSION_NO, COMMENT_TEXT,
      CREATED_AT, CREATED_BY
    ) values (
      v_id, substr(v_code, 1, 100), substr(p_bom_name, 1, 255),
      substr(upper(trim(p_target_articul)), 1, 40), p_target_mod_id,
      substr(p_target_gtin, 1, 14), substr(upper(nvl(p_bom_kind, 'FINISHED_GOODS')), 1, 30),
      p_base_qty, substr(upper(nvl(p_base_unit_code, 'KG')), 1, 20),
      case when nvl(p_is_primary, 0) = 1 then 1 else 0 end,
      'DRAFT', p_valid_from, p_valid_to, p_ware_id, substr(p_production_line, 1, 100),
      1, substr(p_comment_text, 1, 1000), sysdate, substr(p_created_by, 1, 50)
    );

    write_audit(v_id, 'BOM_CREATED', null, 'DRAFT', 'BOM draft created', null, p_created_by);
    return v_id;
  end create_bom;

  procedure update_bom(
    p_bom_id           number,
    p_bom_code         varchar2 default null,
    p_bom_name         varchar2 default null,
    p_target_articul   varchar2 default null,
    p_target_mod_id    number default null,
    p_target_gtin      varchar2 default null,
    p_bom_kind         varchar2 default null,
    p_base_qty         number default null,
    p_base_unit_code   varchar2 default null,
    p_is_primary       number default null,
    p_valid_from       date default null,
    p_valid_to         date default null,
    p_ware_id          number default null,
    p_production_line  varchar2 default null,
    p_comment_text     varchar2 default null,
    p_updated_by       varchar2 default null
  ) is
    v_valid_from date;
    v_valid_to date;
  begin
    assert_draft(p_bom_id);

    select nvl(p_valid_from, VALID_FROM), nvl(p_valid_to, VALID_TO)
      into v_valid_from, v_valid_to
      from RRL_BOM
     where BOM_ID = p_bom_id;
    validate_period(v_valid_from, v_valid_to);

    update RRL_BOM
       set BOM_CODE = nvl(substr(upper(trim(p_bom_code)), 1, 100), BOM_CODE),
           BOM_NAME = nvl(substr(p_bom_name, 1, 255), BOM_NAME),
           TARGET_ARTICUL = nvl(substr(upper(trim(p_target_articul)), 1, 40), TARGET_ARTICUL),
           TARGET_MOD_ID = nvl(p_target_mod_id, TARGET_MOD_ID),
           TARGET_GTIN = nvl(substr(p_target_gtin, 1, 14), TARGET_GTIN),
           BOM_KIND = nvl(substr(upper(p_bom_kind), 1, 30), BOM_KIND),
           BASE_QTY = nvl(p_base_qty, BASE_QTY),
           BASE_UNIT_CODE = nvl(substr(upper(p_base_unit_code), 1, 20), BASE_UNIT_CODE),
           IS_PRIMARY = nvl(case when p_is_primary is null then null when p_is_primary = 1 then 1 else 0 end, IS_PRIMARY),
           VALID_FROM = v_valid_from,
           VALID_TO = v_valid_to,
           WARE_ID = nvl(p_ware_id, WARE_ID),
           PRODUCTION_LINE = nvl(substr(p_production_line, 1, 100), PRODUCTION_LINE),
           COMMENT_TEXT = nvl(substr(p_comment_text, 1, 1000), COMMENT_TEXT),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where BOM_ID = p_bom_id;

    write_audit(p_bom_id, 'BOM_UPDATED', 'DRAFT', 'DRAFT', 'BOM draft updated', null, p_updated_by);
  end update_bom;

  function add_line(
    p_bom_id             number,
    p_line_no            number default null,
    p_component_type     varchar2 default 'RAW',
    p_component_articul  varchar2 default null,
    p_component_mod_id   number default null,
    p_component_name     varchar2 default null,
    p_qty_per_base       number default null,
    p_unit_code          varchar2 default null,
    p_loss_percent       number default 0,
    p_min_tolerance_pct  number default null,
    p_max_tolerance_pct  number default null,
    p_is_required        number default 1,
    p_substitution_group varchar2 default null,
    p_replacement_ratio  number default null,
    p_comment_text       varchar2 default null,
    p_created_by         varchar2 default null
  ) return number is
    v_id number;
    v_line_no number;
    v_type varchar2(30) := upper(nvl(p_component_type, 'RAW'));
  begin
    assert_draft(p_bom_id);
    validate_line(v_type, p_component_articul, p_component_name, p_qty_per_base);

    if p_line_no is null then
      select nvl(max(LINE_NO), 0) + 10 into v_line_no
        from RRL_BOM_LINE
       where BOM_ID = p_bom_id;
    else
      v_line_no := p_line_no;
    end if;

    select RRL_BOM_LINE_SQ.nextval into v_id from dual;

    insert into RRL_BOM_LINE (
      BOM_LINE_ID, BOM_ID, LINE_NO, COMPONENT_TYPE, COMPONENT_ARTICUL,
      COMPONENT_MOD_ID, COMPONENT_NAME, QTY_PER_BASE, UNIT_CODE, LOSS_PERCENT,
      MIN_TOLERANCE_PCT, MAX_TOLERANCE_PCT, IS_REQUIRED, SUBSTITUTION_GROUP,
      REPLACEMENT_RATIO, COMMENT_TEXT, CREATED_AT, CREATED_BY
    ) values (
      v_id, p_bom_id, v_line_no, v_type, substr(upper(trim(p_component_articul)), 1, 40),
      p_component_mod_id, substr(p_component_name, 1, 255), p_qty_per_base,
      substr(upper(p_unit_code), 1, 20), nvl(p_loss_percent, 0),
      p_min_tolerance_pct, p_max_tolerance_pct,
      case when nvl(p_is_required, 1) = 1 then 1 else 0 end,
      substr(p_substitution_group, 1, 100), p_replacement_ratio,
      substr(p_comment_text, 1, 1000), sysdate, substr(p_created_by, 1, 50)
    );

    write_audit(p_bom_id, 'BOM_LINE_ADDED', 'DRAFT', 'DRAFT', 'BOM line added', null, p_created_by);
    return v_id;
  end add_line;

  procedure update_line(
    p_bom_line_id        number,
    p_line_no            number default null,
    p_component_type     varchar2 default null,
    p_component_articul  varchar2 default null,
    p_component_mod_id   number default null,
    p_component_name     varchar2 default null,
    p_qty_per_base       number default null,
    p_unit_code          varchar2 default null,
    p_loss_percent       number default null,
    p_min_tolerance_pct  number default null,
    p_max_tolerance_pct  number default null,
    p_is_required        number default null,
    p_substitution_group varchar2 default null,
    p_replacement_ratio  number default null,
    p_comment_text       varchar2 default null,
    p_updated_by         varchar2 default null
  ) is
    v_bom_id number;
    v_type varchar2(30);
    v_articul varchar2(15);
    v_name varchar2(255);
    v_qty number;
  begin
    select BOM_ID into v_bom_id
      from RRL_BOM_LINE
     where BOM_LINE_ID = p_bom_line_id;
    assert_draft(v_bom_id);

    update RRL_BOM_LINE
       set LINE_NO = nvl(p_line_no, LINE_NO),
           COMPONENT_TYPE = nvl(substr(upper(p_component_type), 1, 30), COMPONENT_TYPE),
           COMPONENT_ARTICUL = nvl(substr(upper(trim(p_component_articul)), 1, 40), COMPONENT_ARTICUL),
           COMPONENT_MOD_ID = nvl(p_component_mod_id, COMPONENT_MOD_ID),
           COMPONENT_NAME = nvl(substr(p_component_name, 1, 255), COMPONENT_NAME),
           QTY_PER_BASE = nvl(p_qty_per_base, QTY_PER_BASE),
           UNIT_CODE = nvl(substr(upper(p_unit_code), 1, 20), UNIT_CODE),
           LOSS_PERCENT = nvl(p_loss_percent, LOSS_PERCENT),
           MIN_TOLERANCE_PCT = nvl(p_min_tolerance_pct, MIN_TOLERANCE_PCT),
           MAX_TOLERANCE_PCT = nvl(p_max_tolerance_pct, MAX_TOLERANCE_PCT),
           IS_REQUIRED = nvl(case when p_is_required is null then null when p_is_required = 1 then 1 else 0 end, IS_REQUIRED),
           SUBSTITUTION_GROUP = nvl(substr(p_substitution_group, 1, 100), SUBSTITUTION_GROUP),
           REPLACEMENT_RATIO = nvl(p_replacement_ratio, REPLACEMENT_RATIO),
           COMMENT_TEXT = nvl(substr(p_comment_text, 1, 1000), COMMENT_TEXT),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where BOM_LINE_ID = p_bom_line_id;

    select COMPONENT_TYPE, COMPONENT_ARTICUL, COMPONENT_NAME, QTY_PER_BASE
      into v_type, v_articul, v_name, v_qty
      from RRL_BOM_LINE
     where BOM_LINE_ID = p_bom_line_id;
    validate_line(v_type, v_articul, v_name, v_qty);

    write_audit(v_bom_id, 'BOM_LINE_UPDATED', 'DRAFT', 'DRAFT', 'BOM line updated', null, p_updated_by);
  exception
    when no_data_found then
      raise_application_error(-20101, 'BOM line not found.');
  end update_line;

  procedure delete_line(
    p_bom_line_id number,
    p_deleted_by  varchar2 default null
  ) is
    v_bom_id number;
  begin
    select BOM_ID into v_bom_id
      from RRL_BOM_LINE
     where BOM_LINE_ID = p_bom_line_id;
    assert_draft(v_bom_id);

    delete from RRL_BOM_LINE
     where BOM_LINE_ID = p_bom_line_id;

    write_audit(v_bom_id, 'BOM_LINE_DELETED', 'DRAFT', 'DRAFT', 'BOM line deleted', null, p_deleted_by);
  exception
    when no_data_found then
      raise_application_error(-20101, 'BOM line not found.');
  end delete_line;

  procedure approve_bom(
    p_bom_id      number,
    p_approved_by varchar2 default null
  ) is
    v_line_count number;
    v_is_primary number;
  begin
    assert_draft(p_bom_id);

    select count(*) into v_line_count
      from RRL_BOM_LINE
     where BOM_ID = p_bom_id;
    if v_line_count = 0 then
      raise_application_error(-20102, 'BOM cannot be approved without lines.');
    end if;

    select IS_PRIMARY into v_is_primary
      from RRL_BOM
     where BOM_ID = p_bom_id;
    if v_is_primary = 1 then
      assert_primary_available(p_bom_id);
    end if;

    update RRL_BOM
       set STATUS = 'APPROVED',
           APPROVED_AT = sysdate,
           APPROVED_BY = substr(p_approved_by, 1, 50),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_approved_by, 1, 50)
     where BOM_ID = p_bom_id;

    write_audit(p_bom_id, 'BOM_APPROVED', 'DRAFT', 'APPROVED', 'BOM approved', null, p_approved_by);
  end approve_bom;

  procedure block_bom(
    p_bom_id     number,
    p_reason     varchar2 default null,
    p_updated_by varchar2 default null
  ) is
    v_old_status varchar2(30);
  begin
    select STATUS into v_old_status
      from RRL_BOM
     where BOM_ID = p_bom_id;

    update RRL_BOM
       set STATUS = 'BLOCKED',
           IS_PRIMARY = 0,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where BOM_ID = p_bom_id;

    write_audit(p_bom_id, 'BOM_BLOCKED', v_old_status, 'BLOCKED', p_reason, null, p_updated_by);
  exception
    when no_data_found then
      raise_application_error(-20091, 'BOM not found.');
  end block_bom;

  procedure archive_bom(
    p_bom_id     number,
    p_reason     varchar2 default null,
    p_updated_by varchar2 default null
  ) is
    v_old_status varchar2(30);
  begin
    select STATUS into v_old_status
      from RRL_BOM
     where BOM_ID = p_bom_id;

    update RRL_BOM
       set STATUS = 'ARCHIVED',
           IS_PRIMARY = 0,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where BOM_ID = p_bom_id;

    write_audit(p_bom_id, 'BOM_ARCHIVED', v_old_status, 'ARCHIVED', p_reason, null, p_updated_by);
  exception
    when no_data_found then
      raise_application_error(-20091, 'BOM not found.');
  end archive_bom;

  procedure make_primary(
    p_bom_id     number,
    p_updated_by varchar2 default null
  ) is
    v_status varchar2(30);
  begin
    select STATUS into v_status
      from RRL_BOM
     where BOM_ID = p_bom_id;

    if v_status not in ('APPROVED', 'ACTIVE') then
      raise_application_error(-20103, 'Only APPROVED or ACTIVE BOM can be made primary.');
    end if;

    assert_primary_available(p_bom_id);

    update RRL_BOM
       set IS_PRIMARY = 1,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where BOM_ID = p_bom_id;

    write_audit(p_bom_id, 'BOM_MADE_PRIMARY', v_status, v_status, 'BOM marked as primary', null, p_updated_by);
  exception
    when no_data_found then
      raise_application_error(-20091, 'BOM not found.');
  end make_primary;

  function clone_bom(
    p_source_bom_id number,
    p_bom_code      varchar2,
    p_valid_from    date,
    p_valid_to      date default null,
    p_created_by    varchar2 default null
  ) return number is
    v_source RRL_BOM%rowtype;
    v_id number;
    v_code varchar2(100) := upper(trim(p_bom_code));
  begin
    if v_code is null then
      raise_application_error(-20098, 'BOM code is required.');
    end if;
    validate_period(p_valid_from, p_valid_to);

    select * into v_source
      from RRL_BOM
     where BOM_ID = p_source_bom_id;

    select RRL_BOM_SQ.nextval into v_id from dual;

    insert into RRL_BOM (
      BOM_ID, BOM_CODE, BOM_NAME, TARGET_ARTICUL, TARGET_MOD_ID, TARGET_GTIN,
      BOM_KIND, BASE_QTY, BASE_UNIT_CODE, IS_PRIMARY, STATUS, VALID_FROM,
      VALID_TO, WARE_ID, PRODUCTION_LINE, VERSION_NO, PARENT_BOM_ID,
      COMMENT_TEXT, CREATED_AT, CREATED_BY
    ) values (
      v_id, substr(v_code, 1, 100), v_source.BOM_NAME, v_source.TARGET_ARTICUL,
      v_source.TARGET_MOD_ID, v_source.TARGET_GTIN, v_source.BOM_KIND,
      v_source.BASE_QTY, v_source.BASE_UNIT_CODE, 0, 'DRAFT',
      p_valid_from, p_valid_to, v_source.WARE_ID, v_source.PRODUCTION_LINE,
      v_source.VERSION_NO + 1, v_source.BOM_ID, v_source.COMMENT_TEXT,
      sysdate, substr(p_created_by, 1, 50)
    );

    insert into RRL_BOM_LINE (
      BOM_LINE_ID, BOM_ID, LINE_NO, COMPONENT_TYPE, COMPONENT_ARTICUL,
      COMPONENT_MOD_ID, COMPONENT_NAME, QTY_PER_BASE, UNIT_CODE, LOSS_PERCENT,
      MIN_TOLERANCE_PCT, MAX_TOLERANCE_PCT, IS_REQUIRED, SUBSTITUTION_GROUP,
      REPLACEMENT_RATIO, COMMENT_TEXT, CREATED_AT, CREATED_BY
    )
    select RRL_BOM_LINE_SQ.nextval, v_id, LINE_NO, COMPONENT_TYPE, COMPONENT_ARTICUL,
           COMPONENT_MOD_ID, COMPONENT_NAME, QTY_PER_BASE, UNIT_CODE, LOSS_PERCENT,
           MIN_TOLERANCE_PCT, MAX_TOLERANCE_PCT, IS_REQUIRED, SUBSTITUTION_GROUP,
           REPLACEMENT_RATIO, COMMENT_TEXT, sysdate, substr(p_created_by, 1, 50)
      from RRL_BOM_LINE
     where BOM_ID = p_source_bom_id;

    write_audit(v_id, 'BOM_CLONED', null, 'DRAFT', 'BOM cloned from ' || p_source_bom_id, null, p_created_by);
    return v_id;
  exception
    when no_data_found then
      raise_application_error(-20091, 'Source BOM not found.');
  end clone_bom;

  function find_primary_bom(
    p_target_articul  varchar2,
    p_planned_date    date default null,
    p_target_mod_id   number default null,
    p_ware_id         number default null,
    p_production_line varchar2 default null
  ) return number is
    v_id number;
    v_date date := nvl(p_planned_date, trunc(sysdate));
  begin
    select BOM_ID
      into v_id
      from (
        select BOM_ID,
               (case when TARGET_MOD_ID = p_target_mod_id then 1 else 0 end) +
               (case when WARE_ID = p_ware_id then 1 else 0 end) +
               (case when upper(PRODUCTION_LINE) = upper(p_production_line) then 1 else 0 end) SPECIFICITY
          from RRL_BOM
         where TARGET_ARTICUL = upper(trim(p_target_articul))
           and IS_PRIMARY = 1
           and STATUS in ('APPROVED', 'ACTIVE')
           and VALID_FROM <= v_date
           and nvl(VALID_TO, date '2999-12-31') >= v_date
           and (p_target_mod_id is null or TARGET_MOD_ID is null or TARGET_MOD_ID = p_target_mod_id)
           and (p_ware_id is null or WARE_ID is null or WARE_ID = p_ware_id)
           and (p_production_line is null or PRODUCTION_LINE is null or upper(PRODUCTION_LINE) = upper(p_production_line))
         order by SPECIFICITY desc, VALID_FROM desc, BOM_ID desc
      )
     where rownum = 1;

    return v_id;
  exception
    when no_data_found then
      return null;
  end find_primary_bom;
end RRL_BOM_API;
/


CREATE OR REPLACE package body RRL_BOX_ASSEMBLY_READ as
 function clocks_json(p_tree clob,p_ware number,p_region varchar2)return clob is
 tree json_object_t:=json_object_t.parse(p_tree);nodes json_array_t:=tree.get_array('nodes');
 result json_array_t:=json_array_t();node json_object_t;j json_object_t;packing json_object_t;
 uid varchar2(200);instant timestamp with time zone;clock_op varchar2(100);start_version number;latest_version number;case_id number;source_ware number;box_version number;wire_instant varchar2(40);region_check varchar2(64);
 type keys is table of boolean index by varchar2(200);seen keys;
 begin
  select to_char(systimestamp at time zone(p_region),'TZR')into region_check from dual;
  if nodes is null or nodes.get_size<1 or nodes.get_size>200 then raise_application_error(-20886,'COST_FROZEN_TREE_BOUND');end if;
  for i in 0..nodes.get_size-1 loop
   node:=treat(nodes.get(i)as json_object_t);uid:=node.get_string('uid');
   if uid is null or seen.exists(uid)then raise_application_error(-20886,'COST_FROZEN_TREE_IDENTITY');end if;seen(uid):=true;
   if (node.get_string('kind')='CASE'and node.has('scale_qc'))or
    (node.get_string('kind')='CONTAINER'and node.get_string('type')='BOX')then
    j:=json_object_t();j.put('box_identifier',uid);j.put('content_version',node.get_number('version'));
    instant:=null;clock_op:=null;start_version:=null;case_id:=null;
    if node.get_string('kind')='CASE'then
     case_id:=node.get_number('case_task_id');j.put('case_task_id',case_id);
     begin select STARTED_AT_INSTANT into instant from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=case_id and WARE_ID=p_ware;
     exception when no_data_found then null;end;
     j.put('source_kind','CASE_START');j.put('state','MISSING_ACTUAL_START');
    else
     j.put('source_kind','BOX_PACKING');j.put('state','ASSEMBLY_SOURCE_NOT_LINKED');
     if node.has('packing_start')then
      packing:=node.get_object('packing_start');clock_op:=packing.get_string('operation_id');start_version:=packing.get_number('content_version');
      source_ware:=packing.get_number('warehouse');box_version:=node.get_number('version');wire_instant:=packing.get_string('instant');
      begin
       select c.STARTED_AT_INSTANT into instant from RRL_HU_PACK_CYCLE c
       join RRL_STOCK_OPERATION op on op.OPERATION_ID=c.START_OPERATION_ID and op.STATE='APPLIED'
       where c.PARENT_UID=uid and c.START_OPERATION_ID=clock_op and c.START_CONTENT_VERSION=start_version
       and c.WARE_ID=p_ware and c.WARE_ID=source_ware
       and c.START_CONTENT_VERSION<=box_version
       and to_char(c.STARTED_AT_INSTANT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM')=wire_instant;
       select max(START_CONTENT_VERSION)into latest_version from RRL_HU_PACK_CYCLE
       where PARENT_UID=uid and START_CONTENT_VERSION<=box_version;
       if latest_version!=start_version then instant:=null;end if;
      exception when no_data_found then instant:=null;end;
     end if;
     j.put('start_operation_id',clock_op);j.put('start_content_version',start_version);
    end if;
    if instant is not null then
     j.put('instant',to_char(instant,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
     j.put('business_date',to_char(instant at time zone(p_region),'YYYY-MM-DD'));j.put('state','READY');
    end if;
    result.append(j);
   end if;
  end loop;
  return result.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_CASE_PALLET_TYPE_READ as
 function describe_type(p_task number,p_actor varchar2)return clob is
  ct RRL_CASE_PICK_TASK%rowtype;j json_object_t:=json_object_t();planned_type number;planned_name varchar2(160);actual_name varchar2(160);
  held_no number;lot_no number;parent_no number;reason_value varchar2(100);
 begin
  RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,'case_pick_view');
  select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task;
  planned_type:=RRL_RECIPIENT_PALLET_POLICY.type_id(ct.CUSTOMER_ID,ct.CUSTOMER_STORE_MAP_ID);
  if planned_type is not null then select PALLET_TYPE_NAME into planned_name from RRL_PALLET_TYPE where PALLET_TYPE_ID=planned_type;end if;
  select PALLET_TYPE_NAME into actual_name from RRL_PALLET_TYPE where PALLET_TYPE_ID=ct.PALLET_TYPE_ID;
  select count(*)into held_no from RRL_TARE_BOOK where PLACE_KIND='CASE'and PLACE_ID=to_char(p_task,'TM9')and STATUS='HELD';
  select count(*)into lot_no from RRL_CASE_CARRIER_LOT where CASE_PICK_TASK_ID=p_task;
  select count(*)into parent_no from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=p_task and ACTIVE_FLAG=1;
  if ct.STATUS not in('NEW','ASSIGNED')or ct.STARTED_AT is not null or nvl(ct.PICKED_QTY,0)!=0 or lot_no>0 then reason_value:='CASE_TYPE_USE_PHYSICAL_REPACK';
  elsif ct.LEGACY_SBORKA_PALLET_ID is not null or ct.CURRENT_CELL is not null or parent_no>0 then reason_value:='CASE_TYPE_BOUND_PLACE_REPACK_REQUIRED';
  elsif held_no>0 then reason_value:='CASE_TYPE_RELEASE_EMPTY_TARE_FIRST';end if;
  j.put('case_task_id',p_task);j.put('warehouse_id',ct.WARE_ID);j.put('sscc',ct.SSCC);j.put('version',nvl(ct.CONTENT_VERSION,0));j.put('status',ct.STATUS);
  j.put('planned_pallet_type_id',planned_type);j.put('planned_type_name',planned_name);j.put('planned_source','RECIPIENT_RULE');
  j.put('actual_pallet_type_id',ct.PALLET_TYPE_ID);j.put('actual_type_name',actual_name);j.put('can_change_empty_type',reason_value is null);
  j.put('change_blocker',reason_value);j.put('assigned_to',ct.ASSIGNED_TO);j.put('stock_changed',false);
  return j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_CASE_RESOURCE_POLICY as
 function context_json(p_task number,p_action varchar2,p_actor varchar2,p_resource number default null,p_session number default null,p_equipment number default null) return clob is
  ct RRL_CASE_PICK_TASK%rowtype;s RRL_RESOURCE_SESSION%rowtype;r RRL_RESOURCE%rowtype;e RRL_RESOURCE_EQUIPMENT%rowtype;sh RRL_RESOURCE_SHIFT%rowtype;
  v_resource number:=p_resource;v_session number:=p_session;v_equipment number:=p_equipment;n number;types varchar2(1000);
  target varchar2(100);j json_object_t:=json_object_t();
 begin
  if p_action not in('CLAIM','START','COMPLETE','REPORT','TRANSFER') or p_action is null or p_actor is null then raise_application_error(-20881,'CASE_RESOURCE_ACTION_REQUIRED');end if;
  select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task;
  RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,case when p_action='TRANSFER'then'case_pick_manage'else'case_pick_execute'end);
  if p_action in('CLAIM','START','COMPLETE') then RRL_STOCK_WAVE_READY.assert_released(ct.PICK_WAVE_ID);end if;
  if p_action='TRANSFER' then
   if RRL_HAS_WRIGHT(p_actor,'case_pick_manage')!=1 then raise_application_error(-20882,'CASE_TRANSFER_FORBIDDEN');end if;
  elsif RRL_HAS_WRIGHT(p_actor,'case_pick_execute')!=1 then raise_application_error(-20882,'CASE_EXECUTE_FORBIDDEN');end if;
  if ct.STATUS is null or ct.STATUS not in('NEW','ASSIGNED','IN_PROGRESS','PARTIAL','WAIT_REPLENISHMENT') then raise_application_error(-20886,'CASE_RESOURCE_TASK_STATE_CONFLICT');end if;
  if p_action!='TRANSFER' then
   v_resource:=nvl(v_resource,ct.ASSIGNED_RESOURCE_ID);v_session:=nvl(v_session,ct.RESOURCE_SESSION_ID);v_equipment:=nvl(v_equipment,ct.EQUIPMENT_ID);
  end if;
  target:=nvl(ct.ASSIGNED_TO,p_actor);
  if v_session is null then
   if v_resource is not null or v_equipment is not null or RRL_HAS_WRIGHT(p_actor,'case_pick_manage')!=1 then raise_application_error(-20882,'CASE_PHYSICAL_SESSION_REQUIRED');end if;
   if p_action='TRANSFER' then raise_application_error(-20881,'CASE_TRANSFER_TARGET_SESSION_REQUIRED');end if;
   target:=p_actor;
  else
   select * into s from RRL_RESOURCE_SESSION where SESSION_ID=v_session;
   target:=s.OPERATOR_USER_ID;
   if target is null or s.STATUS is null or (p_action='CLAIM' and s.STATUS not in('ACTIVE','PAUSED')) or (p_action!='CLAIM' and s.STATUS!='ACTIVE') then raise_application_error(-20886,'CASE_SESSION_UNAVAILABLE');end if;
   if p_action!='TRANSFER' and target!=p_actor and RRL_HAS_WRIGHT(p_actor,'case_pick_manage')!=1 then raise_application_error(-20882,'CASE_SESSION_OWNER_CONFLICT');end if;
   if (v_resource is not null and v_resource!=s.RESOURCE_ID) or (v_equipment is not null and nvl(s.EQUIPMENT_ID,-1)!=v_equipment) then raise_application_error(-20886,'CASE_SESSION_CONTEXT_CONFLICT');end if;
   v_resource:=s.RESOURCE_ID;v_equipment:=s.EQUIPMENT_ID;
   select * into sh from RRL_RESOURCE_SHIFT where SHIFT_ID=s.SHIFT_ID;
   if sh.STATUS is null or sh.START_AT is null or sh.FINISH_AT is null or sh.STATUS not in('PLANNED','OPEN') or (p_action!='CLAIM' and (sh.STATUS!='OPEN' or systimestamp<sh.START_AT or systimestamp>sh.FINISH_AT)) then raise_application_error(-20886,'CASE_SHIFT_UNAVAILABLE');end if;
   select count(*) into n from RRL_WAREHOUSE_TASK where ASSIGNED_TO=target and STATUS='IN_PROGRESS';
   if n>0 or s.CURRENT_INVENTORY_TASK_ID is not null then raise_application_error(-20886,'CASE_OPERATOR_BUSY_WITH_OTHER_PHYSICAL_STEP');end if;
   select * into r from RRL_RESOURCE where RESOURCE_ID=v_resource;
   if nvl(r.ACTIVE,0)!=1 or r.STATUS is null or r.STATUS not in('AVAILABLE','IDLE','IN_WORK') or (r.USER_ID is not null and r.USER_ID!=target) or r.WARE_ID is null or ct.WARE_ID is null or r.WARE_ID!=ct.WARE_ID then raise_application_error(-20886,'CASE_RESOURCE_UNAVAILABLE');end if;
   select DEFAULT_TASK_TYPES into types from RRL_RESOURCE_TYPE where RESOURCE_TYPE=r.RESOURCE_TYPE and ACTIVE=1;
   if types is null or instr(','||replace(types,' ','')||',',',CASE_PICK,')=0 then raise_application_error(-20886,'CASE_RESOURCE_TYPE_UNSUITABLE');end if;
   select count(*) into n from RRL_RESOURCE_TASK_QUAL where RESOURCE_ID=v_resource and TASK_TYPE='CASE_PICK' and ACTIVE=1 and VALID_FROM<=systimestamp and (VALID_UNTIL is null or VALID_UNTIL>systimestamp);
   if n!=1 then raise_application_error(-20886,'CASE_RESOURCE_QUALIFICATION_REQUIRED');end if;
   if r.EQUIPMENT_ID is not null and nvl(v_equipment,-1)!=r.EQUIPMENT_ID then raise_application_error(-20886,'CASE_RESOURCE_EQUIPMENT_BINDING_CONFLICT');end if;
   if v_equipment is not null then
    select * into e from RRL_RESOURCE_EQUIPMENT where EQUIPMENT_ID=v_equipment;
    if nvl(e.ACTIVE,0)!=1 or nvl(e.SERVICE_STATUS,'?')!='ACTIVE' or e.WARE_ID is null or e.WARE_ID!=ct.WARE_ID then raise_application_error(-20886,'CASE_EQUIPMENT_UNAVAILABLE');end if;
   end if;
  end if;
  RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,case when p_action='TRANSFER'then'case_pick_manage'else'case_pick_execute'end,target);
  select count(*) into n from RUSERS where ID=target and nvl(DELETED,0)=0;
  if n!=1 or RRL_HAS_WRIGHT(target,'case_pick_execute')!=1 then raise_application_error(-20882,'CASE_TARGET_NOT_EXECUTOR');end if;
  if p_action in('CLAIM','START') and ct.ASSIGNED_TO is not null and ct.ASSIGNED_TO!=target then raise_application_error(-20886,'CASE_USE_EXPLICIT_TRANSFER');end if;
  if p_action!='TRANSFER' and ct.PICKED_QTY>0 and (nvl(ct.RESOURCE_SESSION_ID,-1)!=nvl(v_session,-1) or nvl(ct.ASSIGNED_RESOURCE_ID,-1)!=nvl(v_resource,-1)) then raise_application_error(-20886,'CASE_CARRIER_NEEDS_EXPLICIT_TRANSFER');end if;
  j.put('resource_id',v_resource);j.put('resource_session_id',v_session);j.put('equipment_id',v_equipment);j.put('assigned_to',target);
  return j.to_clob;
 exception when no_data_found then raise_application_error(-20886,'CASE_RESOURCE_IDENTITY_MISSING');
 end;
end;
/


CREATE OR REPLACE package body RRL_CASE_ROUTE_ADMISSION as
 procedure assert_next(p_case number,p_line number) is
  v_stage number;v_next_stage number;v_group_max number:=0;v_rank number;v_rows number;v_known number;v_pending_unknown number;v_next number;v_passed number;
 begin
  select PICK_SEQUENCE,case STACK_STAGE when 'BASE'then 1 when 'TOP'then 3 else 2 end into v_rank,v_stage from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=p_case and CASE_PICK_LINE_ID=p_line;
  select count(*),count(PICK_SEQUENCE),
   sum(case when PICK_SEQUENCE is null and nvl(STATUS,'NEW')not in('DONE','CANCELLED','SHORT_PICKED')and nvl(PICKED_QTY,0)<PLANNED_QTY then 1 else 0 end),
   min(case when nvl(STATUS,'NEW')not in('DONE','CANCELLED','SHORT_PICKED')and nvl(PICKED_QTY,0)<PLANNED_QTY then PICK_SEQUENCE end),
   max(case when nvl(PICKED_QTY,0)>0 then PICK_SEQUENCE end)
  into v_rows,v_known,v_pending_unknown,v_next,v_passed
  from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=p_case;
  if v_rows>200 then raise_application_error(-20881,'CASE_ROUTE_LINE_BOUND_200');end if;
  -- Issued stages must fit the original one-way route; never reverse it by sorting weights.
  for point in(select PICK_SEQUENCE,
    min(case STACK_STAGE when 'BASE'then 1 when 'TOP'then 3 else 2 end) LO,
    max(case STACK_STAGE when 'BASE'then 1 when 'TOP'then 3 else 2 end) HI
   from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=p_case and PICK_SEQUENCE is not null
    and nvl(STATUS,'NEW')!='CANCELLED'and(case when STATUS='SHORT_PICKED'then nvl(PICKED_QTY,0)else PLANNED_QTY end)>0
   group by PICK_SEQUENCE order by PICK_SEQUENCE)loop
   if point.LO<v_group_max then raise_application_error(-20886,'CASE_STACK_ROUTE_CONFLICT');end if;
   v_group_max:=point.HI;
  end loop;
  select min(case STACK_STAGE when 'BASE'then 1 when 'TOP'then 3 else 2 end)into v_next_stage
   from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=p_case and nvl(STATUS,'NEW')not in('DONE','CANCELLED','SHORT_PICKED')and nvl(PICKED_QTY,0)<PLANNED_QTY
    and(PICK_SEQUENCE=v_rank or(v_known=0 and PICK_SEQUENCE is null));
  if v_next_stage is not null and v_stage!=v_next_stage then raise_application_error(-20886,'CASE_STACK_EARLIER_STAGE_UNFINISHED');end if;
  -- Legacy DIRECT cases without any assigned route keep the original contract.
  if v_known=0 then return;end if;
  if v_rank is null or v_pending_unknown>0 then raise_application_error(-20886,'CASE_ROUTE_ASSIGNED_SEQUENCE_REQUIRED');end if;
  if v_passed is not null and v_rank<v_passed then raise_application_error(-20886,'CASE_ROUTE_BACKTRACK_FORBIDDEN');end if;
  if v_next is not null and v_rank!=v_next then raise_application_error(-20886,'CASE_ROUTE_EARLIER_POINT_UNFINISHED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_CASE_SCALE_ADMISSION as
 procedure assert_empty_tare(p_task number)is
  required number;picked number;ware number;type_id number;carrier varchar2(150);n number;
 begin
  select case when p.FINAL_WEIGHT_REQUIRED=1 and upper(p.LOAD_UNIT_CLASS)='CONTAINER'then 1 else 0 end,c.PICKED_QTY,c.WARE_ID,c.PALLET_TYPE_ID,c.SSCC
   into required,picked,ware,type_id,carrier from RRL_CASE_PICK_TASK c join RRL_PALLET_TYPE p on p.PALLET_TYPE_ID=c.PALLET_TYPE_ID where c.CASE_PICK_TASK_ID=p_task;
  if required=0 or nvl(picked,0)>0 then return;end if;
  select count(*)into n from(select 1 from RRL_WH_SCALE_CAPTURE s join RRL_WH_SCALE_DEVICE v on v.DEVICE_ID=s.DEVICE_ID
   where s.CASE_PICK_TASK_ID=p_task and s.CAPTURE_PURPOSE='EMPTY_TARE' and s.WARE_ID=ware and s.CARRIER_IDENTIFIER=carrier
    and s.PALLET_TYPE_ID=type_id and s.MEASURED_AT>=systimestamp-numtodsinterval(24,'HOUR') and s.MEASURED_AT<=systimestamp+numtodsinterval(2,'SECOND')
    and v.WARE_ID=s.WARE_ID and v.POST_CELL=s.POST_CELL and v.DEVICE_MODE=s.DEVICE_MODE and v.ACTIVE_FLAG=1)where rownum=1;
  if n!=1 then raise_application_error(-20886,'SMALL_BOX_MEASURED_EMPTY_TARE_BEFORE_PICK_REQUIRED');end if;
 end;

 procedure assert_capture(p_request clob,p_previous number)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');
  c RRL_WH_SCALE_CAPTURE%rowtype;v RRL_WH_SCALE_DEVICE%rowtype;
  t RRL_CASE_PICK_TASK%rowtype;l RRL_CASE_PICK_LINE%rowtype;
  k varchar2(64);task_id number;line_id number;n number;serial_flag number;marked number;
  delta_qty number;unit_key varchar2(64);gross number;
 begin
  assert_empty_tare(d.get_object('source').get_number('case_task_id'));
  if not m.has('warehouse_scale_capture')then return;end if;
  k:=m.get_string('warehouse_scale_capture');
  if k is null or not regexp_like(k,'^[A-F0-9]{64}$')then raise_application_error(-20886,'WAREHOUSE_SCALE_CAPTURE_KEY_REQUIRED');end if;
  task_id:=d.get_object('source').get_number('case_task_id');line_id:=d.get_object('source').get_number('case_line_id');
  select *into c from RRL_WH_SCALE_CAPTURE where CAPTURE_KEY=k;
  if c.CAPTURE_PURPOSE!='PICK' then raise_application_error(-20886,'CASE_PICK_SCALE_PURPOSE_REQUIRED');end if;
  select *into v from RRL_WH_SCALE_DEVICE where DEVICE_ID=c.DEVICE_ID;
  select *into t from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_id;
  select *into l from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=task_id and CASE_PICK_LINE_ID=line_id;
  if c.CASE_PICK_TASK_ID!=task_id or c.CASE_PICK_LINE_ID!=line_id or c.WARE_ID!=t.WARE_ID
   or c.CASE_CONTENT_VERSION!=t.CONTENT_VERSION or c.ARTICLE!=l.ARTICUL
   or c.SOURCE_CELL!=l.CELL_CODE or c.CARRIER_IDENTIFIER!=t.SSCC
   or m.get_string('scan_cell')is null or m.get_string('scan_cell')!=c.SOURCE_CELL
   or m.get_string('scan_container')is null or m.get_string('scan_container')!=c.CARRIER_IDENTIFIER
   then raise_application_error(-20886,'WAREHOUSE_SCALE_CASE_SOURCE_CHANGED');end if;
  if v.ACTIVE_FLAG!=1 or v.POLICY_VERSION!=c.DEVICE_POLICY_VERSION or v.WARE_ID!=c.WARE_ID
   or v.POST_CELL!=c.POST_CELL or v.MEASUREMENT_BASIS!=c.MEASUREMENT_BASIS
   or v.DEVICE_MODE!=c.DEVICE_MODE or v.CALIBRATED_UNTIL<systimestamp
   or c.MEASURED_AT<systimestamp-numtodsinterval(120,'SECOND')
   or c.MEASURED_AT>systimestamp+numtodsinterval(2,'SECOND')
   then raise_application_error(-20886,'WAREHOUSE_SCALE_CURRENT_FRESH_DEVICE_REQUIRED');end if;
  select count(*)into n from RUSERS where ID=v.SENDER_ID and ID=c.RECORDED_BY and nvl(DELETED,0)=0
   and WARE_ID=c.WARE_ID and upper(trim(USER_GROUP))!='GLOBAL_ADMIN'and RRL_HAS_WRIGHT(ID,'warehouse_scale_ingest')=1;
  if n!=1 then raise_application_error(-20882,'WAREHOUSE_SCALE_CURRENT_SENDER_REQUIRED');end if;
  select count(*)into n from RRL_WH_SCALE_USE where CAPTURE_KEY=k;
  if n!=0 then raise_application_error(-20886,'WAREHOUSE_SCALE_CAPTURE_ALREADY_USED');end if;
  select nvl(max(SERIALIZED_WEIGHT_BOXES),0),nvl(max(MARKING_REQUIRED),0)into serial_flag,marked
   from RRL_SKU_RECEIPT_POLICY where ARTICUL=l.ARTICUL;
  delta_qty:=RRL_STOCK_MATH.quantity(m.get_string('fact_qty'))-p_previous;
  select count(*)into n from RRL_ARTICULS where ACTICUL=l.ARTICUL and TYPE_W in(2,3,5,6,7);
  if n!=1 then raise_application_error(-20886,'WAREHOUSE_SCALE_CURRENT_WEIGHTED_SKU_REQUIRED');end if;
  select count(*)into n from RRL_STOCK_UOM_CONVERSION where ARTICUL=l.ARTICUL and INPUT_UOM='KG'and BASE_UOM='KG'and NUMERATOR=1 and DENOMINATOR=1;
  if n!=1 then raise_application_error(-20886,'WAREHOUSE_SCALE_CURRENT_KG_BASE_REQUIRED');end if;

  if serial_flag=1 then
   if c.MEASUREMENT_BASIS!='GROSS' or not m.has('weighted_box_scan')
    or m.get_string('weighted_box_scan')is null or m.get_string('weighted_box_scan')!=c.SCANNED_PRODUCT
    or d.get_array('units').get_size!=1 then raise_application_error(-20886,'WAREHOUSE_SCALE_SAME_SEALED_BOX_REQUIRED');end if;
   unit_key:=d.get_array('units').get_string(0);
   select GROSS_WEIGHT_KG into gross from RRL_WMS_RECEIPT_UNIT where PHYSICAL_UNIT_KEY=unit_key
    and BASE_UOM='KG'and GROSS_WEIGHT_KG>=BASE_QTY and MEASUREMENT_REFERENCE is not null and WEIGHT_LABEL_SCAN is not null;
   if abs(gross-c.WEIGHT_KG)>v.RESOLUTION_KG then raise_application_error(-20886,'WAREHOUSE_SCALE_BOX_GROSS_MISMATCH');end if;
  else
   select greatest(nvl((select CRPT_REQUIRED from RRL_FINISHED_GOODS_SKU where ARTICUL=l.ARTICUL),0),
    case when exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=l.ARTICUL)then 1 else 0 end)into n from dual;
   if m.get_string('scan_product')is null or m.get_string('scan_product')!=c.SCANNED_PRODUCT then raise_application_error(-20886,'WAREHOUSE_SCALE_ORIGINAL_PRODUCT_REQUIRED');end if;
   if marked!=0 or n!=0 or c.MEASUREMENT_BASIS!='NET' or d.get_array('units').get_size!=0 or delta_qty!=c.WEIGHT_KG
    then raise_application_error(-20886,'WAREHOUSE_SCALE_UNMARKED_NET_QUANTITY_REQUIRED');end if;
  end if;
 exception when no_data_found or too_many_rows then raise_application_error(-20886,'WAREHOUSE_SCALE_CURRENT_SOURCE_NOT_UNIQUE');
 end;
 procedure claim_capture(p_request clob,p_operation varchar2,p_previous number)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');
  k varchar2(64);task_id number;line_id number;actor_value varchar2(50);
 begin
  if not m.has('warehouse_scale_capture')then return;end if;
  assert_capture(p_request,p_previous);k:=m.get_string('warehouse_scale_capture');
  RRL_STOCK_LOCK_API.assert_held(70,RRL_STOCK_LOCK_API.resource_key('UNIQUE','WH.SCALE.USE:'||k));
  task_id:=d.get_object('source').get_number('case_task_id');line_id:=d.get_object('source').get_number('case_line_id');
  actor_value:=d.get_string('actor');
  insert into RRL_WH_SCALE_USE(CAPTURE_KEY,STOCK_OPERATION_ID,CASE_PICK_TASK_ID,CASE_PICK_LINE_ID,ACTOR)
   values(k,p_operation,task_id,line_id,actor_value);
 end;
end;
/


CREATE OR REPLACE package body RRL_CASE_SSCC_API as
 procedure fence is begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STOCK_POLICY_GUARD','WAREHOUSE.METADATA'));
 end;
 procedure trusted(p_actor varchar2)is begin
  dbms_session.set_context('RRL_CASE_SSCC_CTX','TX_ID',dbms_transaction.local_transaction_id(true));
  dbms_session.set_context('RRL_CASE_SSCC_CTX','ACTOR',p_actor);
 end;
 procedure clear_context is begin dbms_session.clear_context('RRL_CASE_SSCC_CTX',null);end;
 procedure issue(p_task number,p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);ct RRL_CASE_PICK_TASK%rowtype;
  op varchar2(100);code varchar2(18);old RRL_CASE_SSCC_LABEL%rowtype;n number;r json_object_t:=json_object_t();
 begin
  fence;RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,'case_pick_execute');
  op:=d.get_string('operation_id');
  if op is null or length(op)>100 or not regexp_like(op,'^[ -~]+$')or d.get_size!=3 then raise_application_error(-20887,'CASE_LABEL_REQUEST_REQUIRED');end if;
  select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task for update;
  RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,'case_pick_execute');
  begin
   select *into old from RRL_CASE_SSCC_LABEL where OPERATION_ID=op;
   if old.CASE_PICK_TASK_ID!=p_task or old.CREATED_BY!=p_actor or dbms_lob.compare(old.REQUEST_JSON,p_request)!=0 then raise_application_error(-20873,'CASE_LABEL_OPERATION_CONFLICT');end if;
   p_result:=old.RESULT_JSON;return;
  exception when no_data_found then null;end;
  if (ct.ASSIGNED_TO is not null and ct.ASSIGNED_TO!=p_actor)or ct.STATUS not in('NEW','ASSIGNED')or nvl(ct.PICKED_QTY,0)!=0 or ct.CONTENT_VERSION!=d.get_number('expected_content_version')
   or ct.SSCC!=d.get_string('scan_container')or ct.LEGACY_SBORKA_PALLET_ID is not null then raise_application_error(-20873,'CASE_LABEL_EMPTY_CURRENT_CARRIER_REQUIRED');end if;
  select count(*)into n from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=p_task and ACTIVE_FLAG=1;
  if n>0 then raise_application_error(-20873,'CASE_LABEL_ALREADY_PACKED');end if;
  select count(*)into n from RRL_CASE_SSCC_LABEL where CASE_PICK_TASK_ID=p_task;
  if n>0 then raise_application_error(-20873,'CASE_LABEL_REPRINT_EXISTING');end if;
  code:=RRL_SSCC_ALLOCATOR.allocate(ct.WARE_ID,p_actor,'case_pick_execute');
  r.put('case_pick_task_id',p_task);r.put('sscc',code);r.put('original_carrier',ct.SSCC);r.put('content_version',ct.CONTENT_VERSION+1);
  r.put('operation_id',op);r.put('confirmed',false);p_result:=r.to_clob;
  trusted(p_actor);
  insert into RRL_CASE_SSCC_LABEL(OPERATION_ID,CASE_PICK_TASK_ID,SSCC,ORIGINAL_CARRIER,WARE_ID,PALLET_TYPE_ID,REQUESTED_VERSION,CREATED_BY,REQUEST_JSON,RESULT_JSON)
   values(op,p_task,code,ct.SSCC,ct.WARE_ID,ct.PALLET_TYPE_ID,ct.CONTENT_VERSION,p_actor,p_request,p_result);
  update RRL_CASE_PICK_TASK set SSCC=code,CONTENT_VERSION=CONTENT_VERSION+1,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=p_task;
  clear_context;
 exception when others then clear_context;raise;
 end;
 procedure confirm_label(p_task number,p_sscc varchar2,p_actor varchar2,p_result out clob)is
  ct RRL_CASE_PICK_TASK%rowtype;lbl RRL_CASE_SSCC_LABEL%rowtype;r json_object_t:=json_object_t();
 begin
  fence;RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,'case_pick_execute');
  select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task for update;
  RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,'case_pick_execute');
  select *into lbl from RRL_CASE_SSCC_LABEL where CASE_PICK_TASK_ID=p_task for update;
  if p_sscc is null or p_sscc!=lbl.SSCC or ct.SSCC!=lbl.SSCC then raise_application_error(-20873,'SCAN_ATTACHED_CASE_SSCC');end if;
  if lbl.CONFIRMED_AT is null then
   if ct.STATUS not in('NEW','ASSIGNED','IN_PROGRESS')or nvl(ct.PICKED_QTY,0)!=0 then raise_application_error(-20873,'CASE_LABEL_CONFIRM_BEFORE_FILL');end if;
   trusted(p_actor);
   update RRL_CASE_SSCC_LABEL set CONFIRMED_AT=systimestamp,CONFIRMED_BY=p_actor where CASE_PICK_TASK_ID=p_task;
   clear_context;
  end if;
  r.put('case_pick_task_id',p_task);r.put('sscc',lbl.SSCC);r.put('confirmed',true);p_result:=r.to_clob;
 exception when others then clear_context;raise;
 end;
 procedure assert_ready(p_task number)is
  required number;carrier varchar2(64);code varchar2(18);confirmed timestamp with time zone;
 begin
  select case when p.FINAL_WEIGHT_REQUIRED=1 and upper(p.LOAD_UNIT_CLASS)='CONTAINER'then 1 else 0 end,c.SSCC into required,carrier
   from RRL_CASE_PICK_TASK c join RRL_PALLET_TYPE p on p.PALLET_TYPE_ID=c.PALLET_TYPE_ID where c.CASE_PICK_TASK_ID=p_task;
  begin select SSCC,CONFIRMED_AT into code,confirmed from RRL_CASE_SSCC_LABEL where CASE_PICK_TASK_ID=p_task;
  exception when no_data_found then if required=0 then return;end if;raise_application_error(-20887,'SMALL_BOX_CONFIRMED_SSCC_REQUIRED');end;
  if carrier!=code or confirmed is null then raise_application_error(-20887,'CASE_ATTACHED_SSCC_CONFIRM_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_CASE_TASK_ACCESS as
 procedure assert_scope(p_task number,p_actor varchar2,p_permission varchar2,p_assignee varchar2 default null)is
  v_ware number;v_user_ware number;v_group varchar2(100);v_permission varchar2(100):=lower(trim(p_permission));
  procedure check_user(p_user varchar2)is begin
   begin
    select WARE_ID,USER_GROUP into v_user_ware,v_group from RUSERS where ID=p_user and nvl(DELETED,0)=0;
   exception when no_data_found then raise_application_error(-20882,'CASE_ACTIVE_USER_REQUIRED');end;
   if upper(trim(v_group))='GLOBAL_ADMIN'then return;end if;
   if v_user_ware is null or v_user_ware!=v_ware then raise_application_error(-20882,'CASE_USER_WAREHOUSE_FORBIDDEN');end if;
  end;
 begin
  if v_permission is null or v_permission not in('case_pick_view','case_pick_execute','case_pick_manage','case_pick_short_approve','case_move')then
   raise_application_error(-20882,'CASE_ACCESS_PERMISSION_REQUIRED');end if;
  select WARE_ID into v_ware from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task;
  if v_ware is null or v_ware<1 then raise_application_error(-20886,'CASE_TASK_WARE_REQUIRED');end if;
  check_user(p_actor);
  if v_permission='case_move'then
   if RRL_HAS_WRIGHT(p_actor,'case_pick_execute')!=1 and RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then
    raise_application_error(-20882,'CASE_CURRENT_MOVE_FORBIDDEN');end if;
  elsif RRL_HAS_WRIGHT(p_actor,v_permission)!=1 then raise_application_error(-20882,'CASE_CURRENT_ACTION_FORBIDDEN');end if;
  if p_assignee is not null and p_assignee!=p_actor then check_user(p_assignee);end if;
 exception when no_data_found then raise_application_error(-20886,'CASE_TASK_IDENTITY_MISSING');
 end;
 procedure assert_command(p_request clob,p_actor varchar2)is
  d json_object_t:=json_object_t.parse(p_request);s json_object_t;v_kind varchar2(80);v_task number;v_short number;v_permission varchar2(100);
 begin
  v_kind:=d.get_string('command_type');
  if v_kind is null or v_kind not in('CASE_PICK_CONFIRM','CASE_CARRIER_MOVE','CASE_CARRIER_RETURN','CASE_SHORT_APPROVE')then return;end if;
  s:=d.get_object('source');
  if v_kind='CASE_SHORT_APPROVE'then
   v_short:=s.get_number('short_id');select CASE_PICK_TASK_ID into v_task from RRL_CASE_PICK_SHORT where CASE_PICK_SHORT_ID=v_short;
   v_permission:='case_pick_short_approve';
  else
   v_task:=s.get_number('case_task_id');
   v_permission:=case v_kind when 'CASE_CARRIER_MOVE'then'case_move'when'CASE_CARRIER_RETURN'then'case_pick_manage'else'case_pick_execute'end;
  end if;
  assert_scope(v_task,p_actor,v_permission);
 exception when no_data_found then raise_application_error(-20886,'CASE_TASK_IDENTITY_MISSING');
 end;
end;
/


CREATE OR REPLACE package body RRL_CASE_WEIGHT_DECISION as
 function current_json(p_request clob,p_task number,p_line number,p_actor varchar2)return clob is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');
  j json_object_t:=json_object_t.parse(RRL_ORDER_WEIGHT_READ.snapshot_json(p_task,p_line,p_actor));
  reason_value varchar2(1000);
 begin
  if RRL_HAS_WRIGHT(p_actor,'case_pick_short_approve')!=1 then raise_application_error(-20882,'WEIGHT_DECISION_APPROVER_REQUIRED');end if;
  reason_value:=m.get_string('reason');
  if reason_value is null or length(trim(reason_value))<3 or lengthb(reason_value)>1000 then raise_application_error(-20886,'WEIGHT_DECISION_REASON_REQUIRED');end if;
  if m.get_number('expected_weight_policy_version')is null or m.get_number('expected_content_version')is null
   or m.get_number('expected_weight_policy_version')!=j.get_number('policy_version')
   or m.get_number('expected_content_version')!=j.get_number('content_version')
   then raise_application_error(-20886,'WEIGHT_DECISION_CURRENT_VERSIONS_REQUIRED');end if;
  if m.get_string('expected_order_weight_signature')is null
   or m.get_string('expected_order_weight_signature')!=j.get_string('order_weight_signature')
   then raise_application_error(-20886,'WEIGHT_DECISION_ORDER_SNAPSHOT_CHANGED');end if;
  if not j.get_boolean('within_tolerance')then raise_application_error(-20886,'ORDER_WEIGHT_OUTSIDE_SKU_TOLERANCE');end if;
  return j.to_clob;
 end;
 procedure plan_order(p_order number,p_article varchar2,p_resources in out json_array_t)is n number:=0;
 begin
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(p_order));
  for o in(select CUSTOMER_ORDER_ROW_ID from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ID=p_order and ARTICUL=p_article
   order by CUSTOMER_ORDER_ROW_ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20881,'WEIGHT_DECISION_ORDER_ROWS_BOUND');end if;
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CUSTOMER_ORDER_ROW',RRL_STOCK_PLAN_HELPER.decimal_text(o.CUSTOMER_ORDER_ROW_ID));
  end loop;
  n:=0;
  for pt in(select pt.PICK_TASK_ID,pt.PICK_PLAN_ID,pt.PICK_PLAN_LINE_ID from RRL_PICK_TASK pt
   join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=pt.PICK_PLAN_LINE_ID
   join RRL_CUSTOMER_ORDER_ROW cr on cr.CUSTOMER_ORDER_ROW_ID=pl.CUSTOMER_ORDER_ROW_ID
   where cr.CUSTOMER_ORDER_ID=p_order and cr.ARTICUL=p_article
   order by pt.PICK_TASK_ID fetch first 2001 rows only)loop
   n:=n+1;if n>2000 then raise_application_error(-20881,'WEIGHT_DECISION_PICK_TASKS_BOUND');end if;
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(pt.PICK_TASK_ID));
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(pt.PICK_PLAN_ID));
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_PLAN_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(pt.PICK_PLAN_LINE_ID));
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_CASE_WEIGHT_SCAN as
 procedure assert_scan(p_request clob,p_article varchar2,p_line number,p_previous number)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');b json_object_t;
  enabled number;version number;raw_scan varchar2(512);key_value varchar2(64);identity varchar2(100);mass number;n number;fact number;
 begin
  select nvl(max(SERIALIZED_WEIGHT_BOXES),0),max(POLICY_VERSION)into enabled,version from RRL_SKU_RECEIPT_POLICY where ARTICUL=p_article;
  if enabled=0 then
   if m.has('weighted_box_scan')then raise_application_error(-20886,'WEIGHT_BOX_SKU_MODE_DISABLED');end if;
   return;
  end if;
  if not m.has('weighted_box_scan')or not m.has('weighted_policy_version')or m.get_number('weighted_policy_version')is null
   or m.get_number('weighted_policy_version')!=version or d.get_array('units').get_size!=1 then
   raise_application_error(-20886,'WEIGHT_BOX_CURRENT_LABEL_SINGLE_PHYSICAL_UNIT_REQUIRED');end if;
  if lengthb(m.get_string('weighted_box_scan'))>512 then raise_application_error(-20886,'WEIGHT_BOX_SCAN_BOUND_512');end if;
  raw_scan:=m.get_string('weighted_box_scan');b:=json_object_t.parse(RRL_WEIGHT_BOX_READ.decode_json(raw_scan));
  RRL_WEIGHT_BOX_READ.assert_sku(p_article,b.get_string('gtin'));
  identity:=b.get_string('identity');mass:=RRL_STOCK_MATH.quantity(b.get_string('net_weight_kg'));
  key_value:=d.get_array('units').get_string(0);
  fact:=RRL_STOCK_MATH.quantity(m.get_string('fact_qty'));
  if fact-nvl(p_previous,0)!=mass then raise_application_error(-20886,'WEIGHT_BOX_FACT_DELTA_MUST_EQUAL_LABEL_NET_KG');end if;
  select count(*)into n from RRL_WMS_RECEIPT_UNIT u join RRL_PALLETS lot on lot.UID_PALLET=u.CURRENT_UID
   join RRL_CASE_PICK_LINE l on l.CASE_PICK_LINE_ID=p_line and l.ARTICUL=lot.ARTICUL and l.CELL_CODE=u.CURRENT_CELL
   join RRL_STOCK_RESERVATION r on r.RESERVATION_ID=u.HARD_RESERVATION_ID and r.UID_PALLET=u.CURRENT_UID and r.CELL=u.CURRENT_CELL
    and r.SOURCE_DOC_TYPE='PICK_WAVE'and r.SOURCE_DOC_ID=l.PICK_WAVE_ID and r.SOURCE_LINE_ID=l.PICK_TASK_ID
   where lot.ARTICUL=p_article and u.PHYSICAL_UNIT_KEY=key_value and u.UNIT_ID=identity and u.BASE_UOM='KG'and u.BASE_QTY=mass
    and u.STOCK_STATUS!='ISSUED'and r.RESERVATION_KIND='HARD'and r.STATUS in('ACTIVE','ALLOCATED','PICKING')and r.BASE_QTY>=mass;
  if n!=1 then raise_application_error(-20886,'WEIGHT_BOX_CURRENT_PHYSICAL_IDENTITY_MASS_OWN_HARD_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_CLUSTER_CREATE_API as
 g_operation varchar2(100);g_tx varchar2(100);
 function write_allowed(p_operation varchar2)return number is begin
  if p_operation=g_operation and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure actor_allowed(p_actor varchar2)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'transport_dispatch_edit')=1;
  if n!=1 then raise_application_error(-20882,'CLUSTER_ACTIVE_DISPATCHER_REQUIRED');end if;
 end;
 procedure check_saved_scope(p_result clob,p_actor varchar2)is b json_object_t;wares json_array_t;begin
  b:=json_object_t.parse(p_result);wares:=b.get_array('warehouse_ids');
  for i in 0..wares.get_size-1 loop RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,wares.get_number(i));end loop;
 end;
 procedure create_cluster(p_operation varchar2,p_actor varchar2,p_request clob,p_sts clob,p_result out clob)is
  request_text varchar2(4000);request_hash varchar2(64);saved RRL_CLUSTER_CREATE_RESULT%rowtype;
  b json_object_t;fields json_object_t:=json_object_t();numbers json_array_t;wares json_array_t:=json_array_t();
  seen json_object_t:=json_object_t();v_trip number;v_day date;v_count number:=0;v_ware number;v_check clob;
  result json_object_t;assigned json_object_t;
 begin
  savepoint RRL_CLUSTER139;
  actor_allowed(p_actor);
  if p_operation is null or lengthb(p_operation)>100 then raise_application_error(-20886,'CLUSTER_OPERATION_ID_REQUIRED');end if;
  if p_request is null or dbms_lob.getlength(p_request)>2000 then raise_application_error(-20886,'CLUSTER_REQUEST_BOUND_2000');end if;
  request_text:=dbms_lob.substr(p_request,2000,1);
  select lower(rawtohex(standard_hash(request_text,'SHA256')))into request_hash from dual;
  g_operation:=p_operation;g_tx:=dbms_transaction.local_transaction_id(true);
  begin
   insert into RRL_CLUSTER_CREATE_RESULT(OPERATION_ID,ACTOR,REQUEST_HASH,REQUEST_JSON)
    values(p_operation,p_actor,request_hash,p_request);
  exception when dup_val_on_index then
   select *into saved from RRL_CLUSTER_CREATE_RESULT where OPERATION_ID=p_operation;
   if saved.ACTOR!=p_actor or saved.REQUEST_HASH!=request_hash then raise_application_error(-20886,'CLUSTER_OPERATION_PAYLOAD_CONFLICT');end if;
   if saved.RESULT_JSON is null then raise_application_error(-20886,'CLUSTER_RESULT_INCOMPLETE');end if;
   check_saved_scope(saved.RESULT_JSON,p_actor);p_result:=saved.RESULT_JSON;g_operation:=null;g_tx:=null;return;
  end;
  if p_sts is null or dbms_lob.getlength(p_sts)>65536 then raise_application_error(-20886,'CLUSTER_SOURCE_JSON_BOUND');end if;
  b:=json_object_t.parse(p_request);numbers:=json_array_t.parse(p_sts);
  if numbers.get_size<1 or numbers.get_size>200 then raise_application_error(-20886,'CLUSTER_SELECT_1_200_STS');end if;
  -- Store the first selected source snapshot. Native assignment rechecks each locked source.
  for item in(select distinct WARE_ID from RRL_SBORKA_PALLETS sp where ST_NUMBER in(
    select ST_NUMBER from json_table(p_sts,'$[*]'columns(ST_NUMBER varchar2(100)path '$')))order by WARE_ID)loop
   RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,item.WARE_ID);wares.append(item.WARE_ID);
  end loop;
  if wares.get_size=0 then raise_application_error(-20886,'CLUSTER_CURRENT_SOURCE_REQUIRED');end if;
  v_day:=to_date(b.get_string('stdate'),'FXYYYY-MM-DD');
  RRL_TRANSPORT_EDIT_API.create_trip(b.get_string('transtype'),v_day,p_actor,v_trip);
  if b.has('vehicle')and not b.get('vehicle').is_null then fields.put('transport',b.get_string('vehicle'));end if;
  if b.has('driver_id')and not b.get('driver_id').is_null then fields.put('voditel_id',b.get_number('driver_id'));end if;
  if b.has('dock')and not b.get('dock').is_null then fields.put('dock',b.get_string('dock'));end if;
  if fields.get_size>0 then RRL_TRANSPORT_EDIT_API.update_trip(v_trip,p_actor,fields.to_clob,v_check);end if;
  RRL_TRANSPORT_PLAN_API.assign_sts(v_trip,p_sts,p_actor,v_check);assigned:=json_object_t.parse(v_check);
  -- Capture warehouse scope after assignment, not the unlocked discovery.
  wares:=json_array_t();
  for item in(select distinct WARE_ID from RRL_SBORKA_PALLETS where TRANSTASK_ID=v_trip order by WARE_ID)loop
   RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,item.WARE_ID);wares.append(item.WARE_ID);
  end loop;
  result:=json_object_t();result.put('task_id',v_trip);result.put('raion',b.get_string('raion'));
  v_count:=numbers.get_size;result.put('st_count',v_count);result.put('warnings',assigned.get('warnings'));
  result.put('operation_id',p_operation);result.put('warehouse_ids',wares);result.put('source_st_numbers',numbers);
  result.put('stock_changed',false);p_result:=result.to_clob;
  update RRL_CLUSTER_CREATE_RESULT set TRIP_ID=v_trip,RESULT_JSON=p_result where OPERATION_ID=p_operation;
  g_operation:=null;g_tx:=null;
 exception when others then rollback to RRL_CLUSTER139;g_operation:=null;g_tx:=null;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_CUSTOMER_ORDER_API as
  function normalize_key(p_value varchar2) return varchar2 deterministic is
    v_value varchar2(255);
  begin
    v_value := regexp_replace(upper(trim(nvl(p_value, 'NO_ADDRESS'))), '[[:space:]]+', ' ');
    return substr(v_value, 1, 255);
  end normalize_key;

  function ensure_customer_from_legacy_addr(
    p_legacy_addr varchar2,
    p_created_by  varchar2 default null
  ) return number is
    v_key varchar2(255);
    v_customer_id number;
    v_store_map_id number;
    v_addr varchar2(255);
  begin
    v_key := normalize_key(p_legacy_addr);
    v_addr := substr(nvl(p_legacy_addr, 'NO_ADDRESS'), 1, 255);

    begin
      select CUSTOMER_ID
        into v_customer_id
        from RRL_CUSTOMER_STORE_MAP
       where LEGACY_ADDR_KEY = v_key
         and ACTIVE = 1;
      return v_customer_id;
    exception
      when no_data_found then
        null;
    end;

    select RRL_CUSTOMER_SQ.nextval into v_customer_id from dual;

    insert into RRL_CUSTOMER (
      CUSTOMER_ID, CUSTOMER_CODE, CUSTOMER_NAME, CUSTOMER_TYPE,
      ACTIVE, CREATED_AT, CREATED_BY
    ) values (
      v_customer_id,
      'LEGACY_ADDR_' || to_char(v_customer_id),
      v_addr,
      'STORE',
      1,
      sysdate,
      substr(p_created_by, 1, 50)
    );

    insert into RRL_CUSTOMER_ADDRESS (
      CUSTOMER_ADDRESS_ID, CUSTOMER_ID, ADDRESS_TYPE, ADDRESS_TEXT,
      ACTIVE, CREATED_AT, CREATED_BY
    ) values (
      RRL_CUSTOMER_ADDRESS_SQ.nextval,
      v_customer_id,
      'DELIVERY',
      v_addr,
      1,
      sysdate,
      substr(p_created_by, 1, 50)
    );

    select RRL_CUSTOMER_STORE_MAP_SQ.nextval into v_store_map_id from dual;
    insert into RRL_CUSTOMER_STORE_MAP (
      CUSTOMER_STORE_MAP_ID, CUSTOMER_ID, LEGACY_ADDR, LEGACY_ADDR_KEY,
      STORE_CODE, STORE_NAME, ADDRESS_TEXT, ACTIVE, CREATED_AT, CREATED_BY
    ) values (
      v_store_map_id,
      v_customer_id,
      v_addr,
      v_key,
      'LEGACY_ADDR_' || to_char(v_customer_id),
      v_addr,
      v_addr,
      1,
      sysdate,
      substr(p_created_by, 1, 50)
    );

    return v_customer_id;
  end ensure_customer_from_legacy_addr;

  procedure sync_fulfillment_from_legacy(
    p_customer_order_id number,
    p_created_by        varchar2 default null
  ) is
    v_order_no varchar2(100);
  begin
    select ORDER_NO
      into v_order_no
      from RRL_CUSTOMER_ORDER
     where CUSTOMER_ORDER_ID = p_customer_order_id;

    insert into RRL_CUSTOMER_ORDER_FULFILLMENT (
      FULFILLMENT_ID, CUSTOMER_ORDER_ID, LEGACY_SBORKA_PALLET_ID,
      PALLET_UID, ADDRESS_TEXT, STATUS, FACT_QTY, FACT_WEIGHT,
      SOURCE_SYSTEM, CREATED_AT, CREATED_BY
    )
    select RRL_CUSTOMER_ORDER_FULF_SQ.nextval,
           p_customer_order_id,
           src.ID,
           src.PALLET_UID,
           src.ADDR,
           'LEGACY_FACT',
           src.FACT_QTY,
           src.FACT_WEIGHT,
           'LEGACY_WMS',
           sysdate,
           substr(p_created_by, 1, 50)
      from (
        select sp.ID,
               sp.PALLET_UID,
               sp.ADDR,
               sum(nvl(spr.QUANTITY, 0)) FACT_QTY,
               sum(nvl(spr.ORDER_WEIGHT, 0)) FACT_WEIGHT
          from RRL_SBORKA_PALLETS sp
          left join RRL_SBORKA_PALLET_ROWS spr
            on spr.PALLET_UID = sp.PALLET_UID
         where sp.ID is not null
           and (
                sp.ORIGINAL_ORDER_NUMBER = v_order_no
             or sp.ST_NUMBER = v_order_no
             or sp.ORIGINAL_ST_NUMBER = v_order_no
             or sp.NAKLAD_NUMBER = v_order_no
           )
           and not exists (
             select 1
               from RRL_CUSTOMER_ORDER_FULFILLMENT f
              where f.CUSTOMER_ORDER_ID = p_customer_order_id
                and f.LEGACY_SBORKA_PALLET_ID = sp.ID
           )
         group by sp.ID, sp.PALLET_UID, sp.ADDR
      ) src;
  end sync_fulfillment_from_legacy;

  function import_legacy_order(
    p_legacy_order_id number,
    p_created_by      varchar2 default null
  ) return number is
    v_order RRL_ORDERS%rowtype;
    v_customer_id number;
    v_store_map_id number;
    v_customer_order_id number;
  begin
    begin
      select CUSTOMER_ORDER_ID
        into v_customer_order_id
        from RRL_CUSTOMER_ORDER
       where LEGACY_ORDER_ID = p_legacy_order_id;

      sync_fulfillment_from_legacy(v_customer_order_id, p_created_by);
      return v_customer_order_id;
    exception
      when no_data_found then
        null;
    end;

    select *
      into v_order
      from RRL_ORDERS
     where ID = p_legacy_order_id;

    v_customer_id := ensure_customer_from_legacy_addr(v_order.ADDR, p_created_by);

    select CUSTOMER_STORE_MAP_ID
      into v_store_map_id
      from RRL_CUSTOMER_STORE_MAP
     where LEGACY_ADDR_KEY = normalize_key(v_order.ADDR)
       and ACTIVE = 1;

    select RRL_CUSTOMER_ORDER_SQ.nextval into v_customer_order_id from dual;

    insert into RRL_CUSTOMER_ORDER (
      CUSTOMER_ORDER_ID, LEGACY_ORDER_ID, ORDER_NO, CUSTOMER_ID,
      CUSTOMER_STORE_MAP_ID, WARE_ID, ORDER_DATE, SHIPMENT_DATE,
      STATUS, SOURCE_SYSTEM, SOURCE_CREATED_BY, CREATED_AT, CREATED_BY
    ) values (
      v_customer_order_id,
      v_order.ID,
      substr(v_order.ORD_NUMBER, 1, 100),
      v_customer_id,
      v_store_map_id,
      v_order.WARE_ID,
      v_order.CREATE_DATE,
      v_order.ORDDATE,
      'IMPORTED',
      'LEGACY_WMS',
      substr(v_order.USER_ID, 1, 50),
      sysdate,
      substr(p_created_by, 1, 50)
    );

    insert into RRL_CUSTOMER_ORDER_ROW (
      CUSTOMER_ORDER_ROW_ID, CUSTOMER_ORDER_ID, LEGACY_ORDER_ROW_ID,
      LINE_NO, ARTICUL, PRODUCT_NAME, UNIT_CODE, ORDER_QTY, ORDER_WEIGHT,
      PACK_COUNT, WARE_ID, MOD_ID, SORTFIELD, CONDITION_CODE,
      STATUS, CREATED_AT, CREATED_BY
    )
    select RRL_CUSTOMER_ORDER_ROW_SQ.nextval,
           v_customer_order_id,
           r.ID,
           row_number() over (order by nvl(r.SORTFIELD, r.ID), r.ID) * 10,
           upper(substr(r.ARTICUL, 1, 40)),
           substr(r.SHORTNAME, 1, 255),
           upper(substr(r.EI, 1, 20)),
           nvl(r.QUANTITY, 0),
           r.ORDER_WEIGHT,
           r.PACK_COUNT,
           r.WARE_ID,
           r.MOD_ID,
           r.SORTFIELD,
           r.CONDITION,
           'OPEN',
           sysdate,
           substr(p_created_by, 1, 50)
      from RRL_ORDER_ROWS r
     where r.ORDER_ID = p_legacy_order_id;

    sync_fulfillment_from_legacy(v_customer_order_id, p_created_by);

    return v_customer_order_id;
  exception
    when no_data_found then
      raise_application_error(-20960, 'legacy order not found');
  end import_legacy_order;
end RRL_CUSTOMER_ORDER_API;
/


CREATE OR REPLACE package body RRL_CUSTOMER_RULE_API as
  function resolve_vehicle_type(
    p_customer_id           number,
    p_customer_store_map_id number default null
  ) return number is
    v_vehicle_type_id number;
  begin
    begin
      select VEHICLE_TYPE_ID
        into v_vehicle_type_id
        from (
          select a.VEHICLE_TYPE_ID
            from RRL_CUSTOMER_ADDRESS a
           where a.CUSTOMER_ID = p_customer_id
             and a.ACTIVE = 1
             and a.VEHICLE_TYPE_ID is not null
             and a.ADDRESS_TYPE in ('DELIVERY', 'STORE')
           order by case when a.ADDRESS_TYPE = 'DELIVERY' then 0 else 1 end,
                    a.CUSTOMER_ADDRESS_ID
        )
       where rownum = 1;
      return v_vehicle_type_id;
    exception
      when no_data_found then
        null;
    end;

    begin
      select VEHICLE_TYPE_ID
        into v_vehicle_type_id
        from (
          select r.VEHICLE_TYPE_ID
            from RRL_CUSTOMER_VEHICLE_RULE r
           where r.CUSTOMER_ID = p_customer_id
             and r.ACTIVE = 1
             and (r.CUSTOMER_STORE_MAP_ID = p_customer_store_map_id or r.CUSTOMER_STORE_MAP_ID is null)
             and trunc(sysdate) between r.VALID_FROM and nvl(r.VALID_TO, date '2999-12-31')
           order by case when r.CUSTOMER_STORE_MAP_ID = p_customer_store_map_id then 0 else 1 end,
                    r.RULE_PRIORITY,
                    r.CUSTOMER_VEHICLE_RULE_ID
        )
       where rownum = 1;
      return v_vehicle_type_id;
    exception
      when no_data_found then
        null;
    end;

    begin
      select DEFAULT_VEHICLE_TYPE_ID
        into v_vehicle_type_id
        from RRL_CUSTOMER
       where CUSTOMER_ID = p_customer_id
         and DEFAULT_VEHICLE_TYPE_ID is not null;
      return v_vehicle_type_id;
    exception
      when no_data_found then
        null;
    end;

    select VEHICLE_TYPE_ID
      into v_vehicle_type_id
      from RRL_VEHICLE_TYPE
     where VEHICLE_TYPE_CODE = 'TRUCK_33';

    return v_vehicle_type_id;
  end resolve_vehicle_type;

  function split_order_by_pallet_capacity(
    p_customer_order_id  number,
    p_total_pallet_count number,
    p_vehicle_type_id    number default null,
    p_created_by         varchar2 default null
  ) return number is
    v_order RRL_CUSTOMER_ORDER%rowtype;
    v_vehicle_type_id number;
    v_max_pallet_count number;
    v_remaining number;
    v_part_no number := 0;
    v_part_count number := 0;
    v_part_pallets number;
  begin
    if p_total_pallet_count is null or p_total_pallet_count < 0 then
      raise_application_error(-20970, 'total pallet count must be greater than or equal to zero');
    end if;

    select *
      into v_order
      from RRL_CUSTOMER_ORDER
     where CUSTOMER_ORDER_ID = p_customer_order_id;

    v_vehicle_type_id := nvl(p_vehicle_type_id, resolve_vehicle_type(v_order.CUSTOMER_ID, v_order.CUSTOMER_STORE_MAP_ID));

    select nvl((
             select max(nvl(a.MAX_PALLET_COUNT, vt.MAX_PALLET_COUNT))
               from RRL_CUSTOMER_ADDRESS a
              where a.CUSTOMER_ID = v_order.CUSTOMER_ID
                and a.VEHICLE_TYPE_ID = v_vehicle_type_id
                and a.ACTIVE = 1
           ), nvl((
             select max(nvl(r.MAX_PALLET_COUNT, vt.MAX_PALLET_COUNT))
               from RRL_CUSTOMER_VEHICLE_RULE r
              where r.CUSTOMER_ID = v_order.CUSTOMER_ID
                and r.VEHICLE_TYPE_ID = v_vehicle_type_id
                and r.ACTIVE = 1
                and trunc(sysdate) between r.VALID_FROM and nvl(r.VALID_TO, date '2999-12-31')
           ), vt.MAX_PALLET_COUNT))
      into v_max_pallet_count
      from RRL_VEHICLE_TYPE vt
     where vt.VEHICLE_TYPE_ID = v_vehicle_type_id;

    if v_max_pallet_count is null or v_max_pallet_count <= 0 then
      v_max_pallet_count := p_total_pallet_count;
    end if;

    if v_max_pallet_count <= 0 then
      v_max_pallet_count := 1;
    end if;

    v_remaining := p_total_pallet_count;

    while v_remaining > 0 loop
      v_part_no := v_part_no + 1;
      v_part_pallets := least(v_remaining, v_max_pallet_count);

      merge into RRL_SHIPMENT_PART d
      using (
        select p_customer_order_id CUSTOMER_ORDER_ID,
               v_part_no PART_NO
          from dual
      ) s
      on (d.CUSTOMER_ORDER_ID = s.CUSTOMER_ORDER_ID and d.PART_NO = s.PART_NO)
      when matched then update set
        d.VEHICLE_TYPE_ID = v_vehicle_type_id,
        d.PLANNED_PALLET_COUNT = v_part_pallets,
        d.UPDATED_AT = sysdate,
        d.UPDATED_BY = substr(p_created_by, 1, 50)
      when not matched then insert (
        SHIPMENT_PART_ID, CUSTOMER_ORDER_ID, ROUTE_ID, DOCK_ID,
        VEHICLE_TYPE_ID, PART_NO, PLANNED_PALLET_COUNT, STATUS,
        CREATED_AT, CREATED_BY
      ) values (
        RRL_SHIPMENT_PART_SQ.nextval, p_customer_order_id, v_order.ROUTE_ID, v_order.DOCK_ID,
        v_vehicle_type_id, v_part_no, v_part_pallets, 'PLANNED',
        sysdate, substr(p_created_by, 1, 50)
      );

      v_part_count := v_part_count + 1;
      v_remaining := v_remaining - v_part_pallets;
    end loop;

    return v_part_count;
  end split_order_by_pallet_capacity;
end RRL_CUSTOMER_RULE_API;
/


CREATE OR REPLACE package body RRL_DAY_INSPECT_API as
 g_tx varchar2(100);g_operation varchar2(100);g_actor varchar2(50);
 function write_allowed(p_operation varchar2,p_actor varchar2)return number is begin
  if g_tx is not null and g_tx=dbms_transaction.local_transaction_id(false)and g_operation=p_operation and g_actor=p_actor then return 1;end if;return 0;
 end;
 procedure access(p_ware number,p_actor varchar2,p_role varchar2)is n number;v_right varchar2(100);begin
  if p_role not in('WAREHOUSE_CHIEF','DISPATCHER')or p_role is null then raise_application_error(-20886,'DAY_INSPECTION_ROLE_REQUIRED');end if;
  v_right:=case when p_role='WAREHOUSE_CHIEF'then 'warehouse_day_inspect'else 'transport_dispatch_edit'end;
  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0
   and(u.WARE_ID=p_ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,v_right)=1
   and 1=(select count(*)from RRL_WARES where ID=p_ware);
  if n!=1 then raise_application_error(-20882,'DAY_INSPECTION_CURRENT_WARE_ACTOR_REQUIRED');end if;
 end;
 procedure lookup(p_actor varchar2,p_operation varchar2,p_body clob,p_result out clob)is
  b json_object_t;v_review varchar2(100);v_role varchar2(30);v_ware number;v_hash varchar2(64);old RRL_DAY_INSPECTION%rowtype;
 begin
  p_result:=null;
  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_body is null or dbms_lob.getlength(p_body)>4000 then raise_application_error(-20886,'DAY_INSPECTION_REQUEST_BOUND');end if;
  b:=json_object_t.parse(p_body);v_review:=b.get_string('review_operation_id');v_role:=b.get_string('inspection_role');
  select WARE_ID into v_ware from RRL_DAY_REVIEW where OPERATION_ID=v_review;access(v_ware,p_actor,v_role);
  v_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  begin
   select *into old from RRL_DAY_INSPECTION where OPERATION_ID=p_operation;
   if old.ACTOR!=p_actor or old.REQUEST_HASH!=v_hash or dbms_lob.compare(old.REQUEST_JSON,p_body)!=0 then raise_application_error(-20886,'DAY_INSPECTION_OPERATION_CONTENT_CONFLICT');end if;
   p_result:=old.RESULT_JSON;
  exception when no_data_found then null;end;
 exception when no_data_found then raise_application_error(-20886,'DAY_INSPECTION_REVIEW_REQUIRED');
 end;
 procedure resolve(p_actor varchar2,p_operation varchar2,p_body clob,p_result out clob)is
  b json_object_t;parent RRL_DAY_REVIEW%rowtype;v_review varchar2(100);v_role varchar2(30);
  f json_array_t:=json_array_t();resources json_array_t:=json_array_t();result json_object_t:=json_object_t();v_lock boolean:=false;
 begin
  lookup(p_actor,p_operation,p_body,p_result);if p_result is not null then return;end if;
  b:=json_object_t.parse(p_body);v_review:=b.get_string('review_operation_id');v_role:=b.get_string('inspection_role');
  select *into parent from RRL_DAY_REVIEW where OPERATION_ID=v_review;access(parent.WARE_ID,p_actor,v_role);
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.row_key(resources,'RRL_DAY_REVIEW',to_char(parent.WARE_ID,'TM9')||':'||to_char(parent.BUSINESS_DATE,'YYYY-MM-DD')||':'||parent.TIMEZONE_REGION);
  RRL_STOCK_PLAN_HELPER.row_key(resources,'RRL_DAY_INSPECTION',v_review);
  RRL_STOCK_PLAN_HELPER.anchor(resources,70,'UNIQUE','DAY.INSPECTION:'||p_operation);
  RRL_STOCK_LOCK_API.begin_plan;v_lock:=true;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(resources.to_clob);
  access(parent.WARE_ID,p_actor,v_role);lookup(p_actor,p_operation,p_body,p_result);
  if p_result is null then result.put('operation_id',p_operation);result.put('state','NOT_RECORDED');result.put('day_closed',false);p_result:=result.to_clob;end if;
  RRL_STOCK_LOCK_API.clear_plan;
 exception when others then if v_lock then RRL_STOCK_LOCK_API.clear_plan;end if;raise;
 end;
 procedure append_inspection(p_actor varchar2,p_operation varchar2,p_body clob,p_current_hash varchar2,p_checked_at varchar2,p_result out clob)is
  b json_object_t;parent RRL_DAY_REVIEW%rowtype;v_review varchar2(100);v_role varchar2(30);v_source varchar2(64);v_note varchar2(2000);v_observed boolean;v_empty number;
  f json_array_t:=json_array_t();resources json_array_t:=json_array_t();result json_object_t:=json_object_t();
  v_lock boolean:=false;v_saved boolean:=false;v_latest number;v_n number;v_checked timestamp with time zone;v_hash varchar2(64);
 begin
  lookup(p_actor,p_operation,p_body,p_result);if p_result is not null then return;end if;
  b:=json_object_t.parse(p_body);v_review:=b.get_string('review_operation_id');v_role:=b.get_string('inspection_role');v_source:=b.get_string('source_hash');v_note:=b.get_string('note');v_observed:=b.get_boolean('observed_empty');
  if b.get_size!=5 or v_observed is null or v_note is null or length(trim(v_note))<8 or lengthb(v_note)>2000 or v_source is null then raise_application_error(-20886,'DAY_INSPECTION_EXPLICIT_OBSERVATION_REQUIRED');end if;
  v_empty:=case when v_observed then 1 else 0 end;
  select *into parent from RRL_DAY_REVIEW where OPERATION_ID=v_review;access(parent.WARE_ID,p_actor,v_role);
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.row_key(resources,'RRL_DAY_REVIEW',to_char(parent.WARE_ID,'TM9')||':'||to_char(parent.BUSINESS_DATE,'YYYY-MM-DD')||':'||parent.TIMEZONE_REGION);
  RRL_STOCK_PLAN_HELPER.row_key(resources,'RRL_DAY_INSPECTION',v_review);
  RRL_STOCK_PLAN_HELPER.anchor(resources,70,'UNIQUE','DAY.INSPECTION:'||p_operation);
  RRL_STOCK_LOCK_API.begin_plan;v_lock:=true;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(resources.to_clob);
  savepoint RRL_DAY_INSPECT692;v_saved:=true;
  access(parent.WARE_ID,p_actor,v_role);lookup(p_actor,p_operation,p_body,p_result);
  if p_result is not null then RRL_STOCK_LOCK_API.clear_plan;return;end if;
  select max(VERSION_NO)into v_latest from RRL_DAY_REVIEW where WARE_ID=parent.WARE_ID and BUSINESS_DATE=parent.BUSINESS_DATE and TIMEZONE_REGION=parent.TIMEZONE_REGION;
  if parent.VERSION_NO!=v_latest then raise_application_error(-20886,'DAY_INSPECTION_LATEST_REVIEW_REQUIRED');end if;
  if v_source!=parent.SOURCE_HASH or p_current_hash is null or p_current_hash!=parent.SOURCE_HASH then raise_application_error(-20886,'DAY_INSPECTION_CURRENT_SOURCE_CHANGED');end if;
  v_checked:=to_timestamp_tz(p_checked_at,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
  if v_checked is null or v_checked<parent.CAPTURED_AT or v_checked>systimestamp then raise_application_error(-20886,'DAY_INSPECTION_SOURCE_CLOCK_REQUIRED');end if;
  select count(*)into v_n from RRL_DAY_INSPECTION where REVIEW_OPERATION_ID=v_review and INSPECTION_ROLE=v_role;
  if v_n!=0 then raise_application_error(-20886,'DAY_INSPECTION_ROLE_ALREADY_RECORDED');end if;
  select count(*)into v_n from RRL_DAY_INSPECTION where REVIEW_OPERATION_ID=v_review and ACTOR=p_actor;
  if v_n!=0 then raise_application_error(-20886,'DAY_INSPECTION_INDEPENDENT_ACTORS_REQUIRED');end if;
  result.put('operation_id',p_operation);result.put('review_operation_id',v_review);result.put('inspection_role',v_role);result.put('actor',p_actor);
  result.put('observed_empty',v_observed);result.put('note',v_note);result.put('source_hash',v_source);result.put('state','DECLARATION_RECORDED');
  result.put('source_checked_at',to_char(v_checked,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));result.put('day_closed',false);result.put('stock_changed',false);result.put('external_obligations_closed',false);
  p_result:=result.to_clob;v_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  g_tx:=dbms_transaction.local_transaction_id;g_operation:=p_operation;g_actor:=p_actor;
  insert into RRL_DAY_INSPECTION(OPERATION_ID,REVIEW_OPERATION_ID,INSPECTION_ROLE,ACTOR,OBSERVED_EMPTY,NOTE,REQUEST_JSON,REQUEST_HASH,SOURCE_HASH,SOURCE_CHECKED_AT,RESULT_JSON)
  values(p_operation,v_review,v_role,p_actor,v_empty,v_note,p_body,v_hash,v_source,v_checked,p_result);
  g_tx:=null;g_operation:=null;g_actor:=null;RRL_STOCK_LOCK_API.clear_plan;
 exception when others then
  g_tx:=null;g_operation:=null;g_actor:=null;if v_saved then rollback to RRL_DAY_INSPECT692;end if;
  if v_lock then RRL_STOCK_LOCK_API.clear_plan;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_DAY_REVIEW_API as
 g_tx varchar2(100);
 function write_allowed return number is begin
  if g_tx is not null and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure access(p_ware number,p_actor varchar2,p_right varchar2)is n number;begin
  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0
   and(u.WARE_ID=p_ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,p_right)=1
   and 1=(select count(*)from RRL_WARES where ID=p_ware);
  if n!=1 then raise_application_error(-20882,'DAY_REVIEW_CURRENT_WARE_ACTOR_REQUIRED');end if;
 end;
 procedure context(p_ware number,p_day date,p_zone varchar2,p_actor varchar2,p_result out clob)is
  v_version number;r json_object_t:=json_object_t();
 begin
  access(p_ware,p_actor,'transport_dispatch_view');
  select nvl(max(VERSION_NO),0)into v_version from RRL_DAY_REVIEW where WARE_ID=p_ware and BUSINESS_DATE=trunc(p_day)and TIMEZONE_REGION=p_zone;
  r.put('version',v_version);r.put('warehouse_id',p_ware);r.put('business_date',to_char(p_day,'YYYY-MM-DD'));r.put('timezone_region',p_zone);r.put('day_closed',false);p_result:=r.to_clob;
 end;
 procedure lookup(p_actor varchar2,p_operation varchar2,p_body clob,p_result out clob)is
  b json_object_t;saved RRL_DAY_REVIEW%rowtype;v_ware number;v_hash varchar2(64);
 begin
  b:=json_object_t.parse(p_body);v_ware:=b.get_number('warehouse_id');access(v_ware,p_actor,'transport_dispatch_edit');
  v_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  begin select *into saved from RRL_DAY_REVIEW where OPERATION_ID=p_operation;
   if saved.ACTOR!=p_actor or saved.WARE_ID!=v_ware or saved.REQUEST_HASH!=v_hash or dbms_lob.compare(saved.REQUEST_JSON,p_body)!=0 then raise_application_error(-20886,'DAY_REVIEW_OPERATION_PAYLOAD_CONFLICT');end if;
   access(saved.WARE_ID,p_actor,'transport_dispatch_edit');p_result:=saved.RESULT_JSON;
  exception when no_data_found then p_result:=null;end;
 end;
 procedure resolve(p_actor varchar2,p_operation varchar2,p_body clob,p_result out clob)is
  b json_object_t;f json_array_t:=json_array_t();resources json_array_t:=json_array_t();r json_object_t:=json_object_t();
  v_ware number;v_day date;v_zone varchar2(64);v_lock boolean:=false;
 begin
  if p_operation is null or lengthb(p_operation)>100 or p_body is null or dbms_lob.getlength(p_body)>4000 then raise_application_error(-20886,'DAY_REVIEW_RESOLVE_BOUND');end if;
  b:=json_object_t.parse(p_body);v_ware:=b.get_number('warehouse_id');v_day:=to_date(b.get_string('business_date'),'FXYYYY-MM-DD');v_zone:=b.get_string('timezone_region');
  access(v_ware,p_actor,'transport_dispatch_edit');
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.row_key(resources,'RRL_DAY_REVIEW',to_char(v_ware,'TM9')||':'||to_char(v_day,'YYYY-MM-DD')||':'||v_zone);
  RRL_STOCK_PLAN_HELPER.anchor(resources,70,'UNIQUE','DAY.REVIEW:'||p_operation);
  RRL_STOCK_LOCK_API.begin_plan;v_lock:=true;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(resources.to_clob);
  access(v_ware,p_actor,'transport_dispatch_edit');lookup(p_actor,p_operation,p_body,p_result);
  if p_result is null then r.put('operation_id',p_operation);r.put('state','NOT_RECORDED');r.put('day_closed',false);p_result:=r.to_clob;end if;
  RRL_STOCK_LOCK_API.clear_plan;
 exception when others then if v_lock then RRL_STOCK_LOCK_API.clear_plan;end if;raise;
 end;
 procedure append_review(p_actor varchar2,p_operation varchar2,p_body clob,p_material clob,p_captured timestamp with time zone,p_result out clob)is
  b json_object_t;material json_object_t;r json_object_t:=json_object_t();f json_array_t:=json_array_t();resources json_array_t:=json_array_t();
  v_ware number;v_day date;v_zone varchar2(64);v_version number;v_hash varchar2(64);v_source varchar2(64);v_open number;v_lock boolean:=false;v_saved boolean:=false;
 begin
  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_body is null or dbms_lob.getlength(p_body)>4000 then raise_application_error(-20886,'DAY_REVIEW_REQUEST_BOUND');end if;
  b:=json_object_t.parse(p_body);v_ware:=b.get_number('warehouse_id');v_zone:=b.get_string('timezone_region');
  v_day:=to_date(b.get_string('business_date'),'FXYYYY-MM-DD');
  access(v_ware,p_actor,'transport_dispatch_edit');
  if b.get_size!=6 or b.get_number('expected_version')is null or b.get_number('expected_version')<0 or b.get_number('expected_version')!=trunc(b.get_number('expected_version'))
   or v_zone is null or b.get_string('reason')is null or length(trim(b.get_string('reason')))<8 or b.get_string('source_hash')is null then raise_application_error(-20886,'DAY_REVIEW_EXPLICIT_SOURCE_REQUIRED');end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.row_key(resources,'RRL_DAY_REVIEW',to_char(v_ware,'TM9')||':'||to_char(v_day,'YYYY-MM-DD')||':'||v_zone);
  RRL_STOCK_PLAN_HELPER.anchor(resources,70,'UNIQUE','DAY.REVIEW:'||p_operation);
  RRL_STOCK_LOCK_API.begin_plan;v_lock:=true;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(resources.to_clob);
  savepoint RRL_DAY_REVIEW269;v_saved:=true;
  access(v_ware,p_actor,'transport_dispatch_edit');lookup(p_actor,p_operation,p_body,p_result);
  if p_result is not null then RRL_STOCK_LOCK_API.clear_plan;return;end if;
  select nvl(max(VERSION_NO),0)into v_version from RRL_DAY_REVIEW where WARE_ID=v_ware and BUSINESS_DATE=v_day and TIMEZONE_REGION=v_zone;
  if b.get_number('expected_version')!=v_version then raise_application_error(-20886,'DAY_REVIEW_VERSION_CHANGED');end if;
  if p_material is null or dbms_lob.getlength(p_material)>4*1024*1024 or p_captured is null or p_captured>systimestamp then raise_application_error(-20886,'DAY_REVIEW_CAPTURE_BOUND');end if;
  material:=json_object_t.parse(p_material);
  if not material.has('warehouse_id')or not material.has('business_date')or not material.has('timezone_region')or not material.has('consistent_snapshot')or not material.has('day_closed')then raise_application_error(-20886,'DAY_REVIEW_CAPTURE_FIELDS_REQUIRED');end if;
  if material.get_number('warehouse_id')is null or material.get_string('business_date')is null or material.get_string('timezone_region')is null or material.get_boolean('consistent_snapshot')is null or material.get_boolean('day_closed')is null then raise_application_error(-20886,'DAY_REVIEW_CAPTURE_FIELDS_REQUIRED');end if;
  if material.get_number('warehouse_id')!=v_ware or material.get_string('business_date')!=to_char(v_day,'YYYY-MM-DD')or material.get_string('timezone_region')!=v_zone
   or not material.get_boolean('consistent_snapshot')or material.get_boolean('day_closed')then raise_application_error(-20886,'DAY_REVIEW_CAPTURE_SCOPE_INVALID');end if;
  v_source:=lower(rawtohex(sys.dbms_crypto.hash(p_material,sys.dbms_crypto.hash_sh256)));
  if v_source!=b.get_string('source_hash')then raise_application_error(-20886,'DAY_REVIEW_SOURCE_CHANGED');end if;
  v_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  r.put('operation_id',p_operation);r.put('warehouse_id',v_ware);r.put('business_date',to_char(v_day,'YYYY-MM-DD'));r.put('timezone_region',v_zone);
  r.put('version',v_version+1);r.put('source_hash',v_source);r.put('actor',p_actor);r.put('reason',b.get_string('reason'));
  r.put('state','REVIEW_RECORDED');r.put('day_closed',false);r.put('stock_changed',false);r.put('external_obligations_closed',false);
  r.put('captured_at_utc',to_char(sys_extract_utc(p_captured),'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"'));r.put('report',material);p_result:=r.to_clob;g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_DAY_REVIEW(OPERATION_ID,WARE_ID,BUSINESS_DATE,TIMEZONE_REGION,VERSION_NO,ACTOR,REQUEST_HASH,REQUEST_JSON,SOURCE_HASH,REPORT_JSON,RESULT_JSON,CAPTURED_AT)
   values(p_operation,v_ware,v_day,v_zone,v_version+1,p_actor,v_hash,p_body,v_source,p_material,p_result,p_captured);
  g_tx:=null;RRL_STOCK_LOCK_API.clear_plan;
 exception when others then
  g_tx:=null;if v_saved then rollback to RRL_DAY_REVIEW269;end if;if v_lock then RRL_STOCK_LOCK_API.clear_plan;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_DIRECT_RECEIVING_PICK as
 function enabled(p_uid varchar2,p_cell varchar2,p_ware number,p_article varchar2)return number is n number;
 begin
  select count(*)into n from RRL_SAP_PALLET_RECEIPT rec join RRL_SAP_SUPPLY_ORDER so on so.ORDER_ID=rec.ORDER_ID
   join RRL_RECEIPT_SKU_RULE rule on rule.WARE_ID=p_ware and rule.ARTICUL=p_article and rule.SOURCE_PICK_MODE='DIRECT'
   where rec.UID_PALLET=p_uid and so.WARE_ID=p_ware and so.RECEIVE_CELL=p_cell;
  if n=0 then return 0;end if;
  select count(*)into n from RRL_WAREHOUSE_TASK where UID_PALLET=p_uid and FROM_CELL=p_cell
   and TASK_TYPE='PUTAWAY'and STATUS='IN_PROGRESS';
  if n>0 then raise_application_error(-20886,'DIRECT_RECEIVING_PUTAWAY_IN_PROGRESS');end if;
  return 1;
 end;
 procedure compile_holds(p_wave number,p_resources in out nocopy json_array_t,p_holds out clob)is
  a json_array_t:=json_array_t();x json_object_t;
 begin
  for t in(select distinct wh.TASK_ID,wh.UID_PALLET,wh.FROM_CELL,wh.FROM_WARE_ID,wh.STATUS,wh.QTY,wh.FACT_QTY,
    wh.TO_CELL_SLOT_ID,pr.ARTICUL,claim.CELL_SLOT_ID CLAIM_SLOT,claim.STATUS CLAIM_STATUS
   from RRL_PICK_WAVE_ORDER wo join RRL_PICK_RESERVATION pr on pr.PICK_PLAN_ID=wo.PICK_PLAN_ID
   join RRL_PICK_TASK pt on pt.PICK_TASK_ID=pr.PICK_TASK_ID
   join RRL_WAREHOUSE_TASK wh on wh.UID_PALLET=pr.PALLET_UID and wh.FROM_CELL=pr.SOURCE_CELL_CODE
   left join RRL_RECEIPT_SLOT_CLAIM claim on claim.TASK_ID=wh.TASK_ID
   where wo.PICK_WAVE_ID=p_wave and wo.STATUS='ACTIVE'and pr.RESERVATION_STATUS='ACTIVE'and pr.RESERVATION_LEVEL='SOFT'
    and pt.TASK_TYPE='CASE_PICK'and pt.TARGET_CELL_CODE is null
    and wh.TASK_TYPE='PUTAWAY'and wh.TASK_SOURCE='SAP_RECEIPT'and wh.STATUS not in('DONE','CANCELLED')
   order by wh.TASK_ID fetch first 201 rows only)loop
   if enabled(t.UID_PALLET,t.FROM_CELL,t.FROM_WARE_ID,t.ARTICUL)=0 then continue;end if;
   if a.get_size>=200 then raise_application_error(-20881,'DIRECT_RECEIVING_PUTAWAY_BOUND');end if;
   if t.STATUS not in('PLANNED','ASSIGNED','ERROR')or nvl(t.FACT_QTY,0)!=0
    or(t.CLAIM_STATUS is not null and t.CLAIM_STATUS!='RESERVED')then raise_application_error(-20886,'DIRECT_RECEIVING_PUTAWAY_ALREADY_PHYSICAL');end if;
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.TASK_ID));
   if t.CLAIM_SLOT is not null then
    RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(t.TASK_ID));
    RRL_STOCK_PLAN_HELPER.anchor(p_resources,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(t.CLAIM_SLOT));
   end if;
   x:=json_object_t();x.put('task_id',t.TASK_ID);x.put('uid',t.UID_PALLET);x.put('cell',t.FROM_CELL);x.put('status',t.STATUS);
   x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(t.QTY));x.put('slot',t.CLAIM_SLOT);a.append(x);
  end loop;
  p_holds:=a.to_clob;
 end;
 procedure apply_holds(p_holds clob,p_actor varchar2)is
  a json_array_t:=json_array_t.parse(p_holds);x json_object_t;t RRL_WAREHOUSE_TASK%rowtype;id number;slot_id number;n number;
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)
   then raise_application_error(-20863,'DIRECT_RECEIVING_NATIVE_OWNER_REQUIRED');end if;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i)as json_object_t);id:=x.get_number('task_id');slot_id:=x.get_number('slot');
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(id)));
   select *into t from RRL_WAREHOUSE_TASK where TASK_ID=id for update;
   if t.STATUS!=x.get_string('status')or t.UID_PALLET!=x.get_string('uid')or t.FROM_CELL!=x.get_string('cell')
    or RRL_STOCK_PLAN_HELPER.decimal_text(t.QTY)!=x.get_string('quantity')or nvl(t.FACT_QTY,0)!=0
    then raise_application_error(-20890,'CLOSURE_CHANGED: direct receiving putaway');end if;
   select count(*)into n from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=id;
   if slot_id is null and n>0 then raise_application_error(-20890,'CLOSURE_CHANGED: direct putaway claim');end if;
   if slot_id is not null then
    select count(*)into n from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=id and CELL_SLOT_ID=slot_id and STATUS='RESERVED';
    if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: direct putaway claim');end if;
    delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=id;
   end if;
   update RRL_WAREHOUSE_TASK set STATUS='CANCELLED',CANCELLED_AT=sysdate,CANCELLED_BY=p_actor,
    LAST_ERROR='DIRECT_PICK_BY_LINE:'||sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') where TASK_ID=id;
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_FORECAST_PROJECTOR as
 g_load varchar2(100);g_tx varchar2(100);g_ware number;g_day date;
 procedure reset_context is begin g_load:=null;g_tx:=null;g_ware:=null;g_day:=null;end;
 function load_write_allowed(p_load varchar2)return number is begin
  if g_load=p_load and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;end;
 function day_write_allowed(p_ware number,p_day date)return number is begin
  if g_ware=p_ware and g_day=p_day and g_load is not null and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;end;
 procedure increment_day is begin
  update RRL_FORECAST_DAY set LOAD_COUNT=LOAD_COUNT+1,TOP_PLACES=TOP_PLACES+1,LAST_LOAD_OPERATION=g_load where WARE_ID=g_ware and DAY_UTC=g_day;
  if sql%rowcount=0 then
   begin insert into RRL_FORECAST_DAY values(g_ware,g_day,1,1,g_load);
   exception when dup_val_on_index then update RRL_FORECAST_DAY set LOAD_COUNT=LOAD_COUNT+1,TOP_PLACES=TOP_PLACES+1,LAST_LOAD_OPERATION=g_load where WARE_ID=g_ware and DAY_UTC=g_day;end;
  end if;
 end;
 procedure increment_sku(p_article varchar2,p_base varchar2,p_kind varchar2,p_qty number,p_leaves number)is begin
  update RRL_FORECAST_SKU_DAY set BASE_QTY=BASE_QTY+p_qty,LEAF_COUNT=LEAF_COUNT+p_leaves,SOURCE_COUNT=SOURCE_COUNT+1 where WARE_ID=g_ware and DAY_UTC=g_day and ARTICLE=p_article and BASE_UOM=p_base and WORK_KIND=p_kind;
  if sql%rowcount=0 then
   begin insert into RRL_FORECAST_SKU_DAY values(g_ware,g_day,p_article,p_base,p_kind,p_qty,p_leaves,1);
   exception when dup_val_on_index then
    update RRL_FORECAST_SKU_DAY set BASE_QTY=BASE_QTY+p_qty,LEAF_COUNT=LEAF_COUNT+p_leaves,SOURCE_COUNT=SOURCE_COUNT+1 where WARE_ID=g_ware and DAY_UTC=g_day and ARTICLE=p_article and BASE_UOM=p_base and WORK_KIND=p_kind;
   end;
  end if;
 end;
 procedure project_load(p_load varchar2,p_actor varchar2,p_result out clob)is
  source_row RRL_TT_HU_LOAD_FACT%rowtype;raw_hash varchar2(64);old_hash varchar2(64);old_result clob;leaves clob;
  lines json_array_t;node json_object_t;result json_object_t:=json_object_t();qty number;uid varchar2(200);article varchar2(160);base varchar2(20);kind varchar2(20);case_id number;allowed number;
  type group_record is record(article varchar2(160),base varchar2(20),kind varchar2(20),qty number,leaves number);
  type group_map is table of group_record index by varchar2(500);groups group_map;key_text varchar2(500);
  leaf_total number;old_ware number;old_article varchar2(160);old_base varchar2(20);
 begin
  reset_context;
  select *into source_row from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=p_load;
  if source_row.STATUS!='DEPARTED'or source_row.DEPARTED_AT is null then raise_application_error(-20886,'FORECAST_DEPARTED_SOURCE_REQUIRED');end if;
  select count(*)into allowed from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0 and(u.WARE_ID=source_row.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,'transport_dispatch_edit')=1;
  if allowed!=1 then raise_application_error(-20882,'FORECAST_CURRENT_WARE_ACTOR_REQUIRED');end if;
  raw_hash:=lower(rawtohex(sys.dbms_crypto.hash(source_row.COMPOSITION_JSON,sys.dbms_crypto.hash_sh256)));
  begin select SOURCE_HASH,RESULT_JSON into old_hash,old_result from RRL_FORECAST_LOAD where LOAD_OPERATION_ID=p_load;
   if old_hash!=raw_hash then raise_application_error(-20886,'FORECAST_SOURCE_HASH_CHANGED');end if;p_result:=old_result;return;
  exception when no_data_found then null;end;
  RRL_FORECAST_SOURCE_RULES.compile_leaves(source_row.COMPOSITION_JSON,source_row.WARE_ID,leaves);lines:=json_array_t.parse(leaves);leaf_total:=lines.get_size;
  g_load:=p_load;g_ware:=source_row.WARE_ID;g_tx:=dbms_transaction.local_transaction_id(true);
  select trunc(cast(source_row.DEPARTED_AT at time zone 'UTC'as date))into g_day from dual;
  result.put('source_load_operation_id',p_load);result.put('warehouse_id',g_ware);result.put('source_hash',raw_hash);
  result.put('leaf_count',lines.get_size);result.put('top_places',1);result.put('day_utc',to_char(g_day,'YYYY-MM-DD'));
  result.put('stock_changed',false);result.put('status','PROJECTED');p_result:=result.to_clob;
  begin
   insert into RRL_FORECAST_LOAD(LOAD_OPERATION_ID,WARE_ID,DAY_UTC,DEPARTED_AT,SOURCE_HASH,LEAF_COUNT,TOP_PLACES,PROJECTED_BY,RESULT_JSON)
    values(p_load,g_ware,g_day,source_row.DEPARTED_AT,raw_hash,leaf_total,1,p_actor,p_result);
  exception when dup_val_on_index then
   select SOURCE_HASH,RESULT_JSON into old_hash,old_result from RRL_FORECAST_LOAD where LOAD_OPERATION_ID=p_load;
   if old_hash!=raw_hash then raise_application_error(-20886,'FORECAST_SOURCE_HASH_CHANGED');end if;p_result:=old_result;reset_context;return;
  end;
  -- compile_leaves returns stable CASE-origin/UID order; no warehouse-stock locks.
  for i in 0..lines.get_size-1 loop
   node:=treat(lines.get(i)as json_object_t);uid:=node.get_string('uid');article:=node.get_string('article');base:=node.get_string('base_uom');kind:=node.get_string('work_kind');case_id:=node.get_number('case_task_id');qty:=RRL_STOCK_MATH.quantity(node.get_string('quantity'));
   if kind='CASE_DISPATCH'then
    begin insert into RRL_FORECAST_CASE_ORIGIN values(case_id,uid,p_load,g_ware,article,base,qty);
    exception when dup_val_on_index then
     select WARE_ID,ARTICLE,BASE_UOM into old_ware,old_article,old_base from RRL_FORECAST_CASE_ORIGIN where CASE_PICK_TASK_ID=case_id and LOT_UID=uid;
     if old_ware!=g_ware or old_article!=article or old_base!=base then raise_application_error(-20886,'FORECAST_CASE_ORIGIN_CONFLICT');end if;
     kind:='CASE_RELOADED';
    end;
   end if;
   insert into RRL_FORECAST_LEAF values(p_load,i+1,uid,article,base,qty,kind,case_id);
   key_text:=kind||':'||lengthb(article)||':'||article||':'||lengthb(base)||':'||base;
   if not groups.exists(key_text)then groups(key_text).article:=article;groups(key_text).base:=base;groups(key_text).kind:=kind;groups(key_text).qty:=0;groups(key_text).leaves:=0;end if;
   groups(key_text).qty:=groups(key_text).qty+qty;groups(key_text).leaves:=groups(key_text).leaves+1;
  end loop;
  increment_day;key_text:=groups.first;
  while key_text is not null loop
   increment_sku(groups(key_text).article,groups(key_text).base,groups(key_text).kind,groups(key_text).qty,groups(key_text).leaves);key_text:=groups.next(key_text);
  end loop;
  reset_context;
 exception when others then reset_context;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_FORECAST_SOURCE_RULES as
 procedure compile_leaves(p_tree clob,p_ware number,p_leaves out clob)is
  d json_object_t:=json_object_t.parse(p_tree);nodes json_array_t;n json_object_t;line json_object_t;
  result json_array_t:=json_array_t();qty number;uid varchar2(200);article varchar2(160);base varchar2(20);kind varchar2(20);case_id number;origin_ware number;node_count number:=0;
  ordered json_array_t:=json_array_t();raw_leaves clob;
  type identity_map is table of boolean index by varchar2(200);seen identity_map;
 begin
  nodes:=d.get_array('nodes');
  if nodes is null or nodes.get_size<1 or nodes.get_size>200 or nvl(d.get_number('warehouse'),-1)!=p_ware
   or nvl(d.get_number('top_place_count'),-1)!=1 then raise_application_error(-20886,'FORECAST_EXACT_NATIVE_TREE_REQUIRED');end if;
  for i in 0..nodes.get_size-1 loop
   n:=treat(nodes.get(i)as json_object_t);
   if n.get_string('kind')='STOCK'then
    uid:=n.get_string('uid');article:=n.get_string('article');base:=n.get_string('base_uom');
    if uid is null or article is null or base is null or lengthb(uid)>200 or lengthb(article)>160 or lengthb(base)>20 then raise_application_error(-20886,'FORECAST_STOCK_IDENTITY_REQUIRED');end if;
    if seen.exists(uid)then raise_application_error(-20886,'FORECAST_REPEATED_STOCK_LEAF');end if;seen(uid):=true;
    qty:=RRL_STOCK_MATH.quantity(n.get_string('quantity'));case_id:=n.get_number('case_task_id');
    kind:='FULLPAL_DISPATCH';
    if case_id is not null then
     select t.WARE_ID into origin_ware from RRL_CASE_CARRIER_LOT c join RRL_CASE_PICK_TASK t on t.CASE_PICK_TASK_ID=c.CASE_PICK_TASK_ID where c.LOT_UID=uid and c.CASE_PICK_TASK_ID=case_id;
     kind:=case when origin_ware=p_ware then 'CASE_DISPATCH'else'TRANSIT_CASE'end;
    end if;
    line:=json_object_t();line.put('uid',uid);line.put('article',article);line.put('base_uom',base);
    line.put('quantity',to_char(qty,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''));line.put('work_kind',kind);line.put('case_task_id',case_id);
    result.append(line);node_count:=node_count+1;
   end if;
  end loop;
  if node_count<1 or node_count!=nvl(d.get_number('leaf_count'),-1)then raise_application_error(-20886,'FORECAST_NATIVE_LEAF_COUNT_CONFLICT');end if;
  raw_leaves:=result.to_clob;
  for row_key in(select ORDINAL from json_table(raw_leaves,'$[*]'columns(ORDINAL for ordinality,CASE_ID number path '$.case_task_id',LOT_UID varchar2(200)path '$.uid'))order by nvl(CASE_ID,0),nlssort(LOT_UID,'NLS_SORT=BINARY'))loop
   ordered.append(result.get(row_key.ORDINAL-1));
  end loop;
  p_leaves:=ordered.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_HU_PACK_CLOCK as

 g_writing boolean:=false;

 function writing return boolean is begin return g_writing;end;

 procedure begin_empty_box(p_uid varchar2,p_operation varchar2,p_actor varchar2)is

 p RRL_PALLETS%rowtype;n number;ware number;kind varchar2(80);state varchar2(20);actor nvarchar2(50);

 begin

  if nvl(sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID'),'~')!=p_operation or

   sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null or

   sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)

   then raise_application_error(-20863,'BOX_PACKING_ROOT_CONTEXT_REQUIRED');end if;

  select COMMAND_TYPE,STATE,ACTOR into kind,state,actor from RRL_STOCK_OPERATION where OPERATION_ID=p_operation;

  if kind not in('HU_ATTACH','HU_REPACK','HU_REPACK_SLOT')or state!='IN_FLIGHT'or actor!=p_actor then raise_application_error(-20863,'BOX_PACKING_ATTACH_REQUIRED');end if;

  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',p_uid));

  select *into p from RRL_PALLETS where UID_PALLET=p_uid;

  if p.HU_KIND!='CONTAINER'or p.HU_TYPE!='BOX'then return;end if;

  select count(*)into n from RRL_WMS_HU_LINK where PARENT_UID=p_uid and ACTIVE_FLAG=1;

  if n!=0 then return;end if;

  select WARE_ID into ware from RRL_CELLS where CELL=p.HU_CURRENT_CELL;

  g_writing:=true;

  insert into RRL_HU_PACK_CYCLE(PARENT_UID,START_CONTENT_VERSION,START_OPERATION_ID,WARE_ID,ACTOR,STARTED_AT_INSTANT)

  values(p_uid,p.HU_CONTENT_VERSION+1,p_operation,ware,p_actor,systimestamp);

  g_writing:=false;

 exception when others then g_writing:=false;raise;

 end;

 function clock_json(p_uid varchar2,p_version number)return json_object_t is

 j json_object_t;r RRL_HU_PACK_CYCLE%rowtype;

 begin

  select *into r from RRL_HU_PACK_CYCLE where PARENT_UID=p_uid and START_CONTENT_VERSION<=p_version

   order by START_CONTENT_VERSION desc fetch first 1 row only;

  j:=json_object_t();j.put('operation_id',r.START_OPERATION_ID);j.put('content_version',r.START_CONTENT_VERSION);

  j.put('warehouse',r.WARE_ID);

  j.put('instant',to_char(r.STARTED_AT_INSTANT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));

  return j;

 exception when no_data_found then return null;

 end;

end;
/


CREATE OR REPLACE package body RRL_INTERWARE_DEPART_GATE as  
 function promises(p_trip number)return clob is a json_array_t:=json_array_t();j json_object_t;n number;count_value number:=0;  
 begin  
  for p in(select candidate.OPERATION_ID from(  
   select OPERATION_ID from RRL_INTERWARE_PLAN where TARGET_TT_ID=p_trip  
   union select PLAN_OPERATION_ID from RRL_INTERWARE_DECISION where TARGET_TT_ID=p_trip  
  )candidate where RRL_INTERWARE_ROUTING.target_trip(candidate.OPERATION_ID)=p_trip order by candidate.OPERATION_ID fetch first 201 rows only)loop  
   RRL_INTERWARE_THERMAL.assert_release(p.OPERATION_ID);count_value:=count_value+1;if count_value>200 then raise_application_error(-20881,'INTERWARE_DEPART_PROMISE_BOUND_200');end if;  
   select count(*)into n from RRL_INTERWARE_RECEIPT r join RRL_INTERWARE_ONWARD_BIND b on b.RECEIPT_OPERATION_ID=r.OPERATION_ID join RRL_TT_HU_LOAD_ST m on m.SBORKA_PALLET_ID=b.ST_ID and m.ACTIVE_FLAG=1 join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=m.LOAD_OPERATION_ID join RRL_STOCK_OPERATION o on o.OPERATION_ID=l.LOAD_OPERATION_ID and o.STATE='APPLIED' where (r.EXPECTED_BASE_QTY is null or r.BASE_QTY=r.EXPECTED_BASE_QTY or exists( 
 select 1 from RRL_INTERWARE_SHORTAGE_FACT fact join RRL_STOCK_OPERATION confirmed on confirmed.OPERATION_ID=fact.OPERATION_ID 
 where fact.RECEIPT_OPERATION_ID=r.OPERATION_ID and confirmed.STATE='APPLIED'and confirmed.COMMAND_TYPE='INTERWARE_SHORTAGE_CONFIRM' 
 and fact.SHORT_QTY+r.BASE_QTY=r.EXPECTED_BASE_QTY))and r.PLAN_OPERATION_ID=p.OPERATION_ID and l.TT_ID=p_trip and l.STATUS='LOADED'and(
 (l.ROOT_UID=r.ROOT_UID and RRL_STOCK_MATH.quantity(json_value(l.COMPOSITION_JSON,'$.nodes[0].quantity'))=r.BASE_QTY)
 or(o.COMMAND_TYPE='HU_SHIP'and l.ROOT_UID!=r.ROOT_UID
 and json_value(o.RESOLVED_PLAN_JSON,'$.domain.loading.trip'returning number)=p_trip
 and exists(select 1 from RRL_INTERWARE_ONWARD_DISPATCH dispatch where dispatch.OPERATION_ID=l.LOAD_OPERATION_ID
  and dispatch.BIND_OPERATION_ID=b.OPERATION_ID and dispatch.RECEIPT_OPERATION_ID=r.OPERATION_ID
  and dispatch.ROOT_UID=r.ROOT_UID and dispatch.ST_ID=b.ST_ID and dispatch.BASE_QTY=r.BASE_QTY and dispatch.BASE_UOM=r.BASE_UOM)
 and(select count(*)from json_table(l.COMPOSITION_JSON,'$.nodes[*]'columns(
  K varchar2(20)path '$.kind',U varchar2(200)path '$.uid',Q varchar2(60)path '$.quantity'))archive
  where archive.K='STOCK'and archive.U=r.ROOT_UID and RRL_STOCK_MATH.quantity(archive.Q)=r.BASE_QTY)=1))
;  
   j:=json_object_t();j.put('plan_operation_id',p.OPERATION_ID);j.put('physically_loaded',n=1);a.append(j);  
  end loop;  
  for gp in(select OPERATION_ID,SOURCE_JSON from RRL_IW_GROUP_PLAN where TARGET_TT_ID=p_trip order by OPERATION_ID fetch first 201 rows only)loop
   count_value:=count_value+1;if count_value>200 then raise_application_error(-20881,'INTERWARE_DEPART_PROMISE_BOUND_200');end if;
   select count(*)into n from json_table(gp.SOURCE_JSON,'$.lots[*]'columns(SOURCE_UID varchar2(200)path '$.uid',SOURCE_QTY varchar2(60)path '$.quantity',SOURCE_UOM varchar2(20)path '$.base_uom'))expected
   where not exists(
    select 1 from RRL_TT_HU_LOAD_FACT lf join RRL_STOCK_OPERATION o on o.OPERATION_ID=lf.LOAD_OPERATION_ID and o.STATE='APPLIED'
    join json_table(o.RESOLVED_PLAN_JSON,'$.domain.shipments[*]'columns(
     GROUP_PLAN varchar2(100)path '$.domain.interwarehouse_onward_source.group_plan_operation_id',
     LOT_UID varchar2(200)path '$.domain.interwarehouse_onward_source.uid',
     QTY_TEXT varchar2(60)path '$.domain.interwarehouse_onward_source.quantity',
     UOM_TEXT varchar2(20)path '$.domain.interwarehouse_onward_source.base_uom'))loaded
     on loaded.GROUP_PLAN=gp.OPERATION_ID and loaded.LOT_UID=expected.SOURCE_UID and loaded.QTY_TEXT=expected.SOURCE_QTY and loaded.UOM_TEXT=expected.SOURCE_UOM
    where lf.TT_ID=p_trip and lf.STATUS='LOADED'and o.COMMAND_TYPE='HU_SHIP');
   j:=json_object_t();j.put('plan_operation_id',gp.OPERATION_ID);j.put('grouped_cargo',true);j.put('physically_loaded',n=0);a.append(j);
  end loop;
  return a.to_clob;  
 end;  
 procedure assert_ready(p_promises clob)is a json_array_t:=json_array_t.parse(p_promises);j json_object_t;  
 begin  
  for i in 0..a.get_size-1 loop j:=treat(a.get(i)as json_object_t);if not j.get_boolean('physically_loaded')then raise_application_error(-20886,'DEPART_EXPECTED_INTERWARE_CARGO_NOT_READY: '||j.get_string('plan_operation_id'));end if;end loop;  
 end;  
end;
/


CREATE OR REPLACE package body RRL_INTERWARE_INCIDENT_API as
 g_tx varchar2(100);
 function write_allowed return number is begin
  if g_tx is not null and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure scope(p_plan varchar2,p_actor varchar2)is n number;begin
  select count(*)into n from RRL_INTERWARE_PLAN p join RUSERS u on u.ID=p_actor
   where p.OPERATION_ID=p_plan and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'transport_dispatch_edit')=1
   and(u.WARE_ID=p.TARGET_WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'INTERWARE_INCIDENT_CURRENT_TARGET_DISPATCHER_REQUIRED');end if;
 end;
 procedure close_case(p_operation varchar2,p_actor varchar2,p_request clob,p_result out clob)is
  b json_object_t;incident RRL_INTERWARE_DECISION%rowtype;receipt RRL_INTERWARE_RECEIPT%rowtype;plan RRL_INTERWARE_PLAN%rowtype;
  saved RRL_INTERWARE_INCIDENT_CLOSE%rowtype;entered boolean:=false;sp boolean:=false;n number;declared_qty number;hash varchar2(64);j json_object_t;
  incident_id varchar2(100);receipt_id varchar2(100);rev number;reason varchar2(2000);ref varchar2(2000);
 begin
  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_request is null or dbms_lob.getlength(p_request)>6000 then raise_application_error(-20886,'INTERWARE_INCIDENT_CLOSE_REQUEST_BOUND');end if;
  b:=json_object_t.parse(p_request);incident_id:=b.get_string('incident_operation_id');receipt_id:=b.get_string('followup_receipt_operation_id');rev:=b.get_number('incident_revision');
  reason:=b.get_string('reason');ref:=b.get_string('evidence_reference');
  if b.get_size!=5 or incident_id is null or receipt_id is null or lengthb(incident_id)>100 or lengthb(receipt_id)>100 or rev is null or rev<1 or trunc(rev)!=rev
   or trim(reason)is null or length(trim(reason))<8 or length(reason)>500 or trim(ref)is null or length(ref)>255 then raise_application_error(-20886,'INTERWARE_INCIDENT_CLOSE_EXPLICIT_EVIDENCE_REQUIRED');end if;
  select *into incident from RRL_INTERWARE_DECISION where OPERATION_ID=incident_id;scope(incident.PLAN_OPERATION_ID,p_actor);
  hash:=lower(rawtohex(sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'transport_dispatch_edit');entered:=true;savepoint INCIDENT293;sp:=true;scope(incident.PLAN_OPERATION_ID,p_actor);
  begin select *into saved from RRL_INTERWARE_INCIDENT_CLOSE where OPERATION_ID=p_operation;
   if saved.ACTOR!=p_actor or saved.REQUEST_HASH!=hash or dbms_lob.compare(saved.REQUEST_JSON,p_request)!=0 then raise_application_error(-20886,'INTERWARE_INCIDENT_CLOSE_PAYLOAD_CONFLICT');end if;
   p_result:=saved.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;
  exception when no_data_found then null;end;
  select *into incident from RRL_INTERWARE_DECISION where OPERATION_ID=incident_id;
  if incident.INCIDENT_KIND is null or incident.REVISION_NO!=rev then raise_application_error(-20886,'INTERWARE_INCIDENT_REPORTED_REVISION_REQUIRED');end if;
  select count(*)into n from RRL_INTERWARE_INCIDENT_CLOSE where INCIDENT_OPERATION_ID=incident_id;
  if n!=0 then raise_application_error(-20886,'INTERWARE_INCIDENT_ALREADY_CLOSED');end if;
  select *into receipt from RRL_INTERWARE_RECEIPT where OPERATION_ID=receipt_id;
  select *into plan from RRL_INTERWARE_PLAN where OPERATION_ID=incident.PLAN_OPERATION_ID;
  select RRL_STOCK_MATH.quantity(json_value(plan.SOURCE_COMPOSITION_JSON,'$.nodes[0].quantity'))into declared_qty from dual;
  if receipt.PLAN_OPERATION_ID!=plan.OPERATION_ID or receipt.ROOT_UID!=plan.ROOT_UID or receipt.ORIGINAL_ROOT_UID is not null or receipt.BASE_QTY!=declared_qty or receipt.CREATED_AT<=incident.CREATED_AT then raise_application_error(-20886,'INTERWARE_INCIDENT_ACTUAL_FULL_FOLLOWUP_REQUIRED');end if;
  select count(*)into n from RRL_STOCK_OPERATION o join RRL_EVENTS e on e.OPERATION_ID=o.OPERATION_ID
   where o.OPERATION_ID=receipt_id and o.STATE='APPLIED'and o.COMMAND_TYPE='INTERWARE_RECEIVE'
    and e.ID_EVENT=receipt.STOCK_EVENT_ID and e.UID_POLETA=receipt.ROOT_UID and e.BASE_QTY=receipt.BASE_QTY and e.CELL_TO=receipt.RECEIVE_CELL;
  if n!=1 then raise_application_error(-20886,'INTERWARE_INCIDENT_APPLIED_RECEIPT_EVENT_REQUIRED');end if;
  j:=json_object_t();j.put('operation_id',p_operation);j.put('incident_operation_id',incident_id);j.put('incident_revision',rev);
  j.put('plan_operation_id',plan.OPERATION_ID);j.put('followup_receipt_operation_id',receipt_id);j.put('status','CLOSED_AFTER_FULL_RECEIPT');
  j.put('reason',reason);j.put('evidence_reference',ref);j.put('actor',p_actor);j.put('stock_changed',false);j.put('regulatory_ack_verified',false);p_result:=j.to_clob;
  g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_INTERWARE_INCIDENT_CLOSE(OPERATION_ID,PLAN_OPERATION_ID,INCIDENT_OPERATION_ID,FOLLOWUP_RECEIPT_OPERATION_ID,ACTOR,REASON_TEXT,EVIDENCE_REFERENCE,REQUEST_HASH,REQUEST_JSON,RESULT_JSON)
   values(p_operation,plan.OPERATION_ID,incident_id,receipt_id,p_actor,reason,ref,hash,p_request,p_result);
  g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
 exception when no_data_found then
  g_tx:=null;if sp then rollback to INCIDENT293;end if;if entered then RRL_STOCK_METADATA_TX.end_change;end if;
  raise_application_error(-20886,'INTERWARE_INCIDENT_OR_FOLLOWUP_NOT_FOUND');
 when others then g_tx:=null;if sp then rollback to INCIDENT293;end if;if entered then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_INTERWARE_MARK_SCAN as  

 function marked(p_article varchar2) return number is n number;  

 begin  

  select greatest(nvl((select MARKING_REQUIRED from RRL_SKU_RECEIPT_POLICY where ARTICUL=p_article),0),  

   nvl((select CRPT_REQUIRED from RRL_FINISHED_GOODS_SKU where ARTICUL=p_article),0),  

   case when exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=p_article) then 1 else 0 end) into n from dual;return n;  

 end;  

 function required_for_article(p_article varchar2) return number is begin return marked(p_article);end;  

 function required_for_plan(p_domain clob) return number is  

  d json_object_t:=json_object_t.parse(p_domain);a json_array_t:=d.get_array('legs');l json_object_t;  

 begin  

  for i in 0..a.get_size-1 loop l:=treat(a.get(i) as json_object_t);if marked(l.get_string('article'))=1 then return 1;end if;end loop;return 0;  

 end;  

 procedure validate_scan(p_domain clob,p_metadata clob,p_unit_count out number) is  

  d json_object_t:=json_object_t.parse(p_domain);m json_object_t:=json_object_t.parse(p_metadata);  

  a json_array_t:=d.get_array('legs');scans json_array_t:=json_array_t();l json_object_t;x json_object_t;  

  v_uid varchar2(150);v_cell varchar2(60);v_article varchar2(160);v_base varchar2(20);v_qty number;v_sum number;v_count number;v_profiles number;  

  v_expected number:=0;v_resolved number:=0;scans_clob clob;selected_clob clob;v_key varchar2(4000);  

  type seen_map is table of number index by varchar2(4000);expected seen_map;seen_uids seen_map;  

  type index_map is table of number index by pls_integer;resolved index_map;  

  function profile_key(p_unit varchar2,p_system varchar2,p_profile varchar2) return varchar2 is  

  begin return rawtohex(RRL_STOCK_LOCK_API.resource_key('QCMARK',p_unit,rawtohex(RRL_STOCK_LOCK_API.resource_key('PROFILE',p_system,p_profile))));end;  

 begin  

  p_unit_count:=0;  

  RRL_IW_AGG_SCAN.expand(p_metadata,scans_clob);scans:=json_array_t.parse(scans_clob);  

  if scans.get_size>20000 then raise_application_error(-20881,'QUALITY_MARK_SCAN_BOUND');end if;  

  for i in 0..a.get_size-1 loop  

   l:=treat(a.get(i) as json_object_t);v_article:=l.get_string('article');if marked(v_article)!=1 then continue;end if;  

   selected_clob:=null;if l.has('selected_unit_keys')then selected_clob:=l.get_array('selected_unit_keys').to_clob;end if;  

   v_uid:=l.get_string('uid');v_cell:=l.get_string('cell');v_base:=l.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(l.get_string('quantity'));  

   if seen_uids.exists(v_uid) then raise_application_error(-20887,'QUALITY_MARK_SPLIT_ALLOCATION_NOT_SUPPORTED');end if;seen_uids(v_uid):=1;  

   select count(*) into v_profiles from RRL_SKU_RECEIPT_PROFILE where ARTICUL=v_article;  

   select count(*)into v_count from RRL_SKU_RECEIPT_PROFILE p where p.ARTICUL=v_article and(

    p.SCAN_MODE is null or(p.SCAN_MODE not in('UNIT','UNIT_OR_AGGREGATION')and not exists(

     select 1 from json_table(p_metadata,'$.aggregation_scans[*]'columns(S varchar2(40)path '$.system_code',P varchar2(80)path '$.profile_code',L varchar2(10)path '$.level'))agg

     where agg.S=p.SYSTEM_CODE and agg.P=p.PROFILE_CODE and agg.L=p.SCAN_MODE))

    or(p.SCAN_MODE not in('UNIT','UNIT_OR_AGGREGATION')and exists(

     select 1 from json_table(p_metadata,'$.unit_scans[*]'columns(S varchar2(40)path '$.system_code',P varchar2(80)path '$.profile_code',H varchar2(64)path '$.code_hash'))direct_scan,
     RRL_WMS_RECEIPT_UNIT direct_unit,RRL_WMS_RECEIPT_CODE direct_code
     where direct_unit.CURRENT_UID=v_uid and direct_code.UID_PALLET=direct_unit.UID_PALLET
      and direct_code.UNIT_ID=direct_unit.UNIT_ID and direct_code.SYSTEM_CODE=direct_scan.S
      and direct_code.CODE_HASH=direct_scan.H
      and direct_scan.S=p.SYSTEM_CODE and direct_scan.P=p.PROFILE_CODE

     )));  

   if v_count>0 then raise_application_error(-20887,'INTERWARE_UNIT_CAPTURE_FORBIDDEN_BY_PROFILE');end if;  

   if v_profiles<1 or v_profiles>50 then raise_application_error(-20887,'QUALITY_MARK_PROFILES_REQUIRED');end if;  

   select count(*),sum(BASE_QTY) into v_count,v_sum from RRL_WMS_RECEIPT_UNIT  

    where CURRENT_UID=v_uid and CURRENT_CELL=v_cell and STOCK_STATUS='ISSUED' and BASE_UOM=v_base and(selected_clob is null or exists(select 1 from json_table(selected_clob,'$[*]'columns(K varchar2(64)path '$'))chosen where chosen.K=PHYSICAL_UNIT_KEY));  

   if v_count<1 or v_count>10000 or v_sum!=v_qty then raise_application_error(-20887,'QUALITY_MARK_WHOLE_COMPOSITION_REQUIRED');end if;  

   p_unit_count:=p_unit_count+v_count;if p_unit_count>10000 then raise_application_error(-20881,'QUALITY_PHYSICAL_UNIT_BOUND');end if;  

   -- One bounded matrix query per allocation, never a profile SELECT per physical unit.  

   for z in(select u.PHYSICAL_UNIT_KEY,p.SYSTEM_CODE,p.PROFILE_CODE from RRL_WMS_RECEIPT_UNIT u cross join RRL_SKU_RECEIPT_PROFILE p  

    where u.CURRENT_UID=v_uid and u.CURRENT_CELL=v_cell and u.STOCK_STATUS='ISSUED' and u.BASE_UOM=v_base and(selected_clob is null or exists(select 1 from json_table(selected_clob,'$[*]'columns(K varchar2(64)path '$'))chosen where chosen.K=u.PHYSICAL_UNIT_KEY)) and p.ARTICUL=v_article  

    order by u.PHYSICAL_UNIT_KEY,p.SYSTEM_CODE,p.PROFILE_CODE fetch first 20001 rows only) loop  

    v_expected:=v_expected+1;if v_expected>20000 then raise_application_error(-20881,'QUALITY_MARK_PROFILE_MATRIX_BOUND');end if;  

    expected(profile_key(z.PHYSICAL_UNIT_KEY,z.SYSTEM_CODE,z.PROFILE_CODE)):=0;  

   end loop;  

  end loop;  

  for i in 0..scans.get_size-1 loop  

   x:=treat(scans.get(i) as json_object_t);  

   if x.get_string('system_code') is null or x.get_string('profile_code') is null or x.get_string('code_hash') is null  

    or not regexp_like(x.get_string('code_hash'),'^[a-f0-9]{64}$') then raise_application_error(-20871,'QUALITY_MARK_SCAN_INVALID');end if;  

  end loop;  

  scans_clob:=scans.to_clob;  

  -- One indexed code-registry join. In-memory framed keys enforce exact unit/profile set coverage.  

  for z in(select j.I,j.S,j.P,u.PHYSICAL_UNIT_KEY from  

   json_table(scans_clob,'$[*]' columns(I for ordinality,S varchar2(40) path '$.system_code',P varchar2(80) path '$.profile_code',H varchar2(64) path '$.code_hash'))j  

   join RRL_WMS_RECEIPT_CODE c on c.SYSTEM_CODE=j.S and c.CODE_HASH=j.H  

   join RRL_WMS_RECEIPT_UNIT u on u.UID_PALLET=c.UID_PALLET and u.UNIT_ID=c.UNIT_ID  

   where u.STOCK_STATUS='ISSUED' and exists(select 1 from json_table(c.PROFILES_JSON,'$[*]' columns(P varchar2(80) path '$.profile'))pr where pr.P=j.P)) loop  

   v_key:=profile_key(z.PHYSICAL_UNIT_KEY,z.S,z.P);  

   if not expected.exists(v_key) then raise_application_error(-20886,'QUALITY_FOREIGN_UNIT_OR_PROFILE');end if;  

   if resolved.exists(z.I) or expected(v_key)=1 then raise_application_error(-20871,'QUALITY_DUPLICATE_MARK_SCAN');end if;  

   resolved(z.I):=1;expected(v_key):=1;v_resolved:=v_resolved+1;  

  end loop;  

  if v_resolved!=scans.get_size then raise_application_error(-20886,'QUALITY_FOREIGN_UNIT_OR_PROFILE');end if;  

  if v_resolved!=v_expected then raise_application_error(-20886,'QUALITY_UNIQUE_UNIT_PROFILE_COVERAGE_REQUIRED');end if;  

 end;  

end;
/


CREATE OR REPLACE package body RRL_INTERWARE_ROUTING as
 function resolved(p_plan RRL_INTERWARE_PLAN%rowtype)return RRL_INTERWARE_PLAN%rowtype is r RRL_INTERWARE_PLAN%rowtype:=p_plan;
 begin
  begin select TARGET_TT_ID,OUTBOUND_DOCK,READY_DUE into r.TARGET_TT_ID,r.OUTBOUND_DOCK,r.READY_DUE from RRL_INTERWARE_DECISION where PLAN_OPERATION_ID=p_plan.OPERATION_ID order by REVISION_NO desc fetch first 1 row only;exception when no_data_found then null;end;
  return r;
 end;
 function target_trip(p_plan varchar2)return number is r RRL_INTERWARE_PLAN%rowtype;
 begin select *into r from RRL_INTERWARE_PLAN where OPERATION_ID=p_plan;r:=resolved(r);return r.TARGET_TT_ID;end;
 function outbound_dock(p_plan varchar2)return varchar2 is r RRL_INTERWARE_PLAN%rowtype;
 begin select *into r from RRL_INTERWARE_PLAN where OPERATION_ID=p_plan;r:=resolved(r);return r.OUTBOUND_DOCK;end;
 function ready_due(p_plan varchar2)return timestamp with time zone is r RRL_INTERWARE_PLAN%rowtype;
 begin select *into r from RRL_INTERWARE_PLAN where OPERATION_ID=p_plan;r:=resolved(r);return r.READY_DUE;end;
 procedure record_decision(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);original RRL_INTERWARE_PLAN%rowtype;current_plan RRL_INTERWARE_PLAN%rowtype;tt RRL_TRANSPORT_TASK%rowtype;j json_object_t:=json_object_t();
  op varchar2(100):=d.get_string('operation_id');plan_id varchar2(100):=d.get_string('plan_operation_id');kind varchar2(10):=d.get_string('decision_kind');requested number:=d.get_number('target_trip_id');rev number;n number;old_hash raw(32);hash_value raw(32):=sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256);arrival timestamp with time zone;ready timestamp with time zone;reason nvarchar2(500):=d.get_string('reason');ref varchar2(60):=d.get_string('decision_reference');incident_kind varchar2(30):=d.get_string('incident_kind');incident_detail nvarchar2(1000):=d.get_string('incident_detail');evidence_reference nvarchar2(200):=d.get_string('evidence_reference');
  procedure scope_check is
  begin select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'transport_dispatch_edit')=1 and(WARE_ID=original.TARGET_WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN');if n!=1 then raise_application_error(-20882,'INTERWARE_CURRENT_TARGET_DISPATCHER_REQUIRED');end if;end;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
  select *into original from RRL_INTERWARE_PLAN where OPERATION_ID=plan_id;
  scope_check;
  begin select PAYLOAD_HASH,RESULT_JSON into old_hash,p_result from RRL_INTERWARE_DECISION where OPERATION_ID=op;if old_hash!=hash_value then raise_application_error(-20871,'INTERWARE_DECISION_PAYLOAD_CONFLICT');end if;return;exception when no_data_found then null;end;
  select *into original from RRL_INTERWARE_PLAN where OPERATION_ID=plan_id for update;current_plan:=resolved(original);
  select nvl(max(REVISION_NO),0)into rev from RRL_INTERWARE_DECISION where PLAN_OPERATION_ID=plan_id;
  if d.get_number('expected_revision')is null or d.get_number('expected_revision')!=rev then raise_application_error(-20890,'CLOSURE_CHANGED: interwarehouse decision revision');end if;
  if kind is null or kind not in('WAIT','DEFER')or trim(reason)is null or trim(ref)is null then raise_application_error(-20871,'INTERWARE_DISPATCHER_DECISION_REQUIRED');end if;
  if incident_kind is null then
   if d.has('incident_detail')or d.has('evidence_reference')then raise_application_error(-20871,'INTERWARE_INCIDENT_KIND_REQUIRED');end if;
  elsif incident_kind not in('TRANSPORT_DELAY','MISSING_PALLET','IDENTIFIER_MISMATCH')or trim(incident_detail)is null or trim(evidence_reference)is null then raise_application_error(-20871,'INTERWARE_INCIDENT_DETAIL_EVIDENCE_REQUIRED');end if;
  arrival:=to_timestamp_tz(d.get_string('expected_arrival'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');ready:=current_plan.READY_DUE;
  if arrival is null or arrival<systimestamp then raise_application_error(-20886,'INTERWARE_PROSPECTIVE_ARRIVAL_REQUIRED');end if;
  if kind='WAIT'then
   if requested is not null or d.has('ready_due')then raise_application_error(-20871,'INTERWARE_WAIT_RETURNS_SAME_ROUTE');end if;requested:=current_plan.TARGET_TT_ID;
  else
   if requested is null or requested=current_plan.TARGET_TT_ID then raise_application_error(-20886,'INTERWARE_DIFFERENT_EXISTING_TARGET_TRIP_REQUIRED');end if;
   select count(*)into n from RRL_INTERWARE_RECEIPT where PLAN_OPERATION_ID=plan_id;if n>0 then raise_application_error(-20886,'INTERWARE_RECEIVED_CARGO_REASSIGNMENT_TASK_REQUIRED');end if;
   ready:=to_timestamp_tz(d.get_string('ready_due'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');if ready is null or ready<arrival then raise_application_error(-20886,'INTERWARE_NEW_READY_AFTER_EXPECTED_ARRIVAL_REQUIRED');end if;
  end if;
  for x in(select ID from RRL_TRANSPORT_TASK where ID in(current_plan.TARGET_TT_ID,requested)order by ID)loop select *into tt from RRL_TRANSPORT_TASK where ID=x.ID for update;end loop;
  select *into tt from RRL_TRANSPORT_TASK where ID=current_plan.TARGET_TT_ID;
  if nvl(tt.DELETED,0)!=0 or tt.CONDITION is null or tt.CONDITION!='Спланирован'then raise_application_error(-20886,'INTERWARE_CURRENT_TARGET_TRIP_NOT_PLANNED');end if;
  select *into tt from RRL_TRANSPORT_TASK where ID=requested;
  select count(*)into n from RRL_TT_DOCK where DOCK=tt.DOCK and WARE_ID=original.TARGET_WARE_ID and nvl(DOCK_IS_BLOCKED,0)=0;
  if n!=1 or nvl(tt.DELETED,0)!=0 or tt.CONDITION is null or tt.CONDITION!='Спланирован'then raise_application_error(-20886,'INTERWARE_NEW_PLANNED_TRIP_TARGET_WARE_REQUIRED');end if;
  scope_check;
  j.put('operation_id',op);j.put('plan_operation_id',plan_id);j.put('revision',rev+1);j.put('decision_kind',kind);j.put('original_target_trip_id',original.TARGET_TT_ID);j.put('previous_trip_id',current_plan.TARGET_TT_ID);j.put('target_trip_id',requested);j.put('outbound_dock',tt.DOCK);j.put('expected_arrival',d.get_string('expected_arrival'));j.put('ready_due',to_char(ready,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));j.put('stock_changed',false);
  if incident_kind is not null then j.put('incident_kind',incident_kind);j.put('incident_detail',incident_detail);j.put('evidence_reference',evidence_reference);j.put('incident_basis','OPERATOR_REPORT');j.put('quantity_adjusted',false);end if;
  p_result:=j.to_clob;
  insert into RRL_INTERWARE_DECISION(OPERATION_ID,PLAN_OPERATION_ID,REVISION_NO,DECISION_KIND,PREVIOUS_TT_ID,TARGET_TT_ID,OUTBOUND_DOCK,EXPECTED_ARRIVAL,READY_DUE,REASON_TEXT,DECISION_REFERENCE,ACTOR,PAYLOAD_HASH,CANONICAL_REQUEST,RESULT_JSON,INCIDENT_KIND,INCIDENT_DETAIL,EVIDENCE_REFERENCE)
   values(op,plan_id,rev+1,kind,current_plan.TARGET_TT_ID,requested,tt.DOCK,arrival,ready,reason,ref,p_actor,hash_value,p_request,p_result,incident_kind,incident_detail,evidence_reference);
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_CURRENT_PLAN_TRIP_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_INTERWARE_THERMAL as
 procedure sku_range(p_plan RRL_INTERWARE_PLAN%rowtype,p_lo out number,p_hi out number)is article varchar2(160);
 begin
  select ARTICUL into article from RRL_PALLETS where UID_PALLET=p_plan.ROOT_UID;
  begin select TEMP_MIN,TEMP_MAX into p_lo,p_hi from RRL_RECEIPT_SKU_RULE where WARE_ID=p_plan.TARGET_WARE_ID and ARTICUL=article;exception when no_data_found then p_lo:=null;p_hi:=null;end;
  if (p_lo is null and p_hi is not null)or(p_lo is not null and p_hi is null)or p_lo>p_hi then raise_application_error(-20886,'INTERWARE_SKU_TEMPERATURE_RANGE_INVALID');end if;
 end;
 function mode_json(p_plan varchar2)return clob is original RRL_INTERWARE_PLAN%rowtype;fact RRL_INTERWARE_THERMAL_FACT%rowtype;lo number;hi number;j json_object_t:=json_object_t();
 begin
  select *into original from RRL_INTERWARE_PLAN where OPERATION_ID=p_plan;sku_range(original,lo,hi);
  j.put('revision',0);j.put('decision_kind','NONE');j.put_null('decision_operation_id');j.put('task_temp_min',lo);j.put('task_temp_max',hi);j.put('sku_temp_min',lo);j.put('sku_temp_max',hi);j.put('observation_basis','ADMIN_MANUAL');
  begin
   select *into fact from RRL_INTERWARE_THERMAL_FACT where PLAN_OPERATION_ID=p_plan order by REVISION_NO desc fetch first 1 row only;
   j.put('revision',fact.REVISION_NO);j.put('decision_kind',fact.DECISION_KIND);j.put('decision_operation_id',fact.OPERATION_ID);j.put('task_temp_min',fact.TASK_TEMP_MIN);j.put('task_temp_max',fact.TASK_TEMP_MAX);j.put('observed_c',fact.OBSERVED_C);j.put('observation_reference',fact.OBSERVATION_REFERENCE);
   if fact.DECISION_KIND='PROCEED'and((lo is not null and(fact.TASK_TEMP_MIN is null or fact.TASK_TEMP_MIN<lo))or(hi is not null and(fact.TASK_TEMP_MAX is null or fact.TASK_TEMP_MAX>hi)))then raise_application_error(-20886,'INTERWARE_TEMPERATURE_SKU_POLICY_CHANGED');end if;
  exception when no_data_found then null;end;
  return j.to_clob;
 end;
 procedure assert_release(p_plan varchar2)is j json_object_t:=json_object_t.parse(mode_json(p_plan));
 begin if j.get_string('decision_kind')='HOLD'then raise_application_error(-20886,'INTERWARE_TEMPERATURE_DISPATCHER_HOLD');end if;end;
 procedure assert_cell(p_mode clob,p_ware number,p_cell varchar2)is j json_object_t:=json_object_t.parse(p_mode);lo number:=j.get_number('task_temp_min');hi number:=j.get_number('task_temp_max');clo number;chi number;
 begin
  if lo is null and hi is null then return;end if;
  begin select TEMP_MIN,TEMP_MAX into clo,chi from RRL_RECEIPT_CELL_RULE where WARE_ID=p_ware and CELL=p_cell;exception when no_data_found then clo:=null;chi:=null;end;
  if lo is null or hi is null or clo is null or chi is null or clo>chi or clo<lo or chi>hi then raise_application_error(-20886,'INTERWARE_TASK_CELL_TEMPERATURE_INCOMPATIBLE');end if;
 end;
 procedure record_decision(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);original RRL_INTERWARE_PLAN%rowtype;j json_object_t:=json_object_t();op varchar2(100):=d.get_string('operation_id');plan_id varchar2(100):=d.get_string('plan_operation_id');kind varchar2(10):=d.get_string('decision_kind');rev number;n number;lo number;hi number;tlo number:=d.get_number('task_temp_min');thi number:=d.get_number('task_temp_max');observed number:=d.get_number('observed_c');old_hash raw(32);hash_value raw(32):=sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256);trip number;locked_trip number;observation nvarchar2(200):=d.get_string('observation_reference');reason nvarchar2(500):=d.get_string('reason');reference varchar2(60):=d.get_string('decision_reference');
  procedure scope_check is begin
   select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'transport_dispatch_edit')=1 and(WARE_ID=original.TARGET_WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN');if n!=1 then raise_application_error(-20882,'INTERWARE_CURRENT_TARGET_DISPATCHER_REQUIRED');end if;
  end;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
  select *into original from RRL_INTERWARE_PLAN where OPERATION_ID=plan_id;scope_check;
  begin select PAYLOAD_HASH,RESULT_JSON into old_hash,p_result from RRL_INTERWARE_THERMAL_FACT where OPERATION_ID=op;if old_hash!=hash_value then raise_application_error(-20871,'INTERWARE_THERMAL_PAYLOAD_CONFLICT');end if;return;exception when no_data_found then null;end;
  select *into original from RRL_INTERWARE_PLAN where OPERATION_ID=plan_id for update;
  select nvl(max(REVISION_NO),0)into rev from RRL_INTERWARE_THERMAL_FACT where PLAN_OPERATION_ID=plan_id;
  if d.get_number('expected_revision')is null or d.get_number('expected_revision')!=rev then raise_application_error(-20890,'CLOSURE_CHANGED: interwarehouse thermal revision');end if;
  if op is null or kind is null or kind not in('HOLD','PROCEED')or observed is null or observed<-100 or observed>100 or observed!=round(observed,3) or trim(d.get_string('observation_reference'))is null or trim(d.get_string('reason'))is null or trim(d.get_string('decision_reference'))is null then raise_application_error(-20871,'INTERWARE_MANUAL_TEMPERATURE_DECISION_REQUIRED');end if;
  sku_range(original,lo,hi);
  if(tlo is null and thi is not null)or(tlo is not null and thi is null)or tlo>thi or tlo<-100 or thi>100 or tlo!=round(tlo,3) or thi!=round(thi,3) then raise_application_error(-20886,'INTERWARE_TASK_TEMPERATURE_RANGE_INVALID');end if;
  if kind='PROCEED'and((lo is not null and(tlo is null or tlo<lo))or(hi is not null and(thi is null or thi>hi)))then raise_application_error(-20886,'INTERWARE_TASK_TEMPERATURE_SKU_INCOMPATIBLE');end if;
  trip:=RRL_INTERWARE_ROUTING.target_trip(plan_id);
  select ID into locked_trip from RRL_TRANSPORT_TASK where ID=trip and CONDITION='Спланирован'and nvl(DELETED,0)=0 for update;scope_check;
  j.put('operation_id',op);j.put('plan_operation_id',plan_id);j.put('revision',rev+1);j.put('decision_kind',kind);j.put('observed_c',observed);j.put('task_temp_min',tlo);j.put('task_temp_max',thi);j.put('sku_temp_min',lo);j.put('sku_temp_max',hi);j.put('observation_basis','ADMIN_MANUAL');j.put('stock_changed',false);j.put('sensor_verified',false);p_result:=j.to_clob;
  insert into RRL_INTERWARE_THERMAL_FACT(OPERATION_ID,PLAN_OPERATION_ID,REVISION_NO,DECISION_KIND,OBSERVED_C,OBSERVATION_REFERENCE,TASK_TEMP_MIN,TASK_TEMP_MAX,SKU_TEMP_MIN,SKU_TEMP_MAX,REASON_TEXT,DECISION_REFERENCE,ACTOR,PAYLOAD_HASH,CANONICAL_REQUEST,RESULT_JSON)
   values(op,plan_id,rev+1,kind,observed,observation,tlo,thi,lo,hi,reason,reference,p_actor,hash_value,p_request,p_result);
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_THERMAL_EXISTING_PLANNED_TRIP_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_INTERWARE_UNIT_SOURCE as 
 procedure assert_scope(p_load varchar2,p_actor varchar2)is n number; 
 begin 
  select count(*)into n from RRL_TT_HU_LOAD_FACT lf join RUSERS u on u.ID=p_actor 
   where lf.LOAD_OPERATION_ID=p_load and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'transport_dispatch_edit')=1 and(upper(trim(u.USER_GROUP))='GLOBAL_ADMIN'or u.WARE_ID=lf.WARE_ID); 
  if n!=1 then raise_application_error(-20882,'INTERWARE_CURRENT_SOURCE_DISPATCHER_REQUIRED');end if; 
 end; 
 procedure assert_case_archive(p_load varchar2,p_tree json_object_t)is
 nodes clob:=p_tree.get_array('nodes').to_clob;cases number;n number;leafs number;
 begin
 select count(*)into cases from json_table(nodes,'$[*]'columns(NODE_KIND varchar2(20)path '$.kind'))where NODE_KIND='CASE';
 if cases=0 then return;end if;
 select count(*)into n from json_table(nodes,'$[*]'columns(
 NODE_KIND varchar2(20)path '$.kind',NODE_UID varchar2(160)path '$.uid',CASE_ID number path '$.case_task_id',CASE_SSCC varchar2(32)path '$.sscc',CASE_VERSION number path '$.version'))j
 join RRL_CASE_PICK_TASK t on t.CASE_PICK_TASK_ID=j.CASE_ID
 join RRL_TT_HU_LOAD_FACT lf on lf.LOAD_OPERATION_ID=p_load and lf.WARE_ID=t.WARE_ID
 where j.NODE_KIND='CASE'and j.NODE_UID='CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(t.CASE_PICK_TASK_ID)
 and t.STATUS='SHIPPED'and t.SHIPPED_OPERATION=p_load and t.SSCC=j.CASE_SSCC and t.CONTENT_VERSION=j.CASE_VERSION+1;
 if n!=cases then raise_application_error(-20884,'STORE_CASE_EXACT_FROZEN_SHIPMENT_REQUIRED');end if;
 select count(*)into leafs from json_table(nodes,'$[*]'columns(NODE_KIND varchar2(20)path '$.kind',CASE_ID number path '$.case_task_id'))where NODE_KIND='STOCK'and CASE_ID is not null;
 select count(*)into n from json_table(nodes,'$[*]'columns(NODE_KIND varchar2(20)path '$.kind',NODE_UID varchar2(160)path '$.uid',CASE_ID number path '$.case_task_id'))j
 join RRL_CASE_CARRIER_LOT c on c.CASE_PICK_TASK_ID=j.CASE_ID and c.LOT_UID=j.NODE_UID
 where j.NODE_KIND='STOCK'and exists(select 1 from json_table(nodes,'$[*]'columns(PARENT_KIND varchar2(20)path '$.kind',PARENT_CASE number path '$.case_task_id'))p where p.PARENT_KIND='CASE'and p.PARENT_CASE=j.CASE_ID);
 if n!=leafs or leafs<cases then raise_application_error(-20884,'STORE_CASE_EXACT_CARRIER_LOTS_REQUIRED');end if;
 end;
 function issued_manifest(p_load varchar2,p_uid varchar2,p_snapshot clob)return clob is 
  tree json_object_t:=json_object_t.parse(p_snapshot);node json_object_t;plain json_array_t:=json_array_t();units json_array_t:=json_array_t();x json_object_t;j json_object_t:=json_object_t();finger json_object_t:=json_object_t(); 
  wire clob;expected varchar2(64);actual varchar2(64);cell_value varchar2(60);uom_value varchar2(20);qty number;total number:=0;n number:=0;required_count number;proof_count number;nodes json_array_t;candidate json_object_t;stock_nodes number:=0;selected_nodes number:=0;archive_wire clob;archive_tree json_object_t;root_id varchar2(200); 
 begin 
  nodes:=tree.get_array('nodes');
  if nodes.get_size<1 or nodes.get_size>200 or tree.get_number('leaf_count')<1 or tree.get_number('top_place_count')!=1 then raise_application_error(-20886,'INTERWARE_SINGLE_PHYSICAL_ROOT_REQUIRED');end if;
  if nodes.get_size=1 then node:=treat(nodes.get(0)as json_object_t);
  else
   select lf.COMPOSITION_JSON,lf.ROOT_UID into archive_wire,root_id from RRL_TT_HU_LOAD_FACT lf
   join RRL_STOCK_OPERATION root_op on root_op.OPERATION_ID=lf.LOAD_OPERATION_ID and root_op.STATE='APPLIED'and root_op.COMMAND_TYPE in('HU_SHIP','LOAD_SHIPMENT')
   where lf.LOAD_OPERATION_ID=p_load and lf.STATUS in('LOADED','DEPARTED');
   archive_tree:=json_object_t.parse(archive_wire);
   if dbms_lob.compare(archive_tree.to_clob,tree.to_clob)!=0 or root_id!=tree.get_string('root')then raise_application_error(-20884,'INTERWARE_NESTED_FROZEN_LOAD_ARCHIVE_REQUIRED');end if;
   for i in 0..nodes.get_size-1 loop
    candidate:=treat(nodes.get(i)as json_object_t);
    if candidate.get_string('kind')='STOCK'then stock_nodes:=stock_nodes+1;if candidate.get_string('uid')=p_uid then node:=candidate;selected_nodes:=selected_nodes+1;end if;
    elsif candidate.get_string('kind')not in('CONTAINER','CASE')then raise_application_error(-20886,'INTERWARE_NESTED_STOCK_ONLY_REQUIRED');end if;
   end loop;
   if selected_nodes!=1 or stock_nodes!=tree.get_number('leaf_count')then raise_application_error(-20886,'INTERWARE_NESTED_ONE_STOCK_LEAF_REQUIRED');end if;
  end if;
assert_case_archive(p_load,tree);
cell_value:=tree.get_string('cell');uom_value:=node.get_string('base_uom');qty:=RRL_STOCK_MATH.quantity(node.get_string('quantity')); 
  if node.get_string('kind')!='STOCK'or node.get_string('uid')!=p_uid or cell_value is null or uom_value is null then raise_application_error(-20886,'INTERWARE_ORIGINAL_STOCK_SOURCE_REQUIRED');end if; 
  select count(*)into required_count from RRL_PALLETS p where p.UID_PALLET=p_uid and(exists(select 1 from RRL_SKU_RECEIPT_PROFILE profile where profile.ARTICUL=p.ARTICUL)or exists(select 1 from RRL_SKU_RECEIPT_POLICY policy where policy.ARTICUL=p.ARTICUL and(policy.MARKING_REQUIRED=1 or policy.SERIALIZED_WEIGHT_BOXES=1))or exists(select 1 from RRL_FINISHED_GOODS_SKU fg where fg.ARTICUL=p.ARTICUL and fg.CRPT_REQUIRED=1)); 
  for u in(select PHYSICAL_UNIT_KEY,BASE_QTY,BASE_UOM,CURRENT_CELL,UNIT_VERSION,STOCK_STATUS,HARD_RESERVATION_ID from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid order by PHYSICAL_UNIT_KEY fetch first 10001 rows only)loop 
   n:=n+1;if n>10000 or u.PHYSICAL_UNIT_KEY is null or u.BASE_QTY<=0 or u.BASE_UOM is null or u.BASE_UOM!=uom_value or u.CURRENT_CELL is null or u.CURRENT_CELL!=cell_value or u.STOCK_STATUS!='ISSUED'or u.HARD_RESERVATION_ID is not null or u.UNIT_VERSION is null then raise_application_error(-20884,'INTERWARE_ORIGINAL_ISSUED_UNIT_SET_REQUIRED');end if; 
   x:=json_object_t();x.put('key',u.PHYSICAL_UNIT_KEY);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY));x.put('base_uom',u.BASE_UOM);plain.append(x.clone());x.put('version',u.UNIT_VERSION);units.append(x);total:=total+u.BASE_QTY; 
  end loop; 
  if(tree.get_number('leaf_count')=1 and n!=nvl(tree.get_number('physical_unit_count'),0))or(n>0 and total!=qty)or(required_count>0 and n=0)then raise_application_error(-20884,'INTERWARE_EXACT_MARKED_SOURCE_QUANTITY_REQUIRED');end if; 
  if n>0 then 
   select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=p_load and STATE='APPLIED'; 
   select count(*),max(S)into proof_count,expected from json_table(wire,'$.physical_before[*]'columns(U varchar2(150)path '$.uid',S varchar2(64)path '$.unit_signature'))where U=p_uid; 
   if proof_count!=1 or expected is null then raise_application_error(-20884,'INTERWARE_ORIGINAL_UNIT_FINGERPRINT_REQUIRED');end if; 
   finger.put('units',plain);actual:=rawtohex(sys.dbms_crypto.hash(finger.to_clob,sys.dbms_crypto.hash_sh256)); 
   if actual!=expected then raise_application_error(-20884,'INTERWARE_ORIGINAL_UNIT_FINGERPRINT_CONFLICT');end if; 
   j.put('unit_signature',actual); 
  end if; 
  j.put('units',units);j.put('physical_unit_count',n);j.put('unit_capture_required',n>0);j.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));j.put('base_uom',uom_value);j.put('source_cell',cell_value);return j.to_clob; 
 end; 
 procedure capture_plan(p_plan varchar2,p_actor varchar2)is 
  plan RRL_INTERWARE_PLAN%rowtype;wire clob;signature_value varchar2(64);n number; 
 begin 
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6); 
  select *into plan from RRL_INTERWARE_PLAN where OPERATION_ID=p_plan; 
  assert_scope(plan.SOURCE_LOAD_OPERATION_ID,p_actor); 
  select count(*)into n from RRL_INTERWARE_UNIT_MANIFEST where PLAN_OPERATION_ID=p_plan; 
  if n>0 then return;end if; 
  select count(*)into n from RRL_INTERWARE_RECEIPT where PLAN_OPERATION_ID=p_plan; 
  if n>0 then raise_application_error(-20886,'INTERWARE_MANIFEST_CAPTURE_BEFORE_RECEIPT_REQUIRED');end if; 
  select count(*)into n from RRL_REMAINS where UID_POLETA=plan.ROOT_UID and(nvl(REMAIN,0)!=0 or nvl(HARD_RESERVED_BASE,0)!=0); 
  if n>0 then raise_application_error(-20886,'INTERWARE_SOURCE_STOCK_ALREADY_PRESENT');end if; 
  wire:=issued_manifest(plan.SOURCE_LOAD_OPERATION_ID,plan.ROOT_UID,plan.SOURCE_COMPOSITION_JSON); 
  if json_object_t.parse(wire).get_number('physical_unit_count')=0 then return;end if; 
  signature_value:=json_object_t.parse(wire).get_string('unit_signature'); 
  insert into RRL_INTERWARE_UNIT_MANIFEST(PLAN_OPERATION_ID,UNIT_SIGNATURE,MANIFEST_JSON,CREATED_BY)values(p_plan,signature_value,wire,p_actor); 
 end; 
 function plan_manifest(p_plan varchar2,p_actor varchar2)return clob is n number;wire clob; 
 begin 
  select count(*)into n from RRL_INTERWARE_PLAN p join RUSERS u on u.ID=p_actor where p.OPERATION_ID=p_plan and nvl(u.DELETED,0)=0 
   and(upper(trim(u.USER_GROUP))='GLOBAL_ADMIN'or(u.WARE_ID=p.SOURCE_WARE_ID and RRL_HAS_WRIGHT(u.ID,'transport_dispatch_view')=1)or(u.WARE_ID=p.TARGET_WARE_ID and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1)); 
  if n!=1 then raise_application_error(-20882,'INTERWARE_CURRENT_MANIFEST_READER_REQUIRED');end if; 
  begin select MANIFEST_JSON into wire from RRL_INTERWARE_UNIT_MANIFEST where PLAN_OPERATION_ID=p_plan; 
  exception when no_data_found then return '{"units":[],"physical_unit_count":0,"unit_capture_required":false}';end; 
  return wire; 
 end; 
end;
/


CREATE OR REPLACE package body RRL_IW_AGG_SCAN as 

 procedure expand(p_metadata clob,p_scans out clob)is 

 m json_object_t:=json_object_t.parse(p_metadata);direct_scans json_array_t:=json_array_t();aggregates json_array_t:=json_array_t(); 

 result_scans json_array_t:=json_array_t();item json_object_t;expanded json_array_t;members clob;expanded_wire clob; 

 v_system_code varchar2(40);v_profile_code varchar2(80);v_digest varchar2(64);v_level_code varchar2(10);v_origin_uid varchar2(200); 

 n number;expected_count number;current_count number;aggregate_version varchar2(40);current_version varchar2(40);scan_mode varchar2(40); 

 begin 

 if m.has('unit_scans')then direct_scans:=m.get_array('unit_scans');end if; 

 if m.has('aggregation_scans')then aggregates:=m.get_array('aggregation_scans');end if; 

 if direct_scans is null or aggregates is null or direct_scans.get_size>20000 or aggregates.get_size>1000 then raise_application_error(-20881,'INTERWARE_SCAN_BOUND');end if; 

 for i in 0..direct_scans.get_size-1 loop result_scans.append(direct_scans.get(i));end loop; 

 for i in 0..aggregates.get_size-1 loop 

 item:=treat(aggregates.get(i)as json_object_t); 

 if item is null or item.get_size!=4 then raise_application_error(-20871,'INTERWARE_AGGREGATION_SCAN_FIELDS');end if; 

 v_system_code:=item.get_string('system_code');v_profile_code:=item.get_string('profile_code');v_digest:=item.get_string('code_hash');v_level_code:=item.get_string('level'); 

 if v_system_code is null or v_profile_code is null or v_digest is null or not regexp_like(v_digest,'^[a-f0-9]{64}$')or v_level_code not in('BOX','PALLET')or v_level_code is null then raise_application_error(-20871,'INTERWARE_AGGREGATION_SCAN_INVALID');end if; 

 select count(*)into n from RRL_WMS_RECEIPT_AGG where RRL_WMS_RECEIPT_AGG.SYSTEM_CODE=v_system_code and RRL_WMS_RECEIPT_AGG.PROFILE_CODE=v_profile_code and CODE_HASH=v_digest and AGG_LEVEL=v_level_code; 

 if n!=1 then raise_application_error(-20886,'INTERWARE_REGISTERED_AGGREGATION_REQUIRED');end if; 

 select UID_PALLET into v_origin_uid from RRL_WMS_RECEIPT_AGG where RRL_WMS_RECEIPT_AGG.SYSTEM_CODE=v_system_code and RRL_WMS_RECEIPT_AGG.PROFILE_CODE=v_profile_code and CODE_HASH=v_digest and AGG_LEVEL=v_level_code; 

 select count(*)into n from RRL_TRACE_SENDER_AGG a join RRL_TRACE_MANIFEST_USE used on used.MANIFEST_OPERATION_ID=a.MANIFEST_OPERATION_ID 

 join RRL_STOCK_OPERATION op on op.OPERATION_ID=used.STOCK_OPERATION_ID and op.STATE='APPLIED' 

 where used.UID_PALLET=v_origin_uid and a.SYSTEM_CODE=v_system_code and a.PROFILE_CODE=v_profile_code and a.CODE_HASH=v_digest and a.AGG_LEVEL=v_level_code; 

 if n>1 then raise_application_error(-20886,'INTERWARE_AGGREGATION_ORIGIN_AMBIGUOUS');end if;

 if n=1 then

 select a.UNITS_JSON,a.PROFILE_VERSION into members,aggregate_version from RRL_TRACE_SENDER_AGG a join RRL_TRACE_MANIFEST_USE used on used.MANIFEST_OPERATION_ID=a.MANIFEST_OPERATION_ID

 where used.UID_PALLET=v_origin_uid and a.SYSTEM_CODE=v_system_code and a.PROFILE_CODE=v_profile_code and a.CODE_HASH=v_digest and a.AGG_LEVEL=v_level_code;

 else

 select count(*)into n from RRL_SAP_TRACE_AGG a join RRL_SAP_PALLET_RECEIPT rec on rec.ORDER_ID=a.ORDER_ID and rec.LINE_NUMBER=a.LINE_NUMBER

 join RRL_STOCK_OPERATION op on op.OPERATION_ID=rec.STOCK_OPERATION_ID and op.STATE='APPLIED'and op.COMMAND_TYPE='SAP_RECEIPT'

 where rec.UID_PALLET=v_origin_uid and rec.POSTED_BASE_QTY>0 and a.SYSTEM_CODE=v_system_code and a.PROFILE_CODE=v_profile_code and a.CODE_HASH=v_digest and a.AGG_LEVEL=v_level_code;

 if n!=1 then raise_application_error(-20886,'INTERWARE_APPLIED_AGGREGATION_BIRTH_SOURCE_REQUIRED');end if;

 select a.UNITS_JSON into members from RRL_SAP_TRACE_AGG a join RRL_SAP_PALLET_RECEIPT rec on rec.ORDER_ID=a.ORDER_ID and rec.LINE_NUMBER=a.LINE_NUMBER

 where rec.UID_PALLET=v_origin_uid and a.SYSTEM_CODE=v_system_code and a.PROFILE_CODE=v_profile_code and a.CODE_HASH=v_digest and a.AGG_LEVEL=v_level_code;

 aggregate_version:=null;

 end if;

 select count(*)into n from RRL_SKU_RECEIPT_PROFILE profile join RRL_PALLETS p on p.ARTICUL=profile.ARTICUL 

 where p.UID_PALLET=v_origin_uid and profile.SYSTEM_CODE=v_system_code and profile.PROFILE_CODE=v_profile_code; 

 if n!=1 then raise_application_error(-20886,'INTERWARE_AGGREGATION_CURRENT_PROFILE_REQUIRED');end if; 

 select profile.PROFILE_VERSION,profile.SCAN_MODE into current_version,scan_mode from RRL_SKU_RECEIPT_PROFILE profile join RRL_PALLETS p on p.ARTICUL=profile.ARTICUL 

 where p.UID_PALLET=v_origin_uid and profile.SYSTEM_CODE=v_system_code and profile.PROFILE_CODE=v_profile_code; 

 if current_version is null or(aggregate_version is not null and current_version!=aggregate_version)or scan_mode not in(v_level_code,'UNIT_OR_AGGREGATION')or scan_mode is null then raise_application_error(-20887,'INTERWARE_AGGREGATION_PROFILE_VERSION_OR_MODE');end if; 

 RRL_TRACE_AGG_LIFECYCLE.assert_scan(v_system_code,v_profile_code,v_digest);

 if v_system_code='CRPT'then 

 select count(*)into n from RRL_CRPT_AGGREGATION where UID_PALLET=v_origin_uid and upper(AGGREGATION_STATUS)in('DISAGGREGATED','CANCELLED','DESTROYED','REJECTED'); 

 if n!=0 then raise_application_error(-20886,'INTERWARE_REGULATORY_AGGREGATION_INVALIDATED');end if; 

 end if; 

 expected_count:=json_array_t.parse(members).get_size; 

 if expected_count<1 or expected_count>10000 then raise_application_error(-20881,'INTERWARE_AGGREGATION_MEMBER_BOUND');end if; 

 select count(*),json_arrayagg(json_object('system_code'value v_system_code,'profile_code'value v_profile_code,'code_hash'value code.CODE_HASH)order by u.PHYSICAL_UNIT_KEY returning clob) 

 into current_count,expanded_wire 

 from json_table(members,'$[*]'columns(UNIT_ID varchar2(100)path '$.unit_id',Q varchar2(60)path '$.quantity',RAW_CODE varchar2(4000)path '$.code'))j 

 join RRL_WMS_RECEIPT_UNIT u on u.UID_PALLET=v_origin_uid and u.UNIT_ID=j.UNIT_ID 

 join RRL_WMS_RECEIPT_CODE code on code.UID_PALLET=u.UID_PALLET and code.UNIT_ID=u.UNIT_ID and code.SYSTEM_CODE=v_system_code 

 where u.STOCK_STATUS='ISSUED'and u.CURRENT_UID=v_origin_uid and u.HARD_RESERVATION_ID is null and u.BASE_QTY=case when j.Q is not null then RRL_STOCK_MATH.quantity(j.Q) else u.BASE_QTY end 

 and exists(select 1 from json_table(code.PROFILES_JSON,'$[*]'columns(P varchar2(80)path '$.profile',C varchar2(4000)path '$.raw_code',V varchar2(40)path '$.version'))proof where proof.P=v_profile_code and proof.C=j.RAW_CODE and proof.V=current_version); 

 if current_count!=expected_count then raise_application_error(-20886,'INTERWARE_AGGREGATION_MEMBERS_CHANGED');end if; 

 expanded:=json_array_t.parse(expanded_wire); 

 for j in 0..expanded.get_size-1 loop result_scans.append(expanded.get(j));end loop; 

 if result_scans.get_size>20000 then raise_application_error(-20881,'INTERWARE_EXPANDED_SCAN_BOUND');end if; 

 end loop; 

 p_scans:=result_scans.to_clob; 

 end; 

end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_ARCHIVE as
 function snapshot_json(p_load varchar2)return clob is
 lf RRL_TT_HU_LOAD_FACT%rowtype;wire clob;tree json_object_t;domain_value json_object_t;
 nodes json_array_t;shipments json_array_t;lots json_array_t:=json_array_t();links json_array_t;
 item json_object_t;part json_object_t;leg json_object_t;node json_object_t;entry json_object_t;
 result_value json_object_t:=json_object_t();manifest json_object_t;profile_wire clob;n number;st number;
 type seen_set is table of boolean index by varchar2(200);seen_lots seen_set;seen_st seen_set;leaf_count number:=0;
 v_uid varchar2(200);v_article varchar2(160);v_uom varchar2(20);v_qty number;v_version number;v_link number;v_parent varchar2(200);v_child varchar2(200);
 begin
 select *into lf from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=p_load and STATUS='DEPARTED'and ROOT_CASE_TASK_ID is null;
 select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=p_load and STATE='APPLIED'and COMMAND_TYPE='HU_SHIP';
 tree:=json_object_t.parse(lf.COMPOSITION_JSON);nodes:=tree.get_array('nodes');domain_value:=json_object_t.parse(wire).get_object('domain');shipments:=domain_value.get_array('shipments');
 if nodes.get_size<3 or nodes.get_size>200 or tree.get_number('top_place_count')!=1 or tree.get_string('root')!=lf.ROOT_UID or shipments.get_size<2 or shipments.get_size>200 then raise_application_error(-20886,'INTERWARE_GROUP_BOUNDED_TOP_REQUIRED');end if;
 for i in 0..nodes.get_size-1 loop
  node:=treat(nodes.get(i)as json_object_t);v_uid:=node.get_string('uid');v_version:=node.get_number('version');
  if node.get_string('kind')='STOCK'then
   if node.get_number('case_task_id')is not null or seen_lots.exists(node.get_string('uid'))then raise_application_error(-20886,'INTERWARE_GROUP_DISTINCT_STOCK_ONLY');end if;
   seen_lots(node.get_string('uid')):=true;leaf_count:=leaf_count+1;
  elsif node.get_string('kind')='CONTAINER'then
   select count(*)into n from RRL_PALLETS where UID_PALLET=v_uid and HU_KIND='CONTAINER'and HU_CURRENT_CELL is null and HU_SHIPPED_OPERATION=p_load and HU_CONTENT_VERSION=v_version+1;
   if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_CONTAINER_EPOCH_CHANGED');end if;
  else raise_application_error(-20886,'INTERWARE_GROUP_STOCK_CONTAINER_ONLY');end if;
 end loop;
 if leaf_count!=shipments.get_size or leaf_count!=tree.get_number('leaf_count')then raise_application_error(-20886,'INTERWARE_GROUP_ONE_ST_PER_LEAF_REQUIRED');end if;
 links:=tree.get_array('links');
 if links.get_size!=nodes.get_size-1 then raise_application_error(-20886,'INTERWARE_GROUP_COMPLETE_TREE_REQUIRED');end if;
 for i in 0..links.get_size-1 loop
  item:=treat(links.get(i)as json_object_t);v_link:=item.get_number('id');v_parent:=item.get_string('parent');v_child:=item.get_string('child');v_version:=item.get_number('version');
  select count(*)into n from RRL_WMS_HU_LINK where HU_LINK_ID=v_link and PARENT_UID=v_parent and CHILD_PALLET_UID=v_child and CHILD_CASE_TASK_ID is null and ACTIVE_FLAG=0 and UNLINKED_OPERATION_ID=p_load and LINK_VERSION=v_version+1;
  if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_FROZEN_LINK_CHANGED');end if;
 end loop;
 select count(*)into n from RRL_TT_HU_LOAD_ST where LOAD_OPERATION_ID=p_load and ACTIVE_FLAG=1;
 if n!=shipments.get_size then raise_application_error(-20886,'INTERWARE_GROUP_MEMBER_COUNT_CHANGED');end if;
 for i in 0..shipments.get_size-1 loop
  part:=treat(shipments.get(i)as json_object_t).get_object('domain');st:=part.get_number('document_id');
  if part.get_array('legs').get_size!=1 or part.get_number('return_supplier_id')is not null or part.has('interwarehouse_onward_source')or seen_st.exists(to_char(st))then raise_application_error(-20886,'INTERWARE_GROUP_FIRST_CUSTOMER_LEG_REQUIRED');end if;
  seen_st(to_char(st)):=true;leg:=treat(part.get_array('legs').get(0)as json_object_t);
 v_uid:=leg.get_string('uid');v_article:=leg.get_string('article');v_uom:=leg.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(leg.get_string('quantity'));
  if not seen_lots.exists(leg.get_string('uid'))then raise_application_error(-20886,'INTERWARE_GROUP_FOREIGN_LEAF');end if;
  seen_lots.delete(leg.get_string('uid'));
  select count(*)into n from RRL_TT_HU_LOAD_ST where LOAD_OPERATION_ID=p_load and ACTIVE_FLAG=1 and SBORKA_PALLET_ID=st;
  if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_EXACT_MEMBER_REQUIRED');end if;
  select count(*)into n from json_table(lf.COMPOSITION_JSON,'$.nodes[*]'columns(NODE_KIND varchar2(20)path '$.kind',NODE_UID varchar2(200)path '$.uid',ARTICLE_VALUE varchar2(160)path '$.article',QTY_VALUE varchar2(60)path '$.quantity',UOM_VALUE varchar2(20)path '$.base_uom'))j
  where NODE_KIND='STOCK'and NODE_UID=v_uid and ARTICLE_VALUE=v_article and UOM_VALUE=v_uom and RRL_STOCK_MATH.quantity(QTY_VALUE)=v_qty;
  if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_EXACT_WHOLE_LEAF_REQUIRED');end if;
  select count(*)into n from RRL_REMAINS where UID_POLETA=v_uid and(nvl(REMAIN,0)!=0 or nvl(HARD_RESERVED_BASE,0)!=0);
  if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_SOURCE_ALREADY_PRESENT');end if;
  manifest:=json_object_t.parse(RRL_INTERWARE_UNIT_SOURCE.issued_manifest(p_load,leg.get_string('uid'),lf.COMPOSITION_JSON));
  select json_arrayagg(json_object('system_code'value SYSTEM_CODE,'profile_code'value PROFILE_CODE,'profile_version'value PROFILE_VERSION,'scan_mode'value SCAN_MODE)order by SYSTEM_CODE,PROFILE_CODE returning clob)
   into profile_wire from RRL_SKU_RECEIPT_PROFILE where ARTICUL=v_article;
  entry:=leg.clone();entry.put('st_id',st);entry.put('issued_manifest',manifest);entry.put('profiles',json_array_t.parse(nvl(profile_wire,'[]')));lots.append(entry);
 end loop;
 if seen_lots.count!=0 then raise_application_error(-20886,'INTERWARE_GROUP_UNBOUND_LEAF');end if;
 select count(*)into n from RRL_STORE_RECEIPT_FACT where LOAD_OPERATION_ID=p_load;
 if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_ALREADY_ACCEPTED_BY_STORE');end if;
 select count(*)into n from RRL_INTERWARE_PLAN where SOURCE_LOAD_OPERATION_ID=p_load;
 if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_SCALAR_PLAN_EXISTS');end if;
 result_value.put('source_load_operation_id',p_load);result_value.put('source_trip_id',lf.TT_ID);result_value.put('source_warehouse_id',lf.WARE_ID);
 result_value.put('physical_place_identifier',lf.ROOT_UID);result_value.put('source_composition',tree);result_value.put('lots',lots);result_value.put('stock_leaf_count',leaf_count);
 return result_value.to_clob;
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_GROUP_DEPARTED_ARCHIVE_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_CUSTODY_CORE as
 procedure describe_source(p_receipt varchar2,p_actor varchar2,p_domain out json_object_t)is
 receipt RRL_IW_GROUP_RECEIPT%rowtype;plan RRL_IW_GROUP_PLAN%rowtype;placed RRL_IW_GROUP_PLACEMENT%rowtype;cargo RRL_TT_HU_LOAD_FACT%rowtype;
 unloaded RRL_IW_GROUP_UNLOAD%rowtype;n number;expected number;lines_value json_array_t:=json_array_t();x json_object_t;tree json_object_t;
 begin
 select *into receipt from RRL_IW_GROUP_RECEIPT where OPERATION_ID=p_receipt;
 select *into plan from RRL_IW_GROUP_PLAN where OPERATION_ID=receipt.PLAN_OPERATION_ID;
 select *into placed from RRL_IW_GROUP_PLACEMENT where RECEIPT_OPERATION_ID=p_receipt;
 select *into unloaded from RRL_IW_GROUP_UNLOAD where OPERATION_ID=receipt.UNLOAD_OPERATION_ID;
 select *into cargo from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=plan.SOURCE_LOAD_OPERATION_ID;
 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'interwarehouse_receive')=1 and(WARE_ID=receipt.WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN');
 if n!=1 then raise_application_error(-20882,'INTERWARE_GROUP_CUSTODY_RECEIVER_REQUIRED');end if;
 if cargo.STATUS!='DEPARTED'or cargo.CUSTODY_RELEASED_AT is not null or cargo.CUSTODY_RELEASE_OPERATION_ID is not null or cargo.ROOT_UID!=receipt.ROOT_UID or unloaded.ROOT_UID!=receipt.ROOT_UID or unloaded.PLAN_OPERATION_ID!=receipt.PLAN_OPERATION_ID then raise_application_error(-20886,'INTERWARE_GROUP_CUSTODY_ORIGINAL_SOURCE_REQUIRED');end if;
 select count(*)into n from RRL_IW_GROUP_CUSTODY where RECEIPT_OPERATION_ID=p_receipt;if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_CUSTODY_ALREADY_RELEASED');end if;
 tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(receipt.ROOT_UID));
 select count(*)into expected from RRL_IW_GROUP_RECEIPT_LINE where OPERATION_ID=p_receipt;
 if tree.get_number('leaf_count')!=expected or tree.get_number('warehouse')!=receipt.WARE_ID or tree.get_string('cell')!=placed.TARGET_CELL or tree.get_array('ancestors').get_size!=0 then raise_application_error(-20886,'INTERWARE_GROUP_CUSTODY_PLACED_TOP_REQUIRED');end if;
 declare tree_wire clob:=tree.to_clob;begin
 select count(*)into n from RRL_IW_GROUP_RECEIPT_LINE l join json_table(tree_wire,'$.nodes[*]'columns(K varchar2(20)path '$.kind',U varchar2(200)path '$.uid',A varchar2(160)path '$.article',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))j on j.K='STOCK'and j.U=l.ROOT_UID and j.A=l.ARTICLE and RRL_STOCK_MATH.quantity(j.Q)=l.BASE_QTY and j.B=l.BASE_UOM where l.OPERATION_ID=p_receipt;
 if n!=expected then raise_application_error(-20886,'INTERWARE_GROUP_CUSTODY_EXACT_TREE_LEAVES_REQUIRED');end if;end;
 for line_value in(select l.ROOT_UID,l.ARTICLE,l.BASE_QTY,l.BASE_UOM,r.REMAIN,r.HARD_RESERVED_BASE,r.STOCK_VERSION,r.BASE_UOM STOCK_UOM
  from RRL_IW_GROUP_RECEIPT_LINE l left join RRL_REMAINS r on r.UID_POLETA=l.ROOT_UID and r.CELL=placed.TARGET_CELL
  where l.OPERATION_ID=p_receipt order by l.ROOT_UID)loop
  if line_value.REMAIN is null or line_value.REMAIN!=line_value.BASE_QTY or line_value.HARD_RESERVED_BASE!=0 or line_value.STOCK_UOM!=line_value.BASE_UOM then raise_application_error(-20886,'INTERWARE_GROUP_CUSTODY_EXACT_FREE_STOCK_REQUIRED');end if;
  x:=json_object_t();x.put('uid',line_value.ROOT_UID);x.put('article',line_value.ARTICLE);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(line_value.BASE_QTY));x.put('base_uom',line_value.BASE_UOM);x.put('stock_version',line_value.STOCK_VERSION);lines_value.append(x);
 end loop;
 p_domain:=json_object_t();p_domain.put('group_custody',true);p_domain.put('receipt_operation_id',p_receipt);p_domain.put('unload_operation_id',receipt.UNLOAD_OPERATION_ID);p_domain.put('source_load_operation_id',plan.SOURCE_LOAD_OPERATION_ID);p_domain.put('uid',receipt.ROOT_UID);p_domain.put('warehouse_id',receipt.WARE_ID);p_domain.put('cell',placed.TARGET_CELL);p_domain.put('lines',lines_value);
 p_domain.put('custody_released_at',to_char(unloaded.CREATED_AT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));p_domain.put('departure_operation_id',cargo.DEPARTURE_OPERATION_ID);
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_GROUP_CUSTODY_PLACEMENT_REQUIRED');
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();lines_value json_array_t;x json_object_t;
 begin
 describe_source(d.get_object('source').get_string('receipt_operation_id'),d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_IW_GROUP_RECEIPT',v.get_string('receipt_operation_id'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_IW_GROUP_UNLOAD',v.get_string('unload_operation_id'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_IW_GROUP_CUSTODY',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',v.get_string('source_load_operation_id'));RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v.get_string('uid'));RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TT.LOAD.HU:'||v.get_string('uid'));
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 lines_value:=v.get_array('lines');for i in 0..lines_value.get_size-1 loop x:=treat(lines_value.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),x.get_string('article'),v.get_string('cell'),null);end loop;
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');wire clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 receipt_id varchar2(100);load_id varchar2(100);unload_id varchar2(100);release_time timestamp with time zone;left_wire clob;right_wire clob;n number;
 begin
 select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(wire).get_object('domain');
 receipt_id:=v.get_string('receipt_operation_id');load_id:=v.get_string('source_load_operation_id');unload_id:=v.get_string('unload_operation_id');
 describe_source(receipt_id,p_actor,fresh);left_wire:=fresh.to_clob;right_wire:=v.to_clob;select count(*)into n from dual where json_equal(left_wire,right_wire);
 if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_CUSTODY_SOURCE_CHANGED');end if;
 select CREATED_AT into release_time from RRL_IW_GROUP_UNLOAD where OPERATION_ID=unload_id;
 insert into RRL_IW_GROUP_CUSTODY(OPERATION_ID,RECEIPT_OPERATION_ID,SOURCE_LOAD_OPERATION_ID,ACTOR)values(op,receipt_id,load_id,p_actor);
 update RRL_TT_HU_LOAD_FACT set CUSTODY_RELEASED_AT=release_time,CUSTODY_RELEASE_OPERATION_ID=op where LOAD_OPERATION_ID=load_id and CUSTODY_RELEASED_AT is null and CUSTODY_RELEASE_OPERATION_ID is null;
 if sql%rowcount!=1 then raise_application_error(-20886,'INTERWARE_GROUP_CUSTODY_COMPARE_SET_CONFLICT');end if;
 j.put('operation_id',op);j.put('receipt_operation_id',receipt_id);j.put('source_load_operation_id',load_id);j.put('pallet_identifier',v.get_string('uid'));j.put('warehouse_id',v.get_number('warehouse_id'));j.put('status','FIRST_LEG_CUSTODY_RELEASED');j.put('custody_released_at',v.get_string('custody_released_at'));j.put('stock_changed',false);j.put('customer_delivery_confirmed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_FACT_GUARD as
 procedure assert_head(p_operation varchar2,p_plan varchar2,p_uid varchar2,p_ware number,p_actor varchar2,p_kind varchar2,p_cell varchar2 default null,p_unload varchar2 default null)is
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');kind_value varchar2(80);state_value varchar2(20);wire clob;d json_object_t;
 begin
 if op is null or op!=p_operation or p_actor!=sys_context('RRL_STOCK_WRITE_CTX','ACTOR')or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)then raise_application_error(-20863,'INTERWARE_GROUP_FACT_ROOT_REQUIRED');end if;
 select COMMAND_TYPE,STATE,RESOLVED_PLAN_JSON into kind_value,state_value,wire from RRL_STOCK_OPERATION where OPERATION_ID=op;d:=json_object_t.parse(wire).get_object('domain');
 if kind_value!=p_kind or state_value!='IN_FLIGHT'or not d.get_boolean('group_receipt')or d.get_string('plan_operation_id')!=p_plan or d.get_string('uid')!=p_uid or d.get_number('warehouse_id')!=p_ware then raise_application_error(-20863,'INTERWARE_GROUP_EXACT_FACT_REQUIRED');end if;
 if p_kind='INTERWARE_RECEIVE'and(d.get_string('receive_cell')!=p_cell or d.get_string('unload_operation_id')!=p_unload)then raise_application_error(-20863,'INTERWARE_GROUP_EXACT_RECEIPT_REQUIRED');end if;
 RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_IW_GROUP_PLAN',p_plan));
 RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW',case when p_kind='INTERWARE_RECEIVE'then 'RRL_IW_GROUP_RECEIPT'else 'RRL_IW_GROUP_UNLOAD'end,op));
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_NEXT as
 function describe_source(p_st number,p_ware number)return json_object_t is
 bind RRL_IW_GROUP_ST_BIND%rowtype;receipt RRL_IW_GROUP_RECEIPT_LINE%rowtype;parent RRL_IW_GROUP_RECEIPT%rowtype;plan RRL_IW_GROUP_PLAN%rowtype;placed RRL_IW_GROUP_PLACEMENT%rowtype;
 v_p number;v_h number;v_uom varchar2(20);v_ver number;v_policy number;n number;unit_count number;unit_total number;unit_wire clob;unit_snapshot clob;wire clob;j json_object_t:=json_object_t();
 begin
 begin select *into bind from RRL_IW_GROUP_ST_BIND where ST_ID=p_st;exception when no_data_found then return null;end;
 select *into parent from RRL_IW_GROUP_RECEIPT where OPERATION_ID=bind.RECEIPT_OPERATION_ID;
 select *into receipt from RRL_IW_GROUP_RECEIPT_LINE where OPERATION_ID=parent.OPERATION_ID and ROOT_UID=bind.ROOT_UID;
 select *into plan from RRL_IW_GROUP_PLAN where OPERATION_ID=parent.PLAN_OPERATION_ID;
 select *into placed from RRL_IW_GROUP_PLACEMENT where RECEIPT_OPERATION_ID=parent.OPERATION_ID;
 if p_ware!=parent.WARE_ID or bind.WARE_ID!=p_ware or placed.TARGET_CELL!=bind.SOURCE_CELL or bind.SOURCE_ST_ID!=receipt.ST_ID or bind.SOURCE_LOAD_OPERATION_ID!=plan.SOURCE_LOAD_OPERATION_ID or bind.TARGET_TT_ID!=plan.TARGET_TT_ID then raise_application_error(-20886,'INTERWARE_GROUP_ORIGINAL_LINEAGE_REQUIRED');end if;
 select count(*)into n from RRL_IW_GROUP_CUSTODY where RECEIPT_OPERATION_ID=parent.OPERATION_ID;
 if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_FIRST_CUSTODY_REQUIRED');end if;
 select count(*)into n from RRL_IW_GROUP_DISPATCH where BIND_OPERATION_ID=bind.OPERATION_ID;
 if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_ALREADY_DISPATCHED');end if;
 select REMAIN,HARD_RESERVED_BASE,BASE_UOM,STOCK_VERSION into v_p,v_h,v_uom,v_ver from RRL_REMAINS where UID_POLETA=bind.ROOT_UID and CELL=bind.SOURCE_CELL;
 if v_p!=receipt.BASE_QTY or v_h!=0 or v_uom!=receipt.BASE_UOM or v_ver!=bind.STOCK_VERSION then raise_application_error(-20886,'INTERWARE_GROUP_WHOLE_FREE_STOCK_VERSION_REQUIRED');end if;
 select count(*)into n from RRL_REMAINS where UID_POLETA=bind.ROOT_UID and CELL!=bind.SOURCE_CELL and(REMAIN!=0 or HARD_RESERVED_BASE!=0);
 if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_ONE_STOCK_CELL_REQUIRED');end if;
 select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=parent.OPERATION_ID and STATE='APPLIED';
 select MANIFEST into unit_wire from json_table(wire,'$.domain.lots[*]'columns(U varchar2(200)path '$.uid',MANIFEST clob format json path '$.issued_manifest'))where U=bind.ROOT_UID;
 select count(*)into unit_count from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=bind.ROOT_UID;
 if unit_count>0 then
  select count(*),sum(u.BASE_QTY),json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob)
  into n,unit_total,unit_snapshot from RRL_WMS_RECEIPT_UNIT u join json_table(unit_wire,'$.units[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))src on src.K=u.PHYSICAL_UNIT_KEY
  where u.CURRENT_UID=bind.ROOT_UID and u.CURRENT_CELL=bind.SOURCE_CELL and u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null and u.BASE_QTY=RRL_STOCK_MATH.quantity(src.Q)and u.BASE_UOM=src.B;
  if n!=unit_count or unit_total!=receipt.BASE_QTY or json_object_t.parse(unit_wire).get_number('physical_unit_count')!=unit_count then raise_application_error(-20884,'INTERWARE_GROUP_ORIGINAL_AVAILABLE_UNITS_REQUIRED');end if;
  j.put('physical_units',json_array_t.parse(unit_snapshot));
 elsif json_object_t.parse(unit_wire).get_number('physical_unit_count')!=0 or RRL_INTERWARE_MARK_SCAN.required_for_article(receipt.ARTICLE)=1 then raise_application_error(-20884,'INTERWARE_GROUP_MARKED_SOURCE_UNITS_REQUIRED');end if;
 RRL_IW_GROUP_THERMAL.assert_cell(p_ware,receipt.ARTICLE,bind.SOURCE_CELL);
 select max(POLICY_VERSION)into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=receipt.ARTICLE and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=DENOMINATOR;
 if v_policy is null then raise_application_error(-20886,'INTERWARE_GROUP_BASE_UOM_REQUIRED');end if;
 select count(*)into n from RRL_SBORKA_PALLETS where ID=p_st and WARE_ID=p_ware and ADDR=bind.FINAL_ADDRESS and RETURN_SUPPLIER_ID is null and nvl(CONDITION,0)<2 and(TRANSTASK_ID is null or TRANSTASK_ID=bind.TARGET_TT_ID);
 if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_ST_CHANGED');end if;
 j.put('group_receipt_operation_id',parent.OPERATION_ID);j.put('group_plan_operation_id',plan.OPERATION_ID);j.put('binding_operation_id',bind.OPERATION_ID);j.put('receipt_operation_id',parent.OPERATION_ID);j.put('source_load_operation_id',bind.SOURCE_LOAD_OPERATION_ID);j.put('source_st_id',bind.SOURCE_ST_ID);j.put('st_id',p_st);j.put('target_trip_id',bind.TARGET_TT_ID);j.put('warehouse_id',p_ware);
 j.put('uid',bind.ROOT_UID);j.put('cell',bind.SOURCE_CELL);j.put('article',receipt.ARTICLE);j.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_p));j.put('base_uom',v_uom);j.put('stock_version',v_ver);j.put('uom_version',v_policy);return j;
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_GROUP_PLACED_SOURCE_REQUIRED');
 end;
 procedure declare_source(p_source json_object_t,p_operation varchar2,p_resources in out nocopy json_array_t)is
 begin
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_GROUP_ST_BIND',p_source.get_string('binding_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_GROUP_RECEIPT',p_source.get_string('receipt_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_GROUP_DISPATCH',p_operation);
 end;
 procedure validate_load(p_source json_object_t,p_actor varchar2)is
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');n number;v_kind varchar2(80);binding_id varchar2(100):=p_source.get_string('binding_operation_id');st_id number:=p_source.get_number('st_id');trip_id number:=p_source.get_number('target_trip_id');v_ware_id number:=p_source.get_number('warehouse_id');fresh json_object_t;left_wire clob;right_wire clob;
 begin
 select COMMAND_TYPE into v_kind from RRL_STOCK_OPERATION where OPERATION_ID=op and STATE='IN_FLIGHT';
 if v_kind!='HU_SHIP'then raise_application_error(-20886,'INTERWARE_GROUP_WHOLE_HU_LOAD_REQUIRED');end if;
 select count(*)into n from RRL_STOCK_OPERATION o where o.OPERATION_ID=op and json_value(o.RESOLVED_PLAN_JSON,'$.domain.loading.trip'returning number)=trip_id
 and exists(select 1 from json_table(o.RESOLVED_PLAN_JSON,'$.domain.shipments[*]'columns(B varchar2(100)path '$.domain.interwarehouse_onward_source.binding_operation_id',S number path '$.domain.interwarehouse_onward_source.st_id'))s where s.B=binding_id and s.S=st_id);
 if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_RESOLVED_TARGET_LOAD_REQUIRED');end if;
 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'stock_posting_shipping')=1 and(WARE_ID=v_ware_id or upper(trim(USER_GROUP))='GLOBAL_ADMIN');
 if n!=1 then raise_application_error(-20882,'INTERWARE_GROUP_CURRENT_SHIPPER_REQUIRED');end if;
 fresh:=describe_source(st_id,v_ware_id);left_wire:=fresh.to_clob;right_wire:=p_source.to_clob;select count(*)into n from dual where json_equal(left_wire,right_wire);
 if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_LOAD_SOURCE_CHANGED');end if;
 select count(*)into n from RRL_SBORKA_PALLETS where ID=st_id and TRANSTASK_ID=trip_id;if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_ORIGINAL_TARGET_TRIP_REQUIRED');end if;
 end;
 procedure dispatched(p_source json_object_t,p_actor varchar2)is
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');binding_id varchar2(100):=p_source.get_string('binding_operation_id');receipt_id varchar2(100):=p_source.get_string('receipt_operation_id');source_load varchar2(100):=p_source.get_string('source_load_operation_id');st_id number:=p_source.get_number('st_id');lot_id varchar2(200):=p_source.get_string('uid');qty number:=RRL_STOCK_MATH.quantity(p_source.get_string('quantity'));uom_value varchar2(20):=p_source.get_string('base_uom');payload clob;
 begin
 insert into RRL_IW_GROUP_DISPATCH(OPERATION_ID,BIND_OPERATION_ID,RECEIPT_OPERATION_ID,SOURCE_LOAD_OPERATION_ID,ST_ID,ROOT_UID,BASE_QTY,BASE_UOM,ACTOR)values(op,binding_id,receipt_id,source_load,st_id,lot_id,qty,uom_value,p_actor);
 payload:=p_source.to_clob;
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values('IW.GROUP:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op||':'||RRL_STOCK_PLAN_HELPER.decimal_text(st_id),'AL32UTF8'),sys.dbms_crypto.hash_sh256)),'INTERWARE_ONWARD_DISPATCHED',payload);
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_PUT as
 procedure describe_receipt(p_receipt varchar2,p_target varchar2,p_actor varchar2,p_task number,p_domain out json_object_t)is
 receipt RRL_IW_GROUP_RECEIPT%rowtype;tree json_object_t;nodes json_array_t;node json_object_t;line_value json_object_t;lines_value json_array_t:=json_array_t();
 n number;line_count number;wire clob;unit_count number;matched number;total number;lot_uid varchar2(200);lot_qty number;lot_uom varchar2(20);lot_article varchar2(160);
 current_p number;current_h number;stock_version number;current_uom varchar2(20);task_count number;
 begin
 select *into receipt from RRL_IW_GROUP_RECEIPT where OPERATION_ID=p_receipt;
 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'warehouse_task_execute')=1 and(WARE_ID=receipt.WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN');
 if n!=1 then raise_application_error(-20882,'INTERWARE_GROUP_PLACEMENT_ACTOR_REQUIRED');end if;
 select count(*)into n from RRL_IW_GROUP_PLACEMENT where RECEIPT_OPERATION_ID=p_receipt;
 if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_ALREADY_PLACED');end if;
 select count(*)into n from RRL_IW_GROUP_PUT_PLAN p join RRL_WAREHOUSE_TASK t on t.TASK_ID=p.TASK_ID where p.RECEIPT_OPERATION_ID=p_receipt and t.STATUS!='CANCELLED'and(p_task is null or p.TASK_ID!=p_task);
 if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_ACTIVE_PLACEMENT_EXISTS');end if;
 tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(receipt.ROOT_UID,p_task));nodes:=tree.get_array('nodes');
 if tree.get_string('cell')!=receipt.RECEIVE_CELL or tree.get_number('warehouse')!=receipt.WARE_ID or tree.get_array('ancestors').get_size!=0 or nodes.get_size>200 then raise_application_error(-20886,'INTERWARE_GROUP_RECEIVED_TOP_REQUIRED');end if;
 select count(*)into line_count from RRL_IW_GROUP_RECEIPT_LINE where OPERATION_ID=p_receipt;
 if tree.get_number('leaf_count')!=line_count then raise_application_error(-20886,'INTERWARE_GROUP_RECEIVED_LEAF_COUNT_CHANGED');end if;
 select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=p_receipt and STATE='APPLIED';
 for i in 0..nodes.get_size-1 loop
  node:=treat(nodes.get(i)as json_object_t);
  if node.get_string('kind')='STOCK'then
   lot_uid:=node.get_string('uid');lot_article:=node.get_string('article');lot_qty:=RRL_STOCK_MATH.quantity(node.get_string('quantity'));lot_uom:=node.get_string('base_uom');
   RRL_IW_GROUP_THERMAL.assert_cell(receipt.WARE_ID,lot_article,p_target);
   select count(*)into n from RRL_IW_GROUP_RECEIPT_LINE where OPERATION_ID=p_receipt and ROOT_UID=lot_uid and ARTICLE=lot_article and BASE_QTY=lot_qty and BASE_UOM=lot_uom;
   if n!=1 or node.get_number('open_task_count')>0 then raise_application_error(-20886,'INTERWARE_GROUP_EXACT_RECEIVED_LEAF_REQUIRED');end if;
   select REMAIN,HARD_RESERVED_BASE,BASE_UOM,STOCK_VERSION into current_p,current_h,current_uom,stock_version from RRL_REMAINS where UID_POLETA=lot_uid and CELL=receipt.RECEIVE_CELL;
   if current_p!=lot_qty or current_h!=0 or current_uom!=lot_uom then raise_application_error(-20886,'INTERWARE_GROUP_WHOLE_UNRESERVED_RECEIPT_REQUIRED');end if;
   select count(*)into unit_count from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=lot_uid;
   select count(*),sum(u.BASE_QTY)into matched,total from RRL_WMS_RECEIPT_UNIT u join json_table(wire,'$.domain.lots[*]'columns(U varchar2(200)path '$.uid',nested path '$.issued_manifest.units[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom')))j
   on j.U=lot_uid and j.K=u.PHYSICAL_UNIT_KEY and RRL_STOCK_MATH.quantity(j.Q)=u.BASE_QTY and j.B=u.BASE_UOM
   where u.CURRENT_UID=lot_uid and u.CURRENT_CELL=receipt.RECEIVE_CELL and u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null;
   if matched!=unit_count or(unit_count>0 and total!=lot_qty)then raise_application_error(-20884,'INTERWARE_GROUP_ORIGINAL_AVAILABLE_KEYS_REQUIRED');end if;
   line_value:=json_object_t();line_value.put('uid',lot_uid);line_value.put('article',lot_article);line_value.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(lot_qty));line_value.put('base_uom',lot_uom);line_value.put('stock_version',stock_version);line_value.put('physical_unit_count',unit_count);lines_value.append(line_value);
  elsif node.get_string('kind')!='CONTAINER'or node.get_number('open_task_count')>0 then raise_application_error(-20886,'INTERWARE_GROUP_SEALED_TOP_TASK_REQUIRED');end if;
 end loop;
 if p_target is null or p_target=receipt.RECEIVE_CELL then raise_application_error(-20886,'INTERWARE_GROUP_SEPARATE_PLACEMENT_REQUIRED');end if;
 p_domain:=json_object_t();p_domain.put('receipt_operation_id',p_receipt);p_domain.put('uid',receipt.ROOT_UID);p_domain.put('warehouse_id',receipt.WARE_ID);p_domain.put('from_cell',receipt.RECEIVE_CELL);p_domain.put('target_cell',p_target);p_domain.put('lines',lines_value);
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_GROUP_RECEIPT_STOCK_REQUIRED');
 end;
 procedure declare_rows(p_domain json_object_t,p_operation varchar2,p_resources in out nocopy json_array_t)is
 begin
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_GROUP_RECEIPT',p_domain.get_string('receipt_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_GROUP_PUT_PLAN',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_GROUP_PLACEMENT',p_operation);
 end;
 procedure validate_receipt(p_domain json_object_t,p_actor varchar2,p_task number)is
 fresh json_object_t;left_wire clob;right_wire clob;n number;
 begin
 describe_receipt(p_domain.get_string('receipt_operation_id'),p_domain.get_string('target_cell'),p_actor,p_task,fresh);
 left_wire:=fresh.to_clob;right_wire:=p_domain.to_clob;select count(*)into n from dual where json_equal(left_wire,right_wire);
 if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: grouped received HU');end if;
 end;
 procedure record_plan(p_operation varchar2,p_task number,p_domain json_object_t,p_actor varchar2)is
 v_receipt varchar2(100):=p_domain.get_string('receipt_operation_id');v_uid varchar2(200):=p_domain.get_string('uid');v_ware number:=p_domain.get_number('warehouse_id');v_from varchar2(60):=p_domain.get_string('from_cell');v_target varchar2(60):=p_domain.get_string('target_cell');
 begin
 insert into RRL_IW_GROUP_PUT_PLAN(OPERATION_ID,RECEIPT_OPERATION_ID,TASK_ID,ROOT_UID,WARE_ID,FROM_CELL,TARGET_CELL,ACTOR)values(p_operation,v_receipt,p_task,v_uid,v_ware,v_from,v_target,p_actor);
 end;
 procedure record_complete(p_operation varchar2,p_task number,p_domain json_object_t,p_actor varchar2)is
 v_receipt varchar2(100):=p_domain.get_string('receipt_operation_id');v_uid varchar2(200):=p_domain.get_string('uid');v_ware number:=p_domain.get_number('warehouse_id');v_target varchar2(60):=p_domain.get_string('target_cell');
 begin
 insert into RRL_IW_GROUP_PLACEMENT(OPERATION_ID,RECEIPT_OPERATION_ID,TASK_ID,ROOT_UID,WARE_ID,TARGET_CELL,ACTOR)values(p_operation,v_receipt,p_task,v_uid,v_ware,v_target,p_actor);
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_PUT_GUARD as
 procedure assert_fact(p_operation varchar2,p_receipt varchar2,p_task number,p_uid varchar2,p_ware number,p_target varchar2,p_actor varchar2,p_planning number)is
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');kind_value varchar2(80);state_value varchar2(20);wire clob;d json_object_t;g json_object_t;n number;expected number;move_count number;
 begin
 if op is null or op!=p_operation or p_actor!=sys_context('RRL_STOCK_WRITE_CTX','ACTOR')or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)then raise_application_error(-20863,'INTERWARE_GROUP_PUT_FACT_ROOT_REQUIRED');end if;
 select COMMAND_TYPE,STATE,RESOLVED_PLAN_JSON into kind_value,state_value,wire from RRL_STOCK_OPERATION where OPERATION_ID=op;
 d:=json_object_t.parse(wire).get_object('domain');g:=d.get_object('group_placement');
 if state_value!='IN_FLIGHT'or d.get_number('task_id')!=p_task or d.get_number('planning')!=p_planning or g is null or g.get_string('receipt_operation_id')!=p_receipt or g.get_string('uid')!=p_uid or g.get_number('warehouse_id')!=p_ware or g.get_string('target_cell')!=p_target then raise_application_error(-20863,'INTERWARE_GROUP_PUT_EXACT_DOMAIN_REQUIRED');end if;
 if(p_planning=1 and kind_value!='HU_PLAN_MOVE')or(p_planning=0 and kind_value not in('TASK_COMPLETE','HU_TASK_COMPLETE'))then raise_application_error(-20863,'INTERWARE_GROUP_PUT_EXACT_OWNER_REQUIRED');end if;
 RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_IW_GROUP_RECEIPT',p_receipt));
 RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW',case when p_planning=1 then 'RRL_IW_GROUP_PUT_PLAN'else 'RRL_IW_GROUP_PLACEMENT'end,op));
 select count(*)into n from RRL_WAREHOUSE_TASK where TASK_ID=p_task and UID_PALLET=p_uid and FROM_WARE_ID=p_ware and TO_WARE_ID=p_ware and TO_CELL=p_target and SOURCE_DOC_TYPE='WAREHOUSE_HU'and QTY=1 and UNIT_CODE='HU'and STATUS=case when p_planning=1 then 'PLANNED'else 'DONE'end;
 if n!=1 then raise_application_error(-20863,'INTERWARE_GROUP_PUT_EXACT_TASK_REQUIRED');end if;
 if p_planning=0 then
  select count(*)into expected from RRL_IW_GROUP_RECEIPT_LINE where OPERATION_ID=p_receipt;
  select count(*)into move_count from RRL_WAREHOUSE_TASK_STOCK_MOVE where TASK_ID=p_task and OPERATION_ID=op;
  select count(*)into n from RRL_WAREHOUSE_TASK_STOCK_MOVE m join RRL_IW_GROUP_RECEIPT_LINE l on l.OPERATION_ID=p_receipt and l.ROOT_UID=m.UID_PALLET and m.TARGET_UID_PALLET=l.ROOT_UID and m.BASE_QTY=l.BASE_QTY and m.BASE_UOM=l.BASE_UOM
   where m.TASK_ID=p_task and m.OPERATION_ID=op and m.TO_CELL=p_target;
  if n!=expected or move_count!=expected then raise_application_error(-20863,'INTERWARE_GROUP_PUT_ALL_COMMODITY_EFFECTS_REQUIRED');end if;
 end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_REC as

 procedure describe_source(p_request clob,p_actor varchar2,p_domain out json_object_t)is

 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v_plan varchar2(100):=d.get_object('source').get_string('plan_operation_id');

 plan RRL_IW_GROUP_PLAN%rowtype;source_value json_object_t;wire clob;lots json_array_t;nodes json_array_t;links json_array_t;

 nested_value json_object_t:=json_object_t();containers json_array_t:=json_array_t();nested_links json_array_t:=json_array_t();

 legs json_array_t:=json_array_t();item json_object_t;x json_object_t;manifest json_object_t;leg json_object_t;

 v_kind varchar2(80):=d.get_string('command_type');v_vehicle varchar2(60);v_cell varchar2(60);v_unload varchar2(100);

 v_uid varchar2(200);v_article varchar2(160);v_uom varchar2(20);v_barcode_article varchar2(160);v_barcode_uom varchar2(20);v_qty number;v_version number;

 n number;unit_count number;total_units number:=0;requested json_array_t;seen_count number;first_uid varchar2(200);

 begin

 select *into plan from RRL_IW_GROUP_PLAN where OPERATION_ID=v_plan;

 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'interwarehouse_receive')=1 and(WARE_ID=plan.TARGET_WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN');

 if n!=1 then raise_application_error(-20882,'INTERWARE_GROUP_TARGET_RECEIVER_REQUIRED');end if;

 wire:=RRL_IW_GROUP_ARCHIVE.snapshot_json(plan.SOURCE_LOAD_OPERATION_ID);

 if dbms_lob.compare(wire,plan.SOURCE_JSON)!=0 then raise_application_error(-20886,'INTERWARE_GROUP_SOURCE_CHANGED');end if;

 source_value:=json_object_t.parse(wire);lots:=source_value.get_array('lots');nodes:=source_value.get_object('source_composition').get_array('nodes');links:=source_value.get_object('source_composition').get_array('links');

 select count(*)into n from RRL_IW_GROUP_RECEIPT where PLAN_OPERATION_ID=v_plan;if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_ALREADY_RECEIVED');end if;

 select TRANSPORT into v_vehicle from RRL_TRANSPORT_TASK where ID=plan.SOURCE_TT_ID;

 if m.get_string('scan_pallet')is null or m.get_string('scan_pallet')!=plan.ROOT_UID then raise_application_error(-20886,'INTERWARE_GROUP_TOP_SCAN_REQUIRED');end if;

 select count(*)into n from RRL_TT_DOCK where DOCK=plan.INBOUND_DOCK and WARE_ID=plan.TARGET_WARE_ID and nvl(DOCK_IS_BLOCKED,0)=0;

 if n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_DOCK_UNAVAILABLE');end if;

 p_domain:=json_object_t();p_domain.put('group_receipt',true);p_domain.put('plan_operation_id',v_plan);p_domain.put('source_load_operation_id',plan.SOURCE_LOAD_OPERATION_ID);

 p_domain.put('uid',plan.ROOT_UID);p_domain.put('warehouse_id',plan.TARGET_WARE_ID);p_domain.put('lots',lots);p_domain.put('vehicle_number',v_vehicle);p_domain.put('inbound_dock',plan.INBOUND_DOCK);

 if v_kind='INTERWARE_UNLOAD'then

  select count(*)into n from RRL_IW_GROUP_UNLOAD where PLAN_OPERATION_ID=v_plan;

  if n!=0 or m.get_string('scan_vehicle')is null or m.get_string('scan_vehicle')!=v_vehicle or m.get_string('scan_dock')is null or m.get_string('scan_dock')!=plan.INBOUND_DOCK then raise_application_error(-20886,'INTERWARE_GROUP_EXACT_UNLOAD_REQUIRED');end if;

  return;

 end if;

 select OPERATION_ID into v_unload from RRL_IW_GROUP_UNLOAD where PLAN_OPERATION_ID=v_plan;

 v_cell:=m.get_string('scan_cell');

 select count(*)into n from RRL_CELLS where CELL=v_cell and WARE_ID=plan.TARGET_WARE_ID and nvl(BLOCKED_FOR_ACCEPT,0)=0 and BLOCKED_FOR_REMAINS=1 and BLOCKED_FOR_POPOLNENIE=1;

 if n!=1 or m.has('partial_receipt')then raise_application_error(-20886,'INTERWARE_GROUP_WHOLE_UNIT_RECEIPT_REQUIRED');end if;

 requested:=m.get_array('items');if requested is null or requested.get_size!=lots.get_size then raise_application_error(-20886,'INTERWARE_GROUP_ALL_ITEMS_REQUIRED');end if;

 for i in 0..lots.get_size-1 loop

  item:=treat(lots.get(i)as json_object_t);v_uid:=item.get_string('uid');v_article:=item.get_string('article');v_uom:=item.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(item.get_string('quantity'));manifest:=item.get_object('issued_manifest');total_units:=total_units+manifest.get_number('physical_unit_count');

 if total_units>10000 then raise_application_error(-20881,'INTERWARE_GROUP_UNIT_BOUND_10000');end if;

  if first_uid is null then first_uid:=v_uid;end if;

  seen_count:=0;

  for j in 0..requested.get_size-1 loop

   x:=treat(requested.get(j)as json_object_t);

   if x.get_string('uid')=v_uid then

    seen_count:=seen_count+1;

    if x.get_string('article')is null or x.get_string('article')!=v_article or x.get_string('base_uom')is null or x.get_string('base_uom')!=v_uom or x.get_string('quantity')is null or RRL_STOCK_MATH.quantity(x.get_string('quantity'))!=v_qty then raise_application_error(-20886,'INTERWARE_GROUP_EXACT_ITEM_REQUIRED');end if;

    RRL_STOCK_QC_ITEM.resolve_barcode(x.get_string('scan_article'),v_barcode_article,v_barcode_uom);

    if v_barcode_article!=v_article then raise_application_error(-20886,'INTERWARE_GROUP_FOREIGN_ITEM_BARCODE');end if;

   end if;

  end loop;

  if seen_count!=1 then raise_application_error(-20886,'INTERWARE_GROUP_DISTINCT_ALL_ITEMS_REQUIRED');end if;

  RRL_IW_GROUP_THERMAL.assert_cell(plan.TARGET_WARE_ID,v_article,v_cell);

  select max(POLICY_VERSION)into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=DENOMINATOR;

  if v_version is null then raise_application_error(-20886,'INTERWARE_GROUP_BASE_UOM_REQUIRED');end if;

  select count(*)into n from RRL_SKU_RECEIPT_PROFILE where ARTICUL=v_article;

  if n>0 then

   declare matched number;begin

    select count(*)into matched from RRL_WMS_RECEIPT_UNIT u join RRL_WMS_RECEIPT_CODE code on code.UID_PALLET=u.UID_PALLET and code.UNIT_ID=u.UNIT_ID

    join RRL_SKU_RECEIPT_PROFILE card on card.ARTICUL=v_article and card.SYSTEM_CODE=code.SYSTEM_CODE,

    json_table(code.PROFILES_JSON,'$[*]'columns(CODE_PROFILE varchar2(80)path '$.profile',CODE_VERSION varchar2(40)path '$.version'))decoded

    where u.CURRENT_UID=v_uid and u.STOCK_STATUS='ISSUED'and card.PROFILE_CODE=decoded.CODE_PROFILE and card.PROFILE_VERSION=decoded.CODE_VERSION;

    if matched!=n*manifest.get_number('physical_unit_count')then raise_application_error(-20886,'INTERWARE_GROUP_CURRENT_CODE_PROFILE_VERSION_REQUIRED');end if;

   end;

  end if;

  item.put('uom_version',v_version);lots.put(i,item,true);

  leg:=json_object_t();leg.put('uid',v_uid);leg.put('article',v_article);leg.put('quantity',item.get_string('quantity'));leg.put('base_uom',v_uom);leg.put('cell',manifest.get_string('source_cell'));legs.append(leg);

 end loop;

 declare scan_domain json_object_t:=json_object_t();begin

  scan_domain.put('legs',legs);
  if RRL_INTERWARE_MARK_SCAN.required_for_plan(scan_domain.to_clob)=1 then RRL_INTERWARE_MARK_SCAN.validate_scan(scan_domain.to_clob,m.to_clob,unit_count);

  elsif (m.has('unit_scans')and m.get_array('unit_scans').get_size>0)or (m.has('aggregation_scans')and m.get_array('aggregation_scans').get_size>0)then raise_application_error(-20886,'INTERWARE_GROUP_UNEXPECTED_UNIT_SCANS');end if;

 end;

 for i in 0..nodes.get_size-1 loop

  x:=treat(nodes.get(i)as json_object_t);

  if x.get_string('kind')='CONTAINER'then

   item:=json_object_t();item.put('uid',x.get_string('uid'));item.put('version',x.get_number('version')+1);item.put('type',x.get_string('type'));item.put('tare',x.get_string('tare_weight_kg'));containers.append(item);

  end if;

 end loop;

 for i in 0..links.get_size-1 loop x:=treat(links.get(i)as json_object_t);x.put('version',x.get_number('version')+1);nested_links.append(x);end loop;

 nested_value.put('stock_uid',first_uid);nested_value.put('place_uid',plan.ROOT_UID);nested_value.put('source_load_operation_id',plan.SOURCE_LOAD_OPERATION_ID);nested_value.put('containers',containers);nested_value.put('links',nested_links);

 p_domain.put('nested_source',nested_value);p_domain.put('lots',lots);p_domain.put('receive_cell',v_cell);p_domain.put('unload_operation_id',v_unload);p_domain.put('legs',legs);

 exception when no_data_found then raise_application_error(-20886,'INTERWARE_GROUP_PLAN_UNLOAD_REQUIRED');

 end;

 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is

 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();lots json_array_t;item json_object_t;

 units json_array_t;x json_object_t;nested_value json_object_t;links json_array_t;containers json_array_t;new_id number;

 begin

 describe_source(p_request,d.get_string('actor'),v);

 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');

 RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));

 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_IW_GROUP_PLAN',v.get_string('plan_operation_id'));

 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_IW_GROUP_UNLOAD',nvl(v.get_string('unload_operation_id'),p_operation));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_IW_GROUP_RECEIPT',p_operation);

 lots:=v.get_array('lots');

 for i in 0..lots.get_size-1 loop item:=treat(lots.get(i)as json_object_t);

  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,item.get_string('uid'),item.get_string('article'),null,v.get_string('receive_cell'));

  RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',item.get_string('uid'));

  units:=item.get_object('issued_manifest').get_array('units');

  for j in 0..units.get_size-1 loop x:=treat(units.get(j)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',x.get_string('key'));end loop;

 end loop;

 if v.has('nested_source')then

  nested_value:=v.get_object('nested_source');containers:=nested_value.get_array('containers');links:=nested_value.get_array('links');

  for i in 0..containers.get_size-1 loop x:=treat(containers.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',x.get_string('uid'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',x.get_string('uid'));end loop;

  for i in 0..links.get_size-1 loop x:=treat(links.get(i)as json_object_t);select RRL_WMS_HU_LINK_SQ.nextval into new_id from dual;x.put('new_id',new_id);links.put(i,x,true);

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(new_id));

  end loop;

  nested_value.put('links',links);v.put('nested_source',nested_value);

 end if;

 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;

 end;

 procedure assert_fresh(p_request clob,p_actor varchar2,p_domain json_object_t)is

 fresh json_object_t;cached json_object_t:=p_domain.clone();nested_value json_object_t;links json_array_t;x json_object_t;new_id number;n number;fresh_wire clob;cached_wire clob;equal_count number;

 type seen_set is table of boolean index by varchar2(80);seen seen_set;

 begin

 describe_source(p_request,p_actor,fresh);

 if cached.has('nested_source')then

  nested_value:=cached.get_object('nested_source');links:=nested_value.get_array('links');

  for i in 0..links.get_size-1 loop

   x:=treat(links.get(i)as json_object_t);new_id:=x.get_number('new_id');

   if new_id is null or seen.exists(to_char(new_id))then raise_application_error(-20886,'INTERWARE_GROUP_RESERVED_LINK_REQUIRED');end if;seen(to_char(new_id)):=true;

   select count(*)into n from RRL_WMS_HU_LINK where HU_LINK_ID=new_id;if n!=0 then raise_application_error(-20886,'INTERWARE_GROUP_LINK_ALREADY_USED');end if;

   x.remove('new_id');links.put(i,x,true);

  end loop;

  nested_value.put('links',links);cached.put('nested_source',nested_value);

 end if;

 fresh_wire:=fresh.to_clob;cached_wire:=cached.to_clob;select count(*)into equal_count from dual where json_equal(fresh_wire,cached_wire);

 if equal_count!=1 then raise_application_error(-20886,'INTERWARE_GROUP_SOURCE_CHANGED_AFTER_LOCK');end if;

 end;

end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_SOURCE as
 function source_json(p_load varchar2,p_actor varchar2)return clob is
 begin RRL_INTERWARE_UNIT_SOURCE.assert_scope(p_load,p_actor);return RRL_IW_GROUP_ARCHIVE.snapshot_json(p_load);end;
end;
/


CREATE OR REPLACE package body RRL_IW_GROUP_THERMAL as
 procedure assert_cell(p_ware number,p_article varchar2,p_cell varchar2)is
 lo number;hi number;j json_object_t:=json_object_t();wire clob;
 begin
 begin select TEMP_MIN,TEMP_MAX into lo,hi from RRL_RECEIPT_SKU_RULE where WARE_ID=p_ware and ARTICUL=p_article;
 exception when no_data_found then lo:=null;hi:=null;end;
 if(lo is null and hi is not null)or(lo is not null and hi is null)or lo>hi then raise_application_error(-20886,'INTERWARE_GROUP_SKU_TEMPERATURE_RANGE_INVALID');end if;
 j.put('task_temp_min',lo);j.put('task_temp_max',hi);wire:=j.to_clob;
 RRL_INTERWARE_THERMAL.assert_cell(wire,p_ware,p_cell);
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_HU_REC_CORE as
 procedure declare_rows(p_domain json_object_t,p_operation varchar2,p_resources in out nocopy json_array_t)is
 source_hu json_object_t;containers json_array_t;links json_array_t;x json_object_t;
 begin
 if not p_domain.has('nested_source')then return;end if;
 source_hu:=p_domain.get_object('nested_source');containers:=source_hu.get_array('containers');links:=source_hu.get_array('links');
 RRL_STOCK_PLAN_HELPER.anchor(p_resources,30,'HU',source_hu.get_string('stock_uid'));
 for i in 0..containers.get_size-1 loop x:=treat(containers.get(i)as json_object_t);
 RRL_STOCK_PLAN_HELPER.anchor(p_resources,30,'HU',x.get_string('uid'));RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PALLETS',x.get_string('uid'));end loop;
 for i in 0..links.get_size-1 loop x:=treat(links.get(i)as json_object_t);
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('new_id')));
 end loop;
 end;
 procedure restore(p_domain json_object_t,p_operation varchar2,p_actor varchar2)is
 source_hu json_object_t:=p_domain.get_object('nested_source');containers json_array_t:=source_hu.get_array('containers');links json_array_t:=source_hu.get_array('links');x json_object_t;
 v_uid varchar2(200);v_cell varchar2(60):=p_domain.get_string('receive_cell');v_load varchar2(100):=p_domain.get_string('source_load_operation_id');v_version number;
 v_parent varchar2(200);v_child varchar2(200);v_link number;
 begin
 for i in 0..containers.get_size-1 loop
 x:=treat(containers.get(i)as json_object_t);v_uid:=x.get_string('uid');v_version:=x.get_number('version');
 update RRL_PALLETS set HU_CURRENT_CELL=v_cell,HU_SHIPPED_OPERATION=null,HU_CONTENT_VERSION=HU_CONTENT_VERSION+1
 where UID_PALLET=v_uid and HU_KIND='CONTAINER'and HU_CURRENT_CELL is null and HU_SHIPPED_OPERATION=v_load and HU_CONTENT_VERSION=v_version;
 if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: receiving source container');end if;
 end loop;
 for i in 0..links.get_size-1 loop
 x:=treat(links.get(i)as json_object_t);v_parent:=x.get_string('parent');v_child:=x.get_string('child');v_link:=x.get_number('new_id');
 insert into RRL_WMS_HU_LINK(HU_LINK_ID,PARENT_UID,CHILD_PALLET_UID,ACTIVE_FLAG,LINK_VERSION,LINKED_OPERATION_ID,LINKED_BY)
 values(v_link,v_parent,v_child,1,0,p_operation,p_actor);
 end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_HU_SOURCE as
 function stock_uid(p_load varchar2)return varchar2 is
 wire clob;tree json_object_t;nodes json_array_t;x json_object_t;result_uid varchar2(200);n number:=0;
 begin
 select COMPOSITION_JSON into wire from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=p_load and STATUS='DEPARTED'and ROOT_CASE_TASK_ID is null;
 tree:=json_object_t.parse(wire);nodes:=tree.get_array('nodes');
 if nodes.get_size<1 or nodes.get_size>200 or tree.get_number('leaf_count')!=1 or tree.get_number('top_place_count')!=1 then raise_application_error(-20886,'INTERWARE_ONE_STOCK_LEAF_SOURCE_REQUIRED');end if;
 for i in 0..nodes.get_size-1 loop
 x:=treat(nodes.get(i)as json_object_t);
 if x.get_string('kind')='STOCK'then result_uid:=x.get_string('uid');n:=n+1;
 elsif x.get_string('kind')!='CONTAINER'then raise_application_error(-20886,'INTERWARE_STOCK_CONTAINER_ONLY_SOURCE');end if;
 end loop;
 if n!=1 or result_uid is null then raise_application_error(-20886,'INTERWARE_ONE_STOCK_LEAF_SOURCE_REQUIRED');end if;
 return result_uid;
 end;
 function context_json(p_load varchar2)return clob is
 lf RRL_TT_HU_LOAD_FACT%rowtype;tree json_object_t;nodes json_array_t;links json_array_t;containers json_array_t:=json_array_t();context_links json_array_t:=json_array_t();
 x json_object_t;item json_object_t;result_value json_object_t:=json_object_t();pp RRL_PALLETS%rowtype;old_link RRL_WMS_HU_LINK%rowtype;
 leaf_uid varchar2(200);n number;kind_value varchar2(80);v_uid varchar2(200);v_link_id number;
 begin
 leaf_uid:=stock_uid(p_load);select *into lf from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=p_load;
 tree:=json_object_t.parse(lf.COMPOSITION_JSON);nodes:=tree.get_array('nodes');
 if nodes.get_size=1 then return null;end if;
 select COMMAND_TYPE into kind_value from RRL_STOCK_OPERATION where OPERATION_ID=p_load and STATE='APPLIED';
 if kind_value!='HU_SHIP'or lf.ROOT_UID!=tree.get_string('root')then raise_application_error(-20886,'INTERWARE_FROZEN_NESTED_HU_LOAD_REQUIRED');end if;
 for i in 0..nodes.get_size-1 loop
 x:=treat(nodes.get(i)as json_object_t);
 if x.get_string('kind')='CONTAINER'then
 v_uid:=x.get_string('uid');select *into pp from RRL_PALLETS where UID_PALLET=v_uid;
 if pp.HU_KIND!='CONTAINER'or pp.HU_SHIPPED_OPERATION!=p_load or pp.HU_CURRENT_CELL is not null or pp.HU_CONTENT_VERSION!=x.get_number('version')+1 then raise_application_error(-20886,'INTERWARE_NESTED_CONTAINER_EPOCH_CHANGED');end if;
 select count(*)into n from RRL_TARE_BOOK where PLACE_KIND='HU'and PLACE_ID=pp.UID_PALLET and STATUS='HELD';
 if n!=0 then raise_application_error(-20886,'INTERWARE_NESTED_RETAINED_TARE_CUSTODY_REQUIRED');end if;
 item:=json_object_t();item.put('uid',pp.UID_PALLET);item.put('version',pp.HU_CONTENT_VERSION);item.put('type',pp.HU_TYPE);item.put('tare',RRL_STOCK_PLAN_HELPER.decimal_text(pp.HU_TARE_WEIGHT_KG));containers.append(item);
 end if;
 end loop;
 links:=tree.get_array('links');
 if links.get_size!=nodes.get_size-1 then raise_application_error(-20886,'INTERWARE_NESTED_COMPLETE_TREE_REQUIRED');end if;
 for i in 0..links.get_size-1 loop
 x:=treat(links.get(i)as json_object_t);
 v_link_id:=x.get_number('id');select *into old_link from RRL_WMS_HU_LINK where HU_LINK_ID=v_link_id;
 if old_link.ACTIVE_FLAG!=0 or old_link.UNLINKED_OPERATION_ID!=p_load or old_link.PARENT_UID!=x.get_string('parent')or old_link.CHILD_PALLET_UID!=x.get_string('child')or old_link.CHILD_CASE_TASK_ID is not null or old_link.LINK_VERSION!=x.get_number('version')+1 then raise_application_error(-20886,'INTERWARE_NESTED_FROZEN_LINK_CHANGED');end if;
 item:=x.clone();item.put('version',old_link.LINK_VERSION);context_links.append(item);
 end loop;
 result_value.put('source_load_operation_id',p_load);result_value.put('place_uid',lf.ROOT_UID);result_value.put('stock_uid',leaf_uid);result_value.put('containers',containers);result_value.put('links',context_links);
 return result_value.to_clob;
 end;
 procedure capture_context(p_load varchar2,p_actor varchar2,p_context out clob)is
 wire clob;value json_object_t;links json_array_t;x json_object_t;new_id number;
 begin
 RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
 RRL_INTERWARE_UNIT_SOURCE.assert_scope(p_load,p_actor);
 wire:=context_json(p_load);if wire is null then p_context:=null;return;end if;
 value:=json_object_t.parse(wire);links:=value.get_array('links');
 for i in 0..links.get_size-1 loop x:=treat(links.get(i)as json_object_t);select RRL_WMS_HU_LINK_SQ.nextval into new_id from dual;x.put('new_id',new_id);links.put(i,x,true);end loop;
 value.put('links',links);p_context:=value.to_clob;
 end;
 procedure assert_context(p_load varchar2,p_context clob)is
 actual clob:=context_json(p_load);value json_object_t;links json_array_t;x json_object_t;new_id number;n number;
 type id_map is table of number index by varchar2(80);seen id_map;key_value varchar2(80);
 begin
 if actual is null and p_context is null then return;end if;
 if actual is null or p_context is null then raise_application_error(-20886,'INTERWARE_NESTED_CONTEXT_REQUIRED');end if;
 value:=json_object_t.parse(p_context);links:=value.get_array('links');
 for i in 0..links.get_size-1 loop
 x:=treat(links.get(i)as json_object_t);new_id:=x.get_number('new_id');
 if new_id is null or new_id<1 or new_id!=trunc(new_id)then raise_application_error(-20886,'INTERWARE_NESTED_RESERVED_LINK_ID_REQUIRED');end if;
 key_value:=RRL_STOCK_PLAN_HELPER.decimal_text(new_id);
 if seen.exists(key_value)then raise_application_error(-20886,'INTERWARE_NESTED_DUPLICATE_NEW_LINK');end if;seen(key_value):=1;
 select count(*)into n from RRL_WMS_HU_LINK where HU_LINK_ID=new_id;if n!=0 then raise_application_error(-20886,'INTERWARE_NESTED_LINK_ID_ALREADY_USED');end if;
 x.remove('new_id');links.put(i,x,true);
 end loop;
 value.put('links',links);
 if dbms_lob.compare(actual,value.to_clob)!=0 then raise_application_error(-20886,'INTERWARE_NESTED_FROZEN_CONTEXT_CHANGED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_IW_SHORTAGE_GUARD as
 procedure require_command(p_operation varchar2,p_kind varchar2)is n number;begin
 if p_operation is null or p_operation!=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null
 or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)then raise_application_error(-20863,'INTERWARE_SHORTAGE_NATIVE_TRANSACTION_REQUIRED');end if;
 select count(*)into n from RRL_STOCK_OPERATION where OPERATION_ID=p_operation and STATE='IN_FLIGHT'and COMMAND_TYPE=p_kind;
 if n!=1 then raise_application_error(-20863,'INTERWARE_SHORTAGE_CAPTURED_COMMAND_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_MES_PRODUCTION_API as

  function next_line_no(p_production_order_id number) return number is

    v_line_no number;

  begin

    select nvl(max(LINE_NO), 0) + 10

      into v_line_no

      from RRL_PROD_ORDER_BOM_LINE

     where PRODUCTION_ORDER_ID = p_production_order_id;

    return v_line_no;

  end;



  function create_order(

    p_order_no           varchar2,

    p_bom_id             number default null,

    p_target_articul     varchar2,

    p_planned_qty        number,

    p_unit_code          varchar2 default 'KG',

    p_ware_id            number default null,

    p_production_line    varchar2 default null,

    p_shift_id           varchar2 default null,

    p_planned_start_at   date default null,

    p_planned_finish_at  date default null,

    p_source_system      varchar2 default null,

    p_source_message_id  varchar2 default null,

    p_idempotency_key    varchar2 default null,

    p_comment_text       varchar2 default null,

    p_created_by         varchar2 default null

  ) return number is

    v_id number;

    v_bom_id number;

    v_bom RRL_BOM%rowtype;

    v_factor number;

  begin

    if p_idempotency_key is not null then

      begin

        select PRODUCTION_ORDER_ID into v_id

          from RRL_PRODUCTION_ORDER

         where IDEMPOTENCY_KEY = p_idempotency_key;

        return v_id;

      exception

        when no_data_found then null;

      end;

    end if;



    begin

      select PRODUCTION_ORDER_ID into v_id

        from RRL_PRODUCTION_ORDER

       where ORDER_NO = p_order_no;

      return v_id;

    exception

      when no_data_found then null;

    end;



    if p_planned_qty is null or p_planned_qty <= 0 then

      raise_application_error(-20900, 'planned quantity must be greater than zero');

    end if;



    v_bom_id := p_bom_id;

    if v_bom_id is null then

      v_bom_id := RRL_BOM_API.find_primary_bom(

        p_target_articul => p_target_articul,

        p_planned_date => nvl(p_planned_start_at, trunc(sysdate)),

        p_ware_id => p_ware_id,

        p_production_line => p_production_line

      );

    end if;



    if v_bom_id is null then

      raise_application_error(-20901, 'approved primary BOM not found');

    end if;



    select * into v_bom

      from RRL_BOM

     where BOM_ID = v_bom_id

       and STATUS in ('APPROVED', 'ACTIVE');



    if upper(v_bom.TARGET_ARTICUL) <> upper(substr(p_target_articul, 1, 40)) then

      raise_application_error(-20902, 'BOM target articul does not match production order target');

    end if;



    select RRL_PRODUCTION_ORDER_SQ.nextval into v_id from dual;



    insert into RRL_PRODUCTION_ORDER (

      PRODUCTION_ORDER_ID, ORDER_NO, BOM_ID, TARGET_ARTICUL, TARGET_MOD_ID,

      TARGET_GTIN, PLANNED_QTY, UNIT_CODE, WARE_ID, PRODUCTION_LINE, SHIFT_ID,

      STATUS, PLANNED_START_AT, PLANNED_FINISH_AT, IDEMPOTENCY_KEY,

      SOURCE_SYSTEM, SOURCE_MESSAGE_ID, COMMENT_TEXT, CREATED_AT, CREATED_BY

    ) values (

      v_id, substr(p_order_no, 1, 100), v_bom_id, upper(substr(p_target_articul, 1, 40)),

      v_bom.TARGET_MOD_ID, v_bom.TARGET_GTIN, p_planned_qty, upper(substr(nvl(p_unit_code, v_bom.BASE_UNIT_CODE), 1, 20)),

      p_ware_id, substr(p_production_line, 1, 100), substr(p_shift_id, 1, 50),

      'RELEASED', p_planned_start_at, p_planned_finish_at, substr(p_idempotency_key, 1, 100),

      substr(p_source_system, 1, 50), substr(p_source_message_id, 1, 100),

      substr(p_comment_text, 1, 1000), sysdate, substr(p_created_by, 1, 50)

    );



    v_factor := p_planned_qty / v_bom.BASE_QTY;



    insert into RRL_PROD_ORDER_BOM_LINE (

      ORDER_LINE_ID, PRODUCTION_ORDER_ID, BOM_ID, BOM_LINE_ID, LINE_NO,

      COMPONENT_TYPE, COMPONENT_ARTICUL, COMPONENT_MOD_ID, COMPONENT_NAME,

      PLANNED_QTY, UNIT_CODE, LOSS_PERCENT, IS_REQUIRED, CREATED_AT, CREATED_BY

    )

    select RRL_PROD_ORDER_BOM_LINE_SQ.nextval,

           v_id,

           v_bom_id,

           l.BOM_LINE_ID,

           l.LINE_NO,

           l.COMPONENT_TYPE,

           upper(substr(l.COMPONENT_ARTICUL, 1, 40)),

           l.COMPONENT_MOD_ID,

           l.COMPONENT_NAME,

           round(nvl(l.QTY_PER_BASE, 0) * v_factor * (1 + nvl(l.LOSS_PERCENT, 0) / 100), 6),

           nvl(l.UNIT_CODE, v_bom.BASE_UNIT_CODE),

           nvl(l.LOSS_PERCENT, 0),

           nvl(l.IS_REQUIRED, 1),

           sysdate,

           substr(p_created_by, 1, 50)

      from RRL_BOM_LINE l

     where l.BOM_ID = v_bom_id;



    return v_id;

  end create_order;



  function issue_raw_to_production(

    p_production_order_id number,

    p_uid_pallet          varchar2 default null,

    p_raw_batch_id        number default null,

    p_raw_articul         varchar2 default null,

    p_quantity            number,

    p_unit_code           varchar2 default 'KG',

    p_source_location     varchar2 default null,

    p_production_location varchar2 default 'MES_PRODUCTION',

    p_created_by          varchar2 default null

  ) return number is

    v_id number;

    v_order RRL_PRODUCTION_ORDER%rowtype;

    v_raw_articul varchar2(40);

  begin

    if p_quantity is null or p_quantity <= 0 then

      raise_application_error(-20910, 'issue quantity must be greater than zero');

    end if;



    select * into v_order

      from RRL_PRODUCTION_ORDER

     where PRODUCTION_ORDER_ID = p_production_order_id

       for update;



    if v_order.STATUS in ('COMPLETED', 'CANCELLED') then

      raise_application_error(-20911, 'production order is already closed');

    end if;



    v_raw_articul := upper(substr(p_raw_articul, 1, 40));

    if v_raw_articul is null and p_raw_batch_id is not null then

      select upper(substr(ARTICUL, 1, 40))

        into v_raw_articul

        from RRL_RAW_BATCH

       where RAW_BATCH_ID = p_raw_batch_id;

    end if;



    select RRL_MES_MOVEMENT_SQ.nextval into v_id from dual;



    insert into RRL_MES_MOVEMENT (

      MOVEMENT_ID, MOVEMENT_TYPE, PRODUCTION_ORDER_ID, BOM_ID, RAW_BATCH_ID,

      RAW_ARTICUL, UID_PALLET, QUANTITY, UNIT_CODE, SOURCE_LOCATION, TARGET_LOCATION,

      STATUS, CREATED_AT, CREATED_BY

    ) values (

      v_id, 'RAW_ISSUE_TO_PRODUCTION', p_production_order_id, v_order.BOM_ID, p_raw_batch_id,

      v_raw_articul, substr(p_uid_pallet, 1, 200), p_quantity, upper(substr(p_unit_code, 1, 20)),

      substr(p_source_location, 1, 100), substr(p_production_location, 1, 100),

      'MES_POSTED', sysdate, substr(p_created_by, 1, 50)

    );



    update RRL_PRODUCTION_ORDER

       set STATUS = 'IN_PROGRESS',

           STARTED_AT = nvl(STARTED_AT, sysdate),

           UPDATED_AT = sysdate,

           UPDATED_BY = substr(p_created_by, 1, 50)

     where PRODUCTION_ORDER_ID = p_production_order_id

       and STATUS in ('DRAFT', 'RELEASED');



    return v_id;

  end issue_raw_to_production;



  function complete_order(

    p_production_order_id number,

    p_prod_batch_no       varchar2 default null,

    p_fact_qty            number,

    p_unit_code           varchar2 default 'KG',

    p_pallets_json        clob default null,

    p_idempotency_key     varchar2 default null,

    p_created_by          varchar2 default null

  ) return number is

    v_completion_id number;

    v_order RRL_PRODUCTION_ORDER%rowtype;

    v_prod_batch_id number;

    v_prod_batch_no varchar2(100);

    v_consumption_count number;

    v_trace_event_id number;

    v_dummy number;

  begin

    if p_idempotency_key is not null then

      begin

        select COMPLETION_ID into v_completion_id

          from RRL_MES_COMPLETION

         where IDEMPOTENCY_KEY = p_idempotency_key;

        return v_completion_id;

      exception

        when no_data_found then null;

      end;

    end if;



    if p_fact_qty is null or p_fact_qty <= 0 then

      raise_application_error(-20920, 'fact quantity must be greater than zero');

    end if;



    select * into v_order

      from RRL_PRODUCTION_ORDER

     where PRODUCTION_ORDER_ID = p_production_order_id

       for update;



    if v_order.STATUS in ('COMPLETED', 'CANCELLED') then

      raise_application_error(-20921, 'production order is already closed');

    end if;



    v_prod_batch_no := substr(nvl(p_prod_batch_no, v_order.ORDER_NO || '-LOT'), 1, 100);



    v_prod_batch_id := RRL_PRODUCTION_API.create_prod_batch(

      p_prod_batch_no => v_prod_batch_no,

      p_articul => v_order.TARGET_ARTICUL,

      p_mod_id => v_order.TARGET_MOD_ID,

      p_gtin => v_order.TARGET_GTIN,

      p_total_quantity => p_fact_qty,

      p_unit_code => nvl(p_unit_code, v_order.UNIT_CODE),

      p_ware_id => v_order.WARE_ID,

      p_source_system => 'MES',

      p_source_message_id => substr(nvl(p_idempotency_key, v_order.ORDER_NO || ':COMPLETE'), 1, 100),

      p_production_order_id => v_order.PRODUCTION_ORDER_ID,

      p_produced_date_from => trunc(sysdate),

      p_produced_date_to => trunc(sysdate),

      p_production_line => v_order.PRODUCTION_LINE,

      p_shift_id => v_order.SHIFT_ID,

      p_created_by => p_created_by

    );



    select count(*)

      into v_consumption_count

      from RRL_MES_MOVEMENT

     where PRODUCTION_ORDER_ID = p_production_order_id

       and MOVEMENT_TYPE = 'RAW_ISSUE_TO_PRODUCTION'

       and STATUS <> 'CANCELLED';



    if v_consumption_count > 0 then

      for r in (

        select RAW_BATCH_ID,

               RAW_ARTICUL,

               UID_PALLET,

               TARGET_LOCATION PRODUCTION_LOCATION,

               sum(QUANTITY) QUANTITY,

               max(UNIT_CODE) UNIT_CODE

          from RRL_MES_MOVEMENT

         where PRODUCTION_ORDER_ID = p_production_order_id

           and MOVEMENT_TYPE = 'RAW_ISSUE_TO_PRODUCTION'

           and STATUS <> 'CANCELLED'

         group by RAW_BATCH_ID, RAW_ARTICUL, UID_PALLET, TARGET_LOCATION

      ) loop

        v_dummy := RRL_PRODUCTION_API.add_raw_usage(

          p_prod_batch_id => v_prod_batch_id,

          p_raw_batch_id => r.RAW_BATCH_ID,

          p_raw_articul => r.RAW_ARTICUL,

          p_quantity_planned => r.QUANTITY,

          p_quantity_fact => r.QUANTITY,

          p_unit_code => r.UNIT_CODE,

          p_used_by => p_created_by

        );



        select RRL_MES_MOVEMENT_SQ.nextval into v_dummy from dual;

        insert into RRL_MES_MOVEMENT (

          MOVEMENT_ID, MOVEMENT_TYPE, PRODUCTION_ORDER_ID, PROD_BATCH_ID, BOM_ID,

          RAW_BATCH_ID, RAW_ARTICUL, UID_PALLET, QUANTITY, UNIT_CODE, SOURCE_LOCATION, TARGET_LOCATION,

          STATUS, CREATED_AT, CREATED_BY

        ) values (

          v_dummy, 'RAW_CONSUMPTION', p_production_order_id, v_prod_batch_id, v_order.BOM_ID,

          r.RAW_BATCH_ID, r.RAW_ARTICUL, r.UID_PALLET, r.QUANTITY, r.UNIT_CODE, nvl(r.PRODUCTION_LOCATION, 'MES_PROD'),

          'MES_FINISHED_GOODS', 'MES_POSTED', sysdate, substr(p_created_by, 1, 50)

        );

      end loop;

    else

      for r in (

        select BOM_LINE_ID, COMPONENT_ARTICUL, PLANNED_QTY, UNIT_CODE

          from RRL_PROD_ORDER_BOM_LINE

         where PRODUCTION_ORDER_ID = p_production_order_id

           and COMPONENT_TYPE in ('RAW', 'SEMIFINISHED', 'PACKAGING', 'ADDITIVE')

      ) loop

        v_dummy := RRL_PRODUCTION_API.add_raw_usage(

          p_prod_batch_id => v_prod_batch_id,

          p_raw_batch_id => null,

          p_raw_articul => r.COMPONENT_ARTICUL,

          p_quantity_planned => r.PLANNED_QTY,

          p_quantity_fact => round(r.PLANNED_QTY * p_fact_qty / v_order.PLANNED_QTY, 6),

          p_unit_code => r.UNIT_CODE,

          p_used_by => p_created_by

        );



        select RRL_MES_MOVEMENT_SQ.nextval into v_dummy from dual;

        insert into RRL_MES_MOVEMENT (

          MOVEMENT_ID, MOVEMENT_TYPE, PRODUCTION_ORDER_ID, PROD_BATCH_ID, BOM_ID,

          BOM_LINE_ID, RAW_ARTICUL, QUANTITY, UNIT_CODE, SOURCE_LOCATION, TARGET_LOCATION,

          STATUS, CREATED_AT, CREATED_BY

        ) values (

          v_dummy, 'RAW_CONSUMPTION', p_production_order_id, v_prod_batch_id, v_order.BOM_ID,

          r.BOM_LINE_ID, r.COMPONENT_ARTICUL, round(r.PLANNED_QTY * p_fact_qty / v_order.PLANNED_QTY, 6),

          r.UNIT_CODE, 'MES_PRODUCTION', 'MES_FINISHED_GOODS', 'MES_POSTED', sysdate,

          substr(p_created_by, 1, 50)

        );

      end loop;

    end if;



    select RRL_MES_MOVEMENT_SQ.nextval into v_dummy from dual;

    insert into RRL_MES_MOVEMENT (

      MOVEMENT_ID, MOVEMENT_TYPE, PRODUCTION_ORDER_ID, PROD_BATCH_ID, BOM_ID,

      QUANTITY, UNIT_CODE, SOURCE_LOCATION, TARGET_LOCATION, STATUS, CREATED_AT, CREATED_BY

    ) values (

      v_dummy, 'FG_LOT_RELEASE', p_production_order_id, v_prod_batch_id, v_order.BOM_ID,

      p_fact_qty, nvl(p_unit_code, v_order.UNIT_CODE), 'MES_PRODUCTION', 'MES_FINISHED_GOODS',

      'MES_POSTED', sysdate, substr(p_created_by, 1, 50)

    );



    if p_pallets_json is not null then

      for p in (

        select uid_pallet, pallet_no, quantity, pack_count, sscc

          from json_table(

            p_pallets_json,

            '$[*]' columns (

              uid_pallet varchar2(200) path '$.uid_pallet',

              pallet_no number path '$.pallet_no',

              quantity number path '$.quantity',

              pack_count number path '$.pack_count',

              sscc varchar2(50) path '$.sscc'

            )

          )

      ) loop

        if p.uid_pallet is null then

          raise_application_error(-20922, 'pallet uid is required');

        end if;



        merge into RRL_PROD_BATCH_PALLETS d

        using (

          select v_prod_batch_id PROD_BATCH_ID,

                 p.uid_pallet UID_PALLET

            from dual

        ) s

        on (d.PROD_BATCH_ID = s.PROD_BATCH_ID and d.UID_PALLET = s.UID_PALLET)

        when matched then update set

          d.PALLET_NO = nvl(p.pallet_no, d.PALLET_NO),

          d.QUANTITY = nvl(p.quantity, d.QUANTITY),

          d.PACK_COUNT = nvl(p.pack_count, d.PACK_COUNT),

          d.SSCC = nvl(p.sscc, d.SSCC)

        when not matched then insert (

          PROD_BATCH_ID, UID_PALLET, PALLET_NO, QUANTITY, PACK_COUNT,

          SSCC, AGGREGATION_STATUS, CREATED_AT, CREATED_BY

        ) values (

          v_prod_batch_id, p.uid_pallet, p.pallet_no, p.quantity, p.pack_count,

          p.sscc, 'DRAFT', sysdate, p_created_by

        );



        select RRL_MES_MOVEMENT_SQ.nextval into v_dummy from dual;

        insert into RRL_MES_MOVEMENT (

          MOVEMENT_ID, MOVEMENT_TYPE, PRODUCTION_ORDER_ID, PROD_BATCH_ID, BOM_ID,

          UID_PALLET, SSCC, QUANTITY, PACK_COUNT, UNIT_CODE, SOURCE_LOCATION,

          TARGET_LOCATION, STATUS, PAYLOAD_JSON, CREATED_AT, CREATED_BY

        ) values (

          v_dummy, 'FG_PALLET_RELEASE', p_production_order_id, v_prod_batch_id, v_order.BOM_ID,

          substr(p.uid_pallet, 1, 200), substr(p.sscc, 1, 50), p.quantity, p.pack_count,

          nvl(p_unit_code, v_order.UNIT_CODE), 'MES_PRODUCTION', 'MES_FG',

          'MES_POSTED',

          '{"uid_pallet":"' || replace(substr(p.uid_pallet, 1, 200), '"', '\"') || '"}',

          sysdate, substr(p_created_by, 1, 50)

        );

      end loop;

    end if;



    select RRL_MES_COMPLETION_SQ.nextval into v_completion_id from dual;

    insert into RRL_MES_COMPLETION (

      COMPLETION_ID, PRODUCTION_ORDER_ID, PROD_BATCH_ID, IDEMPOTENCY_KEY,

      STATUS, PAYLOAD_JSON, CREATED_AT, CREATED_BY

    ) values (

      v_completion_id, p_production_order_id, v_prod_batch_id,

      substr(p_idempotency_key, 1, 100), 'DONE', p_pallets_json, sysdate,

      substr(p_created_by, 1, 50)

    );



    update RRL_PRODUCTION_ORDER

       set STATUS = 'COMPLETED',

           FACT_QTY = p_fact_qty,

           COMPLETED_AT = sysdate,

           PROD_BATCH_ID = v_prod_batch_id,

           UPDATED_AT = sysdate,

           UPDATED_BY = substr(p_created_by, 1, 50)

     where PRODUCTION_ORDER_ID = p_production_order_id;



    update RRL_PROD_BATCH

       set QUALITY_STATUS = 'RELEASED',

           UPDATED_AT = sysdate,

           UPDATED_BY = substr(p_created_by, 1, 50)

     where PROD_BATCH_ID = v_prod_batch_id;



    v_trace_event_id := RRL_TRACEABILITY_API.add_trace_event(

      p_event_type => 'PRODUCTION_COMPLETED',

      p_entity_type => 'PRODUCTION_ORDER',

      p_entity_id => to_char(p_production_order_id),

      p_source_system => 'MES',

      p_correlation_id => v_order.ORDER_NO,

      p_idempotency_key => substr(nvl(p_idempotency_key, v_order.ORDER_NO || ':TRACE'), 1, 100),

      p_payload_json => p_pallets_json,

      p_created_by => p_created_by

    );



    v_dummy := RRL_TRACEABILITY_API.add_trace_edge(

      p_from_entity_type => 'PRODUCTION_ORDER',

      p_from_entity_id => to_char(p_production_order_id),

      p_to_entity_type => 'FINISHED_GOODS_LOT',

      p_to_entity_id => to_char(v_prod_batch_id),

      p_edge_type => 'PRODUCES',

      p_quantity => p_fact_qty,

      p_unit_code => nvl(p_unit_code, v_order.UNIT_CODE),

      p_trace_event_id => v_trace_event_id,

      p_created_by => p_created_by

    );



    v_dummy := RRL_TRACEABILITY_API.enqueue_event(

      p_event_type => 'PRODUCTION_COMPLETED',

      p_aggregate_type => 'PRODUCTION_ORDER',

      p_aggregate_id => to_char(p_production_order_id),

      p_idempotency_key => substr(nvl(p_idempotency_key, v_order.ORDER_NO || ':OUTBOX'), 1, 100),

      p_payload_json => p_pallets_json,

      p_target_system => 'TRACEABILITY',

      p_correlation_id => v_order.ORDER_NO

    );



    return v_completion_id;

  end complete_order;



  procedure apply_mes_movements_to_wms(

    p_production_order_id number,

    p_applied_by          varchar2 default null

  ) is

    v_event_id number;

    v_error varchar2(4000);v_release varchar2(20);v_operation varchar2(100);v_result clob;
    v_request json_object_t:=json_object_t();v_source json_object_t:=json_object_t();v_ids json_array_t:=json_array_t();

  begin
    select STATE into v_release from RRL_STOCK_RELEASE where RELEASE_ID=1;
    if v_release!='PREPARED' then
      for pending in(select MOVEMENT_ID from RRL_MES_MOVEMENT
        where PRODUCTION_ORDER_ID=p_production_order_id and STATUS in('MES_POSTED','ERROR')
          and MOVEMENT_TYPE in('RAW_ISSUE_TO_PRODUCTION','RAW_CONSUMPTION','FG_PALLET_RELEASE')
        order by MOVEMENT_ID fetch first 201 rows only) loop
        if v_ids.get_size>=200 then raise_application_error(-20881,'MES_MOVEMENT_BATCH_BOUND');end if;
        v_ids.append(pending.MOVEMENT_ID);
      end loop;
      if v_ids.get_size=0 then return;end if;
      v_operation:='MES.NATIVE:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_production_order_id)||':'||
        rawtohex(sys.dbms_crypto.hash(v_ids.to_clob,sys.dbms_crypto.hash_sh256));
      v_request.put('contract_version',2);v_request.put('operation_id',v_operation);
      v_request.put('command_type','MES_MOVEMENTS');v_request.put('actor',p_applied_by);
      v_request.put('lines',json_array_t());v_request.put('units',json_array_t());
      v_source.put('type','PRODUCTION_ORDER');v_source.put('production_order_id',p_production_order_id);v_source.put('movement_ids',v_ids);
      v_request.put('source',v_source);v_request.put('metadata',json_object_t());
      RRL_STOCK_NATIVE_API.post(v_request.to_clob,p_applied_by,v_result);
      return;
    end if;

    for m in (

      select *

        from RRL_MES_MOVEMENT

       where PRODUCTION_ORDER_ID = p_production_order_id

         and STATUS in ('MES_POSTED', 'ERROR')

         and MOVEMENT_TYPE in ('RAW_ISSUE_TO_PRODUCTION', 'RAW_CONSUMPTION', 'FG_PALLET_RELEASE')

       order by MOVEMENT_ID

    ) loop

      begin

        if m.UID_PALLET is null then

          raise_application_error(-20940, 'legacy WMS event requires UID_PALLET');

        end if;



        if m.MOVEMENT_TYPE = 'FG_PALLET_RELEASE' then

          merge into RRL_PALLETS d

          using (

            select m.UID_PALLET UID_PALLET,

                   o.TARGET_ARTICUL ARTICUL,

                   m.QUANTITY UNIT_COUNT,

                   m.PROD_BATCH_ID PROD_BATCH_ID,

                   m.SSCC SSCC

              from RRL_PRODUCTION_ORDER o

             where o.PRODUCTION_ORDER_ID = p_production_order_id

          ) s

          on (d.UID_PALLET = s.UID_PALLET)

          when matched then update set

            d.ARTICUL = nvl(s.ARTICUL, d.ARTICUL),

            d.UNIT_COUNT = nvl(s.UNIT_COUNT, d.UNIT_COUNT),

            d.PROD_BATCH_ID = nvl(s.PROD_BATCH_ID, d.PROD_BATCH_ID),

            d.SSCC = nvl(s.SSCC, d.SSCC),

            d.QUALITY_STATUS = 'RELEASED'

          when not matched then insert (

            UID_PALLET, ARTICUL, UNIT_COUNT, PRIHOD_NAKLAD_ID,

            PROD_BATCH_ID, SSCC, QUALITY_STATUS

          ) values (

            s.UID_PALLET, s.ARTICUL, s.UNIT_COUNT, 0,

            s.PROD_BATCH_ID, s.SSCC, 'RELEASED'

          );

        end if;



        select RRL_EVENT_ID_SQ.nextval into v_event_id from dual;



        if m.MOVEMENT_TYPE = 'RAW_ISSUE_TO_PRODUCTION' then

          insert into RRL_EVENTS (

            ID_EVENT, CELL_FROM, CELL_TO, DATE_EVENT, COUNT_EVENT,

            TYPE_EVENT, UID_POLETA, USER_ID

          ) values (

            v_event_id, substr(nvl(m.SOURCE_LOCATION, 'UNKNOWN'), 1, 20),

            substr(nvl(m.TARGET_LOCATION, 'MES_PROD'), 1, 20), sysdate,

            nvl(m.QUANTITY, 0), 2, substr(m.UID_PALLET, 1, 200),

            substr(nvl(p_applied_by, user), 1, 50)

          );

        elsif m.MOVEMENT_TYPE = 'RAW_CONSUMPTION' then

          insert into RRL_EVENTS (

            ID_EVENT, CELL_FROM, CELL_TO, DATE_EVENT, COUNT_EVENT,

            TYPE_EVENT, UID_POLETA, USER_ID

          ) values (

            v_event_id, substr(nvl(m.SOURCE_LOCATION, 'MES_PROD'), 1, 20),

            'none', sysdate, nvl(m.QUANTITY, 0), 3, substr(m.UID_PALLET, 1, 200),

            substr(nvl(p_applied_by, user), 1, 50)

          );

        elsif m.MOVEMENT_TYPE = 'FG_PALLET_RELEASE' then

          insert into RRL_EVENTS (

            ID_EVENT, CELL_FROM, CELL_TO, DATE_EVENT, COUNT_EVENT,

            TYPE_EVENT, UID_POLETA, USER_ID

          ) values (

            v_event_id, substr(nvl(m.SOURCE_LOCATION, 'MES_PROD'), 1, 20),

            substr(nvl(m.TARGET_LOCATION, 'MES_FG'), 1, 20), sysdate,

            nvl(m.QUANTITY, 0), 1, substr(m.UID_PALLET, 1, 200),

            substr(nvl(p_applied_by, user), 1, 50)

          );

        else

          raise_application_error(-20941, 'movement type is not supported by legacy WMS bridge');

        end if;



        update RRL_MES_MOVEMENT

           set STATUS = 'APPLIED_TO_WMS',

               WMS_APPLIED_AT = sysdate,

               WMS_APPLIED_BY = substr(p_applied_by, 1, 50),

               LAST_ERROR = null,

               UPDATED_AT = sysdate,

               UPDATED_BY = substr(p_applied_by, 1, 50)

         where MOVEMENT_ID = m.MOVEMENT_ID;

      exception

        when others then

          v_error := sqlerrm;

          update RRL_MES_MOVEMENT

             set STATUS = 'ERROR',

                 RETRY_COUNT = RETRY_COUNT + 1,

                 LAST_ERROR = substr(v_error, 1, 4000),

                 UPDATED_AT = sysdate,

                 UPDATED_BY = substr(p_applied_by, 1, 50)

           where MOVEMENT_ID = m.MOVEMENT_ID;

      end;

    end loop;

  end apply_mes_movements_to_wms;



  procedure retry_mes_movement(

    p_movement_id number,

    p_updated_by  varchar2 default null

  ) is

  begin

    update RRL_MES_MOVEMENT

       set STATUS = 'MES_POSTED',

           LAST_ERROR = null,

           UPDATED_AT = sysdate,

           UPDATED_BY = substr(p_updated_by, 1, 50)

     where MOVEMENT_ID = p_movement_id

       and STATUS = 'ERROR';



    if sql%rowcount = 0 then

      raise_application_error(-20930, 'MES movement is not in ERROR status');

    end if;

  end retry_mes_movement;

end RRL_MES_PRODUCTION_API;
/


CREATE OR REPLACE package body RRL_MES_RAW_SUPPLY_API as
 function release_to_production(p_production_order_id number,p_to_ware_id number default null,
  p_to_cell varchar2 default 'MES_PROD',p_allow_partial number default 0,p_created_by varchar2 default null,p_operation_id varchar2 default null) return number is
  state varchar2(20);d json_object_t:=json_object_t();s json_object_t:=json_object_t();m json_object_t:=json_object_t();result clob;
 begin
  select STATE into state from RRL_STOCK_RELEASE where RELEASE_ID=1;
  if state='PREPARED' then return RRL_MES_RAW_SUPPLY_OLD.release_to_production(p_production_order_id,p_to_ware_id,p_to_cell,p_allow_partial,p_created_by);end if;
  if p_operation_id is null then raise_application_error(-20871,'OPERATION_ID_REQUIRED: MES release');end if;
  d.put('contract_version',2);d.put('operation_id',p_operation_id);d.put('command_type','MES_RELEASE_TO_PRODUCTION');d.put('actor',p_created_by);
  d.put('lines',json_array_t());d.put('units',json_array_t());s.put('production_order_id',p_production_order_id);d.put('source',s);
  m.put('to_cell',p_to_cell);m.put('to_ware_id',p_to_ware_id);m.put('allow_partial',p_allow_partial);d.put('metadata',m);
  RRL_STOCK_NATIVE_API.post(d.to_clob,p_created_by,result);
  return json_object_t.parse(result).get_number('task_count');
 end;
end;
/


CREATE OR REPLACE package body RRL_MES_RAW_SUPPLY_OLD as

  function issued_raw_qty(

    p_production_order_id number,

    p_bom_line_id         number,

    p_raw_articul         varchar2

  ) return number is

    v_qty number;

  begin

    select nvl(sum(nvl(QUANTITY, 0)), 0)

      into v_qty

      from RRL_MES_MOVEMENT

     where PRODUCTION_ORDER_ID = p_production_order_id

       and MOVEMENT_TYPE = 'RAW_ISSUE_TO_PRODUCTION'

       and STATUS <> 'CANCELLED'

       and (

            (BOM_LINE_ID is not null and BOM_LINE_ID = p_bom_line_id)

            or (BOM_LINE_ID is null and upper(RAW_ARTICUL) = upper(p_raw_articul))

       );

    return nvl(v_qty, 0);

  end issued_raw_qty;



  function release_to_production(

    p_production_order_id number,

    p_to_ware_id          number default null,

    p_to_cell             varchar2 default 'MES_PROD',

    p_allow_partial       number default 0,

    p_created_by          varchar2 default null

  ) return number is

    v_release varchar2(20);
    v_status varchar2(30);

    v_existing_tasks number;

    v_demand_id number;

    v_soft_reservation_id number;

    v_candidate_id number;

    v_shortage_id number;

    v_reservation_id number;

    v_task_id number;

    v_required_qty number;

    v_issued_qty number;

    v_open_qty number;

    v_available_qty number;

    v_available_total number;

    v_remaining_qty number;

    v_suggested_qty number;

    v_shortage_count number := 0;

    v_task_count number := 0;

    v_sort_order number;

    v_reservation_scope varchar2(20);

    v_actor varchar2(100) := substr(nvl(p_created_by, 'API'), 1, 100);

    v_to_cell varchar2(80) := substr(nvl(p_to_cell, 'MES_PROD'), 1, 80);

  begin

    select STATE into v_release from RRL_STOCK_RELEASE where RELEASE_ID=1;
    if v_release!='PREPARED' then raise_application_error(-20863,'LEGACY_STOCK_WRITER_RETIRED');end if;
    if p_production_order_id is null then

      raise_application_error(-20950, 'production order id is required');

    end if;



    select STATUS

      into v_status

      from RRL_PRODUCTION_ORDER

     where PRODUCTION_ORDER_ID = p_production_order_id

     for update;



    if v_status in ('COMPLETED', 'CANCELLED') then

      raise_application_error(-20951, 'completed/cancelled production order cannot be released');

    end if;



    select count(*)

      into v_existing_tasks

      from RRL_MES_RAW_TRANSFER_TASK

     where PRODUCTION_ORDER_ID = p_production_order_id

       and TASK_STATUS in ('PLANNED', 'IN_PROGRESS');



    if v_existing_tasks > 0 then

      return v_existing_tasks;

    end if;



    update RRL_STOCK_RESERVATION

       set STATUS = 'CANCELLED',

           RELEASED_AT = systimestamp,

           RELEASED_BY = v_actor,

           RELEASE_REASON = 'MES raw supply recalculation'

     where RESERVATION_DOMAIN = 'MES_RAW'

       and PRODUCTION_ORDER_ID = p_production_order_id

       and RESERVATION_KIND = 'SOFT'

       and STATUS = 'ACTIVE';



    delete from RRL_MES_RAW_SUPPLY_CANDIDATE

     where PRODUCTION_ORDER_ID = p_production_order_id;

    delete from RRL_MES_RAW_SHORTAGE

     where PRODUCTION_ORDER_ID = p_production_order_id;

    delete from RRL_MES_RAW_DEMAND

     where PRODUCTION_ORDER_ID = p_production_order_id;



    for line in (

      select ORDER_LINE_ID, PRODUCTION_ORDER_ID, BOM_ID, BOM_LINE_ID, LINE_NO,

             COMPONENT_TYPE, upper(COMPONENT_ARTICUL) COMPONENT_ARTICUL,

             COMPONENT_NAME, PLANNED_QTY, UNIT_CODE

        from RRL_PROD_ORDER_BOM_LINE

       where PRODUCTION_ORDER_ID = p_production_order_id

         and COMPONENT_ARTICUL is not null

       order by LINE_NO, ORDER_LINE_ID

    ) loop

      v_required_qty := nvl(line.PLANNED_QTY, 0);

      v_issued_qty := issued_raw_qty(p_production_order_id, line.BOM_LINE_ID, line.COMPONENT_ARTICUL);

      v_open_qty := greatest(v_required_qty - v_issued_qty, 0);

      v_soft_reservation_id := null;



      if v_open_qty > 0 then

        select RRL_STOCK_RESERVATION_SQ.nextval into v_soft_reservation_id from dual;

        insert into RRL_STOCK_RESERVATION (

          RESERVATION_ID, RESERVATION_KIND, RESERVATION_SCOPE, RESERVATION_DOMAIN,

          SOURCE_DOC_TYPE, SOURCE_DOC_ID, SOURCE_LINE_ID, PRODUCTION_ORDER_ID,

          ARTICUL, QTY, UNIT_CODE, STATUS, PRIORITY, CREATED_BY

        ) values (

          v_soft_reservation_id, 'SOFT', 'QTY', 'MES_RAW',

          'PRODUCTION_ORDER', p_production_order_id, line.ORDER_LINE_ID, p_production_order_id,

          line.COMPONENT_ARTICUL, v_open_qty, line.UNIT_CODE, 'ACTIVE', 100, v_actor

        );

      end if;



      select RRL_MES_RAW_DEMAND_SQ.nextval into v_demand_id from dual;

      insert into RRL_MES_RAW_DEMAND (

        DEMAND_ID, PRODUCTION_ORDER_ID, ORDER_LINE_ID, BOM_ID, BOM_LINE_ID,

        RAW_ARTICUL, REQUIRED_QTY, ISSUED_QTY, OPEN_QTY, UNIT_CODE,

        SOFT_RESERVATION_ID, STATUS, CALCULATED_BY

      ) values (

        v_demand_id, p_production_order_id, line.ORDER_LINE_ID, line.BOM_ID, line.BOM_LINE_ID,

        line.COMPONENT_ARTICUL, v_required_qty, v_issued_qty, v_open_qty, line.UNIT_CODE,

        v_soft_reservation_id, case when v_open_qty > 0 then 'OPEN' else 'COVERED' end, v_actor

      );



      if v_open_qty > 0 then

        v_available_total := 0;

        v_remaining_qty := v_open_qty;

        v_sort_order := 0;



        for cand in (

          select w.ID WARE_ID,

                 r.CELL,

                 r.UID_POLETA UID_PALLET,

                 p.SSCC,

                 p.ARTICUL,

                 p.PRIHOD_NAKLAD_ID RAW_BATCH_ID,

                 to_char(p.PRIHOD_NAKLAD_ID) BATCH_ID,

                 p.EXPIRY_DATE,

                 nvl(p.QUALITY_STATUS, 'UNKNOWN') QUALITY_STATUS,

                 nvl(r.REMAIN, 0) PHYSICAL_QTY,

                 nvl((

                   select sum(nvl(sr.QTY, 0))

                     from RRL_STOCK_RESERVATION sr

                    where sr.RESERVATION_KIND = 'HARD'

                      and sr.STATUS in ('ACTIVE', 'ALLOCATED', 'PICKING')

                      and sr.UID_PALLET = r.UID_POLETA

                 ), 0) HARD_RESERVED_QTY

            from RRL_REMAINS r

            join RRL_CELLS c on c.CELL = r.CELL

            join RRL_WARES w on w.ID = c.WARE_ID

            join RRL_PALLETS p on p.UID_PALLET = r.UID_POLETA

           where nvl(w.FLAG_RAW_MATERIAL, 0) = 1

             and upper(p.ARTICUL) = line.COMPONENT_ARTICUL

             and nvl(r.REMAIN, 0) > 0

           order by p.EXPIRY_DATE nulls last, p.PRODUCED_DATE nulls last, r.CELL, r.UID_POLETA

           for update of r.REMAIN

        ) loop

          v_available_qty := greatest(nvl(cand.PHYSICAL_QTY, 0) - nvl(cand.HARD_RESERVED_QTY, 0), 0);

          if v_available_qty > 0 and v_remaining_qty > 0 then

            v_sort_order := v_sort_order + 1;

            v_suggested_qty := least(v_remaining_qty, v_available_qty);

            v_available_total := v_available_total + v_available_qty;

            v_remaining_qty := greatest(v_remaining_qty - v_suggested_qty, 0);



            select RRL_MES_RAW_SUPPLY_CANDIDATE_SQ.nextval into v_candidate_id from dual;

            insert into RRL_MES_RAW_SUPPLY_CANDIDATE (

              CANDIDATE_ID, DEMAND_ID, PRODUCTION_ORDER_ID, RAW_ARTICUL,

              UID_PALLET, BATCH_ID, RAW_BATCH_ID, SSCC, FROM_WARE_ID, FROM_CELL,

              PHYSICAL_QTY, HARD_RESERVED_QTY, AVAILABLE_QTY, SUGGESTED_QTY,

              EXPIRY_DATE, QUALITY_STATUS, SORT_ORDER

            ) values (

              v_candidate_id, v_demand_id, p_production_order_id, line.COMPONENT_ARTICUL,

              cand.UID_PALLET, cand.BATCH_ID, cand.RAW_BATCH_ID, cand.SSCC, cand.WARE_ID, cand.CELL,

              cand.PHYSICAL_QTY, cand.HARD_RESERVED_QTY, v_available_qty, v_suggested_qty,

              cand.EXPIRY_DATE, cand.QUALITY_STATUS, v_sort_order

            );

          end if;



          exit when v_remaining_qty = 0;

        end loop;



        if v_remaining_qty > 0 then

          v_shortage_count := v_shortage_count + 1;

          select RRL_MES_RAW_SHORTAGE_SQ.nextval into v_shortage_id from dual;

          insert into RRL_MES_RAW_SHORTAGE (

            SHORTAGE_ID, PRODUCTION_ORDER_ID, DEMAND_ID, RAW_ARTICUL,

            REQUIRED_QTY, ISSUED_QTY, AVAILABLE_QTY, SHORTAGE_QTY, UNIT_CODE, STATUS

          ) values (

            v_shortage_id, p_production_order_id, v_demand_id, line.COMPONENT_ARTICUL,

            v_required_qty, v_issued_qty, greatest(v_open_qty - v_remaining_qty, 0), v_remaining_qty,

            line.UNIT_CODE, 'OPEN'

          );

        end if;

      end if;

    end loop;



    if v_shortage_count > 0 and nvl(p_allow_partial, 0) <> 1 then

      return 0;

    end if;



    for c in (

      select d.ORDER_LINE_ID, d.BOM_ID, d.BOM_LINE_ID, d.REQUIRED_QTY, d.UNIT_CODE,

             sc.RAW_ARTICUL, sc.UID_PALLET, sc.BATCH_ID, sc.RAW_BATCH_ID, sc.SSCC,

             sc.FROM_WARE_ID, sc.FROM_CELL, sc.PHYSICAL_QTY, sc.SUGGESTED_QTY

        from RRL_MES_RAW_DEMAND d

        join RRL_MES_RAW_SUPPLY_CANDIDATE sc on sc.DEMAND_ID = d.DEMAND_ID

       where d.PRODUCTION_ORDER_ID = p_production_order_id

         and sc.SUGGESTED_QTY > 0

       order by d.DEMAND_ID, sc.SORT_ORDER, sc.CANDIDATE_ID

    ) loop

      v_reservation_scope := case

        when nvl(c.PHYSICAL_QTY, 0) > 0 and nvl(c.SUGGESTED_QTY, 0) >= nvl(c.PHYSICAL_QTY, 0)

        then 'PALLET'

        else 'QTY'

      end;



      select RRL_STOCK_RESERVATION_SQ.nextval into v_reservation_id from dual;

      insert into RRL_STOCK_RESERVATION (

        RESERVATION_ID, RESERVATION_KIND, RESERVATION_SCOPE, RESERVATION_DOMAIN,

        SOURCE_DOC_TYPE, SOURCE_DOC_ID, SOURCE_LINE_ID, PRODUCTION_ORDER_ID,

        ARTICUL, QTY, UNIT_CODE, WARE_ID, CELL, BATCH_ID, UID_PALLET, SSCC,

        STATUS, PRIORITY, CREATED_BY

      ) values (

        v_reservation_id, 'HARD', v_reservation_scope, 'MES_RAW',

        'PRODUCTION_ORDER', p_production_order_id, c.ORDER_LINE_ID, p_production_order_id,

        c.RAW_ARTICUL, c.SUGGESTED_QTY, c.UNIT_CODE, c.FROM_WARE_ID, c.FROM_CELL,

        c.BATCH_ID, c.UID_PALLET, c.SSCC, 'ACTIVE', 100, v_actor

      );



      select RRL_MES_RAW_TRANSFER_TASK_SQ.nextval into v_task_id from dual;

      insert into RRL_MES_RAW_TRANSFER_TASK (

        TASK_ID, PRODUCTION_ORDER_ID, ORDER_LINE_ID, BOM_ID, BOM_LINE_ID,

        RAW_ARTICUL, RAW_BATCH_ID, BATCH_ID, UID_PALLET, SSCC,

        FROM_WARE_ID, FROM_CELL, TO_WARE_ID, TO_CELL,

        REQUIRED_QTY, TASK_QTY, UNIT_CODE, RESERVATION_ID,

        TASK_STATUS, PRIORITY, CREATED_BY

      ) values (

        v_task_id, p_production_order_id, c.ORDER_LINE_ID, c.BOM_ID, c.BOM_LINE_ID,

        c.RAW_ARTICUL, c.RAW_BATCH_ID, c.BATCH_ID, c.UID_PALLET, c.SSCC,

        c.FROM_WARE_ID, c.FROM_CELL, p_to_ware_id, v_to_cell,

        c.REQUIRED_QTY, c.SUGGESTED_QTY, c.UNIT_CODE, v_reservation_id,

        'PLANNED', 100, v_actor

      );



      update RRL_STOCK_RESERVATION

         set TASK_ID = v_task_id

       where RESERVATION_ID = v_reservation_id;



      v_task_count := v_task_count + 1;

    end loop;



    if v_task_count > 0 then

      update RRL_PRODUCTION_ORDER

         set STATUS = case when STATUS = 'DRAFT' then 'RELEASED' else STATUS end,

             UPDATED_AT = systimestamp,

             UPDATED_BY = v_actor

       where PRODUCTION_ORDER_ID = p_production_order_id

         and STATUS not in ('COMPLETED', 'CANCELLED');

    end if;



    return v_task_count;

  exception

    when no_data_found then

      raise_application_error(-20952, 'MES production order not found');

  end release_to_production;

end RRL_MES_RAW_SUPPLY_OLD;
/


CREATE OR REPLACE package body RRL_NORM_COST_CORRECTION as
 function confirmed_total(p_cost varchar2)return number is original_amount number;adjusted number;begin
  select json_value(r.RESULT_JSON,'$.total' returning number error on error)into original_amount
   from RRL_LOGISTICS_COST_RUN r join RRL_TRANSPORT_COST_CLAIM c on c.OPERATION_ID=r.OPERATION_ID where r.OPERATION_ID=p_cost;
  select nvl(sum(e.AMOUNT*e.ADJUSTMENT_SIGN),0)into adjusted from RRL_LOGISTICS_EXPENSE e
   join RRL_LOGISTICS_EXP_DECISION f on f.EXPENSE_OPERATION_ID=e.OPERATION_ID and f.PHASE='FINANCE'and f.OUTCOME='APPROVE'
   where e.COST_CORRECTION_OF_OP=p_cost;
  return original_amount+adjusted;
 exception when no_data_found then raise_application_error(-20886,'NORMATIVE_ORIGINAL_COST_REQUIRED');end;
 procedure validate_report(p_cost varchar2,p_ware number,p_kind varchar2,p_object number,p_currency varchar2,p_delta number,p_expected number)is
  v_ware number;v_trip number;v_currency varchar2(3);v_op varchar2(100);total number;
 begin
  select r.WARE_ID,r.TT_ID,r.CURRENCY,r.OPERATION_ID into v_ware,v_trip,v_currency,v_op
   from RRL_LOGISTICS_COST_RUN r where r.OPERATION_ID=p_cost
   and exists(select 1 from RRL_TRANSPORT_COST_CLAIM c where c.OPERATION_ID=r.OPERATION_ID)for update;
  if p_ware!=v_ware or p_kind!='TRIP'or p_object!=v_trip or p_currency!=v_currency then raise_application_error(-20886,'NORMATIVE_CORRECTION_ORIGINAL_IDENTITY');end if;
  total:=confirmed_total(p_cost);
  if p_expected is null or p_expected!=total or p_delta is null or p_delta=0 or total+p_delta<0 or total+p_delta>=1e18
   then raise_application_error(-20867,'NORMATIVE_CORRECTION_CURRENT_TOTAL');end if;
 exception when no_data_found then raise_application_error(-20886,'NORMATIVE_ORIGINAL_COST_REQUIRED');end;
 procedure validate_decision(p_expense varchar2,p_phase varchar2,p_outcome varchar2)is
  cost_op varchar2(100);ware number;kind varchar2(10);object_id number;currency_value varchar2(3);delta number;expected number;
 begin
  select COST_CORRECTION_OF_OP,WARE_ID,OBJECT_KIND,OBJECT_ID,CURRENCY,AMOUNT*ADJUSTMENT_SIGN,EXPECTED_CONFIRMED_TOTAL
   into cost_op,ware,kind,object_id,currency_value,delta,expected from RRL_LOGISTICS_EXPENSE where OPERATION_ID=p_expense;
  if cost_op is not null and p_phase='FINANCE'and p_outcome='APPROVE'then
   validate_report(cost_op,ware,kind,object_id,currency_value,delta,expected);
  end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_ORDER_WEIGHT_READ as
 function snapshot_json(p_task number,p_line number,p_actor varchar2)return clob is
  t RRL_CASE_PICK_TASK%rowtype;l RRL_CASE_PICK_LINE%rowtype;
  order_id number;article varchar2(160);pct number;version number;requested number:=0;actual number:=0;
  row_json json_object_t;result_json json_object_t:=json_object_t();rows_json json_array_t:=json_array_t();
  lower_qty number;upper_qty number;n number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'case_pick_short_approve')=1 then RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,'case_pick_short_approve');else RRL_CASE_TASK_ACCESS.assert_scope(p_task,p_actor,'case_pick_execute');end if;
  select *into t from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task;
  select *into l from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=p_task and CASE_PICK_LINE_ID=p_line;
  order_id:=l.CUSTOMER_ORDER_ID;
  article:=l.ARTICUL;
  select count(*)into n from RRL_ARTICULS where ACTICUL=article and TYPE_W in(2,3,5,6,7);
  if n!=1 then raise_application_error(-20886,'ORDER_WEIGHT_CURRENT_WEIGHTED_SKU_REQUIRED');end if;
  select nvl(max(ORDER_WEIGHT_TOLERANCE_PCT),15),nvl(max(POLICY_VERSION),0)into pct,version from RRL_SKU_RECEIPT_POLICY where ARTICUL=article;
  for o in(select CUSTOMER_ORDER_ROW_ID from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ID=order_id and ARTICUL=article
   and STATUS not in('CANCELLED','REJECTED') order by CUSTOMER_ORDER_ROW_ID fetch first 201 rows only)loop
   if rows_json.get_size=200 then raise_application_error(-20881,'ORDER_WEIGHT_ROWS_BOUND_200');end if;
   row_json:=json_object_t.parse(RRL_STOCK_POOL_READ.line_snapshot_json(o.CUSTOMER_ORDER_ROW_ID));
   if row_json.get_string('unit')!='KG' or row_json.get_number('warehouse')!=t.WARE_ID then raise_application_error(-20886,'ORDER_WEIGHT_ORIGINAL_KG_WARE_REQUIRED');end if;
   requested:=requested+RRL_STOCK_MATH.quantity(row_json.get_string('requested_base_quantity'));
   if row_json.get_string('picked_quantity')!='0'then actual:=actual+RRL_STOCK_MATH.quantity(row_json.get_string('picked_quantity'));end if;
   rows_json.append(row_json);
  end loop;
  if requested<=0 then raise_application_error(-20886,'ORDER_WEIGHT_ORIGINAL_DEMAND_REQUIRED');end if;
  lower_qty:=requested*(1-pct/100);upper_qty:=requested*(1+pct/100);
  result_json.put('customer_order_id',order_id);result_json.put('article',article);result_json.put('warehouse_id',t.WARE_ID);
  result_json.put('case_pick_task_id',p_task);result_json.put('case_pick_line_id',p_line);result_json.put('content_version',t.CONTENT_VERSION);
  result_json.put('policy_version',version);result_json.put('tolerance_pct',RRL_STOCK_PLAN_HELPER.decimal_text(pct));
  result_json.put('unit','KG');result_json.put('requested_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(requested));
  result_json.put('picked_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(actual));
  result_json.put('lower_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(lower_qty));result_json.put('upper_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(upper_qty));
  result_json.put('within_tolerance',actual>0 and actual>=lower_qty and actual<=upper_qty);
  result_json.put('allows_close',false);result_json.put('needs_explicit_decision',true);result_json.put('rows',rows_json);
  result_json.put('order_weight_signature',rawtohex(sys.dbms_crypto.hash(result_json.to_clob,sys.dbms_crypto.hash_sh256)));
  return result_json.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_OUTBOX_DELIVERY_API as
 g_event number;g_tx varchar2(100);
 function write_allowed(p_event number)return number is begin
  if p_event=g_event and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure open_write(p_event number)is begin g_event:=p_event;g_tx:=dbms_transaction.local_transaction_id(true);end;
 procedure clear_write is begin g_event:=null;g_tx:=null;end;
 procedure owned(e RRL_EVENT_OUTBOX%rowtype,p_version number,p_worker varchar2)is begin
  if p_version is null or p_version<1 or trim(p_worker)is null or e.CLAIM_VERSION!=p_version or e.STATUS!='LOCKED' or e.LOCKED_BY is null or e.LOCKED_BY!=p_worker then
   raise_application_error(-20886,'OUTBOX_CLAIM_FENCED');end if;
 end;
 procedure claim_next(p_worker varchar2,p_target varchar2,p_seconds number,p_result out clob)is
  cursor candidates is select *from RRL_EVENT_OUTBOX where
   ((STATUS in('PENDING','RETRY')and(NEXT_RETRY_AT is null or NEXT_RETRY_AT<=sysdate))
     or(STATUS='LOCKED'and LEASE_UNTIL is not null and LEASE_UNTIL<=systimestamp))
   and(p_target is null or TARGET_SYSTEM=upper(p_target))
   order by CREATED_AT,EVENT_OUTBOX_ID for update skip locked;
  e RRL_EVENT_OUTBOX%rowtype;j json_object_t:=json_object_t();v_seen number:=0;v_until timestamp with time zone;
  v_saved boolean:=false;
 begin
  p_result:=null;
  if trim(p_worker)is null or lengthb(p_worker)>100 or p_seconds is null or p_seconds not between 1 and 900 then
   raise_application_error(-20881,'OUTBOX_CLAIM_INPUT_REQUIRED');end if;
  open candidates;
  loop
   exit when v_seen>=100;fetch candidates into e;exit when candidates%notfound;
   v_seen:=v_seen+1;
   savepoint RRL_OUTBOX154;v_saved:=true;open_write(e.EVENT_OUTBOX_ID);
   if e.STATUS='LOCKED' then
    update RRL_EVENT_OUTBOX set TRY_COUNT=TRY_COUNT+1,LAST_ERROR='LEASE_EXPIRED_OUTCOME_UNCONFIRMED'where EVENT_OUTBOX_ID=e.EVENT_OUTBOX_ID;
    e.TRY_COUNT:=e.TRY_COUNT+1;
    update RRL_ADAPTER_REQUEST_LOG set STATUS='UNCONFIRMED',ERROR_CODE='LEASE_EXPIRED',
     ERROR_TEXT='Worker lease expired before final response',RESPONSE_AT_TZ=systimestamp
     where EVENT_OUTBOX_ID=e.EVENT_OUTBOX_ID and CLAIM_VERSION=e.CLAIM_VERSION and FINISH_HASH is null and STATUS='STARTED';
   end if;
   if e.TRY_COUNT>=e.MAX_TRY_COUNT then
    update RRL_EVENT_OUTBOX set STATUS='DEAD_LETTER',FINISHED_AT=sysdate,LOCKED_BY=null,LOCKED_AT=null,LEASE_UNTIL=null
     where EVENT_OUTBOX_ID=e.EVENT_OUTBOX_ID;
    clear_write;v_saved:=false;
   else
    v_until:=systimestamp+numtodsinterval(p_seconds,'SECOND');
    update RRL_EVENT_OUTBOX set STATUS='LOCKED',LOCKED_BY=p_worker,LOCKED_AT=sysdate,
     CLAIM_VERSION=CLAIM_VERSION+1,LEASE_UNTIL=v_until where EVENT_OUTBOX_ID=e.EVENT_OUTBOX_ID;
    j.put('event_outbox_id',e.EVENT_OUTBOX_ID);j.put('claim_version',e.CLAIM_VERSION+1);j.put('worker_id',p_worker);
    j.put('lease_until',to_char(v_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
    p_result:=j.to_clob;clear_write;v_saved:=false;exit;
   end if;
  end loop;
  close candidates;
 exception when others then
  if candidates%isopen then close candidates;end if;
  if v_saved then rollback to RRL_OUTBOX154;end if;clear_write;raise;
 end;
 procedure begin_attempt(p_event number,p_version number,p_worker varchar2,p_system varchar2,p_kind varchar2,
  p_business varchar2,p_cert varchar2,p_thumb varchar2,p_signature varchar2,p_request clob,p_request_id out number)is
  e RRL_EVENT_OUTBOX%rowtype;v_saved boolean:=false;n number;
 begin
  select *into e from RRL_EVENT_OUTBOX where EVENT_OUTBOX_ID=p_event for update;owned(e,p_version,p_worker);
  if e.LEASE_UNTIL<=systimestamp then raise_application_error(-20886,'OUTBOX_LEASE_EXPIRED');end if;
  select count(*),max(ADAPTER_REQUEST_ID)into n,p_request_id from RRL_ADAPTER_REQUEST_LOG
   where EVENT_OUTBOX_ID=p_event and CLAIM_VERSION=p_version and CLAIM_WORKER=p_worker;
  if n>0 then raise_application_error(-20886,'OUTBOX_ATTEMPT_ALREADY_STARTED_RECONCILE');end if;
  savepoint RRL_OUTBOX154;v_saved:=true;open_write(p_event);
  p_request_id:=RRL_TRACEABILITY_API.add_adapter_request(p_system,p_kind,p_event,p_business,p_cert,p_thumb,p_signature,p_request,'STARTED',e.TRY_COUNT+1);
  update RRL_ADAPTER_REQUEST_LOG set CLAIM_VERSION=p_version,CLAIM_WORKER=p_worker where ADAPTER_REQUEST_ID=p_request_id;
  clear_write;
 exception when others then if v_saved then rollback to RRL_OUTBOX154;end if;clear_write;raise;
 end;
 procedure finish_attempt(p_event number,p_version number,p_worker varchar2,p_request_id number,p_body clob,p_result out clob)is
  e RRL_EVENT_OUTBOX%rowtype;r RRL_ADAPTER_REQUEST_LOG%rowtype;b json_object_t:=json_object_t.parse(p_body);
  digest varchar2(64);v_status varchar2(30);v_error varchar2(4000);j json_object_t:=json_object_t();v_stale boolean;v_saved boolean:=false;
 begin
  if p_event is null or p_request_id is null or p_version is null or p_version<1 or trim(p_worker)is null then
   raise_application_error(-20881,'OUTBOX_RESPONSE_CLAIM_REQUIRED');end if;
  digest:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  select *into e from RRL_EVENT_OUTBOX where EVENT_OUTBOX_ID=p_event for update;
  select *into r from RRL_ADAPTER_REQUEST_LOG where ADAPTER_REQUEST_ID=p_request_id for update;
  if r.EVENT_OUTBOX_ID!=p_event or r.CLAIM_VERSION!=p_version or r.CLAIM_WORKER is null or r.CLAIM_WORKER!=p_worker then
   raise_application_error(-20882,'OUTBOX_REQUEST_CLAIM_IDENTITY_CONFLICT');end if;
  if r.FINISH_HASH is not null then
   if r.FINISH_HASH!=digest then raise_application_error(-20886,'OUTBOX_RESPONSE_PAYLOAD_CONFLICT');end if;
   j.put('event_outbox_id',p_event);j.put('adapter_request_id',p_request_id);j.put('status',r.STATUS);j.put('idempotent',true);
   p_result:=j.to_clob;return;
  end if;
  v_status:=b.get_string('status');v_error:=b.get_string('error_text');
  if v_status not in('DONE','ERROR')or v_status is null then raise_application_error(-20881,'OUTBOX_FINAL_OUTCOME_REQUIRED');end if;
  v_stale:=e.CLAIM_VERSION!=p_version or e.STATUS!='LOCKED' or e.LOCKED_BY is null or e.LOCKED_BY!=p_worker or e.LEASE_UNTIL is null or e.LEASE_UNTIL<=systimestamp;
  savepoint RRL_OUTBOX154;v_saved:=true;open_write(p_event);
  RRL_TRACEABILITY_API.update_adapter_request(p_request_id,b.get_clob('response_json'),b.get_string('external_request_id'),
   b.get_string('external_document_id'),b.get_string('external_status'),b.get_number('http_status'),
   case when v_stale then 'STALE_RESPONSE'else v_status end,
   case when v_stale then 'OUTBOX_CLAIM_FENCED'else b.get_string('error_code')end,
   case when v_stale then 'Response retained; current event generation unchanged'else v_error end);
  update RRL_ADAPTER_REQUEST_LOG set FINISH_HASH=digest,RESPONSE_AT_TZ=systimestamp where ADAPTER_REQUEST_ID=p_request_id;
  if not v_stale then
   if v_status='DONE'then RRL_TRACEABILITY_API.mark_outbox_done(p_event,'DONE');
   else RRL_TRACEABILITY_API.mark_outbox_error(p_event,v_error,5,0);end if;
   update RRL_EVENT_OUTBOX set LEASE_UNTIL=null where EVENT_OUTBOX_ID=p_event;
  end if;
  j.put('event_outbox_id',p_event);j.put('adapter_request_id',p_request_id);
  j.put('status',case when v_stale then 'STALE_RESPONSE'else v_status end);j.put('idempotent',false);
  p_result:=j.to_clob;clear_write;
 exception when others then if v_saved then rollback to RRL_OUTBOX154;end if;clear_write;raise;
 end;
 procedure manual_retry(p_event number,p_actor varchar2,p_reason varchar2)is
  e RRL_EVENT_OUTBOX%rowtype;n number;v_saved boolean:=false;j json_object_t:=json_object_t();v_payload clob;v_request number;
 begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'external_outbox_retry')=1;
  if n!=1 then raise_application_error(-20882,'OUTBOX_RETRY_CURRENT_ACTOR_REQUIRED');end if;
  if p_reason is null or length(p_reason)<8 then raise_application_error(-20881,'OUTBOX_RETRY_REASON_REQUIRED');end if;
  select *into e from RRL_EVENT_OUTBOX where EVENT_OUTBOX_ID=p_event for update;
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'external_outbox_retry')=1;
  if n!=1 then raise_application_error(-20882,'OUTBOX_RETRY_CURRENT_ACTOR_REQUIRED');end if;
  if e.STATUS in('DONE','EXPORTED','ACKNOWLEDGED')then raise_application_error(-20886,'OUTBOX_COMPLETED_CANNOT_RETRY');end if;
  if e.STATUS='LOCKED'and(e.LEASE_UNTIL is null or e.LEASE_UNTIL>systimestamp)then
   raise_application_error(-20886,'OUTBOX_ACTIVE_OR_LEGACY_LOCK_REQUIRES_RECONCILIATION');end if;
  savepoint RRL_OUTBOX154;v_saved:=true;open_write(p_event);
  update RRL_EVENT_OUTBOX set STATUS='PENDING',CLAIM_VERSION=CLAIM_VERSION+1,LEASE_UNTIL=null,MAX_TRY_COUNT=greatest(MAX_TRY_COUNT,TRY_COUNT+1),
   LOCKED_BY=null,LOCKED_AT=null,NEXT_RETRY_AT=null,LAST_ERROR=substr('Manual retry: '||p_reason,1,4000)
   where EVENT_OUTBOX_ID=p_event;
  j.put('actor',p_actor);j.put('reason',p_reason);j.put('old_try_count',e.TRY_COUNT);j.put('old_max_try_count',e.MAX_TRY_COUNT);
  j.put('new_max_try_count',greatest(e.MAX_TRY_COUNT,e.TRY_COUNT+1));v_payload:=j.to_clob;
  v_request:=RRL_TRACEABILITY_API.add_adapter_request(e.TARGET_SYSTEM,'MANUAL_RETRY',p_event,e.IDEMPOTENCY_KEY,
    null,null,'NOT_APPLICABLE',v_payload,'MANUAL_RETRY',e.TRY_COUNT+1);
  update RRL_ADAPTER_REQUEST_LOG set CLAIM_VERSION=e.CLAIM_VERSION+1,CLAIM_WORKER=p_actor,RESPONSE_AT_TZ=systimestamp
    where ADAPTER_REQUEST_ID=v_request;
  clear_write;
 exception when others then if v_saved then rollback to RRL_OUTBOX154;end if;clear_write;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_OUTGOING_QC_ACCESS as
 procedure assert_identifier(p_identifier varchar2,p_actor varchar2)is
  ware number;user_ware number;grp varchar2(100);
 begin
  if p_actor is null or(RRL_HAS_WRIGHT(p_actor,'outgoing_pallet_check')!=1 and RRL_HAS_WRIGHT(p_actor,'stock_posting_shipping')!=1
   and RRL_HAS_WRIGHT(p_actor,'CLOSE_OTHOD_NAKLAD')!=1)then raise_application_error(-20882,'OUTGOING_QC_PERMISSION_REQUIRED');end if;
  select WARE_ID into ware from RRL_SBORKA_PALLETS where PALLET_UID=p_identifier;
  select WARE_ID,USER_GROUP into user_ware,grp from RUSERS where ID=p_actor and nvl(DELETED,0)=0;
  if ware is null or(upper(trim(grp))!='GLOBAL_ADMIN'and(user_ware is null or user_ware!=ware))
   then raise_application_error(-20882,'OUTGOING_QC_CURRENT_WARE_REQUIRED');end if;
 exception when no_data_found then raise_application_error(-20882,'OUTGOING_QC_CURRENT_SOURCE_AND_ACTOR_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_PALLET_FLOOR_READ as
 function scope_warehouse(p_uid varchar2,p_actor varchar2)return number is ware_no number;n number;
 begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'stock_posting_shipping')=1;
  if n!=1 then raise_application_error(-20882,'PALLET_FLOOR_ACTOR_REQUIRED');end if;
  select count(distinct c.WARE_ID),min(c.WARE_ID)into n,ware_no from RRL_REMAINS r join RRL_CELLS c on c.CELL=r.CELL
   where r.UID_POLETA=p_uid and r.REMAIN>0;
  if n>1 then raise_application_error(-20886,'PALLET_FLOOR_SINGLE_WARE_REQUIRED');end if;
  if n=0 then
   begin select DECLARED_WARE_ID into ware_no from RRL_PALLET_FLOOR_TYPE where UID_PALLET=p_uid;
   exception when no_data_found then raise_application_error(-20886,'PALLET_FLOOR_CURRENT_SOURCE_REQUIRED');end;
  end if;
  select count(*)into n from RUSERS u join RRL_WARES w on w.ID=ware_no where u.ID=p_actor and nvl(u.DELETED,0)=0
   and(u.WARE_ID=ware_no or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'PALLET_FLOOR_CURRENT_WARE_FORBIDDEN');end if;
  return ware_no;
 end;
 function describe_type(p_uid varchar2,p_actor varchar2)return clob is
  ware_no number:=scope_warehouse(p_uid,p_actor);p RRL_PALLETS%rowtype;meta RRL_PALLET_FLOOR_TYPE%rowtype;
  j json_object_t:=json_object_t();n number;cell_value varchar2(60);type_name varchar2(160);
 begin
  select *into p from RRL_PALLETS where UID_PALLET=p_uid;
  if p.HU_KIND is null or p.HU_KIND!='STOCK'then raise_application_error(-20886,'PALLET_FLOOR_STOCK_CARRIER_REQUIRED');end if;
  select count(*)into n from RRL_WMS_HU_LINK where CHILD_PALLET_UID=p_uid and ACTIVE_FLAG=1;
  if n>0 then raise_application_error(-20886,'PALLET_FLOOR_INDEPENDENT_TOP_REQUIRED');end if;
  select count(*)into n from RRL_CASE_CARRIER_LOT where LOT_UID=p_uid;
  if n>0 then raise_application_error(-20886,'PALLET_FLOOR_INDEPENDENT_TOP_REQUIRED');end if;
  select count(*),min(CELL)into n,cell_value from RRL_REMAINS where UID_POLETA=p_uid and REMAIN>0;
  if n>1 then raise_application_error(-20886,'PALLET_FLOOR_SINGLE_PHYSICAL_CELL_REQUIRED');end if;
  j.put('article',p.ARTICUL);j.put('uid',p_uid);j.put('warehouse',ware_no);j.put('kind',p.HU_KIND);j.put('sscc',p.SSCC);j.put('cell',cell_value);
  j.put('has_physical_stock',n=1);j.put('operational_admission',false);j.put('stock_changed',false);
  begin
   select *into meta from RRL_PALLET_FLOOR_TYPE where UID_PALLET=p_uid;
   select PALLET_TYPE_NAME into type_name from RRL_PALLET_TYPE where PALLET_TYPE_ID=meta.PALLET_TYPE_ID;
   j.put('version',meta.TYPE_VERSION);j.put('pallet_type_id',meta.PALLET_TYPE_ID);j.put('current_type_name',type_name);
   j.put('operation_id',meta.LAST_OPERATION_ID);j.put('status','CONFIGURED');
  exception when no_data_found then j.put('version',0);j.put('status','NOT_CONFIGURED');end;
  return j.to_clob;
 exception when no_data_found then raise_application_error(-20886,'PALLET_FLOOR_CURRENT_SOURCE_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_PALLET_TYPE_API as
 procedure clear_context is begin dbms_session.clear_context('RRL_PALLET_TYPE_CTX',null,'TX_ID');dbms_session.clear_context('RRL_PALLET_TYPE_CTX',null,'ACTOR');dbms_session.clear_context('RRL_PALLET_TYPE_CTX',null,'TYPE_ID');end;
 procedure upsert_request(p_request clob,p_actor varchar2,p_id out number)is
  j json_object_t:=json_object_t.parse(p_request);v_id number;v_code varchar2(50);name_value varchar2(160);class_value varchar2(20);
  v_volume number;v_weight number;len_mm number;v_width_mm number;v_height_mm number;v_max_clients number;v_active number;v_required number;n number;current_version number:=0;expected_version number;old_required number;
 begin
  if p_request is null or dbms_lob.getlength(p_request)>16000 then raise_application_error(-20881,'PALLET_TYPE_REQUEST_BOUND');end if;
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0;
  if n!=1 or RRL_HAS_WRIGHT(p_actor,'case_pick_manage')!=1 then raise_application_error(-20882,'PALLET_TYPE_MANAGE_FORBIDDEN');end if;
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STOCK_POLICY_GUARD','WAREHOUSE.METADATA'));
  v_id:=j.get_number('pallet_type_id');v_code:=upper(trim(j.get_string('pallet_type_code')));name_value:=trim(j.get_string('pallet_type_name'));
  class_value:=upper(trim(j.get_string('load_unit_class')));v_volume:=j.get_number('default_volume_m3');v_weight:=j.get_number('default_weight_kg');
  len_mm:=j.get_number('length_mm');v_width_mm:=j.get_number('width_mm');v_height_mm:=j.get_number('height_mm');
  v_max_clients:=j.get_number('default_max_client_pallets');v_active:=j.get_number('active');
  if v_code is null or name_value is null or class_value is null or nvl(v_volume,0)<0 or nvl(v_weight,0)<0 or nvl(len_mm,0)<0
   or nvl(v_width_mm,0)<0 or nvl(v_height_mm,0)<0 or v_max_clients is null or v_max_clients not between 1 and 3 or v_max_clients!=trunc(v_max_clients)
   or v_active is null or v_active not in(0,1) then raise_application_error(-20886,'PALLET_TYPE_FIELDS_INVALID');end if;
  if v_id is null then
   begin select PALLET_TYPE_ID into v_id from RRL_PALLET_TYPE where PALLET_TYPE_CODE=v_code;
   exception when no_data_found then select RRL_PALLET_TYPE_SQ.nextval into v_id from dual;end;
  elsif v_id<1 or v_id!=trunc(v_id)then raise_application_error(-20886,'PALLET_TYPE_ID_INVALID');end if;
  expected_version:=j.get_number('expected_version');
  begin select TYPE_VERSION,FINAL_WEIGHT_REQUIRED into current_version,old_required from RRL_PALLET_TYPE where PALLET_TYPE_ID=v_id;
  exception when no_data_found then current_version:=0;old_required:=0;end;
  if expected_version is not null and expected_version!=current_version then raise_application_error(-20873,'PALLET_TYPE_VERSION_CHANGED');end if;
  v_required:=null;
  if j.has('final_weight_required')and not j.get('final_weight_required').is_null then v_required:=case when j.get_boolean('final_weight_required')then 1 else 0 end;end if;
  if v_required is not null and v_required!=old_required and expected_version is null then raise_application_error(-20886,'PALLET_TYPE_EXPECTED_VERSION_REQUIRED_FOR_FINAL_WEIGHT');end if;
  dbms_session.set_context('RRL_PALLET_TYPE_CTX','TX_ID',dbms_transaction.local_transaction_id(true));
  dbms_session.set_context('RRL_PALLET_TYPE_CTX','ACTOR',p_actor);dbms_session.set_context('RRL_PALLET_TYPE_CTX','TYPE_ID',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));
  merge into RRL_PALLET_TYPE d using(select v_id PALLET_TYPE_ID from dual)s on(d.PALLET_TYPE_ID=s.PALLET_TYPE_ID)
  when matched then update set PALLET_TYPE_CODE=v_code,PALLET_TYPE_NAME=name_value,LOAD_UNIT_CLASS=class_value,
   DEFAULT_VOLUME_M3=v_volume,DEFAULT_WEIGHT_KG=v_weight,LENGTH_MM=len_mm,WIDTH_MM=v_width_mm,HEIGHT_MM=v_height_mm,
   DEFAULT_MAX_CLIENT_PALLETS=v_max_clients,ACTIVE=v_active,FINAL_WEIGHT_REQUIRED=nvl(v_required,d.FINAL_WEIGHT_REQUIRED),TYPE_VERSION=d.TYPE_VERSION+1,UPDATED_AT=systimestamp,UPDATED_BY=p_actor
  when not matched then insert(PALLET_TYPE_ID,PALLET_TYPE_CODE,PALLET_TYPE_NAME,LOAD_UNIT_CLASS,DEFAULT_VOLUME_M3,DEFAULT_WEIGHT_KG,
   LENGTH_MM,WIDTH_MM,HEIGHT_MM,DEFAULT_MAX_CLIENT_PALLETS,ACTIVE,FINAL_WEIGHT_REQUIRED,CREATED_AT,CREATED_BY)
   values(v_id,v_code,name_value,class_value,v_volume,v_weight,len_mm,v_width_mm,v_height_mm,v_max_clients,v_active,nvl(v_required,0),systimestamp,p_actor);
  clear_context;p_id:=v_id;
 exception when others then clear_context;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_PICKING_API as
  function active_reserved_qty(
    p_pallet_uid varchar2,
    p_articul    varchar2,
    p_cell       varchar2 default null
  ) return number is
    v_qty number;
  begin
    select nvl(sum(RESERVED_QTY), 0)
      into v_qty
      from RRL_PICK_RESERVATION
     where RESERVATION_STATUS = 'ACTIVE'
       and (RESERVATION_LEVEL='SOFT' or exists(select 1 from RRL_STOCK_RELEASE where RELEASE_ID=1 and STATE!='ACTIVE'))
       and PALLET_UID = p_pallet_uid
       and (p_cell is null or SOURCE_CELL_CODE=p_cell)
       and upper(ARTICUL) = upper(p_articul);
    return v_qty;
  end active_reserved_qty;

  procedure log_decision(
    p_pick_plan_id      number,
    p_pick_plan_line_id number,
    p_decision_type     varchar2,
    p_message_text      varchar2,
    p_payload_json      clob default null,
    p_created_by        varchar2 default null
  ) is
  begin
    insert into RRL_PICK_DECISION_LOG (
      PICK_DECISION_ID, PICK_PLAN_ID, PICK_PLAN_LINE_ID,
      DECISION_TYPE, MESSAGE_TEXT, PAYLOAD_JSON, CREATED_AT, CREATED_BY
    ) values (
      RRL_PICK_DECISION_LOG_SQ.nextval, p_pick_plan_id, p_pick_plan_line_id,
      substr(p_decision_type, 1, 50), substr(p_message_text, 1, 1000),
      p_payload_json, sysdate, substr(p_created_by, 1, 50)
    );
  end log_decision;

  function create_plan(
    p_customer_order_id number,
    p_plan_strategy     varchar2 default 'FEFO',
    p_created_by        varchar2 default null
  ) return number is
    v_order RRL_CUSTOMER_ORDER%rowtype;
    v_pick_plan_id number;
    v_line_id number;
    v_task_id number;
    v_remaining number;
    v_candidate_available number;
    v_reserved_by_other number;
    v_reserve_qty number;
    v_requested_total number := 0;
    v_planned_total number := 0;
    v_shortage_total number := 0;
    v_line_planned number;
    v_line_shortage number;
    v_task_type varchar2(30);
    v_strategy varchar2(30);
    v_status varchar2(30);
    v_target_cell varchar2(60);
    v_pick_sequence number;
    v_pick_face_id number;
    v_pick_route_cell_id number;
    v_release varchar2(20);v_requested_line_qty number;v_uom varchar2(20);v_version number;v_num number;v_den number;v_scale number;v_demand json_object_t;v_soft number;v_fenced boolean:=false;v_mutating boolean:=false;v_bound_plan number;v_weight_wire clob;v_weight_choice json_object_t;v_weight_id varchar2(100);v_weight_uid varchar2(150);v_weight_cell varchar2(60);
  begin
    select STATE into v_release from RRL_STOCK_RELEASE where RELEASE_ID=1;
    if v_release='ACTIVE'then RRL_PICK_PLAN_ADMISSION.begin_plan(p_customer_order_id,p_created_by);v_fenced:=true;savepoint rrl_pick_plan_begin;v_mutating:=true;end if;
    if v_fenced then v_bound_plan:=RRL_PICK_PLAN_CREATE_API.cached_plan;
     if v_bound_plan is not null then RRL_PICK_PLAN_ADMISSION.end_plan;return v_bound_plan;end if;end if;
    v_strategy := upper(nvl(p_plan_strategy, 'FEFO'));
    if v_strategy not in ('FEFO', 'FIFO') then
      raise_application_error(-20980, 'unsupported picking strategy');
    end if;

    select *
      into v_order
      from RRL_CUSTOMER_ORDER
     where CUSTOMER_ORDER_ID = p_customer_order_id;

    if v_release='ACTIVE'then
     v_bound_plan:=RRL_WEIGHT_PLAN_BIND.bound_plan(p_customer_order_id,v_strategy,p_created_by);
     if v_bound_plan>0 then RRL_PICK_PLAN_ADMISSION.end_plan;return v_bound_plan;end if;
    end if;
    select RRL_PICK_PLAN_SQ.nextval into v_pick_plan_id from dual;

    insert into RRL_PICK_PLAN (
      PICK_PLAN_ID, CUSTOMER_ORDER_ID, CUSTOMER_ID, WARE_ID, ROUTE_ID, DOCK_ID,
      STATUS, PLAN_STRATEGY, CREATED_AT, CREATED_BY
    ) values (
      v_pick_plan_id, v_order.CUSTOMER_ORDER_ID, v_order.CUSTOMER_ID, v_order.WARE_ID,
      v_order.ROUTE_ID, v_order.DOCK_ID, 'DRAFT', v_strategy, sysdate, substr(p_created_by, 1, 50)
    );

    for l in (
      select *
        from RRL_CUSTOMER_ORDER_ROW
       where CUSTOMER_ORDER_ID = p_customer_order_id
         and STATUS <> 'CANCELLED'
       order by LINE_NO, CUSTOMER_ORDER_ROW_ID
    ) loop
      select RRL_PICK_PLAN_LINE_SQ.nextval into v_line_id from dual;
      v_requested_line_qty:=nvl(l.ORDER_QTY,0);v_weight_wire:=null;v_weight_choice:=null;v_weight_id:=null;v_weight_uid:=null;v_weight_cell:=null;
      if v_release='ACTIVE' then
       select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=l.ARTICUL and INPUT_UOM=l.UNIT_CODE;
       select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into v_uom,v_num,v_den,v_scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=l.ARTICUL and INPUT_UOM=l.UNIT_CODE and POLICY_VERSION=v_version;
       v_demand:=json_object_t.parse(RRL_STOCK_POOL_READ.line_snapshot_json(l.CUSTOMER_ORDER_ROW_ID));
       if not v_demand.get_boolean('open')then continue;end if;
       if v_demand.get_string('quantity')='0'then v_requested_line_qty:=0;else v_requested_line_qty:=RRL_STOCK_MATH.quantity(v_demand.get_string('quantity'));end if;
       select nvl(sum(pr.RESERVED_QTY),0)into v_soft from RRL_PICK_RESERVATION pr
        join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=pr.PICK_PLAN_LINE_ID join RRL_PICK_PLAN pp on pp.PICK_PLAN_ID=pl.PICK_PLAN_ID
        where pl.CUSTOMER_ORDER_ROW_ID=l.CUSTOMER_ORDER_ROW_ID and pr.RESERVATION_STATUS='ACTIVE'and pr.RESERVATION_LEVEL='SOFT'
         and pp.STATUS in('DRAFT','PLANNED_FULL','PLANNED_PARTIAL');
       v_requested_line_qty:=greatest(0,v_requested_line_qty-v_soft);
       if v_requested_line_qty=0 then continue;end if;
      end if;
      v_remaining := v_requested_line_qty;
      if v_release='ACTIVE'then
       v_weight_wire:=RRL_WEIGHT_PLAN_BIND.target_json(l.CUSTOMER_ORDER_ROW_ID,p_created_by);
       if v_weight_wire is not null then
        v_weight_choice:=json_object_t.parse(v_weight_wire);
        if v_weight_choice.has('already_planned')and v_weight_choice.get_boolean('already_planned')then continue;end if;
        v_remaining:=RRL_STOCK_MATH.quantity(v_weight_choice.get_string('quantity'));
        v_weight_id:=v_weight_choice.get_string('choice_id');v_weight_uid:=v_weight_choice.get_string('source_uid');v_weight_cell:=v_weight_choice.get_string('source_cell');
       end if;
      end if;

      v_line_planned := 0;
      v_reserved_by_other := 0;
      v_requested_total := v_requested_total + v_requested_line_qty;

      insert into RRL_PICK_PLAN_LINE (
        PICK_PLAN_LINE_ID, PICK_PLAN_ID, CUSTOMER_ORDER_ROW_ID, ARTICUL,
        PRODUCT_NAME, REQUESTED_QTY, STATUS, CREATED_AT, CREATED_BY
      ) values (
        v_line_id, v_pick_plan_id, l.CUSTOMER_ORDER_ROW_ID, case when v_release='ACTIVE' then l.ARTICUL else upper(substr(l.ARTICUL, 1, 40)) end,
        l.PRODUCT_NAME, v_requested_line_qty, 'OPEN', sysdate, substr(p_created_by, 1, 50)
      );

      for c in (
        select r.rowid REMAIN_ROWID,
               r.CELL,
               r.UID_POLETA,
               r.REMAIN,
               p.EXPIRY_DATE,
               p.CREATION_DATE,
               p.PROD_BATCH_ID,
               p.SSCC,
               p.UNIT_COUNT,
               nvl(br.IS_SHIPMENT_ALLOWED, 1) IS_SHIPMENT_ALLOWED
          from RRL_REMAINS r
          join RRL_PALLETS p
            on p.UID_PALLET = r.UID_POLETA
          join RRL_CELLS cc on cc.CELL=r.CELL
          left join RRL_PROD_BATCH_READY_V br
            on br.PROD_BATCH_ID = p.PROD_BATCH_ID
         where r.REMAIN > 0
           and(v_weight_id is null or(r.UID_POLETA=v_weight_uid and r.CELL=v_weight_cell))
           and (v_release!='ACTIVE' or (cc.WARE_ID=v_order.WARE_ID and nvl(cc.BLOCKED_FOR_REMAINS,0)=0 and nvl(cc.BLOCKED_FOR_POPOLNENIE,0)=0 and r.BASE_UOM=v_uom))
           and ((v_release='ACTIVE' and p.ARTICUL=l.ARTICUL) or (v_release!='ACTIVE' and upper(p.ARTICUL)=upper(l.ARTICUL)))
           and (v_release!='ACTIVE' or RRL_STOCK_ELIGIBILITY.reason(r.UID_POLETA,r.CELL,v_order.WARE_ID,0,null,null,'ALLOCATE',null,p.ARTICUL) is null)
         order by case when v_strategy = 'FEFO' then p.EXPIRY_DATE end nulls last,
                  case when v_strategy = 'FIFO' then p.CREATION_DATE end nulls last,
                  r.TIME_OF_LAST_UPDATE nulls last,
                  r.UID_POLETA
      ) loop
        exit when v_remaining <= 0;
        if v_release='ACTIVE'then
         begin RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',c.UID_POLETA));
         exception when others then if sqlcode=-20850 then raise_application_error(-20890,'PICK_PLAN_SOURCE_CHANGED_RETRY');else raise;end if;end;
        end if;

        declare
          v_locked_remain number;
        begin
          if v_release='ACTIVE' then
           select REMAIN-HARD_RESERVED_BASE into v_locked_remain from RRL_REMAINS where rowid=c.REMAIN_ROWID;
          else
          select REMAIN
            into v_locked_remain
            from RRL_REMAINS
           where rowid = c.REMAIN_ROWID
           for update;
          end if;

          if c.IS_SHIPMENT_ALLOWED = 0 then
            log_decision(
              v_pick_plan_id,
              v_line_id,
              'SKIP_NOT_READY',
              'Pallet skipped because batch is not allowed for shipment',
              '{"pallet":"' || replace(c.UID_POLETA, '"', '\"') || '"}',
              p_created_by
            );
          else
            v_candidate_available := greatest(nvl(v_locked_remain, 0) - active_reserved_qty(c.UID_POLETA, l.ARTICUL, c.CELL), 0);
            v_reserved_by_other := v_reserved_by_other + (nvl(v_locked_remain, 0) - v_candidate_available);

            if v_candidate_available > 0 then
              v_reserve_qty := least(v_remaining, v_candidate_available);
              if v_weight_id is not null and v_reserve_qty!=RRL_STOCK_MATH.quantity(v_weight_choice.get_string('quantity'))then
               raise_application_error(-20886,'WEIGHT_PLAN_SELECTED_WHOLE_BOX_SOURCE_NOT_FREE');end if;

              if (v_release='ACTIVE' and v_reserve_qty=c.REMAIN and v_locked_remain=c.REMAIN
                  and active_reserved_qty(c.UID_POLETA,l.ARTICUL,c.CELL)=0)
                 or (v_release!='ACTIVE' and v_reserve_qty>=v_candidate_available) then
                v_task_type := 'FULL_PALLET';
              else
                v_task_type := 'CASE_PICK';
              end if;

              v_target_cell := null;
              v_pick_sequence := null;
              v_pick_face_id := null;
              v_pick_route_cell_id := null;

              if v_task_type = 'CASE_PICK' then
                if RRL_DIRECT_RECEIVING_PICK.enabled(c.UID_POLETA,c.CELL,v_order.WARE_ID,l.ARTICUL)=0 then
                RRL_PICK_TOPOLOGY_API.resolve_pick_face(
                  p_ware_id => v_order.WARE_ID,
                  p_articul => l.ARTICUL,
                  p_target_cell => v_target_cell,
                  p_pick_sequence => v_pick_sequence,
                  p_pick_face_id => v_pick_face_id,
                  p_pick_route_cell_id => v_pick_route_cell_id
                );

                end if;
                if v_target_cell is not null then
                  log_decision(
                    v_pick_plan_id,
                    v_line_id,
                    'PICK_FACE_SELECTED',
                    'Case-pick task assigned to configured pick face',
                    '{"articul":"' || replace(l.ARTICUL, '"', '\"') || '","targetCell":"' || replace(v_target_cell, '"', '\"') || '"}',
                    p_created_by
                  );
                else
                  log_decision(
                    v_pick_plan_id,
                    v_line_id,
                    case when RRL_DIRECT_RECEIVING_PICK.enabled(c.UID_POLETA,c.CELL,v_order.WARE_ID,l.ARTICUL)=1 then 'DIRECT_RECEIVING_SOURCE'else 'NO_PICK_FACE'end,
                    case when RRL_DIRECT_RECEIVING_PICK.enabled(c.UID_POLETA,c.CELL,v_order.WARE_ID,l.ARTICUL)=1 then 'Pick-by-line from admitted SAP receiving pallet; no replenishment'else 'No active pick face found for case-pick task'end,
                    '{"articul":"' || replace(l.ARTICUL, '"', '\"') || '"}',
                    p_created_by
                  );
                end if;
              end if;

              select RRL_PICK_TASK_SQ.nextval into v_task_id from dual;
              insert into RRL_PICK_TASK (
                PICK_TASK_ID, PICK_PLAN_ID, PICK_PLAN_LINE_ID, CUSTOMER_ORDER_ID, CUSTOMER_ID,
                TASK_TYPE, STATUS, ARTICUL, PALLET_UID, SSCC, PROD_BATCH_ID,
                SOURCE_CELL_CODE, TARGET_CELL_CODE, QTY, PICK_SEQUENCE,
                PICK_FACE_ID, PICK_ROUTE_CELL_ID, CREATED_AT, CREATED_BY
              ) values (
                v_task_id, v_pick_plan_id, v_line_id, p_customer_order_id, v_order.CUSTOMER_ID,
                v_task_type, 'NEW', case when v_release='ACTIVE' then l.ARTICUL else upper(substr(l.ARTICUL, 1, 40)) end, c.UID_POLETA,
                c.SSCC, c.PROD_BATCH_ID, c.CELL, v_target_cell, v_reserve_qty,
                v_pick_sequence, v_pick_face_id, v_pick_route_cell_id, sysdate, substr(p_created_by, 1, 50)
              );

              insert into RRL_PICK_RESERVATION (
                PICK_RESERVATION_ID, PICK_PLAN_ID, PICK_PLAN_LINE_ID, PICK_TASK_ID,
                CUSTOMER_ORDER_ID, CUSTOMER_ID, RESERVATION_LEVEL, RESERVATION_STATUS,
                RESERVATION_SCOPE, PALLET_UID, SSCC, ARTICUL, PROD_BATCH_ID,
                SOURCE_CELL_CODE, RESERVED_QTY, CREATED_AT, CREATED_BY
              ) values (
                RRL_PICK_RESERVATION_SQ.nextval, v_pick_plan_id, v_line_id, v_task_id,
                p_customer_order_id, v_order.CUSTOMER_ID, 'SOFT', 'ACTIVE',
                case when v_task_type = 'FULL_PALLET' then 'PALLET' else 'CASE' end,
                c.UID_POLETA, c.SSCC, case when v_release='ACTIVE' then l.ARTICUL else upper(substr(l.ARTICUL, 1, 40)) end, c.PROD_BATCH_ID,
                c.CELL, v_reserve_qty, sysdate, substr(p_created_by, 1, 50)
              );

              v_line_planned := v_line_planned + v_reserve_qty;
              v_remaining := v_remaining - v_reserve_qty;
            end if;
          end if;
        exception
          when no_data_found then
            null;
        end;
      end loop;

      v_line_shortage := greatest(v_requested_line_qty - v_line_planned, 0);
      v_planned_total := v_planned_total + v_line_planned;
      v_shortage_total := v_shortage_total + v_line_shortage;

      update RRL_PICK_PLAN_LINE
         set PLANNED_QTY = v_line_planned,
             FULL_PALLET_QTY = nvl((
               select sum(QTY)
                 from RRL_PICK_TASK
                where PICK_PLAN_LINE_ID = v_line_id
                  and TASK_TYPE = 'FULL_PALLET'
             ), 0),
             CASE_PICK_QTY = nvl((
               select sum(QTY)
                 from RRL_PICK_TASK
                where PICK_PLAN_LINE_ID = v_line_id
                  and TASK_TYPE = 'CASE_PICK'
             ), 0),
             SHORTAGE_QTY = v_line_shortage,
             STATUS = case
               when v_line_shortage = 0 then 'PLANNED_FULL'
               when v_line_planned > 0 then 'PLANNED_PARTIAL'
               else 'NO_STOCK'
             end,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_created_by, 1, 50)
       where PICK_PLAN_LINE_ID = v_line_id;

      if v_weight_id is not null then
       RRL_WEIGHT_PLAN_BIND.finish_bind(v_weight_id,v_pick_plan_id,v_line_id,p_created_by);
       log_decision(v_pick_plan_id,v_line_id,'WEIGHT_BOX_CHOICE','Approved exact whole-box planning target',v_weight_wire,p_created_by);
      end if;
      if v_line_shortage > 0 then
        insert into RRL_PICK_SHORTAGE (
          PICK_SHORTAGE_ID, PICK_PLAN_ID, PICK_PLAN_LINE_ID,
          CUSTOMER_ORDER_ID, CUSTOMER_ORDER_ROW_ID, CUSTOMER_ID, ARTICUL,
          REQUESTED_QTY, AVAILABLE_QTY, RESERVED_BY_OTHER_QTY, PLANNED_QTY,
          SHORTAGE_QTY, REASON_CODE, REASON_TEXT, CREATED_AT, CREATED_BY
        ) values (
          RRL_PICK_SHORTAGE_SQ.nextval, v_pick_plan_id, v_line_id,
          p_customer_order_id, l.CUSTOMER_ORDER_ROW_ID, v_order.CUSTOMER_ID,
          case when v_release='ACTIVE' then l.ARTICUL else upper(substr(l.ARTICUL, 1, 40)) end, v_requested_line_qty,
          v_line_planned, v_reserved_by_other, v_line_planned,
          v_line_shortage, case when v_weight_id is not null then 'WEIGHT_BOX_CHOICE_PENDING'else 'NO_FREE_STOCK'end,
          case when v_weight_id is not null then 'Approved final whole-box deviation; physical execution pending'else 'Free stock is not enough after active reservations'end,
          sysdate, substr(p_created_by, 1, 50)
        );
      end if;
    end loop;

    if v_release='ACTIVE'and v_requested_total=0 then raise_application_error(-20886,'PICK_ORDER_DEMAND_ALREADY_PLANNED_OR_SECURED');end if;
    if v_requested_total = 0 then
      v_status := 'NO_STOCK';
    elsif v_planned_total = 0 then
      v_status := 'NO_STOCK';
    elsif v_shortage_total > 0 then
      v_status := 'PLANNED_PARTIAL';
    else
      v_status := 'PLANNED_FULL';
    end if;

    update RRL_PICK_PLAN
       set STATUS = v_status,
           TOTAL_ORDER_QTY = v_requested_total,
           TOTAL_PLANNED_QTY = v_planned_total,
           TOTAL_SHORTAGE_QTY = v_shortage_total,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_created_by, 1, 50)
     where PICK_PLAN_ID = v_pick_plan_id;

    log_decision(
      v_pick_plan_id,
      null,
      'PLAN_CREATED',
      'Picking plan created with soft reservations',
      '{"requested":' || to_char(v_requested_total) || ',"planned":' || to_char(v_planned_total) || ',"shortage":' || to_char(v_shortage_total) || '}',
      p_created_by
    );

    if v_fenced then RRL_PICK_PLAN_ADMISSION.end_plan;end if;
    return v_pick_plan_id;
  exception when others then
    if v_mutating then rollback to rrl_pick_plan_begin;end if;
    if v_fenced then RRL_PICK_PLAN_ADMISSION.end_plan;end if;
    raise;
  end create_plan;

  procedure cancel_plan(
    p_pick_plan_id number,
    p_updated_by   varchar2 default null
  ) is
  begin
    declare st varchar2(20);j json_object_t:=json_object_t();src json_object_t:=json_object_t();m json_object_t:=json_object_t();result clob;kind varchar2(80);request clob;doc number;
    begin
      select STATE into st from RRL_STOCK_RELEASE where RELEASE_ID=1;
      if st='ACTIVE' then
        if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is not null then
          select COMMAND_TYPE,CANONICAL_REQUEST into kind,request from RRL_STOCK_OPERATION where OPERATION_ID=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');
          doc:=json_object_t.parse(request).get_object('source').get_number('document_id');
          if kind!='PICK_PLAN_CANCEL' or doc!=p_pick_plan_id then raise_application_error(-20863,'PLAN_CANCEL_CONTEXT_CONFLICT');end if;
        else
          j.put('contract_version',2);j.put('operation_id','PLAN.CANCEL:'||to_char(p_pick_plan_id,'TM9'));j.put('command_type','PICK_PLAN_CANCEL');j.put('actor',p_updated_by);
          src.put('document_type','PICK_PLAN');src.put('document_id',p_pick_plan_id);j.put('source',src);j.put('lines',json_array_t());j.put('units',json_array_t());
          m.put('reason','Picking plan cancelled');m.put('only_cancelled_replenishment',0);m.put_null('reservation_kind');j.put('metadata',m);
          RRL_STOCK_NATIVE_API.post(j.to_clob,p_updated_by,result);return;
        end if;
      end if;
    end;

    update RRL_PICK_RESERVATION
       set RESERVATION_STATUS = 'RELEASED',
           RELEASED_AT = sysdate,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_PLAN_ID = p_pick_plan_id
       and RESERVATION_STATUS = 'ACTIVE';

    update RRL_PICK_TASK
       set STATUS = 'CANCELLED',
           ERROR_TEXT = 'Plan cancelled before execution',
           UPDATED_AT = sysdate
     where PICK_PLAN_ID = p_pick_plan_id
       and STATUS in ('NEW', 'ASSIGNED');

    update RRL_PICK_PLAN
       set STATUS = 'CANCELLED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_PLAN_ID = p_pick_plan_id
       and STATUS not in ('DONE');

    log_decision(
      p_pick_plan_id,
      null,
      'PLAN_CANCELLED',
      'Picking plan cancelled and active reservations released',
      null,
      p_updated_by
    );
  end cancel_plan;
end RRL_PICKING_API;
/


CREATE OR REPLACE package body RRL_PICK_PLAN_ACCESS as
 procedure assert_scope(p_order number,p_actor varchar2,p_permission varchar2 default 'pick_plan_create')is
  ware number;uware number;grp varchar2(100);n number;
 begin
  begin select WARE_ID into ware from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=p_order;
  exception when no_data_found then raise_application_error(-20886,'PICK_ORDER_IDENTITY_MISSING');end;
  if ware is null or ware<1 then raise_application_error(-20886,'PICK_ORDER_WARE_REQUIRED');end if;
  select count(*),max(WARE_ID),max(USER_GROUP)into n,uware,grp from RUSERS where ID=p_actor and nvl(DELETED,0)=0;
  if n!=1 then raise_application_error(-20882,'PICK_PLAN_ACTIVE_UNIQUE_ACTOR_REQUIRED');end if;
  if nvl(upper(trim(grp)),'-')!='GLOBAL_ADMIN'and(uware is null or uware!=ware)then raise_application_error(-20882,'PICK_PLAN_CURRENT_WARE_FORBIDDEN');end if;
  if p_permission is null or RRL_HAS_WRIGHT(p_actor,p_permission)!=1 then raise_application_error(-20882,'PICK_PLAN_PERMISSION_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_PICK_PLAN_ADMISSION as
 procedure actor_scope(p_order number,p_actor varchar2)is begin RRL_PICK_PLAN_ACCESS.assert_scope(p_order,p_actor);end;
 procedure begin_plan(p_order number,p_actor varchar2)is
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();ware number;state varchar2(20);
  n number:=0;article_count number:=0;stock_count number:=0;task_count number:=0;v_started boolean:=false;
 begin
  actor_scope(p_order,p_actor);
  select WARE_ID into ware from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=p_order;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(p_order));
  for line in(select CUSTOMER_ORDER_ROW_ID,ARTICUL from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ID=p_order and STATUS!='CANCELLED'
   order by CUSTOMER_ORDER_ROW_ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20881,'PICK_PLAN_ROW_BOUND_200');end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_ROW',RRL_STOCK_PLAN_HELPER.decimal_text(line.CUSTOMER_ORDER_ROW_ID));
   RRL_STOCK_PLAN_HELPER.fence(f,'SKU',line.ARTICUL);
   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','PICK.PLAN.WARESKU:'||RRL_STOCK_PLAN_HELPER.decimal_text(ware)||':'||line.ARTICUL);
  end loop;
  for pt in(select pt.PICK_TASK_ID,pt.PICK_PLAN_ID,pt.PICK_PLAN_LINE_ID from RRL_PICK_TASK pt join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=pt.PICK_PLAN_LINE_ID
   join RRL_CUSTOMER_ORDER_ROW cr on cr.CUSTOMER_ORDER_ROW_ID=pl.CUSTOMER_ORDER_ROW_ID where cr.CUSTOMER_ORDER_ID=p_order
   order by pt.PICK_TASK_ID fetch first 2001 rows only)loop
   task_count:=task_count+1;if task_count>2000 then raise_application_error(-20881,'PICK_PLAN_HISTORY_TASK_BOUND_2000');end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(pt.PICK_TASK_ID));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(pt.PICK_PLAN_ID));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_PLAN_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(pt.PICK_PLAN_LINE_ID));
  end loop;
  for wave in(select distinct wo.PICK_WAVE_ID from RRL_PICK_WAVE_ORDER wo where wo.CUSTOMER_ORDER_ID=p_order order by wo.PICK_WAVE_ID fetch first 201 rows only)loop
   article_count:=article_count+1;if article_count>200 then raise_application_error(-20881,'PICK_PLAN_WAVE_HISTORY_BOUND_200');end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(wave.PICK_WAVE_ID));
  end loop;
  for stock in(select s.UID_POLETA,s.CELL from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA
   join RRL_CELLS c on c.CELL=s.CELL where c.WARE_ID=ware and s.REMAIN>0 and exists(
    select 1 from RRL_CUSTOMER_ORDER_ROW cr where cr.CUSTOMER_ORDER_ID=p_order and cr.ARTICUL=p.ARTICUL and cr.STATUS!='CANCELLED')
   order by s.UID_POLETA,s.CELL fetch first 501 rows only)loop
   stock_count:=stock_count+1;if stock_count>500 then raise_application_error(-20881,'PICK_PLAN_SOURCE_STOCK_BOUND_500');end if;
   RRL_STOCK_PLAN_HELPER.anchor(r,50,'STOCK',stock.UID_POLETA);
  end loop;
  if RRL_PICK_PLAN_CREATE_API.current_operation is not null then RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',RRL_PICK_PLAN_CREATE_API.current_operation);end if;
  RRL_STOCK_LOCK_API.begin_plan;v_started:=true;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(r.to_clob);
  select STATE into state from RRL_STOCK_RELEASE where RELEASE_ID=1;
  if state!='ACTIVE'or state is null then raise_application_error(-20860,'PICK_PLAN_ACTIVE_RELEASE_REQUIRED');end if;
  actor_scope(p_order,p_actor);
 exception when others then if v_started then RRL_STOCK_LOCK_API.clear_plan;end if;raise;
 end;
 procedure end_plan is begin RRL_STOCK_LOCK_API.clear_plan;end;
end;
/


CREATE OR REPLACE package body RRL_PICK_PLAN_CREATE_API as
 g_operation varchar2(100);g_tx varchar2(100);g_hash varchar2(64);g_actor varchar2(100);g_ware number;
 function current_operation return varchar2 is begin return g_operation;end;
 function cached_plan return number is v RRL_PICK_PLAN_CREATE_OP%rowtype;begin
 if g_operation is null then return null;end if;
 begin select *into v from RRL_PICK_PLAN_CREATE_OP where OPERATION_ID=g_operation;exception when no_data_found then return null;end;
 if v.REQUEST_HASH!=g_hash or v.ACTOR!=g_actor or v.WARE_ID!=g_ware then raise_application_error(-20886,'PICK_CREATE_OPERATION_CONTENT_CONFLICT');end if;
 if v.PICK_PLAN_ID is null then raise_application_error(-20886,'PICK_CREATE_SAVED_RESULT_REQUIRED');end if;return v.PICK_PLAN_ID;end;
 procedure assert_write(p_operation varchar2)is
 begin
  if g_operation is null or g_operation!=p_operation or g_tx is null or g_tx!=dbms_transaction.local_transaction_id(false)then
   raise_application_error(-20863,'PICK_CREATE_ONLY_COMMAND_WRITER');end if;
 end;
 function create_command(p_operation varchar2,p_order number,p_strategy varchar2,p_actor varchar2)return number is
  strategy_value varchar2(30):=upper(trim(nvl(p_strategy,'FEFO')));ware_no number;plan_no number;request_hash varchar2(64);
  cached RRL_PICK_PLAN_CREATE_OP%rowtype;n number;inserted boolean:=false;
  function saved_result return number is
  begin
   select *into cached from RRL_PICK_PLAN_CREATE_OP where OPERATION_ID=p_operation;
   if cached.REQUEST_HASH!=request_hash or cached.ACTOR!=p_actor then raise_application_error(-20886,'PICK_CREATE_OPERATION_CONTENT_CONFLICT');end if;
   if cached.WARE_ID!=ware_no then raise_application_error(-20886,'PICK_CREATE_ORDER_WARE_CHANGED');end if;
   if cached.PICK_PLAN_ID is null then raise_application_error(-20886,'PICK_CREATE_SAVED_RESULT_REQUIRED');end if;
   return cached.PICK_PLAN_ID;
  end;
 begin
  if p_operation is null or length(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_order is null or p_order<1 or p_order!=trunc(p_order)
   or strategy_value not in('FEFO','FIFO')or p_actor is null then raise_application_error(-20886,'PICK_CREATE_EXPLICIT_IDENTITY_REQUIRED');end if;
  begin select WARE_ID into ware_no from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=p_order;
  exception when no_data_found then raise_application_error(-20886,'PICK_ORDER_IDENTITY_MISSING');end;
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'pick_plan_create')=1
   and(WARE_ID=ware_no or upper(trim(USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 or ware_no is null then raise_application_error(-20882,'PICK_CREATE_CURRENT_WARE_ACTOR_REQUIRED');end if;
  request_hash:=rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(to_char(p_order,'TM9')||':'||strategy_value||':'||p_actor,'AL32UTF8'),sys.dbms_crypto.hash_sh256));
  select count(*)into n from RRL_PICK_PLAN_CREATE_OP where OPERATION_ID=p_operation;
  if n=1 then return saved_result;end if;
  select count(*)into n from RRL_STOCK_RELEASE where RELEASE_ID=1 and STATE='ACTIVE';
  if n!=1 then raise_application_error(-20860,'PICK_CREATE_ACTIVE_REQUIRED');end if;
  inserted:=false;
  g_operation:=p_operation;g_hash:=request_hash;g_actor:=p_actor;g_ware:=ware_no;
  plan_no:=RRL_PICKING_API.create_plan(p_order,strategy_value,p_actor);inserted:=true;
  select count(*)into n from RRL_PICK_PLAN_CREATE_OP where OPERATION_ID=p_operation;
  if n=0 then
   g_tx:=dbms_transaction.local_transaction_id(false);
   insert into RRL_PICK_PLAN_CREATE_OP(OPERATION_ID,REQUEST_HASH,ACTOR,CUSTOMER_ORDER_ID,WARE_ID,PLAN_STRATEGY,PICK_PLAN_ID)
    values(p_operation,request_hash,p_actor,p_order,ware_no,strategy_value,plan_no);
  end if;
  g_operation:=null;g_tx:=null;
  return plan_no;
 exception when others then
  g_operation:=null;g_tx:=null;
  if inserted then rollback to rrl_pick_plan_begin;end if;
  raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_PICK_RANGE_APPLY_CORE as
 procedure current_actor(p_actor varchar2,p_ware number)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0
   and(WARE_ID=p_ware or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(ID,'pick_topology_edit')=1;
  if n!=1 then raise_application_error(-20882,'PICK_RANGE_CURRENT_WARE_ACTOR_REQUIRED');end if;
 end;
 procedure candidate(p_face number,p_ware number,p_weight number,p_row out RRL_PICK_FACE%rowtype)is n number;
 begin
  select *into p_row from RRL_PICK_FACE where PICK_FACE_ID=p_face and WARE_ID=p_ware for update;
  if p_row.ACTIVE!=1 or(p_row.PICK_FACE_TYPE!='DYNAMIC'and p_row.ALLOW_DYNAMIC_ASSIGNMENT!=1)
   or p_row.MAX_VOLUME is null or p_row.MAX_WEIGHT is null or p_row.MAX_WEIGHT<p_weight then
   raise_application_error(-20886,'PICK_RANGE_CURRENT_FACE_CAPACITY_REQUIRED');end if;
  select count(*)into n from RRL_CELLS c join RRL_PICK_ROUTE r on r.PICK_ROUTE_ID=p_row.PICK_ROUTE_ID
   and r.WARE_ID=c.WARE_ID and r.ACTIVE=1 and r.STATUS='PUBLISHED'
   join RRL_PICK_ROUTE_CELL rc on rc.PICK_ROUTE_CELL_ID=p_row.PICK_ROUTE_CELL_ID and rc.PICK_ROUTE_ID=r.PICK_ROUTE_ID
    and rc.WARE_ID=c.WARE_ID and rc.CELL_CODE=c.CELL and rc.ACTIVE=1
   where c.CELL=p_row.CELL_CODE and c.WARE_ID=p_ware and c.OTBOR=1 and nvl(c.IS_SYSTEM,0)=0
    and nvl(c.BLOCKED_FOR_REMAINS,0)=0 and nvl(c.BLOCKED_FOR_POPOLNENIE,0)=0;
  if n!=1 then raise_application_error(-20886,'PICK_RANGE_CURRENT_PUBLISHED_ROUTE_REQUIRED');end if;
  select (select count(*)from RRL_PICK_FACE_ARTICUL where PICK_FACE_ID=p_face and ACTIVE=1)
   +(select count(*)from RRL_PICK_FACE_ASSIGNMENT where CELL_CODE=p_row.CELL_CODE and STATUS='ACTIVE')
   +(select count(*)from RRL_REMAINS where CELL=p_row.CELL_CODE and(REMAIN>0 or HARD_RESERVED_BASE>0))
   +(select count(*)from RRL_WAREHOUSE_TASK where(TO_CELL=p_row.CELL_CODE or FROM_CELL=p_row.CELL_CODE)and STATUS not in('DONE','CANCELLED'))
   +(select count(*)from RRL_PICK_WAVE_REPLENISH_TASK where TARGET_CELL_CODE=p_row.CELL_CODE and STATUS not in('DONE','CANCELLED','FAILED'))
   +(select count(*)from RRL_CASE_PICK_LINE l join RRL_CASE_PICK_TASK t on t.CASE_PICK_TASK_ID=l.CASE_PICK_TASK_ID
      where l.CELL_CODE=p_row.CELL_CODE and t.STATUS not in('DONE','CANCELLED')and l.PLANNED_QTY>nvl(l.PICKED_QTY,0))
   into n from dual;
  if n!=0 then raise_application_error(-20886,'PICK_RANGE_CANDIDATE_NO_LONGER_EMPTY');end if;
 end;
 procedure clone_template(p_template RRL_PICK_FACE_ARTICUL%rowtype,p_face number,p_actor varchar2,p_mapping out number)is
 begin
  p_mapping:=RRL_PICK_TOPOLOGY_API.assign_articul(null,p_face,p_template.ARTICUL,p_template.PRIORITY,
   p_template.MIN_QTY,p_template.MAX_QTY,1,1,p_template.VALID_FROM,p_template.VALID_TO,p_actor);
  update RRL_PICK_FACE_ARTICUL set REPLENISHMENT_METHOD=p_template.REPLENISHMENT_METHOD,
   REPLENISHMENT_QTY_MODE=p_template.REPLENISHMENT_QTY_MODE,MIN_TRIGGER_BOX_QTY=p_template.MIN_TRIGGER_BOX_QTY,
   MIN_TRIGGER_LAYER_QTY=p_template.MIN_TRIGGER_LAYER_QTY,BOXES_PER_LAYER=p_template.BOXES_PER_LAYER,
   BOXES_PER_PALLET=p_template.BOXES_PER_PALLET,BOX_VOLUME_M3=p_template.BOX_VOLUME_M3,
   ALLOW_PARTIAL_PALLET=p_template.ALLOW_PARTIAL_PALLET,USE_ARTICUL_REPLENISH_RULE=p_template.USE_ARTICUL_REPLENISH_RULE,
   REPLENISHMENT_RELEASE_POLICY=p_template.REPLENISHMENT_RELEASE_POLICY,SAFETY_LAYER_QTY=p_template.SAFETY_LAYER_QTY,
   PREDICTIVE_BUFFER_MIN=p_template.PREDICTIVE_BUFFER_MIN,PICK_RATE_SOURCE=p_template.PICK_RATE_SOURCE,
   RECHECK_ON_PICK_EVENT=p_template.RECHECK_ON_PICK_EVENT where PICK_FACE_ARTICUL_ID=p_mapping;
 end;
 procedure approve(p_operation varchar2,p_actor varchar2,p_ware number,p_article varchar2,
  b json_object_t,s json_object_t,p_result out clob)is
  proposal RRL_PICK_RANGE_PROPOSAL%rowtype;t RRL_PICK_FACE_ARTICUL%rowtype;f RRL_PICK_FACE%rowtype;
  recommendation json_object_t;refs json_array_t;selected json_array_t;old_faces json_array_t;
  x json_object_t;j json_object_t:=json_object_t();new_ids json_array_t:=json_array_t();old_ids json_array_t:=json_array_t();
  identity varchar2(100);n number;mapping number;weight number;multiple number;num number;den number;boxes number;q number;v_proof clob;v_face number;v_cell varchar2(100);layout json_object_t;
 begin
  identity:=b.get_string('proposal_id');
  select *into proposal from RRL_PICK_RANGE_PROPOSAL where PROPOSAL_ID=identity for update;
  current_actor(p_actor,p_ware);
  if proposal.WARE_ID!=p_ware or proposal.ARTICLE!=p_article then raise_application_error(-20882,'PICK_RANGE_PROPOSAL_SCOPE_CONFLICT');end if;
  select(select count(*)from RRL_PICK_RANGE_CANCEL where PROPOSAL_ID=identity)
    +(select count(*)from RRL_PICK_RANGE_APPROVAL where PROPOSAL_ID=identity)into n from dual;
  if n!=0 then raise_application_error(-20886,'PICK_RANGE_PROPOSAL_NOT_CURRENT_DRAFT');end if;
  if s.get_string('source_signature')is null or s.get_string('source_signature')!=proposal.SOURCE_SIGNATURE
   or s.get_string('status')is null or s.get_string('status')!='SCENARIO_ONLY'
   or s.get_string('undated_unpicked_quantity')is null or not regexp_like(s.get_string('undated_unpicked_quantity'),'^0([.]0+)?$') then
   raise_application_error(-20886,'PICK_RANGE_COMPLETE_CURRENT_PERIOD_REQUIRED');end if;
  if b.get_boolean('geometry_checked')is null or not b.get_boolean('geometry_checked')
   or b.get_boolean('product_compatibility_checked')is null or not b.get_boolean('product_compatibility_checked')then
   raise_application_error(-20881,'PICK_RANGE_OPERATOR_LAYOUT_INSPECTION_REQUIRED');end if;
  recommendation:=s.get_object('range_recommendation');selected:=recommendation.get_array('selected_faces');
  refs:=recommendation.get_array('reference_templates');layout:=s.get_object('existing_range');old_faces:=layout.get_array('cells');
  if recommendation.get_string('status')!='NOMINAL_RECOMMENDATION'or selected.get_size not between 1 and 100
   or refs.get_size<1 or old_faces.get_size not between 1 and 100 then
   raise_application_error(-20886,'PICK_RANGE_COMPLETE_NOMINAL_SELECTION_REQUIRED');end if;
  x:=treat(refs.get(0)as json_object_t);v_face:=x.get_number('pick_face_id');
  select a.*into t from RRL_PICK_FACE_ARTICUL a join RRL_PICK_FACE pf on pf.PICK_FACE_ID=a.PICK_FACE_ID
   where a.PICK_FACE_ID=v_face and a.ARTICUL=p_article and a.ACTIVE=1 and pf.WARE_ID=p_ware;
  if t.VALID_FROM is null or trunc(t.VALID_FROM)>trunc(sysdate)or(t.VALID_TO is not null and trunc(t.VALID_TO)<trunc(sysdate))then
   raise_application_error(-20886,'PICK_RANGE_CURRENT_TEMPLATE_DATE_REQUIRED');end if;
  select PALLET_MULTIPLE into multiple from RRL_ARTICULS where ACTICUL=p_article;
  select NUMERATOR,DENOMINATOR into num,den from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM='BOX'
   and POLICY_VERSION=(select max(POLICY_VERSION)from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM='BOX');
  select coalesce(case when t.USE_ARTICUL_REPLENISH_RULE=1 then ar.BOXES_PER_PALLET end,t.BOXES_PER_PALLET)into boxes
   from dual left join RRL_ARTICUL_REPLENISH_RULE ar on ar.ARTICUL=p_article;
  if multiple is null or multiple<=0 or boxes is null or boxes<=0 or num<=0 or den<=0 or boxes*num/den!=multiple then
   raise_application_error(-20886,'PICK_RANGE_PALLET_BASE_NORM_NOT_COHERENT');end if;
  x:=treat(selected.get(0)as json_object_t);weight:=RRL_STOCK_MATH.quantity(x.get_string('declared_pallet_gross_weight_kg'));
  if weight<=0 then raise_application_error(-20881,'PICK_RANGE_GROSS_WEIGHT_REQUIRED');end if;
  for i in 0..selected.get_size-1 loop
   x:=treat(selected.get(i)as json_object_t);candidate(x.get_number('pick_face_id'),p_ware,weight,f);
  end loop;
  current_actor(p_actor,p_ware);
  v_proof:=s.to_clob;
  insert into RRL_PICK_RANGE_APPROVAL(PROPOSAL_ID,OPERATION_ID,WARE_ID,ARTICLE,PROOF_JSON)
   values(identity,p_operation,p_ware,p_article,v_proof);
  for i in 0..selected.get_size-1 loop
   x:=treat(selected.get(i)as json_object_t);
   if RRL_STOCK_MATH.quantity(x.get_string('nominal_pallet_base_quantity'))!=multiple then
    raise_application_error(-20886,'PICK_RANGE_NOMINAL_PALLET_CHANGED');end if;
   candidate(x.get_number('pick_face_id'),p_ware,weight,f);
   clone_template(t,f.PICK_FACE_ID,p_actor,mapping);
   q:=RRL_STOCK_REPL_CAPACITY.unit_volume(f.CELL_CODE,p_article)*multiple;
   if q is null or q>f.MAX_VOLUME then raise_application_error(-20886,'PICK_RANGE_VOLUME_NO_LONGER_FITS');end if;
   merge into RRL_PICK_RANGE_STATUS d using(select mapping ID from dual)v on(d.PICK_FACE_ARTICUL_ID=v.ID)
    when matched then update set MODE_CODE='ACTIVE',APPROVAL_OPERATION_ID=p_operation
    when not matched then insert(PICK_FACE_ARTICUL_ID,MODE_CODE,APPROVAL_OPERATION_ID)values(mapping,'ACTIVE',p_operation);
   insert into RRL_PICK_RANGE_MEMBER(PROPOSAL_ID,PICK_FACE_ARTICUL_ID,ROLE_CODE)values(identity,mapping,'NEW');new_ids.append(mapping);
  end loop;
  for i in 0..old_faces.get_size-1 loop
   x:=treat(old_faces.get(i)as json_object_t);v_face:=x.get_number('pick_face_id');v_cell:=x.get_string('cell');
   select a.PICK_FACE_ARTICUL_ID into mapping from RRL_PICK_FACE_ARTICUL a join RRL_PICK_FACE f on f.PICK_FACE_ID=a.PICK_FACE_ID
    where a.PICK_FACE_ID=v_face and a.ARTICUL=p_article and a.ACTIVE=1 and f.WARE_ID=p_ware for update of a.ACTIVE;
   merge into RRL_PICK_RANGE_STATUS d using(select mapping ID from dual)v on(d.PICK_FACE_ARTICUL_ID=v.ID)
    when matched then update set MODE_CODE='DRAINING',APPROVAL_OPERATION_ID=p_operation
    when not matched then insert(PICK_FACE_ARTICUL_ID,MODE_CODE,APPROVAL_OPERATION_ID)values(mapping,'DRAINING',p_operation);
   insert into RRL_PICK_RANGE_ALLOW_REPL(PICK_FACE_ARTICUL_ID,DRAIN_OPERATION_ID,REPLENISH_TASK_ID,MAX_ORIGINAL_QTY)
    select mapping,p_operation,PICK_WAVE_REPLENISH_TASK_ID,QTY from RRL_PICK_WAVE_REPLENISH_TASK
     where TARGET_CELL_CODE=v_cell and ARTICUL=p_article and STATUS not in('DONE','CANCELLED','FAILED');
   insert into RRL_PICK_RANGE_MEMBER(PROPOSAL_ID,PICK_FACE_ARTICUL_ID,ROLE_CODE)values(identity,mapping,'OLD');old_ids.append(mapping);
  end loop;
  j.put('proposal_id',identity);j.put('status','APPROVED');j.put('new_mapping_ids',new_ids);j.put('draining_mapping_ids',old_ids);
  j.put('stock_changed',false);j.put('existing_task_assignments_changed',false);j.put('range_applied',true);p_result:=j.to_clob;
 end;
 procedure close_drain(p_operation varchar2,p_actor varchar2,p_ware number,p_article varchar2,
  b json_object_t,p_result out clob)is
  a RRL_PICK_FACE_ARTICUL%rowtype;f RRL_PICK_FACE%rowtype;s RRL_PICK_RANGE_STATUS%rowtype;n number;v_mapping number;j json_object_t:=json_object_t();
 begin
  v_mapping:=b.get_number('pick_face_articul_id');
  select *into a from RRL_PICK_FACE_ARTICUL where PICK_FACE_ARTICUL_ID=v_mapping for update;
  select *into f from RRL_PICK_FACE where PICK_FACE_ID=a.PICK_FACE_ID;
  if a.ARTICUL!=p_article or f.WARE_ID!=p_ware then raise_application_error(-20882,'PICK_RANGE_DRAIN_SCOPE_CONFLICT');end if;
  select *into s from RRL_PICK_RANGE_STATUS where PICK_FACE_ARTICUL_ID=a.PICK_FACE_ARTICUL_ID for update;
  current_actor(p_actor,p_ware);
  if s.MODE_CODE!='DRAINING'then raise_application_error(-20886,'PICK_RANGE_NOT_DRAINING');end if;
  select(select count(*)from RRL_REMAINS where CELL=f.CELL_CODE and(REMAIN>0 or HARD_RESERVED_BASE>0))
   +(select count(*)from RRL_WAREHOUSE_TASK where(TO_CELL=f.CELL_CODE or FROM_CELL=f.CELL_CODE)and STATUS not in('DONE','CANCELLED'))
   +(select count(*)from RRL_PICK_WAVE_REPLENISH_TASK where TARGET_CELL_CODE=f.CELL_CODE and ARTICUL=p_article and STATUS not in('DONE','CANCELLED','FAILED'))
   +(select count(*)from RRL_CASE_PICK_LINE l join RRL_CASE_PICK_TASK t on t.CASE_PICK_TASK_ID=l.CASE_PICK_TASK_ID
      where l.CELL_CODE=f.CELL_CODE and t.STATUS not in('DONE','CANCELLED')and l.PLANNED_QTY>nvl(l.PICKED_QTY,0))
   +(select count(*)from RRL_PICK_FACE_ASSIGNMENT where CELL_CODE=f.CELL_CODE and STATUS='ACTIVE')into n from dual;
  if n!=0 then raise_application_error(-20886,'PICK_RANGE_OLD_STOCK_OR_COMMITMENT_REMAINS');end if;
  n:=RRL_PICK_TOPOLOGY_API.assign_articul(a.PICK_FACE_ARTICUL_ID,a.PICK_FACE_ID,a.ARTICUL,a.PRIORITY,a.MIN_QTY,a.MAX_QTY,
   0,0,a.VALID_FROM,a.VALID_TO,p_actor);
  update RRL_PICK_RANGE_STATUS set MODE_CODE='CLOSED'where PICK_FACE_ARTICUL_ID=a.PICK_FACE_ARTICUL_ID;
  insert into RRL_PICK_RANGE_DRAIN_CLOSE(OPERATION_ID,PICK_FACE_ARTICUL_ID,FROM_APPROVAL_OPERATION_ID)
   values(p_operation,a.PICK_FACE_ARTICUL_ID,s.APPROVAL_OPERATION_ID);
  j.put('status','DRAIN_CLOSED');j.put('pick_face_articul_id',a.PICK_FACE_ARTICUL_ID);j.put('stock_changed',false);p_result:=j.to_clob;
 end;
 procedure apply_change(p_operation varchar2,p_actor varchar2,p_action varchar2,p_ware number,p_article varchar2,
  p_request clob,p_source clob,p_result out clob)is b json_object_t:=json_object_t.parse(p_request);s json_object_t;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
  if p_action='APPROVE'then s:=json_object_t.parse(p_source);approve(p_operation,p_actor,p_ware,p_article,b,s,p_result);
  elsif p_action='CLOSE_DRAIN'then close_drain(p_operation,p_actor,p_ware,p_article,b,p_result);
  else raise_application_error(-20881,'PICK_RANGE_APPLY_ACTION_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_PICK_RANGE_POLICY as
 function target_write_allowed(p_cell varchar2,p_article varchar2,p_repl number,p_quantity number)return number is
  n number;identity number;v_mode varchar2(20);operation varchar2(100);
 begin
  select count(*),max(s.PICK_FACE_ARTICUL_ID),max(s.MODE_CODE),max(s.APPROVAL_OPERATION_ID)
   into n,identity,v_mode,operation from RRL_PICK_RANGE_STATUS s
   join RRL_PICK_FACE_ARTICUL a on a.PICK_FACE_ARTICUL_ID=s.PICK_FACE_ARTICUL_ID
   join RRL_PICK_FACE f on f.PICK_FACE_ID=a.PICK_FACE_ID
   where f.CELL_CODE=p_cell and a.ARTICUL=p_article and s.MODE_CODE in('DRAINING','CLOSED');
  if n=0 then return 1;end if;
  if n!=1 or v_mode!='DRAINING'or p_repl is null or p_quantity is null then return 0;end if;
  select count(*)into n from RRL_PICK_RANGE_ALLOW_REPL where PICK_FACE_ARTICUL_ID=identity
   and DRAIN_OPERATION_ID=operation and REPLENISH_TASK_ID=p_repl and MAX_ORIGINAL_QTY>=p_quantity;
  return case when n=1 then 1 else 0 end;
 end;
 function new_target_allowed(p_cell varchar2,p_article varchar2,p_exclude_repl number default null)return number is
  q number;c varchar2(100);a varchar2(40);
 begin
  if p_exclude_repl is not null then
   begin
    select QTY,TARGET_CELL_CODE,ARTICUL into q,c,a from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=p_exclude_repl;
    if c!=p_cell or a!=p_article then return 0;end if;
   exception when no_data_found then return 0;end;
  end if;
  return target_write_allowed(p_cell,p_article,p_exclude_repl,q);
 end;
end;
/


CREATE OR REPLACE package body RRL_PICK_RANGE_PROPOSAL_API as
 g_tx varchar2(100);
 function write_allowed return number is begin
  if g_tx is not null and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;end;
 procedure current_actor(p_actor varchar2,p_ware number)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0
   and(WARE_ID=p_ware or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(ID,'pick_topology_edit')=1;
  if n!=1 then raise_application_error(-20882,'PICK_RANGE_CURRENT_WARE_ACTOR_REQUIRED');end if;
 end;
 procedure execute_command(p_operation varchar2,p_actor varchar2,p_action varchar2,p_ware number,p_article varchar2,
  p_request clob,p_source clob,p_result out clob)is
  b json_object_t:=json_object_t.parse(p_request);s json_object_t;j json_object_t:=json_object_t();
  digest varchar2(64);old RRL_PICK_RANGE_OPERATION%rowtype;proposal RRL_PICK_RANGE_PROPOSAL%rowtype;
  v_saved boolean:=false;n number;reason varchar2(2000);identity varchar2(100);sig varchar2(64);result clob;
 begin
  current_actor(p_actor,p_ware);
  if p_operation is null or lengthb(p_operation)>100 or p_article is null or lengthb(p_article)>40
   or p_action not in('SAVE_DRAFT','CANCEL_DRAFT','APPROVE','CLOSE_DRAIN')or p_action is null then
   raise_application_error(-20881,'PICK_RANGE_OPERATION_INPUT_REQUIRED');end if;
  digest:=lower(rawtohex(sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256)));
  current_actor(p_actor,p_ware);
  begin
   select *into old from RRL_PICK_RANGE_OPERATION where OPERATION_ID=p_operation;
   if old.REQUEST_HASH!=digest or old.ACTOR!=p_actor or old.ACTION_CODE!=p_action or old.WARE_ID!=p_ware or old.ARTICLE!=p_article then
    raise_application_error(-20886,'PICK_RANGE_OPERATION_CONTENT_CONFLICT');end if;
   p_result:=old.RESULT_JSON;return;
  exception when no_data_found then null;end;
  if p_action in('SAVE_DRAFT','APPROVE')and p_source is null then
   j.put('status','SOURCE_RECOMPUTATION_REQUIRED');p_result:=j.to_clob;return;
  end if;
  reason:=b.get_string('reason');
  if reason is null or length(reason)<8 then raise_application_error(-20881,'PICK_RANGE_REASON_REQUIRED');end if;
  select count(*)into n from RRL_ARTICULS where ACTICUL=p_article;
  if n!=1 then raise_application_error(-20886,'PICK_RANGE_ARTICLE_NOT_CURRENT');end if;
  if p_action in('APPROVE','CLOSE_DRAIN')then
   RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
   savepoint RRL_RANGE157;v_saved:=true;g_tx:=dbms_transaction.local_transaction_id(true);
   RRL_PICK_RANGE_APPLY_CORE.apply_change(p_operation,p_actor,p_action,p_ware,p_article,p_request,p_source,result);
   j:=json_object_t.parse(result);j.put('operation_id',p_operation);result:=j.to_clob;
   insert into RRL_PICK_RANGE_OPERATION(OPERATION_ID,ACTION_CODE,WARE_ID,ARTICLE,ACTOR,REQUEST_HASH,REQUEST_JSON,RESULT_JSON)
    values(p_operation,p_action,p_ware,p_article,p_actor,digest,p_request,result);
   p_result:=result;g_tx:=null;return;
  end if;
  if p_action='SAVE_DRAFT'then
   s:=json_object_t.parse(p_source);sig:=s.get_string('source_signature');
   if sig is null or not regexp_like(sig,'^[0-9a-f]{64}$')or b.get_string('expected_source_signature')is null or sig!=b.get_string('expected_source_signature')
    or s.get_number('warehouse_id')is null or s.get_string('article')is null
    or s.get_number('warehouse_id')!=p_ware or s.get_string('article')!=p_article then
    raise_application_error(-20886,'PICK_RANGE_SOURCE_PROOF_CONFLICT');end if;
   j:=s.get_object('range_recommendation');
   if j.get_string('status')is null or j.get_string('status')!='NOMINAL_RECOMMENDATION'
    or j.get_boolean('applied')is null or j.get_boolean('applied')then
    raise_application_error(-20886,'PICK_RANGE_COMPLETE_RECOMMENDATION_REQUIRED');end if;
   j:=json_object_t();identity:=p_operation;
   j.put('status','DRAFT');j.put('proposal_id',identity);j.put('source_signature',sig);
  else
   identity:=b.get_string('proposal_id');
   select *into proposal from RRL_PICK_RANGE_PROPOSAL where PROPOSAL_ID=identity for update;
   if proposal.WARE_ID!=p_ware or proposal.ARTICLE!=p_article then
    raise_application_error(-20882,'PICK_RANGE_PROPOSAL_SCOPE_CONFLICT');end if;
   select (select count(*)from RRL_PICK_RANGE_CANCEL where PROPOSAL_ID=identity)
    +(select count(*)from RRL_PICK_RANGE_APPROVAL where PROPOSAL_ID=identity)into n from dual;
   if n>0 then raise_application_error(-20886,'PICK_RANGE_PROPOSAL_NOT_CURRENT_DRAFT');end if;
   j.put('status','CANCELLED');j.put('proposal_id',identity);
  end if;
  j.put('operation_id',p_operation);j.put('stock_changed',false);j.put('range_applied',false);
  result:=j.to_clob;
  current_actor(p_actor,p_ware);
  savepoint RRL_RANGE157;v_saved:=true;g_tx:=dbms_transaction.local_transaction_id(true);
  begin
  insert into RRL_PICK_RANGE_OPERATION(OPERATION_ID,ACTION_CODE,WARE_ID,ARTICLE,ACTOR,REQUEST_HASH,REQUEST_JSON,RESULT_JSON)
   values(p_operation,p_action,p_ware,p_article,p_actor,digest,p_request,result);
  exception when dup_val_on_index then
   select *into old from RRL_PICK_RANGE_OPERATION where OPERATION_ID=p_operation;
   if old.REQUEST_HASH!=digest or old.ACTOR!=p_actor or old.ACTION_CODE!=p_action or old.WARE_ID!=p_ware or old.ARTICLE!=p_article then
    raise_application_error(-20886,'PICK_RANGE_OPERATION_CONTENT_CONFLICT');end if;
   p_result:=old.RESULT_JSON;g_tx:=null;return;
  end;
  if p_action='SAVE_DRAFT'then
   insert into RRL_PICK_RANGE_PROPOSAL(PROPOSAL_ID,WARE_ID,ARTICLE,SOURCE_SIGNATURE,SOURCE_JSON)
    values(identity,p_ware,p_article,sig,p_source);
  else
   insert into RRL_PICK_RANGE_CANCEL(PROPOSAL_ID,CANCEL_OPERATION_ID,REASON)values(identity,p_operation,reason);
  end if;
  p_result:=result;g_tx:=null;
 exception when others then
  if v_saved then rollback to RRL_RANGE157;end if;g_tx:=null;
  raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_PICK_TOPOLOGY_API as
  function norm_active(p_active number) return number is
  begin
    if nvl(p_active, 1) = 0 then
      return 0;
    end if;
    return 1;
  end;

  function upsert_route(
    p_pick_route_id number default null,
    p_route_code    varchar2,
    p_route_name    varchar2 default null,
    p_ware_id       number,
    p_route_kind    varchar2 default 'PICK',
    p_active        number default 1,
    p_updated_by    varchar2 default null
  ) return number is
    v_id number;
    v_kind varchar2(20);
  begin
    if p_route_code is null or p_ware_id is null then
      raise_application_error(-20970, 'route_code and ware_id are required');
    end if;

    v_kind := upper(nvl(p_route_kind, 'PICK'));
    if v_kind not in ('PICK', 'REPLENISHMENT', 'MIXED') then
      raise_application_error(-20971, 'unsupported route kind');
    end if;

    if p_pick_route_id is not null then
      v_id := p_pick_route_id;
      update RRL_PICK_ROUTE
         set ROUTE_CODE = upper(substr(p_route_code, 1, 50)),
             ROUTE_NAME = substr(p_route_name, 1, 255),
             WARE_ID = p_ware_id,
             ROUTE_KIND = v_kind,
             ACTIVE = case when nvl(p_active, 1) = 0 then 0 else 1 end,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_updated_by, 1, 50)
       where PICK_ROUTE_ID = v_id;
      if sql%rowcount = 0 then
        raise_application_error(-20972, 'pick route not found');
      end if;
      return v_id;
    end if;

    begin
      select PICK_ROUTE_ID
        into v_id
        from RRL_PICK_ROUTE
       where WARE_ID = p_ware_id
         and upper(ROUTE_CODE) = upper(p_route_code)
         and rownum = 1;

      update RRL_PICK_ROUTE
         set ROUTE_NAME = substr(p_route_name, 1, 255),
             ROUTE_KIND = v_kind,
             ACTIVE = case when nvl(p_active, 1) = 0 then 0 else 1 end,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_updated_by, 1, 50)
       where PICK_ROUTE_ID = v_id;
      return v_id;
    exception
      when no_data_found then
        select RRL_PICK_ROUTE_SQ.nextval into v_id from dual;
        insert into RRL_PICK_ROUTE (
          PICK_ROUTE_ID, WARE_ID, ROUTE_CODE, ROUTE_NAME, ROUTE_KIND,
          ACTIVE, CREATED_AT, CREATED_BY
        ) values (
          v_id, p_ware_id, upper(substr(p_route_code, 1, 50)),
          substr(p_route_name, 1, 255), v_kind,
          case when nvl(p_active, 1) = 0 then 0 else 1 end, sysdate, substr(p_updated_by, 1, 50)
        );
        return v_id;
    end;
  end upsert_route;

  function upsert_route_cell(
    p_pick_route_cell_id number default null,
    p_pick_route_id      number,
    p_cell_code          varchar2,
    p_pick_sequence      number,
    p_zone_code          varchar2 default null,
    p_aisle_code         varchar2 default null,
    p_side_code          varchar2 default null,
    p_level_no           number default null,
    p_active             number default 1,
    p_updated_by         varchar2 default null
  ) return number is
    v_id number;
    v_ware_id number;
  begin
    if p_pick_route_id is null or p_cell_code is null or p_pick_sequence is null then
      raise_application_error(-20973, 'route, cell and sequence are required');
    end if;

    select WARE_ID into v_ware_id from RRL_PICK_ROUTE where PICK_ROUTE_ID = p_pick_route_id;

    if p_pick_route_cell_id is not null then
      v_id := p_pick_route_cell_id;
      update RRL_PICK_ROUTE_CELL
         set PICK_ROUTE_ID = p_pick_route_id,
             WARE_ID = v_ware_id,
             CELL_CODE = substr(p_cell_code, 1, 60),
             PICK_SEQUENCE = p_pick_sequence,
             ZONE_CODE = substr(p_zone_code, 1, 50),
             AISLE_CODE = substr(p_aisle_code, 1, 50),
             SIDE_CODE = substr(p_side_code, 1, 20),
             LEVEL_NO = p_level_no,
             ACTIVE = case when nvl(p_active, 1) = 0 then 0 else 1 end,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_updated_by, 1, 50)
       where PICK_ROUTE_CELL_ID = v_id;
      if sql%rowcount = 0 then
        raise_application_error(-20974, 'pick route cell not found');
      end if;
      return v_id;
    end if;

    begin
      select PICK_ROUTE_CELL_ID
        into v_id
        from RRL_PICK_ROUTE_CELL
       where PICK_ROUTE_ID = p_pick_route_id
         and upper(CELL_CODE) = upper(p_cell_code)
         and rownum = 1;

      update RRL_PICK_ROUTE_CELL
         set PICK_SEQUENCE = p_pick_sequence,
             ZONE_CODE = substr(p_zone_code, 1, 50),
             AISLE_CODE = substr(p_aisle_code, 1, 50),
             SIDE_CODE = substr(p_side_code, 1, 20),
             LEVEL_NO = p_level_no,
             ACTIVE = case when nvl(p_active, 1) = 0 then 0 else 1 end,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_updated_by, 1, 50)
       where PICK_ROUTE_CELL_ID = v_id;
      return v_id;
    exception
      when no_data_found then
        select RRL_PICK_ROUTE_CELL_SQ.nextval into v_id from dual;
        insert into RRL_PICK_ROUTE_CELL (
          PICK_ROUTE_CELL_ID, PICK_ROUTE_ID, WARE_ID, CELL_CODE, PICK_SEQUENCE,
          ZONE_CODE, AISLE_CODE, SIDE_CODE, LEVEL_NO, ACTIVE, CREATED_AT, CREATED_BY
        ) values (
          v_id, p_pick_route_id, v_ware_id, substr(p_cell_code, 1, 60), p_pick_sequence,
          substr(p_zone_code, 1, 50), substr(p_aisle_code, 1, 50),
          substr(p_side_code, 1, 20), p_level_no, case when nvl(p_active, 1) = 0 then 0 else 1 end,
          sysdate, substr(p_updated_by, 1, 50)
        );
        return v_id;
    end;
  end upsert_route_cell;

  function upsert_pick_face(
    p_pick_face_id             number default null,
    p_ware_id                  number,
    p_cell_code                varchar2,
    p_pick_face_code           varchar2 default null,
    p_pick_face_type           varchar2 default 'REGULAR',
    p_pick_route_id            number default null,
    p_pick_route_cell_id       number default null,
    p_pick_sequence            number default null,
    p_min_case_qty             number default null,
    p_max_case_qty             number default null,
    p_replenishment_trigger_qty number default null,
    p_max_weight               number default null,
    p_max_volume               number default null,
    p_allow_dynamic_assignment number default 0,
    p_active                   number default 1,
    p_comment_text             varchar2 default null,
    p_updated_by               varchar2 default null
  ) return number is
    v_id number;
    v_type varchar2(20);
    v_route_cell_sequence number;
  begin
    if p_ware_id is null or p_cell_code is null then
      raise_application_error(-20975, 'ware_id and cell_code are required');
    end if;

    v_type := upper(nvl(p_pick_face_type, 'REGULAR'));
    if v_type not in ('REGULAR', 'DYNAMIC') then
      raise_application_error(-20976, 'unsupported pick face type');
    end if;

    if p_pick_route_cell_id is not null then
      begin
        select PICK_SEQUENCE
          into v_route_cell_sequence
          from RRL_PICK_ROUTE_CELL
         where PICK_ROUTE_CELL_ID = p_pick_route_cell_id;
      exception
        when no_data_found then
          raise_application_error(-20977, 'pick route cell not found');
      end;
    end if;

    if p_pick_face_id is not null then
      v_id := p_pick_face_id;
      update RRL_PICK_FACE
         set WARE_ID = p_ware_id,
             CELL_CODE = substr(p_cell_code, 1, 60),
             PICK_FACE_CODE = substr(p_pick_face_code, 1, 100),
             PICK_FACE_TYPE = v_type,
             PICK_ROUTE_ID = p_pick_route_id,
             PICK_ROUTE_CELL_ID = p_pick_route_cell_id,
             PICK_SEQUENCE = nvl(p_pick_sequence, v_route_cell_sequence),
             MIN_CASE_QTY = nvl(p_min_case_qty, 0),
             MAX_CASE_QTY = p_max_case_qty,
             REPLENISHMENT_TRIGGER_QTY = p_replenishment_trigger_qty,
             MAX_WEIGHT = p_max_weight,
             MAX_VOLUME = p_max_volume,
             ALLOW_DYNAMIC_ASSIGNMENT = case when nvl(p_allow_dynamic_assignment, 0) = 0 then 0 else 1 end,
             ACTIVE = case when nvl(p_active, 1) = 0 then 0 else 1 end,
             COMMENT_TEXT = substr(p_comment_text, 1, 1000),
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_updated_by, 1, 50)
       where PICK_FACE_ID = v_id;
      if sql%rowcount = 0 then
        raise_application_error(-20978, 'pick face not found');
      end if;
      return v_id;
    end if;

    select RRL_PICK_FACE_SQ.nextval into v_id from dual;
    insert into RRL_PICK_FACE (
      PICK_FACE_ID, WARE_ID, CELL_CODE, PICK_FACE_CODE, PICK_FACE_TYPE,
      PICK_ROUTE_ID, PICK_ROUTE_CELL_ID, PICK_SEQUENCE, MIN_CASE_QTY, MAX_CASE_QTY,
      REPLENISHMENT_TRIGGER_QTY, MAX_WEIGHT, MAX_VOLUME, ALLOW_DYNAMIC_ASSIGNMENT,
      ACTIVE, COMMENT_TEXT, CREATED_AT, CREATED_BY
    ) values (
      v_id, p_ware_id, substr(p_cell_code, 1, 60), substr(p_pick_face_code, 1, 100), v_type,
      p_pick_route_id, p_pick_route_cell_id, nvl(p_pick_sequence, v_route_cell_sequence),
      nvl(p_min_case_qty, 0), p_max_case_qty, p_replenishment_trigger_qty,
      p_max_weight, p_max_volume, case when nvl(p_allow_dynamic_assignment, 0) = 0 then 0 else 1 end,
      case when nvl(p_active, 1) = 0 then 0 else 1 end, substr(p_comment_text, 1, 1000), sysdate, substr(p_updated_by, 1, 50)
    );
    return v_id;
  end upsert_pick_face;

  function assign_articul(
    p_pick_face_articul_id number default null,
    p_pick_face_id         number,
    p_articul              varchar2,
    p_priority             number default 100,
    p_min_qty              number default null,
    p_max_qty              number default null,
    p_case_pick_enabled    number default 1,
    p_active               number default 1,
    p_valid_from           date default null,
    p_valid_to             date default null,
    p_updated_by           varchar2 default null
  ) return number is
    v_id number;
  begin
    if p_pick_face_id is null or p_articul is null then
      raise_application_error(-20979, 'pick_face_id and articul are required');
    end if;

    if p_pick_face_articul_id is not null then
      v_id := p_pick_face_articul_id;
      update RRL_PICK_FACE_ARTICUL
         set PICK_FACE_ID = p_pick_face_id,
             ARTICUL = upper(substr(p_articul, 1, 40)),
             PRIORITY = nvl(p_priority, 100),
             MIN_QTY = p_min_qty,
             MAX_QTY = p_max_qty,
             CASE_PICK_ENABLED = case when nvl(p_case_pick_enabled, 1) = 0 then 0 else 1 end,
             ACTIVE = case when nvl(p_active, 1) = 0 then 0 else 1 end,
             VALID_FROM = nvl(p_valid_from, trunc(sysdate)),
             VALID_TO = p_valid_to,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_updated_by, 1, 50)
       where PICK_FACE_ARTICUL_ID = v_id;
      if sql%rowcount = 0 then
        raise_application_error(-20980, 'pick face articul row not found');
      end if;
      return v_id;
    end if;

    begin
      select PICK_FACE_ARTICUL_ID
        into v_id
        from RRL_PICK_FACE_ARTICUL
       where PICK_FACE_ID = p_pick_face_id
         and upper(ARTICUL) = upper(p_articul)
         and rownum = 1;

      update RRL_PICK_FACE_ARTICUL
         set PRIORITY = nvl(p_priority, 100),
             MIN_QTY = p_min_qty,
             MAX_QTY = p_max_qty,
             CASE_PICK_ENABLED = case when nvl(p_case_pick_enabled, 1) = 0 then 0 else 1 end,
             ACTIVE = case when nvl(p_active, 1) = 0 then 0 else 1 end,
             VALID_FROM = nvl(p_valid_from, trunc(sysdate)),
             VALID_TO = p_valid_to,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_updated_by, 1, 50)
       where PICK_FACE_ARTICUL_ID = v_id;
      return v_id;
    exception
      when no_data_found then
        select RRL_PICK_FACE_ARTICUL_SQ.nextval into v_id from dual;
        insert into RRL_PICK_FACE_ARTICUL (
          PICK_FACE_ARTICUL_ID, PICK_FACE_ID, ARTICUL, PRIORITY, MIN_QTY, MAX_QTY,
          CASE_PICK_ENABLED, ACTIVE, VALID_FROM, VALID_TO, CREATED_AT, CREATED_BY
        ) values (
          v_id, p_pick_face_id, upper(substr(p_articul, 1, 40)), nvl(p_priority, 100),
      p_min_qty, p_max_qty, case when nvl(p_case_pick_enabled, 1) = 0 then 0 else 1 end, case when nvl(p_active, 1) = 0 then 0 else 1 end,
          nvl(p_valid_from, trunc(sysdate)), p_valid_to, sysdate, substr(p_updated_by, 1, 50)
        );
        return v_id;
    end;
  end assign_articul;

  procedure resolve_pick_face(
    p_ware_id            number,
    p_articul            varchar2,
    p_target_cell        out varchar2,
    p_pick_sequence      out number,
    p_pick_face_id       out number,
    p_pick_route_cell_id out number
  ) is
  begin
    p_target_cell := null;
    p_pick_sequence := null;
    p_pick_face_id := null;
    p_pick_route_cell_id := null;

    select PICK_FACE_ID,
           CELL_CODE,
           PICK_SEQUENCE,
           PICK_ROUTE_CELL_ID
      into p_pick_face_id,
           p_target_cell,
           p_pick_sequence,
           p_pick_route_cell_id
      from (
        select pf.PICK_FACE_ID,
               pf.CELL_CODE,
               nvl(rc.PICK_SEQUENCE, pf.PICK_SEQUENCE) PICK_SEQUENCE,
               pf.PICK_ROUTE_CELL_ID
          from RRL_PICK_FACE_ARTICUL pfa
          join RRL_PICK_FACE pf
            on pf.PICK_FACE_ID = pfa.PICK_FACE_ID
          left join RRL_PICK_ROUTE_CELL rc
            on rc.PICK_ROUTE_CELL_ID = pf.PICK_ROUTE_CELL_ID
           and rc.ACTIVE = 1
         where pfa.ACTIVE = 1
           and pfa.CASE_PICK_ENABLED = 1
           and RRL_PICK_RANGE_POLICY.new_target_allowed(pf.CELL_CODE,pfa.ARTICUL)=1
           and pf.ACTIVE = 1
           and upper(pfa.ARTICUL) = upper(p_articul)
           and (p_ware_id is null or pf.WARE_ID = p_ware_id)
           and trunc(sysdate) between trunc(pfa.VALID_FROM) and nvl(trunc(pfa.VALID_TO), date '2999-12-31')
         order by pfa.PRIORITY, nvl(rc.PICK_SEQUENCE, pf.PICK_SEQUENCE) nulls last, pf.PICK_FACE_ID
      )
     where rownum = 1;
  exception
    when no_data_found then
      p_target_cell := null;
      p_pick_sequence := null;
      p_pick_face_id := null;
      p_pick_route_cell_id := null;
  end resolve_pick_face;
end RRL_PICK_TOPOLOGY_API;
/


CREATE OR REPLACE package body RRL_PICK_WAVE_API as
  procedure write_audit(
    p_pick_wave_id number,
    p_event_type   varchar2,
    p_message_text varchar2,
    p_payload_json clob default null,
    p_created_by   varchar2 default null
  ) is
  begin
    insert into RRL_PICK_WAVE_AUDIT (
      PICK_WAVE_AUDIT_ID, PICK_WAVE_ID, EVENT_TYPE, MESSAGE_TEXT,
      PAYLOAD_JSON, CREATED_AT, CREATED_BY
    ) values (
      RRL_PICK_WAVE_AUDIT_SQ.nextval, p_pick_wave_id, substr(p_event_type, 1, 50),
      substr(p_message_text, 1, 1000), p_payload_json, sysdate, substr(p_created_by, 1, 50)
    );
  end write_audit;

  procedure refresh_counters(p_pick_wave_id number, p_updated_by varchar2 default null) is
  begin
    update RRL_PICK_WAVE w
       set CUSTOMER_COUNT = (
             select count(distinct CUSTOMER_ID)
               from RRL_PICK_WAVE_ORDER
              where PICK_WAVE_ID = p_pick_wave_id
                and STATUS = 'ACTIVE'
           ),
           ORDER_COUNT = (
             select count(distinct CUSTOMER_ORDER_ID)
               from RRL_PICK_WAVE_ORDER
              where PICK_WAVE_ID = p_pick_wave_id
                and STATUS = 'ACTIVE'
           ),
           PLAN_COUNT = (
             select count(*)
               from RRL_PICK_WAVE_ORDER
              where PICK_WAVE_ID = p_pick_wave_id
                and STATUS = 'ACTIVE'
           ),
           TASK_COUNT = (
             select count(*)
               from RRL_PICK_WAVE_TASK
              where PICK_WAVE_ID = p_pick_wave_id
                and STATUS <> 'CANCELLED'
           ),
           HARD_RESERVE_QTY = (
             select nvl(sum(RESERVED_QTY), 0)
               from RRL_PICK_WAVE_RESERVATION
              where PICK_WAVE_ID = p_pick_wave_id
                and RESERVATION_STATUS = 'HARD'
           ),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id;
  end refresh_counters;

  procedure clear_preview(p_pick_wave_id number) is
  begin
    delete from RRL_PICK_WAVE_SHORTAGE where PICK_WAVE_ID = p_pick_wave_id;
    delete from RRL_PICK_WAVE_DEMAND where PICK_WAVE_ID = p_pick_wave_id;
    delete from RRL_PICK_WAVE_LINE where PICK_WAVE_ID = p_pick_wave_id;
  end clear_preview;

  function create_wave(
    p_wave_code         varchar2 default null,
    p_wave_name         varchar2 default null,
    p_ware_id           number default null,
    p_route_id          number default null,
    p_dock_id           number default null,
    p_planned_start_at  date default null,
    p_planned_finish_at date default null,
    p_max_customers     number default 30,
    p_created_by        varchar2 default null
  ) return number is
    v_id number;
    v_code varchar2(50);
  begin
    select RRL_PICK_WAVE_SQ.nextval into v_id from dual;
    v_code := nvl(substr(p_wave_code, 1, 50), 'WAVE-' || to_char(sysdate, 'YYYYMMDD') || '-' || to_char(v_id));

    insert into RRL_PICK_WAVE (
      PICK_WAVE_ID, WAVE_CODE, WAVE_NAME, WARE_ID, ROUTE_ID, DOCK_ID,
      STATUS, WAVE_KIND, PLANNED_START_AT, PLANNED_FINISH_AT, MAX_CUSTOMERS,
      CREATED_AT, CREATED_BY
    ) values (
      v_id, v_code, substr(p_wave_name, 1, 255), p_ware_id, p_route_id, p_dock_id,
      'DRAFT', 'CUSTOMER_ORDER', p_planned_start_at, p_planned_finish_at,
      nvl(p_max_customers, 30), sysdate, substr(p_created_by, 1, 50)
    );

    write_audit(v_id, 'WAVE_CREATED', 'Wave created', '{"waveCode":"' || replace(v_code, '"', '\"') || '"}', p_created_by);
    return v_id;
  end create_wave;

  procedure add_plan(
    p_pick_wave_id number,
    p_pick_plan_id number,
    p_created_by   varchar2 default null
  ) is
    v_wave RRL_PICK_WAVE%rowtype;
    v_plan RRL_PICK_PLAN%rowtype;
    v_order_no varchar2(100);
    v_existing number;
    v_customer_count number;
    v_customer_already number;
  begin
    select *
      into v_wave
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_wave.STATUS not in ('DRAFT', 'PREVIEW') then
      raise_application_error(-20990, 'wave does not accept new plans');
    end if;

    select *
      into v_plan
      from RRL_PICK_PLAN
     where PICK_PLAN_ID = p_pick_plan_id;

    if v_plan.STATUS not in ('PLANNED_FULL', 'PLANNED_PARTIAL') then
      raise_application_error(-20991, 'pick plan must be planned before adding to wave');
    end if;

    if v_wave.WARE_ID is not null and v_plan.WARE_ID is not null and v_wave.WARE_ID <> v_plan.WARE_ID then
      raise_application_error(-20992, 'pick plan warehouse does not match wave warehouse');
    end if;

    select count(*)
      into v_existing
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_WAVE w
        on w.PICK_WAVE_ID = wo.PICK_WAVE_ID
     where wo.PICK_PLAN_ID = p_pick_plan_id
       and wo.STATUS = 'ACTIVE'
       and w.STATUS in ('DRAFT', 'PREVIEW', 'LAUNCHED')
       and wo.PICK_WAVE_ID <> p_pick_wave_id;

    if v_existing > 0 then
      raise_application_error(-20993, 'pick plan is already assigned to another open wave');
    end if;

    select count(*)
      into v_existing
      from RRL_PICK_WAVE_ORDER
     where PICK_WAVE_ID = p_pick_wave_id
       and PICK_PLAN_ID = p_pick_plan_id
       and STATUS = 'ACTIVE';

    if v_existing > 0 then
      return;
    end if;

    select count(distinct CUSTOMER_ID)
      into v_customer_count
      from RRL_PICK_WAVE_ORDER
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS = 'ACTIVE';

    select count(*)
      into v_customer_already
      from RRL_PICK_WAVE_ORDER
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS = 'ACTIVE'
       and nvl(CUSTOMER_ID, -1) = nvl(v_plan.CUSTOMER_ID, -1);

    if v_customer_already = 0 and v_customer_count >= nvl(v_wave.MAX_CUSTOMERS, 30) then
      raise_application_error(-20994, 'wave customer limit exceeded');
    end if;

    select ORDER_NO
      into v_order_no
      from RRL_CUSTOMER_ORDER
     where CUSTOMER_ORDER_ID = v_plan.CUSTOMER_ORDER_ID;

    insert into RRL_PICK_WAVE_ORDER (
      PICK_WAVE_ORDER_ID, PICK_WAVE_ID, PICK_PLAN_ID, CUSTOMER_ORDER_ID,
      CUSTOMER_ID, ORDER_NO, STATUS, CREATED_AT, CREATED_BY
    ) values (
      RRL_PICK_WAVE_ORDER_SQ.nextval, p_pick_wave_id, p_pick_plan_id, v_plan.CUSTOMER_ORDER_ID,
      v_plan.CUSTOMER_ID, substr(v_order_no, 1, 100), 'ACTIVE', sysdate, substr(p_created_by, 1, 50)
    );

    if v_wave.STATUS = 'PREVIEW' then
      clear_preview(p_pick_wave_id);
      update RRL_PICK_WAVE
         set STATUS = 'DRAFT',
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_created_by, 1, 50)
       where PICK_WAVE_ID = p_pick_wave_id;
    end if;

    refresh_counters(p_pick_wave_id, p_created_by);
    write_audit(p_pick_wave_id, 'PLAN_ADDED', 'Pick plan added to wave', '{"pickPlanId":' || to_char(p_pick_plan_id) || '}', p_created_by);
  end add_plan;

  procedure preview_wave(
    p_pick_wave_id number,
    p_updated_by   varchar2 default null
  ) is
    v_status varchar2(30);
    v_plan_count number;
  begin
    select STATUS
      into v_status
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_status not in ('DRAFT', 'PREVIEW') then
      raise_application_error(-20995, 'wave cannot be previewed in current status');
    end if;

    select count(*)
      into v_plan_count
      from RRL_PICK_WAVE_ORDER
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS = 'ACTIVE';

    if v_plan_count = 0 then
      raise_application_error(-20996, 'wave has no active plans');
    end if;

    clear_preview(p_pick_wave_id);

    insert into RRL_PICK_WAVE_LINE (
      PICK_WAVE_LINE_ID, PICK_WAVE_ID, PICK_WAVE_ORDER_ID, PICK_PLAN_ID,
      PICK_PLAN_LINE_ID, CUSTOMER_ORDER_ROW_ID, ARTICUL, REQUESTED_QTY,
      PLANNED_QTY, SHORTAGE_QTY, STATUS, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_LINE_SQ.nextval,
           wo.PICK_WAVE_ID,
           wo.PICK_WAVE_ORDER_ID,
           wo.PICK_PLAN_ID,
           pl.PICK_PLAN_LINE_ID,
           pl.CUSTOMER_ORDER_ROW_ID,
           pl.ARTICUL,
           pl.REQUESTED_QTY,
           pl.PLANNED_QTY,
           pl.SHORTAGE_QTY,
           'PREVIEW',
           sysdate,
           substr(p_updated_by, 1, 50)
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_PLAN_LINE pl
        on pl.PICK_PLAN_ID = wo.PICK_PLAN_ID
     where wo.PICK_WAVE_ID = p_pick_wave_id
       and wo.STATUS = 'ACTIVE';

    insert into RRL_PICK_WAVE_DEMAND (
      PICK_WAVE_DEMAND_ID, PICK_WAVE_ID, ARTICUL, TASK_TYPE,
      TARGET_CELL_CODE, PICK_FACE_ID, PICK_ROUTE_CELL_ID, DEMAND_QTY,
      TASK_COUNT, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_DEMAND_SQ.nextval,
           q.PICK_WAVE_ID,
           q.ARTICUL,
           q.TASK_TYPE,
           q.TARGET_CELL_CODE,
           q.PICK_FACE_ID,
           q.PICK_ROUTE_CELL_ID,
           q.DEMAND_QTY,
           q.TASK_COUNT,
           sysdate,
           substr(p_updated_by, 1, 50)
      from (
        select wo.PICK_WAVE_ID,
               t.ARTICUL,
               t.TASK_TYPE,
               t.TARGET_CELL_CODE,
               t.PICK_FACE_ID,
               t.PICK_ROUTE_CELL_ID,
               sum(t.QTY) DEMAND_QTY,
               count(*) TASK_COUNT
          from RRL_PICK_WAVE_ORDER wo
          join RRL_PICK_TASK t
            on t.PICK_PLAN_ID = wo.PICK_PLAN_ID
         where wo.PICK_WAVE_ID = p_pick_wave_id
           and wo.STATUS = 'ACTIVE'
           and t.STATUS in ('NEW', 'ASSIGNED')
         group by wo.PICK_WAVE_ID, t.ARTICUL, t.TASK_TYPE, t.TARGET_CELL_CODE, t.PICK_FACE_ID, t.PICK_ROUTE_CELL_ID
      ) q;

    insert into RRL_PICK_WAVE_SHORTAGE (
      PICK_WAVE_SHORTAGE_ID, PICK_WAVE_ID, PICK_SHORTAGE_ID, PICK_PLAN_ID,
      CUSTOMER_ORDER_ID, CUSTOMER_ID, ARTICUL, REQUESTED_QTY, PLANNED_QTY,
      SHORTAGE_QTY, REASON_CODE, REASON_TEXT, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_SHORTAGE_SQ.nextval,
           wo.PICK_WAVE_ID,
           s.PICK_SHORTAGE_ID,
           s.PICK_PLAN_ID,
           s.CUSTOMER_ORDER_ID,
           s.CUSTOMER_ID,
           s.ARTICUL,
           s.REQUESTED_QTY,
           s.PLANNED_QTY,
           s.SHORTAGE_QTY,
           s.REASON_CODE,
           s.REASON_TEXT,
           sysdate,
           substr(p_updated_by, 1, 50)
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_SHORTAGE s
        on s.PICK_PLAN_ID = wo.PICK_PLAN_ID
     where wo.PICK_WAVE_ID = p_pick_wave_id
       and wo.STATUS = 'ACTIVE';

    update RRL_PICK_WAVE
       set STATUS = 'PREVIEW',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id;

    refresh_counters(p_pick_wave_id, p_updated_by);
    write_audit(p_pick_wave_id, 'WAVE_PREVIEWED', 'Wave preview calculated', '{"plans":' || to_char(v_plan_count) || '}', p_updated_by);
  end preview_wave;

  procedure launch_wave(
    p_pick_wave_id number,
    p_launched_by  varchar2 default null
  ,
    p_operation_id varchar2 default null
  ) is
    v_status varchar2(30);
    v_res_count number := 0;
    v_task_count number := 0;
    v_replenish_count number := 0;
  begin
    declare
      st varchar2(20);j json_object_t:=json_object_t();src json_object_t:=json_object_t();result clob;
    begin
      select STATE into st from RRL_STOCK_RELEASE where RELEASE_ID=1;
      if st='ACTIVE' then
        if p_operation_id is null then raise_application_error(-20871,'OPERATION_ID_REQUIRED');end if;
        j.put('contract_version',2);j.put('operation_id',p_operation_id);
        j.put('command_type','WAVE_LAUNCH');j.put('actor',p_launched_by);
        src.put('wave_id',p_pick_wave_id);j.put('source',src);j.put('lines',json_array_t());
        j.put('units',json_array_t());j.put('metadata',json_object_t());
        RRL_STOCK_NATIVE_API.post(j.to_clob,p_launched_by,result);return;
      end if;
    end;

    select STATUS
      into v_status
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_status = 'DRAFT' then
      preview_wave(p_pick_wave_id, p_launched_by);
    end if;

    select STATUS
      into v_status
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_status <> 'PREVIEW' then
      raise_application_error(-20997, 'wave must be in PREVIEW status before launch');
    end if;

    for r in (
      select pr.PICK_RESERVATION_ID,
             pr.PICK_PLAN_ID,
             pr.PICK_PLAN_LINE_ID,
             pr.PICK_TASK_ID,
             pr.CUSTOMER_ORDER_ID,
             pr.CUSTOMER_ID,
             pr.PALLET_UID,
             pr.SSCC,
             pr.ARTICUL,
             pr.SOURCE_CELL_CODE,
             pr.RESERVED_QTY
        from RRL_PICK_WAVE_ORDER wo
        join RRL_PICK_RESERVATION pr
          on pr.PICK_PLAN_ID = wo.PICK_PLAN_ID
       where wo.PICK_WAVE_ID = p_pick_wave_id
         and wo.STATUS = 'ACTIVE'
         and pr.RESERVATION_STATUS = 'ACTIVE'
         and pr.RESERVATION_LEVEL = 'SOFT'
       order by pr.PICK_RESERVATION_ID
       for update
    ) loop
      update RRL_PICK_RESERVATION
         set RESERVATION_LEVEL = 'HARD',
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_launched_by, 1, 50)
       where PICK_RESERVATION_ID = r.PICK_RESERVATION_ID;

      insert into RRL_PICK_WAVE_RESERVATION (
        PICK_WAVE_RESERVATION_ID, PICK_WAVE_ID, PICK_RESERVATION_ID, PICK_TASK_ID,
        PICK_PLAN_ID, PICK_PLAN_LINE_ID, CUSTOMER_ORDER_ID, CUSTOMER_ID,
        RESERVATION_STATUS, PALLET_UID, SSCC, ARTICUL, SOURCE_CELL_CODE,
        RESERVED_QTY, CREATED_AT, CREATED_BY
      ) values (
        RRL_PICK_WAVE_RES_SQ.nextval, p_pick_wave_id, r.PICK_RESERVATION_ID, r.PICK_TASK_ID,
        r.PICK_PLAN_ID, r.PICK_PLAN_LINE_ID, r.CUSTOMER_ORDER_ID, r.CUSTOMER_ID,
        'HARD', r.PALLET_UID, r.SSCC, r.ARTICUL, r.SOURCE_CELL_CODE,
        r.RESERVED_QTY, sysdate, substr(p_launched_by, 1, 50)
      );
      v_res_count := v_res_count + 1;
    end loop;

    if v_res_count = 0 then
      raise_application_error(-20998, 'wave has no active soft reservations to launch');
    end if;

    insert into RRL_PICK_WAVE_TASK (
      PICK_WAVE_TASK_ID, PICK_WAVE_ID, PICK_TASK_ID, TASK_TYPE, STATUS,
      ARTICUL, PALLET_UID, SOURCE_CELL_CODE, TARGET_CELL_CODE, QTY,
      PICK_SEQUENCE, PICK_FACE_ID, PICK_ROUTE_CELL_ID, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_TASK_SQ.nextval,
           p_pick_wave_id,
           t.PICK_TASK_ID,
           t.TASK_TYPE,
           'NEW',
           t.ARTICUL,
           t.PALLET_UID,
           t.SOURCE_CELL_CODE,
           t.TARGET_CELL_CODE,
           t.QTY,
           t.PICK_SEQUENCE,
           t.PICK_FACE_ID,
           t.PICK_ROUTE_CELL_ID,
           sysdate,
           substr(p_launched_by, 1, 50)
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_TASK t
        on t.PICK_PLAN_ID = wo.PICK_PLAN_ID
     where wo.PICK_WAVE_ID = p_pick_wave_id
       and wo.STATUS = 'ACTIVE'
       and t.STATUS in ('NEW', 'ASSIGNED')
       and not exists (
         select 1
           from RRL_PICK_WAVE_TASK wt
          where wt.PICK_WAVE_ID = p_pick_wave_id
            and wt.PICK_TASK_ID = t.PICK_TASK_ID
       );

    v_task_count := sql%rowcount;

    insert into RRL_PICK_WAVE_REPLENISH_TASK (
      PICK_WAVE_REPLENISH_TASK_ID, PICK_WAVE_ID, PICK_TASK_ID, STATUS,
      ARTICUL, PALLET_UID, SOURCE_CELL_CODE, TARGET_CELL_CODE, QTY,
      PICK_SEQUENCE, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_REPL_SQ.nextval,
           p_pick_wave_id,
           t.PICK_TASK_ID,
           'NEW',
           t.ARTICUL,
           t.PALLET_UID,
           t.SOURCE_CELL_CODE,
           t.TARGET_CELL_CODE,
           t.QTY,
           t.PICK_SEQUENCE,
           sysdate,
           substr(p_launched_by, 1, 50)
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_TASK t
        on t.PICK_PLAN_ID = wo.PICK_PLAN_ID
     where wo.PICK_WAVE_ID = p_pick_wave_id
       and wo.STATUS = 'ACTIVE'
       and t.TASK_TYPE = 'CASE_PICK'
       and t.TARGET_CELL_CODE is not null;

    v_replenish_count := sql%rowcount;

    update RRL_PICK_TASK
       set STATUS = 'ASSIGNED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_launched_by, 1, 50)
     where PICK_TASK_ID in (
       select PICK_TASK_ID
         from RRL_PICK_WAVE_TASK
        where PICK_WAVE_ID = p_pick_wave_id
     )
       and STATUS = 'NEW';

    update RRL_PICK_PLAN
       set STATUS = 'RELEASED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_launched_by, 1, 50)
     where PICK_PLAN_ID in (
       select PICK_PLAN_ID
         from RRL_PICK_WAVE_ORDER
        where PICK_WAVE_ID = p_pick_wave_id
          and STATUS = 'ACTIVE'
     )
       and STATUS in ('PLANNED_FULL', 'PLANNED_PARTIAL');

    update RRL_PICK_WAVE
       set STATUS = 'LAUNCHED',
           LAUNCHED_AT = sysdate,
           LAUNCHED_BY = substr(p_launched_by, 1, 50),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_launched_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id;

    refresh_counters(p_pick_wave_id, p_launched_by);
    write_audit(
      p_pick_wave_id,
      'WAVE_LAUNCHED',
      'Wave launched and soft reservations converted to hard reservations',
      '{"reservations":' || to_char(v_res_count) || ',"tasks":' || to_char(v_task_count) || ',"replenishmentTasks":' || to_char(v_replenish_count) || '}',
      p_launched_by
    );
  end launch_wave;

  procedure release_reservations(
    p_pick_wave_id number,
    p_updated_by   varchar2 default null
  ,
    p_operation_id varchar2 default null
  ) is
    v_blocking_tasks number;
  begin
    declare
      st varchar2(20);j json_object_t:=json_object_t();src json_object_t:=json_object_t();m json_object_t:=json_object_t();result clob;
    begin
      select STATE into st from RRL_STOCK_RELEASE where RELEASE_ID=1;
      if st='ACTIVE' then
        if p_operation_id is null then raise_application_error(-20871,'OPERATION_ID_REQUIRED');end if;
        j.put('contract_version',2);j.put('operation_id',p_operation_id);

        j.put('command_type','WAVE_RELEASE');
        j.put('actor',p_updated_by);src.put('document_type','PICK_WAVE');src.put('document_id',p_pick_wave_id);
        j.put('source',src);j.put('lines',json_array_t());j.put('units',json_array_t());
        m.put('reason','Release wave reservations');m.put('only_cancelled_replenishment',0);m.put_null('reservation_kind');j.put('metadata',m);
        RRL_STOCK_NATIVE_API.post(j.to_clob,p_updated_by,result);return;
      end if;
    end;

    select count(*)
      into v_blocking_tasks
      from RRL_PICK_WAVE_TASK
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS not in ('NEW', 'ASSIGNED', 'CANCELLED');

    if v_blocking_tasks > 0 then
      raise_application_error(-20999, 'wave has already started tasks; reservations cannot be released automatically');
    end if;

    update RRL_PICK_RESERVATION
       set RESERVATION_LEVEL = 'SOFT',
           RESERVATION_STATUS = 'ACTIVE',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_RESERVATION_ID in (
       select PICK_RESERVATION_ID
         from RRL_PICK_WAVE_RESERVATION
        where PICK_WAVE_ID = p_pick_wave_id
          and RESERVATION_STATUS = 'HARD'
     );

    update RRL_PICK_WAVE_RESERVATION
       set RESERVATION_STATUS = 'RELEASED',
           RELEASED_AT = sysdate,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id
       and RESERVATION_STATUS = 'HARD';

    update RRL_PICK_TASK
       set STATUS = 'NEW',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_TASK_ID in (
       select PICK_TASK_ID
         from RRL_PICK_WAVE_TASK
        where PICK_WAVE_ID = p_pick_wave_id
          and STATUS in ('NEW', 'ASSIGNED')
     )
       and STATUS = 'ASSIGNED';

    update RRL_PICK_WAVE_TASK
       set STATUS = 'CANCELLED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS in ('NEW', 'ASSIGNED');

    update RRL_PICK_WAVE_REPLENISH_TASK
       set STATUS = 'CANCELLED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS in ('NEW', 'ASSIGNED');

    update RRL_PICK_PLAN p
       set STATUS = case when nvl(p.TOTAL_SHORTAGE_QTY, 0) > 0 then 'PLANNED_PARTIAL' else 'PLANNED_FULL' end,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where p.PICK_PLAN_ID in (
       select PICK_PLAN_ID
         from RRL_PICK_WAVE_ORDER
        where PICK_WAVE_ID = p_pick_wave_id
          and STATUS = 'ACTIVE'
     )
       and p.STATUS = 'RELEASED';

    update RRL_PICK_WAVE
       set STATUS = 'PREVIEW',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS = 'LAUNCHED';

    refresh_counters(p_pick_wave_id, p_updated_by);
    write_audit(p_pick_wave_id, 'RESERVATIONS_RELEASED', 'Hard reservations returned to soft reservation state', null, p_updated_by);
  end release_reservations;

  procedure cancel_wave(
    p_pick_wave_id number,
    p_reason       varchar2 default null,
    p_updated_by   varchar2 default null
  ,
    p_operation_id varchar2 default null
  ) is
    v_status varchar2(30);
  begin
    declare
      st varchar2(20);j json_object_t:=json_object_t();src json_object_t:=json_object_t();m json_object_t:=json_object_t();result clob;
    begin
      select STATE into st from RRL_STOCK_RELEASE where RELEASE_ID=1;
      if st='ACTIVE' then
        if p_operation_id is null then raise_application_error(-20871,'OPERATION_ID_REQUIRED');end if;
        j.put('contract_version',2);j.put('operation_id',p_operation_id);

        j.put('command_type','WAVE_CANCEL');
        j.put('actor',p_updated_by);src.put('document_type','PICK_WAVE');src.put('document_id',p_pick_wave_id);
        j.put('source',src);j.put('lines',json_array_t());j.put('units',json_array_t());
        m.put('reason',p_reason);m.put('only_cancelled_replenishment',0);m.put_null('reservation_kind');j.put('metadata',m);
        RRL_STOCK_NATIVE_API.post(j.to_clob,p_updated_by,result);return;
      end if;
    end;

    select STATUS
      into v_status
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_status = 'LAUNCHED' then
      release_reservations(p_pick_wave_id, p_updated_by);
    elsif v_status not in ('DRAFT', 'PREVIEW', 'CANCELLED') then
      raise_application_error(-21000, 'wave cannot be cancelled in current status');
    end if;

    update RRL_PICK_WAVE
       set STATUS = 'CANCELLED',
           CANCELLED_AT = sysdate,
           CANCELLED_BY = substr(p_updated_by, 1, 50),
           COMMENT_TEXT = substr(nvl(p_reason, COMMENT_TEXT), 1, 1000),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id;

    refresh_counters(p_pick_wave_id, p_updated_by);
    write_audit(p_pick_wave_id, 'WAVE_CANCELLED', 'Wave cancelled', substr(p_reason, 1, 1000), p_updated_by);
  end cancel_wave;
end RRL_PICK_WAVE_API;
/


CREATE OR REPLACE package body RRL_PICK_WAVE_META as
  procedure write_audit(
    p_pick_wave_id number,
    p_event_type   varchar2,
    p_message_text varchar2,
    p_payload_json clob default null,
    p_created_by   varchar2 default null
  ) is
  begin
    insert into RRL_PICK_WAVE_AUDIT (
      PICK_WAVE_AUDIT_ID, PICK_WAVE_ID, EVENT_TYPE, MESSAGE_TEXT,
      PAYLOAD_JSON, CREATED_AT, CREATED_BY
    ) values (
      RRL_PICK_WAVE_AUDIT_SQ.nextval, p_pick_wave_id, substr(p_event_type, 1, 50),
      substr(p_message_text, 1, 1000), p_payload_json, sysdate, substr(p_created_by, 1, 50)
    );
  end write_audit;

  procedure refresh_counters(p_pick_wave_id number, p_updated_by varchar2 default null) is
  begin
    update RRL_PICK_WAVE w
       set CUSTOMER_COUNT = (
             select count(distinct CUSTOMER_ID)
               from RRL_PICK_WAVE_ORDER
              where PICK_WAVE_ID = p_pick_wave_id
                and STATUS = 'ACTIVE'
           ),
           ORDER_COUNT = (
             select count(distinct CUSTOMER_ORDER_ID)
               from RRL_PICK_WAVE_ORDER
              where PICK_WAVE_ID = p_pick_wave_id
                and STATUS = 'ACTIVE'
           ),
           PLAN_COUNT = (
             select count(*)
               from RRL_PICK_WAVE_ORDER
              where PICK_WAVE_ID = p_pick_wave_id
                and STATUS = 'ACTIVE'
           ),
           TASK_COUNT = (
             select count(*)
               from RRL_PICK_WAVE_TASK
              where PICK_WAVE_ID = p_pick_wave_id
                and STATUS <> 'CANCELLED'
           ),
           HARD_RESERVE_QTY = (
             select nvl(sum(RESERVED_QTY), 0)
               from RRL_PICK_WAVE_RESERVATION
              where PICK_WAVE_ID = p_pick_wave_id
                and RESERVATION_STATUS = 'HARD'
           ),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id;
  end refresh_counters;

  procedure clear_preview(p_pick_wave_id number) is
  begin
    delete from RRL_PICK_WAVE_SHORTAGE where PICK_WAVE_ID = p_pick_wave_id;
    delete from RRL_PICK_WAVE_DEMAND where PICK_WAVE_ID = p_pick_wave_id;
    delete from RRL_PICK_WAVE_LINE where PICK_WAVE_ID = p_pick_wave_id;
  end clear_preview;

  function create_wave(
    p_wave_code         varchar2 default null,
    p_wave_name         varchar2 default null,
    p_ware_id           number default null,
    p_route_id          number default null,
    p_dock_id           number default null,
    p_planned_start_at  date default null,
    p_planned_finish_at date default null,
    p_max_customers     number default 30,
    p_created_by        varchar2 default null
  ) return number is
    v_id number;
    v_code varchar2(50);
  begin
    select RRL_PICK_WAVE_SQ.nextval into v_id from dual;
    v_code := nvl(substr(p_wave_code, 1, 50), 'WAVE-' || to_char(sysdate, 'YYYYMMDD') || '-' || to_char(v_id));

    insert into RRL_PICK_WAVE (
      PICK_WAVE_ID, WAVE_CODE, WAVE_NAME, WARE_ID, ROUTE_ID, DOCK_ID,
      STATUS, WAVE_KIND, PLANNED_START_AT, PLANNED_FINISH_AT, MAX_CUSTOMERS,
      CREATED_AT, CREATED_BY
    ) values (
      v_id, v_code, substr(p_wave_name, 1, 255), p_ware_id, p_route_id, p_dock_id,
      'DRAFT', 'CUSTOMER_ORDER', p_planned_start_at, p_planned_finish_at,
      nvl(p_max_customers, 30), sysdate, substr(p_created_by, 1, 50)
    );

    write_audit(v_id, 'WAVE_CREATED', 'Wave created', '{"waveCode":"' || replace(v_code, '"', '\"') || '"}', p_created_by);
    return v_id;
  end create_wave;

  procedure add_plan(
    p_pick_wave_id number,
    p_pick_plan_id number,
    p_created_by   varchar2 default null
  ) is
    v_wave RRL_PICK_WAVE%rowtype;
    v_plan RRL_PICK_PLAN%rowtype;
    v_order_no varchar2(100);
    v_existing number;
    v_customer_count number;
    v_customer_already number;
  begin
    select *
      into v_wave
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_wave.STATUS not in ('DRAFT', 'PREVIEW') then
      raise_application_error(-20990, 'wave does not accept new plans');
    end if;

    select *
      into v_plan
      from RRL_PICK_PLAN
     where PICK_PLAN_ID = p_pick_plan_id;

    if v_plan.STATUS not in ('PLANNED_FULL', 'PLANNED_PARTIAL') then
      raise_application_error(-20991, 'pick plan must be planned before adding to wave');
    end if;

    if v_wave.WARE_ID is not null and v_plan.WARE_ID is not null and v_wave.WARE_ID <> v_plan.WARE_ID then
      raise_application_error(-20992, 'pick plan warehouse does not match wave warehouse');
    end if;

    select count(*)
      into v_existing
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_WAVE w
        on w.PICK_WAVE_ID = wo.PICK_WAVE_ID
     where wo.PICK_PLAN_ID = p_pick_plan_id
       and wo.STATUS = 'ACTIVE'
       and w.STATUS in ('DRAFT', 'PREVIEW', 'LAUNCHED')
       and wo.PICK_WAVE_ID <> p_pick_wave_id;

    if v_existing > 0 then
      raise_application_error(-20993, 'pick plan is already assigned to another open wave');
    end if;

    select count(*)
      into v_existing
      from RRL_PICK_WAVE_ORDER
     where PICK_WAVE_ID = p_pick_wave_id
       and PICK_PLAN_ID = p_pick_plan_id
       and STATUS = 'ACTIVE';

    if v_existing > 0 then
      return;
    end if;

    select count(distinct CUSTOMER_ID)
      into v_customer_count
      from RRL_PICK_WAVE_ORDER
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS = 'ACTIVE';

    select count(*)
      into v_customer_already
      from RRL_PICK_WAVE_ORDER
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS = 'ACTIVE'
       and nvl(CUSTOMER_ID, -1) = nvl(v_plan.CUSTOMER_ID, -1);

    if v_customer_already = 0 and v_customer_count >= nvl(v_wave.MAX_CUSTOMERS, 30) then
      raise_application_error(-20994, 'wave customer limit exceeded');
    end if;

    select ORDER_NO
      into v_order_no
      from RRL_CUSTOMER_ORDER
     where CUSTOMER_ORDER_ID = v_plan.CUSTOMER_ORDER_ID;

    insert into RRL_PICK_WAVE_ORDER (
      PICK_WAVE_ORDER_ID, PICK_WAVE_ID, PICK_PLAN_ID, CUSTOMER_ORDER_ID,
      CUSTOMER_ID, ORDER_NO, STATUS, CREATED_AT, CREATED_BY
    ) values (
      RRL_PICK_WAVE_ORDER_SQ.nextval, p_pick_wave_id, p_pick_plan_id, v_plan.CUSTOMER_ORDER_ID,
      v_plan.CUSTOMER_ID, substr(v_order_no, 1, 100), 'ACTIVE', sysdate, substr(p_created_by, 1, 50)
    );

    if v_wave.STATUS = 'PREVIEW' then
      clear_preview(p_pick_wave_id);
      update RRL_PICK_WAVE
         set STATUS = 'DRAFT',
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_created_by, 1, 50)
       where PICK_WAVE_ID = p_pick_wave_id;
    end if;

    refresh_counters(p_pick_wave_id, p_created_by);
    write_audit(p_pick_wave_id, 'PLAN_ADDED', 'Pick plan added to wave', '{"pickPlanId":' || to_char(p_pick_plan_id) || '}', p_created_by);
  end add_plan;

  procedure preview_wave(
    p_pick_wave_id number,
    p_updated_by   varchar2 default null
  ) is
    v_status varchar2(30);
    v_plan_count number;
  begin
    select STATUS
      into v_status
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_status not in ('DRAFT', 'PREVIEW') then
      raise_application_error(-20995, 'wave cannot be previewed in current status');
    end if;

    select count(*)
      into v_plan_count
      from RRL_PICK_WAVE_ORDER
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS = 'ACTIVE';

    if v_plan_count = 0 then
      raise_application_error(-20996, 'wave has no active plans');
    end if;

    clear_preview(p_pick_wave_id);

    insert into RRL_PICK_WAVE_LINE (
      PICK_WAVE_LINE_ID, PICK_WAVE_ID, PICK_WAVE_ORDER_ID, PICK_PLAN_ID,
      PICK_PLAN_LINE_ID, CUSTOMER_ORDER_ROW_ID, ARTICUL, REQUESTED_QTY,
      PLANNED_QTY, SHORTAGE_QTY, STATUS, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_LINE_SQ.nextval,
           wo.PICK_WAVE_ID,
           wo.PICK_WAVE_ORDER_ID,
           wo.PICK_PLAN_ID,
           pl.PICK_PLAN_LINE_ID,
           pl.CUSTOMER_ORDER_ROW_ID,
           pl.ARTICUL,
           pl.REQUESTED_QTY,
           pl.PLANNED_QTY,
           pl.SHORTAGE_QTY,
           'PREVIEW',
           sysdate,
           substr(p_updated_by, 1, 50)
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_PLAN_LINE pl
        on pl.PICK_PLAN_ID = wo.PICK_PLAN_ID
     where wo.PICK_WAVE_ID = p_pick_wave_id
       and wo.STATUS = 'ACTIVE';

    insert into RRL_PICK_WAVE_DEMAND (
      PICK_WAVE_DEMAND_ID, PICK_WAVE_ID, ARTICUL, TASK_TYPE,
      TARGET_CELL_CODE, PICK_FACE_ID, PICK_ROUTE_CELL_ID, DEMAND_QTY,
      TASK_COUNT, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_DEMAND_SQ.nextval,
           q.PICK_WAVE_ID,
           q.ARTICUL,
           q.TASK_TYPE,
           q.TARGET_CELL_CODE,
           q.PICK_FACE_ID,
           q.PICK_ROUTE_CELL_ID,
           q.DEMAND_QTY,
           q.TASK_COUNT,
           sysdate,
           substr(p_updated_by, 1, 50)
      from (
        select wo.PICK_WAVE_ID,
               t.ARTICUL,
               t.TASK_TYPE,
               t.TARGET_CELL_CODE,
               t.PICK_FACE_ID,
               t.PICK_ROUTE_CELL_ID,
               sum(t.QTY) DEMAND_QTY,
               count(*) TASK_COUNT
          from RRL_PICK_WAVE_ORDER wo
          join RRL_PICK_TASK t
            on t.PICK_PLAN_ID = wo.PICK_PLAN_ID
         where wo.PICK_WAVE_ID = p_pick_wave_id
           and wo.STATUS = 'ACTIVE'
           and t.STATUS in ('NEW', 'ASSIGNED')
         group by wo.PICK_WAVE_ID, t.ARTICUL, t.TASK_TYPE, t.TARGET_CELL_CODE, t.PICK_FACE_ID, t.PICK_ROUTE_CELL_ID
      ) q;

    insert into RRL_PICK_WAVE_SHORTAGE (
      PICK_WAVE_SHORTAGE_ID, PICK_WAVE_ID, PICK_SHORTAGE_ID, PICK_PLAN_ID,
      CUSTOMER_ORDER_ID, CUSTOMER_ID, ARTICUL, REQUESTED_QTY, PLANNED_QTY,
      SHORTAGE_QTY, REASON_CODE, REASON_TEXT, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_SHORTAGE_SQ.nextval,
           wo.PICK_WAVE_ID,
           s.PICK_SHORTAGE_ID,
           s.PICK_PLAN_ID,
           s.CUSTOMER_ORDER_ID,
           s.CUSTOMER_ID,
           s.ARTICUL,
           s.REQUESTED_QTY,
           s.PLANNED_QTY,
           s.SHORTAGE_QTY,
           s.REASON_CODE,
           s.REASON_TEXT,
           sysdate,
           substr(p_updated_by, 1, 50)
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_SHORTAGE s
        on s.PICK_PLAN_ID = wo.PICK_PLAN_ID
     where wo.PICK_WAVE_ID = p_pick_wave_id
       and wo.STATUS = 'ACTIVE';

    update RRL_PICK_WAVE
       set STATUS = 'PREVIEW',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id;

    refresh_counters(p_pick_wave_id, p_updated_by);
    write_audit(p_pick_wave_id, 'WAVE_PREVIEWED', 'Wave preview calculated', '{"plans":' || to_char(v_plan_count) || '}', p_updated_by);
  end preview_wave;

  procedure launch_wave(
    p_pick_wave_id number,
    p_launched_by  varchar2 default null
  ) is
    v_status varchar2(30);
    v_res_count number := 0;
    v_task_count number := 0;
    v_replenish_count number := 0;
  begin
    if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null then raise_application_error(-20863,'WAVE_LAUNCH_REQUIRES_POSTING_CONTEXT');end if;
    select STATUS
      into v_status
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_status = 'DRAFT' then
      preview_wave(p_pick_wave_id, p_launched_by);
    end if;

    select STATUS
      into v_status
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_status <> 'PREVIEW' then
      raise_application_error(-20997, 'wave must be in PREVIEW status before launch');
    end if;

    for r in (
      select pr.PICK_RESERVATION_ID,
             pr.PICK_PLAN_ID,
             pr.PICK_PLAN_LINE_ID,
             pr.PICK_TASK_ID,
             pr.CUSTOMER_ORDER_ID,
             pr.CUSTOMER_ID,
             pr.PALLET_UID,
             pr.SSCC,
             pr.ARTICUL,
             pr.SOURCE_CELL_CODE,
             pr.RESERVED_QTY
        from RRL_PICK_WAVE_ORDER wo
        join RRL_PICK_RESERVATION pr
          on pr.PICK_PLAN_ID = wo.PICK_PLAN_ID
       where wo.PICK_WAVE_ID = p_pick_wave_id
         and wo.STATUS = 'ACTIVE'
         and pr.RESERVATION_STATUS = 'ACTIVE'
         and pr.RESERVATION_LEVEL = 'SOFT'
       order by pr.PICK_RESERVATION_ID
       for update
    ) loop
      update RRL_PICK_RESERVATION
         set RESERVATION_LEVEL = 'HARD',
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(p_launched_by, 1, 50)
       where PICK_RESERVATION_ID = r.PICK_RESERVATION_ID;

      insert into RRL_PICK_WAVE_RESERVATION (
        PICK_WAVE_RESERVATION_ID, PICK_WAVE_ID, PICK_RESERVATION_ID, PICK_TASK_ID,
        PICK_PLAN_ID, PICK_PLAN_LINE_ID, CUSTOMER_ORDER_ID, CUSTOMER_ID,
        RESERVATION_STATUS, PALLET_UID, SSCC, ARTICUL, SOURCE_CELL_CODE,
        RESERVED_QTY, CREATED_AT, CREATED_BY
      ) values (
        RRL_PICK_WAVE_RES_SQ.nextval, p_pick_wave_id, r.PICK_RESERVATION_ID, r.PICK_TASK_ID,
        r.PICK_PLAN_ID, r.PICK_PLAN_LINE_ID, r.CUSTOMER_ORDER_ID, r.CUSTOMER_ID,
        'HARD', r.PALLET_UID, r.SSCC, r.ARTICUL, r.SOURCE_CELL_CODE,
        r.RESERVED_QTY, sysdate, substr(p_launched_by, 1, 50)
      );
      v_res_count := v_res_count + 1;
    end loop;

    if v_res_count = 0 then
      raise_application_error(-20998, 'wave has no active soft reservations to launch');
    end if;

    insert into RRL_PICK_WAVE_TASK (
      PICK_WAVE_TASK_ID, PICK_WAVE_ID, PICK_TASK_ID, TASK_TYPE, STATUS,
      ARTICUL, PALLET_UID, SOURCE_CELL_CODE, TARGET_CELL_CODE, QTY,
      PICK_SEQUENCE, PICK_FACE_ID, PICK_ROUTE_CELL_ID, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_TASK_SQ.nextval,
           p_pick_wave_id,
           t.PICK_TASK_ID,
           t.TASK_TYPE,
           'NEW',
           t.ARTICUL,
           t.PALLET_UID,
           t.SOURCE_CELL_CODE,
           t.TARGET_CELL_CODE,
           t.QTY,
           t.PICK_SEQUENCE,
           t.PICK_FACE_ID,
           t.PICK_ROUTE_CELL_ID,
           sysdate,
           substr(p_launched_by, 1, 50)
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_TASK t
        on t.PICK_PLAN_ID = wo.PICK_PLAN_ID
     where wo.PICK_WAVE_ID = p_pick_wave_id
       and wo.STATUS = 'ACTIVE'
       and t.STATUS in ('NEW', 'ASSIGNED')
       and not exists (
         select 1
           from RRL_PICK_WAVE_TASK wt
          where wt.PICK_WAVE_ID = p_pick_wave_id
            and wt.PICK_TASK_ID = t.PICK_TASK_ID
       );

    v_task_count := sql%rowcount;

    insert into RRL_PICK_WAVE_REPLENISH_TASK (
      PICK_WAVE_REPLENISH_TASK_ID, PICK_WAVE_ID, PICK_TASK_ID, STATUS,
      ARTICUL, PALLET_UID, SOURCE_CELL_CODE, TARGET_CELL_CODE, QTY,
      PICK_SEQUENCE, CREATED_AT, CREATED_BY
    )
    select RRL_PICK_WAVE_REPL_SQ.nextval,
           p_pick_wave_id,
           t.PICK_TASK_ID,
           'NEW',
           t.ARTICUL,
           t.PALLET_UID,
           t.SOURCE_CELL_CODE,
           t.TARGET_CELL_CODE,
           t.QTY,
           t.PICK_SEQUENCE,
           sysdate,
           substr(p_launched_by, 1, 50)
      from RRL_PICK_WAVE_ORDER wo
      join RRL_PICK_TASK t
        on t.PICK_PLAN_ID = wo.PICK_PLAN_ID
     where wo.PICK_WAVE_ID = p_pick_wave_id
       and wo.STATUS = 'ACTIVE'
       and t.TASK_TYPE = 'CASE_PICK'
       and t.TARGET_CELL_CODE is not null;

    v_replenish_count := sql%rowcount;

    update RRL_PICK_TASK
       set STATUS = 'ASSIGNED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_launched_by, 1, 50)
     where PICK_TASK_ID in (
       select PICK_TASK_ID
         from RRL_PICK_WAVE_TASK
        where PICK_WAVE_ID = p_pick_wave_id
     )
       and STATUS = 'NEW';

    update RRL_PICK_PLAN
       set STATUS = 'RELEASED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_launched_by, 1, 50)
     where PICK_PLAN_ID in (
       select PICK_PLAN_ID
         from RRL_PICK_WAVE_ORDER
        where PICK_WAVE_ID = p_pick_wave_id
          and STATUS = 'ACTIVE'
     )
       and STATUS in ('PLANNED_FULL', 'PLANNED_PARTIAL');

    update RRL_PICK_WAVE
       set STATUS = 'LAUNCHED',
           LAUNCHED_AT = sysdate,
           LAUNCHED_BY = substr(p_launched_by, 1, 50),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_launched_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id;

    refresh_counters(p_pick_wave_id, p_launched_by);
    write_audit(
      p_pick_wave_id,
      'WAVE_LAUNCHED',
      'Wave launched and soft reservations converted to hard reservations',
      '{"reservations":' || to_char(v_res_count) || ',"tasks":' || to_char(v_task_count) || ',"replenishmentTasks":' || to_char(v_replenish_count) || '}',
      p_launched_by
    );
  end launch_wave;

  procedure release_reservations(
    p_pick_wave_id number,
    p_updated_by   varchar2 default null
  ) is
    v_blocking_tasks number;
  begin
    select count(*)
      into v_blocking_tasks
      from RRL_PICK_WAVE_TASK
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS not in ('NEW', 'ASSIGNED', 'CANCELLED');

    if v_blocking_tasks > 0 then
      raise_application_error(-20999, 'wave has already started tasks; reservations cannot be released automatically');
    end if;

    update RRL_PICK_RESERVATION
       set RESERVATION_LEVEL = 'SOFT',
           RESERVATION_STATUS = 'ACTIVE',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_RESERVATION_ID in (
       select PICK_RESERVATION_ID
         from RRL_PICK_WAVE_RESERVATION
        where PICK_WAVE_ID = p_pick_wave_id
          and RESERVATION_STATUS = 'HARD'
     );

    update RRL_PICK_WAVE_RESERVATION
       set RESERVATION_STATUS = 'RELEASED',
           RELEASED_AT = sysdate,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id
       and RESERVATION_STATUS = 'HARD';

    update RRL_PICK_TASK
       set STATUS = 'NEW',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_TASK_ID in (
       select PICK_TASK_ID
         from RRL_PICK_WAVE_TASK
        where PICK_WAVE_ID = p_pick_wave_id
          and STATUS in ('NEW', 'ASSIGNED')
     )
       and STATUS = 'ASSIGNED';

    update RRL_PICK_WAVE_TASK
       set STATUS = 'CANCELLED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS in ('NEW', 'ASSIGNED');

    update RRL_PICK_WAVE_REPLENISH_TASK
       set STATUS = 'CANCELLED',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS in ('NEW', 'ASSIGNED');

    update RRL_PICK_PLAN p
       set STATUS = case when nvl(p.TOTAL_SHORTAGE_QTY, 0) > 0 then 'PLANNED_PARTIAL' else 'PLANNED_FULL' end,
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where p.PICK_PLAN_ID in (
       select PICK_PLAN_ID
         from RRL_PICK_WAVE_ORDER
        where PICK_WAVE_ID = p_pick_wave_id
          and STATUS = 'ACTIVE'
     )
       and p.STATUS = 'RELEASED';

    update RRL_PICK_WAVE
       set STATUS = 'PREVIEW',
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id
       and STATUS = 'LAUNCHED';

    refresh_counters(p_pick_wave_id, p_updated_by);
    write_audit(p_pick_wave_id, 'RESERVATIONS_RELEASED', 'Hard reservations returned to soft reservation state', null, p_updated_by);
  end release_reservations;

  procedure cancel_wave(
    p_pick_wave_id number,
    p_reason       varchar2 default null,
    p_updated_by   varchar2 default null
  ) is
    v_status varchar2(30);
  begin
    select STATUS
      into v_status
      from RRL_PICK_WAVE
     where PICK_WAVE_ID = p_pick_wave_id
     for update;

    if v_status = 'LAUNCHED' then
      release_reservations(p_pick_wave_id, p_updated_by);
    elsif v_status not in ('DRAFT', 'PREVIEW', 'CANCELLED') then
      raise_application_error(-21000, 'wave cannot be cancelled in current status');
    end if;

    update RRL_PICK_WAVE
       set STATUS = 'CANCELLED',
           CANCELLED_AT = sysdate,
           CANCELLED_BY = substr(p_updated_by, 1, 50),
           COMMENT_TEXT = substr(nvl(p_reason, COMMENT_TEXT), 1, 1000),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(p_updated_by, 1, 50)
     where PICK_WAVE_ID = p_pick_wave_id;

    refresh_counters(p_pick_wave_id, p_updated_by);
    write_audit(p_pick_wave_id, 'WAVE_CANCELLED', 'Wave cancelled', substr(p_reason, 1, 1000), p_updated_by);
  end cancel_wave;
end RRL_PICK_WAVE_META;
/


CREATE OR REPLACE package body RRL_PRODUCTION_API as
  function create_prod_batch(
    p_prod_batch_no        varchar2,
    p_articul              varchar2 default null,
    p_mod_id               number default null,
    p_gtin                 varchar2 default null,
    p_product_name         varchar2 default null,
    p_total_quantity       number default null,
    p_total_pack_count     number default null,
    p_unit_code            varchar2 default 'PCS',
    p_ware_id              number default null,
    p_source_system        varchar2 default null,
    p_source_message_id    varchar2 default null,
    p_external_operation_id varchar2 default null,
    p_external_batch_id    varchar2 default null,
    p_production_order_id  number default null,
    p_produced_date_from   date default null,
    p_produced_date_to     date default null,
    p_expiry_date_from     date default null,
    p_expiry_date_to       date default null,
    p_production_line      varchar2 default null,
    p_shift_id             varchar2 default null,
    p_mercury_required     number default 0,
    p_crpt_required        number default 0,
    p_created_by           varchar2 default user
  ) return number is
    v_id number;
  begin
    if p_source_system is not null and p_source_message_id is not null then
      begin
        select PROD_BATCH_ID
          into v_id
          from RRL_PROD_BATCH
         where SOURCE_SYSTEM = p_source_system
           and SOURCE_MESSAGE_ID = p_source_message_id
           and nvl(EXTERNAL_BATCH_ID, '#') = nvl(p_external_batch_id, '#')
           and rownum = 1;
        return v_id;
      exception
        when no_data_found then null;
      end;
    end if;

    begin
      select PROD_BATCH_ID
        into v_id
        from RRL_PROD_BATCH
       where PROD_BATCH_NO = p_prod_batch_no
         and nvl(ARTICUL, '#') = nvl(p_articul, '#')
         and nvl(WARE_ID, -1) = nvl(p_ware_id, -1)
         and rownum = 1;
      return v_id;
    exception
      when no_data_found then null;
    end;

    select RRL_PROD_BATCH_SQ.nextval into v_id from dual;

    insert into RRL_PROD_BATCH (
      PROD_BATCH_ID,
      PROD_BATCH_NO,
      PRODUCTION_ORDER_ID,
      SOURCE_SYSTEM,
      SOURCE_MESSAGE_ID,
      EXTERNAL_OPERATION_ID,
      EXTERNAL_BATCH_ID,
      ARTICUL,
      MOD_ID,
      GTIN,
      PRODUCT_NAME,
      PRODUCED_DATE_FROM,
      PRODUCED_DATE_TO,
      EXPIRY_DATE_FROM,
      EXPIRY_DATE_TO,
      TOTAL_QUANTITY,
      TOTAL_PACK_COUNT,
      UNIT_CODE,
      WARE_ID,
      PRODUCTION_LINE,
      SHIFT_ID,
      QUALITY_STATUS,
      MERCURY_REQUIRED,
      CRPT_REQUIRED,
      MERCURY_STATUS,
      CRPT_STATUS,
      CREATED_AT,
      CREATED_BY
    ) values (
      v_id,
      p_prod_batch_no,
      p_production_order_id,
      p_source_system,
      p_source_message_id,
      p_external_operation_id,
      p_external_batch_id,
      p_articul,
      p_mod_id,
      p_gtin,
      p_product_name,
      p_produced_date_from,
      p_produced_date_to,
      p_expiry_date_from,
      p_expiry_date_to,
      p_total_quantity,
      p_total_pack_count,
      p_unit_code,
      p_ware_id,
      p_production_line,
      p_shift_id,
      'DRAFT',
      nvl(p_mercury_required, 0),
      nvl(p_crpt_required, 0),
      case when nvl(p_mercury_required, 0) = 1 then 'PENDING' else 'NOT_REQUIRED' end,
      case when nvl(p_crpt_required, 0) = 1 then 'PENDING' else 'NOT_REQUIRED' end,
      sysdate,
      p_created_by
    );

    return v_id;
  end create_prod_batch;

  procedure attach_pallet(
    p_prod_batch_id        number,
    p_uid_pallet           varchar2,
    p_pallet_no            number default null,
    p_quantity             number default null,
    p_pack_count           number default null,
    p_net_weight           number default null,
    p_gross_weight         number default null,
    p_sscc                 varchar2 default null,
    p_quality_status       varchar2 default null,
    p_created_by           varchar2 default user
  ) is
  begin
    merge into RRL_PROD_BATCH_PALLETS d
    using (
      select p_prod_batch_id PROD_BATCH_ID,
             p_uid_pallet UID_PALLET
        from dual
    ) s
    on (d.PROD_BATCH_ID = s.PROD_BATCH_ID and d.UID_PALLET = s.UID_PALLET)
    when matched then update set
      d.PALLET_NO = nvl(p_pallet_no, d.PALLET_NO),
      d.QUANTITY = nvl(p_quantity, d.QUANTITY),
      d.PACK_COUNT = nvl(p_pack_count, d.PACK_COUNT),
      d.NET_WEIGHT = nvl(p_net_weight, d.NET_WEIGHT),
      d.GROSS_WEIGHT = nvl(p_gross_weight, d.GROSS_WEIGHT),
      d.SSCC = nvl(p_sscc, d.SSCC)
    when not matched then insert (
      PROD_BATCH_ID, UID_PALLET, PALLET_NO, QUANTITY, PACK_COUNT,
      NET_WEIGHT, GROSS_WEIGHT, SSCC, AGGREGATION_STATUS, CREATED_AT, CREATED_BY
    ) values (
      p_prod_batch_id, p_uid_pallet, p_pallet_no, p_quantity, p_pack_count,
      p_net_weight, p_gross_weight, p_sscc, 'DRAFT', sysdate, p_created_by
    );

    update RRL_PALLETS
       set PROD_BATCH_ID = p_prod_batch_id,
           SSCC = nvl(p_sscc, SSCC),
           QUALITY_STATUS = nvl(p_quality_status, QUALITY_STATUS)
     where UID_PALLET = p_uid_pallet;
  end attach_pallet;

  function register_raw_batch(
    p_raw_batch_no         varchar2,
    p_articul              varchar2 default null,
    p_supplier_id          varchar2 default null,
    p_producer_name        varchar2 default null,
    p_quantity_initial     number default null,
    p_quantity_available   number default null,
    p_unit_code            varchar2 default 'PCS',
    p_ware_id              number default null,
    p_mercury_stock_entry_uuid varchar2 default null,
    p_mercury_vsd_uuid     varchar2 default null,
    p_created_by           varchar2 default user
  ) return number is
    v_id number;
  begin
    begin
      select RAW_BATCH_ID
        into v_id
        from RRL_RAW_BATCH
       where RAW_BATCH_NO = p_raw_batch_no
         and nvl(ARTICUL, '#') = nvl(p_articul, '#')
         and nvl(WARE_ID, -1) = nvl(p_ware_id, -1)
         and rownum = 1;
      return v_id;
    exception
      when no_data_found then null;
    end;

    select RRL_RAW_BATCH_SQ.nextval into v_id from dual;

    insert into RRL_RAW_BATCH (
      RAW_BATCH_ID, RAW_BATCH_NO, ARTICUL, SUPPLIER_ID, PRODUCER_NAME,
      QUANTITY_INITIAL, QUANTITY_AVAILABLE, UNIT_CODE, WARE_ID,
      MERCURY_STOCK_ENTRY_UUID, MERCURY_VSD_UUID, CREATED_AT, CREATED_BY
    ) values (
      v_id, p_raw_batch_no, p_articul, p_supplier_id, p_producer_name,
      p_quantity_initial, nvl(p_quantity_available, p_quantity_initial), p_unit_code, p_ware_id,
      p_mercury_stock_entry_uuid, p_mercury_vsd_uuid, sysdate, p_created_by
    );

    return v_id;
  end register_raw_batch;

  function add_raw_usage(
    p_prod_batch_id        number,
    p_raw_batch_id         number default null,
    p_raw_articul          varchar2 default null,
    p_quantity_planned     number default null,
    p_quantity_fact        number default null,
    p_unit_code            varchar2 default 'PCS',
    p_used_by              varchar2 default user
  ) return number is
    v_id number;
  begin
    select RRL_PROD_RAW_USAGE_SQ.nextval into v_id from dual;

    insert into RRL_PROD_RAW_USAGE (
      RAW_USAGE_ID, PROD_BATCH_ID, RAW_BATCH_ID, RAW_ARTICUL,
      QUANTITY_PLANNED, QUANTITY_FACT, UNIT_CODE, USED_AT, USED_BY
    ) values (
      v_id, p_prod_batch_id, p_raw_batch_id, p_raw_articul,
      p_quantity_planned, p_quantity_fact, p_unit_code, sysdate, p_used_by
    );

    return v_id;
  end add_raw_usage;

  procedure set_mercury_batch(
    p_prod_batch_id        number,
    p_mercury_operation_id varchar2 default null,
    p_stock_entry_uuid     varchar2 default null,
    p_stock_entry_guid     varchar2 default null,
    p_vet_document_uuid    varchar2 default null,
    p_vet_document_status  varchar2 default null,
    p_vet_document_type    varchar2 default null,
    p_vet_document_form    varchar2 default null,
    p_product_item_guid    varchar2 default null,
    p_product_item_name    varchar2 default null,
    p_last_error           varchar2 default null
  ) is
  begin
    merge into RRL_MERCURY_BATCH d
    using (select p_prod_batch_id PROD_BATCH_ID from dual) s
    on (d.PROD_BATCH_ID = s.PROD_BATCH_ID)
    when matched then update set
      d.MERCURY_OPERATION_ID = nvl(p_mercury_operation_id, d.MERCURY_OPERATION_ID),
      d.STOCK_ENTRY_UUID = nvl(p_stock_entry_uuid, d.STOCK_ENTRY_UUID),
      d.STOCK_ENTRY_GUID = nvl(p_stock_entry_guid, d.STOCK_ENTRY_GUID),
      d.VET_DOCUMENT_UUID = nvl(p_vet_document_uuid, d.VET_DOCUMENT_UUID),
      d.VET_DOCUMENT_STATUS = nvl(p_vet_document_status, d.VET_DOCUMENT_STATUS),
      d.VET_DOCUMENT_TYPE = nvl(p_vet_document_type, d.VET_DOCUMENT_TYPE),
      d.VET_DOCUMENT_FORM = nvl(p_vet_document_form, d.VET_DOCUMENT_FORM),
      d.PRODUCT_ITEM_GUID = nvl(p_product_item_guid, d.PRODUCT_ITEM_GUID),
      d.PRODUCT_ITEM_NAME = nvl(p_product_item_name, d.PRODUCT_ITEM_NAME),
      d.LAST_ERROR = substr(p_last_error, 1, 4000),
      d.UPDATED_AT = sysdate
    when not matched then insert (
      PROD_BATCH_ID, MERCURY_OPERATION_ID, STOCK_ENTRY_UUID, STOCK_ENTRY_GUID,
      VET_DOCUMENT_UUID, VET_DOCUMENT_STATUS, VET_DOCUMENT_TYPE, VET_DOCUMENT_FORM,
      PRODUCT_ITEM_GUID, PRODUCT_ITEM_NAME, LAST_ERROR, UPDATED_AT
    ) values (
      p_prod_batch_id, p_mercury_operation_id, p_stock_entry_uuid, p_stock_entry_guid,
      p_vet_document_uuid, p_vet_document_status, p_vet_document_type, p_vet_document_form,
      p_product_item_guid, p_product_item_name, substr(p_last_error, 1, 4000), sysdate
    );

    update RRL_PROD_BATCH
       set MERCURY_STATUS = nvl(p_vet_document_status, MERCURY_STATUS),
           UPDATED_AT = sysdate,
           UPDATED_BY = user
     where PROD_BATCH_ID = p_prod_batch_id;
  end set_mercury_batch;

  function add_crpt_code(
    p_prod_batch_id        number,
    p_uid_pallet           varchar2 default null,
    p_gtin                 varchar2,
    p_cis                  varchar2,
    p_serial_no            varchar2 default null,
    p_datamatrix_full      varchar2 default null,
    p_parent_sscc          varchar2 default null
  ) return number is
    v_id number;
  begin
    begin
      select CRPT_CODE_ID
        into v_id
        from RRL_CRPT_CODES
       where CIS = p_cis;
      return v_id;
    exception
      when no_data_found then null;
    end;

    select RRL_CRPT_CODES_SQ.nextval into v_id from dual;

    insert into RRL_CRPT_CODES (
      CRPT_CODE_ID, PROD_BATCH_ID, UID_PALLET, GTIN, CIS, SERIAL_NO,
      DATAMATRIX_FULL, CODE_STATUS, PARENT_SSCC, CREATED_AT
    ) values (
      v_id, p_prod_batch_id, p_uid_pallet, p_gtin, p_cis, p_serial_no,
      p_datamatrix_full, 'RESERVED', p_parent_sscc, sysdate
    );

    return v_id;
  end add_crpt_code;

  function create_aggregation(
    p_sscc                 varchar2,
    p_prod_batch_id        number default null,
    p_uid_pallet           varchar2 default null,
    p_parent_sscc          varchar2 default null,
    p_aggregation_level    varchar2 default 'PALLET'
  ) return number is
    v_id number;
  begin
    begin
      select AGGREGATION_ID
        into v_id
        from RRL_CRPT_AGGREGATION
       where SSCC = p_sscc;
      return v_id;
    exception
      when no_data_found then null;
    end;

    select RRL_CRPT_AGGREGATION_SQ.nextval into v_id from dual;

    insert into RRL_CRPT_AGGREGATION (
      AGGREGATION_ID, SSCC, PROD_BATCH_ID, UID_PALLET, PARENT_SSCC,
      AGGREGATION_LEVEL, AGGREGATION_STATUS, CREATED_AT
    ) values (
      v_id, p_sscc, p_prod_batch_id, p_uid_pallet, p_parent_sscc,
      p_aggregation_level, 'DRAFT', sysdate
    );

    if p_uid_pallet is not null then
      update RRL_PROD_BATCH_PALLETS
         set SSCC = p_sscc,
             AGGREGATION_STATUS = 'DRAFT'
       where PROD_BATCH_ID = p_prod_batch_id
         and UID_PALLET = p_uid_pallet;

      update RRL_PALLETS
         set SSCC = p_sscc
       where UID_PALLET = p_uid_pallet;
    end if;

    return v_id;
  end create_aggregation;

  procedure add_aggregation_item(
    p_aggregation_id       number,
    p_child_type           varchar2,
    p_child_cis            varchar2 default null,
    p_child_sscc           varchar2 default null,
    p_gtin                 varchar2 default null,
    p_prod_batch_id        number default null
  ) is
    v_count number;
    v_parent_sscc varchar2(32);
  begin
    select SSCC
      into v_parent_sscc
      from RRL_CRPT_AGGREGATION
     where AGGREGATION_ID = p_aggregation_id;

    select count(*)
      into v_count
      from RRL_CRPT_AGGREGATION_ITEMS
     where AGGREGATION_ID = p_aggregation_id
       and CHILD_TYPE = p_child_type
       and nvl(CHILD_CIS, '#') = nvl(p_child_cis, '#')
       and nvl(CHILD_SSCC, '#') = nvl(p_child_sscc, '#');

    if v_count = 0 then
      insert into RRL_CRPT_AGGREGATION_ITEMS (
        AGGREGATION_ID, CHILD_TYPE, CHILD_CIS, CHILD_SSCC,
        GTIN, PROD_BATCH_ID, CREATED_AT
      ) values (
        p_aggregation_id, p_child_type, p_child_cis, p_child_sscc,
        p_gtin, p_prod_batch_id, sysdate
      );
    end if;

    if p_child_type = 'CIS' and p_child_cis is not null then
      update RRL_CRPT_CODES
         set PARENT_SSCC = v_parent_sscc
       where CIS = p_child_cis;
    elsif p_child_type = 'SSCC' and p_child_sscc is not null then
      update RRL_CRPT_AGGREGATION
         set PARENT_SSCC = v_parent_sscc
       where SSCC = p_child_sscc;
    end if;
  end add_aggregation_item;

  function enqueue_event(
    p_system_code          varchar2,
    p_event_type           varchar2,
    p_prod_batch_id        number default null,
    p_uid_pallet           varchar2 default null,
    p_document_no          varchar2 default null,
    p_payload_json         clob default null,
    p_idempotency_key      varchar2 default null
  ) return number is
    v_id number;
  begin
    if p_idempotency_key is not null then
      begin
        select OUTBOX_ID
          into v_id
          from RRL_REGULATORY_OUTBOX
         where IDEMPOTENCY_KEY = p_idempotency_key
           and rownum = 1;
        return v_id;
      exception
        when no_data_found then null;
      end;
    end if;

    select RRL_REGULATORY_OUTBOX_SQ.nextval into v_id from dual;

    insert into RRL_REGULATORY_OUTBOX (
      OUTBOX_ID, SYSTEM_CODE, EVENT_TYPE, PROD_BATCH_ID, UID_PALLET,
      DOCUMENT_NO, PAYLOAD_JSON, STATUS, TRY_COUNT, CREATED_AT, IDEMPOTENCY_KEY
    ) values (
      v_id, p_system_code, p_event_type, p_prod_batch_id, p_uid_pallet,
      p_document_no, p_payload_json, 'PENDING', 0, sysdate, p_idempotency_key
    );

    return v_id;
  end enqueue_event;

  procedure set_batch_status(
    p_prod_batch_id        number,
    p_quality_status       varchar2 default null,
    p_mercury_status       varchar2 default null,
    p_crpt_status          varchar2 default null,
    p_updated_by           varchar2 default user
  ) is
  begin
    update RRL_PROD_BATCH
       set QUALITY_STATUS = nvl(p_quality_status, QUALITY_STATUS),
           MERCURY_STATUS = nvl(p_mercury_status, MERCURY_STATUS),
           CRPT_STATUS = nvl(p_crpt_status, CRPT_STATUS),
           UPDATED_AT = sysdate,
           UPDATED_BY = p_updated_by
     where PROD_BATCH_ID = p_prod_batch_id;
  end set_batch_status;

  function register_file_message(
    p_exchange_type        varchar2,
    p_source_system        varchar2,
    p_message_id           varchar2,
    p_external_operation_id varchar2 default null,
    p_file_name            varchar2 default null,
    p_file_path            varchar2 default null,
    p_file_hash            varchar2 default null
  ) return number is
    v_id number;
  begin
    begin
      select FILE_LOG_ID
        into v_id
        from RRL_FILE_EXCHANGE_LOG
       where MESSAGE_ID = p_message_id;
      return v_id;
    exception
      when no_data_found then null;
    end;

    select RRL_FILE_EXCHANGE_LOG_SQ.nextval into v_id from dual;

    insert into RRL_FILE_EXCHANGE_LOG (
      FILE_LOG_ID, EXCHANGE_TYPE, SOURCE_SYSTEM, MESSAGE_ID,
      EXTERNAL_OPERATION_ID, FILE_NAME, FILE_PATH, FILE_HASH,
      STATUS, RECEIVED_AT
    ) values (
      v_id, p_exchange_type, p_source_system, p_message_id,
      p_external_operation_id, p_file_name, p_file_path, p_file_hash,
      'RECEIVED', sysdate
    );

    return v_id;
  end register_file_message;

  procedure mark_file_processed(
    p_message_id           varchar2,
    p_prod_batch_id        number default null,
    p_processed_by         varchar2 default user
  ) is
  begin
    update RRL_FILE_EXCHANGE_LOG
       set STATUS = 'PROCESSED',
           ERROR_CODE = null,
           ERROR_TEXT = null,
           PROCESSED_AT = sysdate,
           PROCESSED_BY = p_processed_by,
           CREATED_PROD_BATCH_ID = nvl(p_prod_batch_id, CREATED_PROD_BATCH_ID)
     where MESSAGE_ID = p_message_id;
  end mark_file_processed;

  procedure mark_file_error(
    p_message_id           varchar2,
    p_error_code           varchar2,
    p_error_text           varchar2,
    p_processed_by         varchar2 default user
  ) is
  begin
    update RRL_FILE_EXCHANGE_LOG
       set STATUS = 'ERROR',
           ERROR_CODE = p_error_code,
           ERROR_TEXT = substr(p_error_text, 1, 4000),
           PROCESSED_AT = sysdate,
           PROCESSED_BY = p_processed_by
     where MESSAGE_ID = p_message_id;
  end mark_file_error;

  function get_setting(p_setting_key varchar2) return varchar2 is
    v_value varchar2(4000);
  begin
    select SETTING_VALUE
      into v_value
      from RRL_SYSTEM_SETTINGS
     where SETTING_KEY = p_setting_key;
    return v_value;
  exception
    when no_data_found then
      return null;
  end get_setting;

  procedure set_setting(
    p_setting_key          varchar2,
    p_setting_value        varchar2,
    p_description          varchar2 default null
  ) is
  begin
    merge into RRL_SYSTEM_SETTINGS d
    using (
      select p_setting_key SETTING_KEY,
             p_setting_value SETTING_VALUE,
             p_description DESCRIPTION
        from dual
    ) s
    on (d.SETTING_KEY = s.SETTING_KEY)
    when matched then update set
      d.SETTING_VALUE = s.SETTING_VALUE,
      d.DESCRIPTION = nvl(s.DESCRIPTION, d.DESCRIPTION),
      d.UPDATED_AT = sysdate,
      d.UPDATED_BY = user
    when not matched then insert (
      SETTING_KEY, SETTING_VALUE, DESCRIPTION, UPDATED_AT, UPDATED_BY
    ) values (
      s.SETTING_KEY, s.SETTING_VALUE, s.DESCRIPTION, sysdate, user
    );
  end set_setting;
end RRL_PRODUCTION_API;
/


CREATE OR REPLACE package body RRL_QC_SCOPE_READ as
 function policy_json(p_domain clob) return clob is
  d json_object_t:=json_object_t.parse(p_domain);j json_object_t:=json_object_t();
  w number:=d.get_number('warehouse');origin_ware number:=w;document_no number:=d.get_number('document_id');addr varchar2(255);category varchar2(10);
  mode_name varchar2(10);independent number;percent number;selected_flag number:=0;
  ex_whole number:=0;ex_storage number:=0;depth_no number:=0;visited varchar2(2000):='|';stamp varchar2(16000):='';
  token varchar2(100);digest varchar2(64);
 begin
  select ADDR into addr from RRL_SBORKA_PALLETS where ID=document_no;
  category:=case when d.get_number('case_task') is null then 'STOCK' else 'CASE' end;
  select nvl(s.OUTGOING_QC_MODE,case when nvl(wa.BLOCK_IF_NO_PROOVE,0)=1 then 'ANY' else 'NONE' end),
   nvl(s.OUTGOING_QC_INDEPENDENT,0),nvl(s.OUTGOING_QC_SAMPLE_PERCENT,0)
   into mode_name,independent,percent from RRL_WARES wa left join RRL_RECEIPT_WARE_SETTINGS s on s.WARE_ID=wa.ID where wa.ID=w;
  while w is not null loop
   depth_no:=depth_no+1;token:=RRL_STOCK_PLAN_HELPER.decimal_text(w);
   if depth_no>16 or instr(visited,'|'||token||'|')>0 then raise_application_error(-20886,'QUALITY_WAREHOUSE_HIERARCHY_INVALID');end if;
   visited:=visited||token||'|';
   for r in(select * from RRL_QC_SCOPE_RULE where WARE_ID=w and STORE_ADDR in('*',addr)
    and PLACE_CATEGORY in('ANY',category)
    order by case when STORE_ADDR=addr then 0 else 1 end,case when PLACE_CATEGORY=category then 0 else 1 end)loop
    stamp:=stamp||length(token)||':'||token||length(r.STORE_ADDR)||':'||r.STORE_ADDR||':'||r.PLACE_CATEGORY||':'||r.RULE_VERSION||':'||r.ACTIVE_FLAG||';';
    if selected_flag=0 and r.ACTIVE_FLAG=1 then
     selected_flag:=1;mode_name:=r.CONTROL_MODE;independent:=r.INDEPENDENT_FLAG;percent:=r.SAMPLE_PERCENT;
     ex_whole:=r.EXEMPT_WHOLE;ex_storage:=r.EXEMPT_STORAGE;
     j.put('rule_warehouse_id',r.WARE_ID);j.put('store_addr',r.STORE_ADDR);j.put('place_category',r.PLACE_CATEGORY);j.put('rule_version',r.RULE_VERSION);
    end if;
   end loop;
   select PARENT_WARE_ID into w from RRL_WARES where ID=w;
  end loop;
  if stamp is not null then select standard_hash(stamp,'SHA256') into digest from dual;j.put('policy_stamp',digest);end if;
  j.put('warehouse_id',origin_ware);j.put('mode',mode_name);j.put('independent',independent);j.put('sample_percent',percent);
  j.put('exempt_whole',ex_whole);j.put('exempt_storage',ex_storage);j.put('scoped_rule',selected_flag=1);return j.to_clob;
 end;
 function exemption_json(p_domain clob) return clob is
  d json_object_t:=json_object_t.parse(p_domain);p json_object_t:=json_object_t.parse(policy_json(p_domain));
  j json_object_t:=json_object_t();legs json_array_t:=d.get_array('legs');leg json_object_t;
  v_uid varchar2(200);v_qty number;epoch number;original_qty number;v_uom varchar2(20);op varchar2(100);state_name varchar2(30);
  current_qty number;receipt_json clob;receipt json_object_t;article varchar2(160);batch_no number;expiry date;produced date;birth_op varchar2(100);origin_uid varchar2(200);
  storage_task number;storage_op varchar2(100);storage_cell varchar2(60);selected_cell varchar2(60);
  storage_document number:=d.get_number('document_id');storage_customer number:=d.get_number('customer_order_id');
  storage_identifier varchar2(200):=d.get_string('pallet_identifier');bound_version number:=d.get_number('bound_stock_version');
  current_bound_version number:=d.get_number('bound_current_stock_version');
 begin
  j.put('eligible',false);j.put('reason','NO_APPLICABLE_WHOLE_PALLET_EXCEPTION');
  if p.get_number('exempt_whole')!=1 and p.get_number('exempt_storage')!=1 then return j.to_clob;end if;
  if d.get_number('case_task') is not null or legs.get_size!=1 then j.put('reason','COMPOSITE_OR_CASE_REQUIRES_CONTROL');return j.to_clob;end if;
  leg:=treat(legs.get(0) as json_object_t);v_uid:=leg.get_string('uid');v_qty:=RRL_STOCK_MATH.quantity(leg.get_string('quantity'));
  select STOCK_COMPOSITION_VERSION,ARTICUL,PROD_BATCH_ID,EXPIRY_DATE,PRODUCED_DATE,CREATED_BY_STOCK_OP,STOCK_ORIGIN_UID into epoch,article,batch_no,expiry,produced,birth_op,origin_uid from RRL_PALLETS where UID_PALLET=v_uid;
  -- A fresh native birth changes epoch 0 -> 1. Any later partial/change/restore advances it again.
  if epoch!=1 then j.put('reason','PALLET_CHANGED_OR_LEGACY_PROVENANCE_UNKNOWN');return j.to_clob;end if;
  select r.POSTED_BASE_QTY,r.STOCK_BASE_UOM,r.STOCK_OPERATION_ID,o.STATE,r.RESULT_JSON into original_qty,v_uom,op,state_name,receipt_json
   from RRL_SAP_PALLET_RECEIPT r join RRL_STOCK_OPERATION o on o.OPERATION_ID=r.STOCK_OPERATION_ID where r.UID_PALLET=v_uid;
  select nvl(sum(REMAIN),0) into current_qty from RRL_REMAINS where UID_POLETA=v_uid;
  receipt:=json_object_t.parse(receipt_json);
  if state_name!='APPLIED' or original_qty!=v_qty or current_qty!=v_qty or v_uom!=leg.get_string('base_uom')
   or nvl(article,chr(0))!=nvl(receipt.get_string('material'),chr(0))
   or batch_no is not null or nvl(birth_op,chr(0))!=op or nvl(origin_uid,chr(0))!=v_uid
   or nvl(to_char(expiry,'YYYY-MM-DD'),chr(0))!=nvl(receipt.get_string('expiry_date'),chr(0))
   or nvl(to_char(produced,'YYYY-MM-DD'),chr(0))!=nvl(receipt.get_string('produced_date'),chr(0))
   then j.put('reason','WHOLE_ORIGINAL_RECEIPT_NOT_PROVED');return j.to_clob;end if;
  if p.get_number('exempt_whole')!=1 then
   -- Storage barcode is the existing scanned full-pallet binding, never a label pattern.
   if d.get_string('bound_physical_uid')is null or d.get_string('bound_physical_uid')!=v_uid
    or d.get_number('customer_order_id')is null then
    j.put('reason','STORAGE_IDENTIFIER_BINDING_REQUIRED');return j.to_clob;
   end if;
   selected_cell:=leg.get_string('cell');
   begin
    select wh.TASK_ID,m.OPERATION_ID,m.FROM_CELL into storage_task,storage_op,storage_cell
     from RRL_CUSTOMER_ORDER_FULFILLMENT ff
     join RRL_WAREHOUSE_TASK wh on wh.TASK_ID=ff.PICKED_WAREHOUSE_TASK_ID
     join RRL_WAREHOUSE_TASK_STOCK_MOVE m on m.TASK_ID=wh.TASK_ID and m.OPERATION_ID=ff.PICKED_OPERATION_ID
     join RRL_STOCK_OPERATION stock_op on stock_op.OPERATION_ID=m.OPERATION_ID
     join RRL_REMAINS current_stock on current_stock.UID_POLETA=ff.PICKED_PALLET_UID and current_stock.CELL=m.TO_CELL
     where ff.LEGACY_SBORKA_PALLET_ID=storage_document
      and ff.PALLET_UID=storage_identifier and ff.CUSTOMER_ORDER_ID=storage_customer
      and ff.STATUS='PICKED' and ff.PICKED_PALLET_UID=v_uid and ff.PICKED_STOCK_VERSION=bound_version
      and wh.TASK_SOURCE='WAVE' and wh.TASK_TYPE='PICKING_MOVE' and wh.QTY_MODE='PALLET' and wh.STATUS='DONE'
      and stock_op.STATE='APPLIED' and stock_op.COMMAND_TYPE='TASK_COMPLETE'
      and m.UID_PALLET=v_uid and m.TARGET_UID_PALLET=v_uid and m.BASE_QTY=v_qty and m.BASE_UOM=v_uom
      and current_stock.STOCK_VERSION=current_bound_version
      and current_stock.REMAIN=v_qty and current_stock.BASE_UOM=v_uom and current_stock.CELL=selected_cell;
   exception when no_data_found or too_many_rows then
    j.put('reason','STORAGE_IDENTIFIER_BINDING_NOT_PROVED');return j.to_clob;
   end;
   j.put('exemption_basis','SCANNED_ORIGINAL_STORAGE_IDENTIFIER');j.put('storage_pick_task_id',storage_task);
   j.put('storage_pick_operation_id',storage_op);j.put('storage_source_cell',storage_cell);
  else j.put('exemption_basis','WHOLE_UNCHANGED_NATIVE_RECEIPT');end if;
  j.put('eligible',true);j.put('reason','WHOLE_NATIVE_RECEIPT_UNCHANGED');j.put('uid_pallet',v_uid);
  j.put('supplier_batch',receipt.get_string('supplier_batch'));j.put('receipt_operation_id',op);j.put('base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));j.put('base_uom',v_uom);
  j.put('composition_epoch',epoch);j.put('policy',p);return j.to_clob;
 exception when no_data_found or too_many_rows then j.put('eligible',false);j.put('reason','ORIGINAL_RECEIPT_PROVENANCE_UNAVAILABLE');return j.to_clob;
 end;
 procedure record_exemption(p_domain clob,p_signature varchar2) is
  op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');d json_object_t:=json_object_t.parse(p_domain);
  proof json_object_t;payload clob;existing clob;document_no number:=d.get_number('document_id');
 begin
  if op is null then return;end if;
  proof:=json_object_t.parse(exemption_json(p_domain));if not proof.get_boolean('eligible') then return;end if;
  if proof.get_object('policy').get_string('mode') not in('ANY','WEIGHT','BOTH')then return;end if;
  proof.put('composition_signature',p_signature);proof.put('operation_id',op);proof.put('document_id',d.get_number('document_id'));payload:=proof.to_clob;
  begin select PAYLOAD_JSON into existing from RRL_QC_EXEMPT_FACT where OPERATION_ID=op and DOCUMENT_ID=document_no;
   if dbms_lob.compare(existing,payload)!=0 then raise_application_error(-20886,'QUALITY_EXEMPTION_PROOF_CONFLICT');end if;
  exception when no_data_found then insert into RRL_QC_EXEMPT_FACT(OPERATION_ID,DOCUMENT_ID,PAYLOAD_JSON) values(op,document_no,payload);end;
 end;
end;
/


CREATE OR REPLACE package body RRL_RECIPIENT_PALLET_POLICY as
 function rule_id(p_customer number,p_store number)return number is result_id number;
 begin
  select CUSTOMER_PALLET_TYPE_RULE_ID into result_id from RRL_CUSTOMER_PALLET_TYPE_RULE
   where CUSTOMER_ID=p_customer and(CUSTOMER_STORE_MAP_ID=p_store or(CUSTOMER_STORE_MAP_ID is null and CUSTOMER_ADDRESS_ID is null))
    and ACTIVE=1 and trunc(sysdate)between VALID_FROM and nvl(VALID_TO,date '2999-12-31')
   order by case when CUSTOMER_STORE_MAP_ID=p_store then 0 else 1 end,IS_DEFAULT desc,CUSTOMER_PALLET_TYPE_RULE_ID
   fetch first 1 row only;
  return result_id;
 exception when no_data_found then return null;
 end;
 function type_id(p_customer number,p_store number)return number is result_id number;rule_no number:=rule_id(p_customer,p_store);
 begin
  select r.PALLET_TYPE_ID into result_id from RRL_CUSTOMER_PALLET_TYPE_RULE r join RRL_PALLET_TYPE t on t.PALLET_TYPE_ID=r.PALLET_TYPE_ID
   where r.CUSTOMER_PALLET_TYPE_RULE_ID=rule_no and t.ACTIVE=1;
  return result_id;
 exception when no_data_found then return null;
 end;
end;
/


CREATE OR REPLACE package body RRL_REGULATORY_API as
  function upsert_mercury_site(
    p_site_code           varchar2,
    p_site_name           varchar2 default null,
    p_ware_id             number default null,
    p_enterprise_guid     varchar2 default null,
    p_enterprise_uuid     varchar2 default null,
    p_business_guid       varchar2 default null,
    p_business_uuid       varchar2 default null,
    p_address_text        varchar2 default null,
    p_active              number default 1,
    p_updated_by          varchar2 default user
  ) return number is
    v_id number;
  begin
    begin
      select MERCURY_SITE_ID into v_id
        from RRL_MERCURY_SITE
       where SITE_CODE = p_site_code;
    exception
      when no_data_found then
        select RRL_MERCURY_SITE_SQ.nextval into v_id from dual;
        insert into RRL_MERCURY_SITE (
          MERCURY_SITE_ID, SITE_CODE, SITE_NAME, WARE_ID,
          ENTERPRISE_GUID, ENTERPRISE_UUID, BUSINESS_GUID, BUSINESS_UUID,
          ADDRESS_TEXT, ACTIVE, CREATED_AT, CREATED_BY
        ) values (
          v_id, p_site_code, p_site_name, p_ware_id,
          p_enterprise_guid, p_enterprise_uuid, p_business_guid, p_business_uuid,
          p_address_text, nvl(p_active, 1), sysdate, p_updated_by
        );
        return v_id;
    end;

    update RRL_MERCURY_SITE
       set SITE_NAME = nvl(p_site_name, SITE_NAME),
           WARE_ID = nvl(p_ware_id, WARE_ID),
           ENTERPRISE_GUID = nvl(p_enterprise_guid, ENTERPRISE_GUID),
           ENTERPRISE_UUID = nvl(p_enterprise_uuid, ENTERPRISE_UUID),
           BUSINESS_GUID = nvl(p_business_guid, BUSINESS_GUID),
           BUSINESS_UUID = nvl(p_business_uuid, BUSINESS_UUID),
           ADDRESS_TEXT = nvl(p_address_text, ADDRESS_TEXT),
           ACTIVE = nvl(p_active, ACTIVE),
           UPDATED_AT = sysdate,
           UPDATED_BY = p_updated_by
     where MERCURY_SITE_ID = v_id;

    return v_id;
  end upsert_mercury_site;

  function create_mercury_operation(
    p_prod_batch_id       number default null,
    p_raw_batch_id        number default null,
    p_mercury_site_id     number default null,
    p_operation_type      varchar2,
    p_mercury_operation_id varchar2 default null,
    p_external_operation_id varchar2 default null,
    p_status              varchar2 default 'DRAFT',
    p_request_json        clob default null,
    p_created_by          varchar2 default user
  ) return number is
    v_id number;
    v_journal_id number;
  begin
    if p_mercury_operation_id is not null then
      begin
        select MERCURY_OPERATION_ROW_ID into v_id
          from RRL_MERCURY_OPERATION
         where MERCURY_OPERATION_ID = p_mercury_operation_id
           and rownum = 1;
        return v_id;
      exception
        when no_data_found then null;
      end;
    end if;

    select RRL_MERCURY_OPERATION_SQ.nextval into v_id from dual;

    insert into RRL_MERCURY_OPERATION (
      MERCURY_OPERATION_ROW_ID, PROD_BATCH_ID, RAW_BATCH_ID, MERCURY_SITE_ID,
      OPERATION_TYPE, MERCURY_OPERATION_ID, EXTERNAL_OPERATION_ID, STATUS,
      REQUEST_JSON, STARTED_AT, CREATED_AT, CREATED_BY
    ) values (
      v_id, p_prod_batch_id, p_raw_batch_id, p_mercury_site_id,
      p_operation_type, p_mercury_operation_id, p_external_operation_id, nvl(p_status, 'DRAFT'),
      p_request_json, case when nvl(p_status, 'DRAFT') in ('SENT', 'PROCESSING') then sysdate else null end,
      sysdate, p_created_by
    );

    v_journal_id := write_journal(
      p_system_code => 'MERCURY',
      p_entity_type => 'MERCURY_OPERATION',
      p_entity_id => to_char(v_id),
      p_prod_batch_id => p_prod_batch_id,
      p_raw_batch_id => p_raw_batch_id,
      p_operation_type => p_operation_type,
      p_new_status => nvl(p_status, 'DRAFT'),
      p_external_operation_id => p_external_operation_id,
      p_payload_json => p_request_json,
      p_created_by => p_created_by
    );

    if p_prod_batch_id is not null and p_mercury_site_id is not null then
      update RRL_PROD_BATCH
         set MERCURY_SITE_ID = p_mercury_site_id,
             UPDATED_AT = sysdate,
             UPDATED_BY = p_created_by
       where PROD_BATCH_ID = p_prod_batch_id;
    end if;

    return v_id;
  end create_mercury_operation;

  procedure update_mercury_operation(
    p_operation_row_id    number,
    p_status              varchar2 default null,
    p_mercury_operation_id varchar2 default null,
    p_external_operation_id varchar2 default null,
    p_response_json       clob default null,
    p_last_error          varchar2 default null,
    p_updated_by          varchar2 default user
  ) is
    v_old_status varchar2(50);
    v_new_status varchar2(50);
    v_prod_batch_id number;
    v_raw_batch_id number;
    v_journal_id number;
  begin
    select STATUS, PROD_BATCH_ID, RAW_BATCH_ID
      into v_old_status, v_prod_batch_id, v_raw_batch_id
      from RRL_MERCURY_OPERATION
     where MERCURY_OPERATION_ROW_ID = p_operation_row_id;

    v_new_status := nvl(p_status, v_old_status);

    update RRL_MERCURY_OPERATION
       set STATUS = v_new_status,
           MERCURY_OPERATION_ID = nvl(p_mercury_operation_id, MERCURY_OPERATION_ID),
           EXTERNAL_OPERATION_ID = nvl(p_external_operation_id, EXTERNAL_OPERATION_ID),
           RESPONSE_JSON = nvl(p_response_json, RESPONSE_JSON),
           LAST_ERROR = substr(p_last_error, 1, 4000),
           FINISHED_AT = case when v_new_status in ('ACCEPTED', 'REJECTED', 'ERROR', 'DONE') then sysdate else FINISHED_AT end,
           UPDATED_AT = sysdate,
           UPDATED_BY = p_updated_by
     where MERCURY_OPERATION_ROW_ID = p_operation_row_id;

    v_journal_id := write_journal(
      p_system_code => 'MERCURY',
      p_entity_type => 'MERCURY_OPERATION',
      p_entity_id => to_char(p_operation_row_id),
      p_prod_batch_id => v_prod_batch_id,
      p_raw_batch_id => v_raw_batch_id,
      p_operation_type => 'STATUS',
      p_old_status => v_old_status,
      p_new_status => v_new_status,
      p_external_operation_id => p_external_operation_id,
      p_payload_json => p_response_json,
      p_message => p_last_error,
      p_created_by => p_updated_by
    );
  end update_mercury_operation;

  function write_journal(
    p_system_code         varchar2,
    p_entity_type         varchar2,
    p_entity_id           varchar2 default null,
    p_prod_batch_id       number default null,
    p_raw_batch_id        number default null,
    p_uid_pallet          varchar2 default null,
    p_sscc                varchar2 default null,
    p_operation_type      varchar2,
    p_old_status          varchar2 default null,
    p_new_status          varchar2 default null,
    p_document_id         varchar2 default null,
    p_external_operation_id varchar2 default null,
    p_payload_json        clob default null,
    p_message             varchar2 default null,
    p_created_by          varchar2 default user
  ) return number is
    v_id number;
  begin
    select RRL_REG_OPERATION_JOURNAL_SQ.nextval into v_id from dual;

    insert into RRL_REG_OPERATION_JOURNAL (
      JOURNAL_ID, SYSTEM_CODE, ENTITY_TYPE, ENTITY_ID, PROD_BATCH_ID, RAW_BATCH_ID,
      UID_PALLET, SSCC, OPERATION_TYPE, OLD_STATUS, NEW_STATUS, DOCUMENT_ID,
      EXTERNAL_OPERATION_ID, PAYLOAD_JSON, MESSAGE, CREATED_AT, CREATED_BY
    ) values (
      v_id, p_system_code, p_entity_type, p_entity_id, p_prod_batch_id, p_raw_batch_id,
      p_uid_pallet, p_sscc, p_operation_type, p_old_status, p_new_status, p_document_id,
      p_external_operation_id, p_payload_json, substr(p_message, 1, 4000), sysdate, p_created_by
    );

    return v_id;
  end write_journal;

  function set_crpt_code_status(
    p_cis                 varchar2,
    p_code_status         varchar2,
    p_event_type          varchar2 default null,
    p_document_id         varchar2 default null,
    p_document_no         varchar2 default null,
    p_payload_json        clob default null,
    p_error_text          varchar2 default null,
    p_updated_by          varchar2 default user
  ) return number is
    v_code_id number;
    v_prod_batch_id number;
    v_uid_pallet varchar2(50);
    v_parent_sscc varchar2(32);
    v_old_status varchar2(50);
    v_circ_id number;
    v_event_type varchar2(30);
    v_journal_id number;
  begin
    select CRPT_CODE_ID, PROD_BATCH_ID, UID_PALLET, PARENT_SSCC, CODE_STATUS
      into v_code_id, v_prod_batch_id, v_uid_pallet, v_parent_sscc, v_old_status
      from RRL_CRPT_CODES
     where CIS = p_cis;

    v_event_type := upper(p_event_type);

    update RRL_CRPT_CODES
       set CODE_STATUS = p_code_status,
           INTRODUCED_AT = case when v_event_type = 'INTRODUCE' then sysdate else INTRODUCED_AT end,
           WITHDRAWN_AT = case when v_event_type = 'WITHDRAW' then sysdate else WITHDRAWN_AT end,
           INTRODUCTION_DOCUMENT_ID = case when v_event_type = 'INTRODUCE' then p_document_id else INTRODUCTION_DOCUMENT_ID end,
           WITHDRAWAL_DOCUMENT_ID = case when v_event_type = 'WITHDRAW' then p_document_id else WITHDRAWAL_DOCUMENT_ID end,
           LAST_STATUS_AT = sysdate,
           LAST_ERROR = substr(p_error_text, 1, 4000)
     where CRPT_CODE_ID = v_code_id;

    if v_event_type in ('INTRODUCE', 'WITHDRAW') then
      select RRL_CRPT_CIRCULATION_SQ.nextval into v_circ_id from dual;

      insert into RRL_CRPT_CIRCULATION (
        CIRCULATION_ID, EVENT_TYPE, PROD_BATCH_ID, UID_PALLET, SSCC, CIS,
        DOCUMENT_ID, DOCUMENT_NO, STATUS, PAYLOAD_JSON, ACCEPTED_AT,
        ERROR_TEXT, CREATED_AT, CREATED_BY
      ) values (
        v_circ_id, v_event_type, v_prod_batch_id, v_uid_pallet, v_parent_sscc, p_cis,
        p_document_id, p_document_no, p_code_status, p_payload_json,
        case when p_error_text is null then sysdate else null end,
        substr(p_error_text, 1, 4000), sysdate, p_updated_by
      );
    end if;

    v_journal_id := write_journal(
      p_system_code => 'CRPT',
      p_entity_type => 'CRPT_CODE',
      p_entity_id => p_cis,
      p_prod_batch_id => v_prod_batch_id,
      p_uid_pallet => v_uid_pallet,
      p_sscc => v_parent_sscc,
      p_operation_type => nvl(v_event_type, 'STATUS'),
      p_old_status => v_old_status,
      p_new_status => p_code_status,
      p_document_id => p_document_id,
      p_payload_json => p_payload_json,
      p_message => p_error_text,
      p_created_by => p_updated_by
    );

    return v_code_id;
  end set_crpt_code_status;
  procedure declare_stock_events(p_operation varchar2,p_event varchar2,p_profiles clob,p_resources in out nocopy json_array_t)is
  begin RRL_REGULATORY_STOCK_OUTBOX.declare_events(p_operation,p_event,p_profiles,p_resources);end;
  function enqueue_stock_events(p_operation varchar2,p_event varchar2,p_domain clob,p_units clob,p_profiles clob)return clob is
  begin return RRL_REGULATORY_STOCK_OUTBOX.enqueue_events(p_operation,p_event,p_domain,p_units,p_profiles);end;
end RRL_REGULATORY_API;
/


CREATE OR REPLACE package body RRL_REGULATORY_STOCK_OUTBOX as
 function event_key(p_operation varchar2,p_event varchar2,p_system varchar2)return varchar2 is
 begin
  if p_event not in('MARKED_GOODS_DISPOSED','MARKED_SUPPLIER_RETURN_DISPATCHED')then raise_application_error(-20871,'REGULATORY_STOCK_EVENT_KIND_REQUIRED');end if;
  return case p_event when 'MARKED_GOODS_DISPOSED'then 'RETURN.DISPOSAL.GOV:'else 'RETURN.SUPPLIER.GOV:'end||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation||chr(0)||p_system,'AL32UTF8'),sys.dbms_crypto.hash_sh256));
 end;
 procedure declare_events(p_operation varchar2,p_event varchar2,p_profiles clob,p_resources in out nocopy json_array_t)is k varchar2(100);
 begin
  for x in(select distinct S from json_table(p_profiles,'$[*]'columns(S varchar2(40)path '$.system_code'))order by S)loop
   if x.S is null or lengthb(x.S)>30 then raise_application_error(-20871,'REGULATORY_TARGET_SYSTEM_BOUND');end if;
   k:=event_key(p_operation,p_event,x.S);RRL_STOCK_PLAN_HELPER.anchor(p_resources,70,'UNIQUE',k);
  end loop;
 end;
 function enqueue_events(p_operation varchar2,p_event varchar2,p_domain clob,p_units clob,p_profiles clob)return clob is
  frozen clob;kind_text varchar2(80);domain json_object_t;source json_object_t;gov json_object_t;code_wire clob;gov_id number;k varchar2(100);ids json_array_t:=json_array_t();units_count number;n number;
 begin
  if p_operation!=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)then raise_application_error(-20863,'REGULATORY_STOCK_FACT_ROOT_CONTEXT_REQUIRED');end if;
  select COMMAND_TYPE,RESOLVED_PLAN_JSON into kind_text,frozen from RRL_STOCK_OPERATION where OPERATION_ID=p_operation and STATE='IN_FLIGHT';
  domain:=json_object_t.parse(frozen).get_object('domain');
  if p_event='MARKED_GOODS_DISPOSED'and kind_text='STORE_RETURN_DISPOSE'then source:=domain;
   if dbms_lob.compare(source.get_array('disposal_units').to_clob,p_units)!=0 or dbms_lob.compare(source.get_array('disposal_profiles').to_clob,p_profiles)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: disposal regulatory source');end if;
  elsif p_event='MARKED_SUPPLIER_RETURN_DISPATCHED'and kind_text='LOAD_SHIPMENT'then source:=domain.get_object('shipment').get_object('domain').get_object('supplier_return_source');
   if dbms_lob.compare(source.get_array('units').to_clob,p_units)!=0 or dbms_lob.compare(source.get_array('profiles').to_clob,p_profiles)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: supplier regulatory source');end if;
  else raise_application_error(-20863,'REGULATORY_STOCK_FACT_MATCHING_COMMAND_REQUIRED');end if;
  if dbms_lob.compare(source.to_clob,p_domain)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: regulatory frozen domain');end if;
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',source.get_string('uid')));
  select count(*),count(distinct K)into units_count,n from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key'));
  if units_count<1 or units_count>10000 or units_count!=n then raise_application_error(-20881,'REGULATORY_STOCK_UNIT_BOUND');end if;
  for x in(select K from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key'))order by K)loop RRL_STOCK_LOCK_API.assert_held(60,RRL_STOCK_LOCK_API.resource_key('UNIT',x.K));end loop;
  for target in(select distinct S from json_table(p_profiles,'$[*]'columns(S varchar2(30)path '$.system_code'))order by S)loop
   select json_arrayagg(json_object('physical_unit_key'value u.PHYSICAL_UNIT_KEY,'origin_uid'value u.UID_PALLET,'unit_id'value u.UNIT_ID,'code_hash'value c.CODE_HASH,'canonical_code'value c.CANONICAL_CODE,'profiles'value c.PROFILES_JSON format json)order by u.PHYSICAL_UNIT_KEY,c.CODE_HASH returning clob)into code_wire
    from RRL_WMS_RECEIPT_UNIT u join RRL_WMS_RECEIPT_CODE c on c.UID_PALLET=u.UID_PALLET and c.UNIT_ID=u.UNIT_ID
    where c.SYSTEM_CODE=target.S and u.PHYSICAL_UNIT_KEY in(select K from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key')));
   if code_wire is null then raise_application_error(-20886,'REGULATORY_STOCK_CANONICAL_CODES_REQUIRED');end if;
   gov:=json_object_t.parse(p_domain);gov.put('contract_version',1);gov.put('operation_id',p_operation);gov.put('operation_type',case p_event when 'MARKED_GOODS_DISPOSED'then 'DISPOSAL'else 'SUPPLIER_RETURN_DISPATCH'end);gov.put('system_code',target.S);gov.put('codes',json_array_t.parse(code_wire));gov.put('physical_disposal_recorded',p_event='MARKED_GOODS_DISPOSED');gov.put('external_ack_verified',false);
   k:=event_key(p_operation,p_event,target.S);RRL_STOCK_LOCK_API.assert_held(70,RRL_STOCK_LOCK_API.resource_key('UNIQUE',k));
   gov_id:=RRL_TRACEABILITY_API.enqueue_event(p_event,'STOCK_OPERATION',p_operation,k,gov.to_clob,target.S,p_operation);ids.append(gov_id);
  end loop;
  return ids.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_RETURN_PALLET_IDENTITY as
 procedure assert_preserved(p_approval varchar2,p_uid varchar2)is
 a RRL_STORE_RETURN_APPROVAL%rowtype;p RRL_PALLETS%rowtype;n number;qty number;
 begin
  select *into a from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=p_approval;
  if p_uid is null or p_uid!=a.LOT_UID then raise_application_error(-20886,'RETURN_PALLET_ORIGINAL_IDENTITY_REQUIRED');end if;
  select *into p from RRL_PALLETS where UID_PALLET=p_uid;
  if p.ARTICUL is null or p.ARTICUL!=a.ARTICLE or p.UNIT_COUNT is null or p.UNIT_COUNT!=a.BASE_QTY then
   raise_application_error(-20886,'RETURN_PALLET_FULL_ORIGINAL_QUANTITY_REQUIRED');
  end if;
  select count(*)into n from RRL_REMAINS where UID_POLETA=p_uid and(REMAIN!=0 or HARD_RESERVED_BASE!=0);
  if n!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: preserved pallet still has warehouse stock');end if;
  select count(*)into n from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 and(PARENT_UID=p_uid or CHILD_PALLET_UID=p_uid);
  if n!=0 then raise_application_error(-20886,'RETURN_PALLET_EXPLICIT_HU_UNPACK_REQUIRED');end if;
  select count(*)into n from RRL_CASE_CARRIER_LOT where LOT_UID=p_uid;
  if n!=0 then raise_application_error(-20886,'RETURN_PALLET_ORIGINAL_CASE_REPACKING_UNSUPPORTED');end if;
  select count(*)into n from RRL_WAREHOUSE_TASK where UID_PALLET=p_uid and STATUS not in('DONE','CANCELLED');
  if n!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: preserved pallet physical task issued');end if;
  select count(*),sum(BASE_QTY)into n,qty from RRL_WMS_RECEIPT_UNIT
   where UID_PALLET=p_uid and CURRENT_UID=p_uid and STOCK_STATUS='ISSUED'and HARD_RESERVATION_ID is null;
  if n<1 or qty!=a.BASE_QTY then raise_application_error(-20886,'RETURN_PALLET_UNCHANGED_ORIGINAL_UNITS_REQUIRED');end if;
  select count(*)into n from RRL_WMS_RECEIPT_UNIT u where u.UID_PALLET=p_uid
   and not exists(select 1 from RRL_STORE_RETURN_UNIT b where b.APPROVAL_OPERATION_ID=p_approval and b.PHYSICAL_UNIT_KEY=u.PHYSICAL_UNIT_KEY);
  if n!=0 then raise_application_error(-20886,'RETURN_PALLET_FULL_APPROVED_COMPOSITION_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_RETURN_REUSE_API as
 procedure preview(p_receipt varchar2,p_line number,p_quantity varchar2,p_actor varchar2,p_result out clob)is
  n number;qty number;used number;line RRL_STORE_RECEIPT_LINE%rowtype;proof json_object_t;b json_object_t:=json_object_t();reason varchar2(1000);
 begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'store_return_approve')=1;
  if n!=1 then raise_application_error(-20882,'STORE_RETURN_CURRENT_APPROVER_REQUIRED');end if;
  if p_receipt is null or lengthb(p_receipt)>100 or p_line is null or p_line<1 or p_line>200 or trunc(p_line)!=p_line then raise_application_error(-20886,'RETURN_REUSE_SOURCE_REQUIRED');end if;
  qty:=RRL_STOCK_MATH.quantity(p_quantity);if qty<=0 then raise_application_error(-20886,'RETURN_REUSE_POSITIVE_QUANTITY_REQUIRED');end if;
  select *into line from RRL_STORE_RECEIPT_LINE where OPERATION_ID=p_receipt and LINE_NO=p_line;
  select nvl(sum(BASE_QTY),0)into used from RRL_STORE_RETURN_APPROVAL where RECEIPT_OPERATION_ID=p_receipt and LINE_NO=p_line and RETURN_BASIS='ACCEPTED';
  b.put('receipt_operation_id',p_receipt);b.put('line_no',p_line);b.put('article',line.ARTICLE);b.put('base_uom',line.BASE_UOM);
  b.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));b.put('available_for_approval',RRL_STOCK_PLAN_HELPER.decimal_text(line.ACCEPTED_BASE_QTY-used));
  begin
   RRL_STOCK_RETURN_REUSE.describe_source(line.LOT_UID,line.ARTICLE,line.BASE_UOM,qty,proof);
   b.put('source_eligible',true);b.put('source_proof',proof);b.put_null('source_reason');
   if qty<=line.ACCEPTED_BASE_QTY-used then b.put('currently_approvable',true);else b.put('currently_approvable',false);end if;
  exception when others then
   if sqlcode=-20886 then
    reason:=substr(sqlerrm,instr(sqlerrm,':')+2);b.put('source_eligible',false);b.put('currently_approvable',false);b.put('source_reason',reason);b.put_null('source_proof');
   else raise;end if;
  end;
  b.put('physical_completeness_verified',false);b.put('marked_unit_selection_verified',false);b.put('read_only',true);b.put('stock_changed',false);
  p_result:=b.to_clob;
 exception when no_data_found then raise_application_error(-20886,'RETURN_REUSE_ORIGINAL_LINE_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_SAP_RECEIPT_API as

 g_allowed boolean:=false;

 function pallet_write_allowed return boolean is begin return g_allowed; end;

 procedure register_pallet(p_sscc varchar2,p_articul varchar2,p_expiry date,p_produced date,

 p_qty number,p_naklad number,p_actor varchar2) is n number;v_reg_sscc varchar2(32);v_sum number:=0;

 begin

 select count(*) into n from RRL_SAP_SUPPLY_ORDER where NAKLAD_ID=p_naklad;

 if n!=1 or p_qty<=0 then raise_application_error(-20803,'Invalid SAP receiving document/quantity'); end if;

 if p_sscc is null or length(p_sscc)>50 or lengthb(p_sscc)>150 or regexp_like(p_sscc,'[[:space:][:cntrl:]]')then raise_application_error(-20803,'Invalid physical pallet identifier');end if;
 if regexp_like(p_sscc,'^[0-9]{18}$')then
  for i in 1..17 loop v_sum:=v_sum+to_number(substr(p_sscc,i,1))*case when mod(i,2)=1 then 3 else 1 end;end loop;
  if mod(10-mod(v_sum,10),10)=to_number(substr(p_sscc,18,1))then v_reg_sscc:=p_sscc;end if;
 end if;
 g_allowed:=true;

 begin

 insert into RRL_PALLETS(UID_PALLET,SSCC,ARTICUL,CREATION_DATE,EXPIRY_DATE,PRODUCED_DATE,UNIT_COUNT,PRIHOD_NAKLAD_ID,KLADOVSHIK,PRINTED)

 values(p_sscc,v_reg_sscc,p_articul,sysdate,p_expiry,p_produced,p_qty,p_naklad,substr(p_actor,1,15),0);

 g_allowed:=false;

 exception when others then g_allowed:=false; raise;

 end;

 end;

end;
/


CREATE OR REPLACE package body RRL_SAP_STORE_ADMISSION_API as
 g_tx varchar2(100);
 function write_allowed return number is begin
  if g_tx is not null and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure context(p_order number,p_actor varchar2,p_result out clob)is
  v_ware number;v_version number;saved RRL_SAP_STORE_DECISION%rowtype;b json_object_t:=json_object_t();
 begin
  select WARE_ID into v_ware from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=p_order;
  RRL_STORE_ORDER_SCOPE.assert_scope(p_actor,'customer_order_view',v_ware);
  select nvl(max(VERSION_NO),0)into v_version from RRL_SAP_STORE_DECISION where CUSTOMER_ORDER_ID=p_order;
  b.put('customer_order_id',p_order);b.put('version',v_version);
  if v_version>0 then
   select *into saved from RRL_SAP_STORE_DECISION where CUSTOMER_ORDER_ID=p_order and VERSION_NO=v_version;
   b.put('last_decision',json_object_t.parse(saved.RESULT_JSON));
  end if;p_result:=b.to_clob;
 end;
 procedure apply_decision(p_actor varchar2,p_body clob,p_result out clob)is
  b json_object_t;src RRL_SAP_STORE_ORDER%rowtype;co RRL_CUSTOMER_ORDER%rowtype;
  saved RRL_SAP_STORE_DECISION%rowtype;v_meta boolean:=false;
  v_sender varchar2(100);v_message varchar2(100);v_decision varchar2(100);v_order varchar2(100);v_hash varchar2(64);v_original varchar2(64);v_code varchar2(10);
  v_id number;v_ware number;own_ware number;v_global number;v_version number;n number;v_status varchar2(30);v_co_status varchar2(30);
  v_reason nvarchar2(500);v_ref nvarchar2(500);v_raw clob;v_offset number;v_allowed number;v_rule clob;v_zone varchar2(10);v_finish timestamp with time zone;cached json_object_t;r json_object_t:=json_object_t();
 begin
  RRL_STORE_ORDER_SCOPE.actor_scope(p_actor,'sap_store_decision_import',own_ware,v_global);
  if p_body is null or dbms_lob.getlength(p_body)>8*1024*1024 then raise_application_error(-20886,'STORE_ADMISSION_BODY_BOUND');end if;
  b:=json_object_t.parse(p_body);
  if b.get_size!=11 or b.get_number('expected_version')is null or b.get_number('expected_version')<0 or trunc(b.get_number('expected_version'))!=b.get_number('expected_version')then raise_application_error(-20886,'STORE_ADMISSION_INPUT_FIELDS_INVALID');end if;
  v_sender:=b.get_string('sender');v_message:=b.get_string('message_id');v_decision:=b.get_string('decision_id');
  v_order:=b.get_string('order_number');v_hash:=b.get_string('payload_hash');v_original:=b.get_string('original_content_hash');v_code:=b.get_string('decision');
  v_reason:=b.get_string('reason');v_ref:=b.get_string('reference');v_raw:=b.get_clob('raw_xml');
  if v_sender is null or v_message is null or v_decision is null or v_order is null or v_hash is null or not regexp_like(v_hash,'^[a-f0-9]{64}$','c')
   or v_original is null or not regexp_like(v_original,'^[a-f0-9]{64}$','c')or v_code is null or v_code not in('ACCEPT','REJECT')
   or v_reason is null or length(trim(v_reason))<8 or v_ref is null or length(trim(v_ref))<8 or v_raw is null then raise_application_error(-20886,'STORE_ADMISSION_EXPLICIT_SOURCE_REQUIRED');end if;
  select s.CUSTOMER_ORDER_ID,c.WARE_ID into v_id,v_ware from RRL_SAP_STORE_ORDER s join RRL_CUSTOMER_ORDER c on c.CUSTOMER_ORDER_ID=s.CUSTOMER_ORDER_ID where s.SENDER=v_sender and s.ORDER_NUMBER=v_order;
  RRL_STORE_ORDER_SCOPE.assert_scope(p_actor,'sap_store_decision_import',v_ware);
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'sap_store_decision_import');v_meta:=true;savepoint RRL_ADMISSION267;
  select *into co from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=v_id for update;
  select *into src from RRL_SAP_STORE_ORDER where CUSTOMER_ORDER_ID=v_id for update;
  RRL_STORE_ORDER_SCOPE.assert_scope(p_actor,'sap_store_decision_import',co.WARE_ID);
  begin select *into saved from RRL_SAP_STORE_DECISION where SENDER=v_sender and MESSAGE_ID=v_message;
   cached:=json_object_t.parse(saved.RESULT_JSON);
   if saved.PAYLOAD_HASH!=v_hash or saved.CUSTOMER_ORDER_ID!=v_id
    or saved.DECISION_ID!=v_decision or saved.DECISION_CODE!=v_code or saved.ORIGINAL_CONTENT_HASH!=v_original
    or saved.VERSION_NO!=b.get_number('expected_version')+1 or dbms_lob.compare(saved.RAW_XML,v_raw)!=0
    or cached.get_string('reason')!=v_reason
    or cached.get_string('reference')!=v_ref then raise_application_error(-20886,'STORE_ADMISSION_MESSAGE_PAYLOAD_CONFLICT');end if;
   p_result:=saved.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;
  exception when no_data_found then null;end;
  select count(*)into n from RRL_SAP_STORE_DECISION where SENDER=v_sender and DECISION_ID=v_decision;
  if n>0 then raise_application_error(-20886,'STORE_ADMISSION_DECISION_USE_ORIGINAL_MESSAGE');end if;
  select nvl(max(VERSION_NO),0)into v_version from RRL_SAP_STORE_DECISION where CUSTOMER_ORDER_ID=v_id;
  if b.get_number('expected_version')is null or b.get_number('expected_version')!=v_version or src.CONTENT_HASH!=v_original then raise_application_error(-20886,'STORE_ADMISSION_SOURCE_VERSION_CHANGED');end if;
  if src.PREPARATION_HASH is not null or co.STATUS not in('DRAFT','IMPORTED','OPEN')then raise_application_error(-20886,'STORE_ADMISSION_OPERATIONAL_SOURCE_FROZEN');end if;
  select(select count(*)from RRL_PICK_PLAN where CUSTOMER_ORDER_ID=v_id and STATUS!='CANCELLED')
   +(select count(*)from RRL_CUSTOMER_ORDER_FULFILLMENT where CUSTOMER_ORDER_ID=v_id and STATUS!='CANCELLED')
   +(select count(*)from RRL_STOCK_RESERVATION where(CUSTOMER_ORDER_ID=v_id or(SOURCE_DOC_TYPE='CUSTOMER_ORDER'and SOURCE_DOC_ID=v_id))and STATUS in('ACTIVE','ALLOCATED','PICKING'))into n from dual;
  if n>0 then raise_application_error(-20886,'STORE_ADMISSION_PLANNING_ALREADY_STARTED');end if;
  if v_code='ACCEPT'then
   if src.ADMISSION_STATUS not in('PENDING_LATE','PENDING_CALENDAR')then raise_application_error(-20886,'STORE_ADMISSION_PENDING_SOURCE_REQUIRED');end if;
   RRL_STORE_CALENDAR_API.delivery_rule(co.WARE_ID,co.CUSTOMER_STORE_MAP_ID,src.DELIVERY_DATE,v_offset,v_allowed,v_rule);
   if v_allowed!=1 then raise_application_error(-20886,'STORE_ADMISSION_CALENDAR_CLOSED');end if;
   if v_offset!=src.UTC_OFFSET_MINUTES then raise_application_error(-20886,'STORE_ADMISSION_CALENDAR_ZONE_CHANGED');end if;
   v_zone:=case when src.UTC_OFFSET_MINUTES<0 then '-'else '+'end||lpad(trunc(abs(src.UTC_OFFSET_MINUTES)/60),2,'0')||':'||lpad(mod(abs(src.UTC_OFFSET_MINUTES),60),2,'0');
   select from_tz(cast(src.PICKING_FINISH_AT as timestamp),v_zone)into v_finish from dual;
   if v_finish<=systimestamp then raise_application_error(-20886,'STORE_ADMISSION_PICKING_DEADLINE_PASSED');end if;
   v_status:='ACCEPTED';v_co_status:='IMPORTED';
  else
   if src.ADMISSION_STATUS='REJECTED'then raise_application_error(-20886,'STORE_ADMISSION_ALREADY_REJECTED');end if;
   v_status:='REJECTED';v_co_status:='CANCELLED';
  end if;
  r.put('sender',v_sender);r.put('message_id',v_message);r.put('decision_id',v_decision);r.put('customer_order_id',v_id);
  r.put('version',v_version+1);r.put('original_content_hash',src.CONTENT_HASH);r.put('previous_admission_status',src.ADMISSION_STATUS);
  r.put('admission_status',v_status);r.put('customer_order_status',v_co_status);r.put('reason',v_reason);r.put('reference',v_ref);r.put('actor',p_actor);
  r.put('stock_changed',false);r.put('original_demand_changed',false);r.put('original_schedule_changed',false);
  if v_rule is not null then r.put('calendar_proof',json_object_t.parse(v_rule));end if;
  p_result:=r.to_clob;g_tx:=dbms_transaction.local_transaction_id(false);
  update RRL_SAP_STORE_ORDER set ADMISSION_STATUS=v_status where CUSTOMER_ORDER_ID=v_id;
  update RRL_CUSTOMER_ORDER set STATUS=v_co_status,UPDATED_AT=sysdate,UPDATED_BY=p_actor where CUSTOMER_ORDER_ID=v_id;
  insert into RRL_SAP_STORE_DECISION(SENDER,MESSAGE_ID,DECISION_ID,CUSTOMER_ORDER_ID,VERSION_NO,PAYLOAD_HASH,ORIGINAL_CONTENT_HASH,DECISION_CODE,ACTOR,RAW_XML,RESULT_JSON)
   values(v_sender,v_message,v_decision,v_id,v_version+1,v_hash,v_original,v_code,p_actor,v_raw,p_result);
  g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
 exception when others then
  if v_meta then rollback to RRL_ADMISSION267;end if;g_tx:=null;
  if v_meta then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_SCALE_PACKET_READ as
 function utc_stamp(p_text varchar2)return timestamp with time zone is
 begin
  if p_text is null or not regexp_like(p_text,'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}[+]00:00$','c')then raise_application_error(-20886,'SCALE_UTC_TIMESTAMP_REQUIRED');end if;
  return to_timestamp_tz(p_text,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
 exception when others then
  if sqlcode=-20886 then raise;end if;
  raise_application_error(-20886,'SCALE_VALID_UTC_TIMESTAMP_REQUIRED');
 end;
 function validate_json(p_source clob,p_capacity number,p_resolution number,
  p_expected_basis varchar2 default 'GROSS',p_sample_field varchar2 default 'gross_weight_kg')return clob is
  j json_object_t;result_json json_object_t:=json_object_t();samples json_array_t;x json_object_t;
  minimum number;maximum number;last_weight number;offset_no number;previous_offset number:=-1;first_offset number;span_ms number;
  zero_weight number;zero_text varchar2(30);measured_at timestamp with time zone;zero_at timestamp with time zone;now_at timestamp with time zone:=systimestamp;
 begin
  if p_source is null or dbms_lob.getlength(p_source)>32000 then raise_application_error(-20881,'SCALE_PACKET_BOUND_32000');end if;
  if p_capacity is null or p_resolution is null or p_resolution<=0 or p_capacity<p_resolution then raise_application_error(-20886,'SCALE_RESOLUTION_CAPACITY_INVALID');end if;
  if p_expected_basis is null or p_expected_basis not in('GROSS','NET')or p_sample_field is null or p_sample_field not in('gross_weight_kg','weight_kg')then raise_application_error(-20886,'SCALE_EXPLICIT_BASIS_REQUIRED');end if;
  RRL_STOCK_MATH.assert_base(p_capacity,9);RRL_STOCK_MATH.assert_base(p_resolution,9);
  j:=json_object_t.parse(p_source);
  if j.get_string('unit')is null or j.get_string('unit')!='KG'or j.get_string('basis')is null or j.get_string('basis')!=p_expected_basis
   or not j.has('zero_confirmed')or j.get_string('preset_tare_kg')is null or j.get_string('preset_tare_kg')!='0'
   then raise_application_error(-20886,'SCALE_KG_GROSS_ZERO_PRESET_REQUIRED');end if;
  if j.get_boolean('zero_confirmed')then null;else raise_application_error(-20886,'SCALE_ZERO_CONFIRMATION_REQUIRED');end if;
  measured_at:=utc_stamp(j.get_string('measured_at'));zero_at:=utc_stamp(j.get_string('zero_check_at'));
  if measured_at>now_at+numtodsinterval(2,'SECOND')or measured_at<now_at-numtodsinterval(30,'SECOND')
   or zero_at>measured_at or zero_at<measured_at-numtodsinterval(600,'SECOND')then raise_application_error(-20886,'SCALE_FRESH_ZERO_AND_MEASUREMENT_REQUIRED');end if;
  zero_text:=j.get_string('zero_check_kg');if substr(zero_text,1,1)='-'then zero_text:=substr(zero_text,2);end if;
  if regexp_like(zero_text,'^0{1,18}([.]0{1,9})?$','c')then zero_weight:=0;else zero_weight:=RRL_STOCK_MATH.quantity(zero_text);end if;
  if zero_weight>p_resolution then raise_application_error(-20886,'SCALE_ZERO_CHECK_OUTSIDE_RESOLUTION');end if;
  if not j.has('samples')or not j.get('samples').is_array then raise_application_error(-20886,'SCALE_SAMPLE_ARRAY_REQUIRED');end if;samples:=j.get_array('samples');
  if samples.get_size<5 or samples.get_size>25 then raise_application_error(-20881,'SCALE_SAMPLE_BOUND_5_25');end if;
  for i in 0..samples.get_size-1 loop
   x:=treat(samples.get(i)as json_object_t);offset_no:=x.get_number('offset_ms');last_weight:=RRL_STOCK_MATH.quantity(x.get_string(p_sample_field));
   if offset_no is null or offset_no!=trunc(offset_no)or offset_no<0 or offset_no>10000 or offset_no<=previous_offset or last_weight>p_capacity or mod(last_weight,p_resolution)!=0 then raise_application_error(-20886,'SCALE_SAMPLE_ORDER_OR_CAPACITY_INVALID');end if;
   if i=0 then first_offset:=offset_no;minimum:=last_weight;maximum:=last_weight;end if;
   minimum:=least(minimum,last_weight);maximum:=greatest(maximum,last_weight);previous_offset:=offset_no;
  end loop;
  span_ms:=previous_offset-first_offset;
  if first_offset!=0 or span_ms<2000 or maximum-minimum>p_resolution then raise_application_error(-20886,'SCALE_STABLE_WINDOW_REQUIRED');end if;
  result_json.put('weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(last_weight));result_json.put('basis',p_expected_basis);
  result_json.put('sample_min_kg',RRL_STOCK_PLAN_HELPER.decimal_text(minimum));result_json.put('sample_max_kg',RRL_STOCK_PLAN_HELPER.decimal_text(maximum));
  result_json.put('sample_count',samples.get_size);result_json.put('span_ms',span_ms);
  result_json.put('measured_at',j.get_string('measured_at'));result_json.put('zero_check_at',j.get_string('zero_check_at'));
  return result_json.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_SSCC_ALLOCATOR as
 procedure assert_scope(p_ware number,p_actor varchar2,p_permission varchar2)is
  n number;
 begin
  if p_permission not in('case_pick_execute','warehouse_receipt_confirm')or RRL_HAS_WRIGHT(p_actor,p_permission)!=1 then raise_application_error(-20882,'SSCC_PERMISSION_REQUIRED');end if;
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and(upper(trim(USER_GROUP))='GLOBAL_ADMIN'or WARE_ID=p_ware);
  if n!=1 then raise_application_error(-20882,'SSCC_CURRENT_WARE_REQUIRED');end if;
 end;
 function allocate(p_ware number,p_actor varchar2,p_permission varchar2)return varchar2 is
  pref varchar2(20);ext number;serial number;width number;body varchar2(17);code varchar2(18);total number:=0;n number;
 begin
  assert_scope(p_ware,p_actor,p_permission);
  select COMPANY_PREFIX,EXTENSION_DIGIT into pref,ext from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=p_ware;
  if pref is null or not regexp_like(pref,'^[0-9]{6,12}$')or ext is null or ext!=trunc(ext)or ext<0 or ext>9 then raise_application_error(-20887,'ASSIGNED_GS1_PREFIX_REQUIRED');end if;
  select RRL_RECEIPT_SSCC_SQ.nextval into serial from dual;width:=16-length(pref);
  if serial>=power(10,width)then raise_application_error(-20881,'SSCC_SERIAL_RANGE_EXHAUSTED');end if;
  body:=to_char(ext,'FM0')||pref||lpad(to_char(serial,'FM9999999999999990'),width,'0');
  for i in 1..17 loop total:=total+to_number(substr(body,18-i,1))*case when mod(i,2)=1 then 3 else 1 end;end loop;
  code:=body||to_char(mod(10-mod(total,10),10),'FM0');
  select count(*)into n from(select 1 from RRL_PALLETS where UID_PALLET=code or SSCC=code union all
   select 1 from RRL_CASE_PICK_TASK where SSCC=code union all select 1 from RRL_RECEIPT_LABEL where SSCC=code
   union all select 1 from RRL_CASE_SSCC_LABEL where SSCC=code union all select 1 from RRL_SBORKA_PALLETS where PALLET_UID=code)where rownum=1;
  if n>0 then raise_application_error(-20873,'SSCC_ALREADY_EXISTS');end if;
  return code;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_BALANCE_CORE as
 procedure assert_context is v_tx varchar2(100);
 begin
  v_tx:=dbms_transaction.local_transaction_id(false);
  if v_tx is null or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID') is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=v_tx then
   raise_application_error(-20863,'STOCK_WRITE_FORBIDDEN');
  end if;
 end;
 procedure freeze_pack(p_uid varchar2,p_base varchar2) is
  v_frozen number;v_factor number;v_mod number;v_article varchar2(160);v_base varchar2(20);
 begin
  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',p_uid));
  select STOCK_PACK_FROZEN,STOCK_BOX_FACTOR,MOD_ID,ARTICUL,STOCK_PACK_BASE_UOM into v_frozen,v_factor,v_mod,v_article,v_base
   from RRL_PALLETS where UID_PALLET=p_uid;
  if v_frozen=1 then
   if v_base!=p_base then raise_application_error(-20887,'PALLET_PACK_BASE_CONFLICT');end if;
   return;
  end if;
  v_factor:=null;
  if upper(p_base) in('EA','PCS','ST',unistr('\0428\0422')) then
   if nvl(v_mod,0)>0 then
    select SHT_IN_KOR into v_factor from RRL_ARTICUL_MODS where ID=v_mod and ARTICUL=v_article;
   else
    select COUNT_SHT_IN_KOR into v_factor from RRL_ARTICULS where ACTICUL=v_article;
   end if;
   if v_factor is null or v_factor<1 or v_factor!=trunc(v_factor) or v_factor>1000000000 then v_factor:=null;end if;
  end if;
  update RRL_PALLETS set STOCK_BOX_FACTOR=v_factor,STOCK_PACK_BASE_UOM=p_base,STOCK_PACK_FROZEN=1 where UID_PALLET=p_uid;
 end;
 procedure apply_delta(p_uid varchar2,p_cell varchar2,p_delta_p number,p_delta_h number,
   p_base_uom varchar2,p_uom_version number,p_expected_version number default null) is
  v_p number;v_h number;v_ver number;v_uom varchar2(20);v_article varchar2(160);v_scale number;v_exists boolean:=true;
 begin
  assert_context;
  if p_delta_p!=0 then RRL_STOCK_HU_READ.assert_quantity_write(p_uid);end if;
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
  if p_cell is null or p_base_uom is null or p_delta_p is null or p_delta_h is null then
   raise_application_error(-20864,'STOCK_IDENTITY_OR_DELTA_MISSING');
  end if;
  select ARTICUL into v_article from RRL_PALLETS where UID_PALLET=p_uid;
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('SKU',v_article),4);
  begin
   select BASE_SCALE into v_scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article
    and INPUT_UOM=p_base_uom and BASE_UOM=p_base_uom and POLICY_VERSION=p_uom_version
    and NUMERATOR=DENOMINATOR;
  exception when no_data_found then raise_application_error(-20865,'BASE_UOM_POLICY_REQUIRED');
  end;
  RRL_STOCK_MATH.assert_base(p_delta_p,v_scale);RRL_STOCK_MATH.assert_base(p_delta_h,v_scale);
  begin
   select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION,BASE_UOM into v_p,v_h,v_ver,v_uom
    from RRL_REMAINS where UID_POLETA=p_uid and CELL=p_cell for update;
  exception when no_data_found then v_exists:=false;v_p:=0;v_h:=0;v_ver:=0;v_uom:=p_base_uom;
  end;
  if v_uom is null or v_uom!=p_base_uom then raise_application_error(-20866,'STOCK_BASE_UOM_CONFLICT'); end if;
  if p_expected_version is not null and p_expected_version!=v_ver then raise_application_error(-20867,'VERSION_CONFLICT'); end if;
  RRL_STOCK_MATH.assert_base(v_p+p_delta_p,v_scale);RRL_STOCK_MATH.assert_base(v_h+p_delta_h,v_scale);
  if v_p+p_delta_p<0 then raise_application_error(-20868,'STOCK_INSUFFICIENT'); end if;
  if v_h+p_delta_h<0 or v_h+p_delta_h>v_p+p_delta_p then raise_application_error(-20869,'RESERVATION_CONFLICT'); end if;
  if p_delta_p>0 then freeze_pack(p_uid,p_base_uom);end if;
  RRL_STOCK_CTX_API.begin_effect('STOCK',p_uid,p_cell);
  if v_exists then
   update RRL_REMAINS set REMAIN=REMAIN+p_delta_p,HARD_RESERVED_BASE=HARD_RESERVED_BASE+p_delta_h,
    STOCK_VERSION=STOCK_VERSION+1,PHYSICAL_VERSION=PHYSICAL_VERSION+case when p_delta_p!=0 then 1 else 0 end,TIME_OF_LAST_UPDATE=sysdate
    where UID_POLETA=p_uid and CELL=p_cell and STOCK_VERSION=v_ver;
   if sql%rowcount!=1 then raise_application_error(-20867,'VERSION_CONFLICT'); end if;
  else
   insert into RRL_REMAINS(UID_POLETA,CELL,REMAIN,HARD_RESERVED_BASE,STOCK_VERSION,BASE_UOM,TIME_OF_LAST_UPDATE,PHYSICAL_VERSION)
    values(p_uid,p_cell,p_delta_p,p_delta_h,1,p_base_uom,sysdate,case when p_delta_p!=0 then 1 else 0 end);
  end if;
  RRL_STOCK_CTX_API.end_effect;
 exception when others then RRL_STOCK_CTX_API.end_effect;raise;
 end;
 procedure write_event(p_uid varchar2,p_from varchar2,p_to varchar2,p_qty number,p_base_uom varchar2,
   p_uom_version number,p_line number,p_leg number,p_type number,p_actor varchar2,p_event out number,p_outgoing_doc number default null,p_pallet_row number default null) is
  v_prihod number;v_op varchar2(100);
 begin
  assert_context;
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
  if p_qty is null or p_qty=0 or p_base_uom is null or p_line is null or p_line<1 or p_leg is null or p_leg<1 then
   raise_application_error(-20870,'JOURNAL_FACT_INVALID');
  end if;
  v_op:=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');
  select PRIHOD_NAKLAD_ID into v_prihod from RRL_PALLETS where UID_PALLET=p_uid;
  select RRL_EVENT_ID_SQ.nextval into p_event from dual;
  RRL_STOCK_CTX_API.begin_effect('JOURNAL',p_uid,nvl(p_from,p_to));
  insert into RRL_EVENTS(ID_EVENT,CELL_FROM,CELL_TO,DATE_EVENT,COUNT_EVENT,TYPE_EVENT,UID_POLETA,
   USER_ID,PRIHOD_NAKL_ID,OTHOD_NAKL_ID,PALLET_ROW_ID,OPERATION_ID,LINE_NO,LEG_NO,BASE_QTY,BASE_UOM,UOM_POLICY_VERSION)
   values(p_event,p_from,p_to,sysdate,abs(p_qty),p_type,p_uid,p_actor,v_prihod,p_outgoing_doc,p_pallet_row,v_op,p_line,p_leg,p_qty,p_base_uom,p_uom_version);
  RRL_STOCK_CTX_API.end_effect;
 exception when others then RRL_STOCK_CTX_API.end_effect;raise;
 end;
 procedure write_move(p_uid varchar2,p_from varchar2,p_to varchar2,p_qty number,p_base_uom varchar2,p_uom_version number,p_line number,p_actor varchar2,p_event out number) is
 begin
  if p_from is null or p_to is null or p_from=p_to or p_qty is null or p_qty<=0 then raise_application_error(-20870,'MOVE_JOURNAL_CONTRACT');end if;
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CELL',p_from),4);
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CELL',p_to),4);
  write_event(p_uid,p_from,p_to,p_qty,p_base_uom,p_uom_version,p_line,1,2,p_actor,p_event);
 end;
 procedure write_leg(p_uid varchar2,p_from varchar2,p_to varchar2,p_signed_qty number,p_base_uom varchar2,
   p_uom_version number,p_line number,p_leg number,p_type number,p_actor varchar2,p_event out number,p_outgoing_doc number default null,p_pallet_row number default null) is
 begin
  if p_signed_qty is null or p_signed_qty=0 or
   (p_signed_qty<0 and (p_from is null or p_to is not null)) or
   (p_signed_qty>0 and (p_to is null or p_from is not null)) then
   raise_application_error(-20870,'SIGNED_LEG_LOCATION_CONFLICT');
  end if;
  write_event(p_uid,p_from,p_to,p_signed_qty,p_base_uom,p_uom_version,p_line,p_leg,p_type,p_actor,p_event,p_outgoing_doc,p_pallet_row);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CASE_BIND_MOVE as
 function source_snapshot(p_case RRL_CASE_PICK_TASK%rowtype)return json_object_t is
  f RRL_CUSTOMER_ORDER_FULFILLMENT%rowtype;s RRL_SBORKA_PALLETS%rowtype;n number;j json_object_t:=json_object_t();
 begin
  if p_case.LEGACY_SBORKA_PALLET_ID is null then return null;end if;
  select *into s from RRL_SBORKA_PALLETS where ID=p_case.LEGACY_SBORKA_PALLET_ID;
  select count(*)into n from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=s.ID;
  if n!=1 then raise_application_error(-20886,'CASE_MOVE_SINGLE_BOUND_FULFILLMENT_REQUIRED');end if;
  select *into f from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=s.ID;
  -- Closed fulfillment belongs to immutable shipment history, not the current warehouse movement.
  if f.STATUS in('SHIPPED','CANCELLED')then return null;end if;
  if s.WARE_ID is null or s.WARE_ID!=p_case.WARE_ID or nvl(s.CONDITION,0)=2 or s.RETURN_SUPPLIER_ID is not null
   or f.STATUS!='PICKED'or f.PICKED_CASE_TASK_ID is null or f.PICKED_CASE_TASK_ID!=p_case.CASE_PICK_TASK_ID
   or f.CUSTOMER_ORDER_ID!=p_case.CUSTOMER_ORDER_ID or f.PALLET_UID!=s.PALLET_UID
   or f.PICKED_CONTENT_VERSION is null or f.PICKED_CONTENT_VERSION!=p_case.CONTENT_VERSION
   then raise_application_error(-20886,'CASE_MOVE_CURRENT_BOUND_FULFILLMENT_REQUIRED');end if;
  select count(*)into n from RRL_TT_HU_LOAD_ST ls join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=ls.LOAD_OPERATION_ID
   where ls.SBORKA_PALLET_ID=s.ID and ls.ACTIVE_FLAG=1 and l.STATUS in('LOADED','DEPARTED');
  if n>0 then raise_application_error(-20886,'CASE_MOVE_BOUND_LOAD_ALREADY_ACTIVE');end if;
  j.put('st_member_id',s.ID);j.put('st_number',s.ST_NUMBER);j.put('shipment_identifier',s.PALLET_UID);
  j.put('warehouse',s.WARE_ID);j.put('trip',s.TRANSTASK_ID);j.put('st_condition',s.CONDITION);
  j.put('fulfillment_id',f.FULFILLMENT_ID);j.put('customer_order_id',f.CUSTOMER_ORDER_ID);j.put('case_task_id',f.PICKED_CASE_TASK_ID);
  j.put('content_version',f.PICKED_CONTENT_VERSION);j.put('status',f.STATUS);j.put('fact_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(f.FACT_QTY));j.put('fact_uom',f.FACT_UOM);
  if f.FACT_COMPOSITION_JSON is null then raise_application_error(-20886,'CASE_MOVE_ORIGINAL_COMPOSITION_REQUIRED');end if;
  j.put('composition_hash',lower(rawtohex(sys.dbms_crypto.hash(f.FACT_COMPOSITION_JSON,sys.dbms_crypto.hash_sh256))));
  return j;
 exception when no_data_found then raise_application_error(-20886,'CASE_MOVE_BOUND_SOURCE_NOT_FOUND');
 end;
 procedure plan_move(p_case RRL_CASE_PICK_TASK%rowtype,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t)is j json_object_t;
 begin
  j:=source_snapshot(p_case);if j is null then return;end if;
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(j.get_number('st_member_id')));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(j.get_number('fulfillment_id')));
  p_domain.put('shipment_binding',j);
 end;
 procedure validate_move(p_case RRL_CASE_PICK_TASK%rowtype,p_frozen json_object_t)is j json_object_t;
 begin
  j:=source_snapshot(p_case);
  if j is null and p_frozen is null then return;end if;
  if j is null or p_frozen is null or dbms_lob.compare(j.to_clob,p_frozen.to_clob)!=0
   then raise_application_error(-20890,'CLOSURE_CHANGED: CASE shipment binding');end if;
 end;
 procedure finish_move(p_case RRL_CASE_PICK_TASK%rowtype,p_frozen json_object_t,p_version number,p_actor varchar2)is ff_id number;
 begin
  if p_case.LEGACY_SBORKA_PALLET_ID is null then
   if p_frozen is not null then raise_application_error(-20890,'CLOSURE_CHANGED: CASE shipment removed');end if;return;
  end if;
  if p_frozen is null then
   if source_snapshot(p_case)is not null then raise_application_error(-20890,'CLOSURE_CHANGED: CASE current binding appeared');end if;return;
  end if;
  if p_version!=p_case.CONTENT_VERSION+1 or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is null
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)
   then raise_application_error(-20886,'CASE_MOVE_ROOT_BINDING_VERSION_REQUIRED');end if;
  ff_id:=p_frozen.get_number('fulfillment_id');
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(ff_id)));
  update RRL_CUSTOMER_ORDER_FULFILLMENT set PICKED_CONTENT_VERSION=p_version,UPDATED_AT=sysdate,UPDATED_BY=p_actor
   where FULFILLMENT_ID=ff_id and STATUS='PICKED'and PICKED_CASE_TASK_ID=p_case.CASE_PICK_TASK_ID and PICKED_CONTENT_VERSION=p_case.CONTENT_VERSION;
  if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: CASE fulfillment after move');end if;
 end;
 function binding_for(p_domain json_object_t,p_case_id number)return json_object_t is bindings json_object_t;begin
  bindings:=p_domain.get_object('case_bindings');if bindings is null then return null;end if;
  return bindings.get_object(RRL_STOCK_PLAN_HELPER.decimal_text(p_case_id));
 end;
 procedure plan_tree(p_nodes json_array_t,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t)is
  node json_object_t;one_domain json_object_t;bindings json_object_t;ct RRL_CASE_PICK_TASK%rowtype;case_id number;
 begin
  if p_nodes is null then return;end if;
  bindings:=p_domain.get_object('case_bindings');if bindings is null then bindings:=json_object_t();end if;
  for i in 0..p_nodes.get_size-1 loop
   node:=treat(p_nodes.get(i)as json_object_t);
   if node.get_string('kind')='CASE'then
    case_id:=node.get_number('case_task_id');select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=case_id;
    one_domain:=json_object_t();plan_move(ct,p_resources,one_domain);
    if one_domain.has('shipment_binding')then bindings.put(RRL_STOCK_PLAN_HELPER.decimal_text(case_id),one_domain.get_object('shipment_binding'));end if;
   end if;
  end loop;
  p_domain.put('case_bindings',bindings);
 end;
 procedure validate_tree(p_nodes json_array_t,p_domain json_object_t)is node json_object_t;ct RRL_CASE_PICK_TASK%rowtype;case_id number;begin
  if p_nodes is null then return;end if;
  for i in 0..p_nodes.get_size-1 loop
   node:=treat(p_nodes.get(i)as json_object_t);
   if node.get_string('kind')='CASE'then
    case_id:=node.get_number('case_task_id');select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=case_id;
    validate_move(ct,binding_for(p_domain,case_id));
   end if;
  end loop;
 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_CASE_CLOSE as
 procedure actor_scope(p_case varchar2,p_actor varchar2,p_action varchar2)is v_ware number;n number;
 begin
 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0;if n!=1 then raise_application_error(-20882,'CASE_CURRENT_ACTIVE_ACTOR_REQUIRED');end if;
 if p_action='FINDING'then return;end if;
 select WARE_ID into v_ware from RRL_TT_HU_LOAD_FACT l join RRL_STORE_DISCREPANCY_CASE c on c.LOAD_OPERATION_ID=l.LOAD_OPERATION_ID where c.CASE_ID=p_case;
 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=v_ware or upper(trim(USER_GROUP))='GLOBAL_ADMIN');
 if n!=1 then raise_application_error(-20882,'CASE_CURRENT_WAREHOUSE_MANAGER_REQUIRED');end if;
 end;
 procedure describe(p_case varchar2,p_metadata clob,p_actor varchar2,p_domain in out nocopy json_object_t)is
 m json_object_t:=json_object_t.parse(p_metadata);issue RRL_STORE_DISCREPANCY_CASE%rowtype;
 v_exp varchar2(100);v_sec varchar2(100);v_ware number;v_reason varchar2(2000);v_ref varchar2(255);n number;
 begin
 select *into issue from RRL_STORE_DISCREPANCY_CASE where CASE_ID=p_case;
 if issue.STATUS!='ASSIGNED' or issue.EXPEDITION_USER is null or issue.SECURITY_USER is null or issue.EXPEDITION_USER=issue.SECURITY_USER then raise_application_error(-20886,'CASE_CLOSE_ASSIGNED_INVESTIGATION_REQUIRED');end if;
 if p_actor=issue.EXPEDITION_USER or p_actor=issue.SECURITY_USER then raise_application_error(-20882,'CASE_CLOSE_INDEPENDENT_KRO_REQUIRED');end if;
 select OPERATION_ID into v_exp from RRL_STORE_CASE_FINDING where CASE_ID=p_case and ROLE_CODE='EXPEDITION'and REPORTED_BY=issue.EXPEDITION_USER order by CREATED_AT desc,OPERATION_ID desc fetch first 1 row only;
 select OPERATION_ID into v_sec from RRL_STORE_CASE_FINDING where CASE_ID=p_case and ROLE_CODE='SECURITY'and REPORTED_BY=issue.SECURITY_USER order by CREATED_AT desc,OPERATION_ID desc fetch first 1 row only;
 select count(*)into n from RRL_STORE_DELIVERY_OBLIGATION where CASE_ID=p_case and STATUS not in('LOSS_CONFIRMED','CLOSED');
 if n!=0 then raise_application_error(-20886,'CASE_CLOSE_UNRESOLVED_QUANTITY_OBLIGATIONS');end if;
 select count(*)into n from RRL_STORE_RECEIPT_FACT where OPERATION_ID=p_case and nvl(json_value(COMPOSITION_JSON,'$.physical_unit_count'returning number),1)!=0;
 if n!=0 then raise_application_error(-20886,'CASE_CLOSE_MARKED_REGULATORY_FLOW_REQUIRED');end if;
 select count(*)into n from RRL_STORE_RECEIPT_LINE l where l.OPERATION_ID=p_case and(exists(select 1 from RRL_SKU_RECEIPT_PROFILE p where p.ARTICUL=l.ARTICLE)or exists(select 1 from RRL_SKU_RECEIPT_POLICY p where p.ARTICUL=l.ARTICLE and p.MARKING_REQUIRED=1)or exists(select 1 from RRL_FINISHED_GOODS_SKU p where p.ARTICUL=l.ARTICLE and p.CRPT_REQUIRED=1));
 if n!=0 then raise_application_error(-20886,'CASE_CLOSE_CURRENT_MARKED_POLICY_REQUIRED');end if;
 v_reason:=m.get_string('reason');v_ref:=m.get_string('decision_reference');
 if trim(v_reason)is null or lengthb(v_reason)>2000 or trim(v_ref)is null or lengthb(v_ref)>255 then raise_application_error(-20886,'CASE_CLOSE_REASON_AND_DECISION_REQUIRED');end if;
 select WARE_ID into v_ware from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=issue.LOAD_OPERATION_ID;
 p_domain.put('warehouse_id',v_ware);p_domain.put('expedition_finding_op',v_exp);p_domain.put('security_finding_op',v_sec);p_domain.put('reason',v_reason);p_domain.put('decision_reference',v_ref);
 exception when no_data_found then raise_application_error(-20886,'CASE_CLOSE_BOTH_ORIGINAL_FINDINGS_REQUIRED');end;
 procedure declare_resources(p_domain json_object_t,p_operation varchar2,p_resources in out nocopy json_array_t)is
 begin
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_CASE_CLOSURE',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_CASE_FINDING',p_domain.get_string('expedition_finding_op'));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_CASE_FINDING',p_domain.get_string('security_finding_op'));
 RRL_STOCK_PLAN_HELPER.anchor(p_resources,70,'UNIQUE','SAP.OUTBOX:CASE.CLOSE:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 end;
 procedure persist(p_domain json_object_t,p_actor varchar2)is
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');v_case varchar2(100);v_ware number;v_exp varchar2(100);v_sec varchar2(100);v_reason varchar2(2000);v_ref varchar2(255);payload json_object_t;body clob;event_id varchar2(100);
 begin
 v_case:=p_domain.get_string('case_id');v_ware:=p_domain.get_number('warehouse_id');v_exp:=p_domain.get_string('expedition_finding_op');v_sec:=p_domain.get_string('security_finding_op');v_reason:=p_domain.get_string('reason');v_ref:=p_domain.get_string('decision_reference');
 insert into RRL_STORE_CASE_CLOSURE(OPERATION_ID,CASE_ID,WARE_ID,EXPEDITION_FINDING_OP,SECURITY_FINDING_OP,REASON_TEXT,DECISION_REFERENCE,ACTOR)values(op,v_case,v_ware,v_exp,v_sec,v_reason,v_ref,p_actor);
 payload:=json_object_t.parse(p_domain.to_clob);payload.put('operation_id',op);payload.put('status','CLOSED');payload.put('actor',p_actor);payload.put('warehouse_stock_changed',false);payload.put('external_sap_ack',false);body:=payload.to_clob;
 event_id:='CASE.CLOSE:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op,'AL32UTF8'),sys.dbms_crypto.hash_sh256));
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values(event_id,'STORE_DISCREPANCY_CLOSED',body);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CASE_MOVE_CMD as
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t:=json_object_t();
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;x json_object_t;ct RRL_CASE_PICK_TASK%rowtype;
  task_id number;target varchar2(60);
 begin
  task_id:=d.get_object('source').get_number('case_task_id');select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_id;
  target:=m.get_string('target_cell');
  if target is null or ct.CURRENT_CELL is null or target=ct.CURRENT_CELL or m.get_number('expected_content_version') is null
   or m.get_number('expected_content_version')!=ct.CONTENT_VERSION then raise_application_error(-20886,'CASE_CARRIER_MOVE_SNAPSHOT_TARGET_REQUIRED');end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(task_id));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(ct.PICK_WAVE_ID));
  RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU','CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(task_id));
  a:=json_array_t.parse(RRL_STOCK_CASE_PICK_CMD.carrier_rows(task_id));
  if a.get_size=0 then raise_application_error(-20886,'CASE_CARRIER_HAS_NO_PHYSICAL_STOCK');end if;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),x.get_string('article'),x.get_string('cell'),target);
  end loop;
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  v.put('task',task_id);v.put('warehouse',ct.WARE_ID);v.put('from',ct.CURRENT_CELL);v.put('to',target);
  v.put('carrier_identifier',ct.SSCC);v.put('content_version',ct.CONTENT_VERSION);v.put('stocks',a);
  RRL_STOCK_HU_PLACEMENT_CORE.declare_existing_case(r,task_id);
  RRL_STOCK_CASE_BIND_MOVE.plan_move(ct,r,v);
  RRL_ST_DEFER_CASE_WAIT.plan_move(p_request,d.get_string('actor'),r,v);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;x json_object_t;j json_object_t:=json_object_t();
  ct RRL_CASE_PICK_TASK%rowtype;a json_array_t;plan clob;oldrows clob;nowrows clob;op varchar2(100);task_id number;ware number;
  target varchar2(60);from_cell varchar2(60);base varchar2(20);article varchar2(160);version number;system_flag number;event_id number;mode_name varchar2(20);
 begin
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 and RRL_HAS_WRIGHT(p_actor,'case_pick_execute')!=1 then raise_application_error(-20882,'CASE_CARRIER_MOVE_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v:=json_object_t.parse(plan).get_object('domain');task_id:=v.get_number('task');ware:=v.get_number('warehouse');target:=v.get_string('to');from_cell:=v.get_string('from');
  select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_id for update;
  if ct.WARE_ID is null or ct.WARE_ID!=ware or ct.CURRENT_CELL is null or ct.CURRENT_CELL!=from_cell
   or ct.CONTENT_VERSION!=v.get_number('content_version') then raise_application_error(-20890,'CLOSURE_CHANGED: carrier move');end if;
  RRL_STOCK_CASE_BIND_MOVE.validate_move(ct,v.get_object('shipment_binding'));
  if ct.STATUS is null or ct.STATUS not in('IN_PROGRESS','PARTIAL','WAIT_REPLENISHMENT','WAIT_CONTROL','CONTROL_IN_PROGRESS','READY_TO_SHIP','CONTROLLED') then
   raise_application_error(-20886,'CASE_CARRIER_MOVE_STATE_CONFLICT');end if;
  if m.get_string('scan_container') is null or m.get_string('scan_container')!=ct.SSCC
   or m.get_string('scanned_to_cell') is null or m.get_string('scanned_to_cell')!=target then raise_application_error(-20886,'CASE_CARRIER_DESTINATION_SCAN_REQUIRED');end if;
  select IS_SYSTEM into system_flag from RRL_CELLS where CELL=target;
  if m.get_number('physical_task_id')is not null then
   RRL_ST_DEFER_CASE_WAIT.validate_move(p_request,p_actor,v.get_object('deferred_case_waiting'));
   if system_flag is null or system_flag!=0 then raise_application_error(-20886,'DEFER_CASE_ORDINARY_WAITING_CELL_REQUIRED');end if;
  elsif system_flag is null or system_flag!=1 then raise_application_error(-20886,'CASE_CARRIER_CONTROL_OR_STAGING_ZONE_REQUIRED');end if;
  a:=v.get_array('stocks');oldrows:=a.to_clob;nowrows:=RRL_STOCK_CASE_PICK_CMD.carrier_rows(task_id);
  if dbms_lob.compare(oldrows,nowrows)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: carrier contents');end if;
  mode_name:=case when from_cell='CPT_'||RRL_STOCK_PLAN_HELPER.decimal_text(ware) then 'CASE_EXIT' else 'ORDINARY' end;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   if x.get_string('cell')!=from_cell then raise_application_error(-20887,'CASE_CARRIER_LOCATION_CONFLICT');end if;
   article:=x.get_string('article');base:=x.get_string('base');
   select max(POLICY_VERSION) into version from RRL_STOCK_UOM_CONVERSION where ARTICUL=article and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;
   if version is null then raise_application_error(-20868,'CASE_MOVE_BASE_POLICY_REQUIRED');end if;
   RRL_STOCK_TRANSFER_CORE.move(x.get_string('uid'),x.get_string('uid'),from_cell,target,
    RRL_STOCK_MATH.quantity(x.get_string('quantity')),base,version,ware,p_actor,i+1,null,null,null,null,null,mode_name);
  end loop;
  RRL_STOCK_HU_PLACEMENT_CORE.release_case(task_id,from_cell);
  update RRL_CASE_PICK_TASK set CURRENT_CELL=target,CONTENT_VERSION=CONTENT_VERSION+1,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=task_id;
  RRL_STOCK_CASE_BIND_MOVE.finish_move(ct,v.get_object('shipment_binding'),ct.CONTENT_VERSION+1,p_actor);
  select RRL_CASE_PICK_EVENT_SQ.nextval into event_id from dual;
  insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,EVENT_TYPE,PAYLOAD_JSON,CREATED_BY)
   values(event_id,task_id,'CARRIER_MOVED',p_request,p_actor);
  j.put('operation_id',op);j.put('case_pick_task_id',task_id);j.put('carrier_identifier',ct.SSCC);j.put('from_cell',from_cell);j.put('cell',target);
  j.put('content_version',ct.CONTENT_VERSION+1);j.put('status','MOVED');j.put('lots',a);p_result:=j.to_clob;
  RRL_ST_DEFER_CASE_WAIT.finish_move(p_request,p_actor,p_result);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CASE_PICK_CMD as
 function carrier_rows(p_task number) return clob is
  a json_array_t:=json_array_t();x json_object_t;
 begin
  for r in(select h.LOT_UID,s.CELL,s.REMAIN,s.STOCK_VERSION,s.BASE_UOM,p.ARTICUL,h.CASE_PICK_LINE_ID
   from RRL_CASE_CARRIER_LOT h join RRL_REMAINS s on s.UID_POLETA=h.LOT_UID join RRL_PALLETS p on p.UID_PALLET=h.LOT_UID
   where h.CASE_PICK_TASK_ID=p_task and s.REMAIN>0 order by h.LOT_UID,s.CELL fetch first 201 rows only) loop
   if a.get_size=200 then raise_application_error(-20881,'CASE_CARRIER_LOT_BOUND');end if;
   x:=json_object_t();x.put('uid',r.LOT_UID);x.put('cell',r.CELL);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(r.REMAIN));
   x.put('version',r.STOCK_VERSION);x.put('base',r.BASE_UOM);x.put('article',r.ARTICUL);x.put('case_line',r.CASE_PICK_LINE_ID);a.append(x);
  end loop;
  return a.to_clob;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t:=json_object_t();
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;chunks json_array_t:=json_array_t();x json_object_t;selected_wire clob;
  ct RRL_CASE_PICK_TASK%rowtype;l RRL_CASE_PICK_LINE%rowtype;pt RRL_PICK_TASK%rowtype;
  task_id number;line_id number;fact number;remaining number;q number;basever number;newres number;target varchar2(150);n number:=0;v_cell varchar2(60);target_cell varchar2(60);
  type source_numbers is table of number index by varchar2(150);consumed source_numbers;steps source_numbers;
 begin
  task_id:=d.get_object('source').get_number('case_task_id');line_id:=d.get_object('source').get_number('case_line_id');
  select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_id;
  RRL_CASE_SSCC_API.assert_ready(task_id);
  select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=line_id and CASE_PICK_TASK_ID=task_id;
  RRL_CASE_ROUTE_ADMISSION.assert_next(task_id,line_id);
  select * into pt from RRL_PICK_TASK where PICK_TASK_ID=l.PICK_TASK_ID;
  if ct.WARE_ID is null or ct.WARE_ID<1 or ct.SSCC is null or l.CELL_CODE is null or l.ARTICUL is null or l.PICK_TASK_ID is null or l.PICK_WAVE_TASK_ID is null or l.CUSTOMER_ORDER_ID is null then raise_application_error(-20887,'CASE_TASK_IDENTITY_REQUIRED');end if;
  RRL_STOCK_SHORT_RECOVERY.plan_pick(line_id,r,v);
  fact:=RRL_STOCK_MATH.quantity(m.get_string('fact_qty'));remaining:=fact-nvl(l.PICKED_QTY,0);v_cell:=l.CELL_CODE;target_cell:='CPT_'||RRL_STOCK_PLAN_HELPER.decimal_text(ct.WARE_ID);
  if remaining<=0 or fact>l.PLANNED_QTY then raise_application_error(-20886,'CASE_PICK_FACT_NOT_INCREASING_OR_EXCEEDS_PLAN');end if;
  RRL_CASE_WEIGHT_SCAN.assert_scan(p_request,l.ARTICUL,line_id,nvl(l.PICKED_QTY,0));
  RRL_CASE_SCALE_ADMISSION.assert_capture(p_request,nvl(l.PICKED_QTY,0));
  if m.has('warehouse_scale_capture')then RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','WH.SCALE.USE:'||m.get_string('warehouse_scale_capture'));end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(task_id));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(line_id));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_TASK_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_WAVE_TASK_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_WAVE_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(l.CUSTOMER_ORDER_ID));
  RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU','CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(task_id));
  a:=json_array_t.parse(carrier_rows(task_id));
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),x.get_string('article'),x.get_string('cell'),target_cell);
  end loop;
  declare ctx json_object_t:=json_object_t.parse(RRL_CASE_RESOURCE_POLICY.context_json(task_id,'COMPLETE',d.get_string('actor')));begin
   v.put('case_resource_context',ctx);
   if not ctx.get('resource_session_id').is_null then
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RESOURCE_SESSION',RRL_STOCK_PLAN_HELPER.decimal_text(ctx.get_number('resource_session_id')));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RUSERS',ctx.get_string('assigned_to'));
   end if;
  end;
  selected_wire:=d.get_array('units').to_clob;
  for sr in(select sr.RESERVATION_ID,sr.UID_PALLET,sr.CELL,sr.BASE_QTY,sr.BASE_UOM,s.REMAIN,s.STOCK_VERSION,p.EXPIRY_DATE
   from RRL_STOCK_RESERVATION sr join RRL_REMAINS s on s.UID_POLETA=sr.UID_PALLET and s.CELL=sr.CELL
    join RRL_PALLETS p on p.UID_PALLET=sr.UID_PALLET
   where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=l.PICK_WAVE_ID and sr.SOURCE_LINE_ID=l.PICK_TASK_ID
    and sr.CUSTOMER_ORDER_ID=l.CUSTOMER_ORDER_ID and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING') and sr.CELL=v_cell
    and p.ARTICUL=l.ARTICUL and not exists(select 1 from RRL_CASE_CARRIER_LOT h where h.LOT_UID=sr.UID_PALLET)
    and RRL_STOCK_ELIGIBILITY.reason(sr.UID_PALLET,sr.CELL,ct.WARE_ID,least(remaining,sr.BASE_QTY),null,null,'PICK',sr.RESERVATION_ID,l.ARTICUL) is null
   order by p.EXPIRY_DATE nulls last,sr.UID_PALLET,sr.RESERVATION_ID fetch first 201 rows only) loop
   exit when remaining=0;n:=n+1;
   if n>200 or sr.BASE_QTY is null or sr.BASE_QTY<=0 then raise_application_error(-20881,'CASE_SOURCE_RESERVATION_BOUND_OR_INVALID');end if;
   if d.get_array('units').get_size>0 then
    select nvl(sum(u.BASE_QTY),0) into q from RRL_WMS_RECEIPT_UNIT u
     join json_table(selected_wire,'$[*]' columns(K varchar2(64) path '$'))j on j.K=u.PHYSICAL_UNIT_KEY
     where u.CURRENT_UID=sr.UID_PALLET and u.CURRENT_CELL=v_cell and u.HARD_RESERVATION_ID=sr.RESERVATION_ID and u.STOCK_STATUS!='ISSUED';
    if q=0 then continue;end if;
    if q>remaining or q>sr.BASE_QTY then raise_application_error(-20884,'CASE_SCANNED_UNIT_QUANTITY_CONFLICT');end if;
   else q:=least(remaining,sr.BASE_QTY);end if;
   remaining:=remaining-q;
   select max(POLICY_VERSION) into basever from RRL_STOCK_UOM_CONVERSION where ARTICUL=l.ARTICUL and INPUT_UOM=sr.BASE_UOM and BASE_UOM=sr.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
   if basever is null then raise_application_error(-20868,'CASE_BASE_POLICY_REQUIRED');end if;
   target:='CASELOT:'||substr(rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)),1,38)||':'||RRL_STOCK_PLAN_HELPER.decimal_text(n);
   select RRL_STOCK_RESERVATION_SQ.nextval into newres from dual;
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,sr.UID_PALLET,l.ARTICUL,v_cell,target_cell);
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',target);RRL_STOCK_PLAN_HELPER.anchor(r,50,'STOCK',target);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(newres));
   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','PALLET:'||target);
   x:=json_object_t();x.put('source_uid',sr.UID_PALLET);x.put('target_uid',target);x.put('reservation',sr.RESERVATION_ID);x.put('new_reservation',newres);
   x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(q));x.put('base',sr.BASE_UOM);x.put('policy',basever);
   if not consumed.exists(sr.UID_PALLET) then consumed(sr.UID_PALLET):=0;steps(sr.UID_PALLET):=0;end if;
   x.put('stock_version',sr.STOCK_VERSION+steps(sr.UID_PALLET));x.put('source_p',RRL_STOCK_PLAN_HELPER.decimal_text(sr.REMAIN-consumed(sr.UID_PALLET)));
   consumed(sr.UID_PALLET):=consumed(sr.UID_PALLET)+q;steps(sr.UID_PALLET):=steps(sr.UID_PALLET)+1;chunks.append(x);
  end loop;
  if remaining!=0 then raise_application_error(-20869,'CASE_OWN_HARD_IN_PICK_CELL_INSUFFICIENT');end if;
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  v.put('task_id',task_id);v.put('line_id',line_id);v.put('pick_task',l.PICK_TASK_ID);v.put('wave_task',l.PICK_WAVE_TASK_ID);
  v.put('wave_id',l.PICK_WAVE_ID);v.put('customer_order',l.CUSTOMER_ORDER_ID);v.put('warehouse',ct.WARE_ID);v.put('cell',v_cell);v.put('transit_cell',target_cell);v.put('article',l.ARTICUL);
  v.put('previous_qty',RRL_STOCK_PLAN_HELPER.decimal_text(nvl(l.PICKED_QTY,0)));v.put('planned_qty',RRL_STOCK_PLAN_HELPER.decimal_text(l.PLANNED_QTY));
  v.put('content_version',ct.CONTENT_VERSION);v.put('carrier_identifier',ct.SSCC);v.put('carrier',a);v.put('chunks',chunks);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;x json_object_t;
  a json_array_t;chunks json_array_t;facts json_array_t:=json_array_t();factx json_object_t;keys json_array_t;selected json_array_t;keyx json_element_t;unit_wire clob;
  ct RRL_CASE_PICK_TASK%rowtype;l RRL_CASE_PICK_LINE%rowtype;pt RRL_PICK_TASK%rowtype;p RRL_PALLETS%rowtype;
  plan clob;nowrows clob;oldrows clob;op varchar2(100);task_id number;line_id number;ware number;v_cell varchar2(60);article varchar2(160);target_cell varchar2(60);
  qty number;fact number;before_qty number;ver number;stockver number;physical number;owned number;base varchar2(20);uid varchar2(150);target varchar2(150);sid number;new_sid number;
  wave_status varchar2(40);n number;posted number;line_no number:=0;unit_key varchar2(64);matched number;scan_product varchar2(4000);newstatus varchar2(20);eventid number;offline varchar2(100);
 begin
  if RRL_HAS_WRIGHT(p_actor,'case_pick_execute')!=1 then raise_application_error(-20882,'CASE_PICK_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  task_id:=v.get_number('task_id');line_id:=v.get_number('line_id');ware:=v.get_number('warehouse');v_cell:=v.get_string('cell');article:=v.get_string('article');target_cell:=v.get_string('transit_cell');
  declare
 v_json_sql_1_1 number:=v.get_number('wave_id');
begin
select STATUS into wave_status from RRL_PICK_WAVE where PICK_WAVE_ID=v_json_sql_1_1 for update;
end;
  RRL_STOCK_WAVE_READY.assert_released(v.get_number('wave_id'));
  if wave_status is null or wave_status!='LAUNCHED' then raise_application_error(-20886,'CASE_WAVE_STATE_CONFLICT');end if;
  select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_id for update;
  RRL_CASE_SSCC_API.assert_ready(task_id);
  select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=line_id for update;
  RRL_CASE_ROUTE_ADMISSION.assert_next(task_id,line_id);
  select * into pt from RRL_PICK_TASK where PICK_TASK_ID=l.PICK_TASK_ID for update;
  if ct.WARE_ID!=ware or ct.CONTENT_VERSION!=v.get_number('content_version') or ct.SSCC!=v.get_string('carrier_identifier')
   or l.CASE_PICK_TASK_ID!=task_id or l.PICK_TASK_ID!=v.get_number('pick_task') or l.PICK_WAVE_TASK_ID!=v.get_number('wave_task')
   or l.PICK_WAVE_ID!=v.get_number('wave_id') or l.CUSTOMER_ORDER_ID!=v.get_number('customer_order') or l.CELL_CODE!=v_cell or l.ARTICUL!=article
   or RRL_STOCK_PLAN_HELPER.decimal_text(l.PLANNED_QTY)!=v.get_string('planned_qty')
   or RRL_STOCK_PLAN_HELPER.decimal_text(nvl(l.PICKED_QTY,0))!=v.get_string('previous_qty') then raise_application_error(-20890,'CLOSURE_CHANGED: case task identity');end if;
  if ct.STATUS is null or ct.STATUS not in('IN_PROGRESS','PARTIAL','WAIT_REPLENISHMENT') or l.STATUS is null or l.STATUS not in('NEW','ACTIVE','SKIPPED','IN_PROGRESS','PARTIAL','WAIT_REPLENISHMENT')
   or pt.TASK_TYPE is null or pt.TASK_TYPE!='CASE_PICK' or pt.STATUS is null or pt.STATUS in('DONE','CANCELLED','FAILED') or pt.CUSTOMER_ORDER_ID!=l.CUSTOMER_ORDER_ID or pt.ARTICUL!=article then raise_application_error(-20886,'CASE_TASK_LINE_STATE_CONFLICT');end if;
  -- Reporting/rejecting a short uses CONFIG exclusive; this command holds CONFIG shared
  -- and the same task/line anchors, so the pending decision cannot change this fact mid-post.
  select count(*) into n from RRL_CASE_PICK_SHORT where CASE_PICK_LINE_ID=line_id
   and STATUS in('CREATED','PENDING_APPROVAL');
  if n>0 then raise_application_error(-20886,'CASE_SHORT_DECISION_PENDING');end if;
  declare ctx json_object_t;before_ctx clob;after_ctx clob;sid number;begin
   sid:=v.get_object('case_resource_context').get_number('resource_session_id');
   if sid is not null then select SESSION_ID into sid from RRL_RESOURCE_SESSION where SESSION_ID=sid for update;end if;
   ctx:=json_object_t.parse(RRL_CASE_RESOURCE_POLICY.context_json(task_id,'COMPLETE',p_actor));
   before_ctx:=v.get_object('case_resource_context').to_clob;after_ctx:=ctx.to_clob;
   if dbms_lob.compare(before_ctx,after_ctx)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: CASE resource');end if;
  end;
  if ct.ASSIGNED_TO is not null and ct.ASSIGNED_TO!=p_actor and RRL_HAS_WRIGHT(p_actor,'case_pick_manage')!=1 then raise_application_error(-20882,'CASE_TASK_ACTOR_CONFLICT');end if;
  if m.get_string('scan_cell') is null or upper(m.get_string('scan_cell'))!=upper(v_cell)
   or m.get_string('scan_container') is null or m.get_string('scan_container')!=ct.SSCC then raise_application_error(-20886,'CASE_CELL_CARRIER_SCAN_REQUIRED');end if;
  scan_product:=m.get_string('scan_product');
  select count(*) into n from RRL_ARTICULS where ACTICUL=article and scan_product in(ACTICUL,BARCODE_SHT,BARCODE_KOR,BARCODE_BL);
  if n!=1 and d.get_array('units').get_size=0 then raise_application_error(-20886,'CASE_PRODUCT_SCAN_CONFLICT');end if;
  nowrows:=carrier_rows(task_id);a:=v.get_array('carrier');oldrows:=a.to_clob;
  if dbms_lob.compare(nowrows,oldrows)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: case carrier stock');end if;
  before_qty:=nvl(l.PICKED_QTY,0);posted:=0;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   if x.get_number('case_line')=line_id then posted:=posted+RRL_STOCK_MATH.quantity(x.get_string('quantity'));end if;
  end loop;
  if posted!=before_qty then raise_application_error(-20886,'CASE_PRIOR_FACT_WITHOUT_PHYSICAL_POSTING');end if;
  fact:=RRL_STOCK_MATH.quantity(m.get_string('fact_qty'));
  if fact<=before_qty or fact>l.PLANNED_QTY then raise_application_error(-20886,'CASE_PICK_FACT_CONFLICT');end if;
  RRL_CASE_WEIGHT_SCAN.assert_scan(p_request,article,line_id,before_qty);
  RRL_CASE_SCALE_ADMISSION.claim_capture(p_request,op,before_qty);
  keys:=d.get_array('units');unit_wire:=keys.to_clob;matched:=0;
  -- Move already picked contents with their carrier to the newly scanned pick v_cell.
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);uid:=x.get_string('uid');
   if ct.CURRENT_CELL is null or ct.CURRENT_CELL!=x.get_string('cell') then raise_application_error(-20887,'CASE_CARRIER_LOCATION_CONFLICT');end if;
   if x.get_string('cell')!=target_cell then
    base:=x.get_string('base');
    declare
 v_json_sql_2_1 varchar2(32767):=x.get_string('article');
begin
select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_json_sql_2_1 and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;
end;
    line_no:=line_no+1;
    RRL_STOCK_TRANSFER_CORE.move(uid,uid,x.get_string('cell'),target_cell,RRL_STOCK_MATH.quantity(x.get_string('quantity')),base,ver,ware,p_actor,line_no,null,null,null,null,null,'CASE_TRANSIT');
   end if;
  end loop;
  chunks:=v.get_array('chunks');
  for i in 0..chunks.get_size-1 loop
   x:=treat(chunks.get(i) as json_object_t);uid:=x.get_string('source_uid');target:=x.get_string('target_uid');
   qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));base:=x.get_string('base');sid:=x.get_number('reservation');new_sid:=x.get_number('new_reservation');
   select REMAIN,STOCK_VERSION into physical,stockver from RRL_REMAINS where UID_POLETA=uid and CELL=v_cell;
   if stockver!=x.get_number('stock_version') or RRL_STOCK_PLAN_HELPER.decimal_text(physical)!=x.get_string('source_p') then raise_application_error(-20890,'CLOSURE_CHANGED: case source stock');end if;
   select BASE_QTY into owned from RRL_STOCK_RESERVATION where RESERVATION_ID=sid and UID_PALLET=uid and CELL=v_cell
    and SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=l.PICK_WAVE_ID and SOURCE_LINE_ID=l.PICK_TASK_ID
    and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING');
   if owned<qty then raise_application_error(-20869,'CASE_OWN_HARD_INSUFFICIENT');end if;
   RRL_STOCK_ELIGIBILITY.assert_source(uid,v_cell,ware,qty,null,null,'PICK',sid,article);
   select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=article and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;
   if ver is null or ver!=x.get_number('policy') then raise_application_error(-20890,'CLOSURE_CHANGED: case UOM policy');end if;
   selected:=json_array_t();
   for selected_unit in(select u.PHYSICAL_UNIT_KEY from RRL_WMS_RECEIPT_UNIT u
    join json_table(unit_wire,'$[*]' columns(K varchar2(64) path '$'))j on j.K=u.PHYSICAL_UNIT_KEY
    where u.CURRENT_UID=uid and u.CURRENT_CELL=v_cell and u.HARD_RESERVATION_ID=sid and u.STOCK_STATUS!='ISSUED'
    order by u.PHYSICAL_UNIT_KEY) loop
    selected.append(selected_unit.PHYSICAL_UNIT_KEY);matched:=matched+1;
   end loop;
   select count(*) into n from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=uid and CURRENT_CELL=v_cell and STOCK_STATUS!='ISSUED';
   if n>0 and selected.get_size=0 then raise_application_error(-20884,'CASE_MARKED_UNIT_SCANS_REQUIRED');end if;
   select * into p from RRL_PALLETS where UID_PALLET=uid;
   if p.ARTICUL!=article then raise_application_error(-20887,'CASE_LOT_ARTICLE_CONFLICT');end if;
   p.STOCK_ORIGIN_UID:=nvl(p.STOCK_ORIGIN_UID,p.UID_PALLET);p.CREATED_BY_STOCK_OP:=op;p.UID_PALLET:=target;p.SSCC:=null;p.PRINTED:=0;
   if p.WEIGHT_BRUTTO is not null or p.WEIGHT_TN is not null or p.COUNT_KOR is not null then
    if p.UNIT_COUNT is null or p.UNIT_COUNT<=0 then raise_application_error(-20887,'CASE_LOT_BIRTH_QUANTITY_REQUIRED');end if;
    p.WEIGHT_BRUTTO:=p.WEIGHT_BRUTTO*qty/p.UNIT_COUNT;
    p.WEIGHT_TN:=p.WEIGHT_TN*qty/p.UNIT_COUNT;p.COUNT_KOR:=p.COUNT_KOR*qty/p.UNIT_COUNT;
   end if;
   p.UNIT_COUNT:=qty;p.STOCK_COMPOSITION_VERSION:=0;insert into RRL_PALLETS values p;
   line_no:=line_no+1;
   RRL_STOCK_TRANSFER_CORE.move(uid,target,v_cell,target_cell,qty,base,ver,ware,p_actor,line_no,sid,
    case when selected.get_size>0 then selected.to_clob else null end,new_sid,null,null,'CASE_TRANSIT');
   insert into RRL_CASE_CARRIER_LOT(LOT_UID,CASE_PICK_TASK_ID,CASE_PICK_LINE_ID,CREATED_OPERATION,CREATED_BY)
    values(target,task_id,line_id,op,p_actor);
   factx:=json_object_t();factx.put('uid',target);factx.put('source_uid',uid);factx.put('quantity',x.get_string('quantity'));factx.put('unit',base);facts.append(factx);
  end loop;
  if matched!=keys.get_size then raise_application_error(-20884,'CASE_SELECTED_UNIT_NOT_OWNED');end if;
  newstatus:=case when fact=l.PLANNED_QTY then 'PICKED' else 'PARTIAL' end;offline:=m.get_string('offline_event_id');
  update RRL_CASE_PICK_LINE set PICKED_QTY=fact,STATUS=newstatus,LAST_OFFLINE_EVENT_ID=offline,
   STARTED_AT=nvl(STARTED_AT,systimestamp),DONE_AT=case when newstatus='PICKED' then systimestamp else DONE_AT end,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_LINE_ID=line_id;
  update RRL_PICK_TASK set FACT_QTY=fact,STATUS=case when newstatus='PICKED' then 'DONE' else 'IN_PROGRESS' end,
   DONE_AT=case when newstatus='PICKED' then sysdate else DONE_AT end,DONE_BY=p_actor,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_TASK_ID=l.PICK_TASK_ID;
  update RRL_PICK_WAVE_TASK set FACT_QTY=fact,STATUS=case when newstatus='PICKED' then 'DONE' else 'IN_PROGRESS' end,
   DONE_AT=case when newstatus='PICKED' then sysdate else DONE_AT end,DONE_BY=p_actor,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_TASK_ID=l.PICK_WAVE_TASK_ID;
  update RRL_CASE_PICK_TASK t set CURRENT_CELL=target_cell,CONTENT_VERSION=CONTENT_VERSION+1,
   (TOTAL_LINES,PICKED_LINES,PLANNED_QTY,PICKED_QTY)=(select count(*),nvl(sum(case when STATUS in('PICKED','SHORT_PICKED','CANCELLED') then 1 else 0 end),0),nvl(sum(PLANNED_QTY),0),nvl(sum(PICKED_QTY),0) from RRL_CASE_PICK_LINE z where z.CASE_PICK_TASK_ID=task_id),
   UPDATED_AT=systimestamp,UPDATED_BY=p_actor where t.CASE_PICK_TASK_ID=task_id;
  select RRL_CASE_PICK_EVENT_SQ.nextval into eventid from dual;
  insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,CASE_PICK_LINE_ID,EVENT_TYPE,OFFLINE_EVENT_ID,PAYLOAD_JSON,CREATED_BY)
   values(eventid,task_id,line_id,'LINE_CONFIRMED',offline,p_request,p_actor);
  RRL_STOCK_SHORT_RECOVERY.finish_pick(line_id,p_actor,v);
  select STATUS into newstatus from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=line_id;
  v:=json_object_t();v.put('operation_id',op);v.put('case_pick_task_id',task_id);v.put('case_pick_line_id',line_id);v.put('status',newstatus);
  v.put('remaining_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(l.PLANNED_QTY-fact));v.put('fact_qty',RRL_STOCK_PLAN_HELPER.decimal_text(fact));v.put('carrier_identifier',ct.SSCC);v.put('cell',target_cell);v.put('picked_from_cell',v_cell);v.put('lots',facts);p_result:=v.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CASE_RETURN_CMD as
 procedure assert_empty_cancel(p_task number,p_metadata json_object_t)is
  n number;qty number;
 begin
  if trim(p_metadata.get_string('reason')) is null or length(p_metadata.get_string('reason'))>1000 then
   raise_application_error(-20881,'CASE_EMPTY_CANCEL_REASON_REQUIRED');end if;
  select nvl(PICKED_QTY,0)into qty from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task;
  if qty!=0 then raise_application_error(-20886,'CASE_EMPTY_CANCEL_HISTORICAL_PICK_EXISTS');end if;
  select count(*)into n from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=p_task and nvl(PICKED_QTY,0)!=0;
  if n>0 then raise_application_error(-20886,'CASE_EMPTY_CANCEL_LINE_PICK_EXISTS');end if;
  select count(*)into n from RRL_CASE_PICK_LINE l where l.CASE_PICK_TASK_ID=p_task
   and (l.PICK_TASK_ID is null or l.PICK_WAVE_TASK_ID is null or not exists(select 1 from RRL_PICK_TASK pt where pt.PICK_TASK_ID=l.PICK_TASK_ID) or not exists(select 1 from RRL_PICK_WAVE_TASK wt where wt.PICK_WAVE_TASK_ID=l.PICK_WAVE_TASK_ID) or exists(
    select 1 from RRL_PICK_TASK pt where pt.PICK_TASK_ID=l.PICK_TASK_ID and (nvl(pt.FACT_QTY,0)!=0 or pt.STATUS='DONE'))
    or exists(select 1 from RRL_CASE_PICK_LINE other_line where other_line.PICK_TASK_ID=l.PICK_TASK_ID and other_line.CASE_PICK_TASK_ID!=p_task));
  if n>0 then raise_application_error(-20886,'CASE_EMPTY_CANCEL_SHARED_OR_EXECUTED_PICK_TASK');end if;
  select count(*)into n from RRL_WAREHOUSE_TASK wh where wh.TASK_SOURCE='WAVE'and wh.SOURCE_DOC_ID=(select PICK_WAVE_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task)and nvl(wh.STATUS,'-')!='CANCELLED'
   and nvl(wh.TASK_TYPE,'-')!='REPLENISHMENT'and exists(select 1 from RRL_CASE_PICK_LINE l
    where l.CASE_PICK_TASK_ID=p_task and l.PICK_WAVE_TASK_ID=wh.SOURCE_TASK_ID);
  if n>0 then raise_application_error(-20886,'CASE_EMPTY_CANCEL_PHYSICAL_TASK_REQUIRES_DECISION');end if;
  select count(*)into n from RRL_CASE_CARRIER_LOT where CASE_PICK_TASK_ID=p_task;
  if n>0 then raise_application_error(-20886,'CASE_EMPTY_CANCEL_COMPOSITION_EXISTS');end if;
  select count(*)into n from RRL_RECEIPT_SLOT_CLAIM cl where cl.HU_CASE_TASK_ID=p_task
   and (cl.STATUS='RESERVED' or (cl.STATUS='OCCUPIED'and not exists(select 1 from RRL_CASE_PICK_TASK ct
    where ct.CASE_PICK_TASK_ID=p_task and ct.CURRENT_CELL=cl.CELL)));
  if n>0 then raise_application_error(-20886,'CASE_EMPTY_CANCEL_PLACEMENT_REQUIRES_DECISION');end if;
  select count(*)into n from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=p_task and ACTIVE_FLAG=1;
  if n>0 then raise_application_error(-20886,'CASE_EMPTY_CANCEL_DETACH_PARENT_REQUIRED');end if;
  select count(*)into n from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=p_task;
  if n<1 or n>200 then raise_application_error(-20881,'CASE_EMPTY_CANCEL_LINE_BOUND_1_200');end if;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t:=json_object_t();
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;x json_object_t;
  ct RRL_CASE_PICK_TASK%rowtype;tid number;target varchar2(60);lid number;uid varchar2(150);ids json_array_t;
 begin
  tid:=d.get_object('source').get_number('case_task_id');select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=tid;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(tid));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(ct.PICK_WAVE_ID));
  RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU','CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(tid));
  if ct.LEGACY_SBORKA_PALLET_ID is not null then
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(ct.LEGACY_SBORKA_PALLET_ID));
   for ff in(select FULFILLMENT_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=ct.LEGACY_SBORKA_PALLET_ID order by FULFILLMENT_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(ff.FULFILLMENT_ID));
   end loop;
  end if;
  a:=json_array_t.parse(RRL_STOCK_CASE_PICK_CMD.carrier_rows(tid));
  if m.has('allow_empty') and m.get_boolean('allow_empty')then
   assert_empty_cancel(tid,m);
   if a.get_size!=0 then raise_application_error(-20886,'CASE_EMPTY_CANCEL_COMPOSITION_EXISTS');end if;
   v.put('empty_cancel',true);
  elsif a.get_size=0 then raise_application_error(-20886,'CASE_RETURN_EMPTY_CARRIER');end if;
  if m.get_object('destinations').get_size!=a.get_size then raise_application_error(-20871,'CASE_RETURN_ALL_LOTS_REQUIRED');end if;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);uid:=x.get_string('uid');lid:=x.get_number('case_line');
   select CELL_CODE into target from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=lid;
   if m.get_object('destinations').get_string(uid) is null or m.get_object('destinations').get_string(uid)!=target then raise_application_error(-20886,'CASE_RETURN_SCAN_ORIGINAL_CELL_REQUIRED');end if;
   x.put('target',target);ids:=json_array_t();
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,uid,x.get_string('article'),x.get_string('cell'),target);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(lid));
   for l in(select PICK_TASK_ID,PICK_WAVE_TASK_ID from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=lid) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_TASK_ID));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_WAVE_TASK_ID));
   end loop;
   for h in(select RESERVATION_ID from RRL_STOCK_RESERVATION where UID_PALLET=uid and RESERVATION_KIND='HARD'
    and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_QTY>0 order by RESERVATION_ID) loop
    ids.append(h.RESERVATION_ID);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(h.RESERVATION_ID));
   end loop;
   x.put('reservations',ids);a.put(i,x,true);
  end loop;
  for l in(select CASE_PICK_LINE_ID,PICK_TASK_ID,PICK_WAVE_TASK_ID from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=tid order by CASE_PICK_LINE_ID) loop
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(l.CASE_PICK_LINE_ID));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_TASK_ID));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_WAVE_TASK_ID));
  end loop;
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  v.put('task',tid);v.put('version',ct.CONTENT_VERSION);v.put('carrier',ct.SSCC);v.put('warehouse',ct.WARE_ID);v.put('stocks',a);
  v.put('before',json_array_t.parse(RRL_STOCK_CASE_PICK_CMD.carrier_rows(tid)));
  declare unused json_array_t:=json_array_t();item json_object_t;begin
   for h in(select sr.RESERVATION_ID,sr.UID_PALLET,sr.CELL,sr.BASE_UOM,sr.BASE_QTY,p.ARTICUL
    from RRL_STOCK_RESERVATION sr join RRL_PALLETS p on p.UID_PALLET=sr.UID_PALLET
    where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=ct.PICK_WAVE_ID
     and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING') and sr.BASE_QTY>0
     and exists(select 1 from RRL_CASE_PICK_LINE l where l.CASE_PICK_TASK_ID=tid and l.PICK_TASK_ID=sr.SOURCE_LINE_ID)
     and not exists(select 1 from RRL_CASE_CARRIER_LOT cl where cl.LOT_UID=sr.UID_PALLET)
    order by sr.RESERVATION_ID fetch first 201 rows only) loop
    if unused.get_size=200 then raise_application_error(-20881,'CASE_RETURN_UNUSED_RESERVE_BOUND');end if;
    RRL_STOCK_PLAN_HELPER.stock_closure(f,r,h.UID_PALLET,h.ARTICUL,h.CELL,null);
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(h.RESERVATION_ID));
    item:=json_object_t();item.put('id',h.RESERVATION_ID);item.put('uid',h.UID_PALLET);item.put('article',h.ARTICUL);item.put('base',h.BASE_UOM);item.put('cell',h.CELL);
    unused.append(item);
   end loop;
   for sh in(select CASE_PICK_SHORT_ID from RRL_CASE_PICK_SHORT where CASE_PICK_TASK_ID=tid order by CASE_PICK_SHORT_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_SHORT',RRL_STOCK_PLAN_HELPER.decimal_text(sh.CASE_PICK_SHORT_ID));
   end loop;
   v.put('unused',unused);
  end;
  RRL_STOCK_HU_PLACEMENT_CORE.declare_existing_case(r,tid);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;
  ct RRL_CASE_PICK_TASK%rowtype;sr RRL_STOCK_RESERVATION%rowtype;plan clob;current_rows clob;previous_rows clob;
  tid number;sid number;uid varchar2(150);target varchar2(60);cell varchar2(60);article varchar2(160);base varchar2(20);version number;
  op varchar2(100);a json_array_t;ids json_array_t;x json_object_t;pt number;wave number;n number;qc number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'case_pick_manage')!=1 then raise_application_error(-20882,'CASE_RETURN_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v:=json_object_t.parse(plan).get_object('domain');tid:=v.get_number('task');
  select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=tid for update;
  if ct.CONTENT_VERSION!=v.get_number('version') or ct.CONTENT_VERSION!=m.get_number('expected_content_version')
   or ct.SSCC!=m.get_string('scan_container') or m.get_string('scan_container') is null
   or ct.STATUS in('SHIPPED','CANCELLED','FAILED') then raise_application_error(-20886,'CASE_RETURN_STATE_SCAN_VERSION_CONFLICT');end if;
  if m.has('allow_empty')and m.get_boolean('allow_empty')then assert_empty_cancel(tid,m);end if;
  current_rows:=RRL_STOCK_CASE_PICK_CMD.carrier_rows(tid);previous_rows:=v.get_array('before').to_clob;
  if dbms_lob.compare(current_rows,previous_rows)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: CASE return contents');end if;
  if ct.LEGACY_SBORKA_PALLET_ID is not null then
   select CONDITION into qc from RRL_SBORKA_PALLETS where ID=ct.LEGACY_SBORKA_PALLET_ID for update;
   if nvl(qc,0)>=2 then raise_application_error(-20886,'CASE_RETURN_SHIPMENT_ALREADY_POSTED');end if;
   update RRL_SBORKA_PALLETS set PROOVED=0,PROOVED_BY_SCAN=0 where ID=ct.LEGACY_SBORKA_PALLET_ID;
  end if;
  a:=v.get_array('stocks');wave:=ct.PICK_WAVE_ID;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);uid:=x.get_string('uid');cell:=x.get_string('cell');target:=x.get_string('target');article:=x.get_string('article');base:=x.get_string('base');
   select max(POLICY_VERSION) into version from RRL_STOCK_UOM_CONVERSION where ARTICUL=article and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;
   if version is null then raise_application_error(-20868,'CASE_RETURN_BASE_POLICY_REQUIRED');end if;
   declare lid number:=x.get_number('case_line');begin select PICK_TASK_ID into pt from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=lid;end;
   ids:=x.get_array('reservations');
   for z in 0..ids.get_size-1 loop
    sid:=ids.get_number(z);select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=sid for update;
    if sr.SOURCE_DOC_TYPE!='PICK_WAVE' or sr.SOURCE_DOC_ID!=wave or sr.SOURCE_LINE_ID!=pt or sr.UID_PALLET!=uid or sr.CELL!=cell
     or sr.STATUS not in('ACTIVE','ALLOCATED','PICKING') then raise_application_error(-20869,'CASE_RETURN_FOREIGN_RESERVE:'||sr.SOURCE_DOC_ID||'/'||wave||':'||sr.SOURCE_LINE_ID||'/'||pt||':'||sr.UID_PALLET||'/'||uid||':'||sr.CELL||'/'||cell||':'||sr.STATUS);end if;
    RRL_STOCK_UNIT_CORE.release_units(sid,sr.BASE_QTY,null,0);
    RRL_STOCK_RESERVE_CORE.release_hard(sid,sr.BASE_QTY,version,'PICK_WAVE',wave,p_actor);
   end loop;
   RRL_STOCK_TRANSFER_CORE.move(uid,uid,cell,target,RRL_STOCK_MATH.quantity(x.get_string('quantity')),base,version,ct.WARE_ID,p_actor,i+1,
    null,null,null,null,null,case when cell='CPT_'||RRL_STOCK_PLAN_HELPER.decimal_text(ct.WARE_ID) then 'CASE_EXIT' else 'ORDINARY' end);
   delete from RRL_CASE_CARRIER_LOT where LOT_UID=uid and CASE_PICK_TASK_ID=tid;
  end loop;
  ids:=v.get_array('unused');
  for i in 0..ids.get_size-1 loop
   x:=treat(ids.get(i) as json_object_t);sid:=x.get_number('id');
   select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=sid for update;
   if sr.SOURCE_DOC_TYPE!='PICK_WAVE' or sr.SOURCE_DOC_ID!=wave or sr.UID_PALLET!=x.get_string('uid') or sr.CELL!=x.get_string('cell')
    or sr.STATUS not in('ACTIVE','ALLOCATED','PICKING') then raise_application_error(-20890,'CLOSURE_CHANGED: CASE unused reserve');end if;
   article:=x.get_string('article');base:=x.get_string('base');
   select max(POLICY_VERSION) into version from RRL_STOCK_UOM_CONVERSION where ARTICUL=article and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;
   if version is null then raise_application_error(-20868,'CASE_RETURN_BASE_POLICY_REQUIRED');end if;
   RRL_STOCK_UNIT_CORE.release_units(sid,sr.BASE_QTY,null,0);
   RRL_STOCK_RESERVE_CORE.release_hard(sid,sr.BASE_QTY,version,'PICK_WAVE',wave,p_actor);
  end loop;
  update RRL_CASE_PICK_SHORT set STATUS='CANCELLED',CANCELLED_AT=systimestamp,CANCELLED_BY=p_actor
   where CASE_PICK_TASK_ID=tid and STATUS in('CREATED','PENDING_APPROVAL');
  for l in(select CASE_PICK_LINE_ID,PICK_TASK_ID,PICK_WAVE_TASK_ID from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=tid) loop
   update RRL_CASE_PICK_LINE set STATUS='CANCELLED',UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_LINE_ID=l.CASE_PICK_LINE_ID;
   update RRL_PICK_TASK set STATUS='CANCELLED',UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_TASK_ID=l.PICK_TASK_ID;
   update RRL_PICK_WAVE_TASK set STATUS='CANCELLED',UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_TASK_ID=l.PICK_WAVE_TASK_ID;
  end loop;
  if ct.LEGACY_SBORKA_PALLET_ID is not null then
   update RRL_CUSTOMER_ORDER_FULFILLMENT set STATUS='PLANNED',FACT_QTY=0,FACT_UOM=null,FACT_COMPOSITION_JSON=null,
    PICKED_CASE_TASK_ID=null,PICKED_CONTENT_VERSION=null,PICKED_AT=null,PICKED_BY=null,UPDATED_AT=sysdate,UPDATED_BY=p_actor
    where LEGACY_SBORKA_PALLET_ID=ct.LEGACY_SBORKA_PALLET_ID and PICKED_CASE_TASK_ID=tid and STATUS='PICKED';
  end if;
  RRL_STOCK_HU_PLACEMENT_CORE.release_case(tid,ct.CURRENT_CELL);
  update RRL_CASE_PICK_TASK set STATUS='CANCELLED',LEGACY_SBORKA_PALLET_ID=null,CURRENT_CELL=null,
   CONTENT_VERSION=CONTENT_VERSION+1,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=tid;
  v.put('operation_id',op);
  if m.has('allow_empty')and m.get_boolean('allow_empty')then
   v.put('status','CANCELLED_EMPTY');v.put('physical_quantity_changed',false);
   v.put('next_action','RELEASE_HELD_TARE_BOOK_THEN_WAVE_DECISION');
  else v.put('status','RETURNED');end if;p_result:=v.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CASE_SHORT_CMD as
 function unused_reservations(p_wave number,p_task number) return json_array_t is
  a json_array_t:=json_array_t();x json_object_t;
 begin
  for z in(select RESERVATION_ID,RESERVATION_VERSION,UID_PALLET,CELL,ARTICUL,BASE_QTY,BASE_UOM from RRL_STOCK_RESERVATION sr
   where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=p_wave and sr.SOURCE_LINE_ID=p_task
    and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING')
    and not exists(select 1 from RRL_CASE_CARRIER_LOT c where c.LOT_UID=sr.UID_PALLET)
   order by RESERVATION_ID) loop
   if a.get_size>=200 then raise_application_error(-20881,'CASE_SHORT_RESERVATION_BOUND');end if;
   x:=json_object_t();x.put('id',z.RESERVATION_ID);x.put('version',z.RESERVATION_VERSION);x.put('uid',z.UID_PALLET);
   x.put('cell',z.CELL);x.put('article',z.ARTICUL);x.put('qty',RRL_STOCK_PLAN_HELPER.decimal_text(z.BASE_QTY));x.put('base',z.BASE_UOM);a.append(x);
  end loop;
  return a;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t:=json_object_t();x json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;carrier json_array_t;
  sh RRL_CASE_PICK_SHORT%rowtype;l RRL_CASE_PICK_LINE%rowtype;ct RRL_CASE_PICK_TASK%rowtype;inventory_id number;decision varchar2(20);weight_wire clob;
 begin
  decision:=nvl(d.get_object('metadata').get_string('decision'),'ACCEPT_SHORT');
  if decision='READY' then
   RRL_STOCK_SHORT_RECOVERY.plan_ready(p_request,f,r,v);p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;return;
  end if;
  if decision not in('ACCEPT_SHORT','RESTORE','WEIGHT_TOLERANCE') then raise_application_error(-20881,'SHORT_DECISION_INVALID');end if;
  v.put('decision',decision);
  declare
 v_json_sql_1_1 number:=d.get_object('source').get_number('short_id');
begin
select * into sh from RRL_CASE_PICK_SHORT where CASE_PICK_SHORT_ID=v_json_sql_1_1;
end;
  select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=sh.CASE_PICK_LINE_ID;
  select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=l.CASE_PICK_TASK_ID;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_WAVE_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_SHORT',RRL_STOCK_PLAN_HELPER.decimal_text(sh.CASE_PICK_SHORT_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(ct.CASE_PICK_TASK_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(l.CASE_PICK_LINE_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_TASK_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_WAVE_TASK_ID));
  RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU','CASE:'||ct.CASE_PICK_TASK_ID);
  a:=unused_reservations(l.PICK_WAVE_ID,l.PICK_TASK_ID);
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),x.get_string('article'),x.get_string('cell'),null);
  end loop;
  carrier:=json_array_t.parse(RRL_STOCK_CASE_PICK_CMD.carrier_rows(ct.CASE_PICK_TASK_ID));
  for i in 0..carrier.get_size-1 loop
   x:=treat(carrier.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),x.get_string('article'),x.get_string('cell'),null);
  end loop;
  if decision='WEIGHT_TOLERANCE'then
   weight_wire:=RRL_CASE_WEIGHT_DECISION.current_json(p_request,ct.CASE_PICK_TASK_ID,l.CASE_PICK_LINE_ID,d.get_string('actor'));
   RRL_CASE_WEIGHT_DECISION.plan_order(l.CUSTOMER_ORDER_ID,l.ARTICUL,r);
   v.put('weight_order_snapshot',json_object_t.parse(weight_wire));
  end if;
  select RRL_INVENTORY_TASK_SQ.nextval into inventory_id from dual;
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INVENTORY_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(inventory_id));
  v.put('short_id',sh.CASE_PICK_SHORT_ID);v.put('line_id',l.CASE_PICK_LINE_ID);v.put('task_id',ct.CASE_PICK_TASK_ID);
  v.put('pick_task',l.PICK_TASK_ID);v.put('wave_task',l.PICK_WAVE_TASK_ID);v.put('wave',l.PICK_WAVE_ID);
  v.put('warehouse',ct.WARE_ID);v.put('article',l.ARTICUL);v.put('cell',l.CELL_CODE);v.put('version',ct.CONTENT_VERSION);
  v.put('planned',RRL_STOCK_PLAN_HELPER.decimal_text(l.PLANNED_QTY));v.put('picked',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICKED_QTY));
  v.put('short',RRL_STOCK_PLAN_HELPER.decimal_text(sh.SHORT_QTY));v.put('inventory_id',inventory_id);
  v.put('reservations',a);v.put('carrier',carrier);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;x json_object_t;j json_object_t:=json_object_t();
  a json_array_t;carrier json_array_t;sh RRL_CASE_PICK_SHORT%rowtype;l RRL_CASE_PICK_LINE%rowtype;ct RRL_CASE_PICK_TASK%rowtype;
  sr RRL_STOCK_RESERVATION%rowtype;plan clob;op varchar2(100);short_id number;line_id number;task_id number;wave_id number;
  inv_id number;pt_id number;wt_id number;ware number;ver number;sid number;auto_inv number:=1;resource_type varchar2(100):='INVENTORY';
  weight_wire clob;weight_j json_object_t;weight_pct number;weight_version number;weight_requested number;weight_picked number;decision varchar2(20);confirm_mode varchar2(20):='AUDITOR';sla_seconds number:=300;assignee varchar2(100);wave_status varchar2(40);pt_status varchar2(40);wt_status varchar2(40);total number:=0;held number:=0;qty number;article varchar2(160);v_cell varchar2(60);reason varchar2(1000);
 begin
  if RRL_HAS_WRIGHT(p_actor,'case_pick_short_approve')!=1 then raise_application_error(-20882,'CASE_SHORT_APPROVE_FORBIDDEN');end if;
  decision:=nvl(d.get_object('metadata').get_string('decision'),'ACCEPT_SHORT');
  if decision='READY' then RRL_STOCK_SHORT_RECOVERY.execute_ready(p_request,p_actor,p_result);return;end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  short_id:=v.get_number('short_id');line_id:=v.get_number('line_id');task_id:=v.get_number('task_id');wave_id:=v.get_number('wave');
  pt_id:=v.get_number('pick_task');wt_id:=v.get_number('wave_task');ware:=v.get_number('warehouse');article:=v.get_string('article');v_cell:=v.get_string('cell');
  select STATUS into wave_status from RRL_PICK_WAVE where PICK_WAVE_ID=wave_id for update;
  select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_id for update;
  select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=line_id for update;
  select * into sh from RRL_CASE_PICK_SHORT where CASE_PICK_SHORT_ID=short_id for update;
  select STATUS into pt_status from RRL_PICK_TASK where PICK_TASK_ID=pt_id for update;
  select STATUS into wt_status from RRL_PICK_WAVE_TASK where PICK_WAVE_TASK_ID=wt_id and PICK_TASK_ID=pt_id and PICK_WAVE_ID=wave_id for update;
  if ct.CONTENT_VERSION!=v.get_number('version') or ct.WARE_ID!=ware or l.CASE_PICK_TASK_ID!=task_id
   or l.PICK_TASK_ID!=pt_id or l.PICK_WAVE_ID!=wave_id or l.PICK_WAVE_TASK_ID!=wt_id or l.ARTICUL!=article or l.CELL_CODE!=v_cell
   or RRL_STOCK_PLAN_HELPER.decimal_text(l.PLANNED_QTY)!=v.get_string('planned')
   or RRL_STOCK_PLAN_HELPER.decimal_text(l.PICKED_QTY)!=v.get_string('picked')
   or RRL_STOCK_PLAN_HELPER.decimal_text(sh.SHORT_QTY)!=v.get_string('short') then raise_application_error(-20890,'CLOSURE_CHANGED: case shortage');end if;
  if wave_status is null or wave_status in('CANCELLED','CLOSED','COMPLETED','SHIPPED','DRAFT','PREVIEW')
   or ct.STATUS is null or ct.STATUS not in('IN_PROGRESS','PARTIAL','WAIT_REPLENISHMENT')
   or sh.STATUS is null or sh.STATUS not in('CREATED','PENDING_APPROVAL')
   or l.STATUS is null or l.STATUS!='PARTIAL' or pt_status in('DONE','CANCELLED','FAILED') or wt_status in('DONE','CANCELLED','FAILED')
   or sh.CASE_PICK_TASK_ID!=task_id or sh.CASE_PICK_LINE_ID!=line_id or sh.PICK_WAVE_ID!=wave_id
   or sh.PICKED_QTY!=l.PICKED_QTY or sh.PLANNED_QTY!=l.PLANNED_QTY or sh.SHORT_QTY<=0
   or sh.PICKED_QTY+sh.SHORT_QTY!=sh.PLANNED_QTY then raise_application_error(-20886,'CASE_SHORT_APPROVAL_STATE_CONFLICT');end if;
  if decision='WEIGHT_TOLERANCE'then
   weight_wire:=RRL_CASE_WEIGHT_DECISION.current_json(p_request,task_id,line_id,p_actor);
   if dbms_lob.compare(weight_wire,v.get_object('weight_order_snapshot').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: order weight decision');end if;
   weight_j:=json_object_t.parse(weight_wire);weight_pct:=weight_j.get_number('tolerance_pct');
   weight_version:=weight_j.get_number('policy_version');
   weight_requested:=RRL_STOCK_MATH.quantity(weight_j.get_string('requested_quantity'));
   weight_picked:=RRL_STOCK_MATH.quantity(weight_j.get_string('picked_quantity'));
  end if;
  a:=v.get_array('reservations');carrier:=v.get_array('carrier');
  if dbms_lob.compare(unused_reservations(wave_id,pt_id).to_clob,a.to_clob)!=0
   or dbms_lob.compare(RRL_STOCK_CASE_PICK_CMD.carrier_rows(task_id),carrier.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: case shortage composition');end if;
  for i in 0..carrier.get_size-1 loop
   x:=treat(carrier.get(i) as json_object_t);
   if x.get_number('case_line')=line_id then total:=total+RRL_STOCK_MATH.quantity(x.get_string('quantity'));end if;
  end loop;
  if total!=l.PICKED_QTY then raise_application_error(-20887,'CASE_SHORT_PHYSICAL_FACT_CONFLICT');end if;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);held:=held+RRL_STOCK_MATH.quantity(x.get_string('qty'));
  end loop;
  if held>sh.SHORT_QTY then raise_application_error(-20869,'CASE_SHORT_UNUSED_RESERVE_EXCEEDS_REMAINDER');end if;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);sid:=x.get_number('id');
   select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=sid for update;
   if sr.RESERVATION_VERSION!=x.get_number('version') or sr.ARTICUL!=article then raise_application_error(-20890,'CLOSURE_CHANGED: case shortage reservation');end if;
   select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=sr.ARTICUL and INPUT_UOM=sr.BASE_UOM and BASE_UOM=sr.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
   if ver is null then raise_application_error(-20868,'CASE_SHORT_BASE_POLICY_REQUIRED');end if;
   RRL_STOCK_UNIT_CORE.release_units(sid,sr.BASE_QTY,null,0);
   RRL_STOCK_RESERVE_CORE.release_hard(sid,sr.BASE_QTY,ver,'PICK_WAVE',wave_id,p_actor);
  end loop;
  begin
   select AUTO_INVENTORY_ON_SHORT,INVENTORY_RESOURCE_TYPE,SHORT_CONFIRM_MODE,SHORT_RECOVERY_SLA_SECONDS into auto_inv,resource_type,confirm_mode,sla_seconds from RRL_CASE_PICK_SETTING where WARE_ID=ware and ACTIVE=1;
  exception when no_data_found then null;end;
  if decision='RESTORE' and confirm_mode='SELF' and RRL_HAS_WRIGHT(sh.CREATED_BY,'stock_inventory_count')=1
   and RRL_HAS_WRIGHT(sh.CREATED_BY,'inventory_task_execute')=1 then assignee:=sh.CREATED_BY;end if;
  if decision='RESTORE' or(decision!='WEIGHT_TOLERANCE'and nvl(auto_inv,1)!=0)then
   inv_id:=v.get_number('inventory_id');
   insert into RRL_INVENTORY_TASK(INVENTORY_TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_DOC_TYPE,SOURCE_DOC_ID,STATUS,WARE_ID,CELL_CODE,ARTICUL,PLANNED_QTY,ASSIGNED_RESOURCE_TYPE,CREATED_AT,CREATED_BY,ASSIGNED_TO,PRIORITY)
    values(inv_id,'INVENTORY_CHECK','CASE_PICK_SHORT','CASE_PICK_SHORT',short_id,case when assignee is not null then 'ASSIGNED' else 'NEW' end,ware,v_cell,article,l.PLANNED_QTY,nvl(resource_type,'INVENTORY'),systimestamp,p_actor,assignee,case when decision='RESTORE' then 0 else 100 end);
  end if;
  reason:=d.get_object('metadata').get_string('reason');
  update RRL_CASE_PICK_SHORT set STATUS='ACCEPTED',INVENTORY_TASK_ID=inv_id,APPROVED_AT=systimestamp,APPROVED_BY=p_actor,
   REASON_TEXT=substr(nvl(reason,REASON_TEXT),1,1000),
   RECOVERY_STATE=case when decision='RESTORE' then 'WAIT_INVENTORY' else null end,
   RECOVERY_DEADLINE_AT=case when decision='RESTORE' then nvl(RECOVERY_DEADLINE_AT,CREATED_AT+numtodsinterval(sla_seconds,'SECOND')) else RECOVERY_DEADLINE_AT end
   where CASE_PICK_SHORT_ID=short_id;
  if decision='WEIGHT_TOLERANCE'then
   update RRL_CASE_PICK_SHORT set WEIGHT_POLICY_VERSION=weight_version,WEIGHT_TOLERANCE_PCT=weight_pct,
    WEIGHT_ORDER_REQUESTED_KG=weight_requested,WEIGHT_ORDER_PICKED_KG=weight_picked,WEIGHT_DECISION_OPERATION=op
    where CASE_PICK_SHORT_ID=short_id;
  end if;
  if decision='RESTORE' then
   update RRL_CASE_PICK_LINE set STATUS='WAIT_REPLENISHMENT',UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_LINE_ID=line_id;
   update RRL_PICK_TASK set STATUS='IN_PROGRESS',FACT_QTY=l.PICKED_QTY,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_TASK_ID=pt_id;
   update RRL_PICK_WAVE_TASK set STATUS='IN_PROGRESS',FACT_QTY=l.PICKED_QTY,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_TASK_ID=wt_id;
   update RRL_CASE_PICK_TASK set STATUS='WAIT_REPLENISHMENT' where CASE_PICK_TASK_ID=task_id;
  else
  update RRL_CASE_PICK_LINE set STATUS='SHORT_PICKED',DONE_AT=systimestamp,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_LINE_ID=line_id;
  update RRL_PICK_TASK set FACT_QTY=l.PICKED_QTY,STATUS='DONE',DONE_AT=sysdate,DONE_BY=p_actor,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_TASK_ID=pt_id;
  update RRL_PICK_WAVE_TASK set FACT_QTY=l.PICKED_QTY,STATUS='DONE',DONE_AT=sysdate,DONE_BY=p_actor,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_TASK_ID=wt_id;
  end if;
  update RRL_CASE_PICK_TASK set CONTENT_VERSION=CONTENT_VERSION+1,
   PICKED_LINES=(select count(*) from RRL_CASE_PICK_LINE where CASE_PICK_TASK_ID=task_id and STATUS in('PICKED','SHORT_PICKED','CANCELLED')),
   UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=task_id;
  insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,CASE_PICK_LINE_ID,EVENT_TYPE,PAYLOAD_JSON,CREATED_BY)
   values(RRL_CASE_PICK_EVENT_SQ.nextval,task_id,line_id,case when decision='RESTORE'then 'RECOVERY_STARTED'when decision='WEIGHT_TOLERANCE'then 'WEIGHT_TOLERANCE_ACCEPTED'else 'SHORT_ACCEPTED'end,p_request,p_actor);
  if decision='WEIGHT_TOLERANCE'then j.put('weight_order_snapshot',weight_j);j.put('decision','WEIGHT_TOLERANCE');end if;
  j.put('recovery_state',case when decision='RESTORE' then 'WAIT_INVENTORY' else null end);j.put('status','ACCEPTED');j.put('inventory_task_id',inv_id);j.put('released_reservations',a.get_size);j.put('operation_id',op);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CASE_TYPE_CMD as
 g_task number;g_op varchar2(100);g_tx varchar2(100);
 function snapshot(p_request clob,p_actor varchar2)return clob is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');src json_object_t:=d.get_object('source');
  j json_object_t;keys json_key_list;task_no number;type_no number;version_no number;n number;scan_value varchar2(200);reason_value varchar2(1000);el json_element_t;
 begin
  keys:=src.get_keys;el:=src.get('case_task_id');
  if keys.count!=1 or el is null or not el.is_number then raise_application_error(-20886,'CASE_TYPE_CANONICAL_TASK_REQUIRED');end if;
  task_no:=src.get_number('case_task_id');
  if task_no is null or task_no<1 or task_no!=trunc(task_no)then raise_application_error(-20886,'CASE_TYPE_TASK_REQUIRED');end if;
  RRL_CASE_TASK_ACCESS.assert_scope(task_no,p_actor,'case_pick_execute');
  if d.get_array('lines').get_size!=0 or d.get_array('units').get_size!=0 then raise_application_error(-20886,'CASE_TYPE_ZERO_QUANTITY_COMMAND_REQUIRED');end if;
  keys:=m.get_keys;
  if keys.count!=4 or not m.has('expected_version')or not m.has('pallet_type_id')or not m.has('scan_container')or not m.has('reason')then
   raise_application_error(-20886,'CASE_TYPE_EXPLICIT_FIELDS_REQUIRED');end if;
  el:=m.get('expected_version');if el is null or not el.is_number then raise_application_error(-20886,'CASE_TYPE_VERSION_REQUIRED');end if;
  el:=m.get('pallet_type_id');if el is null or not el.is_number then raise_application_error(-20886,'CASE_TYPE_TYPE_REQUIRED');end if;
  el:=m.get('scan_container');if el is null or not el.is_string then raise_application_error(-20886,'CASE_TYPE_SCAN_REQUIRED');end if;
  el:=m.get('reason');if el is null or not el.is_string then raise_application_error(-20886,'CASE_TYPE_REASON_REQUIRED');end if;
  version_no:=m.get_number('expected_version');type_no:=m.get_number('pallet_type_id');scan_value:=m.get_string('scan_container');reason_value:=trim(m.get_string('reason'));
  if version_no is null or version_no<0 or version_no!=trunc(version_no)or type_no is null or type_no<1 or type_no!=trunc(type_no)then
   raise_application_error(-20886,'CASE_TYPE_INTEGER_FIELDS_REQUIRED');end if;
  if reason_value is null or length(reason_value)>500 then raise_application_error(-20886,'CASE_TYPE_REASON_REQUIRED');end if;
  j:=json_object_t.parse(RRL_CASE_PALLET_TYPE_READ.describe_type(task_no,p_actor));
  if not j.get_boolean('can_change_empty_type')then raise_application_error(-20886,j.get_string('change_blocker'));end if;
  if j.get_number('version')!=version_no then raise_application_error(-20886,'CASE_TYPE_VERSION_CHANGED');end if;
  if scan_value is null or(scan_value!='CASE:'||to_char(task_no,'TM9')and(scan_value!=j.get_string('sscc')or j.get_string('sscc')is null))then
   raise_application_error(-20886,'CASE_TYPE_CURRENT_CONTAINER_SCAN_REQUIRED');end if;
  if type_no=j.get_number('actual_pallet_type_id')then raise_application_error(-20886,'CASE_TYPE_ALREADY_CURRENT');end if;
  select count(*)into n from RRL_PALLET_TYPE where PALLET_TYPE_ID=type_no and ACTIVE=1;
  if n!=1 then raise_application_error(-20886,'CASE_TYPE_ACTIVE_TYPE_REQUIRED');end if;
  if not j.get('assigned_to').is_null and j.get_string('assigned_to')!=p_actor and RRL_HAS_WRIGHT(p_actor,'case_pick_manage')!=1 then
   raise_application_error(-20882,'CASE_TYPE_ASSIGNED_OPERATOR_REQUIRED');end if;
  j.put('new_pallet_type_id',type_no);j.put('reason',reason_value);return j.to_clob;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
  d json_object_t:=json_object_t.parse(p_request);j json_object_t;value_wire clob;f json_array_t:=json_array_t();r json_array_t:=json_array_t();task_key varchar2(100);
 begin
  value_wire:=snapshot(p_request,d.get_string('actor'));j:=json_object_t.parse(value_wire);task_key:=to_char(j.get_number('case_task_id'),'TM9');
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',task_key);
  RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU','CASE:'||task_key);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  j.put('snapshot_signature',rawtohex(sys.dbms_crypto.hash(value_wire,sys.dbms_crypto.hash_sh256)));
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=j.to_clob;
 end;
 procedure assert_writing(p_task number)is n number;
 begin
  if g_task is null or g_task!=p_task or g_op is null or g_tx is null or g_tx!=dbms_transaction.local_transaction_id(false)
   or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=g_op then
   raise_application_error(-20863,'CASE_TYPE_ROOT_OWNER_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_TASK',to_char(p_task,'TM9')));
  select count(*)into n from RRL_STOCK_OPERATION where OPERATION_ID=g_op and COMMAND_TYPE='CASE_PALLET_TYPE_CHANGE'and STATE='IN_FLIGHT';
  if n!=1 then raise_application_error(-20863,'CASE_TYPE_CURRENT_ROOT_REQUIRED');end if;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);frozen json_object_t;j json_object_t;plan clob;value_wire clob;
  task_no number;new_type number;old_version number;locked_version number;op varchar2(100):=d.get_string('operation_id');
 begin
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;frozen:=json_object_t.parse(plan).get_object('domain');
  task_no:=frozen.get_number('case_task_id');new_type:=frozen.get_number('new_pallet_type_id');old_version:=frozen.get_number('version');
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_TASK',to_char(task_no,'TM9')));
  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU','CASE:'||to_char(task_no,'TM9')));
  begin select nvl(CONTENT_VERSION,0)into locked_version from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_no for update nowait;
  exception when others then if sqlcode=-54 then raise_application_error(-20840,'CASE_TYPE_ROW_BUSY');else raise;end if;end;
  value_wire:=snapshot(p_request,p_actor);
  if rawtohex(sys.dbms_crypto.hash(value_wire,sys.dbms_crypto.hash_sh256))!=frozen.get_string('snapshot_signature')then
   raise_application_error(-20890,'CLOSURE_CHANGED: case pallet type');end if;
  g_task:=task_no;g_op:=op;g_tx:=dbms_transaction.local_transaction_id(false);
  update RRL_CASE_PICK_TASK set PALLET_TYPE_ID=new_type,CONTENT_VERSION=old_version+1 where CASE_PICK_TASK_ID=task_no and nvl(CONTENT_VERSION,0)=old_version;
  if sql%rowcount!=1 then raise_application_error(-20886,'CASE_TYPE_VERSION_CHANGED');end if;
  g_task:=null;g_op:=null;g_tx:=null;
  j:=json_object_t();j.put('operation_id',op);j.put('command_type','CASE_PALLET_TYPE_CHANGE');j.put('case_task_id',task_no);
  j.put('pallet_type_id',new_type);j.put('previous_pallet_type_id',frozen.get_number('actual_pallet_type_id'));j.put('planned_pallet_type_id',frozen.get_number('planned_pallet_type_id'));
  j.put('version',old_version+1);j.put('reason',frozen.get_string('reason'));j.put('stock_changed',false);j.put('status','APPLIED');p_result:=j.to_clob;
 exception when others then g_task:=null;g_op:=null;g_tx:=null;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CHANGE_AUDIT as
 function parts(p_key raw) return json_array_t is
  result json_array_t:=json_array_t();v_hex varchar2(2000):=rawtohex(p_key);
  pos pls_integer:=1;colon pls_integer;n pls_integer;value varchar2(2000);
 begin
  while pos<=length(v_hex) loop
   colon:=instr(v_hex,'3A',pos);
   while colon>0 and mod(colon,2)=0 loop colon:=instr(v_hex,'3A',colon+1);end loop;
   if colon=0 then raise_application_error(-20841,'AUDIT_RESOURCE_ENCODING_INVALID');end if;
   n:=to_number(utl_i18n.raw_to_char(hextoraw(substr(v_hex,pos,colon-pos)),'AL32UTF8'));
   if n<1 or colon+2+2*n-1>length(v_hex) then raise_application_error(-20841,'AUDIT_RESOURCE_LENGTH_INVALID');end if;
   pos:=colon+2;value:=utl_i18n.raw_to_char(hextoraw(substr(v_hex,pos,2*n)),'AL32UTF8');result.append(value);pos:=pos+2*n;
  end loop;
  if result.get_string(0)!='2' then raise_application_error(-20841,'AUDIT_RESOURCE_VERSION_INVALID');end if;
  return result;
 end;
 function snapshot(p_resources clob) return clob is
  unit_keys json_array_t:=json_array_t();reserve_ids json_array_t:=json_array_t();key_parts json_array_t;
  result json_object_t:=json_object_t();unit_json clob;reserve_json clob;unit_plan clob;reserve_plan clob;key_raw raw(1000);id_text varchar2(100);
 begin
  for r in(select distinct RANK_NO,KEY_HEX from json_table(p_resources,'$[*]' columns(
   RANK_NO number path '$.rank',KEY_HEX varchar2(2000) path '$.key_hex')) where RANK_NO in(20,60) order by RANK_NO,KEY_HEX) loop
   key_raw:=hextoraw(r.KEY_HEX);key_parts:=parts(key_raw);
   if r.RANK_NO=60 and key_parts.get_string(1)='UNIT' then
    RRL_STOCK_LOCK_API.assert_held(60,key_raw);unit_keys.append(key_parts.get_string(2));
   elsif r.RANK_NO=20 and key_parts.get_string(1)='ROW' and key_parts.get_string(2)='RRL_STOCK_RESERVATION' then
    RRL_STOCK_LOCK_API.assert_held(20,key_raw);id_text:=key_parts.get_string(3);
    if not regexp_like(id_text,'^[1-9][0-9]*$') then raise_application_error(-20841,'AUDIT_RESERVATION_KEY_INVALID');end if;
    reserve_ids.append(id_text);
   end if;
  end loop;
  if unit_keys.get_size>10000 or reserve_ids.get_size>10000 then raise_application_error(-20881,'AUDIT_CHANGESET_BOUND');end if;
  unit_plan:=unit_keys.to_clob;reserve_plan:=reserve_ids.to_clob;
  select json_arrayagg(json_object(
    'key' value u.PHYSICAL_UNIT_KEY,'origin_uid' value u.UID_PALLET,'unit_id' value u.UNIT_ID,
    'uid' value u.CURRENT_UID,'cell' value u.CURRENT_CELL,'quantity' value to_char(u.BASE_QTY,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''),
    'unit' value u.BASE_UOM,'status' value u.STOCK_STATUS,'version' value u.UNIT_VERSION,'reservation_id' value u.HARD_RESERVATION_ID returning clob)
    order by u.PHYSICAL_UNIT_KEY returning clob) into unit_json
   from RRL_WMS_RECEIPT_UNIT u join json_table(unit_plan,'$[*]' columns(K varchar2(64) path '$'))j on j.K=u.PHYSICAL_UNIT_KEY;
  select json_arrayagg(json_object(
    'key' value to_char(sr.RESERVATION_ID,'TM9'),'kind' value sr.RESERVATION_KIND,'scope' value sr.RESERVATION_SCOPE,
    'domain' value sr.RESERVATION_DOMAIN,'status' value sr.STATUS,'uid' value sr.UID_PALLET,'cell' value sr.CELL,
    'quantity' value to_char(sr.BASE_QTY,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''),'unit' value sr.BASE_UOM,'version' value sr.RESERVATION_VERSION,
    'owner_type' value sr.SOURCE_DOC_TYPE,'owner_id' value sr.SOURCE_DOC_ID,'owner_line' value sr.SOURCE_LINE_ID,
    'wave_id' value sr.PICK_WAVE_ID,'plan_id' value sr.PICK_PLAN_ID,'plan_line' value sr.PICK_PLAN_LINE_ID,
    'order_id' value sr.CUSTOMER_ORDER_ID,'production_order_id' value sr.PRODUCTION_ORDER_ID,'slot_id' value sr.CELL_SLOT_ID returning clob)
    order by sr.RESERVATION_ID returning clob) into reserve_json
   from RRL_STOCK_RESERVATION sr join json_table(reserve_plan,'$[*]' columns(ID_VALUE number path '$'))j on j.ID_VALUE=sr.RESERVATION_ID;
  result.put('units',json_array_t.parse(nvl(unit_json,to_clob('[]'))));
  result.put('reservations',json_array_t.parse(nvl(reserve_json,to_clob('[]'))));
  return result.to_clob;
 end;
 function differences(p_before clob,p_after clob) return clob is
  before_doc json_object_t:=json_object_t.parse(p_before);after_doc json_object_t:=json_object_t.parse(p_after);result json_object_t:=json_object_t();
  procedure compare_collection(p_name varchar2) is
   old_array json_array_t:=before_doc.get_array(p_name);new_array json_array_t:=after_doc.get_array(p_name);
   changes json_array_t:=json_array_t();old_row json_object_t;new_row json_object_t;change_row json_object_t;k varchar2(200);
   type row_map is table of json_object_t index by varchar2(200);old_rows row_map;new_rows row_map;
  begin
   for i in 0..old_array.get_size-1 loop old_row:=treat(old_array.get(i) as json_object_t);old_rows(old_row.get_string('key')):=old_row;end loop;
   for i in 0..new_array.get_size-1 loop new_row:=treat(new_array.get(i) as json_object_t);new_rows(new_row.get_string('key')):=new_row;end loop;
   k:=old_rows.first;
   while k is not null loop
    old_row:=old_rows(k);change_row:=null;
    if not new_rows.exists(k) then change_row:=json_object_t();change_row.put_null('after');
    elsif dbms_lob.compare(old_row.to_clob,new_rows(k).to_clob)!=0 then change_row:=json_object_t();change_row.put('after',new_rows(k));end if;
    if change_row is not null then change_row.put('key',k);change_row.put('before',old_row);changes.append(change_row);end if;
    k:=old_rows.next(k);
   end loop;
   k:=new_rows.first;
   while k is not null loop
    if not old_rows.exists(k) then change_row:=json_object_t();change_row.put('key',k);change_row.put_null('before');change_row.put('after',new_rows(k));changes.append(change_row);end if;
    k:=new_rows.next(k);
   end loop;
   result.put(p_name,changes);
  end;
 begin
  compare_collection('units');compare_collection('reservations');return result.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_COMMAND_PLAN as
 procedure compile_move(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob) is
  v_doc json_object_t;v_lines json_array_t;v_line json_object_t;
  v_policies json_array_t:=json_array_t();v_resources json_array_t:=json_array_t();
  v_seen varchar2(32767);v_uid varchar2(200);v_article varchar2(160);v_from varchar2(60);v_to varchar2(60);
  procedure policy(p_kind varchar2,p_id varchar2) is v json_object_t:=json_object_t();
  begin
   v.put('key_hex',rawtohex(RRL_STOCK_LOCK_API.resource_key(p_kind,p_id)));v.put('mode',4);v_policies.append(v);
  end;
  procedure anchor(p_rank number,p_kind varchar2,p_id varchar2) is v json_object_t:=json_object_t();
  begin
   v.put('rank',p_rank);v.put('key_hex',rawtohex(RRL_STOCK_LOCK_API.resource_key(p_kind,p_id)));v_resources.append(v);
  end;
  procedure check_text(p_obj json_object_t,p_name varchar2,p_max number,p_value out varchar2) is v json_element_t;
  begin
   v:=p_obj.get(p_name);
   if v is null or not v.is_string then raise_application_error(-20880,'COMMAND_FIELD_INVALID: '||p_name); end if;
   p_value:=p_obj.get_string(p_name);
   if p_value is null or length(p_value)>p_max or instr(p_value,chr(0))>0 then
    raise_application_error(-20880,'COMMAND_FIELD_INVALID: '||p_name);
   end if;
  end;
 begin
  v_doc:=json_object_t.parse(p_request);v_doc.on_error(1);
  v_lines:=v_doc.get_array('lines');
  if v_lines is null or v_lines.get_size<1 or v_lines.get_size>200 then
   raise_application_error(-20881,'COMMAND_LINES_INVALID');
  end if;
  -- RELEASE precedes all row locks; config writers must take matching exclusive fences.
  policy('RELEASE','STOCK');policy('CONFIG','WAREHOUSE');anchor(10,'OP',p_operation);
  anchor(70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  for i in 0..v_lines.get_size-1 loop
   v_line:=treat(v_lines.get(i) as json_object_t);
   if v_line is null then raise_application_error(-20881,'COMMAND_LINE_NOT_OBJECT'); end if;
   v_line.on_error(1);
   check_text(v_line,'uid',200,v_uid);check_text(v_line,'article',160,v_article);
   check_text(v_line,'source_cell',60,v_from);check_text(v_line,'target_cell',60,v_to);
   policy('SKU',v_article);policy('CELL',v_from);policy('CELL',v_to);
   anchor(30,'HU',v_uid);anchor(50,'STOCK',v_uid);anchor(40,'SLOT','CELL:'||v_from);anchor(40,'SLOT','CELL:'||v_to);
  end loop;
  p_policies:=v_policies.to_clob;p_resources:=v_resources.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_COMPOSITION_CORE as
 function snapshot_before(p_resources clob) return clob is
  a json_array_t:=json_array_t();x json_object_t;v_uid varchar2(200);v_version number;v_qty number;v_sig varchar2(64);v_count number;v_units number:=0;v_uids number:=0;
 begin
  for k in(select distinct KEY_HEX from json_table(p_resources,'$[*]' columns(RANK_NO number path '$.rank',KEY_HEX varchar2(2000) path '$.key_hex')) where RANK_NO=50 order by KEY_HEX) loop
   v_uids:=v_uids+1;if v_uids>20000 then raise_application_error(-20881,'STOCK_COMPOSITION_UID_BOUND_20000');end if;
   v_uid:=RRL_STOCK_INVARIANT_CORE.stock_uid(hextoraw(k.KEY_HEX));
   RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',v_uid));
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_PALLETS',v_uid));
   select nvl(max(STOCK_COMPOSITION_VERSION),0) into v_version from RRL_PALLETS where UID_PALLET=v_uid;
   select nvl(sum(REMAIN),0) into v_qty from RRL_REMAINS where UID_POLETA=v_uid;
   RRL_STOCK_HU_UNIT_SIGNATURE.describe_units(v_uid,null,v_sig,v_count);
   v_units:=v_units+v_count;if v_units>20000 then raise_application_error(-20881,'STOCK_COMPOSITION_UNIT_BOUND_20000');end if;
   x:=json_object_t();x.put('uid',v_uid);x.put('version',v_version);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));x.put('unit_signature',v_sig);a.append(x);
  end loop;
  return a.to_clob;
 end;
 procedure finish_changes(p_before clob) is
  a json_array_t:=json_array_t.parse(p_before);x json_object_t;v_uid varchar2(200);v_version number;v_qty number;v_sig varchar2(64);v_count number;v_units number:=0;changed json_array_t:=json_array_t();changes clob;row_no number;op varchar2(100);actor_name varchar2(50);event_payload clob;j json_object_t;
 begin
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);v_uid:=x.get_string('uid');v_version:=x.get_number('version');
   RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',v_uid));
   select nvl(sum(REMAIN),0) into v_qty from RRL_REMAINS where UID_POLETA=v_uid;
   RRL_STOCK_HU_UNIT_SIGNATURE.describe_units(v_uid,null,v_sig,v_count);
   v_units:=v_units+v_count;if v_units>20000 then raise_application_error(-20881,'STOCK_COMPOSITION_UNIT_BOUND_20000');end if;
   if RRL_STOCK_PLAN_HELPER.decimal_text(v_qty)!=x.get_string('quantity') or v_sig!=x.get_string('unit_signature') then
    RRL_STOCK_CTX_API.begin_effect('COMPOSITION',v_uid);
    update RRL_PALLETS set STOCK_COMPOSITION_VERSION=STOCK_COMPOSITION_VERSION+1 where UID_PALLET=v_uid and STOCK_COMPOSITION_VERSION=v_version;
    if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: stock composition epoch');end if;
    RRL_STOCK_CTX_API.end_effect;changed.append(v_uid);
   end if;
  end loop;
  if changed.get_size=0 then return;end if;changes:=changed.to_clob;
  -- Match QC/physical packing actual-row order. Every row was declared before locking.
  for st in(select ID from RRL_SBORKA_PALLETS where nvl(CONDITION,0)<2 and ID in(
   select LEGACY_SBORKA_PALLET_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(
    select CASE_PICK_TASK_ID from RRL_CASE_CARRIER_LOT where LOT_UID in(select U from json_table(changes,'$[*]' columns(U varchar2(200) path '$'))))
   union select LEGACY_SBORKA_PALLET_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where PICKED_PALLET_UID in(select U from json_table(changes,'$[*]' columns(U varchar2(200) path '$')))) order by ID) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(st.ID)));
   select ID into row_no from RRL_SBORKA_PALLETS where ID=st.ID for update;
   update RRL_SBORKA_PALLETS set SCAN_CONTENT_SIGNATURE=null,WEIGHT_CONTENT_SIGNATURE=null,
    SCAN_MARK_PROVED=0,SCAN_PHYSICAL_UNIT_COUNT=0,SCAN_ITEM_PROVED=0 where ID=st.ID;
  end loop;
  op:=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');select ACTOR into actor_name from RRL_STOCK_OPERATION where OPERATION_ID=op;
  for ct in(select CASE_PICK_TASK_ID,STATUS from RRL_CASE_PICK_TASK where STATUS in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP') and CASE_PICK_TASK_ID in(
   select CASE_PICK_TASK_ID from RRL_CASE_CARRIER_LOT where LOT_UID in(select U from json_table(changes,'$[*]' columns(U varchar2(200) path '$')))) order by CASE_PICK_TASK_ID) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(ct.CASE_PICK_TASK_ID)));
   select CASE_PICK_TASK_ID into row_no from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=ct.CASE_PICK_TASK_ID for update;
   update RRL_CASE_PICK_TASK set STATUS='WAIT_CONTROL',CONTENT_VERSION=CONTENT_VERSION+1,UPDATED_AT=systimestamp,UPDATED_BY=actor_name where CASE_PICK_TASK_ID=ct.CASE_PICK_TASK_ID;
   j:=json_object_t();j.put('operation_id',op);j.put('reason','STOCK_COMPOSITION_CHANGED');j.put('previous_status',ct.STATUS);event_payload:=j.to_clob;
   insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,EVENT_TYPE,PAYLOAD_JSON,CREATED_BY)
    values(RRL_CASE_PICK_EVENT_SQ.nextval,ct.CASE_PICK_TASK_ID,'CONTROL_REVOKED',event_payload,actor_name);
  end loop;
 exception when others then RRL_STOCK_CTX_API.end_effect;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CONFIG_API as
 procedure begin_change(p_actor varchar2,p_permission varchar2) is
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();v_state varchar2(20);
 begin
  if p_actor is null or p_permission is null or p_permission not in('warehouse_settings_edit','finished_goods_edit','sap_article_import','pick_topology_edit','transport_fleet_edit')
   or RRL_HAS_WRIGHT(p_actor,p_permission)!=1 then raise_application_error(-20882,'CONFIGURATION_FORBIDDEN');end if;
  select STATE into v_state from RRL_STOCK_RELEASE where RELEASE_ID=1;
  if v_state not in('PREPARED','ACTIVE') then raise_application_error(-20860,'CONFIGURATION_RELEASE_CLOSED');end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE',6);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_POLICY_GUARD','WAREHOUSE.CONFIGURATION');
  RRL_STOCK_LOCK_API.begin_plan;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(r.to_clob);
  select STATE into v_state from RRL_STOCK_RELEASE where RELEASE_ID=1;
  if v_state not in('PREPARED','ACTIVE') then raise_application_error(-20860,'CONFIGURATION_RELEASE_CLOSED');end if;
  RRL_STOCK_CTX_API.open_configuration(p_actor,p_permission);
 end;
 procedure end_change is
 begin RRL_STOCK_CTX_API.clear_operation;RRL_STOCK_LOCK_API.clear_plan;end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_CTX_API as
 procedure open_operation(p_operation varchar2,p_mode varchar2 default 'EXPLICIT') is v_state varchar2(20);
 begin
  select STATE into v_state from RRL_STOCK_RELEASE where RELEASE_ID=1;
  if v_state!='ACTIVE' then raise_application_error(-20860,'STOCK_RELEASE_NOT_ACTIVE'); end if;
  if p_mode is null or p_mode not in('EXPLICIT','COMPAT') then raise_application_error(-20861,'STOCK_CONTEXT_MODE_INVALID'); end if;
  RRL_STOCK_LOCK_API.assert_held(10,RRL_STOCK_LOCK_API.resource_key('OP',p_operation));
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is not null then raise_application_error(-20862,'POSTING_ALREADY_ENTERED'); end if;
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','OPERATION_ID',p_operation);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','TX_ID',dbms_transaction.local_transaction_id(false));
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','MODE',p_mode);
 end;
 procedure begin_effect(p_kind varchar2,p_uid varchar2 default null,p_cell varchar2 default null,p_row_id number default null) is v_tx varchar2(100);
 begin
  v_tx:=dbms_transaction.local_transaction_id(false);
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null or v_tx is null or
   sys_context('RRL_STOCK_WRITE_CTX','TX_ID') is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=v_tx
   or p_kind is null or p_kind not in('STOCK','JOURNAL','RESERVATION','UNIT','COMPOSITION') then raise_application_error(-20863,'EFFECT_CONTEXT_FORBIDDEN');end if;
  if sys_context('RRL_STOCK_WRITE_CTX','EFFECT') is not null then raise_application_error(-20862,'NESTED_EFFECT_FORBIDDEN');end if;
  if p_uid is not null then RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));end if;
  if p_kind in('STOCK','JOURNAL','UNIT','COMPOSITION') and p_uid is null then raise_application_error(-20863,'EFFECT_UID_REQUIRED');end if;
  if p_kind='RESERVATION' then
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(p_row_id)));
  end if;
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT',p_kind);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT_UID',p_uid);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT_CELL',p_cell);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT_ROW_ID',RRL_STOCK_PLAN_HELPER.decimal_text(p_row_id));
 end;
 procedure begin_staging(p_uid varchar2,p_cell varchar2) is
 begin
  begin_effect('UNIT',p_uid,p_cell);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT','RECEIPT_CAPTURE');
 end;
 procedure end_effect is
 begin
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT',null);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT_UID',null);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT_CELL',null);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','EFFECT_ROW_ID',null);
 end;
 procedure open_configuration(p_actor varchar2,p_permission varchar2) is
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is not null then raise_application_error(-20862,'POSTING_ALREADY_ENTERED');end if;
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','TX_ID',dbms_transaction.local_transaction_id(false));
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','MODE','CONFIG');
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','ACTOR',p_actor);
  dbms_session.set_context('RRL_STOCK_WRITE_CTX','CONFIG_PERMISSION',p_permission);
 end;
 procedure clear_operation is
 begin
  dbms_session.clear_context('RRL_STOCK_WRITE_CTX',null);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_DOC_RESERVE_CMD as
 function document_table(p_type varchar2) return varchar2 is
 begin
  case p_type when 'PICK_WAVE' then return 'RRL_PICK_WAVE';when 'PICK_PLAN' then return 'RRL_PICK_PLAN';
   when 'PRODUCTION_ORDER' then return 'RRL_PRODUCTION_ORDER';else raise_application_error(-20869,'RESERVATION_DOCUMENT_TYPE_UNSUPPORTED');end case;
 end;
 procedure compile_release(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);s json_object_t;v_type varchar2(40);v_doc number;v_only number;v_kind varchar2(10);
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t:=json_array_t();v json_object_t:=json_object_t();x json_object_t;
 begin
  s:=d.get_object('source');v_type:=s.get_string('document_type');v_doc:=s.get_number('document_id');
  v_only:=nvl(d.get_object('metadata').get_number('only_cancelled_replenishment'),0);v_kind:=d.get_object('metadata').get_string('reservation_kind');
  if v_kind is not null and v_kind not in('SOFT','HARD') then raise_application_error(-20869,'RESERVATION_KIND_INVALID');end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,document_table(v_type),RRL_STOCK_PLAN_HELPER.decimal_text(v_doc));
  for sr in(select * from RRL_STOCK_RESERVATION where ((SOURCE_DOC_TYPE=v_type and SOURCE_DOC_ID=v_doc) or (v_type='PICK_PLAN' and (PICK_PLAN_ID=v_doc or (RESERVATION_DOMAIN='WAVE' and exists(select 1 from RRL_PICK_WAVE_REPLENISH_TASK rt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=rt.PICK_TASK_ID where rt.PICK_WAVE_REPLENISH_TASK_ID=SOURCE_LINE_ID and pt.PICK_PLAN_ID=v_doc)))))
   and STATUS in('ACTIVE','ALLOCATED','PICKING') and (v_kind is null or RESERVATION_KIND=v_kind) and
    (v_only=0 or (v_type='PICK_WAVE' and RESERVATION_DOMAIN='WAVE' and exists(
     select 1 from RRL_PICK_WAVE_REPLENISH_TASK rt where rt.PICK_WAVE_ID=v_doc and rt.PICK_WAVE_REPLENISH_TASK_ID=SOURCE_LINE_ID and rt.STATUS in('CANCELLED','FAILED'))))
   order by RESERVATION_ID) loop
   if a.get_size>=10000 then raise_application_error(-20881,'DOCUMENT_RESERVATION_BOUND');end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(sr.RESERVATION_ID));
   if sr.UID_PALLET is not null then RRL_STOCK_PLAN_HELPER.stock_closure(f,r,sr.UID_PALLET,sr.ARTICUL,sr.CELL,null);
   else RRL_STOCK_PLAN_HELPER.fence(f,'SKU',sr.ARTICUL);end if;
   if v_only=1 then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(sr.SOURCE_LINE_ID));end if;
   x:=json_object_t();x.put('id',sr.RESERVATION_ID);x.put('version',sr.RESERVATION_VERSION);x.put('uid',sr.UID_PALLET);x.put('cell',sr.CELL);x.put('owner_type',sr.SOURCE_DOC_TYPE);x.put('owner_id',sr.SOURCE_DOC_ID);a.append(x);
  end loop;
  if d.get_string('command_type') in('WAVE_CANCEL','WAVE_RELEASE') then
   for z in(select PICK_WAVE_TASK_ID,PICK_TASK_ID from RRL_PICK_WAVE_TASK where PICK_WAVE_ID=v_doc order by PICK_WAVE_TASK_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(z.PICK_WAVE_TASK_ID));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(z.PICK_TASK_ID));
   end loop;
   for z in(select PICK_RESERVATION_ID from RRL_PICK_RESERVATION where PICK_PLAN_ID in(select PICK_PLAN_ID from RRL_PICK_WAVE_ORDER where PICK_WAVE_ID=v_doc) order by PICK_RESERVATION_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(z.PICK_RESERVATION_ID));
   end loop;
   for z in(select PICK_WAVE_REPLENISH_TASK_ID from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_ID=v_doc order by PICK_WAVE_REPLENISH_TASK_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(z.PICK_WAVE_REPLENISH_TASK_ID));
   end loop;
   for z in(select TASK_ID from RRL_WAREHOUSE_TASK where SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=v_doc order by TASK_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(z.TASK_ID));
   end loop;
  end if;
  if d.get_string('command_type')='PICK_PLAN_CANCEL' then
   for z in(select PICK_TASK_ID from RRL_PICK_TASK where PICK_PLAN_ID=v_doc order by PICK_TASK_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(z.PICK_TASK_ID));
    for wt in(select PICK_WAVE_TASK_ID,PICK_WAVE_ID from RRL_PICK_WAVE_TASK where PICK_TASK_ID=z.PICK_TASK_ID order by PICK_WAVE_TASK_ID) loop
     RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(wt.PICK_WAVE_ID));
     RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(wt.PICK_WAVE_TASK_ID));
    end loop;
   end loop;
   for pr in(select PICK_RESERVATION_ID from RRL_PICK_RESERVATION where PICK_PLAN_ID=v_doc order by PICK_RESERVATION_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(pr.PICK_RESERVATION_ID));
   end loop;
   for task in(select w.TASK_ID from RRL_WAREHOUSE_TASK w where w.TASK_SOURCE='WAVE' and (
    (w.TASK_TYPE='PICKING_MOVE' and exists(select 1 from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=wt.PICK_TASK_ID where wt.PICK_WAVE_TASK_ID=w.SOURCE_TASK_ID and pt.PICK_PLAN_ID=v_doc))
    or (w.TASK_TYPE='REPLENISHMENT' and exists(select 1 from RRL_PICK_WAVE_REPLENISH_TASK rt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=rt.PICK_TASK_ID where rt.PICK_WAVE_REPLENISH_TASK_ID=w.SOURCE_TASK_ID and pt.PICK_PLAN_ID=v_doc))) order by w.TASK_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(task.TASK_ID));
   end loop;
  end if;
  if d.get_string('command_type') in('WAVE_CANCEL','WAVE_RELEASE','PICK_PLAN_CANCEL') then
   for wr in(select PICK_WAVE_RESERVATION_ID from RRL_PICK_WAVE_RESERVATION where (v_type='PICK_WAVE' and PICK_WAVE_ID=v_doc) or (v_type='PICK_PLAN' and PICK_PLAN_ID=v_doc) order by PICK_WAVE_RESERVATION_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(wr.PICK_WAVE_RESERVATION_ID));
   end loop;
  end if;
  if d.get_string('command_type')='PICK_PLAN_CANCEL' then
   for rt in(select r.PICK_WAVE_REPLENISH_TASK_ID from RRL_PICK_WAVE_REPLENISH_TASK r join RRL_PICK_TASK pt on pt.PICK_TASK_ID=r.PICK_TASK_ID where pt.PICK_PLAN_ID=v_doc order by r.PICK_WAVE_REPLENISH_TASK_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(rt.PICK_WAVE_REPLENISH_TASK_ID));
   end loop;
  end if;
  v.put('document_type',v_type);v.put('document_id',v_doc);v.put('only_cancelled',v_only);v.put('reservations',a);
  p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_release(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;x json_object_t;j json_object_t:=json_object_t();
  a json_array_t;sr RRL_STOCK_RESERVATION%rowtype;v_plan clob;v_type varchar2(40);v_doc number;v_status varchar2(40);v_version number;
 begin
  declare
 v_json_sql_1_1 varchar2(32767):=d.get_string('operation_id');
begin
select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_1_1;
end;
  v:=json_object_t.parse(v_plan).get_object('domain');v_type:=v.get_string('document_type');v_doc:=v.get_number('document_id');a:=v.get_array('reservations');
  if RRL_HAS_WRIGHT(p_actor,'stock_reservation_edit')!=1
   and not(v_type='PICK_WAVE' and (RRL_HAS_WRIGHT(p_actor,'pick_wave_launch')=1 or RRL_HAS_WRIGHT(p_actor,'pick_wave_cancel')=1 or RRL_HAS_WRIGHT(p_actor,'pick_wave_release_reserves')=1))
   and not(v_type='PICK_PLAN' and RRL_HAS_WRIGHT(p_actor,'pick_plan_cancel')=1)
   and not(v_type='PRODUCTION_ORDER' and (RRL_HAS_WRIGHT(p_actor,'mes_raw_transfer_create')=1 or RRL_HAS_WRIGHT(p_actor,'mes_raw_transfer_cancel')=1 or RRL_HAS_WRIGHT(p_actor,'mes_raw_supply_calculate')=1))
   then raise_application_error(-20882,'DOCUMENT_RESERVATION_RELEASE_FORBIDDEN');end if;
  case v_type when 'PICK_WAVE' then select STATUS into v_status from RRL_PICK_WAVE where PICK_WAVE_ID=v_doc for update;
   when 'PICK_PLAN' then select STATUS into v_status from RRL_PICK_PLAN where PICK_PLAN_ID=v_doc for update;
   when 'PRODUCTION_ORDER' then select STATUS into v_status from RRL_PRODUCTION_ORDER where PRODUCTION_ORDER_ID=v_doc for update;
   else raise_application_error(-20869,'DOCUMENT_TYPE_INVALID');end case;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   declare
 v_json_sql_2_1 number:=x.get_number('id');
begin
select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=v_json_sql_2_1 for update;
end;
   if sr.RESERVATION_VERSION!=x.get_number('version') or sr.SOURCE_DOC_TYPE!=x.get_string('owner_type') or sr.SOURCE_DOC_ID!=x.get_number('owner_id') or sr.STATUS not in('ACTIVE','ALLOCATED','PICKING') then raise_application_error(-20890,'CLOSURE_CHANGED: document reservation');end if;
   if v.get_number('only_cancelled')=1 then
    select STATUS into v_status from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_ID=v_doc and PICK_WAVE_REPLENISH_TASK_ID=sr.SOURCE_LINE_ID for update;
    if v_status not in('CANCELLED','FAILED') then raise_application_error(-20890,'CLOSURE_CHANGED: replenishment cancellation');end if;
   end if;
   if sr.RESERVATION_KIND='HARD' then
    select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=sr.ARTICUL and INPUT_UOM=sr.BASE_UOM and BASE_UOM=sr.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
    if v_version is null then raise_application_error(-20868,'RESERVATION_RELEASE_BASE_POLICY_REQUIRED');end if;
    RRL_STOCK_UNIT_CORE.release_units(sr.RESERVATION_ID,sr.BASE_QTY,null,0);
    RRL_STOCK_RESERVE_CORE.release_hard(sr.RESERVATION_ID,sr.BASE_QTY,v_version,sr.SOURCE_DOC_TYPE,sr.SOURCE_DOC_ID,p_actor);
   elsif sr.RESERVATION_KIND='SOFT' then
    RRL_STOCK_CTX_API.begin_effect('RESERVATION',sr.UID_PALLET,sr.CELL,sr.RESERVATION_ID);
    declare
 v_json_sql_3_1 varchar2(32767):=d.get_object('metadata').get_string('reason');
begin
update RRL_STOCK_RESERVATION set STATUS='RELEASED',RELEASED_AT=systimestamp,RELEASED_BY=p_actor,
     RELEASE_REASON=v_json_sql_3_1,RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=sr.RESERVATION_ID;
end;
    RRL_STOCK_CTX_API.end_effect;
   else raise_application_error(-20869,'RESERVATION_KIND_INVALID');end if;
  end loop;
  if d.get_string('command_type')='PICK_PLAN_CANCEL' then
   if RRL_HAS_WRIGHT(p_actor,'pick_plan_cancel')!=1 then raise_application_error(-20882,'PICK_PLAN_CANCEL_FORBIDDEN');end if;
   for pt in(select PICK_TASK_ID,STATUS from RRL_PICK_TASK where PICK_PLAN_ID=v_doc order by PICK_TASK_ID for update) loop
    if pt.STATUS in('IN_PROGRESS','DONE') then raise_application_error(-20886,'PICK_PLAN_TASK_ALREADY_STARTED');end if;
   end loop;
   for task in(select w.TASK_ID,w.STATUS from RRL_WAREHOUSE_TASK w where w.TASK_SOURCE='WAVE' and (
    (w.TASK_TYPE='PICKING_MOVE' and exists(select 1 from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=wt.PICK_TASK_ID where wt.PICK_WAVE_TASK_ID=w.SOURCE_TASK_ID and pt.PICK_PLAN_ID=v_doc))
    or (w.TASK_TYPE='REPLENISHMENT' and exists(select 1 from RRL_PICK_WAVE_REPLENISH_TASK rt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=rt.PICK_TASK_ID where rt.PICK_WAVE_REPLENISH_TASK_ID=w.SOURCE_TASK_ID and pt.PICK_PLAN_ID=v_doc))) order by w.TASK_ID for update) loop
    if task.STATUS in('IN_PROGRESS','DONE') then raise_application_error(-20886,'PICK_PLAN_PHYSICAL_TASK_ALREADY_STARTED');end if;
    update RRL_WAREHOUSE_TASK set STATUS='CANCELLED' where TASK_ID=task.TASK_ID and STATUS in('PLANNED','ASSIGNED');
   end loop;
   RRL_PICKING_API.cancel_plan(v_doc,p_actor);
   update RRL_PICK_WAVE_REPLENISH_TASK set STATUS='CANCELLED',UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_TASK_ID in(select PICK_TASK_ID from RRL_PICK_TASK where PICK_PLAN_ID=v_doc) and STATUS in('NEW','ASSIGNED','RELEASED','QUEUED','WAIT_FREE_CELL','WAIT_MINIMAX');
   update RRL_PICK_WAVE_RESERVATION set RESERVATION_STATUS='RELEASED',RELEASED_AT=sysdate,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_PLAN_ID=v_doc and RESERVATION_STATUS='HARD';
   update RRL_PICK_WAVE_TASK set STATUS='CANCELLED' where PICK_TASK_ID in(select PICK_TASK_ID from RRL_PICK_TASK where PICK_PLAN_ID=v_doc) and STATUS in('NEW','ASSIGNED');
  end if;
  if d.get_string('command_type') in('WAVE_CANCEL','WAVE_RELEASE') then
   for task in(select TASK_ID,STATUS from RRL_WAREHOUSE_TASK where SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=v_doc order by TASK_ID for update) loop
    if task.STATUS in('IN_PROGRESS','DONE') then raise_application_error(-20886,'WAVE_PHYSICAL_TASK_ALREADY_STARTED');end if;
    update RRL_WAREHOUSE_TASK set STATUS='CANCELLED' where TASK_ID=task.TASK_ID and STATUS in('PLANNED','ASSIGNED');
   end loop;
  end if;
  if d.get_string('command_type')='WAVE_CANCEL' then
   if RRL_HAS_WRIGHT(p_actor,'pick_wave_cancel')!=1 then raise_application_error(-20882,'WAVE_CANCEL_FORBIDDEN');end if;
   RRL_PICK_WAVE_META.cancel_wave(v_doc,d.get_object('metadata').get_string('reason'),p_actor);
  elsif d.get_string('command_type')='WAVE_RELEASE' then
   if RRL_HAS_WRIGHT(p_actor,'pick_wave_release_reserves')!=1 then raise_application_error(-20882,'WAVE_RELEASE_FORBIDDEN');end if;
   RRL_PICK_WAVE_META.release_reservations(v_doc,p_actor);
  end if;
  j.put('operation_id',d.get_string('operation_id'));j.put('document_type',v_type);j.put('document_id',v_doc);j.put('released_count',a.get_size);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_EFFECT_CORE as



 procedure consume(p_uid varchar2,p_cell varchar2,p_qty number,p_uom varchar2,p_uom_version number,p_warehouse number,



  p_actor varchar2,p_line number,p_reservation number default null,p_doc_type varchar2 default null,



  p_doc_id number default null,p_units clob default null,p_outgoing_doc number default null,p_pallet_row number default null,p_supplier_return_receipt varchar2 default null,p_disposal_receipt varchar2 default null) is



  v_p number;v_h number;v_ver number;v_uom varchar2(20);v_event number;



 begin



  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));



  if p_supplier_return_receipt is not null and p_disposal_receipt is not null then raise_application_error(-20886,'CONSUMPTION_ONE_EXPLICIT_EXCEPTION_REQUIRED');end if;
  if p_disposal_receipt is not null then RRL_STOCK_RETURN_DISPOSE.validate_consume(p_disposal_receipt,p_uid,p_cell,p_qty,p_warehouse,p_actor);RRL_STOCK_LOCATION_CORE.assert_quarantine(p_cell,p_warehouse);
  elsif p_supplier_return_receipt is null then RRL_STOCK_LOCATION_CORE.assert_ordinary(p_cell,p_warehouse,'SOURCE');

  else RRL_STOCK_SUP_RETURN.validate_consume(p_supplier_return_receipt,p_uid,p_cell,p_qty,p_warehouse,p_actor);RRL_STOCK_LOCATION_CORE.assert_quarantine(p_cell,p_warehouse);end if;



  select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION,BASE_UOM into v_p,v_h,v_ver,v_uom



   from RRL_REMAINS where UID_POLETA=p_uid and CELL=p_cell;



  if p_qty is null or p_qty<=0 or p_qty>v_p or p_uom is null or p_uom!=v_uom then raise_application_error(-20868,'CONSUMPTION_STOCK_CONFLICT');end if;



  if p_reservation is not null then



   RRL_STOCK_UNIT_CORE.release_units(p_reservation,p_qty,p_units,1);



   RRL_STOCK_RESERVE_CORE.consume_hard(p_reservation,p_qty,p_uom_version,p_doc_type,p_doc_id,p_actor);



  else



   if p_qty>v_p-v_h then raise_application_error(-20869,'CONSUMPTION_RESERVATION_CONFLICT');end if;



   RRL_STOCK_UNIT_CORE.issue_free_units(p_uid,p_cell,p_qty,p_units);



   RRL_STOCK_BALANCE_CORE.apply_delta(p_uid,p_cell,-p_qty,0,p_uom,p_uom_version,v_ver);



  end if;



  RRL_STOCK_BALANCE_CORE.write_leg(p_uid,p_cell,null,-p_qty,p_uom,p_uom_version,p_line,1,3,p_actor,v_event,p_outgoing_doc,p_pallet_row);



 end;



end;
/


CREATE OR REPLACE package body RRL_STOCK_ELIGIBILITY as
 function reason(p_uid varchar2,p_cell varchar2,p_warehouse number,p_quantity number default 0,
  p_min_days number default null,p_min_percent number default null,p_purpose varchar2 default 'ALLOCATE',
  p_owner_reservation number default null,p_article varchar2 default null) return varchar2 is
  v_ware number;v_p number;v_h number;v_owned number:=0;v_article varchar2(160);v_expiry date;v_produced date;
  v_block number;v_system number;v_uom varchar2(20);v_mode varchar2(20);v_ready number;v_pending number;v_count number;v_days number;
 begin
  if p_warehouse is null or p_warehouse<1 or p_quantity is null or p_quantity<0
   or p_min_days<0 or p_min_percent<0 or p_min_percent>100
   or p_purpose is null or p_purpose not in('ALLOCATE','PICK','REPLENISH') then return 'SOURCE_ARGUMENT_INVALID';end if;
  begin
   select c.WARE_ID,s.REMAIN,s.HARD_RESERVED_BASE,s.BASE_UOM,p.ARTICUL,p.EXPIRY_DATE,p.PRODUCED_DATE,
    greatest(nvl(c.BLOCKED_FOR_REMAINS,0),nvl(c.BLOCKED_FOR_POPOLNENIE,0)),nvl(c.IS_SYSTEM,0),
    nvl(rule.SOURCE_PICK_MODE,'AFTER_PUTAWAY'),nvl(rule.MIN_SHELF_DAYS,0),nvl(br.IS_SHIPMENT_ALLOWED,1)
   into v_ware,v_p,v_h,v_uom,v_article,v_expiry,v_produced,v_block,v_system,v_mode,v_days,v_ready
   from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA join RRL_CELLS c on c.CELL=s.CELL
    left join RRL_RECEIPT_SKU_RULE rule on rule.WARE_ID=c.WARE_ID and rule.ARTICUL=p.ARTICUL
    left join RRL_PROD_BATCH_READY_V br on br.PROD_BATCH_ID=p.PROD_BATCH_ID
   where s.UID_POLETA=p_uid and s.CELL=p_cell;
  exception when no_data_found then return 'SOURCE_STOCK_NOT_FOUND';end;
  if v_ware is null or v_ware!=p_warehouse then return 'WAREHOUSE_LOCATION_CONFLICT';end if;
  if p_article is not null and p_article!=v_article then return 'SOURCE_ARTICLE_CONFLICT';end if;
  if v_block!=0 then return 'LOCATION_BLOCKED';end if;
  select count(*) into v_count from RRL_CASE_PICK_SHORT sh
   where sh.CELL_CODE=p_cell and sh.ARTICUL=v_article and
    (sh.STATUS in('CREATED','PENDING_APPROVAL') or sh.RECOVERY_STATE='WAIT_INVENTORY'
     or exists(select 1 from RRL_INVENTORY_TASK it where it.INVENTORY_TASK_ID=sh.INVENTORY_TASK_ID
       and it.STATUS not in('DONE','CANCELLED')));
  if v_count>0 then return 'SOURCE_INVENTORY_PENDING';end if;
  if v_p is null or v_h is null or v_p<0 or v_h<0 or v_h>v_p or v_uom is null then return 'SOURCE_BALANCE_INVALID';end if;
  select count(*) into v_count from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 and (CHILD_PALLET_UID=p_uid
   or CHILD_CASE_TASK_ID in(select CASE_PICK_TASK_ID from RRL_CASE_CARRIER_LOT where LOT_UID=p_uid));
  if v_count>0 then return 'SOURCE_NESTED_HU_REQUIRES_UNPACK';end if;
  select count(*) into v_count from RRL_CASE_CARRIER_LOT where LOT_UID=p_uid;
  if v_count>0 then return 'CASE_CARRIER_NOT_ALLOCATABLE';end if;
  if v_ready!=1 then return 'SOURCE_REGULATORY_NOT_READY';end if;
  if v_expiry is not null and trunc(v_expiry)<trunc(sysdate) then return 'SOURCE_EXPIRED';end if;
  v_days:=greatest(v_days,nvl(p_min_days,0));
  if v_days>0 and (v_expiry is null or trunc(v_expiry)-trunc(sysdate)<v_days) then return 'SOURCE_SHELF_DAYS';end if;
  if p_min_percent is not null and (v_expiry is null or v_produced is null
   or trunc(v_expiry)<=trunc(v_produced) or
   (trunc(v_expiry)-trunc(sysdate))*100<p_min_percent*(trunc(v_expiry)-trunc(v_produced))) then return 'SOURCE_SHELF_PERCENT';end if;
  select count(*) into v_pending from dual where exists(
   select 1 from RRL_WAREHOUSE_TASK t where t.UID_PALLET=p_uid and t.TASK_TYPE='PUTAWAY' and t.FROM_CELL=p_cell and t.STATUS not in('DONE','CANCELLED'))
   or exists(select 1 from RRL_SAP_PALLET_RECEIPT rec join RRL_SAP_SUPPLY_ORDER so on so.ORDER_ID=rec.ORDER_ID
    where rec.UID_PALLET=p_uid and so.RECEIVE_CELL=p_cell);
  if v_mode='DIRECT'and v_pending>0 and p_purpose in('PICK','ALLOCATE')then
   select count(*)into v_count from RRL_WAREHOUSE_TASK where UID_PALLET=p_uid and FROM_CELL=p_cell and TASK_TYPE='PUTAWAY'and STATUS='IN_PROGRESS';
   if v_count>0 then return 'SOURCE_PUTAWAY_IN_PROGRESS';end if;
  end if;
  if v_pending>0 and not(v_mode='DIRECT' and p_purpose in('PICK','ALLOCATE')) then return 'SOURCE_PUTAWAY_REQUIRED';end if;
  if v_system!=0 and not(v_pending>0 and v_mode='DIRECT' and p_purpose in('PICK','ALLOCATE')) then return 'SOURCE_SYSTEM_LOCATION';end if;
  if p_purpose='PICK' and v_pending=0 then
   select count(*) into v_count from RRL_PICK_FACE pf join RRL_PICK_FACE_ARTICUL a on a.PICK_FACE_ID=pf.PICK_FACE_ID
    where pf.WARE_ID=p_warehouse and pf.CELL_CODE=p_cell and pf.ACTIVE=1 and a.ARTICUL=v_article and a.ACTIVE=1
     and a.CASE_PICK_ENABLED=1 and (a.VALID_FROM is null or a.VALID_FROM<=sysdate) and (a.VALID_TO is null or a.VALID_TO>=sysdate);
   if v_count=0 and p_owner_reservation is not null then
    select count(*) into v_count from RRL_PICK_FACE_ASSIGNMENT a
     join RRL_PICK_FACE pf on pf.PICK_FACE_ID=a.PICK_FACE_ID
     join RRL_PICK_WAVE w on w.PICK_WAVE_ID=a.PICK_WAVE_ID
     join RRL_STOCK_RESERVATION sr on sr.RESERVATION_ID=p_owner_reservation
     where a.CELL_CODE=p_cell and a.ARTICUL=v_article and a.STATUS='ACTIVE'
      and a.BASE_UOM=v_uom and pf.ACTIVE=1 and pf.WARE_ID=p_warehouse
      and w.STATUS='LAUNCHED' and sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=a.PICK_WAVE_ID;
   end if;
   if v_count=0 then return 'SOURCE_PICK_FACE_UNPUBLISHED';end if;
  end if;
  if p_owner_reservation is not null then
   begin select BASE_QTY into v_owned from RRL_STOCK_RESERVATION where RESERVATION_ID=p_owner_reservation
    and UID_PALLET=p_uid and CELL=p_cell and ARTICUL=v_article and BASE_UOM=v_uom
    and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING');
   exception when no_data_found then return 'SOURCE_RESERVATION_CONFLICT';end;
   if v_owned is null or v_owned<=0 or v_owned>v_h then return 'SOURCE_RESERVATION_CONFLICT';end if;
  end if;
  begin RRL_STOCK_UNIT_CORE.assert_composition(p_uid,p_cell);
  exception when others then
   if sqlcode in(-20884,-20868) then return 'SOURCE_COMPOSITION_CONFLICT';else raise;end if;
  end;
  if v_p<=0 or v_p-v_h+v_owned<p_quantity or (p_quantity=0 and v_p-v_h+v_owned<=0) then return 'SOURCE_FREE_INSUFFICIENT';end if;
  return null;
 end;
 procedure assert_source(p_uid varchar2,p_cell varchar2,p_warehouse number,p_quantity number,
  p_min_days number default null,p_min_percent number default null,p_purpose varchar2 default 'ALLOCATE',
  p_owner_reservation number default null,p_article varchar2 default null) is v_reason varchar2(100);
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CELL',p_cell),4);
  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',p_uid));
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
  v_reason:=reason(p_uid,p_cell,p_warehouse,p_quantity,p_min_days,p_min_percent,p_purpose,p_owner_reservation,p_article);
  if v_reason is not null then raise_application_error(-20886,'SOURCE_INELIGIBLE: '||v_reason);end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_EVENT_BRIDGE as
 procedure after_event(p_operation varchar2,p_line number,p_leg number,p_uid varchar2,p_from varchar2,p_to varchar2,
  p_qty number,p_uom varchar2,p_uom_version number,p_type number) is
  setting varchar2(20);req clob;d json_object_t;a json_array_t;l json_object_t;found boolean:=false;
  base varchar2(20);num number;den number;scale number;ver number;qty number;
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','MODE')='EXPLICIT' then return;end if;
  select nvl(max(SETTING_VALUE),'0') into setting from RRL_SYSTEM_SETTINGS where SETTING_KEY='STOCK_LEGACY_TRIGGER_ENABLED';
  if setting!='1' then raise_application_error(-20863,'LEGACY_STOCK_POSTING_DISABLED');end if;
  if sys_context('RRL_STOCK_WRITE_CTX','MODE') is null or sys_context('RRL_STOCK_WRITE_CTX','MODE')!='COMPAT'
   or p_operation is null or p_operation!=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID') is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false) then
   raise_application_error(-20863,'LEGACY_PLAN_REQUIRED');end if;
  select CANONICAL_REQUEST into req from RRL_STOCK_OPERATION where OPERATION_ID=p_operation and COMMAND_TYPE='COMPAT_MANUAL_MOVE' and STATE='IN_FLIGHT';
  d:=json_object_t.parse(req);a:=d.get_array('lines');
  for i in 0..a.get_size-1 loop
   l:=treat(a.get(i) as json_object_t);
   if l.get_number('line_number')=p_line then
    if found then raise_application_error(-20870,'LEGACY_MANIFEST_LINE_REPEATED');end if;found:=true;
    declare
 v_json_sql_1_1 varchar2(32767):=l.get_string('article');
 v_json_sql_1_2 varchar2(32767):=l.get_string('unit');
begin
select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_json_sql_1_1 and INPUT_UOM=v_json_sql_1_2;
end;
    declare
 v_json_sql_2_1 varchar2(32767):=l.get_string('article');
 v_json_sql_2_2 varchar2(32767):=l.get_string('unit');
begin
select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into base,num,den,scale from RRL_STOCK_UOM_CONVERSION
     where ARTICUL=v_json_sql_2_1 and INPUT_UOM=v_json_sql_2_2 and POLICY_VERSION=ver;
end;
    qty:=RRL_STOCK_MATH.convert_exact(l.get_string('quantity'),num,den,scale);
    declare
 v_json_sql_3_1 varchar2(32767):=l.get_string('article');
begin
select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_json_sql_3_1 and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;
end;
    if p_leg!=1 or p_type!=2 or p_from is null or p_to is null or p_from!=l.get_string('source_cell') or p_to!=l.get_string('target_cell')
     or p_uid!=l.get_string('uid') or p_qty!=qty or p_uom!=base or p_uom_version!=ver then raise_application_error(-20870,'LEGACY_MANIFEST_EVENT_CONFLICT');end if;
   end if;
  end loop;
  if not found then raise_application_error(-20870,'LEGACY_MANIFEST_LINE_REQUIRED');end if;
  RRL_STOCK_BALANCE_CORE.apply_delta(p_uid,p_from,-p_qty,0,p_uom,p_uom_version);
  RRL_STOCK_BALANCE_CORE.apply_delta(p_uid,p_to,p_qty,0,p_uom,p_uom_version);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_FULFILLMENT_FACT as
 procedure project_ship(p_shipment number,p_identifier varchar2,p_order number,p_operation varchar2,p_facts clob,p_actor varchar2) is
  a json_array_t:=json_array_t();x json_object_t;v_total number:=0;v_unit varchar2(20);v_mixed number:=0;v_count number:=0;v_comp clob;
 begin
  for f in(select ARTICLE,BASE_UOM,sum(QTY) QTY from json_table(p_facts,'$[*]' columns(
   ARTICLE varchar2(160) path '$.article' error on error,
   BASE_UOM varchar2(20) path '$.base_uom' error on error,
   QTY number path '$.quantity' error on error)) group by ARTICLE,BASE_UOM order by ARTICLE,BASE_UOM) loop
   if f.ARTICLE is null or f.BASE_UOM is null or f.QTY<=0 then raise_application_error(-20887,'SHIPPED_FACT_COMPOSITION_INVALID');end if;
   if a.get_size>=200 then raise_application_error(-20881,'SHIPPED_FACT_COMPOSITION_BOUND');end if;
   x:=json_object_t();x.put('article',f.ARTICLE);x.put('base_uom',f.BASE_UOM);
   x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(f.QTY));a.append(x);
   if v_unit is null then v_unit:=f.BASE_UOM;elsif v_unit!=f.BASE_UOM then v_mixed:=1;end if;
   v_total:=v_total+f.QTY;
  end loop;
  if a.get_size=0 then raise_application_error(-20887,'SHIPPED_FACT_COMPOSITION_EMPTY');end if;
  v_comp:=a.to_clob;
  for ff in(select FULFILLMENT_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=p_shipment
   and PALLET_UID=p_identifier and CUSTOMER_ORDER_ID=p_order order by FULFILLMENT_ID for update) loop
   v_count:=v_count+1;if v_count>1 then raise_application_error(-20887,'SHIPMENT_FULFILLMENT_AMBIGUOUS');end if;
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(ff.FULFILLMENT_ID)));
   update RRL_CUSTOMER_ORDER_FULFILLMENT set STATUS='SHIPPED',
    FACT_QTY=case when v_mixed=0 then v_total else null end,FACT_UOM=case when v_mixed=0 then v_unit else null end,
    FACT_COMPOSITION_JSON=v_comp,SHIPPED_OPERATION_ID=p_operation,SHIPPED_AT=systimestamp,
    UPDATED_AT=sysdate,UPDATED_BY=p_actor where FULFILLMENT_ID=ff.FULFILLMENT_ID;
  end loop;
  if v_count!=1 then raise_application_error(-20887,'SHIPMENT_FULFILLMENT_MISSING');end if;
 end;
 procedure project_unload(p_shipment number,p_load varchar2,p_case number,p_actor varchar2)is n number:=0;version_no number;
 begin
  select CONTENT_VERSION into version_no from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_case;
  for ff in(select FULFILLMENT_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=p_shipment and PICKED_CASE_TASK_ID=p_case and STATUS='SHIPPED'and SHIPPED_OPERATION_ID=p_load order by FULFILLMENT_ID for update)loop
   n:=n+1;
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(ff.FULFILLMENT_ID)));
   update RRL_CUSTOMER_ORDER_FULFILLMENT set STATUS='PICKED',SHIPPED_OPERATION_ID=null,SHIPPED_AT=null,PICKED_CONTENT_VERSION=version_no,UPDATED_AT=sysdate,UPDATED_BY=p_actor where FULFILLMENT_ID=ff.FULFILLMENT_ID;
  end loop;
  if n!=1 then raise_application_error(-20886,'UNLOAD_ORIGINAL_FULFILLMENT_REQUIRED');end if;
 end;
 procedure project_unload_pallet(p_shipment number,p_load varchar2,p_uid varchar2,p_actor varchar2)is n number:=0;version_no number;
 begin
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
  select STOCK_VERSION into version_no from RRL_REMAINS where UID_POLETA=p_uid and REMAIN>0 and HARD_RESERVED_BASE=REMAIN;
  for ff in(select FULFILLMENT_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=p_shipment and PICKED_CASE_TASK_ID is null and PICKED_PALLET_UID=p_uid and PICKED_WAREHOUSE_TASK_ID is not null and STATUS='SHIPPED'and SHIPPED_OPERATION_ID=p_load order by FULFILLMENT_ID for update)loop
   n:=n+1;RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(ff.FULFILLMENT_ID)));
   update RRL_CUSTOMER_ORDER_FULFILLMENT set STATUS='PICKED',SHIPPED_OPERATION_ID=null,SHIPPED_AT=null,PICKED_STOCK_VERSION=version_no,UPDATED_AT=sysdate,UPDATED_BY=p_actor where FULFILLMENT_ID=ff.FULFILLMENT_ID;
  end loop;
  if n!=1 then raise_application_error(-20886,'UNLOAD_ORIGINAL_FULLPAL_FULFILLMENT_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_FULLPAL_BIND_CMD as
 function snapshot(p_task number,p_st varchar2,p_scan varchar2,p_expected number) return clob is
  t RRL_WAREHOUSE_TASK%rowtype;pt RRL_PICK_TASK%rowtype;m RRL_WAREHOUSE_TASK_STOCK_MOVE%rowtype;
  sr RRL_REMAINS%rowtype;st RRL_SBORKA_PALLETS%rowtype;ff RRL_CUSTOMER_ORDER_FULFILLMENT%rowtype;
  j json_object_t:=json_object_t();a json_array_t:=json_array_t();x json_object_t;qty number:=0;n number;
  v_pick number;v_article varchar2(160);v_ware number;v_block number;v_order number;v_hard number;
  v_policy number;v_base varchar2(20);v_num number;v_den number;v_scale number;v_rows number:=0;v_released number;
 begin
  if p_expected is null or p_expected<0 then raise_application_error(-20881,'EXPECTED_PHYSICAL_STOCK_VERSION_REQUIRED');end if;
  select * into t from RRL_WAREHOUSE_TASK where TASK_ID=p_task;
  if t.TASK_SOURCE!='WAVE' or t.TASK_TYPE!='PICKING_MOVE' or t.STATUS!='DONE' then raise_application_error(-20886,'FULLPAL_CONFIRMED_MOVE_REQUIRED');end if;
  select PICK_TASK_ID into v_pick from RRL_PICK_WAVE_TASK where PICK_WAVE_TASK_ID=t.SOURCE_TASK_ID and PICK_WAVE_ID=t.SOURCE_DOC_ID;
  select * into pt from RRL_PICK_TASK where PICK_TASK_ID=v_pick;
  if pt.TASK_TYPE!='FULL_PALLET' or pt.STATUS!='DONE' then raise_application_error(-20886,'FULLPAL_PICK_TASK_NOT_DONE');end if;
  select count(*) into v_released from RRL_PICK_WAVE where PICK_WAVE_ID=t.SOURCE_DOC_ID and PICK_RELEASED_AT is not null and STATUS in('LAUNCHED','DONE');
  if v_released!=1 then raise_application_error(-20886,'WAVE_PICK_RELEASE_REQUIRED');end if;
  select * into m from RRL_WAREHOUSE_TASK_STOCK_MOVE where TASK_ID=p_task;
  select count(*) into n from RRL_STOCK_OPERATION where OPERATION_ID=m.OPERATION_ID and STATE='APPLIED' and COMMAND_TYPE='TASK_COMPLETE';
  if n!=1 or m.TARGET_UID_PALLET is null or p_scan is null or p_scan!=m.TARGET_UID_PALLET then raise_application_error(-20886,'SCAN_CONFIRMED_PHYSICAL_PALLET');end if;
  select * into sr from RRL_REMAINS where UID_POLETA=m.TARGET_UID_PALLET and CELL=m.TO_CELL;
  if sr.STOCK_VERSION!=p_expected or sr.REMAIN!=m.BASE_QTY or sr.REMAIN<=0 or sr.BASE_UOM!=m.BASE_UOM then raise_application_error(-20886,'FULLPAL_PHYSICAL_VERSION_OR_COMPOSITION_CHANGED');end if;
  select p.ARTICUL,c.WARE_ID,greatest(nvl(c.BLOCKED_FOR_REMAINS,0),nvl(c.BLOCKED_FOR_POPOLNENIE,0)) into v_article,v_ware,v_block
   from RRL_PALLETS p join RRL_CELLS c on c.CELL=sr.CELL where p.UID_PALLET=sr.UID_POLETA;
  if v_block!=0 or v_article!=pt.ARTICUL then raise_application_error(-20886,'FULLPAL_LOCATION_OR_ARTICLE_CONFLICT');end if;
  select * into st from RRL_SBORKA_PALLETS where PALLET_UID=p_st;
  if st.WARE_ID is null or st.WARE_ID!=v_ware or nvl(st.CONDITION,0)>=2 or st.RETURN_SUPPLIER_ID is not null then raise_application_error(-20886,'FULLPAL_ST_STATE_OR_WAREHOUSE_CONFLICT');end if;
  select * into ff from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=st.ID and PALLET_UID=p_st and CUSTOMER_ORDER_ID=pt.CUSTOMER_ORDER_ID;
  if ff.STATUS not in('PLANNED','PICKED') or ff.STATUS is null or ff.PICKED_CASE_TASK_ID is not null then raise_application_error(-20886,'FULLPAL_FULFILLMENT_STATE_CONFLICT');end if;
  if ff.PICKED_PALLET_UID is not null and (ff.PICKED_PALLET_UID!=p_scan or ff.PICKED_WAREHOUSE_TASK_ID!=p_task or ff.PICKED_STOCK_VERSION!=p_expected) then raise_application_error(-20886,'FULLPAL_ST_ALREADY_BOUND');end if;
  select count(*) into n from RRL_CUSTOMER_ORDER_FULFILLMENT where PICKED_PALLET_UID=p_scan and FULFILLMENT_ID!=ff.FULFILLMENT_ID and STATUS in('PICKED','SHIPPED');
  if n>0 then raise_application_error(-20886,'FULLPAL_PHYSICAL_PALLET_ALREADY_BOUND');end if;
  select nvl(sum(BASE_QTY),0) into v_hard from RRL_STOCK_RESERVATION where UID_PALLET=p_scan and CELL=sr.CELL
   and CUSTOMER_ORDER_ID=pt.CUSTOMER_ORDER_ID and SOURCE_LINE_ID=v_pick and SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=t.SOURCE_DOC_ID
   and RESERVATION_KIND='HARD' and RESERVATION_DOMAIN='PICKING' and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_UOM=sr.BASE_UOM;
  if v_hard!=sr.REMAIN or v_hard!=sr.HARD_RESERVED_BASE then raise_application_error(-20886,'FULLPAL_WHOLE_OWNED_RESERVATION_REQUIRED');end if;
  for r in(select * from RRL_SBORKA_PALLET_ROWS where PALLET_UID=p_st order by ID fetch first 201 rows only) loop
   v_rows:=v_rows+1;if v_rows>200 then raise_application_error(-20881,'FULLPAL_ST_ROW_BOUND');end if;
   if r.ARTICUL!=v_article or r.QUANTITY<=0 or r.EI is null then raise_application_error(-20886,'FULLPAL_ST_COMPOSITION_MISMATCH');end if;
   select max(POLICY_VERSION) into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=r.ARTICUL and INPUT_UOM=r.EI;
   select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into v_base,v_num,v_den,v_scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=r.ARTICUL and INPUT_UOM=r.EI and POLICY_VERSION=v_policy;
   if v_base!=sr.BASE_UOM then raise_application_error(-20886,'FULLPAL_ST_BASE_UOM_MISMATCH');end if;
   qty:=qty+RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(r.QUANTITY),v_num,v_den,v_scale);
   x:=json_object_t();x.put('row_id',r.ID);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(r.QUANTITY));x.put('input_uom',r.EI);x.put('policy_version',v_policy);a.append(x);
  end loop;
  if v_rows=0 or qty!=sr.REMAIN then raise_application_error(-20886,'FULLPAL_ST_COMPOSITION_MISMATCH');end if;
  j.put('task_id',p_task);j.put('wave_id',t.SOURCE_DOC_ID);j.put('pick_task_id',v_pick);j.put('source_operation_id',m.OPERATION_ID);
  j.put('shipment_id',st.ID);j.put('shipment_identifier',p_st);j.put('fulfillment_id',ff.FULFILLMENT_ID);j.put('fulfillment_status',ff.STATUS);
  j.put('physical_uid',p_scan);j.put('cell',sr.CELL);j.put('stock_version',sr.STOCK_VERSION);
  j.put('article',v_article);j.put('base_uom',sr.BASE_UOM);j.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(sr.REMAIN));j.put('rows',a);
  return j.to_clob;
 exception when no_data_found then raise_application_error(-20887,'FULLPAL_BIND_IDENTITY_MISSING');
  when too_many_rows then raise_application_error(-20887,'FULLPAL_BIND_IDENTITY_AMBIGUOUS');
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;
  s clob;a json_array_t;x json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
  s:=snapshot(d.get_object('source').get_number('task_id'),m.get_string('shipment_identifier'),m.get_string('scanned_pallet'),m.get_number('expected_stock_version'));
  v:=json_object_t.parse(s);
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('wave_id')));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('task_id')));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('pick_task_id')));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('shipment_id')));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('fulfillment_id')));
  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('physical_uid'),v.get_string('article'),v.get_string('cell'),null);
  a:=v.get_array('rows');for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLET_ROWS',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('row_id')));
  end loop;
  v.put('snapshot_signature',rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256)));
  p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;j json_object_t;
  plan clob;s clob;op varchar2(100);fid number;tid number;stockver number;srcop varchar2(100);puid varchar2(150);base varchar2(20);
  quantity number;comp clob;a json_array_t:=json_array_t();x json_object_t:=json_object_t();
 begin
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'FULLPAL_BIND_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v:=json_object_t.parse(plan).get_object('domain');tid:=v.get_number('task_id');
  s:=snapshot(tid,m.get_string('shipment_identifier'),m.get_string('scanned_pallet'),m.get_number('expected_stock_version'));
  if rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256))!=v.get_string('snapshot_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: whole pallet shipment binding');end if;
  fid:=v.get_number('fulfillment_id');stockver:=v.get_number('stock_version');srcop:=v.get_string('source_operation_id');puid:=v.get_string('physical_uid');
  quantity:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));base:=v.get_string('base_uom');
  x.put('article',v.get_string('article'));x.put('base_uom',base);x.put('quantity',v.get_string('quantity'));a.append(x);comp:=a.to_clob;
  update RRL_CUSTOMER_ORDER_FULFILLMENT set STATUS='PICKED',FACT_QTY=quantity,FACT_UOM=base,FACT_COMPOSITION_JSON=comp,
   PICKED_WAREHOUSE_TASK_ID=tid,PICKED_OPERATION_ID=srcop,PICKED_PALLET_UID=puid,PICKED_STOCK_VERSION=stockver,
   PICKED_AT=systimestamp,PICKED_BY=p_actor,UPDATED_AT=sysdate,UPDATED_BY=p_actor where FULFILLMENT_ID=fid;
  j:=json_object_t();j.put('operation_id',op);j.put('fulfillment_id',fid);j.put('shipment_identifier',v.get_string('shipment_identifier'));
  j.put('pallet_identifier',puid);j.put('status','PICKED');j.put('quantity',v.get_string('quantity'));j.put('base_uom',base);
  j.put('physical_composition',a);j.put('warehouse_task_id',tid);j.put('physical_operation_id',srcop);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_CMD as
 function digest(p_value clob) return varchar2 is begin return rawtohex(sys.dbms_crypto.hash(p_value,sys.dbms_crypto.hash_sh256));end;
 procedure add_tree(f in out nocopy json_array_t,r in out nocopy json_array_t,s clob) is
  j json_object_t:=json_object_t.parse(s);a json_array_t;x json_object_t;v_st number;v_case_id number;
 begin
  a:=j.get_array('nodes');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',x.get_string('uid'));
   if x.get_string('kind')='CASE' then
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('case_task_id')));
    v_case_id:=x.get_number('case_task_id');select LEGACY_SBORKA_PALLET_ID into v_st from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case_id;
    if v_st is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(v_st));end if;
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('wave_id')));
   else RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',x.get_string('uid'));end if;
   if x.get_number('open_task_count')>0 then raise_application_error(-20886,'HU_PHYSICAL_TASK_OPEN');end if;
   if x.get_string('kind')='STOCK' then
    RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),x.get_string('article'),x.get_string('cell'),null);
   else RRL_STOCK_PLAN_HELPER.fence(f,'CELL',x.get_string('cell'));end if;
  end loop;
  a:=j.get_array('links');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   if x.get_number('id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));end if;
  end loop;
  a:=j.get_array('ancestors');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   if x.get_number('open_task_count')>0 then raise_application_error(-20886,'HU_ANCESTOR_PHYSICAL_TASK_OPEN');end if;
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',x.get_string('uid'));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',x.get_string('uid'));
  end loop;
 end;
 procedure declare_tree(f in out nocopy json_array_t,r in out nocopy json_array_t,s clob) is begin add_tree(f,r,s);end;
 procedure assert_scan(p_uid varchar2,p_scan varchar2) is v_alias varchar2(32);
 begin
  select SSCC into v_alias from RRL_PALLETS where UID_PALLET=p_uid;
  if p_scan is null or (p_scan!=p_uid and (v_alias is null or p_scan!=v_alias)) then raise_application_error(-20886,'HU_PHYSICAL_SCAN_REQUIRED');end if;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob,p_allow_slotted boolean default false,p_defer_wait_planning boolean default false) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t:=json_object_t();
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();s clob;t clob;ps json_object_t;cs json_object_t;a json_array_t;x json_object_t;
  v_uid varchar2(200):=d.get_object('source').get_string('uid');v_child varchar2(200):=m.get_string('child_uid');
  v_kind varchar2(80):=d.get_string('command_type');v_link number;v_count number;v_cell varchar2(60);v_ware number;v_sscc varchar2(32);v_sum number:=0;v_target varchar2(60);v_target_ware number;v_system number;v_otbor number;v_weight number;v_height number;v_ignore_task number;v_case number:=m.get_number('child_case_task_id');v_slot number;v_slot_json clob;v_claim number;v_wait_shared boolean:=false;
 begin
  if v_kind='HU_TASK_COMPLETE' then v_kind:='HU_MOVE';v_ignore_task:=m.get_number('physical_task_id');end if;
  if v_uid is null or length(v_uid)>200 or trim(v_uid)!=v_uid then raise_application_error(-20886,'HU_IDENTIFIER_REQUIRED');end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||digest(to_clob(p_operation)));
  RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v_uid);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',v_uid);
  if v_kind='HU_CREATE' then
   select count(*) into v_count from RRL_PALLETS where UID_PALLET=v_uid;
   if v_count>0 then raise_application_error(-20886,'HU_IDENTIFIER_ALREADY_EXISTS');end if;
   v_cell:=m.get_string('cell');v_sscc:=m.get_string('sscc');
   select WARE_ID into v_ware from RRL_CELLS where CELL=v_cell;
   if v_ware is null or v_ware<1 or m.get_number('warehouse') is null or m.get_number('warehouse')!=v_ware
    or m.get_string('container_type') is null or m.get_string('container_type') not in('PALLET','BOX','ROLL_CAGE','BAG')
    or m.get_number('tare_weight_kg') is null or m.get_number('tare_weight_kg')<0 then raise_application_error(-20886,'HU_CREATE_LOCATION_TYPE_OR_TARE_INVALID');end if;
   if v_sscc is not null then
    if not regexp_like(v_sscc,'^[0-9]{18}$') then raise_application_error(-20886,'HU_SSCC_GS1_REQUIRED');end if;
    for i in 1..17 loop v_sum:=v_sum+to_number(substr(v_sscc,i,1))*case when mod(i,2)=1 then 3 else 1 end;end loop;
    if mod(10-mod(v_sum,10),10)!=to_number(substr(v_sscc,18,1)) then raise_application_error(-20886,'HU_SSCC_CHECK_DIGIT_INVALID');end if;
    select count(*) into v_count from RRL_PALLETS where SSCC=v_sscc;
    if v_count>0 then raise_application_error(-20886,'HU_SSCC_ALREADY_BOUND');end if;
    RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','HU.SSCC:'||v_sscc);
   end if;
   RRL_STOCK_PLAN_HELPER.fence(f,'CELL',v_cell);v.put('cell',v_cell);v.put('warehouse',v_ware);
  elsif v_kind='HU_MOVE' then
   s:=RRL_STOCK_HU_READ.snapshot_json(v_uid,v_ignore_task);ps:=json_object_t.parse(s);
   if ps.get_array('ancestors').get_size>0 then raise_application_error(-20886,'HU_TOP_LEVEL_MOVE_REQUIRED');end if;
   if treat(ps.get_array('nodes').get(0) as json_object_t).get_string('kind')!='CONTAINER' then raise_application_error(-20886,'HU_CONTAINER_WITH_STOCK_REQUIRED');end if;
   if m.get_number('expected_version') is null or m.get_number('expected_version')!=treat(ps.get_array('nodes').get(0) as json_object_t).get_number('version') then raise_application_error(-20867,'HU_CONTENT_VERSION_CONFLICT');end if;
   v_target:=m.get_string('target_cell');
   if v_target is null or v_target=ps.get_string('cell') then raise_application_error(-20886,'HU_MOVE_TARGET_REQUIRED');end if;
   select WARE_ID,nvl(IS_SYSTEM,0),nvl(OTBOR,0),nvl(LIMIT_WEIGHT,0),nvl(LIMIT_HEIGHT,0)
    into v_target_ware,v_system,v_otbor,v_weight,v_height from RRL_CELLS where CELL=v_target;
   v_slot_json:=RRL_STOCK_HU_SLOT.target_json(s,m.to_clob,v_ignore_task);
   v.put('placement',json_object_t.parse(v_slot_json));v_slot:=m.get_number('target_slot_id');
   if v_slot is not null then RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(v_slot));end if;
   for claim in(select TASK_ID,CELL_SLOT_ID from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=v_uid and STATUS='OCCUPIED') loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(claim.TASK_ID));
    RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(claim.CELL_SLOT_ID));
   end loop;
   if v_ignore_task is not null and v_slot is not null then
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(v_ignore_task));
   end if;
   if p_defer_wait_planning or v_ignore_task is not null then v_wait_shared:=RRL_ST_DEFER_HU_WAIT.shared_wait_target(p_request,v_ignore_task,v_target,v_target_ware);end if;
   select count(*) into v_count from RRL_REMAINS where CELL=v_target and (REMAIN>0 or HARD_RESERVED_BASE>0);
   if v_count>0 and v_slot is null and not v_wait_shared then raise_application_error(-20886,'HU_MOVE_EMPTY_TARGET_REQUIRED');end if;
   select count(*) into v_count from RRL_PALLETS where case when HU_KIND='CONTAINER' then HU_CURRENT_CELL end=v_target;
   if v_count>0 and v_slot is null and not v_wait_shared then raise_application_error(-20886,'HU_MOVE_TARGET_HAS_CONTAINER');end if;
   select count(*) into v_count from RRL_WAREHOUSE_TASK where TO_CELL=v_target and STATUS not in('DONE','CANCELLED') and (v_ignore_task is null or TASK_ID!=v_ignore_task);
   if v_count>0 and v_slot is null and not v_wait_shared then raise_application_error(-20886,'HU_MOVE_TARGET_HAS_OPEN_ARRIVAL');end if;
   add_tree(f,r,s);RRL_STOCK_PLAN_HELPER.fence(f,'CELL',v_target,6);
   RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT','CELL:'||v_target);
   a:=ps.get_array('nodes');
   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);
    if x.get_string('kind')='STOCK' then RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),x.get_string('article'),x.get_string('cell'),v_target);end if;
   end loop;
   v.put('ignored_task_id',v_ignore_task);v.put('parent_snapshot',ps);v.put('parent_signature',digest(s));v.put('target',v_target);v.put('warehouse',v_target_ware);
  elsif v_kind in('HU_ATTACH','HU_DETACH') then
   if (v_child is null and v_case is null) or(v_child is not null and v_case is not null) or v_child=v_uid then raise_application_error(-20886,'HU_CHILD_IDENTITY_REQUIRED');end if;
   s:=RRL_STOCK_HU_READ.snapshot_json(v_uid);if v_case is null then t:=RRL_STOCK_HU_READ.snapshot_json(v_child);else t:=RRL_STOCK_HU_READ.case_snapshot_json(v_case);end if;
   ps:=json_object_t.parse(s);cs:=json_object_t.parse(t);
   if treat(ps.get_array('nodes').get(0) as json_object_t).get_string('kind')!='CONTAINER' then raise_application_error(-20886,'HU_PARENT_CONTAINER_REQUIRED');end if;
   if ps.get_string('cell')!=cs.get_string('cell') or ps.get_number('warehouse')!=cs.get_number('warehouse') then raise_application_error(-20886,'HU_PACK_SAME_LOCATION_REQUIRED');end if;
   if m.get_number('expected_version') is null or m.get_number('expected_version')!=treat(ps.get_array('nodes').get(0) as json_object_t).get_number('version')
    or m.get_number('expected_child_version') is null or m.get_number('expected_child_version')!=treat(cs.get_array('nodes').get(0) as json_object_t).get_number('version') then raise_application_error(-20867,'HU_CONTENT_VERSION_CONFLICT');end if;
   v_cell:=ps.get_string('cell');
   select count(*) into v_count from RRL_RECEIPT_SLOT_CLAIM where CELL=v_cell and STATUS in('RESERVED','OCCUPIED');
   if v_count>0 and not p_allow_slotted then raise_application_error(-20886,'HU_PACK_UNPACK_REQUIRES_UNSLOTTED_WORK_AREA');end if;
   a:=cs.get_array('nodes');
   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);
    if x.get_string('kind')!='CASE' and x.get_string('uid')=v_uid then raise_application_error(-20886,'HU_CYCLE_FORBIDDEN');end if;
   end loop;
   if v_kind='HU_ATTACH' then
    if cs.get_array('ancestors').get_size>0 then raise_application_error(-20886,'HU_CHILD_ALREADY_HAS_PARENT');end if;
    if ps.get_array('nodes').get_size+cs.get_array('nodes').get_size>200 then raise_application_error(-20881,'HU_ATTACH_NODE_BOUND_200');end if;
    select RRL_WMS_HU_LINK_SQ.nextval into v_link from dual;
   else
    if m.get_string('reason') is null then raise_application_error(-20886,'HU_UNPACK_REASON_REQUIRED');end if;
    begin select HU_LINK_ID into v_link from RRL_WMS_HU_LINK where PARENT_UID=v_uid and (CHILD_PALLET_UID=v_child or CHILD_CASE_TASK_ID=v_case) and ACTIVE_FLAG=1;
    exception when no_data_found then raise_application_error(-20886,'HU_CHILD_NOT_IN_PARENT');end;
   end if;
   if v_kind='HU_ATTACH'and m.get_string('retained_tare_booking_operation_id')is not null then
    if v_case is null then raise_application_error(-20886,'NESTED_TARE_DIRECT_CASE_REQUIRED');end if;
    declare book RRL_TARE_BOOK%rowtype;book_id varchar2(100):=m.get_string('retained_tare_booking_operation_id');begin
     select *into book from RRL_TARE_BOOK where OPERATION_ID=book_id and STATUS='HELD';
     if book.PLACE_KIND!='CASE'or book.PLACE_ID!=RRL_STOCK_PLAN_HELPER.decimal_text(v_case)or book.OWNER_WARE_ID!=ps.get_number('warehouse')then raise_application_error(-20886,'NESTED_TARE_ORIGINAL_CASE_BOOK_REQUIRED');end if;
     RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BOOK',book.OPERATION_ID);
     RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BALANCE',rawtohex(book.BALANCE_KEY));
     v.put('retained_tare_booking_operation_id',book.OPERATION_ID);
    exception when no_data_found then raise_application_error(-20886,'NESTED_TARE_ACTIVE_BOOK_REQUIRED');end;
   end if;
   add_tree(f,r,s);add_tree(f,r,t);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(v_link));
   v.put('parent_snapshot',ps);v.put('child_snapshot',cs);v.put('parent_signature',digest(s));v.put('child_signature',digest(t));v.put('link_id',v_link);
  else raise_application_error(-20888,'HU_COMMAND_SLICE_NOT_INSTALLED');end if;
  v.put('uid',v_uid);v.put('child',v_child);v.put('child_case_task_id',v_case);v.put('kind',v_kind);
  if v.has('parent_snapshot')then RRL_STOCK_CASE_BIND_MOVE.plan_tree(v.get_object('parent_snapshot').get_array('nodes'),r,v);end if;
  if v.has('child_snapshot')then RRL_STOCK_CASE_BIND_MOVE.plan_tree(v.get_object('child_snapshot').get_array('nodes'),r,v);end if;
  p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure bump(p_uid varchar2) is begin update RRL_PALLETS set HU_CONTENT_VERSION=HU_CONTENT_VERSION+1 where UID_PALLET=p_uid;end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;j json_object_t:=json_object_t();a json_array_t;x json_object_t;
  v_op varchar2(100):=d.get_string('operation_id');plan clob;s clob;t clob;v_uid varchar2(200);v_child varchar2(200);v_kind varchar2(80);v_link number;
  v_cell varchar2(60);v_ware number;v_sscc varchar2(32);v_type varchar2(20);v_tare number;v_count number;v_target varchar2(60);v_base varchar2(20);v_policy number;v_qty number;v_from varchar2(60);v_leaf_uid varchar2(200);v_article varchar2(160);v_ignore_task number;v_case number;v_slot number;v_slot_json clob;v_claim number;v_mode varchar2(20);v_case_sscc varchar2(64);v_parent_nodes clob;v_child_nodes clob;old_case RRL_CASE_PICK_TASK%rowtype;v_wait_shared boolean:=false;
 begin
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'HU_EXECUTION_FORBIDDEN');end if;
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=v_op;
  v:=json_object_t.parse(plan).get_object('domain');v_uid:=v.get_string('uid');v_child:=v.get_string('child');v_kind:=v.get_string('kind');v_case:=v.get_number('child_case_task_id');
  if v.has('parent_snapshot') then v_parent_nodes:=v.get_object('parent_snapshot').get_array('nodes').to_clob;end if;
  if v.has('child_snapshot') then v_child_nodes:=v.get_object('child_snapshot').get_array('nodes').to_clob;end if;
  -- Match shipping/QC actual-row order: planned ST rows before CASE rows.
  for st in(select ID from RRL_SBORKA_PALLETS where ID in(
   select LEGACY_SBORKA_PALLET_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(
    select CASE_ID from json_table(v_parent_nodes,'$[*]' columns(CASE_ID number path '$.case_task_id'))
    union select CASE_ID from json_table(v_child_nodes,'$[*]' columns(CASE_ID number path '$.case_task_id')))) order by ID) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(st.ID)));
   select ID into v_claim from RRL_SBORKA_PALLETS where ID=st.ID for update;
  end loop;
  for locked_case in(select CASE_PICK_TASK_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(
   select CASE_ID from json_table(v_parent_nodes,'$[*]' columns(CASE_ID number path '$.case_task_id'))
   union select CASE_ID from json_table(v_child_nodes,'$[*]' columns(CASE_ID number path '$.case_task_id')))
   order by CASE_PICK_TASK_ID) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(locked_case.CASE_PICK_TASK_ID)));
   select CASE_PICK_TASK_ID into v_claim from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=locked_case.CASE_PICK_TASK_ID for update;
  end loop;
  if v.has('parent_snapshot')then RRL_STOCK_CASE_BIND_MOVE.validate_tree(v.get_object('parent_snapshot').get_array('nodes'),v);end if;
  if v.has('child_snapshot')then RRL_STOCK_CASE_BIND_MOVE.validate_tree(v.get_object('child_snapshot').get_array('nodes'),v);end if;
  if v_kind='HU_CREATE' then
   v_cell:=v.get_string('cell');v_ware:=v.get_number('warehouse');v_sscc:=m.get_string('sscc');v_type:=m.get_string('container_type');v_tare:=m.get_number('tare_weight_kg');
   if m.get_string('scan_container') is null or m.get_string('scan_container')!=v_uid
    or m.get_string('scan_cell') is null or m.get_string('scan_cell')!=v_cell then raise_application_error(-20886,'HU_CREATE_SCAN_REQUIRED');end if;
   select count(*) into v_count from RRL_PALLETS where UID_PALLET=v_uid or (v_sscc is not null and SSCC=v_sscc);
   if v_count>0 then raise_application_error(-20890,'CLOSURE_CHANGED: HU alias identity');end if;
   insert into RRL_PALLETS(UID_PALLET,ARTICUL,UNIT_COUNT,PRIHOD_NAKLAD_ID,CREATION_DATE,HU_KIND,HU_TYPE,HU_CONTENT_VERSION,HU_CURRENT_CELL,HU_TARE_WEIGHT_KG,SSCC,CREATED_BY_STOCK_OP)
    values(v_uid,null,0,0,sysdate,'CONTAINER',v_type,0,v_cell,v_tare,v_sscc,v_op);
  elsif v_kind='HU_MOVE' then
   v_ignore_task:=v.get_number('ignored_task_id');s:=RRL_STOCK_HU_READ.snapshot_json(v_uid,v_ignore_task);
   if digest(s)!=v.get_string('parent_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: HU physical composition');end if;
   assert_scan(v_uid,m.get_string('scan_container'));v_target:=v.get_string('target');v_ware:=v.get_number('warehouse');
   v_from:=v.get_object('parent_snapshot').get_string('cell');
   if m.get_string('scanned_from_cell') is null or m.get_string('scanned_from_cell')!=v_from
    or m.get_string('scanned_to_cell') is null or m.get_string('scanned_to_cell')!=v_target then raise_application_error(-20886,'HU_MOVE_FROM_TO_SCAN_REQUIRED');end if;
   if v_ignore_task is not null then v_wait_shared:=RRL_ST_DEFER_HU_WAIT.shared_wait_target(p_request,v_ignore_task,v_target,v_ware);end if;
   v_slot:=m.get_number('target_slot_id');
   select count(*) into v_count from RRL_REMAINS where CELL=v_target and (REMAIN>0 or HARD_RESERVED_BASE>0);
   if v_count>0 and v_slot is null and not v_wait_shared then raise_application_error(-20890,'CLOSURE_CHANGED: HU target occupied');end if;
   select count(*) into v_count from RRL_PALLETS where case when HU_KIND='CONTAINER' then HU_CURRENT_CELL end=v_target;
   if v_count>0 and v_slot is null and not v_wait_shared then raise_application_error(-20890,'CLOSURE_CHANGED: HU target container');end if;
   v_slot:=m.get_number('target_slot_id');
   v_slot_json:=RRL_STOCK_HU_SLOT.target_json(s,m.to_clob,v_ignore_task);
   if dbms_lob.compare(v_slot_json,v.get_object('placement').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: HU slot policy');end if;
   if v_slot is not null and (m.get_string('scanned_to_slot_code') is null or m.get_string('scanned_to_slot_code')!=v.get_object('placement').get_string('slot_code')) then raise_application_error(-20886,'HU_TARGET_SLOT_SCAN_REQUIRED');end if;
   a:=v.get_object('parent_snapshot').get_array('nodes');
   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);
    v_leaf_uid:=x.get_string('uid');
    if x.get_string('kind')='STOCK' then
     v_article:=x.get_string('article');v_base:=x.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));
     select max(POLICY_VERSION) into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article
      and INPUT_UOM=v_base and BASE_UOM=v_base and NUMERATOR=1 and DENOMINATOR=1;
     if v_policy is null then raise_application_error(-20868,'HU_MOVE_BASE_POLICY_REQUIRED');end if;
     v_mode:=case when x.get_number('case_task_id') is not null and v_from='CPT_'||RRL_STOCK_PLAN_HELPER.decimal_text(v_ware) then 'CASE_EXIT' else 'ORDINARY' end;
     if v.has('group_placement')then
      declare gp json_object_t:=v.get_object('group_placement');wire clob;n number;begin
       wire:=gp.get_array('lines').to_clob;
       select count(*)into n from json_table(wire,'$[*]'columns(U varchar2(200)path '$.uid',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))g
       where g.U=v_leaf_uid and RRL_STOCK_MATH.quantity(g.Q)=v_qty and g.B=v_base;
       if d.get_string('command_type')!='HU_TASK_COMPLETE'or gp.get_string('from_cell')!=v_from or gp.get_string('target_cell')!=v_target or gp.get_number('warehouse_id')!=v_ware or n!=1 then raise_application_error(-20886,'INTERWARE_GROUP_EXACT_PUTAWAY_LEAF_REQUIRED');end if;
       v_mode:='PUTAWAY';
      end;
     end if;
     if v.has('interwarehouse_placement')then
      declare iw json_object_t:=v.get_object('interwarehouse_placement');begin
       if d.get_string('command_type')!='HU_TASK_COMPLETE'or iw.get_string('uid')!=v_leaf_uid or iw.get_string('from_cell')!=v_from or iw.get_string('target_cell')!=v_target or iw.get_number('warehouse_id')!=v_ware or RRL_STOCK_MATH.quantity(iw.get_string('quantity'))!=v_qty then raise_application_error(-20886,'INTERWARE_HU_PUTAWAY_EXACT_RECEIPT_REQUIRED');end if;
       v_mode:='PUTAWAY';
      end;
     end if;
     RRL_STOCK_TRANSFER_CORE.move(v_leaf_uid,v_leaf_uid,v_from,v_target,v_qty,v_base,v_policy,v_ware,p_actor,i+1,p_target_slot=>v_slot,p_location_mode=>v_mode);
     bump(v_leaf_uid);
    elsif x.get_string('kind')='CASE' then
     v_case:=x.get_number('case_task_id');
     select *into old_case from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case;
     update RRL_CASE_PICK_TASK set CURRENT_CELL=v_target,CONTENT_VERSION=CONTENT_VERSION+1,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=v_case;
     RRL_STOCK_CASE_BIND_MOVE.finish_move(old_case,RRL_STOCK_CASE_BIND_MOVE.binding_for(v,v_case),old_case.CONTENT_VERSION+1,p_actor);
     insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,EVENT_TYPE,PAYLOAD_JSON,CREATED_BY)
      values(RRL_CASE_PICK_EVENT_SQ.nextval,v_case,'HU_CARRIER_MOVED',p_request,p_actor);
    else
     update RRL_PALLETS set HU_CURRENT_CELL=v_target,HU_CONTENT_VERSION=HU_CONTENT_VERSION+1 where UID_PALLET=v_leaf_uid;
    end if;
   end loop;
   delete from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=v_uid and STATUS='OCCUPIED';
   if v_slot is not null then
    declare measures json_object_t:=v.get_object('placement').get_object('measurements');version_no number;mass_no number;volume_no number;begin
     mass_no:=RRL_STOCK_MATH.quantity(measures.get_string('gross_weight_kg'));volume_no:=RRL_STOCK_MATH.quantity(measures.get_string('bounding_volume_m3'));
     select HU_CONTENT_VERSION into version_no from RRL_PALLETS where UID_PALLET=v_uid;
     insert into RRL_RECEIPT_SLOT_CLAIM(TASK_ID,UID_PALLET,CELL,CELL_SLOT_ID,STATUS,HU_GROSS_WEIGHT_KG,HU_BOUNDING_VOLUME_M3,HU_COMPOSITION_VERSION)
      values(v_ignore_task,v_uid,v_target,v_slot,'OCCUPIED',mass_no,volume_no,version_no);
    end;
   end if;
  else
   s:=RRL_STOCK_HU_READ.snapshot_json(v_uid);if v_case is null then t:=RRL_STOCK_HU_READ.snapshot_json(v_child);else t:=RRL_STOCK_HU_READ.case_snapshot_json(v_case);end if;
   if digest(s)!=v.get_string('parent_signature') or digest(t)!=v.get_string('child_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: HU composition');end if;
   assert_scan(v_uid,m.get_string('scan_container'));
   if v_case is null then assert_scan(v_child,m.get_string('scan_child'));
   else
    select SSCC into v_case_sscc from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case for update;
    if m.get_string('scan_child') is null or m.get_string('scan_child')!=v_case_sscc then raise_application_error(-20886,'HU_CASE_CARRIER_SCAN_REQUIRED');end if;
   end if;v_link:=v.get_number('link_id');
   if v_kind='HU_ATTACH' then
    RRL_HU_PACK_CLOCK.begin_empty_box(v_uid,v_op,p_actor);
    insert into RRL_WMS_HU_LINK(HU_LINK_ID,PARENT_UID,CHILD_PALLET_UID,CHILD_CASE_TASK_ID,ACTIVE_FLAG,LINK_VERSION,LINKED_OPERATION_ID,LINKED_BY)
     values(v_link,v_uid,v_child,v_case,1,0,v_op,p_actor);
   else
    update RRL_WMS_HU_LINK set ACTIVE_FLAG=0,LINK_VERSION=LINK_VERSION+1,UNLINKED_OPERATION_ID=v_op,UNLINKED_AT=systimestamp,UNLINKED_BY=p_actor
     where HU_LINK_ID=v_link and ACTIVE_FLAG=1 and PARENT_UID=v_uid and(CHILD_PALLET_UID=v_child or CHILD_CASE_TASK_ID=v_case);
    if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: HU child link');end if;
   end if;
   bump(v_uid);
   if v_case is null then bump(v_child);
   else
    select *into old_case from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case;
    update RRL_CASE_PICK_TASK set CONTENT_VERSION=CONTENT_VERSION+1,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=v_case;
    RRL_STOCK_CASE_BIND_MOVE.finish_move(old_case,RRL_STOCK_CASE_BIND_MOVE.binding_for(v,v_case),old_case.CONTENT_VERSION+1,p_actor);
    insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,EVENT_TYPE,PAYLOAD_JSON,CREATED_BY)
     values(RRL_CASE_PICK_EVENT_SQ.nextval,v_case,case v_kind when 'HU_ATTACH' then 'HU_PACKED' else 'HU_UNPACKED' end,p_request,p_actor);
   end if;
   -- Ordinary v2 CASE controls are revoked; a measured small box keeps its own unchanged v3 cargo proof.
   -- Moving the intact tree above deliberately preserves admission.
   for ct in(select CASE_PICK_TASK_ID,LEGACY_SBORKA_PALLET_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(
    select CASE_ID from json_table(v_parent_nodes,'$[*]' columns(CASE_ID number path '$.case_task_id'))
    union select CASE_ID from json_table(v_child_nodes,'$[*]' columns(CASE_ID number path '$.case_task_id'))) order by CASE_PICK_TASK_ID) loop
    if ct.LEGACY_SBORKA_PALLET_ID is not null and RRL_WH_FINAL_SCALE_ADMISSION.preserve_case(ct.CASE_PICK_TASK_ID)=1 then
     insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,EVENT_TYPE,PAYLOAD_JSON,CREATED_BY)
      values(RRL_CASE_PICK_EVENT_SQ.nextval,ct.CASE_PICK_TASK_ID,'CONTROL_RETAINED_SMALL_BOX',p_request,p_actor);
    elsif ct.LEGACY_SBORKA_PALLET_ID is not null then
     update RRL_SBORKA_PALLETS set SCAN_CONTENT_SIGNATURE=null,WEIGHT_CONTENT_SIGNATURE=null,
      SCAN_MARK_PROVED=0,SCAN_PHYSICAL_UNIT_COUNT=0,SCAN_ITEM_PROVED=0 where ID=ct.LEGACY_SBORKA_PALLET_ID;
     update RRL_CASE_PICK_TASK set STATUS='WAIT_CONTROL',UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=ct.CASE_PICK_TASK_ID;
     insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,EVENT_TYPE,PAYLOAD_JSON,CREATED_BY)
      values(RRL_CASE_PICK_EVENT_SQ.nextval,ct.CASE_PICK_TASK_ID,'CONTROL_REVOKED',p_request,p_actor);
    end if;
   end loop;
   a:=v.get_object('parent_snapshot').get_array('ancestors');
   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);bump(x.get_string('uid'));end loop;
  end if;
  j:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(v_uid));j.put('operation_id',v_op);j.put('command',v_kind);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE PACKAGE BODY          "RRL_STOCK_HU_LOAD_CORE" as
 procedure compile_load(p_request clob,p_snapshot clob,p_shipments clob,f in out nocopy json_array_t,r in out nocopy json_array_t,p_domain out json_object_t) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');ctx json_object_t;
  tree json_object_t:=json_object_t.parse(p_snapshot);measure json_object_t;tt RRL_TRANSPORT_TASK%rowtype;veh RRL_TR_VEHICLE%rowtype;
  mass_no number;volume_no number;width_no number;depth_no number;height_no number;ware_no number;blocked_no number;n number;trip_no number:=0;lower_mass number:=0;node_json json_object_t;node_array json_array_t;op varchar2(100):=d.get_string('operation_id');ids json_array_t:=json_array_t();destinations json_array_t:=json_array_t();destination json_object_t;j json_object_t;physical_boxes json_array_t;destination_wire clob;thermal_value json_object_t;floor_value json_object_t;
 begin
  if not m.has('loading_context') then p_domain:=null;return;end if;
  ctx:=m.get_object('loading_context');
  trip_no:=ctx.get_number('transport_task_id');select * into tt from RRL_TRANSPORT_TASK where ID=trip_no;
  select * into veh from RRL_TR_VEHICLE where NUM=tt.TRANSPORT and nvl(DELETED,0)=0;
  if tt.CONDITION is null or tt.CONDITION!=unistr('\0421\043F\043B\0430\043D\0438\0440\043E\0432\0430\043D') or nvl(tt.DELETED,0)!=0 or tt.DOCK is null then raise_application_error(-20886,'LOAD_ACTIVE_TRIP_VEHICLE_DOCK_REQUIRED');end if;
  if ctx.get_string('scan_vehicle') is null or ctx.get_string('scan_vehicle')!=tt.TRANSPORT or ctx.get_string('scan_dock') is null or ctx.get_string('scan_dock')!=tt.DOCK then raise_application_error(-20886,'LOAD_VEHICLE_DOCK_SCAN_REQUIRED');end if;
  if nvl(veh.BLOCKED,0)!=0 or nvl(veh.WORKING_NOW,0)!=1 or veh.PALLETS is null or veh.PALLETS<1 or veh.MAX_WEIGHT_KG is null or veh.MAX_WEIGHT_KG<=0 then raise_application_error(-20886,'LOAD_ACTIVE_VEHICLE_CAPACITY_REQUIRED');end if;
  select WARE_ID,nvl(DOCK_IS_BLOCKED,0) into ware_no,blocked_no from RRL_TT_DOCK where DOCK=tt.DOCK;
  if ware_no!=tree.get_number('warehouse') or blocked_no!=0 then raise_application_error(-20886,'LOAD_CURRENT_WAREHOUSE_DOCK_REQUIRED');end if;
  measure:=ctx.get_object('measurements');
  if measure.get_string('origin') is null or measure.get_string('origin')!='MANUAL_CONFIRMED' or measure.get_number('content_version') is null or measure.get_number('content_version')!=treat(tree.get_array('nodes').get(0) as json_object_t).get_number('version') then raise_application_error(-20886,'LOAD_CURRENT_MEASUREMENTS_REQUIRED');end if;
  mass_no:=RRL_STOCK_MATH.quantity(measure.get_string('gross_weight_kg'));width_no:=RRL_STOCK_MATH.quantity(measure.get_string('width_m'));depth_no:=RRL_STOCK_MATH.quantity(measure.get_string('depth_m'));height_no:=RRL_STOCK_MATH.quantity(measure.get_string('height_m'));
  if mass_no is null or width_no is null or depth_no is null or height_no is null or least(mass_no,width_no,depth_no,height_no)<=0 then raise_application_error(-20886,'LOAD_POSITIVE_SI_MEASUREMENTS_REQUIRED');end if;
  node_array:=tree.get_array('nodes');
  for i in 0..node_array.get_size-1 loop node_json:=treat(node_array.get(i) as json_object_t);
   lower_mass:=lower_mass+nvl(node_json.get_number('tare_weight_kg'),0);
   if node_json.get_string('kind')='STOCK' and node_json.get_string('base_uom')='KG' then lower_mass:=lower_mass+RRL_STOCK_MATH.quantity(node_json.get_string('quantity'));end if;
  end loop;
  if mass_no<lower_mass then raise_application_error(-20886,'LOAD_GROSS_BELOW_NET_AND_TARE');end if;
  volume_no:=ceil(width_no*depth_no*height_no*1000000000)/1000000000;
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(veh.ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(tt.ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_DOCK',tt.DOCK);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',op);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TT.LOAD.HU:'||tree.get_string('root'));
  for sp in(select ID,TRANSTASK_ID,WARE_ID,ADDR from RRL_SBORKA_PALLETS where ID in(select ID from json_table(p_shipments,'$[*]' columns(ID number path '$.domain.document_id'))) order by ID) loop
   if sp.ADDR is null then raise_application_error(-20886,'LOAD_ST_DESTINATION_REQUIRED');end if;
   destination:=json_object_t();destination.put('id',sp.ID);destination.put('address',sp.ADDR);destinations.append(destination);
   if sp.TRANSTASK_ID is null or sp.TRANSTASK_ID!=tt.ID or sp.WARE_ID!=ware_no then raise_application_error(-20886,'LOAD_ALL_STS_ASSIGNED_TO_THIS_TRIP_REQUIRED');end if;
   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TT.LOAD.ST:'||RRL_STOCK_PLAN_HELPER.decimal_text(sp.ID));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_ST',op||':'||RRL_STOCK_PLAN_HELPER.decimal_text(sp.ID));ids.append(sp.ID);
  end loop;
  if ids.get_size=0 or ids.get_size>200 then raise_application_error(-20881,'LOAD_MEMBER_ST_BOUND_200');end if;
  destination_wire:=destinations.to_clob;
  select count(*)into n from RRL_STORE_RECEIPT_POLICY where RECEIPT_MODE='WEIGHT_PHOTO'and STORE_ADDR in(select ADDR_TEXT from json_table(destination_wire,'$[*]'columns(ADDR_TEXT varchar2(255)path '$.address')));
  ctx.put('require_complete_box_mass',n>0);
  RRL_STOCK_LOAD_BOX_CORE.compile_boxes(p_snapshot,ctx.to_clob,op,mass_no,r,physical_boxes);
  RRL_STOCK_LOAD_BOX_CORE.assert_policy(destinations.to_clob,physical_boxes);
  RRL_STOCK_LOAD_THERMAL.compile_confirmation(ids.to_clob,veh.ID,ctx.to_clob,thermal_value);
  floor_value:=RRL_STOCK_LOAD_FLOOR.compile_load(p_snapshot,veh.ID,r);
  p_domain:=json_object_t();p_domain.put('trip',tt.ID);p_domain.put('vehicle_id',veh.ID);p_domain.put('vehicle',tt.TRANSPORT);p_domain.put('dock',tt.DOCK);p_domain.put('warehouse',ware_no);p_domain.put('uid',tree.get_string('root'));p_domain.put('case_task_id',tree.get_number('case_task_id'));p_domain.put('content_version',measure.get_number('content_version'));p_domain.put('mass_kg',RRL_STOCK_PLAN_HELPER.decimal_text(mass_no));p_domain.put('volume_m3',RRL_STOCK_PLAN_HELPER.decimal_text(volume_no));p_domain.put('members',ids);p_domain.put('destinations',destinations);p_domain.put('physical_boxes',physical_boxes);
  if floor_value is null then p_domain.put_null('floor_at_loading');else p_domain.put('floor_at_loading',floor_value);end if;
  if thermal_value is null then p_domain.put_null('temperature_at_loading');else p_domain.put('temperature_at_loading',thermal_value);end if;
 exception when no_data_found then raise_application_error(-20886,'LOAD_TRIP_VEHICLE_DOCK_CONFIGURATION_REQUIRED');
 end;
 procedure begin_load(p_domain clob) is
  j json_object_t:=json_object_t.parse(p_domain);tt RRL_TRANSPORT_TASK%rowtype;veh RRL_TR_VEHICLE%rowtype;ware_no number;blocked_no number;places number;mass_no number;
  trip_no number:=j.get_number('trip');vehicle_no number:=j.get_number('vehicle_id');dock_name varchar2(50):=j.get_string('dock');thermal_wire clob;thermal_element json_element_t;floor_wire clob;floor_element json_element_t;
 begin
  RRL_STOCK_LOAD_BOX_CORE.assert_policy(j.get_array('destinations').to_clob,j.get_array('physical_boxes'));
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(vehicle_no)));
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(trip_no)));
  select * into veh from RRL_TR_VEHICLE where ID=vehicle_no for update;
  select * into tt from RRL_TRANSPORT_TASK where ID=trip_no for update;
  select WARE_ID,nvl(DOCK_IS_BLOCKED,0) into ware_no,blocked_no from RRL_TT_DOCK where DOCK=dock_name for update;
  if tt.CONDITION is null or tt.CONDITION!=unistr('\0421\043F\043B\0430\043D\0438\0440\043E\0432\0430\043D') or nvl(tt.DELETED,0)!=0 or tt.TRANSPORT!=j.get_string('vehicle') or tt.DOCK!=dock_name or veh.NUM!=tt.TRANSPORT
   or nvl(veh.BLOCKED,0)!=0 or nvl(veh.WORKING_NOW,0)!=1 or nvl(veh.DELETED,0)!=0 or ware_no!=j.get_number('warehouse') or blocked_no!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: load trip/vehicle/dock');end if;
  if j.has('floor_at_loading')then floor_element:=j.get('floor_at_loading');if not floor_element.is_null then floor_wire:=floor_element.to_clob;end if;end if;
  RRL_STOCK_LOAD_FLOOR.assert_load(vehicle_no,trip_no,floor_wire);
  select count(*),nvl(sum(GROSS_WEIGHT_KG),0) into places,mass_no from RRL_TT_HU_LOAD_FACT where TT_ID=trip_no and STATUS='LOADED';
  if veh.PALLETS is null or veh.MAX_WEIGHT_KG is null or(floor_wire is null and places+1>veh.PALLETS)or mass_no+RRL_STOCK_MATH.quantity(j.get_string('mass_kg'))>veh.MAX_WEIGHT_KG then raise_application_error(-20886,'LOAD_VEHICLE_PHYSICAL_CAPACITY_EXCEEDED');end if;
  select count(*) into places from RRL_TT_HU_LOAD_FACT where VEHICLE_ID=vehicle_no and TT_ID!=trip_no and STATUS='LOADED';
  if places>0 then raise_application_error(-20886,'LOAD_VEHICLE_HAS_ANOTHER_OPEN_TRIP');end if;
  if j.has('temperature_at_loading')then thermal_element:=j.get('temperature_at_loading');if not thermal_element.is_null then thermal_wire:=thermal_element.to_clob;end if;end if;
  RRL_STOCK_LOAD_THERMAL.assert_current(j.get_array('members').to_clob,vehicle_no,thermal_wire);
  RRL_STORE_ACCESS_RULES.assert_members(vehicle_no,j.get_array('members').to_clob);
 end;
 procedure finish_load(p_domain clob,p_snapshot clob,p_operation varchar2,p_actor varchar2) is
  j json_object_t:=json_object_t.parse(p_domain);ids clob:=j.get_array('members').to_clob;trip_no number:=j.get_number('trip');root_uid varchar2(200):=j.get_string('uid');vehicle_no number:=j.get_number('vehicle_id');plate varchar2(50):=j.get_string('vehicle');dock_name varchar2(50):=j.get_string('dock');ware_no number:=j.get_number('warehouse');mass_no number:=RRL_STOCK_MATH.quantity(j.get_string('mass_kg'));volume_no number:=RRL_STOCK_MATH.quantity(j.get_string('volume_m3'));version_no number:=j.get_number('content_version');destinations clob:=j.get_array('destinations').to_clob;case_no number:=j.get_number('case_task_id');n number;thermal_element json_element_t;
 begin
  select count(*) into n from RRL_SBORKA_PALLETS where ID in(select ID from json_table(ids,'$[*]' columns(ID number path '$'))) and TRANSTASK_ID=trip_no and WARE_ID=ware_no and CONDITION=2;
  if n!=j.get_array('members').get_size then raise_application_error(-20890,'CLOSURE_CHANGED: physical load member assignment');end if;
  select count(*) into n from RRL_SBORKA_PALLETS sp join json_table(destinations,'$[*]' columns(ID number path '$.id',ADDR_TEXT varchar2(255) path '$.address')) frozen on frozen.ID=sp.ID and frozen.ADDR_TEXT=sp.ADDR
   where sp.TRANSTASK_ID=trip_no and sp.CONDITION=2;
  if n!=j.get_array('members').get_size then raise_application_error(-20890,'CLOSURE_CHANGED: physical load destinations');end if;
  if case_no is not null then root_uid:=null;end if;
  insert into RRL_TT_HU_LOAD_FACT(LOAD_OPERATION_ID,TT_ID,ROOT_UID,VEHICLE_ID,VEHICLE_NUMBER,DOCK,WARE_ID,STATUS,GROSS_WEIGHT_KG,BOUNDING_VOLUME_M3,CONTENT_VERSION,COMPOSITION_JSON,LOADED_BY,ROOT_CASE_TASK_ID)
   values(p_operation,trip_no,root_uid,vehicle_no,plate,dock_name,ware_no,'LOADED',mass_no,volume_no,version_no,p_snapshot,p_actor,case_no);
  RRL_STOCK_LOAD_BOX_CORE.persist_boxes(p_operation,j.get_array('physical_boxes'),p_actor);
  if j.has('floor_at_loading')then thermal_element:=j.get('floor_at_loading');if not thermal_element.is_null then RRL_STOCK_LOAD_FLOOR.persist_confirmation(p_operation,thermal_element.to_clob,p_actor);end if;end if;
  if j.has('temperature_at_loading')then thermal_element:=j.get('temperature_at_loading');if not thermal_element.is_null then RRL_STOCK_LOAD_THERMAL.persist_confirmation(p_operation,thermal_element.to_clob,p_actor);end if;end if;
  for sp in(select ID,ADDR_TEXT from json_table(destinations,'$[*]' columns(ID number path '$.id',ADDR_TEXT varchar2(255) path '$.address')) order by ID) loop
   insert into RRL_TT_HU_LOAD_ST(LOAD_OPERATION_ID,SBORKA_PALLET_ID,DESTINATION_ADDR) values(p_operation,sp.ID,sp.ADDR_TEXT);
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_PLACEMENT_CORE as
 function stock_source_claims(p_uid varchar2,p_cell varchar2)return clob is a json_array_t:=json_array_t();x json_object_t;n number:=0;
 begin
  for cl in(select TASK_ID,CELL_SLOT_ID,HU_GROSS_WEIGHT_KG,HU_BOUNDING_VOLUME_M3,HU_COMPOSITION_VERSION,HU_STOCK_COMPOSITION_VERSION,HU_PHYSICAL_VERSION,HU_UNIT_SIGNATURE from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=p_uid and CELL=p_cell and STATUS='OCCUPIED'order by TASK_ID fetch first 2 rows only)loop
   n:=n+1;
   if n>1 or cl.CELL_SLOT_ID is null then raise_application_error(-20886,'SINGLE_LOAD_ONE_CURRENT_SOURCE_SLOT_REQUIRED');end if;
   x:=json_object_t();x.put('task',cl.TASK_ID);x.put('slot',cl.CELL_SLOT_ID);x.put('mass',cl.HU_GROSS_WEIGHT_KG);x.put('volume',cl.HU_BOUNDING_VOLUME_M3);x.put('content_version',cl.HU_COMPOSITION_VERSION);x.put('stock_version',cl.HU_STOCK_COMPOSITION_VERSION);x.put('physical_version',cl.HU_PHYSICAL_VERSION);x.put('unit_signature',cl.HU_UNIT_SIGNATURE);a.append(x);
  end loop;
  return a.to_clob;
 end;
 procedure declare_stock_source(r in out nocopy json_array_t,p_uid varchar2,p_cell varchar2,p_claims out clob)is a json_array_t;x json_object_t;
 begin
  p_claims:=stock_source_claims(p_uid,p_cell);a:=json_array_t.parse(p_claims);
  for i in 0..a.get_size-1 loop x:=treat(a.get(i)as json_object_t);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('task')));
   RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('slot')));
  end loop;
 end;
 procedure release_stock_source(p_uid varchar2,p_cell varchar2,p_claims clob)is
  wire clob;domain_json json_object_t;kind varchar2(80);state_value varchar2(20);op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');a json_array_t:=json_array_t.parse(p_claims);x json_object_t;task_no number;
 begin
  select COMMAND_TYPE,STATE,RESOLVED_PLAN_JSON into kind,state_value,wire from RRL_STOCK_OPERATION where OPERATION_ID=op;domain_json:=json_object_t.parse(wire).get_object('domain');
  if kind!='LOAD_SHIPMENT'or state_value!='IN_FLIGHT'or domain_json.get_object('snapshot').get_string('root')!=p_uid or domain_json.get_object('snapshot').get_string('cell')!=p_cell or dbms_lob.compare(domain_json.get_array('source_stock_claims').to_clob,p_claims)!=0 then raise_application_error(-20863,'SINGLE_SOURCE_SLOT_EXACT_PLAN_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
  if dbms_lob.compare(stock_source_claims(p_uid,p_cell),p_claims)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: standalone source occupancy');end if;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i)as json_object_t);task_no:=x.get_number('task');
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(task_no)));
   RRL_STOCK_LOCK_API.assert_held(40,RRL_STOCK_LOCK_API.resource_key('SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('slot'))));
   delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=task_no and UID_PALLET=p_uid and CELL=p_cell and STATUS='OCCUPIED';
   if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: standalone source slot');end if;
  end loop;
 end;
 function sync_key(p_task number) return varchar2 is begin return 'WT:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_task)||':MANUAL:PUTAWAY:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_task)||':';end;
 procedure declare_place(r in out nocopy json_array_t,p_task number,p_sync number) is
 begin
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(p_task));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(p_task));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK_SYNC',RRL_STOCK_PLAN_HELPER.decimal_text(p_sync));
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TASK.SYNC:'||sync_key(p_task));
 end;
 procedure declare_existing_case(r in out nocopy json_array_t,p_case number) is
 begin
  for cl in(select TASK_ID,CELL_SLOT_ID from RRL_RECEIPT_SLOT_CLAIM where HU_CASE_TASK_ID=p_case and STATUS in('RESERVED','OCCUPIED') order by TASK_ID) loop
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(cl.TASK_ID));
   RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(cl.CELL_SLOT_ID));
  end loop;
 end;
 procedure release_case(p_case number,p_cell varchar2) is
 begin
  for cl in(select TASK_ID,CELL_SLOT_ID from RRL_RECEIPT_SLOT_CLAIM where HU_CASE_TASK_ID=p_case and CELL=p_cell and STATUS='OCCUPIED') loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(cl.TASK_ID)));
   RRL_STOCK_LOCK_API.assert_held(40,RRL_STOCK_LOCK_API.resource_key('SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(cl.CELL_SLOT_ID)));
   delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=cl.TASK_ID and HU_CASE_TASK_ID=p_case;
  end loop;
 end;
 procedure record_place(p_request clob,p_actor varchar2,p_uid varchar2,p_warehouse number,p_cell varchar2,p_task number,p_slot number,p_sync number,p_placement clob,p_case_task number default null) is
  placement_json json_object_t:=json_object_t.parse(p_placement);measures json_object_t;version_no number;mass_no number;volume_no number;measurement_json clob;completion_hash varchar2(64);key_text varchar2(255);kind_name varchar2(20);stock_version number;physical_version number;unit_sig varchar2(64);unit_count number;actual_cell varchar2(60);
 begin
  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',p_uid));
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(p_task)));
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(p_task)));
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK_SYNC',RRL_STOCK_PLAN_HELPER.decimal_text(p_sync)));
  RRL_STOCK_LOCK_API.assert_held(40,RRL_STOCK_LOCK_API.resource_key('SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(p_slot)));
  if p_case_task is not null then
   if p_uid!='CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_case_task) then raise_application_error(-20886,'PLACEMENT_CASE_IDENTITY_CONFLICT');end if;
   select CONTENT_VERSION,CURRENT_CELL into version_no,actual_cell from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_case_task and STATUS in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP');
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(p_case_task)));
   if actual_cell is null or actual_cell!=p_cell then raise_application_error(-20890,'PLACEMENT_CASE_CELL_CHANGED');end if;
  else
  select HU_CONTENT_VERSION,HU_KIND,STOCK_COMPOSITION_VERSION,HU_CURRENT_CELL into version_no,kind_name,stock_version,actual_cell from RRL_PALLETS where UID_PALLET=p_uid and HU_SHIPPED_OPERATION is null;
  if kind_name='CONTAINER' then
   if actual_cell is null or actual_cell!=p_cell then raise_application_error(-20890,'PLACEMENT_CONTAINER_CELL_CHANGED');end if;
   stock_version:=null;
  elsif kind_name='STOCK' then
   RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
   select PHYSICAL_VERSION into physical_version from RRL_REMAINS where UID_POLETA=p_uid and CELL=p_cell and REMAIN>0;
   RRL_STOCK_HU_UNIT_SIGNATURE.describe_units(p_uid,null,unit_sig,unit_count);
  else raise_application_error(-20886,'PLACEMENT_OWNER_KIND_INVALID');end if;
  end if;
  measures:=placement_json.get_object('measurements');mass_no:=RRL_STOCK_MATH.quantity(measures.get_string('gross_weight_kg'));volume_no:=RRL_STOCK_MATH.quantity(measures.get_string('bounding_volume_m3'));
  measures.put('content_version',version_no);measurement_json:=measures.to_clob;completion_hash:=rawtohex(sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256));
  insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,UID_PALLET,FROM_WARE_ID,FROM_CELL,TO_WARE_ID,TO_CELL,QTY,FACT_QTY,UNIT_CODE,QTY_MODE,STATUS,CREATED_BY,ASSIGNED_TO,FINISHED_AT,HU_CONTENT_VERSION,TO_CELL_SLOT_ID,HU_MEASUREMENTS_JSON,COMPLETION_HASH,COMPLETION_JSON)
   values(p_task,'PUTAWAY','MANUAL',p_task,'WAREHOUSE_HU',p_uid,p_warehouse,p_cell,p_warehouse,p_cell,1,1,'HU','PALLET','DONE',p_actor,p_actor,systimestamp,version_no,p_slot,measurement_json,completion_hash,p_request);
  insert into RRL_RECEIPT_SLOT_CLAIM(TASK_ID,UID_PALLET,CELL,CELL_SLOT_ID,STATUS,HU_GROSS_WEIGHT_KG,HU_BOUNDING_VOLUME_M3,HU_COMPOSITION_VERSION,HU_STOCK_COMPOSITION_VERSION,HU_PHYSICAL_VERSION,HU_UNIT_SIGNATURE,HU_CASE_TASK_ID)
   values(p_task,p_uid,p_cell,p_slot,'OCCUPIED',mass_no,volume_no,version_no,stock_version,physical_version,unit_sig,p_case_task);
  key_text:=sync_key(p_task);
  insert into RRL_WAREHOUSE_TASK_SYNC(SYNC_ID,TASK_ID,TASK_SOURCE,TASK_TYPE,SOURCE_DOC_TYPE,SOURCE_TASK_ID,SYNC_KEY,SYNC_STATUS,SYNC_ATTEMPT,CREATED_AT,UPDATED_AT,SYNCED_AT,UPDATED_BY)
   values(p_sync,p_task,'MANUAL','PUTAWAY','WAREHOUSE_HU',p_task,key_text,'SYNCED',1,systimestamp,systimestamp,systimestamp,p_actor);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_READ as
 function build_snapshot(p_uid varchar2,p_case number,p_ignore_task number) return clob is
  j json_object_t:=json_object_t();nodes json_array_t:=json_array_t();edges json_array_t:=json_array_t();anc json_array_t:=json_array_t();x json_object_t;
  type seen_type is table of number index by varchar2(200);seen seen_type;
  v_leaf number:=0;v_count number:=0;v_cell varchar2(60);v_ware number;v_open number;v_units number:=0;
  procedure walk(p_id varchar2,p_depth number,p_case_owner number default null);
  procedure walk_case(p_task number,p_depth number) is
   ct RRL_CASE_PICK_TASK%rowtype;a json_object_t;b json_object_t;v_key varchar2(200):='CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_task);n number;mass_wire clob;mass json_object_t;
  begin
   if p_depth>16 or seen.exists(v_key) then raise_application_error(-20886,'HU_CASE_CYCLE_OR_DEPTH_BOUND');end if;
   v_count:=v_count+1;if v_count>200 then raise_application_error(-20881,'HU_NODE_BOUND_200');end if;seen(v_key):=1;
   select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_task;
   if ct.CURRENT_CELL is null or ct.STATUS not in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP') then raise_application_error(-20886,'HU_CASE_CLOSED_PHYSICAL_CARRIER_REQUIRED');end if;
   if v_cell is null then v_cell:=ct.CURRENT_CELL;v_ware:=ct.WARE_ID;
   elsif v_cell!=ct.CURRENT_CELL or v_ware!=ct.WARE_ID then raise_application_error(-20887,'HU_CASE_TREE_LOCATION_CONFLICT');end if;
   a:=json_object_t();a.put('uid',v_key);a.put('case_task_id',p_task);a.put('kind','CASE');a.put('type','CASE');a.put('sscc',ct.SSCC);
   a.put('version',ct.CONTENT_VERSION);a.put('status',ct.STATUS);a.put('wave_id',ct.PICK_WAVE_ID);a.put('cell',ct.CURRENT_CELL);a.put('depth',p_depth);a.put('open_task_count',0);a.put_null('tare_weight_kg');
   mass_wire:=RRL_WH_FINAL_SCALE_ADMISSION.mass_json(p_task);
   if mass_wire is not null then
    mass:=json_object_t.parse(mass_wire);a.put('scale_qc',mass);a.put('gross_weight_kg',mass.get_string('gross_weight_kg'));a.put('tare_weight_kg',mass.get_string('tare_weight_kg'));a.put('net_weight_kg',mass.get_string('net_weight_kg'));
   end if;nodes.append(a);
   n:=0;
   for h in(select LOT_UID from RRL_CASE_CARRIER_LOT where CASE_PICK_TASK_ID=p_task order by LOT_UID fetch first 201 rows only) loop
    n:=n+1;if n>200 then raise_application_error(-20881,'HU_CASE_LEAF_BOUND_200');end if;
    b:=json_object_t();b.put('parent',v_key);b.put('child',h.LOT_UID);b.put('membership','CASE_CARRIER_LOT');edges.append(b);
    walk(h.LOT_UID,p_depth+1,p_task);
   end loop;
   if n=0 then raise_application_error(-20886,'HU_CASE_PHYSICAL_STOCK_REQUIRED');end if;
  end;
  procedure walk(p_id varchar2,p_depth number,p_case_owner number default null) is
   p RRL_PALLETS%rowtype;s RRL_REMAINS%rowtype;n number;cell_name varchar2(60);a json_object_t;b json_object_t;
  begin
   if p_depth>16 or seen.exists('PALLET:'||p_id) then raise_application_error(-20886,'HU_CYCLE_OR_DEPTH_BOUND_16');end if;
   v_count:=v_count+1;if v_count>200 then raise_application_error(-20881,'HU_NODE_BOUND_200');end if;seen('PALLET:'||p_id):=1;
   select * into p from RRL_PALLETS where UID_PALLET=p_id;
   a:=json_object_t();a.put('uid',p_id);a.put('kind',p.HU_KIND);a.put('type',p.HU_TYPE);a.put('version',p.HU_CONTENT_VERSION);
   a.put('sscc',p.SSCC);a.put('tare_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(p.HU_TARE_WEIGHT_KG));
   if p.HU_KIND='CONTAINER' then
    if p.HU_TYPE='BOX'then
     declare packing json_object_t:=RRL_HU_PACK_CLOCK.clock_json(p_id,p.HU_CONTENT_VERSION);begin
      if packing is not null then a.put('packing_start',packing);end if;
     end;
    end if;
    cell_name:=p.HU_CURRENT_CELL;
    select count(*) into n from RRL_REMAINS where UID_POLETA=p_id and (REMAIN!=0 or HARD_RESERVED_BASE!=0);
    if n>0 then raise_application_error(-20887,'HU_CONTAINER_HAS_QUANTITATIVE_STOCK');end if;
   else
    select count(*) into n from RRL_CASE_CARRIER_LOT where LOT_UID=p_id;
    if n>0 then
     select count(*) into n from RRL_CASE_CARRIER_LOT where LOT_UID=p_id and CASE_PICK_TASK_ID=p_case_owner;
     if n!=1 then raise_application_error(-20886,'HU_CASE_MEMBER_REQUIRES_CARRIER_ATTACHMENT');end if;
     a.put('case_task_id',p_case_owner);
    end if;
    select count(*) into n from RRL_REMAINS where UID_POLETA=p_id and REMAIN>0;
    if n!=1 then raise_application_error(-20886,'HU_LEAF_SINGLE_PHYSICAL_LOCATION_REQUIRED');end if;
    select * into s from RRL_REMAINS where UID_POLETA=p_id and REMAIN>0;
    select count(*) into n from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_id and STOCK_STATUS!='ISSUED' and rownum<=10001;
    v_units:=v_units+n;if v_units>10000 then raise_application_error(-20881,'HU_PHYSICAL_UNIT_BOUND_10000');end if;
    cell_name:=s.CELL;v_leaf:=v_leaf+1;
    a.put('article',p.ARTICUL);a.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(s.REMAIN));
    a.put('hard_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(s.HARD_RESERVED_BASE));a.put('base_uom',s.BASE_UOM);
    a.put('stock_version',s.STOCK_VERSION);
    if p_case_owner is null and s.REMAIN=p.UNIT_COUNT then a.put('weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(p.WEIGHT_BRUTTO));else a.put_null('weight_kg');end if;
   end if;
   if cell_name is null then raise_application_error(-20886,'HU_PHYSICAL_LOCATION_REQUIRED');end if;
   if v_cell is null then v_cell:=cell_name;select WARE_ID into v_ware from RRL_CELLS where CELL=v_cell;
   elsif v_cell!=cell_name then raise_application_error(-20887,'HU_TREE_LOCATION_CONFLICT');end if;
   select count(*) into n from RRL_WAREHOUSE_TASK where UID_PALLET=p_id and STATUS not in('DONE','CANCELLED') and (p_ignore_task is null or TASK_ID!=p_ignore_task);
   a.put('open_task_count',n);a.put('cell',cell_name);a.put('depth',p_depth);nodes.append(a);
   for e in(select * from RRL_WMS_HU_LINK where PARENT_UID=p_id and ACTIVE_FLAG=1 order by HU_LINK_ID) loop
    if p.HU_KIND!='CONTAINER' then raise_application_error(-20887,'HU_QUANTITATIVE_LEAF_HAS_CHILDREN');end if;
    b:=json_object_t();b.put('id',e.HU_LINK_ID);b.put('parent',e.PARENT_UID);b.put('child',case when e.CHILD_CASE_TASK_ID is null then e.CHILD_PALLET_UID else 'CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(e.CHILD_CASE_TASK_ID) end);b.put('version',e.LINK_VERSION);edges.append(b);
    if e.CHILD_CASE_TASK_ID is not null then walk_case(e.CHILD_CASE_TASK_ID,p_depth+1);else walk(e.CHILD_PALLET_UID,p_depth+1);end if;
   end loop;
  end;
 begin
  if p_case is null then walk(p_uid,0);else walk_case(p_case,0);end if;
  for h in(select PARENT_UID,level DEPTH,connect_by_iscycle CYCLIC from RRL_WMS_HU_LINK
   start with (CHILD_PALLET_UID=p_uid or CHILD_CASE_TASK_ID=p_case) and ACTIVE_FLAG=1
   connect by nocycle prior PARENT_UID=CHILD_PALLET_UID and ACTIVE_FLAG=1) loop
   if h.DEPTH>16 or h.CYCLIC=1 then raise_application_error(-20886,'HU_ANCESTOR_CYCLE_OR_DEPTH_BOUND');end if;
   x:=json_object_t();
   for p in(select HU_KIND,HU_CURRENT_CELL,HU_CONTENT_VERSION from RRL_PALLETS where UID_PALLET=h.PARENT_UID) loop
    if p.HU_KIND!='CONTAINER' or p.HU_CURRENT_CELL!=v_cell then raise_application_error(-20887,'HU_ANCESTOR_LOCATION_CONFLICT');end if;
    x.put('uid',h.PARENT_UID);x.put('version',p.HU_CONTENT_VERSION);x.put('cell',p.HU_CURRENT_CELL);
   end loop;
   select count(*) into v_open from RRL_WAREHOUSE_TASK where UID_PALLET=h.PARENT_UID and STATUS not in('DONE','CANCELLED') and (p_ignore_task is null or TASK_ID!=p_ignore_task);
   x.put('open_task_count',v_open);anc.append(x);
  end loop;
  j.put('root',case when p_case is null then p_uid else 'CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_case) end);if p_case is not null then j.put('case_task_id',p_case);end if;j.put('warehouse',v_ware);j.put('cell',v_cell);j.put('nodes',nodes);j.put('links',edges);j.put('ancestors',anc);
  j.put('physical_unit_count',v_units);j.put('leaf_count',v_leaf);j.put('top_place_count',case when anc.get_size=0 then 1 else 0 end);return j.to_clob;
 end;
 function snapshot_json(p_uid varchar2,p_ignore_task number default null) return clob is begin return build_snapshot(p_uid,null,p_ignore_task);end;
 function case_snapshot_json(p_task number) return clob is begin return build_snapshot(null,p_task,null);end;
 procedure assert_quantity_write(p_uid varchar2) is v_count number;v_op varchar2(100);v_command varchar2(80);
 begin
  select count(*) into v_count from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 and (CHILD_PALLET_UID=p_uid
   or CHILD_CASE_TASK_ID in(select CASE_PICK_TASK_ID from RRL_CASE_CARRIER_LOT where LOT_UID=p_uid));
  if v_count=0 then return;end if;
  v_op:=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');select COMMAND_TYPE into v_command from RRL_STOCK_OPERATION where OPERATION_ID=v_op;
  if v_command not in('HU_MOVE','HU_TASK_COMPLETE','HU_SHIP') then raise_application_error(-20886,'NESTED_HU_REQUIRES_TOP_MOVE_OR_EXPLICIT_UNPACK');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_REPACK_CMD as
 function proxy(p_request clob)return clob is d json_object_t:=json_object_t.parse(p_request);begin d.put('command_type','HU_ATTACH');return d.to_clob;end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;p json_object_t;c json_object_t;
  f json_array_t;r json_array_t;dom clob;parent_uid varchar2(200);child_uid varchar2(200);cell_name varchar2(60);
  parent_claim number;child_claim number;parent_slot number;child_slot number;task_no number;sync_no number;cv number;v_saved number;v_error number;
 begin
  if trim(m.get_string('reason'))is null or length(m.get_string('reason'))>1000 then raise_application_error(-20886,'HU_REPACK_REASON_REQUIRED');end if;
  if not m.has('measurements')or m.get('measurements').is_null then raise_application_error(-20886,'HU_REPACK_COMBINED_MEASUREMENTS_REQUIRED');end if;
  RRL_STOCK_HU_CMD.compile_command(proxy(p_request),p_operation,p_policies,p_resources,dom,true);
  v:=json_object_t.parse(dom);p:=v.get_object('parent_snapshot');c:=v.get_object('child_snapshot');
  parent_uid:=p.get_string('root');child_uid:=c.get_string('root');cell_name:=p.get_string('cell');
  if p.get_array('ancestors').get_size>0 or c.get_array('ancestors').get_size>0 then raise_application_error(-20886,'HU_REPACK_TWO_TOP_PLACES_REQUIRED');end if;
  cv:=treat(p.get_array('nodes').get(0)as json_object_t).get_number('version');
  if m.get_object('measurements').get_number('content_version')is null or m.get_object('measurements').get_number('content_version')!=cv then raise_application_error(-20890,'HU_REPACK_MEASUREMENT_VERSION_CONFLICT');end if;
  begin
   select TASK_ID,CELL_SLOT_ID into parent_claim,parent_slot from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=parent_uid and CELL=cell_name and STATUS='OCCUPIED';
   select TASK_ID,CELL_SLOT_ID into child_claim,child_slot from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=child_uid and CELL=cell_name and STATUS='OCCUPIED';
  exception when no_data_found then raise_application_error(-20886,'HU_REPACK_TWO_OCCUPIED_PLACES_REQUIRED');end;
  if parent_slot is null or child_slot is null or parent_slot=child_slot then raise_application_error(-20886,'HU_REPACK_DISTINCT_SOURCE_SLOTS_REQUIRED');end if;
  f:=json_array_t.parse(p_policies);r:=json_array_t.parse(p_resources);
  RRL_STOCK_PLAN_HELPER.fence(f,'CELL',cell_name,6);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(parent_claim));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(child_claim));
  RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(parent_slot));
  RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(child_slot));
  task_no:=RRL_WAREHOUSE_TASK_SQ.nextval;sync_no:=RRL_WH_TASK_SYNC_SQ.nextval;
  RRL_STOCK_HU_PLACEMENT_CORE.declare_place(r,task_no,sync_no);
  v.put('parent_claim_task',parent_claim);v.put('child_claim_task',child_claim);v.put('parent_slot',parent_slot);v.put('child_slot',child_slot);
  v.put('placement_task',task_no);v.put('placement_sync',sync_no);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 exception when others then
  v_error:=sqlcode;
  if v_error in(-20886,-20867,-20890)then
   select count(*)into v_saved from RRL_STOCK_OPERATION where OPERATION_ID=p_operation and STATE='APPLIED';
   if v_saved=1 then raise_application_error(-20890,'HU_REPACK_COMMITTED_PEER_RETRY_SAME_OPERATION');end if;
  end if;raise;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');op varchar2(100):=d.get_string('operation_id');
  plan clob;v json_object_t;tree json_object_t;placement_metadata json_object_t;measures json_object_t;placement_json clob;unused_result clob;nodes clob;
  parent_uid varchar2(200);child_uid varchar2(200);cell_name varchar2(60);parent_slot number;child_slot number;parent_claim number;child_claim number;ware number;code varchar2(100);rid number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'HU_EXECUTION_FORBIDDEN');end if;
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  parent_uid:=v.get_object('parent_snapshot').get_string('root');child_uid:=v.get_object('child_snapshot').get_string('root');
  cell_name:=v.get_object('parent_snapshot').get_string('cell');ware:=v.get_object('parent_snapshot').get_number('warehouse');
  parent_slot:=v.get_number('parent_slot');child_slot:=v.get_number('child_slot');parent_claim:=v.get_number('parent_claim_task');child_claim:=v.get_number('child_claim_task');
  if m.get_string('scan_cell')is null or m.get_string('scan_cell')!=cell_name then raise_application_error(-20886,'HU_REPACK_CELL_SCAN_REQUIRED');end if;
  select SLOT_CODE into code from RRL_TOPOLOGY_CELL_SLOT where CELL_SLOT_ID=parent_slot;
  if m.get_string('scan_parent_slot')is null or m.get_string('scan_parent_slot')!=code then raise_application_error(-20886,'HU_REPACK_PARENT_SLOT_SCAN_REQUIRED');end if;
  select SLOT_CODE into code from RRL_TOPOLOGY_CELL_SLOT where CELL_SLOT_ID=child_slot;
  if m.get_string('scan_child_slot')is null or m.get_string('scan_child_slot')!=code then raise_application_error(-20886,'HU_REPACK_CHILD_SLOT_SCAN_REQUIRED');end if;
  -- Existing executor checks both locked source signatures, versions, scans, cycles and book proof.
  RRL_STOCK_HU_CMD.execute_command(proxy(p_request),p_actor,unused_result);
  delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=parent_claim and UID_PALLET=parent_uid and CELL_SLOT_ID=parent_slot and STATUS='OCCUPIED';
  if sql%rowcount!=1 then raise_application_error(-20890,'HU_REPACK_PARENT_CLAIM_CHANGED');end if;
  delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=child_claim and UID_PALLET=child_uid and CELL_SLOT_ID=child_slot and STATUS='OCCUPIED';
  if sql%rowcount!=1 then raise_application_error(-20890,'HU_REPACK_CHILD_CLAIM_CHANGED');end if;
  tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(parent_uid));
  placement_metadata:=json_object_t.parse(m.to_clob);measures:=json_object_t.parse(m.get_object('measurements').to_clob);
  measures.put('content_version',treat(tree.get_array('nodes').get(0)as json_object_t).get_number('version'));
  placement_metadata.put('measurements',measures);placement_metadata.put('target_cell',cell_name);placement_metadata.put('target_slot_id',parent_slot);placement_metadata.put('planned_physical_task_id',v.get_number('placement_task'));
  -- Capacity validation sees the actual merged tree and excludes the replaced root once.
  -- A late refusal rolls back links, epochs and both deleted claims with the same root transaction.
  placement_json:=RRL_STOCK_HU_SLOT.target_json(tree.to_clob,placement_metadata.to_clob,null,parent_uid);
  RRL_STOCK_HU_PLACEMENT_CORE.record_place(p_request,p_actor,parent_uid,ware,cell_name,v.get_number('placement_task'),parent_slot,v.get_number('placement_sync'),placement_json);
  nodes:=tree.get_array('nodes').to_clob;
  for rr in(select RESERVATION_ID,UID_PALLET,CELL,BASE_QTY from RRL_STOCK_RESERVATION where UID_PALLET in(
   select U from json_table(nodes,'$[*]'columns(U varchar2(200)path '$.uid',K varchar2(20)path '$.kind'))where K='STOCK')
   and CELL=cell_name and RESERVATION_KIND='HARD'and STATUS in('ACTIVE','ALLOCATED','PICKING')and BASE_QTY>0 and nvl(CELL_SLOT_ID,-1)!=parent_slot order by RESERVATION_ID)loop
   RRL_STOCK_RESERVE_CORE.move_coverage(rr.RESERVATION_ID,rr.RESERVATION_ID,rr.UID_PALLET,rr.CELL,ware,rr.BASE_QTY,parent_slot,p_actor,rid);
   if rid!=rr.RESERVATION_ID then raise_application_error(-20869,'HU_REPACK_RESERVATION_IDENTITY_CHANGED');end if;
  end loop;
  tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(parent_uid));tree.put('operation_id',op);tree.put('command','HU_REPACK_SLOT');
  tree.put('task_id',v.get_number('placement_task'));tree.put('pallet_identifier',parent_uid);tree.put('slot_id',parent_slot);tree.put('released_child_slot_id',child_slot);tree.put('quantity_unchanged',true);tree.put('tare_assets_preserved',true);
  p_result:=tree.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_SHIP_CMD as  
 function digest(s clob) return varchar2 is begin return rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256));end;  
 procedure append_all(a in out nocopy json_array_t,b json_array_t) is begin for i in 0..b.get_size-1 loop a.append(b.get(i));end loop;end;  
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is  
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t:=json_object_t();snap json_object_t;  
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;plans json_array_t:=json_array_t();x json_object_t;sub json_object_t;src json_object_t;subdomain json_object_t;  
  v_uid varchar2(200):=d.get_object('source').get_string('uid');s clob;nodes clob;p clob;q clob;dom clob;st number;ident varchar2(200);total number:=0;leaf_qty number;leg_uid varchar2(200);leg_cell varchar2(60);leg_qty number;leg_count number;all_legs json_array_t:=json_array_t();type quantity_map is table of number index by varchar2(200);expected_qty quantity_map;consumed_qty quantity_map;loading_domain json_object_t;v_profiles clob;v_first_profiles clob;v_profile_count number;v_warehouse number;v_source_cell varchar2(60);  
 begin  
  s:=RRL_STOCK_HU_READ.snapshot_json(v_uid);snap:=json_object_t.parse(s);v_warehouse:=snap.get_number('warehouse');v_source_cell:=snap.get_string('cell');a:=snap.get_array('nodes');nodes:=a.to_clob;  
  if snap.get_array('ancestors').get_size>0 or a.get_size<2 or treat(a.get(0) as json_object_t).get_string('kind')!='CONTAINER' then raise_application_error(-20886,'HU_SHIP_TOP_CONTAINER_REQUIRED');end if;  
  if m.get_number('expected_version') is null or m.get_number('expected_version')!=treat(a.get(0) as json_object_t).get_number('version') then raise_application_error(-20890,'CLOSURE_CHANGED: HU shipment version');end if;  
  for i in 0..a.get_size-1 loop  
   x:=treat(a.get(i) as json_object_t);  
   if x.get_number('open_task_count')>0 then raise_application_error(-20886,'HU_SHIP_PHYSICAL_TASK_OPEN');end if;  
   if x.get_string('kind')='STOCK' then  
    expected_qty(x.get_string('uid')):=RRL_STOCK_MATH.quantity(x.get_string('quantity'));  
   end if;  
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',x.get_string('uid'));  
   if x.get_string('kind')='CASE' then  
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('case_task_id')));  
   else RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',x.get_string('uid'));end if;  
  end loop;  
  for ct in(select LEGACY_SBORKA_PALLET_ID from(  
   select LEGACY_SBORKA_PALLET_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(  
    select CASE_ID from json_table(nodes,'$[*]' columns(CASE_ID number path '$.case_task_id')))  
   union  
   select LEGACY_SBORKA_PALLET_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where STATUS='PICKED' and PICKED_WAREHOUSE_TASK_ID is not null  
    and PICKED_PALLET_UID in(select U from json_table(nodes,'$[*]' columns(U varchar2(200) path '$.uid',K varchar2(20) path '$.kind',CASE_ID number path '$.case_task_id')) where K='STOCK' and CASE_ID is null))  
   union 
   select b.ST_ID from RRL_INTERWARE_ONWARD_BIND b where b.WARE_ID=v_warehouse and b.SOURCE_CELL=v_source_cell and not exists(select 1 from RRL_INTERWARE_ONWARD_DISPATCH dispatched where dispatched.BIND_OPERATION_ID=b.OPERATION_ID)and b.ROOT_UID in( 
    select U from json_table(nodes,'$[*]'columns(U varchar2(200)path '$.uid',K varchar2(20)path '$.kind'))where K='STOCK') 
   union 
   select b.ST_ID from RRL_IW_GROUP_ST_BIND b where b.WARE_ID=v_warehouse and b.SOURCE_CELL=v_source_cell and not exists(select 1 from RRL_IW_GROUP_DISPATCH dispatched where dispatched.BIND_OPERATION_ID=b.OPERATION_ID)and b.ROOT_UID in(
    select U from json_table(nodes,'$[*]'columns(U varchar2(200)path '$.uid',K varchar2(20)path '$.kind'))where K='STOCK')
   union
   select b.ST_ID from RRL_IW_RECOVERY_ST_BIND b where b.WARE_ID=v_warehouse and b.SOURCE_CELL=v_source_cell and not exists(select 1 from RRL_IW_RECOVERY_DISPATCH dispatched where dispatched.BIND_OPERATION_ID=b.OPERATION_ID)and b.ROOT_UID in( 
    select U from json_table(nodes,'$[*]'columns(U varchar2(200)path '$.uid',K varchar2(20)path '$.kind'))where K='STOCK') 
   order by 1) loop  
   st:=ct.LEGACY_SBORKA_PALLET_ID;if st is null then raise_application_error(-20886,'HU_SHIP_CASE_BINDING_REQUIRED');end if;  
   select PALLET_UID into ident from RRL_SBORKA_PALLETS where ID=st;  
   sub:=json_object_t();src:=json_object_t();src.put('pallet_identifier',ident);  
   sub.put('command_type','SHIP_PALLET');sub.put('operation_id',p_operation);sub.put('source',src);sub.put('metadata',json_object_t());  
   RRL_STOCK_SHIPPING_CORE.compile_shipment(sub.to_clob,p_operation,p,q,dom,true);  
   subdomain:=json_object_t.parse(dom);RRL_STOCK_QC_GATE.assert_approved(dom);  
   total:=total+subdomain.get_array('legs').get_size;if total>200 then raise_application_error(-20881,'HU_SHIP_ALLOCATION_BOUND_200');end if;  
   declare sublegs json_array_t:=subdomain.get_array('legs');leg json_object_t;begin  
    for z in 0..sublegs.get_size-1 loop  
     leg:=treat(sublegs.get(z) as json_object_t);leg_uid:=leg.get_string('uid');leg_cell:=leg.get_string('cell');leg_qty:=RRL_STOCK_MATH.quantity(leg.get_string('quantity'));  
     if not expected_qty.exists(leg_uid) or leg_cell!=snap.get_string('cell') then raise_application_error(-20886,'HU_SHIP_ALLOCATION_OUTSIDE_PHYSICAL_TREE');end if;  
     if not consumed_qty.exists(leg_uid) then consumed_qty(leg_uid):=0;end if;  
     consumed_qty(leg_uid):=consumed_qty(leg_uid)+leg_qty;  
    end loop;  
   end;  
   x:=json_object_t();x.put('request',sub);x.put('domain',subdomain);plans.append(x);  
   append_all(f,json_array_t.parse(p));append_all(r,json_array_t.parse(q));  
  end loop;  
  if plans.get_size=0 then raise_application_error(-20886,'HU_SHIP_BOUND_SHIPMENT_REQUIRED');end if;  
  leg_uid:=expected_qty.first;  
  while leg_uid is not null loop  
   if not consumed_qty.exists(leg_uid) or consumed_qty(leg_uid)!=expected_qty(leg_uid) then raise_application_error(-20886,'HU_SHIP_WHOLE_PHYSICAL_LEAF_BINDING_REQUIRED');end if;  
   leg_uid:=expected_qty.next(leg_uid);  
  end loop;  
  for i in 0..plans.get_size-1 loop 
   x:=treat(plans.get(i)as json_object_t);subdomain:=x.get_object('domain'); 
   if subdomain.has('interwarehouse_onward_source')and(plans.get_size!=1 or expected_qty.count!=1)then
    for t in(select UID_VALUE,ARTICLE_VALUE,KIND_VALUE from json_table(nodes,'$[*]'columns(UID_VALUE varchar2(200)path '$.uid',ARTICLE_VALUE varchar2(160)path '$.article',KIND_VALUE varchar2(20)path '$.kind')))loop
     if t.KIND_VALUE not in('CONTAINER','STOCK')then raise_application_error(-20886,'INTERWARE_CONSOLIDATED_STOCK_ONLY_REQUIRED');end if;
     if t.KIND_VALUE='STOCK'then
      select count(*),json_arrayagg(json_object('system_code'value SYSTEM_CODE,'profile_code'value PROFILE_CODE,'profile_version'value PROFILE_VERSION,'scan_mode'value SCAN_MODE)order by SYSTEM_CODE,PROFILE_CODE returning clob)into v_profile_count,v_profiles from RRL_SKU_RECEIPT_PROFILE where ARTICUL=t.ARTICLE_VALUE;
      select count(*)into leg_count from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=t.UID_VALUE;
      if leg_count>0 and v_profile_count=0 then raise_application_error(-20886,'INTERWARE_CONSOLIDATED_SERIALIZED_PROFILE_REQUIRED');end if;
      if v_profile_count>0 then
       select count(*)into leg_count from RRL_SKU_RECEIPT_PROFILE where ARTICUL=t.ARTICLE_VALUE and SCAN_MODE not in('UNIT','UNIT_OR_AGGREGATION');
       if leg_count>0 and not subdomain.get_object('interwarehouse_onward_source').has('group_receipt_operation_id') then raise_application_error(-20886,'INTERWARE_CONSOLIDATED_UNIT_SCAN_MODE_REQUIRED');end if;
      else v_profiles:=json_array_t().to_clob;end if;

     end if;
    end loop;
   end if;
  end loop; 
  a:=snap.get_array('links');  
  for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);  
   if x.get_number('id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));end if;  
  end loop;  
  for c in(select TASK_ID,CELL_SLOT_ID from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=v_uid and STATUS='OCCUPIED') loop  
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(c.TASK_ID));  
   RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(c.CELL_SLOT_ID));  
  end loop;  
  RRL_STOCK_HU_LOAD_CORE.compile_load(p_request,snap.to_clob,plans.to_clob,f,r,loading_domain);  
  v.put('loading',loading_domain);  
  v.put('uid',v_uid);v.put('snapshot',snap);v.put('signature',digest(s));v.put('shipments',plans);v.put('allocation_count',total);  
  p_domain:=v.to_clob;p_resources:=r.to_clob;p_policies:=f.to_clob;  
 end;  
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is  
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');op varchar2(100):=d.get_string('operation_id');plan clob;  
  v json_object_t;snap json_object_t;a json_array_t;entry json_object_t;subdomain json_object_t;req json_object_t;j json_object_t:=json_object_t();results json_array_t:=json_array_t();  
  v_uid varchar2(200);alias varchar2(32);nodes clob;shipments clob;offset_no number:=0;n number;result clob;dom clob;ident varchar2(200);  
 begin  
  if RRL_HAS_WRIGHT(p_actor,'CLOSE_OTHOD_NAKLAD')!=1 and RRL_HAS_WRIGHT(p_actor,'stock_posting_shipping')!=1 then raise_application_error(-20882,'SHIPPING_FORBIDDEN');end if;  
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');  
  v_uid:=v.get_string('uid');snap:=v.get_object('snapshot');nodes:=snap.get_array('nodes').to_clob;shipments:=v.get_array('shipments').to_clob;  
  select SSCC into alias from RRL_PALLETS where UID_PALLET=v_uid;  
  if m.get_string('scan_container') is null or(m.get_string('scan_container')!=v_uid and(alias is null or m.get_string('scan_container')!=alias))  
   or m.get_string('scan_cell') is null or m.get_string('scan_cell')!=snap.get_string('cell') then raise_application_error(-20886,'HU_SHIP_CONTAINER_CELL_SCAN_REQUIRED');end if;  
  if v.has('loading') and not v.get('loading').is_null then  
   if RRL_HAS_WRIGHT(p_actor,'stock_posting_shipping')!=1 then raise_application_error(-20882,'PHYSICAL_LOAD_FORBIDDEN');end if;  
   RRL_STOCK_HU_LOAD_CORE.begin_load(v.get_object('loading').to_clob);  
  end if;  
  -- All real ST rows precede all CASE rows; logical closure was acquired globally by root.  
  for z in(select ID from RRL_SBORKA_PALLETS where ID in(select ID from json_table(shipments,'$[*]' columns(ID number path '$.domain.document_id'))) order by ID) loop select ID into n from RRL_SBORKA_PALLETS where ID=z.ID for update;end loop;  
  for z in(select CASE_PICK_TASK_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(select ID from json_table(nodes,'$[*]' columns(ID number path '$.case_task_id'))) order by CASE_PICK_TASK_ID) loop select CASE_PICK_TASK_ID into n from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=z.CASE_PICK_TASK_ID for update;end loop;  
  if digest(RRL_STOCK_HU_READ.snapshot_json(v_uid))!=v.get_string('signature') then raise_application_error(-20890,'CLOSURE_CHANGED: HU shipment tree');end if;  
  a:=v.get_array('shipments');  
  -- Recheck all approvals before any leg; later execution also rechecks its own frozen plan.  
  for i in 0..a.get_size-1 loop entry:=treat(a.get(i) as json_object_t);dom:=entry.get_object('domain').to_clob;RRL_STOCK_QC_GATE.assert_approved(dom);end loop;  
  for i in 0..a.get_size-1 loop  
   entry:=treat(a.get(i) as json_object_t);req:=entry.get_object('request');subdomain:=entry.get_object('domain');  
   RRL_STOCK_SHIPPING_CORE.execute_resolved(req.to_clob,subdomain.to_clob,offset_no,p_actor,result);  
   results.append(json_object_t.parse(result));offset_no:=offset_no+subdomain.get_array('legs').get_size;  
  end loop;  
  a:=snap.get_array('links');  
  for i in 0..a.get_size-1 loop entry:=treat(a.get(i) as json_object_t);n:=entry.get_number('id');  
   if n is not null then update RRL_WMS_HU_LINK set ACTIVE_FLAG=0,LINK_VERSION=LINK_VERSION+1,UNLINKED_OPERATION_ID=op,UNLINKED_AT=systimestamp,UNLINKED_BY=p_actor where HU_LINK_ID=n and ACTIVE_FLAG=1;  
    if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: HU departure link');end if;end if;  
  end loop;  
  a:=snap.get_array('nodes');  
  for i in 0..a.get_size-1 loop entry:=treat(a.get(i) as json_object_t);ident:=entry.get_string('uid');  
   if entry.get_string('kind')='CONTAINER' then  
    update RRL_PALLETS set HU_CURRENT_CELL=null,HU_SHIPPED_OPERATION=op,HU_CONTENT_VERSION=HU_CONTENT_VERSION+1 where UID_PALLET=ident and HU_SHIPPED_OPERATION is null;  
    if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: HU departure');end if;  
    delete from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=ident and STATUS='OCCUPIED';  
   end if;  
  end loop;  
  if v.has('loading') and not v.get('loading').is_null then  
   RRL_STOCK_HU_LOAD_CORE.finish_load(v.get_object('loading').to_clob,snap.to_clob,op,p_actor);j.put('physical_load',v.get_object('loading'));  
  end if;  
  j.put('operation_id',op);j.put('status','SHIPPED');j.put('uid',v_uid);j.put('shipments',results);j.put('composition_at_departure',snap);j.put('top_place_count',1);  
  p_result:=j.to_clob;  
 end;  
end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_SLOT as

 procedure occupied_load(p_cell varchar2,p_ignored_task number,p_replace_root varchar2,p_weight out number,p_volume out number) is

  type keys is table of number index by varchar2(200);covered keys;tree json_object_t;a json_array_t;x json_object_t;

  roots number:=0;nodes number:=0;claims number;w number;v number;cv number;version_no number;stock_epoch number;unit_sig varchar2(64);saved_sig varchar2(64);unit_count number;

 begin

  p_weight:=0;p_volume:=0;

  if p_replace_root is not null then

   if substr(p_replace_root,1,5)='CASE:'then

    tree:=json_object_t.parse(RRL_STOCK_HU_READ.case_snapshot_json(to_number(substr(p_replace_root,6))));

   else tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(p_replace_root));end if;a:=tree.get_array('nodes');

   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);

    if x.get_string('kind')='STOCK' then covered(x.get_string('uid')):=1;end if;

   end loop;

  end if;

  for pp in(select UID_PALLET,HU_CONTENT_VERSION from RRL_PALLETS where case when HU_KIND='CONTAINER' then HU_CURRENT_CELL end=p_cell and(p_replace_root is null or UID_PALLET!=p_replace_root)

   and not exists(select 1 from RRL_WMS_HU_LINK h where h.CHILD_PALLET_UID=UID_PALLET and h.ACTIVE_FLAG=1) order by UID_PALLET fetch first 201 rows only) loop

   roots:=roots+1;if roots>200 then raise_application_error(-20881,'HU_CELL_PLACE_BOUND_200');end if;

   select count(*),min(HU_GROSS_WEIGHT_KG),min(HU_BOUNDING_VOLUME_M3),min(HU_COMPOSITION_VERSION)

    into claims,w,v,cv from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=pp.UID_PALLET and CELL=p_cell and STATUS='OCCUPIED';

   if claims!=1 or w is null or v is null or cv is null or cv!=pp.HU_CONTENT_VERSION then raise_application_error(-20886,'HU_CELL_EXISTING_MEASUREMENTS_REQUIRED');end if;

   tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(pp.UID_PALLET));a:=tree.get_array('nodes');

   nodes:=nodes+a.get_size;if nodes>20000 then raise_application_error(-20881,'HU_CELL_COMPOSITION_BOUND_20000');end if;

   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);

    if x.get_string('kind')='STOCK' then covered(x.get_string('uid')):=1;end if;

   end loop;

   p_weight:=p_weight+w;p_volume:=p_volume+v;

  end loop;

  for pp in(select p.UID_PALLET,p.HU_CONTENT_VERSION,p.STOCK_COMPOSITION_VERSION from RRL_PALLETS p

   where p.HU_KIND='STOCK' and exists(select 1 from RRL_REMAINS r where r.UID_POLETA=p.UID_PALLET and r.CELL=p_cell and r.REMAIN>0)

   and(p_replace_root is null or p.UID_PALLET!=p_replace_root)

   and not exists(select 1 from RRL_WMS_HU_LINK h where h.CHILD_PALLET_UID=p.UID_PALLET and h.ACTIVE_FLAG=1)

   and not exists(select 1 from RRL_CASE_CARRIER_LOT ct where ct.LOT_UID=p.UID_PALLET)

   order by p.UID_PALLET fetch first 201 rows only) loop

   roots:=roots+1;if roots>200 then raise_application_error(-20881,'HU_CELL_PLACE_BOUND_200');end if;

   select count(*),min(HU_GROSS_WEIGHT_KG),min(HU_BOUNDING_VOLUME_M3),min(HU_COMPOSITION_VERSION),min(HU_STOCK_COMPOSITION_VERSION),min(HU_UNIT_SIGNATURE)

    into claims,w,v,cv,stock_epoch,saved_sig from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=pp.UID_PALLET and CELL=p_cell and STATUS='OCCUPIED';

   if claims!=1 or w is null or v is null or cv is null or cv!=pp.HU_CONTENT_VERSION or stock_epoch is null

    or stock_epoch!=pp.STOCK_COMPOSITION_VERSION or saved_sig is null then raise_application_error(-20886,'STOCK_PLACE_FRESH_MEASUREMENTS_REQUIRED');end if;

   RRL_STOCK_HU_UNIT_SIGNATURE.describe_units(pp.UID_PALLET,null,unit_sig,unit_count);

   nodes:=nodes+unit_count;if nodes>20000 then raise_application_error(-20881,'HU_CELL_COMPOSITION_BOUND_20000');end if;

   if saved_sig!=unit_sig then raise_application_error(-20886,'STOCK_PLACE_PHYSICAL_MEMBERS_CHANGED');end if;

   covered(pp.UID_PALLET):=1;p_weight:=p_weight+w;p_volume:=p_volume+v;

  end loop;

  for ct in(select CASE_PICK_TASK_ID,CONTENT_VERSION from RRL_CASE_PICK_TASK where CURRENT_CELL=p_cell and STATUS in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP')

   and(p_replace_root is null or 'CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(CASE_PICK_TASK_ID)!=p_replace_root)

   and not exists(select 1 from RRL_WMS_HU_LINK h where h.CHILD_CASE_TASK_ID=CASE_PICK_TASK_ID and h.ACTIVE_FLAG=1)

   order by CASE_PICK_TASK_ID fetch first 201 rows only) loop

   roots:=roots+1;if roots>200 then raise_application_error(-20881,'HU_CELL_PLACE_BOUND_200');end if;

   select count(*),min(HU_GROSS_WEIGHT_KG),min(HU_BOUNDING_VOLUME_M3),min(HU_COMPOSITION_VERSION) into claims,w,v,cv from RRL_RECEIPT_SLOT_CLAIM

    where HU_CASE_TASK_ID=ct.CASE_PICK_TASK_ID and CELL=p_cell and STATUS='OCCUPIED';

   if claims!=1 or w is null or v is null or cv is null or cv!=ct.CONTENT_VERSION then raise_application_error(-20886,'CASE_PLACE_FRESH_MEASUREMENTS_REQUIRED');end if;

   tree:=json_object_t.parse(RRL_STOCK_HU_READ.case_snapshot_json(ct.CASE_PICK_TASK_ID));a:=tree.get_array('nodes');

   nodes:=nodes+a.get_size;if nodes>20000 then raise_application_error(-20881,'HU_CELL_COMPOSITION_BOUND_20000');end if;

   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);if x.get_string('kind')='STOCK' then covered(x.get_string('uid')):=1;end if;end loop;

   p_weight:=p_weight+w;p_volume:=p_volume+v;

  end loop;

  for rr in(select UID_POLETA from RRL_REMAINS where CELL=p_cell and(REMAIN>0 or HARD_RESERVED_BASE>0) order by UID_POLETA fetch first 20001 rows only) loop

   if not covered.exists(rr.UID_POLETA) then raise_application_error(-20886,'HU_CELL_UNSLOTTED_OR_UNMEASURED_STOCK');end if;

  end loop;

  for wt in(select TASK_ID,TO_CELL_SLOT_ID,HU_MEASUREMENTS_JSON from RRL_WAREHOUSE_TASK where TO_CELL=p_cell and STATUS not in('DONE','CANCELLED')

   and(p_ignored_task is null or TASK_ID!=p_ignored_task) order by TASK_ID fetch first 201 rows only) loop

   roots:=roots+1;if roots>200 then raise_application_error(-20881,'HU_CELL_PLACE_BOUND_200');end if;

   if wt.TO_CELL_SLOT_ID is null or wt.HU_MEASUREMENTS_JSON is null then raise_application_error(-20886,'HU_CELL_ARRIVAL_MEASUREMENTS_REQUIRED');end if;

   x:=json_object_t.parse(wt.HU_MEASUREMENTS_JSON);

   w:=RRL_STOCK_MATH.quantity(x.get_string('gross_weight_kg'));

   v:=ceil(RRL_STOCK_MATH.quantity(x.get_string('width_m'))*RRL_STOCK_MATH.quantity(x.get_string('depth_m'))*RRL_STOCK_MATH.quantity(x.get_string('height_m'))*1000000000)/1000000000;

   if w is null or v is null or least(w,v)<=0 then raise_application_error(-20886,'HU_CELL_ARRIVAL_MEASUREMENTS_REQUIRED');end if;

   p_weight:=p_weight+w;p_volume:=p_volume+v;

  end loop;

  -- Other receipt claims cannot be converted to SI implicitly.

  select count(*) into claims from RRL_RECEIPT_SLOT_CLAIM cl where cl.CELL=p_cell and cl.STATUS in('RESERVED','OCCUPIED')

   and not exists(select 1 from RRL_CASE_PICK_TASK ct where ct.CASE_PICK_TASK_ID=cl.HU_CASE_TASK_ID and ct.CURRENT_CELL=p_cell)

   and not exists(select 1 from RRL_PALLETS pp where pp.UID_PALLET=cl.UID_PALLET and ((pp.HU_KIND='CONTAINER' and pp.HU_CURRENT_CELL=p_cell)

    or(pp.HU_KIND='STOCK' and cl.HU_STOCK_COMPOSITION_VERSION is not null and exists(select 1 from RRL_REMAINS rr where rr.UID_POLETA=pp.UID_PALLET and rr.CELL=p_cell and rr.REMAIN>0))))

   and(p_ignored_task is null or cl.TASK_ID!=p_ignored_task) and(p_replace_root is null or cl.UID_PALLET!=p_replace_root);

  if claims>0 then raise_application_error(-20886,'HU_CELL_OTHER_RECEIPT_MEASUREMENTS_REQUIRED');end if;

 end;

 function target_json(p_tree clob,p_metadata clob,p_ignored_task number,p_replace_root varchar2 default null,p_extra_weight number default 0,p_extra_volume number default 0) return clob is

  j json_object_t:=json_object_t.parse(p_tree);m json_object_t:=json_object_t.parse(p_metadata);z json_object_t:=json_object_t();

  measures json_object_t;a json_array_t;x json_object_t;c RRL_CELLS%rowtype;s RRL_TOPOLOGY_CELL_SLOT%rowtype;

  v_slot number:=m.get_number('target_slot_id');v_task number:=m.get_number('planned_physical_task_id');v_count number;v_latest number;v_tc number;v_top_weight number;v_top_volume number;v_code varchar2(100);

  v_existing_mass number:=0;v_existing_volume number:=0;v_mass number;v_width number;v_depth number;v_height number;v_volume number;v_tare number:=0;v_lower number:=0;v_unit varchar2(2);v_scale number;v_article varchar2(160);v_cell varchar2(60):=m.get_string('target_cell');

 begin

  if p_extra_weight is null or p_extra_volume is null or least(p_extra_weight,p_extra_volume)<0 then raise_application_error(-20871,'HU_EXTRA_LOAD_INVALID');end if;

  select * into c from RRL_CELLS where CELL=v_cell;

  if c.WARE_ID!=j.get_number('warehouse') or nvl(c.OTBOR,0)!=0 then raise_application_error(-20886,'HU_STORAGE_OR_CASE_STAGING_REQUIRED');end if;

  if nvl(c.IS_SYSTEM,0)!=0 and m.get_string('group_receipt_operation_id') is not null then
   declare v_receipt varchar2(100):=m.get_string('group_receipt_operation_id');v_root varchar2(200):=j.get_string('root');v_from varchar2(60):=j.get_string('cell');v_ware number:=j.get_number('warehouse');v_match number;
   begin
    select count(*)into v_match from RRL_IW_GROUP_RECEIPT r join RRL_IW_GROUP_PLAN p on p.OPERATION_ID=r.PLAN_OPERATION_ID
     where r.OPERATION_ID=v_receipt and r.ROOT_UID=v_root and r.WARE_ID=v_ware and r.RECEIVE_CELL=v_from and p.OUTBOUND_DOCK=v_cell
     and not exists(select 1 from RRL_IW_GROUP_PLACEMENT done where done.RECEIPT_OPERATION_ID=r.OPERATION_ID);
    if v_match!=1 then raise_application_error(-20886,'HU_GROUP_EXACT_RECEIVED_OUTBOUND_REQUIRED');end if;
    z.put('target_role','INTERWARE_GROUP_OUTBOUND');
   end;
  elsif nvl(c.IS_SYSTEM,0)!=0 then

   a:=j.get_array('nodes');

   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);

    if x.get_string('kind')='STOCK' and x.get_number('case_task_id') is null then raise_application_error(-20886,'HU_SYSTEM_TARGET_ONLY_CLOSED_CASE_CARRIERS');end if;

   end loop;

   z.put('target_role','CASE_CONTROL_OR_STAGING');

  else z.put('target_role','ORDINARY_STORAGE');end if;

  if nvl(c.BLOCKED_FOR_REMAINS,0)!=0 or nvl(c.BLOCKED_FOR_POPOLNENIE,0)!=0 or nvl(c.BLOCKED_FOR_ACCEPT,0)!=0 then raise_application_error(-20879,'LOCATION_BLOCKED');end if;

  select max(TOPOLOGY_ID) into v_latest from RRL_WAREHOUSE_TOPOLOGY where WARE_ID=c.WARE_ID and STATUS='PUBLISHED';

  select count(*) into v_count from RRL_TOPOLOGY_CELL_SLOT sl join RRL_TOPOLOGY_CELL tc on tc.TOPOLOGY_CELL_ID=sl.TOPOLOGY_CELL_ID

   where sl.ACTIVE=1 and sl.SLOT_KIND='STORAGE_SLOT' and tc.ACTIVE=1 and tc.LEGACY_CELL_CODE=v_cell and tc.TOPOLOGY_ID=v_latest;

  if v_slot is null and v_count>0 then raise_application_error(-20886,'HU_PHYSICAL_SLOT_REQUIRED');end if;

  if v_slot is not null then

   if p_ignored_task is null and v_task is null then raise_application_error(-20886,'HU_SLOT_REQUIRES_EXISTING_TASK_PLAN');end if;

   begin

    select sl.* into s from RRL_TOPOLOGY_CELL_SLOT sl

     join RRL_TOPOLOGY_CELL tc on tc.TOPOLOGY_CELL_ID=sl.TOPOLOGY_CELL_ID

     where sl.CELL_SLOT_ID=v_slot and sl.ACTIVE=1 and sl.SLOT_KIND='STORAGE_SLOT' and tc.ACTIVE=1

      and tc.LEGACY_CELL_CODE=v_cell and tc.WARE_ID=c.WARE_ID and tc.TOPOLOGY_ID=v_latest;

   exception when no_data_found then raise_application_error(-20886,'HU_SLOT_NOT_CURRENT_STORAGE');end;

   v_code:=s.SLOT_CODE;

   select MAX_WEIGHT_KG,MAX_VOLUME_M3 into v_top_weight,v_top_volume from RRL_TOPOLOGY_CELL where TOPOLOGY_CELL_ID=s.TOPOLOGY_CELL_ID;

   if nvl(s.CAPACITY_QTY,1)<1 then raise_application_error(-20886,'HU_SLOT_ONE_PLACE_CAPACITY_REQUIRED');end if;

   select count(*) into v_count from RRL_RECEIPT_SLOT_CLAIM where CELL_SLOT_ID=v_slot and STATUS in('RESERVED','OCCUPIED') and(p_replace_root is null or UID_PALLET!=p_replace_root);

   if v_count>0 then raise_application_error(-20886,'HU_PHYSICAL_SLOT_OCCUPIED_OR_RESERVED');end if;

   select count(*) into v_count from RRL_WAREHOUSE_TASK where TO_CELL_SLOT_ID=v_slot and STATUS not in('DONE','CANCELLED') and(p_ignored_task is null or TASK_ID!=p_ignored_task);

   if v_count>0 then raise_application_error(-20886,'HU_PHYSICAL_SLOT_PLANNED_ARRIVAL');end if;

   z.put('slot_id',v_slot);z.put('slot_code',v_code);

  end if;

  if v_slot is not null or nvl(c.LIMIT_WEIGHT,0)>0 or nvl(c.LIMIT_HEIGHT,0)>0 then

   if not m.has('measurements') or m.get('measurements').is_null then raise_application_error(-20886,'HU_FRESH_MEASUREMENTS_REQUIRED');end if;

   measures:=m.get_object('measurements');

   if measures.get_string('origin')!='MANUAL_CONFIRMED' or measures.get_number('content_version') is null

    or measures.get_number('content_version')!=treat(j.get_array('nodes').get(0) as json_object_t).get_number('version')

    then raise_application_error(-20886,'HU_MEASUREMENT_CONTENT_VERSION_REQUIRED');end if;

   v_mass:=RRL_STOCK_MATH.quantity(measures.get_string('gross_weight_kg'));

   v_width:=RRL_STOCK_MATH.quantity(measures.get_string('width_m'));v_depth:=RRL_STOCK_MATH.quantity(measures.get_string('depth_m'));

   v_height:=RRL_STOCK_MATH.quantity(measures.get_string('height_m'));

   if v_mass is null or v_width is null or v_depth is null or v_height is null or least(v_mass,v_width,v_depth,v_height)<=0 then raise_application_error(-20886,'HU_POSITIVE_SI_MEASUREMENTS_REQUIRED');end if;

   v_volume:=ceil(v_width*v_depth*v_height*1000000000)/1000000000;

   a:=j.get_array('nodes');

   for i in 0..a.get_size-1 loop

    x:=treat(a.get(i) as json_object_t);v_tare:=v_tare+nvl(x.get_number('tare_weight_kg'),0);

    if x.get_string('kind')='STOCK' and x.get_string('base_uom')='KG' then v_lower:=v_lower+RRL_STOCK_MATH.quantity(x.get_string('quantity'));end if;

   end loop;

   if v_mass<v_tare+v_lower then raise_application_error(-20886,'HU_GROSS_WEIGHT_BELOW_NET_AND_TARE');end if;

   if v_slot is not null then occupied_load(v_cell,p_ignored_task,p_replace_root,v_existing_mass,v_existing_volume);end if;

   if nvl(c.LIMIT_WEIGHT,0)>0 and v_mass+v_existing_mass+p_extra_weight>c.LIMIT_WEIGHT then raise_application_error(-20886,'HU_CELL_WEIGHT_EXCEEDED');end if;

   if nvl(c.LIMIT_HEIGHT,0)>0 then

    begin select HU_CELL_HEIGHT_UNIT into v_unit from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=c.WARE_ID;

    exception when no_data_found then v_unit:=null;end;

    if v_unit is null then raise_application_error(-20886,'HU_LEGACY_CELL_HEIGHT_UNIT_REQUIRED');end if;

    v_scale:=case v_unit when 'M' then 1 when 'CM' then 0.01 when 'MM' then 0.001 end;

    if v_height>c.LIMIT_HEIGHT*v_scale then raise_application_error(-20886,'HU_CELL_HEIGHT_EXCEEDED');end if;

   end if;

   if v_slot is not null then

    if(nvl(v_top_weight,0)>0 and v_mass+v_existing_mass+p_extra_weight>v_top_weight) or(nvl(v_top_volume,0)>0 and v_volume+v_existing_volume+p_extra_volume>v_top_volume) then raise_application_error(-20886,'HU_TOPOLOGY_CELL_WEIGHT_OR_VOLUME_EXCEEDED');end if;

    if (nvl(s.CAPACITY_WEIGHT_KG,0)>0 and v_mass>s.CAPACITY_WEIGHT_KG)

     or(nvl(s.CAPACITY_VOLUME_M3,0)>0 and v_volume>s.CAPACITY_VOLUME_M3)

     or(nvl(s.WIDTH_M,0)>0 and v_width>s.WIDTH_M) or(nvl(s.DEPTH_M,0)>0 and v_depth>s.DEPTH_M)

     or(nvl(s.HEIGHT_M,0)>0 and v_height>s.HEIGHT_M) then raise_application_error(-20886,'HU_SLOT_WEIGHT_VOLUME_OR_DIMENSIONS_EXCEEDED');end if;

   end if;

   measures.put('bounding_volume_m3',RRL_STOCK_PLAN_HELPER.decimal_text(v_volume));z.put('measurements',measures);

  end if;

  a:=j.get_array('nodes');

  for i in 0..a.get_size-1 loop

   x:=treat(a.get(i) as json_object_t);

   if x.get_string('kind')='STOCK' then

    v_article:=x.get_string('article');

    select count(*) into v_count from RRL_RECEIPT_SKU_RULE r left join RRL_RECEIPT_CELL_RULE cr on cr.CELL=v_cell and cr.WARE_ID=c.WARE_ID

     where r.WARE_ID=c.WARE_ID and r.ARTICUL=v_article

      and ((r.TEMP_MIN is not null and(cr.TEMP_MIN is null or cr.TEMP_MIN<r.TEMP_MIN))

       or(r.TEMP_MAX is not null and(cr.TEMP_MAX is null or cr.TEMP_MAX>r.TEMP_MAX)));

    if v_count>0 then raise_application_error(-20886,'HU_TARGET_TEMPERATURE_RULE_FAILED');end if;

   end if;

  end loop;

  return z.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_SLOT_MOVE_CMD as
 function digest(s clob) return varchar2 is begin return rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256));end;
 function snapshot(p_uid varchar2,p_case number)return clob is begin
  if p_case is null then return RRL_STOCK_HU_READ.snapshot_json(p_uid);end if;
  if p_uid!='CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_case)then raise_application_error(-20886,'CASE_SLOT_IDENTITY_CONFLICT');end if;
  return RRL_STOCK_HU_READ.case_snapshot_json(p_case);
 end;
 function placement(p_tree clob,p_metadata clob,p_uid varchar2,p_task number) return clob is
  m json_object_t:=json_object_t.parse(p_metadata);tree json_object_t:=json_object_t.parse(p_tree);
 begin
  m.put('target_cell',tree.get_string('cell'));m.put('planned_physical_task_id',p_task);
  return RRL_STOCK_HU_SLOT.target_json(p_tree,m.to_clob,null,p_uid);
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t:=json_object_t();tree json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();s clob;v_uid varchar2(200):=d.get_object('source').get_string('uid');
  v_old_task number;v_old_slot number;v_slot number:=m.get_number('target_slot_id');v_task number;v_sync number;v_cell varchar2(60);v_placement clob;v_case number:=m.get_number('case_task_id');
 begin
  s:=snapshot(v_uid,v_case);tree:=json_object_t.parse(s);v_cell:=tree.get_string('cell');
  if tree.get_array('ancestors').get_size>0 or treat(tree.get_array('nodes').get(0) as json_object_t).get_string('kind') not in('CONTAINER','STOCK','CASE') then raise_application_error(-20886,'HU_SLOT_MOVE_TOP_CONTAINER_WITH_STOCK_REQUIRED');end if;
  if m.get_number('expected_version') is null or m.get_number('expected_version')!=treat(tree.get_array('nodes').get(0) as json_object_t).get_number('version') then raise_application_error(-20890,'CLOSURE_CHANGED: HU slot movement version');end if;
  begin select TASK_ID,CELL_SLOT_ID into v_old_task,v_old_slot from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=v_uid and CELL=v_cell and STATUS='OCCUPIED';
  exception when no_data_found then raise_application_error(-20886,'HU_SLOT_MOVE_EXISTING_PLACEMENT_REQUIRED');end;
  if v_slot is null or v_slot=v_old_slot then raise_application_error(-20886,'HU_SLOT_MOVE_DIFFERENT_SLOT_REQUIRED');end if;
  v_task:=RRL_WAREHOUSE_TASK_SQ.nextval;v_sync:=RRL_WH_TASK_SYNC_SQ.nextval;
  v_placement:=placement(s,m.to_clob,v_uid,v_task);
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.fence(f,'CELL',v_cell,6);
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||digest(to_clob(p_operation)));
  RRL_STOCK_HU_CMD.declare_tree(f,r,s);
  RRL_STOCK_CASE_BIND_MOVE.plan_tree(tree.get_array('nodes'),r,v);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(v_old_task));
  RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(v_old_slot));
  RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(v_slot));
  RRL_STOCK_HU_PLACEMENT_CORE.declare_place(r,v_task,v_sync);
  v.put('case_task_id',v_case);v.put('uid',v_uid);v.put('snapshot',tree);v.put('signature',digest(s));v.put('placement',json_object_t.parse(v_placement));
  v.put('old_claim_task',v_old_task);v.put('old_slot',v_old_slot);v.put('slot',v_slot);v.put('task',v_task);v.put('sync',v_sync);
  p_domain:=v.to_clob;p_resources:=r.to_clob;p_policies:=f.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');op varchar2(100):=d.get_string('operation_id');
  plan clob;v json_object_t;tree json_object_t;s clob;new_placement clob;nodes clob;j json_object_t:=json_object_t();
  v_uid varchar2(200);v_cell varchar2(60);alias varchar2(32);code varchar2(100);old_task number;old_slot number;target_slot number;v_ware number;rid number;v_case number;v_case_before RRL_CASE_PICK_TASK%rowtype;v_nodes clob;v_locked_id number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'HU_EXECUTION_FORBIDDEN');end if;
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  v_case:=v.get_number('case_task_id');v_uid:=v.get_string('uid');tree:=v.get_object('snapshot');v_cell:=tree.get_string('cell');v_ware:=tree.get_number('warehouse');old_task:=v.get_number('old_claim_task');old_slot:=v.get_number('old_slot');target_slot:=v.get_number('slot');
  if v_case is null then select SSCC into alias from RRL_PALLETS where UID_PALLET=v_uid;
  else select SSCC into alias from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case;end if;
  if m.get_string('scan_container') is null or(m.get_string('scan_container')!=v_uid and(alias is null or m.get_string('scan_container')!=alias))
   or m.get_string('scan_cell') is null or m.get_string('scan_cell')!=v_cell then raise_application_error(-20886,'HU_SLOT_MOVE_CONTAINER_CELL_SCAN_REQUIRED');end if;
  select SLOT_CODE into code from RRL_TOPOLOGY_CELL_SLOT where CELL_SLOT_ID=old_slot;
  if m.get_string('scan_from_slot') is null or m.get_string('scan_from_slot')!=code then raise_application_error(-20886,'HU_SLOT_MOVE_FROM_SLOT_SCAN_REQUIRED');end if;
  select SLOT_CODE into code from RRL_TOPOLOGY_CELL_SLOT where CELL_SLOT_ID=target_slot;
  if m.get_string('scan_to_slot') is null or m.get_string('scan_to_slot')!=code then raise_application_error(-20886,'HU_SLOT_MOVE_TO_SLOT_SCAN_REQUIRED');end if;
  v_nodes:=tree.get_array('nodes').to_clob;
  -- Actual row locks match the existing shipping/HU ST-before-CASE order.
  for st in(select ID from RRL_SBORKA_PALLETS where ID in(
   select LEGACY_SBORKA_PALLET_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(
    select CASE_ID from json_table(v_nodes,'$[*]' columns(CASE_ID number path '$.case_task_id')))) order by ID) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(st.ID)));
   select ID into v_locked_id from RRL_SBORKA_PALLETS where ID=st.ID for update;
  end loop;
  for ct in(select CASE_PICK_TASK_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(
   select CASE_ID from json_table(v_nodes,'$[*]' columns(CASE_ID number path '$.case_task_id'))) order by CASE_PICK_TASK_ID) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(ct.CASE_PICK_TASK_ID)));
   select CASE_PICK_TASK_ID into v_locked_id from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=ct.CASE_PICK_TASK_ID for update;
  end loop;
  RRL_STOCK_CASE_BIND_MOVE.validate_tree(tree.get_array('nodes'),v);
  if v_case is not null then select *into v_case_before from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case;end if;
  s:=snapshot(v_uid,v_case);
  if digest(s)!=v.get_string('signature') then raise_application_error(-20890,'CLOSURE_CHANGED: HU slot composition');end if;
  new_placement:=placement(s,m.to_clob,v_uid,v.get_number('task'));
  if dbms_lob.compare(new_placement,v.get_object('placement').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: HU target slot');end if;
  delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=old_task and UID_PALLET=v_uid and CELL_SLOT_ID=old_slot and STATUS='OCCUPIED';
  if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: HU source claim');end if;
  if v_case is null then
  update RRL_PALLETS set HU_CONTENT_VERSION=HU_CONTENT_VERSION+1 where UID_PALLET=v_uid and HU_SHIPPED_OPERATION is null;
  else
   update RRL_CASE_PICK_TASK set CONTENT_VERSION=CONTENT_VERSION+1,STATUS='WAIT_CONTROL',UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=v_case and CURRENT_CELL=v_cell and STATUS in('WAIT_CONTROL','CONTROLLED','READY_TO_SHIP');
  end if;
  if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: HU active placement');end if;
  if v_case is not null then
   RRL_STOCK_CASE_BIND_MOVE.finish_move(v_case_before,RRL_STOCK_CASE_BIND_MOVE.binding_for(v,v_case),v_case_before.CONTENT_VERSION+1,p_actor);
  end if;
  RRL_STOCK_HU_PLACEMENT_CORE.record_place(p_request,p_actor,v_uid,v_ware,v_cell,v.get_number('task'),target_slot,v.get_number('sync'),new_placement,v_case);
  nodes:=tree.get_array('nodes').to_clob;
  for rr in(select RESERVATION_ID,UID_PALLET,CELL,BASE_QTY from RRL_STOCK_RESERVATION where UID_PALLET in(
   select U from json_table(nodes,'$[*]' columns(U varchar2(200) path '$.uid',K varchar2(20) path '$.kind')) where K='STOCK')
   and CELL=v_cell and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_QTY>0 order by RESERVATION_ID) loop
   RRL_STOCK_RESERVE_CORE.move_coverage(rr.RESERVATION_ID,rr.RESERVATION_ID,rr.UID_PALLET,rr.CELL,v_ware,rr.BASE_QTY,target_slot,p_actor,rid);
   if rid!=rr.RESERVATION_ID then raise_application_error(-20869,'HU_SLOT_MOVE_RESERVATION_IDENTITY_CHANGED');end if;
  end loop;
  j:=json_object_t.parse(snapshot(v_uid,v_case));j.put('operation_id',op);j.put('command','HU_RELOCATE_SLOT');j.put('task_id',v.get_number('task'));j.put('pallet_identifier',v_uid);j.put('slot_id',target_slot);j.put('quantity_unchanged',true);
  p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_TASK as

 function proxy_request(p_request clob,t RRL_WAREHOUSE_TASK%rowtype) return clob is

  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');src json_object_t:=json_object_t();

 begin

  if d.get_string('command_type')='HU_PLAN_MOVE' then

   d.put('command_type','HU_MOVE');return d.to_clob;

  end if;

  declare v_group_receipt varchar2(100);begin

   select max(RECEIPT_OPERATION_ID)into v_group_receipt from RRL_IW_GROUP_PUT_PLAN where TASK_ID=t.TASK_ID;

   if v_group_receipt is not null then m.put('group_receipt_operation_id',v_group_receipt);

   else m.remove('group_receipt_operation_id');end if;

  end;

  src.put('uid',t.UID_PALLET);d.put('source',src);d.put('command_type','HU_TASK_COMPLETE');

  m.put('expected_version',t.HU_CONTENT_VERSION);m.put('target_cell',t.TO_CELL);m.put('physical_task_id',t.TASK_ID);

  m.put('target_slot_id',t.TO_CELL_SLOT_ID);

  if t.HU_MEASUREMENTS_JSON is not null then m.put('measurements',json_object_t.parse(t.HU_MEASUREMENTS_JSON));end if;

  m.put('scan_container',m.get_string('scanned_pallet'));d.put('metadata',m);return d.to_clob;

 end;

 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is

  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;ctx json_object_t;

  t RRL_WAREHOUSE_TASK%rowtype;pr clob;f json_array_t;r json_array_t;v_id number;v_sync number;v_key varchar2(400);iw_count number;

 begin

  if d.get_string('command_type')='HU_PLAN_MOVE' then

   select RRL_WAREHOUSE_TASK_SQ.nextval into v_id from dual;

   m.put('planned_physical_task_id',v_id);d.put('metadata',m);pr:=proxy_request(d.to_clob,t);

   RRL_STOCK_HU_CMD.compile_command(pr,p_operation,p_policies,p_resources,p_domain,p_defer_wait_planning=>true);

   v:=json_object_t.parse(p_domain);r:=json_array_t.parse(p_resources);

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));

   if m.get_string('group_receipt_operation_id')is not null then

    declare group_value json_object_t;begin

     RRL_IW_GROUP_PUT.describe_receipt(m.get_string('group_receipt_operation_id'),v.get_string('target'),d.get_string('actor'),null,group_value);

     if group_value.get_string('uid')!=v.get_string('uid')then raise_application_error(-20886,'INTERWARE_GROUP_PLACEMENT_ROOT_REQUIRED');end if;

     RRL_IW_GROUP_PUT.declare_rows(group_value,p_operation,r);v.put('group_placement',group_value);

    end;

   end if;

   RRL_ST_DEFER_HU_WAIT.declare_plan(p_request,v_id,r,v);
   v.put('task_id',v_id);v.put('planning',1);p_domain:=v.to_clob;p_resources:=r.to_clob;

  else

   v_id:=d.get_object('source').get_number('task_id');

   select * into t from RRL_WAREHOUSE_TASK where TASK_ID=v_id;

   if t.HU_CONTENT_VERSION is null or t.TASK_SOURCE!='MANUAL' or t.SOURCE_DOC_TYPE!='WAREHOUSE_HU'

    or t.TASK_TYPE!='PUTAWAY' or t.UNIT_CODE!='HU' or t.QTY_MODE!='PALLET' or t.QTY!=1

    or t.STATUS not in('PLANNED','ASSIGNED','IN_PROGRESS') then raise_application_error(-20886,'HU_TASK_CONTRACT_OR_STATE_INVALID');end if;

   if m.has('fact_qty') and not m.get('fact_qty').is_null and RRL_STOCK_MATH.quantity(m.get_string('fact_qty'))!=1 then

    raise_application_error(-20886,'HU_TASK_ONE_WHOLE_PLACE_REQUIRED');end if;

   if m.get_number('scan_draft_id') is not null then raise_application_error(-20886,'HU_TASK_SEALED_TOP_SCAN_REQUIRED');end if;

   pr:=proxy_request(p_request,t);

   RRL_STOCK_HU_CMD.compile_command(pr,p_operation,p_policies,p_resources,p_domain);

   v:=json_object_t.parse(p_domain);r:=json_array_t.parse(p_resources);

   if v.get_object('parent_snapshot').get_string('cell')!=t.FROM_CELL

    or v.get_number('warehouse')!=t.FROM_WARE_ID or t.FROM_WARE_ID!=t.TO_WARE_ID then raise_application_error(-20886,'HU_TASK_SOURCE_LOCATION_CONFLICT');end if;

   ctx:=json_object_t.parse(RRL_TASK_RESOURCE_POLICY.context_json(v_id,'COMPLETE',d.get_string('actor'),d.get_string('actor'),

    m.get_number('resource_id'),m.get_number('resource_session_id'),m.get_number('equipment_id')));

   if ctx.get_number('resource_session_id') is not null then

    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RESOURCE_SESSION',RRL_STOCK_PLAN_HELPER.decimal_text(ctx.get_number('resource_session_id')));

    RRL_STOCK_PLAN_HELPER.row_key(r,'RUSERS',d.get_string('actor'));

   end if;

   if t.RESOURCE_SESSION_ID is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RESOURCE_SESSION',RRL_STOCK_PLAN_HELPER.decimal_text(t.RESOURCE_SESSION_ID));end if;

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));

   v_key:='WT:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_id)||':MANUAL:PUTAWAY:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_id)||':';

   begin select SYNC_ID into v_sync from RRL_WAREHOUSE_TASK_SYNC where SYNC_KEY=v_key;

   exception when no_data_found then select RRL_WH_TASK_SYNC_SQ.nextval into v_sync from dual;end;

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK_SYNC',RRL_STOCK_PLAN_HELPER.decimal_text(v_sync));

   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TASK.SYNC:'||v_key);

   v.put('task_signature',RRL_STOCK_TASK_PLAN.signature(t));v.put('hu_version',t.HU_CONTENT_VERSION);

   select count(*)into iw_count from RRL_INTERWARE_PUT_PLAN where TASK_ID=v_id;

   if iw_count=1 then RRL_STOCK_INTERWARE_PUT.plan_task(t,d.get_string('actor'),r,v);end if;

   declare group_receipt varchar2(100);group_value json_object_t;begin

    select max(RECEIPT_OPERATION_ID)into group_receipt from RRL_IW_GROUP_PUT_PLAN where TASK_ID=v_id;

    if group_receipt is not null then

     RRL_IW_GROUP_PUT.describe_receipt(group_receipt,t.TO_CELL,d.get_string('actor'),v_id,group_value);

     RRL_IW_GROUP_PUT.declare_rows(group_value,p_operation,r);v.put('group_placement',group_value);

    end if;

   end;

   RRL_ST_DEFER_HU_WAIT.declare_plan(p_request,v_id,r,v);
   v.put('resource_context',ctx);v.put('task_id',v_id);v.put('sync_id',v_sync);v.put('sync_key',v_key);v.put('planning',0);

   p_domain:=v.to_clob;p_resources:=r.to_clob;

  end if;

 end;

 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is

  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;j json_object_t:=json_object_t();ctx json_object_t;x json_object_t;

  t RRL_WAREHOUSE_TASK%rowtype;plan clob;s clob;pr clob;a json_array_t;v_op varchar2(100):=d.get_string('operation_id');v_id number;

  v_uid varchar2(200);v_from varchar2(60);v_to varchar2(60);v_ware number;v_version number;v_resource number;v_session number;v_equipment number;v_sync number;v_key varchar2(400);

  v_leaf_uid varchar2(200);v_qty number;v_base varchar2(20);v_sscc varchar2(32);v_slot number;v_measures clob;

 begin

  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'HU_TASK_EXECUTION_FORBIDDEN');end if;

  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=v_op;

  v:=json_object_t.parse(plan).get_object('domain');v_id:=v.get_number('task_id');v_uid:=v.get_string('uid');

  v_from:=v.get_object('parent_snapshot').get_string('cell');v_to:=v.get_string('target');v_ware:=v.get_number('warehouse');

  if v.has('defer_wait_hu')then
   RRL_ST_DEFER_HU_WAIT.validate_plan(p_request,p_actor,v.get_object('defer_wait_hu'),case when v.get_number('planning')=1 then null else v_id end);
  end if;
  if v.has('group_placement')then RRL_IW_GROUP_PUT.validate_receipt(v.get_object('group_placement'),p_actor,case when v.get_number('planning')=1 then null else v_id end);end if;

  if v.get_number('planning')=1 then

   s:=RRL_STOCK_HU_READ.snapshot_json(v_uid);

   if rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256))!=v.get_string('parent_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: HU task planning');end if;

   select SSCC into v_sscc from RRL_PALLETS where UID_PALLET=v_uid;

   if not v.has('defer_wait_hu')and(m.get_string('scan_container') is null or(m.get_string('scan_container')!=v_uid and(v_sscc is null or m.get_string('scan_container')!=v_sscc))) then raise_application_error(-20886,'HU_TASK_PLAN_TOP_SCAN_REQUIRED');end if;

   v_version:=treat(v.get_object('parent_snapshot').get_array('nodes').get(0) as json_object_t).get_number('version');

   v_slot:=v.get_object('placement').get_number('slot_id');

   if v.get_object('placement').has('measurements') then v_measures:=v.get_object('placement').get_object('measurements').to_clob;end if;

   insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,UID_PALLET,

    FROM_WARE_ID,FROM_CELL,TO_WARE_ID,TO_CELL,QTY,UNIT_CODE,QTY_MODE,STATUS,CREATED_BY,HU_CONTENT_VERSION,TO_CELL_SLOT_ID,HU_MEASUREMENTS_JSON)

    values(v_id,'PUTAWAY','MANUAL',v_id,'WAREHOUSE_HU',v_uid,v_ware,v_from,v_ware,v_to,1,'HU','PALLET','PLANNED',p_actor,v_version,v_slot,v_measures);

   if v.has('group_placement')then RRL_IW_GROUP_PUT.record_plan(v_op,v_id,v.get_object('group_placement'),p_actor);end if;

   j.put('operation_id',v_op);j.put('task_id',v_id);j.put('pallet_identifier',v_uid);j.put('from_cell',v_from);j.put('cell',v_to);

   j.put('target_slot_id',v_slot);j.put('placement',v.get_object('placement'));j.put('status','PLANNED');j.put('quantity','1');j.put('unit_code','HU');j.put('content_version',v_version);p_result:=j.to_clob;
   if v.has('defer_wait_hu')then RRL_ST_DEFER_WAIT_API.record_hu_plan(p_request,v_id,v.get_object('defer_wait_hu'),p_result);end if;

  else

   select * into t from RRL_WAREHOUSE_TASK where TASK_ID=v_id for update;

   if t.HU_CONTENT_VERSION!=v.get_number('hu_version') or RRL_STOCK_TASK_PLAN.signature(t)!=v.get_string('task_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: HU physical task');end if;

   if v.has('interwarehouse_placement')then RRL_STOCK_INTERWARE_PUT.validate_task(t,p_actor,v.get_object('interwarehouse_placement'));end if;

   ctx:=json_object_t.parse(RRL_TASK_RESOURCE_POLICY.context_json(v_id,'COMPLETE',p_actor,p_actor,

    m.get_number('resource_id'),m.get_number('resource_session_id'),m.get_number('equipment_id')));

   if dbms_lob.compare(ctx.to_clob,v.get_object('resource_context').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: HU task resource context');end if;

   pr:=proxy_request(p_request,t);RRL_STOCK_HU_CMD.execute_command(pr,p_actor,s);

   v_resource:=ctx.get_number('resource_id');v_session:=ctx.get_number('resource_session_id');v_equipment:=ctx.get_number('equipment_id');

   update RRL_WAREHOUSE_TASK set STATUS='DONE',FACT_QTY=1,TARGET_UID_PALLET=v_uid,FINISHED_AT=systimestamp,

    ASSIGNED_TO=p_actor,RESOURCE_ID=v_resource,RESOURCE_SESSION_ID=v_session,EQUIPMENT_ID=v_equipment,

    COMPLETION_HASH=rawtohex(sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256)),COMPLETION_JSON=p_request,LAST_ERROR=null where TASK_ID=v_id;

   a:=v.get_object('parent_snapshot').get_array('nodes');

   for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);

    if x.get_string('kind')='STOCK' then

     v_leaf_uid:=x.get_string('uid');v_qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));v_base:=x.get_string('base_uom');

     insert into RRL_WAREHOUSE_TASK_STOCK_MOVE(STOCK_MOVE_ID,TASK_ID,TASK_SOURCE,TASK_TYPE,SOURCE_DOC_TYPE,SOURCE_TASK_ID,

      UID_PALLET,TARGET_UID_PALLET,FROM_CELL,TO_CELL,QTY,BASE_QTY,BASE_UOM,OPERATION_ID,CREATED_AT,CREATED_BY)

      values(RRL_WH_TASK_STOCK_MOVE_SQ.nextval,v_id,'MANUAL','PUTAWAY','WAREHOUSE_HU',v_id,v_leaf_uid,v_leaf_uid,

       v_from,v_to,v_qty,v_qty,v_base,v_op,systimestamp,p_actor);

    end if;

   end loop;

   if v_resource is not null or v_session is not null or v_equipment is not null then

    insert into RRL_RESOURCE_FACT_EVENT(EVENT_ID,TASK_ID,SESSION_ID,RESOURCE_ID,EVENT_TYPE,EVENT_AT,EVENT_BY,PAYLOAD_JSON)

     values(RRL_RESOURCE_FACT_EVENT_SQ.nextval,v_id,v_session,v_resource,'COMPLETED',systimestamp,p_actor,p_request);

   end if;

   update RRL_RESOURCE_SESSION set CURRENT_TASK_ID=null where SESSION_ID in(v_session,t.RESOURCE_SESSION_ID) and CURRENT_TASK_ID=v_id;

   if v_session is not null then update RRL_RESOURCE_SESSION set LAST_CELL=v_to,LAST_POSITION_AT=systimestamp,LAST_HEARTBEAT_AT=systimestamp

    where SESSION_ID=v_session and OPERATOR_USER_ID=p_actor;end if;

   v_sync:=v.get_number('sync_id');v_key:=v.get_string('sync_key');

   merge into RRL_WAREHOUSE_TASK_SYNC dst using(select v_key SYNC_KEY from dual)src on(dst.SYNC_KEY=src.SYNC_KEY)

    when matched then update set dst.SYNC_STATUS='SYNCED',dst.SYNCED_AT=systimestamp,dst.UPDATED_AT=systimestamp,dst.UPDATED_BY=p_actor,dst.LAST_ERROR=null

    when not matched then insert(SYNC_ID,TASK_ID,TASK_SOURCE,TASK_TYPE,SOURCE_DOC_TYPE,SOURCE_TASK_ID,SYNC_KEY,SYNC_STATUS,SYNC_ATTEMPT,CREATED_AT,UPDATED_AT,SYNCED_AT,UPDATED_BY)

     values(v_sync,v_id,'MANUAL','PUTAWAY','WAREHOUSE_HU',v_id,v_key,'SYNCED',1,systimestamp,systimestamp,systimestamp,p_actor);

   if v.has('interwarehouse_placement')then

    x:=v.get_object('interwarehouse_placement');

    RRL_STOCK_INTERWARE_PUT.complete_task(t,RRL_STOCK_MATH.quantity(x.get_string('quantity')),x.get_string('uid'),p_actor);

   end if;

   if v.has('group_placement')then RRL_IW_GROUP_PUT.record_complete(v_op,v_id,v.get_object('group_placement'),p_actor);end if;

   j:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(v_uid));j.put('operation_id',v_op);j.put('task_id',v_id);j.put('status','DONE');

   j.put('pallet_identifier',v_uid);j.put('source_pallet_identifier',v_uid);j.put('quantity','1');j.put('unit_code','HU');j.put('remaining_quantity','0');j.put_null('residual_task_id');

   p_result:=j.to_clob;

  end if;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_UNIT_SIGNATURE as
 procedure describe_units(p_uid varchar2,p_cell varchar2,p_signature out varchar2,p_count out number) is
  j json_object_t:=json_object_t();a json_array_t:=json_array_t();x json_object_t;n number:=0;
 begin
  for u in(select PHYSICAL_UNIT_KEY,BASE_QTY,BASE_UOM from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and (p_cell is null or CURRENT_CELL=p_cell) and STOCK_STATUS!='ISSUED' order by PHYSICAL_UNIT_KEY fetch first 10001 rows only) loop
   n:=n+1;if n>10000 then raise_application_error(-20881,'PLACEMENT_PHYSICAL_UNIT_BOUND_10000');end if;
   if u.PHYSICAL_UNIT_KEY is null or u.BASE_QTY is null or u.BASE_QTY<=0 or u.BASE_UOM is null then raise_application_error(-20884,'PHYSICAL_UNIT_SIGNATURE_DATA_REQUIRED');end if;
   x:=json_object_t();x.put('key',u.PHYSICAL_UNIT_KEY);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY));x.put('base_uom',u.BASE_UOM);a.append(x);
  end loop;j.put('units',a);
  p_signature:=rawtohex(sys.dbms_crypto.hash(j.to_clob,sys.dbms_crypto.hash_sh256));p_count:=n;
 end;
 function signature_for(p_uid varchar2,p_cell varchar2) return varchar2 is s varchar2(64);n number;begin describe_units(p_uid,p_cell,s,n);return s;end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_HU_UNPACK_CMD as
 function proxy(p_request clob) return clob is d json_object_t:=json_object_t.parse(p_request);begin d.put('command_type','HU_DETACH');return d.to_clob;end;
 function placement(tree json_object_t,measures json_object_t,slot_no number,task_no number,root_uid varchar2,extra json_object_t) return json_object_t is
  m json_object_t:=json_object_t();w number;vol number;
 begin
  m.put('target_cell',tree.get_string('cell'));m.put('target_slot_id',slot_no);m.put('planned_physical_task_id',task_no);m.put('measurements',measures);
  w:=RRL_STOCK_MATH.quantity(extra.get_string('gross_weight_kg'));
  vol:=ceil(RRL_STOCK_MATH.quantity(extra.get_string('width_m'))*RRL_STOCK_MATH.quantity(extra.get_string('depth_m'))*RRL_STOCK_MATH.quantity(extra.get_string('height_m'))*1000000000)/1000000000;
  return json_object_t.parse(RRL_STOCK_HU_SLOT.target_json(tree.to_clob,m.to_clob,null,root_uid,w,vol));
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t;p json_object_t;c json_object_t;x json_object_t;
  f json_array_t;r json_array_t;nodes json_array_t;remain_nodes json_array_t:=json_array_t();child_nodes json_array_t;pr json_object_t;cr json_object_t;
  type keys is table of number index by varchar2(200);removed keys;
  dom clob;v_uid varchar2(200):=d.get_object('source').get_string('uid');child_uid varchar2(200):=m.get_string('child_uid');old_task number;old_slot number;new_slot number:=m.get_number('child_slot_id');
  parent_task number;child_task number;parent_sync number;child_sync number;sync_key varchar2(255);leaf_count number:=0;n number;cell_name varchar2(60);
 begin
  if (child_uid is null and m.get_number('child_case_task_id') is null) or(child_uid is not null and m.get_number('child_case_task_id') is not null) or new_slot is null then raise_application_error(-20886,'HU_UNPACK_CONTAINER_AND_SLOT_REQUIRED');end if;
  RRL_STOCK_HU_CMD.compile_command(proxy(p_request),p_operation,p_policies,p_resources,dom,true);v:=json_object_t.parse(dom);
  p:=v.get_object('parent_snapshot');c:=v.get_object('child_snapshot');cell_name:=p.get_string('cell');child_uid:=c.get_string('root');
  if p.get_array('ancestors').get_size>0 or treat(c.get_array('nodes').get(0) as json_object_t).get_string('kind') not in('CONTAINER','STOCK','CASE') then raise_application_error(-20886,'HU_UNPACK_TOP_PARENT_CONTAINER_CHILD_REQUIRED');end if;
  begin select TASK_ID,CELL_SLOT_ID into old_task,old_slot from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=v_uid and CELL=cell_name and STATUS='OCCUPIED';
  exception when no_data_found then raise_application_error(-20886,'HU_UNPACK_EXISTING_PARENT_SLOT_REQUIRED');end;
  if old_slot=new_slot then raise_application_error(-20886,'HU_UNPACK_SEPARATE_CHILD_SLOT_REQUIRED');end if;
  child_nodes:=c.get_array('nodes');
  for i in 0..child_nodes.get_size-1 loop x:=treat(child_nodes.get(i) as json_object_t);removed(x.get_string('uid')):=1;end loop;
  nodes:=p.get_array('nodes');
  for i in 0..nodes.get_size-1 loop x:=treat(nodes.get(i) as json_object_t);
   if not removed.exists(x.get_string('uid')) then remain_nodes.append(x);if x.get_string('kind')='STOCK' then leaf_count:=leaf_count+1;end if;end if;
  end loop;
  pr:=json_object_t.parse(p.to_clob);pr.put('nodes',remain_nodes);pr.put('leaf_count',leaf_count);
  parent_task:=RRL_WAREHOUSE_TASK_SQ.nextval;child_task:=RRL_WAREHOUSE_TASK_SQ.nextval;
  if not m.has('parent_measurements') or not m.has('child_measurements') then raise_application_error(-20886,'HU_UNPACK_BOTH_FRESH_MEASUREMENTS_REQUIRED');end if;
  cr:=placement(c,m.get_object('child_measurements'),new_slot,child_task,v_uid,m.get_object('parent_measurements'));
  v.put('child_placement',cr);
  cr:=placement(pr,m.get_object('parent_measurements'),old_slot,parent_task,v_uid,m.get_object('child_measurements'));
  v.put('parent_placement',cr);v.put('remaining_parent_snapshot',pr);
  v.put('old_claim_task',old_task);v.put('parent_slot',old_slot);v.put('child_slot',new_slot);v.put('parent_placement_task',parent_task);v.put('child_placement_task',child_task);
  f:=json_array_t.parse(p_policies);r:=json_array_t.parse(p_resources);RRL_STOCK_PLAN_HELPER.fence(f,'CELL',cell_name,6);
  RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(old_slot));
  RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(new_slot));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(old_task));
  for i in 1..2 loop n:=case i when 1 then parent_task else child_task end;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(n));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(n));
  end loop;
  parent_sync:=RRL_WH_TASK_SYNC_SQ.nextval;child_sync:=RRL_WH_TASK_SYNC_SQ.nextval;
  v.put('parent_sync',parent_sync);v.put('child_sync',child_sync);
  for i in 1..2 loop n:=case i when 1 then parent_task else child_task end;
   sync_key:='WT:'||RRL_STOCK_PLAN_HELPER.decimal_text(n)||':MANUAL:PUTAWAY:'||RRL_STOCK_PLAN_HELPER.decimal_text(n)||':';
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK_SYNC',RRL_STOCK_PLAN_HELPER.decimal_text(case i when 1 then parent_sync else child_sync end));
   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TASK.SYNC:'||sync_key);
  end loop;
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');op varchar2(100):=d.get_string('operation_id');plan clob;unused_result clob;
  v json_object_t;x json_object_t;actual json_object_t;placement_now json_object_t;measures json_object_t;j json_object_t:=json_object_t();children clob;
  v_uid varchar2(200);child_uid varchar2(200);cell_name varchar2(60);ware number;old_task number;old_slot number;child_slot number;rid number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'HU_EXECUTION_FORBIDDEN');end if;
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  v_uid:=v.get_string('uid');child_uid:=v.get_object('child_snapshot').get_string('root');cell_name:=v.get_object('parent_snapshot').get_string('cell');ware:=v.get_object('parent_snapshot').get_number('warehouse');
  old_task:=v.get_number('old_claim_task');old_slot:=v.get_number('parent_slot');child_slot:=v.get_number('child_slot');
  if m.get_string('scan_cell') is null or m.get_string('scan_cell')!=cell_name or m.get_string('scan_parent_slot') is null or m.get_string('scan_child_slot') is null then raise_application_error(-20886,'HU_UNPACK_CELL_AND_SLOTS_SCAN_REQUIRED');end if;
  declare code varchar2(100);begin
   select SLOT_CODE into code from RRL_TOPOLOGY_CELL_SLOT where CELL_SLOT_ID=old_slot;
   if code!=m.get_string('scan_parent_slot') then raise_application_error(-20886,'HU_UNPACK_PARENT_SLOT_SCAN_REQUIRED');end if;
   select SLOT_CODE into code from RRL_TOPOLOGY_CELL_SLOT where CELL_SLOT_ID=child_slot;
   if code!=m.get_string('scan_child_slot') then raise_application_error(-20886,'HU_UNPACK_CHILD_SLOT_SCAN_REQUIRED');end if;
  end;
  placement_now:=placement(v.get_object('child_snapshot'),m.get_object('child_measurements'),child_slot,v.get_number('child_placement_task'),v_uid,m.get_object('parent_measurements'));
  if dbms_lob.compare(placement_now.to_clob,v.get_object('child_placement').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: child placement');end if;
  placement_now:=placement(v.get_object('remaining_parent_snapshot'),m.get_object('parent_measurements'),old_slot,v.get_number('parent_placement_task'),v_uid,m.get_object('child_measurements'));
  if dbms_lob.compare(placement_now.to_clob,v.get_object('parent_placement').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: parent placement');end if;
  RRL_STOCK_HU_CMD.execute_command(proxy(p_request),p_actor,unused_result);
  delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=old_task and UID_PALLET=v_uid and CELL_SLOT_ID=old_slot and STATUS='OCCUPIED';
  if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: parent placement claim');end if;
  RRL_STOCK_HU_PLACEMENT_CORE.record_place(p_request,p_actor,v_uid,ware,cell_name,v.get_number('parent_placement_task'),old_slot,v.get_number('parent_sync'),v.get_object('parent_placement').to_clob);
  RRL_STOCK_HU_PLACEMENT_CORE.record_place(p_request,p_actor,child_uid,ware,cell_name,v.get_number('child_placement_task'),child_slot,v.get_number('child_sync'),v.get_object('child_placement').to_clob,v.get_number('child_case_task_id'));
  children:=v.get_object('child_snapshot').get_array('nodes').to_clob;
  for rr in(select RESERVATION_ID,UID_PALLET,CELL,BASE_QTY from RRL_STOCK_RESERVATION where UID_PALLET in(
   select U from json_table(children,'$[*]' columns(U varchar2(200) path '$.uid',K varchar2(20) path '$.kind')) where K='STOCK')
   and CELL=cell_name and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_QTY>0 order by RESERVATION_ID) loop
   RRL_STOCK_RESERVE_CORE.move_coverage(rr.RESERVATION_ID,rr.RESERVATION_ID,rr.UID_PALLET,rr.CELL,ware,rr.BASE_QTY,child_slot,p_actor,rid);
   if rid!=rr.RESERVATION_ID then raise_application_error(-20869,'HU_UNPACK_RESERVATION_IDENTITY_CHANGED');end if;
  end loop;
  j.put('operation_id',op);j.put('command','HU_UNPACK');j.put('parent',json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(v_uid)));
  if v.get_number('child_case_task_id') is null then j.put('child',json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(child_uid)));else j.put('child',json_object_t.parse(RRL_STOCK_HU_READ.case_snapshot_json(v.get_number('child_case_task_id'))));end if;j.put('parent_task_id',v.get_number('parent_placement_task'));j.put('child_task_id',v.get_number('child_placement_task'));j.put('quantity_unchanged',true);
  p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_INTERNAL_CMD as
 procedure compile_move(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t;v json_object_t:=json_object_t();
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();p RRL_PALLETS%rowtype;
  v_from varchar2(60);v_to varchar2(60);v_p number;v_qty number;v_base varchar2(20);v_ver number;
  v_ware number;v_source_ware number;v_target varchar2(200);v_uom_version number;v_sig varchar2(64);v_input varchar2(20);
 begin
  m:=d.get_object('metadata');m.on_error(1);
  declare
 v_json_sql_1_1 varchar2(32767):=m.get_string('uid');
begin
select * into p from RRL_PALLETS where UID_PALLET=v_json_sql_1_1;
end;
  v_to:=m.get_string('target_cell');
  if m.has('source_cell') and not m.get('source_cell').is_null then v_from:=m.get_string('source_cell');
  else select CELL into v_from from RRL_REMAINS where UID_POLETA=p.UID_PALLET and REMAIN>0;end if;
  select REMAIN,BASE_UOM,STOCK_VERSION into v_p,v_base,v_ver from RRL_REMAINS where UID_POLETA=p.UID_PALLET and CELL=v_from;
  select WARE_ID into v_ware from RRL_CELLS where CELL=v_to;
  select WARE_ID into v_source_ware from RRL_CELLS where CELL=v_from;
  if v_source_ware!=v_ware or v_ware is null then raise_application_error(-20886,'INTERNAL_WAREHOUSE_CONFLICT');end if;
  v_input:=nvl(m.get_string('unit'),v_base);
  if m.get_string('quantity')='0' then
   RRL_STOCK_PALLET_UOM.resolve_quantity(p.UID_PALLET,v_base,RRL_STOCK_PLAN_HELPER.decimal_text(v_p),v_base,v_qty,v_uom_version,v_sig);
  else RRL_STOCK_PALLET_UOM.resolve_quantity(p.UID_PALLET,v_input,m.get_string('quantity'),v_base,v_qty,v_uom_version,v_sig);end if;
  v_target:=p.UID_PALLET;
  if v_qty<v_p then v_target:='PART:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256));end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,p.UID_PALLET,p.ARTICUL,v_from,v_to);
  if p.PRIHOD_NAKLAD_ID is not null and p.PRIHOD_NAKLAD_ID>0 then
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRIHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(p.PRIHOD_NAKLAD_ID));
  end if;
  if v_target!=p.UID_PALLET then
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v_target);RRL_STOCK_PLAN_HELPER.anchor(r,50,'STOCK',v_target);
   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','PALLET:'||v_target);
  end if;
  v.put('uid',p.UID_PALLET);v.put('target_uid',v_target);v.put('article',p.ARTICUL);v.put('from',v_from);v.put('to',v_to);
  v.put('source_p',RRL_STOCK_PLAN_HELPER.decimal_text(v_p));v.put('stock_version',v_ver);v.put('base_uom',v_base);
  v.put('base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));v.put('uom_version',v_uom_version);v.put('uom_signature',v_sig);v.put('warehouse',v_ware);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_move(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t;v json_object_t;j json_object_t:=json_object_t();
  p RRL_PALLETS%rowtype;c RRL_CELLS%rowtype;v_plan clob;v_uid varchar2(200);v_target varchar2(200);
  v_p number;v_ver number;v_qty number;v_base varchar2(20);v_uom_version number;v_sig varchar2(64);
  v_n number;v_input varchar2(20);v_condition number;v_pick_cell varchar2(60);v_stop number;v_weight number;v_units clob;
 begin
  if d.get_string('command_type')='MOVE_QUARANTINE' and RRL_HAS_WRIGHT(p_actor,'QUARANTINE_MOVE')!=1 then raise_application_error(-20882,'QUARANTINE_MOVE_FORBIDDEN');end if;
  if RRL_HAS_WRIGHT(p_actor,'INTERNAL_MOVE')!=1 and RRL_HAS_WRIGHT(p_actor,'stock_posting_manual_move')!=1 then raise_application_error(-20882,'INTERNAL_MOVE_FORBIDDEN');end if;
  declare
 v_json_sql_2_1 varchar2(32767):=d.get_string('operation_id');
begin
select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_2_1;
end;
  v:=json_object_t.parse(v_plan).get_object('domain');m:=d.get_object('metadata');
  v_uid:=v.get_string('uid');v_target:=v.get_string('target_uid');
  select * into p from RRL_PALLETS where UID_PALLET=v_uid;
  if p.ARTICUL!=v.get_string('article') then raise_application_error(-20890,'CLOSURE_CHANGED: pallet article');end if;
  declare
 v_json_sql_3_1 varchar2(32767):=v.get_string('from');
begin
select REMAIN,BASE_UOM,STOCK_VERSION into v_p,v_base,v_ver from RRL_REMAINS where UID_POLETA=v_uid and CELL=v_json_sql_3_1;
end;
  if v_ver!=v.get_number('stock_version') or RRL_STOCK_PLAN_HELPER.decimal_text(v_p)!=v.get_string('source_p') then raise_application_error(-20890,'CLOSURE_CHANGED: internal stock');end if;
  v_input:=nvl(m.get_string('unit'),v_base);
  if m.get_string('quantity')='0' then
   RRL_STOCK_PALLET_UOM.resolve_quantity(v_uid,v_base,RRL_STOCK_PLAN_HELPER.decimal_text(v_p),v_base,v_qty,v_uom_version,v_sig);
  else RRL_STOCK_PALLET_UOM.resolve_quantity(v_uid,v_input,m.get_string('quantity'),v_base,v_qty,v_uom_version,v_sig);end if;
  if v_sig!=v.get_string('uom_signature') or RRL_STOCK_PLAN_HELPER.decimal_text(v_qty)!=v.get_string('base_quantity') then raise_application_error(-20890,'CLOSURE_CHANGED: internal UOM');end if;
  if p.PRIHOD_NAKLAD_ID>0 then
   select CONDITION into v_condition from RRL_PRIHOD_NAKLAD where ID=p.PRIHOD_NAKLAD_ID for update;
   if v_condition in(0,1) then raise_application_error(-20886,'NAKLAD_NE_ZAKRYTA');end if;
  end if;
  declare
 v_json_sql_4_1 varchar2(32767):=v.get_string('to');
begin
select * into c from RRL_CELLS where CELL=v_json_sql_4_1;
end;
  if d.get_string('command_type')='MOVE_QUARANTINE' then
   if v_qty!=v_p then raise_application_error(-20886,'QUARANTINE_MOVE_REQUIRES_WHOLE_PALLET');end if;
   declare
 v_json_sql_5_1 varchar2(32767):=v.get_string('from');
begin
select count(*) into v_n from RRL_CELLS where CELL in(v_json_sql_5_1,c.CELL) and nvl(BLOCKED_FOR_REMAINS,0)=1;
end;
   if v_n=0 then raise_application_error(-20879,'QUARANTINE_CELL_REQUIRED');end if;
  end if;
  if nvl(c.OTBOR,0)=0 and nvl(c.IS_SYSTEM,0)=0 then
   select count(*) into v_n from RRL_REMAINS where CELL=c.CELL and REMAIN>0 and UID_POLETA!=v_uid;
   if v_n>0 then raise_application_error(-20886,'CELL_NOT_EMPTY');end if;
  elsif nvl(c.OTBOR,0)=1 then
   select CELL into v_pick_cell from RRL_ARTICULS where ACTICUL=p.ARTICUL;
   if v_pick_cell is null or v_pick_cell!=c.CELL then raise_application_error(-20886,'OTBOR_DRUGOGO_ARTICULA');end if;
  end if;
  select nvl(WEIGHT_LIMIT_STOP,0) into v_stop from RRL_WARES where ID=c.WARE_ID;
  if v_stop=1 and c.LIMIT_WEIGHT is not null then
   if p.WEIGHT_BRUTTO is null or p.UNIT_COUNT is null or p.UNIT_COUNT<=0 then raise_application_error(-20886,'PALLET_WEIGHT_REQUIRED');end if;
   select nvl(sum(pp.WEIGHT_BRUTTO*rr.REMAIN/nullif(pp.UNIT_COUNT,0)),0) into v_weight
    from RRL_REMAINS rr join RRL_PALLETS pp on pp.UID_PALLET=rr.UID_POLETA where rr.CELL=c.CELL and rr.REMAIN>0;
   if v_weight+p.WEIGHT_BRUTTO*v_qty/p.UNIT_COUNT>c.LIMIT_WEIGHT then raise_application_error(-20886,'CELL_WEIGHT_LIMIT');end if;
  end if;
  if v_target!=v_uid then
   select count(*) into v_n from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=v_uid and STOCK_STATUS!='ISSUED';
   if v_n>0 then raise_application_error(-20884,'PARTIAL_MARKED_MOVE_REQUIRES_PHYSICAL_HU_SPLIT');end if;
   p.STOCK_ORIGIN_UID:=nvl(p.STOCK_ORIGIN_UID,p.UID_PALLET);p.CREATED_BY_STOCK_OP:=d.get_string('operation_id');
   if p.WEIGHT_BRUTTO is not null then
    if p.UNIT_COUNT is null or p.UNIT_COUNT<=0 then raise_application_error(-20887,'PALLET_BIRTH_QUANTITY_REQUIRED');end if;
    p.WEIGHT_BRUTTO:=p.WEIGHT_BRUTTO*v_qty/p.UNIT_COUNT;
   end if;
   p.UID_PALLET:=v_target;p.SSCC:=null;p.UNIT_COUNT:=v_qty;p.PRINTED:=0;
   p.STOCK_COMPOSITION_VERSION:=0;insert into RRL_PALLETS values p;
  end if;
  if d.get_array('units').get_size>0 then v_units:=d.get_array('units').to_clob;end if;
  RRL_STOCK_TRANSFER_CORE.move(v_uid,v_target,v.get_string('from'),c.CELL,v_qty,v_base,v_uom_version,c.WARE_ID,p_actor,1,null,v_units,null,null,null,case when d.get_string('command_type')='MOVE_QUARANTINE' then 'QUARANTINE' else 'ORDINARY' end);
  j.put('operation_id',d.get_string('operation_id'));j.put('status','APPLIED');j.put('source_uid',v_uid);j.put('uid',v_target);
  j.put('from_cell',v.get_string('from'));j.put('cell',c.CELL);j.put('base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));j.put('base_uom',v_base);
  p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_INTERWARE_CUSTODY as
 procedure assert_scope(p_receipt varchar2,p_actor varchar2)is n number;
 begin
  select count(*)into n from RRL_IW_GROUP_RECEIPT r join RUSERS u on u.ID=p_actor where r.OPERATION_ID=p_receipt and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1 and(u.WARE_ID=r.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n=1 then return;end if;
  select count(*)into n from RRL_INTERWARE_RECEIPT r join RUSERS u on u.ID=p_actor where r.OPERATION_ID=p_receipt and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1 and(u.WARE_ID=r.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'INTERWARE_CURRENT_CUSTODY_ACTOR_REQUIRED');end if;
 end;
 procedure describe_source(p_receipt varchar2,p_actor varchar2,p_domain out json_object_t) is
 receipt RRL_INTERWARE_RECEIPT%rowtype;unloaded RRL_INTERWARE_UNLOAD%rowtype;cargo RRL_TT_HU_LOAD_FACT%rowtype;n number;source_uid varchar2(200);loss_id varchar2(100);loss_at timestamp with time zone;physical_uid varchar2(200);source_plan RRL_INTERWARE_PLAN%rowtype;
 begin
 select *into receipt from RRL_INTERWARE_RECEIPT where OPERATION_ID=p_receipt;
 source_uid:=nvl(receipt.ORIGINAL_ROOT_UID,receipt.ROOT_UID);
 select *into source_plan from RRL_INTERWARE_PLAN where OPERATION_ID=receipt.PLAN_OPERATION_ID;physical_uid:=nvl(source_plan.SOURCE_PLACE_UID,source_uid);
 if receipt.ORIGINAL_ROOT_UID is not null then
  select fact.OPERATION_ID,fact.CREATED_AT into loss_id,loss_at from RRL_INTERWARE_SHORTAGE_FACT fact
   join RRL_INTERWARE_SHORTAGE_REQUEST req on req.OPERATION_ID=fact.REQUEST_OPERATION_ID
   join RRL_STOCK_OPERATION o on o.OPERATION_ID=fact.OPERATION_ID and o.STATE='APPLIED'and o.COMMAND_TYPE='INTERWARE_SHORTAGE_CONFIRM'
   where fact.RECEIPT_OPERATION_ID=receipt.OPERATION_ID and req.RECEIPT_OPERATION_ID=receipt.OPERATION_ID
   and req.SOURCE_LOAD_OPERATION_ID=receipt.SOURCE_LOAD_OPERATION_ID and req.ORIGINAL_UID=source_uid
   and req.ACCEPTED_UID=receipt.ROOT_UID and req.WARE_ID=receipt.WARE_ID
   and req.EXPECTED_QTY=receipt.EXPECTED_BASE_QTY and req.ACCEPTED_QTY=receipt.BASE_QTY
   and fact.SHORT_QTY=req.SHORT_QTY and receipt.BASE_QTY+fact.SHORT_QTY=receipt.EXPECTED_BASE_QTY;
 end if;
select *into unloaded from RRL_INTERWARE_UNLOAD where OPERATION_ID=receipt.UNLOAD_OPERATION_ID;
 select *into cargo from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=receipt.SOURCE_LOAD_OPERATION_ID;
 select count(*)into n from RUSERS u where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=receipt.WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1;
 if n!=1 then raise_application_error(-20882,'INTERWARE_CUSTODY_TARGET_ACTOR_REQUIRED');end if;
 if cargo.STATUS!='DEPARTED' or cargo.DEPARTURE_OPERATION_ID is null or cargo.DEPARTED_AT is null or cargo.CUSTODY_RELEASED_AT is not null or cargo.CUSTODY_RELEASE_OPERATION_ID is not null or cargo.ROOT_UID!=physical_uid or unloaded.ROOT_UID!=source_uid or unloaded.PLAN_OPERATION_ID!=receipt.PLAN_OPERATION_ID or unloaded.WARE_ID!=receipt.WARE_ID then raise_application_error(-20886,'INTERWARE_CUSTODY_ORIGINAL_PROOF_REQUIRED');end if;
 select count(*)into n from RRL_STOCK_OPERATION where OPERATION_ID=receipt.OPERATION_ID and STATE='APPLIED'and COMMAND_TYPE='INTERWARE_RECEIVE';if n!=1 then raise_application_error(-20886,'INTERWARE_CUSTODY_APPLIED_RECEIPT_REQUIRED');end if;
 select count(*)into n from RRL_INTERWARE_CUSTODY_PROOF where RECEIPT_OPERATION_ID=p_receipt;if n!=0 then raise_application_error(-20886,'INTERWARE_CUSTODY_ALREADY_RELEASED');end if;
 p_domain:=json_object_t();p_domain.put('receipt_operation_id',p_receipt);p_domain.put('unload_operation_id',receipt.UNLOAD_OPERATION_ID);p_domain.put('source_load_operation_id',receipt.SOURCE_LOAD_OPERATION_ID);p_domain.put('uid',physical_uid);p_domain.put('stock_pallet_identifier',source_uid);p_domain.put('warehouse_id',receipt.WARE_ID);
 p_domain.put('custody_released_at',to_char(nvl(loss_at,unloaded.CREATED_AT),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));p_domain.put('departure_operation_id',cargo.DEPARTURE_OPERATION_ID);
 if loss_id is not null then p_domain.put('shortage_confirmation_operation_id',loss_id);
 p_domain.put('accepted_pallet_identifier',receipt.ROOT_UID);p_domain.put('accepted_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(receipt.BASE_QTY));
 p_domain.put('confirmed_short_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(receipt.EXPECTED_BASE_QTY-receipt.BASE_QTY));p_domain.put('full_physical_receipt',false);end if;
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_CUSTODY_ACTUAL_RECEIPT_OR_CONFIRMED_SHORTAGE_REQUIRED');
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
 declare n number;rec_id varchar2(100):=d.get_object('source').get_string('receipt_operation_id');begin
  select count(*)into n from RRL_IW_GROUP_RECEIPT where OPERATION_ID=rec_id;
  if n=1 then RRL_IW_GROUP_CUSTODY_CORE.compile_command(p_request,p_operation,p_policies,p_resources,p_domain);return;end if;
 end;
 describe_source(d.get_object('source').get_string('receipt_operation_id'),d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECEIPT',v.get_string('receipt_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_UNLOAD',v.get_string('unload_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',v.get_string('source_load_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_CUSTODY_PROOF',p_operation);
 if v.has('shortage_confirmation_operation_id')then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_SHORTAGE_FACT',v.get_string('shortage_confirmation_operation_id'));end if;
 RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v.get_string('uid'));RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TT.LOAD.HU:'||v.get_string('uid'));
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');resolved clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_receipt varchar2(100);v_load varchar2(100);v_unload varchar2(100);released_at timestamp with time zone;v_loss varchar2(100);
 begin
 select RESOLVED_PLAN_JSON into resolved from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(resolved).get_object('domain');
 if v.has('group_custody')then RRL_IW_GROUP_CUSTODY_CORE.execute_command(p_request,p_actor,p_result);return;end if;
 v_receipt:=v.get_string('receipt_operation_id');v_load:=v.get_string('source_load_operation_id');v_unload:=v.get_string('unload_operation_id');
 describe_source(v_receipt,p_actor,fresh);if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'INTERWARE_CUSTODY_SOURCE_CHANGED');end if;
 if v.has('shortage_confirmation_operation_id')then
 v_loss:=v.get_string('shortage_confirmation_operation_id');select CREATED_AT into released_at from RRL_INTERWARE_SHORTAGE_FACT where OPERATION_ID=v_loss;
 else select CREATED_AT into released_at from RRL_INTERWARE_UNLOAD where OPERATION_ID=v_unload;end if;
 insert into RRL_INTERWARE_CUSTODY_PROOF(OPERATION_ID,RECEIPT_OPERATION_ID,SOURCE_LOAD_OPERATION_ID,ACTOR)values(op,v_receipt,v_load,p_actor);
 update RRL_TT_HU_LOAD_FACT set CUSTODY_RELEASED_AT=released_at,CUSTODY_RELEASE_OPERATION_ID=op where LOAD_OPERATION_ID=v_load and CUSTODY_RELEASED_AT is null and CUSTODY_RELEASE_OPERATION_ID is null;
 if sql%rowcount!=1 then raise_application_error(-20886,'INTERWARE_CUSTODY_COMPARE_SET_CONFLICT');end if;
 j.put('operation_id',op);j.put('receipt_operation_id',v_receipt);j.put('source_load_operation_id',v_load);j.put('pallet_identifier',v.get_string('uid'));j.put('warehouse_id',v.get_number('warehouse_id'));
 if v.has('shortage_confirmation_operation_id')then
 j.put('shortage_confirmation_operation_id',v.get_string('shortage_confirmation_operation_id'));j.put('full_physical_receipt',false);
 j.put('accepted_pallet_identifier',v.get_string('accepted_pallet_identifier'));j.put('accepted_quantity',v.get_string('accepted_quantity'));j.put('confirmed_short_quantity',v.get_string('confirmed_short_quantity'));end if;
 j.put('status','FIRST_LEG_CUSTODY_RELEASED');j.put('custody_released_at',v.get_string('custody_released_at'));j.put('original_departure_retained',true);j.put('stock_changed',false);j.put('customer_delivery_confirmed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_INTERWARE_NEXT as   
 function describe_source(p_st number,p_ware number) return json_object_t is   
 bind RRL_INTERWARE_ONWARD_BIND%rowtype;receipt RRL_INTERWARE_RECEIPT%rowtype;placed RRL_INTERWARE_PLACEMENT%rowtype;v_p number;v_h number;v_uom varchar2(20);v_ver number;v_policy number;n number;unit_count number;unit_total number;unit_distinct number;unit_wire clob;unit_snapshot clob;receipt_wire clob;receipt_domain json_object_t;subset_wire json_object_t;j json_object_t:=json_object_t();   
 begin   
 begin select *into bind from RRL_INTERWARE_ONWARD_BIND where ST_ID=p_st;exception when no_data_found then declare grouped json_object_t:=RRL_IW_GROUP_NEXT.describe_source(p_st,p_ware);begin if grouped is not null then return grouped;end if;end;return RRL_STOCK_IW_RECOVERY_NEXT.describe_source(p_st,p_ware);end;   
 select *into receipt from RRL_INTERWARE_RECEIPT where OPERATION_ID=bind.RECEIPT_OPERATION_ID;   
 select *into placed from RRL_INTERWARE_PLACEMENT where RECEIPT_OPERATION_ID=receipt.OPERATION_ID;   
 if p_ware!=receipt.WARE_ID or bind.WARE_ID!=p_ware or bind.ROOT_UID!=receipt.ROOT_UID or placed.TARGET_CELL!=bind.SOURCE_CELL then raise_application_error(-20886,'INTERWARE_ONWARD_ORIGINAL_SOURCE_REQUIRED');end if;   
 select count(*)into n from RRL_INTERWARE_CUSTODY_PROOF where RECEIPT_OPERATION_ID=receipt.OPERATION_ID;if n!=1 then raise_application_error(-20886,'INTERWARE_FIRST_LEG_CUSTODY_REQUIRED');end if;   
 select count(*)into n from RRL_INTERWARE_ONWARD_DISPATCH where BIND_OPERATION_ID=bind.OPERATION_ID;if n!=0 then raise_application_error(-20886,'INTERWARE_ONWARD_ALREADY_DISPATCHED');end if;   
 select REMAIN,HARD_RESERVED_BASE,BASE_UOM,STOCK_VERSION into v_p,v_h,v_uom,v_ver from RRL_REMAINS where UID_POLETA=receipt.ROOT_UID and CELL=bind.SOURCE_CELL;   
 if v_p!=receipt.BASE_QTY or v_h!=0 or v_uom!=receipt.BASE_UOM or v_ver!=bind.STOCK_VERSION then raise_application_error(-20886,'INTERWARE_ONWARD_WHOLE_STOCK_VERSION_REQUIRED');end if;   
 select count(*)into n from RRL_REMAINS where UID_POLETA=receipt.ROOT_UID and CELL!=bind.SOURCE_CELL and(REMAIN!=0 or HARD_RESERVED_BASE!=0);if n!=0 then raise_application_error(-20886,'INTERWARE_ONWARD_ONE_PHYSICAL_CELL_REQUIRED');end if;   
 select count(*)into n from dual where exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=receipt.ARTICLE)or exists(select 1 from RRL_SKU_RECEIPT_POLICY where ARTICUL=receipt.ARTICLE and MARKING_REQUIRED=1)or exists(select 1 from RRL_FINISHED_GOODS_SKU where ARTICUL=receipt.ARTICLE and CRPT_REQUIRED=1);   
 select count(*)into unit_count from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=receipt.ROOT_UID;   
 if n>0 or unit_count>0 then   
  if receipt.ORIGINAL_ROOT_UID is not null then  
   select RESOLVED_PLAN_JSON into receipt_wire from RRL_STOCK_OPERATION where OPERATION_ID=receipt.OPERATION_ID and STATE='APPLIED'and COMMAND_TYPE='INTERWARE_RECEIVE';  
   receipt_domain:=json_object_t.parse(receipt_wire).get_object('domain');subset_wire:=json_object_t();  
   subset_wire.put('units',receipt_domain.get_array('source_units'));subset_wire.put('physical_unit_count',receipt_domain.get_array('source_units').get_size);unit_wire:=subset_wire.to_clob;  
  else  
  select MANIFEST_JSON into unit_wire from RRL_INTERWARE_UNIT_MANIFEST where PLAN_OPERATION_ID=receipt.PLAN_OPERATION_ID;  
  end if;   
  select count(*),sum(u.BASE_QTY),count(distinct u.PHYSICAL_UNIT_KEY),   
   json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob)   
   into n,unit_total,unit_distinct,unit_snapshot   
   from RRL_WMS_RECEIPT_UNIT u join json_table(unit_wire,'$.units[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))j on j.K=u.PHYSICAL_UNIT_KEY   
   where u.CURRENT_UID=receipt.ROOT_UID and u.CURRENT_CELL=bind.SOURCE_CELL and u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null and u.BASE_QTY=RRL_STOCK_MATH.quantity(j.Q)and u.BASE_UOM=j.B and u.BASE_UOM=receipt.BASE_UOM;   
  if unit_count<1 or unit_count>10000 or n!=unit_count or unit_distinct!=unit_count or unit_total!=receipt.BASE_QTY or json_object_t.parse(unit_wire).get_number('physical_unit_count')!=unit_count then raise_application_error(-20884,'INTERWARE_ONWARD_ORIGINAL_UNITS_REQUIRED');end if;   
  j.put('physical_units',json_array_t.parse(unit_snapshot));   
 end if;   
 select max(POLICY_VERSION)into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=receipt.ARTICLE and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=DENOMINATOR;   
 if v_policy is null then raise_application_error(-20886,'INTERWARE_ONWARD_BASE_UOM_REQUIRED');end if;   
 select count(*)into n from RRL_SBORKA_PALLETS where ID=p_st and WARE_ID=p_ware and ADDR=bind.FINAL_ADDRESS and RETURN_SUPPLIER_ID is null and nvl(CONDITION,0)<2 and(TRANSTASK_ID is null or TRANSTASK_ID=bind.TARGET_TT_ID);   
 if n!=1 then raise_application_error(-20886,'INTERWARE_ONWARD_ST_SOURCE_CHANGED');end if;   
 j.put('binding_operation_id',bind.OPERATION_ID);j.put('receipt_operation_id',receipt.OPERATION_ID);j.put('source_load_operation_id',bind.SOURCE_LOAD_OPERATION_ID);j.put('source_st_id',bind.SOURCE_ST_ID);j.put('st_id',p_st);j.put('target_trip_id',bind.TARGET_TT_ID);j.put('warehouse_id',p_ware);   
 j.put('uid',receipt.ROOT_UID);j.put('cell',bind.SOURCE_CELL);j.put('article',receipt.ARTICLE);j.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_p));j.put('base_uom',v_uom);j.put('stock_version',v_ver);j.put('uom_version',v_policy);return j;   
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_ONWARD_PLACED_SOURCE_REQUIRED');   
 end;   
 procedure declare_source(p_source json_object_t,p_operation varchar2,p_resources in out nocopy json_array_t) is   
 begin 
 if p_source.has('group_receipt_operation_id')then RRL_IW_GROUP_NEXT.declare_source(p_source,p_operation,p_resources);return;end if;
if p_source.has('recovery_operation_id')then RRL_STOCK_IW_RECOVERY_NEXT.declare_source(p_source,p_operation,p_resources);return;end if;   
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INTERWARE_ONWARD_BIND',p_source.get_string('binding_operation_id'));   
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INTERWARE_RECEIPT',p_source.get_string('receipt_operation_id'));   
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INTERWARE_ONWARD_DISPATCH',p_operation);   
 end;   
 procedure validate_load(p_source json_object_t,p_actor varchar2) is   
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');n number;v_kind varchar2(80);v_binding varchar2(100):=p_source.get_string('binding_operation_id');v_current json_object_t;trip_id number:=p_source.get_number('target_trip_id');st_id number:=p_source.get_number('st_id');v_warehouse number:=p_source.get_number('warehouse_id');   
 begin 
 if p_source.has('group_receipt_operation_id')then RRL_IW_GROUP_NEXT.validate_load(p_source,p_actor);return;end if;
if p_source.has('recovery_operation_id')then RRL_STOCK_IW_RECOVERY_NEXT.validate_load(p_source,p_actor);return;end if;   
 select COMMAND_TYPE into v_kind from RRL_STOCK_OPERATION where OPERATION_ID=op and STATE='IN_FLIGHT';   
 if v_kind='HU_SHIP'then
 select count(*)into n from RRL_STOCK_OPERATION root_op
 where root_op.OPERATION_ID=op and root_op.STATE='IN_FLIGHT'
 and json_value(root_op.RESOLVED_PLAN_JSON,'$.domain.loading.trip'returning number)=trip_id
 and exists(select 1 from json_table(root_op.RESOLVED_PLAN_JSON,'$.domain.shipments[*]'columns(
  BINDING_ID varchar2(100)path '$.domain.interwarehouse_onward_source.binding_operation_id',
  ST_NO number path '$.domain.interwarehouse_onward_source.st_id'))resolved
  where resolved.BINDING_ID=v_binding and resolved.ST_NO=st_id);
 if n!=1 then raise_application_error(-20886,'INTERWARE_NESTED_ACTUAL_TARGET_LOADING_REQUIRED');end if;
 elsif v_kind!='LOAD_SHIPMENT'then raise_application_error(-20886,'INTERWARE_ONWARD_ACTUAL_LOADING_REQUIRED');end if;   
 select count(*)into n from RUSERS u where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=v_warehouse or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,'stock_posting_shipping')=1;if n!=1 then raise_application_error(-20882,'INTERWARE_ONWARD_CURRENT_WARE_ACTOR_REQUIRED');end if;   
 v_current:=describe_source(st_id,v_warehouse);if v_current is null or dbms_lob.compare(v_current.to_clob,p_source.to_clob)!=0 then raise_application_error(-20886,'INTERWARE_ONWARD_LOAD_SOURCE_CHANGED');end if;   
 select count(*)into n from RRL_SBORKA_PALLETS where ID=st_id and TRANSTASK_ID=trip_id;if n!=1 then raise_application_error(-20886,'INTERWARE_ONWARD_ORIGINAL_TARGET_TRIP_REQUIRED');end if;   
 end;   
 procedure dispatched(p_source json_object_t,p_actor varchar2) is   
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');v_bind varchar2(100):=p_source.get_string('binding_operation_id');v_receipt varchar2(100):=p_source.get_string('receipt_operation_id');v_source varchar2(100):=p_source.get_string('source_load_operation_id');v_st number:=p_source.get_number('st_id');v_uid varchar2(200):=p_source.get_string('uid');v_qty number:=RRL_STOCK_MATH.quantity(p_source.get_string('quantity'));v_uom varchar2(20):=p_source.get_string('base_uom');payload json_object_t:=json_object_t();v_body clob;   
 begin 
 if p_source.has('group_receipt_operation_id')then RRL_IW_GROUP_NEXT.dispatched(p_source,p_actor);return;end if;
if p_source.has('recovery_operation_id')then RRL_STOCK_IW_RECOVERY_NEXT.dispatched(p_source,p_actor);return;end if;   
 insert into RRL_INTERWARE_ONWARD_DISPATCH(OPERATION_ID,BIND_OPERATION_ID,RECEIPT_OPERATION_ID,SOURCE_LOAD_OPERATION_ID,ST_ID,ROOT_UID,BASE_QTY,BASE_UOM,ACTOR)values(op,v_bind,v_receipt,v_source,v_st,v_uid,v_qty,v_uom,p_actor);   
 payload.put('operation_id',op);payload.put('receipt_operation_id',v_receipt);payload.put('source_load_operation_id',v_source);payload.put('source_st_id',p_source.get_number('source_st_id'));payload.put('st_id',v_st);payload.put('warehouse_id',p_source.get_number('warehouse_id'));payload.put('pallet_identifier',v_uid);payload.put('quantity',p_source.get_string('quantity'));payload.put('base_uom',v_uom);payload.put('customer_fulfillment_repeated',false);payload.put('external_sap_ack',false);v_body:=payload.to_clob;   
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values('IW.ONWARD:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op||':'||RRL_STOCK_PLAN_HELPER.decimal_text(v_st),'AL32UTF8'),sys.dbms_crypto.hash_sh256)),'INTERWARE_ONWARD_DISPATCHED',v_body);   
 end;   
end;
/


CREATE OR REPLACE package body RRL_STOCK_INTERWARE_PART as
 procedure describe_partial(p_metadata json_object_t,p_original_uid varchar2,p_original_qty number,p_unit varchar2,p_article varchar2,p_domain in out json_object_t)is
  v_target_uid varchar2(200):=p_metadata.get_string('receipt_pallet_identifier');qty number;gross number;reason varchar2(4000):=p_metadata.get_string('discrepancy_reason');ref varchar2(2000):=p_metadata.get_string('discrepancy_reference');
  lot RRL_PALLETS%rowtype;n number;scale number;
 begin
  if v_target_uid is null or v_target_uid=p_original_uid or length(v_target_uid)>50 or lengthb(v_target_uid)>150 or trim(reason)is null or length(trim(reason))<8 or length(reason)>1000 or trim(ref)is null or length(ref)>255 then raise_application_error(-20886,'INTERWARE_PARTIAL_FRESH_PALLET_REASON_REQUIRED');end if;
  qty:=RRL_STOCK_MATH.quantity(p_metadata.get_string('quantity'));gross:=RRL_STOCK_MATH.quantity(p_metadata.get_string('gross_weight_kg'));
  if qty<=0 or qty>=p_original_qty or gross<=0 or gross>1000000 then raise_application_error(-20886,'INTERWARE_PARTIAL_POSITIVE_ACTUAL_QUANTITY_GROSS_REQUIRED');end if;
  select BASE_SCALE into scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM=p_unit and BASE_UOM=p_unit and NUMERATOR=DENOMINATOR
   and POLICY_VERSION=(select max(POLICY_VERSION)from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM=p_unit and BASE_UOM=p_unit and NUMERATOR=DENOMINATOR);
  RRL_STOCK_MATH.assert_base(qty,scale);
  select count(*)into n from RRL_PALLETS where UID_PALLET=v_target_uid;if n!=0 then raise_application_error(-20886,'INTERWARE_PARTIAL_PALLET_ALREADY_EXISTS');end if;
  select count(*)into n from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_original_uid;
  if RRL_INTERWARE_MARK_SCAN.required_for_article(p_article)=1 and n=0 then raise_application_error(-20886,'INTERWARE_PARTIAL_EXACT_SERIALIZED_SELECTION_REQUIRED');end if;
  if n>0 and RRL_INTERWARE_MARK_SCAN.required_for_article(p_article)=0 then raise_application_error(-20886,'INTERWARE_PARTIAL_SERIALIZED_PROFILE_REQUIRED');end if;
  select *into lot from RRL_PALLETS where UID_PALLET=p_original_uid;
  p_domain.put('partial_receipt',true);p_domain.put('original_root_uid',p_original_uid);p_domain.put('uid',v_target_uid);
  p_domain.put('expected_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(p_original_qty));p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));
  p_domain.put('short_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(p_original_qty-qty));p_domain.put('gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(gross));
  p_domain.put('discrepancy_reason',reason);p_domain.put('discrepancy_reference',ref);p_domain.put('source_price',lot.PRICE);
  p_domain.put('source_expiry',to_char(lot.EXPIRY_DATE,'YYYY-MM-DD HH24:MI:SS'));p_domain.put('source_produced',to_char(lot.PRODUCED_DATE,'YYYY-MM-DD HH24:MI:SS'));
  p_domain.put('source_origin_uid',nvl(lot.STOCK_ORIGIN_UID,lot.UID_PALLET));p_domain.put('source_naklad_id',lot.PRIHOD_NAKLAD_ID);
  p_domain.put('gross_weight_basis','MANUAL_RECEIVER_OBSERVATION');p_domain.put('carrier_shortage_resolved',false);
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_PARTIAL_ORIGINAL_LOT_UOM_REQUIRED');
 end;

 procedure describe_selected_units(p_metadata json_object_t,p_domain in out json_object_t)is
  requested clob;original clob;selected clob;n number;distinct_count number;found number;qty number;total number;
 begin
  if not p_domain.has('source_units')then
   if p_metadata.has('unit_keys')and p_metadata.get_array('unit_keys').get_size>0 then raise_application_error(-20886,'INTERWARE_PARTIAL_UNEXPECTED_UNIT_SELECTION');end if;
   return;
  end if;
  if not p_metadata.has('unit_keys')then raise_application_error(-20886,'INTERWARE_PARTIAL_EXACT_UNIT_SELECTION_REQUIRED');end if;
  requested:=p_metadata.get_array('unit_keys').to_clob;original:=p_domain.get_array('source_units').to_clob;
  select count(*),count(distinct K)into n,distinct_count from json_table(requested,'$[*]'columns(K varchar2(64)path '$'));
  if n<1 or n>10000 or n!=distinct_count then raise_application_error(-20886,'INTERWARE_PARTIAL_UNIQUE_UNIT_SELECTION_REQUIRED');end if;
  select count(*),sum(RRL_STOCK_MATH.quantity(o.Q)),
   json_arrayagg(json_object('key'value o.K,'version'value o.V,'quantity'value o.Q,'base_uom'value o.B)order by o.K returning clob)
   into found,total,selected
   from json_table(original,'$[*]'columns(K varchar2(64)path '$.key',V number path '$.version',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))o
   join json_table(requested,'$[*]'columns(K varchar2(64)path '$'))r on r.K=o.K;
  qty:=RRL_STOCK_MATH.quantity(p_domain.get_string('quantity'));
  if found!=n or total!=qty then raise_application_error(-20886,'INTERWARE_PARTIAL_SELECTED_BASE_QUANTITY_CONFLICT');end if;
  p_domain.put('original_source_units',p_domain.get_array('source_units'));
  p_domain.put('source_units',json_array_t.parse(selected));p_domain.put('selected_unit_keys',p_metadata.get_array('unit_keys'));
 end;
 procedure create_pallet(p_domain json_object_t,p_operation varchar2)is
  v_target_uid varchar2(200):=p_domain.get_string('uid');article varchar2(160):=p_domain.get_string('article');origin varchar2(200):=p_domain.get_string('source_origin_uid');
  expiry date:=to_date(p_domain.get_string('source_expiry'),'YYYY-MM-DD HH24:MI:SS');produced date:=to_date(p_domain.get_string('source_produced'),'YYYY-MM-DD HH24:MI:SS');
  qty number:=RRL_STOCK_MATH.quantity(p_domain.get_string('quantity'));gross number:=RRL_STOCK_MATH.quantity(p_domain.get_string('gross_weight_kg'));price number:=p_domain.get_number('source_price');naklad number:=p_domain.get_number('source_naklad_id');
 begin
  if not p_domain.get_boolean('partial_receipt')then raise_application_error(-20863,'INTERWARE_PARTIAL_CAPTURED_PLAN_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',v_target_uid));
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_domain.get_string('original_root_uid')));
  insert into RRL_PALLETS(UID_PALLET,ARTICUL,CREATION_DATE,EXPIRY_DATE,PRODUCED_DATE,UNIT_COUNT,PRICE,STOCK_ORIGIN_UID,CREATED_BY_STOCK_OP,WEIGHT_BRUTTO,PRIHOD_NAKLAD_ID)
   values(v_target_uid,article,systimestamp,expiry,produced,qty,price,origin,p_operation,gross,naklad);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_INTERWARE_PUT as
 procedure assert_scope(p_receipt varchar2,p_actor varchar2,p_superseded number default null)is n number;
 begin
  select count(*)into n from RRL_INTERWARE_RECEIPT r join RUSERS u on u.ID=p_actor where r.OPERATION_ID=p_receipt and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1 and(u.WARE_ID=r.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'INTERWARE_PLACEMENT_ACTOR_REQUIRED');end if;
  if p_superseded is not null and nvl(RRL_HAS_WRIGHT(p_actor,'warehouse_task_edit'),0)!=1 then raise_application_error(-20882,'INTERWARE_REPLAN_TASK_EDIT_REQUIRED');end if;
 end;
 procedure describe_current(p_receipt varchar2,p_actor varchar2,p_task number,p_domain out json_object_t,p_replacing boolean default false) is
 receipt RRL_INTERWARE_RECEIPT%rowtype;plan RRL_INTERWARE_PLAN%rowtype;
 v_target varchar2(60);v_p number;v_h number;v_unit varchar2(20);v_ver number;v_capacity number;v_height number;v_weight number;v_unknown number;v_gross number;n number;unit_wire clob;unit_snapshot clob;unit_count number;unit_total number;unit_distinct number;thermal json_object_t;stored_thermal varchar2(100);stored_lo number;stored_hi number;hu_tree json_object_t;hu_nodes json_array_t;hu_node json_object_t;hu_stock number:=0;
 begin
 select *into receipt from RRL_INTERWARE_RECEIPT where OPERATION_ID=p_receipt;
 select *into plan from RRL_INTERWARE_PLAN where OPERATION_ID=receipt.PLAN_OPERATION_ID;
 plan:=RRL_INTERWARE_ROUTING.resolved(plan);
 select count(*)into n from RUSERS u where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=receipt.WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1;
 if n!=1 then raise_application_error(-20882,'INTERWARE_PLACEMENT_ACTOR_REQUIRED');end if;
 RRL_INTERWARE_THERMAL.assert_release(plan.OPERATION_ID);
 thermal:=json_object_t.parse(RRL_INTERWARE_THERMAL.mode_json(plan.OPERATION_ID));
 if p_task is not null and not p_replacing then
  select TEMP_DECISION_OPERATION_ID,TASK_TEMP_MIN,TASK_TEMP_MAX into stored_thermal,stored_lo,stored_hi from RRL_INTERWARE_PUT_PLAN where TASK_ID=p_task;
  if nvl(stored_lo,-1000)!=nvl(thermal.get_number('task_temp_min'),-1000)or nvl(stored_hi,-1000)!=nvl(thermal.get_number('task_temp_max'),-1000)then raise_application_error(-20886,'INTERWARE_TASK_TEMPERATURE_REPLAN_REQUIRED');end if;
  thermal.put('task_decision_operation_id',stored_thermal);
 end if;
 v_target:=plan.OUTBOUND_DOCK;
 RRL_INTERWARE_THERMAL.assert_cell(thermal.to_clob,receipt.WARE_ID,v_target);
 select count(*)into n from RRL_TRANSPORT_TASK t join RRL_TT_DOCK d on d.DOCK=t.DOCK where t.ID=plan.TARGET_TT_ID and t.DOCK=v_target and d.WARE_ID=receipt.WARE_ID and nvl(d.DOCK_IS_BLOCKED,0)=0 and t.CONDITION='Спланирован'and nvl(t.DELETED,0)=0;
 if n!=1 then raise_application_error(-20886,'INTERWARE_ORIGINAL_TARGET_TRIP_UNAVAILABLE');end if;
 select count(*)into n from RRL_INTERWARE_PLACEMENT where RECEIPT_OPERATION_ID=p_receipt;if n!=0 then raise_application_error(-20886,'INTERWARE_ALREADY_PLACED');end if;
 select count(*)into n from RRL_INTERWARE_PUT_PLAN p join RRL_WAREHOUSE_TASK wt on wt.TASK_ID=p.TASK_ID where p.RECEIPT_OPERATION_ID=p_receipt and wt.STATUS!='CANCELLED'and(p_task is null or wt.TASK_ID!=p_task);
 if n!=0 then raise_application_error(-20886,'INTERWARE_ACTIVE_PLACEMENT_EXISTS');end if;
 select REMAIN,HARD_RESERVED_BASE,BASE_UOM,STOCK_VERSION into v_p,v_h,v_unit,v_ver from RRL_REMAINS where UID_POLETA=receipt.ROOT_UID and CELL=receipt.RECEIVE_CELL;
 if v_p!=receipt.BASE_QTY or v_h!=0 or v_unit!=receipt.BASE_UOM then raise_application_error(-20886,'INTERWARE_WHOLE_UNRESERVED_RECEIPT_REQUIRED');end if;
 select count(*)into n from RRL_REMAINS where UID_POLETA=receipt.ROOT_UID and CELL!=receipt.RECEIVE_CELL and(REMAIN!=0 or HARD_RESERVED_BASE!=0);if n!=0 then raise_application_error(-20886,'INTERWARE_MULTIPLE_STOCK_CELLS_DENIED');end if;
 select count(*)into n from dual where exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=receipt.ARTICLE)or exists(select 1 from RRL_SKU_RECEIPT_POLICY where ARTICUL=receipt.ARTICLE and MARKING_REQUIRED=1)or exists(select 1 from RRL_FINISHED_GOODS_SKU where ARTICUL=receipt.ARTICLE and CRPT_REQUIRED=1);
 select count(*)into unit_count from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=receipt.ROOT_UID;
 if n>0 or unit_count>0 then
  if receipt.ORIGINAL_ROOT_UID is not null then
   select json_query(RESOLVED_PLAN_JSON,'$.domain.source_units' returning clob)into unit_wire from RRL_STOCK_OPERATION where OPERATION_ID=receipt.OPERATION_ID and STATE='APPLIED';
   declare envelope json_object_t:=json_object_t();a json_array_t:=json_array_t.parse(unit_wire);begin
    envelope.put('units',a);envelope.put('physical_unit_count',a.get_size);unit_wire:=envelope.to_clob;
   end;
  else
  select MANIFEST_JSON into unit_wire from RRL_INTERWARE_UNIT_MANIFEST where PLAN_OPERATION_ID=receipt.PLAN_OPERATION_ID;
  end if;
  select count(*),sum(u.BASE_QTY),count(distinct u.PHYSICAL_UNIT_KEY),
   json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob)
   into n,unit_total,unit_distinct,unit_snapshot
   from RRL_WMS_RECEIPT_UNIT u join json_table(unit_wire,'$.units[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))j on j.K=u.PHYSICAL_UNIT_KEY
   where u.CURRENT_UID=receipt.ROOT_UID and u.CURRENT_CELL=receipt.RECEIVE_CELL and u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null and u.BASE_QTY=RRL_STOCK_MATH.quantity(j.Q)and u.BASE_UOM=j.B and u.BASE_UOM=receipt.BASE_UOM;
  if unit_count<1 or unit_count>10000 or n!=unit_count or unit_distinct!=unit_count or unit_total!=receipt.BASE_QTY or json_object_t.parse(unit_wire).get_number('physical_unit_count')!=unit_count then raise_application_error(-20884,'INTERWARE_ORIGINAL_AVAILABLE_UNITS_REQUIRED');end if;
 end if;
 if receipt.ORIGINAL_ROOT_UID is not null then
  select WEIGHT_BRUTTO into v_gross from RRL_PALLETS where UID_PALLET=receipt.ROOT_UID;
 else
 select GROSS_WEIGHT_KG into v_gross from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=receipt.SOURCE_LOAD_OPERATION_ID;
 end if;
 RRL_STOCK_IW_PUT_CELL.assert_target(receipt.WARE_ID,receipt.ROOT_UID,receipt.RECEIVE_CELL,v_target,v_gross,p_task);
 p_domain:=json_object_t();p_domain.put('temperature',thermal);if unit_snapshot is not null then p_domain.put('physical_units',json_array_t.parse(unit_snapshot));end if;p_domain.put('receipt_operation_id',p_receipt);p_domain.put('plan_operation_id',receipt.PLAN_OPERATION_ID);p_domain.put('warehouse_id',receipt.WARE_ID);p_domain.put('uid',receipt.ROOT_UID);p_domain.put('article',receipt.ARTICLE);
 p_domain.put('from_cell',receipt.RECEIVE_CELL);p_domain.put('target_cell',v_target);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(receipt.BASE_QTY));p_domain.put('base_uom',receipt.BASE_UOM);p_domain.put('stock_version',v_ver);p_domain.put('target_trip_id',plan.TARGET_TT_ID);
 if plan.SOURCE_PLACE_UID is not null then
 hu_tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(plan.SOURCE_PLACE_UID,p_task));hu_nodes:=hu_tree.get_array('nodes');
 if hu_tree.get_string('cell')!=receipt.RECEIVE_CELL or hu_tree.get_number('warehouse')!=receipt.WARE_ID or hu_tree.get_number('leaf_count')!=1 or hu_tree.get_array('ancestors').get_size!=0 then raise_application_error(-20886,'INTERWARE_WHOLE_RECEIVED_HU_REQUIRED');end if;
 for i in 0..hu_nodes.get_size-1 loop hu_node:=treat(hu_nodes.get(i)as json_object_t);
 if hu_node.get_number('open_task_count')>0 then raise_application_error(-20886,'INTERWARE_HU_OTHER_PHYSICAL_TASK_OPEN');end if;
 if hu_node.get_string('kind')='STOCK'then
  hu_stock:=hu_stock+1;
  if hu_node.get_string('uid')!=receipt.ROOT_UID or RRL_STOCK_MATH.quantity(hu_node.get_string('quantity'))!=receipt.BASE_QTY then raise_application_error(-20886,'INTERWARE_HU_ORIGINAL_STOCK_LEAF_REQUIRED');end if;
 elsif hu_node.get_string('kind')!='CONTAINER'then raise_application_error(-20886,'INTERWARE_HU_STOCK_CONTAINER_ONLY');end if;
 end loop;
 if hu_stock!=1 then raise_application_error(-20886,'INTERWARE_HU_ONE_STOCK_REQUIRED');end if;
 p_domain.put('physical_place_uid',plan.SOURCE_PLACE_UID);p_domain.put('hu_version',treat(hu_nodes.get(0)as json_object_t).get_number('version'));
 p_domain.put('hu_snapshot',hu_tree);
 end if;

 exception when no_data_found then raise_application_error(-20886,'INTERWARE_RECEIPT_OUTBOUND_CELL_REQUIRED');
 end;
 procedure describe_plan(p_request clob,p_actor varchar2,p_domain out json_object_t)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');
  receipt_id varchar2(100):=d.get_object('source').get_string('receipt_operation_id');old_task number:=m.get_number('superseded_task_id');
  t RRL_WAREHOUSE_TASK%rowtype;p RRL_INTERWARE_PUT_PLAN%rowtype;reason nvarchar2(500):=m.get_string('replan_reason');n number;
 begin
  assert_scope(receipt_id,p_actor,old_task);
  if old_task is not null then
   if old_task<=0 or old_task!=trunc(old_task)or trim(reason)is null then raise_application_error(-20871,'INTERWARE_REPLAN_OLD_TASK_REASON_REQUIRED');end if;
   select *into p from RRL_INTERWARE_PUT_PLAN where TASK_ID=old_task;
   select *into t from RRL_WAREHOUSE_TASK where TASK_ID=old_task;
   if p.RECEIPT_OPERATION_ID!=receipt_id or t.STATUS is null or t.STATUS!='PLANNED'or nvl(t.TASK_TYPE,'~')!='PUTAWAY'or nvl(t.TASK_SOURCE,'~')!='MANUAL'or nvl(t.SOURCE_DOC_TYPE,'~')not in('INTERWARE','WAREHOUSE_HU')or t.SOURCE_DOC_ID is null or t.SOURCE_DOC_ID!=t.TASK_ID or t.STARTED_AT is not null or t.STARTED_AT_INSTANT is not null or t.FACT_QTY is not null or t.RESOURCE_ID is not null or t.RESOURCE_SESSION_ID is not null or t.EQUIPMENT_ID is not null then raise_application_error(-20886,'INTERWARE_REPLAN_UNSTARTED_UNASSIGNED_ORIGINAL_TASK_REQUIRED');end if;
   select count(*)into n from RRL_STOCK_OPERATION where OPERATION_ID=p.OPERATION_ID and STATE='APPLIED'and COMMAND_TYPE='INTERWARE_PUTAWAY_PLAN';if n!=1 then raise_application_error(-20886,'INTERWARE_REPLAN_ORIGINAL_APPLIED_PLAN_REQUIRED');end if;
   describe_current(receipt_id,p_actor,old_task,p_domain,true);
   if p_domain.has('physical_place_uid')then
    if t.SOURCE_DOC_TYPE!='WAREHOUSE_HU'or t.UID_PALLET!=p_domain.get_string('physical_place_uid')or t.HU_CONTENT_VERSION!=p_domain.get_number('hu_version')or t.FROM_CELL!=p_domain.get_string('from_cell')or t.QTY!=1 or t.UNIT_CODE!='HU'or t.QTY_MODE!='PALLET'then raise_application_error(-20886,'INTERWARE_HU_REPLAN_ORIGINAL_TASK_IDENTITY_REQUIRED');end if;
   else
    if t.SOURCE_DOC_TYPE!='INTERWARE'or t.UID_PALLET!=p_domain.get_string('uid')or t.FROM_CELL!=p_domain.get_string('from_cell')or t.QTY!=RRL_STOCK_MATH.quantity(p_domain.get_string('quantity'))or t.UNIT_CODE!=p_domain.get_string('base_uom')or t.QTY_MODE!='PALLET'then raise_application_error(-20886,'INTERWARE_REPLAN_ORIGINAL_TASK_IDENTITY_REQUIRED');end if;
   end if;
   p_domain.put('superseded_task_id',old_task);p_domain.put('superseded_plan_operation_id',p.OPERATION_ID);p_domain.put('replan_reason',reason);
  else
   if m.has('replan_reason')then raise_application_error(-20871,'INTERWARE_REPLAN_SUPERSEDED_TASK_REQUIRED');end if;
   describe_current(receipt_id,p_actor,null,p_domain);
  end if;
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_REPLAN_ORIGINAL_TASK_REQUIRED');
 end;
 procedure declare_rows(p_domain json_object_t,p_resources in out nocopy json_array_t) is
 begin
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INTERWARE_RECEIPT',p_domain.get_string('receipt_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INTERWARE_PLAN',p_domain.get_string('plan_operation_id'));
 if p_domain.has('superseded_task_id')then
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(p_domain.get_number('superseded_task_id')));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INTERWARE_PUT_PLAN',p_domain.get_string('superseded_plan_operation_id'));
 end if;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();v_task number;
 begin
 describe_plan(p_request,d.get_string('actor'),v);
 select RRL_WAREHOUSE_TASK_SQ.nextval into v_task from dual;v.put('task_id',v_task);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 declare_rows(v,r);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_PUT_PLAN',p_operation);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task));
 RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('uid'),v.get_string('article'),v.get_string('from_cell'),v.get_string('target_cell'));
 if v.has('hu_snapshot')then
 declare nodes json_array_t:=v.get_object('hu_snapshot').get_array('nodes');links json_array_t:=v.get_object('hu_snapshot').get_array('links');item json_object_t;begin
 for i in 0..nodes.get_size-1 loop item:=treat(nodes.get(i)as json_object_t);
 RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',item.get_string('uid'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',item.get_string('uid'));end loop;
 for i in 0..links.get_size-1 loop item:=treat(links.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(item.get_number('id')));end loop;
 end;
 end if;

 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');resolved clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_receipt varchar2(100);v_task number;v_ware number;v_uid varchar2(200);v_article varchar2(160);v_from varchar2(60);v_to varchar2(60);v_unit varchar2(20);v_qty number;temp_op varchar2(100);temp_lo number;temp_hi number;old_task number;reason nvarchar2(500);
 begin
 select RESOLVED_PLAN_JSON into resolved from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(resolved).get_object('domain');v_receipt:=v.get_string('receipt_operation_id');v_task:=v.get_number('task_id');
 describe_plan(p_request,p_actor,fresh);fresh.put('task_id',v_task);
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'INTERWARE_PLACEMENT_PLAN_CHANGED');end if;
 v_ware:=v.get_number('warehouse_id');v_uid:=v.get_string('uid');v_article:=v.get_string('article');v_from:=v.get_string('from_cell');v_to:=v.get_string('target_cell');v_unit:=v.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));
 if v.has('superseded_task_id')then
  old_task:=v.get_number('superseded_task_id');reason:=v.get_string('replan_reason');
  update RRL_WAREHOUSE_TASK set STATUS='CANCELLED',CANCELLED_AT=systimestamp,CANCELLED_BY=p_actor,LAST_ERROR=reason where TASK_ID=old_task and STATUS='PLANNED'and STARTED_AT is null and STARTED_AT_INSTANT is null and RESOURCE_ID is null and RESOURCE_SESSION_ID is null and EQUIPMENT_ID is null;
  if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: superseded interwarehouse task');end if;
  j.put('superseded_task_id',old_task);j.put('replan_reason',reason);
 end if;
 if v.has('physical_place_uid')then
 declare place_id varchar2(200):=v.get_string('physical_place_uid');version_no number:=v.get_number('hu_version');begin
 insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,SOURCE_DOC_ID,UID_PALLET,TARGET_ARTICUL,FROM_CELL,TO_CELL,FROM_WARE_ID,TO_WARE_ID,QTY,UNIT_CODE,QTY_MODE,STATUS,CREATED_BY,HU_CONTENT_VERSION)
 values(v_task,'PUTAWAY','MANUAL',v_task,'WAREHOUSE_HU',v_task,place_id,v_article,v_from,v_to,v_ware,v_ware,1,'HU','PALLET','PLANNED',p_actor,version_no);
 j.put('physical_place_identifier',place_id);j.put('task_quantity','1');j.put('task_unit','HU');
 end;
 else
 insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,SOURCE_DOC_ID,UID_PALLET,TARGET_ARTICUL,FROM_CELL,TO_CELL,FROM_WARE_ID,TO_WARE_ID,QTY,UNIT_CODE,QTY_MODE,STATUS,CREATED_BY)
 values(v_task,'PUTAWAY','MANUAL',v_task,'INTERWARE',v_task,v_uid,v_article,v_from,v_to,v_ware,v_ware,v_qty,v_unit,'PALLET','PLANNED',p_actor);
 end if;
 temp_op:=v.get_object('temperature').get_string('decision_operation_id');temp_lo:=v.get_object('temperature').get_number('task_temp_min');temp_hi:=v.get_object('temperature').get_number('task_temp_max');
 insert into RRL_INTERWARE_PUT_PLAN(OPERATION_ID,RECEIPT_OPERATION_ID,TASK_ID,TARGET_CELL,ACTOR,TEMP_DECISION_OPERATION_ID,TASK_TEMP_MIN,TASK_TEMP_MAX)values(op,v_receipt,v_task,v_to,p_actor,temp_op,temp_lo,temp_hi);
 j.put('temperature',v.get_object('temperature'));j.put('operation_id',op);j.put('task_id',v_task);j.put('receipt_operation_id',v_receipt);j.put('from_cell',v_from);j.put('to_cell',v_to);j.put('quantity',v.get_string('quantity'));j.put('base_uom',v_unit);j.put('stock_changed',false);p_result:=j.to_clob;
 end;
 procedure plan_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t) is
 v_receipt varchar2(100);v_target varchar2(60);v json_object_t;
 begin
 select RECEIPT_OPERATION_ID,TARGET_CELL into v_receipt,v_target from RRL_INTERWARE_PUT_PLAN where TASK_ID=p_task.TASK_ID;
 describe_current(v_receipt,p_actor,p_task.TASK_ID,v);
 if v.has('physical_place_uid')then
 if p_task.TASK_SOURCE!='MANUAL'or p_task.TASK_TYPE!='PUTAWAY'or p_task.SOURCE_DOC_TYPE!='WAREHOUSE_HU'or p_task.SOURCE_DOC_ID!=p_task.TASK_ID or p_task.UID_PALLET!=v.get_string('physical_place_uid')or p_task.HU_CONTENT_VERSION!=v.get_number('hu_version')or p_task.FROM_CELL!=v.get_string('from_cell')or p_task.TO_CELL!=v.get_string('target_cell')or p_task.UNIT_CODE!='HU'or p_task.QTY!=1 or p_task.QTY_MODE!='PALLET'or v_target!=p_task.TO_CELL then raise_application_error(-20886,'INTERWARE_ORIGINAL_HU_TASK_REQUIRED');end if;
 else
 if p_task.TASK_SOURCE!='MANUAL' or p_task.TASK_TYPE!='PUTAWAY' or p_task.SOURCE_DOC_TYPE!='INTERWARE' or p_task.SOURCE_DOC_ID!=p_task.TASK_ID or p_task.UID_PALLET!=v.get_string('uid') or p_task.FROM_CELL!=v.get_string('from_cell') or p_task.TO_CELL!=v.get_string('target_cell') or p_task.UNIT_CODE!=v.get_string('base_uom') or p_task.QTY!=RRL_STOCK_MATH.quantity(v.get_string('quantity')) or p_task.QTY_MODE!='PALLET' or v_target!=p_task.TO_CELL then raise_application_error(-20886,'INTERWARE_ORIGINAL_TASK_REQUIRED');end if;
 end if;
 declare_rows(v,p_resources);RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INTERWARE_PLACEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(p_task.TASK_ID));
 p_domain.put('interwarehouse_placement',v);
 end;
 procedure validate_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_frozen json_object_t) is
 resources json_array_t:=json_array_t();domain json_object_t:=json_object_t();
 begin
 plan_task(p_task,p_actor,resources,domain);
 if dbms_lob.compare(p_frozen.to_clob,domain.get_object('interwarehouse_placement').to_clob)!=0 then raise_application_error(-20886,'INTERWARE_TASK_SOURCE_CHANGED');end if;
 end;
 procedure complete_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_quantity number,p_target_uid varchar2,p_actor varchar2) is
 v_receipt varchar2(100);receipt RRL_INTERWARE_RECEIPT%rowtype;op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');v_json clob;
 begin
 select RECEIPT_OPERATION_ID into v_receipt from RRL_INTERWARE_PUT_PLAN where TASK_ID=p_task.TASK_ID;select *into receipt from RRL_INTERWARE_RECEIPT where OPERATION_ID=v_receipt;
 if p_quantity!=receipt.BASE_QTY or p_target_uid!=receipt.ROOT_UID then raise_application_error(-20886,'INTERWARE_WHOLE_PLACEMENT_REQUIRED');end if;
 insert into RRL_INTERWARE_PLACEMENT(TASK_ID,RECEIPT_OPERATION_ID,OPERATION_ID,ROOT_UID,WARE_ID,TARGET_CELL,BASE_QTY,BASE_UOM,ACTOR)values(p_task.TASK_ID,v_receipt,op,receipt.ROOT_UID,receipt.WARE_ID,p_task.TO_CELL,receipt.BASE_QTY,receipt.BASE_UOM,p_actor);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_INTERWARE_REC as
 procedure execute_group(p_request clob,p_actor varchar2,v json_object_t,p_result out clob)is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');kind_value varchar2(80):=d.get_string('command_type');
 j json_object_t:=json_object_t();lots json_array_t:=v.get_array('lots');results json_array_t:=json_array_t();item json_object_t;manifest json_object_t;line_value json_object_t;
 v_plan varchar2(100):=v.get_string('plan_operation_id');v_root varchar2(200):=v.get_string('uid');v_ware number:=v.get_number('warehouse_id');
 v_cell varchar2(60):=v.get_string('receive_cell');v_unload varchar2(100):=v.get_string('unload_operation_id');v_uid varchar2(200);v_article varchar2(160);v_qty number;v_uom varchar2(20);v_version number;v_event number;v_st number;v_payload clob;unit_count number:=0;
 begin
 RRL_IW_GROUP_REC.assert_fresh(p_request,p_actor,v);
 j.put('operation_id',op);j.put('plan_operation_id',v_plan);j.put('physical_place_identifier',v_root);j.put('warehouse_id',v_ware);j.put('source_load_operation_id',v.get_string('source_load_operation_id'));j.put('customer_fulfillment_repeated',false);
 if kind_value='INTERWARE_UNLOAD'then
  insert into RRL_IW_GROUP_UNLOAD(OPERATION_ID,PLAN_OPERATION_ID,ROOT_UID,WARE_ID,ACTOR)values(op,v_plan,v_root,v_ware,p_actor);
  j.put('status','UNLOADED_PENDING_RECEIPT');j.put('stock_changed',false);p_result:=j.to_clob;return;
 end if;
 RRL_STOCK_LOCATION_CORE.assert_receiving(v_cell,v_ware);
 insert into RRL_IW_GROUP_RECEIPT(OPERATION_ID,PLAN_OPERATION_ID,UNLOAD_OPERATION_ID,ROOT_UID,WARE_ID,RECEIVE_CELL,ACTOR)values(op,v_plan,v_unload,v_root,v_ware,v_cell,p_actor);
 for i in 0..lots.get_size-1 loop
  item:=treat(lots.get(i)as json_object_t);manifest:=item.get_object('issued_manifest');
  v_st:=item.get_number('st_id');v_uid:=item.get_string('uid');v_article:=item.get_string('article');v_qty:=RRL_STOCK_MATH.quantity(item.get_string('quantity'));v_uom:=item.get_string('base_uom');v_version:=item.get_number('uom_version');
  RRL_STOCK_BALANCE_CORE.apply_delta(v_uid,v_cell,v_qty,0,v_uom,v_version,0);
  RRL_STOCK_BALANCE_CORE.write_leg(v_uid,null,v_cell,v_qty,v_uom,v_version,i+1,1,1,p_actor,v_event);
  if manifest.get_number('physical_unit_count')>0 then
   RRL_STOCK_UNIT_CORE.receive_issued(v_uid,manifest.get_string('source_cell'),v_cell,v_qty,manifest.get_array('units').to_clob);
   unit_count:=unit_count+manifest.get_number('physical_unit_count');
  end if;
  insert into RRL_IW_GROUP_RECEIPT_LINE(OPERATION_ID,ROOT_UID,ST_ID,ARTICLE,BASE_QTY,BASE_UOM,STOCK_EVENT_ID)values(op,v_uid,v_st,v_article,v_qty,v_uom,v_event);
  line_value:=json_object_t();line_value.put('uid',v_uid);line_value.put('st_id',item.get_number('st_id'));line_value.put('article',v_article);line_value.put('quantity',item.get_string('quantity'));line_value.put('base_uom',v_uom);line_value.put('event_id',v_event);results.append(line_value);
 end loop;
 RRL_IW_HU_REC_CORE.restore(v,op,p_actor);
 j.put('status','RECEIVED_PENDING_WHOLE_HU_PLACEMENT');j.put('stock_changed',true);j.put('cell',v_cell);j.put('physical_tree_restored',true);j.put('physical_place_count',1);j.put('stock_leaf_count',lots.get_size);j.put('lines',results);j.put('physical_unit_count',unit_count);j.put('regulatory_ack_verified',false);j.put('external_sap_ack',false);
 v_payload:=j.to_clob;
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values('INTERWAREGROUP:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op,'AL32UTF8'),sys.dbms_crypto.hash_sh256)),'INTERWAREHOUSE_RECEIVED',v_payload);
 p_result:=j.to_clob;
 end;
 procedure assert_scope(p_plan varchar2,p_actor varchar2)is n number;
 begin
  select count(*)into n from RRL_IW_GROUP_PLAN where OPERATION_ID=p_plan;
  if n=1 then
   select count(*)into n from RRL_IW_GROUP_PLAN p join RUSERS u on u.ID=p_actor where p.OPERATION_ID=p_plan and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1 and(u.WARE_ID=p.TARGET_WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
   if n!=1 then raise_application_error(-20882,'INTERWARE_GROUP_TARGET_RECEIVER_REQUIRED');end if;return;
  end if;
  select count(*)into n from RRL_INTERWARE_PLAN p join RUSERS u on u.ID=p_actor where p.OPERATION_ID=p_plan and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1 and(u.WARE_ID=p.TARGET_WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'INTERWARE_TARGET_RECEIVER_REQUIRED');end if;
 end;
 procedure describe_source(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v_plan varchar2(100):=d.get_object('source').get_string('plan_operation_id');
 plan RRL_INTERWARE_PLAN%rowtype;cargo RRL_TT_HU_LOAD_FACT%rowtype;lot RRL_PALLETS%rowtype;nodes json_array_t;leaf json_object_t;
 v_kind varchar2(80):=d.get_string('command_type');v_unload varchar2(100);v_vehicle varchar2(60);v_cell varchar2(60);v_uom varchar2(20);v_qty number;v_version number;v_scan_article varchar2(160);v_scan_uom varchar2(20);n number;manifest clob;source_units json_object_t;scan_domain json_object_t;scan_legs json_array_t;scan_leg json_object_t;unit_count number;
 begin
 select * into plan from RRL_INTERWARE_PLAN where OPERATION_ID=v_plan;
 plan:=RRL_INTERWARE_ROUTING.resolved(plan);
 select count(*)into n from RUSERS u where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=plan.TARGET_WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1;
 if n!=1 then raise_application_error(-20882,'INTERWARE_TARGET_RECEIVER_REQUIRED');end if;
 select * into cargo from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=plan.SOURCE_LOAD_OPERATION_ID;
 if cargo.STATUS!='DEPARTED' or dbms_lob.compare(cargo.COMPOSITION_JSON,plan.SOURCE_COMPOSITION_JSON)!=0 then raise_application_error(-20886,'INTERWARE_ORIGINAL_DEPARTURE_CHANGED');end if;
 select * into lot from RRL_PALLETS where UID_PALLET=plan.ROOT_UID;
 nodes:=json_object_t.parse(plan.SOURCE_COMPOSITION_JSON).get_array('nodes');
 if nodes.get_size<1 or nodes.get_size>200 then raise_application_error(-20886,'INTERWARE_STOCK_NODE_BOUND');end if;
 leaf:=null;
 for i in 0..nodes.get_size-1 loop
  declare candidate json_object_t:=treat(nodes.get(i)as json_object_t);begin
   if candidate.get_string('kind')='STOCK'then
    if leaf is not null then raise_application_error(-20886,'INTERWARE_ONE_STOCK_NODE_REQUIRED');end if;leaf:=candidate;
   elsif candidate.get_string('kind')!='CONTAINER'then raise_application_error(-20886,'INTERWARE_STOCK_CONTAINER_ONLY');end if;
  end;
 end loop;
 if leaf is null then raise_application_error(-20886,'INTERWARE_STOCK_NODE_REQUIRED');end if;
 RRL_IW_HU_SOURCE.assert_context(plan.SOURCE_LOAD_OPERATION_ID,plan.SOURCE_HU_JSON);

 if leaf.get_string('uid')!=plan.ROOT_UID or leaf.get_string('article')!=lot.ARTICUL or leaf.get_string('kind')!='STOCK' then raise_application_error(-20886,'INTERWARE_ORIGINAL_LOT_CHANGED');end if;
 v_qty:=RRL_STOCK_MATH.quantity(leaf.get_string('quantity'));v_uom:=leaf.get_string('base_uom');
 select count(*)into n from dual where exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=lot.ARTICUL)or exists(select 1 from RRL_SKU_RECEIPT_POLICY where ARTICUL=lot.ARTICUL and MARKING_REQUIRED=1)or exists(select 1 from RRL_FINISHED_GOODS_SKU where ARTICUL=lot.ARTICUL and CRPT_REQUIRED=1);
 manifest:=RRL_INTERWARE_UNIT_SOURCE.issued_manifest(plan.SOURCE_LOAD_OPERATION_ID,plan.ROOT_UID,plan.SOURCE_COMPOSITION_JSON);
 source_units:=json_object_t.parse(manifest);
 if source_units.get_number('physical_unit_count')>0 then
  select MANIFEST_JSON into manifest from RRL_INTERWARE_UNIT_MANIFEST where PLAN_OPERATION_ID=v_plan;
  if dbms_lob.compare(manifest,source_units.to_clob)!=0 then raise_application_error(-20886,'INTERWARE_FROZEN_UNIT_SOURCE_CHANGED');end if;
 end if;
 select count(*)into n from RRL_REMAINS where UID_POLETA=plan.ROOT_UID and(nvl(REMAIN,0)!=0 or nvl(HARD_RESERVED_BASE,0)!=0);
 if n!=0 then raise_application_error(-20886,'INTERWARE_SOURCE_ALREADY_IN_STOCK');end if;
 select count(*)into n from RRL_INTERWARE_RECEIPT where PLAN_OPERATION_ID=v_plan;
 if n!=0 then raise_application_error(-20886,'INTERWARE_PLAN_ALREADY_RECEIVED');end if;
 select TRANSPORT into v_vehicle from RRL_TRANSPORT_TASK where ID=plan.SOURCE_TT_ID;
 if m.get_string('scan_pallet') is null or m.get_string('scan_pallet')!=nvl(plan.SOURCE_PLACE_UID,plan.ROOT_UID) then raise_application_error(-20886,'INTERWARE_PALLET_SCAN_REQUIRED');end if;
 select count(*)into n from RRL_TT_DOCK where DOCK=plan.INBOUND_DOCK and WARE_ID=plan.TARGET_WARE_ID and nvl(DOCK_IS_BLOCKED,0)=0;
 if n!=1 then raise_application_error(-20886,'INTERWARE_INBOUND_DOCK_UNAVAILABLE');end if;
 p_domain:=json_object_t();p_domain.put('plan_operation_id',v_plan);p_domain.put('source_load_operation_id',plan.SOURCE_LOAD_OPERATION_ID);p_domain.put('source_st_id',plan.SOURCE_ST_ID);
 p_domain.put('uid',plan.ROOT_UID);p_domain.put('warehouse_id',plan.TARGET_WARE_ID);p_domain.put('article',lot.ARTICUL);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));p_domain.put('base_uom',v_uom);p_domain.put('vehicle_number',v_vehicle);p_domain.put('inbound_dock',plan.INBOUND_DOCK);
 if plan.SOURCE_HU_JSON is not null then p_domain.put('nested_source',json_object_t.parse(plan.SOURCE_HU_JSON));end if;
 if source_units.get_number('physical_unit_count')>0 then
  p_domain.put('source_units',source_units.get_array('units'));p_domain.put('source_cell',source_units.get_string('source_cell'));p_domain.put('original_unit_signature',source_units.get_string('unit_signature'));
 end if;
 if m.get_boolean('partial_receipt')then
  if plan.SOURCE_HU_JSON is not null then raise_application_error(-20886,'INTERWARE_NESTED_WHOLE_RECEIPT_REQUIRED');end if;
  if v_kind!='INTERWARE_RECEIVE'then raise_application_error(-20886,'INTERWARE_PARTIAL_RECEIPT_ONLY');end if;
  RRL_STOCK_INTERWARE_PART.describe_partial(m,plan.ROOT_UID,v_qty,v_uom,lot.ARTICUL,p_domain);
  v_qty:=RRL_STOCK_MATH.quantity(p_domain.get_string('quantity'));
  RRL_STOCK_INTERWARE_PART.describe_selected_units(m,p_domain);
 end if;
 if v_kind='INTERWARE_UNLOAD' then
  select count(*)into n from RRL_INTERWARE_UNLOAD where PLAN_OPERATION_ID=v_plan;if n!=0 then raise_application_error(-20886,'INTERWARE_PLAN_ALREADY_UNLOADED');end if;
  if m.get_string('scan_vehicle') is null or m.get_string('scan_vehicle')!=v_vehicle or m.get_string('scan_dock') is null or m.get_string('scan_dock')!=plan.INBOUND_DOCK then raise_application_error(-20886,'INTERWARE_VEHICLE_DOCK_SCAN_REQUIRED');end if;
 else
  select OPERATION_ID into v_unload from RRL_INTERWARE_UNLOAD where PLAN_OPERATION_ID=v_plan;
  v_cell:=m.get_string('scan_cell');
  select count(*)into n from RRL_CELLS where CELL=v_cell and WARE_ID=plan.TARGET_WARE_ID and nvl(BLOCKED_FOR_ACCEPT,0)=0 and BLOCKED_FOR_REMAINS=1 and BLOCKED_FOR_POPOLNENIE=1;
  if n!=1 then raise_application_error(-20886,'INTERWARE_TARGET_RECEIVE_CELL_REQUIRED');end if;
  if m.get_string('article') is null or m.get_string('article')!=lot.ARTICUL or m.get_string('base_uom') is null or m.get_string('base_uom')!=v_uom or RRL_STOCK_MATH.quantity(m.get_string('quantity'))!=v_qty then raise_application_error(-20886,'INTERWARE_EXACT_ORIGINAL_QUANTITY_REQUIRED');end if;
  RRL_STOCK_QC_ITEM.resolve_barcode(m.get_string('scan_article'),v_scan_article,v_scan_uom);
  if v_scan_article!=lot.ARTICUL then raise_application_error(-20886,'INTERWARE_FOREIGN_ARTICLE_BARCODE');end if;
  select max(POLICY_VERSION)into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=lot.ARTICUL and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=DENOMINATOR;
  if v_version is null then raise_application_error(-20886,'INTERWARE_BASE_UOM_REQUIRED');end if;
  if source_units.get_number('physical_unit_count')>0 then
   scan_leg:=json_object_t();scan_leg.put('article',lot.ARTICUL);scan_leg.put('uid',plan.ROOT_UID);scan_leg.put('cell',source_units.get_string('source_cell'));scan_leg.put('base_uom',v_uom);scan_leg.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));
   if p_domain.has('partial_receipt')then
    scan_leg.put('uid',plan.ROOT_UID);scan_leg.put('selected_unit_keys',p_domain.get_array('selected_unit_keys'));
   end if;
   scan_legs:=json_array_t();scan_legs.append(scan_leg);scan_domain:=json_object_t();scan_domain.put('legs',scan_legs);
   if RRL_INTERWARE_MARK_SCAN.required_for_article(lot.ARTICUL)=1 then RRL_INTERWARE_MARK_SCAN.validate_scan(scan_domain.to_clob,m.to_clob,unit_count);end if;
  elsif m.has('unit_scans') and m.get_array('unit_scans').get_size>0 then raise_application_error(-20886,'INTERWARE_UNEXPECTED_UNIT_SCANS');end if;
  p_domain.put('unload_operation_id',v_unload);p_domain.put('receive_cell',v_cell);p_domain.put('uom_version',v_version);
 end if;
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_PLAN_DEPARTURE_UNLOAD_OR_LOT_REQUIRED');
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();units json_array_t;unit_value json_object_t;
 begin
 declare group_count number;group_plan varchar2(100):=d.get_object('source').get_string('plan_operation_id');begin
  select count(*)into group_count from RRL_IW_GROUP_PLAN where OPERATION_ID=group_plan;
  if group_count=1 then RRL_IW_GROUP_REC.compile_command(p_request,p_operation,p_policies,p_resources,p_domain);return;end if;
 end;
 describe_source(p_request,d.get_string('actor'),v);
 RRL_IW_HU_REC_CORE.declare_rows(v,p_operation,r);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_PLAN',v.get_string('plan_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_UNLOAD',nvl(v.get_string('unload_operation_id'),p_operation));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECEIPT',p_operation);
 RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('uid'),v.get_string('article'),null,v.get_string('receive_cell'));

 if v.has('partial_receipt')then
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',v.get_string('uid'));
  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('original_root_uid'),v.get_string('article'),null,null);
  RRL_STOCK_PLAN_HELPER.anchor(r,50,'STOCK',v.get_string('source_origin_uid'));
 end if;
 if v.has('source_units')then
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_UNIT_MANIFEST',v.get_string('plan_operation_id'));
  units:=v.get_array('source_units');
  for i in 0..units.get_size-1 loop unit_value:=treat(units.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',unit_value.get_string('key'));end loop;
 end if;
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');v_kind varchar2(80):=d.get_string('command_type');resolved clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_plan varchar2(100);v_uid varchar2(200);v_source varchar2(100);v_unload varchar2(100);v_ware number;v_article varchar2(160);v_cell varchar2(60);v_uom varchar2(20);v_qty number;v_ver number;v_event number;v_vehicle varchar2(60);v_dock varchar2(60);v_payload clob;v_original_root varchar2(200);v_expected_qty number;v_short_reason varchar2(4000);v_short_ref varchar2(2000);
 begin
 select RESOLVED_PLAN_JSON into resolved from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(resolved).get_object('domain');
 if v.has('group_receipt')then execute_group(p_request,p_actor,v,p_result);return;end if;
 describe_source(p_request,p_actor,fresh);if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'INTERWARE_RECEIVING_SOURCE_CHANGED');end if;
 v_plan:=v.get_string('plan_operation_id');v_uid:=v.get_string('uid');v_ware:=v.get_number('warehouse_id');v_article:=v.get_string('article');v_source:=v.get_string('source_load_operation_id');v_vehicle:=v.get_string('vehicle_number');v_dock:=v.get_string('inbound_dock');
 j.put('operation_id',op);j.put('plan_operation_id',v_plan);j.put('pallet_identifier',v_uid);j.put('warehouse_id',v_ware);j.put('source_load_operation_id',v_source);j.put('source_st_id',v.get_number('source_st_id'));j.put('customer_fulfillment_repeated',false);
 if v_kind='INTERWARE_UNLOAD' then
  insert into RRL_INTERWARE_UNLOAD(OPERATION_ID,PLAN_OPERATION_ID,ROOT_UID,WARE_ID,VEHICLE_NUMBER,INBOUND_DOCK,ACTOR)values(op,v_plan,v_uid,v_ware,v_vehicle,v_dock,p_actor);
  j.put('status','UNLOADED_PENDING_RECEIPT');j.put('stock_changed',false);
 else
  v_cell:=v.get_string('receive_cell');v_unload:=v.get_string('unload_operation_id');v_uom:=v.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));v_ver:=v.get_number('uom_version');
  RRL_STOCK_LOCATION_CORE.assert_receiving(v_cell,v_ware);
  if v.has('partial_receipt')then RRL_STOCK_INTERWARE_PART.create_pallet(v,op);end if;
  RRL_STOCK_BALANCE_CORE.apply_delta(v_uid,v_cell,v_qty,0,v_uom,v_ver,0);
  RRL_STOCK_BALANCE_CORE.write_leg(v_uid,null,v_cell,v_qty,v_uom,v_ver,1,1,1,p_actor,v_event);
  if v.has('source_units')then
   if v.has('partial_receipt')then
    RRL_STOCK_UNIT_CORE.receive_partial_issued(v.get_string('original_root_uid'),v.get_string('source_cell'),v_uid,v_cell,v_qty,v.get_array('source_units').to_clob);
   else
   RRL_STOCK_UNIT_CORE.receive_issued(v_uid,v.get_string('source_cell'),v_cell,v_qty,v.get_array('source_units').to_clob);
   end if;
   j.put('physical_unit_count',v.get_array('source_units').get_size);j.put('original_unit_signature',v.get_string('original_unit_signature'));j.put('regulatory_ack_verified',false);
  end if;
  if v.has('nested_source')then
   RRL_IW_HU_REC_CORE.restore(v,op,p_actor);
   j.put('physical_place_identifier',v.get_object('nested_source').get_string('place_uid'));
   j.put('physical_tree_restored',true);j.put('physical_place_count',1);
  end if;
  v_original_root:=v.get_string('original_root_uid');v_expected_qty:=v.get_number('expected_quantity');
  v_short_reason:=v.get_string('discrepancy_reason');v_short_ref:=v.get_string('discrepancy_reference');
  insert into RRL_INTERWARE_RECEIPT(OPERATION_ID,PLAN_OPERATION_ID,UNLOAD_OPERATION_ID,ROOT_UID,WARE_ID,RECEIVE_CELL,ARTICLE,BASE_QTY,BASE_UOM,SOURCE_LOAD_OPERATION_ID,STOCK_EVENT_ID,ACTOR,ORIGINAL_ROOT_UID,EXPECTED_BASE_QTY,DISCREPANCY_REASON,DISCREPANCY_REFERENCE)
  values(op,v_plan,v_unload,v_uid,v_ware,v_cell,v_article,v_qty,v_uom,v_source,v_event,p_actor,v_original_root,v_expected_qty,v_short_reason,v_short_ref);
  j.put('status','RECEIVED_PENDING_PLACEMENT');j.put('stock_changed',true);j.put('quantity',v.get_string('quantity'));j.put('base_uom',v_uom);j.put('cell',v_cell);j.put('event_id',v_event);j.put('external_sap_ack',false);
  if v.has('partial_receipt')then
   j.put('status','RECEIVED_PARTIAL_PENDING_PLACEMENT');j.put('original_pallet_identifier',v.get_string('original_root_uid'));
   j.put('expected_quantity',v.get_string('expected_quantity'));j.put('short_quantity',v.get_string('short_quantity'));
   j.put('carrier_shortage_resolved',false);j.put('discrepancy_reason',v.get_string('discrepancy_reason'));j.put('discrepancy_reference',v.get_string('discrepancy_reference'));
  end if;
  v_payload:=j.to_clob;
  insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values('INTERWARE:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op,'AL32UTF8'),sys.dbms_crypto.hash_sh256)),'INTERWAREHOUSE_RECEIVED',v_payload);
 end if;
 p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_INTERWARE_SHORT_CMD as 
 procedure assert_scope(p_request clob,p_actor varchar2)is 
 d json_object_t:=json_object_t.parse(p_request);rec_id varchar2(100);v_kind varchar2(80):=d.get_string('command_type');n number;reporter varchar2(100);v_request varchar2(100); 
 begin 
 if v_kind='INTERWARE_SHORTAGE_REPORT'then rec_id:=d.get_object('source').get_string('receipt_operation_id'); 
 elsif v_kind='INTERWARE_SHORTAGE_CONFIRM'then 
  v_request:=d.get_object('source').get_string('request_operation_id');select RECEIPT_OPERATION_ID,ACTOR into rec_id,reporter from RRL_INTERWARE_SHORTAGE_REQUEST where OPERATION_ID=v_request; 
 else raise_application_error(-20886,'INTERWARE_SHORTAGE_COMMAND_REQUIRED');end if; 
 select count(*)into n from RRL_INTERWARE_RECEIPT r join RUSERS u on u.ID=p_actor where r.OPERATION_ID=rec_id and nvl(u.DELETED,0)=0 
 and(u.WARE_ID=r.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN') 
 and RRL_HAS_WRIGHT(u.ID,case when v_kind='INTERWARE_SHORTAGE_REPORT'then 'transport_dispatch_edit'else 'store_return_approve'end)=1; 
 if n!=1 or(v_kind='INTERWARE_SHORTAGE_CONFIRM'and reporter=p_actor)then raise_application_error(-20882,'INTERWARE_SHORTAGE_CURRENT_INDEPENDENT_TARGET_ACTOR_REQUIRED');end if; 
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_SHORTAGE_REQUEST_NOT_FOUND'); 
 end; 
 procedure describe(p_request clob,p_actor varchar2,p_domain out json_object_t)is 
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v_kind varchar2(80):=d.get_string('command_type');receipt RRL_INTERWARE_RECEIPT%rowtype;req RRL_INTERWARE_SHORTAGE_REQUEST%rowtype; 
 rec_id varchar2(100);request_id varchar2(100);resolved clob;dom json_object_t;original_units clob;accepted_units clob;missing_units clob; 
 n number;expected_count number;qty number;v_source_cell varchar2(60);reason varchar2(2000):=m.get_string('reason');ref varchar2(2000):=m.get_string('evidence_reference');quantity number; 
 begin 
 assert_scope(p_request,p_actor); 
 if m.get_size!=3 or trim(reason)is null or length(trim(reason))<8 or length(reason)>500 or trim(ref)is null or length(ref)>255 then raise_application_error(-20886,'INTERWARE_SHORTAGE_REASON_DOCUMENT_REQUIRED');end if; 
 quantity:=RRL_STOCK_MATH.quantity(m.get_string('quantity')); 
 if v_kind='INTERWARE_SHORTAGE_REPORT'then rec_id:=d.get_object('source').get_string('receipt_operation_id'); 
 else request_id:=d.get_object('source').get_string('request_operation_id');select *into req from RRL_INTERWARE_SHORTAGE_REQUEST where OPERATION_ID=request_id;rec_id:=req.RECEIPT_OPERATION_ID;end if; 
 select *into receipt from RRL_INTERWARE_RECEIPT where OPERATION_ID=rec_id; 
 if receipt.ORIGINAL_ROOT_UID is null or receipt.EXPECTED_BASE_QTY<=receipt.BASE_QTY or quantity!=receipt.EXPECTED_BASE_QTY-receipt.BASE_QTY then raise_application_error(-20886,'INTERWARE_SHORTAGE_EXACT_PARTIAL_DIFFERENCE_REQUIRED');end if; 
 select count(*)into n from RRL_INTERWARE_SHORTAGE_FACT where RECEIPT_OPERATION_ID=rec_id;if n!=0 then raise_application_error(-20886,'INTERWARE_SHORTAGE_ALREADY_CONFIRMED');end if; 
 if v_kind='INTERWARE_SHORTAGE_REPORT'then 
  select count(*)into n from RRL_INTERWARE_SHORTAGE_REQUEST where RECEIPT_OPERATION_ID=rec_id;if n!=0 then raise_application_error(-20886,'INTERWARE_SHORTAGE_ALREADY_REPORTED');end if; 
 end if; 
 select RESOLVED_PLAN_JSON into resolved from RRL_STOCK_OPERATION where OPERATION_ID=rec_id and STATE='APPLIED'and COMMAND_TYPE='INTERWARE_RECEIVE'; 
 dom:=json_object_t.parse(resolved).get_object('domain');v_source_cell:=dom.get_string('source_cell');expected_count:=0; 
 if dom.has('original_source_units')then 
  original_units:=dom.get_array('original_source_units').to_clob;accepted_units:=dom.get_array('source_units').to_clob; 
  if dom.get_array('original_source_units').get_size>10000 or dom.get_array('source_units').get_size>10000 then raise_application_error(-20886,'INTERWARE_SHORTAGE_UNIT_BOUND');end if; 
  select count(*)into expected_count from json_table(original_units,'$[*]'columns(K varchar2(64)path '$.key'))j 
   where not exists(select 1 from json_table(accepted_units,'$[*]'columns(K varchar2(64)path '$.key'))a where a.K=j.K); 
  select count(*),sum(u.BASE_QTY), 
   json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob) 
   into n,qty,missing_units from json_table(original_units,'$[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))j 
   join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=j.K 
   where not exists(select 1 from json_table(accepted_units,'$[*]'columns(K varchar2(64)path '$.key'))a where a.K=j.K) 
   and u.CURRENT_UID=receipt.ORIGINAL_ROOT_UID and u.CURRENT_CELL=v_source_cell and u.STOCK_STATUS='ISSUED'and u.HARD_RESERVATION_ID is null 
   and u.BASE_QTY=RRL_STOCK_MATH.quantity(j.Q)and u.BASE_UOM=j.B and u.BASE_UOM=receipt.BASE_UOM 
   and not exists(select 1 from RRL_INTERWARE_SHORTAGE_UNIT booked where booked.PHYSICAL_UNIT_KEY=u.PHYSICAL_UNIT_KEY
    and not exists(select 1 from RRL_INTERWARE_RECOVERY_UNIT recovered join RRL_STOCK_OPERATION restored on restored.OPERATION_ID=recovered.RECOVERY_OPERATION_ID
     where recovered.PHYSICAL_UNIT_KEY=booked.PHYSICAL_UNIT_KEY and recovered.LOSS_OPERATION_ID=booked.FACT_OPERATION_ID
     and restored.STATE='APPLIED'and restored.COMMAND_TYPE='INTERWARE_SHORTAGE_RECOVER')); 
  if expected_count<1 or n!=expected_count or qty!=quantity then raise_application_error(-20886,'INTERWARE_SHORTAGE_CURRENT_EXACT_ISSUED_UNITS_REQUIRED');end if; 
 else missing_units:='[]';end if; 
 p_domain:=json_object_t();p_domain.put('receipt_operation_id',rec_id);p_domain.put('plan_operation_id',receipt.PLAN_OPERATION_ID); 
 p_domain.put('source_load_operation_id',receipt.SOURCE_LOAD_OPERATION_ID);p_domain.put('original_uid',receipt.ORIGINAL_ROOT_UID);p_domain.put('accepted_uid',receipt.ROOT_UID); 
 p_domain.put('warehouse_id',receipt.WARE_ID);p_domain.put('expected_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(receipt.EXPECTED_BASE_QTY)); 
 p_domain.put('accepted_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(receipt.BASE_QTY));p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(quantity)); 
 p_domain.put('base_uom',receipt.BASE_UOM);p_domain.put('missing_units',json_array_t.parse(missing_units));p_domain.put('source_cell',v_source_cell); 
 if request_id is not null then 
  if dbms_lob.compare(json_object_t.parse(req.SOURCE_JSON).get_array('missing_units').to_clob,missing_units)!=0 then raise_application_error(-20886,'INTERWARE_SHORTAGE_REPORTED_UNIT_VERSIONS_CHANGED');end if; 
  p_domain.put('request_operation_id',request_id);p_domain.put('reporter',req.ACTOR); 
 end if; 
 p_domain.put('reason',reason);p_domain.put('evidence_reference',ref); 
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_SHORTAGE_ACTUAL_PARTIAL_RECEIPT_REQUIRED'); 
 end; 
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is 
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();units json_array_t;u json_object_t; 
 begin 
 describe(p_request,d.get_string('actor'),v); 
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECEIPT',v.get_string('receipt_operation_id')); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_SHORTAGE_REQUEST',nvl(v.get_string('request_operation_id'),p_operation)); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_SHORTAGE_FACT',v.get_string('receipt_operation_id')); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',v.get_string('source_load_operation_id')); 
 RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v.get_string('original_uid')); 
 units:=v.get_array('missing_units');for i in 0..units.get_size-1 loop u:=treat(units.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',u.get_string('key'));end loop; 
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','IW.SHORT.RECEIPT:'||v.get_string('receipt_operation_id')); 
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256))); 
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob; 
 end; 
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is 
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');kind varchar2(80):=d.get_string('command_type');wire clob;v json_object_t;fresh json_object_t;j json_object_t; 
 rec_id varchar2(100);plan_id varchar2(100);load_id varchar2(100);req_id varchar2(100);old_uid varchar2(200);new_uid varchar2(200);ware number;expected number;accepted number;quantity number;uom varchar2(20);reason varchar2(2000);ref varchar2(2000);units clob;domain_wire clob; 
 begin 
 select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(wire).get_object('domain'); 
 describe(p_request,p_actor,fresh);if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: interwarehouse shortage');end if; 
 rec_id:=v.get_string('receipt_operation_id');plan_id:=v.get_string('plan_operation_id');load_id:=v.get_string('source_load_operation_id');req_id:=v.get_string('request_operation_id'); 
 old_uid:=v.get_string('original_uid');new_uid:=v.get_string('accepted_uid');ware:=v.get_number('warehouse_id');expected:=RRL_STOCK_MATH.quantity(v.get_string('expected_quantity')); 
 accepted:=RRL_STOCK_MATH.quantity(v.get_string('accepted_quantity'));quantity:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));uom:=v.get_string('base_uom');reason:=v.get_string('reason');ref:=v.get_string('evidence_reference');units:=v.get_array('missing_units').to_clob;domain_wire:=v.to_clob; 
 if kind='INTERWARE_SHORTAGE_REPORT'then 
  insert into RRL_INTERWARE_SHORTAGE_REQUEST(OPERATION_ID,RECEIPT_OPERATION_ID,PLAN_OPERATION_ID,SOURCE_LOAD_OPERATION_ID,ORIGINAL_UID,ACCEPTED_UID,WARE_ID,EXPECTED_QTY,ACCEPTED_QTY,SHORT_QTY,BASE_UOM,ACTOR,REASON_TEXT,EVIDENCE_REFERENCE,SOURCE_JSON) 
   values(op,rec_id,plan_id,load_id,old_uid,new_uid,ware,expected,accepted,quantity,uom,p_actor,reason,ref,domain_wire); 
 else 
  insert into RRL_INTERWARE_SHORTAGE_FACT(OPERATION_ID,REQUEST_OPERATION_ID,RECEIPT_OPERATION_ID,ACTOR,REASON_TEXT,EVIDENCE_REFERENCE,SHORT_QTY,SOURCE_JSON) 
   values(op,req_id,rec_id,p_actor,reason,ref,quantity,domain_wire); 
  insert into RRL_INTERWARE_SHORTAGE_UNIT(PHYSICAL_UNIT_KEY,FACT_OPERATION_ID,ORIGINAL_UID,UNIT_VERSION,BASE_QTY,BASE_UOM) 
   select K,op,old_uid,V,RRL_STOCK_MATH.quantity(Q),B from json_table(units,'$[*]'columns(K varchar2(64)path '$.key',V number path '$.version',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom')); 
 end if; 
 j:=json_object_t.parse(v.to_clob);j.put('operation_id',op);j.put('actor',p_actor);j.put('status',case when kind='INTERWARE_SHORTAGE_REPORT'then 'PENDING_INDEPENDENT_CONFIRMATION'else 'CONFIRMED_CARRIER_SHORTAGE'end); 
 j.put('stock_changed',false);j.put('carrier_custody_released',false);j.put('regulatory_ack_verified',false);p_result:=j.to_clob; 
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values('IW.SHORT:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op,'AL32UTF8'),sys.dbms_crypto.hash_sh256)),kind,p_result); 
 end; 
end;
/


CREATE OR REPLACE package body RRL_STOCK_INVARIANT_CORE as
 function stock_uid(p_key raw) return varchar2 is
  v_pos pls_integer:=1;v_len pls_integer;v_end pls_integer;v_hex varchar2(2000):=rawtohex(p_key);
  v_version varchar2(10);v_kind varchar2(20);v_uid varchar2(200);
  function next_part return varchar2 is v_out varchar2(2000);
  begin
   v_end:=instr(v_hex,'3A',v_pos);
   -- RAW bytes are traversed, so UTF-8 component lengths remain byte lengths.
   while v_end>0 and mod(v_end,2)=0 loop v_end:=instr(v_hex,'3A',v_end+1);end loop;
   if v_end=0 then raise_application_error(-20841,'RESOURCE_ENCODING_INVALID');end if;
   v_len:=to_number(utl_i18n.raw_to_char(hextoraw(substr(v_hex,v_pos,v_end-v_pos)),'AL32UTF8'));
   v_pos:=v_end+2;
   v_out:=utl_i18n.raw_to_char(hextoraw(substr(v_hex,v_pos,2*v_len)),'AL32UTF8');v_pos:=v_pos+2*v_len;
   return v_out;
  end;
 begin
  v_version:=next_part;v_kind:=next_part;v_uid:=next_part;
  if v_version!='2' or v_kind!='STOCK' or v_uid is null or v_pos!=length(v_hex)+1
   or RRL_STOCK_LOCK_API.resource_key('STOCK',v_uid)!=p_key then raise_application_error(-20841,'STOCK_RESOURCE_ENCODING_INVALID');end if;
  return v_uid;
 end;
 function snapshot_stock(p_resources clob) return clob is
  v json_array_t:=json_array_t();u json_object_t;x json_array_t;k json_object_t;v_uid varchar2(200);v_count number:=0;
 begin
  for r in(select distinct KEY_HEX from json_table(p_resources,'$[*]'
   columns(RANK_NO number path '$.rank',KEY_HEX varchar2(2000) path '$.key_hex')) where RANK_NO=50 order by KEY_HEX) loop
   v_uid:=stock_uid(hextoraw(r.KEY_HEX));
   RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',v_uid));
   u:=json_object_t();x:=json_array_t();u.put('uid',v_uid);
   for b in(select CELL,REMAIN,HARD_RESERVED_BASE,STOCK_VERSION,BASE_UOM from RRL_REMAINS where UID_POLETA=v_uid order by CELL) loop
    v_count:=v_count+1;if v_count>20000 then raise_application_error(-20871,'STOCK_CLOSURE_TOO_LARGE');end if;
    k:=json_object_t();k.put('cell',b.CELL);k.put('p',RRL_STOCK_PLAN_HELPER.decimal_text(b.REMAIN));
    k.put('h',RRL_STOCK_PLAN_HELPER.decimal_text(b.HARD_RESERVED_BASE));k.put('version',b.STOCK_VERSION);k.put('base_uom',b.BASE_UOM);x.append(k);
   end loop;
   u.put('balances',x);v.append(u);
  end loop;
  return v.to_clob;
 end;
 procedure verify_posting(p_resources clob,p_before clob,p_operation varchar2) is
  v_uid varchar2(200);v_p number;v_h number;v_old number;v_delta number;v_sum number;v_bad number;v_base varchar2(20);v_unit_count number;
 begin
  if p_operation is null or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=p_operation then
   raise_application_error(-20863,'INVARIANT_CONTEXT_REQUIRED');end if;
  for r in(select distinct KEY_HEX from json_table(p_resources,'$[*]'
   columns(RANK_NO number path '$.rank',KEY_HEX varchar2(2000) path '$.key_hex')) where RANK_NO=50) loop
   v_uid:=stock_uid(hextoraw(r.KEY_HEX));
   RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',v_uid));
   for c in(
    select CELL from RRL_REMAINS where UID_POLETA=v_uid
    union select j.CELL from json_table(p_before,'$[*]' columns(STOCK_UID_JSON varchar2(200) path '$.uid',
      nested path '$.balances[*]' columns(CELL varchar2(60) path '$.cell')))j where j.STOCK_UID_JSON=v_uid and j.CELL is not null
    union select nvl(CELL_FROM,CELL_TO) from RRL_EVENTS where OPERATION_ID=p_operation and UID_POLETA=v_uid
   ) loop
    v_p:=0;v_h:=0;v_base:=null;
    begin select REMAIN,HARD_RESERVED_BASE,BASE_UOM into v_p,v_h,v_base from RRL_REMAINS where UID_POLETA=v_uid and CELL=c.CELL;
    exception when no_data_found then null;end;
    select nvl(sum(to_number(j.QTY,'999999999999999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''')),0) into v_old
     from json_table(p_before,'$[*]' columns(STOCK_UID_JSON varchar2(200) path '$.uid',
      nested path '$.balances[*]' columns(CELL varchar2(60) path '$.cell',QTY varchar2(100) path '$.p')))j
      where j.STOCK_UID_JSON=v_uid and j.CELL=c.CELL;
    select nvl(sum(case when CELL_FROM is not null and CELL_TO is not null then
      case when CELL_FROM=c.CELL then -BASE_QTY else BASE_QTY end else BASE_QTY end),0) into v_delta
     from RRL_EVENTS where OPERATION_ID=p_operation and UID_POLETA=v_uid and (CELL_FROM=c.CELL or CELL_TO=c.CELL);
    if v_p-v_old!=v_delta or v_p<0 or v_h<0 or v_h>v_p then raise_application_error(-20868,'JOURNAL_BALANCE_INVARIANT_FAILED');end if;
    select nvl(sum(BASE_QTY),0),nvl(sum(case when BASE_QTY is null or BASE_QTY<=0 or BASE_UOM is null or BASE_UOM!=v_base then 1 else 0 end),0)
      into v_sum,v_bad from RRL_STOCK_RESERVATION where UID_PALLET=v_uid and CELL=c.CELL
      and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING');
    if v_sum!=v_h or v_bad>0 then raise_application_error(-20869,'RESERVATION_BALANCE_INVARIANT_FAILED');end if;
    RRL_STOCK_UNIT_CORE.assert_composition(v_uid,c.CELL);
    select count(*) into v_unit_count from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=v_uid and CURRENT_CELL=c.CELL and STOCK_STATUS!='ISSUED';
    for z in(select RESERVATION_ID,BASE_QTY from RRL_STOCK_RESERVATION where UID_PALLET=v_uid and CELL=c.CELL
     and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING')) loop
     select count(*),nvl(sum(BASE_QTY),0) into v_bad,v_sum from RRL_WMS_RECEIPT_UNIT
      where CURRENT_UID=v_uid and CURRENT_CELL=c.CELL and HARD_RESERVATION_ID=z.RESERVATION_ID and STOCK_STATUS!='ISSUED';
     if v_unit_count>0 and v_sum!=z.BASE_QTY then raise_application_error(-20869,'RESERVATION_UNIT_INVARIANT_FAILED');end if;
    end loop;
   end loop;
  end loop;
  -- Every journal leg belongs to a planned stock key.
  for e in(select distinct UID_POLETA from RRL_EVENTS where OPERATION_ID=p_operation) loop
   RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',e.UID_POLETA));
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_INVENTORY_BIRTH as

 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is

  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t:=json_object_t();

  f json_array_t:=json_array_t();r json_array_t:=json_array_t();doc number;ware number;uid varchar2(200);cell varchar2(60);article varchar2(160);

  base varchar2(20);other_base varchar2(20);qty number;version number;scale number;expiry date;price number;legacy json_object_t;legacy_doc number;legacy_owner number;v_mod_id number;gross number;net number;boxes number;defect number;

 begin

  doc:=d.get_object('source').get_number('revision_id');uid:=m.get_string('uid');cell:=m.get_string('cell');article:=m.get_string('article');

  if doc is null or uid is null or lengthb(uid)>150 or cell is null or article is null or trim(m.get_string('reason')) is null then raise_application_error(-20871,'INVENTORY_BIRTH_IDENTITY_REQUIRED');end if;

  select WARE_ID into ware from RRL_REVIZION where ID=doc;

  select min(BASE_UOM),max(BASE_UOM) into base,other_base from RRL_STOCK_UOM_CONVERSION where ARTICUL=article and INPUT_UOM=BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;

  if base is null or base!=other_base then raise_application_error(-20868,'INVENTORY_BASE_POLICY_AMBIGUOUS');end if;

  select max(POLICY_VERSION) into version from RRL_STOCK_UOM_CONVERSION where ARTICUL=article and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;

  select BASE_SCALE into scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=article and INPUT_UOM=base and POLICY_VERSION=version;

  qty:=RRL_STOCK_MATH.quantity(m.get_string('quantity'));RRL_STOCK_MATH.assert_base(qty,scale);

  expiry:=to_date(m.get_string('expiry_date'),'FXYYYY-MM-DD');price:=m.get_number('price');

  if expiry is null or price<0 then raise_application_error(-20871,'INVENTORY_LOT_DATA_REQUIRED');end if;

  if m.has('legacy_facts') then

   legacy:=m.get_object('legacy_facts');legacy.on_error(1);legacy_doc:=legacy.get_number('receipt_document_id');

   select REV_NAKLAD_ID into legacy_owner from RRL_REVIZION where ID=doc;

   if legacy_doc is null or legacy_owner is null or legacy_doc!=legacy_owner then raise_application_error(-20887,'INVENTORY_SOURCE_DOCUMENT_CONFLICT');end if;

   v_mod_id:=nvl(legacy.get_number('mod_id'),0);gross:=legacy.get_number('gross_weight');net:=legacy.get_number('net_weight');

   boxes:=legacy.get_number('box_count');defect:=legacy.get_number('defect_percent');

   if gross is null or gross<0 or net is null or net<0 or (gross>0 and net>gross) or boxes is null or boxes<0

    or defect is null or defect<0 or defect>100 or v_mod_id<0 then raise_application_error(-20871,'INVENTORY_PALLET_FACTS_INVALID');end if;

   if v_mod_id>0 then select ID into v_mod_id from RRL_ARTICUL_MODS where ID=v_mod_id and ARTICUL=article;end if;

  end if;

  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');

  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_REVIZION',RRL_STOCK_PLAN_HELPER.decimal_text(doc));

  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,uid,article,cell,null);

  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','PALLET:'||uid);

  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));

  if legacy_doc is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRIHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(legacy_doc));end if;

  v.put('document',doc);v.put('warehouse',ware);v.put('uid',uid);v.put('cell',cell);v.put('article',article);

  v.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));v.put('base',base);v.put('version',version);v.put('expiry_date',to_char(expiry,'YYYY-MM-DD'));v.put('price',price);

  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;

 end;

 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is

  d json_object_t:=json_object_t.parse(p_request);v json_object_t;j json_object_t:=json_object_t();plan clob;

  doc number;ware number;cond number;uid varchar2(200);cell varchar2(60);article varchar2(160);base varchar2(20);version number;

  qty number;expiry date;price number;n number;eventid number;marked number;current_version number;v_count_cell varchar2(60);legacy json_object_t;legacy_doc number;legacy_owner number;v_mod_id number;gross number;net number;boxes number;defect number;

 begin

  if RRL_HAS_WRIGHT(p_actor,'stock_inventory_count')!=1 then raise_application_error(-20882,'INVENTORY_BIRTH_FORBIDDEN');end if;

  uid:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=uid;

  v:=json_object_t.parse(plan).get_object('domain');doc:=v.get_number('document');uid:=v.get_string('uid');cell:=v.get_string('cell');

  article:=v.get_string('article');base:=v.get_string('base');version:=v.get_number('version');qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));

  expiry:=to_date(v.get_string('expiry_date'),'FXYYYY-MM-DD');price:=v.get_number('price');

  select WARE_ID,CONDITION into ware,cond from RRL_REVIZION where ID=doc for update;

  declare actor_count number;begin
  select count(*)into actor_count from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0
   and(u.WARE_ID=ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if actor_count!=1 then raise_application_error(-20882,'INVENTORY_CURRENT_WAREHOUSE_ACTOR_REQUIRED');end if;
  end;
  if ware!=v.get_number('warehouse') or cond is null or cond not in(0,1) then raise_application_error(-20886,'INVENTORY_DOCUMENT_NOT_OPEN');end if;

  if d.get_object('metadata').has('legacy_facts') then

   legacy:=d.get_object('metadata').get_object('legacy_facts');legacy_doc:=legacy.get_number('receipt_document_id');

   select REV_NAKLAD_ID into legacy_owner from RRL_REVIZION where ID=doc;

   if legacy_owner is null or legacy_owner!=legacy_doc then raise_application_error(-20890,'CLOSURE_CHANGED: inventory source document');end if;

   v_mod_id:=nvl(legacy.get_number('mod_id'),0);gross:=legacy.get_number('gross_weight');net:=legacy.get_number('net_weight');

   boxes:=legacy.get_number('box_count');defect:=legacy.get_number('defect_percent');

   if v_mod_id>0 then select ID into v_mod_id from RRL_ARTICUL_MODS where ID=v_mod_id and ARTICUL=article;end if;

  end if;

  RRL_STOCK_LOCATION_CORE.assert_quarantine(cell,ware);

  select max(POLICY_VERSION) into current_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=article and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;

  if current_version!=version then raise_application_error(-20890,'CLOSURE_CHANGED: inventory birth policy');end if;

  select greatest(nvl((select MARKING_REQUIRED from RRL_SKU_RECEIPT_POLICY where ARTICUL=article),0),

    nvl((select CRPT_REQUIRED from RRL_FINISHED_GOODS_SKU where ARTICUL=article),0),

    case when exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=article) then 1 else 0 end) into marked from dual;



  select count(*) into n from RRL_PALLETS where UID_PALLET=uid;

  if n>0 then

   declare v_owner varchar2(100);v_op varchar2(100):=d.get_string('operation_id');begin

    select CREATED_BY_STOCK_OP into v_owner from RRL_PALLETS where UID_PALLET=uid;

    if v_owner is null or v_owner!=v_op then raise_application_error(-20887,'INVENTORY_PALLET_ALREADY_EXISTS: use measured count');end if;

   end;

  end if;

  -- The planned CELL fence serializes birth against existing-lot movements.

  -- A changed input file must not add measured inventory on top of live stock.

  v_count_cell:=cell;

  select count(*) into n from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA

   where s.CELL=v_count_cell and p.ARTICUL=article and s.REMAIN>0;

  if n>0 and legacy is not null then

   -- Different explicitly identified pallets may be measured within one revision.

   -- A new revision/file must not load inventory over unrelated existing stock.

   select count(*) into n from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA

    where s.CELL=v_count_cell and p.ARTICUL=article and s.REMAIN>0 and not exists(

     select 1 from RRL_STOCK_OPERATION o where o.OPERATION_ID=p.CREATED_BY_STOCK_OP and o.STATE='APPLIED'

      and o.COMMAND_TYPE='INVENTORY_REGISTER_LOT' and json_value(o.CANONICAL_REQUEST,'$.source.revision_id' returning number)=doc);

   if n>0 then raise_application_error(-20887,'INVENTORY_CELL_HAS_OTHER_STOCK: count existing lots');end if;

  end if;

  declare

 v_json_sql_1_1 varchar2(32767):=d.get_string('operation_id');

begin

select count(*) into n from RRL_PALLETS where UID_PALLET=uid;

if n=0 then insert into RRL_PALLETS(UID_PALLET,ARTICUL,CREATION_DATE,EXPIRY_DATE,UNIT_COUNT,PRICE,PRIHOD_NAKLAD_ID,STOCK_ORIGIN_UID,CREATED_BY_STOCK_OP)

   values(uid,article,systimestamp,expiry,qty,price,-doc,uid,v_json_sql_1_1);end if;

end;

  if legacy is not null then

   update RRL_PALLETS set MOD_ID=v_mod_id,WEIGHT_BRUTTO=gross,WEIGHT_TN=net,COUNT_KOR=boxes,DEFECT_PERC=defect where UID_PALLET=uid;

  end if;

  RRL_STOCK_BALANCE_CORE.apply_delta(uid,cell,qty,0,base,version,0);

  RRL_STOCK_UNIT_CORE.admit_captured(uid,cell);

  RRL_STOCK_BALANCE_CORE.write_leg(uid,null,cell,qty,base,version,1,1,1,p_actor,eventid);

  j.put('operation_id',d.get_string('operation_id'));j.put('revision_id',doc);j.put('uid',uid);j.put('cell',cell);j.put('article',article);

  j.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));j.put('unit',base);j.put('event_id',eventid);j.put('lot_source','INVENTORY');

  p_result:=j.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_INVENTORY_CMD as

 procedure compile_count(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is

  d json_object_t:=json_object_t.parse(p_request);a json_array_t;b json_array_t:=json_array_t();x json_object_t;y json_object_t;v json_object_t:=json_object_t();

  f json_array_t:=json_array_t();r json_array_t:=json_array_t();doc number;ware number;article varchar2(160);base varchar2(20);inputu varchar2(20);

  qty number;ver number;stockver number;signature varchar2(64);p number;h number;k varchar2(2000);

  revision_row number;row_doc number;row_cell varchar2(60);row_article varchar2(160);

  type keys is table of boolean index by varchar2(2000);seen keys;

 begin

  doc:=d.get_object('source').get_number('revision_id');select WARE_ID into ware from RRL_REVIZION where ID=doc;

  a:=d.get_object('metadata').get_array('counts');

  if a is null or a.get_size>200 or (a.get_size<1 and not d.get_object('metadata').has('inventory_task_id')) then raise_application_error(-20881,'INVENTORY_COUNT_BATCH_BOUND');end if;

  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);

  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_REVIZION',RRL_STOCK_PLAN_HELPER.decimal_text(doc));

  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));

  if d.get_object('metadata').has('revision_row_id') then

   revision_row:=d.get_object('metadata').get_number('revision_row_id');

   if a.get_size!=1 or revision_row is null then raise_application_error(-20871,'INVENTORY_REVISION_ROW_SINGLE_LOT_REQUIRED');end if;

   x:=treat(a.get(0) as json_object_t);

   select REVISION_ID,CELL,ARTICUL1 into row_doc,row_cell,row_article from RRL_REVISION_ROW where ID=revision_row;

   if row_doc is null or row_doc!=doc or row_cell is null or row_cell!=x.get_string('cell')

    or row_article is null or row_article!=x.get_string('article') then raise_application_error(-20887,'INVENTORY_REVISION_ROW_IDENTITY_CONFLICT');end if;

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_REVISION_ROW',RRL_STOCK_PLAN_HELPER.decimal_text(revision_row));

  end if;

  for i in 0..a.get_size-1 loop

   x:=treat(a.get(i) as json_object_t);declare

 v_json_sql_1_1 varchar2(32767):=x.get_string('uid');

begin

select ARTICUL into article from RRL_PALLETS where UID_PALLET=v_json_sql_1_1;

end;

   if article is null or article!=x.get_string('article') then raise_application_error(-20887,'INVENTORY_LOT_ARTICLE_CONFLICT');end if;

   k:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',x.get_string('uid'),x.get_string('cell')));if seen.exists(k) then raise_application_error(-20885,'INVENTORY_LOT_REPEATED');end if;seen(k):=true;

   inputu:=x.get_string('unit');

   RRL_STOCK_PALLET_UOM.resolve_quantity(x.get_string('uid'),inputu,

    case when regexp_like(x.get_string('quantity'),'^0([.]0{1,9})?$') then '1' else x.get_string('quantity') end,base,qty,ver,signature);

   if regexp_like(x.get_string('quantity'),'^0([.]0{1,9})?$') then qty:=0;end if;

   begin declare

 v_json_sql_2_1 varchar2(32767):=x.get_string('uid');

 v_json_sql_2_2 varchar2(32767):=x.get_string('cell');

begin

select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION into p,h,stockver from RRL_REMAINS where UID_POLETA=v_json_sql_2_1 and CELL=v_json_sql_2_2;

end;

   exception when no_data_found then p:=0;h:=0;stockver:=0;end;

   if x.get_number('expected_stock_version') is null or x.get_number('expected_stock_version')!=stockver then raise_application_error(-20867,'INVENTORY_SNAPSHOT_STALE');end if;

   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),article,x.get_string('cell'),null);

   y:=json_object_t();y.put('uid',x.get_string('uid'));y.put('cell',x.get_string('cell'));y.put('article',article);

   y.put('base',base);y.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));y.put('p',RRL_STOCK_PLAN_HELPER.decimal_text(p));

   y.put('h',RRL_STOCK_PLAN_HELPER.decimal_text(h));y.put('version',stockver);y.put('uom_version',ver);y.put('signature',signature);b.append(y);

  end loop;

  v.put('document',doc);v.put('warehouse',ware);v.put('counts',b);RRL_STOCK_SHORT_RECOVERY.plan_inventory(p_request,r,f,v);p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;

 end;

 procedure execute_count(p_request clob,p_actor varchar2,p_result out clob) is

  d json_object_t:=json_object_t.parse(p_request);v json_object_t;x json_object_t;sourcex json_object_t;fact json_object_t;result json_object_t:=json_object_t();

  a json_array_t;original json_array_t;facts json_array_t:=json_array_t();plan clob;doc number;ware number;cond number;

  p number;h number;stockver number;qty number;delta number;ver number;basever number;eventid number;marking number;signature varchar2(64);base varchar2(20);units clob;revision_row number;row_doc number;row_cell varchar2(60);row_article varchar2(160);other_lots number;v_uid varchar2(200);

 begin

  if RRL_HAS_WRIGHT(p_actor,'stock_inventory_count')!=1 then raise_application_error(-20882,'INVENTORY_COUNT_FORBIDDEN');end if;

  if trim(d.get_object('metadata').get_string('reason')) is null then raise_application_error(-20883,'INVENTORY_REASON_REQUIRED');end if;

  declare

 v_json_sql_3_1 varchar2(32767):=d.get_string('operation_id');

begin

select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_3_1;

end;v:=json_object_t.parse(plan).get_object('domain');

  doc:=v.get_number('document');select WARE_ID,CONDITION into ware,cond from RRL_REVIZION where ID=doc for update;

  declare actor_count number;begin
  select count(*)into actor_count from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0
   and(u.WARE_ID=ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if actor_count!=1 then raise_application_error(-20882,'INVENTORY_CURRENT_WAREHOUSE_ACTOR_REQUIRED');end if;
  end;
  if ware!=v.get_number('warehouse') or cond is null or cond in(2,3) then raise_application_error(-20886,'INVENTORY_DOCUMENT_NOT_OPEN');end if;

  a:=v.get_array('counts');original:=d.get_object('metadata').get_array('counts');

  if d.get_object('metadata').has('revision_row_id') then

   revision_row:=d.get_object('metadata').get_number('revision_row_id');x:=treat(a.get(0) as json_object_t);

   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_REVISION_ROW',RRL_STOCK_PLAN_HELPER.decimal_text(revision_row)));

   select REVISION_ID,CELL,ARTICUL1 into row_doc,row_cell,row_article from RRL_REVISION_ROW where ID=revision_row for update;

   if row_doc is null or row_doc!=doc or row_cell is null or row_cell!=x.get_string('cell')

    or row_article is null or row_article!=x.get_string('article') then raise_application_error(-20890,'CLOSURE_CHANGED: revision row');end if;

   v_uid:=x.get_string('uid');

   select count(*) into other_lots from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA

    where s.CELL=row_cell and p.ARTICUL=row_article and s.REMAIN>0 and s.UID_POLETA!=v_uid;

   if other_lots>0 then raise_application_error(-20887,'LOT_SELECTION_REQUIRED: inventory-count.html');end if;

  end if;

  for i in 0..a.get_size-1 loop

   x:=treat(a.get(i) as json_object_t);sourcex:=treat(original.get(i) as json_object_t);

   RRL_STOCK_LOCATION_CORE.assert_quarantine(x.get_string('cell'),ware);

   begin declare

 v_json_sql_4_1 varchar2(32767):=x.get_string('uid');

 v_json_sql_4_2 varchar2(32767):=x.get_string('cell');

begin

select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION into p,h,stockver from RRL_REMAINS where UID_POLETA=v_json_sql_4_1 and CELL=v_json_sql_4_2;

end;

   exception when no_data_found then p:=0;h:=0;stockver:=0;end;

   if stockver!=x.get_number('version') or RRL_STOCK_PLAN_HELPER.decimal_text(p)!=x.get_string('p') or RRL_STOCK_PLAN_HELPER.decimal_text(h)!=x.get_string('h') then raise_application_error(-20890,'CLOSURE_CHANGED: inventory stock');end if;

   RRL_STOCK_PALLET_UOM.resolve_quantity(x.get_string('uid'),sourcex.get_string('unit'),

    case when regexp_like(sourcex.get_string('quantity'),'^0([.]0{1,9})?$') then '1' else sourcex.get_string('quantity') end,base,qty,ver,signature);

   if regexp_like(sourcex.get_string('quantity'),'^0([.]0{1,9})?$') then qty:=0;end if;

   if signature!=x.get_string('signature') or base!=x.get_string('base') then raise_application_error(-20890,'CLOSURE_CHANGED: inventory UOM');end if;

   if qty<h then raise_application_error(-20869,'INVENTORY_COUNT_BELOW_HARD: explicitly release conflicting reservations first');end if;

   declare

 v_json_sql_5_1 varchar2(32767):=x.get_string('article');

begin

select max(POLICY_VERSION) into basever from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_json_sql_5_1 and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;

end;

   if basever is null then raise_application_error(-20868,'INVENTORY_BASE_POLICY_REQUIRED');end if;

   delta:=qty-p;eventid:=null;units:=null;

   if sourcex.has('unit_keys') and sourcex.get_array('unit_keys').get_size>0 then units:=sourcex.get_array('unit_keys').to_clob;end if;

   if delta>0 then

    declare

 v_json_sql_6_1 varchar2(32767):=x.get_string('article');

 v_json_sql_6_2 varchar2(32767):=x.get_string('article');

 v_json_sql_6_3 varchar2(32767):=x.get_string('article');

begin

select greatest(nvl((select MARKING_REQUIRED from RRL_SKU_RECEIPT_POLICY where ARTICUL=v_json_sql_6_1),0),

      nvl((select CRPT_REQUIRED from RRL_FINISHED_GOODS_SKU where ARTICUL=v_json_sql_6_2),0),

      case when exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=v_json_sql_6_3) then 1 else 0 end) into marking from dual;

end;

    if marking!=0 then raise_application_error(-20884,'MARKED_INVENTORY_INCREASE_REQUIRES_CAPTURED_UNITS');end if;

    RRL_STOCK_BALANCE_CORE.apply_delta(x.get_string('uid'),x.get_string('cell'),delta,0,base,basever,stockver);

    RRL_STOCK_BALANCE_CORE.write_leg(x.get_string('uid'),null,x.get_string('cell'),delta,base,basever,i+1,1,1,p_actor,eventid);

   elsif delta<0 then

    RRL_STOCK_UNIT_CORE.issue_free_units(x.get_string('uid'),x.get_string('cell'),-delta,units);

    RRL_STOCK_BALANCE_CORE.apply_delta(x.get_string('uid'),x.get_string('cell'),delta,0,base,basever,stockver);

    RRL_STOCK_BALANCE_CORE.write_leg(x.get_string('uid'),x.get_string('cell'),null,delta,base,basever,i+1,1,3,p_actor,eventid);

   end if;

   fact:=json_object_t();fact.put('uid',x.get_string('uid'));fact.put('cell',x.get_string('cell'));fact.put('base_uom',base);

   fact.put('before',RRL_STOCK_PLAN_HELPER.decimal_text(p));fact.put('after',RRL_STOCK_PLAN_HELPER.decimal_text(qty));fact.put('delta',RRL_STOCK_PLAN_HELPER.decimal_text(delta));fact.put('event_id',eventid);facts.append(fact);

  end loop;

  if revision_row is not null then

   sourcex:=treat(original.get(0) as json_object_t);

   declare v_row_unit varchar2(20):=sourcex.get_string('unit');v_row_qty varchar2(30):=sourcex.get_string('quantity');v_row_op varchar2(100):=d.get_string('operation_id');begin

   update RRL_REVISION_ROW set COUNT1=qty,REV_DATE=sysdate,

    COUNT_KOR=case when v_row_unit='BOX' then to_number(v_row_qty,'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''') else COUNT_KOR end,

    REMARK1=substr(nvl(REMARK1,'')||' POSTED:'||v_row_op,1,255)

    where ID=revision_row;end;

  end if;

  result.put('operation_id',d.get_string('operation_id'));result.put('revision_id',doc);result.put('counts',facts);RRL_STOCK_SHORT_RECOVERY.finish_inventory(p_request,p_actor,v,facts,result);p_result:=result.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_INV_ENTRY as
 function register_line(p_cell varchar2,p_barcode varchar2,p_article_part varchar2,p_qty number,p_document number,
  p_expiry date,p_actor varchar2,p_operation varchar2) return varchar2 is
  d json_object_t:=json_object_t();src json_object_t:=json_object_t();m json_object_t:=json_object_t();x json_object_t;
  requested json_object_t:=json_object_t();a json_array_t:=json_array_t();saved clob;result clob;article varchar2(160);uid varchar2(200);
  base varchar2(20);other_base varchar2(20);version number;n number;quantity_text varchar2(30);wire clob;old_wire clob;lot_expiry date;
 begin
  if p_document is null or p_document<1 or p_operation is null or p_actor is null or p_qty is null or p_qty<0 or (p_barcode is null and p_article_part is null) then
   raise_application_error(-20871,'INVENTORY_DOCUMENT_ACTOR_OPERATION_REQUIRED');end if;
  RRL_STOCK_MATH.assert_base(p_qty,9);quantity_text:=RRL_STOCK_PLAN_HELPER.decimal_text(p_qty);
  requested.put('cell',p_cell);requested.put('barcode',p_barcode);requested.put('article_part',p_article_part);
  requested.put('quantity',quantity_text);requested.put('document',p_document);requested.put('expiry',to_char(p_expiry,'YYYY-MM-DD'));
  begin
   select CANONICAL_REQUEST into saved from RRL_STOCK_OPERATION where OPERATION_ID=p_operation;
  exception when no_data_found then saved:=null;end;
  if saved is not null then
   d:=json_object_t.parse(saved);
   if not d.has('metadata') or not d.get_object('metadata').has('requested_legacy') then
    raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   wire:=requested.to_clob;old_wire:=d.get_object('metadata').get_object('requested_legacy').to_clob;
   if d.get_string('actor')!=p_actor or d.get_string('command_type') not in('INVENTORY_COUNT','INVENTORY_REGISTER_LOT')
    or dbms_lob.compare(wire,old_wire)!=0 then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   RRL_STOCK_NATIVE_API.post(saved,p_actor,result);return RRL_GIVE_NEXT_CELL(p_cell);
  end if;
  begin
   select ACTICUL into article from RRL_ARTICULS where BARCODE_SHT=p_barcode or BARCODE_KOR=p_barcode or BARCODE_BL=p_barcode;
  exception when no_data_found then
   select ACTICUL into article from RRL_ARTICULS where ACTICUL like '%'||p_article_part;
  end;
  select min(BASE_UOM),max(BASE_UOM) into base,other_base from RRL_STOCK_UOM_CONVERSION
   where ARTICUL=article and INPUT_UOM=BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
  if base is null or base!=other_base then raise_application_error(-20868,'INVENTORY_BASE_POLICY_AMBIGUOUS');end if;
  uid:='P_'||article||'_G'||to_char(p_document,'TM9')||'_'||p_cell;
  select count(*) into n from RRL_PALLETS where UID_PALLET=uid;
  d:=json_object_t();d.put('contract_version',2);d.put('operation_id',p_operation);d.put('actor',p_actor);
  d.put('lines',json_array_t());d.put('units',json_array_t());src.put('revision_id',p_document);d.put('source',src);
  m.put('reason','Measured legacy inventory');m.put('requested_legacy',requested);
  if n=0 then
   if p_expiry is null or p_qty<=0 then raise_application_error(-20871,'INVENTORY_INITIAL_EXPIRY_QUANTITY_REQUIRED');end if;
   d.put('command_type','INVENTORY_REGISTER_LOT');m.put('uid',uid);m.put('cell',p_cell);m.put('article',article);
   m.put('quantity',quantity_text);m.put('expiry_date',to_char(p_expiry,'YYYY-MM-DD'));m.put('price',1);
  else
   select EXPIRY_DATE into lot_expiry from RRL_PALLETS where UID_PALLET=uid;
   if p_expiry is not null and (lot_expiry is null or trunc(lot_expiry)!=trunc(p_expiry)) then
    raise_application_error(-20871,'INVENTORY_LOT_EXPIRY_CONFLICT');end if;
   begin select STOCK_VERSION into version from RRL_REMAINS where UID_POLETA=uid and CELL=p_cell;
   exception when no_data_found then version:=0;end;
   d.put('command_type','INVENTORY_COUNT');x:=json_object_t();x.put('uid',uid);x.put('cell',p_cell);x.put('article',article);
   x.put('quantity',quantity_text);x.put('unit',base);x.put('expected_stock_version',version);
   x.put('unit_keys',json_array_t());a.append(x);m.put('counts',a);
  end if;
  d.put('metadata',m);RRL_STOCK_NATIVE_API.post(d.to_clob,p_actor,result);return RRL_GIVE_NEXT_CELL(p_cell);
 end;
 function count_lot(p_cell varchar2,p_uid varchar2,p_quantity varchar2,p_unit varchar2,p_document number,
  p_actor varchar2,p_operation varchar2,p_reason varchar2) return varchar2 is
  requested json_object_t:=json_object_t();d json_object_t:=json_object_t();m json_object_t:=json_object_t();
  src json_object_t:=json_object_t();x json_object_t:=json_object_t();a json_array_t:=json_array_t();
  saved clob;wire clob;old_wire clob;result clob;uid varchar2(200);other_uid varchar2(200);article varchar2(160);version number;
 begin
  if p_document is null or p_document<1 or p_actor is null or p_operation is null or trim(p_reason) is null
   or p_quantity is null or length(p_quantity)>28 or not regexp_like(p_quantity,'^[0-9]{1,18}([.][0-9]{1,9})?$','c') then
   raise_application_error(-20871,'INVENTORY_DOCUMENT_OPERATION_REASON_QUANTITY_REQUIRED');end if;
  requested.put('cell',p_cell);requested.put('uid',p_uid);requested.put('quantity',p_quantity);
  requested.put('unit',p_unit);requested.put('document',p_document);requested.put('reason',p_reason);
  begin select CANONICAL_REQUEST into saved from RRL_STOCK_OPERATION where OPERATION_ID=p_operation;
  exception when no_data_found then saved:=null;end;
  if saved is not null then
   d:=json_object_t.parse(saved);d.on_error(1);
   if d.get_string('actor')!=p_actor or d.get_string('command_type')!='INVENTORY_COUNT'
    or not d.get_object('metadata').has('requested_lot') then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   wire:=requested.to_clob;old_wire:=d.get_object('metadata').get_object('requested_lot').to_clob;
   if dbms_lob.compare(wire,old_wire)!=0 then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   RRL_STOCK_NATIVE_API.post(saved,p_actor,result);return 'ok';
  end if;
  uid:=p_uid;
  if uid is null then
   select min(UID_POLETA),max(UID_POLETA) into uid,other_uid from RRL_REMAINS where CELL=p_cell and REMAIN>0;
   if uid is null or uid!=other_uid then raise_application_error(-20887,'LOT_SELECTION_REQUIRED: count each physical pallet');end if;
  end if;
  select ARTICUL into article from RRL_PALLETS where UID_PALLET=uid;
  begin select STOCK_VERSION into version from RRL_REMAINS where UID_POLETA=uid and CELL=p_cell;
  exception when no_data_found then version:=0;end;
  d:=json_object_t();d.put('contract_version',2);d.put('operation_id',p_operation);d.put('actor',p_actor);
  d.put('command_type','INVENTORY_COUNT');d.put('lines',json_array_t());d.put('units',json_array_t());
  src.put('revision_id',p_document);d.put('source',src);m.put('reason',p_reason);m.put('requested_lot',requested);
  x.put('uid',uid);x.put('cell',p_cell);x.put('article',article);x.put('quantity',p_quantity);
  x.put('unit',p_unit);x.put('expected_stock_version',version);x.put('unit_keys',json_array_t());a.append(x);m.put('counts',a);
  d.put('metadata',m);RRL_STOCK_NATIVE_API.post(d.to_clob,p_actor,result);return 'ok';
 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_IW_PUT_CELL as
 procedure assert_target(p_ware number,p_uid varchar2,p_from varchar2,p_target varchar2,p_gross number,p_task_id number)is
 v_capacity number;v_height number;v_weight number;v_unknown number;n number;
 begin
 select LIMIT_WEIGHT,LIMIT_HEIGHT into v_capacity,v_height from RRL_CELLS where CELL=p_target and WARE_ID=p_ware and nvl(BLOCKED_FOR_ACCEPT,0)=0 and nvl(BLOCKED_FOR_REMAINS,0)=0 and nvl(BLOCKED_FOR_POPOLNENIE,0)=0;
 if p_target=p_from then raise_application_error(-20886,'INTERWARE_SEPARATE_OUTBOUND_BUFFER_REQUIRED');end if;
 if nvl(v_height,0)>0 then raise_application_error(-20886,'INTERWARE_TARGET_HEIGHT_PROOF_REQUIRED');end if;
 select count(*)into n from RRL_TOPOLOGY_CELL_SLOT sl join RRL_TOPOLOGY_CELL tc on tc.TOPOLOGY_CELL_ID=sl.TOPOLOGY_CELL_ID join RRL_WAREHOUSE_TOPOLOGY t on t.TOPOLOGY_ID=tc.TOPOLOGY_ID where tc.LEGACY_CELL_CODE=p_target and tc.WARE_ID=p_ware and tc.ACTIVE=1 and sl.ACTIVE=1 and t.STATUS='PUBLISHED';
 if n!=0 then raise_application_error(-20886,'INTERWARE_TARGET_SLOT_FLOW_REQUIRED');end if;
 if nvl(v_capacity,0)>0 then
  select nvl(sum(pp.WEIGHT_BRUTTO),0),nvl(sum(case when pp.WEIGHT_BRUTTO is null then 1 else 0 end),0)into v_weight,v_unknown from(
   select r.UID_POLETA UID_PALLET from RRL_REMAINS r where r.CELL=p_target and r.REMAIN>0 and r.UID_POLETA!=p_uid
   union select wt.UID_PALLET from RRL_WAREHOUSE_TASK wt where wt.TO_CELL=p_target and wt.STATUS not in('DONE','CANCELLED')and wt.UID_PALLET!=p_uid and(p_task_id is null or wt.TASK_ID!=p_task_id)
  )occupants join RRL_PALLETS pp on pp.UID_PALLET=occupants.UID_PALLET;
  if p_gross is null or v_unknown>0 or v_weight+p_gross>v_capacity then raise_application_error(-20886,'INTERWARE_TARGET_WEIGHT_CAPACITY_EXCEEDED');end if;
 end if;
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_AVAILABLE_TARGET_CELL_REQUIRED');end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_IW_RECOVERY_CANCEL as
 procedure assert_scope(p_request varchar2,p_actor varchar2)is req RRL_INTERWARE_RECOVERY_REQUEST%rowtype;n number;approved number;
 begin
 select *into req from RRL_INTERWARE_RECOVERY_REQUEST where OPERATION_ID=p_request;
 select count(*)into approved from RRL_INTERWARE_RECOVERY_APPROVAL where REQUEST_OPERATION_ID=p_request;
 select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0 and(u.WARE_ID=req.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN')
 and RRL_HAS_WRIGHT(u.ID,'store_return_approve')=1;
 if n!=1 or(approved>0 and req.ACTOR=p_actor)then raise_application_error(-20882,'RECOVERY_CANCEL_CURRENT_INDEPENDENT_CONTROLLER_REQUIRED');end if;
 exception when no_data_found then raise_application_error(-20886,'RECOVERY_CANCEL_REQUEST_REQUIRED');end;
 procedure describe(p_request clob,p_actor varchar2,p_domain out json_object_t)is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');req_id varchar2(100):=d.get_object('source').get_string('request_operation_id');
 req RRL_INTERWARE_RECOVERY_REQUEST%rowtype;n number;reason varchar2(2000):=m.get_string('reason');ref varchar2(2000):=m.get_string('evidence_reference');source json_object_t;
 begin
 assert_scope(req_id,p_actor);select *into req from RRL_INTERWARE_RECOVERY_REQUEST where OPERATION_ID=req_id;
 if m.get_size!=3 or trim(reason)is null or length(trim(reason))<8 or length(reason)>500 or trim(ref)is null or length(ref)>255
 or RRL_STOCK_MATH.quantity(m.get_string('quantity'))!=req.BASE_QTY then raise_application_error(-20886,'RECOVERY_CANCEL_EXACT_REQUEST_REASON_EVIDENCE_REQUIRED');end if;
 select count(*)into n from RRL_IW_RECOVERY_CANCEL where REQUEST_OPERATION_ID=req_id;if n!=0 then raise_application_error(-20886,'RECOVERY_REQUEST_ALREADY_CANCELLED');end if;
 select count(*)into n from RRL_INTERWARE_RECOVERY_APPROVAL approved join RRL_INTERWARE_RECOVERY_RECEIPT received on received.APPROVAL_OPERATION_ID=approved.OPERATION_ID
 where approved.REQUEST_OPERATION_ID=req_id;if n!=0 then raise_application_error(-20886,'RECOVERY_PHYSICALLY_RECEIVED_CANNOT_CANCEL');end if;
 source:=json_object_t.parse(req.SOURCE_JSON);
 p_domain:=json_object_t();p_domain.put('request_operation_id',req_id);p_domain.put('loss_operation_id',req.LOSS_OPERATION_ID);
 p_domain.put('warehouse_id',req.WARE_ID);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(req.BASE_QTY));p_domain.put('base_uom',req.BASE_UOM);
 p_domain.put('source_units',source.get_array('source_units'));p_domain.put('reason',reason);p_domain.put('evidence_reference',ref);
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;u json_object_t;begin
 describe(p_request,d.get_string('actor'),v);RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_SHORTAGE_FACT',v.get_string('loss_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECOVERY_REQUEST',v.get_string('request_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_IW_RECOVERY_CANCEL',v.get_string('request_operation_id'));
 a:=v.get_array('source_units');for i in 0..a.get_size-1 loop u:=treat(a.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',u.get_string('key'));end loop;
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');wire clob;v json_object_t;fresh json_object_t;
 req_id varchar2(100);loss_id varchar2(100);ware number;qty number;uom varchar2(20);reason varchar2(2000);ref varchar2(2000);begin
 select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(wire).get_object('domain');
 describe(p_request,p_actor,fresh);if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'RECOVERY_CANCEL_SOURCE_CHANGED');end if;
 req_id:=v.get_string('request_operation_id');loss_id:=v.get_string('loss_operation_id');ware:=v.get_number('warehouse_id');qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));
 uom:=v.get_string('base_uom');reason:=v.get_string('reason');ref:=v.get_string('evidence_reference');wire:=v.to_clob;
 insert into RRL_IW_RECOVERY_CANCEL(OPERATION_ID,REQUEST_OPERATION_ID,LOSS_OPERATION_ID,WARE_ID,BASE_QTY,BASE_UOM,ACTOR,REASON_TEXT,EVIDENCE_REFERENCE,SOURCE_JSON)
 values(op,req_id,loss_id,ware,qty,uom,p_actor,reason,ref,wire);
 v.put('operation_id',op);v.put('status','RECOVERY_CANCELLED');v.put('stock_changed',false);v.put('historical_loss_preserved',true);v.put('quantity_restored_to_unreported',v.get_string('quantity'));p_result:=v.to_clob;end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_IW_RECOVERY_NEXT as   
 function describe_source(p_st number,p_ware number) return json_object_t is   
 bind RRL_IW_RECOVERY_ST_BIND%rowtype;receipt RRL_INTERWARE_RECOVERY_RECEIPT%rowtype;placed RRL_IW_RECOVERY_PLACEMENT%rowtype;v_p number;v_h number;v_uom varchar2(20);v_ver number;v_policy number;n number;unit_count number;unit_total number;unit_distinct number;unit_wire clob;unit_snapshot clob;receipt_wire clob;receipt_domain json_object_t;subset_wire json_object_t;j json_object_t:=json_object_t();   
 begin   
 begin select *into bind from RRL_IW_RECOVERY_ST_BIND where ST_ID=p_st;exception when no_data_found then return null;end;   
 select *into receipt from RRL_INTERWARE_RECOVERY_RECEIPT where OPERATION_ID=bind.RECOVERY_OPERATION_ID;   
 select *into placed from RRL_IW_RECOVERY_PLACEMENT where RECOVERY_OPERATION_ID=receipt.OPERATION_ID;   
 if p_ware!=receipt.WARE_ID or bind.WARE_ID!=p_ware or bind.ROOT_UID!=receipt.ROOT_UID or placed.TARGET_CELL!=bind.SOURCE_CELL then raise_application_error(-20886,'INTERWARE_ONWARD_ORIGINAL_SOURCE_REQUIRED');end if;   
 select count(*)into n from RRL_INTERWARE_CUSTODY_PROOF where RECEIPT_OPERATION_ID=bind.RECEIPT_OPERATION_ID;if n!=1 then raise_application_error(-20886,'INTERWARE_FIRST_LEG_CUSTODY_REQUIRED');end if;   
 select count(*)into n from RRL_IW_RECOVERY_DISPATCH where BIND_OPERATION_ID=bind.OPERATION_ID;if n!=0 then raise_application_error(-20886,'INTERWARE_ONWARD_ALREADY_DISPATCHED');end if;   
 select REMAIN,HARD_RESERVED_BASE,BASE_UOM,STOCK_VERSION into v_p,v_h,v_uom,v_ver from RRL_REMAINS where UID_POLETA=receipt.ROOT_UID and CELL=bind.SOURCE_CELL;   
 if v_p!=receipt.BASE_QTY or v_h!=0 or v_uom!=receipt.BASE_UOM or v_ver!=bind.STOCK_VERSION then raise_application_error(-20886,'INTERWARE_ONWARD_WHOLE_STOCK_VERSION_REQUIRED');end if;   
 select count(*)into n from RRL_REMAINS where UID_POLETA=receipt.ROOT_UID and CELL!=bind.SOURCE_CELL and(REMAIN!=0 or HARD_RESERVED_BASE!=0);if n!=0 then raise_application_error(-20886,'INTERWARE_ONWARD_ONE_PHYSICAL_CELL_REQUIRED');end if;   
 select count(*)into n from dual where exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=receipt.ARTICLE)or exists(select 1 from RRL_SKU_RECEIPT_POLICY where ARTICUL=receipt.ARTICLE and MARKING_REQUIRED=1)or exists(select 1 from RRL_FINISHED_GOODS_SKU where ARTICUL=receipt.ARTICLE and CRPT_REQUIRED=1);   
 select count(*)into unit_count from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=receipt.ROOT_UID;   
 if n>0 or unit_count>0 then   
  receipt_domain:=json_object_t.parse(receipt.SOURCE_JSON);subset_wire:=json_object_t(); 
  subset_wire.put('units',receipt_domain.get_array('source_units'));subset_wire.put('physical_unit_count',receipt_domain.get_array('source_units').get_size);unit_wire:=subset_wire.to_clob; 
  select count(*),sum(u.BASE_QTY),count(distinct u.PHYSICAL_UNIT_KEY),   
   json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob)   
   into n,unit_total,unit_distinct,unit_snapshot   
   from RRL_WMS_RECEIPT_UNIT u join json_table(unit_wire,'$.units[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))j on j.K=u.PHYSICAL_UNIT_KEY   
   where u.CURRENT_UID=receipt.ROOT_UID and u.CURRENT_CELL=bind.SOURCE_CELL and u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null and u.BASE_QTY=RRL_STOCK_MATH.quantity(j.Q)and u.BASE_UOM=j.B and u.BASE_UOM=receipt.BASE_UOM;   
  if unit_count<1 or unit_count>10000 or n!=unit_count or unit_distinct!=unit_count or unit_total!=receipt.BASE_QTY or json_object_t.parse(unit_wire).get_number('physical_unit_count')!=unit_count then raise_application_error(-20884,'INTERWARE_ONWARD_ORIGINAL_UNITS_REQUIRED');end if;   
  j.put('physical_units',json_array_t.parse(unit_snapshot));   
 end if;   
 select max(POLICY_VERSION)into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=receipt.ARTICLE and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=DENOMINATOR;   
 if v_policy is null then raise_application_error(-20886,'INTERWARE_ONWARD_BASE_UOM_REQUIRED');end if;   
 select count(*)into n from RRL_SBORKA_PALLETS where ID=p_st and WARE_ID=p_ware and ADDR=bind.FINAL_ADDRESS and RETURN_SUPPLIER_ID is null and nvl(CONDITION,0)<2 and(TRANSTASK_ID is null or TRANSTASK_ID=bind.TARGET_TT_ID);   
 if n!=1 then raise_application_error(-20886,'INTERWARE_ONWARD_ST_SOURCE_CHANGED');end if;   
 j.put('binding_operation_id',bind.OPERATION_ID);j.put('receipt_operation_id',bind.RECEIPT_OPERATION_ID);j.put('recovery_operation_id',receipt.OPERATION_ID);j.put('source_load_operation_id',bind.SOURCE_LOAD_OPERATION_ID);j.put('source_st_id',bind.SOURCE_ST_ID);j.put('st_id',p_st);j.put('target_trip_id',bind.TARGET_TT_ID);j.put('warehouse_id',p_ware);   
 j.put('uid',receipt.ROOT_UID);j.put('cell',bind.SOURCE_CELL);j.put('article',receipt.ARTICLE);j.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_p));j.put('base_uom',v_uom);j.put('stock_version',v_ver);j.put('uom_version',v_policy);return j;   
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_ONWARD_PLACED_SOURCE_REQUIRED');   
 end;   
 procedure declare_source(p_source json_object_t,p_operation varchar2,p_resources in out nocopy json_array_t) is   
 begin   
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_RECOVERY_ST_BIND',p_source.get_string('binding_operation_id'));   
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INTERWARE_RECOVERY_RECEIPT',p_source.get_string('recovery_operation_id'));   
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_RECOVERY_DISPATCH',p_operation);   
 end;   
 procedure validate_load(p_source json_object_t,p_actor varchar2) is   
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');n number;v_kind varchar2(80);v_binding varchar2(100):=p_source.get_string('binding_operation_id');v_current json_object_t;trip_id number:=p_source.get_number('target_trip_id');st_id number:=p_source.get_number('st_id');v_warehouse number:=p_source.get_number('warehouse_id');   
 begin   
 select COMMAND_TYPE into v_kind from RRL_STOCK_OPERATION where OPERATION_ID=op and STATE='IN_FLIGHT';   
 if v_kind='HU_SHIP'then
 select count(*)into n from RRL_STOCK_OPERATION root_op
 where root_op.OPERATION_ID=op and root_op.STATE='IN_FLIGHT'
 and json_value(root_op.RESOLVED_PLAN_JSON,'$.domain.loading.trip'returning number)=trip_id
 and exists(select 1 from json_table(root_op.RESOLVED_PLAN_JSON,'$.domain.shipments[*]'columns(
  BINDING_ID varchar2(100)path '$.domain.interwarehouse_onward_source.binding_operation_id',
  ST_NO number path '$.domain.interwarehouse_onward_source.st_id'))resolved
  where resolved.BINDING_ID=v_binding and resolved.ST_NO=st_id);
 if n!=1 then raise_application_error(-20886,'INTERWARE_NESTED_ACTUAL_TARGET_LOADING_REQUIRED');end if;
 elsif v_kind!='LOAD_SHIPMENT'then raise_application_error(-20886,'INTERWARE_ONWARD_ACTUAL_LOADING_REQUIRED');end if;   
 select count(*)into n from RUSERS u where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=v_warehouse or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,'stock_posting_shipping')=1;if n!=1 then raise_application_error(-20882,'INTERWARE_ONWARD_CURRENT_WARE_ACTOR_REQUIRED');end if;   
 v_current:=describe_source(st_id,v_warehouse);if v_current is null or dbms_lob.compare(v_current.to_clob,p_source.to_clob)!=0 then raise_application_error(-20886,'INTERWARE_ONWARD_LOAD_SOURCE_CHANGED');end if;   
 select count(*)into n from RRL_SBORKA_PALLETS where ID=st_id and TRANSTASK_ID=trip_id;if n!=1 then raise_application_error(-20886,'INTERWARE_ONWARD_ORIGINAL_TARGET_TRIP_REQUIRED');end if;   
 end;   
 procedure dispatched(p_source json_object_t,p_actor varchar2) is   
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');v_bind varchar2(100):=p_source.get_string('binding_operation_id');v_receipt varchar2(100):=p_source.get_string('receipt_operation_id');v_recovery varchar2(100):=p_source.get_string('recovery_operation_id');v_source varchar2(100):=p_source.get_string('source_load_operation_id');v_st number:=p_source.get_number('st_id');v_uid varchar2(200):=p_source.get_string('uid');v_qty number:=RRL_STOCK_MATH.quantity(p_source.get_string('quantity'));v_uom varchar2(20):=p_source.get_string('base_uom');payload json_object_t:=json_object_t();v_body clob;   
 begin   
 insert into RRL_IW_RECOVERY_DISPATCH(OPERATION_ID,BIND_OPERATION_ID,RECOVERY_OPERATION_ID,RECEIPT_OPERATION_ID,SOURCE_LOAD_OPERATION_ID,ST_ID,ROOT_UID,BASE_QTY,BASE_UOM,ACTOR)values(op,v_bind,v_recovery,v_receipt,v_source,v_st,v_uid,v_qty,v_uom,p_actor);   
 payload.put('operation_id',op);payload.put('receipt_operation_id',v_receipt);payload.put('source_load_operation_id',v_source);payload.put('source_st_id',p_source.get_number('source_st_id'));payload.put('st_id',v_st);payload.put('warehouse_id',p_source.get_number('warehouse_id'));payload.put('pallet_identifier',v_uid);payload.put('quantity',p_source.get_string('quantity'));payload.put('base_uom',v_uom);payload.put('customer_fulfillment_repeated',false);payload.put('external_sap_ack',false);v_body:=payload.to_clob;   
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values('IW.RECOVERY.ONWARD:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op||':'||RRL_STOCK_PLAN_HELPER.decimal_text(v_st),'AL32UTF8'),sys.dbms_crypto.hash_sh256)),'INTERWARE_RECOVERY_DISPATCHED',v_body);   
 end;   
end;
/


CREATE OR REPLACE package body RRL_STOCK_IW_RECOVERY_PLAN as 
 procedure assert_scope(p_request clob,p_actor varchar2)is 
 d json_object_t:=json_object_t.parse(p_request);kind varchar2(80):=d.get_string('command_type');loss_id varchar2(100);req_id varchar2(100);reporter varchar2(100);n number; 
 begin 
 if kind='INTERWARE_RECOVERY_REPORT'then loss_id:=d.get_object('source').get_string('loss_operation_id'); 
 elsif kind='INTERWARE_RECOVERY_APPROVE'then req_id:=d.get_object('source').get_string('request_operation_id'); 
  select LOSS_OPERATION_ID,ACTOR into loss_id,reporter from RRL_INTERWARE_RECOVERY_REQUEST where OPERATION_ID=req_id; 
 else raise_application_error(-20886,'INTERWARE_RECOVERY_DECISION_REQUIRED');end if; 
 select count(*)into n from RRL_INTERWARE_SHORTAGE_FACT loss join RRL_INTERWARE_RECEIPT r on r.OPERATION_ID=loss.RECEIPT_OPERATION_ID 
 join RUSERS u on u.ID=p_actor where loss.OPERATION_ID=loss_id and nvl(u.DELETED,0)=0 
 and(u.WARE_ID=r.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN') 
 and RRL_HAS_WRIGHT(u.ID,case when kind='INTERWARE_RECOVERY_REPORT'then 'transport_dispatch_edit'else 'store_return_approve'end)=1; 
 if n!=1 or(kind='INTERWARE_RECOVERY_APPROVE'and reporter=p_actor)then raise_application_error(-20882,'INTERWARE_RECOVERY_CURRENT_INDEPENDENT_TARGET_ACTOR_REQUIRED');end if; 
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_RECOVERY_SOURCE_NOT_FOUND'); 
 end; 
 procedure describe(p_request clob,p_actor varchar2,p_domain out json_object_t)is 
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');kind varchar2(80):=d.get_string('command_type'); 
 loss_id varchar2(100);req_id varchar2(100);loss RRL_INTERWARE_SHORTAGE_FACT%rowtype;receipt RRL_INTERWARE_RECEIPT%rowtype;req RRL_INTERWARE_RECOVERY_REQUEST%rowtype; 
 n number;quantity number;wire clob;source json_object_t;unit_wire clob;fresh_units clob;expected_count number;total number;selected_wire clob;selected_count number;allocated_qty number;request_count number; 
 reason varchar2(2000):=m.get_string('reason');ref varchar2(2000):=m.get_string('evidence_reference');old_uid varchar2(200);old_cell varchar2(60); 
 begin 
 assert_scope(p_request,p_actor); 
 if m.get_size not in(3,4)or(m.get_size=4 and not m.has('unit_keys'))or trim(reason)is null or length(trim(reason))<8 or length(reason)>500 or trim(ref)is null or length(ref)>255 then raise_application_error(-20886,'INTERWARE_RECOVERY_EXPLICIT_EVIDENCE_REQUIRED');end if; 
 quantity:=RRL_STOCK_MATH.quantity(m.get_string('quantity')); 
 if kind='INTERWARE_RECOVERY_REPORT'then loss_id:=d.get_object('source').get_string('loss_operation_id'); 
 else req_id:=d.get_object('source').get_string('request_operation_id');select *into req from RRL_INTERWARE_RECOVERY_REQUEST where OPERATION_ID=req_id;loss_id:=req.LOSS_OPERATION_ID;end if; 
 select *into loss from RRL_INTERWARE_SHORTAGE_FACT where OPERATION_ID=loss_id; 
 select *into receipt from RRL_INTERWARE_RECEIPT where OPERATION_ID=loss.RECEIPT_OPERATION_ID; 
 select count(*)into n from RRL_STOCK_OPERATION where OPERATION_ID=loss_id and STATE='APPLIED'and COMMAND_TYPE='INTERWARE_SHORTAGE_CONFIRM'; 
 if n!=1 or quantity<=0 or quantity>loss.SHORT_QTY or receipt.ORIGINAL_ROOT_UID is null or loss.SHORT_QTY+receipt.BASE_QTY!=receipt.EXPECTED_BASE_QTY then raise_application_error(-20886,'INTERWARE_RECOVERY_WHOLE_CONFIRMED_DIFFERENCE_REQUIRED');end if; 
 if kind='INTERWARE_RECOVERY_REPORT'then
  select nvl(sum(BASE_QTY),0),count(*)into allocated_qty,request_count from RRL_INTERWARE_RECOVERY_REQUEST candidate where LOSS_OPERATION_ID=loss_id and not exists(
 select 1 from RRL_IW_RECOVERY_CANCEL cancelled join RRL_STOCK_OPERATION cancel_op on cancel_op.OPERATION_ID=cancelled.OPERATION_ID
 where cancelled.REQUEST_OPERATION_ID=candidate.OPERATION_ID and cancel_op.STATE='APPLIED'and cancel_op.COMMAND_TYPE='INTERWARE_RECOVERY_CANCEL');
  select count(*)into request_count from RRL_INTERWARE_RECOVERY_REQUEST where LOSS_OPERATION_ID=loss_id;
  if request_count>=1000 or quantity>loss.SHORT_QTY-allocated_qty then raise_application_error(-20886,'INTERWARE_RECOVERY_UNREPORTED_QUANTITY_EXCEEDED');end if;
 else
  select count(*)into n from RRL_IW_RECOVERY_CANCEL where REQUEST_OPERATION_ID=req_id;if n!=0 then raise_application_error(-20886,'RECOVERY_REQUEST_CANCELLED');end if;
  if quantity!=req.BASE_QTY then raise_application_error(-20886,'INTERWARE_RECOVERY_EXACT_REPORTED_QUANTITY_REQUIRED');end if;
  select count(*)into n from RRL_INTERWARE_RECOVERY_APPROVAL where REQUEST_OPERATION_ID=req_id;if n!=0 then raise_application_error(-20886,'INTERWARE_RECOVERY_ALREADY_APPROVED');end if;
 end if;
 source:=json_object_t.parse(loss.SOURCE_JSON);
 if kind='INTERWARE_RECOVERY_REPORT'then unit_wire:=source.get_array('missing_units').to_clob;
 else unit_wire:=json_object_t.parse(req.SOURCE_JSON).get_array('source_units').to_clob;end if;
 selected_wire:=null;selected_count:=0;
 if m.has('unit_keys')then
  if m.get('unit_keys').is_null or not m.get('unit_keys').is_array then raise_application_error(-20886,'INTERWARE_RECOVERY_UNIT_KEYS_ARRAY_REQUIRED');end if;
  if kind!='INTERWARE_RECOVERY_REPORT'or m.get_array('unit_keys').get_size>10000 then raise_application_error(-20886,'INTERWARE_RECOVERY_SELECTION_BOUND');end if;
  if m.get_array('unit_keys').get_size>0 then
   selected_wire:=m.get_array('unit_keys').to_clob;
   select count(*),count(distinct K)into n,selected_count from json_table(selected_wire,'$[*]'columns(K varchar2(64)path '$'));
   if n!=selected_count then raise_application_error(-20886,'INTERWARE_RECOVERY_DUPLICATE_SELECTED_UNIT');end if;
  end if;
 end if;
 select count(*)into expected_count from json_table(unit_wire,'$[*]'columns(K varchar2(64)path '$.key'))frozen
 where(selected_wire is null or exists(select 1 from json_table(selected_wire,'$[*]'columns(K varchar2(64)path '$'))chosen where chosen.K=frozen.K))
 and not exists(select 1 from RRL_INTERWARE_RECOVERY_REQUEST claimed,
 json_table(claimed.SOURCE_JSON,'$.source_units[*]'columns(K varchar2(64)path '$.key'))allocated
 where claimed.LOSS_OPERATION_ID=loss_id and(req_id is null or claimed.OPERATION_ID!=req_id)and allocated.K=frozen.K and not exists(select 1 from RRL_IW_RECOVERY_CANCEL cancelled
 join RRL_STOCK_OPERATION cancel_op on cancel_op.OPERATION_ID=cancelled.OPERATION_ID
 where cancelled.REQUEST_OPERATION_ID=claimed.OPERATION_ID and cancel_op.STATE='APPLIED'and cancel_op.COMMAND_TYPE='INTERWARE_RECOVERY_CANCEL'));
 if selected_count>0 and selected_count!=expected_count then raise_application_error(-20886,'INTERWARE_RECOVERY_SELECTED_UNIT_ALREADY_REPORTED_OR_FOREIGN');end if;
 if expected_count>10000 then raise_application_error(-20886,'INTERWARE_RECOVERY_UNIT_BOUND');end if; 
 old_uid:=source.get_string('original_uid');old_cell:=source.get_string('source_cell'); 
 if expected_count>0 then 
 select count(*),sum(u.BASE_QTY),json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob) 
 into n,total,fresh_units from json_table(unit_wire,'$[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom',V number path '$.version'))j 
 join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=j.K join RRL_INTERWARE_SHORTAGE_UNIT book on book.PHYSICAL_UNIT_KEY=j.K and book.FACT_OPERATION_ID=loss_id 
 where u.CURRENT_UID=old_uid and u.CURRENT_CELL=old_cell and u.STOCK_STATUS='ISSUED'and u.HARD_RESERVATION_ID is null 
 and u.BASE_QTY=RRL_STOCK_MATH.quantity(j.Q)and u.BASE_UOM=j.B and u.BASE_UOM=receipt.BASE_UOM and u.UNIT_VERSION=j.V and book.UNIT_VERSION=j.V
 and(selected_wire is null or exists(select 1 from json_table(selected_wire,'$[*]'columns(K varchar2(64)path '$'))chosen where chosen.K=j.K))
 and not exists(select 1 from RRL_INTERWARE_RECOVERY_REQUEST claimed,
 json_table(claimed.SOURCE_JSON,'$.source_units[*]'columns(K varchar2(64)path '$.key'))allocated
 where claimed.LOSS_OPERATION_ID=loss_id and(req_id is null or claimed.OPERATION_ID!=req_id)and allocated.K=j.K and not exists(select 1 from RRL_IW_RECOVERY_CANCEL cancelled
 join RRL_STOCK_OPERATION cancel_op on cancel_op.OPERATION_ID=cancelled.OPERATION_ID
 where cancelled.REQUEST_OPERATION_ID=claimed.OPERATION_ID and cancel_op.STATE='APPLIED'and cancel_op.COMMAND_TYPE='INTERWARE_RECOVERY_CANCEL')); 
 if n!=expected_count or total!=quantity then raise_application_error(-20886,'INTERWARE_RECOVERY_EXACT_ISSUED_LOST_UNITS_REQUIRED');end if; 
 else
 if json_array_t.parse(unit_wire).get_size>0 or selected_count>0 then raise_application_error(-20886,'INTERWARE_RECOVERY_MARKED_SELECTION_EXHAUSTED');end if;
 fresh_units:='[]';end if; 
 p_domain:=json_object_t();p_domain.put('loss_operation_id',loss_id);p_domain.put('receipt_operation_id',receipt.OPERATION_ID);p_domain.put('warehouse_id',receipt.WARE_ID); 
 p_domain.put('original_uid',old_uid);p_domain.put('source_cell',old_cell);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(quantity));p_domain.put('base_uom',receipt.BASE_UOM); 
 p_domain.put('source_units',json_array_t.parse(fresh_units)); 
 if req_id is not null then 
  if dbms_lob.compare(json_object_t.parse(req.SOURCE_JSON).get_array('source_units').to_clob,fresh_units)!=0 then raise_application_error(-20886,'INTERWARE_RECOVERY_REPORTED_VERSIONS_CHANGED');end if; 
  p_domain.put('request_operation_id',req_id);p_domain.put('reporter',req.ACTOR); 
 end if; 
 p_domain.put('reason',reason);p_domain.put('evidence_reference',ref); 
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_RECOVERY_CONFIRMED_SOURCE_REQUIRED'); 
 end; 
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is 
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;u json_object_t; 
 begin 
 describe(p_request,d.get_string('actor'),v); 
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_SHORTAGE_FACT',v.get_string('loss_operation_id')); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECOVERY_REQUEST',nvl(v.get_string('request_operation_id'),p_operation)); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECOVERY_APPROVAL',nvl(v.get_string('request_operation_id'),p_operation)); 
 a:=v.get_array('source_units');for i in 0..a.get_size-1 loop u:=treat(a.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',u.get_string('key'));end loop; 
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','IW.RECOVERY.LOSS:'||v.get_string('loss_operation_id')); 
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256))); 
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob; 
 end; 
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is 
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');kind varchar2(80):=d.get_string('command_type');resolved clob;v json_object_t;fresh json_object_t;j json_object_t; 
 loss_id varchar2(100);rec_id varchar2(100);req_id varchar2(100);ware number;qty number;uom varchar2(20);reason varchar2(2000);ref varchar2(2000);wire clob; 
 begin 
 select RESOLVED_PLAN_JSON into resolved from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(resolved).get_object('domain'); 
 describe(p_request,p_actor,fresh);if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: recovery decision');end if; 
 loss_id:=v.get_string('loss_operation_id');rec_id:=v.get_string('receipt_operation_id');req_id:=v.get_string('request_operation_id'); 
 ware:=v.get_number('warehouse_id');qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));uom:=v.get_string('base_uom');reason:=v.get_string('reason');ref:=v.get_string('evidence_reference');wire:=v.to_clob; 
 if kind='INTERWARE_RECOVERY_REPORT'then 
 insert into RRL_INTERWARE_RECOVERY_REQUEST(OPERATION_ID,LOSS_OPERATION_ID,RECEIPT_OPERATION_ID,WARE_ID,BASE_QTY,BASE_UOM,ACTOR,REASON_TEXT,EVIDENCE_REFERENCE,SOURCE_JSON) 
 values(op,loss_id,rec_id,ware,qty,uom,p_actor,reason,ref,wire); 
 else 
 insert into RRL_INTERWARE_RECOVERY_APPROVAL(OPERATION_ID,REQUEST_OPERATION_ID,ACTOR,REASON_TEXT,EVIDENCE_REFERENCE,SOURCE_JSON)values(op,req_id,p_actor,reason,ref,wire); 
 end if; 
 j:=json_object_t.parse(wire);j.put('operation_id',op);j.put('actor',p_actor);j.put('status',case when kind='INTERWARE_RECOVERY_REPORT'then 'RECOVERY_PENDING_INDEPENDENT_APPROVAL'else 'RECOVERY_APPROVED_PENDING_PHYSICAL_RECEIPT'end); 
 j.put('stock_changed',false);j.put('regulatory_ack_verified',false);p_result:=j.to_clob; 
 end; 
end;
/


CREATE OR REPLACE package body RRL_STOCK_IW_RECOVERY_PUT as
 procedure assert_scope(p_receipt varchar2,p_actor varchar2)is n number;begin
 select count(*)into n from RRL_INTERWARE_RECOVERY_RECEIPT r join RRL_STOCK_OPERATION o on o.OPERATION_ID=r.OPERATION_ID
 join RUSERS u on u.ID=p_actor where r.OPERATION_ID=p_receipt and o.STATE='APPLIED'and o.COMMAND_TYPE='INTERWARE_SHORTAGE_RECOVER'
 and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1
 and(u.WARE_ID=r.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
 if n!=1 then raise_application_error(-20882,'RECOVERY_PLACEMENT_ACTOR_REQUIRED');end if;end;
 procedure describe_current(p_receipt varchar2,p_actor varchar2,p_task number,p_domain out json_object_t)is
 r RRL_INTERWARE_RECOVERY_RECEIPT%rowtype;original_receipt RRL_INTERWARE_RECEIPT%rowtype;plan RRL_INTERWARE_PLAN%rowtype;
 target_cell varchar2(60);v_p number;v_h number;v_uom varchar2(20);v_version number;v_gross number;n number;unit_count number;unit_total number;
 unit_snapshot clob;thermal json_object_t;stored_lo number;stored_hi number;stored_decision varchar2(100);
 begin
 assert_scope(p_receipt,p_actor);
 select *into r from RRL_INTERWARE_RECOVERY_RECEIPT where OPERATION_ID=p_receipt;
 select receipt.*into original_receipt from RRL_INTERWARE_RECEIPT receipt join RRL_INTERWARE_SHORTAGE_REQUEST req on req.RECEIPT_OPERATION_ID=receipt.OPERATION_ID
 join RRL_INTERWARE_SHORTAGE_FACT fact on fact.REQUEST_OPERATION_ID=req.OPERATION_ID where fact.OPERATION_ID=r.LOSS_OPERATION_ID;
 select *into plan from RRL_INTERWARE_PLAN where OPERATION_ID=original_receipt.PLAN_OPERATION_ID;
 plan:=RRL_INTERWARE_ROUTING.resolved(plan);target_cell:=plan.OUTBOUND_DOCK;
 RRL_INTERWARE_THERMAL.assert_release(plan.OPERATION_ID);thermal:=json_object_t.parse(RRL_INTERWARE_THERMAL.mode_json(plan.OPERATION_ID));
 if p_task is not null then
 select TASK_TEMP_MIN,TASK_TEMP_MAX,TEMP_DECISION_OPERATION_ID into stored_lo,stored_hi,stored_decision from RRL_IW_RECOVERY_PUT_PLAN where TASK_ID=p_task;
 if nvl(stored_lo,-1000)!=nvl(thermal.get_number('task_temp_min'),-1000)or nvl(stored_hi,-1000)!=nvl(thermal.get_number('task_temp_max'),-1000)then raise_application_error(-20886,'RECOVERY_TEMPERATURE_REPLAN_REQUIRED');end if;
 thermal.put('task_decision_operation_id',stored_decision);
 end if;
 RRL_INTERWARE_THERMAL.assert_cell(thermal.to_clob,r.WARE_ID,target_cell);
 select count(*)into n from RRL_TT_DOCK where DOCK=target_cell and WARE_ID=r.WARE_ID and nvl(DOCK_IS_BLOCKED,0)=0;
 if n!=1 then raise_application_error(-20886,'RECOVERY_ORIGINAL_OUTBOUND_BUFFER_REQUIRED');end if;
 select count(*)into n from RRL_IW_RECOVERY_PLACEMENT where RECOVERY_OPERATION_ID=p_receipt;
 if n!=0 then raise_application_error(-20886,'RECOVERY_ALREADY_PLACED');end if;
 select count(*)into n from RRL_IW_RECOVERY_PUT_PLAN pp join RRL_WAREHOUSE_TASK t on t.TASK_ID=pp.TASK_ID
 where pp.RECOVERY_OPERATION_ID=p_receipt and t.STATUS!='CANCELLED'and(p_task is null or t.TASK_ID!=p_task);
 if n!=0 then raise_application_error(-20886,'RECOVERY_ACTIVE_PLACEMENT_EXISTS');end if;
 select REMAIN,HARD_RESERVED_BASE,BASE_UOM,STOCK_VERSION into v_p,v_h,v_uom,v_version from RRL_REMAINS where UID_POLETA=r.ROOT_UID and CELL=r.RECEIVE_CELL;
 if v_p!=r.BASE_QTY or v_h!=0 or v_uom!=r.BASE_UOM then raise_application_error(-20886,'RECOVERY_WHOLE_UNRESERVED_RECEIPT_REQUIRED');end if;
 select count(*)into n from RRL_REMAINS where UID_POLETA=r.ROOT_UID and CELL!=r.RECEIVE_CELL and(REMAIN!=0 or HARD_RESERVED_BASE!=0);
 if n!=0 then raise_application_error(-20886,'RECOVERY_MULTIPLE_STOCK_CELLS_DENIED');end if;
 select count(*)into unit_count from RRL_INTERWARE_RECOVERY_UNIT where RECOVERY_OPERATION_ID=p_receipt;
 select count(*)into n from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=r.ROOT_UID;
 if n!=unit_count or unit_count>10000 then raise_application_error(-20884,'RECOVERY_UNIT_COMPOSITION_CHANGED');end if;
 if unit_count>0 then
 select count(*),sum(u.BASE_QTY),json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),
 'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob)
 into n,unit_total,unit_snapshot from RRL_INTERWARE_RECOVERY_UNIT recovered join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=recovered.PHYSICAL_UNIT_KEY
 where recovered.RECOVERY_OPERATION_ID=p_receipt and u.CURRENT_UID=r.ROOT_UID and u.CURRENT_CELL=r.RECEIVE_CELL
 and u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null and u.BASE_QTY=recovered.BASE_QTY and u.BASE_UOM=recovered.BASE_UOM and u.BASE_UOM=r.BASE_UOM;
 if n!=unit_count or unit_total!=r.BASE_QTY then raise_application_error(-20884,'RECOVERY_ORIGINAL_AVAILABLE_UNITS_REQUIRED');end if;
 else
 select count(*)into n from dual where exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=r.ARTICLE)
 or exists(select 1 from RRL_SKU_RECEIPT_POLICY where ARTICUL=r.ARTICLE and MARKING_REQUIRED=1);
 if n>0 then raise_application_error(-20884,'RECOVERY_MARKED_UNITS_REQUIRED');end if;
 end if;
 select WEIGHT_BRUTTO into v_gross from RRL_PALLETS where UID_PALLET=r.ROOT_UID;
 RRL_STOCK_IW_PUT_CELL.assert_target(r.WARE_ID,r.ROOT_UID,r.RECEIVE_CELL,target_cell,v_gross,p_task);
 p_domain:=json_object_t();p_domain.put('temperature',thermal);
 if unit_snapshot is not null then p_domain.put('physical_units',json_array_t.parse(unit_snapshot));end if;
 p_domain.put('recovery_operation_id',p_receipt);p_domain.put('loss_operation_id',r.LOSS_OPERATION_ID);p_domain.put('plan_operation_id',plan.OPERATION_ID);
 p_domain.put('warehouse_id',r.WARE_ID);p_domain.put('uid',r.ROOT_UID);p_domain.put('article',r.ARTICLE);p_domain.put('from_cell',r.RECEIVE_CELL);
 p_domain.put('target_cell',target_cell);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(r.BASE_QTY));p_domain.put('base_uom',r.BASE_UOM);p_domain.put('stock_version',v_version);
 exception when no_data_found then raise_application_error(-20886,'RECOVERY_PLACEMENT_SOURCE_REQUIRED');end;
 procedure declare_rows(v json_object_t,r in out nocopy json_array_t)is begin
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECOVERY_RECEIPT',v.get_string('recovery_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_PLAN',v.get_string('plan_operation_id'));end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();task_id number;
 begin
 describe_current(d.get_object('source').get_string('recovery_operation_id'),d.get_string('actor'),null,v);
 select RRL_WAREHOUSE_TASK_SQ.nextval into task_id from dual;v.put('task_id',task_id);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 declare_rows(v,r);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_IW_RECOVERY_PUT_PLAN',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(task_id));
 RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('uid'),v.get_string('article'),v.get_string('from_cell'),v.get_string('target_cell'));
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');wire clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 task_id number;ware number;lot varchar2(200);sku varchar2(160);origin_cell varchar2(60);target_cell varchar2(60);uom varchar2(20);qty number;receipt_id varchar2(100);temp_id varchar2(100);lo number;hi number;
 begin
 select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(wire).get_object('domain');task_id:=v.get_number('task_id');
 receipt_id:=v.get_string('recovery_operation_id');describe_current(receipt_id,p_actor,null,fresh);fresh.put('task_id',task_id);
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'RECOVERY_PLACEMENT_PLAN_CHANGED');end if;
 ware:=v.get_number('warehouse_id');lot:=v.get_string('uid');sku:=v.get_string('article');origin_cell:=v.get_string('from_cell');target_cell:=v.get_string('target_cell');
 uom:=v.get_string('base_uom');qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));
 insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,SOURCE_DOC_ID,UID_PALLET,TARGET_ARTICUL,FROM_CELL,TO_CELL,FROM_WARE_ID,TO_WARE_ID,QTY,UNIT_CODE,QTY_MODE,STATUS,CREATED_BY)
 values(task_id,'PUTAWAY','MANUAL',task_id,'RECOVERY',task_id,lot,sku,origin_cell,target_cell,ware,ware,qty,uom,'PALLET','PLANNED',p_actor);
 temp_id:=v.get_object('temperature').get_string('decision_operation_id');lo:=v.get_object('temperature').get_number('task_temp_min');hi:=v.get_object('temperature').get_number('task_temp_max');
 insert into RRL_IW_RECOVERY_PUT_PLAN(OPERATION_ID,RECOVERY_OPERATION_ID,TASK_ID,TARGET_CELL,ACTOR,TEMP_DECISION_OPERATION_ID,TASK_TEMP_MIN,TASK_TEMP_MAX)
 values(op,receipt_id,task_id,target_cell,p_actor,temp_id,lo,hi);
 j.put('operation_id',op);j.put('task_id',task_id);j.put('recovery_operation_id',receipt_id);j.put('from_cell',origin_cell);j.put('to_cell',target_cell);
 j.put('quantity',v.get_string('quantity'));j.put('base_uom',uom);j.put('stock_changed',false);p_result:=j.to_clob;end;
 procedure plan_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t)is
 receipt_id varchar2(100);target_cell varchar2(60);v json_object_t;begin
 select RECOVERY_OPERATION_ID,TARGET_CELL into receipt_id,target_cell from RRL_IW_RECOVERY_PUT_PLAN where TASK_ID=p_task.TASK_ID;
 describe_current(receipt_id,p_actor,p_task.TASK_ID,v);
 if p_task.TASK_SOURCE!='MANUAL'or p_task.TASK_TYPE!='PUTAWAY'or p_task.SOURCE_DOC_TYPE!='RECOVERY'or p_task.SOURCE_DOC_ID!=p_task.TASK_ID
 or p_task.UID_PALLET!=v.get_string('uid')or p_task.FROM_CELL!=v.get_string('from_cell')or p_task.TO_CELL!=v.get_string('target_cell')
 or p_task.UNIT_CODE!=v.get_string('base_uom')or p_task.QTY!=RRL_STOCK_MATH.quantity(v.get_string('quantity'))or p_task.QTY_MODE!='PALLET'or target_cell!=p_task.TO_CELL
 then raise_application_error(-20886,'RECOVERY_ORIGINAL_TASK_REQUIRED');end if;
 declare_rows(v,p_resources);RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_IW_RECOVERY_PLACEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(p_task.TASK_ID));
 p_domain.put('recovery_placement',v);end;
 procedure validate_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_frozen json_object_t)is
 resources json_array_t:=json_array_t();domain json_object_t:=json_object_t();begin
 plan_task(p_task,p_actor,resources,domain);
 if dbms_lob.compare(p_frozen.to_clob,domain.get_object('recovery_placement').to_clob)!=0 then raise_application_error(-20886,'RECOVERY_TASK_SOURCE_CHANGED');end if;end;
 procedure complete_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_quantity number,p_target_uid varchar2,p_actor varchar2)is
 r RRL_INTERWARE_RECOVERY_RECEIPT%rowtype;receipt_id varchar2(100);op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');begin
 select RECOVERY_OPERATION_ID into receipt_id from RRL_IW_RECOVERY_PUT_PLAN where TASK_ID=p_task.TASK_ID;
 select *into r from RRL_INTERWARE_RECOVERY_RECEIPT where OPERATION_ID=receipt_id;
 if p_quantity!=r.BASE_QTY or p_target_uid!=r.ROOT_UID then raise_application_error(-20886,'RECOVERY_WHOLE_PLACEMENT_REQUIRED');end if;
 insert into RRL_IW_RECOVERY_PLACEMENT(TASK_ID,RECOVERY_OPERATION_ID,OPERATION_ID,ROOT_UID,WARE_ID,TARGET_CELL,BASE_QTY,BASE_UOM,ACTOR)
 values(p_task.TASK_ID,receipt_id,op,r.ROOT_UID,r.WARE_ID,p_task.TO_CELL,r.BASE_QTY,r.BASE_UOM,p_actor);end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_IW_RECOVERY_REC as 
 procedure assert_scope(p_approval varchar2,p_actor varchar2)is n number;begin 
 select count(*)into n from RRL_INTERWARE_RECOVERY_APPROVAL a join RRL_INTERWARE_RECOVERY_REQUEST req on req.OPERATION_ID=a.REQUEST_OPERATION_ID 
 join RUSERS u on u.ID=p_actor where a.OPERATION_ID=p_approval and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'interwarehouse_receive')=1 
 and(u.WARE_ID=req.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN'); 
 if n!=1 then raise_application_error(-20882,'INTERWARE_RECOVERY_CURRENT_RECEIVER_REQUIRED');end if; 
 end; 
 procedure describe(p_request clob,p_actor varchar2,p_domain out json_object_t)is 
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');approval_id varchar2(100):=d.get_object('source').get_string('approval_operation_id'); 
 approval RRL_INTERWARE_RECOVERY_APPROVAL%rowtype;req RRL_INTERWARE_RECOVERY_REQUEST%rowtype;receipt RRL_INTERWARE_RECEIPT%rowtype;source json_object_t;units clob;fresh_units clob; 
 n number;expected_count number;total number;qty number;target_uid varchar2(200);old_uid varchar2(200);source_cell varchar2(60);target_cell varchar2(60); 
 scan_article varchar2(160);scan_uom varchar2(20);ver number;scan_domain json_object_t;legs json_array_t;leg json_object_t;unit_count number;chosen_keys json_array_t;chosen_unit json_object_t; 
 begin 
 assert_scope(approval_id,p_actor); 
 select *into approval from RRL_INTERWARE_RECOVERY_APPROVAL where OPERATION_ID=approval_id; 
 select *into req from RRL_INTERWARE_RECOVERY_REQUEST where OPERATION_ID=approval.REQUEST_OPERATION_ID; 
 select count(*)into n from RRL_IW_RECOVERY_CANCEL where REQUEST_OPERATION_ID=req.OPERATION_ID;if n!=0 then raise_application_error(-20886,'RECOVERY_REQUEST_CANCELLED');end if;
 select *into receipt from RRL_INTERWARE_RECEIPT where OPERATION_ID=req.RECEIPT_OPERATION_ID; 
 select count(*)into n from RRL_STOCK_OPERATION where OPERATION_ID=approval_id and COMMAND_TYPE='INTERWARE_RECOVERY_APPROVE'and STATE='APPLIED'; 
 if n!=1 then raise_application_error(-20886,'INTERWARE_RECOVERY_APPLIED_APPROVAL_REQUIRED');end if; 
 select count(*)into n from RRL_INTERWARE_RECOVERY_RECEIPT where APPROVAL_OPERATION_ID=approval_id;if n!=0 then raise_application_error(-20886,'INTERWARE_RECOVERY_ALREADY_RECEIVED');end if; 
 source:=json_object_t.parse(approval.SOURCE_JSON);old_uid:=source.get_string('original_uid');source_cell:=source.get_string('source_cell');units:=source.get_array('source_units').to_clob;expected_count:=source.get_array('source_units').get_size; 
 qty:=RRL_STOCK_MATH.quantity(m.get_string('quantity'));target_uid:=m.get_string('receipt_pallet_identifier');target_cell:=m.get_string('scan_cell'); 
 if qty!=req.BASE_QTY or m.get_string('article')!=receipt.ARTICLE or m.get_string('base_uom')!=req.BASE_UOM 
 or m.get_string('scan_source_pallet')is null or m.get_string('scan_source_pallet')!=old_uid 
 or m.get_string('scan_pallet')is null or m.get_string('scan_pallet')!=target_uid then raise_application_error(-20886,'INTERWARE_RECOVERY_EXACT_APPROVED_SOURCE_SCANS_REQUIRED');end if; 
 select count(*)into n from RRL_CELLS where CELL=target_cell and WARE_ID=req.WARE_ID and nvl(BLOCKED_FOR_ACCEPT,0)=0 and BLOCKED_FOR_REMAINS=1 and BLOCKED_FOR_POPOLNENIE=1; 
 if n!=1 then raise_application_error(-20886,'INTERWARE_RECOVERY_RECEIVING_QUARANTINE_CELL_REQUIRED');end if; 
 RRL_STOCK_QC_ITEM.resolve_barcode(m.get_string('scan_article'),scan_article,scan_uom); 
 if scan_article!=receipt.ARTICLE then raise_application_error(-20886,'INTERWARE_RECOVERY_FOREIGN_ARTICLE_BARCODE');end if; 
 select max(POLICY_VERSION)into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=receipt.ARTICLE and INPUT_UOM=req.BASE_UOM and BASE_UOM=req.BASE_UOM and NUMERATOR=DENOMINATOR; 
 if ver is null then raise_application_error(-20886,'INTERWARE_RECOVERY_BASE_UOM_REQUIRED');end if; 
 select count(*)into n from RRL_REMAINS where UID_POLETA=old_uid and(REMAIN!=0 or HARD_RESERVED_BASE!=0); 
 if n!=0 then raise_application_error(-20886,'INTERWARE_RECOVERY_ORIGINAL_STOCK_ALREADY_PRESENT');end if; 
 if expected_count>10000 then raise_application_error(-20886,'INTERWARE_RECOVERY_UNIT_BOUND');end if; 
 if expected_count>0 then 
 select count(*),sum(u.BASE_QTY),json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob) 
 into n,total,fresh_units from json_table(units,'$[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom',V number path '$.version'))j 
 join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=j.K join RRL_INTERWARE_SHORTAGE_UNIT book on book.PHYSICAL_UNIT_KEY=j.K and book.FACT_OPERATION_ID=req.LOSS_OPERATION_ID 
 where u.CURRENT_UID=old_uid and u.CURRENT_CELL=source_cell and u.STOCK_STATUS='ISSUED'and u.HARD_RESERVATION_ID is null 
 and u.UNIT_VERSION=j.V and u.BASE_QTY=RRL_STOCK_MATH.quantity(j.Q)and u.BASE_UOM=j.B and u.BASE_UOM=req.BASE_UOM; 
 if n!=expected_count or total!=qty or dbms_lob.compare(units,fresh_units)!=0 then raise_application_error(-20886,'INTERWARE_RECOVERY_APPROVED_LOST_UNITS_CHANGED');end if; 
 elsif RRL_INTERWARE_MARK_SCAN.required_for_article(receipt.ARTICLE)=1 then raise_application_error(-20886,'INTERWARE_RECOVERY_MARKED_IDENTITY_REQUIRED');end if; 
 p_domain:=json_object_t();p_domain.put('approval_operation_id',approval_id);p_domain.put('request_operation_id',req.OPERATION_ID);p_domain.put('loss_operation_id',req.LOSS_OPERATION_ID); 
 p_domain.put('receipt_operation_id',receipt.OPERATION_ID);p_domain.put('plan_operation_id',receipt.PLAN_OPERATION_ID);p_domain.put('warehouse_id',req.WARE_ID); 
 p_domain.put('article',receipt.ARTICLE);p_domain.put('base_uom',req.BASE_UOM);p_domain.put('source_cell',source_cell);p_domain.put('receive_cell',target_cell);p_domain.put('uom_version',ver); 
 RRL_STOCK_INTERWARE_PART.describe_partial(m,old_uid,receipt.EXPECTED_BASE_QTY,req.BASE_UOM,receipt.ARTICLE,p_domain); 
 p_domain.put('source_units',json_array_t.parse(units));p_domain.put('recovery_receipt',true); 
 if expected_count>0 then 
  leg:=json_object_t();leg.put('article',receipt.ARTICLE);leg.put('uid',old_uid);leg.put('cell',source_cell);leg.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));leg.put('base_uom',req.BASE_UOM); 
  chosen_keys:=json_array_t();
  for selected_index in 0..source.get_array('source_units').get_size-1 loop
   chosen_unit:=treat(source.get_array('source_units').get(selected_index)as json_object_t);chosen_keys.append(chosen_unit.get_string('key'));
  end loop;
  leg.put('selected_unit_keys',chosen_keys);
  legs:=json_array_t();legs.append(leg);scan_domain:=json_object_t();scan_domain.put('legs',legs); 
  RRL_INTERWARE_MARK_SCAN.validate_scan(scan_domain.to_clob,m.to_clob,unit_count); 
  if unit_count!=expected_count then raise_application_error(-20886,'INTERWARE_RECOVERY_EXACT_PROFILE_SCANS_REQUIRED');end if; 
 elsif m.has('unit_scans')and m.get_array('unit_scans').get_size>0 then raise_application_error(-20886,'INTERWARE_RECOVERY_UNEXPECTED_UNIT_SCANS');end if; 
 exception when no_data_found then raise_application_error(-20886,'INTERWARE_RECOVERY_APPROVED_LOST_SOURCE_REQUIRED'); 
 end; 
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is 
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;u json_object_t; 
 begin 
 describe(p_request,d.get_string('actor'),v); 
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_SHORTAGE_FACT',v.get_string('loss_operation_id')); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECOVERY_APPROVAL',v.get_string('approval_operation_id')); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_INTERWARE_RECOVERY_RECEIPT',p_operation); 
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',v.get_string('uid')); 
 RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('uid'),v.get_string('article'),null,v.get_string('receive_cell')); 
 RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('original_root_uid'),v.get_string('article'),null,null); 
 RRL_STOCK_PLAN_HELPER.anchor(r,50,'STOCK',v.get_string('source_origin_uid')); 
 a:=v.get_array('source_units');for i in 0..a.get_size-1 loop u:=treat(a.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',u.get_string('key'));end loop; 
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','IW.RECOVERY.APPROVAL:'||v.get_string('approval_operation_id')); 
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256))); 
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob; 
 end; 
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is 
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');resolved clob;v json_object_t;fresh json_object_t;wire clob;units clob;j json_object_t; 
 uid_value varchar2(200);old_uid varchar2(200);cell_value varchar2(60);source_cell varchar2(60);article varchar2(160);uom varchar2(20);qty number;ware number;version_no number;event_id number; 
 approval_id varchar2(100);loss_id varchar2(100); 
 begin 
 select RESOLVED_PLAN_JSON into resolved from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(resolved).get_object('domain');describe(p_request,p_actor,fresh); 
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: recovery receiving');end if; 
 uid_value:=v.get_string('uid');old_uid:=v.get_string('original_root_uid');cell_value:=v.get_string('receive_cell');source_cell:=v.get_string('source_cell');article:=v.get_string('article'); 
 uom:=v.get_string('base_uom');qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));ware:=v.get_number('warehouse_id');version_no:=v.get_number('uom_version');approval_id:=v.get_string('approval_operation_id');loss_id:=v.get_string('loss_operation_id');wire:=v.to_clob;units:=v.get_array('source_units').to_clob; 
 RRL_STOCK_LOCATION_CORE.assert_receiving(cell_value,ware);RRL_STOCK_INTERWARE_PART.create_pallet(v,op); 
 RRL_STOCK_BALANCE_CORE.apply_delta(uid_value,cell_value,qty,0,uom,version_no,0); 
 RRL_STOCK_BALANCE_CORE.write_leg(uid_value,null,cell_value,qty,uom,version_no,1,1,1,p_actor,event_id); 
 insert into RRL_INTERWARE_RECOVERY_RECEIPT(OPERATION_ID,APPROVAL_OPERATION_ID,LOSS_OPERATION_ID,WARE_ID,ROOT_UID,RECEIVE_CELL,ARTICLE,BASE_QTY,BASE_UOM,STOCK_EVENT_ID,ACTOR,SOURCE_JSON) 
 values(op,approval_id,loss_id,ware,uid_value,cell_value,article,qty,uom,event_id,p_actor,wire); 
 insert into RRL_INTERWARE_RECOVERY_UNIT(PHYSICAL_UNIT_KEY,RECOVERY_OPERATION_ID,LOSS_OPERATION_ID,BASE_QTY,BASE_UOM,PREVIOUS_UNIT_VERSION) 
 select K,op,loss_id,RRL_STOCK_MATH.quantity(Q),B,V from json_table(units,'$[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom',V number path '$.version')); 
 if v.get_array('source_units').get_size>0 then RRL_STOCK_UNIT_CORE.receive_partial_issued(old_uid,source_cell,uid_value,cell_value,qty,units);end if; 
 j:=json_object_t();j.put('operation_id',op);j.put('approval_operation_id',approval_id);j.put('loss_operation_id',loss_id);j.put('status','RECOVERED_PENDING_PLACEMENT'); 
 j.put('pallet_identifier',uid_value);j.put('original_pallet_identifier',old_uid);j.put('warehouse_id',ware);j.put('quantity',v.get_string('quantity'));j.put('base_uom',uom);j.put('cell',cell_value); 
 j.put('physical_unit_count',v.get_array('source_units').get_size);j.put('event_id',event_id);j.put('stock_changed',true);j.put('historical_loss_preserved',true);j.put('customer_delivery_confirmed',false);j.put('regulatory_ack_verified',false);p_result:=j.to_clob; 
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values('IW.RECOVERY:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op,'AL32UTF8'),sys.dbms_crypto.hash_sh256)),'INTERWARE_SHORTAGE_RECOVERED',p_result); 
 end; 
end;
/


CREATE OR REPLACE package body RRL_STOCK_LOADING_READ as
 procedure assert_scope(p_identifier varchar2,p_actor varchar2)is n number;
 begin
  select count(*)into n from RRL_SBORKA_PALLETS s join RUSERS u on u.ID=p_actor
   where s.PALLET_UID=p_identifier and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'stock_posting_shipping')=1
    and(upper(trim(u.USER_GROUP))='GLOBAL_ADMIN'or u.WARE_ID=s.WARE_ID);
  if n!=1 then raise_application_error(-20882,'SINGLE_LOAD_CURRENT_WARE_ACTOR_REQUIRED');end if;
 end;
 procedure describe_source(p_identifier varchar2,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob,p_snapshot out clob) is
  d json_object_t:=json_object_t();src json_object_t:=json_object_t();v json_object_t;tree json_object_t;
 begin
  d.put('command_type','SHIP_PALLET');d.put('operation_id',p_operation);d.put('metadata',json_object_t());src.put('pallet_identifier',p_identifier);d.put('source',src);
  RRL_STOCK_SHIPPING_CORE.compile_shipment(d.to_clob,p_operation,p_policies,p_resources,p_domain,true);v:=json_object_t.parse(p_domain);
  if v.get_number('case_task') is not null then p_snapshot:=RRL_STOCK_HU_READ.case_snapshot_json(v.get_number('case_task'));
  elsif v.get_string('bound_physical_uid') is not null then p_snapshot:=RRL_STOCK_HU_READ.snapshot_json(v.get_string('bound_physical_uid'));
  else raise_application_error(-20886,'SINGLE_LOAD_PHYSICAL_BINDING_REQUIRED');end if;
  tree:=json_object_t.parse(p_snapshot);
  if tree.get_array('ancestors').get_size>0 then raise_application_error(-20886,'SINGLE_LOAD_REQUIRES_WHOLE_UPPER_HU');end if;
 end;
 function preview_json(p_identifier varchar2,p_actor varchar2 default null) return clob is
  p clob;r clob;d clob;s clob;j json_object_t:=json_object_t();tree json_object_t;
 begin
  if p_actor is not null then assert_scope(p_identifier,p_actor);end if;
  describe_source(p_identifier,'READ.LOADING',p,r,d,s);tree:=json_object_t.parse(s);
  j.put('shipment_identifier',p_identifier);j.put('composition_signature',RRL_STOCK_QC_GATE.signature_for_plan(d));
  j.put('root',tree.get_string('root'));j.put('expected_version',treat(tree.get_array('nodes').get(0) as json_object_t).get_number('version'));j.put('snapshot',tree);
  return j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_LOAD_BOX_CORE as
 procedure compile_boxes(p_snapshot clob,p_context clob,p_operation varchar2,p_gross number,r in out nocopy json_array_t,p_boxes out json_array_t) is
  tree json_object_t:=json_object_t.parse(p_snapshot);ctx json_object_t:=json_object_t.parse(p_context);nodes json_array_t:=tree.get_array('nodes');links json_array_t:=tree.get_array('links');observed json_array_t:=json_array_t();
  type node_map is table of json_object_t index by varchar2(200);by_uid node_map;
  type parent_map is table of varchar2(200) index by varchar2(200);parent_by_child parent_map;
  type number_map is table of number index by varchar2(200);leaf_count number_map;lower_by_box number_map;weight_by_box number_map;
  node_json json_object_t;x json_object_t;o json_object_t;item json_object_t;uid_text varchar2(200);owner_uid varchar2(200);cursor_uid varchar2(200);key_uid varchar2(200);box_count number:=0;v_mass number;outer_tare number:=0;measured_total number:=0;v_ref varchar2(100);v_scan varchar2(200);v_version number;manual_no number:=0;uncovered_no number:=0;unknown_case_no number:=0;coverage_no number:=1;proof json_object_t;required_complete boolean:=false;
  function closest_box(p_uid varchar2) return varchar2 is current_uid varchar2(200):=p_uid;n number:=0;candidate json_object_t;
  begin
   loop
    n:=n+1;if n>17 then raise_application_error(-20886,'LOAD_BOX_PARENT_DEPTH_INVALID');end if;
    if not by_uid.exists(current_uid) then raise_application_error(-20886,'LOAD_BOX_PARENT_UNKNOWN');end if;
    candidate:=by_uid(current_uid);
    if(candidate.get_string('kind')='CONTAINER'and candidate.get_string('type')='BOX')or(candidate.get_string('kind')='CASE'and candidate.has('scale_qc'))then return current_uid;end if;
    if not parent_by_child.exists(current_uid) then return null;end if;current_uid:=parent_by_child(current_uid);
   end loop;
  end;
 begin
  p_boxes:=json_array_t();
  if ctx.has('require_complete_box_mass')then required_complete:=ctx.get_boolean('require_complete_box_mass');end if;
  if ctx.has('physical_boxes')and not ctx.get('physical_boxes').is_null then
   if not ctx.get('physical_boxes').is_array then raise_application_error(-20886,'LOAD_PHYSICAL_BOX_ARRAY_REQUIRED');end if;
   observed:=ctx.get_array('physical_boxes');manual_no:=observed.get_size;
  end if;
  if observed.get_size>200 or nodes.get_size>200 then raise_application_error(-20881,'LOAD_PHYSICAL_BOX_BOUND_200');end if;
  for i in 0..nodes.get_size-1 loop
   node_json:=treat(nodes.get(i)as json_object_t);uid_text:=node_json.get_string('uid');by_uid(uid_text):=node_json;
   if node_json.get_string('kind')='CASE'then
    if node_json.has('scale_qc')then
     for k in 0..manual_no-1 loop
      if treat(observed.get(k)as json_object_t).get_string('box_uid')=uid_text then raise_application_error(-20886,'LOAD_CASE_BOX_SERVER_SOURCE_REQUIRED');end if;
     end loop;
     proof:=node_json.get_object('scale_qc');o:=json_object_t();
     o.put('box_uid',uid_text);o.put('content_version',node_json.get_number('version'));o.put('scan_box',node_json.get_string('sscc'));
     o.put('gross_weight_kg',proof.get_string('gross_weight_kg'));o.put('origin','WAREHOUSE_SCALE_QC');o.put('measurement_ref',proof.get_string('measurement_ref'));
     o.put('case_task_id',proof.get_number('case_task_id'));o.put('final_scale_capture',proof.get_string('capture_key'));o.put('warehouse_qc_operation',proof.get_string('qc_operation_id'));
     o.put('tare_weight_kg',proof.get_string('tare_weight_kg'));o.put('net_weight_kg',proof.get_string('net_weight_kg'));o.put('device_mode',proof.get_string('device_mode'));
     o.put('composition_signature',proof.get_string('composition_signature'));o.put('signature_version',proof.get_number('signature_version'));o.put('measured_content_version',proof.get_number('measured_content_version'));
     observed.append(o);
    else unknown_case_no:=unknown_case_no+1;end if;
   end if;
  end loop;
  if observed.get_size=0 then return;end if;
  if observed.get_size>200 then raise_application_error(-20881,'LOAD_PHYSICAL_BOX_BOUND_200');end if;
  if unknown_case_no>0 and(required_complete or manual_no>0)then raise_application_error(-20886,'LOAD_BOX_MANIFEST_CASE_FLOW_REQUIRED');end if;
  for i in 0..links.get_size-1 loop x:=treat(links.get(i) as json_object_t);parent_by_child(x.get_string('child')):=x.get_string('parent');end loop;
  for i in 0..nodes.get_size-1 loop
   node_json:=treat(nodes.get(i) as json_object_t);uid_text:=node_json.get_string('uid');owner_uid:=closest_box(uid_text);
   if node_json.get_string('kind')='STOCK' then
    if owner_uid is null then
     uncovered_no:=uncovered_no+1;if required_complete or manual_no>0 then raise_application_error(-20886,'LOAD_PHYSICAL_BOX_COMPLETE_LEAF_COVERAGE_REQUIRED');end if;continue;end if;
    if not leaf_count.exists(owner_uid) then leaf_count(owner_uid):=0;lower_by_box(owner_uid):=0;end if;leaf_count(owner_uid):=leaf_count(owner_uid)+1;
   end if;
  end loop;
  for i in 0..nodes.get_size-1 loop
   node_json:=treat(nodes.get(i) as json_object_t);uid_text:=node_json.get_string('uid');owner_uid:=closest_box(uid_text);
   v_mass:=nvl(node_json.get_number('tare_weight_kg'),0);
   if node_json.get_string('kind')='STOCK' and node_json.get_string('base_uom')='KG' then v_mass:=v_mass+RRL_STOCK_MATH.quantity(node_json.get_string('quantity'));end if;
   if owner_uid is not null and leaf_count.exists(owner_uid) then lower_by_box(owner_uid):=lower_by_box(owner_uid)+v_mass;else outer_tare:=outer_tare+v_mass;end if;
  end loop;
  coverage_no:=case when uncovered_no=0 and unknown_case_no=0 then 1 else 0 end;
  key_uid:=leaf_count.first;while key_uid is not null loop
   box_count:=box_count+1;cursor_uid:=key_uid;
   while parent_by_child.exists(cursor_uid) loop cursor_uid:=parent_by_child(cursor_uid);if leaf_count.exists(cursor_uid) then raise_application_error(-20886,'LOAD_PHYSICAL_BOX_NESTED_COUNT_CONFLICT');end if;end loop;
   key_uid:=leaf_count.next(key_uid);
  end loop;
  if box_count!=observed.get_size then raise_application_error(-20886,'LOAD_PHYSICAL_BOX_EXACT_COVERAGE_REQUIRED');end if;
  for i in 0..observed.get_size-1 loop
   o:=treat(observed.get(i) as json_object_t);uid_text:=o.get_string('box_uid');
   if uid_text is null or not leaf_count.exists(uid_text) or weight_by_box.exists(uid_text) then raise_application_error(-20886,'LOAD_PHYSICAL_BOX_FOREIGN_OR_DUPLICATE');end if;
   node_json:=by_uid(uid_text);v_scan:=o.get_string('scan_box');v_ref:=o.get_string('measurement_ref');v_version:=o.get_number('content_version');
   if o.get_string('origin') is null or o.get_string('origin')not in('MANUAL_CONFIRMED','WAREHOUSE_SCALE_QC') or trim(v_ref) is null or v_version is null or v_version!=node_json.get_number('version') or v_scan is null
     or(v_scan!=uid_text and(node_json.get_string('sscc') is null or v_scan!=node_json.get_string('sscc'))) then raise_application_error(-20886,'LOAD_PHYSICAL_BOX_CURRENT_MEASUREMENT_SCAN_REQUIRED');end if;
   v_mass:=RRL_STOCK_MATH.quantity(o.get_string('gross_weight_kg'));if v_mass<lower_by_box(uid_text) then raise_application_error(-20886,'LOAD_BOX_GROSS_BELOW_NET_AND_TARE');end if;
   weight_by_box(uid_text):=v_mass;measured_total:=measured_total+v_mass;
   item:=json_object_t();item.put('box_uid',uid_text);item.put('content_version',v_version);item.put('gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_mass));item.put('origin',o.get_string('origin'));item.put('coverage_complete',coverage_no);item.put('measurement_ref',v_ref);item.put('scan_box',v_scan);
   if node_json.get_string('kind')='CASE'then
    if o.get_string('origin')!='WAREHOUSE_SCALE_QC' or not node_json.has('scale_qc')then raise_application_error(-20886,'LOAD_CASE_BOX_CURRENT_QC_SOURCE_REQUIRED');end if;
    for field_no in 1..9 loop
     case field_no
      when 1 then item.put('case_task_id',o.get_number('case_task_id'));
      when 2 then item.put('final_scale_capture',o.get_string('final_scale_capture'));
      when 3 then item.put('warehouse_qc_operation',o.get_string('warehouse_qc_operation'));
      when 4 then item.put('tare_weight_kg',o.get_string('tare_weight_kg'));
      when 5 then item.put('net_weight_kg',o.get_string('net_weight_kg'));
      when 6 then item.put('device_mode',o.get_string('device_mode'));
      when 7 then item.put('composition_signature',o.get_string('composition_signature'));
      when 8 then item.put('signature_version',o.get_number('signature_version'));
      when 9 then item.put('measured_content_version',o.get_number('measured_content_version'));
     end case;
    end loop;
   elsif o.get_string('origin')!='MANUAL_CONFIRMED'then raise_application_error(-20886,'LOAD_ORDINARY_BOX_MANUAL_SOURCE_REQUIRED');end if;
   p_boxes.append(item);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_LOAD_BOX_WEIGHT',p_operation||':'||uid_text);
  end loop;
  if p_gross<measured_total+outer_tare then raise_application_error(-20886,'LOAD_GROSS_BELOW_MEASURED_BOXES_AND_OUTER_TARE');end if;
 end;
 procedure assert_policy(p_destinations clob,p_boxes json_array_t) is v_count number;
 begin
  select count(*) into v_count from RRL_STORE_RECEIPT_POLICY policy
   where policy.RECEIPT_MODE='WEIGHT_PHOTO' and policy.STORE_ADDR in(select ADDR_TEXT from json_table(p_destinations,'$[*]' columns(ADDR_TEXT varchar2(255) path '$.address')));
  if v_count>0 and p_boxes.get_size=0 then raise_application_error(-20886,'LOAD_STORE_WEIGHT_REQUIRES_PHYSICAL_BOX_MASSES');end if;
  if v_count>0 then
   for i in 0..p_boxes.get_size-1 loop
    if nvl(treat(p_boxes.get(i)as json_object_t).get_number('coverage_complete'),1)!=1 then raise_application_error(-20886,'LOAD_STORE_WEIGHT_REQUIRES_COMPLETE_BOX_MASSES');end if;
   end loop;
  end if;
 end;

 procedure persist_boxes(p_operation varchar2,p_boxes json_array_t,p_actor varchar2)is
  x json_object_t;uid_value varchar2(200);version_value number;gross_value number;ref_value varchar2(100);scan_value varchar2(200);origin_value varchar2(20);
  case_value number;capture_value varchar2(64);qc_value varchar2(100);tare_value number;net_value number;mode_value varchar2(10);sig_value varchar2(64);sig_version number;measured_version number;coverage_value number;
 begin
  for i in 0..p_boxes.get_size-1 loop
   x:=treat(p_boxes.get(i)as json_object_t);uid_value:=x.get_string('box_uid');version_value:=x.get_number('content_version');
   gross_value:=RRL_STOCK_MATH.quantity(x.get_string('gross_weight_kg'));ref_value:=x.get_string('measurement_ref');scan_value:=x.get_string('scan_box');origin_value:=x.get_string('origin');
   case_value:=x.get_number('case_task_id');capture_value:=x.get_string('final_scale_capture');qc_value:=x.get_string('warehouse_qc_operation');
   tare_value:=null;net_value:=null;mode_value:=null;sig_value:=null;sig_version:=null;measured_version:=null;coverage_value:=nvl(x.get_number('coverage_complete'),1);
   if origin_value='WAREHOUSE_SCALE_QC'then
    tare_value:=RRL_STOCK_MATH.quantity(x.get_string('tare_weight_kg'));net_value:=RRL_STOCK_MATH.quantity(x.get_string('net_weight_kg'));
    mode_value:=x.get_string('device_mode');sig_value:=x.get_string('composition_signature');sig_version:=x.get_number('signature_version');measured_version:=x.get_number('measured_content_version');
   end if;
   insert into RRL_TT_LOAD_BOX_WEIGHT(LOAD_OPERATION_ID,BOX_UID,BOX_CONTENT_VERSION,GROSS_WEIGHT_KG,MEASUREMENT_ORIGIN,MEASUREMENT_REF,SCAN_IDENTIFIER,RECORDED_BY,
    CASE_BOX_TASK_ID,FINAL_SCALE_CAPTURE,WAREHOUSE_QC_OPERATION,TARE_WEIGHT_KG,NET_WEIGHT_KG,DEVICE_MODE,COMPOSITION_SIGNATURE,SIGNATURE_VERSION,MEASURED_CONTENT_VERSION,COVERAGE_COMPLETE)
   values(p_operation,uid_value,version_value,gross_value,origin_value,ref_value,scan_value,p_actor,
    case_value,capture_value,qc_value,tare_value,net_value,mode_value,sig_value,sig_version,measured_version,coverage_value);
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_LOAD_FLOOR as
 g_writing boolean:=false;g_operation varchar2(100);g_tx varchar2(100);
 function current_matrix(p_vehicle number)return json_object_t is
  profile_value json_object_t:=json_object_t.parse(RRL_VEHICLE_PROFILE_API.describe_profile(p_vehicle));configured json_object_t;
 begin
  if not profile_value.has('profile')then return null;end if;
  configured:=profile_value.get_object('profile');
  if not configured.has('floor_capacity')then return null;end if;
  if profile_value.get_string('state')!='READY'then raise_application_error(-20886,'LOAD_FLOOR_CURRENT_PROFILE_REQUIRED');end if;
  return profile_value;
 end;
 function compile_load(p_snapshot clob,p_vehicle number,p_rows in out nocopy json_array_t)return json_object_t is
  profile_value json_object_t:=current_matrix(p_vehicle);tree json_object_t;node_value json_object_t;nodes json_array_t;
  result json_object_t:=json_object_t();type_no number;case_no number;n number;book_id varchar2(100);
  root_id varchar2(200);ware_no number;type_version number;origin_value varchar2(24);reference_value varchar2(200);
 begin
  if profile_value is null then return null;end if;
  tree:=json_object_t.parse(p_snapshot);root_id:=tree.get_string('root');ware_no:=tree.get_number('warehouse');
  nodes:=tree.get_array('nodes');
  if nodes.get_size<1 or nodes.get_size>200 then raise_application_error(-20886,'LOAD_FLOOR_TOP_SOURCE_REQUIRED');end if;
  node_value:=treat(nodes.get(0) as json_object_t);
  if node_value.get_number('depth')!=0 or node_value.get_string('uid')!=root_id then raise_application_error(-20886,'LOAD_FLOOR_SINGLE_TOP_REQUIRED');end if;
  if node_value.get_string('kind')='CASE'then
   case_no:=node_value.get_number('case_task_id');
   select PALLET_TYPE_ID into type_no from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=case_no and WARE_ID=ware_no and STATUS!='CANCELLED';
   if type_no is null then raise_application_error(-20886,'LOAD_FLOOR_CASE_TYPE_REQUIRED');end if;
   RRL_STOCK_PLAN_HELPER.row_key(p_rows,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(case_no));
   origin_value:='CASE_TYPE';reference_value:=RRL_STOCK_PLAN_HELPER.decimal_text(case_no);
  elsif node_value.get_string('kind')='CONTAINER'then
   select count(*),min(PALLET_TYPE_ID),min(OPERATION_ID)into n,type_no,book_id from RRL_TARE_BOOK
    where PLACE_KIND='HU'and PLACE_ID=root_id and OWNER_WARE_ID=ware_no and STATUS='HELD';
   if n!=1 then raise_application_error(-20886,'LOAD_FLOOR_SINGLE_HELD_HU_TARE_REQUIRED');end if;
   RRL_STOCK_PLAN_HELPER.row_key(p_rows,'RRL_TARE_BOOK',book_id);
   origin_value:='HELD_HU_TARE_BOOK';reference_value:=book_id;
  elsif node_value.get_string('kind')='STOCK'then
   select PALLET_TYPE_ID,TYPE_VERSION,LAST_OPERATION_ID into type_no,type_version,reference_value
    from RRL_PALLET_FLOOR_TYPE where UID_PALLET=root_id;
   RRL_STOCK_PLAN_HELPER.row_key(p_rows,'RRL_PALLET_FLOOR_TYPE',root_id);
   origin_value:='ROOT_STOCK_TYPE';
  else raise_application_error(-20886,'LOAD_FLOOR_CONFIRMED_TOP_TYPE_REQUIRED');end if;
  select count(*)into n from RRL_PALLET_TYPE where PALLET_TYPE_ID=type_no and ACTIVE=1;
  if n!=1 then raise_application_error(-20886,'LOAD_FLOOR_ACTIVE_TOP_TYPE_REQUIRED');end if;
  result.put('vehicle_id',p_vehicle);result.put('profile_version',profile_value.get_number('version'));
  result.put('profile_base_hash',profile_value.get_string('base_hash'));result.put('pallet_type_id',type_no);
  result.put('type_origin',origin_value);result.put('source_reference',reference_value);
  if type_version is not null then result.put('type_version',type_version);end if;
  result.put('root',root_id);result.put('warehouse',ware_no);result.put('top_place_count',1);
  return result;
 exception when no_data_found then raise_application_error(-20886,'LOAD_FLOOR_CURRENT_TOP_SOURCE_REQUIRED');
 end;
 function checked_trip(p_trip number,p_vehicle number,p_extra_type number default null)return clob is
  profile_value json_object_t:=current_matrix(p_vehicle);counts json_array_t:=json_array_t();entry_value json_object_t;result json_object_t;
  type count_map is table of number index by varchar2(100);type_counts count_map;key_value varchar2(100);unknown_no number:=0;load_count number:=0;
 begin
  if profile_value is null then return null;end if;
  for item in(select l.LOAD_OPERATION_ID,l.VEHICLE_ID,l.VEHICLE_NUMBER,f.PALLET_TYPE_ID,f.VEHICLE_ID FLOOR_VEHICLE,o.STATE
   from RRL_TT_HU_LOAD_FACT l left join RRL_TT_LOAD_FLOOR_FACT f on f.LOAD_OPERATION_ID=l.LOAD_OPERATION_ID
   left join RRL_STOCK_OPERATION o on o.OPERATION_ID=l.LOAD_OPERATION_ID
   where l.TT_ID=p_trip and l.STATUS='LOADED'order by l.LOAD_OPERATION_ID fetch first 201 rows only)loop
   load_count:=load_count+1;
   if load_count>200 then raise_application_error(-20881,'LOAD_FLOOR_PLACES_BOUND_200');end if;
   if item.VEHICLE_ID!=p_vehicle or item.STATE is null or item.STATE!='APPLIED'then raise_application_error(-20886,'LOAD_FLOOR_CURRENT_LOAD_PROOF_REQUIRED');end if;
   if item.PALLET_TYPE_ID is null or item.FLOOR_VEHICLE!=p_vehicle then unknown_no:=unknown_no+1;
   else
    key_value:=to_char(item.PALLET_TYPE_ID,'TM9');
    if type_counts.exists(key_value)then type_counts(key_value):=type_counts(key_value)+1;else type_counts(key_value):=1;end if;
   end if;
  end loop;
  if p_extra_type is not null then
   key_value:=to_char(p_extra_type,'TM9');
   if type_counts.exists(key_value)then type_counts(key_value):=type_counts(key_value)+1;else type_counts(key_value):=1;end if;
  end if;
  key_value:=type_counts.first;
  while key_value is not null loop
   entry_value:=json_object_t();entry_value.put('pallet_type_id',to_number(key_value));entry_value.put('places',type_counts(key_value));counts.append(entry_value);
   key_value:=type_counts.next(key_value);
  end loop;
  result:=json_object_t.parse(RRL_VEHICLE_PROFILE_API.check_floor_capacity(p_vehicle,counts.to_clob,unknown_no));
  if result.get_string('status')!='COMPATIBLE'then raise_application_error(-20886,'LOAD_FLOOR_PHYSICAL_VARIANT_NOT_CONFIRMED');end if;
  result.put('loaded_top_places',load_count);result.put('prospective_top_places',load_count+case when p_extra_type is null then 0 else 1 end);
  result.put('profile_base_hash',profile_value.get_string('base_hash'));
  return result.to_clob;
 end;
 function planning_counts(p_vehicle number,p_sts clob,p_base_counts clob,p_unknown number)return clob is
  numbers json_array_t:=json_array_t.parse(p_sts);base_counts json_array_t:=json_array_t.parse(p_base_counts);wire_counts json_array_t:=json_array_t();
  entry_value json_object_t;result json_object_t:=json_object_t();el json_element_t;
  query_value varchar2(32767);cursor_no integer;ran integer;rc sys_refcursor;load_id varchar2(100);type_id number;vehicle_id number;floor_vehicle number;
  unknown_no number:=p_unknown;load_count number:=0;st_value varchar2(100);key_value varchar2(100);
  type count_map is table of number index by varchar2(100);counts count_map;
 begin
  if numbers.get_size<1 or numbers.get_size>200 or base_counts.get_size>200 then raise_application_error(-20881,'PLAN_FLOOR_SOURCE_BOUND_200');end if;
  for i in 0..base_counts.get_size-1 loop
   entry_value:=treat(base_counts.get(i) as json_object_t);key_value:=to_char(entry_value.get_number('pallet_type_id'),'TM9');
   counts(key_value):=entry_value.get_number('places');
  end loop;
  query_value:='select /* PLAN_LOADED_TOP_BOUND1197 */ l.LOAD_OPERATION_ID,f.PALLET_TYPE_ID,l.VEHICLE_ID,f.VEHICLE_ID from RRL_TT_HU_LOAD_FACT l left join RRL_TT_LOAD_FLOOR_FACT f on f.LOAD_OPERATION_ID=l.LOAD_OPERATION_ID where l.STATUS=''LOADED''and l.LOAD_OPERATION_ID in(select m.LOAD_OPERATION_ID from RRL_TT_HU_LOAD_ST m join RRL_SBORKA_PALLETS p on p.ID=m.SBORKA_PALLET_ID where m.ACTIVE_FLAG=1 and p.ST_NUMBER in(';
  for i in 0..numbers.get_size-1 loop
   if i>0 then query_value:=query_value||',';end if;query_value:=query_value||':st'||to_char(i,'FM999');
  end loop;
  query_value:=query_value||'))order by l.LOAD_OPERATION_ID fetch first 201 rows only';
  cursor_no:=dbms_sql.open_cursor;dbms_sql.parse(cursor_no,query_value,dbms_sql.native);
  for i in 0..numbers.get_size-1 loop
   el:=numbers.get(i);
   if not el.is_string then raise_application_error(-20886,'PLAN_FLOOR_ST_REQUIRED');end if;
   st_value:=numbers.get_string(i);
   if st_value is null then raise_application_error(-20886,'PLAN_FLOOR_ST_REQUIRED');end if;
   dbms_sql.bind_variable(cursor_no,':st'||to_char(i,'FM999'),st_value);
  end loop;
  ran:=dbms_sql.execute(cursor_no);rc:=dbms_sql.to_refcursor(cursor_no);cursor_no:=null;
  loop
   fetch rc into load_id,type_id,vehicle_id,floor_vehicle;exit when rc%notfound;
   load_count:=load_count+1;
   if load_count>200 then raise_application_error(-20881,'PLAN_FLOOR_LOADED_BOUND_200');end if;
   if vehicle_id!=p_vehicle then raise_application_error(-20886,'PLAN_FLOOR_LOADED_VEHICLE_CONFLICT');end if;
   if type_id is null or floor_vehicle!=p_vehicle then unknown_no:=unknown_no+1;
   else
    key_value:=to_char(type_id,'TM9');
    if counts.exists(key_value)then counts(key_value):=counts(key_value)+1;else counts(key_value):=1;end if;
   end if;
  end loop;close rc;
  key_value:=counts.first;
  while key_value is not null loop
   entry_value:=json_object_t();entry_value.put('pallet_type_id',to_number(key_value));entry_value.put('places',counts(key_value));wire_counts.append(entry_value);
   key_value:=counts.next(key_value);
  end loop;
  result.put('counts',wire_counts);result.put('unconfirmed_places',unknown_no);return result.to_clob;
 exception when others then
  if cursor_no is not null then if dbms_sql.is_open(cursor_no)then dbms_sql.close_cursor(cursor_no);end if;end if;
  if rc%isopen then close rc;end if;raise;
 end;
 procedure assert_load(p_vehicle number,p_trip number,p_frozen clob)is
  rows_value json_array_t:=json_array_t();current_value json_object_t;current_wire clob;n number;capacity_wire clob;frozen json_object_t;tree json_object_t:=json_object_t();node_value json_object_t:=json_object_t();nodes json_array_t:=json_array_t();
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(p_vehicle)));
  if p_frozen is null then
   current_value:=current_matrix(p_vehicle);
   if current_value is not null then raise_application_error(-20890,'CLOSURE_CHANGED: new load floor profile');end if;
   return;
  end if;
  frozen:=json_object_t.parse(p_frozen);tree.put('root',frozen.get_string('root'));tree.put('warehouse',frozen.get_number('warehouse'));
  node_value.put('uid',frozen.get_string('root'));node_value.put('depth',0);
  if frozen.get_string('type_origin')='CASE_TYPE'then
   node_value.put('kind','CASE');node_value.put('case_task_id',to_number(frozen.get_string('source_reference')));
  elsif frozen.get_string('type_origin')='ROOT_STOCK_TYPE'then node_value.put('kind','STOCK');
  else node_value.put('kind','CONTAINER');end if;
  nodes.append(node_value);tree.put('nodes',nodes);
  current_value:=compile_load(tree.to_clob,p_vehicle,rows_value);
  if p_frozen is null and current_value is null then return;end if;
  if p_frozen is null or current_value is null then raise_application_error(-20890,'CLOSURE_CHANGED: load floor profile');end if;
  current_wire:=current_value.to_clob;select count(*)into n from dual where json_equal(p_frozen,current_wire);
  if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: load top type/profile');end if;
  capacity_wire:=checked_trip(p_trip,p_vehicle,current_value.get_number('pallet_type_id'));
 end;
 procedure assert_departure(p_trip number,p_vehicle number,p_frozen clob)is current_wire clob;n number;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(p_vehicle)));
  current_wire:=checked_trip(p_trip,p_vehicle);
  if p_frozen is null and current_wire is null then return;end if;
  if p_frozen is null or current_wire is null then raise_application_error(-20890,'CLOSURE_CHANGED: depart floor profile');end if;
  select count(*)into n from dual where json_equal(p_frozen,current_wire);
  if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: depart floor cargo/profile');end if;
 end;
 procedure assert_writing(p_operation varchar2)is
 begin
  if not g_writing or g_operation is null or g_operation!=p_operation or g_tx is null
   or g_tx!=dbms_transaction.local_transaction_id(false)
   or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null
   or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=p_operation then raise_application_error(-20863,'LOAD_FLOOR_ROOT_OWNER_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TT_HU_LOAD_FACT',p_operation));
 end;
 procedure persist_confirmation(p_operation varchar2,p_domain clob,p_actor varchar2)is
  d json_object_t;vehicle_no number;version_no number;type_no number;origin_value varchar2(24);reference_value varchar2(200);n number;
 begin
  if p_domain is null then return;end if;
  d:=json_object_t.parse(p_domain);vehicle_no:=d.get_number('vehicle_id');version_no:=d.get_number('profile_version');
  type_no:=d.get_number('pallet_type_id');origin_value:=d.get_string('type_origin');reference_value:=d.get_string('source_reference');
  select count(*)into n from RRL_TT_HU_LOAD_FACT l join RRL_STOCK_OPERATION o on o.OPERATION_ID=l.LOAD_OPERATION_ID
   where l.LOAD_OPERATION_ID=p_operation and l.VEHICLE_ID=vehicle_no and l.LOADED_BY=p_actor and l.STATUS='LOADED'and o.STATE='IN_FLIGHT';
  if n!=1 then raise_application_error(-20863,'LOAD_FLOOR_CURRENT_FACT_REQUIRED');end if;
  g_writing:=true;g_operation:=p_operation;g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_TT_LOAD_FLOOR_FACT(LOAD_OPERATION_ID,VEHICLE_ID,PROFILE_VERSION,PALLET_TYPE_ID,TYPE_ORIGIN,SOURCE_REFERENCE,ACTOR,CONFIRMATION_JSON)
   values(p_operation,vehicle_no,version_no,type_no,origin_value,reference_value,p_actor,p_domain);
  g_writing:=false;g_operation:=null;g_tx:=null;
 exception when others then g_writing:=false;g_operation:=null;g_tx:=null;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_LOAD_RECONCILE_CMD as
 function digest(s clob) return varchar2 is begin return rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256));end;
 procedure read_history(p_original varchar2,p_tree out json_object_t,p_shipments out json_array_t) is
  result clob;plan clob;original_kind varchar2(80);original_state varchar2(20);j json_object_t;domain_json json_object_t;n number;
 begin
  select COMMAND_TYPE,STATE,RESULT_JSON,RESOLVED_PLAN_JSON into original_kind,original_state,result,plan from RRL_STOCK_OPERATION where OPERATION_ID=p_original;
  if original_kind!='HU_SHIP' or original_state!='APPLIED' then raise_application_error(-20886,'RECONCILE_APPLIED_WHOLE_HU_SHIPMENT_REQUIRED');end if;
  j:=json_object_t.parse(result);domain_json:=json_object_t.parse(plan).get_object('domain');
  if j.has('physical_load') and not j.get('physical_load').is_null then raise_application_error(-20886,'RECONCILE_ALREADY_HAS_PHYSICAL_LOAD');end if;
  p_tree:=j.get_object('composition_at_departure');p_shipments:=domain_json.get_array('shipments');
  if p_tree.get_array('nodes').get_size<2 or p_tree.get_array('nodes').get_size>200 or p_shipments.get_size=0 or p_shipments.get_size>200
   or p_tree.get_array('ancestors').get_size!=0 then raise_application_error(-20886,'RECONCILE_WHOLE_HU_HISTORY_REQUIRED');end if;
  select count(*) into n from RRL_TT_LOAD_RECONCILE where SHIPPING_OPERATION_ID=p_original;
  if n>0 then raise_application_error(-20886,'RECONCILE_ORIGINAL_ALREADY_LINKED');end if;
 exception when no_data_found then raise_application_error(-20886,'RECONCILE_ORIGINAL_SHIPMENT_NOT_FOUND');
 end;
 procedure assert_departed(p_tree json_object_t,p_shipments json_array_t,p_original varchar2) is
  nodes json_array_t:=p_tree.get_array('nodes');links json_array_t:=p_tree.get_array('links');x json_object_t;
  uid_text varchar2(200);case_no number;node_version number;kind_text varchar2(20);n number;st_no number;original_plan clob;epochs clob;expected_epoch number;actual_epoch number;
 begin
  select RESOLVED_PLAN_JSON into original_plan from RRL_STOCK_OPERATION where OPERATION_ID=p_original;
  epochs:=json_object_t.parse(original_plan).get_array('physical_before').to_clob;
  for i in 0..nodes.get_size-1 loop
   x:=treat(nodes.get(i) as json_object_t);uid_text:=x.get_string('uid');kind_text:=x.get_string('kind');node_version:=x.get_number('version');
   if kind_text='CONTAINER' then
    select count(*) into n from RRL_PALLETS where UID_PALLET=uid_text and HU_SHIPPED_OPERATION=p_original and HU_CURRENT_CELL is null and HU_CONTENT_VERSION=node_version+1;
    if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: reconciled container departure');end if;
   elsif kind_text='CASE' then
    case_no:=x.get_number('case_task_id');
    select count(*) into n from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=case_no and STATUS='SHIPPED' and SHIPPED_OPERATION=p_original;
    if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: reconciled CASE shipment');end if;
   elsif kind_text!='STOCK' then raise_application_error(-20886,'RECONCILE_NODE_KIND_UNSUPPORTED');end if;
   if kind_text='STOCK' then
    select VERSION_NO into expected_epoch from json_table(epochs,'$[*]' columns(UID_TEXT varchar2(200) path '$.uid',VERSION_NO number path '$.version')) where UID_TEXT=uid_text;
    select STOCK_COMPOSITION_VERSION into actual_epoch from RRL_PALLETS where UID_PALLET=uid_text;
    if actual_epoch!=expected_epoch+1 then raise_application_error(-20890,'CLOSURE_CHANGED: reconciled stock composition epoch');end if;
    select count(*) into n from RRL_REMAINS where UID_POLETA=uid_text and (REMAIN!=0 or HARD_RESERVED_BASE!=0);
    if n>0 then raise_application_error(-20890,'CLOSURE_CHANGED: reconciled stock returned or reused');end if;
    select count(*) into n from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=uid_text and STOCK_STATUS!='ISSUED';
    if n>0 then raise_application_error(-20890,'CLOSURE_CHANGED: reconciled physical units returned');end if;
   end if;
  end loop;
  for i in 0..links.get_size-1 loop
   x:=treat(links.get(i) as json_object_t);case_no:=x.get_number('id');node_version:=x.get_number('version');
   if case_no is not null then
    select count(*) into n from RRL_WMS_HU_LINK where HU_LINK_ID=case_no and ACTIVE_FLAG=0 and UNLINKED_OPERATION_ID=p_original;
    if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: reconciled departure link');end if;
   end if;
  end loop;
  for i in 0..p_shipments.get_size-1 loop
   x:=treat(p_shipments.get(i) as json_object_t).get_object('domain');st_no:=x.get_number('document_id');
   select count(*) into n from RRL_SBORKA_PALLETS where ID=st_no and CONDITION=2;
   if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: reconciled ST status');end if;
   if x.get_number('case_task') is null then
    select count(*) into n from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=st_no and STATUS='SHIPPED' and SHIPPED_OPERATION_ID=p_original;
    if n=0 then raise_application_error(-20886,'RECONCILE_PHYSICAL_OWNER_PROOF_REQUIRED');end if;
   end if;
  end loop;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');original_op varchar2(100):=d.get_object('source').get_string('shipping_operation_id');
  tree json_object_t;ships json_array_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();nodes json_array_t;links json_array_t;x json_object_t;loading json_object_t;v json_object_t:=json_object_t();uid_text varchar2(200);case_no number;st_no number;
 begin
  read_history(original_op,tree,ships);assert_departed(tree,ships,original_op);
  if m.get_number('expected_version') is null or m.get_number('expected_version')!=treat(tree.get_array('nodes').get(0) as json_object_t).get_number('version') or m.get_string('expected_composition_signature') is null or m.get_string('expected_composition_signature')!=digest(tree.to_clob) then raise_application_error(-20890,'CLOSURE_CHANGED: reconciliation history signature');end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TT.RECONCILE:'||original_op);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_LOAD_RECONCILE',p_operation);
  nodes:=tree.get_array('nodes');links:=tree.get_array('links');
  for i in 0..nodes.get_size-1 loop
   x:=treat(nodes.get(i) as json_object_t);uid_text:=x.get_string('uid');
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',uid_text);
   if x.get_string('kind')='CASE' then
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('case_task_id')));
   else RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',uid_text);end if;
   if x.get_string('kind')='STOCK' then RRL_STOCK_PLAN_HELPER.anchor(r,50,'STOCK',uid_text);end if;
  end loop;
  for i in 0..links.get_size-1 loop
   x:=treat(links.get(i) as json_object_t);case_no:=x.get_number('id');
   if case_no is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(case_no));end if;
  end loop;
  for i in 0..ships.get_size-1 loop
   x:=treat(ships.get(i) as json_object_t).get_object('domain');st_no:=x.get_number('document_id');
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(st_no));
  end loop;
  RRL_STOCK_HU_LOAD_CORE.compile_load(p_request,tree.to_clob,ships.to_clob,f,r,loading);
  if loading is null then raise_application_error(-20886,'RECONCILE_CURRENT_LOADING_CONTEXT_REQUIRED');end if;
  v.put('original_operation',original_op);v.put('snapshot',tree);v.put('shipments',ships);v.put('loading',loading);v.put('signature',digest(tree.to_clob));
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');op varchar2(100):=d.get_string('operation_id');plan clob;
  v json_object_t;tree json_object_t;ships json_array_t;fresh json_object_t;fresh_ships json_array_t;nodes clob;ships_json clob;x json_object_t;alias_text varchar2(200);n number;original_op varchar2(100);j json_object_t:=json_object_t();
 begin
  if RRL_HAS_WRIGHT(p_actor,'stock_posting_shipping')!=1 then raise_application_error(-20882,'PHYSICAL_LOAD_FORBIDDEN');end if;
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  original_op:=v.get_string('original_operation');tree:=v.get_object('snapshot');ships:=v.get_array('shipments');x:=treat(tree.get_array('nodes').get(0) as json_object_t);alias_text:=x.get_string('sscc');
  if m.get_string('scan_container') is null or(m.get_string('scan_container')!=tree.get_string('root') and(alias_text is null or m.get_string('scan_container')!=alias_text))
   or m.get_string('scan_cell') is null or m.get_string('scan_cell')!=tree.get_string('cell') then raise_application_error(-20886,'RECONCILE_PHYSICAL_PLACE_CELL_SCAN_REQUIRED');end if;
  RRL_STOCK_HU_LOAD_CORE.begin_load(v.get_object('loading').to_clob);
  ships_json:=ships.to_clob;
  for z in(select ID from RRL_SBORKA_PALLETS where ID in(select ID from json_table(ships_json,'$[*]' columns(ID number path '$.domain.document_id'))) order by ID)loop select ID into n from RRL_SBORKA_PALLETS where ID=z.ID for update;end loop;
  nodes:=tree.get_array('nodes').to_clob;
  for z in(select CASE_PICK_TASK_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(select ID from json_table(nodes,'$[*]' columns(ID number path '$.case_task_id')))order by CASE_PICK_TASK_ID)loop select CASE_PICK_TASK_ID into n from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=z.CASE_PICK_TASK_ID for update;end loop;
  read_history(original_op,fresh,fresh_ships);
  if digest(fresh.to_clob)!=v.get_string('signature') then raise_application_error(-20890,'CLOSURE_CHANGED: reconciliation historical manifest');end if;
  assert_departed(tree,ships,original_op);
  RRL_STOCK_HU_LOAD_CORE.finish_load(v.get_object('loading').to_clob,tree.to_clob,op,p_actor);
  insert into RRL_TT_LOAD_RECONCILE(LOAD_OPERATION_ID,SHIPPING_OPERATION_ID,RECONCILED_BY) values(op,original_op,p_actor);
  j.put('operation_id',op);j.put('shipping_operation_id',original_op);j.put('status','LOADED');j.put('physical_load',v.get_object('loading'));j.put('composition_at_departure',tree);j.put('stock_consumed_again',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_LOAD_RECONCILE_READ as
 function preview_json(p_original varchar2) return clob is
  raw_result clob;j json_object_t;tree json_object_t;out_json json_object_t:=json_object_t();n number;
 begin
  select RESULT_JSON into raw_result from RRL_STOCK_OPERATION where OPERATION_ID=p_original and COMMAND_TYPE='HU_SHIP' and STATE='APPLIED';
  j:=json_object_t.parse(raw_result);tree:=j.get_object('composition_at_departure');
  if j.has('physical_load') and not j.get('physical_load').is_null then raise_application_error(-20886,'RECONCILE_ALREADY_HAS_PHYSICAL_LOAD');end if;
  if tree.get_array('nodes').get_size>200 or tree.get_array('ancestors').get_size!=0 then raise_application_error(-20881,'RECONCILE_PREVIEW_BOUND');end if;
  select count(*) into n from RRL_TT_LOAD_RECONCILE where SHIPPING_OPERATION_ID=p_original;
  out_json.put('shipping_operation_id',p_original);out_json.put('snapshot',tree);
  out_json.put('composition_signature',rawtohex(sys.dbms_crypto.hash(tree.to_clob,sys.dbms_crypto.hash_sh256)));
  out_json.put('already_reconciled',n>0);out_json.put('stock_already_consumed',true);out_json.put('server_rechecks_history_and_current_state',true);
  return out_json.to_clob;
 exception when no_data_found then raise_application_error(-20886,'RECONCILE_APPLIED_WHOLE_HU_SHIPMENT_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_LOAD_THERMAL as
 g_writing boolean:=false;g_operation varchar2(100);g_tx varchar2(100);
 function signed_decimal(p_value varchar2)return number is
 begin
  if p_value is null or not regexp_like(p_value,'^-?[0-9]{1,6}(\.[0-9]{1,3})?$')
   then raise_application_error(-20886,'LOAD_THERMAL_DECIMAL_TEXT_REQUIRED');end if;
  return to_number(p_value,'999999D999','NLS_NUMERIC_CHARACTERS=''.,''');
 end;
 procedure compile_confirmation(p_members clob,p_vehicle number,p_context clob,p_domain out json_object_t,p_phase varchar2 default 'MANUAL_AT_LOADING')is
  ctx json_object_t:=json_object_t.parse(p_context);observation json_object_t;profile json_object_t;capability json_object_t;
  rules json_array_t:=json_array_t();rule_value json_object_t;lo number;hi number;vlo number;vhi number;observed number;
  known_count number:=0;unknown_count number:=0;row_count number:=0;version_no number;keys json_key_list;
  source_value clob;reference_value varchar2(32767);mode_value varchar2(100);observed_element json_element_t;member_values json_array_t:=json_array_t.parse(p_members);
  query_value varchar2(32767);cursor_no integer;query_result integer;rows_cursor sys_refcursor;
  item_ware number;item_article varchar2(32767);item_lo number;item_hi number;member_no number;
 begin
  p_domain:=null;
  if p_phase is null or p_phase not in('MANUAL_AT_LOADING','MANUAL_AT_DEPARTURE')then raise_application_error(-20886,'THERMAL_PHASE_REQUIRED');end if;
  if member_values.get_size<1 or member_values.get_size>200
   then raise_application_error(-20881,'LOAD_THERMAL_MEMBER_BOUND_200');end if;
  query_value:='select /* CURRENT_LOAD_THERMAL_IN1173 */ distinct p.WARE_ID,r.ARTICUL,cfg.TEMP_MIN,cfg.TEMP_MAX from RRL_SBORKA_PALLETS p join RRL_SBORKA_PALLET_ROWS r on r.PALLET_UID=p.PALLET_UID left join RRL_RECEIPT_SKU_RULE cfg on cfg.WARE_ID=p.WARE_ID and cfg.ARTICUL=r.ARTICUL where p.ID in (';
  for i in 0..member_values.get_size-1 loop
   if i>0 then query_value:=query_value||',';end if;query_value:=query_value||':id'||to_char(i,'FM999');
  end loop;
  query_value:=query_value||') order by p.WARE_ID,r.ARTICUL fetch first 1001 rows only';
  cursor_no:=dbms_sql.open_cursor;dbms_sql.parse(cursor_no,query_value,dbms_sql.native);
  for i in 0..member_values.get_size-1 loop
   member_no:=member_values.get_number(i);
   if member_no is null or member_no<1 or member_no!=trunc(member_no)then raise_application_error(-20881,'LOAD_THERMAL_MEMBER_ID_REQUIRED');end if;
   dbms_sql.bind_variable(cursor_no,':id'||to_char(i,'FM999'),member_no);
  end loop;
  query_result:=dbms_sql.execute(cursor_no);rows_cursor:=dbms_sql.to_refcursor(cursor_no);cursor_no:=null;
  loop
   fetch rows_cursor into item_ware,item_article,item_lo,item_hi;exit when rows_cursor%notfound;
   row_count:=row_count+1;
   if row_count>1000 then raise_application_error(-20881,'LOAD_THERMAL_SKU_BOUND_1000');end if;
   if item_article is null then raise_application_error(-20886,'LOAD_THERMAL_ARTICLE_REQUIRED');end if;
   if item_lo is not null and item_hi is not null and item_lo>item_hi
    then raise_application_error(-20886,'LOAD_THERMAL_SKU_RANGE_INVALID');end if;
   rule_value:=json_object_t();rule_value.put('warehouse_id',item_ware);rule_value.put('articul',item_article);
   rule_value.put('temp_min_c',RRL_STOCK_PLAN_HELPER.decimal_text(item_lo));
   rule_value.put('temp_max_c',RRL_STOCK_PLAN_HELPER.decimal_text(item_hi));rules.append(rule_value);
   if item_lo is null and item_hi is null then unknown_count:=unknown_count+1;
   else
    known_count:=known_count+1;
    if item_lo is not null then if lo is null or item_lo>lo then lo:=item_lo;end if;end if;
    if item_hi is not null then if hi is null or item_hi<hi then hi:=item_hi;end if;end if;
   end if;
  end loop;close rows_cursor;
  if row_count=0 then raise_application_error(-20886,'LOAD_THERMAL_SOURCE_ROWS_REQUIRED');end if;
  if known_count=0 and not ctx.has('temperature_confirmation')then return;end if;
  if lo is not null and hi is not null and lo>hi then raise_application_error(-20886,'LOAD_THERMAL_SKU_RANGES_CONFLICT');end if;
  if not ctx.has('temperature_confirmation')then
   if p_phase='MANUAL_AT_DEPARTURE'then raise_application_error(-20886,'DEPART_THERMAL_CURRENT_CONFIRMATION_REQUIRED');else raise_application_error(-20886,'LOAD_THERMAL_CURRENT_CONFIRMATION_REQUIRED');end if;
  end if;
  observation:=ctx.get_object('temperature_confirmation');keys:=observation.get_keys;
  if keys.count!=4 then raise_application_error(-20886,'LOAD_THERMAL_EXPLICIT_FIELDS_REQUIRED');end if;
  for k in 1..keys.count loop
   if keys(k)not in('origin','observed_c','vehicle_profile_version','observation_reference')
    then raise_application_error(-20886,'LOAD_THERMAL_UNKNOWN_FIELD');end if;
  end loop;
  mode_value:=observation.get_string('origin');reference_value:=trim(observation.get_string('observation_reference'));
  if mode_value is null or mode_value!=p_phase or reference_value is null or length(reference_value)>100
   then raise_application_error(-20886,'LOAD_THERMAL_MANUAL_REFERENCE_REQUIRED');end if;
  observed_element:=observation.get('observed_c');
  if observed_element is null or not observed_element.is_string then raise_application_error(-20886,'LOAD_THERMAL_DECIMAL_TEXT_REQUIRED');end if;
  observed:=signed_decimal(observation.get_string('observed_c'));
  version_no:=observation.get_number('vehicle_profile_version');
  profile:=json_object_t.parse(RRL_VEHICLE_PROFILE_API.describe_profile(p_vehicle));
  if profile.get_string('state') is null or profile.get_string('state')!='READY'
   or version_no is null or version_no!=profile.get_number('version')
   then raise_application_error(-20886,'LOAD_THERMAL_CURRENT_VEHICLE_PROFILE_REQUIRED');end if;
  capability:=profile.get_object('profile');
  if not capability.has('temperature_capability')then raise_application_error(-20886,'LOAD_THERMAL_VEHICLE_RANGE_REQUIRED');end if;
  capability:=capability.get_object('temperature_capability');
  vlo:=signed_decimal(capability.get_string('temp_min_c'));vhi:=signed_decimal(capability.get_string('temp_max_c'));
  if vlo>vhi or observed<vlo or observed>vhi
   or(lo is not null and observed<lo)or(hi is not null and observed>hi)
   then raise_application_error(-20886,'LOAD_THERMAL_OBSERVATION_INCOMPATIBLE');end if;
  p_domain:=json_object_t();p_domain.put('vehicle_id',p_vehicle);p_domain.put('profile_version',version_no);
  p_domain.put('profile_base_hash',profile.get_string('base_hash'));p_domain.put('rules',rules);
  p_domain.put('configured_sku_count',known_count);p_domain.put('unconfirmed_sku_count',unknown_count);
  p_domain.put('observed_c',RRL_STOCK_PLAN_HELPER.decimal_text(observed));p_domain.put('observation_reference',reference_value);
  p_domain.put('origin',p_phase);p_domain.put('sensor_verified',false);
  p_domain.put('temperature_confirmation',observation);
 exception when others then
  if cursor_no is not null then if dbms_sql.is_open(cursor_no)then dbms_sql.close_cursor(cursor_no);end if;end if;
  if rows_cursor%isopen then close rows_cursor;end if;raise;
 end;
 procedure assert_current(p_members clob,p_vehicle number,p_domain clob,p_phase varchar2 default 'MANUAL_AT_LOADING')is
  frozen json_object_t;ctx json_object_t:=json_object_t();current_value json_object_t;n number;current_wire clob;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);
  if p_domain is not null then frozen:=json_object_t.parse(p_domain);ctx.put('temperature_confirmation',frozen.get_object('temperature_confirmation'));end if;
  compile_confirmation(p_members,p_vehicle,ctx.to_clob,current_value,p_phase);
  if p_domain is null and current_value is null then return;end if;
  if p_domain is null or current_value is null then raise_application_error(-20890,'CLOSURE_CHANGED: load thermal requirements');end if;
  current_wire:=current_value.to_clob;select count(*)into n from dual where json_equal(p_domain,current_wire);
  if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: load thermal profile/rules');end if;
 end;
 procedure assert_writing(p_operation varchar2)is
 begin
  if not g_writing or g_operation is null or g_operation!=p_operation or g_tx is null
   or g_tx!=dbms_transaction.local_transaction_id(false)
   or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null
   or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=p_operation
   then raise_application_error(-20863,'LOAD_THERMAL_ROOT_OWNER_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TT_HU_LOAD_FACT',p_operation));
 end;
 procedure persist_confirmation(p_operation varchar2,p_domain clob,p_actor varchar2)is
  d json_object_t;n number;vehicle_no number;version_no number;observed_no number;reference_value nvarchar2(100);
 begin
  if p_domain is null then return;end if;
  d:=json_object_t.parse(p_domain);vehicle_no:=d.get_number('vehicle_id');version_no:=d.get_number('profile_version');
  observed_no:=signed_decimal(d.get_string('observed_c'));reference_value:=d.get_string('observation_reference');
  select count(*)into n from RRL_TT_HU_LOAD_FACT l join RRL_STOCK_OPERATION o on o.OPERATION_ID=l.LOAD_OPERATION_ID
   where l.LOAD_OPERATION_ID=p_operation and l.VEHICLE_ID=vehicle_no
    and l.LOADED_BY=p_actor and l.STATUS='LOADED'and o.STATE='IN_FLIGHT';
  if n!=1 then raise_application_error(-20863,'LOAD_THERMAL_CURRENT_LOAD_FACT_REQUIRED');end if;
  g_writing:=true;g_operation:=p_operation;g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_TT_LOAD_THERMAL_FACT(LOAD_OPERATION_ID,VEHICLE_ID,PROFILE_VERSION,OBSERVED_C,OBSERVATION_REFERENCE,OBSERVATION_BASIS,ACTOR,CONFIRMATION_JSON)
   values(p_operation,vehicle_no,version_no,observed_no,reference_value,'MANUAL_AT_LOADING',p_actor,p_domain);
  g_writing:=false;g_operation:=null;g_tx:=null;
 exception when others then g_writing:=false;g_operation:=null;g_tx:=null;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_LOCATION_CORE as
 procedure assert_receiving(p_cell varchar2,p_expected_warehouse number) is v_ware number;v_block number;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CELL',p_cell),4);
  select WARE_ID,nvl(BLOCKED_FOR_ACCEPT,0) into v_ware,v_block from RRL_CELLS where CELL=p_cell;
  if v_ware is null or p_expected_warehouse is null or v_ware!=p_expected_warehouse or v_block!=0 then raise_application_error(-20879,'RECEIVING_LOCATION_UNAVAILABLE');end if;
 end;
 procedure assert_quarantine(p_cell varchar2,p_expected_warehouse number) is v_ware number;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CELL',p_cell),4);
  select WARE_ID into v_ware from RRL_CELLS where CELL=p_cell;
  if v_ware is null or p_expected_warehouse is null or v_ware!=p_expected_warehouse then raise_application_error(-20877,'QUARANTINE_WAREHOUSE_CONFLICT');end if;
 end;
 procedure assert_ordinary(p_cell varchar2,p_expected_warehouse number,p_role varchar2) is
  v_ware number;v_remain number;v_replenish number;v_accept number;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CELL',p_cell),4);
  select WARE_ID,nvl(BLOCKED_FOR_REMAINS,0),nvl(BLOCKED_FOR_POPOLNENIE,0),nvl(BLOCKED_FOR_ACCEPT,0)
   into v_ware,v_remain,v_replenish,v_accept from RRL_CELLS where CELL=p_cell;
  if p_expected_warehouse is null or v_ware is null or v_ware!=p_expected_warehouse then
   raise_application_error(-20877,'WAREHOUSE_LOCATION_CONFLICT');
  end if;
  if p_role not in('SOURCE','TARGET','RECEIVE') or p_role is null then raise_application_error(-20878,'LOCATION_ROLE_INVALID'); end if;
  if v_remain!=0 or v_replenish!=0 or(p_role in('TARGET','RECEIVE') and v_accept!=0) then
   raise_application_error(-20879,'LOCATION_BLOCKED: quarantine/unavailable cell excluded');
  end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_LOCK_API as
 type held_set is table of boolean index by varchar2(2100);
 type policy_set is table of number index by varchar2(2000);
 g_policies policy_set;
 g_held held_set; g_started number; g_phase varchar2(20); g_tx varchar2(100);
 function remaining_seconds return number is v_elapsed number;
 begin
  v_elapsed:=mod(dbms_utility.get_time-g_started+4294967296,4294967296)/100;
  if v_elapsed>=3 then raise_application_error(-20840,'LOCK_TIMEOUT: total lock budget exhausted'); end if;
  return greatest(0,3-v_elapsed);
 end;
 function resource_lock_id(p_rank number,p_key raw) return number is v raw(32);
 begin
  v:=sys.dbms_crypto.hash(utl_raw.concat(utl_i18n.string_to_raw(to_char(p_rank,'FM990')||':','AL32UTF8'),p_key),sys.dbms_crypto.hash_sh256);
  return mod(to_number(substr(rawtohex(v),1,8),'XXXXXXXX'),800000000);
 end;
 function resource_key(p_kind varchar2,p_a varchar2,p_b varchar2 default null,p_c varchar2 default null) return raw is
  v raw(1000); x raw(32767);
  procedure part(p varchar2) is z raw(32767);
  begin
   if p is null then raise_application_error(-20841,'RESOURCE_KEY_EMPTY'); end if;
   z:=utl_i18n.string_to_raw(p,'AL32UTF8');
   x:=utl_raw.concat(x,utl_i18n.string_to_raw(to_char(utl_raw.length(z),'FM9990')||':','AL32UTF8'),z);
  end;
 begin
  part('2');part(p_kind);part(p_a);
  if p_b is not null then part(p_b); end if;
  if p_c is not null then part(p_c); end if;
  if utl_raw.length(x)>1000 then raise_application_error(-20842,'RESOURCE_KEY_TOO_LONG'); end if;
  v:=x;return v;
 end;
 procedure clear_plan is begin g_held.delete;g_policies.delete;g_phase:=null;g_tx:=null;g_started:=null;end;
 procedure begin_plan is
 begin
  if dbms_transaction.local_transaction_id(false) is not null or g_phase is not null then
   raise_application_error(-20843,'DIRTY_TRANSACTION: no domain pre-locks or pre-writes permitted');
  end if;
  g_started:=dbms_utility.get_time;g_phase:='POLICY';
 end;
 procedure acquire_policies(p_plan clob) is v_result number; v_timeout number;
 begin
  if g_phase!='POLICY' or g_phase is null then raise_application_error(-20844,'LOCK_ORDER: policies must precede rows'); end if;
  for r in(select j.KEY_HEX,j.LOCK_MODE from
   json_table(p_plan,'$[*]' columns(KEY_HEX varchar2(2000) path '$.key_hex',LOCK_MODE number path '$.mode' error on error)) j) loop
   if r.KEY_HEX is null or not regexp_like(r.KEY_HEX,'^([0-9A-F]{2})+$','c')
    or r.LOCK_MODE is null or r.LOCK_MODE not in(4,6) then
    raise_application_error(-20845,'POLICY_PLAN_INVALID');
   end if;
  end loop;
  for r in(select p.LOCK_ID,p.POLICY_KEY,max(j.LOCK_MODE) LOCK_MODE from
    json_table(p_plan,'$[*]' columns(KEY_HEX varchar2(2000) path '$.key_hex',
      LOCK_MODE number path '$.mode' error on error)) j
    join RRL_STOCK_POLICY_GUARD p on p.POLICY_KEY=hextoraw(j.KEY_HEX)
    group by p.LOCK_ID,p.POLICY_KEY order by p.LOCK_ID) loop
   if r.LOCK_MODE is null or r.LOCK_MODE not in(4,6) then raise_application_error(-20845,'POLICY_MODE_INVALID'); end if;
   v_timeout:=floor(remaining_seconds);
   v_result:=sys.dbms_lock.request(r.LOCK_ID,r.LOCK_MODE,v_timeout,true);
   if v_result=1 then raise_application_error(-20840,'LOCK_TIMEOUT: policy fence'); end if;
   if v_result=2 then raise_application_error(-20846,'DEADLOCK_RETRY: policy fence'); end if;
   if v_result!=0 then raise_application_error(-20847,'POLICY_LOCK_PROTOCOL_ERROR: '||v_result); end if;
   g_policies(rawtohex(r.POLICY_KEY)):=r.LOCK_MODE;
  end loop;
  -- Every requested policy must be published. Do not silently skip missing keys.
  for r in(select j.KEY_HEX from json_table(p_plan,'$[*]' columns(KEY_HEX varchar2(2000) path '$.key_hex'))j
    where not exists(select 1 from RRL_STOCK_POLICY_GUARD p where p.POLICY_KEY=hextoraw(j.KEY_HEX))) loop
   raise_application_error(-20848,'POLICY_KEY_NOT_PUBLISHED');
  end loop;
  g_phase:='ROWS';
 end;
 procedure acquire_resources(p_plan clob) is v_rank number;v_id varchar2(2100);v_result number;v_locked number;
 begin
  if g_phase!='ROWS' or g_phase is null then raise_application_error(-20849,'LOCK_ORDER: one complete resource plan required');end if;
  -- Acquire all native mutexes in numeric order before creating or locking any guard row.
  -- Hash collisions only serialize unrelated keys; their common acquisition order prevents cycles.
  -- The policy range 900000000..949999999 is disjoint from resource IDs 0..799999999.
  for r in(select distinct RRL_STOCK_LOCK_API.resource_lock_id(j.RESOURCE_RANK,hextoraw(j.KEY_HEX)) LOCK_ID
   from json_table(p_plan,'$[*]' columns(RESOURCE_RANK number path '$.rank' error on error,
    KEY_HEX varchar2(2000) path '$.key_hex' error on error))j order by LOCK_ID) loop
   v_result:=sys.dbms_lock.request(r.LOCK_ID,6,floor(remaining_seconds),true);
   if v_result=1 then raise_application_error(-20840,'LOCK_TIMEOUT: resource mutex');end if;
   if v_result=2 then raise_application_error(-20846,'DEADLOCK_RETRY: resource mutex');end if;
   if v_result!=0 then raise_application_error(-20847,'RESOURCE_MUTEX_PROTOCOL_ERROR: '||v_result);end if;
  end loop;
  -- All shared keys are now exclusively owned. Set DML replaces one INSERT per unit.
  insert into RRL_STOCK_GUARD(RESOURCE_RANK,RESOURCE_KEY)
   select distinct j.RESOURCE_RANK,hextoraw(j.KEY_HEX) from json_table(p_plan,'$[*]'
    columns(RESOURCE_RANK number path '$.rank',KEY_HEX varchar2(2000) path '$.key_hex'))j
   where not exists(select 1 from RRL_STOCK_GUARD g where g.RESOURCE_RANK=j.RESOURCE_RANK and g.RESOURCE_KEY=hextoraw(j.KEY_HEX));
  -- NOWAIT is sufficient after native ownership. An unexpected external writer gets a whole-operation retry.
  for r in(select /*+ index(g RRL_STOCK_GUARD_PK) */ g.RESOURCE_RANK,g.RESOURCE_KEY
   from RRL_STOCK_GUARD g where (g.RESOURCE_RANK,g.RESOURCE_KEY) in
    (select j.RESOURCE_RANK,hextoraw(j.KEY_HEX) from json_table(p_plan,'$[*]'
     columns(RESOURCE_RANK number path '$.rank',KEY_HEX varchar2(2000) path '$.key_hex'))j)
   order by g.RESOURCE_RANK,g.RESOURCE_KEY) loop
   select RESOURCE_RANK into v_locked from RRL_STOCK_GUARD where RESOURCE_RANK=r.RESOURCE_RANK and RESOURCE_KEY=r.RESOURCE_KEY for update nowait;
   if r.RESOURCE_RANK not in(10,20,30,40,50,60,70) then raise_application_error(-20841,'RESOURCE_PLAN_INVALID');end if;
   v_id:=to_char(r.RESOURCE_RANK,'FM990')||':'||rawtohex(r.RESOURCE_KEY);g_held(v_id):=true;
  end loop;
  g_tx:=dbms_transaction.local_transaction_id(false);g_phase:='HELD';
 end;
 procedure assert_policy(p_key raw,p_mode number) is v_key varchar2(2000):=rawtohex(p_key);
 begin
  if g_phase is null or g_phase!='HELD' or g_tx is null
   or dbms_transaction.local_transaction_id(false) is null
   or g_tx!=dbms_transaction.local_transaction_id(false) or p_mode is null or p_mode not in(4,6)
   or not g_policies.exists(v_key) then raise_application_error(-20850,'POLICY_PLAN_VIOLATION'); end if;
  if g_policies(v_key)<p_mode then raise_application_error(-20850,'POLICY_MODE_INSUFFICIENT'); end if;
 end;
 procedure assert_held(p_rank number,p_key raw) is v_id varchar2(2100);
 begin
  v_id:=to_char(p_rank,'FM990')||':'||rawtohex(p_key);
  if g_phase!='HELD' or g_phase is null or g_tx is null
   or dbms_transaction.local_transaction_id(false) is null
   or g_tx!=dbms_transaction.local_transaction_id(false) or not g_held.exists(v_id) then
   raise_application_error(-20850,'WRITE_PLAN_VIOLATION');
  end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_MATH as
 procedure assert_base(p_value number,p_scale number) is
 begin
  if p_value is null or p_scale is null or p_scale!=trunc(p_scale) or p_scale<0 or p_scale>9
     or abs(p_value)>=power(10,18) or trunc(p_value,p_scale)!=p_value then
   raise_application_error(-20830,'QUANTITY_PRECISION: exact bounded base quantity required');
  end if;
 end;
 function quantity(p_text varchar2,p_scale number default 9) return number is v number;
 begin
  if p_text is null or length(p_text)>28 or not regexp_like(p_text,'^[0-9]{1,18}([.][0-9]{1,9})?$','c') then
   raise_application_error(-20831,'QUANTITY_FORMAT: canonical decimal required');
  end if;
  v:=to_number(p_text,'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');
  assert_base(v,p_scale);
  if v<=0 then raise_application_error(-20832,'QUANTITY_POSITIVE: positive quantity required'); end if;
  return v;
 end;
 function convert_exact(p_text varchar2,p_numerator number,p_denominator number,p_scale number) return number is
  v number; v_a number; v_n number; v_d number; v_i number;
 begin
  v:=quantity(p_text);
  if p_numerator is null or p_denominator is null or p_numerator!=trunc(p_numerator)
   or p_denominator!=trunc(p_denominator) or p_numerator<1 or p_numerator>1000000000
   or p_denominator<1 or p_denominator>1000000000 then raise_application_error(-20833,'UOM_FACTOR_INVALID'); end if;
  assert_base(0,p_scale);
  v_a:=case when instr(p_text,'.')=0 then 0 else length(p_text)-instr(p_text,'.') end;
  v_i:=v*power(10,v_a);
  v_n:=v_i*p_numerator*power(10,greatest(p_scale-v_a,0));
  v_d:=p_denominator*power(10,greatest(v_a-p_scale,0));
  if mod(v_n,v_d)!=0 then raise_application_error(-20834,'UOM_ROUNDING_FORBIDDEN'); end if;
  v:=(v_n/v_d)/power(10,p_scale);
  assert_base(v,p_scale);
  return v;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_MES_CANCEL_CMD as
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);t RRL_MES_RAW_TRANSFER_TASK%rowtype;sr RRL_STOCK_RESERVATION%rowtype;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();v json_object_t:=json_object_t();a json_array_t:=json_array_t();
 begin
  declare
 v_json_sql_1_1 number:=d.get_object('source').get_number('raw_task_id');
begin
select * into t from RRL_MES_RAW_TRANSFER_TASK where TASK_ID=v_json_sql_1_1;
end;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRODUCTION_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(t.PRODUCTION_ORDER_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_MES_RAW_TRANSFER_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.TASK_ID));
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  if t.RESERVATION_ID is not null then
   select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=t.RESERVATION_ID;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(sr.RESERVATION_ID));
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,sr.UID_PALLET,sr.ARTICUL,sr.CELL,null);
   v.put('reservation',sr.RESERVATION_ID);v.put('reservation_version',sr.RESERVATION_VERSION);
  end if;
  for w in(select TASK_ID from RRL_WAREHOUSE_TASK where TASK_SOURCE='MES_RAW_SUPPLY' and SOURCE_TASK_ID=t.TASK_ID and STATUS not in('DONE','CANCELLED') order by TASK_ID) loop
   if a.get_size>=200 then raise_application_error(-20881,'MES_CANCEL_TASK_BOUND');end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(w.TASK_ID));a.append(w.TASK_ID);
  end loop;
  v.put('document',t.PRODUCTION_ORDER_ID);v.put('raw_task',t.TASK_ID);v.put('warehouse_tasks',a);
  p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;j json_object_t:=json_object_t();a json_array_t;
  plan clob;t RRL_MES_RAW_TRANSFER_TASK%rowtype;sr RRL_STOCK_RESERVATION%rowtype;status varchar2(40);ver number;n number;id number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'mes_raw_transfer_cancel')!=1 then raise_application_error(-20882,'MES_CANCEL_FORBIDDEN');end if;
  declare
 v_json_sql_2_1 varchar2(32767):=d.get_string('operation_id');
begin
select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_2_1;
end;v:=json_object_t.parse(plan).get_object('domain');a:=v.get_array('warehouse_tasks');
  declare
 v_json_sql_3_1 number:=v.get_number('document');
begin
select STATUS into status from RRL_PRODUCTION_ORDER where PRODUCTION_ORDER_ID=v_json_sql_3_1 for update;
end;
  declare
 v_json_sql_4_1 number:=v.get_number('raw_task');
begin
select * into t from RRL_MES_RAW_TRANSFER_TASK where TASK_ID=v_json_sql_4_1 for update;
end;
  if t.PRODUCTION_ORDER_ID!=v.get_number('document') or nvl(t.RESERVATION_ID,-1)!=nvl(v.get_number('reservation'),-1) then raise_application_error(-20890,'CLOSURE_CHANGED: MES cancellation');end if;
  if t.TASK_STATUS='DONE' then raise_application_error(-20886,'COMPLETED_TASK_CANNOT_CANCEL');end if;
  select count(*) into n from RRL_WAREHOUSE_TASK where TASK_SOURCE='MES_RAW_SUPPLY' and SOURCE_TASK_ID=t.TASK_ID and STATUS not in('DONE','CANCELLED');
  if n!=a.get_size then raise_application_error(-20890,'CLOSURE_CHANGED: MES task children');end if;
  if t.RESERVATION_ID is not null then
   select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=t.RESERVATION_ID for update;
   if sr.RESERVATION_VERSION!=v.get_number('reservation_version') or sr.SOURCE_DOC_TYPE!='PRODUCTION_ORDER' or sr.SOURCE_DOC_ID!=t.PRODUCTION_ORDER_ID then raise_application_error(-20890,'CLOSURE_CHANGED: MES reservation');end if;
   if sr.STATUS in('ACTIVE','ALLOCATED','PICKING') then
    if sr.RESERVATION_KIND!='HARD' then raise_application_error(-20869,'MES_HARD_RESERVATION_REQUIRED');end if;
    select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=sr.ARTICUL and INPUT_UOM=sr.BASE_UOM and BASE_UOM=sr.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
    if ver is null then raise_application_error(-20868,'MES_BASE_POLICY_REQUIRED');end if;
    RRL_STOCK_UNIT_CORE.release_units(sr.RESERVATION_ID,sr.BASE_QTY,null,0);
    RRL_STOCK_RESERVE_CORE.release_hard(sr.RESERVATION_ID,sr.BASE_QTY,ver,'PRODUCTION_ORDER',t.PRODUCTION_ORDER_ID,p_actor);
    RRL_STOCK_CTX_API.begin_effect('RESERVATION',sr.UID_PALLET,sr.CELL,sr.RESERVATION_ID);
    declare
 v_json_sql_5_1 varchar2(32767):=d.get_object('metadata').get_string('reason');
begin
update RRL_STOCK_RESERVATION set STATUS='CANCELLED',RELEASE_REASON=v_json_sql_5_1,RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=sr.RESERVATION_ID;
end;
    RRL_STOCK_CTX_API.end_effect;
   end if;
  end if;
  for i in 0..a.get_size-1 loop
   id:=a.get_number(i);select STATUS into status from RRL_WAREHOUSE_TASK where TASK_ID=id for update;
   if status in('DONE','CANCELLED') then raise_application_error(-20890,'CLOSURE_CHANGED: MES child state');end if;
   declare
 v_json_sql_6_1 varchar2(32767):=d.get_object('metadata').get_string('reason');
begin
update RRL_WAREHOUSE_TASK set STATUS='CANCELLED',CANCELLED_AT=systimestamp,CANCELLED_BY=p_actor,LAST_ERROR=v_json_sql_6_1 where TASK_ID=id;
end;
  end loop;
  declare
 v_json_sql_7_1 varchar2(32767):=d.get_object('metadata').get_string('reason');
begin
update RRL_MES_RAW_TRANSFER_TASK set TASK_STATUS='CANCELLED',CANCELLED_AT=systimestamp,CANCELLED_BY=p_actor,LAST_ERROR=v_json_sql_7_1 where TASK_ID=t.TASK_ID;
end;
  j.put('operation_id',d.get_string('operation_id'));j.put('raw_task_id',t.TASK_ID);j.put('status','CANCELLED');p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_MES_CORE as
 procedure sync_warehouse_fact(p_task RRL_WAREHOUSE_TASK%rowtype,p_qty number,p_target_uid varchar2,p_residual number,p_actor varchar2) is
  v_raw RRL_MES_RAW_TRANSFER_TASK%rowtype;v_movement RRL_MES_MOVEMENT%rowtype;
  v_n number;v_done number;v_id number;v_plan clob;v_domain json_object_t;
 begin
  select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION
   where OPERATION_ID=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');
  v_domain:=json_object_t.parse(v_plan).get_object('domain');
  if p_task.TASK_SOURCE='MES_RAW_SUPPLY' then
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_MES_RAW_TRANSFER_TASK',
    RRL_STOCK_PLAN_HELPER.decimal_text(p_task.SOURCE_TASK_ID)));
   select * into v_raw from RRL_MES_RAW_TRANSFER_TASK where TASK_ID=p_task.SOURCE_TASK_ID for update;
   if v_raw.TASK_STATUS='CANCELLED' or v_raw.PRODUCTION_ORDER_ID!=nvl(p_task.PRODUCTION_ORDER_ID,p_task.SOURCE_DOC_ID)
    then raise_application_error(-20886,'MES_TASK_SOURCE_CONFLICT');end if;
   select nvl(sum(case when STATUS='DONE' then nvl(FACT_QTY,QTY) else 0 end),0),
    sum(case when STATUS not in('DONE','CANCELLED') then 1 else 0 end)
    into v_done,v_n from RRL_WAREHOUSE_TASK where TASK_SOURCE='MES_RAW_SUPPLY' and SOURCE_TASK_ID=p_task.SOURCE_TASK_ID;
   if v_done>v_raw.TASK_QTY then raise_application_error(-20886,'MES_DELIVERY_EXCEEDS_TASK');end if;
   v_id:=v_domain.get_number('new_movement_id');
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_MES_MOVEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(v_id)));
   insert into RRL_MES_MOVEMENT(MOVEMENT_ID,MOVEMENT_TYPE,PRODUCTION_ORDER_ID,BOM_ID,BOM_LINE_ID,
    RAW_BATCH_ID,RAW_ARTICUL,UID_PALLET,QUANTITY,UNIT_CODE,SOURCE_LOCATION,TARGET_LOCATION,STATUS,
    WMS_APPLIED_AT,WMS_APPLIED_BY,CREATED_AT,CREATED_BY,UPDATED_AT,UPDATED_BY,PAYLOAD_JSON)
    values(v_id,'RAW_ISSUE_TO_PRODUCTION',v_raw.PRODUCTION_ORDER_ID,v_raw.BOM_ID,v_raw.BOM_LINE_ID,
     v_raw.RAW_BATCH_ID,v_raw.RAW_ARTICUL,p_target_uid,p_qty,p_task.UNIT_CODE,p_task.FROM_CELL,p_task.TO_CELL,
     'APPLIED_TO_WMS',sysdate,p_actor,sysdate,p_actor,sysdate,p_actor,v_plan);
   update RRL_MES_RAW_TRANSFER_TASK set TASK_STATUS=case when nvl(v_n,0)=0 then 'DONE' else 'IN_PROGRESS' end,
    FACT_QTY=v_done,FINISHED_AT=case when nvl(v_n,0)=0 then sysdate else FINISHED_AT end,LAST_ERROR=null
    where TASK_ID=p_task.SOURCE_TASK_ID;
  elsif p_task.TASK_SOURCE='MES_COMPLETION' then
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_MES_MOVEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(p_task.SOURCE_MOVEMENT_ID)));
   select * into v_movement from RRL_MES_MOVEMENT where MOVEMENT_ID=p_task.SOURCE_MOVEMENT_ID for update;
   if v_movement.MOVEMENT_TYPE!='FG_PALLET_RELEASE' or v_movement.STATUS='CANCELLED'
    or v_movement.UID_PALLET!=nvl(p_task.UID_PALLET,p_task.SSCC) then raise_application_error(-20886,'MES_FINISHED_GOODS_CONFLICT');end if;
   update RRL_MES_MOVEMENT set STATUS='APPLIED_TO_WMS',TARGET_LOCATION=p_task.TO_CELL,
    WMS_APPLIED_AT=nvl(WMS_APPLIED_AT,sysdate),WMS_APPLIED_BY=nvl(WMS_APPLIED_BY,p_actor),
    UPDATED_AT=sysdate,UPDATED_BY=p_actor,LAST_ERROR=null where MOVEMENT_ID=p_task.SOURCE_MOVEMENT_ID;
  else raise_application_error(-20888,'MES_TASK_DOMAIN_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_MES_MOVEMENT_CORE as

 procedure execute_movements(p_request clob,p_actor varchar2,p_result out clob) is

  d json_object_t:=json_object_t.parse(p_request);h json_object_t;v json_object_t;items json_array_t;m RRL_MES_MOVEMENT%rowtype;

  o RRL_PRODUCTION_ORDER%rowtype;p RRL_PALLETS%rowtype;v_plan clob;v_uid varchar2(200);v_target varchar2(200);

  v_qty number;v_base varchar2(20);v_version number;v_source_ware number;v_target_ware number;v_event number;

  v_reservation number;v_new_reservation number;v_p number;v_article varchar2(160);v_units clob;

  result json_object_t:=json_object_t();facts json_array_t:=json_array_t();fact json_object_t;v_n number;

 begin

  if RRL_HAS_WRIGHT(p_actor,'mes_wms_bridge_apply')!=1 then raise_application_error(-20882,'MES_WMS_APPLY_FORBIDDEN');end if;

  declare

 v_json_sql_1_1 varchar2(32767):=d.get_string('operation_id');

begin

select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_1_1;

end;

  h:=json_object_t.parse(v_plan).get_object('domain');items:=h.get_array('movements');

  declare

 v_json_sql_2_1 number:=h.get_number('production_order_id');

begin

select * into o from RRL_PRODUCTION_ORDER where PRODUCTION_ORDER_ID=v_json_sql_2_1 for update;

end;

  select count(*)into v_n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0
   and(u.WARE_ID=o.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if v_n!=1 then raise_application_error(-20882,'MES_CURRENT_WAREHOUSE_ACTOR_REQUIRED');end if;
  if o.STATUS='CANCELLED' then raise_application_error(-20886,'MES_ORDER_CANCELLED');end if;

  for i in 0..items.get_size-1 loop

   v:=treat(items.get(i) as json_object_t);

   declare

 v_json_sql_3_1 number:=v.get_number('movement_id');

begin

select * into m from RRL_MES_MOVEMENT where MOVEMENT_ID=v_json_sql_3_1 for update;

end;

   if RRL_STOCK_MES_MOVEMENT_PLAN.signature(m)!=v.get_string('signature') then raise_application_error(-20890,'CLOSURE_CHANGED: MES movement');end if;

   if m.STATUS not in('MES_POSTED','ERROR') or m.STATUS is null then raise_application_error(-20886,'MES_MOVEMENT_STATE_CONFLICT');end if;

   v_uid:=v.get_string('physical_uid');v_target:=v.get_string('target_uid');v_article:=v.get_string('article');

   v_qty:=RRL_STOCK_MATH.quantity(v.get_string('base_quantity'));v_base:=v.get_string('base_uom');v_version:=v.get_number('uom_version');

   v_reservation:=v.get_number('reservation_id');v_new_reservation:=v.get_number('new_reservation_id');v_units:=null;

   if d.get_object('metadata').has('units_by_movement') then

    if d.get_object('metadata').get_object('units_by_movement').has(RRL_STOCK_PLAN_HELPER.decimal_text(m.MOVEMENT_ID)) then

     v_units:=d.get_object('metadata').get_object('units_by_movement').get_array(RRL_STOCK_PLAN_HELPER.decimal_text(m.MOVEMENT_ID)).to_clob;

    end if;

   end if;

   if m.MOVEMENT_TYPE='FG_PALLET_RELEASE' then

    select WARE_ID into v_target_ware from RRL_CELLS where CELL=m.TARGET_LOCATION;

    if v_target_ware!=o.WARE_ID then raise_application_error(-20886,'MES_FINISHED_WAREHOUSE_CONFLICT');end if;

    RRL_STOCK_LOCATION_CORE.assert_ordinary(m.TARGET_LOCATION,v_target_ware,'TARGET');

    select count(*) into v_n from RRL_REMAINS where UID_POLETA=v_uid;

    if v_n>0 then raise_application_error(-20886,'MES_FINISHED_STOCK_ALREADY_EXISTS');end if;

    select count(*) into v_n from RRL_PALLETS where UID_PALLET=v_uid;

    if v_n=0 then

     insert into RRL_PALLETS(UID_PALLET,ARTICUL,UNIT_COUNT,PRIHOD_NAKLAD_ID,PROD_BATCH_ID,SSCC,QUALITY_STATUS)

      values(v_uid,v_article,v_qty,0,m.PROD_BATCH_ID,m.SSCC,'RELEASED');

    else

     select * into p from RRL_PALLETS where UID_PALLET=v_uid;

     if p.ARTICUL!=v_article or p.PROD_BATCH_ID!=m.PROD_BATCH_ID or p.UNIT_COUNT!=v_qty then raise_application_error(-20887,'MES_FINISHED_LOT_CONFLICT');end if;

    end if;

    RRL_STOCK_BALANCE_CORE.apply_delta(v_uid,m.TARGET_LOCATION,v_qty,0,v_base,v_version);

    RRL_STOCK_UNIT_CORE.admit_captured(v_uid,m.TARGET_LOCATION);

    RRL_STOCK_BALANCE_CORE.write_leg(v_uid,null,m.TARGET_LOCATION,v_qty,v_base,v_version,i+1,1,1,p_actor,v_event);

   else

    select * into p from RRL_PALLETS where UID_PALLET=v_uid;

    if p.ARTICUL!=v_article or (m.RAW_ARTICUL is not null and m.RAW_ARTICUL!=v_article) then raise_application_error(-20887,'MES_RAW_ARTICLE_CONFLICT');end if;

    select WARE_ID into v_source_ware from RRL_CELLS where CELL=m.SOURCE_LOCATION;

    if v_reservation is not null then

     select count(*) into v_n from RRL_STOCK_RESERVATION where RESERVATION_ID=v_reservation and

      SOURCE_DOC_TYPE='PRODUCTION_ORDER' and SOURCE_DOC_ID=o.PRODUCTION_ORDER_ID and UID_PALLET=v_uid and CELL=m.SOURCE_LOCATION;

     if v_n!=1 then raise_application_error(-20869,'MES_RESERVATION_OWNER_CONFLICT');end if;

    end if;

    if m.MOVEMENT_TYPE='RAW_CONSUMPTION' then

     RRL_STOCK_EFFECT_CORE.consume(v_uid,m.SOURCE_LOCATION,v_qty,v_base,v_version,v_source_ware,p_actor,i+1,

      v_reservation,'PRODUCTION_ORDER',o.PRODUCTION_ORDER_ID,v_units);

    else

     select WARE_ID into v_target_ware from RRL_CELLS where CELL=m.TARGET_LOCATION;

     if v_target_ware!=o.WARE_ID then raise_application_error(-20886,'MES_PRODUCTION_WAREHOUSE_CONFLICT');end if;

     select REMAIN into v_p from RRL_REMAINS where UID_POLETA=v_uid and CELL=m.SOURCE_LOCATION;

     if RRL_STOCK_PLAN_HELPER.decimal_text(v_p)!=v.get_string('source_p') then raise_application_error(-20890,'CLOSURE_CHANGED: MES source quantity');end if;

     if v_target!=v_uid then

      p.STOCK_ORIGIN_UID:=nvl(p.STOCK_ORIGIN_UID,p.UID_PALLET);p.CREATED_BY_STOCK_OP:=d.get_string('operation_id');

      if p.WEIGHT_BRUTTO is not null then

       if p.UNIT_COUNT is null or p.UNIT_COUNT<=0 then raise_application_error(-20887,'PALLET_BIRTH_QUANTITY_REQUIRED');end if;

       p.WEIGHT_BRUTTO:=p.WEIGHT_BRUTTO*v_qty/p.UNIT_COUNT;

      end if;

      p.UID_PALLET:=v_target;p.SSCC:=null;p.UNIT_COUNT:=v_qty;p.PRINTED:=0;

      p.STOCK_COMPOSITION_VERSION:=0;insert into RRL_PALLETS values p;

     end if;

     RRL_STOCK_TRANSFER_CORE.move(v_uid,v_target,m.SOURCE_LOCATION,m.TARGET_LOCATION,v_qty,v_base,v_version,v_target_ware,

      p_actor,i+1,v_reservation,v_units,v_new_reservation,null,v_source_ware);

    end if;

   end if;

   declare

 v_json_sql_4_1 varchar2(32767):=d.get_string('operation_id');

begin

update RRL_MES_MOVEMENT set STATUS='APPLIED_TO_WMS',SOURCE_UID_PALLET=v_uid,TARGET_UID_PALLET=v_target,

    UID_PALLET=case when MOVEMENT_TYPE='RAW_ISSUE_TO_PRODUCTION' then v_target else UID_PALLET end,

    STOCK_OPERATION_ID=v_json_sql_4_1,POSTED_BASE_QTY=v_qty,STOCK_BASE_UOM=v_base,

    WMS_APPLIED_AT=sysdate,WMS_APPLIED_BY=p_actor,UPDATED_AT=sysdate,UPDATED_BY=p_actor,LAST_ERROR=null where MOVEMENT_ID=m.MOVEMENT_ID;

end;

   fact:=json_object_t();fact.put('movement_id',m.MOVEMENT_ID);fact.put('uid',v_target);fact.put('base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));

   fact.put('base_uom',v_base);facts.append(fact);

  end loop;

  result.put('operation_id',d.get_string('operation_id'));result.put('production_order_id',o.PRODUCTION_ORDER_ID);result.put('movements',facts);p_result:=result.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_MES_MOVEMENT_PLAN as
 function signature(p_m RRL_MES_MOVEMENT%rowtype) return varchar2 is v json_object_t:=json_object_t();
 begin
  v.put('id',p_m.MOVEMENT_ID);v.put('type',p_m.MOVEMENT_TYPE);v.put('order',p_m.PRODUCTION_ORDER_ID);
  v.put('uid',p_m.UID_PALLET);v.put('sscc',p_m.SSCC);v.put('batch',p_m.PROD_BATCH_ID);v.put('raw',p_m.RAW_ARTICUL);
  v.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(p_m.QUANTITY));v.put('unit',p_m.UNIT_CODE);
  v.put('from',p_m.SOURCE_LOCATION);v.put('to',p_m.TARGET_LOCATION);
  return rawtohex(sys.dbms_crypto.hash(v.to_clob,sys.dbms_crypto.hash_sh256));
 end;
 procedure compile_movements(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);s json_object_t;ids json_array_t;a json_array_t:=json_array_t();
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();v json_object_t:=json_object_t();h json_object_t:=json_object_t();
  m RRL_MES_MOVEMENT%rowtype;o RRL_PRODUCTION_ORDER%rowtype;v_id number;v_article varchar2(160);
  v_p number;v_target varchar2(200);v_reservation number;v_new_reservation number;v_qty number;
  v_num number;v_den number;v_scale number;v_base varchar2(20);v_version number;
  type quantity_map is table of number index by varchar2(2000);v_balances quantity_map;v_target_reservations quantity_map;
  type identity_map is table of varchar2(200) index by varchar2(2000);v_targets identity_map;
  v_source_key varchar2(2000);v_target_key varchar2(2000);v_physical_uid varchar2(200);
  function projected(p_uid varchar2,p_cell varchar2) return number is k varchar2(2000);n number;
  begin
   k:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid,p_cell));
   if not v_balances.exists(k) then
    begin select REMAIN into n from RRL_REMAINS where UID_POLETA=p_uid and CELL=p_cell;exception when no_data_found then n:=0;end;
    v_balances(k):=n;
   end if;
   return v_balances(k);
  end;

 begin
  s:=d.get_object('source');ids:=s.get_array('movement_ids');
  if ids is null or ids.get_size<1 or ids.get_size>200 then raise_application_error(-20871,'MES_MOVEMENT_BATCH_SIZE');end if;
  declare
 v_json_sql_1_1 number:=s.get_number('production_order_id');
begin
select * into o from RRL_PRODUCTION_ORDER where PRODUCTION_ORDER_ID=v_json_sql_1_1;
end;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRODUCTION_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(o.PRODUCTION_ORDER_ID));
  for i in 0..ids.get_size-1 loop
   v_id:=ids.get_number(i);select * into m from RRL_MES_MOVEMENT where MOVEMENT_ID=v_id;
   if m.PRODUCTION_ORDER_ID!=o.PRODUCTION_ORDER_ID or m.UID_PALLET is null
    or m.MOVEMENT_TYPE not in('RAW_ISSUE_TO_PRODUCTION','RAW_CONSUMPTION','FG_PALLET_RELEASE') then
    raise_application_error(-20886,'MES_MOVEMENT_IDENTITY_CONFLICT');end if;
   v_physical_uid:=m.UID_PALLET;
   v_source_key:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',m.UID_PALLET,m.SOURCE_LOCATION));
   if m.MOVEMENT_TYPE='RAW_CONSUMPTION' and v_targets.exists(v_source_key) then v_physical_uid:=v_targets(v_source_key);end if;
   if m.MOVEMENT_TYPE='FG_PALLET_RELEASE' then v_article:=o.TARGET_ARTICUL;
   else select ARTICUL into v_article from RRL_PALLETS where UID_PALLET=m.UID_PALLET;end if;
   select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=m.UNIT_CODE;
   select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into v_base,v_num,v_den,v_scale
    from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=m.UNIT_CODE and POLICY_VERSION=v_version;
   v_qty:=RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(m.QUANTITY),v_num,v_den,v_scale);
   select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_base and BASE_UOM=v_base and NUMERATOR=1 and DENOMINATOR=1;
   if v_version is null then raise_application_error(-20868,'MES_BASE_POLICY_REQUIRED');end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_MES_MOVEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v_physical_uid,v_article,
    case when m.MOVEMENT_TYPE!='FG_PALLET_RELEASE' then m.SOURCE_LOCATION end,
    case when m.MOVEMENT_TYPE!='RAW_CONSUMPTION' then m.TARGET_LOCATION end);
   v_target:=v_physical_uid;v_reservation:=null;v_new_reservation:=null;v_p:=null;
   if m.MOVEMENT_TYPE='RAW_ISSUE_TO_PRODUCTION' then
    v_p:=projected(v_physical_uid,m.SOURCE_LOCATION);
    if v_qty<v_p then
     v_target:='PART:'||substr(rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation||':'||RRL_STOCK_PLAN_HELPER.decimal_text(v_id),'AL32UTF8'),sys.dbms_crypto.hash_sh256)),1,64);
     select RRL_STOCK_RESERVATION_SQ.nextval into v_new_reservation from dual;
     RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(v_new_reservation));
     RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v_target);RRL_STOCK_PLAN_HELPER.anchor(r,50,'STOCK',v_target);
     RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','PALLET:'||v_target);
    end if;
   end if;
   if m.MOVEMENT_TYPE!='FG_PALLET_RELEASE' then
    begin select RESERVATION_ID into v_reservation from RRL_STOCK_RESERVATION where UID_PALLET=m.UID_PALLET and CELL=m.SOURCE_LOCATION
     and SOURCE_DOC_TYPE='PRODUCTION_ORDER' and SOURCE_DOC_ID=o.PRODUCTION_ORDER_ID and RESERVATION_KIND='HARD'
     and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_QTY>=v_qty;
    exception when no_data_found then null;when too_many_rows then raise_application_error(-20869,'MES_RESERVATION_AMBIGUOUS');end;
   else RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','PALLET:'||m.UID_PALLET);end if;
   if m.MOVEMENT_TYPE='RAW_CONSUMPTION' and v_target_reservations.exists(v_source_key) then v_reservation:=v_target_reservations(v_source_key);end if;
   if m.MOVEMENT_TYPE='RAW_ISSUE_TO_PRODUCTION' then
    v_source_key:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',v_physical_uid,m.SOURCE_LOCATION));
    v_balances(v_source_key):=projected(v_physical_uid,m.SOURCE_LOCATION)-v_qty;
    v_target_key:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',v_target,m.TARGET_LOCATION));
    v_balances(v_target_key):=projected(v_target,m.TARGET_LOCATION)+v_qty;
    v_target_key:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',m.UID_PALLET,m.TARGET_LOCATION));
    if v_targets.exists(v_target_key) and v_targets(v_target_key)!=v_target then
     raise_application_error(-20886,'MES_CONSUMPTION_REQUIRES_PHYSICAL_PALLET_ALLOCATION');end if;
    v_targets(v_target_key):=v_target;
    if v_reservation is not null then v_target_reservations(v_target_key):=case when v_target=m.UID_PALLET then v_reservation else v_new_reservation end;end if;
   elsif m.MOVEMENT_TYPE='RAW_CONSUMPTION' then
    v_source_key:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',v_physical_uid,m.SOURCE_LOCATION));
    if projected(v_physical_uid,m.SOURCE_LOCATION)<v_qty then raise_application_error(-20868,'MES_CONSUMPTION_STOCK_INSUFFICIENT');end if;
    v_balances(v_source_key):=v_balances(v_source_key)-v_qty;
   end if;
   v:=json_object_t();v.put('physical_uid',v_physical_uid);v.put('movement_id',v_id);v.put('signature',signature(m));v.put('article',v_article);
   v.put('base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));v.put('base_uom',v_base);v.put('uom_version',v_version);
   v.put('source_p',case when v_p is not null then RRL_STOCK_PLAN_HELPER.decimal_text(v_p) end);
   v.put('target_uid',v_target);v.put('reservation_id',v_reservation);v.put('new_reservation_id',v_new_reservation);a.append(v);
  end loop;
  h.put('production_order_id',o.PRODUCTION_ORDER_ID);h.put('movements',a);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=h.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_MES_SUPPLY_CMD as
 function nonnegative(p_text varchar2) return number is
 begin if p_text='0' then return 0;end if;return RRL_STOCK_MATH.quantity(p_text);end;

 function convert_qty(p_article varchar2,p_unit varchar2,p_qty number,p_base out varchar2) return number is
  n number;dn number;sc number;ver number;
 begin
  if p_qty is null or p_qty<0 then raise_application_error(-20869,'MES_QUANTITY_INVALID');end if;
  select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM=p_unit;
  if ver is null then raise_application_error(-20868,'MES_UOM_REQUIRED');end if;
  select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into p_base,n,dn,sc from RRL_STOCK_UOM_CONVERSION
   where ARTICUL=p_article and INPUT_UOM=p_unit and POLICY_VERSION=ver;
  if p_qty=0 then return 0;end if;
  return RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(p_qty),n,dn,sc);
 end;
 function lines_json(p_order number) return clob is a json_array_t:=json_array_t();x json_object_t;
  req number;iss number;b varchar2(20);mb varchar2(20);n number;
 begin
  for l in(select * from RRL_PROD_ORDER_BOM_LINE where PRODUCTION_ORDER_ID=p_order and COMPONENT_ARTICUL is not null order by ORDER_LINE_ID) loop
   if a.get_size>=200 then raise_application_error(-20881,'MES_BOM_BATCH_BOUND');end if;
   req:=convert_qty(l.COMPONENT_ARTICUL,l.UNIT_CODE,l.PLANNED_QTY,b);iss:=0;
   for m in(select BOM_LINE_ID,QUANTITY,UNIT_CODE from RRL_MES_MOVEMENT where PRODUCTION_ORDER_ID=p_order and MOVEMENT_TYPE='RAW_ISSUE_TO_PRODUCTION'
    and STATUS<>'CANCELLED' and RAW_ARTICUL=l.COMPONENT_ARTICUL and (BOM_LINE_ID=l.BOM_LINE_ID or BOM_LINE_ID is null)) loop
    if m.BOM_LINE_ID is null then
     select count(*) into n from RRL_PROD_ORDER_BOM_LINE where PRODUCTION_ORDER_ID=p_order and COMPONENT_ARTICUL=l.COMPONENT_ARTICUL;
     if n!=1 then raise_application_error(-20869,'MES_ISSUED_BOM_LINE_AMBIGUOUS');end if;
    end if;
    iss:=iss+convert_qty(l.COMPONENT_ARTICUL,m.UNIT_CODE,m.QUANTITY,mb);
    if mb!=b then raise_application_error(-20868,'MES_BASE_UOM_CONFLICT');end if;
   end loop;
   x:=json_object_t();x.put('line',l.ORDER_LINE_ID);x.put('bom',l.BOM_ID);x.put('bom_line',l.BOM_LINE_ID);x.put('article',l.COMPONENT_ARTICUL);
   x.put('required',RRL_STOCK_PLAN_HELPER.decimal_text(req));x.put('issued',RRL_STOCK_PLAN_HELPER.decimal_text(iss));x.put('base',b);a.append(x);
  end loop;return a.to_clob;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t:=json_object_t();x json_object_t;y json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;b json_array_t:=json_array_t();oldsr json_array_t:=json_array_t();
  doc number;task number;sr number;wid number;id number;qty number;remainq number;freeq number;total number;ware number;target varchar2(60);
  base varchar2(20);ver number;pending number;raw clob;
  type qty_map is table of number index by varchar2(2000);used qty_map;k varchar2(2000);
 begin
  doc:=d.get_object('source').get_number('production_order_id');target:=d.get_object('metadata').get_string('to_cell');
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRODUCTION_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(doc));
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  select count(*) into pending from RRL_MES_RAW_TRANSFER_TASK where PRODUCTION_ORDER_ID=doc and TASK_STATUS in('PLANNED','IN_PROGRESS');
  v.put('pending',pending);v.put('document',doc);
  if pending=0 then
   if d.get_string('command_type')='MES_RELEASE_TO_PRODUCTION' then
   select WARE_ID into ware from RRL_CELLS where CELL=target;
   if d.get_object('metadata').get_number('to_ware_id') is not null and d.get_object('metadata').get_number('to_ware_id')!=ware then raise_application_error(-20869,'MES_TARGET_WARE_CONFLICT');end if;
   RRL_STOCK_PLAN_HELPER.fence(f,'CELL',target);end if;v.put('target',target);v.put('warehouse',ware);
   raw:=lines_json(doc);a:=json_array_t.parse(raw);v.put('signature',rawtohex(sys.dbms_crypto.hash(raw,sys.dbms_crypto.hash_sh256)));
   for s in(select * from RRL_STOCK_RESERVATION where SOURCE_DOC_TYPE='PRODUCTION_ORDER' and SOURCE_DOC_ID=doc and RESERVATION_KIND='SOFT' and STATUS in('ACTIVE','ALLOCATED')) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(s.RESERVATION_ID));x:=json_object_t();x.put('id',s.RESERVATION_ID);x.put('version',s.RESERVATION_VERSION);oldsr.append(x);
   end loop;
   for i in 0..a.get_size-1 loop
    x:=treat(a.get(i) as json_object_t);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PROD_ORDER_BOM_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('line')));
    RRL_STOCK_PLAN_HELPER.fence(f,'SKU',x.get_string('article'));
    select RRL_MES_RAW_DEMAND_SQ.nextval into id from dual;x.put('demand',id);
    remainq:=greatest(nonnegative(x.get_string('required'))-nonnegative(x.get_string('issued')),0);
    x.put('open',RRL_STOCK_PLAN_HELPER.decimal_text(remainq));x.put_null('soft');
    if remainq>0 then select RRL_STOCK_RESERVATION_SQ.nextval into sr from dual;x.put('soft',sr);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(sr));end if;
    declare
 v_json_sql_1_1 varchar2(32767):=x.get_string('article');
begin
for c in(select rr.UID_POLETA,rr.CELL,rr.REMAIN,rr.HARD_RESERVED_BASE,rr.BASE_UOM,cc.WARE_ID
     from RRL_REMAINS rr join RRL_PALLETS pp on pp.UID_PALLET=rr.UID_POLETA join RRL_CELLS cc on cc.CELL=rr.CELL join RRL_WARES ww on ww.ID=cc.WARE_ID
     where pp.ARTICUL=v_json_sql_1_1 and ww.FLAG_RAW_MATERIAL=1 and rr.REMAIN>rr.HARD_RESERVED_BASE
      and nvl(cc.BLOCKED_FOR_REMAINS,0)=0 and nvl(cc.BLOCKED_FOR_POPOLNENIE,0)=0 and (target is null or rr.CELL!=target)
     order by pp.EXPIRY_DATE nulls last,pp.PRODUCED_DATE nulls last,rr.CELL,rr.UID_POLETA) loop
     exit when remainq=0;if b.get_size>=1000 then raise_application_error(-20881,'MES_ALLOCATION_BATCH_BOUND');end if;
     if c.BASE_UOM!=x.get_string('base') then raise_application_error(-20868,'MES_SOURCE_BASE_CONFLICT');end if;
     k:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',c.UID_POLETA,c.CELL));if not used.exists(k) then used(k):=0;end if;
     freeq:=c.REMAIN-c.HARD_RESERVED_BASE-used(k);if freeq<=0 then continue;end if;
     qty:=least(freeq,remainq);used(k):=used(k)+qty;remainq:=remainq-qty;
     declare
 v_json_sql_1_1 varchar2(32767):=x.get_string('article');
begin
select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_json_sql_1_1 and INPUT_UOM=c.BASE_UOM and BASE_UOM=c.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
end;
     if ver is null then raise_application_error(-20868,'MES_BASE_POLICY_REQUIRED');end if;
     select RRL_STOCK_RESERVATION_SQ.nextval,RRL_MES_RAW_TRANSFER_TASK_SQ.nextval,RRL_WAREHOUSE_TASK_SQ.nextval,RRL_MES_RAW_SUPPLY_CANDIDATE_SQ.nextval into sr,task,wid,id from dual;
     RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(sr));
     RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_MES_RAW_TRANSFER_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(task));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(wid));
     RRL_STOCK_PLAN_HELPER.stock_closure(f,r,c.UID_POLETA,x.get_string('article'),c.CELL,null);
     y:=json_object_t();y.put('demand',x.get_number('demand'));y.put('reservation',sr);y.put('task',task);y.put('warehouse_task',wid);y.put('candidate',id);
     y.put('uid',c.UID_POLETA);y.put('cell',c.CELL);y.put('ware',c.WARE_ID);y.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));y.put('physical',RRL_STOCK_PLAN_HELPER.decimal_text(c.REMAIN));
     y.put('hard',RRL_STOCK_PLAN_HELPER.decimal_text(c.HARD_RESERVED_BASE));y.put('uom_version',ver);y.put('line_index',i);b.append(y);
    end loop;
end;
    x.put('shortage',RRL_STOCK_PLAN_HELPER.decimal_text(remainq));
    if remainq>0 then select RRL_MES_RAW_SHORTAGE_SQ.nextval into id from dual;x.put('shortage_id',id);end if;
    a.put(i,x);
   end loop;
   v.put('lines',a);v.put('allocations',b);v.put('old_soft',oldsr);
  end if;
  p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;x json_object_t;y json_object_t;detail json_object_t;result json_object_t:=json_object_t();
  plan clob;a json_array_t;b json_array_t;oldsr json_array_t;doc number;pending number;qty number;req number;iss number;oq number;shortq number;n number;cnt number:=0;physical number;hard number;
  status varchar2(40);raw clob;unitkeys clob;pal RRL_PALLETS%rowtype;old RRL_STOCK_RESERVATION%rowtype;
 begin
  if (d.get_string('command_type')='MES_CALCULATE_SUPPLY' and RRL_HAS_WRIGHT(p_actor,'mes_raw_supply_calculate')!=1) or (d.get_string('command_type')='MES_RELEASE_TO_PRODUCTION' and RRL_HAS_WRIGHT(p_actor,'mes_raw_transfer_create')!=1) then raise_application_error(-20882,'MES_SUPPLY_FORBIDDEN');end if;
  declare
 v_json_sql_2_1 varchar2(32767):=d.get_string('operation_id');
begin
select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_2_1;
end;v:=json_object_t.parse(plan).get_object('domain');doc:=v.get_number('document');
  select STATUS into status from RRL_PRODUCTION_ORDER where PRODUCTION_ORDER_ID=doc for update;
  if status is null or status in('COMPLETED','CANCELLED') then raise_application_error(-20886,'MES_ORDER_NOT_OPEN');end if;
  select count(*) into pending from RRL_MES_RAW_TRANSFER_TASK where PRODUCTION_ORDER_ID=doc and TASK_STATUS in('PLANNED','IN_PROGRESS');
  if pending!=v.get_number('pending') then raise_application_error(-20890,'CLOSURE_CHANGED: MES pending tasks');end if;
  if pending>0 then
   select count(*) into n from RRL_MES_RAW_DEMAND where PRODUCTION_ORDER_ID=doc;result.put('demand_count',n);
   select count(*) into n from RRL_MES_RAW_SUPPLY_CANDIDATE where PRODUCTION_ORDER_ID=doc;result.put('candidate_count',n);
   select count(*) into n from RRL_MES_RAW_SHORTAGE where PRODUCTION_ORDER_ID=doc and STATUS='OPEN';result.put('shortage_count',n);
   result.put('task_count',pending);result.put('existing',1);p_result:=result.to_clob;return;end if;
  a:=v.get_array('lines');b:=v.get_array('allocations');oldsr:=v.get_array('old_soft');
  for i in 0..a.get_size-1 loop x:=treat(a.get(i) as json_object_t);declare
 v_json_sql_3_1 number:=x.get_number('line');
begin
select ORDER_LINE_ID into n from RRL_PROD_ORDER_BOM_LINE where ORDER_LINE_ID=v_json_sql_3_1 for update;
end;end loop;
  raw:=lines_json(doc);if rawtohex(sys.dbms_crypto.hash(raw,sys.dbms_crypto.hash_sh256))!=v.get_string('signature') then raise_application_error(-20890,'CLOSURE_CHANGED: MES requirements');end if;
  if d.get_string('command_type')='MES_RELEASE_TO_PRODUCTION' then RRL_STOCK_LOCATION_CORE.assert_ordinary(v.get_string('target'),v.get_number('warehouse'),'TARGET');end if;
  for i in 0..b.get_size-1 loop
   y:=treat(b.get(i) as json_object_t);
   declare
 v_json_sql_4_1 varchar2(32767):=y.get_string('uid');
 v_json_sql_4_2 varchar2(32767):=y.get_string('cell');
begin
select REMAIN,HARD_RESERVED_BASE into physical,hard from RRL_REMAINS where UID_POLETA=v_json_sql_4_1 and CELL=v_json_sql_4_2;
end;
   if physical!=RRL_STOCK_MATH.quantity(y.get_string('physical')) or hard!=nonnegative(y.get_string('hard')) then raise_application_error(-20890,'CLOSURE_CHANGED: MES source availability');end if;
  end loop;
  for i in 0..oldsr.get_size-1 loop
   x:=treat(oldsr.get(i) as json_object_t);declare
 v_json_sql_5_1 number:=x.get_number('id');
begin
select * into old from RRL_STOCK_RESERVATION where RESERVATION_ID=v_json_sql_5_1 for update;
end;
   if old.RESERVATION_VERSION!=x.get_number('version') or old.RESERVATION_KIND!='SOFT' or old.STATUS not in('ACTIVE','ALLOCATED') then raise_application_error(-20890,'CLOSURE_CHANGED: MES soft demand');end if;
   RRL_STOCK_CTX_API.begin_effect('RESERVATION',null,null,old.RESERVATION_ID);
   update RRL_STOCK_RESERVATION set STATUS='CANCELLED',RELEASED_AT=systimestamp,RELEASED_BY=p_actor,RELEASE_REASON='MES raw supply recalculation',RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=old.RESERVATION_ID;RRL_STOCK_CTX_API.end_effect;
  end loop;
  delete from RRL_MES_RAW_SUPPLY_CANDIDATE where PRODUCTION_ORDER_ID=doc;delete from RRL_MES_RAW_SHORTAGE where PRODUCTION_ORDER_ID=doc;delete from RRL_MES_RAW_DEMAND where PRODUCTION_ORDER_ID=doc;
  shortq:=0;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);req:=nonnegative(x.get_string('required'));iss:=nonnegative(x.get_string('issued'));oq:=nonnegative(x.get_string('open'));qty:=nonnegative(x.get_string('shortage'));
   if oq>0 then
    RRL_STOCK_CTX_API.begin_effect('RESERVATION',null,null,x.get_number('soft'));
    declare
 v_json_sql_6_1 number:=x.get_number('soft');
 v_json_sql_6_2 number:=x.get_number('line');
 v_json_sql_6_3 varchar2(32767):=x.get_string('article');
 v_json_sql_6_4 varchar2(32767):=x.get_string('base');
begin
insert into RRL_STOCK_RESERVATION(RESERVATION_ID,RESERVATION_KIND,RESERVATION_SCOPE,RESERVATION_DOMAIN,SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_LINE_ID,PRODUCTION_ORDER_ID,ARTICUL,QTY,UNIT_CODE,STATUS,PRIORITY,CREATED_BY,RESERVATION_VERSION)
     values(v_json_sql_6_1,'SOFT','QTY','MES_RAW','PRODUCTION_ORDER',doc,v_json_sql_6_2,doc,v_json_sql_6_3,oq,v_json_sql_6_4,'ACTIVE',100,p_actor,0);
end;RRL_STOCK_CTX_API.end_effect;
   end if;
   declare
 v_json_sql_7_1 number:=x.get_number('demand');
 v_json_sql_7_2 number:=x.get_number('line');
 v_json_sql_7_3 number:=x.get_number('bom');
 v_json_sql_7_4 number:=x.get_number('bom_line');
 v_json_sql_7_5 varchar2(32767):=x.get_string('article');
 v_json_sql_7_6 varchar2(32767):=x.get_string('base');
 v_json_sql_7_7 number:=x.get_number('soft');
begin
insert into RRL_MES_RAW_DEMAND(DEMAND_ID,PRODUCTION_ORDER_ID,ORDER_LINE_ID,BOM_ID,BOM_LINE_ID,RAW_ARTICUL,REQUIRED_QTY,ISSUED_QTY,OPEN_QTY,UNIT_CODE,SOFT_RESERVATION_ID,STATUS,CALCULATED_BY)
    values(v_json_sql_7_1,doc,v_json_sql_7_2,v_json_sql_7_3,v_json_sql_7_4,v_json_sql_7_5,req,iss,oq,v_json_sql_7_6,v_json_sql_7_7,case when oq>0 then 'OPEN' else 'COVERED' end,p_actor);
end;
   if qty>0 then
    shortq:=shortq+1;
    declare
 v_json_sql_8_1 number:=x.get_number('shortage_id');
 v_json_sql_8_2 number:=x.get_number('demand');
 v_json_sql_8_3 varchar2(32767):=x.get_string('article');
 v_json_sql_8_4 varchar2(32767):=x.get_string('base');
begin
insert into RRL_MES_RAW_SHORTAGE(SHORTAGE_ID,PRODUCTION_ORDER_ID,DEMAND_ID,RAW_ARTICUL,REQUIRED_QTY,ISSUED_QTY,AVAILABLE_QTY,SHORTAGE_QTY,UNIT_CODE,STATUS)
     values(v_json_sql_8_1,doc,v_json_sql_8_2,v_json_sql_8_3,req,iss,oq-qty,qty,v_json_sql_8_4,'OPEN');
end;
   end if;
  end loop;
  for i in 0..b.get_size-1 loop
   y:=treat(b.get(i) as json_object_t);x:=treat(a.get(y.get_number('line_index')) as json_object_t);qty:=RRL_STOCK_MATH.quantity(y.get_string('quantity'));
   declare
 v_json_sql_9_1 varchar2(32767):=y.get_string('uid');
begin
select * into pal from RRL_PALLETS where UID_PALLET=v_json_sql_9_1;
end;
   if pal.ARTICUL!=x.get_string('article') then raise_application_error(-20890,'CLOSURE_CHANGED: MES source article');end if;
   RRL_STOCK_LOCATION_CORE.assert_ordinary(y.get_string('cell'),y.get_number('ware'),'SOURCE');
   physical:=RRL_STOCK_MATH.quantity(y.get_string('physical'));hard:=nonnegative(y.get_string('hard'));req:=nonnegative(x.get_string('required'));
   declare
 v_json_sql_10_1 number:=y.get_number('candidate');
 v_json_sql_10_2 number:=x.get_number('demand');
 v_json_sql_10_3 varchar2(32767):=x.get_string('article');
 v_json_sql_10_4 number:=y.get_number('ware');
 v_json_sql_10_5 varchar2(32767):=y.get_string('cell');
begin
insert into RRL_MES_RAW_SUPPLY_CANDIDATE(CANDIDATE_ID,DEMAND_ID,PRODUCTION_ORDER_ID,RAW_ARTICUL,UID_PALLET,BATCH_ID,RAW_BATCH_ID,SSCC,FROM_WARE_ID,FROM_CELL,PHYSICAL_QTY,HARD_RESERVED_QTY,AVAILABLE_QTY,SUGGESTED_QTY,EXPIRY_DATE,QUALITY_STATUS,SORT_ORDER)
    values(v_json_sql_10_1,v_json_sql_10_2,doc,v_json_sql_10_3,pal.UID_PALLET,to_char(pal.PRIHOD_NAKLAD_ID),pal.PRIHOD_NAKLAD_ID,pal.SSCC,v_json_sql_10_4,v_json_sql_10_5,physical,hard,qty,qty,pal.EXPIRY_DATE,pal.QUALITY_STATUS,i+1);
end;
   if d.get_string('command_type')='MES_RELEASE_TO_PRODUCTION' and (shortq=0 or d.get_object('metadata').get_number('allow_partial')=1) then
    detail:=json_object_t();detail.put('reservation_scope','QTY');detail.put('task_id',y.get_number('task'));detail.put('production_order_id',doc);detail.put('batch_id',to_char(pal.PRIHOD_NAKLAD_ID));
    RRL_STOCK_RESERVE_CORE.create_hard(y.get_number('reservation'),pal.UID_PALLET,y.get_string('cell'),qty,x.get_string('base'),y.get_number('uom_version'),'PRODUCTION_ORDER',doc,x.get_number('line'),'MES_RAW',p_actor,detail.to_clob);
    unitkeys:=RRL_STOCK_UNIT_CORE.automatic_units(pal.UID_PALLET,y.get_string('cell'),qty);RRL_STOCK_UNIT_CORE.reserve_units(pal.UID_PALLET,y.get_string('cell'),y.get_number('reservation'),qty,unitkeys);
    declare
 v_json_sql_11_1 number:=y.get_number('task');
 v_json_sql_11_2 number:=x.get_number('line');
 v_json_sql_11_3 number:=x.get_number('bom');
 v_json_sql_11_4 number:=x.get_number('bom_line');
 v_json_sql_11_5 varchar2(32767):=x.get_string('article');
 v_json_sql_11_6 number:=y.get_number('ware');
 v_json_sql_11_7 varchar2(32767):=y.get_string('cell');
 v_json_sql_11_8 number:=v.get_number('warehouse');
 v_json_sql_11_9 varchar2(32767):=v.get_string('target');
 v_json_sql_11_10 varchar2(32767):=x.get_string('base');
 v_json_sql_11_11 number:=y.get_number('reservation');
begin
insert into RRL_MES_RAW_TRANSFER_TASK(TASK_ID,PRODUCTION_ORDER_ID,ORDER_LINE_ID,BOM_ID,BOM_LINE_ID,RAW_ARTICUL,RAW_BATCH_ID,BATCH_ID,UID_PALLET,SSCC,FROM_WARE_ID,FROM_CELL,TO_WARE_ID,TO_CELL,REQUIRED_QTY,TASK_QTY,UNIT_CODE,RESERVATION_ID,TASK_STATUS,PRIORITY,CREATED_BY)
     values(v_json_sql_11_1,doc,v_json_sql_11_2,v_json_sql_11_3,v_json_sql_11_4,v_json_sql_11_5,pal.PRIHOD_NAKLAD_ID,to_char(pal.PRIHOD_NAKLAD_ID),pal.UID_PALLET,pal.SSCC,v_json_sql_11_6,v_json_sql_11_7,v_json_sql_11_8,v_json_sql_11_9,req,qty,v_json_sql_11_10,v_json_sql_11_11,'PLANNED',100,p_actor);
end;
    declare
 v_json_sql_12_1 number:=y.get_number('warehouse_task');
 v_json_sql_12_2 number:=y.get_number('task');
 v_json_sql_12_3 varchar2(32767):=x.get_string('article');
 v_json_sql_12_4 number:=y.get_number('ware');
 v_json_sql_12_5 varchar2(32767):=y.get_string('cell');
 v_json_sql_12_6 number:=v.get_number('warehouse');
 v_json_sql_12_7 varchar2(32767):=v.get_string('target');
 v_json_sql_12_8 varchar2(32767):=x.get_string('base');
begin
insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,SOURCE_DOC_ID,PRODUCTION_ORDER_ID,RAW_ARTICUL,UID_PALLET,SSCC,FROM_WARE_ID,FROM_CELL,TO_WARE_ID,TO_CELL,QTY,UNIT_CODE,QTY_MODE,PRIORITY,STATUS,CREATED_AT,CREATED_BY)
     values(v_json_sql_12_1,'RAW_TO_PRODUCTION','MES_RAW_SUPPLY',v_json_sql_12_2,'PRODUCTION_ORDER',doc,doc,v_json_sql_12_3,pal.UID_PALLET,pal.SSCC,v_json_sql_12_4,v_json_sql_12_5,v_json_sql_12_6,v_json_sql_12_7,qty,v_json_sql_12_8,'QTY',100,'PLANNED',systimestamp,p_actor);
end;cnt:=cnt+1;
   end if;
  end loop;
  if cnt>0 then update RRL_PRODUCTION_ORDER set STATUS=case when STATUS='DRAFT' then 'RELEASED' else STATUS end,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where PRODUCTION_ORDER_ID=doc;end if;
  result.put('operation_id',d.get_string('operation_id'));result.put('task_count',cnt);result.put('shortage_count',shortq);result.put('demand_count',a.get_size);result.put('candidate_count',b.get_size);p_result:=result.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_METADATA_TX as

 procedure begin_change(p_actor varchar2,p_permission varchar2) is

  f json_array_t:=json_array_t();r json_array_t:=json_array_t();state varchar2(20);

 begin

  if p_actor is null or p_permission is null or p_permission not in('pick_wave_launch','inventory_task_execute','warehouse_task_execute','warehouse_task_assign','warehouse_task_edit','case_pick_manage','case_pick_execute','case_pick_short_approve','outgoing_pallet_edit','warehouse_return_dispatch','store_return_approve','transport_dispatch_edit','warehouse_settings_edit','trace_manifest_import','resource_shift_edit','customer_rule_edit','sap_store_decision_import')

   or RRL_HAS_WRIGHT(p_actor,p_permission)!=1 then raise_application_error(-20882,'TASK_METADATA_FORBIDDEN');end if;

  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE',6);

  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_POLICY_GUARD','WAREHOUSE.METADATA');

  RRL_STOCK_LOCK_API.begin_plan;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(r.to_clob);

  select STATE into state from RRL_STOCK_RELEASE where RELEASE_ID=1;

  if state is null or state not in('PREPARED','ACTIVE') then raise_application_error(-20860,'TASK_METADATA_RELEASE_CLOSED');end if;

 end;

 procedure end_change is begin RRL_STOCK_LOCK_API.clear_plan;end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_MOVE_CORE as
 procedure manual_whole(p_request clob,p_actor varchar2,p_result out clob) is
  v_doc json_object_t:=json_object_t.parse(p_request);v_source json_object_t;v_lines json_array_t;
  v_line json_object_t;v_result json_object_t:=json_object_t();v_facts json_array_t:=json_array_t();v_fact json_object_t;
  v_uid varchar2(200);v_article varchar2(160);v_actual varchar2(160);v_from varchar2(60);v_to varchar2(60);
  v_unit varchar2(20);v_base varchar2(20);v_sscc varchar2(32);v_quality varchar2(40);v_warehouse number;
  v_n number;v_q number;v_p number;v_h number;v_version number;v_num number;v_den number;v_scale number;
  v_policy number;v_marked number;v_event_from number;v_event_to number;v_line_no number;v_expected number;
  type seen_set is table of boolean index by varchar2(200);
  v_seen seen_set;v_line_seen seen_set;v_compat varchar2(20);
 begin
  v_doc.on_error(1);
  if v_doc.get_string('command_type')='COMPAT_MANUAL_MOVE' then
   select nvl(max(SETTING_VALUE),'0') into v_compat from RRL_SYSTEM_SETTINGS where SETTING_KEY='STOCK_LEGACY_TRIGGER_ENABLED';
   if v_compat!='1' then raise_application_error(-20863,'LEGACY_STOCK_POSTING_DISABLED');end if;
  end if;
  if RRL_HAS_WRIGHT(p_actor,'stock_posting_manual_move')!=1 then raise_application_error(-20882,'MANUAL_MOVE_FORBIDDEN'); end if;
  v_source:=v_doc.get_object('source');v_source.on_error(1);
  if v_source.get_string('type') is null or v_source.get_string('type')!='MANUAL' or v_source.get_string('reason') is null
   or length(v_source.get_string('reason'))>1000 then raise_application_error(-20883,'MANUAL_SOURCE_REQUIRED'); end if;
  v_warehouse:=v_source.get_number('warehouse_id');
  if v_warehouse is null or v_warehouse<1 or v_warehouse!=trunc(v_warehouse) then raise_application_error(-20883,'WAREHOUSE_REQUIRED'); end if;
  if v_doc.get_array('units').get_size!=0 then raise_application_error(-20884,'COMPOSITION_HANDLER_REQUIRED'); end if;
  v_lines:=v_doc.get_array('lines');
  for i in 0..v_lines.get_size-1 loop
   v_line:=treat(v_lines.get(i) as json_object_t);v_line.on_error(1);
   v_uid:=v_line.get_string('uid');v_article:=v_line.get_string('article');
   v_from:=v_line.get_string('source_cell');v_to:=v_line.get_string('target_cell');
   v_unit:=v_line.get_string('unit');v_line_no:=v_line.get_number('line_number');
   if v_line_no is null or v_line_no<1 or v_line_no!=trunc(v_line_no)
    or v_line_seen.exists(to_char(v_line_no,'TM9')) then raise_application_error(-20881,'COMMAND_LINE_ID_INVALID'); end if;
   v_line_seen(to_char(v_line_no,'TM9')):=true;
   if v_seen.exists(v_uid) then raise_application_error(-20885,'PALLET_REPEATED'); end if;
   v_seen(v_uid):=true;
   if v_from=v_to or v_line.get_string('target_uid') is null or v_line.get_string('target_uid')!=v_uid
    or v_line.get_string('reservation_action') is null or v_line.get_string('reservation_action')!='NONE' or not v_line.get('reservation_id').is_null then
    raise_application_error(-20886,'DEDICATED_MOVE_HANDLER_REQUIRED');
   end if;
   RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',v_uid));
   RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',v_uid));
   RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('SKU',v_article),4);
   select ARTICUL,SSCC,QUALITY_STATUS into v_actual,v_sscc,v_quality from RRL_PALLETS where UID_PALLET=v_uid;
   if v_actual!=v_article or v_actual is null then raise_application_error(-20887,'PALLET_ARTICLE_CONFLICT'); end if;

   -- Fail closed: no guessed regulatory status and no rebuilding of existing composition.
   select MARKING_REQUIRED into v_marked from RRL_SKU_RECEIPT_POLICY where ARTICUL=v_article;
   select count(*) into v_n from RRL_SKU_RECEIPT_PROFILE where ARTICUL=v_article;
   if v_marked!=0 or v_marked is null or v_n!=0 then raise_application_error(-20884,'MARKED_HANDLER_REQUIRED'); end if;
   select count(*) into v_n from RRL_WMS_RECEIPT_UNIT where UID_PALLET=v_uid;
   if v_n!=0 then raise_application_error(-20884,'UNIT_HANDLER_REQUIRED'); end if;
   select count(*) into v_n from RRL_CRPT_AGGREGATION where UID_PALLET=v_uid or SSCC=v_sscc or PARENT_SSCC=v_sscc;
   if v_n!=0 then raise_application_error(-20884,'HU_HANDLER_REQUIRED'); end if;
   RRL_STOCK_LOCATION_CORE.assert_ordinary(v_from,v_warehouse,'SOURCE');
   RRL_STOCK_LOCATION_CORE.assert_ordinary(v_to,v_warehouse,'TARGET');
   select max(POLICY_VERSION) into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_unit;
   select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into v_base,v_num,v_den,v_scale
    from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_unit and POLICY_VERSION=v_policy;
   v_q:=RRL_STOCK_MATH.convert_exact(v_line.get_string('quantity'),v_num,v_den,v_scale);
   select max(POLICY_VERSION) into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_base and BASE_UOM=v_base and NUMERATOR=1 and DENOMINATOR=1;
   if v_policy is null then raise_application_error(-20868,'MANUAL_BASE_POLICY_REQUIRED');end if;
   select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION into v_p,v_h,v_version from RRL_REMAINS where UID_POLETA=v_uid and CELL=v_from;
   if v_line.has('expected_stock_version') and not v_line.get('expected_stock_version').is_null then
    v_expected:=v_line.get_number('expected_stock_version');
    if v_expected is null or v_expected!=v_version then raise_application_error(-20867,'VERSION_CONFLICT'); end if;
   end if;
   select count(*) into v_n from RRL_REMAINS where UID_POLETA=v_uid and CELL!=v_from and (REMAIN!=0 or HARD_RESERVED_BASE!=0);
   if v_n!=0 or v_p!=v_q or v_h!=0 then raise_application_error(-20886,'WHOLE_UNRESERVED_PALLET_REQUIRED'); end if;
   select count(*) into v_n from RRL_STOCK_RESERVATION where UID_PALLET=v_uid and RESERVATION_KIND='HARD'
    and STATUS in('ACTIVE','ALLOCATED','PICKING');
   if v_n!=0 then raise_application_error(-20886,'RESERVATION_HANDLER_REQUIRED'); end if;
   if sys_context('RRL_STOCK_WRITE_CTX','MODE')='EXPLICIT' then
   RRL_STOCK_BALANCE_CORE.apply_delta(v_uid,v_from,-v_q,0,v_base,v_policy,v_version);
   RRL_STOCK_BALANCE_CORE.apply_delta(v_uid,v_to,v_q,0,v_base,v_policy);
   end if;
   RRL_STOCK_BALANCE_CORE.write_move(v_uid,v_from,v_to,v_q,v_base,v_policy,v_line_no,p_actor,v_event_from);
   v_event_to:=v_event_from;
   v_fact:=json_object_t();v_fact.put('line_number',v_line_no);v_fact.put('uid',v_uid);
   v_fact.put('source_cell',v_from);v_fact.put('target_cell',v_to);v_fact.put('base_quantity',to_char(v_q,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''));
   v_fact.put('base_uom',v_base);v_fact.put('uom_policy_version',v_policy);
   v_fact.put('source_event_id',v_event_from);v_fact.put('target_event_id',v_event_to);v_facts.append(v_fact);
  end loop;
  v_result.put('operation_id',v_doc.get_string('operation_id'));v_result.put('command_type','MANUAL_MOVE');
  v_result.put('status','APPLIED');v_result.put('lines',v_facts);p_result:=v_result.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_NATIVE_API as
 procedure post(p_request clob,p_actor varchar2,p_result out clob) is
  v_attempt number:=0;v_started timestamp:=systimestamp;v_code number;
  v_committing boolean:=false;v_committed boolean:=false;v_cleanup_failed boolean;
  v_operation varchar2(100);
 begin
  if dbms_transaction.local_transaction_id(false) is not null then raise_application_error(-20862,'NATIVE_POST_REQUIRES_CLEAN_TRANSACTION');end if;
  v_operation:=json_object_t.parse(p_request).get_string('operation_id');
  loop
   v_attempt:=v_attempt+1;v_committed:=false;v_committing:=false;
   begin
    RRL_STOCK_POSTING_API.prepare_command(p_request,p_actor,p_result);
    if p_result is null then RRL_STOCK_POSTING_API.execute_prepared(p_result);end if;
    v_committing:=true;commit;v_committed:=true;v_committing:=false;
    RRL_STOCK_POSTING_API.reset_connection;return;
   exception when others then
    v_code:=sqlcode;v_cleanup_failed:=false;
    begin rollback;exception when others then v_cleanup_failed:=true;end;
    begin RRL_STOCK_POSTING_API.reset_connection;exception when others then v_cleanup_failed:=true;end;
    if v_committed then raise_application_error(-20892,'POSTED_CONNECTION_RESET_FAILED: '||v_operation||'; discard connection; recover same operation ID');end if;
    if v_committing then raise_application_error(-20891,'RESULT_UNCERTAIN: '||v_operation||'; discard connection; retry identical operation ID');end if;
    if v_cleanup_failed then raise_application_error(-20893,'CONNECTION_UNUSABLE: '||v_operation||'; discard connection; original code '||v_code);end if;
    if v_code not in(-60,-54,-30006,-20840,-20890) or v_attempt>=3 or systimestamp>v_started+interval '25' second then raise;end if;
    sys.dbms_lock.sleep(case when v_attempt=1 then 0.1 else 0.3 end);
   end;
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_OPERATION_CORE as
 procedure begin_operation(p_request clob,p_actor varchar2,p_operation varchar2,p_kind varchar2,p_replay out clob,p_plan clob default null) is
  v_saved clob;v_hash varchar2(64);v_actor varchar2(50);v_state varchar2(20);v_base varchar2(100);
 begin
  p_replay:=null;
  RRL_STOCK_LOCK_API.assert_held(10,RRL_STOCK_LOCK_API.resource_key('OP',p_operation));
  if p_request is null or dbms_lob.getlength(p_request)>4194304 or p_actor is null
   or length(p_actor)>50 or p_operation is null or length(p_operation)>100 then raise_application_error(-20871,'OPERATION_CONTRACT_INVALID'); end if;
  v_hash:=rawtohex(sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256));
  begin
   select CANONICAL_REQUEST,ACTOR,STATE,RESULT_JSON into v_saved,v_actor,v_state,p_replay
    from RRL_STOCK_OPERATION where OPERATION_ID=p_operation;
   if v_actor!=p_actor or dbms_lob.getlength(v_saved)!=dbms_lob.getlength(p_request)
    or dbms_lob.compare(v_saved,p_request)!=0 then raise_application_error(-20872,'OPERATION_CONFLICT'); end if;
   if v_state!='APPLIED' then raise_application_error(-20873,'UNFINISHED_OPERATION: unexpected committed envelope'); end if;
   return;
  exception when no_data_found then p_replay:=null;
  end;
  RRL_STOCK_CTX_API.open_operation(p_operation,case when p_kind='COMPAT_MANUAL_MOVE' then 'COMPAT' else 'EXPLICIT' end);
  select BASELINE_ID into v_base from RRL_STOCK_RELEASE where RELEASE_ID=1;
  if v_base is null then raise_application_error(-20874,'BASELINE_REQUIRED'); end if;
  insert into RRL_STOCK_OPERATION(OPERATION_ID,CONTRACT_VERSION,COMMAND_TYPE,ACTOR,REQUEST_HASH,
   CANONICAL_REQUEST,RESOLVED_PLAN_JSON,STATE,BASELINE_ID) values(p_operation,2,p_kind,p_actor,v_hash,p_request,p_plan,'IN_FLIGHT',v_base);
 end;
 procedure finish_operation(p_operation varchar2,p_result clob) is
 begin
  RRL_STOCK_LOCK_API.assert_held(10,RRL_STOCK_LOCK_API.resource_key('OP',p_operation));
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null or
   sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=p_operation or p_result is null then
   raise_application_error(-20863,'STOCK_WRITE_FORBIDDEN');
  end if;
  update RRL_STOCK_OPERATION set RESULT_JSON=p_result,STATE='APPLIED',APPLIED_AT=systimestamp
   where OPERATION_ID=p_operation and STATE='IN_FLIGHT';
  if sql%rowcount!=1 then raise_application_error(-20875,'OPERATION_FINISH_CONFLICT'); end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_PALLET_QC_CMD as
 procedure quality(p_request clob,p_id number,p_pass out number,p_ship out number,p_expected out number,p_tolerance out number,p_domain clob,p_reason out varchar2,p_unit_count out number,p_item_proved out number) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v_uid varchar2(150);
  v_errors number;v_gross number;v_wood number;auto_ship number;v_kind varchar2(20);
 begin
  v_uid:=d.get_object('source').get_string('pallet_identifier');v_kind:=m.get_string('quality_kind');
  -- Physical loading is an explicit root command; a QC success cannot prove loading.
  auto_ship:=0;
  p_pass:=0;p_ship:=0;p_expected:=null;p_tolerance:=null;p_reason:=null;p_unit_count:=0;p_item_proved:=0;
  if v_kind='PLAN' then return;elsif v_kind='SCAN' then
   v_errors:=m.get_number('error_count');
   if v_errors is null or v_errors<0 or v_errors!=trunc(v_errors) then raise_application_error(-20871,'QUALITY_ERROR_COUNT_INVALID');end if;
   if v_errors=0 then p_pass:=1;end if;
  elsif v_kind in('WEIGHT','WEIGHT2') then
   RRL_WH_FINAL_SCALE_ADMISSION.assert_capture(p_request,p_domain);
   v_gross:=RRL_STOCK_MATH.quantity(m.get_string('gross_weight'));v_wood:=case when regexp_like(m.get_string('wood_weight'),'^0([.]0{1,9})?$') then 0 else RRL_STOCK_MATH.quantity(m.get_string('wood_weight')) end;
   if v_gross<v_wood then raise_application_error(-20871,'QUALITY_NET_WEIGHT_NEGATIVE');end if;
   RRL_STOCK_QC_WEIGHT.calculate(p_domain,p_expected,p_tolerance);
   if p_tolerance is null or p_tolerance<=0 or p_expected is null or p_expected<0 then raise_application_error(-20887,'QUALITY_WEIGHT_POLICY_REQUIRED');end if;
   if abs(v_gross-v_wood-p_expected)<=p_tolerance then p_pass:=1;end if;
  else raise_application_error(-20871,'QUALITY_KIND_INVALID');end if;
  if p_pass=1 and v_kind='SCAN' then
   begin
    RRL_STOCK_QC_MARK.validate_scan(p_domain,m.to_clob,p_unit_count);
    if RRL_STOCK_QC_POLICY.full_scan_required(p_domain)=1 or(m.has('item_scans') and m.get_array('item_scans').get_size>0) then
     RRL_STOCK_QC_ITEM.validate_scan(p_domain,m.to_clob);p_item_proved:=1;
    end if;
   exception when others then
    if sqlcode in(-20871,-20886) and not instr(sqlerrm,'OUTGOING_CONTROL_PLAN_REQUIRED')>0 then
     p_pass:=0;p_unit_count:=0;p_item_proved:=0;p_reason:=regexp_substr(sqlerrm,'QUALITY_[A-Z0-9_]+');
    else raise;end if;
   end;
  end if;
  if p_pass=1 and auto_ship=1 and v_kind in('SCAN','WEIGHT2') then p_ship:=1;end if;
 end;
 procedure terminal_audit(p_request clob,p_uid varchar2) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');t json_object_t;x json_object_t;a json_array_t;
  v_article varchar2(160);v_qty number;v_time varchar2(30);v_zone varchar2(60);n number;
 begin
  if not m.has('terminal_audit') then return;end if;
  t:=m.get_object('terminal_audit');a:=t.get_array('errors');
  if a.get_size>200 or t.get_array('vp_lines').get_size>200 then raise_application_error(-20881,'QUALITY_AUDIT_BOUND');end if;
  if a.get_size>0 and m.get_number('error_count')=0 then raise_application_error(-20871,'QUALITY_ERRORS_WITH_ZERO_COUNT');end if;
  delete from LOT_AUDIT where SSCC=p_uid;delete from LOT_AUDIT_ERROR_LINES where SSCC=p_uid;
  v_zone:=unistr('\0417\041E\041D\0410_\042D\041A\0421\041F\0415\0414\0418\0426\0418\0418');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);v_article:=x.get_string('article');v_qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));
   if x.get_string('condition')=unistr('\041D\0415\0414\041E\0421\0422\0410\0427\0410') then v_zone:=unistr('\0417\041E\041D\0410_\041E\0428\0418\0411\041E\041A');end if;
   update RRL_SBORKA_PALLET_ROWS set SOBRANO=v_qty where PALLET_UID=p_uid and ARTICUL=v_article;
   if sql%rowcount!=1 then raise_application_error(-20887,'QUALITY_AUDIT_ARTICLE_NOT_UNIQUE');end if;
  end loop;
  a:=t.get_array('vp_lines');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);v_article:=x.get_string('article');v_time:=x.get_string('checked_at');
   update RRL_SBORKA_PALLET_ROWS set TIME_OF_CHECKING=to_date(v_time,'FXYYYY-MM-DD HH24:MI:SS') where PALLET_UID=p_uid and ARTICUL=v_article;
   if sql%rowcount!=1 then raise_application_error(-20887,'QUALITY_AUDIT_ARTICLE_NOT_UNIQUE');end if;
  end loop;
  insert into LOT_AUDIT(SSCC,CONDITION) values(p_uid,v_zone);
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);sh json_object_t;q json_object_t:=json_object_t();v json_object_t:=json_object_t();
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();v_uid varchar2(150);v_id number;ware number;passed number;shipped number;expected number;tolerance number;v_reason varchar2(160);v_units number;v_items number;
 begin
  v_uid:=d.get_object('source').get_string('pallet_identifier');
  select ID,WARE_ID into v_id,ware from RRL_SBORKA_PALLETS where PALLET_UID=v_uid;
  sh:=json_object_t.parse(p_request);sh.put('command_type','SHIP_PALLET');
  RRL_STOCK_SHIPPING_CORE.compile_shipment(sh.to_clob,p_operation,p_policies,p_resources,p_domain,true);
  f:=json_array_t.parse(p_policies);r:=json_array_t.parse(p_resources);v:=json_object_t.parse(p_domain);
  quality(p_request,v_id,passed,shipped,expected,tolerance,p_domain,v_reason,v_units,v_items);
  if d.get_object('metadata').has('final_scale_capture')then
   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','WH.FINAL.SCALE.USE:'||d.get_object('metadata').get_string('final_scale_capture'));
  end if;
  for z in(select ARTICUL from RRL_RECEIPT_SKU_RULE where WARE_ID=ware and ARTICUL in(select ARTICUL from RRL_SBORKA_PALLET_ROWS where PALLET_UID=v_uid) order by ARTICUL) loop
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SKU_RULE',RRL_STOCK_PLAN_HELPER.decimal_text(ware)||':'||z.ARTICUL);end loop;
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WARES',RRL_STOCK_PLAN_HELPER.decimal_text(ware));
  q.put('pallet_id',v_id);q.put('identifier',v_uid);q.put('warehouse',ware);q.put('passed',passed);q.put('ship',shipped);q.put('expected',expected);q.put('tolerance',tolerance);q.put('failure_reason',v_reason);q.put('unit_count',v_units);q.put('item_proved',v_items);
  if d.get_object('metadata').has('terminal_audit') then
   RRL_STOCK_PLAN_HELPER.row_key(r,'LOT_AUDIT',v_uid);RRL_STOCK_PLAN_HELPER.row_key(r,'LOT_AUDIT_ERROR_LINES',v_uid);
  end if;
  q.put('composition_signature',RRL_STOCK_QC_GATE.signature_for_plan(v.to_clob));
  q.put('composition_signature_version',RRL_STOCK_QC_GATE.signature_version_for_plan(v.to_clob));
  if d.get_object('metadata').has('expected_composition_signature')
   and d.get_object('metadata').get_string('expected_composition_signature')!=q.get_string('composition_signature') then
   raise_application_error(-20873,'QUALITY_SCANNED_COMPOSITION_CHANGED');end if;
  v.put('quality',q);p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');q json_object_t;v json_object_t;
  sh json_object_t;j json_object_t:=json_object_t();plan clob;shipment clob;op varchar2(100);v_uid varchar2(150);v_id number;ware number;actual_ware number;
  passed number;shipped number;expected number;tolerance number;v_condition number;gross number;wood number;errors number;note varchar2(1000);picker varchar2(100);v_kind varchar2(20);n number;v_full_scan number;v_reason varchar2(160);v_units number;v_items number;v_ready number;v_nested number;v_status json_object_t;
 begin
  if RRL_HAS_WRIGHT(p_actor,'outgoing_pallet_check')!=1 and RRL_HAS_WRIGHT(p_actor,'stock_posting_shipping')!=1 and RRL_HAS_WRIGHT(p_actor,'CLOSE_OTHOD_NAKLAD')!=1 then
   raise_application_error(-20882,'OUTGOING_QUALITY_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v:=json_object_t.parse(plan).get_object('domain');q:=v.get_object('quality');v_id:=q.get_number('pallet_id');v_uid:=q.get_string('identifier');ware:=q.get_number('warehouse');
  select WARE_ID,CONDITION into actual_ware,v_condition from RRL_SBORKA_PALLETS where ID=v_id and PALLET_UID=v_uid for update;
  if actual_ware!=ware or nvl(v_condition,0)>=2 then raise_application_error(-20886,'QUALITY_PALLET_ALREADY_CLOSED');end if;
  select ID into n from RRL_WARES where ID=ware for update;
  for z in(select ID from RRL_SBORKA_PALLET_ROWS where PALLET_UID=v_uid order by ID for update) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_SBORKA_PALLET_ROWS',RRL_STOCK_PLAN_HELPER.decimal_text(z.ID)));
  end loop;
  quality(p_request,v_id,passed,shipped,expected,tolerance,v.to_clob,v_reason,v_units,v_items);
  if passed!=q.get_number('passed') or shipped!=q.get_number('ship')
   or nvl(expected,-1)!=nvl(q.get_number('expected'),-1) or nvl(tolerance,-1)!=nvl(q.get_number('tolerance'),-1) or nvl(v_reason,chr(0))!=nvl(q.get_string('failure_reason'),chr(0))
   or v_units!=q.get_number('unit_count') or v_items!=q.get_number('item_proved') then
   raise_application_error(-20890,'CLOSURE_CHANGED: quality calculation');end if;
  v_kind:=m.get_string('quality_kind');
  if v_kind='PLAN' then
   RRL_STOCK_QC_POLICY.assign_sampling(v.to_clob);
   j.put('operation_id',op);j.put('verified',0);j.put('shipped',0);j.put('plan_assigned',true);
   v_status:=json_object_t.parse(RRL_STOCK_QC_GATE.status_json(v_uid));v_ready:=case when v_status.get_boolean('ready') then 1 else 0 end;
   if v_ready=1 then RRL_QC_SCOPE_READ.record_exemption(v.to_clob,RRL_STOCK_QC_GATE.signature_for_plan(v.to_clob));end if;
   RRL_STOCK_QC_CASE.project(v.to_clob,v_ready,0,1,p_actor,op,null);
   declare v_case number:=v.get_number('case_task');v_state varchar2(40);begin if v_case is not null then select STATUS into v_state from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case;v_status.put('case_status',v_state);end if;end;
   j.put('control_status',v_status);p_result:=j.to_clob;return;
  end if;
  RRL_STOCK_QC_POLICY.assert_controller(v.to_clob,p_actor);
  RRL_WH_FINAL_SCALE_ADMISSION.claim_capture(p_request,v.to_clob,op);
  v_full_scan:=RRL_STOCK_QC_POLICY.full_scan_required(v.to_clob);
  RRL_STOCK_QC_POLICY.assign_sampling(v.to_clob);
  if v_kind='SCAN' then
   errors:=greatest(m.get_number('error_count'),case when passed=0 then 1 else 0 end);note:=m.get_string('note');picker:=m.get_string('picker');
   update RRL_SBORKA_PALLETS set PROOVED_BY_SCAN=passed,COUNT_OF_ERRORS=errors,PRIM=note,SBORSHIK=nvl(picker,SBORSHIK),KLADOVSHIK=p_actor where ID=v_id;
  else
   gross:=RRL_STOCK_MATH.quantity(m.get_string('gross_weight'));wood:=case when regexp_like(m.get_string('wood_weight'),'^0([.]0{1,9})?$') then 0 else RRL_STOCK_MATH.quantity(m.get_string('wood_weight')) end;
   update RRL_SBORKA_PALLETS set TRIAL_WEIGHT=gross,WOOD_WEIGHT=wood,VESOVSHIK=p_actor,PROOVED=passed,
    STATE=case when passed=1 then unistr('\041F\0440\043E\0432\0435\0440\0435\043D\0412\0435\0441\0430\043C\0438') else unistr('\0412\044B\0434\0430\043D \0432 \0441\0431\043E\0440\043A\0443') end where ID=v_id;
   insert into RRL_SBORKA_PALLETS_HISTORY(PALLET_UID,USER_ID,ZONE,EVENT,WEIGHT)
    values(v_uid,p_actor,'STOCK_QC',case when passed=1 then 'WEIGHT_PASSED' else 'WEIGHT_FAILED' end,gross-wood);
  end if;
  terminal_audit(p_request,v_uid);
  declare v_signature varchar2(64);v_unit_count number:=0;v_item_proved number:=0;begin
   if passed=0 then update RRL_SBORKA_PALLETS set SCAN_CONTENT_SIGNATURE=null,WEIGHT_CONTENT_SIGNATURE=null,SCAN_ITEM_PROVED=0,QC_RESCAN_REQUIRED=1 where ID=v_id;end if;
   if passed=1 and v_kind='SCAN' then
    v_unit_count:=v_units;v_item_proved:=v_items;
    if v_item_proved=1 then update RRL_SBORKA_PALLETS set QC_RESCAN_REQUIRED=0 where ID=v_id;end if;
   end if;
   if passed=1 then v_signature:=RRL_STOCK_QC_GATE.signature_for_plan(v.to_clob);end if;
   if v_kind='SCAN' then
    update RRL_SBORKA_PALLETS set SCAN_CONTENT_SIGNATURE=v_signature,SCAN_QC_OPERATION_ID=op,SCAN_MARK_PROVED=case when passed=1 and v_unit_count>0 then 1 else 0 end,SCAN_PHYSICAL_UNIT_COUNT=v_unit_count,SCAN_ITEM_PROVED=v_item_proved where ID=v_id;
   else
    update RRL_SBORKA_PALLETS set WEIGHT_CONTENT_SIGNATURE=v_signature,WEIGHT_QC_OPERATION_ID=op,
     WEIGHT_QC_METHOD=v_kind,WEIGHT_QC_EXPECTED=expected,WEIGHT_QC_TOLERANCE=tolerance where ID=v_id;
   end if;
  end;
  v_ready:=1;
  begin RRL_STOCK_QC_GATE.assert_approved(v.to_clob);
  exception when others then if sqlcode=-20886 then v_ready:=0;else raise;end if;end;
  if v_ready=1 then RRL_QC_SCOPE_READ.record_exemption(v.to_clob,RRL_STOCK_QC_GATE.signature_for_plan(v.to_clob));end if;
  RRL_STOCK_QC_CASE.project(v.to_clob,v_ready,case when passed=0 then 1 else 0 end,0,p_actor,op,v_reason);
  v_nested:=RRL_STOCK_QC_CASE.nested(v.to_clob);
  if shipped=1 and (v_ready=0 or v_nested=1) then shipped:=0;end if;
  j.put('ready',v_ready=1);j.put('whole_hu_shipment_required',v_nested=1);
  if shipped=1 then
   sh:=json_object_t.parse(p_request);sh.put('command_type','SHIP_PALLET');
   RRL_STOCK_SHIPPING_CORE.execute_shipment(sh.to_clob,p_actor,shipment);j.put('shipment',json_object_t.parse(shipment));
  end if;
  if m.has('final_scale_capture')then
   declare capture_json json_object_t;key_value varchar2(64):=m.get_string('final_scale_capture');wire clob;begin
    select RESULT_JSON into wire from RRL_WH_SCALE_CAPTURE where CAPTURE_KEY=key_value;capture_json:=json_object_t.parse(wire);
    j.put('final_scale_capture',key_value);j.put('final_scale_device_mode',capture_json.get_string('device_mode'));
    j.put('gross_weight_kg',capture_json.get_string('weight_kg'));j.put('tare_weight_kg',capture_json.get_string('tare_weight_kg'));j.put('net_weight_kg',capture_json.get_string('net_weight_kg'));
   end;
  end if;
  j.put('failure_reason',v_reason);j.put('operation_id',op);j.put('verified',passed);j.put('shipped',shipped);j.put('physical_loading_required',v_ready=1);j.put('return_code',case when v_kind='SCAN' then 0 else passed end);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_PALLET_TYPE_CMD as
 g_writing boolean:=false;g_uid varchar2(200);g_operation varchar2(100);g_tx varchar2(100);
 function snapshot(p_request clob,p_actor varchar2)return clob is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');j json_object_t;
  uid_value varchar2(200):=d.get_object('source').get_string('uid');keys json_key_list;el json_element_t;
  version_no number;type_no number;reference_value varchar2(255);scan_value varchar2(200);n number;
 begin
  keys:=d.get_object('source').get_keys;el:=d.get_object('source').get('uid');
  if keys.count!=1 or el is null or not el.is_string then raise_application_error(-20886,'PALLET_FLOOR_CANONICAL_SOURCE_REQUIRED');end if;
  if uid_value is null or length(uid_value)>200 or trim(uid_value)!=uid_value then raise_application_error(-20886,'PALLET_FLOOR_UID_REQUIRED');end if;
  if d.get_array('lines').get_size!=0 or d.get_array('units').get_size!=0 then raise_application_error(-20886,'PALLET_FLOOR_ZERO_QUANTITY_COMMAND_REQUIRED');end if;
  keys:=m.get_keys;
  if keys.count!=5 or not m.has('pallet_type_id')or not m.has('expected_version')or not m.has('scan_pallet')or not m.has('scan_cell')or not m.has('evidence_reference')then
   raise_application_error(-20886,'PALLET_FLOOR_EXPLICIT_FIELDS_REQUIRED');end if;
  el:=m.get('pallet_type_id');if not el.is_number then raise_application_error(-20886,'PALLET_FLOOR_INTEGER_TYPE_REQUIRED');end if;
  el:=m.get('expected_version');if not el.is_number then raise_application_error(-20886,'PALLET_FLOOR_INTEGER_VERSION_REQUIRED');end if;
  el:=m.get('scan_pallet');if not el.is_string then raise_application_error(-20886,'PALLET_FLOOR_SCAN_TEXT_REQUIRED');end if;
  el:=m.get('scan_cell');if not el.is_string then raise_application_error(-20886,'PALLET_FLOOR_SCAN_TEXT_REQUIRED');end if;
  el:=m.get('evidence_reference');if not el.is_string then raise_application_error(-20886,'PALLET_FLOOR_REFERENCE_TEXT_REQUIRED');end if;
  version_no:=m.get_number('expected_version');type_no:=m.get_number('pallet_type_id');
  if version_no is null or version_no<0 or version_no!=trunc(version_no)or type_no is null or type_no<1 or type_no!=trunc(type_no)then
   raise_application_error(-20886,'PALLET_FLOOR_INTEGER_FIELDS_REQUIRED');end if;
  reference_value:=trim(m.get_string('evidence_reference'));
  if reference_value is null or lengthb(reference_value)>255 then raise_application_error(-20886,'PALLET_FLOOR_REFERENCE_REQUIRED');end if;
  j:=json_object_t.parse(RRL_PALLET_FLOOR_READ.describe_type(uid_value,p_actor));
  if not j.get_boolean('has_physical_stock')or j.get_string('cell')is null then raise_application_error(-20886,'PALLET_FLOOR_CURRENT_PHYSICAL_STOCK_REQUIRED');end if;
  if j.get_number('version')!=version_no then raise_application_error(-20886,'PALLET_FLOOR_VERSION_CHANGED');end if;
  scan_value:=m.get_string('scan_pallet');
  if scan_value is null or(scan_value!=uid_value and(j.get_string('sscc')is null or scan_value!=j.get_string('sscc')))then
   raise_application_error(-20886,'PALLET_FLOOR_CURRENT_PALLET_SCAN_REQUIRED');end if;
  if m.get_string('scan_cell')is null or m.get_string('scan_cell')!=j.get_string('cell')then raise_application_error(-20886,'PALLET_FLOOR_CURRENT_CELL_SCAN_REQUIRED');end if;
  select count(*)into n from RRL_PALLET_TYPE where PALLET_TYPE_ID=type_no and ACTIVE=1;
  if n!=1 then raise_application_error(-20886,'PALLET_FLOOR_ACTIVE_TYPE_REQUIRED');end if;
  j.put('new_pallet_type_id',type_no);j.put('evidence_reference',reference_value);return j.to_clob;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
  d json_object_t:=json_object_t.parse(p_request);s clob;j json_object_t;uid_value varchar2(200);f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
  s:=snapshot(p_request,d.get_string('actor'));j:=json_object_t.parse(s);uid_value:=j.get_string('uid');
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',j.get_string('uid'));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLET_FLOOR_TYPE',j.get_string('uid'));
  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,uid_value,j.get_string('article'),j.get_string('cell'),null);
  j.put('snapshot_signature',rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256)));
  p_domain:=j.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure assert_writing(p_uid varchar2,p_operation varchar2)is n number;
 begin
  if not g_writing or g_uid is null or g_uid!=p_uid or g_operation is null or g_operation!=p_operation
   or g_tx is null or g_tx!=dbms_transaction.local_transaction_id(false)
   or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=p_operation then
   raise_application_error(-20863,'PALLET_FLOOR_ROOT_OWNER_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_PALLET_FLOOR_TYPE',p_uid));
  select count(*)into n from RRL_STOCK_OPERATION where OPERATION_ID=p_operation and COMMAND_TYPE='PALLET_FLOOR_TYPE_CONFIRM'and STATE='IN_FLIGHT';
  if n!=1 then raise_application_error(-20863,'PALLET_FLOOR_CURRENT_ROOT_REQUIRED');end if;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);frozen json_object_t;j json_object_t;s clob;plan clob;
  op varchar2(100):=d.get_string('operation_id');uid_value varchar2(200);ware_no number;type_no number;version_no number;
 begin
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;frozen:=json_object_t.parse(plan).get_object('domain');
  s:=snapshot(p_request,p_actor);
  if rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256))!=frozen.get_string('snapshot_signature')then raise_application_error(-20890,'CLOSURE_CHANGED: pallet floor type');end if;
  uid_value:=frozen.get_string('uid');ware_no:=frozen.get_number('warehouse');type_no:=frozen.get_number('new_pallet_type_id');version_no:=frozen.get_number('version')+1;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_PALLETS',uid_value));
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);
  g_writing:=true;g_uid:=uid_value;g_operation:=op;g_tx:=dbms_transaction.local_transaction_id(false);
  merge into RRL_PALLET_FLOOR_TYPE t using(select uid_value UID_PALLET from dual)src on(t.UID_PALLET=src.UID_PALLET)
   when matched then update set PALLET_TYPE_ID=type_no,TYPE_VERSION=version_no,LAST_OPERATION_ID=op,DECLARED_WARE_ID=ware_no
   when not matched then insert(UID_PALLET,PALLET_TYPE_ID,TYPE_VERSION,LAST_OPERATION_ID,DECLARED_WARE_ID)values(uid_value,type_no,version_no,op,ware_no);
  g_writing:=false;g_uid:=null;g_operation:=null;g_tx:=null;
  j:=json_object_t();j.put('operation_id',op);j.put('command_type','PALLET_FLOOR_TYPE_CONFIRM');j.put('uid',uid_value);j.put('warehouse',ware_no);
  j.put('pallet_type_id',type_no);j.put('version',version_no);j.put('evidence_reference',frozen.get_string('evidence_reference'));j.put('actor',p_actor);
  j.put('stock_changed',false);j.put('tare_balance_changed',false);j.put('status','APPLIED');p_result:=j.to_clob;
 exception when others then g_writing:=false;g_uid:=null;g_operation:=null;g_tx:=null;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_PALLET_UOM as
 procedure resolve_quantity(p_uid varchar2,p_input varchar2,p_quantity varchar2,
  p_base out varchar2,p_quantity_base out number,p_version out number,p_signature out varchar2) is
  p RRL_PALLETS%rowtype;v_input varchar2(20);v_stock_base varchar2(20);
  v_num number;v_den number;v_scale number;v_pack number;v_input_version number;v_provenance varchar2(1000);
  v json_object_t:=json_object_t();
 begin
  select * into p from RRL_PALLETS where UID_PALLET=p_uid;
  select min(BASE_UOM),max(BASE_UOM) into v_stock_base,p_base from RRL_REMAINS where UID_POLETA=p_uid and REMAIN>0;
  if v_stock_base is null then
   select min(BASE_UOM),max(BASE_UOM) into v_stock_base,p_base from RRL_STOCK_UOM_CONVERSION where ARTICUL=p.ARTICUL and INPUT_UOM=BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
  end if;
  if v_stock_base is null or p_base!=v_stock_base then raise_application_error(-20887,'PALLET_BASE_UOM_AMBIGUOUS');end if;
  v_input:=nvl(p_input,p_base);
  select max(POLICY_VERSION) into p_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=p.ARTICUL and INPUT_UOM=v_input;
  select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE,PROVENANCE into p_base,v_num,v_den,v_scale,v_provenance
   from RRL_STOCK_UOM_CONVERSION where ARTICUL=p.ARTICUL and INPUT_UOM=v_input and POLICY_VERSION=p_version;
  if p_base!=v_stock_base then raise_application_error(-20887,'PALLET_BASE_UOM_CONFLICT');end if;
  -- BOX arithmetic follows the actual pallet pack, never a rounded legacy box count.
  if upper(v_input) in ('BOX','CAR','CS','KAR','KOR','КОР') then
   if upper(p_base) not in ('EA','PCS','ST','ШТ') then
    raise_application_error(-20887,'PALLET_BOX_REQUIRES_EXACT_BASE_ALLOCATION');
   end if;
   if p.STOCK_PACK_FROZEN=1 then
    if p.STOCK_PACK_BASE_UOM!=p_base then raise_application_error(-20887,'PALLET_PACK_BASE_CONFLICT');end if;
    v_pack:=p.STOCK_BOX_FACTOR;v_provenance:='PALLET.FROZEN_PACK';
   else
    -- A lot already in stock must never silently adopt a later article factor.
    select count(*) into v_pack from RRL_REMAINS where UID_POLETA=p_uid and REMAIN>0;
    if v_pack>0 then raise_application_error(-20887,'PALLET_PACK_SNAPSHOT_REQUIRED');end if;
    if nvl(p.MOD_ID,0)!=0 then
     select SHT_IN_KOR into v_pack from RRL_ARTICUL_MODS where ID=p.MOD_ID and ARTICUL=p.ARTICUL;
     v_provenance:='PALLET.MOD_ID';
    else
     select COUNT_SHT_IN_KOR into v_pack from RRL_ARTICULS where ACTICUL=p.ARTICUL;
     v_provenance:='ARTICLE.DEFAULT_PACK_BEFORE_ADMISSION';
    end if;
   end if;
   if v_pack is null or v_pack<1 or v_pack!=trunc(v_pack) or v_pack>1000000000 then
    raise_application_error(-20887,'PALLET_PACK_FACTOR_INVALID');
   end if;
   v_num:=v_pack;v_den:=1;
  end if;
  p_quantity_base:=RRL_STOCK_MATH.convert_exact(p_quantity,v_num,v_den,v_scale);
  v_input_version:=p_version;
  select max(POLICY_VERSION) into p_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=p.ARTICUL and INPUT_UOM=p_base and BASE_UOM=p_base and NUMERATOR=1 and DENOMINATOR=1;
  if p_version is null then raise_application_error(-20868,'PALLET_BASE_POLICY_REQUIRED');end if;
  v.put('uid',p_uid);v.put('article',p.ARTICUL);v.put('mod_id',p.MOD_ID);
  v.put('input',v_input);v.put('base',p_base);v.put('version',v_input_version);v.put('base_version',p_version);
  v.put('numerator',v_num);v.put('denominator',v_den);v.put('scale',v_scale);v.put('provenance',v_provenance);
  p_signature:=rawtohex(sys.dbms_crypto.hash(v.to_clob,sys.dbms_crypto.hash_sh256));
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_PLAN_HELPER as
 procedure fence(p_plan in out nocopy json_array_t,p_kind varchar2,p_id varchar2,p_mode number default 4) is v json_object_t:=json_object_t();
 begin
  v.put('key_hex',rawtohex(RRL_STOCK_LOCK_API.resource_key(p_kind,p_id)));v.put('mode',p_mode);p_plan.append(v);
 end;
 procedure anchor(p_plan in out nocopy json_array_t,p_rank number,p_kind varchar2,p_a varchar2,p_b varchar2 default null) is v json_object_t:=json_object_t();
 begin
  v.put('rank',p_rank);v.put('key_hex',rawtohex(RRL_STOCK_LOCK_API.resource_key(p_kind,p_a,p_b)));p_plan.append(v);
 end;
 procedure row_key(p_plan in out nocopy json_array_t,p_table varchar2,p_id varchar2) is
 begin anchor(p_plan,20,'ROW',p_table,p_id);end;
 function decimal_text(p_value number) return varchar2 is v varchar2(200);
 begin
  v:=to_char(p_value,'TM9','NLS_NUMERIC_CHARACTERS=''.,''');
  if substr(v,1,1)='.' then return '0'||v;end if;
  if substr(v,1,2)='-.' then return '-0'||substr(v,2);end if;
  return v;
 end;
 procedure stock_closure(p_policies in out nocopy json_array_t,p_resources in out nocopy json_array_t,
  p_uid varchar2,p_article varchar2,p_from varchar2,p_to varchar2) is
 begin
  for h in(select HU_LINK_ID,PARENT_UID,level DEPTH,connect_by_iscycle CYCLIC from RRL_WMS_HU_LINK
   start with ACTIVE_FLAG=1 and (CHILD_PALLET_UID=p_uid or CHILD_CASE_TASK_ID in
    (select CASE_PICK_TASK_ID from RRL_CASE_CARRIER_LOT where LOT_UID=p_uid))
   connect by nocycle prior PARENT_UID=CHILD_PALLET_UID and ACTIVE_FLAG=1) loop
   if h.DEPTH>16 or h.CYCLIC=1 then raise_application_error(-20886,'HU_ANCESTOR_CYCLE_OR_DEPTH_BOUND');end if;
   anchor(p_resources,30,'HU',h.PARENT_UID);row_key(p_resources,'RRL_PALLETS',h.PARENT_UID);
   row_key(p_resources,'RRL_WMS_HU_LINK',decimal_text(h.HU_LINK_ID));
  end loop;
  fence(p_policies,'CONFIG','WAREHOUSE');fence(p_policies,'SKU',p_article);
  if p_from is not null then fence(p_policies,'CELL',p_from);anchor(p_resources,40,'SLOT','CELL:'||p_from);end if;
  if p_to is not null then fence(p_policies,'CELL',p_to);anchor(p_resources,40,'SLOT','CELL:'||p_to);end if;
  anchor(p_resources,30,'HU',p_uid);anchor(p_resources,50,'STOCK',p_uid);
  for r in(select RESERVATION_ID,CELL_SLOT_ID,SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_LINE_ID,RESERVATION_DOMAIN from RRL_STOCK_RESERVATION
    where UID_PALLET=p_uid and STATUS in('ACTIVE','ALLOCATED','PICKING') and RESERVATION_KIND='HARD') loop
   if r.SOURCE_DOC_TYPE='PICK_WAVE' then row_key(p_resources,'RRL_PICK_WAVE',decimal_text(r.SOURCE_DOC_ID));
   elsif r.SOURCE_DOC_TYPE='PICK_PLAN' then row_key(p_resources,'RRL_PICK_PLAN',decimal_text(r.SOURCE_DOC_ID));
   elsif r.SOURCE_DOC_TYPE='PRODUCTION_ORDER' then row_key(p_resources,'RRL_PRODUCTION_ORDER',decimal_text(r.SOURCE_DOC_ID));end if;
   row_key(p_resources,'RRL_STOCK_RESERVATION',decimal_text(r.RESERVATION_ID));
   if r.SOURCE_DOC_TYPE='PICK_WAVE' and r.RESERVATION_DOMAIN='PICKING' and r.SOURCE_LINE_ID is not null then
    row_key(p_resources,'RRL_PICK_TASK',decimal_text(r.SOURCE_LINE_ID));end if;

   if r.CELL_SLOT_ID is not null then anchor(p_resources,40,'SLOT',decimal_text(r.CELL_SLOT_ID));end if;
  end loop;
  for c in(select TASK_ID,CELL_SLOT_ID from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=p_uid and STATUS='OCCUPIED') loop
   row_key(p_resources,'RRL_RECEIPT_SLOT_CLAIM',decimal_text(c.TASK_ID));
   anchor(p_resources,40,'SLOT',decimal_text(c.CELL_SLOT_ID));
  end loop;
  for u in(select PHYSICAL_UNIT_KEY from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and STOCK_STATUS!='ISSUED') loop
   if u.PHYSICAL_UNIT_KEY is null then raise_application_error(-20884,'COMPOSITION_BINDING_REQUIRED');end if;
   anchor(p_resources,60,'UNIT',u.PHYSICAL_UNIT_KEY);
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_POOL_CMD as
 function nonnegative(p_text varchar2) return number is
 begin if p_text='0' then return 0;end if;return RRL_STOCK_MATH.quantity(p_text);end;
 function same_snapshot(a clob,b clob) return boolean is
 begin return dbms_crypto.hash(a,dbms_crypto.hash_sh256)=dbms_crypto.hash(b,dbms_crypto.hash_sh256);end;
 procedure compile_wave_pool(p_ware number,p_wave number,p_resources in out nocopy json_array_t,p_pools out json_array_t) is
  x json_object_t;rid number;qty number;ver number;flag number;
 begin
  p_pools:=json_array_t();
  for demand in(select pl.CUSTOMER_ORDER_ROW_ID,pr.ARTICUL,sum(pr.RESERVED_QTY) BASE_QTY
   from RRL_PICK_RESERVATION pr join RRL_PICK_WAVE_ORDER wo on wo.PICK_PLAN_ID=pr.PICK_PLAN_ID
   join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=pr.PICK_PLAN_LINE_ID
   where wo.PICK_WAVE_ID=p_wave and wo.STATUS='ACTIVE' and pr.RESERVATION_STATUS='ACTIVE' and pr.RESERVATION_LEVEL='SOFT'
   group by pl.CUSTOMER_ORDER_ROW_ID,pr.ARTICUL order by pr.ARTICUL,pl.CUSTOMER_ORDER_ROW_ID) loop
   if p_pools.get_size>=200 then raise_application_error(-20881,'WAVE_POOL_BOUND_200');end if;
   RRL_STOCK_PLAN_HELPER.anchor(p_resources,20,'UNIQUE','SOFT.POOL:'||p_ware||':'||demand.ARTICUL);
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CUSTOMER_ORDER_ROW',RRL_STOCK_PLAN_HELPER.decimal_text(demand.CUSTOMER_ORDER_ROW_ID));
   begin
    select RESERVATION_ID,QTY,RESERVATION_VERSION into rid,qty,ver from RRL_STOCK_RESERVATION
     where POOL_WARE_ID=p_ware and ARTICUL=demand.ARTICUL and SOURCE_LINE_ID=demand.CUSTOMER_ORDER_ROW_ID
      and RESERVATION_KIND='SOFT' and STATUS in('ACTIVE','ALLOCATED');
   exception when no_data_found then
    flag:=0;
    begin select nvl(SHIP_FROM_STOCK,case STOCK_ALLOC_CLASS when 'DRY_RACK' then 1 else 0 end) into flag
     from RRL_RECEIPT_SKU_RULE where WARE_ID=p_ware and ARTICUL=demand.ARTICUL;exception when no_data_found then null;end;
    if flag=1 then raise_application_error(-20886,'WAVE_COMMON_POOL_ALLOCATION_REQUIRED');end if;
    rid:=null;
   end;
   if rid is not null then
    if qty<demand.BASE_QTY then raise_application_error(-20886,'WAVE_EXCEEDS_COMMON_POOL_ALLOCATION');end if;
    RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(rid));
    x:=json_object_t();x.put('id',rid);x.put('version',ver);x.put('old_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));
    x.put('consume_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(demand.BASE_QTY));
    x.put('warehouse',p_ware);x.put('article',demand.ARTICUL);x.put('line_id',demand.CUSTOMER_ORDER_ROW_ID);p_pools.append(x);
   end if;
  end loop;
 end;
 procedure consume_wave_pool(p_pools json_array_t,p_actor varchar2) is
  x json_object_t;sr RRL_STOCK_RESERVATION%rowtype;rid number;qty number;left_qty number;
 begin
  for i in 0..p_pools.get_size-1 loop
   x:=treat(p_pools.get(i) as json_object_t);rid:=x.get_number('id');
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('UNIQUE','SOFT.POOL:'||x.get_number('warehouse')||':'||x.get_string('article')));
   select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=rid for update;
   if sr.RESERVATION_VERSION!=x.get_number('version') or sr.QTY!=RRL_STOCK_MATH.quantity(x.get_string('old_quantity'))
    or sr.STATUS not in('ACTIVE','ALLOCATED') or sr.RESERVATION_KIND!='SOFT'
    or sr.ARTICUL!=x.get_string('article') or sr.POOL_WARE_ID!=x.get_number('warehouse') or sr.SOURCE_LINE_ID!=x.get_number('line_id')
    then raise_application_error(-20890,'CLOSURE_CHANGED: wave common pool');end if;
   qty:=RRL_STOCK_MATH.quantity(x.get_string('consume_quantity'));left_qty:=sr.QTY-qty;
   if left_qty<0 then raise_application_error(-20886,'WAVE_EXCEEDS_COMMON_POOL_ALLOCATION');end if;
   RRL_STOCK_CTX_API.begin_effect('RESERVATION',null,null,rid);
   update RRL_STOCK_RESERVATION set QTY=left_qty,STATUS=case when left_qty=0 then 'CONSUMED' else 'ACTIVE' end,
    RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=rid;
   RRL_STOCK_CTX_API.end_effect;
  end loop;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_hints clob,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);h json_object_t;s json_object_t;v json_object_t:=json_object_t();x json_object_t;item json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();lines json_array_t:=json_array_t();a json_array_t;old json_array_t;
  raw_snapshot clob;current_snapshot clob;ware number;article varchar2(160);rid number;oid number;lid number;qty number;total number:=0;step number;available number;found boolean;
 begin
  if p_hints is null then raise_application_error(-20881,'POOL_TRUSTED_PLAN_REQUIRED');end if;
  h:=json_object_t.parse(p_hints);s:=d.get_object('source');ware:=s.get_number('warehouse');article:=s.get_string('article');
  if h.get_string('algorithm')!='PROPORTIONAL_WHOLE_STEP_V1' then raise_application_error(-20881,'POOL_ALGORITHM_REQUIRED');end if;
  raw_snapshot:=h.get_clob('snapshot');current_snapshot:=RRL_STOCK_POOL_READ.snapshot_json(ware,article);
  if not same_snapshot(raw_snapshot,current_snapshot) then raise_application_error(-20890,'CLOSURE_CHANGED: pool planning snapshot');end if;
  s:=json_object_t.parse(raw_snapshot);available:=nonnegative(s.get_string('available'));step:=RRL_STOCK_MATH.quantity(s.get_string('step'));
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.fence(f,'SKU',article);
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,20,'UNIQUE','SOFT.POOL:'||ware||':'||article);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),dbms_crypto.hash_sh256)));
  a:=s.get_array('stocks');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   if nonnegative(x.get_string('free'))>0 then
    RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),article,x.get_string('cell'),null);
   end if;
  end loop;
  old:=s.get_array('reservations');
  for i in 0..old.get_size-1 loop
   x:=treat(old.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));
  end loop;
  a:=s.get_array('orders');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);oid:=x.get_number('order_id');lid:=x.get_number('line_id');
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(oid));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_ROW',RRL_STOCK_PLAN_HELPER.decimal_text(lid));
   qty:=nonnegative(h.get_object('allocations').get_string(RRL_STOCK_PLAN_HELPER.decimal_text(lid)));
   if qty<0 or qty>nonnegative(x.get_string('quantity')) or mod(qty,step)!=0 then raise_application_error(-20881,'POOL_ALLOCATION_INVALID');end if;
   if s.get_number('from_stock')=0 and qty!=0 then raise_application_error(-20881,'POOL_PLANNED_RECEIPT_IS_NOT_STOCK');end if;
   total:=total+qty;rid:=null;
   for k in 0..old.get_size-1 loop
    item:=treat(old.get(k) as json_object_t);
    if item.get_number('line_id')=lid then rid:=item.get_number('id');exit;end if;
   end loop;
   if qty>0 and rid is null then select RRL_STOCK_RESERVATION_SQ.nextval into rid from dual;
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(rid));end if;
   item:=json_object_t();item.put('order_id',oid);item.put('line_id',lid);item.put('customer_id',x.get_number('customer_id'));item.put('reservation_id',rid);
   item.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));lines.append(item);
  end loop;
  if total>available then raise_application_error(-20881,'POOL_OVERALLOCATED');end if;
  v.put('snapshot',raw_snapshot);v.put('warehouse',ware);v.put('article',article);v.put('lines',lines);v.put('total',RRL_STOCK_PLAN_HELPER.decimal_text(total));
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;s json_object_t;x json_object_t;item json_object_t;j json_object_t:=json_object_t();
  a json_array_t;old json_array_t;lines json_array_t;wire clob;raw_snapshot clob;ware number;article varchar2(160);op varchar2(100);rid number;oid number;lid number;cid number;qty number;base varchar2(20);found boolean;dummy number;order_wire clob;
 begin
  if RRL_HAS_WRIGHT(p_actor,'stock_reservation_edit')!=1 then raise_application_error(-20882,'POOL_ALLOCATION_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v:=json_object_t.parse(wire).get_object('domain');ware:=v.get_number('warehouse');article:=v.get_string('article');
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('UNIQUE','SOFT.POOL:'||ware||':'||article));
  raw_snapshot:=v.get_clob('snapshot');s:=json_object_t.parse(raw_snapshot);a:=s.get_array('orders');order_wire:=a.to_clob;base:=s.get_string('unit');lines:=v.get_array('lines');old:=s.get_array('reservations');
  for row_id in(select CUSTOMER_ORDER_ID,CUSTOMER_ORDER_ROW_ID from RRL_CUSTOMER_ORDER_ROW
    where CUSTOMER_ORDER_ROW_ID in(select ID from json_table(order_wire,'$[*]' columns(ID number path '$.line_id')))
    order by CUSTOMER_ORDER_ID,CUSTOMER_ORDER_ROW_ID) loop
   select CUSTOMER_ORDER_ID into dummy from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=row_id.CUSTOMER_ORDER_ID for update;
   select CUSTOMER_ORDER_ROW_ID into dummy from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ROW_ID=row_id.CUSTOMER_ORDER_ROW_ID for update;
  end loop;
  if not same_snapshot(raw_snapshot,RRL_STOCK_POOL_READ.snapshot_json(ware,article)) then raise_application_error(-20890,'CLOSURE_CHANGED: locked pool snapshot');end if;
  for i in 0..old.get_size-1 loop
   x:=treat(old.get(i) as json_object_t);rid:=x.get_number('id');found:=false;
   for k in 0..lines.get_size-1 loop
    item:=treat(lines.get(k) as json_object_t);
    if item.get_number('reservation_id')=rid and nonnegative(item.get_string('quantity'))>0 then found:=true;exit;end if;
   end loop;
   if not found then
    RRL_STOCK_CTX_API.begin_effect('RESERVATION',null,null,rid);
    update RRL_STOCK_RESERVATION set QTY=0,STATUS='RELEASED',RESERVATION_VERSION=RESERVATION_VERSION+1,RELEASED_AT=systimestamp,RELEASED_BY=p_actor,RELEASE_REASON='Demand pool recalculation' where RESERVATION_ID=rid;
    RRL_STOCK_CTX_API.end_effect;
   end if;
  end loop;
  for i in 0..lines.get_size-1 loop
   x:=treat(lines.get(i) as json_object_t);rid:=x.get_number('reservation_id');oid:=x.get_number('order_id');lid:=x.get_number('line_id');cid:=x.get_number('customer_id');qty:=nonnegative(x.get_string('quantity'));
   if qty>0 then
    RRL_STOCK_CTX_API.begin_effect('RESERVATION',null,null,rid);
    update RRL_STOCK_RESERVATION set QTY=qty,UNIT_CODE=base,STATUS='ACTIVE',RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=rid;
    if sql%rowcount=0 then
     insert into RRL_STOCK_RESERVATION(RESERVATION_ID,RESERVATION_KIND,RESERVATION_SCOPE,RESERVATION_DOMAIN,SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_LINE_ID,CUSTOMER_ID,CUSTOMER_ORDER_ID,POOL_WARE_ID,ARTICUL,QTY,UNIT_CODE,STATUS,PRIORITY,CREATED_BY,BASE_QTY,RESERVATION_VERSION)
      values(rid,'SOFT','QTY','PICKING','CUSTOMER_ORDER',oid,lid,cid,oid,ware,article,qty,base,'ACTIVE',100,p_actor,0,0);
    end if;
    RRL_STOCK_CTX_API.end_effect;
   end if;
  end loop;
  j.put('operation_id',op);j.put('warehouse',ware);j.put('article',article);j.put('unit',base);j.put('allocated_quantity',v.get_string('total'));j.put('available_quantity',s.get_string('available'));
  j.put('physical_reserve',false);j.put('from_stock',s.get_number('from_stock')=1);j.put('allocations',lines);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_POOL_READ as
 function line_snapshot_json(p_line number)return clob is
  o RRL_CUSTOMER_ORDER_ROW%rowtype;h RRL_CUSTOMER_ORDER%rowtype;
  base varchar2(20);p_article varchar2(160);qty number;requested number;waived_qty number;choice_pending number;choice_waived number;hard_qty number;picked_qty number;picked_hard number;
  num number;den number;scale number;conversion number;x json_object_t;
  v_row_status varchar2(40);v_order_status varchar2(40);v_customer number;
 begin
  if p_line is null or p_line<1 or p_line!=trunc(p_line)then raise_application_error(-20881,'POOL_LINE_IDENTITY_REQUIRED');end if;
  select *into o from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ROW_ID=p_line;
  select *into h from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=o.CUSTOMER_ORDER_ID;
  p_article:=o.ARTICUL;v_row_status:=o.STATUS;v_order_status:=h.STATUS;v_customer:=h.CUSTOMER_ID;
  select BASE_UOM into base from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM=BASE_UOM and NUMERATOR=1 and DENOMINATOR=1
   order by POLICY_VERSION desc fetch first 1 row only;
   if o.UNIT_CODE is null then raise_application_error(-20868,'POOL_ORDER_UOM_REQUIRED');end if;
   select NUMERATOR,DENOMINATOR,BASE_SCALE,POLICY_VERSION into num,den,scale,conversion from RRL_STOCK_UOM_CONVERSION
    where ARTICUL=p_article and INPUT_UOM=o.UNIT_CODE and BASE_UOM=base order by POLICY_VERSION desc fetch first 1 row only;
   qty:=RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(o.ORDER_QTY),num,den,scale);
   select nvl(sum(sr.BASE_QTY),0) into hard_qty from RRL_STOCK_RESERVATION sr
    join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=sr.PICK_PLAN_LINE_ID
    where pl.CUSTOMER_ORDER_ROW_ID=o.CUSTOMER_ORDER_ROW_ID and sr.RESERVATION_KIND='HARD'
     and sr.ARTICUL=p_article and sr.STATUS in('ACTIVE','ALLOCATED','PICKING');
   -- Demand already secured physically must not be promised again in the common pool.
   select nvl(sum(nvl(pt.FACT_QTY,0)),0) into picked_qty from RRL_PICK_TASK pt
    join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=pt.PICK_PLAN_LINE_ID
    where pl.CUSTOMER_ORDER_ROW_ID=o.CUSTOMER_ORDER_ROW_ID and pt.ARTICUL=p_article
     and pt.STATUS in('IN_PROGRESS','DONE');
   -- Confirmed picks still carry HARD until shipment; count their overlap once.
   select nvl(sum(sr.BASE_QTY),0) into picked_hard from RRL_STOCK_RESERVATION sr
    join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=sr.PICK_PLAN_LINE_ID
    left join RRL_PICK_TASK pt on pt.PICK_TASK_ID=sr.SOURCE_LINE_ID
    where pl.CUSTOMER_ORDER_ROW_ID=o.CUSTOMER_ORDER_ROW_ID and sr.RESERVATION_KIND='HARD'
     and sr.ARTICUL=p_article and sr.STATUS in('ACTIVE','ALLOCATED','PICKING')
     and (exists(select 1 from RRL_CASE_CARRIER_LOT lot where lot.LOT_UID=sr.UID_PALLET)
      or (pt.TASK_TYPE='FULL_PALLET' and exists(select 1 from RRL_PICK_WAVE_TASK wt
       join RRL_WAREHOUSE_TASK wh on wh.SOURCE_TASK_ID=wt.PICK_WAVE_TASK_ID
       join RRL_WAREHOUSE_TASK_STOCK_MOVE mv on mv.TASK_ID=wh.TASK_ID
       where wt.PICK_TASK_ID=pt.PICK_TASK_ID and wh.TASK_SOURCE='WAVE' and wh.TASK_TYPE='PICKING_MOVE'
        and mv.TARGET_UID_PALLET=sr.UID_PALLET and mv.TO_CELL=sr.CELL)));
   requested:=qty;waived_qty:=RRL_WEIGHT_DEVIATION_READ.waived_line(o.CUSTOMER_ORDER_ROW_ID);qty:=greatest(0,qty-hard_qty-greatest(0,picked_qty-picked_hard)-waived_qty);
   RRL_WEIGHT_CHOICE_DEMAND_READ.adjustments(o.CUSTOMER_ORDER_ROW_ID,qty,choice_pending,choice_waived);
   waived_qty:=waived_qty+choice_waived;qty:=greatest(0,qty-choice_pending-choice_waived);
   x:=json_object_t();x.put('picked_hard_overlap',RRL_STOCK_PLAN_HELPER.decimal_text(picked_hard));x.put('picked_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(picked_qty));x.put('hard_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(hard_qty));x.put('line_id',o.CUSTOMER_ORDER_ROW_ID);x.put('order_id',o.CUSTOMER_ORDER_ID);x.put('customer_id',v_customer);
   x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));x.put('uom_version',conversion);x.put('order_status',v_order_status);x.put('line_status',v_row_status);

  x.put('warehouse',nvl(o.WARE_ID,h.WARE_ID));x.put('article',p_article);x.put('unit',base);
  x.put('requested_base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(requested));
  x.put('weight_choice_pending_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(choice_pending));
  x.put('accepted_weight_deviation_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(waived_qty));
  x.put('quantity_semantics',case when choice_pending>0 then 'UNALLOCATED_BASE_AFTER_PENDING_WEIGHT_CHOICE'when waived_qty>0 then 'UNALLOCATED_BASE_AFTER_ACCEPTED_WEIGHT_DEVIATION'else 'UNALLOCATED_BASE_NOT_SHIPPED_PROOF'end);
  x.put('open',v_row_status in('OPEN','PLANNED_FULL','PLANNED_PARTIAL','NO_STOCK')and
    v_order_status in('IMPORTED','OPEN','PLANNED_FULL','PLANNED_PARTIAL','NO_STOCK')and o.ORDER_QTY>0);
  return x.to_clob;
 exception when no_data_found then raise_application_error(-20868,'POOL_LINE_OR_UOM_NOT_FOUND');end;
 function snapshot_json(p_ware number,p_article varchar2) return clob is
  j json_object_t:=json_object_t();stocks json_array_t:=json_array_t();orders json_array_t:=json_array_t();reserves json_array_t:=json_array_t();x json_object_t;
  enabled number:=0;step number:=1;ver number:=0;available number:=0;eligible number;marked_free number;unit_count number;base varchar2(20);uom varchar2(20);
  n number;num number;den number;scale number;qty number;hard_qty number;picked_qty number;picked_hard number;conversion number;note varchar2(100);
 begin
  if p_ware is null or p_ware<1 or p_ware!=trunc(p_ware) or p_article is null then raise_application_error(-20881,'POOL_IDENTITY_REQUIRED');end if;
  begin select nvl(SHIP_FROM_STOCK,case STOCK_ALLOC_CLASS when 'DRY_RACK' then 1 else 0 end),PICK_STEP_BASE,ALLOCATION_VERSION into enabled,step,ver from RRL_RECEIPT_SKU_RULE where WARE_ID=p_ware and ARTICUL=p_article;
  exception when no_data_found then null;end;
  select BASE_UOM into base from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM=BASE_UOM and NUMERATOR=1 and DENOMINATOR=1
   order by POLICY_VERSION desc fetch first 1 row only;
  select count(*) into n from RRL_STOCK_RESERVATION where ARTICUL=p_article and RESERVATION_KIND='SOFT'
   and STATUS in('ACTIVE','ALLOCATED') and QTY>0 and POOL_WARE_ID is null;
  if enabled=1 and n>0 then raise_application_error(-20886,'POOL_LEGACY_SOFT_REQUIRES_RECONCILIATION');end if;
  for s in(select r.UID_POLETA,r.CELL,r.REMAIN,r.HARD_RESERVED_BASE,r.STOCK_VERSION,r.BASE_UOM from RRL_REMAINS r
    join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA join RRL_CELLS c on c.CELL=r.CELL
    where p.ARTICUL=p_article and c.WARE_ID=p_ware and r.REMAIN>0 order by r.UID_POLETA,r.CELL fetch first 501 rows only) loop
   if stocks.get_size>=500 then raise_application_error(-20881,'POOL_STOCK_BOUND_500');end if;
   eligible:=0;note:=RRL_STOCK_ELIGIBILITY.reason(s.UID_POLETA,s.CELL,p_ware,0,null,null,'ALLOCATE',null,p_article);
   if note is null and enabled=1 then
    if s.BASE_UOM!=base then raise_application_error(-20868,'POOL_BASE_UOM_CONFLICT');end if;
    eligible:=s.REMAIN-s.HARD_RESERVED_BASE;
    select count(*),nvl(sum(case when STOCK_STATUS='AVAILABLE' and HARD_RESERVATION_ID is null then BASE_QTY else 0 end),0)
     into unit_count,marked_free from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=s.UID_POLETA and CURRENT_CELL=s.CELL and STOCK_STATUS!='ISSUED';
    if unit_count>0 then eligible:=least(eligible,marked_free);end if;
   end if;
   available:=available+eligible;x:=json_object_t();x.put('uid',s.UID_POLETA);x.put('cell',s.CELL);
   x.put('stock_version',s.STOCK_VERSION);x.put('free',RRL_STOCK_PLAN_HELPER.decimal_text(eligible));x.put('reason',note);stocks.append(x);
  end loop;
  for o in(select r.CUSTOMER_ORDER_ROW_ID,r.CUSTOMER_ORDER_ID,r.ORDER_QTY,r.UNIT_CODE,r.STATUS ROW_STATUS,h.STATUS ORDER_STATUS,h.CUSTOMER_ID
    from RRL_CUSTOMER_ORDER_ROW r join RRL_CUSTOMER_ORDER h on h.CUSTOMER_ORDER_ID=r.CUSTOMER_ORDER_ID
    where nvl(r.WARE_ID,h.WARE_ID)=p_ware and r.ARTICUL=p_article and h.STATUS in('IMPORTED','OPEN','PLANNED_FULL','PLANNED_PARTIAL','NO_STOCK')
     and r.STATUS in('OPEN','PLANNED_FULL','PLANNED_PARTIAL','NO_STOCK') and r.ORDER_QTY>0

    order by h.SHIPMENT_DATE nulls last,r.SORTFIELD nulls last,h.CUSTOMER_ORDER_ID,r.LINE_NO fetch first 2001 rows only) loop
   if orders.get_size>=2000 then raise_application_error(-20881,'POOL_DEMAND_BOUND_2000');end if;
   x:=json_object_t.parse(line_snapshot_json(o.CUSTOMER_ORDER_ROW_ID));
   x.remove('warehouse');x.remove('article');x.remove('unit');x.remove('requested_base_quantity');x.remove('quantity_semantics');x.remove('open');
   x.put('dispatch_order',orders.get_size);orders.append(x);
  end loop;
  for sr in(select RESERVATION_ID,SOURCE_DOC_ID,SOURCE_LINE_ID,QTY,RESERVATION_VERSION,STATUS from RRL_STOCK_RESERVATION
   where RESERVATION_KIND='SOFT' and POOL_WARE_ID=p_ware and ARTICUL=p_article and STATUS in('ACTIVE','ALLOCATED')
   order by RESERVATION_ID fetch first 2001 rows only) loop
   if reserves.get_size>=2000 then raise_application_error(-20881,'POOL_RESERVATION_BOUND_2000');end if;
   x:=json_object_t();x.put('id',sr.RESERVATION_ID);x.put('order_id',sr.SOURCE_DOC_ID);x.put('line_id',sr.SOURCE_LINE_ID);
   x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(sr.QTY));x.put('version',sr.RESERVATION_VERSION);x.put('status',sr.STATUS);reserves.append(x);
  end loop;
  j.put('warehouse',p_ware);j.put('article',p_article);j.put('from_stock',enabled);j.put('policy_version',ver);
  j.put('step',RRL_STOCK_PLAN_HELPER.decimal_text(step));j.put('unit',base);j.put('available',RRL_STOCK_PLAN_HELPER.decimal_text(available));
  j.put('stocks',stocks);j.put('orders',orders);j.put('reservations',reserves);return j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_POSTING_API as  
 g_request clob;g_resolution clob;g_change_before clob;g_actor varchar2(50);g_operation varchar2(100);g_kind varchar2(80);g_tx varchar2(100);g_prepared boolean:=false;  
 procedure assert_actor_active(p_actor varchar2) is v_n number;  
 begin  
  select count(*)into v_n from RUSERS where ID=p_actor and nvl(DELETED,0)=0;  
  if v_n!=1 then raise_application_error(-20882,'STOCK_CURRENT_ACTOR_REQUIRED');end if;  
 end;  
 procedure assert_case_slot_actor(p_request clob,p_actor varchar2)is d json_object_t:=json_object_t.parse(p_request);m json_object_t;v_case number;begin  
  if d.get_string('command_type')not in('HU_RELOCATE_SLOT','HU_ATTACH','HU_DETACH','HU_UNPACK','HU_REPACK_SLOT')then return;end if;  
  m:=d.get_object('metadata');  
  if d.get_string('command_type')='HU_RELOCATE_SLOT'then v_case:=m.get_number('case_task_id');  
  else v_case:=m.get_number('child_case_task_id');end if;  
  if substr(d.get_object('source').get_string('uid'),1,5)='CASE:'and v_case is null then raise_application_error(-20886,'CASE_SLOT_TASK_ID_REQUIRED');end if;  
  if v_case is null then return;end if;  
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'CASE_SLOT_EXECUTION_FORBIDDEN');end if;  
  RRL_CASE_TASK_ACCESS.assert_scope(v_case,p_actor,'case_move');  
 end;  
 procedure assert_repack_actor(p_request clob,p_actor varchar2)is  
  d json_object_t:=json_object_t.parse(p_request);uid varchar2(200);ware number;user_ware number;grp varchar2(100);  
 begin  
  if d.get_string('command_type')!='HU_REPACK_SLOT'then return;end if;uid:=d.get_object('source').get_string('uid');  
  select c.WARE_ID into ware from RRL_PALLETS p join RRL_CELLS c on c.CELL=p.HU_CURRENT_CELL where p.UID_PALLET=uid;  
  select WARE_ID,USER_GROUP into user_ware,grp from RUSERS where ID=p_actor and nvl(DELETED,0)=0;  
  if ware is null or ware<1 then raise_application_error(-20886,'HU_REPACK_WARE_REQUIRED');end if;  
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 or(nvl(upper(trim(grp)),'-')!='GLOBAL_ADMIN'and(user_ware is null or user_ware!=ware))then raise_application_error(-20882,'HU_REPACK_CURRENT_WARE_EXECUTOR_REQUIRED');end if;  
 exception when no_data_found then raise_application_error(-20886,'HU_REPACK_CURRENT_SOURCE_REQUIRED');end;  
 procedure reset_connection is  
 begin  
  RRL_STOCK_CTX_API.clear_operation;RRL_STOCK_LOCK_API.clear_plan;  
  g_request:=null;g_resolution:=null;g_change_before:=null;g_actor:=null;g_operation:=null;g_kind:=null;g_tx:=null;g_prepared:=false;  
 end;  
 procedure prepare_command(p_request clob,p_actor varchar2,p_replay out clob,p_hints clob default null) is  
  v_doc json_object_t;v_policies clob;v_resources clob;v_exists number;v_release varchar2(20);v_domain clob;v_resolution json_object_t:=json_object_t();  
  v_plan json_array_t:=json_array_t();v_entry json_object_t:=json_object_t();v_resources_json json_array_t:=json_array_t();  
 begin  
  p_replay:=null;  
  if g_prepared or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is not null then  
   raise_application_error(-20862,'POSTING_ALREADY_ENTERED');  
  end if;  
  if p_request is null or dbms_lob.getlength(p_request)>4194304 then raise_application_error(-20871,'OPERATION_CONTRACT_INVALID'); end if;  
  v_doc:=json_object_t.parse(p_request);v_doc.on_error(1);  
  g_operation:=v_doc.get_string('operation_id');g_kind:=v_doc.get_string('command_type');  
  if v_doc.get_number('contract_version') is null or v_doc.get_number('contract_version')!=2 or v_doc.get_string('actor') is null  
   or v_doc.get_string('actor')!=p_actor or p_actor is null or length(p_actor)>50  
   or g_operation is null or length(g_operation)>100 or g_kind is null then  
   raise_application_error(-20871,'OPERATION_CONTRACT_INVALID');  
  end if;  
  assert_actor_active(p_actor);  
  if g_kind='STORE_RETURN_DISPOSE'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_RETURN_DISPOSE.assert_scope(doc.get_object('source').get_string('request_operation_id'),p_actor);end;end if;  
  if g_kind='STORE_RETURN_PUTAWAY_PLAN'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_STORE_RETURN_PUT.assert_scope(doc.get_object('source').get_string('receipt_operation_id'),p_actor);end;end if;  
  if g_kind='STORE_RETURN_RECEIVE'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_STORE_RETURN_REC_CMD.assert_scope(doc.get_object('source').get_string('pickup_operation_id'),p_actor);end;end if;  
  if g_kind in('STORE_RETURN_HANDOVER','STORE_RETURN_PICKUP')then RRL_STOCK_STORE_RETURN_CUST_CMD.assert_scope(p_request,p_actor);end if;  
  if g_kind='STORE_CUSTODY_RELEASE'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_STORE_CUSTODY_CMD.assert_scope(doc.get_object('source').get_string('receipt_operation_id'),p_actor);end;end if;  
  if g_kind='STORE_RETURN_APPROVE'then RRL_STOCK_STORE_RETURN_CMD.assert_actor(p_actor);end if;  
  if g_kind='STORE_RECEIPT'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_STORE_RECEIPT_READ.require_receiver(p_actor,doc.get_object('source').get_string('store_address'));end;end if;  
  if g_kind='INTERWARE_RECOVERY_CANCEL'then declare req json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_IW_RECOVERY_CANCEL.assert_scope(req.get_object('source').get_string('request_operation_id'),p_actor);end;end if;
  if g_kind='INTERWARE_RECOVERY_PUTAWAY_PLAN'then declare req json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_IW_RECOVERY_PUT.assert_scope(req.get_object('source').get_string('recovery_operation_id'),p_actor);end;end if;
  if g_kind='INTERWARE_SHORTAGE_RECOVER'then declare req json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_IW_RECOVERY_REC.assert_scope(req.get_object('source').get_string('approval_operation_id'),p_actor);end;end if;
  if g_kind in('INTERWARE_RECOVERY_REPORT','INTERWARE_RECOVERY_APPROVE')then RRL_STOCK_IW_RECOVERY_PLAN.assert_scope(p_request,p_actor);end if;
  if g_kind in('INTERWARE_SHORTAGE_REPORT','INTERWARE_SHORTAGE_CONFIRM')then RRL_STOCK_INTERWARE_SHORT_CMD.assert_scope(p_request,p_actor);end if; 
  if g_kind='INTERWARE_CUSTODY_RELEASE'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_INTERWARE_CUSTODY.assert_scope(doc.get_object('source').get_string('receipt_operation_id'),p_actor);end;end if;  
  if g_kind='INTERWARE_PUTAWAY_PLAN'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_INTERWARE_PUT.assert_scope(doc.get_object('source').get_string('receipt_operation_id'),p_actor,doc.get_object('metadata').get_number('superseded_task_id'));end;end if;  
  if g_kind in('INTERWARE_UNLOAD','INTERWARE_RECEIVE')then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_INTERWARE_REC.assert_scope(doc.get_object('source').get_string('plan_operation_id'),p_actor);end;end if;  
  if g_kind='LOAD_SHIPMENT'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_LOADING_READ.assert_scope(doc.get_object('source').get_string('pallet_identifier'),p_actor);end;end if;  
  if g_kind='TARE_OFFER_CANCEL'then RRL_STOCK_TARE_CANCEL_CMD.assert_scope(p_request,p_actor);end if;  
  if g_kind='TARE_BOOK'then RRL_TARE_LOAD_RECOVERY_API.assert_scope(p_request,p_actor);end if;assert_case_slot_actor(p_request,p_actor);assert_repack_actor(p_request,p_actor);  
  if g_kind='UNLOAD_SHIPMENT'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_UNLOAD_CMD.assert_scope(doc.get_object('source').get_string('load_operation_id'),p_actor);end;end if;  
  if g_kind in('TASK_COMPLETE','HU_TASK_COMPLETE','PICK_PALLET_BIND_SHIPMENT') then RRL_WAREHOUSE_TASK_ACCESS.assert_completion(p_request,p_actor);end if;  
  if g_kind='OUTGOING_PALLET_CHECK'then RRL_OUTGOING_QC_ACCESS.assert_identifier(json_object_t.parse(p_request).get_object('source').get_string('pallet_identifier'),p_actor);end if;  
  if g_kind in('CASE_PICK_CONFIRM','CASE_CARRIER_MOVE','CASE_CARRIER_RETURN','CASE_SHORT_APPROVE')then RRL_CASE_TASK_ACCESS.assert_command(p_request,p_actor);end if;
  if g_kind='CASE_CARRIER_MOVE'then RRL_ST_DEFER_CASE_WAIT.assert_command(p_request,p_actor);end if;  
  if g_kind in('WAVE_EXECUTION_FINISH','WAVE_PICK_RELEASE')then RRL_WAVE_EXEC_ACCESS.assert_command(p_request,p_actor);end if;  
  if g_kind='CASE_PALLET_TYPE_CHANGE'then RRL_CASE_TASK_ACCESS.assert_scope(v_doc.get_object('source').get_number('case_task_id'),p_actor,'case_pick_execute');end if;
  if g_kind='PALLET_FLOOR_TYPE_CONFIRM'then declare doc json_object_t:=json_object_t.parse(p_request);ware_no number;begin ware_no:=RRL_PALLET_FLOOR_READ.scope_warehouse(doc.get_object('source').get_string('uid'),p_actor);end;end if;
  if g_kind='ST_PREPARED_ROW_MOVE'then declare doc json_object_t:=json_object_t.parse(p_request);w number;begin w:=RRL_ST_LAYOUT_READ.scope_order(doc.get_object('source').get_number('order_id'),p_actor,'outgoing_pallet_edit');end;end if;
  -- Immutable committed replay is considered before any mutable article/cell/UOM validation.  
  select count(*) into v_exists from RRL_STOCK_OPERATION where OPERATION_ID=g_operation;  
  if v_exists!=0 then  
   v_entry.put('key_hex',rawtohex(RRL_STOCK_LOCK_API.resource_key('RELEASE','STOCK')));v_entry.put('mode',4);v_plan.append(v_entry);  
   v_entry:=json_object_t();v_entry.put('rank',10);  
   v_entry.put('key_hex',rawtohex(RRL_STOCK_LOCK_API.resource_key('OP',g_operation)));v_resources_json.append(v_entry);  
   v_policies:=v_plan.to_clob;v_resources:=v_resources_json.to_clob;  
  else  
   begin  
   if g_kind='ST_PREPARED_ROW_MOVE'then RRL_STOCK_ST_ROW_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);
   elsif g_kind='CASE_PALLET_TYPE_CHANGE'then RRL_STOCK_CASE_TYPE_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);
   elsif g_kind='PALLET_FLOOR_TYPE_CONFIRM'then RRL_STOCK_PALLET_TYPE_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);
   elsif g_kind='INTERWARE_RECOVERY_CANCEL'then RRL_STOCK_IW_RECOVERY_CANCEL.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);
   elsif g_kind='INTERWARE_RECOVERY_PUTAWAY_PLAN'then RRL_STOCK_IW_RECOVERY_PUT.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);
   elsif g_kind='INTERWARE_SHORTAGE_RECOVER'then RRL_STOCK_IW_RECOVERY_REC.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);
   elsif g_kind in('INTERWARE_RECOVERY_REPORT','INTERWARE_RECOVERY_APPROVE')then RRL_STOCK_IW_RECOVERY_PLAN.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);
   elsif g_kind in('INTERWARE_SHORTAGE_REPORT','INTERWARE_SHORTAGE_CONFIRM')then RRL_STOCK_INTERWARE_SHORT_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain); 
   elsif g_kind in('INTERWARE_UNLOAD','INTERWARE_RECEIVE') then RRL_STOCK_INTERWARE_REC.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind in('MANUAL_MOVE','COMPAT_MANUAL_MOVE') then RRL_STOCK_COMMAND_PLAN.compile_move(p_request,g_operation,v_policies,v_resources);  
   elsif g_kind ='INTERWARE_PUTAWAY_PLAN' then RRL_STOCK_INTERWARE_PUT.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind ='INTERWARE_CUSTODY_RELEASE' then RRL_STOCK_INTERWARE_CUSTODY.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='STORE_RETURN_DISPOSE' then RRL_STOCK_RETURN_DISPOSE.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='STORE_CUSTODY_RELEASE'then RRL_STOCK_STORE_CUSTODY_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='RESERVATION_ALLOCATE_POOL' then RRL_STOCK_POOL_CMD.compile_command(p_request,g_operation,p_hints,v_policies,v_resources,v_domain);  
   elsif g_kind='PICK_PALLET_BIND_SHIPMENT' then RRL_STOCK_FULLPAL_BIND_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind in('HU_PLAN_MOVE','HU_TASK_COMPLETE') then RRL_STOCK_HU_TASK.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='HU_RELOCATE_SLOT' then RRL_STOCK_HU_SLOT_MOVE_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='HU_REPACK_SLOT'then RRL_STOCK_HU_REPACK_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='HU_UNPACK' then RRL_STOCK_HU_UNPACK_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind in('TARE_LOSS_REPORT','TARE_LOSS_DECIDE') then RRL_STOCK_TARE_LOSS.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind in('TARE_BOOK','TARE_BOOK_CANCEL') then RRL_STOCK_TARE_BOOK_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind in('TARE_DAMAGE','TARE_WRITE_OFF') then RRL_STOCK_TARE_RESOLVE.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='TARE_OFFER_CANCEL'then RRL_STOCK_TARE_CANCEL_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind in('TARE_COUNT','TARE_OFFER','TARE_ACCEPT') then RRL_STOCK_TARE_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='STORE_RETURN_PUTAWAY_PLAN' then RRL_STOCK_STORE_RETURN_PUT.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='STORE_RETURN_RECEIVE' then RRL_STOCK_STORE_RETURN_REC_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind in('STORE_RETURN_HANDOVER','STORE_RETURN_PICKUP') then RRL_STOCK_STORE_RETURN_CUST_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='STORE_RETURN_TRANSPORT_PLAN' then RRL_STOCK_STORE_RETURN_TR_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='STORE_RETURN_SAP_BIND' then RRL_STOCK_STORE_RETURN_SAP_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='STORE_RETURN_APPROVE' then RRL_STOCK_STORE_RETURN_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='STORE_CASE_WORK' then RRL_STOCK_STORE_CASE_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='STORE_RECEIPT' then RRL_STOCK_STORE_RECEIPT_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='RECONCILE_HU_LOAD' then RRL_STOCK_LOAD_RECONCILE_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='UNLOAD_SHIPMENT' then RRL_STOCK_UNLOAD_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='LOAD_SHIPMENT' then RRL_STOCK_SINGLE_LOAD_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='TRIP_DEPART' then RRL_STOCK_TRIP_DEPART_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='HU_SHIP' then RRL_STOCK_HU_SHIP_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind in('HU_CREATE','HU_ATTACH','HU_DETACH','HU_MOVE') then RRL_STOCK_HU_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='WAVE_EXECUTION_FINISH' then RRL_STOCK_WAVE_FINISH_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
  elsif g_kind='WAVE_PICK_RELEASE' then RRL_STOCK_WAVE_PICK_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='WAVE_LAUNCH' then RRL_STOCK_WAVE_LAUNCH_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='OUTGOING_PALLET_CHECK' then RRL_STOCK_PALLET_QC_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='CASE_SHORT_APPROVE' then RRL_STOCK_CASE_SHORT_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='CASE_CARRIER_RETURN' then RRL_STOCK_CASE_RETURN_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='CASE_CARRIER_MOVE' then RRL_STOCK_CASE_MOVE_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='CASE_PICK_CONFIRM' then RRL_STOCK_CASE_PICK_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='RECEIPT_REVERSE' then RRL_STOCK_RECEIPT_REVERSE.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='INVENTORY_REGISTER_LOT' then RRL_STOCK_INVENTORY_BIRTH.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='INVENTORY_COUNT' then RRL_STOCK_INVENTORY_CMD.compile_count(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='MES_RAW_TASK_CANCEL' then RRL_STOCK_MES_CANCEL_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind in('MES_RELEASE_TO_PRODUCTION','MES_CALCULATE_SUPPLY') then RRL_STOCK_MES_SUPPLY_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind in('DOCUMENT_RELEASE_RESERVATIONS','WAVE_CANCEL','WAVE_RELEASE','PICK_PLAN_CANCEL') then RRL_STOCK_DOC_RESERVE_CMD.compile_release(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='WAVE_RESERVE_SOURCES' then RRL_STOCK_WAVE_CMD.compile_reserve(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind in('SHIP_DOCUMENT','SHIP_PALLET') then RRL_STOCK_SHIPPING_CORE.compile_shipment(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind in('INTERNAL_MOVE','MOVE_QUARANTINE') then RRL_STOCK_INTERNAL_CMD.compile_move(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='MES_MOVEMENTS' then RRL_STOCK_MES_MOVEMENT_PLAN.compile_movements(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind='SAP_RECEIPT' then RRL_STOCK_RECEIPT_PLAN.compile_receipt(p_request,g_operation,p_hints,v_policies,v_resources,v_domain);  
   elsif g_kind='TASK_COMPLETE' then RRL_STOCK_TASK_PLAN.compile_task(p_request,g_operation,v_policies,v_resources,v_domain);  
   elsif g_kind in('RESERVATION_CREATE','RESERVATION_PROMOTE','RESERVATION_RELEASE','RESERVATION_CANCEL','RESERVATION_CONSUME') then RRL_STOCK_RESERVATION_CMD.compile_command(p_request,g_operation,v_policies,v_resources,v_domain);  
   else raise_application_error(-20888,'COMMAND_HANDLER_NOT_INSTALLED');end if;  
   exception when others then  
    -- A concurrent identical command may have committed while this planner read mutable stock.  
    -- Rebuild only the existing replay lock plan; never take OP before the full resource plan.  
    select count(*) into v_exists from RRL_STOCK_OPERATION where OPERATION_ID=g_operation;  
    if v_exists=0 then raise;end if;  
    v_domain:=null;v_plan:=json_array_t();v_resources_json:=json_array_t();  
    v_entry:=json_object_t();v_entry.put('key_hex',rawtohex(RRL_STOCK_LOCK_API.resource_key('RELEASE','STOCK')));v_entry.put('mode',4);v_plan.append(v_entry);  
    v_entry:=json_object_t();v_entry.put('rank',10);v_entry.put('key_hex',rawtohex(RRL_STOCK_LOCK_API.resource_key('OP',g_operation)));v_resources_json.append(v_entry);  
    v_policies:=v_plan.to_clob;v_resources:=v_resources_json.to_clob;  
   end;  
  end if;  
  if v_domain is not null and p_hints is not null and g_kind in('INVENTORY_REGISTER_LOT','MES_MOVEMENTS') then  
   declare h json_object_t:=json_object_t.parse(p_hints);a json_array_t;b json_object_t;u json_object_t;  
    rr json_array_t:=json_array_t.parse(v_resources);dom json_object_t:=json_object_t.parse(v_domain);  
    uid varchar2(150);qty varchar2(30);base varchar2(20);cell varchar2(60);expected_article varchar2(160);found boolean;total number;  
   begin  
    a:=h.get_array('births');if a.get_size>200 then raise_application_error(-20881,'BIRTH_CAPTURE_BOUND');end if;  
    for i in 0..a.get_size-1 loop  
     b:=treat(a.get(i) as json_object_t);uid:=b.get_string('uid');found:=false;  
     if g_kind='INVENTORY_REGISTER_LOT' and dom.get_string('uid')=uid then  
      found:=true;qty:=dom.get_string('quantity');base:=dom.get_string('base');cell:=dom.get_string('cell');expected_article:=dom.get_string('article');  
     elsif g_kind='MES_MOVEMENTS' then  
      for z in 0..dom.get_array('movements').get_size-1 loop  
       u:=treat(dom.get_array('movements').get(z) as json_object_t);  
       if u.get_string('physical_uid')=uid and u.get_number('movement_id')=b.get_number('movement_id') then  
        declare m RRL_MES_MOVEMENT%rowtype;mid number:=u.get_number('movement_id');begin  
         select * into m from RRL_MES_MOVEMENT where MOVEMENT_ID=mid;  
         if m.MOVEMENT_TYPE!='FG_PALLET_RELEASE' then raise_application_error(-20884,'NOT_A_BIRTH_MOVEMENT');end if;  
         found:=true;qty:=u.get_string('base_quantity');base:=u.get_string('base_uom');cell:=m.TARGET_LOCATION;expected_article:=u.get_string('article');  
        end;  
       end if;  
      end loop;  
     end if;  
     if not found or RRL_STOCK_MATH.quantity(b.get_string('quantity'))!=RRL_STOCK_MATH.quantity(qty) or b.get_string('article')!=expected_article or b.get_string('base')!=base or b.get_string('cell')!=cell  
      then raise_application_error(-20890,'CLOSURE_CHANGED: birth capture');end if;  
     total:=0;  
     if b.get_array('unit_bindings').get_size<1 or b.get_array('unit_bindings').get_size>10000 then raise_application_error(-20881,'BIRTH_UNIT_BOUND');end if;  
     for z in 0..b.get_array('unit_bindings').get_size-1 loop  
      u:=treat(b.get_array('unit_bindings').get(z) as json_object_t);  
      total:=total+RRL_STOCK_MATH.quantity(u.get_string('quantity'));  
      RRL_STOCK_PLAN_HELPER.anchor(rr,60,'UNIT',u.get_string('key'));  
     end loop;  
     if total!=RRL_STOCK_MATH.quantity(qty) then raise_application_error(-20884,'BIRTH_UNIT_QUANTITY_CONFLICT');end if;  
     for z in 0..b.get_array('aliases').get_size-1 loop  
      u:=treat(b.get_array('aliases').get(z) as json_object_t);  
      RRL_STOCK_PLAN_HELPER.anchor(rr,70,'UNIQUE','MARK:'||u.get_string('system')||':'||u.get_string('hash'));  
     end loop;  
    end loop;  
    v_resources:=rr.to_clob;v_resolution.put('births',a);  
   end;  
  end if;  
  -- A composition update is a predeclared part of the same command, never a late lock.  
  declare rr json_array_t:=json_array_t.parse(v_resources);uid_value varchar2(200);raw_resources clob:=v_resources;begin  
   for k in(select distinct KEY_HEX from json_table(raw_resources,'$[*]' columns(RANK_NO number path '$.rank',KEY_HEX varchar2(2000) path '$.key_hex')) where RANK_NO=50) loop  
    uid_value:=RRL_STOCK_INVARIANT_CORE.stock_uid(hextoraw(k.KEY_HEX));  
    RRL_STOCK_PLAN_HELPER.row_key(rr,'RRL_PALLETS',uid_value);  
    for ct in(select CASE_PICK_TASK_ID,LEGACY_SBORKA_PALLET_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(select CASE_PICK_TASK_ID from RRL_CASE_CARRIER_LOT where LOT_UID=uid_value)) loop  
     RRL_STOCK_PLAN_HELPER.row_key(rr,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(ct.CASE_PICK_TASK_ID));  
     if ct.LEGACY_SBORKA_PALLET_ID is not null then RRL_STOCK_PLAN_HELPER.row_key(rr,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(ct.LEGACY_SBORKA_PALLET_ID));end if;  
    end loop;  
    for st in(select distinct LEGACY_SBORKA_PALLET_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where PICKED_PALLET_UID=uid_value and LEGACY_SBORKA_PALLET_ID is not null) loop  
     RRL_STOCK_PLAN_HELPER.row_key(rr,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(st.LEGACY_SBORKA_PALLET_ID));  
    end loop;  
   end loop;v_resources:=rr.to_clob;  
  end;  
  RRL_STOCK_LOCK_API.begin_plan;  
  RRL_STOCK_LOCK_API.acquire_policies(v_policies);  
  RRL_STOCK_LOCK_API.acquire_resources(v_resources);  
  assert_actor_active(p_actor);  
  if g_kind='STORE_RETURN_DISPOSE'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_RETURN_DISPOSE.assert_scope(doc.get_object('source').get_string('request_operation_id'),p_actor);end;end if;  
  if g_kind='STORE_RETURN_PUTAWAY_PLAN'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_STORE_RETURN_PUT.assert_scope(doc.get_object('source').get_string('receipt_operation_id'),p_actor);end;end if;  
  if g_kind='STORE_RETURN_RECEIVE'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_STORE_RETURN_REC_CMD.assert_scope(doc.get_object('source').get_string('pickup_operation_id'),p_actor);end;end if;  
  if g_kind in('STORE_RETURN_HANDOVER','STORE_RETURN_PICKUP')then RRL_STOCK_STORE_RETURN_CUST_CMD.assert_scope(p_request,p_actor);end if;  
  if g_kind='STORE_CUSTODY_RELEASE'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_STORE_CUSTODY_CMD.assert_scope(doc.get_object('source').get_string('receipt_operation_id'),p_actor);end;end if;  
  if g_kind='STORE_RETURN_APPROVE'then RRL_STOCK_STORE_RETURN_CMD.assert_actor(p_actor);end if;  
  if g_kind='STORE_RECEIPT'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_STORE_RECEIPT_READ.require_receiver(p_actor,doc.get_object('source').get_string('store_address'));end;end if;  
  if g_kind='INTERWARE_RECOVERY_CANCEL'then declare req json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_IW_RECOVERY_CANCEL.assert_scope(req.get_object('source').get_string('request_operation_id'),p_actor);end;end if;
  if g_kind='INTERWARE_RECOVERY_PUTAWAY_PLAN'then declare req json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_IW_RECOVERY_PUT.assert_scope(req.get_object('source').get_string('recovery_operation_id'),p_actor);end;end if;
  if g_kind='INTERWARE_SHORTAGE_RECOVER'then declare req json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_IW_RECOVERY_REC.assert_scope(req.get_object('source').get_string('approval_operation_id'),p_actor);end;end if;
  if g_kind in('INTERWARE_RECOVERY_REPORT','INTERWARE_RECOVERY_APPROVE')then RRL_STOCK_IW_RECOVERY_PLAN.assert_scope(p_request,p_actor);end if;
  if g_kind in('INTERWARE_SHORTAGE_REPORT','INTERWARE_SHORTAGE_CONFIRM')then RRL_STOCK_INTERWARE_SHORT_CMD.assert_scope(p_request,p_actor);end if; 
  if g_kind='INTERWARE_CUSTODY_RELEASE'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_INTERWARE_CUSTODY.assert_scope(doc.get_object('source').get_string('receipt_operation_id'),p_actor);end;end if;  
  if g_kind='INTERWARE_PUTAWAY_PLAN'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_INTERWARE_PUT.assert_scope(doc.get_object('source').get_string('receipt_operation_id'),p_actor,doc.get_object('metadata').get_number('superseded_task_id'));end;end if;  
  if g_kind in('INTERWARE_UNLOAD','INTERWARE_RECEIVE')then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_INTERWARE_REC.assert_scope(doc.get_object('source').get_string('plan_operation_id'),p_actor);end;end if;  
  if g_kind='LOAD_SHIPMENT'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_LOADING_READ.assert_scope(doc.get_object('source').get_string('pallet_identifier'),p_actor);end;end if;  
  if g_kind='TARE_OFFER_CANCEL'then RRL_STOCK_TARE_CANCEL_CMD.assert_scope(p_request,p_actor);end if;  
  if g_kind='TARE_BOOK'then RRL_TARE_LOAD_RECOVERY_API.assert_scope(p_request,p_actor);end if;assert_case_slot_actor(p_request,p_actor);assert_repack_actor(p_request,p_actor);  
  if g_kind='UNLOAD_SHIPMENT'then declare doc json_object_t:=json_object_t.parse(p_request);begin RRL_STOCK_UNLOAD_CMD.assert_scope(doc.get_object('source').get_string('load_operation_id'),p_actor);end;end if;  
  select STATE into v_release from RRL_STOCK_RELEASE where RELEASE_ID=1;  
  if v_release!='ACTIVE' then raise_application_error(-20860,'STOCK_RELEASE_NOT_ACTIVE'); end if;  
  if v_domain is not null then v_resolution.put('domain',json_object_t.parse(v_domain));end if;  
  v_resolution.put('stock_before',json_array_t.parse(RRL_STOCK_INVARIANT_CORE.snapshot_stock(v_resources)));  
  v_resolution.put('physical_before',json_array_t.parse(RRL_STOCK_COMPOSITION_CORE.snapshot_before(v_resources)));  
  v_resolution.put('resources',json_array_t.parse(v_resources));  
  v_resolution.put('policies',json_array_t.parse(v_policies));  
  if g_kind in('TASK_COMPLETE','HU_TASK_COMPLETE','PICK_PALLET_BIND_SHIPMENT') then RRL_WAREHOUSE_TASK_ACCESS.assert_completion(p_request,p_actor);end if;  
  if g_kind='OUTGOING_PALLET_CHECK'then RRL_OUTGOING_QC_ACCESS.assert_identifier(json_object_t.parse(p_request).get_object('source').get_string('pallet_identifier'),p_actor);end if;  
  if g_kind in('CASE_PICK_CONFIRM','CASE_CARRIER_MOVE','CASE_CARRIER_RETURN','CASE_SHORT_APPROVE')then RRL_CASE_TASK_ACCESS.assert_command(p_request,p_actor);end if;
  if g_kind='CASE_CARRIER_MOVE'then RRL_ST_DEFER_CASE_WAIT.assert_command(p_request,p_actor);end if;  
  if g_kind in('WAVE_EXECUTION_FINISH','WAVE_PICK_RELEASE')then RRL_WAVE_EXEC_ACCESS.assert_command(p_request,p_actor);end if;  
  RRL_STOCK_OPERATION_CORE.begin_operation(p_request,p_actor,g_operation,g_kind,p_replay,v_resolution.to_clob);  
  if p_replay is not null then return; end if;  
  g_change_before:=RRL_STOCK_CHANGE_AUDIT.snapshot(v_resources);  
  g_request:=p_request;g_resolution:=v_resolution.to_clob;g_actor:=p_actor;g_tx:=dbms_transaction.local_transaction_id(false);g_prepared:=true;  
  if g_kind='SAP_RECEIPT' then RRL_STOCK_CTX_API.begin_staging(v_resolution.get_object('domain').get_string('uid'),v_resolution.get_object('domain').get_string('receive_cell'));end if;  
 end;  
 procedure stage_birth(p_uid varchar2) is  
  d json_object_t:=json_object_t.parse(g_resolution);b json_object_t;v json_object_t;a json_array_t;  
  n number;policy number;capture_required number;found boolean:=false;uid varchar2(150);article varchar2(160);cell varchar2(60);qty number;  
  doc number;expiry date;price number;mid number;m RRL_MES_MOVEMENT%rowtype;  
 begin  
  if not g_prepared or g_tx is null or g_tx!=dbms_transaction.local_transaction_id(false)  
   or g_kind not in('INVENTORY_REGISTER_LOT','MES_MOVEMENTS') then raise_application_error(-20850,'WRITE_PLAN_VIOLATION');end if;  
  if RRL_HAS_WRIGHT(g_actor,case when g_kind='INVENTORY_REGISTER_LOT' then 'stock_inventory_count' else 'mes_wms_bridge_apply' end)!=1  
   then raise_application_error(-20882,'BIRTH_CAPTURE_FORBIDDEN');end if;  
  a:=d.get_array('births');  
  for i in 0..a.get_size-1 loop  
   b:=treat(a.get(i) as json_object_t);  
   if b.get_string('uid')=p_uid then found:=true;exit;end if;  
  end loop;  
  if not found then raise_application_error(-20884,'BIRTH_CAPTURE_NOT_PLANNED');end if;  
  uid:=b.get_string('uid');article:=b.get_string('article');cell:=b.get_string('cell');qty:=RRL_STOCK_MATH.quantity(b.get_string('quantity'));  
  select POLICY_VERSION,greatest(MARKING_REQUIRED,SERIALIZED_WEIGHT_BOXES)into policy,capture_required from RRL_SKU_RECEIPT_POLICY where ARTICUL=article;  
  if capture_required!=1 or policy!=b.get_number('policy_version') then raise_application_error(-20890,'CLOSURE_CHANGED: birth marking policy');end if;  
  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',uid));  
  select count(*) into n from RRL_REMAINS where UID_POLETA=uid and REMAIN>0;  
  if n>0 then raise_application_error(-20886,'BIRTH_STOCK_ALREADY_EXISTS');end if;  
  select count(*) into n from RRL_PALLETS where UID_PALLET=uid;  
  if n=0 then  
   if g_kind='INVENTORY_REGISTER_LOT' then  
    v:=d.get_object('domain');doc:=v.get_number('document');expiry:=to_date(v.get_string('expiry_date'),'FXYYYY-MM-DD');price:=v.get_number('price');  
    insert into RRL_PALLETS(UID_PALLET,ARTICUL,CREATION_DATE,EXPIRY_DATE,UNIT_COUNT,PRICE,PRIHOD_NAKLAD_ID,STOCK_ORIGIN_UID,CREATED_BY_STOCK_OP)  
     values(uid,article,systimestamp,expiry,qty,price,-doc,uid,g_operation);  
   else  
    mid:=b.get_number('movement_id');select * into m from RRL_MES_MOVEMENT where MOVEMENT_ID=mid;  
    insert into RRL_PALLETS(UID_PALLET,ARTICUL,UNIT_COUNT,PRIHOD_NAKLAD_ID,PROD_BATCH_ID,SSCC,QUALITY_STATUS,CREATED_BY_STOCK_OP)  
     values(uid,article,qty,0,m.PROD_BATCH_ID,m.SSCC,'RELEASED',g_operation);  
   end if;  
  end if;  
  RRL_STOCK_CTX_API.begin_staging(uid,cell);  
 end;  
 procedure finish_birth_capture is  
 begin  
  if not g_prepared or g_tx!=dbms_transaction.local_transaction_id(false) then raise_application_error(-20850,'WRITE_PLAN_VIOLATION');end if;  
  RRL_STOCK_CTX_API.end_effect;  
 end;  
 procedure execute_prepared(p_result out clob) is  
  v_outbox number;v_existing number;v_key varchar2(100);v_json json_object_t;v_resolved json_object_t;v_event json_object_t;v_changes clob;v_resources clob;v_after clob;v_composition json_object_t;v_unit_changes json_array_t;v_unit_change json_object_t;v_old_unit json_object_t;v_new_unit json_object_t;v_repacking boolean:=false;  
 begin  
  if not g_prepared or g_tx is null or dbms_transaction.local_transaction_id(false) is null  
   or g_tx!=dbms_transaction.local_transaction_id(false) then raise_application_error(-20850,'WRITE_PLAN_VIOLATION'); end if;  
  if g_kind='SAP_RECEIPT' then RRL_STOCK_CTX_API.end_effect;end if;  
  if g_kind='ST_PREPARED_ROW_MOVE'then RRL_STOCK_ST_ROW_CMD.execute_command(g_request,g_actor,p_result);
  elsif g_kind='CASE_PALLET_TYPE_CHANGE'then RRL_STOCK_CASE_TYPE_CMD.execute_command(g_request,g_actor,p_result);
  elsif g_kind='PALLET_FLOOR_TYPE_CONFIRM'then RRL_STOCK_PALLET_TYPE_CMD.execute_command(g_request,g_actor,p_result);
  elsif g_kind in('MANUAL_MOVE','COMPAT_MANUAL_MOVE') then RRL_STOCK_MOVE_CORE.manual_whole(g_request,g_actor,p_result);  
  elsif g_kind='PICK_PALLET_BIND_SHIPMENT' then RRL_STOCK_FULLPAL_BIND_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind in('HU_PLAN_MOVE','HU_TASK_COMPLETE') then RRL_STOCK_HU_TASK.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='HU_RELOCATE_SLOT' then RRL_STOCK_HU_SLOT_MOVE_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='HU_REPACK_SLOT'then RRL_STOCK_HU_REPACK_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='HU_UNPACK' then RRL_STOCK_HU_UNPACK_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind in('TARE_LOSS_REPORT','TARE_LOSS_DECIDE') then RRL_STOCK_TARE_LOSS.execute_command(g_request,g_actor,p_result);  
  elsif g_kind in('TARE_BOOK','TARE_BOOK_CANCEL') then RRL_STOCK_TARE_BOOK_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind in('TARE_DAMAGE','TARE_WRITE_OFF') then RRL_STOCK_TARE_RESOLVE.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='TARE_OFFER_CANCEL'then RRL_STOCK_TARE_CANCEL_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind in('TARE_COUNT','TARE_OFFER','TARE_ACCEPT') then RRL_STOCK_TARE_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_RETURN_PUTAWAY_PLAN' then RRL_STOCK_STORE_RETURN_PUT.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_RETURN_RECEIVE' then RRL_STOCK_STORE_RETURN_REC_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind in('STORE_RETURN_HANDOVER','STORE_RETURN_PICKUP') then RRL_STOCK_STORE_RETURN_CUST_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_RETURN_TRANSPORT_PLAN' then RRL_STOCK_STORE_RETURN_TR_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_RETURN_SAP_BIND' then RRL_STOCK_STORE_RETURN_SAP_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_RETURN_APPROVE' then RRL_STOCK_STORE_RETURN_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_CASE_WORK' then RRL_STOCK_STORE_CASE_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_RECEIPT' then RRL_STOCK_STORE_RECEIPT_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='RECONCILE_HU_LOAD' then RRL_STOCK_LOAD_RECONCILE_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='UNLOAD_SHIPMENT' then RRL_STOCK_UNLOAD_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='INTERWARE_RECOVERY_CANCEL'then RRL_STOCK_IW_RECOVERY_CANCEL.execute_command(g_request,g_actor,p_result);
  elsif g_kind='INTERWARE_RECOVERY_PUTAWAY_PLAN'then RRL_STOCK_IW_RECOVERY_PUT.execute_command(g_request,g_actor,p_result);
  elsif g_kind='INTERWARE_SHORTAGE_RECOVER'then RRL_STOCK_IW_RECOVERY_REC.execute_command(g_request,g_actor,p_result);
  elsif g_kind in('INTERWARE_RECOVERY_REPORT','INTERWARE_RECOVERY_APPROVE')then RRL_STOCK_IW_RECOVERY_PLAN.execute_command(g_request,g_actor,p_result);
  elsif g_kind in('INTERWARE_SHORTAGE_REPORT','INTERWARE_SHORTAGE_CONFIRM')then RRL_STOCK_INTERWARE_SHORT_CMD.execute_command(g_request,g_actor,p_result); 
  elsif g_kind in('INTERWARE_UNLOAD','INTERWARE_RECEIVE') then RRL_STOCK_INTERWARE_REC.execute_command(g_request,g_actor,p_result);  
  elsif g_kind ='INTERWARE_PUTAWAY_PLAN' then RRL_STOCK_INTERWARE_PUT.execute_command(g_request,g_actor,p_result);  
  elsif g_kind ='INTERWARE_CUSTODY_RELEASE' then RRL_STOCK_INTERWARE_CUSTODY.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_RETURN_DISPOSE' then RRL_STOCK_RETURN_DISPOSE.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='STORE_CUSTODY_RELEASE'then RRL_STOCK_STORE_CUSTODY_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='LOAD_SHIPMENT' then RRL_STOCK_SINGLE_LOAD_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='TRIP_DEPART' then RRL_STOCK_TRIP_DEPART_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='HU_SHIP' then RRL_STOCK_HU_SHIP_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind in('HU_CREATE','HU_ATTACH','HU_DETACH','HU_MOVE') then RRL_STOCK_HU_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='WAVE_EXECUTION_FINISH' then RRL_STOCK_WAVE_FINISH_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='WAVE_PICK_RELEASE' then RRL_STOCK_WAVE_PICK_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='WAVE_LAUNCH' then RRL_STOCK_WAVE_LAUNCH_CMD.execute_command(g_request,g_actor,p_result);  
   elsif g_kind='OUTGOING_PALLET_CHECK' then RRL_STOCK_PALLET_QC_CMD.execute_command(g_request,g_actor,p_result);  
   elsif g_kind='CASE_SHORT_APPROVE' then RRL_STOCK_CASE_SHORT_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='CASE_CARRIER_RETURN' then RRL_STOCK_CASE_RETURN_CMD.execute_command(g_request,g_actor,p_result);  
   elsif g_kind='CASE_CARRIER_MOVE' then RRL_STOCK_CASE_MOVE_CMD.execute_command(g_request,g_actor,p_result);  
   elsif g_kind='CASE_PICK_CONFIRM' then RRL_STOCK_CASE_PICK_CMD.execute_command(g_request,g_actor,p_result);  
   elsif g_kind='RECEIPT_REVERSE' then RRL_STOCK_RECEIPT_REVERSE.execute_command(g_request,g_actor,p_result);  
   elsif g_kind='INVENTORY_REGISTER_LOT' then RRL_STOCK_INVENTORY_BIRTH.execute_command(g_request,g_actor,p_result);  
   elsif g_kind='INVENTORY_COUNT' then RRL_STOCK_INVENTORY_CMD.execute_count(g_request,g_actor,p_result);  
   elsif g_kind='MES_RAW_TASK_CANCEL' then RRL_STOCK_MES_CANCEL_CMD.execute_command(g_request,g_actor,p_result);  
   elsif g_kind in('MES_RELEASE_TO_PRODUCTION','MES_CALCULATE_SUPPLY') then RRL_STOCK_MES_SUPPLY_CMD.execute_command(g_request,g_actor,p_result);  
   elsif g_kind in('DOCUMENT_RELEASE_RESERVATIONS','WAVE_CANCEL','WAVE_RELEASE','PICK_PLAN_CANCEL') then RRL_STOCK_DOC_RESERVE_CMD.execute_release(g_request,g_actor,p_result);  
  elsif g_kind='RESERVATION_ALLOCATE_POOL' then RRL_STOCK_POOL_CMD.execute_command(g_request,g_actor,p_result);  
  elsif g_kind='WAVE_RESERVE_SOURCES' then RRL_STOCK_WAVE_CMD.execute_reserve(g_request,g_actor,p_result);  
  elsif g_kind in('SHIP_DOCUMENT','SHIP_PALLET') then RRL_STOCK_SHIPPING_CORE.execute_shipment(g_request,g_actor,p_result);  
  elsif g_kind in('INTERNAL_MOVE','MOVE_QUARANTINE') then RRL_STOCK_INTERNAL_CMD.execute_move(g_request,g_actor,p_result);  
  elsif g_kind='MES_MOVEMENTS' then RRL_STOCK_MES_MOVEMENT_CORE.execute_movements(g_request,g_actor,p_result);  
  elsif g_kind='SAP_RECEIPT' then RRL_STOCK_RECEIPT_CORE.execute_receipt(g_request,g_actor,p_result);  
  elsif g_kind='TASK_COMPLETE' then RRL_STOCK_TASK_CORE.execute_task(g_request,g_actor,p_result);  
  elsif g_kind in('RESERVATION_CREATE','RESERVATION_PROMOTE','RESERVATION_RELEASE','RESERVATION_CANCEL','RESERVATION_CONSUME') then RRL_STOCK_RESERVATION_CMD.execute_command(g_request,g_actor,p_result);  
  else raise_application_error(-20888,'COMMAND_HANDLER_NOT_INSTALLED'); end if;  
  v_resolved:=json_object_t.parse(g_resolution);  
  RRL_STOCK_COMPOSITION_CORE.finish_changes(v_resolved.get_array('physical_before').to_clob);  
  RRL_STOCK_INVARIANT_CORE.verify_posting(v_resolved.get_array('resources').to_clob,v_resolved.get_array('stock_before').to_clob,g_operation);  
  v_key:='STOCK:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(g_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256));  
  RRL_STOCK_LOCK_API.assert_held(70,RRL_STOCK_LOCK_API.resource_key('UNIQUE','STOCK.OUTBOX:'||substr(v_key,7)));  
  select count(*) into v_existing from RRL_EVENT_OUTBOX where IDEMPOTENCY_KEY=v_key;  
  if v_existing!=0 then raise_application_error(-20889,'OUTBOX_IDENTITY_CONFLICT'); end if;  
  v_resources:=v_resolved.get_array('resources').to_clob;  
  v_after:=RRL_STOCK_CHANGE_AUDIT.snapshot(v_resources);v_changes:=RRL_STOCK_CHANGE_AUDIT.differences(g_change_before,v_after);  
  v_event:=json_object_t();v_event.put('contract_version',3);v_event.put('operation_id',g_operation);v_event.put('command_type',g_kind);  
  v_event.put('source',json_object_t.parse(g_request).get_object('source'));v_event.put('result',json_object_t.parse(p_result));  
  v_event.put('stock_before',v_resolved.get_array('stock_before'));  
  v_event.put('stock_after',json_array_t.parse(RRL_STOCK_INVARIANT_CORE.snapshot_stock(v_resources)));  
  v_composition:=json_object_t.parse(v_changes);v_unit_changes:=v_composition.get_array('units');  
  for i in 0..v_unit_changes.get_size-1 loop  
   v_unit_change:=treat(v_unit_changes.get(i) as json_object_t);  
   if not v_unit_change.get('before').is_null and not v_unit_change.get('after').is_null then  
    v_old_unit:=v_unit_change.get_object('before');v_new_unit:=v_unit_change.get_object('after');  
    if v_old_unit.get_string('uid')!=v_new_unit.get_string('uid') then v_repacking:=true;end if;  
   end if;  
  end loop;  
  v_event.put('composition_changes',v_composition);  
  if v_repacking then  
   v_event.put('regulatory_composition_status','PENDING');  
   v_event.put('regulatory_action','PHYSICAL_REPACK_PROPOSED');  
  end if;  
  v_event.put('immutable_request_reference',g_operation);  
  v_outbox:=RRL_TRACEABILITY_API.enqueue_event('STOCK_POSTED','STOCK_OPERATION',g_operation,v_key,v_event.to_clob,'WMS',g_operation);  
  v_json:=json_object_t.parse(p_result);v_json.put('outbox_id',v_outbox);  
  if v_repacking then v_json.put('regulatory_composition_status','PENDING');end if;  
  p_result:=v_json.to_clob;  
  RRL_STOCK_OPERATION_CORE.finish_operation(g_operation,p_result);  
  g_prepared:=false;  
 end;  
end;
/


CREATE OR REPLACE package body RRL_STOCK_QC_CASE as
 function nested(p_domain clob) return number is
  d json_object_t:=json_object_t.parse(p_domain);v_case number:=d.get_number('case_task');a json_array_t:=d.get_array('legs');l json_object_t;n number;v_uid varchar2(150);
 begin
  if v_case is not null then select count(*) into n from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=v_case and ACTIVE_FLAG=1;if n>0 then return 1;end if;end if;
  for i in 0..a.get_size-1 loop l:=treat(a.get(i) as json_object_t);v_uid:=l.get_string('uid');
   select count(*) into n from RRL_WMS_HU_LINK where CHILD_PALLET_UID=v_uid and ACTIVE_FLAG=1;if n>0 then return 1;end if;
  end loop;return 0;
 end;
 procedure project(p_domain clob,p_ready number,p_failed number,p_is_plan number,p_actor varchar2,p_operation varchar2,p_reason varchar2) is
  d json_object_t:=json_object_t.parse(p_domain);v_case number:=d.get_number('case_task');ct RRL_CASE_PICK_TASK%rowtype;
  v_payload clob;v_status varchar2(40);v_event varchar2(40);j json_object_t:=json_object_t();
 begin
  if v_case is null then return;end if;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_case)));
  select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case for update;
  if ct.LEGACY_SBORKA_PALLET_ID!=d.get_number('document_id') or ct.WARE_ID!=d.get_number('warehouse')
   or ct.CONTENT_VERSION!=d.get_number('case_version') or ct.STATUS not in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP') then
   raise_application_error(-20890,'CLOSURE_CHANGED: CASE control');end if;
  if p_ready=1 then
   if p_is_plan=1 then v_status:=case when ct.STATUS in('CONTROLLED','READY_TO_SHIP') then ct.STATUS else 'READY_TO_SHIP' end;v_event:='CONTROL_PLAN_READY';
   else v_status:='CONTROLLED';v_event:='CONTROL_PASSED';end if;
  elsif p_failed=1 then v_status:='WAIT_CONTROL';v_event:='CONTROL_FAILED';
  else v_status:='CONTROL_IN_PROGRESS';v_event:=case when p_is_plan=1 then 'CONTROL_PLAN_ASSIGNED' else 'CONTROL_PENDING' end;end if;
  update RRL_CASE_PICK_TASK set STATUS=v_status,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=v_case;
  j.put('operation_id',p_operation);j.put('previous_status',ct.STATUS);j.put('status',v_status);j.put('ready',p_ready=1);j.put('failure_reason',p_reason);
  v_payload:=j.to_clob;
  insert into RRL_CASE_PICK_EVENT(CASE_PICK_EVENT_ID,CASE_PICK_TASK_ID,EVENT_TYPE,PAYLOAD_JSON,CREATED_BY)
   values(RRL_CASE_PICK_EVENT_SQ.nextval,v_case,v_event,v_payload,p_actor);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_QC_GATE as
 function signature_version_for_plan(p_domain clob)return number is
  d json_object_t:=json_object_t.parse(p_domain);task_no number:=d.get_number('case_task');n number;
 begin
  if task_no is null then return 2;end if;
  select case when p.FINAL_WEIGHT_REQUIRED=1 and upper(p.LOAD_UNIT_CLASS)='CONTAINER'then 3 else 2 end into n
   from RRL_CASE_PICK_TASK c join RRL_PALLET_TYPE p on p.PALLET_TYPE_ID=c.PALLET_TYPE_ID where c.CASE_PICK_TASK_ID=task_no;
  return n;
 end;
 function signature_for_plan(p_domain clob) return varchar2 is
  d json_object_t:=json_object_t.parse(p_domain);j json_object_t:=json_object_t();a json_array_t:=json_array_t();legs json_array_t:=d.get_array('legs');
  l json_object_t;x json_object_t;units json_array_t;links json_array_t;profiles json_array_t;codes json_array_t;c json_object_t;u json_object_t;
  v_uid varchar2(150);v_ware number:=d.get_number('warehouse');v_article varchar2(160);v_case number:=d.get_number('case_task');v_codes number:=0;v_units number:=0;v_links number:=0;v_signature_version number;
 begin
  v_signature_version:=signature_version_for_plan(p_domain);j.put('version',v_signature_version);
  if v_signature_version=3 then
   for z in(select SSCC,PALLET_TYPE_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case)loop j.put('case_identifier',z.SSCC);j.put('case_type_id',z.PALLET_TYPE_ID);end loop;
  end if;j.put('document_id',d.get_number('document_id'));j.put('identifier',d.get_string('pallet_identifier'));
  j.put('warehouse',d.get_number('warehouse'));j.put('customer_order',d.get_number('customer_order_id'));
  declare scoped_policy json_object_t:=json_object_t.parse(RRL_QC_SCOPE_READ.policy_json(p_domain));begin
   if scoped_policy.has('policy_stamp')then j.put('scope_policy_stamp',scoped_policy.get_string('policy_stamp'));end if;end;
  j.put('return_supplier',d.get_string('return_supplier_id'));j.put('rows',d.get_string('rows_signature'));
  for i in 0..legs.get_size-1 loop
   l:=treat(legs.get(i) as json_object_t);v_uid:=l.get_string('uid');x:=json_object_t();
   x.put('row',l.get_number('row_id'));x.put('uid',v_uid);x.put('quantity',l.get_string('quantity'));
   x.put('base_uom',l.get_string('base_uom'));x.put('uom_policy',l.get_number('uom_version'));
   x.put('owner_type',l.get_string('owner_type'));x.put('owner_id',l.get_number('owner_id'));x.put('pick_task',l.get_number('pick_task_id'));
   for p in(select ARTICUL,STOCK_COMPOSITION_VERSION,EXPIRY_DATE,PRODUCED_DATE,PROD_BATCH_ID,STOCK_ORIGIN_UID,SSCC,STOCK_BOX_FACTOR,STOCK_PACK_BASE_UOM
    from RRL_PALLETS where UID_PALLET=v_uid) loop
    for sku in(select BARCODE_SHT,BARCODE_KOR from RRL_ARTICULS where ACTICUL=p.ARTICUL) loop x.put('item_barcode',sku.BARCODE_SHT);x.put('box_barcode',sku.BARCODE_KOR);end loop;
    x.put('article',p.ARTICUL);x.put('stock_composition_version',p.STOCK_COMPOSITION_VERSION);x.put('expiry',to_char(p.EXPIRY_DATE,'YYYY-MM-DD HH24:MI:SS'));
    x.put('produced',to_char(p.PRODUCED_DATE,'YYYY-MM-DD HH24:MI:SS'));x.put('batch',p.PROD_BATCH_ID);x.put('origin',p.STOCK_ORIGIN_UID);
    x.put('sscc',p.SSCC);x.put('box_factor',p.STOCK_BOX_FACTOR);x.put('pack_uom',p.STOCK_PACK_BASE_UOM);
    profiles:=json_array_t();
    for z in(select POLICY_VERSION,MARKING_REQUIRED from RRL_SKU_RECEIPT_POLICY where ARTICUL=p.ARTICUL order by POLICY_VERSION) loop
     u:=json_object_t();u.put('policy',z.POLICY_VERSION);u.put('marking',z.MARKING_REQUIRED);profiles.append(u);
    end loop;
    for z in(select SYSTEM_CODE,PROFILE_CODE,PROFILE_VERSION,SCAN_MODE from RRL_SKU_RECEIPT_PROFILE where ARTICUL=p.ARTICUL order by SYSTEM_CODE,PROFILE_CODE) loop
     u:=json_object_t();u.put('system',z.SYSTEM_CODE);u.put('profile',z.PROFILE_CODE);u.put('version',z.PROFILE_VERSION);u.put('scan_mode',z.SCAN_MODE);profiles.append(u);
    end loop;x.put('profiles',profiles);
    for z in(select CRPT_REQUIRED from RRL_FINISHED_GOODS_SKU where ARTICUL=p.ARTICUL) loop x.put('legacy_crpt_required',z.CRPT_REQUIRED);end loop;
   end loop;
   v_article:=l.get_string('article');
   for z in(select QC_BASE_WEIGHT_KG,QC_BOX_WEIGHT_KG,QC_WEIGHT_VERSION,QC_WEIGHT_BASE_UOM from RRL_RECEIPT_SKU_RULE
    where WARE_ID=v_ware and ARTICUL=v_article) loop
    x.put('weight_base_uom',z.QC_WEIGHT_BASE_UOM);x.put('weight_version',z.QC_WEIGHT_VERSION);x.put('base_weight_kg',z.QC_BASE_WEIGHT_KG);x.put('box_weight_kg',z.QC_BOX_WEIGHT_KG);
   end loop;
   units:=json_array_t();
   for z in(select UID_PALLET,PHYSICAL_UNIT_KEY,UNIT_ID,POLICY_VERSION,BASE_QTY,BASE_UOM from RRL_WMS_RECEIPT_UNIT
    where CURRENT_UID=v_uid and STOCK_STATUS='AVAILABLE' order by PHYSICAL_UNIT_KEY fetch first 10001 rows only) loop
    v_units:=v_units+1;if v_units>10000 then raise_application_error(-20881,'QUALITY_UNIT_BOUND');end if;
    u:=json_object_t();u.put('key',z.PHYSICAL_UNIT_KEY);u.put('id',z.UNIT_ID);u.put('policy',z.POLICY_VERSION);u.put('quantity',z.BASE_QTY);u.put('uom',z.BASE_UOM);units.append(u);
   end loop;x.put('units',units);codes:=json_array_t();
   for code in(select u.PHYSICAL_UNIT_KEY,c.SYSTEM_CODE,c.CODE_HASH,c.PROFILES_JSON from RRL_WMS_RECEIPT_UNIT u
    join RRL_WMS_RECEIPT_CODE c on c.UID_PALLET=u.UID_PALLET and c.UNIT_ID=u.UNIT_ID
    where u.CURRENT_UID=v_uid and u.STOCK_STATUS='AVAILABLE' order by u.PHYSICAL_UNIT_KEY,c.SYSTEM_CODE,c.CODE_HASH fetch first 20001 rows only) loop
    v_codes:=v_codes+1;if v_codes>20000 then raise_application_error(-20881,'QUALITY_CODE_COMPOSITION_BOUND');end if;
    c:=json_object_t();c.put('key',code.PHYSICAL_UNIT_KEY);c.put('system',code.SYSTEM_CODE);c.put('hash',code.CODE_HASH);c.put('profiles',json_array_t.parse(code.PROFILES_JSON));codes.append(c);
   end loop;x.put('codes',codes);links:=json_array_t();
   if v_signature_version=2 then
   for z in(select HU_LINK_ID,PARENT_UID,LINK_VERSION,level DEPTH,connect_by_iscycle CYCLIC from RRL_WMS_HU_LINK
    start with (CHILD_PALLET_UID=v_uid or CHILD_CASE_TASK_ID=v_case) and ACTIVE_FLAG=1
    connect by nocycle prior PARENT_UID=CHILD_PALLET_UID and ACTIVE_FLAG=1 order siblings by HU_LINK_ID) loop
    v_links:=v_links+1;if v_links>3200 or z.DEPTH>16 or z.CYCLIC=1 then raise_application_error(-20881,'QUALITY_HIERARCHY_BOUND');end if;
    u:=json_object_t();u.put('id',z.HU_LINK_ID);u.put('parent',z.PARENT_UID);u.put('version',z.LINK_VERSION);links.append(u);
   end loop;
   end if;x.put('links',links);
   for z in(select CASE_PICK_TASK_ID,CREATED_OPERATION from RRL_CASE_CARRIER_LOT where LOT_UID=v_uid) loop
    x.put('case',z.CASE_PICK_TASK_ID);x.put('case_membership',z.CREATED_OPERATION);
   end loop;a.append(x);
  end loop;
  j.put('allocations',a);return rawtohex(sys.dbms_crypto.hash(j.to_clob,sys.dbms_crypto.hash_sh256));
 end;
 procedure assert_approved(p_domain clob) is
  d json_object_t:=json_object_t.parse(p_domain);v_id number:=d.get_number('document_id');v_mode varchar2(10);v_independent number;
  v_scan number;v_weight number;v_mark_proved number;v_signature varchar2(64);v_scan_sig varchar2(64);v_weight_sig varchar2(64);
  v_scan_op varchar2(100);v_weight_op varchar2(100);v_actor varchar2(100);v_method varchar2(20);v_expected number;v_tolerance number;v_current number;v_current_tolerance number;
  v_full_scan number;v_item_proved number;v_marked number;scan_ok boolean:=false;weight_ok boolean:=false;
 begin
  RRL_STOCK_QC_POLICY.settings_for_plan(p_domain,v_mode,v_independent);v_marked:=RRL_STOCK_QC_MARK.required_for_plan(p_domain);v_full_scan:=RRL_STOCK_QC_POLICY.full_scan_required(p_domain);
  if v_mode='NONE' and v_marked=0 and v_full_scan=0 then return;end if;
  select nvl(PROOVED_BY_SCAN,0),nvl(PROOVED,0),SCAN_MARK_PROVED,SCAN_CONTENT_SIGNATURE,WEIGHT_CONTENT_SIGNATURE,
   SCAN_QC_OPERATION_ID,WEIGHT_QC_OPERATION_ID,WEIGHT_QC_METHOD,WEIGHT_QC_EXPECTED,WEIGHT_QC_TOLERANCE,SCAN_ITEM_PROVED
   into v_scan,v_weight,v_mark_proved,v_scan_sig,v_weight_sig,v_scan_op,v_weight_op,v_method,v_expected,v_tolerance,v_item_proved from RRL_SBORKA_PALLETS where ID=v_id;
  v_signature:=signature_for_plan(p_domain);
  if v_scan=1 and v_scan_sig=v_signature then
   if v_independent=0 then scan_ok:=true;else
    begin select ACTOR into v_actor from RRL_STOCK_OPERATION where OPERATION_ID=v_scan_op and STATE='APPLIED';
     scan_ok:=RRL_STOCK_QC_POLICY.controller_allowed(p_domain,v_actor)=1;
    exception when no_data_found then scan_ok:=false;end;
   end if;
  end if;
  if v_weight=1 and v_weight_sig=v_signature and v_method in('WEIGHT','WEIGHT2') then
   RRL_STOCK_QC_WEIGHT.calculate(p_domain,v_current,v_current_tolerance);
   if v_current=v_expected and v_current_tolerance=v_tolerance then
    if v_independent=0 then weight_ok:=true;else
     begin select ACTOR into v_actor from RRL_STOCK_OPERATION where OPERATION_ID=v_weight_op and STATE='APPLIED';
      weight_ok:=RRL_STOCK_QC_POLICY.controller_allowed(p_domain,v_actor)=1;
     exception when no_data_found then weight_ok:=false;end;
    end if;
   end if;
  end if;
  -- The currently executing QC operation is still POSTING, not APPLIED. Its authenticated context is authoritative.
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')=v_scan_op and v_scan=1 and v_scan_sig=v_signature then
   select ACTOR into v_actor from RRL_STOCK_OPERATION where OPERATION_ID=v_scan_op;scan_ok:=RRL_STOCK_QC_POLICY.controller_allowed(p_domain,v_actor)=1;end if;
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')=v_weight_op and v_weight=1 and v_weight_sig=v_signature then
   select ACTOR into v_actor from RRL_STOCK_OPERATION where OPERATION_ID=v_weight_op;weight_ok:=RRL_STOCK_QC_POLICY.controller_allowed(p_domain,v_actor)=1;end if;
  if weight_ok and RRL_WH_FINAL_SCALE_ADMISSION.approved(p_domain,v_weight_op)!=1 then weight_ok:=false;end if;
  if v_mode in('ANY','WEIGHT','BOTH') and json_object_t.parse(RRL_QC_SCOPE_READ.exemption_json(p_domain)).get_boolean('eligible')then weight_ok:=true;end if;
  if v_marked=1 and (not scan_ok or v_mark_proved!=1) then raise_application_error(-20886,'SHIPMENT_CURRENT_UNIQUE_MARK_CONTROL_REQUIRED');end if;
  if v_full_scan=1 and (not scan_ok or v_item_proved!=1) then raise_application_error(-20886,'SHIPMENT_FULL_COMPOSITION_SCAN_REQUIRED');end if;
  if v_mode='NONE' or(v_mode='ANY' and(scan_ok or weight_ok)) or(v_mode='SCAN' and scan_ok)
   or(v_mode='WEIGHT' and weight_ok) or(v_mode='BOTH' and scan_ok and weight_ok) then return;end if;
  raise_application_error(-20886,'SHIPMENT_CURRENT_COMPOSITION_QUALITY_REQUIRED:'||v_mode);
 end;
 function status_json(p_identifier varchar2) return clob is
  j json_object_t:=json_object_t();d json_object_t:=json_object_t();s json_object_t:=json_object_t();
  domain clob;policies clob;resources clob;v_signature varchar2(64);v_ware number;v_required number;v_id number;v_scan varchar2(64);v_weight varchar2(64);v_expected number;v_tolerance number;profiles json_array_t:=json_array_t();profile json_object_t;v_unit_count number;v_legs clob;v_bucket number;v_percent number;v_selected number;v_rescan number;v_mode varchar2(10);v_independent number;
 begin
  select p.ID,p.WARE_ID,nvl(w.BLOCK_IF_NO_PROOVE,0),p.SCAN_CONTENT_SIGNATURE,p.WEIGHT_CONTENT_SIGNATURE
   into v_id,v_ware,v_required,v_scan,v_weight from RRL_SBORKA_PALLETS p join RRL_WARES w on w.ID=p.WARE_ID where p.PALLET_UID=p_identifier;
  j.put('shipment_identifier',p_identifier);j.put('document_id',v_id);RRL_STOCK_QC_POLICY.settings(v_ware,v_mode,v_independent);j.put('required',v_mode!='NONE');j.put('control_mode',v_mode);j.put('independent_controller_required',v_independent=1);j.put('ready',false);j.put('weight_exemption_recorded',false);
  d.put('command_type','SHIP_PALLET');s.put('pallet_identifier',p_identifier);d.put('source',s);
  begin
   RRL_STOCK_SHIPPING_CORE.compile_shipment(d.to_clob,'READ.QC:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_id),policies,resources,domain,true);
   RRL_STOCK_QC_POLICY.settings_for_plan(domain,v_mode,v_independent);
   declare dom json_object_t:=json_object_t.parse(domain);task_no number;required_flag number:=0;begin
    task_no:=dom.get_number('case_task');j.put('case_task_id',task_no);j.put('case_content_version',dom.get_number('case_version'));j.put('composition_signature_version',signature_version_for_plan(domain));
    if task_no is not null then select case when p.FINAL_WEIGHT_REQUIRED=1 and upper(p.LOAD_UNIT_CLASS)='CONTAINER'then 1 else 0 end into required_flag
     from RRL_CASE_PICK_TASK c join RRL_PALLET_TYPE p on p.PALLET_TYPE_ID=c.PALLET_TYPE_ID where c.CASE_PICK_TASK_ID=task_no;end if;
    j.put('final_scale_required',required_flag=1);
   end;
   j.put('required',v_mode!='NONE');j.put('control_mode',v_mode);j.put('independent_controller_required',v_independent=1);
   j.put('quality_policy',json_object_t.parse(RRL_QC_SCOPE_READ.policy_json(domain)));
   j.put('weight_exemption',json_object_t.parse(RRL_QC_SCOPE_READ.exemption_json(domain)));
   j.put('unique_mark_control_required',RRL_STOCK_QC_MARK.required_for_plan(domain)=1);
   for z in(select distinct r.SYSTEM_CODE,r.PROFILE_CODE from RRL_SKU_RECEIPT_PROFILE r
    join RRL_SBORKA_PALLET_ROWS sr on sr.ARTICUL=r.ARTICUL where sr.PALLET_UID=p_identifier order by r.SYSTEM_CODE,r.PROFILE_CODE fetch first 51 rows only) loop
    if profiles.get_size>=50 then raise_application_error(-20881,'QUALITY_MARK_PROFILE_BOUND');end if;
    profile:=json_object_t();profile.put('system_code',z.SYSTEM_CODE);profile.put('profile_code',z.PROFILE_CODE);profiles.append(profile);
   end loop;j.put('mark_profiles',profiles);
   declare v_case number:=json_object_t.parse(domain).get_number('case_task');v_case_status varchar2(40);begin
    if v_case is not null then select STATUS into v_case_status from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case;j.put('case_task_id',v_case);j.put('case_status',v_case_status);end if;
   end;
   v_legs:=json_object_t.parse(domain).get_array('legs').to_clob;
   select count(distinct u.PHYSICAL_UNIT_KEY) into v_unit_count from
    json_table(v_legs,'$[*]' columns(U varchar2(150) path '$.uid',C varchar2(60) path '$.cell'))l
    join RRL_WMS_RECEIPT_UNIT u on u.CURRENT_UID=l.U and u.CURRENT_CELL=l.C and u.STOCK_STATUS='AVAILABLE';
   j.put('physical_unit_count',v_unit_count);
   v_signature:=signature_for_plan(domain);j.put('composition_signature',v_signature);
   declare recorded_count number;begin
    select count(*) into recorded_count from RRL_QC_EXEMPT_FACT f
     where f.DOCUMENT_ID=v_id
      and json_value(f.PAYLOAD_JSON,'$.composition_signature' returning varchar2(64))=v_signature
      and rownum=1;
    j.put('weight_exemption_recorded',recorded_count=1);
   end;
   RRL_STOCK_QC_POLICY.sampling(domain,v_bucket,v_percent,v_selected,v_rescan);
   j.put('sample_percent',v_percent);j.put('sample_selected',v_selected=1);j.put('rescan_required',v_rescan=1);
   j.put('control_plan_required',v_bucket is null and v_percent>0);j.put('full_scan_required',v_mode in('SCAN','BOTH') or v_selected=1 or v_rescan=1);
   j.put('scan_matches',v_scan=v_signature);j.put('weight_matches',v_weight=v_signature);
   begin
    RRL_STOCK_QC_WEIGHT.calculate(domain,v_expected,v_tolerance);
    j.put('expected_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_expected));
    j.put('tolerance_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_tolerance));
   exception when others then j.put('weight_policy_reason',substr(sqlerrm,1,1000));end;
   assert_approved(domain);j.put('ready',true);
  exception when others then j.put('reason',substr(sqlerrm,1,1000));end;
  return j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_QC_ITEM as
 procedure resolve_barcode(p_code varchar2,p_article out varchar2,p_input_uom out varchar2) is n number:=0;
 begin
  if p_code is null or lengthb(p_code)>128 then raise_application_error(-20886,'QUALITY_FOREIGN_ITEM_BARCODE');end if;
  for z in(select ACTICUL ARTICLE,'EA' INPUT_UOM from RRL_ARTICULS where BARCODE_SHT=p_code
    union all select ACTICUL,'BOX' from RRL_ARTICULS where BARCODE_KOR=p_code) loop
   n:=n+1;if n>1 then raise_application_error(-20887,'QUALITY_ITEM_BARCODE_AMBIGUOUS');end if;
   p_article:=z.ARTICLE;p_input_uom:=z.INPUT_UOM;
  end loop;
  if n!=1 then raise_application_error(-20886,'QUALITY_FOREIGN_ITEM_BARCODE');end if;
 end;

 procedure validate_scan(p_domain clob,p_metadata clob) is
  d json_object_t:=json_object_t.parse(p_domain);m json_object_t:=json_object_t.parse(p_metadata);a json_array_t:=d.get_array('legs');scans json_array_t:=json_array_t();
  l json_object_t;x json_object_t;v_article varchar2(160);v_base varchar2(20);v_code varchar2(128);v_event varchar2(100);v_input varchar2(20);
  v_qty number;v_value number;v_version number;v_num number;v_den number;v_scale number;v_matches number;k varchar2(160);v_hash varchar2(128);
  type quantity_map is table of number index by varchar2(160);expected quantity_map;actual quantity_map;
  type unit_map is table of varchar2(20) index by varchar2(160);base_units unit_map;
  type event_map is table of varchar2(128) index by varchar2(100);events event_map;
  type article_cache is table of varchar2(160) index by varchar2(128);articles article_cache;
  type amount_cache is table of number index by varchar2(128);amounts amount_cache;
 begin
  for i in 0..a.get_size-1 loop
   l:=treat(a.get(i) as json_object_t);v_article:=l.get_string('article');
   if RRL_STOCK_QC_MARK.required_for_article(v_article)=1 then continue;end if;
   v_qty:=RRL_STOCK_MATH.quantity(l.get_string('quantity'));v_base:=l.get_string('base_uom');
   if not expected.exists(v_article) then expected(v_article):=0;base_units(v_article):=v_base;end if;
   if base_units(v_article)!=v_base then raise_application_error(-20887,'QUALITY_ITEM_BASE_UOM_CONFLICT');end if;
   expected(v_article):=expected(v_article)+v_qty;
  end loop;
  if m.has('item_scans') then scans:=m.get_array('item_scans');end if;
  if scans.get_size>20000 then raise_application_error(-20881,'QUALITY_ITEM_SCAN_BOUND');end if;
  for i in 0..scans.get_size-1 loop
   x:=treat(scans.get(i) as json_object_t);v_code:=x.get_string('barcode');v_event:=x.get_string('scan_id');v_qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));
   if v_qty!=1 then raise_application_error(-20871,'QUALITY_UNIT_SCAN_ONE_ITEM_REQUIRED');end if;
   if v_code is null or v_event is null then raise_application_error(-20871,'QUALITY_ITEM_SCAN_FIELDS_REQUIRED');end if;
   v_hash:=rawtohex(RRL_STOCK_LOCK_API.resource_key('QCITEM',v_code,RRL_STOCK_PLAN_HELPER.decimal_text(v_qty)));
   if events.exists(v_event) then
    if events(v_event)!=v_hash then raise_application_error(-20871,'QUALITY_ITEM_SCAN_EVENT_CONTENT_CONFLICT');end if;
    continue;
   end if;events(v_event):=v_hash;v_matches:=0;
   if articles.exists(v_code) then v_article:=articles(v_code);v_value:=amounts(v_code);else
   resolve_barcode(v_code,v_article,v_input);v_matches:=1;
   if v_matches!=1 or not expected.exists(v_article) then raise_application_error(-20886,'QUALITY_FOREIGN_ITEM_BARCODE');end if;
   select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_input;
   select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into v_base,v_num,v_den,v_scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_input and POLICY_VERSION=v_version;
   if v_base!=base_units(v_article) then raise_application_error(-20887,'QUALITY_ITEM_BASE_UOM_CONFLICT');end if;
   v_value:=RRL_STOCK_MATH.convert_exact(x.get_string('quantity'),v_num,v_den,v_scale);
    articles(v_code):=v_article;amounts(v_code):=v_value;
   end if;
   if not actual.exists(v_article) then actual(v_article):=0;end if;
   actual(v_article):=actual(v_article)+v_value;
   if actual(v_article)>expected(v_article) then raise_application_error(-20886,'QUALITY_ITEM_QUANTITY_EXCESS');end if;
  end loop;
  k:=expected.first;while k is not null loop
   if not actual.exists(k) then raise_application_error(-20886,'QUALITY_ITEM_COMPOSITION_COVERAGE_REQUIRED:'||k);end if;
   if actual(k)!=expected(k) then raise_application_error(-20886,'QUALITY_ITEM_COMPOSITION_COVERAGE_REQUIRED:'||k);end if;k:=expected.next(k);
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_QC_MARK as
 function marked(p_article varchar2) return number is n number;
 begin
  select greatest(nvl((select MARKING_REQUIRED from RRL_SKU_RECEIPT_POLICY where ARTICUL=p_article),0),
   nvl((select CRPT_REQUIRED from RRL_FINISHED_GOODS_SKU where ARTICUL=p_article),0),
   case when exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=p_article) then 1 else 0 end) into n from dual;return n;
 end;
 function required_for_article(p_article varchar2) return number is begin return marked(p_article);end;
 function required_for_plan(p_domain clob) return number is
  d json_object_t:=json_object_t.parse(p_domain);a json_array_t:=d.get_array('legs');l json_object_t;
 begin
  for i in 0..a.get_size-1 loop l:=treat(a.get(i) as json_object_t);if marked(l.get_string('article'))=1 then return 1;end if;end loop;return 0;
 end;
 procedure validate_scan(p_domain clob,p_metadata clob,p_unit_count out number) is
  d json_object_t:=json_object_t.parse(p_domain);m json_object_t:=json_object_t.parse(p_metadata);
  a json_array_t:=d.get_array('legs');scans json_array_t:=json_array_t();l json_object_t;x json_object_t;
  v_uid varchar2(150);v_cell varchar2(60);v_article varchar2(160);v_base varchar2(20);v_qty number;v_sum number;v_count number;v_profiles number;
  v_expected number:=0;v_resolved number:=0;scans_clob clob;v_key varchar2(4000);
  type seen_map is table of number index by varchar2(4000);expected seen_map;seen_uids seen_map;
  type index_map is table of number index by pls_integer;resolved index_map;
  function profile_key(p_unit varchar2,p_system varchar2,p_profile varchar2) return varchar2 is
  begin return rawtohex(RRL_STOCK_LOCK_API.resource_key('QCMARK',p_unit,rawtohex(RRL_STOCK_LOCK_API.resource_key('PROFILE',p_system,p_profile))));end;
 begin
  p_unit_count:=0;
  if m.has('unit_scans') then scans:=m.get_array('unit_scans');end if;
  if scans.get_size>20000 then raise_application_error(-20881,'QUALITY_MARK_SCAN_BOUND');end if;
  for i in 0..a.get_size-1 loop
   l:=treat(a.get(i) as json_object_t);v_article:=l.get_string('article');if marked(v_article)!=1 then continue;end if;
   v_uid:=l.get_string('uid');v_cell:=l.get_string('cell');v_base:=l.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(l.get_string('quantity'));
   if seen_uids.exists(v_uid) then raise_application_error(-20887,'QUALITY_MARK_SPLIT_ALLOCATION_NOT_SUPPORTED');end if;seen_uids(v_uid):=1;
   select count(*) into v_profiles from RRL_SKU_RECEIPT_PROFILE where ARTICUL=v_article;
   if v_profiles<1 or v_profiles>50 then raise_application_error(-20887,'QUALITY_MARK_PROFILES_REQUIRED');end if;
   select count(*),sum(BASE_QTY) into v_count,v_sum from RRL_WMS_RECEIPT_UNIT
    where CURRENT_UID=v_uid and CURRENT_CELL=v_cell and STOCK_STATUS='AVAILABLE' and BASE_UOM=v_base;
   if v_count<1 or v_count>10000 or v_sum!=v_qty then raise_application_error(-20887,'QUALITY_MARK_WHOLE_COMPOSITION_REQUIRED');end if;
   p_unit_count:=p_unit_count+v_count;if p_unit_count>10000 then raise_application_error(-20881,'QUALITY_PHYSICAL_UNIT_BOUND');end if;
   -- One bounded matrix query per allocation, never a profile SELECT per physical unit.
   for z in(select u.PHYSICAL_UNIT_KEY,p.SYSTEM_CODE,p.PROFILE_CODE from RRL_WMS_RECEIPT_UNIT u cross join RRL_SKU_RECEIPT_PROFILE p
    where u.CURRENT_UID=v_uid and u.CURRENT_CELL=v_cell and u.STOCK_STATUS='AVAILABLE' and u.BASE_UOM=v_base and p.ARTICUL=v_article
    order by u.PHYSICAL_UNIT_KEY,p.SYSTEM_CODE,p.PROFILE_CODE fetch first 20001 rows only) loop
    v_expected:=v_expected+1;if v_expected>20000 then raise_application_error(-20881,'QUALITY_MARK_PROFILE_MATRIX_BOUND');end if;
    expected(profile_key(z.PHYSICAL_UNIT_KEY,z.SYSTEM_CODE,z.PROFILE_CODE)):=0;
   end loop;
  end loop;
  for i in 0..scans.get_size-1 loop
   x:=treat(scans.get(i) as json_object_t);
   if x.get_string('system_code') is null or x.get_string('profile_code') is null or x.get_string('code_hash') is null
    or not regexp_like(x.get_string('code_hash'),'^[a-f0-9]{64}$') then raise_application_error(-20871,'QUALITY_MARK_SCAN_INVALID');end if;
  end loop;
  scans_clob:=scans.to_clob;
  -- One indexed code-registry join. In-memory framed keys enforce exact unit/profile set coverage.
  for z in(select j.I,j.S,j.P,u.PHYSICAL_UNIT_KEY from
   json_table(scans_clob,'$[*]' columns(I for ordinality,S varchar2(40) path '$.system_code',P varchar2(80) path '$.profile_code',H varchar2(64) path '$.code_hash'))j
   join RRL_WMS_RECEIPT_CODE c on c.SYSTEM_CODE=j.S and c.CODE_HASH=j.H
   join RRL_WMS_RECEIPT_UNIT u on u.UID_PALLET=c.UID_PALLET and u.UNIT_ID=c.UNIT_ID
   where u.STOCK_STATUS='AVAILABLE' and exists(select 1 from json_table(c.PROFILES_JSON,'$[*]' columns(P varchar2(80) path '$.profile'))pr where pr.P=j.P)) loop
   v_key:=profile_key(z.PHYSICAL_UNIT_KEY,z.S,z.P);
   if not expected.exists(v_key) then raise_application_error(-20886,'QUALITY_FOREIGN_UNIT_OR_PROFILE');end if;
   if resolved.exists(z.I) or expected(v_key)=1 then raise_application_error(-20871,'QUALITY_DUPLICATE_MARK_SCAN');end if;
   resolved(z.I):=1;expected(v_key):=1;v_resolved:=v_resolved+1;
  end loop;
  if v_resolved!=scans.get_size then raise_application_error(-20886,'QUALITY_FOREIGN_UNIT_OR_PROFILE');end if;
  if v_resolved!=v_expected then raise_application_error(-20886,'QUALITY_UNIQUE_UNIT_PROFILE_COVERAGE_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_QC_POLICY as
 procedure settings(p_warehouse number,p_mode out varchar2,p_independent out number) is
 begin
  select nvl(s.OUTGOING_QC_MODE,case when nvl(w.BLOCK_IF_NO_PROOVE,0)=1 then 'ANY' else 'NONE' end),
   nvl(s.OUTGOING_QC_INDEPENDENT,0) into p_mode,p_independent from RRL_WARES w
   left join RRL_RECEIPT_WARE_SETTINGS s on s.WARE_ID=w.ID where w.ID=p_warehouse;
 end;
 procedure settings_for_plan(p_domain clob,p_mode out varchar2,p_independent out number)is
  d json_object_t:=json_object_t.parse(p_domain);case_id number:=d.get_number('case_task');required number;policy json_object_t;
 begin
  policy:=json_object_t.parse(RRL_QC_SCOPE_READ.policy_json(p_domain));p_mode:=policy.get_string('mode');p_independent:=policy.get_number('independent');
  if case_id is not null then
   select t.FINAL_WEIGHT_REQUIRED into required from RRL_CASE_PICK_TASK c join RRL_PALLET_TYPE t on t.PALLET_TYPE_ID=c.PALLET_TYPE_ID
    where c.CASE_PICK_TASK_ID=case_id;
   if required=1 then
    if p_mode in('NONE','ANY')then p_mode:='WEIGHT';elsif p_mode='SCAN'then p_mode:='BOTH';end if;
   end if;
  end if;
 end;
 function controller_allowed(p_domain clob,p_actor varchar2) return number is
  d json_object_t:=json_object_t.parse(p_domain);v_mode varchar2(10);v_independent number;
  v_case number:=d.get_number('case_task');v_id number:=d.get_number('document_id');v_known number:=0;v_count number;v_actor varchar2(100);
 begin
  settings_for_plan(p_domain,v_mode,v_independent);if v_independent=0 then return 1;end if;
  if p_actor is null then return 0;end if;
  if v_case is not null then
   for z in(select h.CREATED_BY,op.ACTOR,op.STATE from RRL_CASE_CARRIER_LOT h left join RRL_STOCK_OPERATION op on op.OPERATION_ID=h.CREATED_OPERATION
    where h.CASE_PICK_TASK_ID=v_case order by h.LOT_UID fetch first 201 rows only) loop
    v_known:=v_known+1;
    if v_known>200 or z.ACTOR is null or z.CREATED_BY is null or z.STATE!='APPLIED' or z.CREATED_BY!=z.ACTOR then return 0;end if;
    if z.ACTOR=p_actor then return 0;end if;
   end loop;
  else
   for z in(select m.CREATED_BY,op.ACTOR,op.STATE from RRL_CUSTOMER_ORDER_FULFILLMENT ff
    join RRL_WAREHOUSE_TASK_STOCK_MOVE m on m.TASK_ID=ff.PICKED_WAREHOUSE_TASK_ID
    left join RRL_STOCK_OPERATION op on op.OPERATION_ID=m.OPERATION_ID
    where ff.LEGACY_SBORKA_PALLET_ID=v_id order by m.OPERATION_ID fetch first 201 rows only) loop
    v_known:=v_known+1;
    if v_known>200 or z.ACTOR is null or z.CREATED_BY is null or z.STATE!='APPLIED' or z.CREATED_BY!=z.ACTOR then return 0;end if;
    if z.ACTOR=p_actor then return 0;end if;
   end loop;
  end if;
  if v_known=0 then return 0;end if;return 1;
 end;
 procedure assert_controller(p_domain clob,p_actor varchar2) is
 begin if controller_allowed(p_domain,p_actor)!=1 then raise_application_error(-20882,'QUALITY_INDEPENDENT_CONTROLLER_REQUIRED_ACTUAL_PICK_FACTS');end if;end;
 procedure sampling(p_domain clob,p_bucket out number,p_percent out number,p_selected out number,p_rescan out number) is
  d json_object_t:=json_object_t.parse(p_domain);v_id number:=d.get_number('document_id');v_ware number:=d.get_number('warehouse');
 begin
  select QC_SAMPLE_BUCKET,QC_SAMPLE_REQUIRED,QC_RESCAN_REQUIRED into p_bucket,p_selected,p_rescan from RRL_SBORKA_PALLETS where ID=v_id;
  p_percent:=json_object_t.parse(RRL_QC_SCOPE_READ.policy_json(p_domain)).get_number('sample_percent');
  if p_bucket is not null and p_bucket<p_percent*100 then p_selected:=1;end if;
 end;
 function full_scan_required(p_domain clob) return number is
  d json_object_t:=json_object_t.parse(p_domain);v_mode varchar2(10);v_independent number;v_bucket number;v_percent number;v_selected number;v_rescan number;
 begin
  settings_for_plan(p_domain,v_mode,v_independent);sampling(p_domain,v_bucket,v_percent,v_selected,v_rescan);
  if v_bucket is null and v_percent>0 then raise_application_error(-20886,'OUTGOING_CONTROL_PLAN_REQUIRED');end if;
  if v_mode in('SCAN','BOTH') or v_selected=1 or v_rescan=1 then return 1;end if;return 0;
 end;
 procedure assign_sampling(p_domain clob) is
  d json_object_t:=json_object_t.parse(p_domain);v_id number:=d.get_number('document_id');v_bucket number;v_percent number;v_selected number;v_rescan number;
 begin
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(v_id)));
  sampling(p_domain,v_bucket,v_percent,v_selected,v_rescan);
  if v_bucket is null then
   update RRL_SBORKA_PALLETS set QC_SAMPLE_BUCKET=trunc(dbms_random.value(0,10000)) where ID=v_id;
   sampling(p_domain,v_bucket,v_percent,v_selected,v_rescan);
  end if;
  if v_selected=1 then update RRL_SBORKA_PALLETS set QC_SAMPLE_REQUIRED=1 where ID=v_id;end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_QC_WEIGHT as
 procedure physical_mass(p_uid varchar2,p_quantity number,p_mass out number,p_lightest out number)is
  n number;bad number;qty number;
 begin
  if p_uid is null then raise_application_error(-20887,'QUALITY_WEIGHT_PHYSICAL_UID_REQUIRED');end if;
  select count(*),nvl(sum(BASE_QTY),0),nvl(sum(GROSS_WEIGHT_KG),0),min(GROSS_WEIGHT_KG),
   nvl(sum(case when BASE_QTY is null or BASE_QTY<=0 or BASE_UOM is null or BASE_UOM!='KG'
    or GROSS_WEIGHT_KG is null or GROSS_WEIGHT_KG<BASE_QTY or MEASUREMENT_REFERENCE is null or WEIGHT_LABEL_SCAN is null then 1 else 0 end),0)
   into n,qty,p_mass,p_lightest,bad from(select BASE_QTY,BASE_UOM,GROSS_WEIGHT_KG,MEASUREMENT_REFERENCE,WEIGHT_LABEL_SCAN
    from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and STOCK_STATUS!='ISSUED'and rownum<=10001);
  if n>10000 then raise_application_error(-20881,'QUALITY_WEIGHT_PHYSICAL_UNIT_BOUND_10000');end if;
  if n=0 or bad>0 or qty!=p_quantity then raise_application_error(-20887,'QUALITY_WEIGHT_ACTUAL_BOX_MASS_COMPOSITION_REQUIRED');end if;
 end;
 procedure calculate(p_domain clob,p_expected out number,p_tolerance out number) is
  d json_object_t:=json_object_t.parse(p_domain);a json_array_t:=d.get_array('legs');l json_object_t;
  v_article varchar2(160);v_ware number:=d.get_number('warehouse');v_base_weight number;v_box_weight number;
  v_policy_uom varchar2(20);v_qty number;v_count number:=0;v_physical_mass number;v_lightest number;
 begin
  p_expected:=0;p_tolerance:=null;
  if a.get_size<1 or a.get_size>200 then raise_application_error(-20881,'QUALITY_WEIGHT_ALLOCATION_BOUND');end if;
  for i in 0..a.get_size-1 loop
   l:=treat(a.get(i) as json_object_t);v_article:=l.get_string('article');v_qty:=RRL_STOCK_MATH.quantity(l.get_string('quantity'));
   if RRL_WEIGHT_BOX_CAPACITY.enabled(v_article)=1 then
    if l.get_string('base_uom')is null or l.get_string('base_uom')!='KG'then raise_application_error(-20887,'QUALITY_WEIGHT_PHYSICAL_KG_REQUIRED');end if;
    physical_mass(l.get_string('uid'),v_qty,v_physical_mass,v_lightest);
    p_expected:=p_expected+v_physical_mass;v_count:=v_count+1;
    p_tolerance:=case when p_tolerance is null then v_lightest/2 else least(p_tolerance,v_lightest/2)end;
    continue;
   end if;
   begin
    select QC_BASE_WEIGHT_KG,QC_BOX_WEIGHT_KG,QC_WEIGHT_BASE_UOM into v_base_weight,v_box_weight,v_policy_uom from RRL_RECEIPT_SKU_RULE where WARE_ID=v_ware and ARTICUL=v_article;
   exception when no_data_found then raise_application_error(-20887,'QUALITY_SI_WEIGHT_POLICY_REQUIRED:'||v_article);end;
   if v_base_weight is null or v_base_weight<=0 or v_box_weight is null or v_box_weight<=0 then
    raise_application_error(-20887,'QUALITY_SI_WEIGHT_POLICY_REQUIRED:'||v_article);end if;
   if v_policy_uom is null or v_policy_uom!=l.get_string('base_uom') then raise_application_error(-20887,'QUALITY_MASS_BASE_UOM_CONFLICT:'||v_article);end if;
   p_expected:=p_expected+v_qty*v_base_weight;v_count:=v_count+1;
   p_tolerance:=case when p_tolerance is null then v_box_weight/2 else least(p_tolerance,v_box_weight/2) end;
  end loop;
  if v_count=0 then raise_application_error(-20887,'QUALITY_EMPTY_WEIGHT_COMPOSITION');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_QUALITY_ENTRY as
 function run(p_pallet varchar2,p_metadata json_object_t,p_actor varchar2,p_operation varchar2) return number is
  d json_object_t:=json_object_t();s json_object_t:=json_object_t();wire clob;j json_object_t;
 begin
  if p_pallet is null or p_actor is null or p_operation is null then raise_application_error(-20871,'QUALITY_ACTOR_AND_OPERATION_REQUIRED');end if;
  d.put('contract_version',2);d.put('command_type','OUTGOING_PALLET_CHECK');d.put('operation_id',p_operation);d.put('actor',p_actor);
  s.put('pallet_identifier',p_pallet);d.put('source',s);d.put('metadata',p_metadata);d.put('lines',json_array_t());d.put('units',json_array_t());
  RRL_STOCK_NATIVE_API.post(d.to_clob,p_actor,wire);j:=json_object_t.parse(wire);return j.get_number('return_code');
 end;
 function scan(p_pallet varchar2,p_errors number,p_note varchar2,p_picker varchar2,p_actor varchar2,p_operation varchar2) return number is m json_object_t:=json_object_t();
 begin
  m.put('quality_kind','SCAN');m.put('error_count',p_errors);m.put('note',p_note);m.put('picker',p_picker);
  return run(p_pallet,m,p_actor,p_operation);
 end;
 function weight(p_kind varchar2,p_pallet varchar2,p_gross varchar2,p_wood varchar2,p_actor varchar2,p_operation varchar2) return number is m json_object_t:=json_object_t();gross number;wood number;
 begin
  gross:=RRL_STOCK_MATH.quantity(replace(trim(p_gross),',','.'));wood:=RRL_STOCK_MATH.quantity(replace(trim(p_wood),',','.'));
  m.put('quality_kind',p_kind);m.put('gross_weight',RRL_STOCK_PLAN_HELPER.decimal_text(gross));m.put('wood_weight',RRL_STOCK_PLAN_HELPER.decimal_text(wood));
  return run(p_pallet,m,p_actor,p_operation);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_RECEIPT_CORE as
 procedure execute_receipt(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);h json_object_t;m json_object_t;o RRL_SAP_SUPPLY_ORDER%rowtype;
  v_plan clob;v_result clob;v_response json_object_t;v_policy number;v_qty number;v_planned number;v_done number;v_n number;
  v_base varchar2(20);v_unit varchar2(20);v_article varchar2(160);v_uom_version number;v_base_version number;v_num number;v_den number;v_scale number;
  v_uid varchar2(200);v_cell varchar2(60);v_event number;v_task number;v_expiry date;v_header number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'warehouse_receipt_confirm')!=1 then raise_application_error(-20882,'RECEIPT_FORBIDDEN');end if;
  declare
 v_json_sql_1_1 varchar2(32767):=d.get_string('operation_id');
begin
select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_1_1;
end;
  h:=json_object_t.parse(v_plan).get_object('domain');m:=d.get_object('metadata');
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);
  declare
 v_json_sql_2_1 varchar2(32767):=h.get_string('source_order_id');
begin
select * into o from RRL_SAP_SUPPLY_ORDER where ORDER_ID=v_json_sql_2_1 for update;
end;
  if o.REVISION!=h.get_number('order_revision') or o.NAKLAD_ID!=h.get_number('naklad_id')
   or o.WARE_ID!=h.get_number('warehouse_id') or o.RECEIVE_CELL!=h.get_string('receive_cell') then
   raise_application_error(-20890,'CLOSURE_CHANGED: SAP receipt order');end if;
  select CONDITION into v_header from RRL_PRIHOD_NAKLAD where ID=o.NAKLAD_ID for update;
  if nvl(v_header,0)!=0 then raise_application_error(-20886,'RECEIPT_DOCUMENT_CLOSED');end if;
  declare
 v_json_sql_3_1 varchar2(32767):=h.get_string('line_number');
begin
select ARTICUL,PLANNED_QTY,BASE_UOM into v_article,v_planned,v_unit from RRL_SAP_SUPPLY_LINE
   where ORDER_ID=o.ORDER_ID and LINE_NUMBER=v_json_sql_3_1;
end;
  if v_article!=h.get_string('article') or v_unit!=h.get_string('input_uom') then raise_application_error(-20890,'CLOSURE_CHANGED: SAP receipt line');end if;
  select max(POLICY_VERSION) into v_uom_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_unit;
  select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into v_base,v_num,v_den,v_scale
   from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_unit and POLICY_VERSION=v_uom_version;
  v_qty:=RRL_STOCK_MATH.convert_exact(m.get_string('quantity'),v_num,v_den,v_scale);
  v_planned:=RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(v_planned),v_num,v_den,v_scale);
  if h.get_number('uom_version')!=v_uom_version or h.get_string('base_uom')!=v_base or
   RRL_STOCK_MATH.quantity(h.get_string('base_quantity'))!=v_qty then raise_application_error(-20890,'CLOSURE_CHANGED: receipt UOM');end if;
  declare
 v_json_sql_4_1 varchar2(32767):=h.get_string('line_number');
begin
select count(*) into v_n from RRL_SAP_PALLET_RECEIPT where ORDER_ID=o.ORDER_ID and LINE_NUMBER=v_json_sql_4_1
   and (POSTED_BASE_QTY is null or STOCK_BASE_UOM is null or STOCK_BASE_UOM!=v_base);
end;
  if v_n>0 then raise_application_error(-20884,'LEGACY_RECEIPT_BASELINE_REQUIRED');end if;
  declare
 v_json_sql_5_1 varchar2(32767):=h.get_string('line_number');
begin
select nvl(sum(POSTED_BASE_QTY),0) into v_done from RRL_SAP_PALLET_RECEIPT where ORDER_ID=o.ORDER_ID and LINE_NUMBER=v_json_sql_5_1;
end;
  if v_done+v_qty>v_planned then raise_application_error(-20886,'RECEIPT_OVER_SUPPLY');end if;
  select POLICY_VERSION into v_policy from RRL_SKU_RECEIPT_POLICY where ARTICUL=v_article;
  if v_policy!=h.get_number('marking_policy_version') then raise_application_error(-20890,'CLOSURE_CHANGED: marking policy');end if;
  v_uid:=h.get_string('uid');v_cell:=o.RECEIVE_CELL;v_task:=h.get_number('task_id');
  declare
 v_json_sql_6_1 varchar2(32767):=m.get_string('expiry_date');
begin
select count(*) into v_n from RRL_PALLETS where UID_PALLET=v_uid and ARTICUL=v_article and PRIHOD_NAKLAD_ID=o.NAKLAD_ID
   and UNIT_COUNT=v_qty and EXPIRY_DATE=to_date(v_json_sql_6_1,'YYYY-MM-DD');
end;
  if v_n!=1 then raise_application_error(-20884,'RECEIPT_STAGING_PALLET_CONFLICT');end if;
  declare
 v_json_sql_7_1 varchar2(32767):=h.get_object('placement').get_string('cell');
begin
select count(*) into v_n from RRL_WAREHOUSE_TASK where TASK_ID=v_task and UID_PALLET=v_uid and STATUS='PLANNED'
   and FROM_CELL=v_cell and TO_CELL=v_json_sql_7_1;
end;
  if v_n!=1 then raise_application_error(-20884,'RECEIPT_STAGING_TASK_CONFLICT');end if;
  select count(*) into v_n from RRL_REMAINS where UID_POLETA=v_uid;
  if v_n>0 then raise_application_error(-20886,'RECEIPT_STOCK_ALREADY_EXISTS');end if;
  RRL_STOCK_LOCATION_CORE.assert_receiving(v_cell,o.WARE_ID);
  select count(*) into v_n from RRL_CELLS where CELL=v_cell and WARE_ID=o.WARE_ID and nvl(BLOCKED_FOR_ACCEPT,0)=0;
  if v_n!=1 then raise_application_error(-20886,'RECEIVING_CELL_BLOCKED');end if;
  select max(POLICY_VERSION) into v_base_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_base and BASE_UOM=v_base and NUMERATOR=1 and DENOMINATOR=1;
  if v_base_version is null then raise_application_error(-20868,'RECEIPT_BASE_POLICY_REQUIRED');end if;
  RRL_STOCK_BALANCE_CORE.apply_delta(v_uid,v_cell,v_qty,0,v_base,v_base_version);
  RRL_STOCK_UNIT_CORE.assert_composition(v_uid,v_cell);
  RRL_STOCK_UNIT_CORE.admit_captured(v_uid,v_cell);
  declare
 v_json_sql_8_1 varchar2(32767):=d.get_string('operation_id');
begin
update RRL_PALLETS set STOCK_ORIGIN_UID=v_uid,CREATED_BY_STOCK_OP=v_json_sql_8_1 where UID_PALLET=v_uid;
end;
  RRL_STOCK_BALANCE_CORE.write_leg(v_uid,null,v_cell,v_qty,v_base,v_base_version,1,1,1,p_actor,v_event);
  v_response:=h.get_object('result');v_response.put('task_id',v_task);p_result:=v_response.to_clob;
  declare
 v_json_sql_9_1 varchar2(32767):=d.get_string('operation_id');
 v_json_sql_9_2 varchar2(32767):=h.get_string('line_number');
 v_json_sql_9_3 varchar2(32767):=m.get_string('supplier_batch');
 v_json_sql_9_4 varchar2(32767):=d.get_string('operation_id');
begin
insert into RRL_SAP_PALLET_RECEIPT(OPERATION_ID,ORDER_ID,LINE_NUMBER,UID_PALLET,SUPPLIER_BATCH,PAYLOAD_HASH,RESULT_JSON,
   RECEIVED_BY,POSTED_BASE_QTY,STOCK_BASE_UOM,STOCK_OPERATION_ID)
   values(v_json_sql_9_1,o.ORDER_ID,v_json_sql_9_2,v_uid,v_json_sql_9_3,
    rawtohex(sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256)),p_result,p_actor,v_qty,v_base,v_json_sql_9_4);
end;
  select count(*) into v_n from RRL_SAP_SUPPLY_LINE sl where sl.ORDER_ID=o.ORDER_ID and (
   not exists(select 1 from RRL_STOCK_UOM_CONVERSION u where u.ARTICUL=sl.ARTICUL and u.INPUT_UOM=sl.BASE_UOM)
   or nvl((select sum(rec.POSTED_BASE_QTY) from RRL_SAP_PALLET_RECEIPT rec where rec.ORDER_ID=sl.ORDER_ID and rec.LINE_NUMBER=sl.LINE_NUMBER),0)<
     (select RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(sl.PLANNED_QTY),u.NUMERATOR,u.DENOMINATOR,u.BASE_SCALE)
      from RRL_STOCK_UOM_CONVERSION u where u.ARTICUL=sl.ARTICUL and u.INPUT_UOM=sl.BASE_UOM and u.POLICY_VERSION=(select max(x.POLICY_VERSION) from RRL_STOCK_UOM_CONVERSION x where x.ARTICUL=sl.ARTICUL and x.INPUT_UOM=sl.BASE_UOM)));
  if v_n=0 then update RRL_PRIHOD_NAKLAD set CONDITION=1,DATE_OF_ACCEPT=nvl(DATE_OF_ACCEPT,sysdate) where ID=o.NAKLAD_ID;end if;
  declare
 v_json_sql_10_1 varchar2(32767):=d.get_string('operation_id');
begin
insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)
   values(v_json_sql_10_1,'PALLET_RECEIVED',p_result);
end;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_RECEIPT_PLAN as
 procedure compile_receipt(p_request clob,p_operation varchar2,p_hints clob,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);s json_object_t;m json_object_t;h json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();o RRL_SAP_SUPPLY_ORDER%rowtype;
  v_article varchar2(160);v_uid varchar2(200);v_task number;v_target varchar2(60);v_slot number;v_line varchar2(30);
 begin
  if p_hints is null or dbms_lob.getlength(p_hints)>4194304 then raise_application_error(-20871,'RECEIPT_PLAN_REQUIRED');end if;
  h:=json_object_t.parse(p_hints);s:=d.get_object('source');m:=d.get_object('metadata');
  declare
 v_json_sql_1_1 varchar2(32767):=s.get_string('order_id');
begin
select * into o from RRL_SAP_SUPPLY_ORDER where ORDER_ID=v_json_sql_1_1;
end;
  v_line:=m.get_string('line_number');
  select ARTICUL into v_article from RRL_SAP_SUPPLY_LINE where ORDER_ID=o.ORDER_ID and LINE_NUMBER=v_line;
  if h.get_string('article')!=v_article or h.get_number('order_revision')!=o.REVISION or h.get_number('naklad_id')!=o.NAKLAD_ID then
   raise_application_error(-20890,'CLOSURE_CHANGED: receipt source');end if;
  v_uid:=m.get_string('sscc');v_target:=h.get_object('placement').get_string('cell');v_slot:=h.get_object('placement').get_number('slot_id');
  if v_uid is null or v_target is null then raise_application_error(-20871,'RECEIPT_IDENTITY_REQUIRED');end if;
  select RRL_WAREHOUSE_TASK_SQ.nextval into v_task from dual;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SAP_SUPPLY_ORDER',o.ORDER_ID);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRIHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(o.NAKLAD_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SAP_SUPPLY_LINE',o.ORDER_ID||':'||v_line);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(v_task));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_LABEL',v_uid);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','PALLET:'||v_uid);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','SAP.RECEIPT:'||p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','SAP.OUTBOX:'||p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v_uid,v_article,o.RECEIVE_CELL,v_target);
  if v_slot is not null then RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(v_slot));end if;
  for u in(select UNIT_KEY from json_table(p_hints,'$.unit_bindings[*]' columns(UNIT_KEY varchar2(64) path '$.key'))) loop
   RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',u.UNIT_KEY);
  end loop;
  for a in(select SYSTEM_CODE,CODE_HASH from json_table(p_hints,'$.aliases[*]' columns(SYSTEM_CODE varchar2(40) path '$.system',CODE_HASH varchar2(64) path '$.hash'))) loop
   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','MARK:'||a.SYSTEM_CODE||':'||a.CODE_HASH);
  end loop;
  RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v_uid);
  for a in(select SYSTEM_CODE,CODE_HASH from json_table(p_hints,'$.aggregations[*]' columns(SYSTEM_CODE varchar2(40) path '$.system',CODE_HASH varchar2(64) path '$.hash'))) loop
   RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','AGG:'||a.SYSTEM_CODE||':'||a.CODE_HASH);
  end loop;
  h.put('task_id',v_task);h.put('warehouse_id',o.WARE_ID);h.put('receive_cell',o.RECEIVE_CELL);
  h.put('uid',v_uid);h.put('source_order_id',o.ORDER_ID);h.put('line_number',v_line);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=h.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_RECEIPT_REVERSE as
 function physical_rows(p_document number) return clob is
  a json_array_t:=json_array_t();x json_object_t;
 begin
  for r in(select s.UID_POLETA,s.CELL,s.REMAIN,s.HARD_RESERVED_BASE,s.STOCK_VERSION,s.BASE_UOM,p.ARTICUL
   from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA
   where p.PRIHOD_NAKLAD_ID=p_document and s.REMAIN>0 order by s.UID_POLETA,s.CELL fetch first 201 rows only) loop
   if a.get_size=200 then raise_application_error(-20881,'RECEIPT_REVERSE_BATCH_BOUND');end if;
   x:=json_object_t();x.put('uid',r.UID_POLETA);x.put('cell',r.CELL);x.put('article',r.ARTICUL);
   x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(r.REMAIN));x.put('hard',RRL_STOCK_PLAN_HELPER.decimal_text(r.HARD_RESERVED_BASE));
   x.put('version',r.STOCK_VERSION);x.put('base',r.BASE_UOM);a.append(x);
  end loop;
  return a.to_clob;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t:=json_object_t();x json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;
  doc number;ware number;sap varchar2(32);receive_cell varchar2(60);n number:=0;
 begin
  doc:=d.get_object('source').get_number('receipt_document_id');
  if doc is null or doc<1 or trim(d.get_object('metadata').get_string('reason')) is null then raise_application_error(-20871,'RECEIPT_REVERSE_IDENTITY_REASON_REQUIRED');end if;
  select WARE_ID into ware from RRL_PRIHOD_NAKLAD where ID=doc;
  begin select ORDER_ID,RECEIVE_CELL into sap,receive_cell from RRL_SAP_SUPPLY_ORDER where NAKLAD_ID=doc;
  exception when no_data_found then sap:=null;receive_cell:='IN_DOCK';end;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRIHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(doc));
  if sap is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SAP_SUPPLY_ORDER',sap);end if;
  a:=json_array_t.parse(physical_rows(doc));
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),x.get_string('article'),x.get_string('cell'),null);
  end loop;
  for t in(select TASK_ID,TO_CELL_SLOT_ID from RRL_WAREHOUSE_TASK where TASK_SOURCE='SAP_RECEIPT' and SOURCE_DOC_ID=doc order by TASK_ID fetch first 201 rows only) loop
   n:=n+1;if n>200 then raise_application_error(-20881,'RECEIPT_REVERSE_TASK_BOUND');end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.TASK_ID));
   for c in(select CELL_SLOT_ID from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=t.TASK_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(t.TASK_ID));
    RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(c.CELL_SLOT_ID));
   end loop;
  end loop;
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','SAP.REVERSE:'||p_operation);
  v.put('document',doc);v.put('warehouse',ware);v.put('sap_order',sap);v.put('receive_cell',receive_cell);v.put('stocks',a);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;x json_object_t;j json_object_t:=json_object_t();
  a json_array_t;facts json_array_t:=json_array_t();fact json_object_t;plan clob;nowrows clob;oldrows clob;
  doc number;ware number;cond number;op varchar2(100);uid varchar2(200);cell varchar2(60);base varchar2(20);
  qty number;ver number;event_id number;n number;expected number;actual number;sap varchar2(32);receive_cell varchar2(60);current_ware number;sap_sender varchar2(100);sap_number varchar2(100);
 begin
  if RRL_HAS_WRIGHT(p_actor,'stock_receipt_reverse')!=1 then raise_application_error(-20882,'RECEIPT_REVERSE_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v:=json_object_t.parse(plan).get_object('domain');doc:=v.get_number('document');ware:=v.get_number('warehouse');
  sap:=v.get_string('sap_order');receive_cell:=v.get_string('receive_cell');a:=v.get_array('stocks');
  select CONDITION,WARE_ID into cond,current_ware from RRL_PRIHOD_NAKLAD where ID=doc for update;
  if current_ware!=ware or current_ware is null then raise_application_error(-20890,'CLOSURE_CHANGED: receipt warehouse');end if;
  if cond is null or cond not in(0,1,2) then raise_application_error(-20886,'RECEIPT_REVERSE_DOCUMENT_STATE');end if;
  nowrows:=physical_rows(doc);oldrows:=a.to_clob;
  if dbms_lob.compare(nowrows,oldrows)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: receipt stock');end if;
  select count(*) into n from RRL_EVENTS e join RRL_PALLETS p on p.UID_PALLET=e.UID_POLETA
   where p.PRIHOD_NAKLAD_ID=doc and e.TYPE_EVENT=3;
  if n>0 then raise_application_error(-20886,'RECEIPT_REVERSE_SUBSEQUENT_ISSUE: explicit correction required');end if;
  -- Original admitted quantity must still exist, including every derived lot.
  -- No automatic reversal after consumption/shipment or an unrecorded shortage.
  expected:=0;
  for born in(select p.UID_PALLET,p.UNIT_COUNT from RRL_PALLETS p
   where p.PRIHOD_NAKLAD_ID=doc and (p.STOCK_ORIGIN_UID=p.UID_PALLET or p.STOCK_ORIGIN_UID is null)
    and (p.CREATED_BY_STOCK_OP is not null or exists(select 1 from RRL_EVENTS e
     where e.UID_POLETA=p.UID_PALLET and e.TYPE_EVENT=1 and e.COUNT_EVENT>0))) loop
   select nvl(sum(s.REMAIN),0) into actual from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA
    where p.PRIHOD_NAKLAD_ID=doc and nvl(p.STOCK_ORIGIN_UID,p.UID_PALLET)=born.UID_PALLET;
   expected:=expected+nvl(born.UNIT_COUNT,0);
   if born.UNIT_COUNT is null or born.UNIT_COUNT<=0 or actual!=born.UNIT_COUNT then raise_application_error(-20886,'RECEIPT_REVERSE_SUBSEQUENT_EFFECT: explicit correction required');end if;
  end loop;
  select nvl(sum(s.REMAIN),0) into actual from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA
   where p.PRIHOD_NAKLAD_ID=doc and s.REMAIN>0;
  if actual!=expected then raise_application_error(-20886,'RECEIPT_REVERSE_UNPROVEN_ORIGIN');end if;
  if a.get_size=0 then raise_application_error(-20886,'RECEIPT_REVERSE_NO_PHYSICAL_STOCK');end if;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);uid:=x.get_string('uid');cell:=x.get_string('cell');base:=x.get_string('base');
   qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));
   if cell!=receive_cell or x.get_string('hard')!='0' then raise_application_error(-20869,'RECEIPT_REVERSE_LOCATION_OR_RESERVE_CONFLICT');end if;
   RRL_STOCK_LOCATION_CORE.assert_quarantine(cell,ware);
   declare
 v_json_sql_1_1 varchar2(32767):=x.get_string('article');
begin
select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION
    where ARTICUL=v_json_sql_1_1 and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1;
end;
   if ver is null then raise_application_error(-20868,'RECEIPT_REVERSE_BASE_POLICY_REQUIRED');end if;
   RRL_STOCK_UNIT_CORE.issue_free_units(uid,cell,qty,null);
   RRL_STOCK_BALANCE_CORE.apply_delta(uid,cell,-qty,0,base,ver,x.get_number('version'));
   RRL_STOCK_BALANCE_CORE.write_leg(uid,cell,null,-qty,base,ver,i+1,1,3,p_actor,event_id);
   fact:=json_object_t();fact.put('uid',uid);fact.put('article',x.get_string('article'));fact.put('quantity',x.get_string('quantity'));
   fact.put('unit',base);fact.put('event_id',event_id);facts.append(fact);
  end loop;
  for t in(select TASK_ID,STATUS from RRL_WAREHOUSE_TASK where TASK_SOURCE='SAP_RECEIPT' and SOURCE_DOC_ID=doc) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.TASK_ID)));
   if t.STATUS='IN_PROGRESS' then raise_application_error(-20886,'RECEIPT_REVERSE_TASK_IN_PROGRESS');end if;
   if t.STATUS in('PLANNED','ASSIGNED') then
    update RRL_WAREHOUSE_TASK set STATUS='CANCELLED',CANCELLED_AT=systimestamp,CANCELLED_BY=p_actor,LAST_ERROR='Receipt reversed'
     where TASK_ID=t.TASK_ID;
    for c in(select CELL_SLOT_ID from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=t.TASK_ID and STATUS='RESERVED') loop
     RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(t.TASK_ID)));
     RRL_STOCK_LOCK_API.assert_held(40,RRL_STOCK_LOCK_API.resource_key('SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(c.CELL_SLOT_ID)));
     delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=t.TASK_ID and STATUS='RESERVED';
    end loop;
   end if;
  end loop;
  update RRL_PRIHOD_NAKLAD set CONDITION=3 where ID=doc;
  j.put('operation_id',op);j.put('receipt_document_id',doc);j.put('sap_order_id',sap);j.put('status','REVERSED');j.put('facts',facts);
  if sap is not null then
   select SENDER,ORDER_NUMBER into sap_sender,sap_number from RRL_SAP_SUPPLY_ORDER where ORDER_ID=sap;
   j.put('sap_sender',sap_sender);j.put('sap_order_number',sap_number);
  end if;
  j.put('reason',d.get_object('metadata').get_string('reason'));p_result:=j.to_clob;
  if sap is not null then
   RRL_STOCK_LOCK_API.assert_held(70,RRL_STOCK_LOCK_API.resource_key('UNIQUE','SAP.REVERSE:'||op));
   insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON) values(op,'RECEIPT_REVERSED',p_result);
  end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_REPL_ADMISSION as

 function lot_key(p_uid varchar2) return varchar2 is v RRL_PALLETS%rowtype;v_supplier varchar2(100);v_key varchar2(500);

 begin

  select * into v from RRL_PALLETS where UID_PALLET=p_uid;

  select max(SUPPLIER_BATCH) into v_supplier from RRL_SAP_PALLET_RECEIPT where UID_PALLET=nvl(v.STOCK_ORIGIN_UID,v.UID_PALLET);

  v_key:=case when v.PROD_BATCH_ID is not null then 'MES:'||to_char(v.PROD_BATCH_ID,'TM9')

   when v_supplier is not null then 'SAP:'||v_supplier

   when v.PRIHOD_NAKLAD_ID is not null then 'DOC:'||to_char(v.PRIHOD_NAKLAD_ID,'TM9')

   else 'UID:'||nvl(v.STOCK_ORIGIN_UID,v.UID_PALLET) end;

  return v_key||':EXP:'||nvl(to_char(v.EXPIRY_DATE,'YYYYMMDDHH24MISS'),'NULL')

   ||':MADE:'||nvl(to_char(v.PRODUCED_DATE,'YYYYMMDDHH24MISS'),'NULL');

 end;

 function reason(p_uid varchar2,p_target varchar2,p_ware number,p_article varchar2) return varchar2 is

  v_mix number;v_pick number;v_count number;v_key varchar2(1000);

 begin

  select count(*),max(OTBOR) into v_count,v_pick from RRL_CELLS where CELL=p_target and WARE_ID=p_ware;

  if v_count!=1 then return 'REPLENISHMENT_TARGET_MISSING_OR_AMBIGUOUS';end if;

  select nvl(max(ALLOW_PICK_BATCH_MIX),0) into v_mix from RRL_RECEIPT_SKU_RULE where WARE_ID=p_ware and ARTICUL=p_article;

  v_key:=lot_key(p_uid);v_count:=0;

  for t in(select p.UID_PALLET,p.ARTICUL from RRL_REMAINS r join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA where r.CELL=p_target and r.REMAIN>0) loop

   v_count:=v_count+1;if v_count>200 then raise_application_error(-20881,'REPLENISHMENT_TARGET_LOTS_BOUND');end if;

   if t.ARTICUL!=p_article then return 'REPLENISHMENT_TARGET_OTHER_SKU';end if;

   if not(v_mix=1 and v_pick=1) and lot_key(t.UID_PALLET)!=v_key then return 'REPLENISHMENT_TARGET_BATCH_MIX_FORBIDDEN';end if;

  end loop;

  return null;

 end;

 function mode_for(p_task number) return varchar2 is t RRL_PICK_WAVE_REPLENISH_TASK%rowtype;

  v_kind varchar2(40);v_abc varchar2(100);v_occupied number;v_short number;

 begin

  select * into t from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=p_task;

  select WAVE_KIND into v_kind from RRL_PICK_WAVE where PICK_WAVE_ID=t.PICK_WAVE_ID;

  select count(*) into v_short from RRL_CASE_PICK_SHORT where REPLENISH_TASK_ID=p_task and RECOVERY_STATE='WAIT_REPLENISHMENT';

  -- Minimax and urgent shortage retain their explicit quantity contracts.

  if v_kind='REPLENISHMENT' or v_short>0 then return nvl(t.REPLENISHMENT_QTY_MODE,'FULL_PALLET');end if;

  select upper(trim(ABC_GROUP)) into v_abc from RRL_ARTICULS where ACTICUL=t.ARTICUL;

  select count(*) into v_occupied from RRL_REMAINS r join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA

   where r.CELL=t.TARGET_CELL_CODE and r.REMAIN>0 and p.ARTICUL=t.ARTICUL;

  if v_abc='B' and v_occupied>0 and nvl(t.REPLENISHMENT_QTY_MODE,'FULL_PALLET')!='FULL_PALLET' then return 'FILL_TO_VOLUME';end if;

  return 'FULL_PALLET';

 end;

 function policy_signature(p_task number) return varchar2 is v json_object_t:=json_object_t();v_abc varchar2(100);v_mix number;v_ware number;v_article varchar2(160);

 begin

  select w.WARE_ID,t.ARTICUL,a.ABC_GROUP into v_ware,v_article,v_abc from RRL_PICK_WAVE_REPLENISH_TASK t

   join RRL_PICK_WAVE w on w.PICK_WAVE_ID=t.PICK_WAVE_ID join RRL_ARTICULS a on a.ACTICUL=t.ARTICUL where t.PICK_WAVE_REPLENISH_TASK_ID=p_task;

  select nvl(max(ALLOW_PICK_BATCH_MIX),0) into v_mix from RRL_RECEIPT_SKU_RULE where WARE_ID=v_ware and ARTICUL=v_article;

  v.put('mode',mode_for(p_task));v.put('abc',v_abc);v.put('mix',v_mix);

  return rawtohex(sys.dbms_crypto.hash(v.to_clob,sys.dbms_crypto.hash_sh256));

 end;

 procedure assert_target(p_uid varchar2,p_target varchar2,p_ware number,p_article varchar2) is v_reason varchar2(200);

 begin

  v_reason:=reason(p_uid,p_target,p_ware,p_article);

  if v_reason is not null then raise_application_error(-20887,v_reason);end if;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_REPL_BIND as

 function coverage(p_pick number,p_cell varchar2) return number is

 begin return RRL_STOCK_REPL_NEED.target_coverage(p_pick,p_cell);end;

 function consumer_signature(p_task RRL_WAREHOUSE_TASK%rowtype) return varchar2 is

  a json_array_t:=json_array_t();x json_object_t;

 begin

  for l in(select l.CASE_PICK_LINE_ID,l.PICK_TASK_ID,l.PLANNED_QTY,l.PICKED_QTY,l.STATUS,ct.STATUS CASE_STATUS

   from RRL_CASE_PICK_LINE l join RRL_CASE_PICK_TASK ct on ct.CASE_PICK_TASK_ID=l.CASE_PICK_TASK_ID

   where l.PICK_WAVE_ID=p_task.SOURCE_DOC_ID and l.ARTICUL=(select ARTICUL from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=p_task.SOURCE_TASK_ID) and l.CELL_CODE=p_task.TO_CELL

    and l.STATUS not in('PICKED','CANCELLED') and ct.STATUS!='CANCELLED'

   order by l.PICK_SEQUENCE nulls last,l.CASE_PICK_LINE_ID fetch first 201 rows only) loop

   if a.get_size>=200 then raise_application_error(-20881,'GENERIC_REPLENISHMENT_CONSUMER_BOUND');end if;

   x:=json_object_t();x.put('line',l.CASE_PICK_LINE_ID);x.put('pick',l.PICK_TASK_ID);x.put('planned',l.PLANNED_QTY);

   x.put('picked',l.PICKED_QTY);x.put('status',l.STATUS);x.put('case_status',l.CASE_STATUS);x.put('covered',coverage(l.PICK_TASK_ID,p_task.TO_CELL));a.append(x);

  end loop;

  return rawtohex(dbms_crypto.hash(a.to_clob,dbms_crypto.hash_sh256));

 end;

 procedure plan_bind(p_task RRL_WAREHOUSE_TASK%rowtype,p_qty number,p_anchors in out nocopy json_array_t,p_plan out json_object_t) is

  rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;x json_object_t;bindings json_array_t:=json_array_t();q number;remaining number;rid number;covered number;

 begin

  p_plan:=json_object_t();p_plan.put('lines',bindings);

  if p_task.TASK_SOURCE!='WAVE' or p_task.TASK_TYPE!='REPLENISHMENT' then return;end if;

  select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=p_task.SOURCE_TASK_ID;

  if rt.PICK_TASK_ID is not null then

   declare pt RRL_PICK_TASK%rowtype;covered_target number;incoming_other number:=0;begin

    select * into pt from RRL_PICK_TASK where PICK_TASK_ID=rt.PICK_TASK_ID;

    if pt.TASK_TYPE!='CASE_PICK' then return;end if;

    covered_target:=coverage(pt.PICK_TASK_ID,p_task.TO_CELL);

    p_plan.put('explicit',true);p_plan.put('pick_task',pt.PICK_TASK_ID);p_plan.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(pt.QTY));

    p_plan.put('fact',RRL_STOCK_PLAN_HELPER.decimal_text(nvl(pt.FACT_QTY,0)));p_plan.put('status',pt.STATUS);

    p_plan.put('target_covered',RRL_STOCK_PLAN_HELPER.decimal_text(covered_target));
    if p_task.QTY_MODE='PALLET' then
     select nvl(sum(BASE_QTY),0) into incoming_other from RRL_STOCK_RESERVATION
      where UID_PALLET=p_task.UID_PALLET and CELL=p_task.FROM_CELL
       and SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=rt.PICK_WAVE_ID
       and SOURCE_LINE_ID=rt.PICK_TASK_ID and RESERVATION_DOMAIN='PICKING'
       and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING')
       and RESERVATION_ID!=rt.SOURCE_RESERVATION_ID and BASE_QTY>0;
    end if;
    p_plan.put('expected_target_covered',RRL_STOCK_PLAN_HELPER.decimal_text(covered_target+incoming_other));


    RRL_STOCK_PLAN_HELPER.row_key(p_anchors,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(pt.PICK_TASK_ID));

    return;

   end;

  end if;

  p_plan.put('signature',consumer_signature(p_task));

  if rt.SOURCE_RESERVATION_ID is null then raise_application_error(-20886,'GENERIC_REPLENISHMENT_RESERVATION_REQUIRED');end if;

  select least(BASE_QTY,p_qty) into remaining from RRL_STOCK_RESERVATION where RESERVATION_ID=rt.SOURCE_RESERVATION_ID;

  for l in(select l.* from RRL_CASE_PICK_LINE l join RRL_CASE_PICK_TASK ct on ct.CASE_PICK_TASK_ID=l.CASE_PICK_TASK_ID where ct.STATUS!='CANCELLED' and l.PICK_WAVE_ID=rt.PICK_WAVE_ID and l.ARTICUL=rt.ARTICUL

    and l.CELL_CODE=rt.TARGET_CELL_CODE and l.STATUS not in('PICKED','CANCELLED')

    order by l.PICK_SEQUENCE nulls last,l.CASE_PICK_LINE_ID fetch first 201 rows only) loop

   exit when remaining<=0;

   if bindings.get_size>=200 then raise_application_error(-20881,'GENERIC_REPLENISHMENT_CONSUMER_BOUND');end if;

   covered:=coverage(l.PICK_TASK_ID,p_task.TO_CELL);q:=least(remaining,greatest(0,l.PLANNED_QTY-l.PICKED_QTY-covered));

   if q<=0 then continue;end if;

   select RRL_STOCK_RESERVATION_SQ.nextval into rid from dual;

   RRL_STOCK_PLAN_HELPER.row_key(p_anchors,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(rid));

   RRL_STOCK_PLAN_HELPER.row_key(p_anchors,'RRL_CASE_PICK_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(l.CASE_PICK_LINE_ID));

   RRL_STOCK_PLAN_HELPER.row_key(p_anchors,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.CASE_PICK_TASK_ID));

   RRL_STOCK_PLAN_HELPER.row_key(p_anchors,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_TASK_ID));

   for sr in(select RESERVATION_ID from RRL_STOCK_RESERVATION where SOURCE_DOC_TYPE='PICK_WAVE'

    and SOURCE_LINE_ID=l.PICK_TASK_ID and RESERVATION_DOMAIN='PICKING' and RESERVATION_KIND='HARD'

    and STATUS in('ACTIVE','ALLOCATED','PICKING') order by RESERVATION_ID) loop

    RRL_STOCK_PLAN_HELPER.row_key(p_anchors,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(sr.RESERVATION_ID));

   end loop;

   x:=json_object_t();x.put('line',l.CASE_PICK_LINE_ID);x.put('pick_task',l.PICK_TASK_ID);x.put('reservation',rid);

   x.put('planned',RRL_STOCK_PLAN_HELPER.decimal_text(l.PLANNED_QTY));x.put('picked',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICKED_QTY));

   x.put('covered',RRL_STOCK_PLAN_HELPER.decimal_text(covered));x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(q));x.put('status',l.STATUS);

   bindings.append(x);remaining:=remaining-q;

  end loop;

  p_plan.put('lines',bindings);

 end;

 procedure execute_bind(p_task RRL_WAREHOUSE_TASK%rowtype,p_uid varchar2,p_reservation number,p_plan json_object_t,p_actor varchar2) is

  sr RRL_STOCK_RESERVATION%rowtype;l RRL_CASE_PICK_LINE%rowtype;pt RRL_PICK_TASK%rowtype;

  x json_object_t;detail json_object_t;bindings json_array_t;units json_array_t;wire clob;qty number;total number;ver number;rid number;lid number;repl_pick number;

  function selected_units(p_id number,p_qty number) return clob is n number;q number:=0;a json_array_t:=json_array_t();

  begin

   select count(*) into n from RRL_WMS_RECEIPT_UNIT where HARD_RESERVATION_ID=p_id and STOCK_STATUS!='ISSUED';

   if n=0 then return null;end if;

   for u in(select PHYSICAL_UNIT_KEY,BASE_QTY,STOCK_STATUS from RRL_WMS_RECEIPT_UNIT where HARD_RESERVATION_ID=p_id

    and STOCK_STATUS!='ISSUED' order by PHYSICAL_UNIT_KEY) loop

    exit when q=p_qty;

    if u.STOCK_STATUS!='AVAILABLE' or q+u.BASE_QTY>p_qty then raise_application_error(-20884,'GENERIC_REPLENISHMENT_WHOLE_UNITS_REQUIRED');end if;

    a.append(u.PHYSICAL_UNIT_KEY);q:=q+u.BASE_QTY;

    if a.get_size>10000 then raise_application_error(-20881,'GENERIC_REPLENISHMENT_UNIT_BOUND');end if;

   end loop;

   if q!=p_qty then raise_application_error(-20884,'GENERIC_REPLENISHMENT_UNIT_QUANTITY_CONFLICT');end if;

   return a.to_clob;

  end;

 begin

  if p_task.TASK_SOURCE!='WAVE' or p_task.TASK_TYPE!='REPLENISHMENT' then return;end if;

  select PICK_TASK_ID into repl_pick from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=p_task.SOURCE_TASK_ID;

  if repl_pick is not null then

   if not p_plan.has('explicit') then return;end if;

   select * into pt from RRL_PICK_TASK where PICK_TASK_ID=repl_pick for update;

   select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=p_reservation for update;

   total:=RRL_STOCK_REPL_NEED.target_coverage(repl_pick,p_task.TO_CELL,p_reservation);

   if pt.TASK_TYPE!='CASE_PICK' or pt.STATUS!=p_plan.get_string('status')

    or RRL_STOCK_PLAN_HELPER.decimal_text(pt.QTY)!=p_plan.get_string('quantity')

    or RRL_STOCK_PLAN_HELPER.decimal_text(nvl(pt.FACT_QTY,0))!=p_plan.get_string('fact')

    or RRL_STOCK_PLAN_HELPER.decimal_text(total)!=p_plan.get_string('expected_target_covered')

    or sr.SOURCE_DOC_TYPE!='PICK_WAVE' or sr.SOURCE_DOC_ID!=p_task.SOURCE_DOC_ID or sr.SOURCE_LINE_ID!=repl_pick

    or sr.RESERVATION_DOMAIN!='PICKING' or sr.UID_PALLET!=p_uid or sr.CELL!=p_task.TO_CELL then

     raise_application_error(-20890,'CLOSURE_CHANGED: explicit CASE replenishment consumer');end if;

   qty:=greatest(0,sr.BASE_QTY-greatest(0,pt.QTY-nvl(pt.FACT_QTY,0)-total));

   if qty>0 then

    select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=sr.ARTICUL

     and INPUT_UOM=sr.BASE_UOM and BASE_UOM=sr.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;

    wire:=selected_units(p_reservation,qty);

    RRL_STOCK_UNIT_CORE.release_units(p_reservation,qty,wire);

    RRL_STOCK_RESERVE_CORE.release_hard(p_reservation,qty,ver,'PICK_WAVE',p_task.SOURCE_DOC_ID,p_actor);

   end if;

   return;

  end if;

  if p_plan.get_string('signature')!=consumer_signature(p_task) then raise_application_error(-20890,'CLOSURE_CHANGED: generic consumer set');end if;

  bindings:=p_plan.get_array('lines');

  if p_reservation is null then raise_application_error(-20886,'GENERIC_DELIVERED_RESERVATION_REQUIRED');end if;

  select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=p_reservation for update;

  if sr.SOURCE_DOC_TYPE!='PICK_WAVE' or sr.SOURCE_DOC_ID!=p_task.SOURCE_DOC_ID or sr.RESERVATION_DOMAIN!='WAVE'

   or sr.SOURCE_LINE_ID!=p_task.SOURCE_TASK_ID or sr.UID_PALLET!=p_uid or sr.CELL!=p_task.TO_CELL then

   raise_application_error(-20886,'GENERIC_DELIVERED_RESERVATION_IDENTITY_CONFLICT');end if;

  select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=sr.ARTICUL

   and INPUT_UOM=sr.BASE_UOM and BASE_UOM=sr.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;

  for i in 0..bindings.get_size-1 loop

   x:=treat(bindings.get(i) as json_object_t);lid:=x.get_number('line');rid:=x.get_number('reservation');

   select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=lid for update;

   if l.STATUS!=x.get_string('status') or RRL_STOCK_PLAN_HELPER.decimal_text(l.PLANNED_QTY)!=x.get_string('planned')

    or RRL_STOCK_PLAN_HELPER.decimal_text(l.PICKED_QTY)!=x.get_string('picked')

    or RRL_STOCK_PLAN_HELPER.decimal_text(coverage(l.PICK_TASK_ID,p_task.TO_CELL))!=x.get_string('covered')

    or l.CELL_CODE!=p_task.TO_CELL or l.PICK_WAVE_ID!=p_task.SOURCE_DOC_ID or l.ARTICUL!=sr.ARTICUL then

    raise_application_error(-20890,'CLOSURE_CHANGED: generic replenishment consumer');end if;

   select * into pt from RRL_PICK_TASK where PICK_TASK_ID=l.PICK_TASK_ID for update;

   if pt.TASK_TYPE!='CASE_PICK' or pt.ARTICUL!=l.ARTICUL or pt.PICK_PLAN_LINE_ID!=l.PICK_PLAN_LINE_ID

    or pt.CUSTOMER_ORDER_ID!=l.CUSTOMER_ORDER_ID or pt.STATUS in('DONE','CANCELLED','FAILED') then raise_application_error(-20886,'GENERIC_PICK_CONSUMER_IDENTITY_CONFLICT');end if;

   qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));wire:=selected_units(p_reservation,qty);

   RRL_STOCK_UNIT_CORE.release_units(p_reservation,qty,wire);

   RRL_STOCK_RESERVE_CORE.release_hard(p_reservation,qty,ver,'PICK_WAVE',p_task.SOURCE_DOC_ID,p_actor);

   detail:=json_object_t();detail.put('reservation_scope','QTY');detail.put('pick_wave_id',p_task.SOURCE_DOC_ID);

   detail.put('customer_order_id',l.CUSTOMER_ORDER_ID);detail.put('customer_id',l.CUSTOMER_ID);

   detail.put('pick_plan_id',pt.PICK_PLAN_ID);detail.put('pick_plan_line_id',pt.PICK_PLAN_LINE_ID);

   RRL_STOCK_RESERVE_CORE.create_hard(rid,p_uid,p_task.TO_CELL,qty,sr.BASE_UOM,ver,'PICK_WAVE',p_task.SOURCE_DOC_ID,l.PICK_TASK_ID,'PICKING',p_actor,detail.to_clob);

   RRL_STOCK_UNIT_CORE.reserve_units(p_uid,p_task.TO_CELL,rid,qty,wire);

  end loop;

  -- Surplus of this delivered chunk returns to free stock for subsequent waves.

  select BASE_QTY into total from RRL_STOCK_RESERVATION where RESERVATION_ID=p_reservation;

  if total>0 then

   wire:=selected_units(p_reservation,total);

   RRL_STOCK_UNIT_CORE.release_units(p_reservation,total,wire);

   RRL_STOCK_RESERVE_CORE.release_hard(p_reservation,total,ver,'PICK_WAVE',p_task.SOURCE_DOC_ID,p_actor);

  end if;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_REPL_CAPACITY as

 function unit_volume(p_cell varchar2,p_article varchar2) return number is

  v_box number;v_num number;v_den number;n number;

 begin

  if RRL_WEIGHT_BOX_CAPACITY.enabled(p_article)=1 then return RRL_WEIGHT_BOX_CAPACITY.kg_volume_upper_bound(p_cell,p_article);end if;

  select count(*),max(coalesce(case when a.USE_ARTICUL_REPLENISH_RULE=1 then ar.BOX_VOLUME_M3 end,a.BOX_VOLUME_M3))

   into n,v_box from RRL_PICK_FACE pf join RRL_PICK_FACE_ARTICUL a on a.PICK_FACE_ID=pf.PICK_FACE_ID

   left join RRL_ARTICUL_REPLENISH_RULE ar on ar.ARTICUL=a.ARTICUL

   where pf.CELL_CODE=p_cell and pf.ACTIVE=1 and a.ARTICUL=p_article and a.ACTIVE=1;

  if n=0 then

   select count(*),max(UNIT_VOLUME_M3) into n,v_box from RRL_PICK_FACE_ASSIGNMENT

    where CELL_CODE=p_cell and ARTICUL=p_article and STATUS='ACTIVE'

     and BASE_UOM=(select max(BASE_UOM) from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article

      and INPUT_UOM=BASE_UOM and NUMERATOR=1 and DENOMINATOR=1);

   if n=1 and v_box>0 then return v_box;end if;

   raise_application_error(-20887,'PICK_CAPACITY_DYNAMIC_VOLUME_REQUIRED:'||p_article);

  end if;

  if n!=1 or v_box is null or v_box<=0 then raise_application_error(-20887,'PICK_CAPACITY_BOX_VOLUME_REQUIRED:'||p_article);end if;

  begin

   select NUMERATOR,DENOMINATOR into v_num,v_den from RRL_STOCK_UOM_CONVERSION

    where ARTICUL=p_article and INPUT_UOM='BOX' and POLICY_VERSION=(select max(POLICY_VERSION) from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM='BOX');

  exception when no_data_found then raise_application_error(-20887,'PICK_CAPACITY_BOX_BASE_CONVERSION_REQUIRED:'||p_article);end;

  if v_num<=0 or v_den<=0 then raise_application_error(-20887,'PICK_CAPACITY_CONVERSION_INVALID');end if;

  return v_box*v_den/v_num;

 end;

 function remaining_base_quantity(p_cell varchar2,p_article varchar2,p_exclude_repl number default null) return number is

  v_max number;n number;v_occupied number:=0;v_arriving number:=0;v_unit number;v_scale number;v_base varchar2(20);v_remaining number;

  type volume_map is table of number index by varchar2(160);volumes volume_map;

  function volume_for(p_art varchar2) return number is

  begin

   if not volumes.exists(p_art) then volumes(p_art):=unit_volume(p_cell,p_art);end if;

   return volumes(p_art);

  end;

 begin

  if RRL_PICK_RANGE_POLICY.new_target_allowed(p_cell,p_article,p_exclude_repl)!=1 then return 0;end if;

  select count(*),max(MAX_VOLUME) into n,v_max from RRL_PICK_FACE where CELL_CODE=p_cell and ACTIVE=1;

  if n=0 or v_max is null then return null;end if;

  if n!=1 or v_max<=0 then raise_application_error(-20887,'PICK_CAPACITY_VOLUME_AMBIGUOUS_OR_INVALID');end if;

  n:=0;

  for r in(select p.ARTICUL,s.REMAIN,s.UID_POLETA from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA

   where s.CELL=p_cell and s.REMAIN>0 order by s.UID_POLETA fetch first 201 rows only) loop

   n:=n+1;if n>200 then raise_application_error(-20881,'PICK_CAPACITY_STOCK_BOUND');end if;

   if RRL_WEIGHT_BOX_CAPACITY.enabled(r.ARTICUL)=1 then v_occupied:=v_occupied+RRL_WEIGHT_BOX_CAPACITY.physical_volume(r.UID_POLETA,p_cell,r.REMAIN);

   else v_occupied:=v_occupied+r.REMAIN*volume_for(r.ARTICUL);end if;

  end loop;

  n:=0;

  for r in(
   select *from(
    select rt.ARTICUL,rt.QTY,rt.SOURCE_RESERVATION_ID,rt.PALLET_UID,rt.SOURCE_CELL_CODE,
     rt.REPLENISHMENT_QTY_MODE,rem.REMAIN WHOLE_SOURCE_QTY,rt.PICK_WAVE_REPLENISH_TASK_ID,
     nvl((select sum(m.BASE_QTY)from RRL_WAREHOUSE_TASK t join RRL_WAREHOUSE_TASK_STOCK_MOVE m on m.TASK_ID=t.TASK_ID
      where t.TASK_SOURCE='WAVE'and t.TASK_TYPE='REPLENISHMENT'and t.SOURCE_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID),0)ARRIVED,
     row_number()over(partition by rt.REPLENISHMENT_QTY_MODE,
      case when rt.REPLENISHMENT_QTY_MODE='FULL_PALLET'then rt.PALLET_UID else to_char(rt.PICK_WAVE_REPLENISH_TASK_ID)end,
      rt.SOURCE_CELL_CODE order by rt.PICK_WAVE_REPLENISH_TASK_ID)PHYSICAL_RANK
    from RRL_PICK_WAVE_REPLENISH_TASK rt
    left join RRL_STOCK_RESERVATION sr on sr.RESERVATION_ID=rt.SOURCE_RESERVATION_ID
    left join RRL_REMAINS rem on rem.UID_POLETA=rt.PALLET_UID and rem.CELL=rt.SOURCE_CELL_CODE
    where rt.TARGET_CELL_CODE=p_cell and rt.SOURCE_RESERVATION_ID is not null
     and rt.STATUS not in('DONE','CANCELLED','FAILED')
     and(p_exclude_repl is null or rt.PICK_WAVE_REPLENISH_TASK_ID!=p_exclude_repl)
     and(nvl(rt.REPLENISHMENT_QTY_MODE,'BASE')!='FULL_PALLET'or(
      sr.UID_PALLET=rt.PALLET_UID and sr.CELL=rt.SOURCE_CELL_CODE
      and sr.STATUS in('ACTIVE','ALLOCATED','PICKING')and sr.RESERVATION_KIND='HARD'
      and sr.BASE_QTY>0 and rem.REMAIN>0 and sr.ARTICUL=rt.ARTICUL
      and not exists(select 1 from RRL_PICK_WAVE_REPLENISH_TASK excluded
       where excluded.PICK_WAVE_REPLENISH_TASK_ID=p_exclude_repl
        and excluded.REPLENISHMENT_QTY_MODE='FULL_PALLET'
        and excluded.PALLET_UID=rt.PALLET_UID and excluded.SOURCE_CELL_CODE=rt.SOURCE_CELL_CODE
        and excluded.TARGET_CELL_CODE=rt.TARGET_CELL_CODE)))
   )where PHYSICAL_RANK=1 order by PICK_WAVE_REPLENISH_TASK_ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20881,'PICK_CAPACITY_OPEN_ARRIVAL_BOUND');end if;
   if r.REPLENISHMENT_QTY_MODE='FULL_PALLET'then
    if RRL_WEIGHT_BOX_CAPACITY.enabled(r.ARTICUL)=1 then
     v_arriving:=v_arriving+RRL_WEIGHT_BOX_CAPACITY.physical_volume(r.PALLET_UID,r.SOURCE_CELL_CODE,r.WHOLE_SOURCE_QTY);
    else v_arriving:=v_arriving+r.WHOLE_SOURCE_QTY*volume_for(r.ARTICUL);end if;
   elsif RRL_WEIGHT_BOX_CAPACITY.enabled(r.ARTICUL)=1 then
    v_arriving:=v_arriving+RRL_WEIGHT_BOX_CAPACITY.reservation_volume(r.SOURCE_RESERVATION_ID,greatest(0,r.QTY-r.ARRIVED));
   else v_arriving:=v_arriving+greatest(0,r.QTY-r.ARRIVED)*volume_for(r.ARTICUL);end if;
  end loop;
  n:=0;
  for r in(select p.ARTICUL,p.UID_PALLET,t.FROM_CELL,

    case when t.QTY_MODE='PALLET' then ss.REMAIN else t.QTY*

     case when nvl(t.UNIT_CODE,ss.BASE_UOM)=ss.BASE_UOM then 1 else cv.NUMERATOR/cv.DENOMINATOR end end BASE_QTY

    from RRL_WAREHOUSE_TASK t join RRL_PALLETS p on p.UID_PALLET=nvl(t.UID_PALLET,t.SSCC)

    join RRL_REMAINS ss on ss.UID_POLETA=p.UID_PALLET and ss.CELL=t.FROM_CELL

    left join RRL_STOCK_UOM_CONVERSION cv on cv.ARTICUL=p.ARTICUL and cv.INPUT_UOM=t.UNIT_CODE

     and cv.POLICY_VERSION=(select max(POLICY_VERSION) from RRL_STOCK_UOM_CONVERSION where ARTICUL=p.ARTICUL and INPUT_UOM=t.UNIT_CODE)

    where t.TO_CELL=p_cell and t.FROM_CELL!=p_cell and t.STATUS in('PLANNED','ASSIGNED','IN_PROGRESS')

     and not(t.TASK_SOURCE='WAVE' and t.TASK_TYPE='REPLENISHMENT')

    order by t.TASK_ID fetch first 201 rows only) loop

   n:=n+1;if n>200 then raise_application_error(-20881,'PICK_CAPACITY_OTHER_ARRIVAL_BOUND');end if;

   if r.BASE_QTY is null or r.BASE_QTY<0 then raise_application_error(-20887,'PICK_CAPACITY_ARRIVAL_UOM_REQUIRED');end if;

   if RRL_WEIGHT_BOX_CAPACITY.enabled(r.ARTICUL)=1 then v_arriving:=v_arriving+RRL_WEIGHT_BOX_CAPACITY.physical_volume(r.UID_PALLET,r.FROM_CELL,r.BASE_QTY,0);

   else v_arriving:=v_arriving+r.BASE_QTY*volume_for(r.ARTICUL);end if;

  end loop;

  v_unit:=volume_for(p_article);

  begin

   select BASE_UOM,BASE_SCALE into v_base,v_scale from RRL_STOCK_UOM_CONVERSION

    where ARTICUL=p_article and INPUT_UOM=BASE_UOM and NUMERATOR=1 and DENOMINATOR=1

     and POLICY_VERSION=(select max(POLICY_VERSION) from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM=BASE_UOM and NUMERATOR=1 and DENOMINATOR=1);

  exception when no_data_found or too_many_rows then raise_application_error(-20887,'PICK_CAPACITY_BASE_POLICY_REQUIRED');end;

  if v_base in('PCE','PCS','PC','EA','ST','STK','ШТ','ШТУКА') then v_scale:=0;end if;

  v_remaining:=greatest(0,v_max-v_occupied-v_arriving)/v_unit;

  return floor(v_remaining*power(10,v_scale))/power(10,v_scale);

 end;

 procedure assert_arrival(p_repl number,p_base_quantity number) is rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;q number;

 begin

  select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=p_repl;

  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);

  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CELL',rt.TARGET_CELL_CODE),6);

  q:=remaining_base_quantity(rt.TARGET_CELL_CODE,rt.ARTICUL,p_repl);

  if q is not null and p_base_quantity>q then raise_application_error(-20886,'PICK_CAPACITY_INSUFFICIENT: wait for free capacity');end if;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_REPL_CONTINUATION as

 procedure plan_next(p_task RRL_WAREHOUSE_TASK%rowtype,p_qty number,p_residual number,p_rows in out nocopy json_array_t,p_domain in out nocopy json_object_t) is

  rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;v_fact number;v_next number;v_short number;v_remaining number;v_incoming_owned number;v json_object_t:=json_object_t();

 begin

  if p_task.TASK_SOURCE!='WAVE' or p_task.TASK_TYPE!='REPLENISHMENT' or p_residual is not null then return;end if;

  select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=p_task.SOURCE_TASK_ID;

  select count(*) into v_short from RRL_CASE_PICK_SHORT where REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID and RECOVERY_STATE='WAIT_REPLENISHMENT';

  if rt.MINIMAX_CYCLE_ID is not null or v_short>0 then return;end if;

  select nvl(sum(m.BASE_QTY),0)+p_qty into v_fact from RRL_WAREHOUSE_TASK t join RRL_WAREHOUSE_TASK_STOCK_MOVE m on m.TASK_ID=t.TASK_ID

   where t.TASK_SOURCE='WAVE' and t.TASK_TYPE='REPLENISHMENT' and t.SOURCE_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID;

  v_remaining:=greatest(0,nvl(rt.DEMAND_BASE_QTY,rt.QTY)-v_fact);

  if rt.PICK_TASK_ID is not null then

   if p_task.QTY_MODE='PALLET' then
    select least(nvl(sum(BASE_QTY),0),p_qty) into v_incoming_owned from RRL_STOCK_RESERVATION
     where UID_PALLET=p_task.UID_PALLET and CELL=p_task.FROM_CELL
      and SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=rt.PICK_WAVE_ID
      and SOURCE_LINE_ID=rt.PICK_TASK_ID and RESERVATION_DOMAIN='PICKING'
      and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_QTY>0;
   else
    select least(BASE_QTY,p_qty) into v_incoming_owned from RRL_STOCK_RESERVATION where RESERVATION_ID=rt.SOURCE_RESERVATION_ID;
   end if;

   v_remaining:=greatest(0,RRL_STOCK_REPL_NEED.remaining_for_task(rt.PICK_TASK_ID,p_task.TO_CELL)-v_incoming_owned);

  end if;

  if v_remaining<=0 then return;end if;

  select RRL_PICK_WAVE_REPL_SQ.nextval into v_next from dual;

  RRL_STOCK_PLAN_HELPER.row_key(p_rows,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_next));

  RRL_STOCK_PLAN_HELPER.anchor(p_rows,70,'UNIQUE','REPL.CONT:'||RRL_STOCK_PLAN_HELPER.decimal_text(rt.PICK_WAVE_REPLENISH_TASK_ID));

  v.put('id',v_next);v.put('demand',RRL_STOCK_PLAN_HELPER.decimal_text(nvl(rt.DEMAND_BASE_QTY,rt.QTY)));

  v.put('fact',RRL_STOCK_PLAN_HELPER.decimal_text(v_fact));v.put('remaining',RRL_STOCK_PLAN_HELPER.decimal_text(v_remaining));

  p_domain.put('replenishment_continuation',v);

 end;

 procedure create_next(p_task RRL_WAREHOUSE_TASK%rowtype,p_domain json_object_t,p_actor varchar2) is

  rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;v json_object_t;v_fact number;v_id number;

 begin

  if not p_domain.has('replenishment_continuation') then return;end if;

  v:=p_domain.get_object('replenishment_continuation');v_id:=v.get_number('id');

  select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=p_task.SOURCE_TASK_ID;

  select nvl(sum(m.BASE_QTY),0) into v_fact from RRL_WAREHOUSE_TASK t join RRL_WAREHOUSE_TASK_STOCK_MOVE m on m.TASK_ID=t.TASK_ID

   where t.TASK_SOURCE='WAVE' and t.TASK_TYPE='REPLENISHMENT' and t.SOURCE_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID;

  if rt.STATUS!='DONE' or RRL_STOCK_PLAN_HELPER.decimal_text(nvl(rt.DEMAND_BASE_QTY,rt.QTY))!=v.get_string('demand')

   or RRL_STOCK_PLAN_HELPER.decimal_text(v_fact)!=v.get_string('fact') then raise_application_error(-20890,'CLOSURE_CHANGED: replenishment remaining demand');end if;

  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_id)));

  rt.PARENT_REPLENISH_TASK_ID:=rt.PICK_WAVE_REPLENISH_TASK_ID;rt.PICK_WAVE_REPLENISH_TASK_ID:=v_id;

  rt.QTY:=RRL_STOCK_MATH.quantity(v.get_string('remaining'));rt.DEMAND_BASE_QTY:=rt.QTY;rt.STATUS:='RELEASED';

  rt.SOURCE_RESERVATION_ID:=null;rt.PALLET_UID:=null;rt.SOURCE_CELL_CODE:=null;rt.SOURCE_AVAILABLE_QTY:=null;

  rt.SOURCE_PRODUCED_DATE:=null;rt.SOURCE_EXPIRY_DATE:=null;rt.RELEASED_AT:=sysdate;rt.RELEASED_BY:=p_actor;

  rt.CREATED_AT:=sysdate;rt.CREATED_BY:=p_actor;rt.UPDATED_AT:=sysdate;rt.UPDATED_BY:=p_actor;

  rt.RESERVE_REQUEST_JSON:=null;

  rt.RESERVE_OPERATION_ID:='REPL.CONT.SOURCE:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_id);

  rt.WAIT_REASON:='Remaining demand after confirmed source pallet delivery';

  insert into RRL_PICK_WAVE_REPLENISH_TASK values rt;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_REPL_NEED as
 function target_coverage(p_pick number,p_cell varchar2,p_exclude number default null) return number is
  v_total number:=0;v_count number:=0;v_ware number;v_article varchar2(160);v_type varchar2(30);v_order number;
 begin
  select co.WARE_ID,pt.ARTICUL,pt.TASK_TYPE,pt.CUSTOMER_ORDER_ID into v_ware,v_article,v_type,v_order from RRL_PICK_TASK pt
   join RRL_CUSTOMER_ORDER co on co.CUSTOMER_ORDER_ID=pt.CUSTOMER_ORDER_ID where pt.PICK_TASK_ID=p_pick;
  for sr in(select * from RRL_STOCK_RESERVATION where SOURCE_DOC_TYPE='PICK_WAVE'
   and SOURCE_LINE_ID=p_pick and CUSTOMER_ORDER_ID=v_order and CELL=p_cell and ARTICUL=v_article and RESERVATION_DOMAIN='PICKING'
   and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING')
   and (p_exclude is null or RESERVATION_ID!=p_exclude) order by RESERVATION_ID fetch first 201 rows only) loop
   v_count:=v_count+1;if v_count>200 then raise_application_error(-20881,'TARGET_COVERAGE_BOUND');end if;
   if RRL_STOCK_ELIGIBILITY.reason(sr.UID_PALLET,sr.CELL,v_ware,sr.BASE_QTY,null,null,
     case when v_type='CASE_PICK' then 'PICK' else 'ALLOCATE' end,sr.RESERVATION_ID,v_article) is null then
    v_total:=v_total+sr.BASE_QTY;
   end if;
  end loop;
  return v_total;
 end;
 function remaining_for_task(p_pick number,p_cell varchar2) return number is v_qty number;v_fact number;
 begin
  select QTY,nvl(FACT_QTY,0) into v_qty,v_fact from RRL_PICK_TASK where PICK_TASK_ID=p_pick;
  return greatest(0,v_qty-v_fact-target_coverage(p_pick,p_cell));
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_REPL_SHARED as

 function allowed(p_uid varchar2,p_cell varchar2,p_target varchar2,p_ware number,p_owner number) return number is

  n number;v_count number:=0;v_qty number;v_target varchar2(60);v_type varchar2(30);v_status varchar2(30);v_ware number;v_remaining number;v_target_owned number;v_source_owned number;

 begin

  select count(*) into n from RRL_STOCK_RESERVATION where RESERVATION_ID=p_owner and UID_PALLET=p_uid and CELL=p_cell

   and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_QTY>0;

  if n!=1 then return 0;end if;

  for sr in(select * from RRL_STOCK_RESERVATION where UID_PALLET=p_uid and CELL=p_cell

   and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') order by RESERVATION_ID fetch first 201 rows only) loop

   v_count:=v_count+1;if v_count>200 then raise_application_error(-20881,'SHARED_REPLENISHMENT_OWNER_BOUND');end if;

   if sr.RESERVATION_ID=p_owner then continue;end if;

   if sr.SOURCE_DOC_TYPE is null or sr.SOURCE_DOC_TYPE!='PICK_WAVE' or sr.RESERVATION_DOMAIN is null or sr.RESERVATION_DOMAIN!='PICKING'

    or sr.SOURCE_LINE_ID is null or sr.BASE_QTY is null or sr.BASE_QTY<=0 then return 0;end if;

   begin

    select t.TARGET_CELL_CODE,t.TASK_TYPE,t.STATUS,w.WARE_ID,greatest(t.QTY-nvl(t.FACT_QTY,0),0) into v_target,v_type,v_status,v_ware,v_remaining

     from RRL_PICK_TASK t join RRL_PICK_WAVE w on w.PICK_WAVE_ID=sr.SOURCE_DOC_ID

     where t.PICK_TASK_ID=sr.SOURCE_LINE_ID and w.STATUS='LAUNCHED' and t.ARTICUL=sr.ARTICUL and t.CUSTOMER_ORDER_ID=sr.CUSTOMER_ORDER_ID;

   exception when no_data_found then return 0;end;

   if v_target is null or v_target!=p_target or v_type!='CASE_PICK' or v_status not in('NEW','ASSIGNED','IN_PROGRESS')

    or v_ware!=p_ware then return 0;end if;

   select nvl(sum(BASE_QTY),0) into v_source_owned from RRL_STOCK_RESERVATION

    where UID_PALLET=p_uid and CELL=p_cell and SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=sr.SOURCE_DOC_ID

     and SOURCE_LINE_ID=sr.SOURCE_LINE_ID and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING');

   -- Separate bindings of the same owner share one physical source.
   -- Admission compares their total quantity, without merging their identities.

   select nvl(sum(BASE_QTY),0) into v_target_owned from RRL_STOCK_RESERVATION

    where CELL=p_target and SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=sr.SOURCE_DOC_ID and SOURCE_LINE_ID=sr.SOURCE_LINE_ID

     and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING');

   if v_source_owned>greatest(0,v_remaining-v_target_owned) then return 0;end if;

  end loop;

  return 1;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_RESERVATION_CMD as
 procedure source_anchor(p_r in out nocopy json_array_t,p_type varchar2,p_id number) is v_table varchar2(40);
 begin
  if p_id is null or p_id<1 or p_id!=trunc(p_id) then raise_application_error(-20869,'RESERVATION_DOCUMENT_REQUIRED');end if;
  case p_type when 'PRODUCTION_ORDER' then v_table:='RRL_PRODUCTION_ORDER';
   when 'PICK_WAVE' then v_table:='RRL_PICK_WAVE';when 'PICK_PLAN' then v_table:='RRL_PICK_PLAN';
   else raise_application_error(-20869,'RESERVATION_DOCUMENT_TYPE_UNSUPPORTED');end case;
  RRL_STOCK_PLAN_HELPER.row_key(p_r,v_table,RRL_STOCK_PLAN_HELPER.decimal_text(p_id));
 end;
 procedure validate_source(p_type varchar2,p_id number,p_allow_closed number default 0) is v_status varchar2(40);
 begin
  case p_type when 'PRODUCTION_ORDER' then
    select STATUS into v_status from RRL_PRODUCTION_ORDER where PRODUCTION_ORDER_ID=p_id for update;
   when 'PICK_WAVE' then select STATUS into v_status from RRL_PICK_WAVE where PICK_WAVE_ID=p_id for update;
   when 'PICK_PLAN' then select STATUS into v_status from RRL_PICK_PLAN where PICK_PLAN_ID=p_id for update;
   else raise_application_error(-20869,'RESERVATION_DOCUMENT_TYPE_UNSUPPORTED');end case;
  if p_allow_closed=0 and (v_status is null or v_status in('CANCELLED','CLOSED','COMPLETED','SHIPPED')) then
   raise_application_error(-20869,'RESERVATION_DOCUMENT_NOT_OPEN');end if;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t;s json_object_t;
  r json_array_t:=json_array_t();f json_array_t:=json_array_t();v json_object_t:=json_object_t();
  old RRL_STOCK_RESERVATION%rowtype;v_id number;v_uid varchar2(200);v_cell varchar2(60);v_article varchar2(160);
  v_type varchar2(50);v_doc number;v_version number;
 begin
  m:=d.get_object('metadata');s:=d.get_object('source');
  if d.get_string('command_type')='RESERVATION_CREATE' then
   select RRL_STOCK_RESERVATION_SQ.nextval into v_id from dual;
   v_uid:=m.get_string('uid_pallet');v_cell:=m.get_string('cell');v_article:=m.get_string('articul');
   v_type:=m.get_string('source_doc_type');v_doc:=m.get_number('source_doc_id');
  else
   v_id:=s.get_number('reservation_id');
   select * into old from RRL_STOCK_RESERVATION where RESERVATION_ID=v_id;
   v_uid:=old.UID_PALLET;v_cell:=old.CELL;v_article:=old.ARTICUL;v_type:=old.SOURCE_DOC_TYPE;v_doc:=old.SOURCE_DOC_ID;
   v_version:=old.RESERVATION_VERSION;
   if d.get_string('command_type')='RESERVATION_PROMOTE' then
    v_uid:=m.get_string('uid_pallet');v_cell:=m.get_string('cell');
   end if;
  end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));
  source_anchor(r,v_type,v_doc);
  if v_uid is not null and v_cell is not null then RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v_uid,v_article,v_cell,null);
  else RRL_STOCK_PLAN_HELPER.fence(f,'SKU',v_article);end if;
  v.put('reservation_id',v_id);v.put('uid',v_uid);v.put('cell',v_cell);v.put('article',v_article);
  v.put('doc_type',v_type);v.put('doc_id',v_doc);v.put('version',v_version);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t;v json_object_t;j json_object_t:=json_object_t();
  old RRL_STOCK_RESERVATION%rowtype;v_plan clob;v_id number;v_kind varchar2(80);v_qty number;v_input varchar2(20);
  v_base varchar2(20);v_num number;v_den number;v_scale number;v_version number;v_ware number;v_article varchar2(160);
  v_uid varchar2(200);v_cell varchar2(60);v_type varchar2(50);v_doc number;v_units clob;v_event number;v_n number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'stock_reservation_edit')!=1 then raise_application_error(-20882,'RESERVATION_FORBIDDEN');end if;
  m:=d.get_object('metadata');v_kind:=d.get_string('command_type');
  if v_kind='RESERVATION_CREATE' and (m.get_string('reservation_kind') is null or m.get_string('reservation_kind') not in('SOFT','HARD')) then raise_application_error(-20869,'RESERVATION_KIND_INVALID');end if;
  declare
 v_json_sql_1_1 varchar2(32767):=d.get_string('operation_id');
begin
select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_1_1;
end;
  v:=json_object_t.parse(v_plan).get_object('domain');
  v_id:=v.get_number('reservation_id');v_uid:=v.get_string('uid');v_cell:=v.get_string('cell');
  v_article:=v.get_string('article');v_type:=v.get_string('doc_type');v_doc:=v.get_number('doc_id');
  validate_source(v_type,v_doc,case when v_kind in('RESERVATION_RELEASE','RESERVATION_CANCEL') then 1 else 0 end);
  if v_kind!='RESERVATION_CREATE' then
   select * into old from RRL_STOCK_RESERVATION where RESERVATION_ID=v_id for update;
   if old.RESERVATION_VERSION!=v.get_number('version') or old.SOURCE_DOC_TYPE!=v_type or old.SOURCE_DOC_ID!=v_doc
    or (v_kind!='RESERVATION_PROMOTE' and (old.UID_PALLET!=v_uid or old.CELL!=v_cell)) then
    raise_application_error(-20890,'CLOSURE_CHANGED: reservation');end if;
  end if;
  -- Release/cancellation remains legal after its source document is closed.

  if d.get_array('units').get_size>0 then v_units:=d.get_array('units').to_clob;end if;
  if v_kind='RESERVATION_CREATE' and (m.get_string('reservation_scope') is null or m.get_string('reservation_scope') not in('PALLET','QTY')) then raise_application_error(-20869,'RESERVATION_SCOPE_INVALID');end if;
  if v_kind='RESERVATION_CREATE' and m.get_string('reservation_kind')='SOFT' then
   if m.get_string('uid_pallet') is not null or m.get_string('cell') is not null or m.get_number('ware_id') is not null or m.get_string('batch_id') is not null or m.get_number('prod_batch_id') is not null or m.get_string('sscc') is not null then raise_application_error(-20869,'SOFT_HAS_PHYSICAL_BINDING');end if;
   v_qty:=RRL_STOCK_MATH.quantity(m.get_string('qty'));
   RRL_STOCK_CTX_API.begin_effect('RESERVATION',null,null,v_id);
   declare
 v_json_sql_2_1 varchar2(32767):=m.get_string('reservation_scope');
 v_json_sql_2_2 varchar2(32767):=m.get_string('reservation_domain');
 v_json_sql_2_3 number:=m.get_number('source_line_id');
 v_json_sql_2_4 number:=m.get_number('task_id');
 v_json_sql_2_5 number:=m.get_number('customer_id');
 v_json_sql_2_6 number:=m.get_number('customer_order_id');
 v_json_sql_2_7 number:=m.get_number('pick_plan_line_id');
 v_json_sql_2_8 number:=m.get_number('pick_wave_line_id');
 v_json_sql_2_9 varchar2(32767):=m.get_string('unit_code');
 v_json_sql_2_10 number:=m.get_number('priority');
begin
insert into RRL_STOCK_RESERVATION(RESERVATION_ID,RESERVATION_KIND,RESERVATION_SCOPE,RESERVATION_DOMAIN,
    SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_LINE_ID,TASK_ID,CUSTOMER_ID,CUSTOMER_ORDER_ID,PRODUCTION_ORDER_ID,PICK_PLAN_ID,PICK_PLAN_LINE_ID,PICK_WAVE_ID,PICK_WAVE_LINE_ID,ARTICUL,QTY,UNIT_CODE,STATUS,PRIORITY,CREATED_BY,RESERVATION_VERSION)
    values(v_id,'SOFT',v_json_sql_2_1,v_json_sql_2_2,v_type,v_doc,
     v_json_sql_2_3,v_json_sql_2_4,v_json_sql_2_5,v_json_sql_2_6,
     case when v_type='PRODUCTION_ORDER' then v_doc else null end,case when v_type='PICK_PLAN' then v_doc else null end,v_json_sql_2_7,case when v_type='PICK_WAVE' then v_doc else null end,v_json_sql_2_8,v_article,v_qty,v_json_sql_2_9,'ACTIVE',nvl(v_json_sql_2_10,100),p_actor,0);
end;
   RRL_STOCK_CTX_API.end_effect;
  elsif old.RESERVATION_KIND='SOFT' and v_kind in('RESERVATION_RELEASE','RESERVATION_CANCEL') then
   if old.STATUS not in('ACTIVE','ALLOCATED') then raise_application_error(-20869,'SOFT_RELEASE_STATE_CONFLICT');end if;
   RRL_STOCK_CTX_API.begin_effect('RESERVATION',null,null,v_id);
   update RRL_STOCK_RESERVATION set STATUS=case when v_kind='RESERVATION_CANCEL' then 'CANCELLED' else 'RELEASED' end,
    RELEASED_AT=systimestamp,RELEASED_BY=p_actor,RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=v_id;
   RRL_STOCK_CTX_API.end_effect;
  else
   if v_uid is null or v_cell is null then raise_application_error(-20869,'HARD_STOCK_REQUIRED');end if;
   select ARTICUL into v_article from RRL_PALLETS where UID_PALLET=v_uid;
   if v_article!=v.get_string('article') then raise_application_error(-20869,'RESERVATION_ARTICLE_CONFLICT');end if;
   select WARE_ID into v_ware from RRL_CELLS where CELL=v_cell;
   if v_kind in('RESERVATION_CREATE','RESERVATION_PROMOTE') then
    RRL_STOCK_LOCATION_CORE.assert_ordinary(v_cell,v_ware,'SOURCE');
    if m.get_number('ware_id') is null or m.get_number('ware_id')!=v_ware then raise_application_error(-20869,'RESERVATION_WAREHOUSE_CONFLICT');end if;
    v_input:=nvl(m.get_string('unit_code'),old.UNIT_CODE);
    v_qty:=case when m.has('qty') and not m.get('qty').is_null then RRL_STOCK_MATH.quantity(m.get_string('qty')) else old.QTY end;
    select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_input;
    select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into v_base,v_num,v_den,v_scale
     from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_input and POLICY_VERSION=v_version;
    v_qty:=RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(v_qty),v_num,v_den,v_scale);
    -- Conversion version describes input units; balances always use the
    -- latest identity policy for their canonical base unit.
    select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION
     where ARTICUL=v_article and INPUT_UOM=v_base and BASE_UOM=v_base
       and NUMERATOR=1 and DENOMINATOR=1;
    if v_version is null then raise_application_error(-20868,'BASE_IDENTITY_POLICY_REQUIRED');end if;
    if v_type in('PICK_WAVE','PICK_PLAN') then
     RRL_STOCK_ELIGIBILITY.assert_source(v_uid,v_cell,v_ware,v_qty,null,null,'ALLOCATE',null,v_article);
    end if;
    if v_kind='RESERVATION_PROMOTE' then
     if old.RESERVATION_KIND!='SOFT' or old.STATUS not in('ACTIVE','ALLOCATED') then raise_application_error(-20869,'SOFT_PROMOTION_CONFLICT');end if;
     RRL_STOCK_BALANCE_CORE.apply_delta(v_uid,v_cell,0,v_qty,v_base,v_version);
     RRL_STOCK_CTX_API.begin_effect('RESERVATION',v_uid,v_cell,v_id);
     declare
 v_json_sql_3_1 varchar2(32767):=m.get_string('reservation_scope');
begin
update RRL_STOCK_RESERVATION set RESERVATION_KIND='HARD',RESERVATION_SCOPE=v_json_sql_3_1,
      UID_PALLET=v_uid,CELL=v_cell,WARE_ID=v_ware,QTY=v_qty,UNIT_CODE=v_base,BASE_QTY=v_qty,BASE_UOM=v_base,
      STATUS='ACTIVE',RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=v_id;
end;
     RRL_STOCK_CTX_API.end_effect;
    else RRL_STOCK_RESERVE_CORE.create_hard(v_id,v_uid,v_cell,v_qty,v_base,v_version,v_type,v_doc,
      m.get_number('source_line_id'),m.get_string('reservation_domain'),p_actor,m.to_clob);end if;
    select nvl(max(MARKING_REQUIRED),0) into v_n from RRL_SKU_RECEIPT_POLICY where ARTICUL=v_article;
    if v_n=1 then
     select count(*) into v_n from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=v_uid and CURRENT_CELL=v_cell and STOCK_STATUS!='ISSUED';
     if v_n=0 then raise_application_error(-20884,'MARKED_BINDING_REQUIRED');end if;
    end if;
    RRL_STOCK_UNIT_CORE.reserve_units(v_uid,v_cell,v_id,v_qty,v_units);
   else
    v_qty:=old.BASE_QTY;v_base:=old.BASE_UOM;
    select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_base and BASE_UOM=v_base and NUMERATOR=DENOMINATOR;
    if v_kind='RESERVATION_CONSUME' then
     RRL_STOCK_LOCATION_CORE.assert_ordinary(v_cell,v_ware,'SOURCE');
     RRL_STOCK_UNIT_CORE.release_units(v_id,v_qty,v_units,1);
     RRL_STOCK_RESERVE_CORE.consume_hard(v_id,v_qty,v_version,v_type,v_doc,p_actor);
     RRL_STOCK_BALANCE_CORE.write_leg(v_uid,v_cell,null,-v_qty,v_base,v_version,1,1,3,p_actor,v_event);
    else
     RRL_STOCK_UNIT_CORE.release_units(v_id,v_qty,v_units,0);
     RRL_STOCK_RESERVE_CORE.release_hard(v_id,v_qty,v_version,v_type,v_doc,p_actor);
     if v_kind='RESERVATION_CANCEL' then RRL_STOCK_CTX_API.begin_effect('RESERVATION',v_uid,v_cell,v_id);update RRL_STOCK_RESERVATION set STATUS='CANCELLED',RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=v_id;RRL_STOCK_CTX_API.end_effect;end if;
    end if;
   end if;
  end if;
  j.put('operation_id',d.get_string('operation_id'));j.put('reservation_id',v_id);j.put('action',v_kind);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_RESERVE_CORE as
 procedure lock_identity(p_id number) is
 begin
  if p_id is null or p_id<1 or p_id!=trunc(p_id) then raise_application_error(-20876,'RESERVATION_ID_INVALID'); end if;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STOCK_RESERVATION',to_char(p_id,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')));
 end;
 procedure check_owner(p_id number,p_qty number,p_doc_type varchar2,p_doc_id number,p_r out RRL_STOCK_RESERVATION%rowtype) is
 begin
  lock_identity(p_id);
  select * into p_r from RRL_STOCK_RESERVATION where RESERVATION_ID=p_id for update;
  if p_r.RESERVATION_KIND is null or p_r.RESERVATION_KIND!='HARD' or p_r.STATUS is null or p_r.STATUS not in('ACTIVE','ALLOCATED','PICKING')
   or p_r.BASE_QTY is null or p_r.BASE_UOM is null or p_qty is null or p_qty<=0 or p_qty>p_r.BASE_QTY
   or p_doc_type is null or p_doc_id is null or p_r.SOURCE_DOC_TYPE is null or p_r.SOURCE_DOC_ID is null or p_r.SOURCE_DOC_TYPE!=p_doc_type or p_r.SOURCE_DOC_ID!=p_doc_id then
   raise_application_error(-20869,'RESERVATION_CONFLICT');
  end if;
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_r.UID_PALLET));
 end;
 procedure decrease(p_r RRL_STOCK_RESERVATION%rowtype,p_qty number,p_status varchar2,p_actor varchar2) is
 begin
  RRL_STOCK_CTX_API.begin_effect('RESERVATION',p_r.UID_PALLET,p_r.CELL,p_r.RESERVATION_ID);
  update RRL_STOCK_RESERVATION set BASE_QTY=BASE_QTY-p_qty,QTY=BASE_QTY-p_qty,UNIT_CODE=BASE_UOM,
   STATUS=case when BASE_QTY=p_qty then p_status else STATUS end,
   CONSUMED_AT=case when BASE_QTY=p_qty and p_status='CONSUMED' then systimestamp else CONSUMED_AT end,
   CONSUMED_BY=case when BASE_QTY=p_qty and p_status='CONSUMED' then p_actor else CONSUMED_BY end,
   RELEASED_AT=case when BASE_QTY=p_qty and p_status='RELEASED' then systimestamp else RELEASED_AT end,
   RELEASED_BY=case when BASE_QTY=p_qty and p_status='RELEASED' then p_actor else RELEASED_BY end,
   RESERVATION_VERSION=RESERVATION_VERSION+1
   where RESERVATION_ID=p_r.RESERVATION_ID and RESERVATION_VERSION=p_r.RESERVATION_VERSION;
  if sql%rowcount!=1 then raise_application_error(-20867,'VERSION_CONFLICT'); end if;
  RRL_STOCK_CTX_API.end_effect;
 end;
 procedure create_hard(p_id number,p_uid varchar2,p_cell varchar2,p_qty number,p_uom varchar2,p_uom_version number,
   p_doc_type varchar2,p_doc_id number,p_line_id number,p_domain varchar2,p_actor varchar2,p_details clob default null) is v_article varchar2(160);v_ware number;v_details json_object_t;v_carrier number;
 begin
  lock_identity(p_id);
  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',p_uid));
  select count(*) into v_carrier from RRL_CASE_CARRIER_LOT where LOT_UID=p_uid;
  if v_carrier>0 then raise_application_error(-20869,'CASE_CARRIER_NOT_ALLOCATABLE: unpack through carrier return');end if;
  select ARTICUL into v_article from RRL_PALLETS where UID_PALLET=p_uid;
  select WARE_ID into v_ware from RRL_CELLS where CELL=p_cell;
  if p_qty is null or p_qty<=0 or p_doc_id is null or p_doc_type is null or p_domain is null then raise_application_error(-20869,'RESERVATION_CONFLICT'); end if;
  if p_domain in('PICKING','WAVE') or p_doc_type in('PICK_WAVE','PICK_PLAN') then
   RRL_STOCK_ELIGIBILITY.assert_source(p_uid,p_cell,v_ware,p_qty,null,null,'ALLOCATE',null,v_article);
  end if;
  RRL_STOCK_BALANCE_CORE.apply_delta(p_uid,p_cell,0,p_qty,p_uom,p_uom_version);
  RRL_STOCK_CTX_API.begin_effect('RESERVATION',p_uid,p_cell,p_id);
  insert into RRL_STOCK_RESERVATION(RESERVATION_ID,RESERVATION_KIND,RESERVATION_SCOPE,RESERVATION_DOMAIN,
   SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_LINE_ID,ARTICUL,QTY,UNIT_CODE,WARE_ID,CELL,UID_PALLET,
   STATUS,PRIORITY,CREATED_BY,BASE_QTY,BASE_UOM,RESERVATION_VERSION)
   values(p_id,'HARD','QTY',p_domain,p_doc_type,p_doc_id,p_line_id,v_article,p_qty,p_uom,v_ware,p_cell,p_uid,
   'ACTIVE',0,p_actor,p_qty,p_uom,0);
  if p_details is not null then
   v_details:=json_object_t.parse(p_details);
   if v_details.get_string('reservation_scope') is null or v_details.get_string('reservation_scope') not in('PALLET','QTY') then raise_application_error(-20869,'RESERVATION_SCOPE_INVALID');end if;
   declare
 v_json_sql_1_1 varchar2(32767):=v_details.get_string('reservation_scope');
 v_json_sql_1_2 number:=v_details.get_number('task_id');
 v_json_sql_1_3 number:=v_details.get_number('customer_id');
 v_json_sql_1_4 number:=v_details.get_number('customer_order_id');
 v_json_sql_1_5 number:=v_details.get_number('production_order_id');
 v_json_sql_1_6 number:=v_details.get_number('pick_plan_id');
 v_json_sql_1_7 number:=v_details.get_number('pick_plan_line_id');
 v_json_sql_1_8 number:=v_details.get_number('pick_wave_id');
 v_json_sql_1_9 number:=v_details.get_number('pick_wave_line_id');
 v_json_sql_1_10 varchar2(32767):=v_details.get_string('batch_id');
 v_json_sql_1_11 number:=v_details.get_number('prod_batch_id');
 v_json_sql_1_12 number:=v_details.get_number('cell_slot_id');
 v_json_sql_1_13 number:=v_details.get_number('priority');
begin
update RRL_STOCK_RESERVATION set RESERVATION_SCOPE=v_json_sql_1_1,
    TASK_ID=v_json_sql_1_2,CUSTOMER_ID=v_json_sql_1_3,CUSTOMER_ORDER_ID=v_json_sql_1_4,
    PRODUCTION_ORDER_ID=case when p_doc_type='PRODUCTION_ORDER' then p_doc_id else v_json_sql_1_5 end,
    PICK_PLAN_ID=case when p_doc_type='PICK_PLAN' then p_doc_id else v_json_sql_1_6 end,
    PICK_PLAN_LINE_ID=v_json_sql_1_7,PICK_WAVE_ID=case when p_doc_type='PICK_WAVE' then p_doc_id else v_json_sql_1_8 end,
    PICK_WAVE_LINE_ID=v_json_sql_1_9,BATCH_ID=v_json_sql_1_10,PROD_BATCH_ID=v_json_sql_1_11,
    CELL_SLOT_ID=v_json_sql_1_12,PRIORITY=nvl(v_json_sql_1_13,100),RESERVATION_VERSION=RESERVATION_VERSION+1
    where RESERVATION_ID=p_id;
end;
  end if;
  RRL_STOCK_CTX_API.end_effect;
 end;
 procedure release_hard(p_id number,p_qty number,p_uom_version number,p_doc_type varchar2,p_doc_id number,p_actor varchar2) is r RRL_STOCK_RESERVATION%rowtype;
 begin
  check_owner(p_id,p_qty,p_doc_type,p_doc_id,r);
  RRL_STOCK_BALANCE_CORE.apply_delta(r.UID_PALLET,r.CELL,0,-p_qty,r.BASE_UOM,p_uom_version);
  decrease(r,p_qty,'RELEASED',p_actor);
 end;
 procedure consume_hard(p_id number,p_qty number,p_uom_version number,p_doc_type varchar2,p_doc_id number,p_actor varchar2) is r RRL_STOCK_RESERVATION%rowtype;
 begin
  check_owner(p_id,p_qty,p_doc_type,p_doc_id,r);
  RRL_STOCK_BALANCE_CORE.apply_delta(r.UID_PALLET,r.CELL,-p_qty,-p_qty,r.BASE_UOM,p_uom_version);
  decrease(r,p_qty,'CONSUMED',p_actor);
 end;
 procedure relocate_hard(p_id number,p_new_id number,p_target_uid varchar2,p_target_cell varchar2,
   p_qty number,p_uom_version number,p_actor varchar2) is
  r RRL_STOCK_RESERVATION%rowtype;v_art varchar2(160);v_ware number;
 begin
  lock_identity(p_id);lock_identity(p_new_id);
  select * into r from RRL_STOCK_RESERVATION where RESERVATION_ID=p_id for update;
  if r.RESERVATION_KIND!='HARD' or r.STATUS not in('ACTIVE','ALLOCATED','PICKING')
   or r.BASE_QTY is null or p_qty is null or p_qty<=0 or r.BASE_QTY<p_qty then raise_application_error(-20869,'RESERVATION_CONFLICT'); end if;
  select ARTICUL into v_art from RRL_PALLETS where UID_PALLET=p_target_uid;
  select WARE_ID into v_ware from RRL_CELLS where CELL=p_target_cell;
  if v_art!=r.ARTICUL then raise_application_error(-20869,'RESERVATION_ARTICLE_CONFLICT'); end if;
  -- Must accompany physical movement of the same q; source/destination P/H changed together.
  RRL_STOCK_BALANCE_CORE.apply_delta(r.UID_PALLET,r.CELL,-p_qty,-p_qty,r.BASE_UOM,p_uom_version);
  RRL_STOCK_BALANCE_CORE.apply_delta(p_target_uid,p_target_cell,p_qty,p_qty,r.BASE_UOM,p_uom_version);
  RRL_STOCK_CTX_API.begin_effect('RESERVATION',p_target_uid,p_target_cell,p_new_id);
  insert into RRL_STOCK_RESERVATION(RESERVATION_ID,RESERVATION_KIND,RESERVATION_SCOPE,RESERVATION_DOMAIN,
   SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_LINE_ID,TASK_ID,CUSTOMER_ID,CUSTOMER_ORDER_ID,PRODUCTION_ORDER_ID,
   PICK_PLAN_ID,PICK_PLAN_LINE_ID,PICK_WAVE_ID,PICK_WAVE_LINE_ID,ARTICUL,QTY,UNIT_CODE,WARE_ID,CELL,
   BATCH_ID,PROD_BATCH_ID,UID_PALLET,SSCC,STATUS,PRIORITY,CREATED_BY,BASE_QTY,BASE_UOM,RESERVATION_VERSION)
   values(p_new_id,'HARD',r.RESERVATION_SCOPE,r.RESERVATION_DOMAIN,r.SOURCE_DOC_TYPE,r.SOURCE_DOC_ID,
   r.SOURCE_LINE_ID,r.TASK_ID,r.CUSTOMER_ID,r.CUSTOMER_ORDER_ID,r.PRODUCTION_ORDER_ID,r.PICK_PLAN_ID,
   r.PICK_PLAN_LINE_ID,r.PICK_WAVE_ID,r.PICK_WAVE_LINE_ID,r.ARTICUL,p_qty,r.BASE_UOM,v_ware,p_target_cell,
   r.BATCH_ID,r.PROD_BATCH_ID,p_target_uid,null,r.STATUS,r.PRIORITY,p_actor,p_qty,r.BASE_UOM,0);
  RRL_STOCK_CTX_API.end_effect;
  decrease(r,p_qty,'CONSUMED',p_actor);
 end;
 procedure move_coverage(p_id number,p_new_id number,p_target_uid varchar2,p_target_cell varchar2,
  p_target_ware number,p_qty number,p_target_slot number,p_actor varchar2,p_result_id out number) is
  v_r RRL_STOCK_RESERVATION%rowtype;v_new RRL_STOCK_RESERVATION%rowtype;
 begin
  lock_identity(p_id);
  select * into v_r from RRL_STOCK_RESERVATION where RESERVATION_ID=p_id for update;
  if v_r.BASE_QTY is null or p_qty is null or p_qty<=0 or p_qty>v_r.BASE_QTY
   or v_r.RESERVATION_KIND is null or v_r.RESERVATION_KIND!='HARD'
   or v_r.STATUS is null or v_r.STATUS not in('ACTIVE','ALLOCATED','PICKING')
   or v_r.BASE_UOM is null then raise_application_error(-20869,'RESERVATION_COVERAGE_CONFLICT');end if;
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false) then
   raise_application_error(-20863,'STOCK_WRITE_FORBIDDEN');end if;
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',v_r.UID_PALLET));
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_target_uid));
  if p_target_slot is not null then
   RRL_STOCK_LOCK_API.assert_held(40,RRL_STOCK_LOCK_API.resource_key('SLOT',to_char(p_target_slot,'TM9')));
  end if;
  if p_qty=v_r.BASE_QTY then
   RRL_STOCK_CTX_API.begin_effect('RESERVATION',p_target_uid,p_target_cell,p_id);
   update RRL_STOCK_RESERVATION set UID_PALLET=p_target_uid,CELL=p_target_cell,WARE_ID=p_target_ware,
    CELL_SLOT_ID=p_target_slot,RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=p_id;
   RRL_STOCK_CTX_API.end_effect;
   p_result_id:=p_id;
  else
   lock_identity(p_new_id);v_new:=v_r;v_new.RESERVATION_ID:=p_new_id;
   v_new.UID_PALLET:=p_target_uid;v_new.CELL:=p_target_cell;v_new.WARE_ID:=p_target_ware;
   v_new.CELL_SLOT_ID:=p_target_slot;v_new.BASE_QTY:=p_qty;v_new.QTY:=p_qty;v_new.UNIT_CODE:=v_new.BASE_UOM;
   v_new.RESERVATION_VERSION:=0;v_new.CREATED_AT:=systimestamp;v_new.CREATED_BY:=p_actor;
   v_new.RELEASED_AT:=null;v_new.RELEASED_BY:=null;v_new.CONSUMED_AT:=null;v_new.CONSUMED_BY:=null;
   RRL_STOCK_CTX_API.begin_effect('RESERVATION',p_target_uid,p_target_cell,p_new_id);
   insert into RRL_STOCK_RESERVATION values v_new;
   RRL_STOCK_CTX_API.end_effect;
   RRL_STOCK_CTX_API.begin_effect('RESERVATION',v_r.UID_PALLET,v_r.CELL,p_id);
   update RRL_STOCK_RESERVATION set BASE_QTY=BASE_QTY-p_qty,QTY=BASE_QTY-p_qty,UNIT_CODE=BASE_UOM,
    RESERVATION_VERSION=RESERVATION_VERSION+1 where RESERVATION_ID=p_id;
   RRL_STOCK_CTX_API.end_effect;
   p_result_id:=p_new_id;
  end if;
 end;
 procedure restore_consumed(p_id number,p_new_id number,p_qty number,p_uom_version number,p_actor varchar2)is
  old_row RRL_STOCK_RESERVATION%rowtype;new_row RRL_STOCK_RESERVATION%rowtype;
  op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');n number;qty_text varchar2(60):=RRL_STOCK_PLAN_HELPER.decimal_text(p_qty);
 begin
  lock_identity(p_id);lock_identity(p_new_id);
  select *into old_row from RRL_STOCK_RESERVATION where RESERVATION_ID=p_id for update;
  if p_qty<=0 or old_row.STATUS!='CONSUMED'or old_row.BASE_QTY!=0 or old_row.RESERVATION_KIND!='HARD'or old_row.SOURCE_DOC_TYPE!='PICK_WAVE'then raise_application_error(-20869,'UNLOAD_CONSUMED_CASE_RESERVATION_REQUIRED');end if;
  select count(*)into n from RRL_STOCK_OPERATION operation
   join json_table(operation.RESOLVED_PLAN_JSON,'$.domain.legs[*]'columns(OLD_ID number path '$.reservation_id',NEW_ID number path '$.new_reservation',UID_TEXT varchar2(150)path '$.uid',QTY_TEXT varchar2(60)path '$.quantity'))leg
    on leg.OLD_ID=p_id and leg.NEW_ID=p_new_id and leg.UID_TEXT=old_row.UID_PALLET and leg.QTY_TEXT=qty_text
   where operation.OPERATION_ID=op and operation.COMMAND_TYPE='UNLOAD_SHIPMENT'and operation.STATE='IN_FLIGHT';
  if n!=1 then raise_application_error(-20863,'UNLOAD_RESERVED_RECOVERY_PLAN_REQUIRED');end if;
  RRL_STOCK_BALANCE_CORE.apply_delta(old_row.UID_PALLET,old_row.CELL,0,p_qty,old_row.BASE_UOM,p_uom_version);
  new_row:=old_row;new_row.RESERVATION_ID:=p_new_id;new_row.QTY:=p_qty;new_row.BASE_QTY:=p_qty;new_row.STATUS:='ACTIVE';new_row.RESERVATION_VERSION:=0;
  new_row.CREATED_AT:=systimestamp;new_row.CREATED_BY:=p_actor;new_row.CONSUMED_AT:=null;new_row.CONSUMED_BY:=null;
  new_row.RELEASED_AT:=null;new_row.RELEASED_BY:=null;new_row.RELEASE_REASON:=null;new_row.LOCK_OWNER:=null;new_row.LOCKED_AT:=null;new_row.LAST_ERROR:=null;
  RRL_STOCK_CTX_API.begin_effect('RESERVATION',old_row.UID_PALLET,old_row.CELL,p_new_id);
  insert into RRL_STOCK_RESERVATION values new_row;
  RRL_STOCK_CTX_API.end_effect;
 exception when others then RRL_STOCK_CTX_API.end_effect;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_RETURN_DISPOSE as
 procedure assert_scope(p_request varchar2,p_actor varchar2)is n number;
 begin
  select count(*)into n from RRL_RETURN_DISPOSAL_REQUEST q join RRL_STORE_RETURN_RECEIPT r on r.OPERATION_ID=q.RECEIPT_OPERATION_ID join RUSERS u on u.ID=p_actor
   where q.OPERATION_ID=p_request and q.ACTOR!=p_actor and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'store_return_approve')=1 and(u.WARE_ID=r.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'RETURN_DISPOSAL_CURRENT_INDEPENDENT_ACTOR_REQUIRED');end if;
 end;
 procedure describe(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');
 req RRL_RETURN_DISPOSAL_REQUEST%rowtype;rec RRL_STORE_RETURN_RECEIPT%rowtype;
 v_id varchar2(100):=m.get_string('request_operation_id');v_cell varchar2(60);v_qty number;v_h number;v_version number;v_uom varchar2(20);v_policy number;v_store varchar2(255);n number;actual number;total number;unit_wire clob;key_wire clob;profiles clob;leg json_object_t;legs json_array_t;scan_domain json_object_t;unit_count number;j json_object_t:=json_object_t();
 begin
 select *into req from RRL_RETURN_DISPOSAL_REQUEST where OPERATION_ID=v_id;
 select *into rec from RRL_STORE_RETURN_RECEIPT where OPERATION_ID=req.RECEIPT_OPERATION_ID;
 if rec.DISPOSITION!='DISPOSAL' then raise_application_error(-20886,'RETURN_DISPOSAL_APPROVED_DISPOSITION_REQUIRED');end if;
 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=rec.WARE_ID or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(ID,'store_return_approve')=1;
 if n!=1 or req.ACTOR=p_actor then raise_application_error(-20882,'RETURN_DISPOSAL_INDEPENDENT_BOUND_SC_REQUIRED');end if;
 if m.get_string('decision_reference')is null or length(m.get_string('decision_reference'))>60 then raise_application_error(-20886,'RETURN_DISPOSAL_DECISION_REQUIRED');end if;
 select count(*)into n from RRL_RETURN_DISPOSAL_FACT where RECEIPT_OPERATION_ID=rec.OPERATION_ID;if n!=0 then raise_application_error(-20886,'RETURN_DISPOSAL_ALREADY_POSTED');end if;
 select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION,BASE_UOM,CELL into v_qty,v_h,v_version,v_uom,v_cell from RRL_REMAINS where UID_POLETA=rec.UID_PALLET and REMAIN>0;
 if v_qty!=rec.BASE_QTY or v_h!=0 or v_uom!=rec.BASE_UOM or v_version!=m.get_number('expected_stock_version')or m.get_number('expected_stock_version')is null then raise_application_error(-20886,'RETURN_DISPOSAL_CURRENT_WHOLE_UNRESERVED_VERSION_REQUIRED');end if;
 if m.get_string('scan_pallet')is null or m.get_string('scan_pallet')!=rec.UID_PALLET or m.get_string('scan_cell')is null or m.get_string('scan_cell')!=v_cell then raise_application_error(-20886,'RETURN_DISPOSAL_SOURCE_SCANS_REQUIRED');end if;
 select count(*)into n from RRL_CELLS where CELL=v_cell and WARE_ID=rec.WARE_ID and BLOCKED_FOR_REMAINS=1 and BLOCKED_FOR_POPOLNENIE=1;if n!=1 then raise_application_error(-20886,'RETURN_DISPOSAL_SEGREGATED_SOURCE_REQUIRED');end if;
 select count(*)into n from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 and(CHILD_PALLET_UID=rec.UID_PALLET or PARENT_UID=rec.UID_PALLET);if n!=0 then raise_application_error(-20886,'RETURN_DISPOSAL_STANDALONE_SOURCE_REQUIRED');end if;
 select count(*)into n from dual where exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=rec.ARTICLE)or exists(select 1 from RRL_SKU_RECEIPT_POLICY where ARTICUL=rec.ARTICLE and MARKING_REQUIRED=1)or exists(select 1 from RRL_FINISHED_GOODS_SKU where ARTICUL=rec.ARTICLE and CRPT_REQUIRED=1);
 if n!=0 then
  select count(*),sum(case when SCAN_MODE='UNIT'and lengthb(SYSTEM_CODE)<=30 then 0 else 1 end),json_arrayagg(json_object('system_code'value SYSTEM_CODE,'profile_code'value PROFILE_CODE,'profile_version'value PROFILE_VERSION,'scan_mode'value SCAN_MODE)order by SYSTEM_CODE,PROFILE_CODE returning clob)
   into n,actual,profiles from RRL_SKU_RECEIPT_PROFILE where ARTICUL=rec.ARTICLE;
  if n<1 or n>50 or actual!=0 then raise_application_error(-20886,'RETURN_DISPOSAL_CURRENT_UNIT_PROFILES_REQUIRED');end if;
  select count(*),sum(u.BASE_QTY),json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION,'origin_uid'value u.UID_PALLET,'unit_id'value u.UNIT_ID)order by u.PHYSICAL_UNIT_KEY returning clob),json_arrayagg(u.PHYSICAL_UNIT_KEY order by u.PHYSICAL_UNIT_KEY returning clob)
   into n,total,unit_wire,key_wire from RRL_STORE_RETURN_UNIT b join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=b.PHYSICAL_UNIT_KEY
   where b.APPROVAL_OPERATION_ID=rec.APPROVAL_OPERATION_ID and u.CURRENT_UID=rec.UID_PALLET and u.CURRENT_CELL=v_cell and u.BASE_QTY=b.BASE_QTY and u.BASE_UOM=b.BASE_UOM and u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null;
  select count(*)into actual from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=rec.UID_PALLET and CURRENT_CELL=v_cell;
  if n<1 or n>10000 or actual!=n or total!=rec.BASE_QTY then raise_application_error(-20886,'RETURN_DISPOSAL_EXACT_ORIGINAL_APPROVED_UNITS_REQUIRED');end if;
  leg:=json_object_t();leg.put('uid',rec.UID_PALLET);leg.put('article',rec.ARTICLE);leg.put('cell',v_cell);leg.put('base_uom',v_uom);leg.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));legs:=json_array_t();legs.append(leg);scan_domain:=json_object_t();scan_domain.put('legs',legs);
  RRL_STOCK_QC_MARK.validate_scan(scan_domain.to_clob,m.to_clob,unit_count);
  if unit_count!=n then raise_application_error(-20886,'RETURN_DISPOSAL_EXACT_SCANNED_UNIT_COUNT_REQUIRED');end if;
  j.put('disposal_units',json_array_t.parse(unit_wire));j.put('disposal_unit_keys',json_array_t.parse(key_wire));j.put('disposal_profiles',json_array_t.parse(profiles));
 elsif m.has('unit_scans')and m.get_array('unit_scans').get_size>0 then raise_application_error(-20886,'RETURN_DISPOSAL_ORDINARY_UNEXPECTED_SCANS');end if;
 select max(POLICY_VERSION)into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=rec.ARTICLE and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=1 and DENOMINATOR=1;
 if v_policy is null then raise_application_error(-20886,'RETURN_DISPOSAL_BASE_UOM_REQUIRED');end if;
 select f.STORE_ADDR into v_store from RRL_STORE_RETURN_APPROVAL a join RRL_STORE_RECEIPT_FACT f on f.OPERATION_ID=a.RECEIPT_OPERATION_ID where a.OPERATION_ID=rec.APPROVAL_OPERATION_ID;
 if v_store is null then raise_application_error(-20886,'RETURN_DISPOSAL_ORIGINAL_LOSS_STORE_REQUIRED');end if;
 j.put('request_operation_id',req.OPERATION_ID);j.put('receipt_operation_id',rec.OPERATION_ID);j.put('uid',rec.UID_PALLET);j.put('article',rec.ARTICLE);j.put('cell',v_cell);j.put('warehouse_id',rec.WARE_ID);j.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));j.put('base_uom',v_uom);j.put('uom_version',v_policy);j.put('stock_version',v_version);j.put('loss_store_addr',v_store);j.put('document_reference',req.DOCUMENT_REFERENCE);j.put('document_sha256',req.DOCUMENT_SHA256);j.put('decision_reference',m.get_string('decision_reference'));
 p_domain:=j;
 exception when no_data_found then raise_application_error(-20886,'RETURN_DISPOSAL_SOURCE_REQUIRED');when too_many_rows then raise_application_error(-20886,'RETURN_DISPOSAL_ONE_SOURCE_REQUIRED');end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
 describe(p_request,d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
 RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RETURN_DISPOSAL_REQUEST',v.get_string('request_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_RECEIPT',v.get_string('receipt_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RETURN_DISPOSAL_FACT',p_operation);
 RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('uid'),v.get_string('article'),v.get_string('cell'),null);
 if v.has('disposal_profiles')then RRL_REGULATORY_API.declare_stock_events(p_operation,'MARKED_GOODS_DISPOSED',v.get_array('disposal_profiles').to_clob,r);end if;
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','SAP.OUTBOX:RETURN_DISPOSAL:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure validate_consume(p_receipt varchar2,p_uid varchar2,p_cell varchar2,p_quantity number,p_ware number,p_actor varchar2) is
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');kind_name varchar2(80);req clob;v json_object_t;
 begin
 select COMMAND_TYPE,CANONICAL_REQUEST into kind_name,req from RRL_STOCK_OPERATION where OPERATION_ID=op and STATE='IN_FLIGHT';
 if kind_name!='STORE_RETURN_DISPOSE' then raise_application_error(-20886,'RETURN_DISPOSAL_EXPLICIT_ROOT_REQUIRED');end if;
 describe(req,p_actor,v);
 if v.get_string('receipt_operation_id')!=p_receipt or v.get_string('uid')!=p_uid or v.get_string('cell')!=p_cell or v.get_number('warehouse_id')!=p_ware or RRL_STOCK_MATH.quantity(v.get_string('quantity'))!=p_quantity then raise_application_error(-20886,'RETURN_DISPOSAL_EXACT_SOURCE_REQUIRED');end if;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();payload json_object_t;body clob;
 v_req varchar2(100);v_receipt varchar2(100);v_uid varchar2(200);v_cell varchar2(60);v_unit varchar2(20);v_store varchar2(255);v_ref varchar2(255);v_qty number;v_ware number;v_policy number;v_event varchar2(100);keys clob;unit_wire clob;profile_wire clob;code_wire clob;gov json_object_t;gov_id number;gov_key varchar2(100);gov_ids json_array_t:=json_array_t();
 begin
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');describe(p_request,p_actor,fresh);
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: return disposal');end if;
 v_req:=v.get_string('request_operation_id');v_receipt:=v.get_string('receipt_operation_id');v_uid:=v.get_string('uid');v_cell:=v.get_string('cell');v_unit:=v.get_string('base_uom');v_store:=v.get_string('loss_store_addr');v_ref:=v.get_string('decision_reference');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));v_ware:=v.get_number('warehouse_id');v_policy:=v.get_number('uom_version');
 if v.has('disposal_unit_keys')then keys:=v.get_array('disposal_unit_keys').to_clob;end if;
 RRL_STOCK_EFFECT_CORE.consume(v_uid,v_cell,v_qty,v_unit,v_policy,v_ware,p_actor,1,p_units=>keys,p_disposal_receipt=>v_receipt);
 insert into RRL_RETURN_DISPOSAL_FACT(OPERATION_ID,REQUEST_OPERATION_ID,RECEIPT_OPERATION_ID,UID_PALLET,BASE_QTY,BASE_UOM,LOSS_STORE_ADDR,DECISION_REFERENCE,ACTOR)values(op,v_req,v_receipt,v_uid,v_qty,v_unit,v_store,v_ref,p_actor);
 j.put('operation_id',op);j.put('status','DISPOSED');j.put('receipt_operation_id',v_receipt);j.put('quantity',v.get_string('quantity'));j.put('base_uom',v_unit);j.put('pallet_identifier',v_uid);j.put('loss_store_addr',v_store);j.put('external_sap_ack',false);
 if v.has('disposal_profiles')then
  gov_ids:=json_array_t.parse(RRL_REGULATORY_API.enqueue_stock_events(op,'MARKED_GOODS_DISPOSED',v.to_clob,v.get_array('disposal_units').to_clob,v.get_array('disposal_profiles').to_clob));
  j.put('physical_unit_count',v.get_array('disposal_units').get_size);j.put('regulatory_event_ids',gov_ids);j.put('regulatory_status','PENDING');j.put('external_regulatory_ack',false);
 end if;
 payload:=json_object_t.parse(v.to_clob);payload.put('operation_id',op);payload.put('status','DISPOSED');payload.put('actor',p_actor);body:=payload.to_clob;v_event:='RETURN.DISPOSAL:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op,'AL32UTF8'),sys.dbms_crypto.hash_sh256));
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values(v_event,'STORE_RETURN_DISPOSED',body);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE PACKAGE BODY          "RRL_STOCK_RETURN_REUSE" as

 procedure describe_source(p_lot varchar2,p_article varchar2,p_unit varchar2,p_qty number,p_proof out json_object_t)is
  lot RRL_PALLETS%rowtype;n number;batch varchar2(100);base varchar2(20);num number;den number;scale number;version number;box number;
 begin
  select *into lot from RRL_PALLETS where UID_PALLET=p_lot;
  if lot.ARTICUL is null or lot.ARTICUL!=p_article or lot.EXPIRY_DATE is null or trunc(lot.EXPIRY_DATE)<trunc(sysdate)then raise_application_error(-20886,'RETURN_REUSE_SOURCE_EXPIRY_ARTICLE_REQUIRED');end if;
  select count(*),min(SUPPLIER_BATCH)into n,batch from RRL_SAP_PALLET_RECEIPT where UID_PALLET=nvl(lot.STOCK_ORIGIN_UID,lot.UID_PALLET);
  if n!=1 or batch is null then raise_application_error(-20886,'RETURN_REUSE_ORIGINAL_VERIFIED_BATCH_GOOD_BOX_REQUIRED');end if;
  select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE,POLICY_VERSION into base,num,den,scale,version from RRL_STOCK_UOM_CONVERSION
   where ARTICUL=p_article and INPUT_UOM='BOX'and POLICY_VERSION=(select max(POLICY_VERSION)from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM='BOX');
  box:=RRL_STOCK_MATH.convert_exact('1',num,den,scale);
  if base!=p_unit or box<=0 or mod(p_qty,box)!=0 then raise_application_error(-20886,'RETURN_REUSE_FULL_BOX_BASE_QUANTITY_CONFLICT');end if;
  p_proof:=json_object_t();p_proof.put('supplier_batch',batch);p_proof.put('origin_uid',nvl(lot.STOCK_ORIGIN_UID,lot.UID_PALLET));
  p_proof.put('expiry_date',to_char(lot.EXPIRY_DATE,'YYYY-MM-DD'));p_proof.put('uom_policy_version',version);
  p_proof.put('box_count',RRL_STOCK_PLAN_HELPER.decimal_text(p_qty/box));p_proof.put('box_base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(box));
  p_proof.put('physical_completeness_verified',false);
 exception when no_data_found then raise_application_error(-20886,'RETURN_REUSE_CURRENT_SOURCE_BOX_UOM_REQUIRED');
 end;

 procedure describe_boxes(p_approval RRL_STORE_RETURN_APPROVAL%rowtype,p_metadata json_object_t,p_scan_uom varchar2,p_batch_source varchar2,p_ware number,p_proof out json_object_t) is
 v_count number;v_num number;v_den number;v_scale number;v_version number;v_base varchar2(20);v_box number;v_quantity number;v_good boolean;v_min_days number;
 begin
 if p_approval.COMPLETE_GOOD_BOX!=1 or p_batch_source!='ORIGINAL_SAP_VERIFIED' then raise_application_error(-20886,'RETURN_REUSE_ORIGINAL_VERIFIED_BATCH_GOOD_BOX_REQUIRED');end if;
 v_good:=p_metadata.get_boolean('complete_good_boxes');
 if v_good is null or not v_good or p_scan_uom!='BOX' or not regexp_like(p_metadata.get_string('full_box_count'),'^[1-9][0-9]{0,17}$')then raise_application_error(-20886,'RETURN_REUSE_PHYSICAL_COMPLETE_BOX_BARCODE_COUNT_REQUIRED');end if;
 select nvl(max(MIN_SHELF_DAYS),0)into v_min_days from RRL_RECEIPT_SKU_RULE where ARTICUL=p_approval.ARTICLE and WARE_ID=p_ware;
 if to_date(p_metadata.get_string('expiry_date'),'FXYYYY-MM-DD')<trunc(sysdate)+v_min_days then raise_application_error(-20886,'RETURN_REUSE_SHELF_LIFE_REQUIRED');end if;
 v_count:=RRL_STOCK_MATH.quantity(p_metadata.get_string('full_box_count'));
 select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE,POLICY_VERSION into v_base,v_num,v_den,v_scale,v_version from RRL_STOCK_UOM_CONVERSION
 where ARTICUL=p_approval.ARTICLE and INPUT_UOM='BOX' and POLICY_VERSION=(select max(POLICY_VERSION)from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_approval.ARTICLE and INPUT_UOM='BOX');
 v_box:=RRL_STOCK_MATH.convert_exact('1',v_num,v_den,v_scale);v_quantity:=RRL_STOCK_MATH.convert_exact(p_metadata.get_string('full_box_count'),v_num,v_den,v_scale);
 if v_base!=p_approval.BASE_UOM or v_quantity!=p_approval.BASE_QTY then raise_application_error(-20886,'RETURN_REUSE_FULL_BOX_BASE_QUANTITY_CONFLICT');end if;
 p_proof:=json_object_t();p_proof.put('box_count',RRL_STOCK_PLAN_HELPER.decimal_text(v_count));p_proof.put('box_base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_box));p_proof.put('uom_policy_version',v_version);p_proof.put('barcode',p_metadata.get_string('scan_article'));p_proof.put('supplier_batch',p_metadata.get_string('supplier_batch'));
 exception when no_data_found then raise_application_error(-20886,'RETURN_REUSE_CURRENT_BOX_UOM_REQUIRED');end;
 procedure persist_boxes(p_operation varchar2,p_actor varchar2,p_proof json_object_t) is v_count number;v_box number;v_version number;v_code varchar2(128);v_batch varchar2(100);
 begin
 if p_proof is null then return;end if;
 v_count:=RRL_STOCK_MATH.quantity(p_proof.get_string('box_count'));v_box:=RRL_STOCK_MATH.quantity(p_proof.get_string('box_base_quantity'));v_version:=p_proof.get_number('uom_policy_version');v_code:=p_proof.get_string('barcode');v_batch:=p_proof.get_string('supplier_batch');
 insert into RRL_RETURN_REUSE_PROOF(OPERATION_ID,BOX_COUNT,BOX_BASE_QTY,UOM_POLICY_VERSION,ARTICLE_BARCODE,SOURCE_BATCH,ACTOR)values(p_operation,v_count,v_box,v_version,v_code,v_batch,p_actor);
 end;
 procedure assert_pick_target(p_receipt RRL_STORE_RETURN_RECEIPT%rowtype,p_target varchar2) is n number;v_min_days number;v_tmin number;v_tmax number;v_cell_min number;v_cell_max number;v_mix number;v_planned_count number:=0;v_key varchar2(1000);
 begin
 select count(*)into n from RRL_RETURN_REUSE_PROOF where OPERATION_ID=p_receipt.OPERATION_ID and BOX_COUNT*BOX_BASE_QTY=p_receipt.BASE_QTY and SOURCE_BATCH=p_receipt.OBSERVED_BATCH;
 if n!=1 or p_receipt.BATCH_SOURCE!='ORIGINAL_SAP_VERIFIED'then raise_application_error(-20886,'RETURN_REUSE_RECEIVED_FULL_BOX_PROOF_REQUIRED');end if;
 select count(*)into n from RRL_CELLS where CELL=p_target and WARE_ID=p_receipt.WARE_ID and OTBOR=1 and nvl(IS_SYSTEM,0)=0 and nvl(BLOCKED_FOR_ACCEPT,0)=0 and nvl(BLOCKED_FOR_REMAINS,0)=0 and nvl(BLOCKED_FOR_POPOLNENIE,0)=0;
 if n!=1 then raise_application_error(-20886,'RETURN_REUSE_CURRENT_PICKING_CELL_REQUIRED');end if;
 select nvl(max(MIN_SHELF_DAYS),0),max(TEMP_MIN),max(TEMP_MAX)into v_min_days,v_tmin,v_tmax from RRL_RECEIPT_SKU_RULE where WARE_ID=p_receipt.WARE_ID and ARTICUL=p_receipt.ARTICLE;
 if trunc(p_receipt.EXPIRY_DATE)<trunc(sysdate)+v_min_days then raise_application_error(-20886,'RETURN_REUSE_SHELF_LIFE_REQUIRED');end if;
 if v_tmin is not null or v_tmax is not null then
  select TEMP_MIN,TEMP_MAX into v_cell_min,v_cell_max from RRL_RECEIPT_CELL_RULE where WARE_ID=p_receipt.WARE_ID and CELL=p_target;
  if v_cell_min is null or v_cell_max is null or(v_tmin is not null and v_cell_min<v_tmin)or(v_tmax is not null and v_cell_max>v_tmax)then raise_application_error(-20886,'RETURN_REUSE_PICKING_TEMPERATURE_REQUIRED');end if;
 end if;
 select nvl(max(ALLOW_PICK_BATCH_MIX),0) into v_mix from RRL_RECEIPT_SKU_RULE where WARE_ID=p_receipt.WARE_ID and ARTICUL=p_receipt.ARTICLE;
 v_key:=RRL_STOCK_REPL_ADMISSION.lot_key(p_receipt.UID_PALLET);
 for planned in(select wt.UID_PALLET,pp.ARTICUL from RRL_WAREHOUSE_TASK wt join RRL_PALLETS pp on pp.UID_PALLET=wt.UID_PALLET
  where wt.TO_CELL=p_target and wt.STATUS not in('DONE','CANCELLED') and wt.UID_PALLET!=p_receipt.UID_PALLET)loop
  v_planned_count:=v_planned_count+1;if v_planned_count>200 then raise_application_error(-20881,'RETURN_REUSE_PLANNED_TARGET_BOUND_200');end if;
  if planned.ARTICUL!=p_receipt.ARTICLE or(v_mix!=1 and RRL_STOCK_REPL_ADMISSION.lot_key(planned.UID_PALLET)!=v_key)then raise_application_error(-20886,'RETURN_REUSE_PLANNED_TARGET_SKU_BATCH_CONFLICT');end if;
 end loop;
 RRL_STOCK_REPL_ADMISSION.assert_target(p_receipt.UID_PALLET,p_target,p_receipt.WARE_ID,p_receipt.ARTICLE);
 exception when no_data_found then raise_application_error(-20886,'RETURN_REUSE_PICKING_POLICY_REQUIRED');end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_REVISION_ENTRY as
 function count_row(p_article varchar2,p_cell varchar2,p_quantity number,p_unit varchar2,p_row number,p_actor varchar2,p_operation varchar2) return varchar2 is
  requested json_object_t:=json_object_t();d json_object_t;m json_object_t:=json_object_t();s json_object_t:=json_object_t();
  x json_object_t:=json_object_t();a json_array_t:=json_array_t();saved clob;wire clob;old_wire clob;result clob;
  doc number;article varchar2(160);v_cell varchar2(60);uid varchar2(200);other_uid varchar2(200);version number;quantity varchar2(30);
 begin
  if p_actor is null or p_operation is null or p_row is null or p_quantity is null or p_quantity<0 or trunc(p_quantity,9)!=p_quantity then
   raise_application_error(-20871,'INVENTORY_ROW_OPERATION_QUANTITY_REQUIRED');end if;
  quantity:=RRL_STOCK_PLAN_HELPER.decimal_text(p_quantity);
  requested.put('article',p_article);requested.put('cell',p_cell);requested.put('quantity',quantity);requested.put('unit',p_unit);requested.put('revision_row',p_row);
  begin select CANONICAL_REQUEST into saved from RRL_STOCK_OPERATION where OPERATION_ID=p_operation;
  exception when no_data_found then saved:=null;end;
  if saved is not null then
   d:=json_object_t.parse(saved);d.on_error(1);
   if d.get_string('actor')!=p_actor or d.get_string('command_type')!='INVENTORY_COUNT'
    or not d.get_object('metadata').has('requested_revision_row') then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   wire:=requested.to_clob;old_wire:=d.get_object('metadata').get_object('requested_revision_row').to_clob;
   if dbms_lob.compare(wire,old_wire)!=0 then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   RRL_STOCK_NATIVE_API.post(saved,p_actor,result);return 'ok';
  end if;
  select REVISION_ID,ARTICUL1,CELL into doc,article,v_cell from RRL_REVISION_ROW where ID=p_row;
  if doc is null or article is null or article!=p_article or v_cell is null or v_cell!=p_cell then
   raise_application_error(-20887,'INVENTORY_REVISION_ROW_IDENTITY_CONFLICT');end if;
  select min(r.UID_POLETA),max(r.UID_POLETA) into uid,other_uid from RRL_REMAINS r
   join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA where r.CELL=v_cell and p.ARTICUL=article and r.REMAIN>0;
  if uid is null or uid!=other_uid then raise_application_error(-20887,'LOT_SELECTION_REQUIRED: inventory-count.html');end if;
  select STOCK_VERSION into version from RRL_REMAINS where UID_POLETA=uid and CELL=v_cell;
  d:=json_object_t();d.put('contract_version',2);d.put('operation_id',p_operation);d.put('actor',p_actor);d.put('command_type','INVENTORY_COUNT');
  d.put('lines',json_array_t());d.put('units',json_array_t());s.put('revision_id',doc);d.put('source',s);
  m.put('reason','Measured revision row');m.put('revision_row_id',p_row);m.put('requested_revision_row',requested);
  x.put('uid',uid);x.put('article',article);x.put('cell',v_cell);x.put('unit',p_unit);x.put('quantity',quantity);
  x.put('expected_stock_version',version);x.put('unit_keys',json_array_t());a.append(x);m.put('counts',a);d.put('metadata',m);
  RRL_STOCK_NATIVE_API.post(d.to_clob,p_actor,result);return 'ok';
 end;
 function count_document(p_cell varchar2,p_document number,p_quantity number,p_unit varchar2,p_actor varchar2,p_operation varchar2) return varchar2 is
  saved clob;result clob;d json_object_t;r json_object_t;row_id number;other_row number;article varchar2(160);
 begin
  if p_operation is null or p_actor is null or p_quantity is null or p_quantity<0 then raise_application_error(-20871,'INVENTORY_OPERATION_QUANTITY_REQUIRED');end if;
  begin select CANONICAL_REQUEST into saved from RRL_STOCK_OPERATION where OPERATION_ID=p_operation;
  exception when no_data_found then saved:=null;end;
  if saved is not null then
   d:=json_object_t.parse(saved);d.on_error(1);
   if d.get_string('actor')!=p_actor or d.get_string('command_type')!='INVENTORY_COUNT'
    or d.get_object('source').get_number('revision_id')!=p_document
    or not d.get_object('metadata').has('requested_revision_row') then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   r:=d.get_object('metadata').get_object('requested_revision_row');
   if r.get_string('cell')!=p_cell or r.get_string('unit')!=p_unit
    or r.get_string('quantity')!=RRL_STOCK_PLAN_HELPER.decimal_text(p_quantity) then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   RRL_STOCK_NATIVE_API.post(saved,p_actor,result);return 'ok';
  end if;
  select min(ID),max(ID) into row_id,other_row from RRL_REVISION_ROW where CELL=p_cell and REVISION_ID=p_document;
  if row_id is null or row_id!=other_row then raise_application_error(-20887,'REVISION_ROW_SELECTION_REQUIRED: inventory-count.html');end if;
  select ARTICUL1 into article from RRL_REVISION_ROW where ID=row_id;
  return count_row(article,p_cell,p_quantity,p_unit,row_id,p_actor,p_operation);
 end;
 function birth_legacy(p_facts clob,p_actor varchar2,p_operation varchar2) return varchar2 is
  requested json_object_t:=json_object_t.parse(p_facts);d json_object_t;m json_object_t;s json_object_t:=json_object_t();
  saved clob;result clob;old_wire clob;wire clob;doc number;other_doc number;naklad number;uid varchar2(200);
 begin
  if p_actor is null or p_operation is null then raise_application_error(-20871,'INVENTORY_OPERATION_ACTOR_REQUIRED');end if;
  begin select CANONICAL_REQUEST into saved from RRL_STOCK_OPERATION where OPERATION_ID=p_operation;
  exception when no_data_found then saved:=null;end;
  if saved is not null then
   d:=json_object_t.parse(saved);d.on_error(1);
   if d.get_string('actor')!=p_actor or d.get_string('command_type')!='INVENTORY_REGISTER_LOT'
    or not d.get_object('metadata').has('legacy_facts') then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   wire:=requested.to_clob;old_wire:=d.get_object('metadata').get_object('legacy_facts').to_clob;
   if dbms_lob.compare(wire,old_wire)!=0 then raise_application_error(-20872,'OPERATION_CONFLICT');end if;
   RRL_STOCK_NATIVE_API.post(saved,p_actor,result);return d.get_object('metadata').get_string('uid');
  end if;
  naklad:=requested.get_number('receipt_document_id');
  select min(ID),max(ID) into doc,other_doc from RRL_REVIZION where REV_NAKLAD_ID=naklad;
  if doc is null or doc!=other_doc then raise_application_error(-20887,'INVENTORY_REVISION_DOCUMENT_AMBIGUOUS');end if;
  if requested.get_number('pallet_number') is null or requested.get_number('pallet_number')<1
   or requested.get_number('pallet_number')!=trunc(requested.get_number('pallet_number')) then raise_application_error(-20871,'INVENTORY_PALLET_NUMBER_REQUIRED');end if;
  uid:='P_'||requested.get_string('article')||'_G3_'||requested.get_string('cell')||'_'||RRL_STOCK_PLAN_HELPER.decimal_text(requested.get_number('pallet_number'));
  d:=json_object_t();d.put('contract_version',2);d.put('operation_id',p_operation);d.put('actor',p_actor);d.put('command_type','INVENTORY_REGISTER_LOT');
  d.put('lines',json_array_t());d.put('units',json_array_t());s.put('revision_id',doc);d.put('source',s);
  m:=json_object_t();m.put('reason','Measured inventory pallet');m.put('uid',uid);m.put('article',requested.get_string('article'));
  m.put('cell',requested.get_string('cell'));m.put('quantity',requested.get_string('quantity'));m.put('expiry_date',requested.get_string('expiry_date'));
  m.put('price',1);m.put('legacy_facts',requested);d.put('metadata',m);
  RRL_STOCK_NATIVE_API.post(d.to_clob,p_actor,result);return uid;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_SETTING_API as
 procedure set_compatibility(p_value varchar2,p_reason varchar2,p_actor varchar2) is
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();oldvalue varchar2(100);ver number;state varchar2(20);
 begin
  if dbms_transaction.local_transaction_id(false) is not null then raise_application_error(-20862,'SETTING_REQUIRES_CLEAN_TRANSACTION');end if;
  if p_value is null or p_value not in('0','1') or trim(p_reason) is null or length(p_reason)>1000 or p_actor is null
   or RRL_HAS_WRIGHT(p_actor,'stock_compatibility_admin')!=1 then raise_application_error(-20882,'COMPATIBILITY_SETTING_FORBIDDEN');end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK',6);RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE',6);
  RRL_STOCK_LOCK_API.begin_plan;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(r.to_clob);
  select STATE into state from RRL_STOCK_RELEASE where RELEASE_ID=1 for update;
  if state not in('PREPARED','ACTIVE') then raise_application_error(-20860,'SETTING_RELEASE_CLOSED');end if;
  RRL_STOCK_CTX_API.open_configuration(p_actor,'stock_compatibility_admin');
  select SETTING_VALUE into oldvalue from RRL_SYSTEM_SETTINGS where SETTING_KEY='STOCK_LEGACY_TRIGGER_ENABLED' for update;
  select nvl(max(SETTING_VERSION),0)+1 into ver from RRL_STOCK_SETTING_AUDIT where SETTING_KEY='STOCK_LEGACY_TRIGGER_ENABLED';
  update RRL_SYSTEM_SETTINGS set SETTING_VALUE=p_value,UPDATED_AT=sysdate,UPDATED_BY=p_actor where SETTING_KEY='STOCK_LEGACY_TRIGGER_ENABLED';
  insert into RRL_STOCK_SETTING_AUDIT(SETTING_KEY,SETTING_VERSION,OLD_VALUE,NEW_VALUE,REASON,CHANGED_BY)
   values('STOCK_LEGACY_TRIGGER_ENABLED',ver,oldvalue,p_value,p_reason,p_actor);
  commit;RRL_STOCK_CTX_API.clear_operation;RRL_STOCK_LOCK_API.clear_plan;
 exception when others then rollback;RRL_STOCK_CTX_API.clear_operation;RRL_STOCK_LOCK_API.clear_plan;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_SHIPPING_CORE as
 function rows_json(p_kind varchar2,p_id number,p_uid varchar2) return clob is a json_array_t:=json_array_t();v json_object_t;
 begin
  for l in(
   select ID,ARTICUL,COUNT1 QTY,cast(null as varchar2(20)) INPUT_UOM from RRL_OTHOD_NAKLAD_ROWS where p_kind='SHIP_DOCUMENT' and ID_NAKLAD=p_id
   union all select ID,ARTICUL,QUANTITY,EI from RRL_SBORKA_PALLET_ROWS where p_kind='SHIP_PALLET' and PALLET_UID=p_uid
   order by ID
  ) loop
   v:=json_object_t();v.put('id',l.ID);v.put('article',l.ARTICUL);v.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(l.QTY));v.put('input_uom',l.INPUT_UOM);a.append(v);
  end loop;
  return a.to_clob;
 end;
 procedure compile_shipment(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob,p_skip_qc boolean default false) is
  d json_object_t:=json_object_t.parse(p_request);s json_object_t;v json_object_t:=json_object_t();leg json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;legs json_array_t:=json_array_t();
  l json_object_t;v_kind varchar2(80);v_id number;v_uid varchar2(200);v_ware number;v_cell varchar2(60);v_return_supplier varchar2(255);
  v_article varchar2(160);v_qty number;v_take number;v_base varchar2(20);v_version number;v_row_json clob;v_available number;v_customer_order number;v_order_count number;v_num number;v_den number;v_scale number;v_input varchar2(20);
  v_customer_status varchar2(30);v_closed_fulfillment number;
  v_supplier_source json_object_t;v_interware_source json_object_t;v_bound_uid varchar2(150);v_bound_version number;v_bound_count number;v_bound_pick number;v_bound_wh number;v_bound_physical number;v_bound_selected number;v_current_bound_version number;
  v_case_task number;v_case_version number;v_case_cell varchar2(60);v_case_status varchar2(40);v_carrier clob;v_carrier_rows json_array_t;v_carrier_row json_object_t;
  type quantity_map is table of number index by varchar2(2000);used quantity_map;reserved_used quantity_map;k varchar2(2000);sk varchar2(2000);
 begin
  s:=d.get_object('source');v_kind:=d.get_string('command_type');v_id:=s.get_number('document_id');v_uid:=s.get_string('pallet_identifier');
  if v_kind='SHIP_DOCUMENT' then select WARE_ID into v_ware from RRL_OTHOD_NAKLAD where ID=v_id;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_OTHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));
  elsif v_kind='SHIP_PALLET' then select ID,WARE_ID,RETURN_SUPPLIER_ID into v_id,v_ware,v_return_supplier from RRL_SBORKA_PALLETS where PALLET_UID=v_uid;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));
  else raise_application_error(-20871,'SHIPPING_SOURCE_TYPE_INVALID');end if;
  if v_kind='SHIP_PALLET' then
   select count(distinct CUSTOMER_ORDER_ID),min(CUSTOMER_ORDER_ID) into v_order_count,v_customer_order from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=v_id and PALLET_UID=v_uid;
   if v_order_count>1 then raise_application_error(-20887,'SHIPMENT_CUSTOMER_ORDER_AMBIGUOUS');end if;
   if v_return_supplier is not null and v_customer_order is not null then raise_application_error(-20887,'SUPPLIER_RETURN_CUSTOMER_SOURCE_CONFLICT');end if;
   if v_customer_order is not null then
    select STATUS into v_customer_status from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=v_customer_order;
    select count(*) into v_closed_fulfillment from RRL_CUSTOMER_ORDER_FULFILLMENT
     where LEGACY_SBORKA_PALLET_ID=v_id and PALLET_UID=v_uid and STATUS in('CANCELLED','SHIPPED');
    if v_customer_status='CANCELLED' or v_closed_fulfillment>0 then raise_application_error(-20886,'SHIPMENT_CUSTOMER_FULFILLMENT_CLOSED');end if;
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(v_customer_order));
    for ff in(select FULFILLMENT_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=v_id and PALLET_UID=v_uid order by FULFILLMENT_ID) loop
     RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(ff.FULFILLMENT_ID));
    end loop;
   end if;
  end if;
  if v_ware is null then raise_application_error(-20886,'SHIPPING_WAREHOUSE_REQUIRED');end if;
  if v_kind='SHIP_PALLET' then
   begin
    select CASE_PICK_TASK_ID,CONTENT_VERSION,CURRENT_CELL,STATUS into v_case_task,v_case_version,v_case_cell,v_case_status
     from RRL_CASE_PICK_TASK where LEGACY_SBORKA_PALLET_ID=v_id;
   exception when no_data_found then v_case_task:=null;end;
   if v_case_task is not null then
    if v_customer_order is null or v_case_status not in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP')
     or v_case_cell is null then raise_application_error(-20886,'CASE_SHIPMENT_CARRIER_STATE_REQUIRED');end if;
    RRL_STOCK_HU_PLACEMENT_CORE.declare_existing_case(r,v_case_task);
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_case_task));
    RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU','CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_case_task));
    v_carrier:=RRL_STOCK_CASE_PICK_CMD.carrier_rows(v_case_task);v_carrier_rows:=json_array_t.parse(v_carrier);
    if v_carrier_rows.get_size=0 then raise_application_error(-20886,'CASE_SHIPMENT_EMPTY_CARRIER');end if;
    for z in 0..v_carrier_rows.get_size-1 loop
     v_carrier_row:=treat(v_carrier_rows.get(z) as json_object_t);
     if v_carrier_row.get_string('cell')!=v_case_cell then raise_application_error(-20887,'CASE_SHIPMENT_CARRIER_LOCATION_CONFLICT');end if;
     RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v_carrier_row.get_string('uid'),v_carrier_row.get_string('article'),v_case_cell,null);
    end loop;
   end if;
  end if;
  if v_kind='SHIP_PALLET' then
   v_interware_source:=RRL_STOCK_INTERWARE_NEXT.describe_source(v_id,v_ware);
   if v_interware_source is not null then
    if v_customer_order is not null or v_return_supplier is not null then raise_application_error(-20886,'INTERWARE_ONWARD_NO_DUPLICATE_CUSTOMER_FULFILLMENT');end if;
    v_bound_uid:=v_interware_source.get_string('uid');v_bound_version:=v_interware_source.get_number('stock_version');RRL_STOCK_INTERWARE_NEXT.declare_source(v_interware_source,p_operation,r);
   end if;
  end if;
  if v_return_supplier is not null then
   v_supplier_source:=RRL_STOCK_SUP_RETURN.describe_source(v_id,v_return_supplier,v_ware);
   if v_supplier_source is not null then v_bound_uid:=v_supplier_source.get_string('uid');v_bound_version:=v_supplier_source.get_number('stock_version');RRL_STOCK_SUP_RETURN.declare_source(v_supplier_source,p_operation,r);end if;
  end if;
  if v_customer_order is not null and v_case_task is null then
   select count(*),max(PICKED_PALLET_UID),max(PICKED_STOCK_VERSION),max(PICKED_WAREHOUSE_TASK_ID) into v_bound_count,v_bound_uid,v_bound_version,v_bound_wh
    from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=v_id and PALLET_UID=v_uid
     and CUSTOMER_ORDER_ID=v_customer_order and STATUS='PICKED' and PICKED_WAREHOUSE_TASK_ID is not null;
   if v_bound_count!=1 or v_bound_uid is null or v_bound_version is null then raise_application_error(-20886,'FULLPAL_PHYSICAL_SHIPMENT_BIND_REQUIRED');end if;
   select wt.PICK_TASK_ID into v_bound_pick from RRL_WAREHOUSE_TASK wh join RRL_PICK_WAVE_TASK wt
    on wt.PICK_WAVE_TASK_ID=wh.SOURCE_TASK_ID and wt.PICK_WAVE_ID=wh.SOURCE_DOC_ID
    where wh.TASK_ID=v_bound_wh and wh.TASK_SOURCE='WAVE' and wh.TASK_TYPE='PICKING_MOVE' and wh.STATUS='DONE';
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_bound_wh));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_bound_pick));
  end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  v_row_json:=rows_json(v_kind,v_id,v_uid);a:=json_array_t.parse(v_row_json);
  if a.get_size<1 or a.get_size>200 then raise_application_error(-20881,'SHIPPING_DOCUMENT_LINE_BOUND');end if;
  for i in 0..a.get_size-1 loop
   l:=treat(a.get(i) as json_object_t);v_article:=l.get_string('article');v_qty:=RRL_STOCK_MATH.quantity(l.get_string('quantity'));
   RRL_STOCK_PLAN_HELPER.row_key(r,case when v_kind='SHIP_DOCUMENT' then 'RRL_OTHOD_NAKLAD_ROWS' else 'RRL_SBORKA_PALLET_ROWS' end,RRL_STOCK_PLAN_HELPER.decimal_text(l.get_number('id')));
   RRL_STOCK_PLAN_HELPER.fence(f,'SKU',v_article);
   if v_customer_order is not null then
    v_input:=l.get_string('input_uom');
    select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_input;
    select BASE_UOM,NUMERATOR,DENOMINATOR,BASE_SCALE into v_base,v_num,v_den,v_scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=v_input and POLICY_VERSION=v_version;
    v_qty:=RRL_STOCK_MATH.convert_exact(l.get_string('quantity'),v_num,v_den,v_scale);
    for c in(select sr.RESERVATION_ID,sr.SOURCE_LINE_ID,sr.SOURCE_DOC_TYPE,sr.SOURCE_DOC_ID,sr.RESERVATION_VERSION,sr.BASE_QTY,sr.BASE_UOM,rr.UID_POLETA,rr.CELL,rr.REMAIN
     from RRL_STOCK_RESERVATION sr join RRL_REMAINS rr on rr.UID_POLETA=sr.UID_PALLET and rr.CELL=sr.CELL
     join RRL_PALLETS pp on pp.UID_PALLET=sr.UID_PALLET join RRL_CELLS cc on cc.CELL=sr.CELL
     left join RRL_PROD_BATCH_READY_V br on br.PROD_BATCH_ID=pp.PROD_BATCH_ID
     where sr.CUSTOMER_ORDER_ID=v_customer_order and sr.ARTICUL=v_article and sr.RESERVATION_KIND='HARD'
      and sr.RESERVATION_DOMAIN='PICKING' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING') and sr.BASE_QTY>0
      and sr.BASE_UOM=v_base and cc.WARE_ID=v_ware
      and (v_bound_uid is null or (sr.UID_PALLET=v_bound_uid and sr.SOURCE_LINE_ID=v_bound_pick)) and nvl(cc.BLOCKED_FOR_REMAINS,0)=0 and nvl(cc.BLOCKED_FOR_POPOLNENIE,0)=0
      and nvl(br.IS_SHIPMENT_ALLOWED,1)=1
      and ((v_case_task is null and not exists(select 1 from RRL_CASE_CARRIER_LOT h where h.LOT_UID=sr.UID_PALLET))
       or (v_case_task is not null and sr.CELL=v_case_cell and exists(select 1 from RRL_CASE_CARRIER_LOT h where h.LOT_UID=sr.UID_PALLET and h.CASE_PICK_TASK_ID=v_case_task)))
      and exists(select 1 from RRL_PICK_TASK pt where pt.PICK_TASK_ID=sr.SOURCE_LINE_ID and pt.CUSTOMER_ORDER_ID=v_customer_order and pt.ARTICUL=v_article and pt.STATUS='DONE')
     order by pp.EXPIRY_DATE nulls last,sr.RESERVATION_ID) loop
     exit when v_qty=0;
     sk:=RRL_STOCK_PLAN_HELPER.decimal_text(c.RESERVATION_ID);if not reserved_used.exists(sk) then reserved_used(sk):=0;end if;
     k:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',c.UID_POLETA,c.CELL));if not used.exists(k) then used(k):=0;end if;
     v_available:=c.BASE_QTY-reserved_used(sk);
     if v_available>0 then
      v_take:=least(v_qty,v_available);
      select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=c.BASE_UOM and BASE_UOM=c.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
      if v_version is null then raise_application_error(-20868,'SHIPPING_BASE_POLICY_REQUIRED');end if;
      RRL_STOCK_PLAN_HELPER.row_key(r,case when c.SOURCE_DOC_TYPE='PICK_WAVE' then 'RRL_PICK_WAVE' else 'RRL_PICK_PLAN' end,RRL_STOCK_PLAN_HELPER.decimal_text(c.SOURCE_DOC_ID));
      RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(c.SOURCE_LINE_ID));
      for pr in(select PICK_RESERVATION_ID from RRL_PICK_RESERVATION where PICK_TASK_ID=c.SOURCE_LINE_ID order by PICK_RESERVATION_ID) loop
       RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(pr.PICK_RESERVATION_ID));
      end loop;
      for wr in(select PICK_WAVE_RESERVATION_ID from RRL_PICK_WAVE_RESERVATION where PICK_TASK_ID=c.SOURCE_LINE_ID order by PICK_WAVE_RESERVATION_ID) loop
       RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(wr.PICK_WAVE_RESERVATION_ID));
      end loop;
      RRL_STOCK_PLAN_HELPER.stock_closure(f,r,c.UID_POLETA,v_article,c.CELL,null);
      leg:=json_object_t();leg.put('row_id',l.get_number('id'));leg.put('uid',c.UID_POLETA);leg.put('cell',c.CELL);leg.put('article',v_article);
      leg.put('source_p',RRL_STOCK_PLAN_HELPER.decimal_text(c.REMAIN-used(k)));leg.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_take));
      leg.put('base_uom',c.BASE_UOM);leg.put('uom_version',v_version);leg.put('reservation_id',c.RESERVATION_ID);leg.put('owner_type',c.SOURCE_DOC_TYPE);leg.put('owner_id',c.SOURCE_DOC_ID);
      leg.put('pick_task_id',c.SOURCE_LINE_ID);leg.put('reservation_version',c.RESERVATION_VERSION);legs.append(leg);used(k):=used(k)+v_take;reserved_used(sk):=reserved_used(sk)+v_take;v_qty:=v_qty-v_take;
      if legs.get_size>200 then raise_application_error(-20881,'SHIPPING_ALLOCATION_BOUND');end if;
     end if;
    end loop;
    if v_qty>0 then raise_application_error(-20868,'SHIPMENT_OWN_PICKED_RESERVATION_INSUFFICIENT');end if;
   else
   if v_interware_source is not null then
    v_base:=v_interware_source.get_string('base_uom');
    if nvl(l.get_string('input_uom'),'~')!=v_base or a.get_size!=1 or v_article!=v_interware_source.get_string('article')or v_qty!=RRL_STOCK_MATH.quantity(v_interware_source.get_string('quantity'))then raise_application_error(-20886,'INTERWARE_ONWARD_EXISTING_ST_EXACT_BASE_COMPOSITION_REQUIRED');end if;
    v_cell:=v_interware_source.get_string('cell');v_version:=v_interware_source.get_number('uom_version');
    RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v_bound_uid,v_article,v_cell,null);
    leg:=json_object_t();leg.put('row_id',l.get_number('id'));leg.put('uid',v_bound_uid);leg.put('cell',v_cell);leg.put('article',v_article);leg.put('source_p',v_interware_source.get_string('quantity'));leg.put('quantity',v_interware_source.get_string('quantity'));leg.put('base_uom',v_base);leg.put('uom_version',v_version);legs.append(leg);v_qty:=0;
   elsif v_supplier_source is not null then
    v_base:=v_supplier_source.get_string('base_uom');
    if nvl(l.get_string('input_uom'),'~')!=v_base then raise_application_error(-20886,'SUP_RETURN_ST_ORIGINAL_BASE_UOM_REQUIRED');end if;
    if a.get_size!=1 or v_article!=v_supplier_source.get_string('article')or v_base!=v_supplier_source.get_string('base_uom')or v_qty!=RRL_STOCK_MATH.quantity(v_supplier_source.get_string('quantity'))then raise_application_error(-20886,'SUP_RETURN_EXISTING_ST_WHOLE_SOURCE_COMPOSITION_REQUIRED');end if;
    v_cell:=v_supplier_source.get_string('cell');v_version:=v_supplier_source.get_number('uom_version');
    RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v_bound_uid,v_article,v_cell,null);
    leg:=json_object_t();leg.put('row_id',l.get_number('id'));leg.put('uid',v_bound_uid);leg.put('cell',v_cell);leg.put('article',v_article);leg.put('source_p',v_supplier_source.get_string('quantity'));leg.put('quantity',v_supplier_source.get_string('quantity'));leg.put('base_uom',v_base);leg.put('uom_version',v_version);legs.append(leg);v_qty:=0;
   else
   if v_return_supplier is not null then
    v_cell:='RETURNS';
    RRL_STOCK_PLAN_HELPER.fence(f,'CELL',v_cell);
    declare v_return_ware number;begin
     select WARE_ID into v_return_ware from RRL_CELLS where CELL=v_cell;
     if v_return_ware is null or v_return_ware!=v_ware then raise_application_error(-20886,'SUPPLIER_RETURN_LOCATION_REQUIRED');end if;
    exception when no_data_found then raise_application_error(-20886,'SUPPLIER_RETURN_LOCATION_REQUIRED');end;
   else select CELL into v_cell from RRL_ARTICULS where ACTICUL=v_article;end if;
   -- Plan only matching article, warehouse and eligible physical cells. No fabricated excess stock.
   for c in(select rr.UID_POLETA,rr.CELL,rr.REMAIN,rr.HARD_RESERVED_BASE,rr.STOCK_VERSION,rr.BASE_UOM,pp.EXPIRY_DATE
    from RRL_REMAINS rr join RRL_PALLETS pp on pp.UID_PALLET=rr.UID_POLETA
    join RRL_CELLS cc on cc.CELL=rr.CELL
    where pp.ARTICUL=v_article and rr.CELL=v_cell and rr.REMAIN>rr.HARD_RESERVED_BASE and cc.WARE_ID=v_ware
     and not exists(select 1 from RRL_CASE_CARRIER_LOT h where h.LOT_UID=rr.UID_POLETA)
     and nvl(cc.BLOCKED_FOR_REMAINS,0)=0 and nvl(cc.BLOCKED_FOR_POPOLNENIE,0)=0
    order by pp.EXPIRY_DATE nulls last,pp.CREATION_DATE nulls last,rr.UID_POLETA
   ) loop
    exit when v_qty=0;
    k:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',c.UID_POLETA,c.CELL));
    if not used.exists(k) then used(k):=0;end if;
    v_available:=c.REMAIN-c.HARD_RESERVED_BASE-used(k);
    if v_available>0 then
     v_take:=least(v_qty,v_available);
     select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=c.BASE_UOM and BASE_UOM=c.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
     if v_version is null then raise_application_error(-20868,'SHIPPING_BASE_POLICY_REQUIRED');end if;
     RRL_STOCK_PLAN_HELPER.stock_closure(f,r,c.UID_POLETA,v_article,c.CELL,null);
     leg:=json_object_t();leg.put('row_id',l.get_number('id'));leg.put('uid',c.UID_POLETA);leg.put('cell',c.CELL);leg.put('article',v_article);
     leg.put('source_p',RRL_STOCK_PLAN_HELPER.decimal_text(c.REMAIN-used(k)));leg.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_take));
     leg.put('base_uom',c.BASE_UOM);leg.put('uom_version',v_version);
     legs.append(leg);used(k):=used(k)+v_take;v_qty:=v_qty-v_take;
     if legs.get_size>200 then raise_application_error(-20881,'SHIPPING_ALLOCATION_BOUND');end if;
    end if;
   end loop;
   if v_qty>0 then raise_application_error(-20868,'SHIPMENT_AVAILABLE_STOCK_INSUFFICIENT');end if;
   end if;
   end if;
  end loop;
  if v_bound_uid is not null then
   select count(*),nvl(sum(REMAIN),0),max(STOCK_VERSION) into v_bound_count,v_bound_physical,v_current_bound_version from RRL_REMAINS
    where UID_POLETA=v_bound_uid and REMAIN>0;
   if v_bound_count!=1 then raise_application_error(-20886,'FULLPAL_SINGLE_PHYSICAL_LOCATION_REQUIRED');end if;
   v_bound_selected:=0;
   for z in 0..legs.get_size-1 loop
    v_carrier_row:=treat(legs.get(z) as json_object_t);
    v_bound_selected:=v_bound_selected+RRL_STOCK_MATH.quantity(v_carrier_row.get_string('quantity'));
   end loop;
   if v_bound_physical<=0 or v_bound_selected!=v_bound_physical then raise_application_error(-20886,'FULLPAL_BOUND_WHOLE_COMPOSITION_REQUIRED');end if;
  end if;
  if v_case_task is not null then
   for z in 0..v_carrier_rows.get_size-1 loop
    v_carrier_row:=treat(v_carrier_rows.get(z) as json_object_t);
    k:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',v_carrier_row.get_string('uid'),v_carrier_row.get_string('cell')));
    if not used.exists(k) then raise_application_error(-20886,'CASE_SHIPMENT_CONTENT_MISMATCH');end if;
    if used(k)!=RRL_STOCK_MATH.quantity(v_carrier_row.get_string('quantity')) then raise_application_error(-20886,'CASE_SHIPMENT_CONTENT_MISMATCH');end if;
   end loop;
  end if;
  if v_interware_source is not null then v.put('interwarehouse_onward_source',v_interware_source);end if;
  if v_supplier_source is not null then v.put('supplier_return_source',v_supplier_source);end if;
  v.put('bound_physical_uid',v_bound_uid);v.put('bound_stock_version',v_bound_version);v.put('bound_current_stock_version',v_current_bound_version);
  v.put('case_cell',v_case_cell);v.put('case_task',v_case_task);v.put('case_version',v_case_version);v.put('case_carrier',v_carrier_rows);
  v.put('return_supplier_id',v_return_supplier);v.put('customer_order_id',v_customer_order);v.put('document_id',v_id);v.put('pallet_identifier',v_uid);v.put('warehouse',v_ware);
  v.put('rows_signature',rawtohex(sys.dbms_crypto.hash(v_row_json,sys.dbms_crypto.hash_sh256)));v.put('legs',legs);
  if v_kind='SHIP_PALLET' and not p_skip_qc then RRL_STOCK_QC_GATE.assert_approved(v.to_clob);end if;
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_resolved(p_request clob,p_domain clob,p_offset number,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;l json_object_t;j json_object_t:=json_object_t();
  a json_array_t;facts json_array_t:=json_array_t();v_plan clob;v_condition number;v_id number;v_uid varchar2(200);
  v_row_json clob;v_p number;v_article varchar2(160);v_units clob;v_row_id number;v_qty number;v_kind varchar2(80);v_ready number;v_pick_task number;v_remaining number;v_return_supplier varchar2(255);sr RRL_STOCK_RESERVATION%rowtype;v_root_kind varchar2(80);
 begin
  if RRL_HAS_WRIGHT(p_actor,'CLOSE_OTHOD_NAKLAD')!=1 and RRL_HAS_WRIGHT(p_actor,'stock_posting_shipping')!=1 then raise_application_error(-20882,'SHIPPING_FORBIDDEN');end if;
  v_kind:=d.get_string('command_type');
  declare op varchar2(100):=d.get_string('operation_id');begin select COMMAND_TYPE into v_root_kind from RRL_STOCK_OPERATION where OPERATION_ID=op;end;
  if p_offset is null or p_offset<0 or p_offset!=trunc(p_offset) then raise_application_error(-20871,'SHIPMENT_LINE_OFFSET_INVALID');end if;
  v:=json_object_t.parse(p_domain);v_id:=v.get_number('document_id');v_uid:=v.get_string('pallet_identifier');
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=d.get_string('operation_id') then raise_application_error(-20863,'SHIPMENT_ROOT_REQUIRED');end if;
  if v_root_kind!='HU_SHIP' and RRL_STOCK_QC_CASE.nested(p_domain)=1 then raise_application_error(-20886,'SHIPMENT_WHOLE_HU_REQUIRED');end if;
  if v_kind='SHIP_PALLET' then RRL_STOCK_QC_GATE.assert_approved(p_domain);
   RRL_QC_SCOPE_READ.record_exemption(p_domain,RRL_STOCK_QC_GATE.signature_for_plan(p_domain));end if;
  if v_kind='SHIP_DOCUMENT' then select CONDITION into v_condition from RRL_OTHOD_NAKLAD where ID=v_id for update;
  else select CONDITION,RETURN_SUPPLIER_ID into v_condition,v_return_supplier from RRL_SBORKA_PALLETS where ID=v_id for update;
   if nvl(v_return_supplier,chr(1))!=nvl(v.get_string('return_supplier_id'),chr(1)) then raise_application_error(-20890,'CLOSURE_CHANGED: supplier return');end if;end if;
  if nvl(v_condition,0)>=2 then raise_application_error(-20886,'SHIPMENT_ALREADY_CLOSED_WITH_OTHER_OPERATION');end if;
  v_row_json:=rows_json(v_kind,v_id,v_uid);
  if rawtohex(sys.dbms_crypto.hash(v_row_json,sys.dbms_crypto.hash_sh256))!=v.get_string('rows_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: shipment rows');end if;
  -- Lock actual document rows before stock DML, consistently with the planned domain.
  if v_kind='SHIP_DOCUMENT' then
   for z in(select ID from RRL_OTHOD_NAKLAD_ROWS where ID_NAKLAD=v_id order by ID for update) loop null;end loop;
  else
   for z in(select ID from RRL_SBORKA_PALLET_ROWS where PALLET_UID=v_uid order by ID for update) loop null;end loop;
  end if;
  v_row_json:=rows_json(v_kind,v_id,v_uid);
  if rawtohex(sys.dbms_crypto.hash(v_row_json,sys.dbms_crypto.hash_sh256))!=v.get_string('rows_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: shipment rows');end if;
  if v.get_number('customer_order_id') is not null then
   declare v_customer number:=v.get_number('customer_order_id');v_state varchar2(30);v_closed number;begin
    select STATUS into v_state from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=v_customer for update;
    select count(*) into v_closed from RRL_CUSTOMER_ORDER_FULFILLMENT
     where LEGACY_SBORKA_PALLET_ID=v_id and PALLET_UID=v_uid and STATUS in('CANCELLED','SHIPPED');
    if v_state='CANCELLED' or v_closed>0 then raise_application_error(-20886,'SHIPMENT_CUSTOMER_FULFILLMENT_CLOSED');end if;
   end;
  end if;
  if v.get_string('bound_physical_uid') is not null and not v.has('supplier_return_source') and not v.has('interwarehouse_onward_source') then
   declare bound_uid varchar2(150):=v.get_string('bound_physical_uid');bound_version number:=v.get_number('bound_stock_version');current_version number:=v.get_number('bound_current_stock_version');n number;begin
    select count(*) into n from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=v_id and PALLET_UID=v_uid
     and STATUS='PICKED' and PICKED_PALLET_UID=bound_uid and PICKED_STOCK_VERSION=bound_version;
    if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: full pallet shipment binding');end if;
    select count(*) into n from RRL_REMAINS where UID_POLETA=bound_uid and STOCK_VERSION=current_version and REMAIN>0;
    if n!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: bound physical pallet');end if;
   end;
  end if;
  if v.get_number('case_task') is not null then
   declare ct RRL_CASE_PICK_TASK%rowtype;v_task number:=v.get_number('case_task');v_current clob;v_previous clob;begin
    RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task)));
    select * into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_task for update;
    if ct.LEGACY_SBORKA_PALLET_ID is null or ct.LEGACY_SBORKA_PALLET_ID!=v_id or ct.CUSTOMER_ORDER_ID!=v.get_number('customer_order_id')
     or ct.WARE_ID is null or ct.WARE_ID!=v.get_number('warehouse')
     or ct.CONTENT_VERSION!=v.get_number('case_version') or ct.STATUS not in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP')
     then raise_application_error(-20890,'CLOSURE_CHANGED: CASE shipment');end if;
    v_current:=RRL_STOCK_CASE_PICK_CMD.carrier_rows(v_task);
    v_previous:=v.get_array('case_carrier').to_clob;
    if dbms_lob.compare(v_current,v_previous)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: CASE contents');end if;
   end;
  end if;
  if v.has('interwarehouse_onward_source')then RRL_STOCK_INTERWARE_NEXT.validate_load(v.get_object('interwarehouse_onward_source'),p_actor);end if;
  a:=v.get_array('legs');
  for i in 0..a.get_size-1 loop
   l:=treat(a.get(i) as json_object_t);v_units:=null;v_row_id:=l.get_number('row_id');v_qty:=RRL_STOCK_MATH.quantity(l.get_string('quantity'));
   declare
 v_json_sql_2_1 varchar2(32767):=l.get_string('uid');
begin
select ARTICUL into v_article from RRL_PALLETS where UID_PALLET=v_json_sql_2_1;
end;
   if v_article!=l.get_string('article') then raise_application_error(-20890,'CLOSURE_CHANGED: shipment article');end if;
   declare
 v_json_sql_3_1 varchar2(32767):=l.get_string('uid');
begin
select nvl(br.IS_SHIPMENT_ALLOWED,1) into v_ready from RRL_PALLETS pp left join RRL_PROD_BATCH_READY_V br on br.PROD_BATCH_ID=pp.PROD_BATCH_ID where pp.UID_PALLET=v_json_sql_3_1;
end;
   if v_ready!=1 then raise_application_error(-20886,'SHIPMENT_REGULATORY_NOT_READY');end if;
   if l.has('reservation_id') then
    declare
 v_json_sql_4_1 number:=l.get_number('reservation_id');
begin
select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=v_json_sql_4_1 for update;
end;
    if sr.CUSTOMER_ORDER_ID!=v.get_number('customer_order_id') or sr.RESERVATION_KIND!='HARD' or sr.RESERVATION_DOMAIN!='PICKING'
     or sr.STATUS not in('ACTIVE','ALLOCATED','PICKING') or sr.UID_PALLET!=l.get_string('uid') or sr.CELL!=l.get_string('cell') then raise_application_error(-20890,'CLOSURE_CHANGED: shipment owner');end if;
   end if;
   declare
 v_json_sql_5_1 varchar2(32767):=l.get_string('uid');
 v_json_sql_5_2 varchar2(32767):=l.get_string('cell');
begin
select REMAIN into v_p from RRL_REMAINS where UID_POLETA=v_json_sql_5_1 and CELL=v_json_sql_5_2;
end;
   if RRL_STOCK_PLAN_HELPER.decimal_text(v_p)!=l.get_string('source_p') then raise_application_error(-20890,'CLOSURE_CHANGED: shipment stock');end if;
   if d.get_object('metadata').has('units_by_allocation') then
    if d.get_object('metadata').get_object('units_by_allocation').has(RRL_STOCK_PLAN_HELPER.decimal_text(i+1)) then
     v_units:=d.get_object('metadata').get_object('units_by_allocation').get_array(RRL_STOCK_PLAN_HELPER.decimal_text(i+1)).to_clob;
    end if;
   end if;
   RRL_STOCK_EFFECT_CORE.consume(l.get_string('uid'),l.get_string('cell'),v_qty,l.get_string('base_uom'),l.get_number('uom_version'),v.get_number('warehouse'),
    p_actor,p_offset+i+1,l.get_number('reservation_id'),l.get_string('owner_type'),l.get_number('owner_id'),v_units,case when v_kind='SHIP_DOCUMENT' then v_id end,case when v_kind='SHIP_PALLET' then v_row_id end,case when v.has('supplier_return_source') then v.get_object('supplier_return_source').get_string('receipt_operation_id')end);
   if v_kind='SHIP_PALLET' then
    declare
 v_json_sql_6_1 varchar2(32767):=l.get_string('uid');
begin
update RRL_SBORKA_PALLET_ROWS set PRIHOD_PALLET_UID=v_json_sql_6_1 where ID=v_row_id;
end;
   end if;
   facts.append(l);
  end loop;
  if v_kind='SHIP_DOCUMENT' then update RRL_OTHOD_NAKLAD set CONDITION=2 where ID=v_id;
  else update RRL_SBORKA_PALLETS set CONDITION=2 where ID=v_id;end if;
  if v.get_number('customer_order_id') is not null then
   RRL_STOCK_FULFILLMENT_FACT.project_ship(v_id,v_uid,v.get_number('customer_order_id'),d.get_string('operation_id'),facts.to_clob,p_actor);
  end if;
  if v.get_number('case_task') is not null then
   declare v_task number:=v.get_number('case_task');v_operation varchar2(100):=d.get_string('operation_id');begin
    RRL_STOCK_HU_PLACEMENT_CORE.release_case(v_task,v.get_string('case_cell'));
    update RRL_CASE_PICK_TASK set STATUS='SHIPPED',SHIPPED_OPERATION=v_operation,
     CONTENT_VERSION=CONTENT_VERSION+1,DONE_AT=systimestamp,UPDATED_AT=systimestamp,UPDATED_BY=p_actor
     where CASE_PICK_TASK_ID=v_task;
   end;
  end if;
  j.put('case_pick_task_id',v.get_number('case_task'));
  j.put('operation_id',d.get_string('operation_id'));j.put('status','APPLIED');j.put('document_id',v_id);j.put('allocations',facts);
  if v.has('interwarehouse_onward_source')then RRL_STOCK_INTERWARE_NEXT.dispatched(v.get_object('interwarehouse_onward_source'),p_actor);end if;
  if v.has('supplier_return_source')then RRL_STOCK_SUP_RETURN.dispatched(v.get_object('supplier_return_source'),p_actor);end if;
  p_result:=j.to_clob;
 end;
 procedure execute_shipment(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v_plan clob;op varchar2(100):=d.get_string('operation_id');v_domain clob;
 begin
  select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v_domain:=json_object_t.parse(v_plan).get_object('domain').to_clob;
  execute_resolved(p_request,v_domain,0,p_actor,p_result);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_SHORT_RECOVERY as
 procedure add_case_rows(s RRL_CASE_PICK_SHORT%rowtype,p_resources in out nocopy json_array_t) is l RRL_CASE_PICK_LINE%rowtype;
 begin
  select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=s.CASE_PICK_LINE_ID;
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CASE_PICK_SHORT',RRL_STOCK_PLAN_HELPER.decimal_text(s.CASE_PICK_SHORT_ID));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(s.PICK_WAVE_ID));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(s.CASE_PICK_TASK_ID));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CASE_PICK_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(s.CASE_PICK_LINE_ID));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_TASK_ID));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(l.PICK_WAVE_TASK_ID));
 end;
 procedure plan_inventory(p_request clob,p_resources in out nocopy json_array_t,p_policies in out nocopy json_array_t,p_domain in out nocopy json_object_t) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t;counts json_array_t;x json_object_t;
  it RRL_INVENTORY_TASK%rowtype;s RRL_CASE_PICK_SHORT%rowtype;doc number;ware number;new_repl number;n number;id number;found boolean;
 begin
  m:=d.get_object('metadata');m.on_error(0);
  if not m.has('inventory_task_id') or m.get('inventory_task_id').is_null then return;end if;
  id:=m.get_number('inventory_task_id');doc:=d.get_object('source').get_number('revision_id');
  if id is null or id<=0 or id!=trunc(id) then raise_application_error(-20881,'INVENTORY_TASK_ID_REQUIRED');end if;
  select * into it from RRL_INVENTORY_TASK where INVENTORY_TASK_ID=id;
  select * into s from RRL_CASE_PICK_SHORT where CASE_PICK_SHORT_ID=it.SOURCE_DOC_ID;
  select WARE_ID into ware from RRL_REVIZION where ID=doc;
  if it.SOURCE_DOC_TYPE!='CASE_PICK_SHORT' or it.TASK_SOURCE!='CASE_PICK_SHORT'
    or it.INVENTORY_TASK_ID!=s.INVENTORY_TASK_ID or it.STATUS not in('NEW','ASSIGNED','IN_PROGRESS')
    or s.STATUS!='ACCEPTED' or s.RECOVERY_STATE is null or s.RECOVERY_STATE!='WAIT_INVENTORY'
    or it.WARE_ID!=ware or it.CELL_CODE!=s.CELL_CODE or it.ARTICUL!=s.ARTICUL then
   raise_application_error(-20886,'SHORT_INVENTORY_TASK_STATE_CONFLICT');end if;
  counts:=m.get_array('counts');
  for i in 0..counts.get_size-1 loop
   x:=treat(counts.get(i) as json_object_t);
   if x.get_string('cell')!=it.CELL_CODE or x.get_string('article')!=it.ARTICUL then
    raise_application_error(-20887,'SHORT_INVENTORY_SCOPE_CONFLICT');end if;
  end loop;
  for lot in(select r.UID_POLETA from RRL_REMAINS r join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA
   where r.CELL=it.CELL_CODE and p.ARTICUL=it.ARTICUL and r.REMAIN>0 fetch first 201 rows only) loop
   found:=false;
   for i in 0..counts.get_size-1 loop
    x:=treat(counts.get(i) as json_object_t);
    if x.get_string('uid')=lot.UID_POLETA then found:=true;exit;end if;
   end loop;
   if not found then raise_application_error(-20887,'SHORT_INVENTORY_SCOPE_INCOMPLETE: refresh all lots');end if;
  end loop;
  RRL_STOCK_PLAN_HELPER.fence(p_policies,'CELL',it.CELL_CODE,6);
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_INVENTORY_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(id));
  add_case_rows(s,p_resources);
  if it.RESOURCE_SESSION_ID is not null then
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_RESOURCE_SESSION',RRL_STOCK_PLAN_HELPER.decimal_text(it.RESOURCE_SESSION_ID));
  end if;
  p_domain.put('inventory_session',it.RESOURCE_SESSION_ID);
  select RRL_PICK_WAVE_REPL_SQ.nextval into new_repl from dual;
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(new_repl));
  p_domain.put('inventory_task_id',id);p_domain.put('short_id',s.CASE_PICK_SHORT_ID);p_domain.put('new_repl_id',new_repl);
 end;
 procedure finish_inventory(p_request clob,p_actor varchar2,p_domain json_object_t,p_facts json_array_t,p_result in out nocopy json_object_t) is
  d json_object_t:=json_object_t.parse(p_request);id number;it RRL_INVENTORY_TASK%rowtype;s RRL_CASE_PICK_SHORT%rowtype;l RRL_CASE_PICK_LINE%rowtype;
  qty number:=0;need number;new_repl number;op varchar2(100);x json_object_t;found boolean;min_days number;min_percent number;
 begin
  if not p_domain.has('inventory_task_id') then return;end if;
  if RRL_HAS_WRIGHT(p_actor,'inventory_task_execute')!=1 then raise_application_error(-20882,'SHORT_INVENTORY_EXECUTE_FORBIDDEN');end if;
  id:=p_domain.get_number('inventory_task_id');new_repl:=p_domain.get_number('new_repl_id');op:=d.get_string('operation_id');
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_INVENTORY_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(id)));
  select * into it from RRL_INVENTORY_TASK where INVENTORY_TASK_ID=id for update;
  select * into s from RRL_CASE_PICK_SHORT where CASE_PICK_SHORT_ID=it.SOURCE_DOC_ID for update;
  select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=s.CASE_PICK_LINE_ID for update;
  if s.CASE_PICK_SHORT_ID!=p_domain.get_number('short_id') or s.RECOVERY_STATE!='WAIT_INVENTORY'
    or it.STATUS not in('NEW','ASSIGNED','IN_PROGRESS') or (it.ASSIGNED_TO is not null and it.ASSIGNED_TO!=p_actor) then
   raise_application_error(-20886,'SHORT_INVENTORY_EXECUTOR_OR_STATE_CONFLICT');end if;
  if nvl(it.RESOURCE_SESSION_ID,-1)!=nvl(p_domain.get_number('inventory_session'),-1) then
   raise_application_error(-20890,'CLOSURE_CHANGED: inventory session');end if;
  if it.RESOURCE_SESSION_ID is not null then
   declare n number;begin
    select count(*) into n from RRL_RESOURCE_SESSION ss join RRL_RESOURCE_SHIFT sh on sh.SHIFT_ID=ss.SHIFT_ID
     join RRL_RESOURCE_TASK_QUAL qq on qq.RESOURCE_ID=ss.RESOURCE_ID and qq.TASK_TYPE='INVENTORY_CHECK'
     where ss.SESSION_ID=it.RESOURCE_SESSION_ID and ss.OPERATOR_USER_ID=p_actor and ss.STATUS='ACTIVE'
      and ss.CURRENT_INVENTORY_TASK_ID=id and qq.ACTIVE=1 and qq.VALID_FROM<=systimestamp
      and (qq.VALID_UNTIL is null or qq.VALID_UNTIL>systimestamp) and sh.STATUS='OPEN' and systimestamp between sh.START_AT and sh.FINISH_AT;
    if n!=1 then raise_application_error(-20886,'SHORT_INVENTORY_SESSION_OR_QUALIFICATION_CONFLICT');end if;
   end;
  end if;
  for i in 0..p_facts.get_size-1 loop x:=treat(p_facts.get(i) as json_object_t);if not regexp_like(x.get_string('after'),'^0([.]0{1,9})?$') then qty:=qty+RRL_STOCK_MATH.quantity(x.get_string('after'));end if;end loop;
  -- CELL X prevents an unobserved concurrent arrival. A new unlisted lot requires refresh.
  for lot in(select r.UID_POLETA from RRL_REMAINS r join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA
    where r.CELL=it.CELL_CODE and p.ARTICUL=it.ARTICUL and r.REMAIN>0) loop
   found:=false;
   for i in 0..p_facts.get_size-1 loop x:=treat(p_facts.get(i) as json_object_t);if x.get_string('uid')=lot.UID_POLETA then found:=true;exit;end if;end loop;
   if not found then raise_application_error(-20890,'CLOSURE_CHANGED: short inventory lot set');end if;
  end loop;
  need:=l.PLANNED_QTY-l.PICKED_QTY;
  if need<=0 or need!=s.SHORT_QTY or l.STATUS!='WAIT_REPLENISHMENT' then raise_application_error(-20886,'SHORT_RECOVERY_REMAINDER_CHANGED');end if;
  select max(MIN_SHELF_LIFE_DAYS),max(MIN_SHELF_LIFE_PERCENT) into min_days,min_percent from RRL_PICK_WAVE_REPLENISH_TASK where PICK_TASK_ID=l.PICK_TASK_ID;
  insert into RRL_PICK_WAVE_REPLENISH_TASK(PICK_WAVE_REPLENISH_TASK_ID,PICK_WAVE_ID,PICK_TASK_ID,STATUS,ARTICUL,
   TARGET_CELL_CODE,QTY,PICK_SEQUENCE,CREATED_BY,REPLENISHMENT_METHOD,REPLENISHMENT_QTY_MODE,RELEASED_AT,RELEASED_BY,MIN_SHELF_LIFE_DAYS,MIN_SHELF_LIFE_PERCENT)
   values(new_repl,l.PICK_WAVE_ID,l.PICK_TASK_ID,'RELEASED',l.ARTICUL,l.CELL_CODE,need,l.PICK_SEQUENCE,p_actor,'IMMEDIATE','FILL_TO_VOLUME',sysdate,p_actor,min_days,min_percent);
  declare
 v_json_sql_1_1 number:=p_domain.get_number('document');
begin
update RRL_INVENTORY_TASK set STATUS='DONE',FACT_QTY=qty,DONE_AT=systimestamp,UPDATED_AT=systimestamp,UPDATED_BY=p_actor,
   ASSIGNED_TO=nvl(ASSIGNED_TO,p_actor),REVISION_ID=v_json_sql_1_1,COUNT_OPERATION_ID=op where INVENTORY_TASK_ID=id;
end;
  update RRL_CASE_PICK_SHORT set RECOVERY_STATE='WAIT_REPLENISHMENT',REPLENISH_TASK_ID=new_repl,RECOVERY_LAST_ERROR=null,RECOVERY_WORKER=null,RECOVERY_LEASE_UNTIL=null where CASE_PICK_SHORT_ID=s.CASE_PICK_SHORT_ID;
  if it.RESOURCE_SESSION_ID is not null then
   update RRL_RESOURCE_SESSION set CURRENT_INVENTORY_TASK_ID=null,LAST_CELL=it.CELL_CODE,
    LAST_POSITION_AT=systimestamp,LAST_HEARTBEAT_AT=systimestamp
    where SESSION_ID=it.RESOURCE_SESSION_ID and CURRENT_INVENTORY_TASK_ID=id;
  end if;
  p_result.put('inventory_task_id',id);p_result.put('short_id',s.CASE_PICK_SHORT_ID);p_result.put('replenish_task_id',new_repl);
  p_result.put('observed_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(qty));p_result.put('recovery_state','WAIT_REPLENISHMENT');
 end;

 procedure set_ready(s RRL_CASE_PICK_SHORT%rowtype,p_actor varchar2) is
 begin
  update RRL_CASE_PICK_SHORT set RECOVERY_STATE='READY',RECOVERY_LAST_ERROR=null,RECOVERY_WORKER=null,RECOVERY_LEASE_UNTIL=null
   where CASE_PICK_SHORT_ID=s.CASE_PICK_SHORT_ID;
  update RRL_CASE_PICK_LINE set STATUS='ACTIVE',UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_LINE_ID=s.CASE_PICK_LINE_ID;
  update RRL_CASE_PICK_TASK set STATUS=case when exists(select 1 from RRL_CASE_PICK_LINE l
    where l.CASE_PICK_TASK_ID=s.CASE_PICK_TASK_ID and l.STATUS='WAIT_REPLENISHMENT') then 'WAIT_REPLENISHMENT' else 'IN_PROGRESS' end,
   CONTENT_VERSION=CONTENT_VERSION+1,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=s.CASE_PICK_TASK_ID;
 end;
 procedure plan_replenishment(p_repl number,p_resources in out nocopy json_array_t) is
 begin
  for s in(select * from RRL_CASE_PICK_SHORT where REPLENISH_TASK_ID=p_repl and RECOVERY_STATE='WAIT_REPLENISHMENT') loop add_case_rows(s,p_resources);end loop;
 end;
 procedure finish_replenishment(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2) is
  qty number;need number;status varchar2(30);
 begin
  for s in(select * from RRL_CASE_PICK_SHORT where REPLENISH_TASK_ID=p_task.SOURCE_TASK_ID and RECOVERY_STATE='WAIT_REPLENISHMENT') loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_SHORT',RRL_STOCK_PLAN_HELPER.decimal_text(s.CASE_PICK_SHORT_ID)));
   select STATUS into status from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=s.REPLENISH_TASK_ID;
   select PLANNED_QTY-PICKED_QTY into need from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=s.CASE_PICK_LINE_ID;
   select nvl(sum(sr.BASE_QTY),0) into qty from RRL_STOCK_RESERVATION sr join RRL_CASE_PICK_LINE l on l.CASE_PICK_LINE_ID=s.CASE_PICK_LINE_ID
    where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=s.PICK_WAVE_ID and sr.SOURCE_LINE_ID=l.PICK_TASK_ID
     and sr.CELL=s.CELL_CODE and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING')
     and not exists(select 1 from RRL_CASE_CARRIER_LOT h where h.LOT_UID=sr.UID_PALLET);
   if status in('DONE','IN_PROGRESS') and need>0 and qty>0 then set_ready(s,p_actor);end if;
  end loop;
 end;
 procedure plan_pick(p_line number,p_resources in out nocopy json_array_t) is
 begin
  for s in(select * from RRL_CASE_PICK_SHORT where CASE_PICK_LINE_ID=p_line and RECOVERY_STATE in('WAIT_INVENTORY','WAIT_REPLENISHMENT','READY')) loop
   if s.RECOVERY_STATE!='READY' then raise_application_error(-20886,'SHORT_RECOVERY_NOT_READY');end if;
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CASE_PICK_SHORT',RRL_STOCK_PLAN_HELPER.decimal_text(s.CASE_PICK_SHORT_ID));
  end loop;
 end;
 procedure finish_pick(p_line number,p_actor varchar2) is
 begin
  for s in(select * from RRL_CASE_PICK_SHORT where CASE_PICK_LINE_ID=p_line and RECOVERY_STATE in('WAIT_INVENTORY','WAIT_REPLENISHMENT','READY')) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CASE_PICK_SHORT',RRL_STOCK_PLAN_HELPER.decimal_text(s.CASE_PICK_SHORT_ID)));
   if s.RECOVERY_STATE!='READY' then raise_application_error(-20886,'SHORT_RECOVERY_NOT_READY');end if;
   update RRL_CASE_PICK_SHORT set RECOVERY_STATE='RESUMED',RESTORED_AT=systimestamp,RECOVERY_WORKER=null,RECOVERY_LEASE_UNTIL=null
    where CASE_PICK_SHORT_ID=s.CASE_PICK_SHORT_ID;
  end loop;
 end;

 procedure plan_ready(p_request clob,p_policies in out nocopy json_array_t,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t) is
  d json_object_t:=json_object_t.parse(p_request);s RRL_CASE_PICK_SHORT%rowtype;l RRL_CASE_PICK_LINE%rowtype;rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;
  chunks json_array_t:=json_array_t();x json_object_t;id number;ware number;need number;covered number;take_qty number;rid number;ver number;
 begin
  id:=d.get_object('source').get_number('short_id');select * into s from RRL_CASE_PICK_SHORT where CASE_PICK_SHORT_ID=id;
  select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=s.CASE_PICK_LINE_ID;
  select WARE_ID into ware from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=s.CASE_PICK_TASK_ID;
  if s.STATUS!='ACCEPTED' or s.RECOVERY_STATE is null or s.RECOVERY_STATE not in('WAIT_REPLENISHMENT','READY') then
   raise_application_error(-20886,'SHORT_READY_STATE_CONFLICT');end if;
  RRL_STOCK_PLAN_HELPER.fence(p_policies,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(p_policies,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(p_resources,10,'OP',d.get_string('operation_id'));
  RRL_STOCK_PLAN_HELPER.anchor(p_resources,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(d.get_string('operation_id'),'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  add_case_rows(s,p_resources);
  select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=s.REPLENISH_TASK_ID;
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(s.REPLENISH_TASK_ID));
  need:=l.PLANNED_QTY-l.PICKED_QTY;
  if need<=0 or rt.PICK_TASK_ID!=l.PICK_TASK_ID or rt.PICK_WAVE_ID!=l.PICK_WAVE_ID or rt.ARTICUL!=l.ARTICUL or rt.TARGET_CELL_CODE!=l.CELL_CODE then
   raise_application_error(-20886,'SHORT_READY_IDENTITY_CONFLICT');end if;
  select nvl(sum(sr.BASE_QTY),0) into covered from RRL_STOCK_RESERVATION sr
   where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=l.PICK_WAVE_ID and sr.SOURCE_LINE_ID=l.PICK_TASK_ID
    and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING') and sr.CELL=l.CELL_CODE
    and not exists(select 1 from RRL_CASE_CARRIER_LOT h where h.LOT_UID=sr.UID_PALLET);
  if rt.SOURCE_RESERVATION_ID is not null and covered<=0 then
   raise_application_error(-20886,'SHORT_EXISTING_REPLENISHMENT_MUST_FINISH');end if;
  p_domain.put('short_id',id);p_domain.put('repl_id',s.REPLENISH_TASK_ID);p_domain.put('repl_status',rt.STATUS);
  p_domain.put('source_reservation',rt.SOURCE_RESERVATION_ID);p_domain.put('line_id',s.CASE_PICK_LINE_ID);
  p_domain.put('remaining',RRL_STOCK_PLAN_HELPER.decimal_text(need));p_domain.put('warehouse',ware);
  p_domain.put('covered',RRL_STOCK_PLAN_HELPER.decimal_text(covered));p_domain.put('decision','READY');
  need:=greatest(need-covered,0);
  if rt.SOURCE_RESERVATION_ID is null then
  for c in(select rr.UID_POLETA,rr.REMAIN,rr.HARD_RESERVED_BASE,rr.STOCK_VERSION,rr.BASE_UOM,p.EXPIRY_DATE
    from RRL_REMAINS rr join RRL_PALLETS p on p.UID_PALLET=rr.UID_POLETA
    where rr.CELL=l.CELL_CODE and p.ARTICUL=l.ARTICUL and rr.REMAIN>rr.HARD_RESERVED_BASE
    order by p.EXPIRY_DATE nulls last,rr.UID_POLETA fetch first 201 rows only) loop
   exit when need=0;
   if RRL_STOCK_ELIGIBILITY.reason(c.UID_POLETA,l.CELL_CODE,ware,0,rt.MIN_SHELF_LIFE_DAYS,rt.MIN_SHELF_LIFE_PERCENT,'PICK',null,l.ARTICUL) is not null then continue;end if;
   if chunks.get_size>=200 then raise_application_error(-20881,'SHORT_READY_SOURCE_BOUND');end if;
   take_qty:=least(need,c.REMAIN-c.HARD_RESERVED_BASE);need:=need-take_qty;
   select RRL_STOCK_RESERVATION_SQ.nextval into rid from dual;
   select max(POLICY_VERSION) into ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=l.ARTICUL and INPUT_UOM=c.BASE_UOM and BASE_UOM=c.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;
   if ver is null then raise_application_error(-20868,'SHORT_READY_BASE_POLICY_REQUIRED');end if;
   RRL_STOCK_PLAN_HELPER.stock_closure(p_policies,p_resources,c.UID_POLETA,l.ARTICUL,l.CELL_CODE,null);
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(rid));
   x:=json_object_t();x.put('uid',c.UID_POLETA);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(take_qty));x.put('base',c.BASE_UOM);
   x.put('version',c.STOCK_VERSION);x.put('reservation',rid);x.put('policy',ver);chunks.append(x);
  end loop;
  end if;
  if covered=0 and chunks.get_size=0 then raise_application_error(-20886,'SHORT_NO_ELIGIBLE_TARGET_STOCK');end if;
  p_domain.put('chunks',chunks);
 end;
 procedure execute_ready(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;chunks json_array_t;x json_object_t;detail json_object_t:=json_object_t();j json_object_t:=json_object_t();
  plan clob;op varchar2(100);s RRL_CASE_PICK_SHORT%rowtype;l RRL_CASE_PICK_LINE%rowtype;rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;
  qty number;covered number;ver number;uid varchar2(200);rid number;base varchar2(20);policy number;stockver number;units clob;wave_status varchar2(40);
 begin
  if RRL_HAS_WRIGHT(p_actor,'case_pick_short_approve')!=1 then raise_application_error(-20882,'SHORT_READY_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v:=json_object_t.parse(plan).get_object('domain');
  declare
 v_json_sql_2_1 number:=v.get_number('short_id');
begin
select * into s from RRL_CASE_PICK_SHORT where CASE_PICK_SHORT_ID=v_json_sql_2_1 for update;
end;
  select STATUS into wave_status from RRL_PICK_WAVE where PICK_WAVE_ID=s.PICK_WAVE_ID for update;
  select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=s.CASE_PICK_LINE_ID for update;
  select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=s.REPLENISH_TASK_ID for update;
  if wave_status is null or wave_status in('CANCELLED','CLOSED','COMPLETED','SHIPPED','DRAFT','PREVIEW') or
   s.STATUS!='ACCEPTED' or s.RECOVERY_STATE not in('WAIT_REPLENISHMENT','READY') or s.REPLENISH_TASK_ID!=v.get_number('repl_id')
   or rt.STATUS!=v.get_string('repl_status') or nvl(rt.SOURCE_RESERVATION_ID,-1)!=nvl(v.get_number('source_reservation'),-1)
   or RRL_STOCK_PLAN_HELPER.decimal_text(l.PLANNED_QTY-l.PICKED_QTY)!=v.get_string('remaining') then
   raise_application_error(-20890,'CLOSURE_CHANGED: short target stock');end if;
  select nvl(sum(sr.BASE_QTY),0) into covered from RRL_STOCK_RESERVATION sr
   where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=l.PICK_WAVE_ID and sr.SOURCE_LINE_ID=l.PICK_TASK_ID
    and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING') and sr.CELL=l.CELL_CODE
    and not exists(select 1 from RRL_CASE_CARRIER_LOT h where h.LOT_UID=sr.UID_PALLET);
  if RRL_STOCK_PLAN_HELPER.decimal_text(covered)!=v.get_string('covered') then raise_application_error(-20890,'CLOSURE_CHANGED: short target coverage');end if;
  chunks:=v.get_array('chunks');
  for i in 0..chunks.get_size-1 loop
   x:=treat(chunks.get(i) as json_object_t);uid:=x.get_string('uid');rid:=x.get_number('reservation');base:=x.get_string('base');policy:=x.get_number('policy');
   qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));
   select STOCK_VERSION into stockver from RRL_REMAINS where UID_POLETA=uid and CELL=l.CELL_CODE;
   if stockver!=x.get_number('version') then raise_application_error(-20890,'CLOSURE_CHANGED: short target stock version');end if;
   RRL_STOCK_ELIGIBILITY.assert_source(uid,l.CELL_CODE,v.get_number('warehouse'),qty,rt.MIN_SHELF_LIFE_DAYS,rt.MIN_SHELF_LIFE_PERCENT,'PICK',null,l.ARTICUL);
   units:=RRL_STOCK_UNIT_CORE.automatic_units(uid,l.CELL_CODE,qty);detail.put('pick_wave_id',l.PICK_WAVE_ID);detail.put('reservation_scope','QTY');
   RRL_STOCK_RESERVE_CORE.create_hard(rid,uid,l.CELL_CODE,qty,base,policy,'PICK_WAVE',l.PICK_WAVE_ID,l.PICK_TASK_ID,'PICKING',p_actor,detail.to_clob);
   RRL_STOCK_UNIT_CORE.reserve_units(uid,l.CELL_CODE,rid,qty,units);
  end loop;
  if rt.SOURCE_RESERVATION_ID is null then update RRL_PICK_WAVE_REPLENISH_TASK set STATUS='CANCELLED',WAIT_REASON='Confirmed stock available at original pick cell',UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_REPLENISH_TASK_ID=s.REPLENISH_TASK_ID;end if;
  set_ready(s,p_actor);j.put('operation_id',op);j.put('short_id',s.CASE_PICK_SHORT_ID);j.put('recovery_state','READY');j.put('new_reservations',chunks.get_size);
  p_result:=j.to_clob;
 end;
 procedure plan_pick(p_line number,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t) is
  a json_array_t:=json_array_t();x json_object_t;rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;new_id number;
 begin
  plan_pick(p_line,p_resources);
  for s in(select * from RRL_CASE_PICK_SHORT where CASE_PICK_LINE_ID=p_line and RECOVERY_STATE='READY') loop
   select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=s.REPLENISH_TASK_ID;
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(s.REPLENISH_TASK_ID));
   select RRL_PICK_WAVE_REPL_SQ.nextval into new_id from dual;
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(new_id));
   x:=json_object_t();x.put('short_id',s.CASE_PICK_SHORT_ID);x.put('old_repl',s.REPLENISH_TASK_ID);x.put('new_repl',new_id);
   x.put('old_status',rt.STATUS);x.put('source_reservation',rt.SOURCE_RESERVATION_ID);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(rt.QTY));a.append(x);
  end loop;
  p_domain.put('recovery_continuations',a);
 end;
 procedure finish_pick(p_line number,p_actor varchar2,p_domain json_object_t) is
  a json_array_t:=p_domain.get_array('recovery_continuations');x json_object_t;s RRL_CASE_PICK_SHORT%rowtype;l RRL_CASE_PICK_LINE%rowtype;
  rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;id number;old_id number;new_id number;need number;
 begin
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);id:=x.get_number('short_id');old_id:=x.get_number('old_repl');new_id:=x.get_number('new_repl');
   select * into s from RRL_CASE_PICK_SHORT where CASE_PICK_SHORT_ID=id for update;
   select * into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=p_line;
   select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=old_id for update;
   if s.CASE_PICK_LINE_ID!=p_line or s.RECOVERY_STATE!='READY' or s.REPLENISH_TASK_ID!=old_id
    or rt.STATUS!=x.get_string('old_status') or nvl(rt.SOURCE_RESERVATION_ID,-1)!=nvl(x.get_number('source_reservation'),-1)
    or RRL_STOCK_PLAN_HELPER.decimal_text(rt.QTY)!=x.get_string('quantity') then raise_application_error(-20890,'CLOSURE_CHANGED: recovery continuation');end if;
   need:=l.PLANNED_QTY-l.PICKED_QTY;
   if need=0 then
    update RRL_CASE_PICK_SHORT set RECOVERY_STATE='RESUMED',RESTORED_AT=systimestamp,RECOVERY_WORKER=null,RECOVERY_LEASE_UNTIL=null,RECOVERY_LAST_ERROR=null
     where CASE_PICK_SHORT_ID=id;
   else
    if need<0 then raise_application_error(-20886,'SHORT_CONTINUATION_FACT_EXCEEDS_PLAN');end if;
    if rt.STATUS in('DONE','CANCELLED','FAILED') then
     RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(new_id)));
     insert into RRL_PICK_WAVE_REPLENISH_TASK(PICK_WAVE_REPLENISH_TASK_ID,PICK_WAVE_ID,PICK_TASK_ID,STATUS,ARTICUL,
      TARGET_CELL_CODE,QTY,DEMAND_BASE_QTY,PICK_SEQUENCE,CREATED_BY,REPLENISHMENT_METHOD,REPLENISHMENT_QTY_MODE,RELEASED_AT,RELEASED_BY,MIN_SHELF_LIFE_DAYS,MIN_SHELF_LIFE_PERCENT)
      values(new_id,l.PICK_WAVE_ID,l.PICK_TASK_ID,'RELEASED',l.ARTICUL,l.CELL_CODE,need,need,l.PICK_SEQUENCE,p_actor,'IMMEDIATE','FILL_TO_VOLUME',sysdate,p_actor,rt.MIN_SHELF_LIFE_DAYS,rt.MIN_SHELF_LIFE_PERCENT);
    else new_id:=old_id;end if;
    update RRL_CASE_PICK_SHORT set RECOVERY_STATE='WAIT_REPLENISHMENT',REPLENISH_TASK_ID=new_id,RECOVERY_SOURCE_REQUEST=null,
     RECOVERY_WORKER=null,RECOVERY_LEASE_UNTIL=null,RECOVERY_LAST_ERROR=null where CASE_PICK_SHORT_ID=id;
    update RRL_CASE_PICK_LINE set STATUS='WAIT_REPLENISHMENT' where CASE_PICK_LINE_ID=p_line;
    update RRL_CASE_PICK_TASK set STATUS='WAIT_REPLENISHMENT' where CASE_PICK_TASK_ID=s.CASE_PICK_TASK_ID;
   end if;
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_SINGLE_LOAD_CMD as
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');src json_object_t:=d.get_object('source');v json_object_t:=json_object_t();tree json_object_t;sd json_object_t;load_domain json_object_t;
  p clob;r clob;dom clob;snap clob;f json_array_t;resources json_array_t;ships json_array_t:=json_array_t();entry json_object_t:=json_object_t();req json_object_t:=json_object_t();signature_text varchar2(64);source_claims clob;root_node json_object_t;
 begin
  if not m.has('loading_context') then raise_application_error(-20886,'SINGLE_LOAD_CONTEXT_REQUIRED');end if;
  RRL_STOCK_LOADING_READ.describe_source(src.get_string('pallet_identifier'),p_operation,p,r,dom,snap);
  tree:=json_object_t.parse(snap);sd:=json_object_t.parse(dom);signature_text:=RRL_STOCK_QC_GATE.signature_for_plan(dom);
  if m.get_string('expected_composition_signature') is null or m.get_string('expected_composition_signature')!=signature_text
   or m.get_number('expected_version') is null or m.get_number('expected_version')!=treat(tree.get_array('nodes').get(0) as json_object_t).get_number('version') then raise_application_error(-20890,'CLOSURE_CHANGED: standalone load composition');end if;
  RRL_STOCK_QC_GATE.assert_approved(dom);
  req.put('command_type','SHIP_PALLET');req.put('operation_id',p_operation);req.put('source',src);req.put('metadata',json_object_t());entry.put('request',req);entry.put('domain',sd);ships.append(entry);
  f:=json_array_t.parse(p);resources:=json_array_t.parse(r);
  RRL_STOCK_HU_LOAD_CORE.compile_load(p_request,snap,ships.to_clob,f,resources,load_domain);
  root_node:=treat(tree.get_array('nodes').get(0)as json_object_t);
  if root_node.get_string('kind')='STOCK'then
   RRL_STOCK_HU_PLACEMENT_CORE.declare_stock_source(resources,tree.get_string('root'),tree.get_string('cell'),source_claims);
   v.put('source_stock_claims',json_array_t.parse(source_claims));
   if json_array_t.parse(source_claims).get_size>0 then RRL_STOCK_PLAN_HELPER.fence(f,'CELL',tree.get_string('cell'),6);end if;
  end if;
  v.put('shipment',entry);v.put('snapshot',tree);v.put('composition_signature',signature_text);v.put('loading',load_domain);
  p_policies:=f.to_clob;p_resources:=resources.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');plan clob;v json_object_t;tree json_object_t;entry json_object_t;sd json_object_t;
  op varchar2(100):=d.get_string('operation_id');root_node json_object_t;scan_alias varchar2(200);now_p clob;now_r clob;now_d clob;now_s clob;result_json clob;j json_object_t:=json_object_t();
 begin
  if RRL_HAS_WRIGHT(p_actor,'stock_posting_shipping')!=1 then raise_application_error(-20882,'PHYSICAL_LOAD_FORBIDDEN');end if;
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');tree:=v.get_object('snapshot');root_node:=treat(tree.get_array('nodes').get(0) as json_object_t);
  scan_alias:=root_node.get_string('sscc');
  if m.get_string('scan_container') is null or(m.get_string('scan_container')!=tree.get_string('root') and(scan_alias is null or m.get_string('scan_container')!=scan_alias))
   or m.get_string('scan_cell') is null or m.get_string('scan_cell')!=tree.get_string('cell') then raise_application_error(-20886,'SINGLE_LOAD_PLACE_CELL_SCAN_REQUIRED');end if;
  RRL_STOCK_HU_LOAD_CORE.begin_load(v.get_object('loading').to_clob);
  entry:=v.get_object('shipment');sd:=entry.get_object('domain');
  -- Actual ST/CASE locks are taken in the existing shipping engine after the trip locks.
  RRL_STOCK_LOADING_READ.describe_source(d.get_object('source').get_string('pallet_identifier'),op,now_p,now_r,now_d,now_s);
  if RRL_STOCK_QC_GATE.signature_for_plan(now_d)!=v.get_string('composition_signature') or dbms_lob.compare(now_s,tree.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: standalone physical load');end if;
  if root_node.get_string('kind')='STOCK'then RRL_STOCK_HU_PLACEMENT_CORE.release_stock_source(tree.get_string('root'),tree.get_string('cell'),v.get_array('source_stock_claims').to_clob);end if;
  RRL_STOCK_SHIPPING_CORE.execute_resolved(entry.get_object('request').to_clob,sd.to_clob,0,p_actor,result_json);
  RRL_STOCK_HU_LOAD_CORE.finish_load(v.get_object('loading').to_clob,tree.to_clob,op,p_actor);
  j.put('operation_id',op);j.put('status','LOADED');j.put('physical_load',v.get_object('loading'));j.put('shipment',json_object_t.parse(result_json));j.put('composition_at_departure',tree);j.put('physical_places',1);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_CASE_CMD as
 function timestamp_utc(p_text varchar2) return timestamp with time zone is
 begin
  if p_text is null or not regexp_like(p_text,'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}[+]00:00$','c') then raise_application_error(-20886,'CASE_EXPLICIT_UTC_DEADLINE_REQUIRED');end if;
  return to_timestamp_tz(p_text,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
 end;
 procedure investigator(p_user varchar2) is n number;
 begin
  select count(*) into n from RUSERS where ID=p_user and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'store_case_investigate')=1;
  if n!=1 then raise_application_error(-20882,'CASE_ACTIVE_INVESTIGATOR_REQUIRED');end if;
 end;
 procedure describe_case(p_case varchar2,p_metadata clob,p_actor varchar2,p_domain out json_object_t) is
  m json_object_t:=json_object_t.parse(p_metadata);issue RRL_STORE_DISCREPANCY_CASE%rowtype;v_action varchar2(30):=m.get_string('action');v_permission varchar2(30);
  v_exp varchar2(50);v_sec varchar2(50);v_role varchar2(20);v_report varchar2(32767);v_reason varchar2(32767);v_deadline timestamp with time zone;v_line number;n number;obligation RRL_STORE_DELIVERY_OBLIGATION%rowtype;source_line RRL_STORE_RECEIPT_LINE%rowtype;v_units number;
 begin
  v_permission:=case v_action when 'ASSIGN' then 'store_case_manage' when 'FINDING' then 'store_case_investigate' when 'LOSS_CONFIRM' then 'store_loss_confirm' when 'CLOSE' then 'store_loss_confirm' else null end;
  if v_permission is null then raise_application_error(-20886,'CASE_ACTION_UNSUPPORTED');end if;
  if RRL_HAS_WRIGHT(p_actor,v_permission)!=1 then raise_application_error(-20882,'CASE_ACTION_FORBIDDEN');end if;
  RRL_STOCK_CASE_CLOSE.actor_scope(p_case,p_actor,v_action);
  select * into issue from RRL_STORE_DISCREPANCY_CASE where CASE_ID=p_case;
  if m.get_number('expected_version') is null or m.get_number('expected_version')!=issue.CASE_VERSION then raise_application_error(-20886,'CASE_VERSION_CONFLICT');end if;
  if issue.STATUS not in('OPEN','ASSIGNED') then raise_application_error(-20886,'CASE_ALREADY_RESOLVED');end if;
  p_domain:=json_object_t();p_domain.put('case_id',p_case);p_domain.put('action',v_action);p_domain.put('version_before',issue.CASE_VERSION);p_domain.put('load_operation_id',issue.LOAD_OPERATION_ID);
  if v_action='ASSIGN' then
   v_exp:=m.get_string('expedition_user');v_sec:=m.get_string('security_user');
   if v_exp is null or v_sec is null or v_exp=v_sec then raise_application_error(-20886,'CASE_SEPARATE_INVESTIGATORS_REQUIRED');end if;
   investigator(v_exp);investigator(v_sec);v_deadline:=timestamp_utc(m.get_string('search_deadline'));
   if v_deadline<=systimestamp then raise_application_error(-20886,'CASE_FUTURE_SEARCH_DEADLINE_REQUIRED');end if;
   p_domain.put('expedition_user',v_exp);p_domain.put('security_user',v_sec);p_domain.put('search_deadline',m.get_string('search_deadline'));
  elsif v_action='FINDING' then
   if issue.STATUS!='ASSIGNED' then raise_application_error(-20886,'CASE_INVESTIGATION_ASSIGNMENT_REQUIRED');end if;
   v_role:=m.get_string('role');v_report:=m.get_string('report');
   if v_role is null or v_role not in('EXPEDITION','SECURITY') or trim(v_report) is null or lengthb(v_report)>2000 then raise_application_error(-20886,'CASE_FINDING_ROLE_AND_REPORT_REQUIRED');end if;
   if (v_role='EXPEDITION' and (issue.EXPEDITION_USER is null or issue.EXPEDITION_USER!=p_actor))
     or(v_role='SECURITY' and(issue.SECURITY_USER is null or issue.SECURITY_USER!=p_actor))then raise_application_error(-20882,'CASE_ASSIGNED_INVESTIGATOR_ONLY');end if;
   p_domain.put('role',v_role);p_domain.put('report',v_report);
  elsif v_action='CLOSE' then
   RRL_STOCK_CASE_CLOSE.describe(p_case,p_metadata,p_actor,p_domain);
  else
   if issue.STATUS!='ASSIGNED' or issue.SEARCH_DEADLINE is null then raise_application_error(-20886,'CASE_INVESTIGATION_ASSIGNMENT_REQUIRED');end if;
   if p_actor=issue.EXPEDITION_USER or p_actor=issue.SECURITY_USER then raise_application_error(-20882,'CASE_LOSS_INDEPENDENT_KRO_REQUIRED');end if;
   select count(distinct ROLE_CODE) into n from RRL_STORE_CASE_FINDING where CASE_ID=p_case
    and((ROLE_CODE='EXPEDITION' and REPORTED_BY=issue.EXPEDITION_USER)or(ROLE_CODE='SECURITY' and REPORTED_BY=issue.SECURITY_USER));
   if n!=2 then raise_application_error(-20886,'CASE_BOTH_INVESTIGATOR_FINDINGS_REQUIRED');end if;
   v_line:=m.get_number('line_no');v_reason:=m.get_string('reason');
   if v_line is null or v_line!=trunc(v_line) or v_line<1 or trim(v_reason) is null or lengthb(v_reason)>2000 then raise_application_error(-20886,'CASE_LOSS_LINE_AND_REASON_REQUIRED');end if;
   select * into obligation from RRL_STORE_DELIVERY_OBLIGATION where CASE_ID=p_case and LINE_NO=v_line and KIND='MISSING_INVESTIGATION';
   if obligation.STATUS not in('OPEN','SEARCHING') then raise_application_error(-20886,'CASE_MISSING_OBLIGATION_ALREADY_DECIDED');end if;
   select * into source_line from RRL_STORE_RECEIPT_LINE where OPERATION_ID=p_case and LINE_NO=v_line;
   if obligation.BASE_QTY!=source_line.MISSING_BASE_QTY or obligation.BASE_UOM!=source_line.BASE_UOM then raise_application_error(-20886,'CASE_ORIGINAL_MISSING_QUANTITY_CONFLICT');end if;
   select nvl(json_value(COMPOSITION_JSON,'$.physical_unit_count' returning number),1) into v_units from RRL_STORE_RECEIPT_FACT where OPERATION_ID=p_case;
   if v_units!=0 then raise_application_error(-20886,'CASE_MARKED_LOSS_UNIT_AND_REGULATORY_FLOW_REQUIRED');end if;
   p_domain.put('line_no',v_line);p_domain.put('lot_uid',source_line.LOT_UID);p_domain.put('article',source_line.ARTICLE);p_domain.put('base_uom',source_line.BASE_UOM);
   p_domain.put('loss_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(obligation.BASE_QTY));p_domain.put('reason',v_reason);
  end if;
 exception when no_data_found then raise_application_error(-20886,'CASE_SOURCE_OR_MISSING_OBLIGATION_NOT_FOUND');
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);v_case varchar2(100):=d.get_object('source').get_string('case_id');v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();v_action varchar2(30);
 begin
  describe_case(v_case,d.get_object('metadata').to_clob,d.get_string('actor'),v);v_action:=v.get_string('action');
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_DISCREPANCY_CASE',v_case);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_CASE_ACTION',p_operation);
  if v_action='FINDING' then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_CASE_FINDING',p_operation);end if;
  if v_action='CLOSE' then RRL_STOCK_CASE_CLOSE.declare_resources(v,p_operation,r);end if;
  if v_action='LOSS_CONFIRM' then
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_LOSS_RECOGNITION',p_operation);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_DELIVERY_OBLIGATION',v_case||':'||RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('line_no'))||':MISSING_INVESTIGATION');
  end if;
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');op varchar2(100):=d.get_string('operation_id');v_case varchar2(100):=d.get_object('source').get_string('case_id');
  plan clob;v json_object_t;fresh json_object_t;version_before number;version_after number;v_action varchar2(30);details clob;j json_object_t:=json_object_t();v_exp varchar2(50);v_sec varchar2(50);v_deadline timestamp with time zone;v_role varchar2(20);v_report varchar2(2000);v_line number;v_lot varchar2(200);v_article varchar2(160);v_unit varchar2(20);v_qty number;v_reason varchar2(2000);
 begin
  select CASE_VERSION into version_before from RRL_STORE_DISCREPANCY_CASE where CASE_ID=v_case for update;
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  describe_case(v_case,m.to_clob,p_actor,fresh);
  if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'CASE_VERSION_OR_SOURCE_CONFLICT');end if;
  version_after:=version_before+1;v_action:=v.get_string('action');details:=v.to_clob;
  insert into RRL_STORE_CASE_ACTION(OPERATION_ID,CASE_ID,ACTION_CODE,VERSION_BEFORE,VERSION_AFTER,ACTOR,DETAILS_JSON)values(op,v_case,v_action,version_before,version_after,p_actor,details);
  if v_action='ASSIGN' then
   v_exp:=v.get_string('expedition_user');v_sec:=v.get_string('security_user');v_deadline:=timestamp_utc(v.get_string('search_deadline'));
   update RRL_STORE_DISCREPANCY_CASE set STATUS='ASSIGNED',EXPEDITION_USER=v_exp,SECURITY_USER=v_sec,ASSIGNED_TO=v_exp,SEARCH_DEADLINE=v_deadline,CASE_VERSION=version_after,LAST_DECISION_OPERATION=op where CASE_ID=v_case;
  elsif v_action='FINDING' then
   v_role:=v.get_string('role');v_report:=v.get_string('report');
   insert into RRL_STORE_CASE_FINDING(OPERATION_ID,CASE_ID,ROLE_CODE,REPORT_TEXT,REPORTED_BY)values(op,v_case,v_role,v_report,p_actor);
  elsif v_action='CLOSE' then
   RRL_STOCK_CASE_CLOSE.persist(v,p_actor);j.put('status','CLOSED');
  else
   v_line:=v.get_number('line_no');v_lot:=v.get_string('lot_uid');v_article:=v.get_string('article');v_unit:=v.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('loss_quantity'));v_reason:=v.get_string('reason');
   update RRL_STORE_DELIVERY_OBLIGATION set STATUS='LOSS_CONFIRMED' where CASE_ID=v_case and LINE_NO=v_line and KIND='MISSING_INVESTIGATION' and STATUS in('OPEN','SEARCHING');
   if sql%rowcount!=1 then raise_application_error(-20886,'CASE_MISSING_OBLIGATION_ALREADY_DECIDED');end if;
   insert into RRL_STORE_LOSS_RECOGNITION(OPERATION_ID,CASE_ID,LINE_NO,LOT_UID,ARTICLE,BASE_UOM,BASE_QTY,REASON_TEXT,CONFIRMED_BY)values(op,v_case,v_line,v_lot,v_article,v_unit,v_qty,v_reason,p_actor);
   j.put('loss_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));j.put('base_uom',v_unit);j.put('original_load_operation',v.get_string('load_operation_id'));
  end if;
  if v_action!='ASSIGN' then update RRL_STORE_DISCREPANCY_CASE set STATUS=case when v_action='CLOSE' then 'CLOSED'else STATUS end,CASE_VERSION=version_after,LAST_DECISION_OPERATION=op where CASE_ID=v_case;end if;
  j.put('operation_id',op);j.put('case_id',v_case);j.put('action',v_action);j.put('case_version',version_after);j.put('warehouse_stock_changed',false);j.put('government_ack_created',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_CUSTODY_CMD as
 procedure assert_scope(p_receipt varchar2,p_actor varchar2)is n number;
 begin
  select count(*)into n from RRL_STORE_RECEIPT_FACT r join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=r.LOAD_OPERATION_ID join RUSERS u on u.ID=p_actor
   where r.OPERATION_ID=p_receipt and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'transport_dispatch_close')=1 and(u.WARE_ID=l.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'STORE_CUSTODY_CURRENT_DISPATCHER_REQUIRED');end if;
 end;
 procedure declare_receipt(p_receipt varchar2,p_load varchar2,p_uid varchar2,p_resources in out nocopy json_array_t,p_operation varchar2 default null)is
 begin
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_RECEIPT_FACT',p_receipt);
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_TT_HU_LOAD_FACT',p_load);
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_LOAD_CUSTODY',nvl(p_operation,p_receipt));
  RRL_STOCK_PLAN_HELPER.anchor(p_resources,30,'HU',p_uid);
  RRL_STOCK_PLAN_HELPER.anchor(p_resources,70,'UNIQUE','TT.LOAD.HU:'||p_uid);
 end;
 procedure describe_source(p_receipt varchar2,p_domain out json_object_t)is
  r RRL_STORE_RECEIPT_FACT%rowtype;l RRL_TT_HU_LOAD_FACT%rowtype;n number;
 begin
  select *into r from RRL_STORE_RECEIPT_FACT where OPERATION_ID=p_receipt;
  select *into l from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=r.LOAD_OPERATION_ID;
  if r.RECEIPT_STATE!='ACCEPTED'or l.STATUS!='DEPARTED'or l.CUSTODY_RELEASED_AT is not null or l.CUSTODY_RELEASE_OPERATION_ID is not null or(l.ROOT_UID is null and l.ROOT_CASE_TASK_ID is null) or dbms_lob.compare(r.COMPOSITION_JSON,l.COMPOSITION_JSON)!=0 then raise_application_error(-20886,'STORE_CUSTODY_FULL_ACCEPTED_DEPARTED_SOURCE_REQUIRED');end if;
  select count(*)into n from RRL_STORE_LOAD_CUSTODY where RECEIPT_OPERATION_ID=p_receipt;
  if n>0 then raise_application_error(-20886,'STORE_CUSTODY_ALREADY_RELEASED');end if;
  select count(*)into n from RRL_STORE_RECEIPT_LINE where OPERATION_ID=p_receipt and(ACCEPTED_BASE_QTY!=SHIPPED_BASE_QTY or MISSING_BASE_QTY!=0 or REFUSED_BASE_QTY!=0 or DAMAGED_BASE_QTY!=0 or REPORTED_EXTRA_BASE_QTY!=0);
  if n>0 then raise_application_error(-20886,'STORE_CUSTODY_DISCREPANCY_REMAINS');end if;
  p_domain:=json_object_t();p_domain.put('receipt_operation_id',p_receipt);p_domain.put('load_operation_id',r.LOAD_OPERATION_ID);p_domain.put('uid',nvl(l.ROOT_UID,'CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(l.ROOT_CASE_TASK_ID)));p_domain.put('warehouse_id',l.WARE_ID);
 end;
 procedure release_accepted(p_receipt varchar2,p_actor varchar2)is
  op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');d json_object_t;load_id varchar2(100);now_value timestamp with time zone;
 begin
  describe_source(p_receipt,d);load_id:=d.get_string('load_operation_id');
  select RECEIVED_AT into now_value from RRL_STORE_RECEIPT_FACT where OPERATION_ID=p_receipt;
  insert into RRL_STORE_LOAD_CUSTODY(OPERATION_ID,RECEIPT_OPERATION_ID,LOAD_OPERATION_ID,RELEASED_AT,RELEASED_BY)values(op,p_receipt,load_id,now_value,p_actor);
  update RRL_TT_HU_LOAD_FACT set CUSTODY_RELEASED_AT=now_value,CUSTODY_RELEASE_OPERATION_ID=op where LOAD_OPERATION_ID=load_id and CUSTODY_RELEASED_AT is null and CUSTODY_RELEASE_OPERATION_ID is null;
  if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: final store custody');end if;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();receipt varchar2(100):=d.get_object('source').get_string('receipt_operation_id');
 begin
  assert_scope(receipt,d.get_string('actor'));describe_source(receipt,v);
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  declare_receipt(receipt,v.get_string('load_operation_id'),v.get_string('uid'),r,p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);receipt varchar2(100):=d.get_object('source').get_string('receipt_operation_id');v json_object_t;plan clob;fresh json_object_t;op varchar2(100):=d.get_string('operation_id');j json_object_t:=json_object_t();
 begin
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  assert_scope(receipt,p_actor);describe_source(receipt,fresh);
  if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: final receipt custody');end if;
  release_accepted(receipt,p_actor);
  j.put('operation_id',d.get_string('operation_id'));j.put('receipt_operation_id',receipt);j.put('load_operation_id',v.get_string('load_operation_id'));j.put('stock_changed',false);j.put('original_departure_retained',true);j.put('custody','STORE');p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_DISPOSITION as
 function nonnegative(p_text varchar2) return number is
 begin
  if regexp_like(p_text,'^0{1,18}([.]0{1,9})?$','c') then return 0;end if;
  return RRL_STOCK_MATH.quantity(p_text);
 end;
 function count_value(x json_object_t,p_name varchar2) return number is qty number:=0;
 begin
  if x.has(p_name) then qty:=nonnegative(x.get_string(p_name));end if;
  if qty is null or qty<0 then raise_application_error(-20886,'STORE_DISPOSITION_NONNEGATIVE_QTY_REQUIRED');end if;return qty;
 end;
 procedure resolve_counts(p_snapshot clob,p_metadata clob,p_lines out json_array_t,p_has_issue out boolean) is
  tree json_object_t:=json_object_t.parse(p_snapshot);m json_object_t:=json_object_t.parse(p_metadata);nodes json_array_t:=tree.get_array('nodes');observed json_array_t:=json_array_t();x json_object_t;o json_object_t;line_json json_object_t;
  type observed_map is table of json_object_t index by varchar2(200);by_uid observed_map;
  uid_text varchar2(200);article_text varchar2(160);unit_text varchar2(20);shipped number;accepted number;missing number;refused number;damaged number;extra_no number;scale_no number;line_no number:=0;reason_text varchar2(32767);
 begin
  p_lines:=json_array_t();p_has_issue:=false;
  if m.has('observations') then
   if not m.get('observations').is_array then raise_application_error(-20886,'STORE_DISPOSITION_ARRAY_REQUIRED');end if;
   observed:=m.get_array('observations');
  end if;
  if observed.get_size>200 then raise_application_error(-20881,'STORE_DISPOSITION_LINE_BOUND_200');end if;
  for i in 0..observed.get_size-1 loop
   o:=treat(observed.get(i) as json_object_t);uid_text:=o.get_string('lot_uid');
   if uid_text is null or by_uid.exists(uid_text) then raise_application_error(-20886,'STORE_DISPOSITION_DUPLICATE_OR_MISSING_LEAF');end if;by_uid(uid_text):=o;
  end loop;
  for i in 0..nodes.get_size-1 loop
   x:=treat(nodes.get(i) as json_object_t);
   if x.get_string('kind')='STOCK' then
    line_no:=line_no+1;uid_text:=x.get_string('uid');article_text:=x.get_string('article');unit_text:=x.get_string('base_uom');shipped:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));
    if observed.get_size=0 then accepted:=shipped;missing:=0;refused:=0;damaged:=0;extra_no:=0;
    else
     if not by_uid.exists(uid_text) then raise_application_error(-20886,'STORE_DISPOSITION_COMPLETE_LEAF_COVERAGE_REQUIRED');end if;
     o:=by_uid(uid_text);accepted:=count_value(o,'accepted');missing:=count_value(o,'missing');refused:=count_value(o,'refused');damaged:=count_value(o,'damaged');extra_no:=count_value(o,'extra');
    end if;
    if shipped is null or shipped<=0 or accepted+missing+refused+damaged!=shipped then raise_application_error(-20886,'STORE_DISPOSITION_TOTAL_MISMATCH');end if;
    select BASE_SCALE into scale_no from RRL_STOCK_UOM_CONVERSION where ARTICUL=article_text and INPUT_UOM=unit_text and BASE_UOM=unit_text
     and POLICY_VERSION=(select max(POLICY_VERSION) from RRL_STOCK_UOM_CONVERSION where ARTICUL=article_text and INPUT_UOM=unit_text and BASE_UOM=unit_text);
    RRL_STOCK_MATH.assert_base(accepted,scale_no);RRL_STOCK_MATH.assert_base(missing,scale_no);RRL_STOCK_MATH.assert_base(refused,scale_no);RRL_STOCK_MATH.assert_base(damaged,scale_no);RRL_STOCK_MATH.assert_base(extra_no,scale_no);
    p_has_issue:=p_has_issue or missing>0 or refused>0 or damaged>0 or extra_no>0;
    line_json:=json_object_t();line_json.put('line_no',line_no);line_json.put('lot_uid',uid_text);line_json.put('article',article_text);line_json.put('base_uom',unit_text);
    line_json.put('shipped',RRL_STOCK_PLAN_HELPER.decimal_text(shipped));line_json.put('accepted',RRL_STOCK_PLAN_HELPER.decimal_text(accepted));line_json.put('missing',RRL_STOCK_PLAN_HELPER.decimal_text(missing));line_json.put('refused',RRL_STOCK_PLAN_HELPER.decimal_text(refused));line_json.put('damaged',RRL_STOCK_PLAN_HELPER.decimal_text(damaged));line_json.put('extra',RRL_STOCK_PLAN_HELPER.decimal_text(extra_no));p_lines.append(line_json);
   end if;
  end loop;
  if observed.get_size>0 and observed.get_size!=line_no then raise_application_error(-20886,'STORE_DISPOSITION_FOREIGN_LEAF');end if;
  reason_text:=m.get_string('case_note');
  if reason_text is not null and lengthb(reason_text)>2000 then raise_application_error(-20886,'STORE_CASE_NOTE_TOO_LONG');end if;
  if p_has_issue and trim(reason_text) is null then raise_application_error(-20886,'STORE_DISCREPANCY_REASON_REQUIRED');end if;
 exception when no_data_found then raise_application_error(-20886,'STORE_DISPOSITION_BASE_POLICY_REQUIRED');
 end;
 procedure declare_rows(p_operation varchar2,p_lines json_array_t,p_has_issue boolean,r in out nocopy json_array_t) is x json_object_t;
  procedure obligation(p_index number,p_kind varchar2,p_qty varchar2) is
  begin if nonnegative(p_qty)>0 then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_DELIVERY_OBLIGATION',p_operation||':'||RRL_STOCK_PLAN_HELPER.decimal_text(p_index)||':'||p_kind);end if;end;
 begin
  if p_has_issue then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_DISCREPANCY_CASE',p_operation);end if;
  for i in 0..p_lines.get_size-1 loop x:=treat(p_lines.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RECEIPT_LINE',p_operation||':'||RRL_STOCK_PLAN_HELPER.decimal_text(i+1));
   obligation(i+1,'MISSING_INVESTIGATION',x.get_string('missing'));obligation(i+1,'REFUSED_RETURN_DECISION',x.get_string('refused'));obligation(i+1,'DAMAGED_RETURN_DECISION',x.get_string('damaged'));obligation(i+1,'EXCESS_REVIEW',x.get_string('extra'));
  end loop;
 end;
 procedure persist(p_operation varchar2,p_domain json_object_t,p_actor varchar2,p_result out json_array_t) is
  lines json_array_t:=p_domain.get_array('disposition');x json_object_t;line_no number;uid_text varchar2(200);article_text varchar2(160);unit_text varchar2(20);shipped number;accepted number;missing number;refused number;damaged number;extra_no number;load_op varchar2(100):=p_domain.get_string('load_operation_id');addr_text varchar2(255):=p_domain.get_string('store_address');reason_text varchar2(2000):=p_domain.get_string('case_note');
  procedure obligation(p_kind varchar2,p_qty number) is
  begin if p_qty>0 then insert into RRL_STORE_DELIVERY_OBLIGATION(CASE_ID,LINE_NO,KIND,BASE_QTY,BASE_UOM)values(p_operation,line_no,p_kind,p_qty,unit_text);end if;end;
 begin
  if p_domain.get_boolean('has_discrepancy') then
   insert into RRL_STORE_DISCREPANCY_CASE(CASE_ID,LOAD_OPERATION_ID,STORE_ADDR,REASON_TEXT,REPORTED_BY)values(p_operation,load_op,addr_text,reason_text,p_actor);
  end if;
  p_result:=json_array_t();
  for i in 0..lines.get_size-1 loop
   x:=treat(lines.get(i) as json_object_t);line_no:=x.get_number('line_no');uid_text:=x.get_string('lot_uid');article_text:=x.get_string('article');unit_text:=x.get_string('base_uom');
   shipped:=RRL_STOCK_MATH.quantity(x.get_string('shipped'));accepted:=nonnegative(x.get_string('accepted'));missing:=nonnegative(x.get_string('missing'));refused:=nonnegative(x.get_string('refused'));damaged:=nonnegative(x.get_string('damaged'));extra_no:=nonnegative(x.get_string('extra'));
   insert into RRL_STORE_RECEIPT_LINE(OPERATION_ID,LINE_NO,LOT_UID,ARTICLE,BASE_UOM,SHIPPED_BASE_QTY,ACCEPTED_BASE_QTY,MISSING_BASE_QTY,REFUSED_BASE_QTY,DAMAGED_BASE_QTY,REPORTED_EXTRA_BASE_QTY)
    values(p_operation,line_no,uid_text,article_text,unit_text,shipped,accepted,missing,refused,damaged,extra_no);
   obligation('MISSING_INVESTIGATION',missing);obligation('REFUSED_RETURN_DECISION',refused);obligation('DAMAGED_RETURN_DECISION',damaged);obligation('EXCESS_REVIEW',extra_no);
   x.put('accepted_quantity',x.get_string('accepted'));p_result.append(x);
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_RECEIPT_CMD as

 procedure assert_input(m json_object_t,v in out nocopy json_object_t) is scan_text varchar2(200):=m.get_string('scan_place');root_node json_object_t;proof json_object_t;

 begin

  if v.get_boolean('already_received') then raise_application_error(-20886,'STORE_PLACE_ALREADY_RECEIVED');end if;

  if v.get_string('mode') is null or v.get_string('mode') not in('BARCODE','WEIGHT_PHOTO') then raise_application_error(-20886,'STORE_RECEIPT_MODE_UNSUPPORTED');end if;

  if v.get_boolean('requires_marked_recipient_flow') then RRL_STORE_MARK_CORE.verify_scans(v,m,proof);v.put('marked_unit_proof',proof);elsif m.has('unit_scans')and m.get_array('unit_scans').get_size>0 then raise_application_error(-20886,'STORE_UNEXPECTED_UNIT_SCANS');end if;

  if not m.has('before_cameras') or m.get_boolean('before_cameras') is null or not m.get_boolean('before_cameras') then raise_application_error(-20886,'STORE_RECEIPT_BEFORE_CAMERAS_REQUIRED');end if;

  if m.get_string('expected_composition_signature') is null or m.get_string('expected_composition_signature')!=v.get_string('composition_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: store receipt manifest signature');end if;

  root_node:=treat(v.get_object('snapshot').get_array('nodes').get(0) as json_object_t);

  if scan_text is null or(scan_text!=v.get_string('root_scan_identifier') and(root_node.get_string('kind')='CASE' or v.get_string('root_sscc') is null or scan_text!=v.get_string('root_sscc'))) then raise_application_error(-20886,'STORE_RECEIPT_PHYSICAL_PLACE_SCAN_REQUIRED');end if;

 end;

 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is

  d json_object_t:=json_object_t.parse(p_request);src json_object_t:=d.get_object('source');m json_object_t:=d.get_object('metadata');

  f json_array_t:=json_array_t();r json_array_t:=json_array_t();v json_object_t;raw_domain clob;load_op varchar2(100):=src.get_string('load_operation_id');addr_text varchar2(255):=src.get_string('store_address');nodes json_array_t;x json_object_t;line_no number:=0;disposition json_array_t;has_issue boolean;weight_proof json_object_t;weight_issue boolean;unit_dispositions json_array_t;unit_value json_object_t;

 begin

  RRL_STOCK_STORE_RECEIPT_READ.describe_load(load_op,d.get_string('actor'),addr_text,raw_domain);v:=json_object_t.parse(raw_domain);assert_input(m,v);RRL_STORE_UNLOAD_CORE.validate_input(m,v);

  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');

  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);

  if v.has('marked_unit_proof')then RRL_STORE_MARK_CORE.declare_rows(v,f,r);end if;

  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STORE.RECEIPT.LOAD:'||load_op);

  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));

  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('trip_id')));

  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',load_op);

  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RECEIPT_FACT',p_operation);
  if m.has('unloading')and not m.get('unloading').is_null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_UNLOAD_START',m.get_object('unloading').get_string('start_operation_id'));end if;

  RRL_STOCK_STORE_CUSTODY_CMD.declare_receipt(p_operation,load_op,v.get_string('root'),r);

  nodes:=v.get_object('snapshot').get_array('nodes');

  for i in 0..nodes.get_size-1 loop

   x:=treat(nodes.get(i) as json_object_t);

   if x.get_string('kind')='STOCK' then

    line_no:=line_no+1;RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RECEIPT_LINE',p_operation||':'||RRL_STOCK_PLAN_HELPER.decimal_text(line_no));

   end if;

  end loop;

  if line_no=0 then raise_application_error(-20886,'STORE_RECEIPT_PHYSICAL_LINES_REQUIRED');end if;

  RRL_STOCK_STORE_DISPOSITION.resolve_counts(v.get_object('snapshot').to_clob,m.to_clob,disposition,has_issue);

  RRL_STOCK_STORE_WEIGHT_CORE.resolve_weight(v.to_clob,m.to_clob,d.get_string('actor'),weight_proof,weight_issue);

  has_issue:=has_issue or weight_issue;

  if v.has('marked_unit_proof')then

   RRL_STORE_MARK_CORE.resolve_disposition(v.get_object('marked_unit_proof'),m,disposition,unit_dispositions);v.put('marked_unit_dispositions',unit_dispositions);

   for i in 0..unit_dispositions.get_size-1 loop unit_value:=treat(unit_dispositions.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RECEIPT_UNIT',p_operation||':'||unit_value.get_string('key'));end loop;

  end if;

  if weight_proof is null then v.put_null('weight');else v.put('weight',weight_proof);end if;

  RRL_STOCK_STORE_WEIGHT_CORE.declare_rows(p_operation,weight_proof,r);

  v.put('disposition',disposition);v.put('has_discrepancy',has_issue);v.put('case_note',m.get_string('case_note'));

  RRL_STOCK_STORE_DISPOSITION.declare_rows(p_operation,disposition,has_issue,r);

  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;

 end;

 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is

  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');op varchar2(100):=d.get_string('operation_id');plan clob;v json_object_t;fresh clob;now_v json_object_t;

  load_op varchar2(100);addr_text varchar2(255);root_text varchar2(200);signature_text varchar2(64);version_no number;trip_no number;n number;tree clob;j json_object_t:=json_object_t();lines json_array_t;state_text varchar2(30);fresh_disposition json_array_t;has_issue boolean;fresh_weight json_object_t;weight_issue boolean;fresh_units json_array_t;

 begin

  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');

  load_op:=v.get_string('load_operation_id');addr_text:=v.get_string('store_address');trip_no:=v.get_number('trip_id');

  select ID into n from RRL_TRANSPORT_TASK where ID=trip_no for update;

  select TT_ID into n from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=load_op for update;

  if n!=trip_no then raise_application_error(-20890,'CLOSURE_CHANGED: store receipt trip');end if;

  RRL_STOCK_STORE_RECEIPT_READ.describe_load(load_op,p_actor,addr_text,fresh);now_v:=json_object_t.parse(fresh);

  if now_v.get_string('composition_signature')!=v.get_string('composition_signature') or now_v.get_number('policy_version')!=v.get_number('policy_version') or now_v.get_string('mode')!=v.get_string('mode') or now_v.get_boolean('requires_marked_recipient_flow')!=v.get_boolean('requires_marked_recipient_flow') then raise_application_error(-20890,'CLOSURE_CHANGED: store receipt configuration or load');end if;

  assert_input(m,now_v);RRL_STORE_UNLOAD_CORE.validate_input(m,now_v);

  if v.has('marked_unit_proof')and(not now_v.has('marked_unit_proof')or dbms_lob.compare(v.get_object('marked_unit_proof').to_clob,now_v.get_object('marked_unit_proof').to_clob)!=0)then raise_application_error(-20890,'CLOSURE_CHANGED: store marked unit proof');end if;

  RRL_STOCK_STORE_DISPOSITION.resolve_counts(now_v.get_object('snapshot').to_clob,m.to_clob,fresh_disposition,has_issue);

  if dbms_lob.compare(fresh_disposition.to_clob,v.get_array('disposition').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: store disposition');end if;

  RRL_STOCK_STORE_WEIGHT_CORE.resolve_weight(now_v.to_clob,m.to_clob,p_actor,fresh_weight,weight_issue);

  if fresh_weight is null then

   if not v.get('weight').is_null then raise_application_error(-20890,'CLOSURE_CHANGED: receipt weight evidence');end if;

  elsif v.get('weight').is_null or dbms_lob.compare(fresh_weight.to_clob,v.get_object('weight').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: receipt weight evidence');end if;

  has_issue:=has_issue or weight_issue;

  if v.has('marked_unit_proof')then

   RRL_STORE_MARK_CORE.resolve_disposition(now_v.get_object('marked_unit_proof'),m,fresh_disposition,fresh_units);

   if dbms_lob.compare(fresh_units.to_clob,v.get_array('marked_unit_dispositions').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: store unit disposition');end if;

  end if;

  state_text:=case when has_issue then 'DISCREPANCY' else 'ACCEPTED' end;

  root_text:=v.get_string('root');signature_text:=v.get_string('composition_signature');version_no:=v.get_number('policy_version');tree:=v.get_object('snapshot').to_clob;

  insert into RRL_STORE_RECEIPT_FACT(OPERATION_ID,LOAD_OPERATION_ID,STORE_ADDR,ROOT_KEY,POLICY_VERSION,RECEIPT_STATE,CAMERA_CONFIRMED,COMPOSITION_SIGNATURE,COMPOSITION_JSON,RECEIVED_BY)

   values(op,load_op,addr_text,root_text,version_no,state_text,1,signature_text,tree,p_actor);

  RRL_STOCK_STORE_DISPOSITION.persist(op,v,p_actor,lines);

  if v.has('marked_unit_dispositions')then RRL_STORE_MARK_CORE.persist(op,load_op,v.get_array('marked_unit_dispositions'),p_actor);j.put('unit_dispositions',v.get_array('marked_unit_dispositions'));end if;

  RRL_STOCK_STORE_WEIGHT_CORE.persist(op,fresh_weight,p_actor);

  if state_text='ACCEPTED'then RRL_STOCK_STORE_CUSTODY_CMD.release_accepted(op,p_actor);j.put('load_custody_released',true);else j.put('load_custody_released',false);end if;

  if fresh_weight is not null then j.put('weight',fresh_weight);end if;

  if v.has('marked_unit_proof')then j.put('physical_unit_count',v.get_object('marked_unit_proof').get_number('physical_unit_count'));j.put('original_unit_signature',v.get_object('marked_unit_proof').get_string('unit_signature'));j.put('mark_scan_confirmed',true);j.put('regulatory_ack_verified',false);end if;

  RRL_STORE_UNLOAD_CORE.capture(p_request,p_actor);
  if m.has('unloading')and not m.get('unloading').is_null then j.put('unloading',m.get_object('unloading'));end if;
  j.put('operation_id',op);j.put('load_operation_id',load_op);j.put('store_address',addr_text);j.put('root',root_text);j.put('status',state_text);if has_issue then j.put('discrepancy_case_id',op);end if;j.put('accepted_lines',lines);j.put('warehouse_stock_consumed_again',false);j.put('government_ack_created',false);p_result:=j.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_RECEIPT_READ as
 procedure require_receiver(p_actor varchar2,p_store varchar2) is n number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'store_receipt_confirm')!=1 then raise_application_error(-20882,'STORE_RECEIPT_FORBIDDEN');end if;
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0;
  if n!=1 then raise_application_error(-20882,'STORE_CURRENT_RECEIVER_REQUIRED');end if;
  select count(*) into n from RUSERS where ID=p_actor and upper(trim(USER_GROUP))='GLOBAL_ADMIN';
  if n=0 then
   select count(*) into n from RRL_STORE_RECEIPT_USER where USER_ID=p_actor and STORE_ADDR=p_store;
   if n!=1 then raise_application_error(-20882,'STORE_RECEIVER_ADDRESS_BINDING_REQUIRED');end if;
  end if;
 end;
 procedure describe_load(p_load varchar2,p_actor varchar2,p_store varchar2,p_domain out clob) is
  lf RRL_TT_HU_LOAD_FACT%rowtype;policy RRL_STORE_RECEIPT_POLICY%rowtype;n number;members number;
  tree json_object_t;j json_object_t:=json_object_t();root_node json_object_t;nodes clob;ids json_array_t:=json_array_t();physical_boxes json_array_t:=json_array_t();box_json json_object_t;min_box_kg number;box_no number:=0;
 begin
  require_receiver(p_actor,p_store);
  select * into policy from RRL_STORE_RECEIPT_POLICY where STORE_ADDR=p_store;
  select * into lf from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=p_load;
  if lf.STATUS!='DEPARTED' or lf.DEPARTURE_OPERATION_ID is null then raise_application_error(-20886,'STORE_RECEIPT_ACTUAL_DEPARTURE_REQUIRED');end if;
  select count(*) into n from RRL_STOCK_OPERATION where OPERATION_ID=lf.LOAD_OPERATION_ID and STATE='APPLIED';
  if n!=1 then raise_application_error(-20886,'STORE_RECEIPT_COMMITTED_LOAD_REQUIRED');end if;
  select count(*) into n from RRL_STOCK_OPERATION where OPERATION_ID=lf.DEPARTURE_OPERATION_ID and STATE='APPLIED';
  if n!=1 then raise_application_error(-20886,'STORE_RECEIPT_COMMITTED_DEPARTURE_REQUIRED');end if;
  select count(*),sum(case when DESTINATION_ADDR=p_store then 1 else 0 end) into members,n
   from RRL_TT_HU_LOAD_ST where LOAD_OPERATION_ID=p_load and ACTIVE_FLAG=1;
  if members<1 or members>200 or n is null or n!=members then raise_application_error(-20886,'STORE_RECEIPT_FROZEN_SINGLE_DESTINATION_REQUIRED');end if;
  tree:=json_object_t.parse(lf.COMPOSITION_JSON);root_node:=treat(tree.get_array('nodes').get(0) as json_object_t);
  if tree.get_array('nodes').get_size>200 then raise_application_error(-20881,'STORE_RECEIPT_NODE_BOUND_200');end if;
  nodes:=tree.get_array('nodes').to_clob;
  select count(*) into n from json_table(nodes,'$[*]' columns(KIND_NAME varchar2(20) path '$.kind',ARTICLE varchar2(160) path '$.article')) x
   where x.KIND_NAME='STOCK' and(exists(select 1 from RRL_SKU_RECEIPT_PROFILE p where p.ARTICUL=x.ARTICLE)
    or exists(select 1 from RRL_SKU_RECEIPT_POLICY p where p.ARTICUL=x.ARTICLE and p.MARKING_REQUIRED=1));
  j.put('requires_marked_recipient_flow',n>0 or nvl(tree.get_number('physical_unit_count'),1)>0);
  j.put('load_operation_id',p_load);j.put('trip_id',lf.TT_ID);j.put('store_address',p_store);
  j.put('root',tree.get_string('root'));j.put('root_scan_identifier',case when root_node.get_string('kind')='CASE' then root_node.get_string('sscc') else tree.get_string('root') end);
  j.put('root_sscc',root_node.get_string('sscc'));j.put('policy_version',policy.POLICY_VERSION);j.put('mode',policy.RECEIPT_MODE);
  j.put('snapshot',tree);j.put('composition_signature',rawtohex(sys.dbms_crypto.hash(tree.to_clob,sys.dbms_crypto.hash_sh256)));
  j.put('shipping_gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(lf.GROSS_WEIGHT_KG));
  select count(*) into n from RRL_STORE_RECEIPT_FACT where LOAD_OPERATION_ID=p_load;j.put('already_received',n>0);
  for r in(select SBORKA_PALLET_ID from RRL_TT_HU_LOAD_ST where LOAD_OPERATION_ID=p_load and ACTIVE_FLAG=1 order by SBORKA_PALLET_ID)loop ids.append(r.SBORKA_PALLET_ID);end loop;j.put('st_ids',ids);
  for box in(select BOX_UID,BOX_CONTENT_VERSION,GROSS_WEIGHT_KG,MEASUREMENT_ORIGIN,MEASUREMENT_REF,RECORDED_BY,SCAN_IDENTIFIER,CASE_BOX_TASK_ID,FINAL_SCALE_CAPTURE,WAREHOUSE_QC_OPERATION,TARE_WEIGHT_KG,NET_WEIGHT_KG,DEVICE_MODE,COMPOSITION_SIGNATURE,SIGNATURE_VERSION,MEASURED_CONTENT_VERSION,COVERAGE_COMPLETE from RRL_TT_LOAD_BOX_WEIGHT where LOAD_OPERATION_ID=p_load order by BOX_UID fetch first 201 rows only)loop
   box_no:=box_no+1;if box_no>200 then raise_application_error(-20881,'STORE_PHYSICAL_BOX_BOUND_200');end if;
   if min_box_kg is null then min_box_kg:=box.GROSS_WEIGHT_KG;else min_box_kg:=least(min_box_kg,box.GROSS_WEIGHT_KG);end if;
   box_json:=json_object_t();box_json.put('box_uid',box.BOX_UID);box_json.put('content_version',box.BOX_CONTENT_VERSION);box_json.put('gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(box.GROSS_WEIGHT_KG));
   box_json.put('origin',box.MEASUREMENT_ORIGIN);box_json.put('measurement_ref',box.MEASUREMENT_REF);box_json.put('recorded_by',box.RECORDED_BY);box_json.put('scan_identifier',box.SCAN_IDENTIFIER);box_json.put('coverage_complete',box.COVERAGE_COMPLETE=1);
   if box.CASE_BOX_TASK_ID is not null then
    box_json.put('case_task_id',box.CASE_BOX_TASK_ID);box_json.put('sscc',box.SCAN_IDENTIFIER);box_json.put('final_scale_capture',box.FINAL_SCALE_CAPTURE);box_json.put('warehouse_qc_operation',box.WAREHOUSE_QC_OPERATION);
    box_json.put('tare_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(box.TARE_WEIGHT_KG));box_json.put('net_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(box.NET_WEIGHT_KG));
    box_json.put('device_mode',box.DEVICE_MODE);box_json.put('composition_signature',box.COMPOSITION_SIGNATURE);box_json.put('signature_version',box.SIGNATURE_VERSION);box_json.put('measured_content_version',box.MEASURED_CONTENT_VERSION);
   end if;physical_boxes.append(box_json);
  end loop;
  j.put('physical_boxes',physical_boxes);j.put('shipping_weight_tolerance_kg',RRL_STOCK_PLAN_HELPER.decimal_text(min_box_kg/2));
  if j.get_boolean('requires_marked_recipient_flow')and not j.get_boolean('already_received')then j.put('marked_unit_control',json_object_t.parse(RRL_STORE_MARK_CORE.preview(j)));j.put('marked_partial_control',true);end if;
  p_domain:=j.to_clob;
 exception when no_data_found then raise_application_error(-20886,'STORE_RECEIPT_LOAD_OR_EXPLICIT_POLICY_NOT_FOUND');
 end;
 function preview_json(p_load varchar2,p_actor varchar2,p_store varchar2) return clob is result clob;
 begin describe_load(p_load,p_actor,p_store,result);return result;end;
end;
/


CREATE OR REPLACE PACKAGE BODY          "RRL_STOCK_STORE_RETURN_CMD" as
 procedure assert_actor(p_actor varchar2)is n number;
 begin select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'store_return_approve')=1;if n!=1 then raise_application_error(-20882,'STORE_RETURN_CURRENT_APPROVER_REQUIRED');end if;end;
 procedure describe_return(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);s json_object_t:=d.get_object('source');m json_object_t:=d.get_object('metadata');
 v_receipt varchar2(100):=s.get_string('receipt_operation_id');v_line number:=s.get_number('line_no');
 v_qty number;v_used number;v_basis varchar2(10):=nvl(m.get_string('return_basis'),'ACCEPTED');v_limit number;v_units number;v_scale number;v_destination varchar2(20):=m.get_string('disposition');v_reason varchar2(32767):=m.get_string('reason');
 v_reference varchar2(32767):=m.get_string('decision_reference');v_good boolean:=m.get_boolean('complete_good_box');
 original RRL_STORE_RECEIPT_LINE%rowtype;v_store varchar2(255);v_load varchar2(100);selected_units clob;source_cell varchar2(60);reuse_source json_object_t;
 begin
 if RRL_HAS_WRIGHT(p_actor,'store_return_approve')!=1 then raise_application_error(-20882,'STORE_RETURN_SUPPLY_CHAIN_APPROVAL_REQUIRED');end if;
 if v_line is null or v_line!=trunc(v_line) or v_line<1 then raise_application_error(-20886,'STORE_RETURN_ORIGINAL_LINE_REQUIRED');end if;
 if v_destination is null or v_destination not in('REUSE','SUPPLIER','DISPOSAL') or trim(v_reason) is null or lengthb(v_reason)>2000 or trim(v_reference) is null or lengthb(v_reference)>255 then raise_application_error(-20886,'STORE_RETURN_REASON_DESTINATION_DECISION_REQUIRED');end if;
 if v_basis not in('ACCEPTED','REFUSED','DAMAGED')then raise_application_error(-20886,'STORE_RETURN_BASIS_REQUIRED');end if;
 if v_basis!='ACCEPTED'and v_destination='REUSE'then raise_application_error(-20886,'STORE_RETURN_EXCEPTION_REUSE_INSPECTION_REQUIRED');end if;
 if v_destination='REUSE' and (v_good is null or not v_good) then raise_application_error(-20886,'STORE_RETURN_REUSE_COMPLETE_GOOD_BOX_REQUIRED');end if;
 select * into original from RRL_STORE_RECEIPT_LINE where OPERATION_ID=v_receipt and LINE_NO=v_line;
 select STORE_ADDR,LOAD_OPERATION_ID,nvl(json_value(COMPOSITION_JSON,'$.physical_unit_count' returning number),1) into v_store,v_load,v_units from RRL_STORE_RECEIPT_FACT where OPERATION_ID=v_receipt;

 v_qty:=RRL_STOCK_MATH.quantity(m.get_string('quantity'));
 select BASE_SCALE into v_scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=original.ARTICLE and INPUT_UOM=original.BASE_UOM and BASE_UOM=original.BASE_UOM and POLICY_VERSION=(select max(POLICY_VERSION) from RRL_STOCK_UOM_CONVERSION where ARTICUL=original.ARTICLE and INPUT_UOM=original.BASE_UOM and BASE_UOM=original.BASE_UOM);
 RRL_STOCK_MATH.assert_base(v_qty,v_scale);
 select nvl(sum(BASE_QTY),0) into v_used from RRL_STORE_RETURN_APPROVAL where RECEIPT_OPERATION_ID=v_receipt and LINE_NO=v_line and RETURN_BASIS=v_basis;
 case v_basis when 'ACCEPTED'then v_limit:=original.ACCEPTED_BASE_QTY;when 'REFUSED'then v_limit:=original.REFUSED_BASE_QTY;when 'DAMAGED'then v_limit:=original.DAMAGED_BASE_QTY;end case;
 if v_qty+v_used>v_limit then raise_application_error(-20886,'STORE_RETURN_SOURCE_DISPOSITION_QUANTITY_EXCEEDED');end if;
 if RRL_STOCK_QC_MARK.required_for_article(original.ARTICLE)=1 then v_units:=greatest(v_units,1);end if;
 p_domain:=json_object_t();
 if v_destination='REUSE'then
  RRL_STOCK_RETURN_REUSE.describe_source(original.LOT_UID,original.ARTICLE,original.BASE_UOM,v_qty,reuse_source);
  p_domain.put('reuse_source',reuse_source);
 end if;

 if v_units>0 then
  if not m.has('unit_keys')then raise_application_error(-20886,'STORE_RETURN_EXACT_UNIT_SELECTION_REQUIRED');end if;
  selected_units:=RRL_STORE_RETURN_UNIT_CORE.select_disposition_units(v_receipt,original.LOT_UID,original.BASE_UOM,v_qty,m.get_array('unit_keys').to_clob,v_basis);
  select json_value(COMPOSITION_JSON,'$.cell')into source_cell from RRL_STORE_RECEIPT_FACT where OPERATION_ID=v_receipt;
  p_domain.put('return_units',json_array_t.parse(selected_units));p_domain.put('source_cell',source_cell);
 elsif m.has('unit_keys')and m.get_array('unit_keys').get_size>0 then raise_application_error(-20886,'STORE_RETURN_UNEXPECTED_UNIT_SELECTION');end if;
if v_basis!='ACCEPTED'then p_domain.put('return_basis',v_basis);end if;
 p_domain.put('receipt_operation_id',v_receipt);p_domain.put('line_no',v_line);p_domain.put('load_operation_id',v_load);p_domain.put('store_address',v_store);
 p_domain.put('lot_uid',original.LOT_UID);p_domain.put('article',original.ARTICLE);p_domain.put('base_uom',original.BASE_UOM);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));
 p_domain.put('previously_approved',RRL_STOCK_PLAN_HELPER.decimal_text(v_used));p_domain.put('disposition',v_destination);p_domain.put('reason',v_reason);p_domain.put('decision_reference',v_reference);
 if v_good then p_domain.put('complete_good_box',1);else p_domain.put('complete_good_box',0);end if;
 exception when no_data_found then raise_application_error(-20886,'STORE_RETURN_ORIGINAL_RECEIPT_OR_UOM_NOT_FOUND');
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();units json_array_t;x json_object_t;
 begin
 describe_return(p_request,d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RECEIPT_LINE',v.get_string('receipt_operation_id')||':'||RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('line_no')));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_APPROVAL',p_operation);
 if v.has('return_units')then
  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('lot_uid'),v.get_string('article'),v.get_string('source_cell'),null);
  units:=v.get_array('return_units');for i in 0..units.get_size-1 loop x:=treat(units.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',x.get_string('key'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_UNIT',p_operation||':'||x.get_string('key'));end loop;
 end if;
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');v_receipt varchar2(100):=d.get_object('source').get_string('receipt_operation_id');
 v_line number:=d.get_object('source').get_number('line_no');v_dummy number;plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_lot varchar2(200);v_article varchar2(160);v_unit varchar2(20);v_qty number;v_destination varchar2(20);v_reason varchar2(2000);v_reference varchar2(255);v_good number;v_basis varchar2(10);
 begin
 select LINE_NO into v_dummy from RRL_STORE_RECEIPT_LINE where OPERATION_ID=v_receipt and LINE_NO=v_line for update;
 describe_return(p_request,p_actor,fresh);
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'STORE_RETURN_SOURCE_OR_APPROVAL_CHANGED');end if;
 v_basis:=nvl(v.get_string('return_basis'),'ACCEPTED');
 v_lot:=v.get_string('lot_uid');v_article:=v.get_string('article');v_unit:=v.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));
 v_destination:=v.get_string('disposition');v_reason:=v.get_string('reason');v_reference:=v.get_string('decision_reference');v_good:=v.get_number('complete_good_box');
 insert into RRL_STORE_RETURN_APPROVAL(OPERATION_ID,RECEIPT_OPERATION_ID,LINE_NO,LOT_UID,ARTICLE,BASE_UOM,BASE_QTY,DISPOSITION,REASON_TEXT,DECISION_REFERENCE,COMPLETE_GOOD_BOX,APPROVED_BY,RETURN_BASIS)
 values(op,v_receipt,v_line,v_lot,v_article,v_unit,v_qty,v_destination,v_reason,v_reference,v_good,p_actor,v_basis);
 if v.has('return_units')then
  RRL_STORE_RETURN_UNIT_CORE.persist(op,v_receipt,v_lot,v.get_string('source_cell'),v.get_array('return_units').to_clob);j.put('physical_unit_count',v.get_array('return_units').get_size);
 end if;
 if v_basis!='ACCEPTED'then j.put('return_basis',v_basis);j.put('customer_accepted_quantity_changed',false);end if;
 j.put('operation_id',op);j.put('receipt_operation_id',v_receipt);j.put('line_no',v_line);j.put('quantity',v.get_string('quantity'));j.put('base_uom',v_unit);j.put('disposition',v_destination);
 j.put('status','WAITING_SAP_AND_LOGISTICS');j.put('warehouse_stock_changed',false);j.put('sap_verified',false);j.put('government_ack_created',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_RETURN_CUST_CMD as
 procedure assert_scope(p_request clob,p_actor varchar2)is
  d json_object_t:=json_object_t.parse(p_request);source json_object_t:=d.get_object('source');tr varchar2(100);addr_text varchar2(255);driver number;handed_by varchar2(50);n number;
 begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0;
  if n!=1 then raise_application_error(-20882,'STORE_RETURN_CURRENT_ACTIVE_ACTOR_REQUIRED');end if;
  if d.get_string('command_type')='STORE_RETURN_HANDOVER'then
   tr:=source.get_string('transport_operation_id');
   select STORE_ADDR into addr_text from RRL_STORE_RETURN_TRANSPORT where OPERATION_ID=tr;
   if RRL_HAS_WRIGHT(p_actor,'store_return_handover')!=1 then raise_application_error(-20882,'STORE_RETURN_HANDOVER_FORBIDDEN');end if;
   RRL_STOCK_STORE_RECEIPT_READ.require_receiver(p_actor,addr_text);
  else
   tr:=source.get_string('handover_operation_id');
   select t.DRIVER_ID,h.HANDED_BY into driver,handed_by from RRL_STORE_RETURN_HANDOVER h join RRL_STORE_RETURN_TRANSPORT t on t.OPERATION_ID=h.TRANSPORT_OPERATION_ID where h.OPERATION_ID=tr;
   select count(*)into n from RRL_TRANSPORT_DRIVER_USER b join RUSERS u on u.ID=b.USER_ID where b.DRIVER_ID=driver and b.USER_ID=p_actor and b.ACTIVE=1 and nvl(u.DELETED,0)=0 and upper(trim(u.USER_GROUP))!='GLOBAL_ADMIN';
   if n!=1 or handed_by=p_actor or RRL_HAS_WRIGHT(p_actor,'driver_return_accept')!=1 then raise_application_error(-20882,'STORE_RETURN_CURRENT_SEPARATE_BOUND_DRIVER_REQUIRED');end if;
  end if;
 exception when no_data_found then raise_application_error(-20882,'STORE_RETURN_CURRENT_CUSTODY_SCOPE_REQUIRED');
 end;
 procedure describe_context(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);s json_object_t:=d.get_object('source');m json_object_t:=d.get_object('metadata');v_kind varchar2(80):=d.get_string('command_type');
 v_transport varchar2(100):=s.get_string('transport_operation_id');v_handover varchar2(100):=s.get_string('handover_operation_id');transport RRL_STORE_RETURN_TRANSPORT%rowtype;handed RRL_STORE_RETURN_HANDOVER%rowtype;approved RRL_STORE_RETURN_APPROVAL%rowtype;
 tt RRL_TRANSPORT_TASK%rowtype;veh RRL_TR_VEHICLE%rowtype;binding RRL_TRANSPORT_DRIVER_USER%rowtype;
 unit_proof clob;n number;v_mass number;v_slots number;v_pallet varchar2(32767);v_outbound_mass number;v_outbound_places number;v_return_mass number;v_return_places number;
 begin
 if v_kind='STORE_RETURN_PICKUP' then select * into handed from RRL_STORE_RETURN_HANDOVER where OPERATION_ID=v_handover;v_transport:=handed.TRANSPORT_OPERATION_ID;end if;
 select * into transport from RRL_STORE_RETURN_TRANSPORT where OPERATION_ID=v_transport;
 select * into approved from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=transport.APPROVAL_OPERATION_ID;
 assert_scope(p_request,p_actor);unit_proof:=RRL_STORE_RETURN_UNIT_CORE.custody_proof(approved.OPERATION_ID,m);
 select * into tt from RRL_TRANSPORT_TASK where ID=transport.TT_ID;
 select * into veh from RRL_TR_VEHICLE where ID=transport.VEHICLE_ID;
 if tt.CONDITION is null or tt.CONDITION!=unistr('\041E\0442\0433\0440\0443\0436\0435\043D') or nvl(tt.DELETED,0)!=0 or tt.TRANSPORT is null or tt.TRANSPORT!=transport.VEHICLE_NUMBER or tt.VODITEL_ID is null or tt.VODITEL_ID!=transport.DRIVER_ID
 or veh.NUM!=transport.VEHICLE_NUMBER or nvl(veh.DELETED,0)!=0 or nvl(veh.BLOCKED,0)!=0 or nvl(veh.WORKING_NOW,0)!=1 or veh.PALLETS is null or veh.MAX_WEIGHT_KG is null then raise_application_error(-20886,'STORE_RETURN_CURRENT_DEPARTED_TRIP_REQUIRED');end if;
 select count(*) into n from RRL_TR_VODITEL where ID=transport.DRIVER_ID and nvl(DELETED,0)=0;
 if n!=1 then raise_application_error(-20886,'STORE_RETURN_CURRENT_ACTIVE_DRIVER_REQUIRED');end if;
 select count(*) into n from RRL_TT_HU_LOAD_FACT where VEHICLE_ID=veh.ID and TT_ID!=tt.ID and STATUS='LOADED';
 if n>0 then raise_application_error(-20886,'STORE_RETURN_VEHICLE_HAS_OTHER_OPEN_LOAD');end if;
 select nvl(sum(GROSS_WEIGHT_KG),0),count(*) into v_outbound_mass,v_outbound_places from RRL_TT_HU_LOAD_FACT where TT_ID=tt.ID and STATUS in('LOADED','DEPARTED')and CUSTODY_RELEASED_AT is null;
 select nvl(sum(GROSS_WEIGHT_KG),0),nvl(sum(PHYSICAL_PLACES),0) into v_return_mass,v_return_places from RRL_STORE_RETURN_TRANSPORT where TT_ID=tt.ID;
 if v_outbound_mass+v_return_mass>veh.MAX_WEIGHT_KG or v_outbound_places+v_return_places>veh.PALLETS then raise_application_error(-20886,'STORE_RETURN_CURRENT_CAPACITY_EXCEEDED');end if;
 if transport.PHYSICAL_PLACES!=1 then raise_application_error(-20886,'STORE_RETURN_MULTI_PLACE_MANIFEST_REQUIRED');end if;
 if v_kind='STORE_RETURN_HANDOVER' then
  if RRL_HAS_WRIGHT(p_actor,'store_return_handover')!=1 then raise_application_error(-20882,'STORE_RETURN_HANDOVER_FORBIDDEN');end if;
  RRL_STOCK_STORE_RECEIPT_READ.require_receiver(p_actor,transport.STORE_ADDR);
  v_pallet:=m.get_string('pallet_identifier');v_mass:=RRL_STOCK_MATH.quantity(m.get_string('gross_weight_kg'));v_slots:=m.get_number('physical_places');
  if trim(v_pallet) is null or lengthb(v_pallet)>200 or v_slots is null or v_slots!=transport.PHYSICAL_PLACES or v_mass>transport.GROSS_WEIGHT_KG then raise_application_error(-20886,'STORE_RETURN_PHYSICAL_PLACE_OR_PLAN_MISMATCH');end if;
  if m.get_string('base_uom') is null or m.get_string('base_uom')!=approved.BASE_UOM or RRL_STOCK_MATH.quantity(m.get_string('quantity'))!=approved.BASE_QTY then raise_application_error(-20886,'STORE_RETURN_FULL_APPROVED_QUANTITY_REQUIRED');end if;
  select count(*) into n from RRL_STORE_RETURN_HANDOVER where TRANSPORT_OPERATION_ID=v_transport;
  if n!=0 then raise_application_error(-20886,'STORE_RETURN_ALREADY_HANDED_OVER');end if;
 else
  if RRL_HAS_WRIGHT(p_actor,'driver_return_accept')!=1 then raise_application_error(-20882,'STORE_RETURN_DRIVER_ACCEPT_FORBIDDEN');end if;
  select * into binding from RRL_TRANSPORT_DRIVER_USER where DRIVER_ID=transport.DRIVER_ID and ACTIVE=1 and USER_ID=p_actor;
  select count(*) into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and upper(trim(USER_GROUP))!='GLOBAL_ADMIN';
  if n!=1 then raise_application_error(-20882,'STORE_RETURN_DEDICATED_DRIVER_REQUIRED');end if;
  if p_actor=handed.HANDED_BY then raise_application_error(-20882,'STORE_RETURN_SEPARATE_HANDOVER_AND_DRIVER_REQUIRED');end if;
  if m.get_string('scan_vehicle') is null or m.get_string('scan_vehicle')!=veh.NUM or m.get_string('scan_pallet') is null or m.get_string('scan_pallet')!=handed.PALLET_IDENTIFIER then raise_application_error(-20886,'STORE_RETURN_DRIVER_VEHICLE_PALLET_SCAN_REQUIRED');end if;
  select count(*) into n from RRL_STORE_RETURN_PICKUP where HANDOVER_OPERATION_ID=v_handover;
  if n!=0 then raise_application_error(-20886,'STORE_RETURN_ALREADY_PICKED_UP');end if;
  v_pallet:=handed.PALLET_IDENTIFIER;v_mass:=handed.GROSS_WEIGHT_KG;v_slots:=handed.PHYSICAL_PLACES;
 end if;
 p_domain:=json_object_t();if approved.RETURN_BASIS!='ACCEPTED'then p_domain.put('return_basis',approved.RETURN_BASIS);end if;p_domain.put('transport_operation_id',v_transport);p_domain.put('approval_operation_id',transport.APPROVAL_OPERATION_ID);p_domain.put('task_id',tt.ID);p_domain.put('vehicle_id',veh.ID);p_domain.put('vehicle_number',veh.NUM);p_domain.put('driver_id',transport.DRIVER_ID);
 p_domain.put('pallet_identifier',v_pallet);p_domain.put('gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_mass));p_domain.put('physical_places',v_slots);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(approved.BASE_QTY));p_domain.put('base_uom',approved.BASE_UOM);
 if unit_proof is not null then p_domain.put('return_unit_proof',json_object_t.parse(unit_proof));end if;
 if v_kind='STORE_RETURN_PICKUP' then p_domain.put('handover_operation_id',v_handover);p_domain.put('binding_version',binding.BINDING_VERSION);end if;
 exception when no_data_found then
  if v_kind='STORE_RETURN_PICKUP' then raise_application_error(-20882,'STORE_RETURN_BOUND_DRIVER_AND_HANDOVER_REQUIRED');else raise_application_error(-20886,'STORE_RETURN_CURRENT_SOURCE_CONFIGURATION_REQUIRED');end if;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();v_kind varchar2(80):=d.get_string('command_type');unit_value json_object_t;unit_wire clob;
 begin
 describe_context(p_request,d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_TRANSPORT',v.get_string('transport_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('task_id')));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('vehicle_id')));
 if v_kind='STORE_RETURN_HANDOVER' then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_HANDOVER',p_operation);
 else
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_HANDOVER',v.get_string('handover_operation_id'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_PICKUP',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_DRIVER_USER',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('driver_id')));
 end if;
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_APPROVAL',v.get_string('approval_operation_id'));
 if v.has('return_unit_proof')then
  unit_wire:=v.get_object('return_unit_proof').get_array('units').to_clob;
  for z in(select K from json_table(unit_wire,'$[*]'columns(K varchar2(64)path '$.key')))loop
   RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',z.K);
  end loop;
 end if;
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');v_kind varchar2(80):=d.get_string('command_type');plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_dummy number;v_trip number;v_transport varchar2(100);v_handover varchar2(100);v_vehicle number;v_driver number;v_binding number;v_plate varchar2(50);v_mass number;v_slots number;v_pallet varchar2(200);
 begin
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
 v_vehicle:=v.get_number('vehicle_id');v_trip:=v.get_number('task_id');
 select ID into v_dummy from RRL_TR_VEHICLE where ID=v_vehicle for update;
 select ID into v_dummy from RRL_TRANSPORT_TASK where ID=v_trip for update;
 describe_context(p_request,p_actor,fresh);
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'STORE_RETURN_CUSTODY_SOURCE_CHANGED');end if;
 v_transport:=v.get_string('transport_operation_id');v_vehicle:=v.get_number('vehicle_id');v_driver:=v.get_number('driver_id');v_plate:=v.get_string('vehicle_number');
 v_mass:=RRL_STOCK_MATH.quantity(v.get_string('gross_weight_kg'));v_slots:=v.get_number('physical_places');v_pallet:=v.get_string('pallet_identifier');
 if v_kind='STORE_RETURN_HANDOVER' then
  insert into RRL_STORE_RETURN_HANDOVER(OPERATION_ID,TRANSPORT_OPERATION_ID,PALLET_IDENTIFIER,GROSS_WEIGHT_KG,PHYSICAL_PLACES,HANDED_BY)values(op,v_transport,v_pallet,v_mass,v_slots,p_actor);
  j.put('custody','STORE_PENDING_DRIVER');
 else
  v_handover:=v.get_string('handover_operation_id');v_binding:=v.get_number('binding_version');
  insert into RRL_STORE_RETURN_PICKUP(OPERATION_ID,HANDOVER_OPERATION_ID,DRIVER_ID,VEHICLE_ID,VEHICLE_NUMBER,BINDING_VERSION,TAKEN_BY)values(op,v_handover,v_driver,v_vehicle,v_plate,v_binding,p_actor);
  j.put('custody','VEHICLE');j.put('handover_operation_id',v_handover);
 end if;
 if v.has('return_unit_proof')then j.put('physical_unit_count',v.get_object('return_unit_proof').get_number('physical_unit_count'));j.put('mark_scan_confirmed',true);end if;
 j.put('operation_id',op);j.put('transport_operation_id',v_transport);j.put('quantity',v.get_string('quantity'));j.put('base_uom',v.get_string('base_uom'));j.put('warehouse_stock_changed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_RETURN_PUT as
 procedure assert_scope(p_receipt varchar2,p_actor varchar2)is n number;
 begin
  select count(*)into n from RRL_STORE_RETURN_RECEIPT r join RUSERS u on u.ID=p_actor where r.OPERATION_ID=p_receipt and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(p_actor,'warehouse_return_place')=1 and(u.WARE_ID=r.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'STORE_RETURN_CURRENT_PLACEMENT_ACTOR_REQUIRED');end if;
 end;
 procedure describe_current(p_receipt varchar2,p_actor varchar2,p_task number,p_domain out json_object_t) is
 receipt RRL_STORE_RETURN_RECEIPT%rowtype;policy RRL_STORE_RETURN_WARE_POLICY%rowtype;
 v_target varchar2(60);v_p number;v_h number;v_unit varchar2(20);v_stock_version number;v_capacity number;v_height number;v_weight number;v_unknown number;n number;v_plan_count number;
 begin
 if RRL_HAS_WRIGHT(p_actor,'warehouse_return_place')!=1 then raise_application_error(-20882,'STORE_RETURN_PLACEMENT_FORBIDDEN');end if;
 select * into receipt from RRL_STORE_RETURN_RECEIPT where OPERATION_ID=p_receipt;
 select count(*) into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and(upper(trim(USER_GROUP))='GLOBAL_ADMIN' or WARE_ID=receipt.WARE_ID);
 if n!=1 then raise_application_error(-20882,'STORE_RETURN_PLACEMENT_WAREHOUSE_BINDING_REQUIRED');end if;
 select * into policy from RRL_STORE_RETURN_WARE_POLICY where WARE_ID=receipt.WARE_ID;
 if receipt.DISPOSITION='REUSE' then
 select nvl(r.PICK_CELL,a.CELL) into v_target from RRL_ARTICULS a left join RRL_RECEIPT_SKU_RULE r on r.ARTICUL=a.ACTICUL and r.WARE_ID=receipt.WARE_ID where a.ACTICUL=receipt.ARTICLE;
 RRL_STOCK_RETURN_REUSE.assert_pick_target(receipt,v_target);
 else v_target:=case receipt.DISPOSITION when 'SUPPLIER' then policy.SUPPLIER_TARGET_CELL else policy.DISPOSAL_TARGET_CELL end;end if;
 if v_target is null or v_target=receipt.RECEIVE_CELL then raise_application_error(-20886,'STORE_RETURN_SEPARATE_TARGET_CONFIGURATION_REQUIRED');end if;
 if receipt.DISPOSITION!='REUSE' then
 select count(*) into n from RRL_CELLS where CELL=v_target and WARE_ID=receipt.WARE_ID and nvl(BLOCKED_FOR_ACCEPT,0)=0 and BLOCKED_FOR_REMAINS=1 and BLOCKED_FOR_POPOLNENIE=1 and nvl(OTBOR,0)=0;
 if n!=1 then raise_application_error(-20886,'STORE_RETURN_BLOCKED_TARGET_REQUIRED');end if;end if;
 select LIMIT_WEIGHT,LIMIT_HEIGHT into v_capacity,v_height from RRL_CELLS where CELL=v_target;
 if nvl(v_height,0)>0 then raise_application_error(-20886,'STORE_RETURN_TARGET_HEIGHT_PROOF_REQUIRED');end if;
 select count(*) into n from RRL_TOPOLOGY_CELL_SLOT slot_record join RRL_TOPOLOGY_CELL cell_record on cell_record.TOPOLOGY_CELL_ID=slot_record.TOPOLOGY_CELL_ID
 join RRL_WAREHOUSE_TOPOLOGY topology on topology.TOPOLOGY_ID=cell_record.TOPOLOGY_ID
 where cell_record.LEGACY_CELL_CODE=v_target and cell_record.WARE_ID=receipt.WARE_ID and cell_record.ACTIVE=1 and slot_record.ACTIVE=1 and topology.STATUS='PUBLISHED';
 if n!=0 then raise_application_error(-20886,'STORE_RETURN_PHYSICAL_SLOT_PLAN_REQUIRED');end if;
 select count(*) into n from RRL_STORE_RETURN_PLACEMENT where RECEIPT_OPERATION_ID=p_receipt;
 if n!=0 then raise_application_error(-20886,'STORE_RETURN_ALREADY_PLACED');end if;
 select REMAIN,HARD_RESERVED_BASE,BASE_UOM,STOCK_VERSION into v_p,v_h,v_unit,v_stock_version from RRL_REMAINS where UID_POLETA=receipt.UID_PALLET and CELL=receipt.RECEIVE_CELL;
 if v_p!=receipt.BASE_QTY or v_h!=0 or v_unit!=receipt.BASE_UOM then raise_application_error(-20886,'STORE_RETURN_WHOLE_UNRESERVED_RECEIVING_STOCK_REQUIRED');end if;
 select count(*) into n from RRL_REMAINS where UID_POLETA=receipt.UID_PALLET and CELL!=receipt.RECEIVE_CELL and(REMAIN!=0 or HARD_RESERVED_BASE!=0);
 if n!=0 then raise_application_error(-20886,'STORE_RETURN_MULTIPLE_SOURCE_CELLS_DENIED');end if;
 select count(*) into v_plan_count from RRL_STORE_RETURN_PUT_PLAN where RECEIPT_OPERATION_ID=p_receipt;
 if v_plan_count>100 then raise_application_error(-20881,'STORE_RETURN_PLAN_HISTORY_BOUND_100');end if;
 select count(*) into n from RRL_STORE_RETURN_PUT_PLAN plan_record join RRL_WAREHOUSE_TASK wt on wt.TASK_ID=plan_record.TASK_ID
 where plan_record.RECEIPT_OPERATION_ID=p_receipt and wt.STATUS!='CANCELLED' and(p_task is null or wt.TASK_ID!=p_task);
 if n!=0 then raise_application_error(-20886,'STORE_RETURN_EXISTING_ACTIVE_PLACEMENT_TASK');end if;
 if nvl(v_capacity,0)>0 then
  select nvl(sum(pp.WEIGHT_BRUTTO),0),nvl(sum(case when pp.WEIGHT_BRUTTO is null then 1 else 0 end),0) into v_weight,v_unknown
  from (
   select r.UID_POLETA UID_PALLET from RRL_REMAINS r where r.CELL=v_target and r.REMAIN>0 and r.UID_POLETA!=receipt.UID_PALLET
   union
   select wt.UID_PALLET from RRL_WAREHOUSE_TASK wt where wt.TO_CELL=v_target and wt.STATUS not in('DONE','CANCELLED')
    and wt.UID_PALLET!=receipt.UID_PALLET and(p_task is null or wt.TASK_ID!=p_task)
  ) occupants join RRL_PALLETS pp on pp.UID_PALLET=occupants.UID_PALLET;
  if v_unknown>0 or v_weight+receipt.GROSS_WEIGHT_KG>v_capacity then raise_application_error(-20886,'STORE_RETURN_TARGET_TOTAL_WEIGHT_EXCEEDED');end if;
 end if;
 p_domain:=json_object_t();p_domain.put('receipt_operation_id',p_receipt);p_domain.put('naklad_id',receipt.NAKLAD_ID);p_domain.put('warehouse_id',receipt.WARE_ID);p_domain.put('uid',receipt.UID_PALLET);p_domain.put('article',receipt.ARTICLE);
 p_domain.put('from_cell',receipt.RECEIVE_CELL);p_domain.put('target_cell',v_target);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(receipt.BASE_QTY));p_domain.put('base_uom',receipt.BASE_UOM);p_domain.put('stock_version',v_stock_version);
 p_domain.put('policy_version',policy.POLICY_VERSION);p_domain.put('disposition',receipt.DISPOSITION);
 exception when no_data_found then raise_application_error(-20886,'STORE_RETURN_PLACEMENT_SOURCE_CONFIGURATION_REQUIRED');
 end;
 procedure declare_rows(p_domain json_object_t,p_resources in out nocopy json_array_t) is
 begin
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_RETURN_RECEIPT',p_domain.get_string('receipt_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_PRIHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(p_domain.get_number('naklad_id')));
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();v_task number;
 begin
 describe_current(d.get_object('source').get_string('receipt_operation_id'),d.get_string('actor'),null,v);
 select RRL_WAREHOUSE_TASK_SQ.nextval into v_task from dual;v.put('task_id',v_task);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 declare_rows(v,r);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_PUT_PLAN',p_operation);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task));
 RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('uid'),v.get_string('article'),v.get_string('from_cell'),v.get_string('target_cell'));
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_receipt varchar2(100);v_task number;v_doc number;v_ware number;v_policy number;v_uid varchar2(200);v_article varchar2(160);v_from varchar2(60);v_to varchar2(60);v_unit varchar2(20);v_qty number;
 begin
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');v_receipt:=v.get_string('receipt_operation_id');v_task:=v.get_number('task_id');
 describe_current(v_receipt,p_actor,null,fresh);fresh.put('task_id',v_task);
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'STORE_RETURN_PLACEMENT_PLAN_SOURCE_CHANGED');end if;
 v_doc:=v.get_number('naklad_id');v_ware:=v.get_number('warehouse_id');v_policy:=v.get_number('policy_version');v_uid:=v.get_string('uid');v_article:=v.get_string('article');v_from:=v.get_string('from_cell');v_to:=v.get_string('target_cell');v_unit:=v.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));
 insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,SOURCE_DOC_ID,UID_PALLET,TARGET_ARTICUL,FROM_CELL,TO_CELL,FROM_WARE_ID,TO_WARE_ID,QTY,UNIT_CODE,QTY_MODE,STATUS,CREATED_BY)
 values(v_task,'PUTAWAY','MANUAL',v_task,'STORE_RETURN',v_doc,v_uid,v_article,v_from,v_to,v_ware,v_ware,v_qty,v_unit,'PALLET','PLANNED',p_actor);
 insert into RRL_STORE_RETURN_PUT_PLAN(OPERATION_ID,RECEIPT_OPERATION_ID,TASK_ID,POLICY_VERSION,TARGET_CELL,PLANNED_BY)values(op,v_receipt,v_task,v_policy,v_to,p_actor);
 j.put('operation_id',op);j.put('task_id',v_task);j.put('receipt_operation_id',v_receipt);j.put('from_cell',v_from);j.put('to_cell',v_to);j.put('quantity',v.get_string('quantity'));j.put('base_uom',v_unit);j.put('warehouse_stock_changed',false);p_result:=j.to_clob;
 end;
 procedure plan_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t) is
 v_receipt varchar2(100);v json_object_t;v_policy number;v_target varchar2(60);op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');
 begin
 select RECEIPT_OPERATION_ID,POLICY_VERSION,TARGET_CELL into v_receipt,v_policy,v_target from RRL_STORE_RETURN_PUT_PLAN where TASK_ID=p_task.TASK_ID;
 describe_current(v_receipt,p_actor,p_task.TASK_ID,v);
 if p_task.TASK_SOURCE!='MANUAL' or p_task.TASK_TYPE!='PUTAWAY' or p_task.SOURCE_DOC_TYPE!='STORE_RETURN' or p_task.SOURCE_DOC_ID!=v.get_number('naklad_id')
 or p_task.UID_PALLET!=v.get_string('uid') or p_task.FROM_CELL!=v.get_string('from_cell') or p_task.TO_CELL!=v.get_string('target_cell') or p_task.UNIT_CODE!=v.get_string('base_uom')
 or p_task.QTY!=RRL_STOCK_MATH.quantity(v.get_string('quantity')) or p_task.QTY_MODE!='PALLET' or v_policy!=v.get_number('policy_version') or v_target!=p_task.TO_CELL then raise_application_error(-20886,'STORE_RETURN_ORIGINAL_PLACEMENT_TASK_CONFLICT');end if;
 declare_rows(v,p_resources);
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_RETURN_PLACEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(p_task.TASK_ID));
 RRL_STOCK_PLAN_HELPER.anchor(p_resources,70,'UNIQUE','SAP.OUTBOX:STORE_RETURN_PLACED:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_task.TASK_ID));
 p_domain.put('store_return_placement',v);
 exception when no_data_found then raise_application_error(-20886,'STORE_RETURN_REGISTERED_PLACEMENT_TASK_REQUIRED');
 end;
 procedure validate_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_frozen json_object_t) is
 r json_array_t:=json_array_t();d json_object_t:=json_object_t();current_domain json_object_t;
 begin
 plan_task(p_task,p_actor,r,d);current_domain:=d.get_object('store_return_placement');
 if p_frozen is null or dbms_lob.compare(current_domain.to_clob,p_frozen.to_clob)!=0 then raise_application_error(-20886,'STORE_RETURN_PLACEMENT_LOCKED_SOURCE_CHANGED');end if;
 end;
 procedure complete_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_quantity number,p_target_uid varchar2,p_actor varchar2) is
 v_receipt varchar2(100);receipt RRL_STORE_RETURN_RECEIPT%rowtype;sap RRL_STORE_RETURN_SAP%rowtype;approval RRL_STORE_RETURN_APPROVAL%rowtype;
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');payload json_object_t:=json_object_t();v_payload clob;v_event varchar2(100);n number;
 begin
 select RECEIPT_OPERATION_ID into v_receipt from RRL_STORE_RETURN_PUT_PLAN where TASK_ID=p_task.TASK_ID;
 select * into receipt from RRL_STORE_RETURN_RECEIPT where OPERATION_ID=v_receipt;
 if p_quantity!=receipt.BASE_QTY or p_target_uid!=receipt.UID_PALLET then raise_application_error(-20886,'STORE_RETURN_WHOLE_PLACEMENT_REQUIRED');end if;
 RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STORE_RETURN_PLACEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(p_task.TASK_ID)));
 select count(*) into n from RRL_WAREHOUSE_TASK where TASK_ID=p_task.TASK_ID and STATUS='DONE' and FACT_QTY=receipt.BASE_QTY;
 if n!=1 then raise_application_error(-20886,'STORE_RETURN_COMPLETED_PHYSICAL_TASK_REQUIRED');end if;
 insert into RRL_STORE_RETURN_PLACEMENT(OPERATION_ID,RECEIPT_OPERATION_ID,TASK_ID,UID_PALLET,TARGET_CELL,BASE_QTY,BASE_UOM,PLACED_BY)values(op,v_receipt,p_task.TASK_ID,p_target_uid,p_task.TO_CELL,receipt.BASE_QTY,receipt.BASE_UOM,p_actor);
 update RRL_PRIHOD_NAKLAD set CONDITION=2 where ID=receipt.NAKLAD_ID and DOCUMENT_KIND='STORE_RETURN' and CONDITION=1;
 if sql%rowcount!=1 then raise_application_error(-20886,'STORE_RETURN_DOCUMENT_PLACEMENT_STATE_CONFLICT');end if;
 select * into sap from RRL_STORE_RETURN_SAP where OPERATION_ID=receipt.SAP_OPERATION_ID;
 select * into approval from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=receipt.APPROVAL_OPERATION_ID;
 payload.put('operation_id',op);payload.put('return_document',sap.RETURN_DOCUMENT);payload.put('sender',sap.SAP_SENDER);payload.put('approval_operation_id',receipt.APPROVAL_OPERATION_ID);payload.put('receipt_operation_id',v_receipt);payload.put('original_store_receipt',approval.RECEIPT_OPERATION_ID);
 payload.put('pallet_identifier',p_target_uid);payload.put('original_lot_uid',receipt.ORIGINAL_LOT_UID);payload.put('article',receipt.ARTICLE);payload.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(receipt.BASE_QTY));payload.put('base_uom',receipt.BASE_UOM);
 payload.put('warehouse_id',receipt.WARE_ID);payload.put('cell',p_task.TO_CELL);payload.put('disposition',receipt.DISPOSITION);payload.put('supplier_batch',receipt.OBSERVED_BATCH);payload.put('batch_source',receipt.BATCH_SOURCE);payload.put('expiry_date',to_char(receipt.EXPIRY_DATE,'YYYY-MM-DD'));
 payload.put('placement_confirmed',true);payload.put('supplier_transfer_confirmed',false);payload.put('external_sap_ack',false);
 v_event:='STORE_RETURN_PLACED:'||RRL_STOCK_PLAN_HELPER.decimal_text(p_task.TASK_ID);v_payload:=payload.to_clob;
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values(v_event,'STORE_RETURN_PLACED',v_payload);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_RETURN_REC_CMD as

 procedure assert_scope(p_pickup varchar2,p_actor varchar2)is n number;

 begin

  select count(*)into n from RRL_STORE_RETURN_PICKUP p join RRL_STORE_RETURN_HANDOVER h on h.OPERATION_ID=p.HANDOVER_OPERATION_ID join RRL_STORE_RETURN_TRANSPORT t on t.OPERATION_ID=h.TRANSPORT_OPERATION_ID join RUSERS u on u.ID=p_actor

   where p.OPERATION_ID=p_pickup and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(p_actor,'warehouse_return_receive')=1 and(u.WARE_ID=t.RECEIVING_WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');

  if n!=1 then raise_application_error(-20882,'STORE_RETURN_CURRENT_RECEIVING_WAREHOUSE_ACTOR_REQUIRED');end if;

 end;

 function actual_date(p_text varchar2) return date is

 begin

  if p_text is null or not regexp_like(p_text,'^[0-9]{4}-[0-9]{2}-[0-9]{2}$','c') then raise_application_error(-20886,'STORE_RETURN_ACTUAL_DATE_REQUIRED');end if;

  begin return to_date(p_text,'FXYYYY-MM-DD');exception when others then raise_application_error(-20886,'STORE_RETURN_ACTUAL_DATE_INVALID');end;

 end;

 procedure describe_receipt(p_request clob,p_actor varchar2,p_domain out json_object_t) is

 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v_pickup varchar2(100):=d.get_object('source').get_string('pickup_operation_id');

 pickup RRL_STORE_RETURN_PICKUP%rowtype;handed RRL_STORE_RETURN_HANDOVER%rowtype;transport RRL_STORE_RETURN_TRANSPORT%rowtype;approved RRL_STORE_RETURN_APPROVAL%rowtype;sap RRL_STORE_RETURN_SAP%rowtype;

 original RRL_PALLETS%rowtype;policy RRL_STORE_RETURN_WARE_POLICY%rowtype;

 v_cell varchar2(60);v_uid varchar2(200);v_gross number;v_net number;v_expiry date;v_batch varchar2(32767);v_original_batch varchar2(100);v_origin varchar2(200);v_batch_source varchar2(30);v_uom_version number;v_scale number;n number;v_scan_article varchar2(160);v_scan_uom varchar2(20);v_scan_code varchar2(128);v_proof json_object_t;return_proof clob;source_cell varchar2(60);source_max varchar2(60);

 begin

 if RRL_HAS_WRIGHT(p_actor,'warehouse_return_receive')!=1 then raise_application_error(-20882,'STORE_RETURN_WAREHOUSE_RECEIVE_FORBIDDEN');end if;

 select * into pickup from RRL_STORE_RETURN_PICKUP where OPERATION_ID=v_pickup;

 select * into handed from RRL_STORE_RETURN_HANDOVER where OPERATION_ID=pickup.HANDOVER_OPERATION_ID;

 select * into transport from RRL_STORE_RETURN_TRANSPORT where OPERATION_ID=handed.TRANSPORT_OPERATION_ID;

 select * into approved from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=transport.APPROVAL_OPERATION_ID;

 select * into sap from RRL_STORE_RETURN_SAP where OPERATION_ID=transport.SAP_OPERATION_ID;



 select count(*) into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and(upper(trim(USER_GROUP))='GLOBAL_ADMIN' or WARE_ID=sap.WARE_ID);

 if n!=1 then raise_application_error(-20882,'STORE_RETURN_RECEIVER_WAREHOUSE_BINDING_REQUIRED');end if;

 select * into policy from RRL_STORE_RETURN_WARE_POLICY where WARE_ID=sap.WARE_ID;

 v_cell:=case approved.DISPOSITION when 'SUPPLIER' then policy.SUPPLIER_RECEIVE_CELL when 'REUSE' then policy.REUSE_RECEIVE_CELL else policy.DISPOSAL_RECEIVE_CELL end;

 select count(*) into n from RRL_CELLS where CELL=v_cell and WARE_ID=sap.WARE_ID and nvl(BLOCKED_FOR_ACCEPT,0)=0 and BLOCKED_FOR_REMAINS=1 and BLOCKED_FOR_POPOLNENIE=1;

 if n!=1 then raise_application_error(-20886,'STORE_RETURN_SEGREGATED_RECEIVING_CELL_REQUIRED');end if;

 v_uid:=handed.PALLET_IDENTIFIER;

 if length(v_uid)>50 or lengthb(v_uid)>150 then raise_application_error(-20886,'STORE_RETURN_PALLET_LEGACY_ID_BOUND_50');end if;

 if m.get_string('scan_pallet') is null or m.get_string('scan_pallet')!=v_uid or m.get_string('scan_vehicle') is null or m.get_string('scan_vehicle')!=pickup.VEHICLE_NUMBER or m.get_string('scan_cell') is null or m.get_string('scan_cell')!=v_cell then raise_application_error(-20886,'STORE_RETURN_WAREHOUSE_PALLET_VEHICLE_CELL_SCAN_REQUIRED');end if;

 if m.get_string('article') is null or m.get_string('article')!=approved.ARTICLE or m.get_string('base_uom') is null or m.get_string('base_uom')!=approved.BASE_UOM or RRL_STOCK_MATH.quantity(m.get_string('quantity'))!=approved.BASE_QTY then raise_application_error(-20886,'STORE_RETURN_WAREHOUSE_FULL_ORIGINAL_QUANTITY_REQUIRED');end if;

 v_scan_code:=m.get_string('scan_article');RRL_STOCK_QC_ITEM.resolve_barcode(v_scan_code,v_scan_article,v_scan_uom);

 if v_scan_article!=approved.ARTICLE then raise_application_error(-20886,'STORE_RETURN_FOREIGN_ARTICLE_BARCODE');end if;

 select count(*) into n from RRL_PALLETS where UID_PALLET=v_uid;

 if n!=0 then
  RRL_RETURN_PALLET_IDENTITY.assert_preserved(approved.OPERATION_ID,v_uid);
 end if;

 select count(*) into n from RRL_STORE_RETURN_RECEIPT where PICKUP_OPERATION_ID=v_pickup or APPROVAL_OPERATION_ID=approved.OPERATION_ID;

 if n!=0 then raise_application_error(-20886,'STORE_RETURN_PICKUP_ALREADY_RECEIVED');end if;

 select * into original from RRL_PALLETS where UID_PALLET=approved.LOT_UID;

 if original.ARTICUL is null or original.ARTICUL!=approved.ARTICLE or original.EXPIRY_DATE is null then raise_application_error(-20886,'STORE_RETURN_ORIGINAL_LOT_METADATA_REQUIRED');end if;

 v_expiry:=actual_date(m.get_string('expiry_date'));

 if v_expiry is null or v_expiry!=trunc(original.EXPIRY_DATE) then raise_application_error(-20886,'STORE_RETURN_ORIGINAL_EXPIRY_CONFLICT');end if;

 v_batch:=m.get_string('supplier_batch');

 if trim(v_batch) is null or lengthb(v_batch)>100 then raise_application_error(-20886,'STORE_RETURN_ACTUAL_BATCH_REQUIRED');end if;

 v_origin:=nvl(original.STOCK_ORIGIN_UID,original.UID_PALLET);

 select count(*),min(SUPPLIER_BATCH) into n,v_original_batch from RRL_SAP_PALLET_RECEIPT where UID_PALLET=v_origin;

 if n>1 then raise_application_error(-20886,'STORE_RETURN_ORIGINAL_BATCH_AMBIGUOUS');end if;

 if n=1 and v_original_batch is not null then

  if v_batch!=v_original_batch then raise_application_error(-20886,'STORE_RETURN_ORIGINAL_BATCH_CONFLICT');end if;v_batch_source:='ORIGINAL_SAP_VERIFIED';

 else v_batch_source:='OBSERVED_LEGACY_UNVERIFIED';end if;

 select count(*) into n from dual where exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=approved.ARTICLE)

 or exists(select 1 from RRL_SKU_RECEIPT_POLICY where ARTICUL=approved.ARTICLE and MARKING_REQUIRED=1)

 or exists(select 1 from RRL_FINISHED_GOODS_SKU where ARTICUL=approved.ARTICLE and CRPT_REQUIRED=1);

 return_proof:=RRL_STORE_RETURN_UNIT_CORE.custody_proof(approved.OPERATION_ID,m);

 if n!=0 and return_proof is null then raise_application_error(-20886,'STORE_RETURN_MARKED_EXACT_APPROVAL_REQUIRED');end if;

 if return_proof is not null then

  select min(SOURCE_CELL),max(SOURCE_CELL)into source_cell,source_max from RRL_STORE_RETURN_UNIT where APPROVAL_OPERATION_ID=approved.OPERATION_ID;

  if source_cell is null or source_cell!=source_max then raise_application_error(-20886,'STORE_RETURN_UNIT_SOURCE_CELL_REQUIRED');end if;

 end if;

 select max(POLICY_VERSION) into v_uom_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=approved.ARTICLE and INPUT_UOM=approved.BASE_UOM and BASE_UOM=approved.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;

 select BASE_SCALE into v_scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=approved.ARTICLE and INPUT_UOM=approved.BASE_UOM and BASE_UOM=approved.BASE_UOM and POLICY_VERSION=v_uom_version and NUMERATOR=1 and DENOMINATOR=1;

 RRL_STOCK_MATH.assert_base(approved.BASE_QTY,v_scale);

 v_gross:=RRL_STOCK_MATH.quantity(m.get_string('gross_weight_kg'));v_net:=RRL_STOCK_MATH.quantity(m.get_string('net_weight_kg'));

 if v_gross!=handed.GROSS_WEIGHT_KG or v_net>v_gross then raise_application_error(-20886,'STORE_RETURN_WAREHOUSE_WEIGHT_CONFLICT');end if;

 if approved.DISPOSITION='REUSE' then RRL_STOCK_RETURN_REUSE.describe_boxes(approved,m,v_scan_uom,v_batch_source,sap.WARE_ID,v_proof);end if;

 p_domain:=json_object_t();
 if v_uid=approved.LOT_UID then p_domain.put('preserved_pallet_identity',true);end if;if approved.RETURN_BASIS!='ACCEPTED'then p_domain.put('return_basis',approved.RETURN_BASIS);end if;if return_proof is not null then p_domain.put('return_unit_proof',json_object_t.parse(return_proof));p_domain.put('return_source_cell',source_cell);end if;if v_proof is not null then p_domain.put('reuse_boxes',v_proof);end if;p_domain.put('pickup_operation_id',v_pickup);p_domain.put('approval_operation_id',approved.OPERATION_ID);p_domain.put('sap_operation_id',sap.OPERATION_ID);p_domain.put('return_document',sap.RETURN_DOCUMENT);

 p_domain.put('warehouse_id',sap.WARE_ID);p_domain.put('receive_cell',v_cell);p_domain.put('policy_version',policy.POLICY_VERSION);p_domain.put('uid',v_uid);p_domain.put('original_lot_uid',approved.LOT_UID);p_domain.put('stock_origin_uid',v_origin);

 p_domain.put('article',approved.ARTICLE);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(approved.BASE_QTY));p_domain.put('base_uom',approved.BASE_UOM);p_domain.put('uom_version',v_uom_version);p_domain.put('disposition',approved.DISPOSITION);

 p_domain.put('expiry_date',to_char(v_expiry,'YYYY-MM-DD'));p_domain.put('produced_date',to_char(original.PRODUCED_DATE,'YYYY-MM-DD'));p_domain.put('price',original.PRICE);

 p_domain.put('scan_article',v_scan_code);p_domain.put('scan_input_uom',v_scan_uom);p_domain.put('supplier_batch',v_batch);p_domain.put('batch_source',v_batch_source);p_domain.put('gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_gross));p_domain.put('net_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_net));

 exception when no_data_found then raise_application_error(-20886,'STORE_RETURN_PICKUP_LOT_OR_WAREHOUSE_POLICY_REQUIRED');

 end;

 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is

 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();v_naklad number;

 begin

 describe_receipt(p_request,d.get_string('actor'),v);

 select RRL_PRIHOD_NAKLAD_SQ.nextval into v_naklad from dual;v.put('naklad_id',v_naklad);

 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);

 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));

 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRIHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(v_naklad));

 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_PICKUP',v.get_string('pickup_operation_id'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_RECEIPT',p_operation);

 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',v.get_string('original_lot_uid'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',v.get_string('uid'));

 RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('uid'),v.get_string('article'),null,v.get_string('receive_cell'));

 if v.has('return_unit_proof')then

  RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('original_lot_uid'),v.get_string('article'),v.get_string('return_source_cell'),null);

  declare wire clob:=v.get_object('return_unit_proof').get_array('units').to_clob;begin

   for x in(select K from json_table(wire,'$[*]'columns(K varchar2(64)path '$.key')))loop RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',x.K);end loop;

  end;

  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_APPROVAL',v.get_string('approval_operation_id'));

 end if;

 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','PALLET:'||v.get_string('uid'));

 if v.has('reuse_boxes')then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_RETURN_REUSE_PROOF',p_operation);end if;

 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;

 end;

 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is

 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();

 v_naklad number;v_document varchar2(100);v_number varchar2(20);v_pickup varchar2(100);v_approval varchar2(100);v_sap varchar2(100);v_uid varchar2(200);v_old_uid varchar2(200);v_origin varchar2(200);v_article varchar2(160);v_ware number;v_cell varchar2(60);v_base varchar2(20);v_qty number;v_version number;v_event number;v_gross number;v_net number;v_price number;v_expiry date;v_produced date;v_batch varchar2(100);v_batch_source varchar2(30);v_disposition varchar2(20);

 begin

 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');

 describe_receipt(p_request,p_actor,fresh);fresh.put('naklad_id',v.get_number('naklad_id'));

 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'STORE_RETURN_RECEIVING_SOURCE_CHANGED');end if;

 v_pickup:=v.get_string('pickup_operation_id');v_approval:=v.get_string('approval_operation_id');v_sap:=v.get_string('sap_operation_id');v_uid:=v.get_string('uid');v_old_uid:=v.get_string('original_lot_uid');v_origin:=v.get_string('stock_origin_uid');v_article:=v.get_string('article');

 v_ware:=v.get_number('warehouse_id');v_cell:=v.get_string('receive_cell');v_base:=v.get_string('base_uom');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));v_version:=v.get_number('uom_version');

 v_gross:=RRL_STOCK_MATH.quantity(v.get_string('gross_weight_kg'));v_net:=RRL_STOCK_MATH.quantity(v.get_string('net_weight_kg'));v_price:=v.get_number('price');v_expiry:=to_date(v.get_string('expiry_date'),'FXYYYY-MM-DD');v_produced:=to_date(v.get_string('produced_date'),'FXYYYY-MM-DD');v_batch:=v.get_string('supplier_batch');v_batch_source:=v.get_string('batch_source');v_disposition:=v.get_string('disposition');

 RRL_STOCK_LOCATION_CORE.assert_receiving(v_cell,v_ware);

 v_naklad:=v.get_number('naklad_id');v_document:=v.get_string('return_document');v_number:='RTN:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_naklad);

 insert into RRL_PRIHOD_NAKLAD(ID,NAKLAD_NUMBER,ZAKAZ_NUMBER,DATE_OF_NAKLAD,DATE_OF_ACCEPT,WARE_ID,POSTAVSHIK_NAME,CONDITION,DOCUMENT_KIND,RETURN_APPROVAL_OPERATION_ID,RETURN_DOCUMENT_REFERENCE)

 values(v_naklad,v_number,v_number,sysdate,sysdate,v_ware,unistr('\0412\043E\0437\0432\0440\0430\0442 \043C\0430\0433\0430\0437\0438\043D\0430'),1,'STORE_RETURN',v_approval,v_document);

 if not v.has('preserved_pallet_identity')then
 insert into RRL_PALLETS(UID_PALLET,ARTICUL,CREATION_DATE,EXPIRY_DATE,PRODUCED_DATE,UNIT_COUNT,PRICE,STOCK_ORIGIN_UID,CREATED_BY_STOCK_OP,WEIGHT_BRUTTO,PRIHOD_NAKLAD_ID)

 values(v_uid,v_article,systimestamp,v_expiry,v_produced,v_qty,v_price,v_origin,op,v_gross,v_naklad);
 end if;

 RRL_STOCK_BALANCE_CORE.apply_delta(v_uid,v_cell,v_qty,0,v_base,v_version,0);

 if v.has('return_unit_proof')then

  RRL_STOCK_UNIT_CORE.receive_return(v_old_uid,v.get_string('return_source_cell'),v_uid,v_cell,v_qty,v.get_object('return_unit_proof').get_array('units').to_clob);

  j.put('physical_unit_count',v.get_object('return_unit_proof').get_number('physical_unit_count'));j.put('mark_scan_confirmed',true);j.put('original_unit_codes_retained',true);

 end if;

 RRL_STOCK_BALANCE_CORE.write_leg(v_uid,null,v_cell,v_qty,v_base,v_version,1,1,1,p_actor,v_event);

 insert into RRL_STORE_RETURN_RECEIPT(OPERATION_ID,PICKUP_OPERATION_ID,APPROVAL_OPERATION_ID,SAP_OPERATION_ID,UID_PALLET,ORIGINAL_LOT_UID,WARE_ID,RECEIVE_CELL,ARTICLE,BASE_QTY,BASE_UOM,DISPOSITION,OBSERVED_BATCH,BATCH_SOURCE,EXPIRY_DATE,GROSS_WEIGHT_KG,NET_WEIGHT_KG,STOCK_EVENT_ID,RECEIVED_BY,NAKLAD_ID)

 values(op,v_pickup,v_approval,v_sap,v_uid,v_old_uid,v_ware,v_cell,v_article,v_qty,v_base,v_disposition,v_batch,v_batch_source,v_expiry,v_gross,v_net,v_event,p_actor,v_naklad);

 if v.has('reuse_boxes')then RRL_STOCK_RETURN_REUSE.persist_boxes(op,p_actor,v.get_object('reuse_boxes'));end if;

 if v.has('return_basis')then j.put('return_basis',v.get_string('return_basis'));j.put('customer_accepted_quantity_changed',false);end if;j.put('operation_id',op);j.put('pickup_operation_id',v_pickup);j.put('pallet_identifier',v_uid);j.put('warehouse_id',v_ware);j.put('cell',v_cell);j.put('quantity',v.get_string('quantity'));j.put('base_uom',v_base);

 if v.has('preserved_pallet_identity')then j.put('preserved_pallet_identity',true);end if;j.put('receiving_document_id',v_naklad);j.put('document_kind','STORE_RETURN');j.put('event_id',v_event);j.put('status','RECEIVED_PENDING_PLACEMENT');j.put('custody','WAREHOUSE');j.put('available_for_reservation',false);j.put('batch_source',v_batch_source);j.put('financial_erp_completion_created',false);p_result:=j.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_RETURN_SAP_CMD as
 procedure describe_binding(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);v_approval varchar2(100):=d.get_object('source').get_string('approval_operation_id');m json_object_t:=d.get_object('metadata');
 approved RRL_STORE_RETURN_APPROVAL%rowtype;v_ware number:=m.get_number('warehouse_id');v_cell varchar2(255):=m.get_string('receive_cell');v_sender varchar2(32767):=m.get_string('sender');v_message varchar2(32767):=m.get_string('message_id');v_document varchar2(32767):=m.get_string('return_document');
 v_raw varchar2(32767):=m.get_string('raw_base64');v_hash varchar2(64):=m.get_string('payload_hash');v_bytes raw(32767);n number;v_xml varchar2(32767);v_quantity_text varchar2(40):=m.get_string('quantity');
 begin
 if RRL_HAS_WRIGHT(p_actor,'sap_return_import')!=1 then raise_application_error(-20882,'SAP_RETURN_IMPORT_FORBIDDEN');end if;
 select * into approved from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=v_approval;
 if m.get_string('receipt_operation_id') is null or m.get_string('receipt_operation_id')!=approved.RECEIPT_OPERATION_ID
 or m.get_number('line_no') is null or m.get_number('line_no')!=approved.LINE_NO
 or m.get_string('article') is null or m.get_string('article')!=approved.ARTICLE
 or m.get_string('lot_uid') is null or m.get_string('lot_uid')!=approved.LOT_UID
 or m.get_string('base_uom') is null or m.get_string('base_uom')!=approved.BASE_UOM
 or nvl(m.get_string('return_basis'),'ACCEPTED')!=approved.RETURN_BASIS
 or m.get_string('disposition') is null or m.get_string('disposition')!=approved.DISPOSITION
 or RRL_STOCK_MATH.quantity(m.get_string('quantity'))!=approved.BASE_QTY then raise_application_error(-20886,'SAP_RETURN_ORIGINAL_APPROVAL_MISMATCH');end if;
 if trim(v_sender) is null or lengthb(v_sender)>100 or trim(v_message) is null or lengthb(v_message)>100 or trim(v_document) is null or lengthb(v_document)>100 then raise_application_error(-20886,'SAP_RETURN_SENDER_MESSAGE_DOCUMENT_REQUIRED');end if;
 if v_ware is null or v_ware!=trunc(v_ware) or v_ware<1 or v_cell is null then raise_application_error(-20886,'SAP_RETURN_WAREHOUSE_RECIPIENT_REQUIRED');end if;
 select count(*) into n from RRL_WARES where ID=v_ware and DEFAULT_RECEIVE_CELL=v_cell;
 if n!=1 then raise_application_error(-20886,'SAP_RETURN_CONFIGURED_RECEIVING_ZONE_REQUIRED');end if;
 select count(*) into n from RRL_CELLS where WARE_ID=v_ware and CELL=v_cell and nvl(BLOCKED_FOR_ACCEPT,0)=0;
 if n!=1 then raise_application_error(-20886,'SAP_RETURN_RECEIVING_ZONE_UNAVAILABLE');end if;
 if v_raw is null or lengthb(v_raw)>21848 or v_hash is null or not regexp_like(v_hash,'^[0-9a-f]{64}$','c') then raise_application_error(-20886,'SAP_RETURN_ORIGINAL_XML_REQUIRED');end if;
 v_bytes:=utl_encode.base64_decode(utl_raw.cast_to_raw(v_raw));
 if length(v_bytes)>16384 or lower(rawtohex(sys.dbms_crypto.hash(v_bytes,sys.dbms_crypto.hash_sh256)))!=v_hash then raise_application_error(-20886,'SAP_RETURN_ORIGINAL_XML_HASH_CONFLICT');end if;
 v_xml:=utl_i18n.raw_to_char(v_bytes,'AL32UTF8');
 if instr(upper(v_xml),'<!DOCTYPE')>0 or instr(upper(v_xml),'<!ENTITY')>0 then raise_application_error(-20886,'SAP_RETURN_XML_DTD_FORBIDDEN');end if;
 select count(*) into n from xmltable('/WarehouseStoreReturn[@version="1" or @version="2"]' passing xmltype(v_xml)
 columns contract_version varchar2(10)path '@version',return_basis varchar2(10)path 'OriginalReceiptDisposition',sender varchar2(100) path 'Sender',message_id varchar2(100) path 'MessageId',return_document varchar2(100) path 'ReturnDocumentNumber',
 approval_id varchar2(100) path 'ApprovalOperationId',receipt_id varchar2(100) path 'OriginalReceiptOperationId',line_no number path 'OriginalLineNumber',
 ware_id number path 'WarehouseId',receive_cell varchar2(255) path 'ReceiveCell',article varchar2(160) path 'Article',lot_uid varchar2(200) path 'LotId',
 qty varchar2(40) path 'Quantity',base_uom varchar2(20) path 'Quantity/@unit',disposition varchar2(20) path 'Disposition') x
 where((x.contract_version='1'and x.return_basis is null and approved.RETURN_BASIS='ACCEPTED')or(x.contract_version='2'and x.return_basis=approved.RETURN_BASIS))
 and x.sender=v_sender and x.message_id=v_message and x.return_document=v_document and x.approval_id=v_approval
 and x.receipt_id=approved.RECEIPT_OPERATION_ID and x.line_no=approved.LINE_NO and x.ware_id=v_ware and x.receive_cell=v_cell
 and x.article=approved.ARTICLE and x.lot_uid=approved.LOT_UID and x.qty=v_quantity_text and x.base_uom=approved.BASE_UOM and x.disposition=approved.DISPOSITION;
 if n!=1 then raise_application_error(-20886,'SAP_RETURN_ORIGINAL_XML_FIELDS_CONFLICT');end if;
 select count(*) into n from RRL_STORE_RETURN_SAP where APPROVAL_OPERATION_ID=v_approval or(SAP_SENDER=v_sender and(RETURN_DOCUMENT=v_document or MESSAGE_ID=v_message));
 if n!=0 then raise_application_error(-20886,'SAP_RETURN_APPROVAL_OR_DOCUMENT_ALREADY_BOUND');end if;
 p_domain:=json_object_t();if approved.RETURN_BASIS!='ACCEPTED'then p_domain.put('return_basis',approved.RETURN_BASIS);end if;p_domain.put('approval_operation_id',v_approval);p_domain.put('sender',v_sender);p_domain.put('message_id',v_message);p_domain.put('return_document',v_document);p_domain.put('warehouse_id',v_ware);p_domain.put('receive_cell',v_cell);p_domain.put('payload_hash',v_hash);
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
 describe_binding(p_request,d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_APPROVAL',v.get_string('approval_operation_id'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_SAP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','SAP.RETURN.DOC:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(v.get_string('sender')||chr(0)||v.get_string('return_document'),'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');op varchar2(100):=d.get_string('operation_id');v_approval varchar2(100):=d.get_object('source').get_string('approval_operation_id');
 v_dummy varchar2(100);plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_sender varchar2(100);v_message varchar2(100);v_document varchar2(100);v_ware number;v_cell varchar2(255);v_raw clob;v_hash varchar2(64);
 begin
 select OPERATION_ID into v_dummy from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=v_approval for update;
 describe_binding(p_request,p_actor,fresh);
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'SAP_RETURN_SOURCE_CHANGED');end if;
 v_sender:=v.get_string('sender');v_message:=v.get_string('message_id');v_document:=v.get_string('return_document');v_ware:=v.get_number('warehouse_id');v_cell:=v.get_string('receive_cell');v_raw:=m.get_string('raw_base64');v_hash:=v.get_string('payload_hash');
 insert into RRL_STORE_RETURN_SAP(OPERATION_ID,APPROVAL_OPERATION_ID,SAP_SENDER,MESSAGE_ID,RETURN_DOCUMENT,WARE_ID,RECEIVE_CELL,ORIGINAL_XML_BASE64,ORIGINAL_SHA256,IMPORTED_BY)values(op,v_approval,v_sender,v_message,v_document,v_ware,v_cell,v_raw,v_hash,p_actor);
 if v.has('return_basis')then j.put('return_basis',v.get_string('return_basis'));end if;j.put('operation_id',op);j.put('approval_operation_id',v_approval);j.put('return_document',v_document);j.put('warehouse_id',v_ware);j.put('receive_cell',v_cell);j.put('sap_contract_imported',true);j.put('external_ack_created',false);j.put('warehouse_stock_changed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_RETURN_TR_CMD as
 procedure describe_plan(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v_approval varchar2(100):=d.get_object('source').get_string('approval_operation_id');
 v_trip number:=m.get_number('task_id');tt RRL_TRANSPORT_TASK%rowtype;veh RRL_TR_VEHICLE%rowtype;approved RRL_STORE_RETURN_APPROVAL%rowtype;sap RRL_STORE_RETURN_SAP%rowtype;
 v_store varchar2(255);v_qty number:=RRL_STOCK_MATH.quantity(m.get_string('gross_weight_kg'));v_places number:=m.get_number('physical_places');
 v_loaded_count number;v_loaded_mass number;v_return_count number;v_return_mass number;n number;
 begin
 if RRL_HAS_WRIGHT(p_actor,'store_return_transport')!=1 then raise_application_error(-20882,'STORE_RETURN_TRANSPORT_FORBIDDEN');end if;
 if v_trip is null or v_trip<1 or v_trip!=trunc(v_trip) or v_places is null or v_places<1 or v_places>200 or v_places!=trunc(v_places) then raise_application_error(-20886,'STORE_RETURN_TRIP_PHYSICAL_PLACES_REQUIRED');end if;
 select * into approved from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=v_approval;
 select * into sap from RRL_STORE_RETURN_SAP where APPROVAL_OPERATION_ID=v_approval;
 select STORE_ADDR into v_store from RRL_STORE_RECEIPT_FACT where OPERATION_ID=approved.RECEIPT_OPERATION_ID;
 select * into tt from RRL_TRANSPORT_TASK where ID=v_trip;
 select * into veh from RRL_TR_VEHICLE where NUM=tt.TRANSPORT and nvl(DELETED,0)=0;
 if tt.CONDITION is null or tt.CONDITION not in(unistr('\0421\043F\043B\0430\043D\0438\0440\043E\0432\0430\043D'),unistr('\041E\0442\0433\0440\0443\0436\0435\043D')) or nvl(tt.DELETED,0)!=0 or tt.VODITEL_ID is null
 or nvl(veh.BLOCKED,0)!=0 or nvl(veh.WORKING_NOW,0)!=1 or veh.PALLETS is null or veh.PALLETS<=0 or veh.MAX_WEIGHT_KG is null or veh.MAX_WEIGHT_KG<=0 then raise_application_error(-20886,'STORE_RETURN_ACTIVE_TRIP_VEHICLE_CAPACITY_REQUIRED');end if;
 select count(*) into n from RRL_TR_VODITEL where ID=tt.VODITEL_ID;
 if n!=1 then raise_application_error(-20886,'STORE_RETURN_ACTUAL_DRIVER_REQUIRED');end if;
 select count(*) into n from RRL_SBORKA_PALLETS where TRANSTASK_ID=v_trip and ADDR=v_store;
 if n=0 then raise_application_error(-20886,'STORE_RETURN_STORE_NOT_ON_EXISTING_TRIP');end if;
 select count(*) into n from RRL_STORE_RETURN_TRANSPORT where APPROVAL_OPERATION_ID=v_approval;
 if n!=0 then raise_application_error(-20886,'STORE_RETURN_ALREADY_PLANNED');end if;
 select count(*),nvl(sum(GROSS_WEIGHT_KG),0) into v_loaded_count,v_loaded_mass from RRL_TT_HU_LOAD_FACT where TT_ID=v_trip and STATUS in('LOADED','DEPARTED')and CUSTODY_RELEASED_AT is null;
 select count(*),nvl(sum(PHYSICAL_PLACES),0),nvl(sum(GROSS_WEIGHT_KG),0) into n,v_return_count,v_return_mass from RRL_STORE_RETURN_TRANSPORT where TT_ID=v_trip;
 if n>=200 then raise_application_error(-20881,'STORE_RETURN_TRIP_PLAN_BOUND_200');end if;
 if v_loaded_count+v_return_count+v_places>veh.PALLETS or v_loaded_mass+v_return_mass+v_qty>veh.MAX_WEIGHT_KG then raise_application_error(-20886,'STORE_RETURN_CONSERVATIVE_CAPACITY_EXCEEDED');end if;
 p_domain:=json_object_t();if approved.RETURN_BASIS!='ACCEPTED'then p_domain.put('return_basis',approved.RETURN_BASIS);end if;p_domain.put('approval_operation_id',v_approval);p_domain.put('sap_operation_id',sap.OPERATION_ID);p_domain.put('receiving_warehouse',sap.WARE_ID);
 p_domain.put('task_id',v_trip);p_domain.put('vehicle_id',veh.ID);p_domain.put('vehicle_number',veh.NUM);p_domain.put('driver_id',tt.VODITEL_ID);p_domain.put('store_address',v_store);
 p_domain.put('gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));p_domain.put('physical_places',v_places);p_domain.put('existing_outbound_mass_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_loaded_mass));p_domain.put('existing_outbound_places',v_loaded_count);
 p_domain.put('previous_return_mass_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_return_mass));p_domain.put('previous_return_places',v_return_count);p_domain.put('capacity_basis','CONSERVATIVE_FULL_OUTBOUND');
 exception when no_data_found then raise_application_error(-20886,'STORE_RETURN_APPROVAL_SAP_TRIP_CONFIGURATION_REQUIRED');when too_many_rows then raise_application_error(-20886,'STORE_RETURN_CONFIGURATION_AMBIGUOUS');
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
 describe_plan(p_request,d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_APPROVAL',v.get_string('approval_operation_id'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RETURN_TRANSPORT',p_operation);
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('task_id')));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('vehicle_id')));
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_dummy number;v_trip number;v_vehicle number;v_driver number;v_ware number;v_mass number;v_places number;v_approval varchar2(100);v_sap varchar2(100);v_plate varchar2(50);v_store varchar2(255);
 begin
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
 v_trip:=v.get_number('task_id');v_vehicle:=v.get_number('vehicle_id');
 select ID into v_dummy from RRL_TR_VEHICLE where ID=v_vehicle for update;
 select ID into v_dummy from RRL_TRANSPORT_TASK where ID=v_trip for update;
 describe_plan(p_request,p_actor,fresh);
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20886,'STORE_RETURN_TRIP_OR_CAPACITY_CHANGED');end if;
 v_approval:=v.get_string('approval_operation_id');v_sap:=v.get_string('sap_operation_id');v_driver:=v.get_number('driver_id');v_ware:=v.get_number('receiving_warehouse');v_plate:=v.get_string('vehicle_number');v_store:=v.get_string('store_address');v_mass:=RRL_STOCK_MATH.quantity(v.get_string('gross_weight_kg'));v_places:=v.get_number('physical_places');
 insert into RRL_STORE_RETURN_TRANSPORT(OPERATION_ID,APPROVAL_OPERATION_ID,SAP_OPERATION_ID,TT_ID,VEHICLE_ID,VEHICLE_NUMBER,DRIVER_ID,STORE_ADDR,RECEIVING_WARE_ID,GROSS_WEIGHT_KG,PHYSICAL_PLACES,PLANNED_BY)
 values(op,v_approval,v_sap,v_trip,v_vehicle,v_plate,v_driver,v_store,v_ware,v_mass,v_places,p_actor);
 j.put('operation_id',op);j.put('approval_operation_id',v_approval);j.put('task_id',v_trip);j.put('receiving_warehouse',v_ware);j.put('status','PLANNED_PICKUP');j.put('capacity_basis','CONSERVATIVE_FULL_OUTBOUND');j.put('physical_pickup_confirmed',false);j.put('warehouse_stock_changed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_STORE_WEIGHT_CORE as
 procedure resolve_weight(p_source clob,p_metadata clob,p_actor varchar2,p_proof out json_object_t,p_has_issue out boolean) is
  src json_object_t:=json_object_t.parse(p_source);m json_object_t:=json_object_t.parse(p_metadata);cap RRL_STORE_SCALE_CAPTURE%rowtype;device RRL_STORE_SCALE_DEVICE%rowtype;
  photos json_array_t;ids json_array_t:=json_array_t();v_key varchar2(64);v_load varchar2(100):=src.get_string('load_operation_id');v_store varchar2(255):=src.get_string('store_address');
  v_photo varchar2(64);v_view varchar2(12);v_sha varchar2(64);v_ship number;v_actual number;v_min number;v_tol number;v_delta number;v_count number;v_in_range number;v_act number:=0;reason_text varchar2(32767);
  type seen_map is table of number index by varchar2(64);seen seen_map;v_views seen_map;assets_seen seen_map;view_count number:=0;item json_object_t;
 begin
  p_proof:=null;p_has_issue:=false;
  if src.get_string('mode')='BARCODE' then return;end if;
  if src.get_string('mode') is null or src.get_string('mode')!='WEIGHT_PHOTO' then raise_application_error(-20886,'STORE_RECEIPT_MODE_UNSUPPORTED');end if;
  v_key:=m.get_string('scale_capture_key');
  if v_key is null then raise_application_error(-20886,'STORE_RECEIPT_WEIGHT_AND_PHOTOS_REQUIRED');end if;
  select * into cap from RRL_STORE_SCALE_CAPTURE where CAPTURE_KEY=v_key;
  if cap.LOAD_OPERATION_ID!=v_load or cap.STORE_ADDR!=v_store then raise_application_error(-20886,'STORE_WEIGHT_CAPTURE_SOURCE_MISMATCH');end if;
  select * into device from RRL_STORE_SCALE_DEVICE where DEVICE_ID=cap.DEVICE_ID;
  if RRL_HAS_WRIGHT(device.SENDER_ID,'store_scale_ingest')!=1 or device.SENDER_ID!=cap.RECORDED_BY or device.ACTIVE_FLAG!=1 or device.POLICY_VERSION!=cap.DEVICE_POLICY_VERSION or device.STORE_ADDR!=v_store or device.CALIBRATED_UNTIL<systimestamp
   or cap.RECEIVED_AT<systimestamp-numtodsinterval(300,'SECOND') or cap.MEASURED_AT<systimestamp-numtodsinterval(300,'SECOND') then raise_application_error(-20886,'STORE_WEIGHT_CAPTURE_EXPIRED_OR_POLICY_CHANGED');end if;
  select count(*)into v_count from RRL_TT_LOAD_BOX_WEIGHT where LOAD_OPERATION_ID=v_load and COVERAGE_COMPLETE!=1;
  if v_count>0 then raise_application_error(-20886,'STORE_WEIGHT_COMPLETE_FROZEN_BOXES_REQUIRED');end if;
  select count(*),min(GROSS_WEIGHT_KG) into v_count,v_min from RRL_TT_LOAD_BOX_WEIGHT where LOAD_OPERATION_ID=v_load;
  if v_count<1 or v_count>200 or v_min is null or v_min<=0 then raise_application_error(-20886,'STORE_WEIGHT_FROZEN_PHYSICAL_BOXES_REQUIRED');end if;
  v_ship:=RRL_STOCK_MATH.quantity(src.get_string('shipping_gross_weight_kg'));v_actual:=cap.GROSS_WEIGHT_KG;v_tol:=v_min/2;v_delta:=v_actual-v_ship;
  if not m.has('photo_ids') or not m.get('photo_ids').is_array then raise_application_error(-20886,'STORE_WEIGHT_PHOTOS_REQUIRED');end if;photos:=m.get_array('photo_ids');
  if photos.get_size<3 or photos.get_size>12 then raise_application_error(-20881,'STORE_WEIGHT_PHOTO_BOUND_3_12');end if;
  for i in 0..photos.get_size-1 loop
   v_photo:=photos.get_string(i);
   if v_photo is null or seen.exists(v_photo) then raise_application_error(-20886,'STORE_WEIGHT_PHOTO_DUPLICATE');end if;seen(v_photo):=1;
   select VIEW_CODE,ASSET_SHA256 into v_view,v_sha from RRL_STORE_RECEIPT_PHOTO where PHOTO_ID=v_photo and LOAD_OPERATION_ID=v_load and STORE_ADDR=v_store;
   if assets_seen.exists(v_sha) then raise_application_error(-20886,'STORE_WEIGHT_DISTINCT_ORIGINAL_PHOTOS_REQUIRED');end if;assets_seen(v_sha):=1;
   if not v_views.exists(v_view) then v_views(v_view):=1;view_count:=view_count+1;end if;
   item:=json_object_t();item.put('photo_id',v_photo);item.put('view',v_view);item.put('sha256',v_sha);ids.append(item);
  end loop;
  if view_count<3 then raise_application_error(-20886,'STORE_WEIGHT_THREE_DISTINCT_VIEWS_REQUIRED');end if;
  v_in_range:=case when abs(v_delta)<=v_tol then 1 else 0 end;
  if v_in_range=0 then
   if not m.has('weight_act_confirmed') then raise_application_error(-20886,'STORE_WEIGHT_ACT_REQUIRED');end if;
   if m.get_boolean('weight_act_confirmed') then null;else raise_application_error(-20886,'STORE_WEIGHT_ACT_REQUIRED');end if;
   if RRL_HAS_WRIGHT(p_actor,'store_weight_act')!=1 then raise_application_error(-20882,'STORE_WEIGHT_REPRESENTATIVE_REQUIRED');end if;
   reason_text:=m.get_string('case_note');
   if trim(reason_text) is null or lengthb(reason_text)>2000 or not m.has('observations') then raise_application_error(-20886,'STORE_WEIGHT_ACT_COUNTS_AND_REASON_REQUIRED');end if;
   if m.get_array('observations').get_size=0 then raise_application_error(-20886,'STORE_WEIGHT_ACT_COUNTS_AND_REASON_REQUIRED');end if;
   v_act:=1;p_has_issue:=true;
  end if;
  p_proof:=json_object_t();p_proof.put('capture_key',v_key);p_proof.put('device_id',cap.DEVICE_ID);p_proof.put('device_policy_version',cap.DEVICE_POLICY_VERSION);
  p_proof.put('shipping_gross_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_ship));p_proof.put('observed_gross_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_actual));
  p_proof.put('tolerance_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_tol));p_proof.put('delta_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v_delta));p_proof.put('in_tolerance',v_in_range);p_proof.put('act_confirmed',v_act);p_proof.put('photos',ids);
 exception when no_data_found then raise_application_error(-20886,'STORE_WEIGHT_CAPTURE_OR_PHOTO_SOURCE_NOT_FOUND');
 end;
 procedure declare_rows(p_operation varchar2,p_proof json_object_t,r in out nocopy json_array_t) is photos json_array_t;x json_object_t;
 begin
  if p_proof is null then return;end if;
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RECEIPT_WEIGHT',p_operation);photos:=p_proof.get_array('photos');
  for i in 0..photos.get_size-1 loop x:=treat(photos.get(i) as json_object_t);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STORE_RECEIPT_WEIGHT_PHOTO',p_operation||':'||x.get_string('photo_id'));end loop;
 end;
 procedure persist(p_operation varchar2,p_proof json_object_t,p_actor varchar2) is
  v_key varchar2(64);v_ship number;v_actual number;v_tol number;v_delta number;v_in_range number;v_act number;v_photos clob;photos json_array_t;x json_object_t;v_photo varchar2(64);
 begin
  if p_proof is null then return;end if;
  v_key:=p_proof.get_string('capture_key');v_ship:=RRL_STOCK_MATH.quantity(p_proof.get_string('shipping_gross_kg'));v_actual:=RRL_STOCK_MATH.quantity(p_proof.get_string('observed_gross_kg'));v_tol:=p_proof.get_number('tolerance_kg');v_delta:=v_actual-v_ship;v_in_range:=p_proof.get_number('in_tolerance');v_act:=p_proof.get_number('act_confirmed');photos:=p_proof.get_array('photos');v_photos:=photos.to_clob;
  insert into RRL_STORE_RECEIPT_WEIGHT(OPERATION_ID,CAPTURE_KEY,SHIPPING_GROSS_KG,OBSERVED_GROSS_KG,TOLERANCE_KG,DELTA_KG,IN_TOLERANCE,ACT_CONFIRMED,PHOTOS_JSON,RECORDED_BY)
   values(p_operation,v_key,v_ship,v_actual,v_tol,v_delta,v_in_range,v_act,v_photos,p_actor);
  for i in 0..photos.get_size-1 loop x:=treat(photos.get(i) as json_object_t);v_photo:=x.get_string('photo_id');
   insert into RRL_STORE_RECEIPT_WEIGHT_PHOTO(OPERATION_ID,PHOTO_ID)values(p_operation,v_photo);
  end loop;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_ST_ROW_CMD as
 function describe_request(p_request clob,p_actor varchar2)return json_object_t is
  d json_object_t:=json_object_t.parse(p_request);src json_object_t:=d.get_object('source');
  m json_object_t:=d.get_object('metadata');j json_object_t;w number;keys json_key_list;
 begin
  keys:=src.get_keys;
  if keys.count!=3 or src.get_number('order_id')is null or src.get_number('row_id')is null or src.get_number('target_shipment_id')is null
   or d.get_array('lines').get_size!=0 or d.get_array('units').get_size!=0 then raise_application_error(-20881,'ST_LAYOUT_CANONICAL_SOURCE_REQUIRED');end if;
  keys:=m.get_keys;
  if keys.count!=2 or m.get_string('reason')is null or length(m.get_string('reason'))>500
   or m.get_string('expected_signature')is null or not regexp_like(m.get_string('expected_signature'),'^[A-F0-9]{64}$')then raise_application_error(-20881,'ST_LAYOUT_SIGNATURE_REASON_REQUIRED');end if;
  w:=RRL_ST_LAYOUT_READ.scope_order(src.get_number('order_id'),p_actor,'outgoing_pallet_edit');
  j:=json_object_t.parse(RRL_ST_LAYOUT_READ.snapshot(src.get_number('order_id'),src.get_number('row_id'),src.get_number('target_shipment_id'),p_actor));
  if j.get_string('signature')!=m.get_string('expected_signature')then raise_application_error(-20886,'ST_LAYOUT_CHANGED_REVIEW_AGAIN');end if;
  return j;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
  d json_object_t:=json_object_t.parse(p_request);j json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;x json_object_t;
 begin
  j:=describe_request(p_request,d.get_string('actor'));
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(j.get_number('order_id')));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(j.get_number('source_shipment_id')));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(j.get_number('target_shipment_id')));
  if nvl(j.get_number('trip_id'),0)>0 then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(j.get_number('trip_id')));end if;
  a:=j.get_array('fulfillments');
  for i in 0..a.get_size-1 loop x:=treat(a.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));end loop;
  a:=j.get_array('before');
  for i in 0..a.get_size-1 loop x:=treat(a.get(i)as json_object_t);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLET_ROWS',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));end loop;
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  p_domain:=j.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);j json_object_t;fresh json_object_t;plan clob;op varchar2(100):=d.get_string('operation_id');
  source_id number;target_id number;trip_id number;row_id number;result_id number;n number;a json_array_t;x json_object_t;row_value RRL_SBORKA_PALLET_ROWS%rowtype;
 begin
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;j:=json_object_t.parse(plan).get_object('domain');
  source_id:=j.get_number('source_shipment_id');target_id:=j.get_number('target_shipment_id');trip_id:=j.get_number('trip_id');row_id:=j.get_number('row_id');
  -- Actual row locks also serialize old transport callers that do not use Root advisory locks.
  if nvl(trip_id,0)>0 then select ID into n from RRL_TRANSPORT_TASK where ID=trip_id for update nowait;end if;
  for rec in(select ID from RRL_SBORKA_PALLETS where ID in(source_id,target_id)order by ID for update nowait)loop null;end loop;
  for rec in(select FULFILLMENT_ID from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID in(source_id,target_id)order by FULFILLMENT_ID for update nowait)loop null;end loop;
  for rec in(select r.ID from RRL_SBORKA_PALLET_ROWS r join RRL_SBORKA_PALLETS s on s.PALLET_UID=r.PALLET_UID where s.ID in(source_id,target_id)order by r.ID for update of r.QUANTITY nowait)loop null;end loop;
  fresh:=describe_request(p_request,p_actor);
  if fresh.get_string('signature')!=j.get_string('signature')then raise_application_error(-20890,'CLOSURE_CHANGED: prepared row move');end if;
  result_id:=RRL_UPDATE_SBORKA_PALLET_ROWS2(j.get_string('target_pallet'),row_id);
  -- Compare every expected remaining row; this also proves exact quantity/pack/weight conservation.
  a:=j.get_array('after');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i)as json_object_t);n:=x.get_number('id');
   select *into row_value from RRL_SBORKA_PALLET_ROWS where ID=n;
   if row_value.PALLET_UID!=x.get_string('pallet')or row_value.ARTICUL!=x.get_string('article')or row_value.EI!=x.get_string('unit')
    or RRL_STOCK_PLAN_HELPER.decimal_text(row_value.QUANTITY)!=x.get_string('quantity')
    or RRL_STOCK_PLAN_HELPER.decimal_text(row_value.ORDER_WEIGHT)!=x.get_string('weight')
    or RRL_STOCK_PLAN_HELPER.decimal_text(row_value.PACK_COUNT)!=x.get_string('packs')then raise_application_error(-20886,'ST_LAYOUT_WRITER_RESULT_CONFLICT');end if;
  end loop;
  select count(*)into n from RRL_SBORKA_PALLET_ROWS r join RRL_SBORKA_PALLETS s on s.PALLET_UID=r.PALLET_UID where s.ID in(source_id,target_id);
  if n!=a.get_size then raise_application_error(-20886,'ST_LAYOUT_ROW_SET_CHANGED');end if;
  j.put('operation_id',op);j.put('status','APPLIED');j.put('result_row_id',result_id);j.put('reason',d.get_object('metadata').get_string('reason'));
  j.put('physical_binding_changed',false);j.put('trip_assignment_changed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_SUP_RETURN as
 function describe_source(p_st number,p_supplier varchar2,p_ware number) return json_object_t is
 binding RRL_STORE_RETURN_SUP_BIND%rowtype;receipt RRL_STORE_RETURN_RECEIPT%rowtype;placed RRL_STORE_RETURN_PLACEMENT%rowtype;j json_object_t:=json_object_t();
 v_cell varchar2(60);v_qty number;v_h number;v_version number;v_uom varchar2(20);v_policy number;n number;actual number;total number;units clob;profiles clob;
 begin
 begin select * into binding from RRL_STORE_RETURN_SUP_BIND where ST_ID=p_st;exception when no_data_found then return null;end;
 select * into receipt from RRL_STORE_RETURN_RECEIPT where OPERATION_ID=binding.RECEIPT_OPERATION_ID;
 select * into placed from RRL_STORE_RETURN_PLACEMENT where RECEIPT_OPERATION_ID=receipt.OPERATION_ID;
 if receipt.DISPOSITION!='SUPPLIER' or receipt.WARE_ID!=p_ware or binding.SUPPLIER_INN!=p_supplier then raise_application_error(-20886,'SUP_RETURN_TYPED_SOURCE_CONFLICT');end if;
 select count(*)into n from RRL_SUPPLIERS where INN=p_supplier;if n!=1 then raise_application_error(-20886,'SUP_RETURN_UNIQUE_SUPPLIER_REQUIRED');end if;
 select count(*)into n from RRL_STORE_RETURN_SUP_DISPATCH where BIND_OPERATION_ID=binding.OPERATION_ID;if n!=0 then raise_application_error(-20886,'SUP_RETURN_ALREADY_DISPATCHED');end if;
 select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION,BASE_UOM,CELL into v_qty,v_h,v_version,v_uom,v_cell from RRL_REMAINS where UID_POLETA=receipt.UID_PALLET and REMAIN>0;
 if v_qty!=receipt.BASE_QTY or v_h!=0 or v_uom!=receipt.BASE_UOM or v_cell!=placed.TARGET_CELL then raise_application_error(-20886,'SUP_RETURN_WHOLE_PLACED_UNRESERVED_SOURCE_REQUIRED');end if;
 select count(*)into n from RRL_CELLS where CELL=v_cell and WARE_ID=p_ware and BLOCKED_FOR_REMAINS=1 and BLOCKED_FOR_POPOLNENIE=1;
 if n!=1 then raise_application_error(-20886,'SUP_RETURN_SEGREGATED_SOURCE_REQUIRED');end if;
 select count(*)into n from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 and(CHILD_PALLET_UID=receipt.UID_PALLET or PARENT_UID=receipt.UID_PALLET);if n!=0 then raise_application_error(-20886,'SUP_RETURN_SINGLE_PHYSICAL_PLACE_REQUIRED');end if;
 select count(*)into n from dual where exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=receipt.ARTICLE)or exists(select 1 from RRL_SKU_RECEIPT_POLICY where ARTICUL=receipt.ARTICLE and MARKING_REQUIRED=1)or exists(select 1 from RRL_FINISHED_GOODS_SKU where ARTICUL=receipt.ARTICLE and CRPT_REQUIRED=1);
 if n!=0 then
  select count(*),sum(case when SCAN_MODE='UNIT'and lengthb(SYSTEM_CODE)<=30 then 0 else 1 end),json_arrayagg(json_object('system_code'value SYSTEM_CODE,'profile_code'value PROFILE_CODE,'profile_version'value PROFILE_VERSION,'scan_mode'value SCAN_MODE)order by SYSTEM_CODE,PROFILE_CODE returning clob)
   into n,actual,profiles from RRL_SKU_RECEIPT_PROFILE where ARTICUL=receipt.ARTICLE;
  if n<1 or n>50 or actual!=0 then raise_application_error(-20886,'SUP_RETURN_CURRENT_UNIT_PROFILES_REQUIRED');end if;
  select count(*),sum(u.BASE_QTY),json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION,'origin_uid'value u.UID_PALLET,'unit_id'value u.UNIT_ID)order by u.PHYSICAL_UNIT_KEY returning clob)
   into n,total,units from RRL_STORE_RETURN_UNIT b join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=b.PHYSICAL_UNIT_KEY
   where b.APPROVAL_OPERATION_ID=receipt.APPROVAL_OPERATION_ID and u.CURRENT_UID=receipt.UID_PALLET and u.CURRENT_CELL=v_cell and u.BASE_QTY=b.BASE_QTY and u.BASE_UOM=b.BASE_UOM and u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null;
  select count(*)into actual from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=receipt.UID_PALLET and CURRENT_CELL=v_cell;
  if n<1 or n>10000 or actual!=n or total!=receipt.BASE_QTY then raise_application_error(-20886,'SUP_RETURN_EXACT_APPROVED_ORIGINAL_UNITS_REQUIRED');end if;
  j.put('units',json_array_t.parse(units));j.put('profiles',json_array_t.parse(profiles));
 end if;
 select max(POLICY_VERSION)into v_policy from RRL_STOCK_UOM_CONVERSION where ARTICUL=receipt.ARTICLE and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=1 and DENOMINATOR=1;
 if v_policy is null then raise_application_error(-20886,'SUP_RETURN_BASE_UOM_POLICY_REQUIRED');end if;
 j.put('binding_operation_id',binding.OPERATION_ID);j.put('receipt_operation_id',receipt.OPERATION_ID);j.put('st_id',p_st);j.put('supplier_inn',p_supplier);j.put('warehouse_id',p_ware);j.put('uid',receipt.UID_PALLET);j.put('cell',v_cell);j.put('article',receipt.ARTICLE);
 j.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));j.put('base_uom',v_uom);j.put('stock_version',v_version);j.put('uom_version',v_policy);j.put('placement_task_id',placed.TASK_ID);j.put('return_document',receipt.SAP_OPERATION_ID);
 return j;
 exception when no_data_found then raise_application_error(-20886,'SUP_RETURN_PLACED_SOURCE_REQUIRED');when too_many_rows then raise_application_error(-20886,'SUP_RETURN_ONE_SOURCE_LOCATION_REQUIRED');end;
 procedure declare_source(p_source json_object_t,p_operation varchar2,p_resources in out nocopy json_array_t) is
 begin
 if p_source.has('profiles')then RRL_REGULATORY_API.declare_stock_events(p_operation,'MARKED_SUPPLIER_RETURN_DISPATCHED',p_source.get_array('profiles').to_clob,p_resources);end if;
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_RETURN_SUP_BIND',p_source.get_string('binding_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_RETURN_RECEIPT',p_source.get_string('receipt_operation_id'));
 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_STORE_RETURN_SUP_DISPATCH',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(p_resources,70,'UNIQUE','SAP.OUTBOX:SUPPLIER_DISPATCH:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 end;
 procedure validate_consume(p_receipt varchar2,p_uid varchar2,p_cell varchar2,p_quantity number,p_ware number,p_actor varchar2) is
 v_st number;v_supplier varchar2(255);v json_object_t;op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');v_kind varchar2(80);n number;
 begin
 if RRL_HAS_WRIGHT(p_actor,'warehouse_return_dispatch')!=1 then raise_application_error(-20882,'SUP_RETURN_DISPATCH_PERMISSION_REQUIRED');end if;
 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=p_ware or upper(trim(USER_GROUP))='GLOBAL_ADMIN');if n!=1 then raise_application_error(-20882,'SUP_RETURN_CURRENT_WAREHOUSE_BINDING_REQUIRED');end if;
 select COMMAND_TYPE into v_kind from RRL_STOCK_OPERATION where OPERATION_ID=op and STATE='IN_FLIGHT';
 if v_kind!='LOAD_SHIPMENT' then raise_application_error(-20886,'SUP_RETURN_ACTUAL_PHYSICAL_LOADING_REQUIRED');end if;
 select ST_ID,SUPPLIER_INN into v_st,v_supplier from RRL_STORE_RETURN_SUP_BIND where RECEIPT_OPERATION_ID=p_receipt;
 v:=describe_source(v_st,v_supplier,p_ware);
 if v.get_string('uid')!=p_uid or v.get_string('cell')!=p_cell or RRL_STOCK_MATH.quantity(v.get_string('quantity'))!=p_quantity then raise_application_error(-20886,'SUP_RETURN_EXACT_ORIGINAL_PALLET_QUANTITY_REQUIRED');end if;
 end;
 procedure dispatched(p_source json_object_t,p_actor varchar2) is
 op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');v_bind varchar2(100);v_receipt varchar2(100);v_st number;v_uid varchar2(200);v_quantity number;v_unit varchar2(20);v_supplier varchar2(255);payload json_object_t:=json_object_t();v_body clob;v_event varchar2(100);gov_ids clob;
 begin
 v_bind:=p_source.get_string('binding_operation_id');v_receipt:=p_source.get_string('receipt_operation_id');v_st:=p_source.get_number('st_id');v_uid:=p_source.get_string('uid');v_quantity:=RRL_STOCK_MATH.quantity(p_source.get_string('quantity'));v_unit:=p_source.get_string('base_uom');v_supplier:=p_source.get_string('supplier_inn');
 insert into RRL_STORE_RETURN_SUP_DISPATCH(OPERATION_ID,BIND_OPERATION_ID,RECEIPT_OPERATION_ID,ST_ID,UID_PALLET,BASE_QTY,BASE_UOM,SUPPLIER_INN,ACTOR)values(op,v_bind,v_receipt,v_st,v_uid,v_quantity,v_unit,v_supplier,p_actor);
 payload.put('operation_id',op);payload.put('receipt_operation_id',v_receipt);payload.put('supplier_inn',v_supplier);payload.put('pallet_identifier',v_uid);payload.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_quantity));payload.put('base_uom',v_unit);payload.put('warehouse_exit_confirmed',true);payload.put('supplier_received',false);payload.put('external_sap_ack',false);
 if p_source.has('profiles')then gov_ids:=RRL_REGULATORY_API.enqueue_stock_events(op,'MARKED_SUPPLIER_RETURN_DISPATCHED',p_source.to_clob,p_source.get_array('units').to_clob,p_source.get_array('profiles').to_clob);payload.put('regulatory_event_ids',json_array_t.parse(gov_ids));payload.put('regulatory_status','PENDING');payload.put('external_regulatory_ack',false);end if;
 v_body:=payload.to_clob;v_event:='SUPPLIER_DISPATCH:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(op,'AL32UTF8'),sys.dbms_crypto.hash_sh256));
 insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values(v_event,'SUPPLIER_RETURN_DISPATCHED',v_body);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TARE_BOOK_CMD as
 procedure describe_command(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);s json_object_t:=d.get_object('source');m json_object_t:=d.get_object('metadata');kind varchar2(80):=d.get_string('command_type');
 v_place_kind varchar2(6);v_place varchar2(200);v_type number;v_ware number;v_wave number;v_status varchar2(40);v_cell varchar2(60);v_content number;v_class varchar2(20);v_p number;v_available number;v_version number;v_key raw(32);n number;v_case number;v_book varchar2(100);v_goods_kind varchar2(20);v_article varchar2(100);v_stock_version number;
 recovery_json json_object_t;recovery_wire clob;
 booked RRL_TARE_BOOK%rowtype;pp RRL_PALLETS%rowtype;task RRL_CASE_PICK_TASK%rowtype;
 begin
 if RRL_HAS_WRIGHT(p_actor,'tare_plan')!=1 then raise_application_error(-20882,'TARE_ASSEMBLY_PLANNING_PERMISSION_REQUIRED');end if;
 if m.has('load_recovery')and not m.get('load_recovery').is_null then
  if kind!='TARE_BOOK'then raise_application_error(-20886,'TARE_RECOVERY_BOOK_ONLY');end if;
  recovery_wire:=RRL_TARE_LOAD_RECOVERY_API.describe_recovery(p_request,p_actor);recovery_json:=json_object_t.parse(recovery_wire);
 end if;
 if kind='TARE_BOOK_CANCEL' then
  v_book:=s.get_string('booking_operation_id');select * into booked from RRL_TARE_BOOK where OPERATION_ID=v_book and STATUS='HELD';
  v_place_kind:=booked.PLACE_KIND;v_place:=booked.PLACE_ID;v_type:=booked.PALLET_TYPE_ID;
 else v_place_kind:=s.get_string('place_kind');v_place:=s.get_string('place_id');v_type:=m.get_number('pallet_type_id');end if;
 if v_place_kind is null or v_place_kind not in('CASE','HU') or v_place is null then raise_application_error(-20886,'TARE_ASSEMBLY_EXISTING_PLACE_REQUIRED');end if;
 if v_place_kind='CASE' then
  if not regexp_like(v_place,'^[1-9][0-9]{0,18}$')then raise_application_error(-20886,'TARE_EXISTING_CASE_ID_REQUIRED');end if;
  v_case:=to_number(v_place);select * into task from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=v_case;
  if v_type is not null and v_type!=task.PALLET_TYPE_ID then raise_application_error(-20886,'TARE_CASE_ORIGINAL_PALLET_TYPE_REQUIRED');end if;
  v_type:=task.PALLET_TYPE_ID;v_ware:=task.WARE_ID;v_wave:=task.PICK_WAVE_ID;v_status:=task.STATUS;
  select count(*) into n from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=v_case and ACTIVE_FLAG=1;
  if n!=0 then raise_application_error(-20886,'TARE_BOOK_TOP_PLACE_REQUIRED');end if;
  if kind='TARE_BOOK_CANCEL' then
   if task.STATUS not in('NEW','ASSIGNED','CANCELLED')then raise_application_error(-20886,'TARE_BOOK_CASE_PHYSICALLY_UNUSED_REQUIRED');end if;
   select count(*) into n from RRL_CASE_CARRIER_LOT l join RRL_REMAINS r on r.UID_POLETA=l.LOT_UID where l.CASE_PICK_TASK_ID=v_case and r.REMAIN>0;
   if n!=0 then raise_application_error(-20886,'TARE_BOOK_EMPTY_PLACE_REQUIRED');end if;
  elsif task.STATUS in('SHIPPED','CANCELLED')and recovery_json is null then raise_application_error(-20886,'TARE_CASE_ALREADY_DISPATCHED_OR_CANCELLED');end if;
 else
  select * into pp from RRL_PALLETS where UID_PALLET=v_place;
  v_goods_kind:=nvl(pp.HU_KIND,'STOCK');v_article:=pp.ARTICUL;
  v_content:=pp.HU_CONTENT_VERSION;
  if recovery_json is not null then
   v_cell:=recovery_json.get_string('root_cell');v_ware:=recovery_json.get_number('warehouse_id');v_stock_version:=recovery_json.get_number('root_stock_version');
   v_status:=case when v_goods_kind='CONTAINER'then pp.HU_TYPE else 'STOCK_PALLET_SHIPPED'end;
   if v_goods_kind!=recovery_json.get_string('root_kind')or(v_goods_kind='CONTAINER'and pp.HU_TYPE not in('PALLET','ROLL_CAGE'))then raise_application_error(-20886,'TARE_RECOVERY_RETURNABLE_ROOT_TYPE_REQUIRED');end if;
  elsif v_goods_kind='CONTAINER' then
   if pp.HU_CURRENT_CELL is null or pp.HU_TYPE not in('PALLET','ROLL_CAGE')then raise_application_error(-20886,'TARE_RETURNABLE_CURRENT_CONTAINER_REQUIRED');end if;
   v_cell:=pp.HU_CURRENT_CELL;v_status:=pp.HU_TYPE;
  elsif v_goods_kind='STOCK' then
   select count(*),min(CELL),min(STOCK_VERSION) into n,v_cell,v_stock_version from RRL_REMAINS where UID_POLETA=v_place and REMAIN>0;
   if n!=1 then raise_application_error(-20886,'TARE_STOCK_SINGLE_CURRENT_CELL_REQUIRED');end if;
   if kind='TARE_BOOK_CANCEL' then raise_application_error(-20886,'TARE_BOOK_EMPTY_PLACE_REQUIRED');end if;
   select count(*) into n from RRL_CASE_CARRIER_LOT where LOT_UID=v_place;
   if n!=0 then raise_application_error(-20886,'TARE_CASE_GOODS_USE_EXISTING_CASE_ROOT');end if;
   v_status:='STOCK_PALLET';
  else raise_application_error(-20886,'TARE_RETURNABLE_CURRENT_PLACE_REQUIRED');end if;
  select WARE_ID into v_ware from RRL_CELLS where CELL=v_cell;
  select LOAD_UNIT_CLASS into v_class from RRL_PALLET_TYPE where PALLET_TYPE_ID=v_type and ACTIVE=1;
  if(v_goods_kind='STOCK' and v_class!='PALLET')or(pp.HU_TYPE='PALLET' and v_class!='PALLET')or(pp.HU_TYPE='ROLL_CAGE' and v_class!='TROLLEY')then raise_application_error(-20886,'TARE_CONTAINER_PHYSICAL_TYPE_CONFLICT');end if;
  select count(*) into n from RRL_WMS_HU_LINK where CHILD_PALLET_UID=v_place and ACTIVE_FLAG=1;
  if n!=0 then raise_application_error(-20886,'TARE_BOOK_TOP_PLACE_REQUIRED');end if;
  select count(*) into n from RRL_TT_HU_LOAD_FACT where ROOT_UID=v_place and STATUS in('LOADED','DEPARTED');
  if n!=0 and recovery_json is null then raise_application_error(-20886,'TARE_BOOK_PLACE_ALREADY_ON_VEHICLE');end if;
  if kind='TARE_BOOK_CANCEL' then
   select count(*) into n from RRL_WMS_HU_LINK where PARENT_UID=v_place and ACTIVE_FLAG=1;
   if n!=0 then raise_application_error(-20886,'TARE_BOOK_EMPTY_PLACE_REQUIRED');end if;
  else
   select count(*) into n from RRL_TARE_BOOK b where b.STATUS='HELD' and(
    (b.PLACE_KIND='HU' and b.PLACE_ID in(select CHILD_PALLET_UID from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 start with PARENT_UID=v_place connect by nocycle prior CHILD_PALLET_UID=PARENT_UID and ACTIVE_FLAG=1))
    or(b.PLACE_KIND='CASE' and b.PLACE_ID in(select to_char(CHILD_CASE_TASK_ID,'TM9') from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 start with PARENT_UID=v_place connect by nocycle prior CHILD_PALLET_UID=PARENT_UID and ACTIVE_FLAG=1)));
   if n!=0 then raise_application_error(-20886,'TARE_NESTED_PLACE_ALREADY_BOOKED');end if;
  end if;
 end if;
 if m.has('expected_warehouse_id') and(m.get_number('expected_warehouse_id') is null or m.get_number('expected_warehouse_id')!=v_ware)then raise_application_error(-20886,'TARE_PLACE_SELECTED_WAREHOUSE_CONFLICT');end if;
 RRL_TARE_PARTICIPANT.warehouse_actor(p_actor,v_ware);
 select count(*) into n from RRL_PALLET_TYPE where PALLET_TYPE_ID=v_type and ACTIVE=1;if n!=1 then raise_application_error(-20886,'TARE_ACTIVE_EXISTING_PALLET_TYPE_REQUIRED');end if;
 if kind='TARE_BOOK_CANCEL' and(booked.OWNER_WARE_ID!=v_ware or booked.PALLET_TYPE_ID!=v_type)then raise_application_error(-20886,'TARE_BOOK_ORIGINAL_WARE_TYPE_CONFLICT');end if;
 v_key:=RRL_TARE_BALANCE_KEY(v_ware,v_type,'GOOD','WAREHOUSE',RRL_STOCK_PLAN_HELPER.decimal_text(v_ware));
 select PHYSICAL_QTY,AVAILABLE_QTY,BALANCE_VERSION into v_p,v_available,v_version from RRL_TARE_AVAILABILITY where BALANCE_KEY=v_key;
 if kind='TARE_BOOK' then
  select count(*) into n from RRL_TARE_BOOK where PLACE_KIND=v_place_kind and PLACE_ID=v_place and STATUS='HELD';
  if n!=0 then raise_application_error(-20886,'TARE_PLACE_ALREADY_BOOKED');end if;
  if v_available<1 then raise_application_error(-20886,'TARE_GOOD_WAREHOUSE_AVAILABILITY_REQUIRED');end if;
 end if;
 p_domain:=json_object_t();p_domain.put('place_kind',v_place_kind);p_domain.put('place_id',v_place);p_domain.put('pallet_type_id',v_type);p_domain.put('warehouse_id',v_ware);p_domain.put('wave_id',v_wave);p_domain.put('place_status',v_status);p_domain.put('cell',v_cell);p_domain.put('content_version',v_content);
 p_domain.put('goods_kind',v_goods_kind);p_domain.put('article',v_article);p_domain.put('stock_version',v_stock_version);
 if recovery_json is not null then p_domain.put('load_recovery',recovery_json);end if;
 p_domain.put('balance_key',rawtohex(v_key));p_domain.put('physical_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_p));p_domain.put('available_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_available));p_domain.put('balance_version',v_version);p_domain.put('booking_operation_id',v_book);
 exception when no_data_found then raise_application_error(-20886,'TARE_EXISTING_PLACE_OR_GOOD_COUNT_REQUIRED');end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
 describe_command(p_request,d.get_string('actor'),v);RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BALANCE',v.get_string('balance_key'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BOOK',case when d.get_string('command_type')='TARE_BOOK_CANCEL' then v.get_string('booking_operation_id')else p_operation end);
 if v.get_string('place_kind')='CASE' then
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',v.get_string('place_id'));if v.get_number('wave_id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('wave_id')));end if;
 else RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',v.get_string('place_id'));RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v.get_string('place_id'));end if;
 if v.get_string('goods_kind')='STOCK' then RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v.get_string('place_id'),v.get_string('article'),v.get_string('cell'),null);end if;
 if v.has('load_recovery')then RRL_TARE_LOAD_RECOVERY_API.declare_recovery(v.get_object('load_recovery').to_clob,p_operation,r);end if;
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');kind varchar2(80):=d.get_string('command_type');plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_place varchar2(200);v_place_kind varchar2(6);v_key raw(32);v_ware number;v_type number;v_available number;v_book varchar2(100);n number;
 begin
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
 if v.get_number('wave_id') is not null then n:=v.get_number('wave_id');select PICK_WAVE_ID into n from RRL_PICK_WAVE where PICK_WAVE_ID=n for update;end if;
 v_place:=v.get_string('place_id');v_place_kind:=v.get_string('place_kind');
 if v_place_kind='CASE' then n:=to_number(v_place);select CASE_PICK_TASK_ID into n from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=n for update;
 else select HU_CONTENT_VERSION into n from RRL_PALLETS where UID_PALLET=v_place for update;end if;
 v_key:=hextoraw(v.get_string('balance_key'));select QUANTITY into n from RRL_TARE_BALANCE where BALANCE_KEY=v_key for update;
 describe_command(p_request,p_actor,fresh);if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: tare assembly');end if;
 v_ware:=v.get_number('warehouse_id');v_type:=v.get_number('pallet_type_id');v_available:=to_number(v.get_string('available_quantity'));v_book:=v.get_string('booking_operation_id');
 if kind='TARE_BOOK' then
 insert into RRL_TARE_BOOK(OPERATION_ID,BALANCE_KEY,OWNER_WARE_ID,PALLET_TYPE_ID,PLACE_KIND,PLACE_ID,CREATED_BY)values(op,v_key,v_ware,v_type,v_place_kind,v_place,p_actor);
 if v.has('load_recovery')then RRL_TARE_LOAD_RECOVERY_API.record_recovery(v.get_object('load_recovery').to_clob,op,p_actor);j.put('load_recovery',v.get_object('load_recovery'));end if;
 v_available:=v_available-1;
 else
 update RRL_TARE_BOOK set STATUS='CANCELLED',CLOSED_OPERATION_ID=op,CLOSED_BY=p_actor,CLOSED_AT=systimestamp where OPERATION_ID=v_book and STATUS='HELD';
 if sql%rowcount!=1 then raise_application_error(-20886,'TARE_BOOK_CURRENT_HOLD_REQUIRED');end if;v_available:=v_available+1;
 end if;
 update RRL_TARE_BALANCE set BALANCE_VERSION=BALANCE_VERSION+1,LAST_OPERATION_ID=op,UPDATED_AT=systimestamp where BALANCE_KEY=v_key;
 j.put('operation_id',op);j.put('status',case when kind='TARE_BOOK' then 'HELD' else 'CANCELLED' end);j.put('place_kind',v_place_kind);j.put('place_id',v_place);j.put('pallet_type_id',v_type);j.put('warehouse_id',v_ware);
 j.put('available_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_available));j.put('quantity','1');j.put('physical_tare_changed',false);j.put('goods_stock_changed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TARE_CANCEL_CMD as
 procedure assert_scope(p_request clob,p_actor varchar2)is
  d json_object_t:=json_object_t.parse(p_request);o RRL_TARE_OFFER%rowtype;t RRL_TRANSPORT_TASK%rowtype;n number;offer_id varchar2(100);
 begin
  offer_id:=d.get_object('source').get_string('offer_operation_id');
  select *into o from RRL_TARE_OFFER where OPERATION_ID=offer_id;
  select *into t from RRL_TRANSPORT_TASK where ID=o.TT_ID;
  if RRL_HAS_WRIGHT(p_actor,'tare_offer')!=1 then raise_application_error(-20882,'TARE_CANCEL_CURRENT_PERMISSION_REQUIRED');end if;
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and upper(trim(USER_GROUP))='GLOBAL_ADMIN';
  if n=0 then
   if p_actor!=o.OFFERED_BY then raise_application_error(-20882,'TARE_CANCEL_ORIGINAL_SENDER_REQUIRED');end if;
   RRL_TARE_PARTICIPANT.holder_actor(p_actor,o.FROM_KIND,o.FROM_ID,o.OWNER_WARE_ID,t,'tare_offer');
  end if;
 exception when no_data_found then raise_application_error(-20886,'TARE_CANCEL_ORIGINAL_OFFER_REQUIRED');end;
 function describe_command(p_request clob,p_actor varchar2)return json_object_t is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');j json_object_t:=json_object_t();a json_array_t:=json_array_t();x json_object_t;
  id varchar2(100):=d.get_object('source').get_string('offer_operation_id');o RRL_TARE_OFFER%rowtype;t RRL_TRANSPORT_TASK%rowtype;veh RRL_TR_VEHICLE%rowtype;n number;
 begin
  assert_scope(p_request,p_actor);select *into o from RRL_TARE_OFFER where OPERATION_ID=id;
  select count(*)into n from RRL_TARE_ACCEPT where OFFER_OPERATION_ID=id;
  if n!=0 then raise_application_error(-20886,'TARE_CANCEL_ACCEPTED_RETURN_REQUIRED');end if;
  select count(*)into n from RRL_TARE_OFFER_CANCEL where OFFER_OPERATION_ID=id;
  if n!=0 then raise_application_error(-20886,'TARE_OFFER_ALREADY_CANCELLED');end if;
  if trim(m.get_string('reason'))is null or length(m.get_string('reason'))>500 or m.get_string('scan_vehicle')is null or m.get_string('scan_vehicle')!=o.VEHICLE_NUMBER then raise_application_error(-20886,'TARE_CANCEL_REASON_ORIGINAL_VEHICLE_SCAN_REQUIRED');end if;
  select *into t from RRL_TRANSPORT_TASK where ID=o.TT_ID;
  select *into veh from RRL_TR_VEHICLE where ID=o.VEHICLE_ID;
  if nvl(t.DELETED,0)!=0 or t.TRANSPORT!=o.VEHICLE_NUMBER or nvl(veh.DELETED,0)!=0 or veh.NUM!=o.VEHICLE_NUMBER then raise_application_error(-20886,'TARE_CANCEL_CURRENT_ORIGINAL_TRIP_REQUIRED');end if;
  for b in(select ob.BOOK_OPERATION_ID,ob.LOAD_OPERATION_ID,tb.STATUS,lf.STATUS LOAD_STATUS,lf.DEPARTURE_OPERATION_ID from RRL_TARE_OFFER_BOOK ob join RRL_TARE_BOOK tb on tb.OPERATION_ID=ob.BOOK_OPERATION_ID join RRL_TT_HU_LOAD_FACT lf on lf.LOAD_OPERATION_ID=ob.LOAD_OPERATION_ID where ob.OFFER_OPERATION_ID=id order by ob.BOOK_OPERATION_ID)loop
   if b.STATUS!='HELD'or b.LOAD_STATUS!='LOADED'or b.DEPARTURE_OPERATION_ID is not null then raise_application_error(-20886,'TARE_CANCEL_HELD_UNDEPARTED_BOOK_REQUIRED');end if;
   x:=json_object_t();x.put('book',b.BOOK_OPERATION_ID);x.put('load',b.LOAD_OPERATION_ID);a.append(x);
   if a.get_size>100 then raise_application_error(-20881,'TARE_CANCEL_BOOK_BOUND_100');end if;
  end loop;
  j.put('offer_operation_id',id);j.put('task_id',o.TT_ID);j.put('vehicle_id',o.VEHICLE_ID);j.put('warehouse_id',o.OWNER_WARE_ID);j.put('books',a);j.put('reason',m.get_string('reason'));j.put('vehicle',o.VEHICLE_NUMBER);return j;
 exception when no_data_found then raise_application_error(-20886,'TARE_CANCEL_ORIGINAL_CONTEXT_REQUIRED');end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t;x json_object_t;
 begin
  v:=describe_command(p_request,d.get_string('actor'));RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER',v.get_string('offer_operation_id'));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER_CANCEL',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('task_id')));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('vehicle_id')));
  a:=v.get_array('books');
  for i in 0..a.get_size-1 loop x:=treat(a.get(i)as json_object_t);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BOOK',x.get_string('book'));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',x.get_string('load'));
  end loop;
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');wire clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();offer_id varchar2(100);reason_value nvarchar2(500);
 begin
  select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(wire).get_object('domain');
  fresh:=describe_command(p_request,p_actor);
  if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: tare cancellation');end if;
  offer_id:=v.get_string('offer_operation_id');reason_value:=v.get_string('reason');
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TARE_OFFER',offer_id));
  insert into RRL_TARE_OFFER_CANCEL(OPERATION_ID,OFFER_OPERATION_ID,REASON,CANCELLED_BY)values(op,offer_id,reason_value,p_actor);
  j.put('operation_id',op);j.put('offer_operation_id',offer_id);j.put('status','CANCELLED');j.put('tare_balance_changed',false);j.put('original_offer_preserved',true);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TARE_CMD as
 procedure balance(p_key raw,p_qty out number,p_version out number) is
 begin select QUANTITY,BALANCE_VERSION into p_qty,p_version from RRL_TARE_BALANCE where BALANCE_KEY=p_key;
 exception when no_data_found then p_qty:=0;p_version:=0;end;
 function integer_qty(p_text varchar2,p_zero boolean default false) return number is v number;
 begin
 if p_text is null or not regexp_like(p_text,'^[0-9]{1,18}$') then raise_application_error(-20886,'TARE_INTEGER_QUANTITY_REQUIRED');end if;
 v:=to_number(p_text);if not p_zero and v=0 then raise_application_error(-20886,'TARE_POSITIVE_QUANTITY_REQUIRED');end if;return v;
 end;
 procedure describe_command(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');s json_object_t:=d.get_object('source');kind varchar2(80):=d.get_string('command_type');
 v_owner number;v_type number;v_condition varchar2(10);v_from_kind varchar2(12);v_from_id varchar2(255);v_to_kind varchar2(12);v_to_id varchar2(255);
 v_from raw(32);v_to raw(32);v_from_qty number;v_from_version number;v_to_qty number;v_to_version number;v_qty number;v_tt number;v_vehicle number;v_store varchar2(255);v_reason varchar2(2000);v_ref varchar2(255);n number;v_offer_id varchar2(100);v_books json_array_t:=json_array_t();v_damage varchar2(100);
 trip RRL_TRANSPORT_TASK%rowtype;vehicle RRL_TR_VEHICLE%rowtype;offer RRL_TARE_OFFER%rowtype;
 begin
 p_domain:=json_object_t();
 select count(*) into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0;if n!=1 then raise_application_error(-20882,'TARE_ACTIVE_ACTOR_REQUIRED');end if;
 if kind='TARE_COUNT' then
  if RRL_HAS_WRIGHT(p_actor,'tare_adjust')!=1 then raise_application_error(-20882,'TARE_ADJUSTMENT_PERMISSION_REQUIRED');end if;
  v_owner:=m.get_number('owner_ware_id');v_type:=m.get_number('pallet_type_id');v_condition:=m.get_string('condition');
  RRL_TARE_PARTICIPANT.warehouse_actor(p_actor,v_owner);v_to_kind:='WAREHOUSE';v_to_id:=RRL_STOCK_PLAN_HELPER.decimal_text(v_owner);
  v_qty:=integer_qty(m.get_string('observed_quantity'),true);v_reason:=m.get_string('reason');v_ref:=m.get_string('decision_reference');
  if trim(v_reason) is null or lengthb(v_reason)>2000 or trim(v_ref) is null or lengthb(v_ref)>255 then raise_application_error(-20886,'TARE_ADJUSTMENT_REASON_DECISION_REQUIRED');end if;
 else
  if kind='TARE_ACCEPT' then
   v_offer_id:=s.get_string('offer_operation_id');select * into offer from RRL_TARE_OFFER where OPERATION_ID=v_offer_id;
   select count(*)into n from RRL_TARE_OFFER_CANCEL where OFFER_OPERATION_ID=offer.OPERATION_ID;
   if n!=0 then raise_application_error(-20886,'TARE_CANCELLED_OFFER_CANNOT_ACCEPT');end if;
   select count(*) into n from RRL_TARE_ACCEPT where OFFER_OPERATION_ID=offer.OPERATION_ID;
   if n!=0 then raise_application_error(-20886,'TARE_OFFER_ALREADY_ACCEPTED');end if;
   v_owner:=offer.OWNER_WARE_ID;v_type:=offer.PALLET_TYPE_ID;v_condition:=offer.CONDITION_CODE;
   v_from_kind:=offer.FROM_KIND;v_from_id:=offer.FROM_ID;v_to_kind:=offer.TO_KIND;v_to_id:=offer.TO_ID;v_tt:=offer.TT_ID;v_vehicle:=offer.VEHICLE_ID;v_store:=offer.STORE_ADDR;
   v_qty:=integer_qty(m.get_string('accepted_quantity'));
   if v_qty>offer.QUANTITY then raise_application_error(-20886,'TARE_ACCEPTED_QUANTITY_EXCEEDS_OFFER');end if;
   if offer.OFFERED_BY=p_actor then raise_application_error(-20882,'TARE_TWO_DIFFERENT_PARTICIPANTS_REQUIRED');end if;
   v_damage:=RRL_TARE_DAMAGE_TRACE.offer_origin(offer.OPERATION_ID);
   p_domain.put('offer_operation_id',offer.OPERATION_ID);p_domain.put('offered_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(offer.QUANTITY));
  else
   v_owner:=m.get_number('owner_ware_id');v_type:=m.get_number('pallet_type_id');v_condition:=m.get_string('condition');
   v_from_kind:=m.get_string('from_kind');v_from_id:=m.get_string('from_id');v_to_kind:=m.get_string('to_kind');v_to_id:=m.get_string('to_id');
   v_tt:=s.get_number('task_id');v_qty:=integer_qty(m.get_string('quantity'));v_damage:=s.get_string('damage_operation_id');
  end if;
  if v_from_kind||'>'||v_to_kind not in('WAREHOUSE>VEHICLE','VEHICLE>STORE','STORE>VEHICLE','VEHICLE>WAREHOUSE') then raise_application_error(-20886,'TARE_SUPPORTED_PHYSICAL_TRANSFER_REQUIRED');end if;
  select * into trip from RRL_TRANSPORT_TASK where ID=v_tt;
  select * into vehicle from RRL_TR_VEHICLE where NUM=trip.TRANSPORT and nvl(DELETED,0)=0;
  if nvl(trip.DELETED,0)!=0 or trip.CONDITION is null or trip.CONDITION not in(unistr('\0421\043F\043B\0430\043D\0438\0440\043E\0432\0430\043D'),unistr('\041E\0442\0433\0440\0443\0436\0435\043D'))
   or nvl(vehicle.BLOCKED,0)!=0 or nvl(vehicle.WORKING_NOW,0)!=1 or trip.VODITEL_ID is null then raise_application_error(-20886,'TARE_CURRENT_ACTIVE_TRIP_VEHICLE_DRIVER_REQUIRED');end if;
  select count(*) into n from RRL_TR_VODITEL where ID=trip.VODITEL_ID and nvl(DELETED,0)=0;
  if n!=1 then raise_application_error(-20886,'TARE_ACTIVE_DRIVER_REQUIRED');end if;
  if kind='TARE_ACCEPT' and(v_vehicle!=vehicle.ID or offer.VEHICLE_NUMBER!=vehicle.NUM) then raise_application_error(-20886,'TARE_ORIGINAL_TRIP_VEHICLE_CHANGED');end if;
  v_vehicle:=vehicle.ID;
  if(v_from_kind='VEHICLE' and v_from_id!=RRL_STOCK_PLAN_HELPER.decimal_text(v_vehicle)) or(v_to_kind='VEHICLE' and v_to_id!=RRL_STOCK_PLAN_HELPER.decimal_text(v_vehicle))
   or(v_from_kind='WAREHOUSE' and v_from_id!=RRL_STOCK_PLAN_HELPER.decimal_text(v_owner)) or(v_to_kind='WAREHOUSE' and v_to_id!=RRL_STOCK_PLAN_HELPER.decimal_text(v_owner)) then raise_application_error(-20886,'TARE_CURRENT_HOLDER_ID_REQUIRED');end if;
  if v_from_kind='STORE' or v_to_kind='STORE' then
   v_store:=case when v_from_kind='STORE' then v_from_id else v_to_id end;
   if trip.CONDITION!=unistr('\041E\0442\0433\0440\0443\0436\0435\043D') then raise_application_error(-20886,'TARE_STORE_TRANSFER_DEPARTED_TRIP_REQUIRED');end if;
   select count(*) into n from RRL_SBORKA_PALLETS where TRANSTASK_ID=trip.ID and ADDR=v_store;
   if n=0 then raise_application_error(-20886,'TARE_STORE_NOT_IN_EXISTING_TRIP');end if;
  end if;
  if m.get_string('scan_vehicle') is null or m.get_string('scan_vehicle')!=vehicle.NUM then raise_application_error(-20886,'TARE_CURRENT_VEHICLE_SCAN_REQUIRED');end if;
  RRL_TARE_PARTICIPANT.holder_actor(p_actor,case when kind='TARE_ACCEPT' then v_to_kind else v_from_kind end,case when kind='TARE_ACCEPT' then v_to_id else v_from_id end,v_owner,trip,case when kind='TARE_ACCEPT' then 'tare_accept' else 'tare_offer' end);
  v_from:=RRL_TARE_BALANCE_KEY(v_owner,v_type,v_condition,v_from_kind,v_from_id);balance(v_from,v_from_qty,v_from_version);
  if v_from_qty<v_qty then raise_application_error(-20886,'TARE_SOURCE_QUANTITY_UNAVAILABLE');end if;
  p_domain.put('from_key',rawtohex(v_from));p_domain.put('from_kind',v_from_kind);p_domain.put('from_id',v_from_id);p_domain.put('from_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_from_qty));p_domain.put('from_version',v_from_version);
  p_domain.put('task_id',trip.ID);p_domain.put('vehicle_id',vehicle.ID);p_domain.put('vehicle_number',vehicle.NUM);p_domain.put('driver_id',trip.VODITEL_ID);p_domain.put('store_address',v_store);
 end if;
 if v_owner is null or v_type is null or v_condition is null or v_condition not in('GOOD','DAMAGED') or v_to_id is null or v_from_id is null and kind!='TARE_COUNT' then raise_application_error(-20886,'TARE_OWNER_TYPE_CONDITION_HOLDER_REQUIRED');end if;
 select count(*) into n from RRL_WARES where ID=v_owner;if n!=1 then raise_application_error(-20886,'TARE_OWNER_WAREHOUSE_REQUIRED');end if;
 select count(*) into n from RRL_PALLET_TYPE where PALLET_TYPE_ID=v_type and ACTIVE=1;if n!=1 then raise_application_error(-20886,'TARE_ACTIVE_EXISTING_PALLET_TYPE_REQUIRED');end if;
 v_to:=RRL_TARE_BALANCE_KEY(v_owner,v_type,v_condition,v_to_kind,v_to_id);balance(v_to,v_to_qty,v_to_version);
 if kind='TARE_COUNT' and v_qty<RRL_TARE_PLANNING.held_quantity(v_to) then raise_application_error(-20886,'TARE_COUNT_BELOW_ASSEMBLY_HOLD');end if;
 if kind in('TARE_OFFER','TARE_ACCEPT') then
 RRL_STOCK_TARE_HANDOVER.describe_books(p_request,kind,v_offer_id,v_owner,v_type,v_condition,v_from_kind,v_tt,v_vehicle,v_qty,v_books);p_domain.put('booked_places',v_books);
 RRL_TARE_PLANNING.assert_available(v_from,v_from_qty+v_books.get_size,v_qty);end if;
 if v_condition='DAMAGED' then
 if kind='TARE_COUNT' then
  if v_qty<RRL_TARE_DAMAGE_TRACE.tracked_quantity(v_to)+RRL_TARE_PLANNING.held_quantity(v_to)then raise_application_error(-20886,'TARE_COUNT_BELOW_DAMAGE_CUSTODY');end if;
 else RRL_TARE_DAMAGE_TRACE.check_transfer(v_damage,v_from,v_qty,v_from_qty);end if;
 elsif v_damage is not null then raise_application_error(-20886,'TARE_DAMAGE_CONDITION_REQUIRED');end if;
 p_domain.put('damage_operation_id',v_damage);
 if kind='TARE_COUNT' and(m.get_number('expected_version') is null or m.get_number('expected_version')!=v_to_version)then raise_application_error(-20886,'TARE_COUNT_VERSION_CONFLICT');end if;
 p_domain.put('owner_ware_id',v_owner);p_domain.put('pallet_type_id',v_type);p_domain.put('condition',v_condition);p_domain.put('to_key',rawtohex(v_to));p_domain.put('to_kind',v_to_kind);p_domain.put('to_id',v_to_id);
 p_domain.put('to_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_to_qty));p_domain.put('to_version',v_to_version);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));
 if kind='TARE_COUNT' then p_domain.put('reason',v_reason);p_domain.put('decision_reference',v_ref);end if;
 if kind='TARE_ACCEPT' and v_to_kind='STORE' then
  declare policy_domain json_object_t;begin RRL_STOCK_TARE_POLICY.describe_store(v_to_id,policy_domain);p_domain.put('return_policy',policy_domain);end;
 end if;
 exception when no_data_found then raise_application_error(-20886,'TARE_ORIGINAL_HOLDER_TRIP_OR_OFFER_REQUIRED');when too_many_rows then raise_application_error(-20886,'TARE_EXISTING_VEHICLE_IDENTITY_AMBIGUOUS');end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();kind varchar2(80):=d.get_string('command_type');
 begin
 describe_command(p_request,d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BALANCE',v.get_string('to_key'));
 if kind!='TARE_COUNT' then
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BALANCE',v.get_string('from_key'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('task_id')));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('vehicle_id')));
 end if;
 if kind='TARE_OFFER' then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER',p_operation);
 elsif kind='TARE_ACCEPT' then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER',v.get_string('offer_operation_id'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_ACCEPT',p_operation);end if;
 if kind!='TARE_OFFER' then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_JOURNAL',p_operation);end if;
 if kind='TARE_ACCEPT' and v.get_string('to_kind')='STORE' then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_DELIVERY_POLICY',p_operation);end if;
 if v.get_string('damage_operation_id')is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_RESOLUTION',v.get_string('damage_operation_id'));end if;
 if kind in('TARE_OFFER','TARE_ACCEPT') then RRL_STOCK_TARE_HANDOVER.declare_books(v.get_array('booked_places'),case when kind='TARE_OFFER' then p_operation else v.get_string('offer_operation_id')end,r);end if;
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);kind varchar2(80):=d.get_string('command_type');op varchar2(100):=d.get_string('operation_id');
 v json_object_t;fresh json_object_t;plan clob;j json_object_t:=json_object_t();
 v_owner number;v_type number;v_condition varchar2(10);v_from raw(32);v_to raw(32);v_to_kind varchar2(12);v_to_id varchar2(255);v_from_kind varchar2(12);v_from_id varchar2(255);
 v_qty number;v_before number;v_after number;v_version number;v_reason varchar2(2000);v_ref varchar2(255);v_offer varchar2(100);v_offered number;v_tt number;v_vehicle number;v_vehicle_num varchar2(50);v_store varchar2(255);n number;
 begin
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
 if kind!='TARE_COUNT' then
  v_tt:=v.get_number('task_id');v_vehicle:=v.get_number('vehicle_id');
  select ID into n from RRL_TRANSPORT_TASK where ID=v_tt for update;
  select ID into n from RRL_TR_VEHICLE where ID=v_vehicle for update;
 end if;
 v_from:=hextoraw(v.get_string('from_key'));v_to:=hextoraw(v.get_string('to_key'));
 for row_record in(select BALANCE_KEY from RRL_TARE_BALANCE where BALANCE_KEY in(v_from,v_to)order by BALANCE_KEY for update)loop null;end loop;
 describe_command(p_request,p_actor,fresh);
 if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: tare context or quantity');end if;
 v_owner:=v.get_number('owner_ware_id');v_type:=v.get_number('pallet_type_id');v_condition:=v.get_string('condition');
 v_from:=hextoraw(v.get_string('from_key'));v_to:=hextoraw(v.get_string('to_key'));v_to_kind:=v.get_string('to_kind');v_to_id:=v.get_string('to_id');v_from_kind:=v.get_string('from_kind');v_from_id:=v.get_string('from_id');
 v_qty:=integer_qty(v.get_string('quantity'),kind='TARE_COUNT');v_before:=to_number(v.get_string('to_quantity'));v_version:=v.get_number('to_version');
 if kind='TARE_OFFER' then
  v_vehicle_num:=v.get_string('vehicle_number');v_store:=v.get_string('store_address');
  insert into RRL_TARE_OFFER(OPERATION_ID,FROM_BALANCE_KEY,TO_BALANCE_KEY,TT_ID,VEHICLE_ID,VEHICLE_NUMBER,STORE_ADDR,OWNER_WARE_ID,PALLET_TYPE_ID,CONDITION_CODE,FROM_KIND,FROM_ID,TO_KIND,TO_ID,QUANTITY,OFFERED_BY)
  values(op,v_from,v_to,v_tt,v_vehicle,v_vehicle_num,v_store,v_owner,v_type,v_condition,v_from_kind,v_from_id,v_to_kind,v_to_id,v_qty,p_actor);
  RRL_STOCK_TARE_HANDOVER.persist_offer(op,v.get_array('booked_places'));
  RRL_TARE_DAMAGE_TRACE.record_offer(op,v.get_string('damage_operation_id'));
  j.put('status','WAITING_OTHER_PARTICIPANT');j.put('tare_balance_changed',false);
 else
  if kind='TARE_ACCEPT' then
   v_offer:=v.get_string('offer_operation_id');v_offered:=to_number(v.get_string('offered_quantity'));
   insert into RRL_TARE_ACCEPT(OPERATION_ID,OFFER_OPERATION_ID,ACCEPTED_QTY,SHORT_QTY,ACCEPTED_BY)values(op,v_offer,v_qty,v_offered-v_qty,p_actor);
   RRL_STOCK_TARE_HANDOVER.transfer_books(v.get_array('booked_places'),op,p_actor);
   if v_to_kind='STORE' then RRL_STOCK_TARE_POLICY.record_delivery(op,v.get_object('return_policy'));end if;
   update RRL_TARE_BALANCE set QUANTITY=QUANTITY-v_qty,BALANCE_VERSION=BALANCE_VERSION+1,LAST_OPERATION_ID=op,UPDATED_AT=systimestamp
    where BALANCE_KEY=v_from and QUANTITY>=v_qty;
   if sql%rowcount!=1 then raise_application_error(-20886,'TARE_SOURCE_QUANTITY_UNAVAILABLE');end if;
   v_after:=v_before+v_qty;
  else v_after:=v_qty;v_reason:=v.get_string('reason');v_ref:=v.get_string('decision_reference');end if;
  merge into RRL_TARE_BALANCE b using(select v_to BALANCE_KEY from dual)s on(b.BALANCE_KEY=s.BALANCE_KEY)
  when matched then update set QUANTITY=v_after,BALANCE_VERSION=BALANCE_VERSION+1,LAST_OPERATION_ID=op,UPDATED_AT=systimestamp
  when not matched then insert(BALANCE_KEY,OWNER_WARE_ID,PALLET_TYPE_ID,CONDITION_CODE,CUSTODIAN_KIND,CUSTODIAN_ID,QUANTITY,BALANCE_VERSION,LAST_OPERATION_ID)
  values(v_to,v_owner,v_type,v_condition,v_to_kind,v_to_id,v_after,1,op);
  insert into RRL_TARE_JOURNAL(OPERATION_ID,ACTION_KIND,FROM_BALANCE_KEY,TO_BALANCE_KEY,QUANTITY,BEFORE_QTY,AFTER_QTY,REASON_TEXT,DECISION_REFERENCE,ACTOR)
  values(op,case when kind='TARE_COUNT' then 'COUNT' else 'TRANSFER' end,v_from,v_to,case when kind='TARE_COUNT' then v_after-v_before else v_qty end,v_before,v_after,v_reason,v_ref,p_actor);
  if kind='TARE_ACCEPT' then RRL_TARE_DAMAGE_TRACE.record_transfer(op,v.get_string('damage_operation_id'),v_from,v_to,v_qty);end if;
  j.put('status','POSTED');j.put('tare_balance_changed',true);j.put('destination_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_after));
  if kind='TARE_ACCEPT' then j.put('offer_operation_id',v_offer);j.put('short_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_offered-v_qty));end if;
 end if;
 j.put('operation_id',op);j.put('quantity',v.get_string('quantity'));j.put('owner_ware_id',v_owner);j.put('pallet_type_id',v_type);j.put('condition',v_condition);
 j.put('goods_stock_changed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TARE_HANDOVER as
 procedure describe_books(p_request clob,p_kind varchar2,p_offer varchar2,p_owner number,p_type number,p_condition varchar2,p_from_kind varchar2,p_trip number,p_vehicle number,p_qty number,p_books out json_array_t) is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');ids json_array_t:=json_array_t();item json_object_t;book RRL_TARE_BOOK%rowtype;
 v_id varchar2(100);v_load varchar2(100);v_saved_load varchar2(100);n number;case_no number;seen clob;
 begin
 if p_kind='TARE_ACCEPT' then
  for row_record in(select BOOK_OPERATION_ID from RRL_TARE_OFFER_BOOK where OFFER_OPERATION_ID=p_offer order by BOOK_OPERATION_ID)loop ids.append(row_record.BOOK_OPERATION_ID);end loop;
 elsif m.has('booking_operation_ids') then ids:=m.get_array('booking_operation_ids');end if;
 if ids is null or ids.get_size>100 then raise_application_error(-20881,'TARE_HANDOVER_BOOK_BOUND_100');end if;
 if ids.get_size>0 and(p_from_kind!='WAREHOUSE' or p_condition!='GOOD')then raise_application_error(-20886,'TARE_HANDOVER_GOOD_WAREHOUSE_BOOKS_REQUIRED');end if;
 if p_qty<ids.get_size then raise_application_error(-20886,'TARE_HANDOVER_WHOLE_SELECTED_BOOKS_REQUIRED');end if;
 p_books:=json_array_t();seen:=ids.to_clob;
 select count(*)-count(distinct ID) into n from json_table(seen,'$[*]' columns(ID varchar2(100) path '$' error on error));
 if n!=0 then raise_application_error(-20886,'TARE_HANDOVER_DUPLICATE_BOOK');end if;
 for row_record in(select ID from json_table(seen,'$[*]' columns(ID varchar2(100) path '$' error on error))order by ID)loop
  v_id:=row_record.ID;select * into book from RRL_TARE_BOOK where OPERATION_ID=v_id and STATUS='HELD';
  if p_kind='TARE_OFFER'then
   select count(*)into n from RRL_TARE_OFFER_BOOK ob where ob.BOOK_OPERATION_ID=v_id and not exists(select 1 from RRL_TARE_OFFER_CANCEL c where c.OFFER_OPERATION_ID=ob.OFFER_OPERATION_ID);
   if n>0 then raise_application_error(-20886,'TARE_BOOK_HAS_ACTIVE_HANDOVER_OFFER');end if;
  end if;
  if book.OWNER_WARE_ID!=p_owner or book.PALLET_TYPE_ID!=p_type then raise_application_error(-20886,'TARE_HANDOVER_BOOK_WARE_TYPE_CONFLICT');end if;
  case_no:=case when book.PLACE_KIND='CASE' then to_number(book.PLACE_ID) else null end;
  select count(*),min(lf.LOAD_OPERATION_ID)into n,v_load from RRL_TT_HU_LOAD_FACT lf
   where lf.TT_ID=p_trip and lf.VEHICLE_ID=p_vehicle and lf.WARE_ID=p_owner and lf.STATUS in('LOADED','DEPARTED')
   and((book.PLACE_KIND='HU'and lf.ROOT_UID=book.PLACE_ID)or(book.PLACE_KIND='CASE'and lf.ROOT_CASE_TASK_ID=case_no)
    or(book.PLACE_KIND='CASE'and exists(select 1 from json_table(lf.COMPOSITION_JSON,'$.nodes[*]'
     columns(K varchar2(20)path '$.kind',CASE_ID number path '$.case_task_id'))node where node.K='CASE'and node.CASE_ID=case_no)));
  if n!=1 then raise_application_error(-20886,'TARE_HANDOVER_ONE_ARCHIVED_PHYSICAL_LOAD_REQUIRED');end if;
  if p_kind='TARE_ACCEPT' then
   select LOAD_OPERATION_ID into v_saved_load from RRL_TARE_OFFER_BOOK where OFFER_OPERATION_ID=p_offer and BOOK_OPERATION_ID=v_id;
   if v_saved_load!=v_load then raise_application_error(-20886,'TARE_HANDOVER_ORIGINAL_LOAD_CHANGED');end if;
  end if;
  item:=json_object_t();item.put('booking_operation_id',v_id);item.put('load_operation_id',v_load);item.put('place_kind',book.PLACE_KIND);item.put('place_id',book.PLACE_ID);p_books.append(item);
 end loop;
 exception when no_data_found then raise_application_error(-20886,'TARE_HANDOVER_CURRENT_BOOK_AND_ACTUAL_LOAD_REQUIRED');end;
 procedure declare_books(p_books json_array_t,p_offer varchar2,p_resources in out nocopy json_array_t) is
 item json_object_t;v_id varchar2(100);
 begin
 if p_books.get_size>0 then
 for idx in 0..p_books.get_size-1 loop
  item:=treat(p_books.get(idx) as json_object_t);v_id:=item.get_string('booking_operation_id');
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_TARE_BOOK',v_id);
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_TARE_OFFER_BOOK',p_offer||':'||v_id);
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_TT_HU_LOAD_FACT',item.get_string('load_operation_id'));
 end loop;end if;
 end;
 procedure persist_offer(p_offer varchar2,p_books json_array_t) is
 item json_object_t;v_id varchar2(100);v_load varchar2(100);
 begin
 if p_books.get_size>0 then for idx in 0..p_books.get_size-1 loop
 item:=treat(p_books.get(idx) as json_object_t);v_id:=item.get_string('booking_operation_id');v_load:=item.get_string('load_operation_id');
 insert into RRL_TARE_OFFER_BOOK(OFFER_OPERATION_ID,BOOK_OPERATION_ID,LOAD_OPERATION_ID)values(p_offer,v_id,v_load);
 end loop;end if;
 end;
 procedure transfer_books(p_books json_array_t,p_operation varchar2,p_actor varchar2) is
 item json_object_t;v_id varchar2(100);
 begin
 if p_books.get_size>0 then for idx in 0..p_books.get_size-1 loop
 item:=treat(p_books.get(idx) as json_object_t);v_id:=item.get_string('booking_operation_id');
 update RRL_TARE_BOOK set STATUS='TRANSFERRED',CLOSED_OPERATION_ID=p_operation,CLOSED_BY=p_actor,CLOSED_AT=systimestamp where OPERATION_ID=v_id and STATUS='HELD';
 if sql%rowcount!=1 then raise_application_error(-20886,'TARE_HANDOVER_BOOK_ALREADY_TRANSFERRED');end if;
 end loop;end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TARE_LOSS as
 procedure describe_command(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');s json_object_t:=d.get_object('source');kind varchar2(80):=d.get_string('command_type');
 v_claim varchar2(100);claim RRL_TARE_LOSS_CLAIM%rowtype;v_owner number;v_type number;v_condition varchar2(10);v_qty number;v_key raw(32);v_p number;v_version number;v_held number;n number;
 v_reason varchar2(32767):=m.get_string('reason');v_ref varchar2(32767):=m.get_string('decision_reference');v_outcome varchar2(12);v_holder varchar2(12);v_id varchar2(255);v_source_claim varchar2(100);v_delivery varchar2(100);v_tt number;v_vehicle number;v_plate varchar2(50);v_outstanding number;v_pending number;trip RRL_TRANSPORT_TASK%rowtype;
 begin
 select count(*) into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0;if n!=1 then raise_application_error(-20882,'TARE_ACTIVE_ACTOR_REQUIRED');end if;
 if trim(v_reason) is null or lengthb(v_reason)>2000 or trim(v_ref) is null or lengthb(v_ref)>255 then raise_application_error(-20886,'TARE_LOSS_REASON_DECISION_REQUIRED');end if;
 if kind='TARE_LOSS_REPORT' then
  if RRL_HAS_WRIGHT(p_actor,'tare_loss_report')!=1 then raise_application_error(-20882,'TARE_LOSS_REPORT_PERMISSION_REQUIRED');end if;
  v_owner:=m.get_number('owner_ware_id');v_type:=m.get_number('pallet_type_id');v_condition:=m.get_string('condition');
  if v_owner is null or v_type is null or v_condition is null or v_condition not in('GOOD','DAMAGED') then raise_application_error(-20886,'TARE_WAREHOUSE_LOSS_TYPE_REQUIRED');end if;
  if not regexp_like(m.get_string('quantity'),'^[0-9]{1,18}$') then raise_application_error(-20886,'TARE_INTEGER_QUANTITY_REQUIRED');end if;
  v_qty:=RRL_STOCK_MATH.quantity(m.get_string('quantity'));
  v_holder:=nvl(m.get_string('custodian_kind'),'WAREHOUSE');v_id:=nvl(m.get_string('custodian_id'),RRL_STOCK_PLAN_HELPER.decimal_text(v_owner));
  if v_holder not in('WAREHOUSE','VEHICLE','STORE')then raise_application_error(-20886,'TARE_LOSS_CURRENT_HOLDER_REQUIRED');end if;
  if v_holder='WAREHOUSE' and v_id!=RRL_STOCK_PLAN_HELPER.decimal_text(v_owner)then raise_application_error(-20886,'TARE_LOSS_WAREHOUSE_ID_CONFLICT');end if;
  if v_holder='VEHICLE' then
   v_tt:=s.get_number('task_id');select * into trip from RRL_TRANSPORT_TASK where ID=v_tt and nvl(DELETED,0)=0;
   select ID,NUM into v_vehicle,v_plate from RRL_TR_VEHICLE where NUM=trip.TRANSPORT and nvl(DELETED,0)=0 and nvl(BLOCKED,0)=0;
   if v_id!=RRL_STOCK_PLAN_HELPER.decimal_text(v_vehicle)or m.get_string('scan_vehicle') is null or m.get_string('scan_vehicle')!=v_plate then raise_application_error(-20886,'TARE_LOSS_CURRENT_VEHICLE_SCAN_REQUIRED');end if;
  end if;
  RRL_TARE_PARTICIPANT.holder_actor(p_actor,v_holder,v_id,v_owner,trip,'tare_loss_report');
  if v_holder='STORE' then v_source_claim:=s.get_string('source_claim_id');end if;
 else
  if RRL_HAS_WRIGHT(p_actor,'tare_writeoff')!=1 then raise_application_error(-20882,'TARE_LOSS_DECISION_PERMISSION_REQUIRED');end if;
  v_claim:=s.get_string('claim_operation_id');select * into claim from RRL_TARE_LOSS_CLAIM where OPERATION_ID=v_claim;
  if claim.ACTOR=p_actor then raise_application_error(-20882,'TARE_INDEPENDENT_LOSS_DECISION_REQUIRED');end if;
  v_owner:=claim.OWNER_WARE_ID;v_type:=claim.PALLET_TYPE_ID;v_condition:=claim.CONDITION_CODE;v_qty:=claim.QUANTITY;
  select CUSTODIAN_KIND,CUSTODIAN_ID into v_holder,v_id from RRL_TARE_BALANCE where BALANCE_KEY=claim.BALANCE_KEY;
  v_source_claim:=claim.SOURCE_CLAIM_ID;v_tt:=claim.TRANSPORT_TASK_ID;
  v_outcome:=m.get_string('outcome');if v_outcome is null or v_outcome not in('WRITE_OFF','REJECT') then raise_application_error(-20886,'TARE_LOSS_EXPLICIT_OUTCOME_REQUIRED');end if;
  select count(*) into n from RRL_TARE_LOSS_DECISION where CLAIM_OPERATION_ID=v_claim;if n!=0 then raise_application_error(-20886,'TARE_LOSS_ALREADY_DECIDED');end if;
 end if;
 v_key:=RRL_TARE_BALANCE_KEY(v_owner,v_type,v_condition,v_holder,v_id);
 select QUANTITY,BALANCE_VERSION into v_p,v_version from RRL_TARE_BALANCE where BALANCE_KEY=v_key;
 v_held:=RRL_TARE_PLANNING.held_quantity(v_key);
 if v_holder='STORE' then
  select OUTSTANDING_QTY,ACCEPT_OPERATION_ID into v_outstanding,v_delivery from RRL_TARE_STORE_DEBT where CLAIM_KEY=v_source_claim and OWNER_WARE_ID=v_owner and PALLET_TYPE_ID=v_type and STORE_ADDR=v_id and CONDITION_CODE=v_condition;
  select nvl(sum(c.QUANTITY),0) into v_pending from RRL_TARE_LOSS_CLAIM c where c.SOURCE_CLAIM_ID=v_source_claim and not exists(select 1 from RRL_TARE_LOSS_DECISION x where x.CLAIM_OPERATION_ID=c.OPERATION_ID);
  if v_qty>v_outstanding-case when kind='TARE_LOSS_REPORT' then v_pending else 0 end then raise_application_error(-20886,'TARE_LOSS_ORIGINAL_STORE_CLAIM_EXCEEDED');end if;
 end if;
 if kind='TARE_LOSS_REPORT' then
  if m.get_number('expected_version') is null or m.get_number('expected_version')!=v_version then raise_application_error(-20886,'TARE_LOSS_BALANCE_VERSION_CONFLICT');end if;
  RRL_TARE_PLANNING.assert_available(v_key,v_p,v_qty);
  if v_condition='DAMAGED' then RRL_TARE_DAMAGE_TRACE.check_transfer(null,v_key,v_qty,v_p);end if;
 elsif v_p<v_held or v_qty>v_p then raise_application_error(-20886,'TARE_LOSS_PENDING_PHYSICAL_BALANCE_CONFLICT');end if;
 p_domain:=json_object_t();p_domain.put('claim_operation_id',v_claim);p_domain.put('owner_ware_id',v_owner);p_domain.put('pallet_type_id',v_type);p_domain.put('condition',v_condition);
 p_domain.put('custodian_kind',v_holder);p_domain.put('custodian_id',v_id);p_domain.put('source_claim_id',v_source_claim);p_domain.put('task_id',v_tt);p_domain.put('vehicle_id',v_vehicle);p_domain.put('vehicle_number',v_plate);p_domain.put('delivery_accept_operation_id',v_delivery);p_domain.put('store_outstanding',v_outstanding);p_domain.put('store_pending',v_pending);
 p_domain.put('balance_key',rawtohex(v_key));p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));p_domain.put('physical_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_p));p_domain.put('balance_version',v_version);p_domain.put('held_quantity',v_held);
 p_domain.put('outcome',v_outcome);p_domain.put('reason',v_reason);p_domain.put('decision_reference',v_ref);
 exception when no_data_found then raise_application_error(-20886,'TARE_LOSS_EXISTING_BALANCE_CLAIM_REQUIRED');end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
 describe_command(p_request,d.get_string('actor'),v);
 RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BALANCE',v.get_string('balance_key'));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_LOSS_CLAIM',case when d.get_string('command_type')='TARE_LOSS_REPORT' then p_operation else v.get_string('claim_operation_id')end);
 if d.get_string('command_type')='TARE_LOSS_DECIDE' then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_LOSS_DECISION',p_operation);end if;
 if v.get_string('source_claim_id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_OPERATION',v.get_string('source_claim_id'));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_ACCEPT',v.get_string('delivery_accept_operation_id'));end if;
 if v.get_number('task_id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('task_id')));end if;
 if v.get_number('vehicle_id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('vehicle_id')));end if;
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');kind varchar2(80):=d.get_string('command_type');plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_key raw(32);v_claim varchar2(100);v_owner number;v_type number;v_condition varchar2(10);v_qty number;v_outcome varchar2(12);v_reason varchar2(2000);v_ref varchar2(255);n number;v_source_claim varchar2(100);v_tt number;
 begin
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');v_key:=hextoraw(v.get_string('balance_key'));v_claim:=v.get_string('claim_operation_id');
 if v.get_number('task_id') is not null then n:=v.get_number('task_id');select ID into n from RRL_TRANSPORT_TASK where ID=n for update;end if;
 if v.get_number('vehicle_id') is not null then n:=v.get_number('vehicle_id');select ID into n from RRL_TR_VEHICLE where ID=n for update;end if;
 select QUANTITY into n from RRL_TARE_BALANCE where BALANCE_KEY=v_key for update;
 if v_claim is not null then select QUANTITY into n from RRL_TARE_LOSS_CLAIM where OPERATION_ID=v_claim for update;end if;
 describe_command(p_request,p_actor,fresh);if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: tare loss');end if;
 v_owner:=v.get_number('owner_ware_id');v_type:=v.get_number('pallet_type_id');v_condition:=v.get_string('condition');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));v_outcome:=v.get_string('outcome');v_reason:=v.get_string('reason');v_ref:=v.get_string('decision_reference');
 v_source_claim:=v.get_string('source_claim_id');v_tt:=v.get_number('task_id');
 if kind='TARE_LOSS_REPORT' then
 insert into RRL_TARE_LOSS_CLAIM(OPERATION_ID,BALANCE_KEY,OWNER_WARE_ID,PALLET_TYPE_ID,CONDITION_CODE,QUANTITY,REASON_TEXT,DECISION_REFERENCE,ACTOR,SOURCE_CLAIM_ID,TRANSPORT_TASK_ID)values(op,v_key,v_owner,v_type,v_condition,v_qty,v_reason,v_ref,p_actor,v_source_claim,v_tt);
 else
 insert into RRL_TARE_LOSS_DECISION(OPERATION_ID,CLAIM_OPERATION_ID,OUTCOME,REASON_TEXT,DECISION_REFERENCE,ACTOR)values(op,v_claim,v_outcome,v_reason,v_ref,p_actor);
 end if;
 update RRL_TARE_BALANCE set QUANTITY=QUANTITY-case when v_outcome='WRITE_OFF' then v_qty else 0 end,BALANCE_VERSION=BALANCE_VERSION+1,LAST_OPERATION_ID=op,UPDATED_AT=systimestamp where BALANCE_KEY=v_key;
 j.put('operation_id',op);j.put('status',case when kind='TARE_LOSS_REPORT' then 'REPORTED' else v_outcome end);j.put('quantity',v.get_string('quantity'));j.put('total_tare_changed',v_outcome='WRITE_OFF');j.put('goods_stock_changed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TARE_POLICY as
 procedure describe_store(p_store varchar2,p_domain out json_object_t) is
 policy RRL_TARE_RETURN_POLICY%rowtype;v_customer number;v_key varchar2(255);n number;
 begin
 select count(*) into n from RRL_TARE_RETURN_POLICY where SCOPE_KIND='STORE' and SCOPE_KEY=p_store;
 if n=1 then select * into policy from RRL_TARE_RETURN_POLICY where SCOPE_KIND='STORE' and SCOPE_KEY=p_store;
 else
  select count(distinct CUSTOMER_ID),min(CUSTOMER_ID) into n,v_customer from RRL_CUSTOMER_STORE_MAP where LEGACY_ADDR=p_store and ACTIVE=1;
  if n!=1 then raise_application_error(-20886,'TARE_EXPLICIT_STORE_POLICY_OR_SINGLE_CUSTOMER_REQUIRED');end if;
  v_key:=RRL_STOCK_PLAN_HELPER.decimal_text(v_customer);
  select * into policy from RRL_TARE_RETURN_POLICY where SCOPE_KIND='CUSTOMER' and SCOPE_KEY=v_key;
 end if;
 p_domain:=json_object_t();p_domain.put('scope_kind',policy.SCOPE_KIND);p_domain.put('scope_key',policy.SCOPE_KEY);p_domain.put('policy_version',policy.POLICY_VERSION);p_domain.put('return_mode',policy.RETURN_MODE);p_domain.put('return_days',policy.RETURN_DAYS);p_domain.put('timezone_region',policy.TIMEZONE_REGION);
 exception when no_data_found then raise_application_error(-20886,'TARE_RETURN_POLICY_REQUIRED');end;
 procedure record_delivery(p_operation varchar2,p_domain json_object_t) is
 v_scope varchar2(10):=p_domain.get_string('scope_kind');v_key varchar2(255):=p_domain.get_string('scope_key');v_version number:=p_domain.get_number('policy_version');
 v_mode varchar2(16):=p_domain.get_string('return_mode');v_days number:=p_domain.get_number('return_days');v_tz varchar2(64):=p_domain.get_string('timezone_region');
 v_accepted timestamp with time zone;v_due timestamp with time zone;v_day date;
 begin
 select ACCEPTED_AT into v_accepted from RRL_TARE_ACCEPT where OPERATION_ID=p_operation;
 if v_mode!='NEXT_DELIVERY' then
  select trunc(cast(v_accepted at time zone (v_tz) as date)) into v_day from dual;
  v_due:=from_tz(cast(v_day+1+case when v_mode='DAYS' then v_days else 0 end as timestamp),v_tz);
 end if;
 insert into RRL_TARE_DELIVERY_POLICY(ACCEPT_OPERATION_ID,SCOPE_KIND,SCOPE_KEY,POLICY_VERSION,RETURN_MODE,RETURN_DAYS,TIMEZONE_REGION,DUE_AT)
 values(p_operation,v_scope,v_key,v_version,v_mode,v_days,v_tz,v_due);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TARE_RESOLVE as
 procedure read_balance(p_key raw,p_qty out number,p_version out number) is
 begin select QUANTITY,BALANCE_VERSION into p_qty,p_version from RRL_TARE_BALANCE where BALANCE_KEY=p_key;
 exception when no_data_found then p_qty:=0;p_version:=0;end;
 procedure describe_command(p_request clob,p_actor varchar2,p_domain out json_object_t) is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');s json_object_t:=d.get_object('source');kind varchar2(80):=d.get_string('command_type');
 v_owner number;v_type number;v_holder varchar2(12);v_id varchar2(255);v_qty number;v_from raw(32);v_to raw(32);v_from_qty number;v_from_version number;v_to_qty number;v_to_version number;
 v_delivery varchar2(100);v_damage varchar2(100);v_outstanding number;v_used number;v_reason varchar2(32767):=m.get_string('reason');v_ref varchar2(32767):=m.get_string('decision_reference');
 v_tt number;v_vehicle number;v_plate varchar2(50);n number;trip RRL_TRANSPORT_TASK%rowtype;damage RRL_TARE_RESOLUTION%rowtype;
 begin
 select count(*) into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0;if n!=1 then raise_application_error(-20882,'TARE_ACTIVE_ACTOR_REQUIRED');end if;
 if trim(v_reason) is null or lengthb(v_reason)>2000 or trim(v_ref) is null or lengthb(v_ref)>255 then raise_application_error(-20886,'TARE_RESOLUTION_REASON_DECISION_REQUIRED');end if;
 if not regexp_like(m.get_string('quantity'),'^[0-9]{1,18}$') then raise_application_error(-20886,'TARE_INTEGER_QUANTITY_REQUIRED');end if;
 v_qty:=RRL_STOCK_MATH.quantity(m.get_string('quantity'));
 if kind='TARE_WRITE_OFF' then
  if RRL_HAS_WRIGHT(p_actor,'tare_writeoff')!=1 then raise_application_error(-20882,'TARE_TRANSPORT_WRITEOFF_DECISION_REQUIRED');end if;
  v_damage:=s.get_string('damage_operation_id');select * into damage from RRL_TARE_RESOLUTION where OPERATION_ID=v_damage and RESOLUTION_KIND='DAMAGE';
  if damage.ACTOR=p_actor then raise_application_error(-20882,'TARE_INDEPENDENT_DAMAGE_DECISION_REQUIRED');end if;
  v_owner:=damage.OWNER_WARE_ID;v_type:=damage.PALLET_TYPE_ID;v_holder:=damage.CUSTODIAN_KIND;v_id:=damage.CUSTODIAN_ID;v_delivery:=damage.DELIVERY_ACCEPT_OPERATION_ID;
  if m.get_number('writeoff_warehouse_id')is not null then
   if m.get_number('writeoff_warehouse_id')!=v_owner or not RRL_TARE_DAMAGE_TRACE.origin_exists(v_damage)then raise_application_error(-20886,'TARE_TRACED_OWNER_WAREHOUSE_REQUIRED');end if;
   RRL_TARE_PARTICIPANT.warehouse_actor(p_actor,v_owner);
   v_holder:='WAREHOUSE';v_id:=RRL_STOCK_PLAN_HELPER.decimal_text(v_owner);
  end if;
  select nvl(sum(QUANTITY),0) into v_used from RRL_TARE_RESOLUTION where DAMAGE_OPERATION_ID=v_damage and RESOLUTION_KIND='WRITE_OFF';
  if v_qty>damage.QUANTITY-v_used then raise_application_error(-20886,'TARE_DAMAGE_DECISION_QUANTITY_EXCEEDED');end if;
 else
  v_owner:=m.get_number('owner_ware_id');v_type:=m.get_number('pallet_type_id');v_holder:=m.get_string('custodian_kind');v_id:=m.get_string('custodian_id');
  if v_owner is null or v_type is null or v_holder is null or v_holder not in('WAREHOUSE','VEHICLE','STORE') or v_id is null then raise_application_error(-20886,'TARE_RESOLUTION_HOLDER_REQUIRED');end if;
  if v_holder='WAREHOUSE' and v_id!=RRL_STOCK_PLAN_HELPER.decimal_text(v_owner)then raise_application_error(-20886,'TARE_CURRENT_HOLDER_ID_REQUIRED');end if;
  if v_holder='VEHICLE' then
   v_tt:=s.get_number('task_id');select * into trip from RRL_TRANSPORT_TASK where ID=v_tt and nvl(DELETED,0)=0;
   select ID,NUM into v_vehicle,v_plate from RRL_TR_VEHICLE where NUM=trip.TRANSPORT and nvl(DELETED,0)=0 and nvl(BLOCKED,0)=0;
   if v_id!=RRL_STOCK_PLAN_HELPER.decimal_text(v_vehicle) or m.get_string('scan_vehicle') is null or m.get_string('scan_vehicle')!=v_plate then raise_application_error(-20886,'TARE_DAMAGE_CURRENT_VEHICLE_SCAN_REQUIRED');end if;
  end if;
  RRL_TARE_PARTICIPANT.holder_actor(p_actor,v_holder,v_id,v_owner,trip,'tare_damage');
  if v_holder='STORE' then v_delivery:=s.get_string('delivery_accept_operation_id');end if;
 end if;
 select count(*) into n from RRL_WARES where ID=v_owner;if n!=1 then raise_application_error(-20886,'TARE_OWNER_WAREHOUSE_REQUIRED');end if;
 select count(*) into n from RRL_PALLET_TYPE where PALLET_TYPE_ID=v_type and ACTIVE=1;if n!=1 then raise_application_error(-20886,'TARE_ACTIVE_EXISTING_PALLET_TYPE_REQUIRED');end if;
 if v_holder='STORE' then
  select OUTSTANDING_QTY into v_outstanding from RRL_TARE_STORE_DEBT where CLAIM_KEY=case when kind='TARE_DAMAGE' then v_delivery else v_damage end
   and OWNER_WARE_ID=v_owner and PALLET_TYPE_ID=v_type and STORE_ADDR=v_id and CONDITION_CODE=case when kind='TARE_DAMAGE' then 'GOOD' else 'DAMAGED' end;
  if v_qty>v_outstanding then raise_application_error(-20886,'TARE_ORIGINAL_STORE_DEBT_QUANTITY_EXCEEDED');end if;
 end if;
 v_from:=RRL_TARE_BALANCE_KEY(v_owner,v_type,case when kind='TARE_DAMAGE' then 'GOOD' else 'DAMAGED' end,v_holder,v_id);read_balance(v_from,v_from_qty,v_from_version);
 if v_qty>v_from_qty then raise_application_error(-20886,'TARE_SOURCE_QUANTITY_UNAVAILABLE');end if;
 RRL_TARE_PLANNING.assert_available(v_from,v_from_qty,v_qty);
 if kind='TARE_WRITE_OFF' then
  RRL_TARE_DAMAGE_TRACE.check_transfer(case when RRL_TARE_DAMAGE_TRACE.origin_exists(v_damage)then v_damage else null end,v_from,v_qty,v_from_qty);
 end if;
 if kind='TARE_DAMAGE' then v_to:=RRL_TARE_BALANCE_KEY(v_owner,v_type,'DAMAGED',v_holder,v_id);read_balance(v_to,v_to_qty,v_to_version);end if;
 p_domain:=json_object_t();p_domain.put('owner_ware_id',v_owner);p_domain.put('pallet_type_id',v_type);p_domain.put('custodian_kind',v_holder);p_domain.put('custodian_id',v_id);p_domain.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));
 p_domain.put('from_key',rawtohex(v_from));p_domain.put('from_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_from_qty));p_domain.put('from_version',v_from_version);
 p_domain.put('to_key',rawtohex(v_to));p_domain.put('to_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_to_qty));p_domain.put('to_version',v_to_version);
 p_domain.put('delivery_accept_operation_id',v_delivery);p_domain.put('damage_operation_id',v_damage);p_domain.put('store_outstanding',v_outstanding);p_domain.put('previously_written_off',v_used);
 p_domain.put('task_id',v_tt);p_domain.put('vehicle_id',v_vehicle);p_domain.put('vehicle_number',v_plate);p_domain.put('reason',v_reason);p_domain.put('decision_reference',v_ref);
 exception when no_data_found then raise_application_error(-20886,'TARE_ORIGINAL_DAMAGE_DELIVERY_OR_HOLDER_REQUIRED');end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;f json_array_t:=json_array_t();r json_array_t:=json_array_t();
 begin
 describe_command(p_request,d.get_string('actor'),v);RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
 RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BALANCE',v.get_string('from_key'));if v.get_string('to_key') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BALANCE',v.get_string('to_key'));end if;
 RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_RESOLUTION',p_operation);
 if v.get_string('damage_operation_id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_RESOLUTION',v.get_string('damage_operation_id'));end if;
 if v.get_string('delivery_accept_operation_id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_ACCEPT',v.get_string('delivery_accept_operation_id'));end if;
 if v.get_number('task_id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('task_id')));RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('vehicle_id')));end if;
 p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
 d json_object_t:=json_object_t.parse(p_request);op varchar2(100):=d.get_string('operation_id');kind varchar2(80):=d.get_string('command_type');plan clob;v json_object_t;fresh json_object_t;j json_object_t:=json_object_t();
 v_owner number;v_type number;v_holder varchar2(12);v_id varchar2(255);v_qty number;v_from raw(32);v_to raw(32);v_after number;v_delivery varchar2(100);v_damage varchar2(100);v_reason varchar2(2000);v_ref varchar2(255);n number;
 begin
 select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');v_from:=hextoraw(v.get_string('from_key'));v_to:=hextoraw(v.get_string('to_key'));
 if v.get_number('task_id') is not null then
  n:=v.get_number('task_id');select ID into n from RRL_TRANSPORT_TASK where ID=n for update;n:=v.get_number('vehicle_id');select ID into n from RRL_TR_VEHICLE where ID=n for update;
 end if;
 for row_record in(select BALANCE_KEY from RRL_TARE_BALANCE where BALANCE_KEY in(v_from,v_to)order by BALANCE_KEY for update)loop null;end loop;
 describe_command(p_request,p_actor,fresh);if dbms_lob.compare(v.to_clob,fresh.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: tare resolution');end if;
 v_owner:=v.get_number('owner_ware_id');v_type:=v.get_number('pallet_type_id');v_holder:=v.get_string('custodian_kind');v_id:=v.get_string('custodian_id');v_qty:=RRL_STOCK_MATH.quantity(v.get_string('quantity'));
 v_delivery:=v.get_string('delivery_accept_operation_id');v_damage:=v.get_string('damage_operation_id');v_reason:=v.get_string('reason');v_ref:=v.get_string('decision_reference');
 update RRL_TARE_BALANCE set QUANTITY=QUANTITY-v_qty,BALANCE_VERSION=BALANCE_VERSION+1,LAST_OPERATION_ID=op,UPDATED_AT=systimestamp where BALANCE_KEY=v_from and QUANTITY>=v_qty;
 if sql%rowcount!=1 then raise_application_error(-20886,'TARE_SOURCE_QUANTITY_UNAVAILABLE');end if;
 if kind='TARE_DAMAGE' then
  v_after:=to_number(v.get_string('to_quantity'))+v_qty;
  merge into RRL_TARE_BALANCE b using(select v_to BALANCE_KEY from dual)s on(b.BALANCE_KEY=s.BALANCE_KEY)
  when matched then update set QUANTITY=v_after,BALANCE_VERSION=BALANCE_VERSION+1,LAST_OPERATION_ID=op,UPDATED_AT=systimestamp
  when not matched then insert(BALANCE_KEY,OWNER_WARE_ID,PALLET_TYPE_ID,CONDITION_CODE,CUSTODIAN_KIND,CUSTODIAN_ID,QUANTITY,BALANCE_VERSION,LAST_OPERATION_ID)values(v_to,v_owner,v_type,'DAMAGED',v_holder,v_id,v_after,1,op);
 end if;
 insert into RRL_TARE_RESOLUTION(OPERATION_ID,RESOLUTION_KIND,OWNER_WARE_ID,PALLET_TYPE_ID,CUSTODIAN_KIND,CUSTODIAN_ID,FROM_BALANCE_KEY,TO_BALANCE_KEY,QUANTITY,DELIVERY_ACCEPT_OPERATION_ID,DAMAGE_OPERATION_ID,REASON_TEXT,DECISION_REFERENCE,ACTOR)
 values(op,case when kind='TARE_DAMAGE' then 'DAMAGE' else 'WRITE_OFF' end,v_owner,v_type,v_holder,v_id,v_from,v_to,v_qty,v_delivery,v_damage,v_reason,v_ref,p_actor);
 if kind='TARE_DAMAGE' then RRL_TARE_DAMAGE_TRACE.register_damage(op,v_to,v_qty);
 else RRL_TARE_DAMAGE_TRACE.record_writeoff(op,v_damage,v_from,v_qty);end if;
 j.put('operation_id',op);j.put('quantity',v.get_string('quantity'));j.put('status','POSTED');j.put('resolution_kind',case when kind='TARE_DAMAGE' then 'DAMAGE' else 'WRITE_OFF' end);j.put('total_tare_changed',kind='TARE_WRITE_OFF');j.put('goods_stock_changed',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TASK_CORE as 
 procedure validate_metadata(p_meta json_object_t) is 
  v_keys json_key_list:=p_meta.get_keys;v_value json_element_t;v_key varchar2(4000); 
 begin 
  for i in 1..v_keys.count loop 
   v_key:=v_keys(i);v_value:=p_meta.get(v_key); 
   if not v_value.is_null then 
    if v_key in('resource_id','resource_session_id','equipment_id','document_confirmation') then 
     if not v_value.is_number then raise_application_error(-20881,'TASK_METADATA_NUMBER_REQUIRED:'||v_key);end if; 
     if v_key!='document_confirmation' and (p_meta.get_number(v_key)<=0 or p_meta.get_number(v_key)!=trunc(p_meta.get_number(v_key))) then 
      raise_application_error(-20881,'TASK_RESOURCE_ID_INVALID:'||v_key);end if; 
    elsif v_key in('scan_draft_id','scanned_pallet','scanned_from_cell','scanned_to_cell') then 
     if not v_value.is_string then raise_application_error(-20881,'TASK_METADATA_STRING_REQUIRED:'||v_key);end if; 
    elsif v_key='fact_qty' then 
     if not v_value.is_string and not v_value.is_number then raise_application_error(-20881,'TASK_FACT_QUANTITY_TYPE');end if; 
    elsif v_key='unit_keys' then 
     if not v_value.is_array then raise_application_error(-20881,'TASK_UNIT_KEYS_ARRAY_REQUIRED');end if; 
    end if; 
   end if; 
  end loop; 
 end; 
 procedure execute_task(p_request clob,p_actor varchar2,p_result out clob) is 
  v_doc json_object_t:=json_object_t.parse(p_request);v_meta json_object_t;v_source json_object_t;v_domain json_object_t;v_context json_object_t; 
  v_plan clob;v_task RRL_WAREHOUSE_TASK%rowtype;v_residual RRL_WAREHOUSE_TASK%rowtype;v_pallet RRL_PALLETS%rowtype; 
  v_task_id number;v_qty number;v_original number;v_qbase number;v_target varchar2(200);v_base varchar2(20); 
  v_factor_num number;v_factor_den number;v_scale number;v_version number;v_article varchar2(160); 
  v_delivered_reservation number;v_residual_id number;v_reservation number;v_new_reservation number;v_ware number;v_pick_task number; 
  v_signature varchar2(64);v_hash varchar2(64);v_op varchar2(100);v_units clob;v_n number;v_doc_status varchar2(40); 
  v_result json_object_t:=json_object_t();v_resource number;v_session number;v_equipment number;v_sync_id number;v_sync_key varchar2(400);v_session_actor varchar2(100);v_input_uom varchar2(20);v_source_p number;v_uom_signature varchar2(64);v_sap_header number;v_sap_cell varchar2(60);v_sap_ware number;v_document_confirmation number:=0; 
 begin 
  v_doc.on_error(1);v_source:=v_doc.get_object('source');v_meta:=v_doc.get_object('metadata');v_meta.on_error(0); -- Oracle 19c HAS raises for missing keys with nonzero error modes. 
  validate_metadata(v_meta); 
  if v_meta.has('document_confirmation') then v_document_confirmation:=nvl(v_meta.get_number('document_confirmation'),0);end if; 
  v_op:=v_doc.get_string('operation_id');v_task_id:=v_source.get_number('task_id'); 
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task_id))); 
  select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=v_op; 
  v_domain:=json_object_t.parse(v_plan).get_object('domain'); 
  -- Existing assignment/start commands lock the source document before the task. 
  -- Read identity without a row lock, validate the planned signature, then use the same order. 
  select * into v_task from RRL_WAREHOUSE_TASK where TASK_ID=v_task_id; 
  if v_document_confirmation=1 then 
   if v_task.TASK_SOURCE!='MES_RAW_SUPPLY' or RRL_HAS_WRIGHT(p_actor,'mes_raw_transfer_confirm')!=1 then raise_application_error(-20882,'MES_DOCUMENT_CONFIRM_FORBIDDEN');end if; 
  elsif RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'TASK_COMPLETE_FORBIDDEN');end if; 
  if RRL_STOCK_TASK_PLAN.signature(v_task)!=v_domain.get_string('task_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: task source');end if; 
  if v_task.TASK_SOURCE='WAVE' then 
   select STATUS into v_doc_status from RRL_PICK_WAVE where PICK_WAVE_ID=v_task.SOURCE_DOC_ID for update; 
   if v_doc_status is null or v_doc_status!='LAUNCHED' then raise_application_error(-20886,'WAVE_PHYSICAL_EXECUTION_REQUIRES_LAUNCHED');end if; 
  elsif v_task.TASK_SOURCE in('MES_RAW_SUPPLY','MES_COMPLETION') then 
   select STATUS into v_doc_status from RRL_PRODUCTION_ORDER where PRODUCTION_ORDER_ID=nvl(v_task.PRODUCTION_ORDER_ID,v_task.SOURCE_DOC_ID) for update; 
  elsif v_task.TASK_SOURCE='SAP_RECEIPT' then 
   declare 
 v_json_sql_1_1 varchar2(32767):=v_domain.get_string('sap_order_id'); 
begin 
select NAKLAD_ID,RECEIVE_CELL,WARE_ID into v_sap_header,v_sap_cell,v_sap_ware from RRL_SAP_SUPPLY_ORDER where ORDER_ID=v_json_sql_1_1 for update; 
end; 
   if v_sap_header!=v_task.SOURCE_DOC_ID or v_sap_cell!=v_task.FROM_CELL or v_sap_ware!=v_domain.get_number('from_ware_id') then raise_application_error(-20890,'CLOSURE_CHANGED: putaway source order');end if; 
   select to_char(CONDITION) into v_doc_status from RRL_PRIHOD_NAKLAD where ID=v_task.SOURCE_DOC_ID for update; 
  end if; 
  select * into v_task from RRL_WAREHOUSE_TASK where TASK_ID=v_task_id for update; 
  if RRL_STOCK_TASK_PLAN.signature(v_task)!=v_domain.get_string('task_signature') then 
   raise_application_error(-20890,'CLOSURE_CHANGED: task identity'); 
  end if; 
  if v_task.STATUS is null or v_task.STATUS not in('PLANNED','ASSIGNED','IN_PROGRESS') then 
   raise_application_error(-20886,'TASK_STATE_CONFLICT');end if; 
  v_task.FROM_WARE_ID:=v_domain.get_number('from_ware_id');v_task.TO_WARE_ID:=v_domain.get_number('to_ware_id'); 
  if v_task.FROM_WARE_ID is null or v_task.TO_WARE_ID is null or (v_task.FROM_WARE_ID!=v_task.TO_WARE_ID and v_task.TASK_SOURCE not in('MES_RAW_SUPPLY','MES_COMPLETION')) then 
   raise_application_error(-20886,'INTERWAREHOUSE_COMMAND_REQUIRED');end if; 
  if v_document_confirmation!=1 and (upper(trim(v_meta.get_string('scanned_pallet'))) is null or 
   trim(v_meta.get_string('scanned_pallet')) not in(nvl(v_task.UID_PALLET,v_task.SSCC),nvl(v_task.SSCC,v_task.UID_PALLET)) 
   or upper(trim(v_meta.get_string('scanned_from_cell'))) is null or upper(trim(v_meta.get_string('scanned_from_cell')))!=upper(v_task.FROM_CELL) 
   or upper(trim(v_meta.get_string('scanned_to_cell'))) is null or upper(trim(v_meta.get_string('scanned_to_cell')))!=upper(v_task.TO_CELL)) then 
   raise_application_error(-20886,'TASK_SCAN_CONFLICT');end if; 
  if v_task.TASK_SOURCE='MANUAL'and v_task.SOURCE_DOC_TYPE='RECOVERY'then RRL_STOCK_IW_RECOVERY_PUT.validate_task(v_task,p_actor,v_domain.get_object('recovery_placement'));end if;
  if v_task.TASK_SOURCE='MANUAL' and v_task.SOURCE_DOC_TYPE='INTERWARE' then RRL_STOCK_INTERWARE_PUT.validate_task(v_task,p_actor,v_domain.get_object('interwarehouse_placement'));end if; 
  if v_task.TASK_SOURCE='MANUAL' and v_task.SOURCE_DOC_TYPE='STORE_RETURN' then RRL_STOCK_STORE_RETURN_PUT.validate_task(v_task,p_actor,v_domain.get_object('store_return_placement'));end if; 
  v_original:=v_task.QTY;v_qty:=v_original; 
  if v_meta.has('fact_qty') and not v_meta.get('fact_qty').is_null then v_qty:=RRL_STOCK_MATH.quantity(v_meta.get_string('fact_qty'));end if; 
  if v_qty is null or v_qty<=0 or v_qty>v_original or (v_task.QTY_MODE='PALLET' and v_qty!=v_original) then 
   raise_application_error(-20886,'TASK_QUANTITY_CONFLICT');end if; 
  if v_task.TASK_SOURCE='MANUAL'and v_task.SOURCE_DOC_TYPE='ST_DEFER'then RRL_ST_DEFER_WAIT_CORE.validate_task(v_task,p_actor,v_domain.get_object('deferred_waiting'));end if;
  v_target:=v_domain.get_string('target_uid');v_residual_id:=v_domain.get_number('residual_task_id'); 
  v_reservation:=v_domain.get_number('source_reservation_id');v_new_reservation:=v_domain.get_number('new_reservation_id'); 
  v_pick_task:=v_domain.get_number('pick_task_id'); 
  select * into v_pallet from RRL_PALLETS where UID_PALLET=nvl(v_task.UID_PALLET,v_task.SSCC); 
  v_article:=v_pallet.ARTICUL; 
  if (v_task.RAW_ARTICUL is not null and v_task.RAW_ARTICUL!=v_article) or (v_task.TARGET_ARTICUL is not null and v_task.TARGET_ARTICUL!=v_article) then raise_application_error(-20887,'TASK_ARTICLE_CONFLICT');end if; 
  select BASE_UOM,REMAIN into v_input_uom,v_source_p from RRL_REMAINS where UID_POLETA=v_pallet.UID_PALLET and CELL=v_task.FROM_CELL; 
  v_input_uom:=nvl(v_task.UNIT_CODE,v_input_uom); 
  RRL_STOCK_PALLET_UOM.resolve_quantity(v_pallet.UID_PALLET,v_input_uom,RRL_STOCK_PLAN_HELPER.decimal_text(v_qty), 
   v_base,v_qbase,v_version,v_uom_signature); 
  if v_uom_signature!=v_domain.get_string('uom_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: pallet pack');end if; 
  if v_version!=v_domain.get_number('uom_version') or RRL_STOCK_PLAN_HELPER.decimal_text(v_qbase)!=v_domain.get_string('base_quantity') or RRL_STOCK_PLAN_HELPER.decimal_text(v_source_p)!=v_domain.get_string('source_p') then raise_application_error(-20890,'CLOSURE_CHANGED: task quantity policy');end if; 
  if v_task.QTY_MODE='PALLET' and v_qbase!=v_source_p then raise_application_error(-20886,'WHOLE_PALLET_STOCK_CHANGED');end if; 
  if v_task.TASK_SOURCE='WAVE' and v_task.TASK_TYPE='PICKING_MOVE' and v_task.QTY_MODE='PALLET' then 
   select count(*) into v_n from RRL_STOCK_RESERVATION where UID_PALLET=v_pallet.UID_PALLET and CELL=v_task.FROM_CELL 
    and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') and 
      (SOURCE_DOC_TYPE is null or SOURCE_DOC_TYPE!='PICK_WAVE' or SOURCE_DOC_ID is null or SOURCE_DOC_ID!=v_task.SOURCE_DOC_ID 
       or SOURCE_LINE_ID is null or SOURCE_LINE_ID!=v_pick_task or RESERVATION_DOMAIN is null or RESERVATION_DOMAIN!='PICKING'); 
   if v_n>0 then raise_application_error(-20869,'FULLPAL_OTHER_OWNER_RESERVATION');end if; 
   select nvl(sum(BASE_QTY),0) into v_n from RRL_STOCK_RESERVATION where UID_PALLET=v_pallet.UID_PALLET and CELL=v_task.FROM_CELL 
    and SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=v_task.SOURCE_DOC_ID and SOURCE_LINE_ID=v_pick_task 
    and RESERVATION_DOMAIN='PICKING' and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING'); 
   if v_n!=v_qbase then raise_application_error(-20869,'FULLPAL_WHOLE_OWNED_RESERVATION_REQUIRED');end if; 
  end if; 
  if v_task.TASK_SOURCE='WAVE' then 
   RRL_STOCK_ELIGIBILITY.assert_source(v_pallet.UID_PALLET,v_task.FROM_CELL,v_task.FROM_WARE_ID,case when v_task.QTY_MODE='PALLET' and v_task.TASK_TYPE in('REPLENISHMENT','PICKING_MOVE') and v_reservation is not null then 0 else v_qbase end,null,null, 
    case when v_task.TASK_TYPE='REPLENISHMENT' then 'REPLENISH' else 'ALLOCATE' end,v_reservation,v_article); 
  end if; 
  if v_task.TASK_SOURCE='WAVE' then 
   select STATUS into v_doc_status from RRL_PICK_WAVE where PICK_WAVE_ID=v_task.SOURCE_DOC_ID for update; 
   if v_doc_status is null or v_doc_status!='LAUNCHED' then raise_application_error(-20886,'WAVE_PHYSICAL_EXECUTION_REQUIRES_LAUNCHED');end if; 
   if v_doc_status='CANCELLED' then raise_application_error(-20886,'SOURCE_DOCUMENT_CANCELLED');end if; 
  elsif v_task.TASK_SOURCE='SAP_RECEIPT' then 
   if v_qty!=v_original then raise_application_error(-20886,'PUTAWAY_MUST_BE_WHOLE');end if; 
   select count(*) into v_n from RRL_SAP_PALLET_RECEIPT rec join RRL_SAP_SUPPLY_ORDER so on so.ORDER_ID=rec.ORDER_ID 
    where rec.UID_PALLET=v_pallet.UID_PALLET and so.NAKLAD_ID=v_task.SOURCE_DOC_ID and so.RECEIVE_CELL=v_task.FROM_CELL and so.WARE_ID=v_task.FROM_WARE_ID; 
   if v_n!=1 then raise_application_error(-20886,'PUTAWAY_RECEIPT_SOURCE_CONFLICT');end if; 
   if v_task.TO_CELL_SLOT_ID is not null then 
    select count(*) into v_n from RRL_RECEIPT_SLOT_CLAIM cl join RRL_TOPOLOGY_CELL_SLOT sl on sl.CELL_SLOT_ID=cl.CELL_SLOT_ID 
     where cl.TASK_ID=v_task_id and cl.STATUS='RESERVED' and sl.ACTIVE=1; 
    if v_n!=1 then raise_application_error(-20886,'PUTAWAY_SLOT_CONFLICT');end if; 
   end if; 
  elsif v_task.TASK_SOURCE in('MES_RAW_SUPPLY','MES_COMPLETION') then 
   select STATUS into v_doc_status from RRL_PRODUCTION_ORDER 
    where PRODUCTION_ORDER_ID=nvl(v_task.PRODUCTION_ORDER_ID,v_task.SOURCE_DOC_ID) for update; 
   if v_doc_status='CANCELLED' then raise_application_error(-20886,'SOURCE_DOCUMENT_CANCELLED');end if; 
  elsif v_task.TASK_SOURCE='MANUAL'and v_task.SOURCE_DOC_TYPE='RECOVERY'then
   if v_qty!=v_original or v_target!=v_pallet.UID_PALLET then raise_application_error(-20886,'RECOVERY_WHOLE_PLACEMENT_REQUIRED');end if;
  elsif v_task.TASK_SOURCE='MANUAL' and v_task.SOURCE_DOC_TYPE='INTERWARE' then 
   if v_qty!=v_original or v_target!=v_pallet.UID_PALLET then raise_application_error(-20886,'INTERWARE_WHOLE_PLACEMENT_REQUIRED');end if; 
  elsif v_task.TASK_SOURCE='MANUAL' and v_task.SOURCE_DOC_TYPE='STORE_RETURN' then 
   if v_qty!=v_original or v_target!=v_pallet.UID_PALLET then raise_application_error(-20886,'STORE_RETURN_WHOLE_PLACEMENT_REQUIRED');end if; 
   select to_char(CONDITION) into v_doc_status from RRL_PRIHOD_NAKLAD where ID=v_task.SOURCE_DOC_ID and DOCUMENT_KIND='STORE_RETURN' for update; 
   if v_doc_status!='1' then raise_application_error(-20886,'STORE_RETURN_DOCUMENT_PLACEMENT_STATE_CONFLICT');end if; 
  elsif v_task.TASK_SOURCE='MANUAL'and v_task.SOURCE_DOC_TYPE='ST_DEFER'then
   if v_qty!=v_original or v_target!=v_pallet.UID_PALLET then raise_application_error(-20886,'DEFER_WAIT_WHOLE_PALLET_REQUIRED');end if;
  else raise_application_error(-20888,'TASK_DOMAIN_HANDLER_REQUIRED');end if; 
  if v_target!=v_pallet.UID_PALLET then 
   RRL_STOCK_LOCK_API.assert_held(70,RRL_STOCK_LOCK_API.resource_key('UNIQUE','PALLET:'||v_target)); 
   v_pallet.STOCK_ORIGIN_UID:=nvl(v_pallet.STOCK_ORIGIN_UID,v_pallet.UID_PALLET);v_pallet.CREATED_BY_STOCK_OP:=v_op; 
   if v_pallet.WEIGHT_BRUTTO is not null then 
    if v_pallet.UNIT_COUNT is null or v_pallet.UNIT_COUNT<=0 then raise_application_error(-20887,'PALLET_BIRTH_QUANTITY_REQUIRED');end if; 
    v_pallet.WEIGHT_BRUTTO:=v_pallet.WEIGHT_BRUTTO*v_qbase/v_pallet.UNIT_COUNT; 
   end if; 
   v_pallet.UID_PALLET:=v_target;v_pallet.SSCC:=null;v_pallet.UNIT_COUNT:=v_qbase;v_pallet.PRINTED:=0; 
   v_pallet.STOCK_COMPOSITION_VERSION:=0;insert into RRL_PALLETS values v_pallet; 
  end if; 
  RRL_STOCK_TASK_SCAN.assert_draft(p_request,v_task_id,nvl(v_task.UID_PALLET,v_task.SSCC),v_task.FROM_CELL,p_actor); 
  if v_meta.has('unit_keys') and not v_meta.get('unit_keys').is_null and v_meta.get_array('unit_keys').get_size>0 then v_units:=v_meta.get_array('unit_keys').to_clob;end if; 
  if v_task.TASK_SOURCE='WAVE' and v_task.TASK_TYPE='REPLENISHMENT' then 
   if v_task.QTY_MODE='PALLET' then 
    select count(*) into v_n from RRL_STOCK_RESERVATION where UID_PALLET=nvl(v_task.UID_PALLET,v_task.SSCC) and CELL=v_task.FROM_CELL 
     and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_QTY>0 and RESERVATION_ID!=v_reservation; 
    if v_n>0 and RRL_STOCK_REPL_SHARED.allowed(nvl(v_task.UID_PALLET,v_task.SSCC),v_task.FROM_CELL,v_task.TO_CELL,v_task.FROM_WARE_ID,v_reservation)!=1 then 
     raise_application_error(-20886,'WHOLE_REPLENISHMENT_OTHER_DESTINATION_OR_OWNER');end if; 
   end if; 
   RRL_STOCK_REPL_CAPACITY.assert_arrival(v_task.SOURCE_TASK_ID,v_qbase); 
   RRL_STOCK_REPL_ADMISSION.assert_target(nvl(v_task.UID_PALLET,v_task.SSCC),v_task.TO_CELL,v_task.TO_WARE_ID,v_article); 
  end if; 
  RRL_STOCK_TRANSFER_CORE.move(nvl(v_task.UID_PALLET,v_task.SSCC),v_target,v_task.FROM_CELL,v_task.TO_CELL, 
   v_qbase,v_base,v_version,v_task.TO_WARE_ID,p_actor,1,v_reservation,v_units,v_new_reservation,v_task.TO_CELL_SLOT_ID,v_task.FROM_WARE_ID,case when v_task.TASK_SOURCE='MANUAL' and v_task.SOURCE_DOC_TYPE in('INTERWARE','RECOVERY') then 'PUTAWAY' when v_task.TASK_SOURCE='SAP_RECEIPT' then 'PUTAWAY' when v_task.TASK_SOURCE='MANUAL' and v_task.SOURCE_DOC_TYPE='STORE_RETURN' then 'QUARANTINE' else 'ORDINARY' end); 
  if v_task.TASK_SOURCE='WAVE' and v_task.TASK_TYPE='REPLENISHMENT' then 
   select case when UID_PALLET=v_target and CELL=v_task.TO_CELL then RESERVATION_ID else v_new_reservation end 
    into v_delivered_reservation from RRL_STOCK_RESERVATION where RESERVATION_ID=v_reservation; 
   RRL_STOCK_REPL_BIND.execute_bind(v_task,v_target,v_delivered_reservation,v_domain.get_object('consumer_bindings'),p_actor); 
  end if; 
  v_resource:=v_meta.get_number('resource_id');v_session:=v_meta.get_number('resource_session_id');v_equipment:=v_meta.get_number('equipment_id'); 
  if v_document_confirmation!=1 and v_session is null and v_task.ASSIGNED_TO=p_actor then v_session:=v_task.RESOURCE_SESSION_ID;end if; 
  for ses in(select SESSION_ID from RRL_RESOURCE_SESSION where SESSION_ID in(v_session,v_task.RESOURCE_SESSION_ID) order by SESSION_ID for update) loop 
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_RESOURCE_SESSION',RRL_STOCK_PLAN_HELPER.decimal_text(ses.SESSION_ID))); 
  end loop; 
  v_context:=json_object_t.parse(RRL_TASK_RESOURCE_POLICY.context_json(v_task_id,case when v_document_confirmation=1 then 'COMPLETE_DOCUMENT' else 'COMPLETE' end,p_actor,p_actor, 
   v_meta.get_number('resource_id'),v_meta.get_number('resource_session_id'),v_meta.get_number('equipment_id'))); 
  if dbms_lob.compare(v_context.to_clob,v_domain.get_object('resource_context').to_clob)!=0 then 
   raise_application_error(-20890,'CLOSURE_CHANGED: task resource context');end if; 
  v_resource:=v_context.get_number('resource_id');v_session:=v_context.get_number('resource_session_id');v_equipment:=v_context.get_number('equipment_id'); 
  v_hash:=rawtohex(sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256)); 
  if v_residual_id is not null then 
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_residual_id))); 
   v_residual:=v_task;v_residual.TASK_ID:=v_residual_id;v_residual.QTY:=v_original-v_qty; 
   v_residual.PARENT_TASK_ID:=v_task_id;v_residual.STATUS:='PLANNED';v_residual.FACT_QTY:=null; 
   v_residual.CREATED_BY:=p_actor;v_residual.CREATED_AT:=systimestamp;v_residual.COMPLETION_HASH:=null; 
   v_residual.COMPLETION_JSON:=null;v_residual.FINISHED_AT:=null;v_residual.ASSIGNED_TO:=null; 
   v_residual.STARTED_AT:=null;v_residual.STARTED_AT_INSTANT:=null;v_residual.STARTED_SHIFT_TIME_ZONE:=null;v_residual.TARGET_UID_PALLET:=null; 
   v_residual.RESOURCE_ID:=null;v_residual.RESOURCE_SESSION_ID:=null;v_residual.EQUIPMENT_ID:=null; 
   v_residual.PLANNED_START_AT:=null;v_residual.PLANNED_FINISH_AT:=case when v_task.PRIORITY=0 then v_task.PLANNED_FINISH_AT else null end;v_residual.LAST_ERROR:='Residual of task '||v_task_id; 
   insert into RRL_WAREHOUSE_TASK values v_residual; 
  end if; 
  update RRL_WAREHOUSE_TASK set STATUS='DONE',QTY=v_qty,FACT_QTY=v_qty,TARGET_UID_PALLET=v_target, 
   FROM_WARE_ID=v_task.FROM_WARE_ID,TO_WARE_ID=v_task.TO_WARE_ID,FINISHED_AT=systimestamp,ASSIGNED_TO=p_actor,RESOURCE_ID=v_resource, 
   RESOURCE_SESSION_ID=v_session,EQUIPMENT_ID=v_equipment, 
   COMPLETION_HASH=v_hash,COMPLETION_JSON=p_request,LAST_ERROR=null where TASK_ID=v_task_id; 
  insert into RRL_WAREHOUSE_TASK_STOCK_MOVE(STOCK_MOVE_ID,TASK_ID,TASK_SOURCE,TASK_TYPE,SOURCE_DOC_TYPE,SOURCE_DOC_ID, 
   SOURCE_TASK_ID,UID_PALLET,TARGET_UID_PALLET,FROM_CELL,TO_CELL,QTY,BASE_QTY,BASE_UOM,OPERATION_ID,CREATED_AT,CREATED_BY) 
   values(RRL_WH_TASK_STOCK_MOVE_SQ.nextval,v_task_id,v_task.TASK_SOURCE,v_task.TASK_TYPE,v_task.SOURCE_DOC_TYPE,v_task.SOURCE_DOC_ID, 
    v_task.SOURCE_TASK_ID,nvl(v_task.UID_PALLET,v_task.SSCC),v_target,v_task.FROM_CELL,v_task.TO_CELL,v_qty,v_qbase,v_base,v_op,systimestamp,p_actor); 
  if v_resource is not null or v_session is not null or v_equipment is not null then 
   insert into RRL_RESOURCE_FACT_EVENT(EVENT_ID,TASK_ID,SESSION_ID,RESOURCE_ID,EVENT_TYPE,EVENT_AT,EVENT_BY,PAYLOAD_JSON) 
    values(RRL_RESOURCE_FACT_EVENT_SQ.nextval,v_task_id,v_session,v_resource,'COMPLETED',systimestamp,p_actor,p_request); 
  end if; 
  update RRL_RESOURCE_SESSION set CURRENT_TASK_ID=null 
   where SESSION_ID in(v_session,v_task.RESOURCE_SESSION_ID) and CURRENT_TASK_ID=v_task_id; 
  if v_session is not null then 
   update RRL_RESOURCE_SESSION set LAST_CELL=v_task.TO_CELL,LAST_POSITION_AT=systimestamp, 
    LAST_HEARTBEAT_AT=systimestamp where SESSION_ID=v_session and OPERATOR_USER_ID=p_actor; 
  end if; 
  RRL_STOCK_TASK_DOMAIN.sync_fact(v_task,v_qty,v_target,v_residual_id,p_actor); 
  RRL_STOCK_REPL_CONTINUATION.create_next(v_task,v_domain,p_actor); 
  v_sync_id:=v_domain.get_number('sync_id');v_sync_key:=v_domain.get_string('sync_key'); 
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK_SYNC',RRL_STOCK_PLAN_HELPER.decimal_text(v_sync_id))); 
  merge into RRL_WAREHOUSE_TASK_SYNC d using(select v_sync_key SYNC_KEY from dual)s on(d.SYNC_KEY=s.SYNC_KEY) 
   when matched then update set d.SYNC_STATUS='SYNCED',d.SYNCED_AT=systimestamp,d.UPDATED_AT=systimestamp,d.UPDATED_BY=p_actor,d.LAST_ERROR=null 
   when not matched then insert(SYNC_ID,TASK_ID,TASK_SOURCE,TASK_TYPE,SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_TASK_ID,SOURCE_MOVEMENT_ID,SYNC_KEY,SYNC_STATUS,SYNC_ATTEMPT,CREATED_AT,UPDATED_AT,SYNCED_AT,UPDATED_BY) 
    values(v_sync_id,v_task_id,v_task.TASK_SOURCE,v_task.TASK_TYPE,v_task.SOURCE_DOC_TYPE,v_task.SOURCE_DOC_ID,v_task.SOURCE_TASK_ID,v_task.SOURCE_MOVEMENT_ID,v_sync_key,'SYNCED',1,systimestamp,systimestamp,systimestamp,p_actor); 
  v_result.put('operation_id',v_op);v_result.put('task_id',v_task_id);v_result.put('status','DONE'); 
  v_result.put('pallet_identifier',v_target);v_result.put('source_pallet_identifier',nvl(v_task.UID_PALLET,v_task.SSCC)); 
  v_result.put('cell',v_task.TO_CELL);v_result.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty)); 
  v_result.put('base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qbase));v_result.put('base_uom',v_base); 
  v_result.put('remaining_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_original-v_qty)); 
  v_result.put('residual_task_id',v_residual_id);v_result.put('movement_id',v_domain.get_number('new_movement_id'));p_result:=v_result.to_clob; 
  if v_task.TASK_SOURCE='SAP_RECEIPT' then 
   v_result.put('order_id',v_domain.get_string('sap_order_id'));v_result.put('line_number',v_domain.get_string('sap_line_number')); 
   v_result.put('article',v_article);p_result:=v_result.to_clob; 
   insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON) 
    values('PUTAWAY:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_task_id),'PALLET_PUTAWAY',p_result); 
  end if; 
 end; 
end;
/


CREATE OR REPLACE package body RRL_STOCK_TASK_DOMAIN as 
 procedure sync_fact(p_task RRL_WAREHOUSE_TASK%rowtype,p_qty number,p_target_uid varchar2,p_residual number,p_actor varchar2) is 
  v_total number;v_n number;v_status varchar2(40);v_pick number; 
 begin 
  if p_task.TASK_SOURCE='MANUAL' and p_task.SOURCE_DOC_TYPE='INTERWARE' then 
   RRL_STOCK_INTERWARE_PUT.complete_task(p_task,p_qty,p_target_uid,p_actor); 
  elsif p_task.TASK_SOURCE='MANUAL'and p_task.SOURCE_DOC_TYPE='RECOVERY'then
   RRL_STOCK_IW_RECOVERY_PUT.complete_task(p_task,p_qty,p_target_uid,p_actor);
  elsif p_task.TASK_SOURCE='MANUAL' and p_task.SOURCE_DOC_TYPE='STORE_RETURN' then 
   RRL_STOCK_STORE_RETURN_PUT.complete_task(p_task,p_qty,p_target_uid,p_actor); 
  elsif p_task.TASK_SOURCE='MANUAL'and p_task.SOURCE_DOC_TYPE='ST_DEFER'then
   RRL_ST_DEFER_WAIT_CORE.complete_task(p_task,p_qty,p_target_uid,p_actor);
  elsif p_task.TASK_SOURCE='WAVE' then 
   select count(*) into v_n from RRL_WAREHOUSE_TASK where TASK_SOURCE='WAVE' and TASK_TYPE=p_task.TASK_TYPE 
    and SOURCE_TASK_ID=p_task.SOURCE_TASK_ID and STATUS not in('DONE','CANCELLED'); 
   v_status:=case when v_n=0 then 'DONE' else 'IN_PROGRESS' end; 
   if p_task.TASK_TYPE='REPLENISHMENT' then 
    update RRL_PICK_WAVE_REPLENISH_TASK set STATUS=v_status,UPDATED_AT=sysdate,UPDATED_BY=p_actor 
     where PICK_WAVE_REPLENISH_TASK_ID=p_task.SOURCE_TASK_ID; 
    RRL_STOCK_SHORT_RECOVERY.finish_replenishment(p_task,p_actor); 
    -- HARD coverage is now at the target. Do not mark it CONSUMED by placement. 
   elsif p_task.TASK_TYPE='PICKING_MOVE' then 
    select PICK_TASK_ID into v_pick from RRL_PICK_WAVE_TASK where PICK_WAVE_TASK_ID=p_task.SOURCE_TASK_ID; 
    select nvl(sum(m.BASE_QTY),0) into v_total from RRL_WAREHOUSE_TASK t 
     join RRL_WAREHOUSE_TASK_STOCK_MOVE m on m.TASK_ID=t.TASK_ID 
     where t.TASK_SOURCE='WAVE' and t.TASK_TYPE='PICKING_MOVE' and t.SOURCE_TASK_ID=p_task.SOURCE_TASK_ID; 
    update RRL_PICK_WAVE_TASK set STATUS=v_status,FACT_QTY=v_total, 
     DONE_AT=case when v_status='DONE' then sysdate else DONE_AT end, 
     DONE_BY=case when v_status='DONE' then p_actor else DONE_BY end, 
     TARGET_CELL_CODE=p_task.TO_CELL,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_TASK_ID=p_task.SOURCE_TASK_ID; 
    update RRL_PICK_TASK set STATUS=v_status,FACT_QTY=v_total, 
     DONE_AT=case when v_status='DONE' then sysdate else DONE_AT end, 
     DONE_BY=case when v_status='DONE' then p_actor else DONE_BY end, 
     TARGET_CELL_CODE=p_task.TO_CELL,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_TASK_ID=v_pick; 
    -- Physical relocation preserves HARD until ISSUE/SHIP, even if the picking task is DONE. 
   else raise_application_error(-20888,'WAVE_TASK_HANDLER_REQUIRED');end if; 
  elsif p_task.TASK_SOURCE='SAP_RECEIPT' then 
   update RRL_RECEIPT_SLOT_CLAIM set STATUS='OCCUPIED' where TASK_ID=p_task.TASK_ID and STATUS='RESERVED'; 
   select count(*) into v_n from RRL_WAREHOUSE_TASK where TASK_SOURCE='SAP_RECEIPT' and SOURCE_DOC_ID=p_task.SOURCE_DOC_ID and STATUS not in('DONE','CANCELLED'); 
   if v_n=0 then update RRL_PRIHOD_NAKLAD set CONDITION=2 where ID=p_task.SOURCE_DOC_ID and CONDITION=1;end if; 
  elsif p_task.TASK_SOURCE in('MES_RAW_SUPPLY','MES_COMPLETION') then 
   RRL_STOCK_MES_CORE.sync_warehouse_fact(p_task,p_qty,p_target_uid,p_residual,p_actor); 
  else raise_application_error(-20888,'TASK_DOMAIN_HANDLER_REQUIRED');end if; 
 end; 
end;
/


CREATE OR REPLACE package body RRL_STOCK_TASK_PLAN as 
 function signature(p_task RRL_WAREHOUSE_TASK%rowtype) return varchar2 is v json_object_t:=json_object_t(); 
 begin 
  v.put('task_id',p_task.TASK_ID);v.put('source',p_task.TASK_SOURCE);v.put('kind',p_task.TASK_TYPE); 
  v.put('uid',p_task.UID_PALLET);v.put('sscc',p_task.SSCC);v.put('from',p_task.FROM_CELL);v.put('to',p_task.TO_CELL); 
  v.put('from_ware',p_task.FROM_WARE_ID);v.put('to_ware',p_task.TO_WARE_ID);v.put('slot_from',p_task.FROM_CELL_SLOT_ID); 
  v.put('slot_to',p_task.TO_CELL_SLOT_ID);v.put('doc_type',p_task.SOURCE_DOC_TYPE);v.put('doc',p_task.SOURCE_DOC_ID); 
  v.put('source_task',p_task.SOURCE_TASK_ID);v.put('movement',p_task.SOURCE_MOVEMENT_ID); 
  v.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(p_task.QTY));v.put('unit',p_task.UNIT_CODE); 
  v.put('raw_article',p_task.RAW_ARTICUL);v.put('target_article',p_task.TARGET_ARTICUL); 
  v.put('status',p_task.STATUS);v.put('assigned_to',p_task.ASSIGNED_TO);v.put('resource_id',p_task.RESOURCE_ID); 
  v.put('resource_session_id',p_task.RESOURCE_SESSION_ID);v.put('equipment_id',p_task.EQUIPMENT_ID); 
  v.put('started_instant',to_char(p_task.STARTED_AT_INSTANT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));v.put('started_zone',p_task.STARTED_SHIFT_TIME_ZONE); 
  v.put('mode',p_task.QTY_MODE);v.put('production',p_task.PRODUCTION_ORDER_ID); 
  return rawtohex(sys.dbms_crypto.hash(v.to_clob,sys.dbms_crypto.hash_sh256)); 
 end; 
 procedure compile_task(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is 
  v_doc json_object_t:=json_object_t.parse(p_request);v_source json_object_t;v_meta json_object_t; 
  v_bind json_object_t;v_context json_object_t;v_task RRL_WAREHOUSE_TASK%rowtype;v_uid varchar2(200);v_article varchar2(160);v_target varchar2(200); 
  v_p json_array_t:=json_array_t();v_r json_array_t:=json_array_t();v_domain json_object_t:=json_object_t(); 
  v_task_id number;v_residual number;v_reservation number;v_new_reservation number;v_fact number;v_pick_task number;v_movement_id number;v_sync_id number;v_sync_key varchar2(400);v_from_ware number;v_to_ware number;v_source_p number;v_base varchar2(20);v_input varchar2(20);v_sap_order varchar2(100);v_sap_line varchar2(40);v_qbase number;v_num number;v_den number;v_scale number;v_uom_version number;v_uom_signature varchar2(64); 
 begin 
  v_source:=v_doc.get_object('source');v_meta:=v_doc.get_object('metadata');v_source.on_error(1); 
  v_task_id:=v_source.get_number('task_id'); 
  if v_task_id is null or v_task_id<1 or v_task_id!=trunc(v_task_id) then raise_application_error(-20881,'TASK_ID_REQUIRED');end if; 
  select * into v_task from RRL_WAREHOUSE_TASK where TASK_ID=v_task_id; 
  v_uid:=nvl(v_task.UID_PALLET,v_task.SSCC); 
  RRL_STOCK_TASK_SCAN.assert_draft(p_request,v_task_id,v_uid,v_task.FROM_CELL,v_doc.get_string('actor')); 
  v_meta.on_error(0); 
  if v_meta.has('scan_draft_id') and not v_meta.get('scan_draft_id').is_null then 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_TASK_SCAN_DRAFT',v_meta.get_string('scan_draft_id'));end if; 
  v_sync_key:='WT:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_task_id)||':'||v_task.TASK_SOURCE||':'||v_task.TASK_TYPE||':'||RRL_STOCK_PLAN_HELPER.decimal_text(v_task.SOURCE_TASK_ID)||':'||RRL_STOCK_PLAN_HELPER.decimal_text(v_task.SOURCE_MOVEMENT_ID); 
  begin select SYNC_ID into v_sync_id from RRL_WAREHOUSE_TASK_SYNC where SYNC_KEY=v_sync_key; 
  exception when no_data_found then select RRL_WH_TASK_SYNC_SQ.nextval into v_sync_id from dual;end; 
  select ARTICUL into v_article from RRL_PALLETS where UID_PALLET=v_uid; 
  select WARE_ID into v_from_ware from RRL_CELLS where CELL=v_task.FROM_CELL; 
  select WARE_ID into v_to_ware from RRL_CELLS where CELL=v_task.TO_CELL; 
  if (v_task.FROM_WARE_ID is not null and v_task.FROM_WARE_ID!=v_from_ware) or 
   (v_task.TO_WARE_ID is not null and v_task.TO_WARE_ID!=v_to_ware) then raise_application_error(-20886,'TASK_CELL_WAREHOUSE_CONFLICT');end if; 
  v_fact:=v_task.QTY; 
  if v_meta.has('fact_qty') and not v_meta.get('fact_qty').is_null then 
   v_fact:=RRL_STOCK_MATH.quantity(v_meta.get_string('fact_qty')); 
  end if; 
  select REMAIN,BASE_UOM into v_source_p,v_base from RRL_REMAINS where UID_POLETA=v_uid and CELL=v_task.FROM_CELL; 
  v_input:=nvl(v_task.UNIT_CODE,v_base); 
  RRL_STOCK_PALLET_UOM.resolve_quantity(v_uid,v_input,RRL_STOCK_PLAN_HELPER.decimal_text(v_fact), 
   v_base,v_qbase,v_uom_version,v_uom_signature); 
  v_target:=v_uid; 
  if v_fact<v_task.QTY then select RRL_WAREHOUSE_TASK_SQ.nextval into v_residual from dual;end if; 
  if v_qbase<v_source_p then 
   v_target:='PART:'||substr(rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)),1,45); -- PART prefix + 45 hex characters fits legacy UID_PALLET(50 CHAR). 
   select RRL_STOCK_RESERVATION_SQ.nextval into v_new_reservation from dual; 
  end if; 
  RRL_STOCK_PLAN_HELPER.fence(v_p,'RELEASE','STOCK'); 
  RRL_STOCK_PLAN_HELPER.anchor(v_r,10,'OP',p_operation); 
  RRL_STOCK_PLAN_HELPER.anchor(v_r,70,'UNIQUE','STOCK.OUTBOX:'|| 
   rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256))); 
  RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task_id)); 
  RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_WAREHOUSE_TASK_SYNC',RRL_STOCK_PLAN_HELPER.decimal_text(v_sync_id)); 
  RRL_STOCK_PLAN_HELPER.anchor(v_r,70,'UNIQUE','TASK.SYNC:'||v_sync_key); 
  if v_residual is not null then RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_residual));end if; 
  if v_new_reservation is not null then RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(v_new_reservation));end if; 
  if v_task.TASK_SOURCE='WAVE' then 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.SOURCE_DOC_ID)); 
   if v_task.TASK_TYPE='REPLENISHMENT' then 
    RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.SOURCE_TASK_ID)); 
    RRL_STOCK_SHORT_RECOVERY.plan_replenishment(v_task.SOURCE_TASK_ID,v_r); 
    select SOURCE_RESERVATION_ID into v_reservation from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=v_task.SOURCE_TASK_ID; 
   elsif v_task.TASK_TYPE='PICKING_MOVE' then 
    RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.SOURCE_TASK_ID)); 
    select PICK_TASK_ID into v_pick_task from RRL_PICK_WAVE_TASK where PICK_WAVE_TASK_ID=v_task.SOURCE_TASK_ID; 
    RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_pick_task)); 
    begin 
     select RESERVATION_ID into v_reservation from ( 
      select RESERVATION_ID from RRL_STOCK_RESERVATION where UID_PALLET=v_uid and CELL=v_task.FROM_CELL 
       and SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=v_task.SOURCE_DOC_ID and SOURCE_LINE_ID=v_pick_task 
       and RESERVATION_DOMAIN='PICKING' and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') 
       and BASE_QTY>0 order by BASE_QTY desc,RESERVATION_ID) where rownum=1; 
    exception when no_data_found then raise_application_error(-20869,'FULLPAL_OWN_SOURCE_RESERVATION_REQUIRED');end; 
   end if; 
  elsif v_task.TASK_SOURCE='SAP_RECEIPT' then 
   select ORDER_ID,LINE_NUMBER into v_sap_order,v_sap_line from RRL_SAP_PALLET_RECEIPT where UID_PALLET=v_uid; 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_SAP_SUPPLY_ORDER',v_sap_order); 
   v_domain.put('sap_order_id',v_sap_order);v_domain.put('sap_line_number',v_sap_line); 
   RRL_STOCK_PLAN_HELPER.anchor(v_r,70,'UNIQUE','SAP.OUTBOX:PUTAWAY:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_task_id)); 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_PRIHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.SOURCE_DOC_ID)); 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(v_task_id)); 
  elsif v_task.TASK_SOURCE in('MES_RAW_SUPPLY','MES_COMPLETION') then 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_PRODUCTION_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(nvl(v_task.PRODUCTION_ORDER_ID,v_task.SOURCE_DOC_ID))); 
   if v_task.SOURCE_TASK_ID is not null then 
    RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_MES_RAW_TRANSFER_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.SOURCE_TASK_ID)); 
   end if; 
   if v_task.SOURCE_MOVEMENT_ID is not null then 
    RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_MES_MOVEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.SOURCE_MOVEMENT_ID)); 
   end if; 
  end if; 
  if v_task.TASK_SOURCE='MES_RAW_SUPPLY' then 
   select RESERVATION_ID into v_reservation from RRL_MES_RAW_TRANSFER_TASK where TASK_ID=v_task.SOURCE_TASK_ID; 
   select RRL_MES_MOVEMENT_SQ.nextval into v_movement_id from dual; 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_MES_MOVEMENT',RRL_STOCK_PLAN_HELPER.decimal_text(v_movement_id)); 
  end if; 
  v_context:=json_object_t.parse(RRL_TASK_RESOURCE_POLICY.context_json(v_task_id,case when v_meta.get_number('document_confirmation')=1 then 'COMPLETE_DOCUMENT' else 'COMPLETE' end,v_doc.get_string('actor'),v_doc.get_string('actor'), 
   v_meta.get_number('resource_id'),v_meta.get_number('resource_session_id'),v_meta.get_number('equipment_id'))); 
  if not v_context.get('resource_session_id').is_null then 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_RESOURCE_SESSION',RRL_STOCK_PLAN_HELPER.decimal_text(v_context.get_number('resource_session_id'))); 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RUSERS',v_doc.get_string('actor')); 
  end if; 
  if v_task.RESOURCE_SESSION_ID is not null then 
   RRL_STOCK_PLAN_HELPER.row_key(v_r,'RRL_RESOURCE_SESSION',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.RESOURCE_SESSION_ID)); 
  end if; 
  v_domain.put('resource_context',v_context); 
  if v_task.FROM_CELL_SLOT_ID is not null then RRL_STOCK_PLAN_HELPER.anchor(v_r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.FROM_CELL_SLOT_ID));end if; 
  if v_task.TO_CELL_SLOT_ID is not null then RRL_STOCK_PLAN_HELPER.anchor(v_r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(v_task.TO_CELL_SLOT_ID));end if; 
  RRL_STOCK_PLAN_HELPER.stock_closure(v_p,v_r,v_uid,v_article,v_task.FROM_CELL,v_task.TO_CELL); 
  if v_task.TASK_SOURCE='WAVE' and v_task.TASK_TYPE='REPLENISHMENT' then 
   RRL_STOCK_PLAN_HELPER.fence(v_p,'CELL',v_task.TO_CELL,6); 
  end if; 
  if v_target!=v_uid then 
   RRL_STOCK_PLAN_HELPER.anchor(v_r,30,'HU',v_target);RRL_STOCK_PLAN_HELPER.anchor(v_r,50,'STOCK',v_target); 
   RRL_STOCK_PLAN_HELPER.anchor(v_r,70,'UNIQUE','PALLET:'||v_target); 
  end if; 
  v_domain.put('uom_signature',v_uom_signature);v_domain.put('source_p',RRL_STOCK_PLAN_HELPER.decimal_text(v_source_p));v_domain.put('uom_version',v_uom_version);v_domain.put('base_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qbase)); 
  v_domain.put('from_ware_id',v_from_ware);v_domain.put('to_ware_id',v_to_ware); 
  v_domain.put('sync_id',v_sync_id);v_domain.put('sync_key',v_sync_key); 
  v_domain.put('task_signature',signature(v_task));v_domain.put('target_uid',v_target); 
  v_domain.put('residual_task_id',v_residual);v_domain.put('source_reservation_id',v_reservation); 
  v_domain.put('new_movement_id',v_movement_id); 
  v_domain.put('new_reservation_id',v_new_reservation);v_domain.put('pick_task_id',v_pick_task); 
  RRL_STOCK_REPL_CONTINUATION.plan_next(v_task,v_qbase,v_residual,v_r,v_domain); 
  RRL_STOCK_REPL_BIND.plan_bind(v_task,v_qbase,v_r,v_bind);v_domain.put('consumer_bindings',v_bind); 
  if v_task.TASK_SOURCE='MANUAL'and v_task.SOURCE_DOC_TYPE='RECOVERY'then RRL_STOCK_IW_RECOVERY_PUT.plan_task(v_task,v_doc.get_string('actor'),v_r,v_domain);end if;
  if v_task.TASK_SOURCE='MANUAL' and v_task.SOURCE_DOC_TYPE='INTERWARE' then RRL_STOCK_INTERWARE_PUT.plan_task(v_task,v_doc.get_string('actor'),v_r,v_domain);end if; 
  if v_task.TASK_SOURCE='MANUAL' and v_task.SOURCE_DOC_TYPE='STORE_RETURN' then RRL_STOCK_STORE_RETURN_PUT.plan_task(v_task,v_doc.get_string('actor'),v_r,v_domain);end if; 
  if v_task.TASK_SOURCE='MANUAL'and v_task.SOURCE_DOC_TYPE='ST_DEFER'then
   RRL_STOCK_PLAN_HELPER.fence(v_p,'CONFIG','WAREHOUSE');
   RRL_ST_DEFER_WAIT_CORE.plan_task(v_task,v_doc.get_string('actor'),v_r,v_domain);
  end if;
  p_policies:=v_p.to_clob;p_resources:=v_r.to_clob;p_domain:=v_domain.to_clob; 
 end; 
end;
/


CREATE OR REPLACE package body RRL_STOCK_TASK_SCAN as
 function profile_signature(p_article varchar2) return varchar2 is
  j json_object_t:=json_object_t();a json_array_t:=json_array_t();x json_object_t;n number;v number;
 begin
  select nvl(max(MARKING_REQUIRED),0),nvl(max(POLICY_VERSION),0) into n,v from RRL_SKU_RECEIPT_POLICY where ARTICUL=p_article;
  j.put('marked',n);j.put('policy',v);
  for r in(select SYSTEM_CODE,PROFILE_CODE,PROFILE_VERSION,SCAN_MODE from RRL_SKU_RECEIPT_PROFILE where ARTICUL=p_article order by SYSTEM_CODE,PROFILE_CODE fetch first 51 rows only) loop
   if a.get_size=50 then raise_application_error(-20881,'TASK_MARK_PROFILE_BOUND');end if;
   x:=json_object_t();x.put('system',r.SYSTEM_CODE);x.put('profile',r.PROFILE_CODE);x.put('version',r.PROFILE_VERSION);x.put('scan_mode',r.SCAN_MODE);a.append(x);
  end loop;
  j.put('profiles',a);
  return rawtohex(sys.dbms_crypto.hash(j.to_clob,sys.dbms_crypto.hash_sh256));
 end;
 procedure assert_draft(p_request clob,p_task number,p_uid varchar2,p_cell varchar2,p_actor varchar2) is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t;draft RRL_TASK_SCAN_DRAFT%rowtype;
  v_version number;v_article varchar2(160);a clob;b clob;v_draft_id varchar2(100);
 begin
  m:=d.get_object('metadata');m.on_error(0);
  if not m.has('scan_draft_id') or m.get('scan_draft_id').is_null then return;end if;
  v_draft_id:=m.get_string('scan_draft_id');
  select * into draft from RRL_TASK_SCAN_DRAFT where DRAFT_ID=v_draft_id;
  if draft.TASK_ID!=p_task or draft.ACTOR!=p_actor or draft.SOURCE_UID!=p_uid or draft.SOURCE_CELL!=p_cell then
   raise_application_error(-20886,'TASK_SCAN_DRAFT_IDENTITY_CONFLICT');end if;
  select s.STOCK_VERSION,p.ARTICUL into v_version,v_article from RRL_REMAINS s join RRL_PALLETS p on p.UID_PALLET=s.UID_POLETA
   where s.UID_POLETA=p_uid and s.CELL=p_cell;
  if v_version!=draft.STOCK_VERSION or profile_signature(v_article)!=draft.PROFILE_SIGNATURE then
   raise_application_error(-20886,'TASK_SCAN_DRAFT_STALE: reload profile and scan current composition');end if;
  a:=json_array_t.parse(draft.UNIT_KEYS_JSON).to_clob;b:=m.get_array('unit_keys').to_clob;
  if dbms_lob.compare(a,b)!=0 then raise_application_error(-20884,'TASK_SCAN_DRAFT_SELECTION_CHANGED');end if;
 exception when no_data_found then raise_application_error(-20886,'TASK_SCAN_DRAFT_OR_STOCK_NOT_FOUND');
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_TRANSFER_CORE as
 procedure require_row(p_id number) is
 begin
  begin RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STOCK_RESERVATION',
   RRL_STOCK_PLAN_HELPER.decimal_text(p_id)));
  exception when others then
   if sqlcode=-20850 then raise_application_error(-20890,'CLOSURE_CHANGED: reservation set');else raise;end if;
  end;
 end;
 procedure move(p_uid varchar2,p_target_uid varchar2,p_from varchar2,p_to varchar2,p_qty number,
  p_uom varchar2,p_uom_version number,p_warehouse number,p_actor varchar2,p_line number,
  p_reservation number default null,p_units clob default null,p_new_reservation number default null,p_target_slot number default null,p_source_warehouse number default null,p_location_mode varchar2 default 'ORDINARY') is
  v_p number;v_h number;v_ver number;v_uom varchar2(20);v_article varchar2(160);v_sum number;
  v_hmove number:=0;v_event number;v_units number;v_unit_qty number;v_selected number;v_expected number;
  v_r RRL_STOCK_RESERVATION%rowtype;v_result_reservation number;v_system number;v_command varchar2(80);v_operation varchar2(100);
 begin
  if p_uid is null or p_target_uid is null or p_from is null or p_to is null or (p_from=p_to and p_uid=p_target_uid)
   or p_qty is null or p_qty<=0 then raise_application_error(-20886,'TRANSFER_CONTRACT_INVALID');end if;
  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',p_uid));
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
  RRL_STOCK_LOCK_API.assert_held(30,RRL_STOCK_LOCK_API.resource_key('HU',p_target_uid));
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_target_uid));
  select count(*) into v_sum from RRL_CASE_CARRIER_LOT where LOT_UID in(p_uid,p_target_uid);
  if v_sum>0 then
   v_operation:=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');
   select COMMAND_TYPE into v_command from RRL_STOCK_OPERATION where OPERATION_ID=v_operation;
   if v_command not in('CASE_PICK_CONFIRM','CASE_CARRIER_MOVE','CASE_CARRIER_RETURN','HU_MOVE','HU_TASK_COMPLETE') then raise_application_error(-20886,'CASE_MEMBER_REQUIRES_CARRIER_COMMAND');end if;
  end if;
  if p_location_mode='CASE_TRANSIT' then
   if p_to!='CPT_'||RRL_STOCK_PLAN_HELPER.decimal_text(p_warehouse) then raise_application_error(-20886,'CASE_TRANSIT_TARGET_REQUIRED');end if;
   select IS_SYSTEM into v_system from RRL_CELLS where CELL=p_to;
   if v_system is null or v_system!=1 then raise_application_error(-20886,'CASE_TRANSIT_SYSTEM_LOCATION_REQUIRED');end if;
   if p_from=p_to then RRL_STOCK_LOCATION_CORE.assert_quarantine(p_from,p_warehouse);
   else RRL_STOCK_LOCATION_CORE.assert_ordinary(p_from,nvl(p_source_warehouse,p_warehouse),'SOURCE');end if;
   RRL_STOCK_LOCATION_CORE.assert_quarantine(p_to,p_warehouse);
  elsif p_location_mode='CASE_EXIT' then
   if p_from!='CPT_'||RRL_STOCK_PLAN_HELPER.decimal_text(nvl(p_source_warehouse,p_warehouse)) then raise_application_error(-20886,'CASE_TRANSIT_SOURCE_REQUIRED');end if;
   RRL_STOCK_LOCATION_CORE.assert_quarantine(p_from,nvl(p_source_warehouse,p_warehouse));
   RRL_STOCK_LOCATION_CORE.assert_ordinary(p_to,p_warehouse,'TARGET');
  elsif p_location_mode='PUTAWAY' then
   RRL_STOCK_LOCATION_CORE.assert_receiving(p_from,nvl(p_source_warehouse,p_warehouse));
   RRL_STOCK_LOCATION_CORE.assert_ordinary(p_to,p_warehouse,'TARGET');
  elsif p_location_mode='QUARANTINE' then
   if RRL_HAS_WRIGHT(p_actor,'QUARANTINE_MOVE')!=1 then raise_application_error(-20882,'QUARANTINE_MOVE_FORBIDDEN');end if;
   RRL_STOCK_LOCATION_CORE.assert_quarantine(p_from,nvl(p_source_warehouse,p_warehouse));
   RRL_STOCK_LOCATION_CORE.assert_quarantine(p_to,p_warehouse);
  elsif p_location_mode='ORDINARY' then
   RRL_STOCK_LOCATION_CORE.assert_ordinary(p_from,nvl(p_source_warehouse,p_warehouse),'SOURCE');
   RRL_STOCK_LOCATION_CORE.assert_ordinary(p_to,p_warehouse,'TARGET');
  else raise_application_error(-20878,'TRANSFER_LOCATION_MODE_INVALID');end if;
  select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION,BASE_UOM into v_p,v_h,v_ver,v_uom
   from RRL_REMAINS where UID_POLETA=p_uid and CELL=p_from;
  if v_uom is null or v_uom!=p_uom or p_qty>v_p then raise_application_error(-20868,'TRANSFER_STOCK_CONFLICT');end if;
  select ARTICUL into v_article from RRL_PALLETS where UID_PALLET=p_uid;
  select count(*) into v_sum from RRL_STOCK_RESERVATION where UID_PALLET=p_uid and CELL=p_from and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') and (BASE_QTY is null or BASE_QTY<=0 or BASE_UOM is null or BASE_UOM!=p_uom);
  if v_sum>0 then raise_application_error(-20869,'HARD_BASE_IDENTITY_CONFLICT');end if;
  select nvl(sum(BASE_QTY),0) into v_sum from RRL_STOCK_RESERVATION where UID_PALLET=p_uid
   and CELL=p_from and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING');
  if v_sum!=v_h then raise_application_error(-20869,'HARD_MATERIALIZATION_CONFLICT');end if;
  for r in(select RESERVATION_ID from RRL_STOCK_RESERVATION where UID_PALLET=p_uid and CELL=p_from
   and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING')) loop require_row(r.RESERVATION_ID);end loop;
  if p_qty=v_p then
   v_hmove:=v_h;
  elsif p_reservation is not null then
   require_row(p_reservation);
   select * into v_r from RRL_STOCK_RESERVATION where RESERVATION_ID=p_reservation;
   if v_r.UID_PALLET is null or v_r.UID_PALLET!=p_uid or v_r.CELL is null or v_r.CELL!=p_from
    or v_r.RESERVATION_KIND!='HARD' or v_r.STATUS not in('ACTIVE','ALLOCATED','PICKING')
    or v_r.BASE_QTY is null or v_r.BASE_QTY<=0 then raise_application_error(-20869,'TRANSFER_RESERVATION_CONFLICT');end if;
   v_hmove:=least(p_qty,v_r.BASE_QTY);
   if p_qty-v_hmove>v_p-v_h then raise_application_error(-20869,'TRANSFER_FREE_PORTION_INSUFFICIENT');end if;
  elsif p_qty>v_p-v_h then raise_application_error(-20869,'TRANSFER_UNRESERVED_INSUFFICIENT');end if;
  if p_target_uid!=p_uid then
   declare t RRL_PALLETS%rowtype;s RRL_PALLETS%rowtype;
   begin
    select * into s from RRL_PALLETS where UID_PALLET=p_uid;
    select * into t from RRL_PALLETS where UID_PALLET=p_target_uid;
    if t.ARTICUL!=s.ARTICUL or t.PRIHOD_NAKLAD_ID!=s.PRIHOD_NAKLAD_ID
     or (t.EXPIRY_DATE!=s.EXPIRY_DATE or (t.EXPIRY_DATE is null and s.EXPIRY_DATE is not null) or (t.EXPIRY_DATE is not null and s.EXPIRY_DATE is null)) or (t.PRODUCED_DATE!=s.PRODUCED_DATE or (t.PRODUCED_DATE is null and s.PRODUCED_DATE is not null) or (t.PRODUCED_DATE is not null and s.PRODUCED_DATE is null))
     or (t.PROD_BATCH_ID!=s.PROD_BATCH_ID or (t.PROD_BATCH_ID is null and s.PROD_BATCH_ID is not null) or (t.PROD_BATCH_ID is not null and s.PROD_BATCH_ID is null)) then raise_application_error(-20887,'TRANSFER_LOT_IDENTITY_CONFLICT');end if;
   end;
  end if;
  select count(*),nvl(sum(BASE_QTY),0) into v_units,v_unit_qty from RRL_WMS_RECEIPT_UNIT
   where CURRENT_UID=p_uid and CURRENT_CELL=p_from and STOCK_STATUS!='ISSUED';
  if v_units>0 then
   -- CURRENT_UID is the warehouse physical authority. Published regulatory
   -- aggregations are retained; the coordinator queues composition before/after
   -- in the same transaction, for asynchronous regulatory reaggregation.
   -- Birth UID/code and external acknowledgement are never rewritten here.
   if v_unit_qty!=v_p then raise_application_error(-20884,'COMPOSITION_STOCK_CONFLICT');end if;
   if p_qty!=v_p and p_units is null then raise_application_error(-20884,'PARTIAL_UNIT_SELECTION_REQUIRED');end if;
   select count(*),nvl(sum(u.BASE_QTY),0) into v_selected,v_unit_qty from RRL_WMS_RECEIPT_UNIT u
    where u.CURRENT_UID=p_uid and u.CURRENT_CELL=p_from and u.STOCK_STATUS!='ISSUED' and
     (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY));
   if v_unit_qty!=p_qty then raise_application_error(-20884,'SELECTED_UNIT_QUANTITY_CONFLICT');end if;
   if p_units is not null then
    select count(distinct K) into v_expected from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'));
    if v_expected!=v_selected then raise_application_error(-20884,'SELECTED_UNIT_IDENTITY_CONFLICT');end if;
   end if;
   if p_qty!=v_p and p_reservation is not null then
    select nvl(sum(u.BASE_QTY),0) into v_unit_qty from RRL_WMS_RECEIPT_UNIT u
     where u.CURRENT_UID=p_uid and u.CURRENT_CELL=p_from and u.HARD_RESERVATION_ID=p_reservation and
      (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY));
    if v_unit_qty!=v_hmove then raise_application_error(-20869,'RESERVED_UNIT_SELECTION_CONFLICT');end if;
   end if;
   for u in(select PHYSICAL_UNIT_KEY,HARD_RESERVATION_ID from RRL_WMS_RECEIPT_UNIT
    where CURRENT_UID=p_uid and CURRENT_CELL=p_from and STOCK_STATUS!='ISSUED' and
     (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=PHYSICAL_UNIT_KEY))) loop
    begin RRL_STOCK_LOCK_API.assert_held(60,RRL_STOCK_LOCK_API.resource_key('UNIT',u.PHYSICAL_UNIT_KEY));
    exception when others then if sqlcode=-20850 then raise_application_error(-20890,'CLOSURE_CHANGED: unit set');else raise;end if;end;
    if u.HARD_RESERVATION_ID is not null and p_qty!=v_p and
      (p_reservation is null or u.HARD_RESERVATION_ID!=p_reservation) then raise_application_error(-20869,'UNIT_RESERVED_BY_OTHER_OWNER');end if;
   end loop;
  else
   select nvl(max(MARKING_REQUIRED),0) into v_expected from RRL_SKU_RECEIPT_POLICY where ARTICUL=v_article;
   if v_expected=1 then raise_application_error(-20884,'MARKED_BINDING_REQUIRED');end if;
  end if;
  RRL_STOCK_BALANCE_CORE.apply_delta(p_uid,p_from,-p_qty,-v_hmove,p_uom,p_uom_version,v_ver);
  RRL_STOCK_BALANCE_CORE.apply_delta(p_target_uid,p_to,p_qty,v_hmove,p_uom,p_uom_version);
  if p_qty=v_p then
   for c in(select TASK_ID from RRL_RECEIPT_SLOT_CLAIM where UID_PALLET=p_uid and CELL=p_from and STATUS='OCCUPIED') loop
    RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_RECEIPT_SLOT_CLAIM',RRL_STOCK_PLAN_HELPER.decimal_text(c.TASK_ID)));
    delete from RRL_RECEIPT_SLOT_CLAIM where TASK_ID=c.TASK_ID and STATUS='OCCUPIED';
   end loop;
  end if;
  if v_hmove>0 then
   for r in(select RESERVATION_ID,BASE_QTY from RRL_STOCK_RESERVATION
    where UID_PALLET=p_uid and CELL=p_from and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING')
     and (p_qty=v_p or RESERVATION_ID=p_reservation)) loop
    RRL_STOCK_RESERVE_CORE.move_coverage(r.RESERVATION_ID,p_new_reservation,p_target_uid,p_to,p_warehouse,
     case when p_qty=v_p then r.BASE_QTY else v_hmove end,p_target_slot,p_actor,v_result_reservation);
    RRL_STOCK_CTX_API.begin_effect('UNIT',p_uid,p_from);
    update RRL_WMS_RECEIPT_UNIT set HARD_RESERVATION_ID=v_result_reservation,UNIT_VERSION=UNIT_VERSION+1
     where CURRENT_UID=p_uid and CURRENT_CELL=p_from and HARD_RESERVATION_ID=r.RESERVATION_ID and
      (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=PHYSICAL_UNIT_KEY));
    RRL_STOCK_CTX_API.end_effect;
   end loop;
  end if;
  RRL_STOCK_CTX_API.begin_effect('UNIT',p_uid,p_from);
  update RRL_WMS_RECEIPT_UNIT set CURRENT_UID=p_target_uid,CURRENT_CELL=p_to,UNIT_VERSION=UNIT_VERSION+1
   where CURRENT_UID=p_uid and CURRENT_CELL=p_from and STOCK_STATUS!='ISSUED' and
    (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=PHYSICAL_UNIT_KEY));
  RRL_STOCK_CTX_API.end_effect;
  if p_target_uid=p_uid then
   RRL_STOCK_BALANCE_CORE.write_move(p_uid,p_from,p_to,p_qty,p_uom,p_uom_version,p_line,p_actor,v_event);
  else
  RRL_STOCK_BALANCE_CORE.write_leg(p_uid,p_from,null,-p_qty,p_uom,p_uom_version,p_line,1,2,p_actor,v_event);
  RRL_STOCK_BALANCE_CORE.write_leg(p_target_uid,null,p_to,p_qty,p_uom,p_uom_version,p_line,2,2,p_actor,v_event);
  end if;
 end;
end;
/


CREATE OR REPLACE PACKAGE BODY          "RRL_STOCK_TRIP_DEPART_CMD" as
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t:=json_object_t();f json_array_t:=json_array_t();r json_array_t:=json_array_t();members json_array_t:=json_array_t();loads json_array_t:=json_array_t();
  trip_no number:=d.get_object('source').get_number('task_id');tt RRL_TRANSPORT_TASK%rowtype;vehicle_no number;ware_no number;n number:=0;promise_wire clob;thermal_value json_object_t;floor_wire clob;
 begin
  promise_wire:=RRL_INTERWARE_DEPART_GATE.promises(trip_no);RRL_INTERWARE_DEPART_GATE.assert_ready(promise_wire);
  select * into tt from RRL_TRANSPORT_TASK where ID=trip_no;
  select ID into vehicle_no from RRL_TR_VEHICLE where NUM=tt.TRANSPORT and nvl(DELETED,0)=0;
  select WARE_ID into ware_no from RRL_TT_DOCK where DOCK=tt.DOCK;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(trip_no));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VEHICLE',RRL_STOCK_PLAN_HELPER.decimal_text(vehicle_no));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TR_VODITEL',RRL_STOCK_PLAN_HELPER.decimal_text(tt.VODITEL_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_VEHICLE_SOURCE',RRL_STOCK_PLAN_HELPER.decimal_text(trip_no));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_DOCK',tt.DOCK);
  for sp in(select ID from RRL_SBORKA_PALLETS where TRANSTASK_ID=trip_no order by ID fetch first 201 rows only) loop
   n:=n+1;if n>200 then raise_application_error(-20881,'DEPART_MEMBER_ST_BOUND_200');end if;
   members.append(sp.ID);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(sp.ID));
  end loop;
  if n=0 then raise_application_error(-20886,'DEPART_ASSIGNED_ST_REQUIRED');end if;
  n:=0;
  for ld in(select LOAD_OPERATION_ID from RRL_TT_HU_LOAD_FACT where TT_ID=trip_no and STATUS='LOADED' order by LOAD_OPERATION_ID fetch first 201 rows only) loop
   n:=n+1;if n>200 then raise_application_error(-20881,'DEPART_PLACE_BOUND_200');end if;
   loads.append(ld.LOAD_OPERATION_ID);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',ld.LOAD_OPERATION_ID);
  end loop;
  if n=0 then raise_application_error(-20886,'DEPART_PHYSICAL_LOAD_REQUIRED');end if;
  floor_wire:=RRL_STOCK_LOAD_FLOOR.checked_trip(trip_no,vehicle_no);
  if floor_wire is null then v.put_null('floor_at_departure');else v.put('floor_at_departure',json_object_t.parse(floor_wire));end if;
  RRL_STOCK_LOAD_THERMAL.compile_confirmation(members.to_clob,vehicle_no,d.get_object('metadata').to_clob,thermal_value,'MANUAL_AT_DEPARTURE');
  if thermal_value is null then v.put_null('temperature_at_departure');else v.put('temperature_at_departure',thermal_value);end if;
  v.put('incoming_promises',json_array_t.parse(promise_wire));
  v.put('trip',trip_no);v.put('vehicle_id',vehicle_no);v.put('vehicle',tt.TRANSPORT);v.put('dock',tt.DOCK);v.put('warehouse',ware_no);v.put('driver_id',tt.VODITEL_ID);v.put('members',members);v.put('loads',loads);
  p_policies:=f.to_clob;p_resources:=r.to_clob;p_domain:=v.to_clob;
 exception when no_data_found then raise_application_error(-20886,'DEPART_TRIP_VEHICLE_DOCK_CONFIGURATION_REQUIRED');
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);plan clob;v json_object_t;j json_object_t:=json_object_t();tt RRL_TRANSPORT_TASK%rowtype;veh RRL_TR_VEHICLE%rowtype;
  trip_no number;vehicle_no number;ware_no number;blocked_no number;places number;mass_no number;minimum_no number;member_ids clob;load_ids clob;n number;op varchar2(100):=d.get_string('operation_id');dock_name varchar2(50);promise_wire clob;depart_instant timestamp with time zone;thermal_element json_element_t;thermal_wire clob;floor_wire clob;floor_element json_element_t;
 begin
  if RRL_HAS_WRIGHT(p_actor,'transport_dispatch_close')!=1 then raise_application_error(-20882,'TRIP_DEPART_FORBIDDEN');end if;
  select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(plan).get_object('domain');
  trip_no:=v.get_number('trip');vehicle_no:=v.get_number('vehicle_id');dock_name:=v.get_string('dock');member_ids:=v.get_array('members').to_clob;load_ids:=v.get_array('loads').to_clob;
  select * into veh from RRL_TR_VEHICLE where ID=vehicle_no for update;
  select * into tt from RRL_TRANSPORT_TASK where ID=trip_no for update;
  select WARE_ID,nvl(DOCK_IS_BLOCKED,0) into ware_no,blocked_no from RRL_TT_DOCK where DOCK=dock_name for update;
  if tt.CONDITION is null or tt.CONDITION!=unistr('\0421\043F\043B\0430\043D\0438\0440\043E\0432\0430\043D') or nvl(tt.DELETED,0)!=0 or tt.TRANSPORT!=v.get_string('vehicle') or tt.DOCK!=dock_name or tt.VODITEL_ID is null
   or nvl(tt.VODITEL_ID,-1)!=nvl(v.get_number('driver_id'),-1) or veh.NUM!=tt.TRANSPORT or nvl(veh.BLOCKED,0)!=0 or nvl(veh.WORKING_NOW,0)!=1 or nvl(veh.DELETED,0)!=0 or ware_no!=v.get_number('warehouse') or blocked_no!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: departure assignment');end if;
  begin select ID into n from RRL_TR_VODITEL where ID=tt.VODITEL_ID and nvl(DELETED,0)=0 for update;
  exception when no_data_found then raise_application_error(-20886,'DEPART_ACTUAL_DRIVER_REQUIRED');end;
  n:=1;
  if n!=1 then raise_application_error(-20886,'DEPART_ACTUAL_DRIVER_REQUIRED');end if;
  promise_wire:=RRL_INTERWARE_DEPART_GATE.promises(trip_no);RRL_INTERWARE_DEPART_GATE.assert_ready(promise_wire);
  if dbms_lob.compare(promise_wire,v.get_array('incoming_promises').to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: expected incoming cargo');end if;
  for sp in(select ID from RRL_SBORKA_PALLETS where ID in(select ID from json_table(member_ids,'$[*]' columns(ID number path '$'))) order by ID) loop
   select ID into n from RRL_SBORKA_PALLETS where ID=sp.ID for update;
  end loop;
  select count(*) into n from RRL_SBORKA_PALLETS where TRANSTASK_ID=trip_no;
  if n!=v.get_array('members').get_size then raise_application_error(-20890,'CLOSURE_CHANGED: departure ST membership');end if;
  select count(*) into n from RRL_SBORKA_PALLETS sp where sp.TRANSTASK_ID=trip_no and(sp.CONDITION is null or sp.CONDITION!=2 or not exists(
   select 1 from RRL_TT_HU_LOAD_ST ls join RRL_TT_HU_LOAD_FACT lf on lf.LOAD_OPERATION_ID=ls.LOAD_OPERATION_ID
    join RRL_STOCK_OPERATION operation_record on operation_record.OPERATION_ID=lf.LOAD_OPERATION_ID and operation_record.STATE='APPLIED'
   where ls.SBORKA_PALLET_ID=sp.ID and lf.TT_ID=trip_no and lf.VEHICLE_ID=vehicle_no and lf.VEHICLE_NUMBER=tt.TRANSPORT and lf.DOCK=dock_name and lf.STATUS='LOADED'));
  if n>0 then raise_application_error(-20886,'DEPART_WAITING_FOR_ACTUAL_LOADED_STS');end if;
  select count(*),nvl(sum(GROSS_WEIGHT_KG),0) into places,mass_no from RRL_TT_HU_LOAD_FACT where TT_ID=trip_no and STATUS='LOADED';
  if places!=v.get_array('loads').get_size then raise_application_error(-20890,'CLOSURE_CHANGED: departure physical places');end if;
  if v.has('floor_at_departure')then floor_element:=v.get('floor_at_departure');if not floor_element.is_null then floor_wire:=floor_element.to_clob;end if;end if;
  RRL_STOCK_LOAD_FLOOR.assert_departure(trip_no,vehicle_no,floor_wire);
  select nvl(MIN_PALLET_LOAD,0) into minimum_no from RRL_TRANSPORT_TYPE where TRANSPORTTYPE=veh.TR_TYPE;
  if veh.PALLETS is null or veh.MAX_WEIGHT_KG is null or(floor_wire is null and places>veh.PALLETS)or mass_no>veh.MAX_WEIGHT_KG then raise_application_error(-20886,'DEPART_PHYSICAL_CAPACITY_EXCEEDED');end if;
  if places<minimum_no and RRL_HAS_WRIGHT(p_actor,'SEND_EMPTY_TRUCK')!=1 then raise_application_error(-20886,'DEPART_BELOW_MINIMUM_PHYSICAL_LOAD');end if;
  if v.has('temperature_at_departure')then thermal_element:=v.get('temperature_at_departure');if not thermal_element.is_null then thermal_wire:=thermal_element.to_clob;end if;end if;
  RRL_STOCK_LOAD_THERMAL.assert_current(member_ids,vehicle_no,thermal_wire,'MANUAL_AT_DEPARTURE');
  RRL_STORE_ACCESS_RULES.assert_members(vehicle_no,member_ids);
  depart_instant:=systimestamp;
  for ld in(select ID from json_table(load_ids,'$[*]' columns(ID varchar2(100) path '$')) order by ID) loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TT_HU_LOAD_FACT',ld.ID));
   update RRL_TT_HU_LOAD_FACT set STATUS='DEPARTED',DEPARTURE_OPERATION_ID=op,DEPARTED_AT=depart_instant where LOAD_OPERATION_ID=ld.ID and TT_ID=trip_no and STATUS='LOADED';
   if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: departure load fact');end if;
  end loop;
  update RRL_TRANSPORT_TASK set CONDITION=unistr('\041E\0442\0433\0440\0443\0436\0435\043D'),USER_ID=p_actor where ID=trip_no;
  RRL_VEH_DEPART_SOURCE.capture_source(op,trip_no,vehicle_no,depart_instant);
  if floor_wire is not null then j.put('floor_at_departure',json_object_t.parse(floor_wire));end if;
  if thermal_wire is not null then j.put('temperature_at_departure',json_object_t.parse(thermal_wire));j.put('temperature_confirmed_at',to_char(depart_instant,'YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM'));end if;
  j.put('operation_id',op);j.put('task_id',trip_no);j.put('status','DEPARTED');j.put('physical_places',places);j.put('gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(mass_no));j.put('stock_consumed_again',false);p_result:=j.to_clob;
 exception when no_data_found then raise_application_error(-20886,'DEPART_CONFIGURATION_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_UNIT_CORE as 
 procedure require_context is 
 begin 
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null or 
   sys_context('RRL_STOCK_WRITE_CTX','TX_ID') is null or 
   sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false) then 
   raise_application_error(-20863,'UNIT_WRITE_FORBIDDEN');end if; 
 end; 
 procedure own_unit(p_key varchar2) is n number; 
 begin 
  if p_key is null then raise_application_error(-20884,'UNIT_BINDING_REQUIRED');end if; 
  select count(*)into n from RRL_INTERWARE_SHORTAGE_UNIT booked where booked.PHYSICAL_UNIT_KEY=p_key
 and not exists(select 1 from RRL_INTERWARE_RECOVERY_UNIT recovered join RRL_STOCK_OPERATION o on o.OPERATION_ID=recovered.RECOVERY_OPERATION_ID
 where recovered.PHYSICAL_UNIT_KEY=booked.PHYSICAL_UNIT_KEY and recovered.LOSS_OPERATION_ID=booked.FACT_OPERATION_ID
 and o.COMMAND_TYPE='INTERWARE_SHORTAGE_RECOVER'and(o.STATE='APPLIED'or(o.STATE='IN_FLIGHT'and o.OPERATION_ID=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID'))));if n!=0 then raise_application_error(-20886,'UNIT_CONFIRMED_CARRIER_LOSS_REQUIRES_CORRECTION');end if; 
  begin RRL_STOCK_LOCK_API.assert_held(60,RRL_STOCK_LOCK_API.resource_key('UNIT',p_key)); 
  exception when others then if sqlcode=-20850 then raise_application_error(-20890,'CLOSURE_CHANGED: units');else raise;end if;end; 
 end; 
 procedure assert_composition(p_uid varchar2,p_cell varchar2) is 
  v_p number;v_base varchar2(20);v_total number;v_count number;v_bad number;v_article varchar2(160);v_capture_required number;v_scale number; 
 begin 
  select REMAIN,BASE_UOM into v_p,v_base from RRL_REMAINS where UID_POLETA=p_uid and CELL=p_cell; 
  select ARTICUL into v_article from RRL_PALLETS where UID_PALLET=p_uid; 
  select greatest(nvl((select SERIALIZED_WEIGHT_BOXES from RRL_SKU_RECEIPT_POLICY where ARTICUL=v_article),0),nvl((select MARKING_REQUIRED from RRL_SKU_RECEIPT_POLICY where ARTICUL=v_article),0), 
   nvl((select CRPT_REQUIRED from RRL_FINISHED_GOODS_SKU where ARTICUL=v_article),0), 
   case when exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=v_article) then 1 else 0 end) into v_capture_required from dual; 
  select count(*),nvl(sum(BASE_QTY),0),nvl(sum(case when PHYSICAL_UNIT_KEY is null or STOCK_STATUS is null or BASE_QTY<=0 or BASE_UOM is null or BASE_UOM!=v_base then 1 else 0 end),0) 
   into v_count,v_total,v_bad from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and (STOCK_STATUS is null or STOCK_STATUS!='ISSUED'); 
  select max(BASE_SCALE) into v_scale from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and BASE_UOM=v_base; 
  if v_scale is null then raise_application_error(-20868,'COMPOSITION_BASE_POLICY_REQUIRED');end if; 
  select count(*) into v_bad from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and (STOCK_STATUS is null or STOCK_STATUS!='ISSUED') 
   and (STOCK_STATUS is null or BASE_QTY is null or BASE_QTY<=0 or abs(BASE_QTY)>=power(10,18) or trunc(BASE_QTY,v_scale)!=BASE_QTY or BASE_UOM is null or BASE_UOM!=v_base or PHYSICAL_UNIT_KEY is null); 
  if v_bad>0 or (v_count>0 and v_total!=v_p) or (v_capture_required=1 and v_p>0 and v_count=0) then 
   raise_application_error(-20884,'PHYSICAL_COMPOSITION_CONFLICT');end if; 
 end; 
 function automatic_units(p_uid varchar2,p_cell varchar2,p_qty number) return clob is 
  a json_array_t:=json_array_t();v_n number;v_qty number:=0; 
 begin 
  require_context;assert_composition(p_uid,p_cell); 
  select count(*) into v_n from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED'; 
  if v_n=0 then return null;end if; 
  for u in(select PHYSICAL_UNIT_KEY,BASE_QTY from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS='AVAILABLE' and HARD_RESERVATION_ID is null order by PHYSICAL_UNIT_KEY) loop 
   exit when v_qty=p_qty; 
   own_unit(u.PHYSICAL_UNIT_KEY); 
   if v_qty+u.BASE_QTY>p_qty then raise_application_error(-20884,'PHYSICAL_UNIT_ALLOCATION_REQUIRES_SELECTION');end if; 
   a.append(u.PHYSICAL_UNIT_KEY);v_qty:=v_qty+u.BASE_QTY; 
   if a.get_size>10000 then raise_application_error(-20884,'UNIT_SELECTION_BOUND');end if; 
  end loop; 
  if v_qty!=p_qty then raise_application_error(-20884,'ADMITTED_FREE_UNITS_INSUFFICIENT');end if; 
  return a.to_clob; 
 end; 
 procedure admit_captured(p_uid varchar2,p_cell varchar2) is 
 begin 
  require_context;assert_composition(p_uid,p_cell); 
  for u in(select PHYSICAL_UNIT_KEY from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS='CAPTURED') loop own_unit(u.PHYSICAL_UNIT_KEY);end loop; 
  RRL_STOCK_CTX_API.begin_effect('UNIT',p_uid,p_cell); 
  update RRL_WMS_RECEIPT_UNIT set STOCK_STATUS='AVAILABLE',UNIT_VERSION=UNIT_VERSION+1 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS='CAPTURED'; 
  RRL_STOCK_CTX_API.end_effect; 
 end; 
 procedure issue_free_units(p_uid varchar2,p_cell varchar2,p_qty number,p_units clob) is v_total number;v_count number;v_qty number;v_expected number;v_distinct number; 
 begin 
  require_context;assert_composition(p_uid,p_cell); 
  select count(*) into v_total from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED'; 
  if v_total=0 then return;end if; 
  select count(*),nvl(sum(BASE_QTY),0) into v_count,v_qty from RRL_WMS_RECEIPT_UNIT u 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY)); 
  if v_qty!=p_qty then raise_application_error(-20884,'ISSUE_UNIT_QUANTITY_CONFLICT');end if; 
  if p_units is not null then 
   select count(*),count(distinct K) into v_expected,v_distinct from json_table(p_units,'$[*]' columns(K varchar2(64) path '$')); 
   if v_count!=v_expected or v_expected!=v_distinct then raise_application_error(-20884,'UNIT_SELECTION_CONFLICT');end if; 
  end if; 
  for r in(select PHYSICAL_UNIT_KEY,STOCK_STATUS,HARD_RESERVATION_ID from RRL_WMS_RECEIPT_UNIT u 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY))) loop 
   own_unit(r.PHYSICAL_UNIT_KEY); 
   if r.HARD_RESERVATION_ID is not null then raise_application_error(-20869,'UNIT_RESERVED_BY_OTHER_OWNER');end if; 
   if r.STOCK_STATUS!='AVAILABLE' then raise_application_error(-20884,'UNIT_NOT_ADMITTED');end if; 
  end loop; 
  RRL_STOCK_CTX_API.begin_effect('UNIT',p_uid,p_cell); 
  update RRL_WMS_RECEIPT_UNIT u set STOCK_STATUS='ISSUED',UNIT_VERSION=UNIT_VERSION+1 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY)); 
  RRL_STOCK_CTX_API.end_effect; 
 end; 
 procedure reserve_units(p_uid varchar2,p_cell varchar2,p_id number,p_qty number,p_units clob) is 
  v_count number;v_total number;v_chosen number;v_qty number;v_expected number; 
 begin 
  require_context;assert_composition(p_uid,p_cell); 
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid)); 
  select count(*),nvl(sum(BASE_QTY),0) into v_count,v_total from RRL_WMS_RECEIPT_UNIT 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED'; 
  if v_count=0 then return;end if; 
  select count(*),nvl(sum(BASE_QTY),0) into v_chosen,v_qty from RRL_WMS_RECEIPT_UNIT u 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY)); 
  if v_qty!=p_qty then raise_application_error(-20884,'RESERVATION_UNIT_QUANTITY_CONFLICT');end if; 
  if p_units is not null then 
   select count(*),count(distinct K) into v_expected,v_count from json_table(p_units,'$[*]' columns(K varchar2(64) path '$')); 
   if v_expected!=v_count or v_expected!=v_chosen then raise_application_error(-20884,'UNIT_SELECTION_CONFLICT');end if; 
  end if; 
  for r in(select PHYSICAL_UNIT_KEY,HARD_RESERVATION_ID,STOCK_STATUS from RRL_WMS_RECEIPT_UNIT u 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY))) loop 
   own_unit(r.PHYSICAL_UNIT_KEY); 
   if r.HARD_RESERVATION_ID is not null then raise_application_error(-20869,'UNIT_ALREADY_RESERVED');end if; 
   if r.STOCK_STATUS!='AVAILABLE' then raise_application_error(-20884,'UNIT_NOT_ADMITTED');end if; 
  end loop; 
  RRL_STOCK_CTX_API.begin_effect('UNIT',p_uid,p_cell); 
  update RRL_WMS_RECEIPT_UNIT u set HARD_RESERVATION_ID=p_id,UNIT_VERSION=UNIT_VERSION+1 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY)); 
  RRL_STOCK_CTX_API.end_effect; 
 end; 
 procedure release_units(p_id number,p_qty number,p_units clob,p_issue number default 0) is 
  v_qty number;v_count number;v_expected number;v_distinct number;v_uid varchar2(200);v_cell varchar2(60); 
 begin 
  require_context; 
  select UID_PALLET,CELL into v_uid,v_cell from RRL_STOCK_RESERVATION where RESERVATION_ID=p_id; 
  assert_composition(v_uid,v_cell); 
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',v_uid)); 
  select count(*),nvl(sum(BASE_QTY),0) into v_count,v_qty from RRL_WMS_RECEIPT_UNIT u 
   where HARD_RESERVATION_ID=p_id and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY)); 
  if v_count=0 then 
   select count(*) into v_expected from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=v_uid and CURRENT_CELL=v_cell and STOCK_STATUS!='ISSUED'; 
   if v_expected>0 then raise_application_error(-20869,'RESERVATION_UNIT_BINDING_REQUIRED');end if; 
   return;end if; 
  if v_qty!=p_qty then raise_application_error(-20884,'RESERVATION_UNIT_QUANTITY_CONFLICT');end if; 
  if p_units is not null then 
   select count(*),count(distinct K) into v_expected,v_distinct from json_table(p_units,'$[*]' columns(K varchar2(64) path '$')); 
   if v_count!=v_expected or v_expected!=v_distinct then raise_application_error(-20884,'UNIT_SELECTION_CONFLICT');end if; 
  end if; 
  for r in(select PHYSICAL_UNIT_KEY,STOCK_STATUS from RRL_WMS_RECEIPT_UNIT u 
   where HARD_RESERVATION_ID=p_id and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY))) loop 
   own_unit(r.PHYSICAL_UNIT_KEY); 
   if p_issue=1 and r.STOCK_STATUS!='AVAILABLE' then raise_application_error(-20884,'UNIT_NOT_ADMITTED');end if; 
  end loop; 
  RRL_STOCK_CTX_API.begin_effect('UNIT',v_uid,v_cell); 
  update RRL_WMS_RECEIPT_UNIT u set HARD_RESERVATION_ID=null,UNIT_VERSION=UNIT_VERSION+1, 
   STOCK_STATUS=case when p_issue=1 then 'ISSUED' else STOCK_STATUS end 
   where HARD_RESERVATION_ID=p_id and STOCK_STATUS!='ISSUED' 
    and (p_units is null or exists(select 1 from json_table(p_units,'$[*]' columns(K varchar2(64) path '$'))j where j.K=u.PHYSICAL_UNIT_KEY)); 
  RRL_STOCK_CTX_API.end_effect; 
 end; 
 procedure restore_issued(p_uid varchar2,p_cell varchar2,p_new_reservation number,p_qty number,p_units clob)is 
  op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');n number;v_count number;v_sum number;v_expected number;v_distinct number;locked_version number; 
 begin 
  require_context; 
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid)); 
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(p_new_reservation))); 
  select count(*)into n from RRL_STOCK_OPERATION o join json_table(o.RESOLVED_PLAN_JSON,'$.domain.legs[*]'columns(UID_TEXT varchar2(150)path '$.uid',CELL_TEXT varchar2(60)path '$.cell',NEW_RES number path '$.new_reservation',QTY_TEXT varchar2(60)path '$.quantity',UNITS clob format json path '$.restored_units'))leg 
   on leg.UID_TEXT=p_uid and leg.CELL_TEXT=p_cell and leg.NEW_RES=p_new_reservation and leg.QTY_TEXT=RRL_STOCK_PLAN_HELPER.decimal_text(p_qty) and dbms_lob.compare(leg.UNITS,p_units)=0 
   where o.OPERATION_ID=op and o.COMMAND_TYPE='UNLOAD_SHIPMENT'and o.STATE='IN_FLIGHT'; 
  if n!=1 then raise_application_error(-20863,'UNLOAD_UNIT_RECOVERY_PLAN_REQUIRED');end if; 
  select count(*),count(distinct K)into v_expected,v_distinct from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key')); 
  if v_expected<1 or v_expected>10000 or v_expected!=v_distinct then raise_application_error(-20884,'UNLOAD_UNIT_SET_REQUIRED');end if; 
  v_count:=0;v_sum:=0; 
  for u in(select u.PHYSICAL_UNIT_KEY,u.BASE_QTY,u.BASE_UOM,u.STOCK_STATUS,u.HARD_RESERVATION_ID,u.UNIT_VERSION,j.V,j.Q,j.UOM 
   from RRL_WMS_RECEIPT_UNIT u join json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key',V number path '$.version',Q varchar2(60)path '$.quantity',UOM varchar2(20)path '$.base_uom'))j on j.K=u.PHYSICAL_UNIT_KEY 
   where u.CURRENT_UID=p_uid and u.CURRENT_CELL=p_cell order by u.PHYSICAL_UNIT_KEY)loop 
   own_unit(u.PHYSICAL_UNIT_KEY); 
   select UNIT_VERSION into locked_version from RRL_WMS_RECEIPT_UNIT where PHYSICAL_UNIT_KEY=u.PHYSICAL_UNIT_KEY for update; 
   if locked_version!=u.UNIT_VERSION then raise_application_error(-20890,'CLOSURE_CHANGED: unload unit physical row');end if; 
   if u.STOCK_STATUS!='ISSUED'or u.HARD_RESERVATION_ID is not null or u.UNIT_VERSION!=u.V or u.BASE_QTY!=RRL_STOCK_MATH.quantity(u.Q)or u.BASE_UOM!=u.UOM then raise_application_error(-20890,'CLOSURE_CHANGED: unload exact issued unit');end if; 
   v_count:=v_count+1;v_sum:=v_sum+u.BASE_QTY; 
  end loop; 
  if v_count!=v_expected or v_sum!=p_qty then raise_application_error(-20884,'UNLOAD_UNIT_QUANTITY_CONFLICT');end if; 
  RRL_STOCK_CTX_API.begin_effect('UNIT',p_uid,p_cell); 
  update RRL_WMS_RECEIPT_UNIT u set STOCK_STATUS='AVAILABLE',HARD_RESERVATION_ID=p_new_reservation,UNIT_VERSION=UNIT_VERSION+1 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and exists(select 1 from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key'))j where j.K=u.PHYSICAL_UNIT_KEY); 
  if sql%rowcount!=v_expected then raise_application_error(-20890,'CLOSURE_CHANGED: unload unit count');end if; 
  RRL_STOCK_CTX_API.end_effect;assert_composition(p_uid,p_cell); 
 exception when others then RRL_STOCK_CTX_API.end_effect;raise; 
 end; 
 procedure receive_issued(p_uid varchar2,p_source_cell varchar2,p_target_cell varchar2,p_qty number,p_units clob)is 
  op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');n number;expected_count number;actual_count number;total number;locked_version number; 
 begin 
  require_context;RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid)); 
  select count(*)into n from RRL_STOCK_OPERATION o join json_table(o.RESOLVED_PLAN_JSON,'$.domain'columns(U varchar2(150)path '$.uid',S varchar2(60)path '$.source_cell',T varchar2(60)path '$.receive_cell',Q varchar2(60)path '$.quantity',A clob format json path '$.source_units'))d 
   on d.U=p_uid and d.S=p_source_cell and d.T=p_target_cell and d.Q=RRL_STOCK_PLAN_HELPER.decimal_text(p_qty) and dbms_lob.compare(d.A,p_units)=0 
   where o.OPERATION_ID=op and o.COMMAND_TYPE='INTERWARE_RECEIVE'and o.STATE='IN_FLIGHT'; 
  if n=0 then
   select count(*)into n from RRL_STOCK_OPERATION o join json_table(o.RESOLVED_PLAN_JSON,'$.domain'columns(
    GROUP_FLAG varchar2(5)path '$.group_receipt',TARGET_CELL varchar2(60)path '$.receive_cell',
    nested path '$.lots[*]'columns(LOT_UID varchar2(200)path '$.uid',SOURCE_CELL varchar2(60)path '$.issued_manifest.source_cell',QTY_TEXT varchar2(60)path '$.quantity',UNITS_JSON clob format json path '$.issued_manifest.units')))g
    on g.GROUP_FLAG='true'and g.LOT_UID=p_uid and g.SOURCE_CELL=p_source_cell and g.TARGET_CELL=p_target_cell and g.QTY_TEXT=RRL_STOCK_PLAN_HELPER.decimal_text(p_qty)and dbms_lob.compare(g.UNITS_JSON,p_units)=0
    where o.OPERATION_ID=op and o.COMMAND_TYPE='INTERWARE_RECEIVE'and o.STATE='IN_FLIGHT';
  end if;
  if n!=1 then raise_application_error(-20863,'INTERWARE_UNIT_RECEIPT_PLAN_REQUIRED');end if; 
  select count(*),count(distinct K)into expected_count,n from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key')); 
  if expected_count<1 or expected_count>10000 or n!=expected_count then raise_application_error(-20884,'INTERWARE_UNIT_SET_REQUIRED');end if; 
  select count(*),sum(BASE_QTY)into actual_count,total from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid; 
  if actual_count!=expected_count or total!=p_qty then raise_application_error(-20884,'INTERWARE_WHOLE_UNIT_SET_REQUIRED');end if; 
  actual_count:=0; 
  for x in(select u.PHYSICAL_UNIT_KEY,u.UNIT_VERSION,u.STOCK_STATUS,u.HARD_RESERVATION_ID,u.BASE_QTY,u.BASE_UOM,j.V,j.Q,j.B 
   from RRL_WMS_RECEIPT_UNIT u join json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key',V number path '$.version',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))j on j.K=u.PHYSICAL_UNIT_KEY 
   where u.CURRENT_UID=p_uid and u.CURRENT_CELL=p_source_cell order by u.PHYSICAL_UNIT_KEY)loop 
   own_unit(x.PHYSICAL_UNIT_KEY); 
   select UNIT_VERSION into locked_version from RRL_WMS_RECEIPT_UNIT where PHYSICAL_UNIT_KEY=x.PHYSICAL_UNIT_KEY for update; 
   if locked_version!=x.V or x.UNIT_VERSION!=x.V or x.STOCK_STATUS!='ISSUED'or x.HARD_RESERVATION_ID is not null or x.BASE_QTY!=RRL_STOCK_MATH.quantity(x.Q)or x.BASE_UOM!=x.B then raise_application_error(-20890,'CLOSURE_CHANGED: interware original unit');end if; 
   actual_count:=actual_count+1; 
  end loop; 
  if actual_count!=expected_count then raise_application_error(-20884,'INTERWARE_UNIT_SOURCE_CONFLICT');end if; 
  -- Guard checks OLD source binding; update keeps birth provenance and every code unchanged. 
  RRL_STOCK_CTX_API.begin_effect('UNIT',p_uid,p_source_cell); 
  update RRL_WMS_RECEIPT_UNIT set CURRENT_CELL=p_target_cell,STOCK_STATUS='AVAILABLE',HARD_RESERVATION_ID=null,UNIT_VERSION=UNIT_VERSION+1 
   where CURRENT_UID=p_uid and CURRENT_CELL=p_source_cell and STOCK_STATUS='ISSUED'; 
  if sql%rowcount!=expected_count then raise_application_error(-20890,'CLOSURE_CHANGED: interware unit count');end if; 
  RRL_STOCK_CTX_API.end_effect;assert_composition(p_uid,p_target_cell); 
 exception when others then RRL_STOCK_CTX_API.end_effect;raise; 
 end; 
 procedure receive_return(p_old_uid varchar2,p_source_cell varchar2,p_uid varchar2,p_target_cell varchar2,p_qty number,p_units clob)is 
  op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');n number;expected_count number;actual_count number:=0;total number:=0;locked_version number; 
 begin 
  require_context;RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_old_uid));RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid)); 
  select count(*)into n from RRL_STOCK_OPERATION o join json_table(o.RESOLVED_PLAN_JSON,'$.domain'columns(O varchar2(150)path '$.original_lot_uid',U varchar2(150)path '$.uid',S varchar2(60)path '$.return_source_cell',T varchar2(60)path '$.receive_cell',Q varchar2(60)path '$.quantity',A clob format json path '$.return_unit_proof.units'))d 
   on d.O=p_old_uid and d.U=p_uid and d.S=p_source_cell and d.T=p_target_cell and d.Q=RRL_STOCK_PLAN_HELPER.decimal_text(p_qty)and dbms_lob.compare(d.A,p_units)=0 
   where o.OPERATION_ID=op and o.COMMAND_TYPE='STORE_RETURN_RECEIVE'and o.STATE='IN_FLIGHT'; 
  if n!=1 then raise_application_error(-20863,'STORE_RETURN_EXACT_UNIT_RECEIPT_PLAN_REQUIRED');end if; 
  select count(*),count(distinct K)into expected_count,n from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key')); 
  if expected_count<1 or expected_count>10000 or n!=expected_count then raise_application_error(-20884,'STORE_RETURN_EXACT_UNIT_SET_REQUIRED');end if; 
  for x in(select u.PHYSICAL_UNIT_KEY,u.UNIT_VERSION,u.STOCK_STATUS,u.HARD_RESERVATION_ID,u.BASE_QTY,u.BASE_UOM,j.V,j.Q,j.B 
   from RRL_WMS_RECEIPT_UNIT u join json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key',V number path '$.version',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))j on j.K=u.PHYSICAL_UNIT_KEY 
   where u.CURRENT_UID=p_old_uid and u.CURRENT_CELL=p_source_cell order by u.PHYSICAL_UNIT_KEY)loop 
   own_unit(x.PHYSICAL_UNIT_KEY); 
   select UNIT_VERSION into locked_version from RRL_WMS_RECEIPT_UNIT where PHYSICAL_UNIT_KEY=x.PHYSICAL_UNIT_KEY for update; 
   if locked_version!=x.V or x.UNIT_VERSION!=x.V or x.STOCK_STATUS!='ISSUED'or x.HARD_RESERVATION_ID is not null or x.BASE_QTY!=RRL_STOCK_MATH.quantity(x.Q)or x.BASE_UOM!=x.B then raise_application_error(-20890,'CLOSURE_CHANGED: original return unit');end if; 
   actual_count:=actual_count+1;total:=total+x.BASE_QTY; 
  end loop; 
  if actual_count!=expected_count or total!=p_qty then raise_application_error(-20884,'STORE_RETURN_ORIGINAL_UNIT_QUANTITY_CONFLICT');end if; 
  RRL_STOCK_CTX_API.begin_effect('UNIT',p_old_uid,p_source_cell); 
  update RRL_WMS_RECEIPT_UNIT u set CURRENT_UID=p_uid,CURRENT_CELL=p_target_cell,STOCK_STATUS='AVAILABLE',HARD_RESERVATION_ID=null,UNIT_VERSION=UNIT_VERSION+1 
   where CURRENT_UID=p_old_uid and CURRENT_CELL=p_source_cell and STOCK_STATUS='ISSUED'and exists(select 1 from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key'))j where j.K=u.PHYSICAL_UNIT_KEY); 
  if sql%rowcount!=expected_count then raise_application_error(-20890,'CLOSURE_CHANGED: original returned unit count');end if; 
  RRL_STOCK_CTX_API.end_effect;assert_composition(p_uid,p_target_cell);assert_composition(p_old_uid,p_source_cell); 
 exception when others then RRL_STOCK_CTX_API.end_effect;raise; 
 end; procedure receive_partial_issued(p_old_uid varchar2,p_source_cell varchar2,p_uid varchar2,p_target_cell varchar2,p_qty number,p_units clob)is 
  op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');n number;expected_count number;actual_count number:=0;total number:=0;locked_version number; 
 begin 
  require_context;RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_old_uid));RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid)); 
  select count(*)into n from RRL_STOCK_OPERATION o join json_table(o.RESOLVED_PLAN_JSON,'$.domain'columns(O varchar2(150)path '$.original_root_uid',U varchar2(150)path '$.uid',S varchar2(60)path '$.source_cell',T varchar2(60)path '$.receive_cell',Q varchar2(60)path '$.quantity',A clob format json path '$.source_units'))d 
   on d.O=p_old_uid and d.U=p_uid and d.S=p_source_cell and d.T=p_target_cell and d.Q=RRL_STOCK_PLAN_HELPER.decimal_text(p_qty)and dbms_lob.compare(d.A,p_units)=0 
   where o.OPERATION_ID=op and o.COMMAND_TYPE in('INTERWARE_RECEIVE','INTERWARE_SHORTAGE_RECOVER')and json_value(o.RESOLVED_PLAN_JSON,'$.domain.partial_receipt')='true'and o.STATE='IN_FLIGHT'; 
  if n!=1 then raise_application_error(-20863,'INTERWARE_PARTIAL_EXACT_UNIT_RECEIPT_PLAN_REQUIRED');end if; 
  select count(*),count(distinct K)into expected_count,n from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key')); 
  if expected_count<1 or expected_count>10000 or n!=expected_count then raise_application_error(-20884,'INTERWARE_PARTIAL_EXACT_UNIT_SET_REQUIRED');end if; 
  for x in(select u.PHYSICAL_UNIT_KEY,u.UNIT_VERSION,u.STOCK_STATUS,u.HARD_RESERVATION_ID,u.BASE_QTY,u.BASE_UOM,j.V,j.Q,j.B 
   from RRL_WMS_RECEIPT_UNIT u join json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key',V number path '$.version',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom'))j on j.K=u.PHYSICAL_UNIT_KEY 
   where u.CURRENT_UID=p_old_uid and u.CURRENT_CELL=p_source_cell order by u.PHYSICAL_UNIT_KEY)loop 
   own_unit(x.PHYSICAL_UNIT_KEY); 
   select UNIT_VERSION into locked_version from RRL_WMS_RECEIPT_UNIT where PHYSICAL_UNIT_KEY=x.PHYSICAL_UNIT_KEY for update; 
   if locked_version!=x.V or x.UNIT_VERSION!=x.V or x.STOCK_STATUS!='ISSUED'or x.HARD_RESERVATION_ID is not null or x.BASE_QTY!=RRL_STOCK_MATH.quantity(x.Q)or x.BASE_UOM!=x.B then raise_application_error(-20890,'CLOSURE_CHANGED: partial interware unit');end if; 
   actual_count:=actual_count+1;total:=total+x.BASE_QTY; 
  end loop; 
  if actual_count!=expected_count or total!=p_qty then raise_application_error(-20884,'INTERWARE_PARTIAL_ORIGINAL_UNIT_QUANTITY_CONFLICT');end if; 
  RRL_STOCK_CTX_API.begin_effect('UNIT',p_old_uid,p_source_cell); 
  update RRL_WMS_RECEIPT_UNIT u set CURRENT_UID=p_uid,CURRENT_CELL=p_target_cell,STOCK_STATUS='AVAILABLE',HARD_RESERVATION_ID=null,UNIT_VERSION=UNIT_VERSION+1 
   where CURRENT_UID=p_old_uid and CURRENT_CELL=p_source_cell and STOCK_STATUS='ISSUED'and exists(select 1 from json_table(p_units,'$[*]'columns(K varchar2(64)path '$.key'))j where j.K=u.PHYSICAL_UNIT_KEY); 
  if sql%rowcount!=expected_count then raise_application_error(-20890,'CLOSURE_CHANGED: partial interwareed unit count');end if; 
  RRL_STOCK_CTX_API.end_effect;assert_composition(p_uid,p_target_cell);assert_composition(p_old_uid,p_source_cell); 
 exception when others then RRL_STOCK_CTX_API.end_effect;raise; 
 end; 
end;
/


CREATE OR REPLACE package body RRL_STOCK_UNLOAD_CMD as
 procedure assert_scope(p_load varchar2,p_actor varchar2)is n number;
 begin
  select count(*)into n from RRL_TT_HU_LOAD_FACT lf join RUSERS u on u.ID=p_actor
   where lf.LOAD_OPERATION_ID=p_load and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'stock_posting_shipping')=1
    and(upper(trim(u.USER_GROUP))='GLOBAL_ADMIN'or u.WARE_ID=lf.WARE_ID);
  if n!=1 then raise_application_error(-20882,'UNLOAD_CURRENT_WARE_ACTOR_REQUIRED');end if;
 end;
 function issued_units(p_load varchar2,p_uid varchar2,p_cell varchar2,p_qty number)return clob is
  wire clob;expected_sig varchar2(64);sig varchar2(64);a json_array_t:=json_array_t();plain json_array_t:=json_array_t();x json_object_t;j json_object_t:=json_object_t();n number:=0;total number:=0;original_count number;
 begin
  select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=p_load;
  select count(*),max(S)into original_count,expected_sig from json_table(wire,'$.physical_before[*]'columns(U varchar2(150)path '$.uid',S varchar2(64)path '$.unit_signature'))where U=p_uid;
  if original_count!=1 or expected_sig is null then raise_application_error(-20884,'UNLOAD_ORIGINAL_UNIT_PROOF_REQUIRED');end if;
  for u in(select PHYSICAL_UNIT_KEY,BASE_QTY,BASE_UOM,UNIT_VERSION,STOCK_STATUS,HARD_RESERVATION_ID from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=p_uid and CURRENT_CELL=p_cell order by PHYSICAL_UNIT_KEY fetch first 10001 rows only)loop
   n:=n+1;if n>10000 or u.PHYSICAL_UNIT_KEY is null or u.BASE_QTY<=0 or u.BASE_UOM is null or u.UNIT_VERSION is null or u.STOCK_STATUS!='ISSUED'or u.HARD_RESERVATION_ID is not null then raise_application_error(-20884,'UNLOAD_EXACT_ORIGINAL_ISSUED_SET_REQUIRED');end if;
   x:=json_object_t();x.put('key',u.PHYSICAL_UNIT_KEY);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY));x.put('base_uom',u.BASE_UOM);plain.append(x.clone());x.put('version',u.UNIT_VERSION);a.append(x);total:=total+u.BASE_QTY;
  end loop;
  j.put('units',plain);sig:=rawtohex(sys.dbms_crypto.hash(j.to_clob,sys.dbms_crypto.hash_sh256));
  if sig!=expected_sig or(n>0 and total!=p_qty)then raise_application_error(-20884,'UNLOAD_ORIGINAL_UNIT_FINGERPRINT_CONFLICT');end if;
  if n=0 then
   select count(*)into n from RRL_PALLETS p where p.UID_PALLET=p_uid and(exists(select 1 from RRL_SKU_RECEIPT_POLICY sp where sp.ARTICUL=p.ARTICUL and(sp.MARKING_REQUIRED=1 or sp.SERIALIZED_WEIGHT_BOXES=1))or exists(select 1 from RRL_SKU_RECEIPT_PROFILE profile where profile.ARTICUL=p.ARTICUL)or exists(select 1 from RRL_FINISHED_GOODS_SKU fg where fg.ARTICUL=p.ARTICUL and fg.CRPT_REQUIRED=1));
   if n>0 then raise_application_error(-20884,'UNLOAD_ORIGINAL_MARKED_CAPTURE_REQUIRED');end if;
  end if;
  return a.to_clob;
 end;
 function held_recovery(p_load varchar2,p_book varchar2)return number is
  original RRL_TARE_BOOK%rowtype;current_book RRL_TARE_BOOK%rowtype;proof RRL_TARE_LOAD_RECOVERY%rowtype;next_book varchar2(100);seen varchar2(4000):='|';n number;
 begin
  select *into original from RRL_TARE_BOOK where OPERATION_ID=p_book;
  if original.STATUS!='TRANSFERRED'then return 0;end if;current_book:=original;
  for depth in 0..16 loop
   if instr(seen,'|'||current_book.OPERATION_ID||'|')>0 then raise_application_error(-20886,'UNLOAD_TARE_RECOVERY_CYCLE');end if;
   seen:=seen||current_book.OPERATION_ID||'|';
   if current_book.OWNER_WARE_ID!=original.OWNER_WARE_ID or current_book.PALLET_TYPE_ID!=original.PALLET_TYPE_ID or current_book.PLACE_KIND!=original.PLACE_KIND or current_book.PLACE_ID!=original.PLACE_ID or current_book.BALANCE_KEY!=original.BALANCE_KEY or current_book.QUANTITY!=1 then raise_application_error(-20886,'UNLOAD_TARE_RECOVERY_LINEAGE_CONFLICT');end if;
   if current_book.STATUS='HELD'then return 1;end if;
   if current_book.STATUS!='TRANSFERRED'then return 0;end if;
   if depth=16 then raise_application_error(-20881,'UNLOAD_TARE_RECOVERY_DEPTH_16');end if;
   select *into proof from RRL_TARE_LOAD_RECOVERY where ORIGINAL_BOOK_OPERATION_ID=current_book.OPERATION_ID;
   if proof.LOAD_OPERATION_ID!=p_load or proof.WARE_ID!=original.OWNER_WARE_ID or proof.PALLET_TYPE_ID!=original.PALLET_TYPE_ID
    or(original.PLACE_KIND='CASE'and(proof.CASE_PICK_TASK_ID is null or RRL_STOCK_PLAN_HELPER.decimal_text(proof.CASE_PICK_TASK_ID)!=original.PLACE_ID or proof.ROOT_UID is not null))
    or(original.PLACE_KIND='HU'and(proof.ROOT_UID is null or proof.ROOT_UID!=original.PLACE_ID or proof.CASE_PICK_TASK_ID is not null))then raise_application_error(-20886,'UNLOAD_TARE_RECOVERY_ORIGINAL_LOAD_REQUIRED');end if;
   select count(*)into n from RRL_TARE_ACCEPT a join RRL_TARE_OFFER_BOOK ob on ob.OFFER_OPERATION_ID=a.OFFER_OPERATION_ID where a.OPERATION_ID=current_book.CLOSED_OPERATION_ID and ob.BOOK_OPERATION_ID=current_book.OPERATION_ID and ob.LOAD_OPERATION_ID=p_load and a.ACCEPTED_QTY=1 and a.SHORT_QTY=0;
   if n!=1 then raise_application_error(-20886,'UNLOAD_TARE_RECOVERY_ORIGINAL_ACCEPT_REQUIRED');end if;
   next_book:=proof.OPERATION_ID;select *into current_book from RRL_TARE_BOOK where OPERATION_ID=next_book;
  end loop;
  return 0;
 exception when no_data_found then return 0;end;
 procedure source_state(p_load varchar2,p_metadata json_object_t,p_lf out RRL_TT_HU_LOAD_FACT%rowtype,p_domain out json_object_t)is
  wire clob;kind_name varchar2(80);state_name varchar2(20);ct RRL_CASE_PICK_TASK%rowtype;tree json_object_t;root_node json_object_t;n number;trip RRL_TRANSPORT_TASK%rowtype;cell_ware number;blocked number;cell_text varchar2(60);
  original json_object_t;plans json_array_t;sub json_object_t;members json_array_t:=json_array_t();legs json_array_t:=json_array_t();a json_array_t;x json_object_t;y json_object_t;uid_text varchar2(150);version_no number;shipped_op varchar2(100);current_cell varchar2(60);case_value number;old_link_id number;parent_value varchar2(150);child_value varchar2(200);expected_link_version number;sid number;physical_uid varchar2(150);wave_value number;full_task number;physical_total number;held_total number;
 begin
  select *into p_lf from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=p_load;
  if p_lf.STATUS!='LOADED'or p_lf.DEPARTURE_OPERATION_ID is not null or p_lf.DEPARTED_AT is not null or p_lf.CUSTODY_RELEASE_OPERATION_ID is not null then raise_application_error(-20886,'UNLOAD_PREDEPARTURE_LOADED_REQUIRED');end if;
  select COMMAND_TYPE,STATE,RESOLVED_PLAN_JSON into kind_name,state_name,wire from RRL_STOCK_OPERATION where OPERATION_ID=p_load;
  if state_name!='APPLIED'or kind_name not in('LOAD_SHIPMENT','HU_SHIP')then raise_application_error(-20886,'UNLOAD_NATIVE_ORIGINAL_LOAD_REQUIRED');end if;
  original:=json_object_t.parse(wire).get_object('domain');tree:=json_object_t.parse(p_lf.COMPOSITION_JSON);root_node:=treat(tree.get_array('nodes').get(0)as json_object_t);
  if tree.get_array('ancestors').get_size!=0 then raise_application_error(-20886,'UNLOAD_WHOLE_TOP_PLACE_REQUIRED');end if;
  plans:=json_array_t();
  if kind_name='LOAD_SHIPMENT'and p_lf.ROOT_CASE_TASK_ID is not null and p_lf.ROOT_UID is null and root_node.get_string('kind')='CASE'then plans.append(original.get_object('shipment'));
  elsif kind_name='LOAD_SHIPMENT'and p_lf.ROOT_CASE_TASK_ID is null and p_lf.ROOT_UID is not null and root_node.get_string('kind')='STOCK'then plans.append(original.get_object('shipment'));
  elsif kind_name='HU_SHIP'and p_lf.ROOT_UID is not null and p_lf.ROOT_CASE_TASK_ID is null and root_node.get_string('kind')='CONTAINER'then plans:=original.get_array('shipments');
  else raise_application_error(-20886,'UNLOAD_CASE_OR_CASE_HU_REQUIRED');end if;
  if plans.get_size<1 or plans.get_size>200 then raise_application_error(-20881,'UNLOAD_MEMBER_BOUND_1_200');end if;
  for i in 0..plans.get_size-1 loop
   sub:=treat(plans.get(i)as json_object_t).get_object('domain');
   if sub.has('interwarehouse_onward_source')or sub.has('supplier_return_source')then raise_application_error(-20886,'UNLOAD_SPECIAL_CUSTODY_DECISION_REQUIRED');end if;
   if sub.get_number('case_task')is not null then
   case_value:=sub.get_number('case_task');select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=case_value;
   if ct.STATUS!='SHIPPED'or ct.SHIPPED_OPERATION!=p_load or ct.WARE_ID!=p_lf.WARE_ID or ct.CONTENT_VERSION!=sub.get_number('case_version')+1 then raise_application_error(-20886,'UNLOAD_ORIGINAL_CASE_STATE_REQUIRED');end if;
   select count(*)into n from RRL_PICK_WAVE where PICK_WAVE_ID=ct.PICK_WAVE_ID and STATUS='LAUNCHED';
   if n!=1 then raise_application_error(-20886,'UNLOAD_ACTIVE_CASE_WAVE_REQUIRED');end if;
   select count(*)into n from RRL_TT_HU_LOAD_ST where LOAD_OPERATION_ID=p_load and ACTIVE_FLAG=1 and SBORKA_PALLET_ID=ct.LEGACY_SBORKA_PALLET_ID;
   if n!=1 or ct.LEGACY_SBORKA_PALLET_ID!=sub.get_number('document_id')then raise_application_error(-20886,'UNLOAD_ORIGINAL_ACTIVE_ST_REQUIRED');end if;
   x:=json_object_t();x.put('case_id',ct.CASE_PICK_TASK_ID);x.put('shipment_id',ct.LEGACY_SBORKA_PALLET_ID);x.put('case_version',ct.CONTENT_VERSION);x.put_null('physical_uid');members.append(x);
   else
    physical_uid:=sub.get_string('bound_physical_uid');sid:=sub.get_number('document_id');
    if physical_uid is null or sub.get_number('bound_stock_version')is null then raise_application_error(-20886,'UNLOAD_ORIGINAL_BOUND_FULLPAL_REQUIRED');end if;
    select nvl(sum(REMAIN),0),nvl(sum(HARD_RESERVED_BASE),0)into physical_total,held_total from RRL_REMAINS where UID_POLETA=physical_uid;
    if physical_total!=0 or held_total!=0 then raise_application_error(-20886,'UNLOAD_WHOLE_ORIGINAL_FULLPAL_NOT_EMPTY');end if;
    select count(*),max(PICKED_WAREHOUSE_TASK_ID)into n,full_task from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=sid and STATUS='SHIPPED'and SHIPPED_OPERATION_ID=p_load and PICKED_CASE_TASK_ID is null and PICKED_PALLET_UID=physical_uid;
    if n!=1 or full_task is null then raise_application_error(-20886,'UNLOAD_ORIGINAL_FULLPAL_FULFILLMENT_REQUIRED');end if;
    select count(*)into n from RRL_WAREHOUSE_TASK where TASK_ID=full_task and STATUS='DONE'and TASK_TYPE='PICKING_MOVE'and UID_PALLET=physical_uid and TO_WARE_ID=p_lf.WARE_ID;
    if n!=1 then raise_application_error(-20886,'UNLOAD_ORIGINAL_FULLPAL_COMPLETED_TASK_REQUIRED');end if;
    a:=sub.get_array('legs');
    if a.get_size!=1 then raise_application_error(-20886,'UNLOAD_WHOLE_SINGLE_FULLPAL_LEAF_REQUIRED');end if;
    y:=treat(a.get(0)as json_object_t);wave_value:=y.get_number('owner_id');
    if y.get_string('uid')!=physical_uid or y.get_string('owner_type')!='PICK_WAVE'then raise_application_error(-20886,'UNLOAD_ORIGINAL_FULLPAL_WAVE_OWNER_REQUIRED');end if;
    select count(*)into n from RRL_PICK_WAVE where PICK_WAVE_ID=wave_value and STATUS='LAUNCHED';
    if n!=1 then raise_application_error(-20886,'UNLOAD_ACTIVE_FULLPAL_WAVE_REQUIRED');end if;
    select count(*)into n from RRL_TT_HU_LOAD_ST where LOAD_OPERATION_ID=p_load and ACTIVE_FLAG=1 and SBORKA_PALLET_ID=sid;
    if n!=1 then raise_application_error(-20886,'UNLOAD_ORIGINAL_ACTIVE_ST_REQUIRED');end if;
    x:=json_object_t();x.put_null('case_id');x.put('shipment_id',sid);x.put_null('case_version');x.put('physical_uid',physical_uid);x.put('wave_id',wave_value);x.put('fullpal_task_id',full_task);members.append(x);
   end if;
   a:=sub.get_array('legs');for k in 0..a.get_size-1 loop legs.append(a.get(k));end loop;
  end loop;
  select count(*)into n from RRL_TT_HU_LOAD_ST where LOAD_OPERATION_ID=p_load and ACTIVE_FLAG=1;
  if n!=members.get_size then raise_application_error(-20886,'UNLOAD_ALL_ORIGINAL_MEMBERS_REQUIRED');end if;
  if p_metadata.get_number('expected_version')is null or p_metadata.get_number('expected_version')!=p_lf.CONTENT_VERSION
   or p_metadata.get_string('scan_container')is null or(p_metadata.get_string('scan_container')!=root_node.get_string('uid')and(root_node.get_string('sscc')is null or p_metadata.get_string('scan_container')!=root_node.get_string('sscc')))
   or p_metadata.get_string('scan_cell')is null or p_metadata.get_string('scan_cell')!=tree.get_string('cell')
   or p_metadata.get_string('scan_vehicle')is null or p_metadata.get_string('scan_vehicle')!=p_lf.VEHICLE_NUMBER
   or p_metadata.get_string('scan_dock')is null or p_metadata.get_string('scan_dock')!=p_lf.DOCK
   or trim(p_metadata.get_string('reason'))is null or length(p_metadata.get_string('reason'))>1000 then raise_application_error(-20886,'UNLOAD_ORIGINAL_PLACE_VEHICLE_DOCK_CELL_SCAN_REQUIRED');end if;
  select *into trip from RRL_TRANSPORT_TASK where ID=p_lf.TT_ID;
  if trip.CONDITION='Отгружен'or nvl(trip.DELETED,0)!=0 or nvl(trip.PAY_ORDER_ID,0)!=0 or trip.TRANSPORT!=p_lf.VEHICLE_NUMBER or trip.DOCK!=p_lf.DOCK then raise_application_error(-20886,'UNLOAD_CURRENT_UNDEPARTED_TRIP_REQUIRED');end if;
  cell_text:=tree.get_string('cell');
  select WARE_ID,nvl(BLOCKED_FOR_REMAINS,0)into cell_ware,blocked from RRL_CELLS where CELL=cell_text;
  if cell_ware!=p_lf.WARE_ID or blocked!=0 then raise_application_error(-20886,'UNLOAD_ORIGINAL_CELL_CURRENTLY_BLOCKED');end if;
  n:=0;
  for old_offer in(select ob.BOOK_OPERATION_ID,c.OPERATION_ID CANCEL_ID from RRL_TARE_OFFER_BOOK ob left join RRL_TARE_OFFER_CANCEL c on c.OFFER_OPERATION_ID=ob.OFFER_OPERATION_ID where ob.LOAD_OPERATION_ID=p_load order by ob.OFFER_OPERATION_ID,ob.BOOK_OPERATION_ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20881,'UNLOAD_TARE_ASSOCIATION_BOUND_200');end if;
   if old_offer.CANCEL_ID is null and held_recovery(p_load,old_offer.BOOK_OPERATION_ID)!=1 then raise_application_error(-20886,'UNLOAD_TARE_HANDOVER_DECISION_REQUIRED');end if;
  end loop;
  select count(*)into n from RRL_TOPOLOGY_CELL_SLOT sl join RRL_TOPOLOGY_CELL tc on tc.TOPOLOGY_CELL_ID=sl.TOPOLOGY_CELL_ID
   where tc.LEGACY_CELL_CODE=cell_text and tc.WARE_ID=p_lf.WARE_ID and tc.ACTIVE=1 and sl.ACTIVE=1 and sl.SLOT_KIND='STORAGE_SLOT'
    and tc.TOPOLOGY_ID=(select max(TOPOLOGY_ID)from RRL_WAREHOUSE_TOPOLOGY where WARE_ID=p_lf.WARE_ID and STATUS='PUBLISHED');
  if n=0 then select count(*)into n from RRL_CELLS where CELL=cell_text and(nvl(LIMIT_WEIGHT,0)>0 or nvl(LIMIT_HEIGHT,0)>0);end if;
  if n>0 and p_metadata.get_number('target_slot_id')is null then raise_application_error(-20886,'UNLOAD_STORAGE_SLOT_PLACEMENT_REQUIRED');end if;
  if kind_name='HU_SHIP'then
   a:=tree.get_array('nodes');
   for i in 0..a.get_size-1 loop
    x:=treat(a.get(i)as json_object_t);uid_text:=x.get_string('uid');
    if x.get_string('kind')='CONTAINER'then
     select HU_CONTENT_VERSION,HU_SHIPPED_OPERATION,HU_CURRENT_CELL into version_no,shipped_op,current_cell from RRL_PALLETS where UID_PALLET=uid_text and HU_KIND='CONTAINER';
     if version_no!=x.get_number('version')+1 or shipped_op!=p_load or current_cell is not null then raise_application_error(-20886,'UNLOAD_ORIGINAL_CONTAINER_EPOCH_REQUIRED');end if;
    end if;
    case_value:=x.get_number('case_task_id');select count(*)into n from RRL_WMS_HU_LINK where ACTIVE_FLAG=1 and(PARENT_UID=uid_text or CHILD_PALLET_UID=uid_text or CHILD_CASE_TASK_ID=case_value);
    if n>0 then raise_application_error(-20886,'UNLOAD_ORIGINAL_TREE_ALREADY_REUSED');end if;
   end loop;
   a:=tree.get_array('links');
   for i in 0..a.get_size-1 loop
    x:=treat(a.get(i)as json_object_t);
    if x.get_number('id')is not null then
     old_link_id:=x.get_number('id');parent_value:=x.get_string('parent');child_value:=x.get_string('child');expected_link_version:=x.get_number('version');
     select count(*)into n from RRL_WMS_HU_LINK where HU_LINK_ID=old_link_id and PARENT_UID=parent_value and ACTIVE_FLAG=0 and UNLINKED_OPERATION_ID=p_load and LINK_VERSION=expected_link_version+1 and nvl(CHILD_PALLET_UID,'CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(CHILD_CASE_TASK_ID))=child_value;
     if n!=1 then raise_application_error(-20886,'UNLOAD_ORIGINAL_LINK_HISTORY_REQUIRED');end if;
    end if;
   end loop;
  end if;
  p_domain:=json_object_t();p_domain.put('members',members);p_domain.put('legs',legs);
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');v json_object_t:=json_object_t();sd json_object_t;
  lf RRL_TT_HU_LOAD_FACT%rowtype;legs json_array_t;restored json_array_t:=json_array_t();x json_object_t;y json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();load_id varchar2(100):=d.get_object('source').get_string('load_operation_id');
  uid_text varchar2(150);cell_text varchar2(60);qty number;physical number;held number;version_no number;new_res number;article_text varchar2(160);n number;signed_total number;sid number;case_id number;unit_wire clob;unit_array json_array_t;unit_obj json_object_t;members json_array_t;tree json_object_t;nodes json_array_t;links json_array_t;recover_links json_array_t:=json_array_t();new_link number;physical_uid varchar2(150);full_task number;wave_value number;actual_article varchar2(160);actual_uom varchar2(20);target_slot number;placement_task number;placement_sync number;request_wire clob;original_measures json_object_t;slot_code varchar2(100);
 begin
  assert_scope(load_id,d.get_string('actor'));source_state(load_id,m,lf,sd);legs:=sd.get_array('legs');case_id:=lf.ROOT_CASE_TASK_ID;members:=sd.get_array('members');tree:=json_object_t.parse(lf.COMPOSITION_JSON);
  if legs.get_size<1 or legs.get_size>200 then raise_application_error(-20881,'UNLOAD_LEG_BOUND_1_200');end if;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','UNLOAD.LOAD:'||load_id);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(lf.TT_ID));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',load_id);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_UNLOAD_FACT',p_operation);
  for member_index in 0..members.get_size-1 loop
   x:=treat(members.get(member_index)as json_object_t);sid:=x.get_number('shipment_id');case_id:=x.get_number('case_id');physical_uid:=x.get_string('physical_uid');
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_ST',load_id||':'||RRL_STOCK_PLAN_HELPER.decimal_text(sid));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(sid));
   if case_id is not null then
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(case_id));
    select PICK_WAVE_ID into wave_value from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=case_id;
   else
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('fullpal_task_id')));
    wave_value:=x.get_number('wave_id');
   end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(wave_value));
   n:=0;
   for ff in(select FULFILLMENT_ID,CUSTOMER_ORDER_ID,PICKED_CASE_TASK_ID,PICKED_PALLET_UID from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=sid and STATUS='SHIPPED'and SHIPPED_OPERATION_ID=load_id order by FULFILLMENT_ID)loop
    n:=n+1;if n>1 or nvl(ff.PICKED_CASE_TASK_ID,-1)!=nvl(case_id,-1)or(case_id is null and ff.PICKED_PALLET_UID!=physical_uid)then raise_application_error(-20886,'UNLOAD_ORIGINAL_FULFILLMENT_REQUIRED');end if;
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(ff.FULFILLMENT_ID));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(ff.CUSTOMER_ORDER_ID));
   end loop;
   if n!=1 then raise_application_error(-20886,'UNLOAD_ORIGINAL_FULFILLMENT_REQUIRED');end if;
  end loop;
  for association in(select ob.OFFER_OPERATION_ID,c.OPERATION_ID CANCEL_ID from RRL_TARE_OFFER_BOOK ob left join RRL_TARE_OFFER_CANCEL c on c.OFFER_OPERATION_ID=ob.OFFER_OPERATION_ID where ob.LOAD_OPERATION_ID=load_id order by ob.OFFER_OPERATION_ID)loop
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER',association.OFFER_OPERATION_ID);
   if association.CANCEL_ID is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER_CANCEL',association.CANCEL_ID);end if;
  end loop;
  for proof in(select OPERATION_ID,ORIGINAL_BOOK_OPERATION_ID,RETURN_OFFER_OPERATION_ID,RETURN_ACCEPT_OPERATION_ID from RRL_TARE_LOAD_RECOVERY where LOAD_OPERATION_ID=load_id order by OPERATION_ID)loop
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_LOAD_RECOVERY',proof.OPERATION_ID);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BOOK',proof.ORIGINAL_BOOK_OPERATION_ID);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER',proof.RETURN_OFFER_OPERATION_ID);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_ACCEPT',proof.RETURN_ACCEPT_OPERATION_ID);
  end loop;
  nodes:=tree.get_array('nodes');
  for node_index in 0..nodes.get_size-1 loop
   x:=treat(nodes.get(node_index)as json_object_t);uid_text:=x.get_string('uid');
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',uid_text);
   if x.get_string('kind')='CONTAINER'then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PALLETS',uid_text);end if;
   for book in(select OPERATION_ID,BALANCE_KEY,OWNER_WARE_ID from RRL_TARE_BOOK where STATUS='HELD'and((PLACE_KIND='HU'and PLACE_ID=uid_text)or(PLACE_KIND='CASE'and 'CASE:'||PLACE_ID=uid_text)))loop
    if book.OWNER_WARE_ID!=lf.WARE_ID then raise_application_error(-20886,'UNLOAD_TARE_BOOK_WARE_CONFLICT');end if;
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BOOK',book.OPERATION_ID);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BALANCE',rawtohex(book.BALANCE_KEY));
   end loop;
  end loop;
  links:=tree.get_array('links');
  for link_index in 0..links.get_size-1 loop
   x:=treat(links.get(link_index)as json_object_t);
   if x.get_number('id')is not null then
    select RRL_WMS_HU_LINK_SQ.nextval into new_link from dual;
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WMS_HU_LINK',RRL_STOCK_PLAN_HELPER.decimal_text(new_link));
    y:=x.clone();y.put('new_id',new_link);recover_links.append(y);
   end if;
  end loop;
  target_slot:=m.get_number('target_slot_id');
  if target_slot is not null then
   if target_slot<1 or target_slot!=trunc(target_slot)or m.get_string('scanned_to_slot_code')is null then raise_application_error(-20886,'UNLOAD_SLOT_SCAN_REQUIRED');end if;
   cell_text:=m.get_string('scan_cell');select sl.SLOT_CODE into slot_code from RRL_TOPOLOGY_CELL_SLOT sl join RRL_TOPOLOGY_CELL tc on tc.TOPOLOGY_CELL_ID=sl.TOPOLOGY_CELL_ID
    where sl.CELL_SLOT_ID=target_slot and sl.ACTIVE=1 and sl.SLOT_KIND='STORAGE_SLOT'and tc.ACTIVE=1 and tc.LEGACY_CELL_CODE=cell_text and tc.WARE_ID=lf.WARE_ID and tc.TOPOLOGY_ID=(select max(TOPOLOGY_ID)from RRL_WAREHOUSE_TOPOLOGY where WARE_ID=lf.WARE_ID and STATUS='PUBLISHED');
   if slot_code!=m.get_string('scanned_to_slot_code')then raise_application_error(-20886,'UNLOAD_SLOT_SCAN_REQUIRED');end if;
   select CANONICAL_REQUEST into request_wire from RRL_STOCK_OPERATION where OPERATION_ID=load_id;
   original_measures:=json_object_t.parse(request_wire).get_object('metadata').get_object('loading_context').get_object('measurements');
   RRL_STOCK_PLAN_HELPER.fence(f,'CELL',m.get_string('scan_cell'),6);
   RRL_STOCK_PLAN_HELPER.anchor(r,40,'SLOT',RRL_STOCK_PLAN_HELPER.decimal_text(target_slot));
   placement_task:=RRL_WAREHOUSE_TASK_SQ.nextval;placement_sync:=RRL_WH_TASK_SYNC_SQ.nextval;
   RRL_STOCK_HU_PLACEMENT_CORE.declare_place(r,placement_task,placement_sync);
   v.put('placement_slot',target_slot);v.put('placement_task',placement_task);v.put('placement_sync',placement_sync);v.put('original_measures',original_measures);
  elsif m.get_string('scanned_to_slot_code')is not null then raise_application_error(-20886,'UNLOAD_SLOT_SCAN_REQUIRED');end if;
  for i in 0..legs.get_size-1 loop
   x:=treat(legs.get(i)as json_object_t);uid_text:=x.get_string('uid');cell_text:=x.get_string('cell');qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));
   if cell_text!=m.get_string('scan_cell')or x.get_number('reservation_id')is null then raise_application_error(-20886,'UNLOAD_ORIGINAL_RESERVED_CASE_LEAF_REQUIRED');end if;
   select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION into physical,held,version_no from RRL_REMAINS where UID_POLETA=uid_text and CELL=cell_text;
   if physical!=0 or held!=0 then raise_application_error(-20886,'UNLOAD_ORIGINAL_LEAF_NOT_EMPTY');end if;
   select p.ARTICUL,rem.BASE_UOM into actual_article,actual_uom from RRL_PALLETS p join RRL_REMAINS rem on rem.UID_POLETA=p.UID_PALLET where p.UID_PALLET=uid_text and rem.CELL=cell_text;
   if actual_article!=x.get_string('article')or actual_uom!=x.get_string('base_uom')then raise_application_error(-20886,'UNLOAD_ORIGINAL_ARTICLE_UOM_REQUIRED');end if;
   unit_wire:=issued_units(load_id,uid_text,cell_text,qty);unit_array:=json_array_t.parse(unit_wire);
   if unit_array.get_size>0 then
    for unit_index in 0..unit_array.get_size-1 loop
     unit_obj:=treat(unit_array.get(unit_index)as json_object_t);RRL_STOCK_PLAN_HELPER.anchor(r,60,'UNIT',unit_obj.get_string('key'));
    end loop;
   end if;
   select nvl(sum(BASE_QTY),0)into signed_total from RRL_EVENTS where OPERATION_ID=load_id and UID_POLETA=uid_text;
   if signed_total!=-qty then raise_application_error(-20886,'UNLOAD_ORIGINAL_SIGNED_SHIP_JOURNAL_REQUIRED');end if;
   select RRL_STOCK_RESERVATION_SQ.nextval into new_res from dual;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(new_res));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('reservation_id')));
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,uid_text,x.get_string('article'),cell_text,cell_text);
   y:=x.clone();y.put('restored_units',unit_array);y.put('new_reservation',new_res);y.put('current_stock_version',version_no);restored.append(y);
  end loop;
  v.put('load_id',load_id);v.put('trip_id',lf.TT_ID);v.put('case_id',lf.ROOT_CASE_TASK_ID);v.put('root_uid',lf.ROOT_UID);v.put('members',members);v.put('recover_links',recover_links);v.put('warehouse',lf.WARE_ID);
  v.put('snapshot',json_object_t.parse(lf.COMPOSITION_JSON));v.put('legs',restored);
  p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');wire clob;v json_object_t;sd json_object_t;lf RRL_TT_HU_LOAD_FACT%rowtype;
  reason_text varchar2(1000):=m.get_string('reason');op varchar2(100):=d.get_string('operation_id');load_id varchar2(100);case_id number;sid number;trip_id number;ware number;cell_text varchar2(60);
  a json_array_t;x json_object_t;history RRL_STOCK_RESERVATION%rowtype;details json_object_t;uid_text varchar2(150);qty number;version_no number;physical number;held number;event_id number;n number;new_id number;uom_version number;uom_text varchar2(20);unit_wire clob;fresh_units clob;members json_array_t;nodes json_array_t;links json_array_t;node_wire clob;member_wire clob;root_uid varchar2(150);child_uid varchar2(150);child_case number;new_link number;parent_uid varchar2(150);placement_metadata json_object_t;placement_tree json_object_t;measures json_object_t;placement_wire clob;placement_root varchar2(150);new_coverage number;j json_object_t:=json_object_t();
 begin
  select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=op;v:=json_object_t.parse(wire).get_object('domain');
  load_id:=v.get_string('load_id');case_id:=v.get_number('case_id');members:=v.get_array('members');root_uid:=v.get_string('root_uid');member_wire:=members.to_clob;node_wire:=v.get_object('snapshot').get_array('nodes').to_clob;trip_id:=v.get_number('trip_id');ware:=v.get_number('warehouse');cell_text:=m.get_string('scan_cell');
  assert_scope(load_id,p_actor);
  select ID into n from RRL_TRANSPORT_TASK where ID=trip_id for update;
  select TT_ID into n from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=load_id for update;
  for owner in(select ID from RRL_SBORKA_PALLETS where ID in(select SID from json_table(member_wire,'$[*]'columns(SID number path '$.shipment_id')))order by ID)loop select ID into n from RRL_SBORKA_PALLETS where ID=owner.ID for update;end loop;
  for owner in(select CASE_PICK_TASK_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID in(select C from json_table(member_wire,'$[*]'columns(C number path '$.case_id')))order by CASE_PICK_TASK_ID)loop select CASE_PICK_TASK_ID into n from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=owner.CASE_PICK_TASK_ID for update;end loop;
  source_state(load_id,m,lf,sd);
  if lf.TT_ID!=trip_id or nvl(lf.ROOT_CASE_TASK_ID,-1)!=nvl(case_id,-1)or nvl(lf.ROOT_UID,'~')!=nvl(root_uid,'~')or lf.WARE_ID!=ware or dbms_lob.compare(sd.get_array('members').to_clob,member_wire)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: unload owners');end if;
  a:=v.get_array('legs');
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i)as json_object_t);uid_text:=x.get_string('uid');new_id:=x.get_number('new_reservation');qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));uom_text:=x.get_string('base_uom');uom_version:=x.get_number('uom_version');
   select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION into physical,held,version_no from RRL_REMAINS where UID_POLETA=uid_text and CELL=cell_text for update;
   if physical!=0 or held!=0 or version_no!=x.get_number('current_stock_version')then raise_application_error(-20890,'CLOSURE_CHANGED: unload physical stock');end if;
   declare old_id number:=x.get_number('reservation_id');begin select *into history from RRL_STOCK_RESERVATION where RESERVATION_ID=old_id;end;
   if history.UID_PALLET!=uid_text or history.CELL!=cell_text or history.STATUS!='CONSUMED'or history.BASE_QTY!=0 or history.SOURCE_DOC_TYPE!='PICK_WAVE'or history.RESERVATION_DOMAIN!='PICKING'then raise_application_error(-20886,'UNLOAD_ORIGINAL_CONSUMED_RESERVATION_REQUIRED');end if;
   unit_wire:=x.get_array('restored_units').to_clob;fresh_units:=issued_units(load_id,uid_text,cell_text,qty);
   if dbms_lob.compare(unit_wire,fresh_units)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: unload original units');end if;
   RRL_STOCK_BALANCE_CORE.apply_delta(uid_text,cell_text,qty,0,uom_text,uom_version,version_no);
   RRL_STOCK_BALANCE_CORE.write_leg(uid_text,null,cell_text,qty,uom_text,uom_version,i+1,1,1,p_actor,event_id);
   details:=json_object_t();details.put('reservation_scope',history.RESERVATION_SCOPE);details.put('customer_order_id',history.CUSTOMER_ORDER_ID);details.put('customer_id',history.CUSTOMER_ID);details.put('pick_plan_id',history.PICK_PLAN_ID);details.put('pick_plan_line_id',history.PICK_PLAN_LINE_ID);details.put('restores_load_operation',load_id);
   RRL_STOCK_RESERVE_CORE.restore_consumed(history.RESERVATION_ID,new_id,qty,uom_version,p_actor);
   if x.get_array('restored_units').get_size>0 then RRL_STOCK_UNIT_CORE.restore_issued(uid_text,cell_text,new_id,qty,unit_wire);end if;
  end loop;
  nodes:=v.get_object('snapshot').get_array('nodes');
  for node_index in 0..nodes.get_size-1 loop
   x:=treat(nodes.get(node_index)as json_object_t);uid_text:=x.get_string('uid');
   if x.get_string('kind')='CONTAINER'then
    update RRL_PALLETS set HU_SHIPPED_OPERATION=null,HU_CURRENT_CELL=cell_text,HU_CONTENT_VERSION=HU_CONTENT_VERSION+1 where UID_PALLET=uid_text and HU_SHIPPED_OPERATION=load_id;
    if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: unload container');end if;
   end if;
  end loop;
  for member_index in 0..members.get_size-1 loop
   x:=treat(members.get(member_index)as json_object_t);case_id:=x.get_number('case_id');sid:=x.get_number('shipment_id');
   if case_id is not null then
   update RRL_CASE_PICK_TASK set STATUS='WAIT_CONTROL',SHIPPED_OPERATION=null,CONTENT_VERSION=CONTENT_VERSION+1,CURRENT_CELL=cell_text,DONE_AT=null,UPDATED_AT=systimestamp,UPDATED_BY=p_actor where CASE_PICK_TASK_ID=case_id;
   RRL_STOCK_FULFILLMENT_FACT.project_unload(sid,load_id,case_id,p_actor);
   else
    RRL_STOCK_FULFILLMENT_FACT.project_unload_pallet(sid,load_id,x.get_string('physical_uid'),p_actor);
   end if;
   update RRL_SBORKA_PALLETS set CONDITION=0,PROOVED=0,SCAN_MARK_PROVED=0,SCAN_PHYSICAL_UNIT_COUNT=0,SCAN_ITEM_PROVED=0,TRIAL_WEIGHT=0,WOOD_WEIGHT=0,PROOVED_BY_SCAN=0,SCAN_CONTENT_SIGNATURE=null,WEIGHT_CONTENT_SIGNATURE=null,SCAN_QC_OPERATION_ID=null,WEIGHT_QC_OPERATION_ID=null,QC_RESCAN_REQUIRED=1 where ID=sid;
  end loop;
  links:=v.get_array('recover_links');
  for link_index in 0..links.get_size-1 loop
   x:=treat(links.get(link_index)as json_object_t);parent_uid:=x.get_string('parent');uid_text:=x.get_string('child');new_link:=x.get_number('new_id');child_uid:=null;child_case:=null;
   if substr(uid_text,1,5)='CASE:'then child_case:=to_number(substr(uid_text,6));else child_uid:=uid_text;end if;
   insert into RRL_WMS_HU_LINK(HU_LINK_ID,PARENT_UID,CHILD_PALLET_UID,CHILD_CASE_TASK_ID,ACTIVE_FLAG,LINK_VERSION,LINKED_OPERATION_ID,LINKED_BY)values(new_link,parent_uid,child_uid,child_case,1,0,op,p_actor);
  end loop;
  if v.get_number('placement_slot')is not null then
   placement_root:=nvl(lf.ROOT_UID,'CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(lf.ROOT_CASE_TASK_ID));
   if lf.ROOT_CASE_TASK_ID is null then placement_tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(placement_root));
   else placement_tree:=json_object_t.parse(RRL_STOCK_HU_READ.case_snapshot_json(lf.ROOT_CASE_TASK_ID));end if;
   measures:=v.get_object('original_measures').clone();measures.put('content_version',treat(placement_tree.get_array('nodes').get(0)as json_object_t).get_number('version'));
   placement_metadata:=m.clone();placement_metadata.put('target_cell',cell_text);placement_metadata.put('planned_physical_task_id',v.get_number('placement_task'));placement_metadata.put('measurements',measures);
   placement_wire:=RRL_STOCK_HU_SLOT.target_json(placement_tree.to_clob,placement_metadata.to_clob,null,placement_root);
   RRL_STOCK_HU_PLACEMENT_CORE.record_place(p_request,p_actor,placement_root,ware,cell_text,v.get_number('placement_task'),v.get_number('placement_slot'),v.get_number('placement_sync'),placement_wire,lf.ROOT_CASE_TASK_ID);
   for leg_index in 0..a.get_size-1 loop
    x:=treat(a.get(leg_index)as json_object_t);qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));new_id:=x.get_number('new_reservation');
    RRL_STOCK_RESERVE_CORE.move_coverage(new_id,new_id,x.get_string('uid'),cell_text,ware,qty,v.get_number('placement_slot'),p_actor,new_coverage);
    if new_coverage!=new_id then raise_application_error(-20869,'UNLOAD_RESERVATION_IDENTITY_CHANGED');end if;
   end loop;
   j.put('placement_task',v.get_number('placement_task'));j.put('placement_slot',v.get_number('placement_slot'));
  end if;
  insert into RRL_TT_UNLOAD_FACT(OPERATION_ID,LOAD_OPERATION_ID,TT_ID,CASE_PICK_TASK_ID,ROOT_UID,WARE_ID,CELL_CODE,COMPOSITION_JSON,REASON,CREATED_BY)
   values(op,load_id,trip_id,lf.ROOT_CASE_TASK_ID,lf.ROOT_UID,ware,cell_text,lf.COMPOSITION_JSON,reason_text,p_actor);
  update RRL_TT_HU_LOAD_FACT set STATUS='UNLOADED'where LOAD_OPERATION_ID=load_id;
  update RRL_TT_HU_LOAD_ST set ACTIVE_FLAG=0 where LOAD_OPERATION_ID=load_id and ACTIVE_FLAG=1;
  if sql%rowcount!=members.get_size then raise_application_error(-20890,'CLOSURE_CHANGED: unload active members');end if;
  j.put('operation_id',op);j.put('status','UNLOADED');j.put('load_operation_id',load_id);j.put('case_task_id',lf.ROOT_CASE_TASK_ID);j.put('root_uid',lf.ROOT_UID);j.put('members',members);j.put('cell',cell_text);j.put('restored_lines',a);j.put('quality_control_required',true);j.put('original_ship_history_preserved',true);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_UOM_CONFIG as
 procedure require_configuration is
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','MODE') is null or sys_context('RRL_STOCK_WRITE_CTX','MODE')!='CONFIG' or
   sys_context('RRL_STOCK_WRITE_CTX','TX_ID') is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false) then
   raise_application_error(-20863,'CONFIGURATION_CONTEXT_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
 end;
 procedure publish(p_article varchar2,p_input varchar2,p_base varchar2,p_numerator number,p_denominator number,p_scale number,p_provenance varchar2) is
  n number;v_version number;v_key raw(1000);v_id number;v_old RRL_STOCK_UOM_CONVERSION%rowtype;
 begin
  require_configuration;
  if p_article is null or p_input is null or p_base is null or p_provenance is null or length(p_input)>20 or length(p_base)>20 then raise_application_error(-20833,'UOM_POLICY_IDENTITY_INVALID');end if;
  select count(*) into n from RRL_ARTICULS where ACTICUL=p_article;
  if n!=1 then raise_application_error(-20887,'ARTICLE_IDENTITY_AMBIGUOUS');end if;
  RRL_STOCK_MATH.assert_base(0,p_scale);
  if p_numerator is null or p_denominator is null or p_numerator<1 or p_denominator<1 or p_numerator>1000000000 or p_denominator>1000000000 or
   p_numerator!=trunc(p_numerator) or p_denominator!=trunc(p_denominator) then raise_application_error(-20833,'UOM_FACTOR_INVALID');end if;
  if p_input=p_base and (p_numerator!=1 or p_denominator!=1) then raise_application_error(-20833,'BASE_UOM_IDENTITY_REQUIRED');end if;
  select count(*) into n from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and BASE_UOM!=p_base;
  if n>0 then raise_application_error(-20866,'BASE_CHANGE_REQUIRES_EXPLICIT_CONVERSION');end if;
  select count(*) into n from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and BASE_SCALE!=p_scale;
  if n>0 then raise_application_error(-20866,'BASE_PRECISION_CHANGE_REQUIRES_EXPLICIT_CONVERSION');end if;
  select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM=p_input;
  if v_version is not null then
   select * into v_old from RRL_STOCK_UOM_CONVERSION where ARTICUL=p_article and INPUT_UOM=p_input and POLICY_VERSION=v_version;
   if v_old.NUMERATOR=p_numerator and v_old.DENOMINATOR=p_denominator and v_old.BASE_SCALE=p_scale then return;end if;
  end if;
  -- Global configuration X fence serializes publication; posting never creates policy identities.
  v_key:=RRL_STOCK_LOCK_API.resource_key('SKU',p_article);
  select count(*) into n from RRL_STOCK_POLICY_GUARD where POLICY_KEY=v_key;
  if n=0 then
   select nvl(max(LOCK_ID),900000000)+1 into v_id from RRL_STOCK_POLICY_GUARD;
   if v_id>949999999 then raise_application_error(-20808,'POLICY_ID_RANGE_EXHAUSTED');end if;
   insert into RRL_STOCK_POLICY_GUARD(POLICY_KEY,LOCK_ID,POLICY_VERSION) values(v_key,v_id,1);
  end if;
  insert into RRL_STOCK_UOM_CONVERSION(ARTICUL,INPUT_UOM,BASE_UOM,POLICY_VERSION,NUMERATOR,DENOMINATOR,BASE_SCALE,PROVENANCE)
   values(p_article,p_input,p_base,nvl(v_version,0)+1,p_numerator,p_denominator,p_scale,p_provenance);
  update RRL_STOCK_POLICY_GUARD set POLICY_VERSION=POLICY_VERSION+1 where POLICY_KEY=v_key;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_WAVE_CMD as

 function release_amount(p_text varchar2)return number is

 begin

  if p_text='0'then return 0;end if;

  return RRL_STOCK_MATH.quantity(p_text);

 end;

 function signature(p_row RRL_PICK_WAVE_REPLENISH_TASK%rowtype) return varchar2 is v json_object_t:=json_object_t();

 begin

  v.put('id',p_row.PICK_WAVE_REPLENISH_TASK_ID);v.put('wave',p_row.PICK_WAVE_ID);v.put('article',p_row.ARTICUL);

  v.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(p_row.QTY));v.put('target',p_row.TARGET_CELL_CODE);

  v.put('demand',p_row.DEMAND_BASE_QTY);v.put('pick_task',p_row.PICK_TASK_ID);v.put('scope',p_row.REPLENISHMENT_QTY_MODE);v.put('shelf_days',p_row.MIN_SHELF_LIFE_DAYS);v.put('shelf_percent',p_row.MIN_SHELF_LIFE_PERCENT);

  return rawtohex(sys.dbms_crypto.hash(v.to_clob,sys.dbms_crypto.hash_sh256));

 end;

 procedure compile_target_supply(rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype,p_needed number,p_ware number,p_mode varchar2,p_capacity number,

  f in out nocopy json_array_t,r in out nocopy json_array_t,p_used in out nocopy json_object_t,

  p_changes in out nocopy json_object_t,p_decision out json_object_t,p_plan out json_object_t) is

  old_a json_array_t:=json_array_t();new_a json_array_t:=json_array_t();x json_object_t;

  v_total number:=0;v_count number;v_version number;v_id number;v_left number:=p_needed;v_take number;v_key varchar2(2000);v_base varchar2(20);v_taken number;v_release_left number;v_release number;v_source json_object_t;v_source_uid varchar2(200);v_source_cell varchar2(60);v_source_p number;v_source_ver number;v_reason varchar2(4000);v_candidates json_array_t:=json_array_t();v_cand json_object_t;

 begin

  p_plan:=null;p_decision:=json_object_t();p_decision.put('needed',p_needed);

  p_decision.put('mode',p_mode);p_decision.put('capacity',p_capacity);

  if rt.PICK_TASK_ID is null or p_needed is null or p_needed<=0 then return;end if;

  select count(*) into v_count from RRL_WAREHOUSE_TASK wh join RRL_PICK_WAVE_REPLENISH_TASK rr

   on rr.PICK_WAVE_REPLENISH_TASK_ID=wh.SOURCE_TASK_ID and rr.PICK_WAVE_ID=wh.SOURCE_DOC_ID

   where wh.TASK_SOURCE='WAVE' and wh.TASK_TYPE='REPLENISHMENT' and rr.PICK_WAVE_ID=rt.PICK_WAVE_ID

    and rr.PICK_TASK_ID=rt.PICK_TASK_ID and wh.STATUS not in('DONE','CANCELLED');

  if v_count>0 then p_decision.put('reason','PHYSICAL_TASK_ALREADY_PLANNED');return;end if;

  for sr in(select sr.* from RRL_STOCK_RESERVATION sr join RRL_PICK_TASK pt on pt.PICK_TASK_ID=sr.SOURCE_LINE_ID

   join RRL_CELLS c on c.CELL=sr.CELL

   where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=rt.PICK_WAVE_ID and sr.SOURCE_LINE_ID=rt.PICK_TASK_ID

    and sr.RESERVATION_DOMAIN='PICKING' and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING')

    and sr.BASE_QTY>0 and sr.CELL!=rt.TARGET_CELL_CODE and sr.ARTICUL=rt.ARTICUL

    and sr.CUSTOMER_ORDER_ID=pt.CUSTOMER_ORDER_ID and c.WARE_ID=p_ware order by sr.RESERVATION_ID fetch first 201 rows only) loop

   if old_a.get_size>=200 then raise_application_error(-20881,'TARGET_SUPPLY_OWNER_BOUND_200');end if;

   if v_base is null then v_base:=sr.BASE_UOM;elsif v_base!=sr.BASE_UOM then raise_application_error(-20868,'TARGET_SUPPLY_BASE_CONFLICT');end if;

   x:=json_object_t();x.put('id',sr.RESERVATION_ID);x.put('version',sr.RESERVATION_VERSION);

   x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(sr.BASE_QTY));x.put('uid',sr.UID_PALLET);x.put('cell',sr.CELL);

   x.put('base_uom',sr.BASE_UOM);old_a.append(x);v_total:=v_total+sr.BASE_QTY;

  end loop;

  p_decision.put('source_binding_count',old_a.get_size);p_decision.put('source_owned_quantity',v_total);

  if v_total!=p_needed or old_a.get_size=0 then p_decision.put('reason','COMPLETE_OWN_SOURCE_BINDING_REQUIRED');return;end if;

  for i in 0..old_a.get_size-1 loop

   x:=treat(old_a.get(i) as json_object_t);v_source_uid:=x.get_string('uid');v_source_cell:=x.get_string('cell');

   select count(*) into v_count from RRL_WAREHOUSE_TASK where UID_PALLET=v_source_uid and FROM_CELL=v_source_cell and STATUS not in('DONE','CANCELLED');

   if v_count>0 then p_decision.put('reason','SOURCE_PALLET_PHYSICAL_TASK_ALREADY_PLANNED');return;end if;

  end loop;

  v_count:=0;

  for st in(select rr.UID_POLETA,rr.CELL,rr.REMAIN,rr.HARD_RESERVED_BASE,rr.STOCK_VERSION,rr.BASE_UOM

   from RRL_REMAINS rr join RRL_PALLETS pp on pp.UID_PALLET=rr.UID_POLETA join RRL_CELLS c on c.CELL=rr.CELL

   where rr.CELL=rt.TARGET_CELL_CODE and c.WARE_ID=p_ware and pp.ARTICUL=rt.ARTICUL and rr.REMAIN>rr.HARD_RESERVED_BASE

   order by pp.EXPIRY_DATE nulls last,pp.PRODUCED_DATE nulls last,rr.UID_POLETA fetch first 201 rows only) loop

   exit when v_left=0;v_count:=v_count+1;if v_count>200 then raise_application_error(-20881,'TARGET_SUPPLY_CANDIDATE_BOUND_200');end if;

   v_key:=RRL_STOCK_LOCK_API.resource_key('STOCK',st.UID_POLETA,st.CELL);

   v_take:=least(v_left,st.REMAIN-st.HARD_RESERVED_BASE-nvl(p_used.get_number(v_key),0));

   v_cand:=json_object_t();v_cand.put('uid',st.UID_POLETA);v_cand.put('free',st.REMAIN-st.HARD_RESERVED_BASE);v_cand.put('planned_used',nvl(p_used.get_number(v_key),0));v_cand.put('take',v_take);

   if v_take<=0 then v_cand.put('reason','NO_UNPLANNED_FREE_QUANTITY');v_candidates.append(v_cand);continue;end if;

   v_reason:=RRL_STOCK_ELIGIBILITY.reason(st.UID_POLETA,st.CELL,p_ware,v_take,rt.MIN_SHELF_LIFE_DAYS,

    rt.MIN_SHELF_LIFE_PERCENT,'ALLOCATE',null,rt.ARTICUL);

   v_cand.put('reason',v_reason);v_candidates.append(v_cand);

   if v_reason is not null then continue;end if;

   if st.BASE_UOM!=v_base then raise_application_error(-20868,'TARGET_SUPPLY_BASE_CONFLICT');end if;

   select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=rt.ARTICUL

    and INPUT_UOM=st.BASE_UOM and BASE_UOM=st.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;

   if v_version is null then raise_application_error(-20868,'TARGET_SUPPLY_BASE_POLICY_REQUIRED');end if;

   select RRL_STOCK_RESERVATION_SQ.nextval into v_id from dual;

   x:=json_object_t();x.put('uid',st.UID_POLETA);x.put('cell',st.CELL);x.put('id',v_id);x.put('base_uom',st.BASE_UOM);

   x.put('stock_version',st.STOCK_VERSION+nvl(p_changes.get_number(v_key),0));x.put('uom_version',v_version);

   x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_take));new_a.append(x);v_left:=v_left-v_take;

  end loop;

  v_taken:=p_needed-v_left;p_decision.put('candidates',v_candidates);p_decision.put('usable_target_quantity',v_taken);

  -- Compute releases without changing global batch accounting until admission succeeds.

  v_release_left:=v_taken;

  for i in 0..old_a.get_size-1 loop

   x:=treat(old_a.get(i)as json_object_t);

   v_release:=least(v_release_left,RRL_STOCK_MATH.quantity(x.get_string('quantity')));

   v_release_left:=v_release_left-v_release;

   x.put('release_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_release));old_a.put(i,x,true);

  end loop;

  if v_left>0 then

   if v_taken<=0 or p_mode!='FULL_PALLET' then p_decision.put('reason','PARTIAL_TARGET_WHOLE_SOURCE_REQUIRED');return;end if;

   -- Retain every untouched own binding. Issue only the first whole source;

   -- the existing REPL_CONTINUATION calculates further own demand after its receipt.

   v_count:=0;

   for i in 0..old_a.get_size-1 loop

    x:=treat(old_a.get(i)as json_object_t);

    if RRL_STOCK_MATH.quantity(x.get_string('quantity'))>release_amount(x.get_string('release_quantity'))then

     v_count:=v_count+1;

     if v_source is null then v_source:=json_object_t.parse(x.to_clob);end if;

    end if;

   end loop;

   if v_source is null then raise_application_error(-20890,'TARGET_SUPPLY_RETAINED_OWNER_REQUIRED');end if;

   p_decision.put('remaining_source_binding_count',v_count);

   v_source_uid:=v_source.get_string('uid');v_source_cell:=v_source.get_string('cell');

   -- Every retained reservation is captured in old_a and verified separately.
   -- One representative binding selects physical stock; original whole arrival
   -- moves all captured owners, including multiple bindings of this same owner.
   select REMAIN,STOCK_VERSION into v_source_p,v_source_ver from RRL_REMAINS where UID_POLETA=v_source_uid and CELL=v_source_cell;

   p_decision.put('whole_source_quantity',v_source_p);

   if p_capacity is not null and v_source_p>p_capacity then p_decision.put('reason','WHOLE_SOURCE_EXCEEDS_REMAINING_TARGET_CAPACITY');return;end if;

   v_release:=release_amount(v_source.get_string('release_quantity'));

   v_source.put('remaining_owner_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(RRL_STOCK_MATH.quantity(v_source.get_string('quantity'))-v_release));

   v_source.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_source_p));

   v_source.put('remaining_total_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_left));

   v_source.put('reservation_version',v_source.get_number('version')+case when v_release>0 then 1 else 0 end);

   v_key:=RRL_STOCK_LOCK_API.resource_key('STOCK',v_source_uid,v_source_cell);

   v_count:=0;

   for i in 0..old_a.get_size-1 loop

    x:=treat(old_a.get(i)as json_object_t);

    if x.get_string('uid')=v_source_uid and x.get_string('cell')=v_source_cell

     and release_amount(x.get_string('release_quantity'))>0 then v_count:=v_count+1;end if;

   end loop;

   v_source.put('stock_version',v_source_ver+nvl(p_changes.get_number(v_key),0)+v_count);

  end if;

  v_release_left:=v_taken;

  for i in 0..old_a.get_size-1 loop

   x:=treat(old_a.get(i) as json_object_t);

   v_release:=least(v_release_left,RRL_STOCK_MATH.quantity(x.get_string('quantity')));v_release_left:=v_release_left-v_release;

   x.put('release_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_release));old_a.put(i,x,true);v_key:=RRL_STOCK_LOCK_API.resource_key('STOCK',x.get_string('uid'),x.get_string('cell'));

   if v_release>0 then p_changes.put(v_key,nvl(p_changes.get_number(v_key),0)+1);end if;

   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),rt.ARTICUL,x.get_string('cell'),null);

  end loop;

  for i in 0..new_a.get_size-1 loop

   x:=treat(new_a.get(i) as json_object_t);v_key:=RRL_STOCK_LOCK_API.resource_key('STOCK',x.get_string('uid'),x.get_string('cell'));

   p_used.put(v_key,nvl(p_used.get_number(v_key),0)+RRL_STOCK_MATH.quantity(x.get_string('quantity')));

   p_changes.put(v_key,nvl(p_changes.get_number(v_key),0)+1);

   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,x.get_string('uid'),rt.ARTICUL,x.get_string('cell'),null);

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(x.get_number('id')));

  end loop;

  p_plan:=json_object_t();p_plan.put('old',old_a);p_plan.put('new',new_a);

  p_decision.put('reason',case when v_source is null then 'COMPLETE_TARGET_REPLACEMENT' else 'PARTIAL_TARGET_AND_WHOLE_SOURCE' end);

  p_plan.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_taken));if v_source is not null then p_plan.put('continuation',v_source);end if;

 end;

 procedure execute_target_supply(rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype,p_plan json_object_t,p_ware number,p_actor varchar2) is

  a json_array_t:=p_plan.get_array('old');b json_array_t:=p_plan.get_array('new');x json_object_t;sr RRL_STOCK_RESERVATION%rowtype;

  v_qty number;v_stock number;v_count number;v_units clob;v_uid varchar2(200);v_cell varchar2(60);v_id number;

  v_details json_object_t:=json_object_t();v_rid number;v_version number;v_old_qty number;v_first varchar2(200);v_release_qty number;v_remaining_owner number;v_source_p number;v_source_ver number;v_source_res_ver number;v_next json_object_t;

 begin

  select count(*) into v_count from RRL_WAREHOUSE_TASK wh join RRL_PICK_WAVE_REPLENISH_TASK rr

   on rr.PICK_WAVE_REPLENISH_TASK_ID=wh.SOURCE_TASK_ID and rr.PICK_WAVE_ID=wh.SOURCE_DOC_ID

   where wh.TASK_SOURCE='WAVE' and wh.TASK_TYPE='REPLENISHMENT' and rr.PICK_WAVE_ID=rt.PICK_WAVE_ID

    and rr.PICK_TASK_ID=rt.PICK_TASK_ID and wh.STATUS not in('DONE','CANCELLED');

  if v_count>0 then raise_application_error(-20890,'CLOSURE_CHANGED: target supply physical task issued');end if;

  for pt in(select CUSTOMER_ID,CUSTOMER_ORDER_ID,PICK_PLAN_ID,PICK_PLAN_LINE_ID from RRL_PICK_TASK

   where PICK_TASK_ID=rt.PICK_TASK_ID and ARTICUL=rt.ARTICUL and TASK_TYPE='CASE_PICK' and STATUS not in('DONE','CANCELLED','FAILED')) loop

   v_details.put('reservation_scope','QTY');v_details.put('customer_id',pt.CUSTOMER_ID);v_details.put('customer_order_id',pt.CUSTOMER_ORDER_ID);

   v_details.put('pick_plan_id',pt.PICK_PLAN_ID);v_details.put('pick_plan_line_id',pt.PICK_PLAN_LINE_ID);v_details.put('pick_wave_id',rt.PICK_WAVE_ID);

  end loop;

  if not v_details.has('customer_order_id') then raise_application_error(-20887,'TARGET_SUPPLY_CASE_OWNER_REQUIRED');end if;

  for i in 0..a.get_size-1 loop

   x:=treat(a.get(i) as json_object_t);v_uid:=x.get_string('uid');v_cell:=x.get_string('cell');

   select count(*) into v_count from RRL_WAREHOUSE_TASK where UID_PALLET=v_uid and FROM_CELL=v_cell and STATUS not in('DONE','CANCELLED');

   if v_count>0 then raise_application_error(-20890,'CLOSURE_CHANGED: source pallet physical task planned');end if;

   v_rid:=x.get_number('id');

   select * into sr from RRL_STOCK_RESERVATION where RESERVATION_ID=v_rid for update;

   v_old_qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));

   if sr.RESERVATION_VERSION!=x.get_number('version') or sr.BASE_QTY!=v_old_qty

    or sr.UID_PALLET!=x.get_string('uid') or sr.CELL!=x.get_string('cell')

    or sr.SOURCE_DOC_TYPE!='PICK_WAVE' or sr.SOURCE_DOC_ID!=rt.PICK_WAVE_ID or sr.SOURCE_LINE_ID!=rt.PICK_TASK_ID

    or sr.CUSTOMER_ORDER_ID!=v_details.get_number('customer_order_id')

    or sr.RESERVATION_DOMAIN!='PICKING' or sr.RESERVATION_KIND!='HARD'

    or sr.STATUS not in('ACTIVE','ALLOCATED','PICKING') then raise_application_error(-20890,'CLOSURE_CHANGED: target supply owner');end if;

   select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=rt.ARTICUL

    and INPUT_UOM=sr.BASE_UOM and BASE_UOM=sr.BASE_UOM and NUMERATOR=1 and DENOMINATOR=1;

   v_release_qty:=release_amount(x.get_string('release_quantity'));

   if v_release_qty>0 then RRL_STOCK_UNIT_CORE.release_units(v_rid,v_release_qty,null,0);

   RRL_STOCK_RESERVE_CORE.release_hard(v_rid,v_release_qty,v_version,'PICK_WAVE',rt.PICK_WAVE_ID,p_actor);end if;

  end loop;

  for i in 0..b.get_size-1 loop

   x:=treat(b.get(i) as json_object_t);v_uid:=x.get_string('uid');v_cell:=x.get_string('cell');v_id:=x.get_number('id');

   v_qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));

   select STOCK_VERSION into v_stock from RRL_REMAINS where UID_POLETA=v_uid and CELL=v_cell;

   if v_stock!=x.get_number('stock_version') then raise_application_error(-20890,'CLOSURE_CHANGED: target supply stock');end if;

   RRL_STOCK_ELIGIBILITY.assert_source(v_uid,v_cell,p_ware,v_qty,rt.MIN_SHELF_LIFE_DAYS,rt.MIN_SHELF_LIFE_PERCENT,'ALLOCATE',null,rt.ARTICUL);

   v_units:=RRL_WEIGHT_CHOICE_UNIT_READ.selected_units(rt.PICK_TASK_ID,v_uid,v_cell,v_qty);

   if v_units is null then v_units:=RRL_STOCK_UNIT_CORE.automatic_units(v_uid,v_cell,v_qty);end if;

   RRL_STOCK_RESERVE_CORE.create_hard(v_id,v_uid,v_cell,v_qty,x.get_string('base_uom'),x.get_number('uom_version'),

    'PICK_WAVE',rt.PICK_WAVE_ID,rt.PICK_TASK_ID,'PICKING',p_actor,v_details.to_clob);

   RRL_STOCK_UNIT_CORE.reserve_units(v_uid,v_cell,v_id,v_qty,v_units);

   if v_first is null then v_first:=v_uid;end if;

  end loop;

  if p_plan.has('continuation') then

   v_next:=p_plan.get_object('continuation');v_uid:=v_next.get_string('uid');v_cell:=v_next.get_string('cell');v_id:=v_next.get_number('id');

   v_qty:=RRL_STOCK_MATH.quantity(v_next.get_string('quantity'));

   v_remaining_owner:=RRL_STOCK_MATH.quantity(v_next.get_string('remaining_owner_quantity'));

   select BASE_QTY,RESERVATION_VERSION into v_old_qty,v_source_res_ver from RRL_STOCK_RESERVATION where RESERVATION_ID=v_id;

   select REMAIN,STOCK_VERSION into v_source_p,v_source_ver from RRL_REMAINS where UID_POLETA=v_uid and CELL=v_cell;

   if v_old_qty!=v_remaining_owner or v_source_res_ver!=v_next.get_number('reservation_version')

    or v_source_p!=v_qty or v_source_ver!=v_next.get_number('stock_version') then raise_application_error(-20890,'CLOSURE_CHANGED: partial target source binding');end if;

   update RRL_PICK_TASK set PALLET_UID=v_uid,SOURCE_CELL_CODE=v_cell where PICK_TASK_ID=rt.PICK_TASK_ID;

   update RRL_PICK_WAVE_TASK set PALLET_UID=v_uid,SOURCE_CELL_CODE=v_cell where PICK_WAVE_ID=rt.PICK_WAVE_ID and PICK_TASK_ID=rt.PICK_TASK_ID;

   update RRL_PICK_WAVE_REPLENISH_TASK set STATUS='RELEASED',SOURCE_RESERVATION_ID=v_id,PALLET_UID=v_uid,SOURCE_CELL_CODE=v_cell,

    DEMAND_BASE_QTY=v_remaining_owner,QTY=v_qty,SOURCE_AVAILABLE_QTY=v_qty,REPLENISHMENT_QTY_MODE='FULL_PALLET',

    WAIT_REASON='Existing target HARD plus remaining own whole-pallet source; physical receipt still required',

    UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID;

  else

  update RRL_PICK_TASK set PALLET_UID=v_first,SOURCE_CELL_CODE=rt.TARGET_CELL_CODE where PICK_TASK_ID=rt.PICK_TASK_ID;

  update RRL_PICK_WAVE_TASK set PALLET_UID=v_first,SOURCE_CELL_CODE=rt.TARGET_CELL_CODE where PICK_WAVE_ID=rt.PICK_WAVE_ID and PICK_TASK_ID=rt.PICK_TASK_ID;

  update RRL_PICK_WAVE_REPLENISH_TASK set STATUS='CANCELLED',DEMAND_BASE_QTY=0,WAIT_REASON='Atomic multi-UID target HARD replacement; no physical replenishment',

   UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID;

  end if;

 end;

 procedure compile_reserve(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is

  d json_object_t:=json_object_t.parse(p_request);v_wave number;v_ware number;v_id number;v_qty number;v_version number;

  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t:=json_array_t();v json_object_t:=json_object_t();x json_object_t;

  v_uid varchar2(200);v_cell varchar2(60);v_uom varchar2(20);v_free number;v_own_id number;v_own_qty number;v_capacity number;v_wanted number;v_is_short number;v_needed number;v_num number;v_den number;v_scale number;

  v_target_supply json_object_t;v_target_decision json_object_t;v_target_used json_object_t:=json_object_t();v_target_changes json_object_t:=json_object_t();v_target_picks json_object_t:=json_object_t();v_pick_key varchar2(80);v_rebind number:=0;v_requested clob;v_requested_array json_array_t;v_mode varchar2(40);v_kind varchar2(40);

  type quantities is table of number index by varchar2(2000);used quantities;k varchar2(2000);

 begin

  if d.get_object('metadata').get_boolean('allow_unissued_source_rebind') then v_rebind:=1;end if;

  if d.get_object('metadata').has('requested_row_ids') then

   v_requested_array:=d.get_object('metadata').get_array('requested_row_ids');

   if v_requested_array is null or v_requested_array.get_size<1 or v_requested_array.get_size>200 then raise_application_error(-20881,'WAVE_REQUESTED_ROWS_BOUND');end if;

   v_requested:=v_requested_array.to_clob;

  end if;

  v_wave:=d.get_object('source').get_number('wave_id');select WARE_ID,WAVE_KIND into v_ware,v_kind from RRL_PICK_WAVE where PICK_WAVE_ID=v_wave;

  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');

  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);

  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));

  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(v_wave));

  for rt in(select * from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_ID=v_wave

   and STATUS in('RELEASED','QUEUED','WAIT_FREE_CELL','WAIT_MINIMAX') and(SOURCE_RESERVATION_ID is null or v_rebind=1)

   and (v_requested is null or PICK_WAVE_REPLENISH_TASK_ID in(select id from json_table(v_requested,'$[*]' columns(id number path '$' error on error))))

   order by PICK_WAVE_REPLENISH_TASK_ID) loop

   if a.get_size>=200 then raise_application_error(-20881,'WAVE_RESERVATION_BATCH_BOUND');end if;

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(rt.PICK_WAVE_REPLENISH_TASK_ID));

   RRL_STOCK_PLAN_HELPER.fence(f,'SKU',rt.ARTICUL);

   if rt.PICK_TASK_ID is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(rt.PICK_TASK_ID));end if;

   v_uid:=null;v_qty:=null;v_cell:=null;v_uom:=null;v_version:=null;

   v_own_id:=null;v_own_qty:=null;

   RRL_STOCK_PLAN_HELPER.fence(f,'CELL',rt.TARGET_CELL_CODE,6);

   v_capacity:=RRL_STOCK_REPL_CAPACITY.remaining_base_quantity(rt.TARGET_CELL_CODE,rt.ARTICUL,rt.PICK_WAVE_REPLENISH_TASK_ID);

   select count(*) into v_is_short from RRL_CASE_PICK_SHORT where REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID and RECOVERY_STATE='WAIT_REPLENISHMENT';

   v_mode:=RRL_STOCK_REPL_ADMISSION.mode_for(rt.PICK_WAVE_REPLENISH_TASK_ID);

   v_wanted:=case when v_mode='FILL_TO_VOLUME' and v_is_short=0 and nvl(v_kind,'CUSTOMER_ORDER')!='REPLENISHMENT' and v_capacity is not null then v_capacity

    when v_capacity is not null and v_mode!='FULL_PALLET' then least(rt.QTY,v_capacity) else rt.QTY end;

   v_needed:=null;

   if rt.PICK_TASK_ID is not null then

    v_needed:=RRL_STOCK_REPL_NEED.remaining_for_task(rt.PICK_TASK_ID,rt.TARGET_CELL_CODE);

    if v_needed<=0 then v_wanted:=0;end if;

   end if;

   v_pick_key:=RRL_STOCK_PLAN_HELPER.decimal_text(rt.PICK_TASK_ID);

   if v_pick_key is not null and v_target_picks.has(v_pick_key) then continue;end if;

   compile_target_supply(rt,v_needed,v_ware,v_mode,v_capacity,f,r,v_target_used,v_target_changes,v_target_decision,v_target_supply);

   if v_target_supply is not null then v_target_picks.put(v_pick_key,1);end if;

   if rt.SOURCE_RESERVATION_ID is not null and v_target_supply is null then continue;end if;

   if v_wanted>0 and v_target_supply is null then

   for own in(select sr.RESERVATION_ID,sr.BASE_QTY,sr.UID_PALLET,sr.CELL,sr.BASE_UOM,rr.REMAIN

    from RRL_STOCK_RESERVATION sr join RRL_REMAINS rr on rr.UID_POLETA=sr.UID_PALLET and rr.CELL=sr.CELL

    join RRL_CELLS cc on cc.CELL=sr.CELL

    where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=v_wave and sr.SOURCE_LINE_ID=rt.PICK_TASK_ID

     and sr.RESERVATION_DOMAIN='PICKING' and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING') and sr.CELL!=rt.TARGET_CELL_CODE

     and sr.BASE_QTY>0 and cc.WARE_ID=v_ware

     and (v_mode!='FULL_PALLET' or RRL_STOCK_REPL_SHARED.allowed(sr.UID_PALLET,sr.CELL,rt.TARGET_CELL_CODE,v_ware,sr.RESERVATION_ID)=1)

     and RRL_STOCK_REPL_ADMISSION.reason(sr.UID_PALLET,rt.TARGET_CELL_CODE,v_ware,rt.ARTICUL) is null

     and (v_mode!='FULL_PALLET' or v_capacity is null or rr.REMAIN<=v_capacity) and nvl(cc.BLOCKED_FOR_REMAINS,0)=0 and nvl(cc.BLOCKED_FOR_POPOLNENIE,0)=0

    and RRL_STOCK_ELIGIBILITY.reason(sr.UID_PALLET,sr.CELL,v_ware,least(v_wanted,sr.BASE_QTY),rt.MIN_SHELF_LIFE_DAYS,rt.MIN_SHELF_LIFE_PERCENT,'REPLENISH',sr.RESERVATION_ID,rt.ARTICUL) is null

    order by sr.RESERVATION_ID) loop

    v_own_id:=own.RESERVATION_ID;v_own_qty:=own.BASE_QTY;v_uid:=own.UID_PALLET;v_cell:=own.CELL;v_uom:=own.BASE_UOM;

    v_qty:=case when v_mode='FULL_PALLET' then own.REMAIN else least(v_wanted,own.BASE_QTY) end;

    select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=rt.ARTICUL and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=1 and DENOMINATOR=1;

    if v_version is null then raise_application_error(-20868,'WAVE_BASE_POLICY_REQUIRED');end if;

    exit;

   end loop;

   if v_own_id is null then

   for c in(select rr.UID_POLETA,rr.CELL,rr.REMAIN,rr.HARD_RESERVED_BASE,rr.BASE_UOM,pp.EXPIRY_DATE,pp.PRODUCED_DATE

    from RRL_REMAINS rr join RRL_PALLETS pp on pp.UID_PALLET=rr.UID_POLETA join RRL_CELLS cc on cc.CELL=rr.CELL

    where pp.ARTICUL=rt.ARTICUL and rr.REMAIN>rr.HARD_RESERVED_BASE and cc.WARE_ID=v_ware

     and RRL_STOCK_REPL_ADMISSION.reason(rr.UID_POLETA,rt.TARGET_CELL_CODE,v_ware,rt.ARTICUL) is null

     and rr.CELL!=rt.TARGET_CELL_CODE and nvl(cc.BLOCKED_FOR_REMAINS,0)=0 and nvl(cc.BLOCKED_FOR_POPOLNENIE,0)=0

     and (rt.MIN_SHELF_LIFE_DAYS is null or trunc(pp.EXPIRY_DATE)-trunc(sysdate)>=rt.MIN_SHELF_LIFE_DAYS)

     and (rt.MIN_SHELF_LIFE_PERCENT is null or (pp.PRODUCED_DATE is not null and pp.EXPIRY_DATE>pp.PRODUCED_DATE

      and (trunc(pp.EXPIRY_DATE)-trunc(sysdate))*100 >= rt.MIN_SHELF_LIFE_PERCENT*(trunc(pp.EXPIRY_DATE)-trunc(pp.PRODUCED_DATE))))

     and RRL_STOCK_ELIGIBILITY.reason(rr.UID_POLETA,rr.CELL,v_ware,least(v_wanted,rr.REMAIN-rr.HARD_RESERVED_BASE),rt.MIN_SHELF_LIFE_DAYS,rt.MIN_SHELF_LIFE_PERCENT,'REPLENISH',null,rt.ARTICUL) is null

    order by pp.EXPIRY_DATE nulls last,pp.PRODUCED_DATE nulls last,rr.CELL,rr.UID_POLETA

   ) loop

    k:=rawtohex(RRL_STOCK_LOCK_API.resource_key('STOCK',c.UID_POLETA,c.CELL));if not used.exists(k) then used(k):=0;end if;

    v_free:=c.REMAIN-c.HARD_RESERVED_BASE-used(k);

    if v_free>0 and (v_mode!='FULL_PALLET' or (c.HARD_RESERVED_BASE+used(k)=0 and (v_capacity is null or c.REMAIN<=v_capacity))) then

     v_uid:=c.UID_POLETA;v_cell:=c.CELL;v_uom:=c.BASE_UOM;

     v_qty:=case when v_mode='FULL_PALLET' then c.REMAIN else least(v_wanted,v_free) end;

     select max(POLICY_VERSION) into v_version from RRL_STOCK_UOM_CONVERSION where ARTICUL=rt.ARTICUL and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=1 and DENOMINATOR=1;

     if v_version is null then raise_application_error(-20868,'WAVE_BASE_POLICY_REQUIRED');end if;

     used(k):=used(k)+v_qty;exit;

    end if;

   end loop;

   end if;

   end if;

   x:=json_object_t();x.put('needed_base',case when v_needed is not null then RRL_STOCK_PLAN_HELPER.decimal_text(v_needed) end);x.put('already_covered',case when v_needed=0 then 1 else 0 end);x.put('resolved_mode',v_mode);x.put('policy_signature',RRL_STOCK_REPL_ADMISSION.policy_signature(rt.PICK_WAVE_REPLENISH_TASK_ID));x.put('capacity_wait',case when v_capacity is not null and v_capacity=0 then 1 else 0 end);x.put('own_reservation_id',v_own_id);x.put('own_qty',case when v_own_qty is not null then RRL_STOCK_PLAN_HELPER.decimal_text(v_own_qty) end);x.put('source_reservation_before',rt.SOURCE_RESERVATION_ID);x.put('task_id',rt.PICK_WAVE_REPLENISH_TASK_ID);x.put('signature',signature(rt));x.put('uid',v_uid);

   if v_target_decision is not null then x.put('target_supply_decision',v_target_decision);end if;

   if v_target_supply is not null then x.put('target_supply',v_target_supply);end if;

   if v_uid is not null then

    if v_own_id is null then select RRL_STOCK_RESERVATION_SQ.nextval into v_id from dual;else v_id:=v_own_id;end if;

    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));

    RRL_STOCK_PLAN_HELPER.stock_closure(f,r,v_uid,rt.ARTICUL,v_cell,null);

    x.put('reservation_id',v_id);x.put('cell',v_cell);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(v_qty));x.put('base_uom',v_uom);x.put('uom_version',v_version);

   end if;

   a.append(x);

  end loop;

  v.put('wave_id',v_wave);v.put('warehouse',v_ware);v.put('tasks',a);p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;

 end;

 procedure execute_reserve(p_request clob,p_actor varchar2,p_result out clob) is

  d json_object_t:=json_object_t.parse(p_request);v json_object_t;x json_object_t;j json_object_t:=json_object_t();

  a json_array_t;v_plan clob;v_status varchar2(40);rt RRL_PICK_WAVE_REPLENISH_TASK%rowtype;

  v_qty number;v_id number;v_units clob;v_count number:=0;v_details json_object_t;v_produced date;v_expiry date;own RRL_STOCK_RESERVATION%rowtype;

 v_recovery_count number;v_mode varchar2(40);v_needed number;

 begin

  if RRL_HAS_WRIGHT(p_actor,'pick_wave_launch')!=1 and RRL_HAS_WRIGHT(p_actor,'pick_wave_release_reserves')!=1 then raise_application_error(-20882,'WAVE_RESERVATION_FORBIDDEN');end if;

  declare

 v_json_sql_1_1 varchar2(32767):=d.get_string('operation_id');

begin

select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_1_1;

end;

  v:=json_object_t.parse(v_plan).get_object('domain');a:=v.get_array('tasks');

  declare

 v_json_sql_2_1 number:=v.get_number('wave_id');

begin

select STATUS into v_status from RRL_PICK_WAVE where PICK_WAVE_ID=v_json_sql_2_1 for update;

end;

  if v_status in('CANCELLED','DONE','COMPLETED','CLOSED') then raise_application_error(-20886,'WAVE_NOT_OPEN');end if;

  for i in 0..a.get_size-1 loop

   x:=treat(a.get(i) as json_object_t);

   declare

 v_json_sql_3_1 number:=x.get_number('task_id');

begin

select * into rt from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_REPLENISH_TASK_ID=v_json_sql_3_1 for update;

end;

   if RRL_STOCK_REPL_ADMISSION.policy_signature(rt.PICK_WAVE_REPLENISH_TASK_ID)!=x.get_string('policy_signature') then raise_application_error(-20890,'CLOSURE_CHANGED: replenishment policy');end if;

   v_mode:=x.get_string('resolved_mode');

   if nvl(rt.SOURCE_RESERVATION_ID,-1)!=nvl(x.get_number('source_reservation_before'),-1) or signature(rt)!=x.get_string('signature') or rt.STATUS not in('RELEASED','QUEUED','WAIT_FREE_CELL','WAIT_MINIMAX') then raise_application_error(-20890,'CLOSURE_CHANGED: replenishment row');end if;

   v_needed:=null;

   if rt.PICK_TASK_ID is not null then

    v_needed:=RRL_STOCK_REPL_NEED.remaining_for_task(rt.PICK_TASK_ID,rt.TARGET_CELL_CODE);

    if RRL_STOCK_PLAN_HELPER.decimal_text(v_needed)!=x.get_string('needed_base') then raise_application_error(-20890,'CLOSURE_CHANGED: explicit picking target need');end if;

    update RRL_PICK_WAVE_REPLENISH_TASK set DEMAND_BASE_QTY=v_needed where PICK_WAVE_REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID;

   end if;

   if x.has('target_supply') then

    execute_target_supply(rt,x.get_object('target_supply'),v.get_number('warehouse'),p_actor);v_count:=v_count+1;

   elsif x.get_number('already_covered')=1 then

    update RRL_PICK_WAVE_REPLENISH_TASK set STATUS='CANCELLED',WAIT_REASON='Existing usable own target coverage satisfies this CASE task',

     UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID;

   elsif x.get('uid').is_null then

    declare

 v_json_sql_1_1 number:=x.get_number('capacity_wait');

 v_json_sql_1_2 number:=x.get_number('capacity_wait');

begin

update RRL_PICK_WAVE_REPLENISH_TASK set STATUS=case when v_json_sql_1_1=1 then 'WAIT_FREE_CELL' else 'FAILED' end,WAIT_REASON=case when v_json_sql_1_2=1 then 'Waiting for canonical pick-face capacity including open arrivals' else 'No eligible source stock' end,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID;

end;

   else

    v_qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));v_id:=x.get_number('reservation_id');

    RRL_STOCK_REPL_CAPACITY.assert_arrival(rt.PICK_WAVE_REPLENISH_TASK_ID,v_qty);

    RRL_STOCK_REPL_ADMISSION.assert_target(x.get_string('uid'),rt.TARGET_CELL_CODE,v.get_number('warehouse'),rt.ARTICUL);

    if rt.PICK_TASK_ID is not null then

     select count(*) into v_recovery_count from RRL_PICK_TASK pt join RRL_PICK_WAVE_TASK wt on wt.PICK_TASK_ID=pt.PICK_TASK_ID

      where pt.PICK_TASK_ID=rt.PICK_TASK_ID and wt.PICK_WAVE_ID=rt.PICK_WAVE_ID and pt.ARTICUL=rt.ARTICUL and pt.STATUS not in('DONE','CANCELLED','FAILED');

     if v_recovery_count=0 then raise_application_error(-20887,'REPLENISHMENT_PICK_DEMAND_IDENTITY_CONFLICT');end if;

    end if;

    RRL_STOCK_ELIGIBILITY.assert_source(x.get_string('uid'),x.get_string('cell'),v.get_number('warehouse'),case when x.get_number('own_reservation_id') is not null then least(v_qty,RRL_STOCK_MATH.quantity(x.get_string('own_qty'))) else v_qty end,

     rt.MIN_SHELF_LIFE_DAYS,rt.MIN_SHELF_LIFE_PERCENT,'REPLENISH',x.get_number('own_reservation_id'),rt.ARTICUL);

    if x.get('own_reservation_id').is_null then

    v_units:=RRL_WEIGHT_CHOICE_UNIT_READ.selected_units(rt.PICK_TASK_ID,x.get_string('uid'),x.get_string('cell'),v_qty);

    if v_units is null then v_units:=RRL_STOCK_UNIT_CORE.automatic_units(x.get_string('uid'),x.get_string('cell'),v_qty);end if;

    v_details:=json_object_t();v_details.put('pick_wave_id',v.get_number('wave_id'));

    v_details.put('reservation_scope',case when v_mode='FULL_PALLET' then 'PALLET' else 'QTY' end);

    if rt.PICK_TASK_ID is not null then

     for pt in(select CUSTOMER_ID,CUSTOMER_ORDER_ID,PICK_PLAN_ID,PICK_PLAN_LINE_ID from RRL_PICK_TASK where PICK_TASK_ID=rt.PICK_TASK_ID) loop

      v_details.put('customer_id',pt.CUSTOMER_ID);v_details.put('customer_order_id',pt.CUSTOMER_ORDER_ID);

      v_details.put('pick_plan_id',pt.PICK_PLAN_ID);v_details.put('pick_plan_line_id',pt.PICK_PLAN_LINE_ID);

     end loop;

    end if;

    select count(*) into v_recovery_count from RRL_CASE_PICK_SHORT sh where sh.REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID and sh.RECOVERY_STATE='WAIT_REPLENISHMENT';

    RRL_STOCK_RESERVE_CORE.create_hard(v_id,x.get_string('uid'),x.get_string('cell'),v_qty,x.get_string('base_uom'),x.get_number('uom_version'),

     'PICK_WAVE',v.get_number('wave_id'),

     case when rt.PICK_TASK_ID is not null then rt.PICK_TASK_ID else rt.PICK_WAVE_REPLENISH_TASK_ID end,

     case when rt.PICK_TASK_ID is not null then 'PICKING' else 'WAVE' end,p_actor,v_details.to_clob);

    RRL_STOCK_UNIT_CORE.reserve_units(x.get_string('uid'),x.get_string('cell'),v_id,v_qty,v_units);

    else

     select * into own from RRL_STOCK_RESERVATION where RESERVATION_ID=v_id for update;

     if own.SOURCE_DOC_TYPE!='PICK_WAVE' or own.SOURCE_DOC_ID!=v.get_number('wave_id') or own.SOURCE_LINE_ID!=rt.PICK_TASK_ID

      or own.RESERVATION_DOMAIN!='PICKING' or own.RESERVATION_KIND!='HARD' or own.STATUS not in('ACTIVE','ALLOCATED','PICKING')

      or own.UID_PALLET!=x.get_string('uid') or own.CELL!=x.get_string('cell') or RRL_STOCK_PLAN_HELPER.decimal_text(own.BASE_QTY)!=x.get_string('own_qty') then

      raise_application_error(-20890,'CLOSURE_CHANGED: own picking reserve');end if;

    end if;

    declare

 v_json_sql_4_1 varchar2(32767):=x.get_string('uid');

begin

select PRODUCED_DATE,EXPIRY_DATE into v_produced,v_expiry from RRL_PALLETS where UID_PALLET=v_json_sql_4_1;

end;

    declare

 v_json_sql_5_1 varchar2(32767):=x.get_string('uid');

 v_json_sql_5_2 varchar2(32767):=x.get_string('cell');

begin

update RRL_PICK_WAVE_REPLENISH_TASK set SOURCE_RESERVATION_ID=v_id,PALLET_UID=v_json_sql_5_1,SOURCE_CELL_CODE=v_json_sql_5_2,

     REPLENISHMENT_QTY_MODE=v_mode,DEMAND_BASE_QTY=case when v_needed is not null then v_needed else nvl(DEMAND_BASE_QTY,QTY) end,SOURCE_AVAILABLE_QTY=v_qty,SOURCE_PRODUCED_DATE=v_produced,SOURCE_EXPIRY_DATE=v_expiry,QTY=v_qty,WAIT_REASON=null,UPDATED_AT=sysdate,UPDATED_BY=p_actor

     where PICK_WAVE_REPLENISH_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID;

end;

    v_count:=v_count+1;

   end if;

  end loop;

  j.put('operation_id',d.get_string('operation_id'));j.put('wave_id',v.get_number('wave_id'));j.put('reserved_count',v_count);p_result:=j.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_STOCK_WAVE_FINISH_CMD as
 function snapshot_json(p_wave number) return clob is
  j json_object_t:=json_object_t();a json_array_t:=json_array_t();x json_object_t;
  v_status varchar2(40);v_kind varchar2(40);v_count number:=0;v_block number:=0;v_ship number;v_short number;v_pt number:=0;
  procedure item(p_kind varchar2,p_id varchar2,p_status varchar2,p_actor varchar2,p_reason varchar2,p_qty number default null) is
  begin
   v_count:=v_count+1;if v_count>1200 then raise_application_error(-20881,'WAVE_EXECUTION_SNAPSHOT_BOUND_1200');end if;
   x:=json_object_t();x.put('kind',p_kind);x.put('id',p_id);x.put('status',p_status);x.put('actor',p_actor);
   x.put('reason',p_reason);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(p_qty));a.append(x);
   if p_reason is not null then v_block:=v_block+1;end if;
  end;
 begin
  select STATUS,WAVE_KIND into v_status,v_kind from RRL_PICK_WAVE where PICK_WAVE_ID=p_wave;
  for pt in(select pt.* from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=wt.PICK_TASK_ID
   where wt.PICK_WAVE_ID=p_wave order by pt.PICK_TASK_ID) loop
   v_pt:=v_pt+1;if v_pt>200 then raise_application_error(-20881,'WAVE_EXECUTION_TASK_BOUND_200');end if;
   v_ship:=0;
   if nvl(pt.FACT_QTY,0)>0 then
    select count(*) into v_ship from RRL_CUSTOMER_ORDER_FULFILLMENT ff
     where ff.CUSTOMER_ORDER_ID=pt.CUSTOMER_ORDER_ID and ff.STATUS='SHIPPED' and ff.SHIPPED_OPERATION_ID is not null
      and (exists(select 1 from RRL_WAREHOUSE_TASK wh join RRL_PICK_WAVE_TASK wt on wt.PICK_WAVE_TASK_ID=wh.SOURCE_TASK_ID
        where wh.TASK_ID=ff.PICKED_WAREHOUSE_TASK_ID and wh.TASK_SOURCE='WAVE' and wh.SOURCE_DOC_ID=p_wave
         and wt.PICK_TASK_ID=pt.PICK_TASK_ID and wh.STATUS='DONE')
       or exists(select 1 from RRL_CASE_PICK_LINE cl join RRL_CASE_PICK_TASK ct on ct.CASE_PICK_TASK_ID=cl.CASE_PICK_TASK_ID
        where cl.PICK_TASK_ID=pt.PICK_TASK_ID and ct.PICK_WAVE_ID=p_wave and ff.PICKED_CASE_TASK_ID=ct.CASE_PICK_TASK_ID
         and ct.STATUS='SHIPPED' and cl.PICKED_QTY>0));
   end if;
   select nvl(sum(greatest(l.PLANNED_QTY-l.PICKED_QTY,0)),0) into v_short from RRL_CASE_PICK_LINE l
    where l.PICK_WAVE_ID=p_wave and l.PICK_TASK_ID=pt.PICK_TASK_ID and l.STATUS='SHORT_PICKED'
     and exists(select 1 from RRL_CASE_PICK_SHORT sh where sh.CASE_PICK_LINE_ID=l.CASE_PICK_LINE_ID
      and sh.STATUS='ACCEPTED' and sh.SHORT_QTY=l.PLANNED_QTY-l.PICKED_QTY and sh.APPROVED_BY is not null);
   item('PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(pt.PICK_TASK_ID),pt.STATUS,pt.ASSIGNED_TO,
    case when pt.STATUS not in('DONE','CANCELLED') then 'PICKING_PENDING'
     when pt.STATUS='CANCELLED' then 'CANCELLED_DEMAND_REQUIRES_RECONCILIATION'
     when nvl(pt.FACT_QTY,0)+v_short!=pt.QTY then 'FACT_OR_APPROVED_SHORT_INCOMPLETE'
     when nvl(pt.FACT_QTY,0)>0 and v_ship=0 then 'PHYSICAL_FULFILLMENT_OR_SHIPPING_PENDING' end,pt.FACT_QTY);
  end loop;
  for rt in(select * from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_ID=p_wave order by PICK_WAVE_REPLENISH_TASK_ID) loop
   item('REPLENISHMENT',RRL_STOCK_PLAN_HELPER.decimal_text(rt.PICK_WAVE_REPLENISH_TASK_ID),rt.STATUS,null,
    case when rt.STATUS not in('DONE','CANCELLED') then 'REPLENISHMENT_PENDING' end,case when rt.STATUS='DONE' then rt.QTY end);
  end loop;
  for wh in(select * from RRL_WAREHOUSE_TASK where TASK_SOURCE='WAVE' and SOURCE_DOC_ID=p_wave order by TASK_ID) loop
   item('WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(wh.TASK_ID),wh.STATUS,wh.ASSIGNED_TO,
    case when wh.STATUS not in('DONE','CANCELLED') then 'PHYSICAL_TASK_PENDING' end,wh.FACT_QTY);
  end loop;
  for ct in(select * from RRL_CASE_PICK_TASK where PICK_WAVE_ID=p_wave order by CASE_PICK_TASK_ID) loop
   item('CASE',RRL_STOCK_PLAN_HELPER.decimal_text(ct.CASE_PICK_TASK_ID),ct.STATUS,ct.ASSIGNED_TO,
    case when nvl(ct.PICKED_QTY,0)>0 and ct.STATUS!='SHIPPED' then 'CASE_CONTROL_OR_SHIPPING_PENDING'
     when nvl(ct.PICKED_QTY,0)=0 and ct.STATUS not in('CONTROLLED','READY_TO_SHIP','SHIPPED','CANCELLED') then 'EMPTY_CASE_DECISION_PENDING' end,ct.PICKED_QTY);
  end loop;
  for sr in(select * from RRL_STOCK_RESERVATION where SOURCE_DOC_TYPE='PICK_WAVE' and SOURCE_DOC_ID=p_wave
   and RESERVATION_KIND='HARD' and STATUS in('ACTIVE','ALLOCATED','PICKING') and BASE_QTY>0 order by RESERVATION_ID) loop
   item('HARD',RRL_STOCK_PLAN_HELPER.decimal_text(sr.RESERVATION_ID),sr.STATUS,null,'ACTIVE_WAVE_HARD_REMAINS',sr.BASE_QTY);
  end loop;
  j.put('wave_id',p_wave);j.put('status',v_status);j.put('kind',v_kind);j.put('items',a);j.put('blocking_count',v_block);
  j.put('ready',v_count>0 and v_block=0 and (v_pt>0 or v_kind='REPLENISHMENT') and v_status='LAUNCHED');
  j.put('completed',v_status='DONE');return j.to_clob;
 end;
 function closure_json(p_wave number,p_disposition varchar2)return clob is
  j json_object_t:=json_object_t.parse(snapshot_json(p_wave));defer json_object_t;
 begin
  if p_disposition='RETURNED_TO_PLANNING'then
   defer:=json_object_t.parse(RRL_WAVE_EXEC_ACCESS.deferred_snapshot_json(p_wave));j.put('deferred_decision',defer);
  elsif p_disposition='PARTIAL_SHIPPED_RETURNED'then
   defer:=json_object_t.parse(RRL_WAVE_EXEC_ACCESS.mixed_snapshot_json(p_wave));j.put('deferred_decision',defer);
  elsif p_disposition is not null then raise_application_error(-20881,'WAVE_DISPOSITION_UNSUPPORTED');end if;
  return j.to_clob;
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);v_wave number:=d.get_object('source').get_number('wave_id');
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();v json_object_t:=json_object_t();a json_array_t;x json_object_t;
  v_disposition varchar2(100):=d.get_object('metadata').get_string('disposition');s clob;v_kind varchar2(40);v_id varchar2(200);v_ff number:=0;
 begin
  s:=closure_json(v_wave,d.get_object('metadata').get_string('disposition'));a:=json_object_t.parse(s).get_array('items');
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(v_wave));
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);v_kind:=x.get_string('kind');v_id:=x.get_string('id');
   RRL_STOCK_PLAN_HELPER.row_key(r,case v_kind when 'PICK_TASK' then 'RRL_PICK_TASK' when 'REPLENISHMENT' then 'RRL_PICK_WAVE_REPLENISH_TASK'
    when 'WAREHOUSE_TASK' then 'RRL_WAREHOUSE_TASK' when 'CASE' then 'RRL_CASE_PICK_TASK' when 'HARD' then 'RRL_STOCK_RESERVATION' end,v_id);
  end loop;
  if d.get_object('metadata').get_string('disposition') in('RETURNED_TO_PLANNING','PARTIAL_SHIPPED_RETURNED')then
   for line in(select pl.PICK_PLAN_LINE_ID,pl.PICK_PLAN_ID,cr.CUSTOMER_ORDER_ROW_ID,cr.CUSTOMER_ORDER_ID
    from RRL_PICK_WAVE_ORDER wo join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_ID=wo.PICK_PLAN_ID
    join RRL_CUSTOMER_ORDER_ROW cr on cr.CUSTOMER_ORDER_ROW_ID=pl.CUSTOMER_ORDER_ROW_ID
    where wo.PICK_WAVE_ID=v_wave order by pl.PICK_PLAN_LINE_ID fetch first 201 rows only)loop
    v_ff:=v_ff+1;if v_ff>200 then raise_application_error(-20881,'WAVE_DEFER_DEMAND_BOUND_200');end if;
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(line.PICK_PLAN_ID));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_PLAN_LINE',RRL_STOCK_PLAN_HELPER.decimal_text(line.PICK_PLAN_LINE_ID));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(line.CUSTOMER_ORDER_ID));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_ROW',RRL_STOCK_PLAN_HELPER.decimal_text(line.CUSTOMER_ORDER_ROW_ID));
   end loop;v_ff:=0;
  end if;
  for ff in(select ff.FULFILLMENT_ID from RRL_CUSTOMER_ORDER_FULFILLMENT ff where
   (v_disposition in('RETURNED_TO_PLANNING','PARTIAL_SHIPPED_RETURNED')and exists(
    select 1 from RRL_PICK_WAVE_ORDER wo where wo.PICK_WAVE_ID=v_wave and wo.CUSTOMER_ORDER_ID=ff.CUSTOMER_ORDER_ID))
   or
   exists(select 1 from RRL_CASE_PICK_TASK ct where ct.CASE_PICK_TASK_ID=ff.PICKED_CASE_TASK_ID and ct.PICK_WAVE_ID=v_wave)
   or exists(select 1 from RRL_WAREHOUSE_TASK wh where wh.TASK_ID=ff.PICKED_WAREHOUSE_TASK_ID and wh.TASK_SOURCE='WAVE' and wh.SOURCE_DOC_ID=v_wave)
   order by ff.FULFILLMENT_ID fetch first 201 rows only) loop
   v_ff:=v_ff+1;if v_ff>200 then raise_application_error(-20881,'WAVE_FULFILLMENT_CLOSURE_BOUND_200');end if;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(ff.FULFILLMENT_ID));
  end loop;
  v.put('wave_id',v_wave);v.put('signature',rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256)));
  p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;j json_object_t;v_plan clob;s clob;
  v_op varchar2(100):=d.get_string('operation_id');v_wave number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'pick_wave_launch')!=1 then raise_application_error(-20882,'WAVE_FINISH_FORBIDDEN');end if;
  select RESOLVED_PLAN_JSON into v_plan from RRL_STOCK_OPERATION where OPERATION_ID=v_op;
  v:=json_object_t.parse(v_plan).get_object('domain');v_wave:=v.get_number('wave_id');s:=closure_json(v_wave,d.get_object('metadata').get_string('disposition'));
  if rawtohex(sys.dbms_crypto.hash(s,sys.dbms_crypto.hash_sh256))!=v.get_string('signature') then
   raise_application_error(-20890,'CLOSURE_CHANGED: wave execution');end if;
  j:=json_object_t.parse(s);
  RRL_WAVE_EXEC_ACCESS.assert_command(p_request,p_actor);
  if d.get_object('metadata').get_string('disposition')='RETURNED_TO_PLANNING'then
   if not j.get_object('deferred_decision').get_boolean('eligible')then
    raise_application_error(-20886,'WAVE_DEFER_NOT_ELIGIBLE:'||j.get_object('deferred_decision').get_string('reason'));end if;
   j.put('completion_outcome','UNFULFILLED_RETURNED_TO_PLANNING');
   j.put('order_fulfilled',false);j.put('physical_stock_changed',false);
  elsif d.get_object('metadata').get_string('disposition')='PARTIAL_SHIPPED_RETURNED'then
   if not j.get_object('deferred_decision').get_boolean('eligible')then
    raise_application_error(-20886,'WAVE_MIXED_NOT_ELIGIBLE:'||j.get_object('deferred_decision').get_string('reason'));end if;
   declare items json_array_t:=j.get_array('items');entry json_object_t;kind varchar2(40);status varchar2(40);reason varchar2(100);
   begin
    for i in 0..items.get_size-1 loop
     entry:=treat(items.get(i)as json_object_t);kind:=entry.get_string('kind');status:=entry.get_string('status');reason:=entry.get_string('reason');
     if reason is not null and not(
       kind='PICK_TASK'and status='CANCELLED'and reason='CANCELLED_DEMAND_REQUIRES_RECONCILIATION'
       or kind='CASE'and status='CANCELLED'and reason in('CASE_CONTROL_OR_SHIPPING_PENDING','EMPTY_CASE_DECISION_PENDING'))then
      raise_application_error(-20886,'WAVE_MIXED_EXECUTION_PENDING:'||reason);end if;
    end loop;
   end;
   j.put('completion_outcome','MIXED_SHIPPED_AND_RETURNED');
   j.put('order_fulfillment_changed',false);j.put('physical_stock_changed',false);
  else
   if not j.get_boolean('ready') then raise_application_error(-20886,'WAVE_EXECUTION_OR_SHIPPING_PENDING');end if;
   j.put('completion_outcome','PHYSICAL_EXECUTION_COMPLETE');
  end if;
  update RRL_PICK_WAVE set STATUS='DONE',UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_ID=v_wave and STATUS='LAUNCHED';
  if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: wave finish');end if;
  j.put('operation_id',v_op);j.put('status','DONE');j.put('completed',true);j.put('ready',false);p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_WAVE_LAUNCH_CMD as
 function signature(p RRL_PICK_RESERVATION%rowtype) return varchar2 is j json_object_t:=json_object_t();
 begin
  j.put('id',p.PICK_RESERVATION_ID);j.put('plan',p.PICK_PLAN_ID);j.put('line',p.PICK_PLAN_LINE_ID);j.put('task',p.PICK_TASK_ID);
  j.put('uid',p.PALLET_UID);j.put('cell',p.SOURCE_CELL_CODE);j.put('article',p.ARTICUL);j.put('qty',RRL_STOCK_PLAN_HELPER.decimal_text(p.RESERVED_QTY));
  j.put('status',p.RESERVATION_STATUS);j.put('level',p.RESERVATION_LEVEL);
  j.put('customer',p.CUSTOMER_ID);j.put('order',p.CUSTOMER_ORDER_ID);
  return rawtohex(sys.dbms_crypto.hash(j.to_clob,sys.dbms_crypto.hash_sh256));
 end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);direct_holds clob;v_wave number;v_ware number;v_id number;v_uom varchar2(20);v_ver number;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();a json_array_t:=json_array_t();pools json_array_t;v json_object_t:=json_object_t();x json_object_t;
 begin
  v_wave:=d.get_object('source').get_number('wave_id');select WARE_ID into v_ware from RRL_PICK_WAVE where PICK_WAVE_ID=v_wave;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(v_wave));
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  for o in(select * from RRL_PICK_WAVE_ORDER where PICK_WAVE_ID=v_wave and STATUS='ACTIVE' order by PICK_WAVE_ORDER_ID) loop
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(o.PICK_WAVE_ORDER_ID));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(o.PICK_PLAN_ID));
   for t in(select PICK_TASK_ID from RRL_PICK_TASK where PICK_PLAN_ID=o.PICK_PLAN_ID order by PICK_TASK_ID) loop
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.PICK_TASK_ID));
   end loop;
  end loop;
  for pr in(select pr.* from RRL_PICK_RESERVATION pr join RRL_PICK_WAVE_ORDER wo on wo.PICK_PLAN_ID=pr.PICK_PLAN_ID
   where wo.PICK_WAVE_ID=v_wave and wo.STATUS='ACTIVE' and pr.RESERVATION_STATUS='ACTIVE' and pr.RESERVATION_LEVEL='SOFT' order by pr.PICK_RESERVATION_ID) loop
   if a.get_size>=200 then raise_application_error(-20881,'WAVE_LAUNCH_BATCH_BOUND');end if;
   if pr.PALLET_UID is null or pr.SOURCE_CELL_CODE is null or pr.RESERVED_QTY<=0 then raise_application_error(-20884,'WAVE_SOURCE_IDENTITY_REQUIRED');end if;
   select BASE_UOM into v_uom from RRL_REMAINS where UID_POLETA=pr.PALLET_UID and CELL=pr.SOURCE_CELL_CODE;
   select max(POLICY_VERSION) into v_ver from RRL_STOCK_UOM_CONVERSION where ARTICUL=pr.ARTICUL and INPUT_UOM=v_uom and BASE_UOM=v_uom and NUMERATOR=1 and DENOMINATOR=1;
   if v_ver is null then raise_application_error(-20868,'WAVE_BASE_POLICY_REQUIRED');end if;
   select RRL_STOCK_RESERVATION_SQ.nextval into v_id from dual;
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(pr.PICK_RESERVATION_ID));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(v_id));
   RRL_STOCK_PLAN_HELPER.stock_closure(f,r,pr.PALLET_UID,pr.ARTICUL,pr.SOURCE_CELL_CODE,null);
   x:=json_object_t();x.put('projection_id',pr.PICK_RESERVATION_ID);x.put('reservation_id',v_id);x.put('signature',signature(pr));
   x.put('uom',v_uom);x.put('version',v_ver);a.append(x);
  end loop;
  RRL_DIRECT_RECEIVING_PICK.compile_holds(v_wave,r,direct_holds);v.put('direct_putaway_holds',json_array_t.parse(direct_holds));
  if a.get_size=0 then raise_application_error(-20886,'WAVE_NO_SOFT_RESERVATIONS');end if;
  RRL_STOCK_POOL_CMD.compile_wave_pool(v_ware,v_wave,r,pools);v.put('pools',pools);
  v.put('wave',v_wave);v.put('warehouse',v_ware);v.put('reservations',a);p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);v json_object_t;x json_object_t;j json_object_t:=json_object_t();details json_object_t;
  a json_array_t;plan clob;status varchar2(30);cnt number;ware number;ready number;units clob;pr RRL_PICK_RESERVATION%rowtype;
 begin
  if RRL_HAS_WRIGHT(p_actor,'pick_wave_launch')!=1 then raise_application_error(-20882,'WAVE_LAUNCH_FORBIDDEN');end if;
  declare
 v_json_sql_1_1 varchar2(32767):=d.get_string('operation_id');
begin
select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=v_json_sql_1_1;
end;v:=json_object_t.parse(plan).get_object('domain');a:=v.get_array('reservations');
  declare
 v_json_sql_2_1 number:=v.get_number('wave');
begin
select STATUS,WARE_ID into status,ware from RRL_PICK_WAVE where PICK_WAVE_ID=v_json_sql_2_1 for update;
end;
  if status not in('DRAFT','PREVIEW') or ware!=v.get_number('warehouse') then raise_application_error(-20886,'WAVE_NOT_LAUNCHABLE');end if;
  declare
 v_json_sql_3_1 number:=v.get_number('wave');
begin
select count(*) into cnt from RRL_PICK_RESERVATION pr join RRL_PICK_WAVE_ORDER wo on wo.PICK_PLAN_ID=pr.PICK_PLAN_ID
   where wo.PICK_WAVE_ID=v_json_sql_3_1 and wo.STATUS='ACTIVE' and pr.RESERVATION_STATUS='ACTIVE' and pr.RESERVATION_LEVEL='SOFT';
end;
  if cnt!=a.get_size then raise_application_error(-20890,'CLOSURE_CHANGED: wave sources');end if;
  for i in 0..a.get_size-1 loop
   x:=treat(a.get(i) as json_object_t);declare
 v_json_sql_4_1 number:=x.get_number('projection_id');
begin
select * into pr from RRL_PICK_RESERVATION where PICK_RESERVATION_ID=v_json_sql_4_1 for update;
end;
   if signature(pr)!=x.get_string('signature') then raise_application_error(-20890,'CLOSURE_CHANGED: wave reservation');end if;
   RRL_STOCK_LOCATION_CORE.assert_ordinary(pr.SOURCE_CELL_CODE,ware,'SOURCE');
   RRL_STOCK_ELIGIBILITY.assert_source(pr.PALLET_UID,pr.SOURCE_CELL_CODE,ware,pr.RESERVED_QTY,null,null,'ALLOCATE',null,pr.ARTICUL);
   select nvl(br.IS_SHIPMENT_ALLOWED,1) into ready from RRL_PALLETS pp left join RRL_PROD_BATCH_READY_V br on br.PROD_BATCH_ID=pp.PROD_BATCH_ID where pp.UID_PALLET=pr.PALLET_UID;
   if ready!=1 then raise_application_error(-20886,'WAVE_SOURCE_REGULATORY_NOT_READY');end if;
   units:=RRL_WEIGHT_CHOICE_UNIT_READ.selected_units(pr.PICK_TASK_ID,pr.PALLET_UID,pr.SOURCE_CELL_CODE,pr.RESERVED_QTY);
   if units is null then units:=RRL_STOCK_UNIT_CORE.automatic_units(pr.PALLET_UID,pr.SOURCE_CELL_CODE,pr.RESERVED_QTY);end if;
   details:=json_object_t();details.put('reservation_scope','QTY');details.put('pick_wave_id',v.get_number('wave'));
   details.put('pick_plan_id',pr.PICK_PLAN_ID);details.put('pick_plan_line_id',pr.PICK_PLAN_LINE_ID);
   details.put('customer_order_id',pr.CUSTOMER_ORDER_ID);details.put('customer_id',pr.CUSTOMER_ID);
   RRL_STOCK_RESERVE_CORE.create_hard(x.get_number('reservation_id'),pr.PALLET_UID,pr.SOURCE_CELL_CODE,pr.RESERVED_QTY,x.get_string('uom'),x.get_number('version'),
    'PICK_WAVE',v.get_number('wave'),pr.PICK_TASK_ID,'PICKING',p_actor,details.to_clob);
   RRL_STOCK_UNIT_CORE.reserve_units(pr.PALLET_UID,pr.SOURCE_CELL_CODE,x.get_number('reservation_id'),pr.RESERVED_QTY,units);
  end loop;
  RRL_DIRECT_RECEIVING_PICK.apply_holds(v.get_array('direct_putaway_holds').to_clob,p_actor);
  RRL_STOCK_POOL_CMD.consume_wave_pool(v.get_array('pools'),p_actor);
  RRL_PICK_WAVE_META.launch_wave(v.get_number('wave'),p_actor);
  j.put('operation_id',d.get_string('operation_id'));j.put('wave_id',v.get_number('wave'));j.put('reserved_count',a.get_size);j.put('status','LAUNCHED');p_result:=j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_WAVE_PICK_CMD as
 function signature(p_json clob) return varchar2 is
 begin return rawtohex(sys.dbms_crypto.hash(p_json,sys.dbms_crypto.hash_sh256));end;
 procedure compile_command(p_request clob,p_operation varchar2,p_policies out clob,p_resources out clob,p_domain out clob) is
  d json_object_t:=json_object_t.parse(p_request);snapshot clob;j json_object_t;v json_object_t:=json_object_t();
  tasks json_array_t;repl json_array_t;owned json_array_t;t json_object_t;sr json_object_t;
  f json_array_t:=json_array_t();r json_array_t:=json_array_t();wave number;
 begin
  wave:=d.get_object('source').get_number('wave_id');snapshot:=RRL_STOCK_WAVE_READY.snapshot_json(wave);j:=json_object_t.parse(snapshot);
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',p_operation);RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(wave));
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STOCK.OUTBOX:'||rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(p_operation,'AL32UTF8'),sys.dbms_crypto.hash_sh256)));
  tasks:=j.get_array('tasks');
  for i in 0..tasks.get_size-1 loop
   t:=treat(tasks.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.get_number('pick_task_id')));
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.get_number('wave_task_id')));
   RRL_STOCK_PLAN_HELPER.fence(f,'SKU',t.get_string('article'));
   if t.get_string('cell') is not null then RRL_STOCK_PLAN_HELPER.fence(f,'CELL',t.get_string('cell'));end if;
   owned:=t.get_array('reservations');
   for k in 0..owned.get_size-1 loop
    sr:=treat(owned.get(k) as json_object_t);
    RRL_STOCK_PLAN_HELPER.stock_closure(f,r,sr.get_string('uid'),sr.get_string('article'),sr.get_string('cell'),null);
   end loop;
  end loop;
  repl:=j.get_array('open_replenishments');
  for i in 0..repl.get_size-1 loop
   t:=treat(repl.get(i) as json_object_t);
   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.get_number('replenishment_id')));
   if t.get_number('warehouse_task_id') is not null then RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(t.get_number('warehouse_task_id')));end if;
  end loop;
  v.put('wave_id',wave);v.put('signature',signature(snapshot));p_domain:=v.to_clob;p_policies:=f.to_clob;p_resources:=r.to_clob;
 end;
 procedure execute_command(p_request clob,p_actor varchar2,p_result out clob) is
  d json_object_t:=json_object_t.parse(p_request);plan clob;v json_object_t;snapshot clob;j json_object_t;
  wave number;op varchar2(100);w RRL_PICK_WAVE%rowtype;rows json_array_t;rowdata json_object_t;row_id number;
 begin
  if RRL_HAS_WRIGHT(p_actor,'pick_wave_launch')!=1 then raise_application_error(-20882,'WAVE_PICK_RELEASE_FORBIDDEN');end if;
  op:=d.get_string('operation_id');select RESOLVED_PLAN_JSON into plan from RRL_STOCK_OPERATION where OPERATION_ID=op;
  v:=json_object_t.parse(plan).get_object('domain');wave:=v.get_number('wave_id');
  select * into w from RRL_PICK_WAVE where PICK_WAVE_ID=wave for update;
  if w.STATUS!='LAUNCHED' or w.STATUS is null then raise_application_error(-20886,'WAVE_NOT_LAUNCHED');end if;
  if w.PICK_RELEASED_AT is null then
   snapshot:=RRL_STOCK_WAVE_READY.snapshot_json(wave);
   if signature(snapshot)!=v.get_string('signature') then raise_application_error(-20890,'CLOSURE_CHANGED: wave picking coverage');end if;
   j:=json_object_t.parse(snapshot);
   if not j.get_boolean('ready') then raise_application_error(-20886,'WAVE_PICK_COVERAGE_OR_REPLENISHMENT_PENDING');end if;
   rows:=j.get_array('open_replenishments');
   for i in 0..rows.get_size-1 loop
    rowdata:=treat(rows.get(i) as json_object_t);
    if rowdata.get_boolean('can_cancel_before_release') then
     row_id:=rowdata.get_number('replenishment_id');
     RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_PICK_WAVE_REPLENISH_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(row_id)));
     update RRL_PICK_WAVE_REPLENISH_TASK set STATUS='CANCELLED',
      WAIT_REASON='Actual eligible owned stock covers selected demand; no physical source was allocated',
      UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_REPLENISH_TASK_ID=row_id and SOURCE_RESERVATION_ID is null;
     if sql%rowcount!=1 then raise_application_error(-20890,'CLOSURE_CHANGED: covered replenishment');end if;
    end if;
   end loop;
   update RRL_PICK_WAVE set PICK_RELEASED_AT=systimestamp,PICK_RELEASED_BY=p_actor,PICK_RELEASE_OPERATION_ID=op where PICK_WAVE_ID=wave;
  end if;
  p_result:=RRL_STOCK_WAVE_READY.snapshot_json(wave);
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_WAVE_READY as
 procedure assert_released(p_wave number) is n number;
 begin
  select count(*) into n from RRL_PICK_WAVE where PICK_WAVE_ID=p_wave and STATUS='LAUNCHED' and PICK_RELEASED_AT is not null;
  if n!=1 then raise_application_error(-20886,'WAVE_PICK_RELEASE_REQUIRED');end if;
 end;
 function snapshot_json(p_wave number) return clob is
  w RRL_PICK_WAVE%rowtype;j json_object_t:=json_object_t();tasks json_array_t:=json_array_t();
  repl json_array_t:=json_array_t();owned json_array_t;entry json_object_t;x json_object_t;
  missing number;covered number;needed number;v_cell varchar2(60);v_reason varchar2(100);v_base varchar2(20);
  v_ready boolean:=true;v_total number:=0;v_hard_count number:=0;
 begin
  select * into w from RRL_PICK_WAVE where PICK_WAVE_ID=p_wave;
  if w.STATUS!='LAUNCHED' or w.STATUS is null then v_ready:=false;end if;
  for rt in(select rt.*,wh.TASK_ID WH_TASK_ID,wh.STATUS WH_STATUS,wh.ASSIGNED_TO,wh.RESOURCE_ID
   from RRL_PICK_WAVE_REPLENISH_TASK rt left join RRL_WAREHOUSE_TASK wh
    on wh.TASK_SOURCE='WAVE' and wh.TASK_TYPE='REPLENISHMENT' and wh.SOURCE_DOC_ID=rt.PICK_WAVE_ID
    and wh.SOURCE_TASK_ID=rt.PICK_WAVE_REPLENISH_TASK_ID and wh.PARENT_TASK_ID is null
   where rt.PICK_WAVE_ID=p_wave and (rt.STATUS is null or rt.STATUS not in('DONE','CANCELLED'))
   order by rt.PICK_WAVE_REPLENISH_TASK_ID,wh.TASK_ID fetch first 201 rows only) loop
   if repl.get_size>=200 then raise_application_error(-20881,'WAVE_READY_REPL_BOUND');end if;
   x:=json_object_t();x.put('replenishment_id',rt.PICK_WAVE_REPLENISH_TASK_ID);x.put('status',rt.STATUS);
   x.put('article',rt.ARTICUL);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(rt.QTY));
   x.put('demand_base',RRL_STOCK_PLAN_HELPER.decimal_text(rt.DEMAND_BASE_QTY));x.put('target',rt.TARGET_CELL_CODE);
   x.put('warehouse_task_id',rt.WH_TASK_ID);x.put('warehouse_task_status',rt.WH_STATUS);
   x.put('assigned_to',rt.ASSIGNED_TO);x.put('resource_id',rt.RESOURCE_ID);x.put('reason',rt.WAIT_REASON);
   x.put('source_reservation_id',rt.SOURCE_RESERVATION_ID);repl.append(x);
  end loop;
  for t in(select pt.*,wt.PICK_WAVE_TASK_ID from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=wt.PICK_TASK_ID
   where wt.PICK_WAVE_ID=p_wave and wt.TASK_TYPE in('CASE_PICK','FULL_PALLET')
    and nvl(wt.STATUS,'?')!='CANCELLED' and nvl(pt.STATUS,'?')!='CANCELLED'
   order by wt.PICK_WAVE_TASK_ID fetch first 201 rows only) loop
   if tasks.get_size>=200 then raise_application_error(-20881,'WAVE_READY_TASK_BOUND');end if;
   v_total:=v_total+1;needed:=greatest(nvl(t.QTY,0)-nvl(t.FACT_QTY,0),0);
   v_cell:=t.SOURCE_CELL_CODE;covered:=0;v_base:=null;owned:=json_array_t();
   if t.TASK_TYPE='CASE_PICK' then
    select nvl(max(CELL_CODE),v_cell) into v_cell from RRL_CASE_PICK_LINE
     where PICK_TASK_ID=t.PICK_TASK_ID and PICK_WAVE_ID=p_wave and STATUS!='CANCELLED';
   end if;
   for sr in(select sr.*,s.REMAIN,s.STOCK_VERSION,s.HARD_RESERVED_BASE
    from RRL_STOCK_RESERVATION sr left join RRL_REMAINS s on s.UID_POLETA=sr.UID_PALLET and s.CELL=sr.CELL
    where sr.SOURCE_DOC_TYPE='PICK_WAVE' and sr.SOURCE_DOC_ID=p_wave and sr.SOURCE_LINE_ID=t.PICK_TASK_ID
     and sr.ARTICUL=t.ARTICUL and sr.RESERVATION_KIND='HARD' and sr.STATUS in('ACTIVE','ALLOCATED','PICKING')
     and not exists(select 1 from RRL_CASE_CARRIER_LOT h where h.LOT_UID=sr.UID_PALLET)
    order by sr.RESERVATION_ID fetch first 501 rows only) loop
    v_hard_count:=v_hard_count+1;if v_hard_count>500 then raise_application_error(-20881,'WAVE_READY_HARD_BOUND');end if;
    v_reason:=RRL_STOCK_ELIGIBILITY.reason(sr.UID_PALLET,sr.CELL,w.WARE_ID,sr.BASE_QTY,null,null,
      case when t.TASK_TYPE='CASE_PICK' then 'PICK' else 'ALLOCATE' end,sr.RESERVATION_ID,t.ARTICUL);
    if sr.CELL!=v_cell or v_cell is null then v_reason:='PICK_TARGET_RESERVATION_REQUIRED';end if;
    if v_base is not null and v_base!=sr.BASE_UOM then v_reason:='PICK_BASE_UOM_CONFLICT';end if;
    if v_reason is null then covered:=covered+sr.BASE_QTY;v_base:=sr.BASE_UOM;end if;
    x:=json_object_t();x.put('reservation_id',sr.RESERVATION_ID);x.put('uid',sr.UID_PALLET);
    x.put('cell',sr.CELL);x.put('article',sr.ARTICUL);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(sr.BASE_QTY));
    x.put('base_uom',sr.BASE_UOM);x.put('stock_version',sr.STOCK_VERSION);x.put('physical',RRL_STOCK_PLAN_HELPER.decimal_text(sr.REMAIN));
    x.put('hard',RRL_STOCK_PLAN_HELPER.decimal_text(sr.HARD_RESERVED_BASE));x.put('reason',v_reason);owned.append(x);
   end loop;
   missing:=greatest(needed-covered,0);if missing>0 or t.QTY is null or t.QTY<=0 then v_ready:=false;end if;
   entry:=json_object_t();entry.put('pick_task_id',t.PICK_TASK_ID);entry.put('wave_task_id',t.PICK_WAVE_TASK_ID);
   entry.put('article',t.ARTICUL);entry.put('task_type',t.TASK_TYPE);entry.put('status',t.STATUS);entry.put('cell',v_cell);
   entry.put('required_base',RRL_STOCK_PLAN_HELPER.decimal_text(needed));entry.put('covered_base',RRL_STOCK_PLAN_HELPER.decimal_text(covered));
   entry.put('missing_base',RRL_STOCK_PLAN_HELPER.decimal_text(missing));entry.put('base_uom',v_base);entry.put('reservations',owned);tasks.append(entry);
  end loop;
  if v_total=0 then v_ready:=false;end if;
  for i in 0..repl.get_size-1 loop
   x:=treat(repl.get(i) as json_object_t);
   declare v_covered boolean:=false;v_cancel boolean:=false;t json_object_t;begin
    if x.get_number('source_reservation_id') is null and
      (x.get_number('warehouse_task_id') is null or x.get_string('warehouse_task_status') in('DONE','CANCELLED')) then
     for k in 0..tasks.get_size-1 loop
      t:=treat(tasks.get(k) as json_object_t);
      if t.get_string('article')=x.get_string('article') and t.get_string('cell')=x.get_string('target')
       and t.get_string('missing_base')='0' then v_covered:=true;end if;
     end loop;
     v_cancel:=v_covered;
    end if;
    x.put('can_cancel_before_release',v_cancel);repl.put(i,x,true);
    if not v_cancel then v_ready:=false;end if;
   end;
  end loop;
  j.put('wave_id',p_wave);j.put('warehouse',w.WARE_ID);j.put('status',w.STATUS);
  j.put('released_at',to_char(w.PICK_RELEASED_AT,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
  j.put('released_by',w.PICK_RELEASED_BY);j.put('release_operation_id',w.PICK_RELEASE_OPERATION_ID);
  j.put('ready',v_ready);j.put('tasks',tasks);j.put('open_replenishments',repl);return j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STOCK_WRITE_GUARD as
 function enforcement_required return boolean is v_state varchar2(20);
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is not null then return true;end if;
  select STATE into v_state from RRL_STOCK_RELEASE where RELEASE_ID=1;
  return v_state!='PREPARED';
 end;
 procedure require_effect(p_kind varchar2,p_uid varchar2 default null,p_cell varchar2 default null,p_row_id number default null) is v_tx varchar2(100);
 begin
  v_tx:=dbms_transaction.local_transaction_id(false);
  if v_tx is null or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is null or
   sys_context('RRL_STOCK_WRITE_CTX','TX_ID') is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=v_tx or
   sys_context('RRL_STOCK_WRITE_CTX','EFFECT') is null or sys_context('RRL_STOCK_WRITE_CTX','EFFECT')!=p_kind then
   raise_application_error(-20863,'DIRECT_STOCK_WRITE_FORBIDDEN');end if;
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('RELEASE','STOCK'),4);
  if p_uid is not null then RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));end if;
  if p_kind in('STOCK','JOURNAL') and
   (p_uid is null or p_cell is null or sys_context('RRL_STOCK_WRITE_CTX','EFFECT_UID') is null or sys_context('RRL_STOCK_WRITE_CTX','EFFECT_CELL') is null or sys_context('RRL_STOCK_WRITE_CTX','EFFECT_UID')!=p_uid or
    sys_context('RRL_STOCK_WRITE_CTX','EFFECT_CELL')!=p_cell) then raise_application_error(-20863,'STOCK_EFFECT_KEY_CONFLICT');end if;
  if p_kind='RESERVATION' then
   if p_row_id is null or sys_context('RRL_STOCK_WRITE_CTX','EFFECT_ROW_ID') is null or
    sys_context('RRL_STOCK_WRITE_CTX','EFFECT_ROW_ID')!=RRL_STOCK_PLAN_HELPER.decimal_text(p_row_id) then
    raise_application_error(-20863,'RESERVATION_EFFECT_KEY_CONFLICT');end if;
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STOCK_RESERVATION',RRL_STOCK_PLAN_HELPER.decimal_text(p_row_id)));
  end if;
 end;
 procedure require_unit(p_key varchar2,p_uid varchar2) is
 begin
  if p_key is null or p_uid is null then raise_application_error(-20884,'UNIT_BINDING_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(60,RRL_STOCK_LOCK_API.resource_key('UNIT',p_key));
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
 end;
end;
/


CREATE OR REPLACE package body RRL_STORE_ACCESS_RULES as
 procedure check_addresses(p_vehicle number,p_addresses clob,p_complete number,p_result out clob)is
  profile json_object_t;physical json_object_t;outer_height number;outer_length number;
  result json_object_t:=json_object_t();rules json_array_t:=json_array_t();rule_value json_object_t;
  missing json_array_t:=json_array_t();profile_read boolean:=false;ready boolean:=false;n number:=0;
 begin
  if p_complete is null or p_complete not in(0,1)then raise_application_error(-20886,'STORE_ACCESS_COMPLETENESS_REQUIRED');end if;
  for r in(select cfg.STORE_ADDR,cfg.PROFILE_VERSION,cfg.MAX_VEHICLE_OUTER_HEIGHT_MM height_limit,
    cfg.MAX_VEHICLE_OUTER_LENGTH_MM length_limit,case when a.ADDR is null then 1 else nvl(a.DELETED3,0)end deleted
    from json_table(p_addresses,'$[*]'columns(address varchar2(255)path '$'))inputs
    join RRL_STORE_PROFILE cfg on cfg.STORE_ADDR=inputs.address
    left join RRL_ADDR a on a.ADDR=cfg.STORE_ADDR
    where cfg.MAX_VEHICLE_OUTER_HEIGHT_MM is not null or cfg.MAX_VEHICLE_OUTER_LENGTH_MM is not null
    order by cfg.STORE_ADDR fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20886,'STORE_ACCESS_ADDRESS_BOUND_200');end if;
   if r.deleted!=0 then raise_application_error(-20886,'STORE_ACCESS_ADDRESS_INACTIVE');end if;
   if not profile_read then
    profile:=json_object_t.parse(RRL_VEHICLE_PROFILE_API.describe_profile(p_vehicle));profile_read:=true;
    ready:=nvl(profile.get_string('state'),'~')='READY';
    if ready then physical:=profile.get_object('profile');outer_height:=physical.get_number('outer_height_mm');outer_length:=physical.get_number('outer_length_mm');end if;
   end if;
   rule_value:=json_object_t();rule_value.put('address',r.STORE_ADDR);rule_value.put('profile_version',r.PROFILE_VERSION);
   rule_value.put('max_vehicle_outer_height_mm',r.height_limit);rule_value.put('max_vehicle_outer_length_mm',r.length_limit);rules.append(rule_value);
   if not ready or(r.height_limit is not null and outer_height is null)or(r.length_limit is not null and outer_length is null)then
    if p_complete=1 then raise_application_error(-20886,'STORE_ACCESS_CURRENT_OUTER_DIMENSIONS_REQUIRED: '||substr(r.STORE_ADDR,1,255));end if;
    missing.append(r.STORE_ADDR);
   end if;
   if ready then
    if r.height_limit is not null and outer_height>r.height_limit then raise_application_error(-20886,'STORE_ACCESS_OUTER_HEIGHT_EXCEEDED: '||substr(r.STORE_ADDR,1,255));end if;
    if r.length_limit is not null and outer_length>r.length_limit then raise_application_error(-20886,'STORE_ACCESS_OUTER_LENGTH_EXCEEDED: '||substr(r.STORE_ADDR,1,255));end if;
   end if;
  end loop;
  result.put('vehicle_id',p_vehicle);result.put('rules',rules);result.put('missing_dimension_addresses',missing);
  result.put('requires_outer_dimensions',n>0);result.put('complete',missing.get_size=0);
  if profile_read then result.put('fleet_profile_version',profile.get_number('version'));result.put('fleet_profile_state',profile.get_string('state'));result.put('fleet_base_hash',profile.get_string('base_hash'));end if;
  result.put('outer_height_mm',outer_height);result.put('outer_length_mm',outer_length);p_result:=result.to_clob;
 end;
 procedure check_sts(p_vehicle number,p_sts clob,p_complete number,p_result out clob)is
  inputs json_array_t:=json_array_t.parse(p_sts);addresses json_array_t:=json_array_t();element_value json_element_t;
 begin
  if inputs.get_size>200 then raise_application_error(-20886,'STORE_ACCESS_ST_BOUND_200');end if;
  if inputs.get_size=0 then check_addresses(p_vehicle,addresses.to_clob,p_complete,p_result);return;end if;
  for i in 0..inputs.get_size-1 loop
   element_value:=inputs.get(i);
   if not element_value.is_string then raise_application_error(-20886,'STORE_ACCESS_ST_NUMBER_REQUIRED');end if;
   if inputs.get_string(i)is null or length(inputs.get_string(i))>100 then raise_application_error(-20886,'STORE_ACCESS_ST_NUMBER_REQUIRED');end if;
  end loop;
  for r in(select /*+ leading(inputs) use_nl(p) index(p) */ distinct p.ADDR from json_table(p_sts,'$[*]'columns(st_number varchar2(100)path '$'))inputs
    join RRL_SBORKA_PALLETS p on p.ST_NUMBER=inputs.st_number where p.ADDR is not null
    order by p.ADDR fetch first 201 rows only)loop
   if addresses.get_size>=200 then raise_application_error(-20886,'STORE_ACCESS_ADDRESS_BOUND_200');end if;addresses.append(r.ADDR);
  end loop;
  check_addresses(p_vehicle,addresses.to_clob,p_complete,p_result);
 end;
 procedure assert_members(p_vehicle number,p_members clob)is
  inputs json_array_t:=json_array_t.parse(p_members);addresses json_array_t:=json_array_t();element_value json_element_t;member_id number;result clob;n number;
 begin
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);
  if inputs.get_size<1 or inputs.get_size>200 then raise_application_error(-20886,'STORE_ACCESS_MEMBER_BOUND_200');end if;
  for i in 0..inputs.get_size-1 loop
   element_value:=inputs.get(i);if not element_value.is_number then raise_application_error(-20886,'STORE_ACCESS_MEMBER_ID_REQUIRED');end if;
   member_id:=inputs.get_number(i);if member_id is null or member_id<1 or member_id!=trunc(member_id)then raise_application_error(-20886,'STORE_ACCESS_MEMBER_ID_REQUIRED');end if;
  end loop;
  select /*+ leading(inputs) use_nl(p) index(p) */ count(*)into n from json_table(p_members,'$[*]'columns(id number path '$'))inputs
   left join RRL_SBORKA_PALLETS p on p.ID=inputs.id where p.ID is null;
  if n>0 then raise_application_error(-20886,'STORE_ACCESS_CURRENT_MEMBER_REQUIRED');end if;
  for r in(select distinct p.ADDR from json_table(p_members,'$[*]'columns(id number path '$'))inputs
    join RRL_SBORKA_PALLETS p on p.ID=inputs.id where p.ADDR is not null order by p.ADDR)loop addresses.append(r.ADDR);end loop;
  check_addresses(p_vehicle,addresses.to_clob,1,result);
 end;
end;
/


CREATE OR REPLACE package body RRL_STORE_AGG_SCAN as
 procedure normalize(p_proof clob,p_metadata clob,p_scans out clob)is
  proof json_object_t:=json_object_t.parse(p_proof);m json_object_t:=json_object_t.parse(p_metadata);
  scans json_array_t:=json_array_t();aggregates json_array_t:=json_array_t();result json_array_t:=json_array_t();
  entry json_object_t;input json_object_t;entries json_array_t;expanded json_array_t;value json_object_t;
  wire clob;direct_wire clob;units_wire clob;expanded_wire clob;disposition varchar2(20);bad number;
 begin
  if m.has('unit_scans')then scans:=m.get_array('unit_scans');end if;
  if m.has('aggregation_scans')then aggregates:=m.get_array('aggregation_scans');end if;
  if scans is null or aggregates is null or scans.get_size>20000 or aggregates.get_size>1000 then raise_application_error(-20881,'STORE_AGG_SCAN_BOUND');end if;
  direct_wire:=scans.to_clob;units_wire:=proof.get_array('units').to_clob;
  -- Check the mode on the exact physical key, so equal profile names across SKUs do not prohibit UNIT evidence.
  select count(*)into bad from json_table(direct_wire,'$[*]'columns(S varchar2(40)path '$.system_code',P varchar2(80)path '$.profile_code',H varchar2(64)path '$.code_hash'))scan_value
   join RRL_WMS_RECEIPT_CODE code on code.SYSTEM_CODE=scan_value.S and code.CODE_HASH=scan_value.H
   join RRL_WMS_RECEIPT_UNIT u on u.UID_PALLET=code.UID_PALLET and u.UNIT_ID=code.UNIT_ID
   join json_table(units_wire,'$[*]'columns(K varchar2(64)path '$.key',nested path '$.profiles[*]'columns(S varchar2(40)path '$.system_code',P varchar2(80)path '$.profile_code',M varchar2(40)path '$.scan_mode')))expected
    on expected.K=u.PHYSICAL_UNIT_KEY and expected.S=scan_value.S and expected.P=scan_value.P where expected.M in('BOX','PALLET');
  if bad!=0 then raise_application_error(-20887,'STORE_AGGREGATION_ONLY_NO_UNIT_FALLBACK');end if;
  for i in 0..scans.get_size-1 loop result.append(scans.get(i));end loop;
  for i in 0..aggregates.get_size-1 loop
   entry:=treat(aggregates.get(i)as json_object_t).clone();disposition:=entry.get_string('disposition');
   if disposition is null or disposition not in('ACCEPTED','REFUSED','DAMAGED')then raise_application_error(-20871,'STORE_AGG_DISPOSITION_REQUIRED');end if;
   entry.remove('disposition');input:=json_object_t();entries:=json_array_t();entries.append(entry);input.put('aggregation_scans',entries);wire:=input.to_clob;
   RRL_IW_AGG_SCAN.expand(wire,expanded_wire);expanded:=json_array_t.parse(expanded_wire);
   for j in 0..expanded.get_size-1 loop value:=treat(expanded.get(j)as json_object_t);value.put('disposition',disposition);result.append(value);end loop;
   if result.get_size>20000 then raise_application_error(-20881,'STORE_AGG_EXPANDED_BOUND');end if;
  end loop;
  p_scans:=result.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STORE_CALENDAR_API as
 g_operation varchar2(100);g_tx varchar2(100);g_config boolean:=false;
 function write_allowed(p_operation varchar2)return number is begin
  if g_operation=p_operation and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 function config_write_allowed return number is begin
  if g_config and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure scope(p_ware number,p_actor varchar2)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0
   and RRL_HAS_WRIGHT(ID,'customer_rule_edit')=1
   and(WARE_ID=p_ware or upper(trim(USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'STORE_CAL_CURRENT_WARE_ACTOR_REQUIRED');end if;
  select count(*)into n from RRL_WARES where ID=p_ware;
  if n!=1 then raise_application_error(-20886,'STORE_CAL_WARE_NOT_FOUND');end if;
 end;
 function store_id(p_store varchar2)return number is n number;v_id number;begin
  select count(*),max(CUSTOMER_STORE_MAP_ID)into n,v_id from RRL_CUSTOMER_STORE_MAP where STORE_CODE=p_store and ACTIVE=1;
  if n!=1 then raise_application_error(-20886,'STORE_CAL_UNIQUE_ACTIVE_STORE_REQUIRED');end if;return v_id;
 end;
 function local_date(p_day varchar2)return date is d date;begin
  d:=to_date(p_day,'FXYYYY-MM-DD');
  if p_day is null or to_char(d,'YYYY-MM-DD')!=p_day then raise_application_error(-20886,'STORE_CAL_EXPLICIT_LOCAL_DATE_REQUIRED');end if;return d;
 end;
 procedure context(p_ware number,p_store varchar2,p_day varchar2,p_actor varchar2,p_result out clob)is
  v_store number;v_day date;v_version number;src RRL_SAP_STORE_CALENDAR%rowtype;saved RRL_SAP_STORE_CAL_EXCEPTION%rowtype;b json_object_t:=json_object_t();
 begin
  scope(p_ware,p_actor);v_store:=store_id(p_store);v_day:=local_date(p_day);
  b.put('warehouse_id',p_ware);b.put('store_code',p_store);b.put('delivery_date',p_day);
  select nvl(max(VERSION_NO),0)into v_version from RRL_SAP_STORE_CAL_EXCEPTION where WARE_ID=p_ware and CUSTOMER_STORE_MAP_ID=v_store and DELIVERY_DATE=v_day;
  b.put('version',v_version);b.put('exception_status','NO_EXCEPTION');b.put('stock_changed',false);
  begin select *into src from RRL_SAP_STORE_CALENDAR where WARE_ID=p_ware and CUSTOMER_STORE_MAP_ID=v_store;
   b.put('configured',true);b.put('utc_offset_minutes',src.UTC_OFFSET_MINUTES);b.put('delivery_weekdays',src.DELIVERY_WEEKDAYS);b.put('allow_same_day',src.ALLOW_SAME_DAY=1);
  exception when no_data_found then b.put('configured',false);end;
  if v_version>0 then
   select *into saved from RRL_SAP_STORE_CAL_EXCEPTION where WARE_ID=p_ware and CUSTOMER_STORE_MAP_ID=v_store and DELIVERY_DATE=v_day and VERSION_NO=v_version;
   b.put('exception_status',saved.DAY_STATE);b.put('last_exception',json_object_t.parse(saved.RESULT_JSON));
  end if;p_result:=b.to_clob;
 end;
 procedure delivery_rule(p_ware number,p_store_id number,p_day date,p_offset out number,p_allowed out number,p_proof out clob)is
  v_days varchar2(20);v_same number;v_state varchar2(10);v_version number;v_operation varchar2(100);v_weekday number;b json_object_t:=json_object_t();
 begin
  if p_day is null or p_day!=trunc(p_day)then raise_application_error(-20886,'STORE_CAL_LOCAL_DELIVERY_DATE_REQUIRED');end if;
  begin
   select cal.UTC_OFFSET_MINUTES,cal.DELIVERY_WEEKDAYS,cal.ALLOW_SAME_DAY,ex.DAY_STATE,ex.VERSION_NO,ex.OPERATION_ID
    into p_offset,v_days,v_same,v_state,v_version,v_operation
    from RRL_SAP_STORE_CALENDAR cal
    join RRL_CUSTOMER_STORE_MAP m on m.CUSTOMER_STORE_MAP_ID=cal.CUSTOMER_STORE_MAP_ID and m.ACTIVE=1
    join RRL_CUSTOMER c on c.CUSTOMER_ID=m.CUSTOMER_ID and c.ACTIVE=1
    left join RRL_SAP_STORE_CAL_EXCEPTION ex on ex.WARE_ID=cal.WARE_ID and ex.CUSTOMER_STORE_MAP_ID=cal.CUSTOMER_STORE_MAP_ID
      and ex.DELIVERY_DATE=p_day and ex.VERSION_NO=(select max(latest.VERSION_NO)from RRL_SAP_STORE_CAL_EXCEPTION latest
        where latest.WARE_ID=cal.WARE_ID and latest.CUSTOMER_STORE_MAP_ID=cal.CUSTOMER_STORE_MAP_ID and latest.DELIVERY_DATE=p_day)
    where cal.WARE_ID=p_ware and cal.CUSTOMER_STORE_MAP_ID=p_store_id;
  exception when no_data_found then raise_application_error(-20886,'STORE_CAL_ACTIVE_SOURCE_BOOK_REQUIRED');end;
  v_weekday:=p_day-trunc(p_day,'IW')+1;
  if v_state='OPEN'then p_allowed:=1;elsif v_state='CLOSED'then p_allowed:=0;
   elsif instr(','||v_days||',',','||to_char(v_weekday,'FM9')||',')>0 then p_allowed:=1;else p_allowed:=0;end if;
  b.put('warehouse_id',p_ware);b.put('store_map_id',p_store_id);b.put('delivery_date',to_char(p_day,'YYYY-MM-DD'));
  b.put('utc_offset_minutes',p_offset);b.put('delivery_weekdays',v_days);b.put('allow_same_day',v_same=1);b.put('allowed',p_allowed=1);
  b.put('calendar_basis',case when v_state is null then 'WEEKLY_SOURCE_BOOK'else 'DATE_EXCEPTION'end);
  if v_state is not null then b.put('exception_state',v_state);b.put('exception_version',v_version);b.put('exception_operation_id',v_operation);end if;
  p_proof:=b.to_clob;
 end;
 procedure configure(p_ware number,p_store varchar2,p_body clob,p_actor varchar2,p_result out clob)is
  b json_object_t:=json_object_t.parse(p_body);a json_array_t:=b.get_array('delivery_weekdays');v_store number;v_offset number;v_same number;v_days varchar2(20);v_day number;v_meta boolean:=false;
 begin
  scope(p_ware,p_actor);RRL_STOCK_METADATA_TX.begin_change(p_actor,'customer_rule_edit');v_meta:=true;savepoint RRL_STORE_CAL264;
  scope(p_ware,p_actor);v_store:=store_id(p_store);v_offset:=b.get_number('utc_offset_minutes');
  if v_offset is null or v_offset not between -720 and 840 or trunc(v_offset)!=v_offset or a is null or a.get_size not between 1 and 7 or not b.has('allow_same_day')then raise_application_error(-20886,'STORE_CAL_CONFIG_INVALID');end if;
  if b.get_boolean('allow_same_day')then v_same:=1;else v_same:=0;end if;
  for i in 0..a.get_size-1 loop v_day:=a.get_number(i);
   if v_day is null or v_day not between 1 and 7 or trunc(v_day)!=v_day then raise_application_error(-20886,'STORE_CAL_WEEKDAY_INVALID');end if;
   if instr(','||v_days||',',','||v_day||',')=0 then v_days:=v_days||case when v_days is null then null else ','end||v_day;end if;
  end loop;
  g_config:=true;g_tx:=dbms_transaction.local_transaction_id(false);
  merge into RRL_SAP_STORE_CALENDAR d using(select p_ware WARE_ID,v_store CUSTOMER_STORE_MAP_ID from dual)s on(d.WARE_ID=s.WARE_ID and d.CUSTOMER_STORE_MAP_ID=s.CUSTOMER_STORE_MAP_ID)
  when matched then update set UTC_OFFSET_MINUTES=v_offset,DELIVERY_WEEKDAYS=v_days,ALLOW_SAME_DAY=v_same,UPDATED_BY=p_actor,UPDATED_AT=systimestamp
  when not matched then insert(WARE_ID,CUSTOMER_STORE_MAP_ID,UTC_OFFSET_MINUTES,DELIVERY_WEEKDAYS,ALLOW_SAME_DAY,UPDATED_BY)values(p_ware,v_store,v_offset,v_days,v_same,p_actor);
  g_config:=false;g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
  b.put('warehouse_id',p_ware);b.put('store_code',p_store);p_result:=b.to_clob;
 exception when others then
  if v_meta then rollback to RRL_STORE_CAL264;end if;g_config:=false;g_tx:=null;
  if v_meta then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
 procedure set_exception(p_operation varchar2,p_actor varchar2,p_body clob,p_result out clob)is
  b json_object_t;v_ware number;v_store_code varchar2(100);v_store number;v_day date;v_version number;
  v_req_hash varchar2(64);v_state varchar2(10);v_ref nvarchar2(500);v_reason nvarchar2(500);v_meta boolean:=false;n number;
  saved RRL_SAP_STORE_CAL_EXCEPTION%rowtype;r json_object_t:=json_object_t();
 begin
  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_body is null or dbms_lob.getlength(p_body)>4000 then raise_application_error(-20886,'STORE_CAL_EXCEPTION_INPUT_BOUND');end if;
  b:=json_object_t.parse(p_body);v_ware:=b.get_number('warehouse_id');v_store_code:=b.get_string('store_code');v_day:=local_date(b.get_string('delivery_date'));
  scope(v_ware,p_actor);v_req_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'customer_rule_edit');v_meta:=true;savepoint RRL_CAL_EX264;
  scope(v_ware,p_actor);v_store:=store_id(v_store_code);
  begin select *into saved from RRL_SAP_STORE_CAL_EXCEPTION where OPERATION_ID=p_operation;
   if saved.ACTOR!=p_actor or saved.WARE_ID!=v_ware or saved.CUSTOMER_STORE_MAP_ID!=v_store or saved.REQUEST_HASH!=v_req_hash then raise_application_error(-20886,'STORE_CAL_EXCEPTION_PAYLOAD_CONFLICT');end if;
   p_result:=saved.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;
  exception when no_data_found then null;end;
  select count(*)into n from RRL_SAP_STORE_CALENDAR where WARE_ID=v_ware and CUSTOMER_STORE_MAP_ID=v_store;
  if n!=1 then raise_application_error(-20886,'STORE_CAL_CONFIGURE_SOURCE_BOOK_REQUIRED');end if;
  select nvl(max(VERSION_NO),0)into v_version from RRL_SAP_STORE_CAL_EXCEPTION where WARE_ID=v_ware and CUSTOMER_STORE_MAP_ID=v_store and DELIVERY_DATE=v_day;
  if b.get_number('expected_version')is null or b.get_number('expected_version')!=v_version then raise_application_error(-20886,'STORE_CAL_EXCEPTION_VERSION_CHANGED');end if;
  v_state:=b.get_string('day_state');v_ref:=b.get_string('source_reference');v_reason:=b.get_string('reason');
  if v_state is null or v_state not in('OPEN','CLOSED')or v_ref is null or length(trim(v_ref))<8 or v_reason is null or length(trim(v_reason))<8 then raise_application_error(-20886,'STORE_CAL_EXCEPTION_REASON_REQUIRED');end if;
  r.put('operation_id',p_operation);r.put('warehouse_id',v_ware);r.put('store_code',v_store_code);r.put('delivery_date',to_char(v_day,'YYYY-MM-DD'));
  r.put('version',v_version+1);r.put('day_state',v_state);r.put('source_reference',v_ref);r.put('reason',v_reason);r.put('actor',p_actor);r.put('stock_changed',false);
  p_result:=r.to_clob;g_operation:=p_operation;g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_SAP_STORE_CAL_EXCEPTION(WARE_ID,CUSTOMER_STORE_MAP_ID,DELIVERY_DATE,VERSION_NO,OPERATION_ID,ACTOR,REQUEST_HASH,DAY_STATE,SOURCE_REFERENCE,REASON,RESULT_JSON)
   values(v_ware,v_store,v_day,v_version+1,p_operation,p_actor,v_req_hash,v_state,v_ref,v_reason,p_result);
  g_operation:=null;g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
 exception when others then
  if v_meta then rollback to RRL_CAL_EX264;end if;g_operation:=null;g_tx:=null;
  if v_meta then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STORE_EVIDENCE_API as
 procedure clear_context is
 begin
  dbms_session.set_context('RRL_STORE_MEDIA_CTX','TX_ID',null);
  dbms_session.set_context('RRL_STORE_MEDIA_CTX','ASSET_HASH',null);
  dbms_session.set_context('RRL_STORE_MEDIA_CTX','PHOTO_ID',null);
 end;
 procedure register_photo(p_load varchar2,p_store varchar2,p_view varchar2,p_actor varchar2,p_mime varchar2,p_width number,p_height number,p_bytes blob,p_result out clob) is
  source_json clob;sha varchar2(64);photo_key varchar2(64);size_no number;n number;comparison_no number;j json_object_t:=json_object_t();identity_text clob;old_mime varchar2(20);old_width number;old_height number;
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is not null then raise_application_error(-20886,'PHOTO_UPLOAD_OUTSIDE_STOCK_TRANSACTION_REQUIRED');end if;
  RRL_STOCK_STORE_RECEIPT_READ.describe_load(p_load,p_actor,p_store,source_json);
  size_no:=dbms_lob.getlength(p_bytes);
  if p_mime is null or p_mime not in('image/jpeg','image/png') or p_view is null or p_view not in('FRONT','LEFT','RIGHT','BACK','TOP')
   or size_no is null or size_no<1 or size_no>4194304 or p_width is null or p_height is null or least(p_width,p_height)<1
   or p_width*p_height>12000000 or p_width!=trunc(p_width) or p_height!=trunc(p_height) then raise_application_error(-20886,'PHOTO_ARCHIVE_CONTRACT_INVALID');end if;
  sha:=rawtohex(sys.dbms_crypto.hash(p_bytes,sys.dbms_crypto.hash_sh256));
  declare a json_array_t:=json_array_t();begin a.append(p_load);a.append(p_store);a.append(p_view);a.append(sha);identity_text:=a.to_clob;end;
  photo_key:=rawtohex(sys.dbms_crypto.hash(identity_text,sys.dbms_crypto.hash_sh256));
  select TT_ID into n from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=p_load for update;
  RRL_STOCK_STORE_RECEIPT_READ.describe_load(p_load,p_actor,p_store,source_json);
  select count(*) into n from RRL_STORE_RECEIPT_PHOTO where PHOTO_ID=photo_key;
  if n=0 then
   select count(*) into n from RRL_STORE_RECEIPT_PHOTO where LOAD_OPERATION_ID=p_load and STORE_ADDR=p_store;
   if n>=12 then raise_application_error(-20881,'PHOTO_ARCHIVE_LIMIT_12');end if;
  end if;
  dbms_session.set_context('RRL_STORE_MEDIA_CTX','TX_ID',dbms_transaction.local_transaction_id(true));
  dbms_session.set_context('RRL_STORE_MEDIA_CTX','ASSET_HASH',sha);
  dbms_session.set_context('RRL_STORE_MEDIA_CTX','PHOTO_ID',photo_key);
  begin
   insert into RRL_STORE_MEDIA_ASSET(SHA256,MIME_TYPE,BYTE_COUNT,WIDTH_PX,HEIGHT_PX,CONTENT_BYTES)values(sha,p_mime,size_no,p_width,p_height,p_bytes);
  exception when dup_val_on_index then
   select MIME_TYPE,WIDTH_PX,HEIGHT_PX,dbms_lob.compare(CONTENT_BYTES,p_bytes) into old_mime,old_width,old_height,comparison_no from RRL_STORE_MEDIA_ASSET where SHA256=sha;
   if old_mime!=p_mime or old_width!=p_width or old_height!=p_height or comparison_no is null or comparison_no!=0 then raise_application_error(-20886,'PHOTO_ASSET_HASH_CONTENT_CONFLICT');end if;
  end;
  begin
   insert into RRL_STORE_RECEIPT_PHOTO(PHOTO_ID,LOAD_OPERATION_ID,STORE_ADDR,VIEW_CODE,ASSET_SHA256,RECORDED_BY)values(photo_key,p_load,p_store,p_view,sha,p_actor);
  exception when dup_val_on_index then
   select count(*) into n from RRL_STORE_RECEIPT_PHOTO where PHOTO_ID=photo_key and LOAD_OPERATION_ID=p_load and STORE_ADDR=p_store and VIEW_CODE=p_view and ASSET_SHA256=sha;
   if n!=1 then raise_application_error(-20886,'PHOTO_SOURCE_IDENTITY_CONFLICT');end if;
  end;
  clear_context;
  j.put('photo_id',photo_key);j.put('load_operation_id',p_load);j.put('store_address',p_store);j.put('view',p_view);j.put('sha256',sha);j.put('byte_count',size_no);j.put('mime_type',p_mime);j.put('width_px',p_width);j.put('height_px',p_height);j.put('status','ARCHIVED');p_result:=j.to_clob;
 exception when others then clear_context;raise;
 end;
 function photos_json(p_load varchar2,p_store varchar2,p_actor varchar2) return clob is source_json clob;a json_array_t:=json_array_t();j json_object_t;n number:=0;
 begin
  RRL_STOCK_STORE_RECEIPT_READ.describe_load(p_load,p_actor,p_store,source_json);
  for r in(select p.PHOTO_ID,p.VIEW_CODE,p.ASSET_SHA256,p.RECORDED_BY,p.RECORDED_AT,s.MIME_TYPE,s.BYTE_COUNT,s.WIDTH_PX,s.HEIGHT_PX
    from RRL_STORE_RECEIPT_PHOTO p join RRL_STORE_MEDIA_ASSET s on s.SHA256=p.ASSET_SHA256
    where p.LOAD_OPERATION_ID=p_load and p.STORE_ADDR=p_store order by p.RECORDED_AT,p.PHOTO_ID fetch first 13 rows only)loop
   n:=n+1;if n>12 then raise_application_error(-20881,'PHOTO_ARCHIVE_LIST_BOUND_12');end if;
   j:=json_object_t();j.put('photo_id',r.PHOTO_ID);j.put('view',r.VIEW_CODE);j.put('sha256',r.ASSET_SHA256);j.put('recorded_by',r.RECORDED_BY);j.put('recorded_at',to_char(r.RECORDED_AT,'YYYY-MM-DD"T"HH24:MI:SS.FFTZH:TZM'));j.put('mime_type',r.MIME_TYPE);j.put('byte_count',r.BYTE_COUNT);j.put('width_px',r.WIDTH_PX);j.put('height_px',r.HEIGHT_PX);a.append(j);
  end loop;return a.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_STORE_MARK_CORE as 

 function stock_leaf(p_tree json_object_t)return json_object_t is

 nodes json_array_t:=p_tree.get_array('nodes');node json_object_t;candidate json_object_t;n number:=0;

 begin

 if nodes.get_size<1 or nodes.get_size>200 or p_tree.get_number('leaf_count')!=1 or p_tree.get_number('top_place_count')!=1 then raise_application_error(-20886,'STORE_MARK_SINGLE_STOCK_SCOPE_REQUIRED');end if;

 for i in 0..nodes.get_size-1 loop

 candidate:=treat(nodes.get(i)as json_object_t);

 if candidate.get_string('kind')='STOCK'then node:=candidate;n:=n+1;

 elsif candidate.get_string('kind')not in('CONTAINER','CASE')then raise_application_error(-20886,'STORE_MARK_NESTED_STOCK_ONLY_REQUIRED');end if;

 end loop;

 if n!=1 then raise_application_error(-20886,'STORE_MARK_SINGLE_STOCK_SCOPE_REQUIRED');end if;

 return node;

 end;

 function stock_leaves(p_tree json_object_t)return json_array_t is

 nodes json_array_t:=p_tree.get_array('nodes');result json_array_t:=json_array_t();candidate json_object_t;

 begin

 if nodes.get_size<1 or nodes.get_size>200 or p_tree.get_number('leaf_count')<1 or p_tree.get_number('top_place_count')!=1 then raise_application_error(-20886,'STORE_MARK_FROZEN_STOCK_SCOPE_REQUIRED');end if;

 for i in 0..nodes.get_size-1 loop candidate:=treat(nodes.get(i)as json_object_t);

 if candidate.get_string('kind')='STOCK'then result.append(candidate);

 elsif candidate.get_string('kind')not in('CONTAINER','CASE')then raise_application_error(-20886,'STORE_MARK_NESTED_STOCK_ONLY_REQUIRED');end if;end loop;

 if result.get_size!=p_tree.get_number('leaf_count')then raise_application_error(-20886,'STORE_MARK_EXACT_STOCK_LEAVES_REQUIRED');end if;return result;

 end;

 function source_proof(p_domain json_object_t)return json_object_t is

 tree json_object_t:=p_domain.get_object('snapshot');leaves json_array_t;node json_object_t;proof json_object_t:=json_object_t();leafproof json_object_t;

 allunits json_array_t:=json_array_t();signatures json_array_t:=json_array_t();units json_array_t;unit_value json_object_t;signature_entry json_object_t;

 profiles clob;first_profiles clob;n number;bad number;matched number;scan_total number:=0;profile_union json_array_t:=json_array_t();ordinary_lots json_array_t:=json_array_t();current_profiles json_array_t;profile_item json_object_t;profile_key varchar2(500);article varchar2(160);wire clob;v_lot_uid varchar2(200);

 type keys_map is table of number index by varchar2(64);seen keys_map;seen_profiles keys_map;k varchar2(64);

 begin

 leaves:=stock_leaves(tree);

 for z in 0..leaves.get_size-1 loop

 node:=treat(leaves.get(z)as json_object_t);article:=node.get_string('article');v_lot_uid:=node.get_string('uid');

 wire:=RRL_INTERWARE_UNIT_SOURCE.issued_manifest(p_domain.get_string('load_operation_id'),node.get_string('uid'),tree.to_clob);leafproof:=json_object_t.parse(wire);

 select count(*),sum(case when SCAN_MODE in('UNIT','UNIT_OR_AGGREGATION','BOX','PALLET')then 0 else 1 end),

 json_arrayagg(json_object('system_code'value SYSTEM_CODE,'profile_code'value PROFILE_CODE,'profile_version'value PROFILE_VERSION,'scan_mode'value SCAN_MODE)order by SYSTEM_CODE,PROFILE_CODE returning clob)

 into n,bad,profiles from RRL_SKU_RECEIPT_PROFILE where ARTICUL=article;

 units:=leafproof.get_array('units');

 if n=0 and units.get_size=0 then ordinary_lots.append(node.get_string('uid'));

 else

 if n=0 or units.get_size=0 then raise_application_error(-20886,'STORE_MARK_UNIT_PROFILE_MATRIX_REQUIRED');end if;

 if n>50 or bad!=0 or leafproof.get_number('physical_unit_count')<1 then raise_application_error(-20886,'STORE_MARK_CURRENT_UNIT_PROFILES_REQUIRED');end if;

 current_profiles:=json_array_t.parse(profiles);

 for pi in 0..current_profiles.get_size-1 loop profile_item:=treat(current_profiles.get(pi)as json_object_t);

 profile_key:=rawtohex(sys.dbms_crypto.hash(profile_item.to_clob,sys.dbms_crypto.hash_sh256));

 if not seen_profiles.exists(profile_key)then seen_profiles(profile_key):=1;profile_union.append(profile_item);end if;end loop;

 if profile_union.get_size>50 then raise_application_error(-20881,'STORE_MARK_PROFILE_UNION_BOUND_50');end if;

 select count(distinct u.PHYSICAL_UNIT_KEY||':'||c.SYSTEM_CODE||':'||pr.PROFILE_CODE)into matched

 from RRL_WMS_RECEIPT_UNIT u join RRL_WMS_RECEIPT_CODE c on c.UID_PALLET=u.UID_PALLET and c.UNIT_ID=u.UNIT_ID

,json_table(c.PROFILES_JSON,'$[*]'columns(PROFILE_CODE varchar2(80)path '$.profile',PROFILE_VERSION varchar2(40)path '$.version'))pr

,RRL_SKU_RECEIPT_PROFILE profile where profile.ARTICUL=article and profile.SYSTEM_CODE=c.SYSTEM_CODE and profile.PROFILE_CODE=pr.PROFILE_CODE and profile.PROFILE_VERSION=pr.PROFILE_VERSION

 and u.CURRENT_UID=v_lot_uid and u.STOCK_STATUS='ISSUED';

 if matched!=n*leafproof.get_number('physical_unit_count')then raise_application_error(-20886,'STORE_MARK_CURRENT_SAVED_CODE_PROFILE_VERSION_REQUIRED');end if;

 units:=leafproof.get_array('units');

 for i in 0..units.get_size-1 loop unit_value:=treat(units.get(i)as json_object_t);k:=unit_value.get_string('key');

 if seen.exists(k)then raise_application_error(-20886,'STORE_MARK_DUPLICATE_PHYSICAL_UNIT');end if;seen(k):=1;

 unit_value.put('lot_uid',node.get_string('uid'));unit_value.put('article',article);unit_value.put('profiles',current_profiles);allunits.append(unit_value);end loop;

 end if;

 signature_entry:=json_object_t();signature_entry.put('uid',node.get_string('uid'));signature_entry.put('signature',leafproof.get_string('unit_signature'));signatures.append(signature_entry);

 scan_total:=scan_total+n*units.get_size;

 if allunits.get_size>10000 or scan_total>20000 then raise_application_error(-20881,'STORE_MARK_SCAN_BOUND');end if;

 end loop;

 if allunits.get_size!=tree.get_number('physical_unit_count')then raise_application_error(-20884,'STORE_MARK_EXACT_TREE_PHYSICAL_UNIT_COUNT');end if;

 proof.put('ordinary_lots',ordinary_lots);proof.put('units',allunits);proof.put('profiles',profile_union);proof.put('supported',true);proof.put('physical_unit_count',allunits.get_size);proof.put('expected_scan_count',scan_total);

 if leaves.get_size=1 then proof.put('unit_signature',leafproof.get_string('unit_signature'));else proof.put('unit_signature',rawtohex(sys.dbms_crypto.hash(signatures.to_clob,sys.dbms_crypto.hash_sh256)));end if;

 return proof;

 end;

 function preview(p_domain json_object_t)return clob is p json_object_t; 

 begin p:=source_proof(p_domain);return p.to_clob; 

 exception when others then 

  if sqlcode between -20999 and -20800 then p:=json_object_t();p.put('supported',false);p.put('reason',substr(sqlerrm,1,250));return p.to_clob;else raise;end if; 

 end; 

 procedure verify_scans(p_domain json_object_t,p_metadata json_object_t,p_proof out json_object_t)is 

 v_wire clob;begin p_proof:=source_proof(p_domain);RRL_STORE_AGG_SCAN.normalize(p_proof.to_clob,p_metadata.to_clob,v_wire);p_proof.put('validated_store_scans',json_array_t.parse(v_wire));end; 

 function tuple_key(p_unit varchar2,p_system varchar2,p_profile varchar2)return varchar2 is 

 begin return rawtohex(RRL_STOCK_LOCK_API.resource_key('STOREMARK',p_unit,rawtohex(RRL_STOCK_LOCK_API.resource_key('PROFILE',p_system,p_profile))));end; 

 procedure resolve_disposition(p_proof json_object_t,p_metadata json_object_t,p_lines json_array_t,p_units out json_array_t)is 

  units json_array_t:=p_proof.get_array('units');profiles json_array_t:=p_proof.get_array('profiles');scans json_array_t:=json_array_t(); 

  unit_value json_object_t;profile_value json_object_t;scan_value json_object_t;line_value json_object_t;result_value json_object_t; 

  type marks_map is table of number index by varchar2(4000);expected marks_map;resolved marks_map;coverage marks_map; 

  type state_map is table of varchar2(20)index by varchar2(64);states state_map;type count_map is table of number index by varchar2(64);unit_profile_counts count_map; 

  k varchar2(4000);unit_key varchar2(64);disposition varchar2(20);wire clob;resolved_count number:=0; 

  accepted number:=0;missing number:=0;refused number:=0;damaged number:=0;qty number;profile_count number:=profiles.get_size;lot_key varchar2(200);line_lot varchar2(200);

 type qty_map is table of number index by varchar2(200);accepted_lots qty_map;missing_lots qty_map;refused_lots qty_map;damaged_lots qty_map;declared_lots qty_map;ordinary_keys qty_map;ordinary_array json_array_t; 

  function nonnegative(p_text varchar2)return number is 

  begin if regexp_like(p_text,'^0{1,18}([.]0{1,9})?$')then return 0;end if;return RRL_STOCK_MATH.quantity(p_text);end; 

 begin

  if p_proof.has('ordinary_lots')then ordinary_array:=p_proof.get_array('ordinary_lots');for i in 0..ordinary_array.get_size-1 loop ordinary_keys(ordinary_array.get_string(i)):=1;end loop;end if;

  if p_proof.has('validated_store_scans')then scans:=p_proof.get_array('validated_store_scans');elsif p_metadata.has('unit_scans')then scans:=p_metadata.get_array('unit_scans');end if; 

  if scans.get_size>20000 or p_lines.get_size<1 or p_lines.get_size>200 then raise_application_error(-20881,'STORE_MARK_DISPOSITION_BOUND');end if; 

  for i in 0..units.get_size-1 loop 

   unit_value:=treat(units.get(i)as json_object_t);unit_key:=unit_value.get_string('key');coverage(unit_key):=0;states(unit_key):='MISSING';lot_key:=unit_value.get_string('lot_uid');if lot_key is null then raise_application_error(-20886,'STORE_MARK_UNIT_LOT_REQUIRED');end if;

   if not accepted_lots.exists(lot_key)then accepted_lots(lot_key):=0;missing_lots(lot_key):=0;refused_lots(lot_key):=0;damaged_lots(lot_key):=0;end if; 

   profiles:=unit_value.get_array('profiles');unit_profile_counts(unit_key):=profiles.get_size;

   for j in 0..profiles.get_size-1 loop 

    profile_value:=treat(profiles.get(j)as json_object_t);expected(tuple_key(unit_key,profile_value.get_string('system_code'),profile_value.get_string('profile_code'))):=0; 

   end loop; 

  end loop; 

  for i in 0..scans.get_size-1 loop 

   scan_value:=treat(scans.get(i)as json_object_t); 

   if scan_value.get_string('system_code')is null or scan_value.get_string('profile_code')is null or not regexp_like(scan_value.get_string('code_hash'),'^[a-f0-9]{64}$')then raise_application_error(-20871,'STORE_MARK_SCAN_INVALID');end if; 

   disposition:=nvl(scan_value.get_string('disposition'),'ACCEPTED'); 

   if disposition not in('ACCEPTED','REFUSED','DAMAGED')then raise_application_error(-20871,'STORE_MARK_PHYSICAL_SCAN_DISPOSITION_REQUIRED');end if; 

  end loop; 

  wire:=scans.to_clob; 

  for z in(select j.I,j.S,j.P,nvl(j.D,'ACCEPTED')D,u.PHYSICAL_UNIT_KEY from 

   json_table(wire,'$[*]'columns(I for ordinality,S varchar2(40)path '$.system_code',P varchar2(80)path '$.profile_code',H varchar2(64)path '$.code_hash',D varchar2(20)path '$.disposition'))j 

   join RRL_WMS_RECEIPT_CODE c on c.SYSTEM_CODE=j.S and c.CODE_HASH=j.H 

   join RRL_WMS_RECEIPT_UNIT u on u.UID_PALLET=c.UID_PALLET and u.UNIT_ID=c.UNIT_ID 

   where u.STOCK_STATUS='ISSUED'and exists(select 1 from json_table(c.PROFILES_JSON,'$[*]'columns(P varchar2(80)path '$.profile'))pr where pr.P=j.P))loop 

   k:=tuple_key(z.PHYSICAL_UNIT_KEY,z.S,z.P); 

   if not expected.exists(k)then raise_application_error(-20886,'STORE_MARK_FOREIGN_UNIT_OR_PROFILE');end if; 

   if resolved.exists(to_char(z.I))or expected(k)=1 then raise_application_error(-20871,'STORE_MARK_DUPLICATE_SCAN');end if; 

   if coverage(z.PHYSICAL_UNIT_KEY)>0 and states(z.PHYSICAL_UNIT_KEY)!=z.D then raise_application_error(-20886,'STORE_MARK_ONE_UNIT_DISPOSITION_REQUIRED');end if; 

   resolved(to_char(z.I)):=1;expected(k):=1;coverage(z.PHYSICAL_UNIT_KEY):=coverage(z.PHYSICAL_UNIT_KEY)+1;states(z.PHYSICAL_UNIT_KEY):=z.D;resolved_count:=resolved_count+1; 

  end loop; 

  if resolved_count!=scans.get_size then raise_application_error(-20886,'STORE_MARK_FOREIGN_CODE');end if; 

  p_units:=json_array_t(); 

  for i in 0..units.get_size-1 loop 

   unit_value:=treat(units.get(i)as json_object_t);unit_key:=unit_value.get_string('key');disposition:=states(unit_key);qty:=RRL_STOCK_MATH.quantity(unit_value.get_string('quantity')); 

   if coverage(unit_key)>0 and coverage(unit_key)!=unit_profile_counts(unit_key) then raise_application_error(-20886,'STORE_MARK_ALL_UNIT_PROFILES_REQUIRED');end if; 

   lot_key:=unit_value.get_string('lot_uid');

   if disposition='ACCEPTED'then accepted_lots(lot_key):=accepted_lots(lot_key)+qty;elsif disposition='MISSING'then missing_lots(lot_key):=missing_lots(lot_key)+qty;elsif disposition='REFUSED'then refused_lots(lot_key):=refused_lots(lot_key)+qty;else damaged_lots(lot_key):=damaged_lots(lot_key)+qty;end if; 

   result_value:=unit_value.clone();result_value.put('disposition',disposition);p_units.append(result_value); 

  end loop; 

  for i in 0..p_lines.get_size-1 loop

   line_value:=treat(p_lines.get(i)as json_object_t);line_lot:=line_value.get_string('lot_uid');

   if line_lot is null or declared_lots.exists(line_lot)or(not accepted_lots.exists(line_lot)and not ordinary_keys.exists(line_lot))then raise_application_error(-20886,'STORE_MARK_EXACT_LOT_LINES_REQUIRED');end if;declared_lots(line_lot):=1;

   if accepted_lots.exists(line_lot)then

   if nonnegative(line_value.get_string('accepted'))!=accepted_lots(line_lot)or nonnegative(line_value.get_string('missing'))!=missing_lots(line_lot)or nonnegative(line_value.get_string('refused'))!=refused_lots(line_lot)or nonnegative(line_value.get_string('damaged'))!=damaged_lots(line_lot)or nonnegative(line_value.get_string('extra'))!=0 then raise_application_error(-20886,'STORE_MARK_EXACT_UNIT_DISPOSITION_QUANTITY_REQUIRED');end if;

   end if;

  end loop;

  if declared_lots.count!=accepted_lots.count+ordinary_keys.count then raise_application_error(-20886,'STORE_MARK_ALL_LOT_LINES_REQUIRED');end if;

 end; 

 procedure persist(p_operation varchar2,p_load varchar2,p_units json_array_t,p_actor varchar2)is 

  x json_object_t;key_value varchar2(64);state_value varchar2(20);qty number;uom varchar2(20);version_value number; 

 begin 

  for i in 0..p_units.get_size-1 loop 

   x:=treat(p_units.get(i)as json_object_t);key_value:=x.get_string('key');state_value:=x.get_string('disposition');qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));uom:=x.get_string('base_uom');version_value:=x.get_number('version'); 

   insert into RRL_STORE_RECEIPT_UNIT(OPERATION_ID,LOAD_OPERATION_ID,PHYSICAL_UNIT_KEY,UNIT_DISPOSITION,BASE_QTY,BASE_UOM,SOURCE_UNIT_VERSION,RECORDED_BY) 

    values(p_operation,p_load,key_value,state_value,qty,uom,version_value,p_actor); 

  end loop; 

 end; 

 procedure declare_rows(p_domain json_object_t,p_policies in out nocopy json_array_t,p_resources in out nocopy json_array_t)is node json_object_t;leaves json_array_t:=stock_leaves(p_domain.get_object('snapshot'));nodes clob:=p_domain.get_object('snapshot').get_array('nodes').to_clob;

 begin

 for v in(select CASE_ID from json_table(nodes,'$[*]'columns(NODE_KIND varchar2(20)path '$.kind',CASE_ID number path '$.case_task_id'))where NODE_KIND='CASE')loop

 RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CASE_PICK_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.CASE_ID));end loop;

 for i in 0..leaves.get_size-1 loop node:=treat(leaves.get(i)as json_object_t);

 RRL_STOCK_PLAN_HELPER.stock_closure(p_policies,p_resources,node.get_string('uid'),node.get_string('article'),p_domain.get_object('snapshot').get_string('cell'),null);

 end loop;

 end;

end;
/


CREATE OR REPLACE package body RRL_STORE_ORDER_SCOPE as

 procedure actor_scope(p_actor varchar2,p_permission varchar2,p_ware out number,p_global out number)is begin

  if p_permission is null or p_permission not in('customer_order_view','customer_fulfillment_view','sap_store_order_import','customer_order_import','sap_store_decision_import','sap_supply_import')then raise_application_error(-20882,'STORE_ORDER_SCOPE_PERMISSION_REQUIRED');end if;

  begin

   select WARE_ID,case when upper(trim(USER_GROUP))='GLOBAL_ADMIN'

    or(p_permission in('sap_store_order_import','sap_store_decision_import','sap_supply_import')and RRL_HAS_WRIGHT(ID,'sap_store_all_ware')=1)then 1 else 0 end into p_ware,p_global

    from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,p_permission)=1;

  exception when no_data_found then raise_application_error(-20882,'STORE_ORDER_CURRENT_ACTOR_REQUIRED');end;

  if p_global=0 and(p_ware is null or p_ware<=0)then raise_application_error(-20882,'STORE_ORDER_CURRENT_WARE_REQUIRED');end if;

 end;

 procedure assert_scope(p_actor varchar2,p_permission varchar2,p_ware number)is own_ware number;v_global number;begin

  actor_scope(p_actor,p_permission,own_ware,v_global);

  if p_ware is null or p_ware<=0 or(v_global=0 and p_ware!=own_ware)then raise_application_error(-20882,'STORE_ORDER_CURRENT_WARE_FORBIDDEN');end if;

 end;

 procedure begin_source(p_actor varchar2,p_permission varchar2,p_ware number,p_order number default null)is

  f json_array_t:=json_array_t();r json_array_t:=json_array_t();

 begin

  if p_permission not in('sap_store_order_import','customer_order_import','sap_supply_import')then raise_application_error(-20882,'STORE_ORDER_SOURCE_COMMAND_REQUIRED');end if;

  assert_scope(p_actor,p_permission,p_ware);

  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE',4);

  RRL_STOCK_LOCK_API.begin_plan;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);

  if p_order is not null then

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(p_order));

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SAP_STORE_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(p_order));

  end if;

  RRL_STOCK_LOCK_API.acquire_resources(r.to_clob);

  assert_scope(p_actor,p_permission,p_ware);

 exception when others then RRL_STOCK_LOCK_API.clear_plan;raise;

 end;

 procedure begin_supply(p_actor varchar2,p_ware number,p_sender varchar2,p_order varchar2,p_message varchar2)is

  f json_array_t:=json_array_t();r json_array_t:=json_array_t();

  declared_id varchar2(32);current_id varchar2(32);v_nak number;old_ware number;n number:=0;

 begin

  assert_scope(p_actor,'sap_supply_import',p_ware);

  if p_sender is null or lengthb(p_sender)>100 or p_order is null or lengthb(p_order)>20 or p_message is null or lengthb(p_message)>100 then raise_application_error(-20886,'SUPPLY_SOURCE_RESOURCE_INPUT_BOUND');end if;

  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE',4);

  RRL_STOCK_LOCK_API.begin_plan;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);

  RRL_STOCK_PLAN_HELPER.anchor(r,20,'SUPPLY.SOURCE',p_sender,p_order);

  RRL_STOCK_PLAN_HELPER.anchor(r,20,'SUPPLY.MESSAGE',p_sender,p_message);

  begin

   select ORDER_ID,NAKLAD_ID,WARE_ID into declared_id,v_nak,old_ware from RRL_SAP_SUPPLY_ORDER where SENDER=p_sender and ORDER_NUMBER=p_order;

   assert_scope(p_actor,'sap_supply_import',old_ware);

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SAP_SUPPLY_ORDER',declared_id);

   RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRIHOD_NAKLAD',RRL_STOCK_PLAN_HELPER.decimal_text(v_nak));

   for x in(select LINE_NUMBER,ROW_ID from RRL_SAP_SUPPLY_LINE where ORDER_ID=declared_id order by LINE_NUMBER fetch first 1001 rows only)loop

    n:=n+1;if n>1000 then raise_application_error(-20886,'SUPPLY_SOURCE_LINE_RESOURCE_BOUND_1000');end if;

    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_SAP_SUPPLY_LINE',declared_id||':'||x.LINE_NUMBER);

    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PRIHOD_NAKLAD_ROWS',RRL_STOCK_PLAN_HELPER.decimal_text(x.ROW_ID));

   end loop;

  exception when no_data_found then null;end;

  RRL_STOCK_LOCK_API.acquire_resources(r.to_clob);

  assert_scope(p_actor,'sap_supply_import',p_ware);

  begin select ORDER_ID,WARE_ID into current_id,old_ware from RRL_SAP_SUPPLY_ORDER where SENDER=p_sender and ORDER_NUMBER=p_order;

   assert_scope(p_actor,'sap_supply_import',old_ware);

  exception when no_data_found then current_id:=null;end;

  if nvl(current_id,'~')!=nvl(declared_id,'~')then raise_application_error(-20886,'SUPPLY_SOURCE_REPLAN_REQUIRED');end if;

 exception when others then RRL_STOCK_LOCK_API.clear_plan;raise;

 end;

 procedure end_source is begin RRL_STOCK_LOCK_API.clear_plan;end;

end;
/


CREATE OR REPLACE package body RRL_STORE_RETURN_UNIT_CORE as

 function approved_proof(p_approval varchar2)return clob is

  a RRL_STORE_RETURN_APPROVAL%rowtype;profile_count number;matched number;parts json_array_t;part json_object_t;n number;bad number;eligible number;total number;profiles clob;units clob;proof json_object_t;lines json_array_t:=json_array_t();line_value json_object_t:=json_object_t();resolved json_array_t;

 begin

  select *into a from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=p_approval;

  select count(*)into n from RRL_STORE_RETURN_UNIT where APPROVAL_OPERATION_ID=p_approval;

  select count(*),sum(case when SCAN_MODE in('UNIT','UNIT_OR_AGGREGATION','BOX','PALLET')then 0 else 1 end),json_arrayagg(json_object('system_code'value SYSTEM_CODE,'profile_code'value PROFILE_CODE,'profile_version'value PROFILE_VERSION,'scan_mode'value SCAN_MODE)order by SYSTEM_CODE,PROFILE_CODE returning clob)

   into eligible,bad,profiles from RRL_SKU_RECEIPT_PROFILE where ARTICUL=a.ARTICLE;profile_count:=eligible;

  if n=0 and eligible=0 then

   return null;

  end if;

  if n<1 or n>10000 or eligible<1 or eligible>50 or bad!=0 or n*eligible>20000 then raise_application_error(-20886,'STORE_RETURN_APPROVED_CURRENT_UNIT_PROFILES_REQUIRED');end if;

  select count(*),sum(u.BASE_QTY),json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob)

   into eligible,total,units from RRL_STORE_RETURN_UNIT b join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=b.PHYSICAL_UNIT_KEY

   where b.APPROVAL_OPERATION_ID=p_approval and u.CURRENT_UID=b.ORIGINAL_UID and u.CURRENT_CELL=b.SOURCE_CELL and u.BASE_QTY=b.BASE_QTY and u.BASE_UOM=b.BASE_UOM and u.UNIT_VERSION=b.SOURCE_UNIT_VERSION and u.STOCK_STATUS='ISSUED'and u.HARD_RESERVATION_ID is null;

  if eligible!=n or total!=a.BASE_QTY then raise_application_error(-20890,'CLOSURE_CHANGED: exact approved return units');end if;

  select count(distinct u.PHYSICAL_UNIT_KEY||':'||code.SYSTEM_CODE||':'||decoded.CODE_PROFILE)into matched

  from RRL_STORE_RETURN_UNIT b join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=b.PHYSICAL_UNIT_KEY

  join RRL_WMS_RECEIPT_CODE code on code.UID_PALLET=u.UID_PALLET and code.UNIT_ID=u.UNIT_ID

  ,json_table(code.PROFILES_JSON,'$[*]'columns(CODE_PROFILE varchar2(80)path '$.profile',CODE_VERSION varchar2(40)path '$.version'))decoded

  ,RRL_SKU_RECEIPT_PROFILE card

  where b.APPROVAL_OPERATION_ID=p_approval and card.ARTICUL=a.ARTICLE and card.SYSTEM_CODE=code.SYSTEM_CODE

  and card.PROFILE_CODE=decoded.CODE_PROFILE and card.PROFILE_VERSION=decoded.CODE_VERSION;

  if matched!=n*profile_count then raise_application_error(-20886,'RETURN_CURRENT_SAVED_CODE_PROFILE_VERSION_REQUIRED');end if;

  parts:=json_array_t.parse(units);

  for i in 0..parts.get_size-1 loop part:=treat(parts.get(i)as json_object_t);

   part.put('lot_uid',a.LOT_UID);part.put('article',a.ARTICLE);part.put('profiles',json_array_t.parse(profiles));parts.put(i,part,true);

  end loop;

  proof:=json_object_t();proof.put('units',parts);proof.put('profiles',json_array_t.parse(profiles));proof.put('physical_unit_count',n);

  line_value.put('accepted',RRL_STOCK_PLAN_HELPER.decimal_text(a.BASE_QTY));line_value.put('missing','0');line_value.put('refused','0');line_value.put('damaged','0');line_value.put('extra','0');lines.append(line_value);

  proof.put('supported',true);proof.put('expected_scan_count',n*proof.get_array('profiles').get_size);return proof.to_clob;

 end;

 function custody_proof(p_approval varchar2,p_metadata json_object_t)return clob is

  wire clob:=approved_proof(p_approval);proof json_object_t;qty number;lot_value varchar2(200);lines json_array_t:=json_array_t();x json_object_t:=json_object_t();resolved json_array_t;normalized json_object_t;expanded_wire clob;input_wire clob;direct_wire clob;profile_wire clob;bad_direct number;aggregation_count number:=0;

 begin

  if wire is null then

   if(p_metadata.has('unit_scans')and p_metadata.get_array('unit_scans').get_size>0)or(p_metadata.has('aggregation_scans')and p_metadata.get_array('aggregation_scans').get_size>0)then raise_application_error(-20886,'STORE_RETURN_ORDINARY_UNEXPECTED_UNIT_SCANS');end if;

   return null;

  end if;

  proof:=json_object_t.parse(wire);select BASE_QTY,LOT_UID into qty,lot_value from RRL_STORE_RETURN_APPROVAL where OPERATION_ID=p_approval;

  x.put('lot_uid',lot_value);x.put('accepted',RRL_STOCK_PLAN_HELPER.decimal_text(qty));x.put('missing','0');x.put('refused','0');x.put('damaged','0');x.put('extra','0');lines.append(x);

  normalized:=p_metadata.clone();profile_wire:=proof.get_array('profiles').to_clob;
  direct_wire:=to_clob('[]');if normalized.has('unit_scans')then direct_wire:=normalized.get_array('unit_scans').to_clob;end if;
  select count(*)into bad_direct from json_table(direct_wire,'$[*]'columns(S varchar2(40)path '$.system_code',P varchar2(80)path '$.profile_code'))scan_value
   join json_table(profile_wire,'$[*]'columns(S varchar2(40)path '$.system_code',P varchar2(80)path '$.profile_code',M varchar2(40)path '$.scan_mode'))profile_value
    on profile_value.S=scan_value.S and profile_value.P=scan_value.P where profile_value.M in('BOX','PALLET');
  if bad_direct!=0 then raise_application_error(-20887,'RETURN_AGGREGATION_ONLY_NO_UNIT_FALLBACK');end if;
  if normalized.has('aggregation_scans')then aggregation_count:=normalized.get_array('aggregation_scans').get_size;end if;
  if aggregation_count>0 then
   input_wire:=normalized.get_array('aggregation_scans').to_clob;
   select count(*)into bad_direct from json_table(input_wire,'$[*]'columns(L varchar2(10)path '$.level'))where L='PALLET';
   if bad_direct!=0 then
    lot_value:=normalized.get_string('pallet_identifier');
    if lot_value is null then lot_value:=normalized.get_string('scan_pallet');end if;
    RRL_RETURN_PALLET_IDENTITY.assert_preserved(p_approval,lot_value);
   end if;
   input_wire:=normalized.to_clob;RRL_IW_AGG_SCAN.expand(input_wire,expanded_wire);
   normalized.put('unit_scans',json_array_t.parse(expanded_wire));
  end if;
  RRL_STORE_MARK_CORE.resolve_disposition(proof,normalized,lines,resolved);proof.put('units',resolved);return proof.to_clob;

 end;

 function disposition_units(p_receipt varchar2,p_uid varchar2,p_uom varchar2,p_basis varchar2)return clob is

  proof clob;cell_text varchar2(60);state_text varchar2(30);fact_count number;wire clob;

 begin

  if p_basis is null or p_basis not in('ACCEPTED','REFUSED','DAMAGED')then raise_application_error(-20886,'STORE_RETURN_BASIS_REQUIRED');end if;

  select json_value(COMPOSITION_JSON,'$.cell'),RECEIPT_STATE into cell_text,state_text from RRL_STORE_RECEIPT_FACT where OPERATION_ID=p_receipt;

  select RESOLVED_PLAN_JSON into proof from RRL_STOCK_OPERATION where OPERATION_ID=p_receipt and COMMAND_TYPE='STORE_RECEIPT'and STATE='APPLIED';

  select count(*)into fact_count from RRL_STORE_RECEIPT_UNIT where OPERATION_ID=p_receipt;

  if fact_count=0 and p_basis!='ACCEPTED'then return to_clob('[]');end if;

  if fact_count=0 and not json_object_t.parse(proof).get_object('domain').has('marked_unit_proof')then return to_clob('[]');end if;

  if fact_count=0 and state_text!='ACCEPTED'then raise_application_error(-20886,'STORE_RETURN_ACCEPTED_UNIT_EVIDENCE_REQUIRED');end if;

  select json_arrayagg(json_object('key'value u.PHYSICAL_UNIT_KEY,'unit_id'value u.UNIT_ID,'origin_uid'value u.UID_PALLET,'quantity'value RRL_STOCK_PLAN_HELPER.decimal_text(u.BASE_QTY),'base_uom'value u.BASE_UOM,'version'value u.UNIT_VERSION)order by u.PHYSICAL_UNIT_KEY returning clob)into wire

   from RRL_WMS_RECEIPT_UNIT u join(

    select PHYSICAL_UNIT_KEY K,BASE_QTY Q,BASE_UOM B,SOURCE_UNIT_VERSION V from RRL_STORE_RECEIPT_UNIT where OPERATION_ID=p_receipt and UNIT_DISPOSITION=p_basis

    union all

    select j.K,RRL_STOCK_MATH.quantity(j.Q),j.B,j.V from json_table(proof,'$.domain.marked_unit_proof.units[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom',V number path '$.version'))j where fact_count=0 and state_text='ACCEPTED'and p_basis='ACCEPTED'

   )source on source.K=u.PHYSICAL_UNIT_KEY and source.Q=u.BASE_QTY and source.B=u.BASE_UOM and source.V=u.UNIT_VERSION

   where u.CURRENT_UID=p_uid and u.CURRENT_CELL=cell_text and u.BASE_UOM=p_uom and u.STOCK_STATUS='ISSUED'and u.HARD_RESERVATION_ID is null

   and not exists(select 1 from RRL_STORE_RETURN_UNIT b where b.RECEIPT_OPERATION_ID=p_receipt and b.PHYSICAL_UNIT_KEY=u.PHYSICAL_UNIT_KEY);

  return nvl(wire,to_clob('[]'));

 end;

 function select_disposition_units(p_receipt varchar2,p_uid varchar2,p_uom varchar2,p_qty number,p_keys clob,p_basis varchar2)return clob is

  wire clob:=disposition_units(p_receipt,p_uid,p_uom,p_basis);n number;distinct_count number;chosen number;total number;result_wire clob;

 begin

  select count(*),count(distinct K)into n,distinct_count from json_table(p_keys,'$[*]'columns(K varchar2(64)path '$'));

  if n<1 or n>10000 or n!=distinct_count then raise_application_error(-20886,'STORE_RETURN_EXACT_UNIT_SELECTION_REQUIRED');end if;

  select count(*),sum(RRL_STOCK_MATH.quantity(j.Q)),

   json_arrayagg(json_object('key'value j.K,'quantity'value j.Q,'base_uom'value j.B,'version'value j.V)order by j.K returning clob)

   into chosen,total,result_wire from json_table(wire,'$[*]'columns(K varchar2(64)path '$.key',Q varchar2(60)path '$.quantity',B varchar2(20)path '$.base_uom',V number path '$.version'))j

   where j.K in(select K from json_table(p_keys,'$[*]'columns(K varchar2(64)path '$')));

  if chosen!=n or total!=p_qty then raise_application_error(-20886,'STORE_RETURN_DISPOSITION_SELECTED_UNIT_QUANTITY_REQUIRED');end if;

  return result_wire;

 end;

 function accepted_units(p_receipt varchar2,p_uid varchar2,p_uom varchar2)return clob is

 begin return disposition_units(p_receipt,p_uid,p_uom,'ACCEPTED');end;

 function select_units(p_receipt varchar2,p_uid varchar2,p_uom varchar2,p_qty number,p_keys clob)return clob is

 begin return select_disposition_units(p_receipt,p_uid,p_uom,p_qty,p_keys,'ACCEPTED');end;

 procedure persist(p_approval varchar2,p_receipt varchar2,p_uid varchar2,p_cell varchar2,p_units clob)is

  a json_array_t:=json_array_t.parse(p_units);x json_object_t;k varchar2(64);qty number;uom varchar2(20);v number;

 begin

  for i in 0..a.get_size-1 loop

   x:=treat(a.get(i)as json_object_t);k:=x.get_string('key');qty:=RRL_STOCK_MATH.quantity(x.get_string('quantity'));uom:=x.get_string('base_uom');v:=x.get_number('version');

   insert into RRL_STORE_RETURN_UNIT(APPROVAL_OPERATION_ID,RECEIPT_OPERATION_ID,PHYSICAL_UNIT_KEY,ORIGINAL_UID,SOURCE_CELL,BASE_QTY,BASE_UOM,SOURCE_UNIT_VERSION)

    values(p_approval,p_receipt,k,p_uid,p_cell,qty,uom,v);

  end loop;

 end;

end;
/


CREATE OR REPLACE package body RRL_STORE_SCALE_API as
 procedure clear_context is
 begin
  dbms_session.set_context('RRL_STORE_SCALE_CTX','TX_ID',null);
  dbms_session.set_context('RRL_STORE_SCALE_CTX','CAPTURE_KEY',null);
 end;
 function stamp(p_text varchar2) return timestamp with time zone is
 begin
  if not regexp_like(p_text,'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}[+]00:00$','c') then raise_application_error(-20886,'SCALE_UTC_TIMESTAMP_REQUIRED');end if;
  return to_timestamp_tz(p_text,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
 end;
 procedure capture(p_source clob,p_actor varchar2,p_result out clob) is
  j json_object_t;reading json_object_t;result_json json_object_t:=json_object_t();identity_json json_array_t:=json_array_t();samples json_array_t;x json_object_t;
  device RRL_STORE_SCALE_DEVICE%rowtype;existing RRL_STORE_SCALE_CAPTURE%rowtype;
  v_device_id varchar2(100);v_capture_id varchar2(100);v_load_op varchar2(100);v_store_addr varchar2(255);v_capture_key varchar2(64);sha varchar2(64);n number;
  min_kg number;max_kg number;last_kg number;offset_no number;previous_offset number:=-1;first_offset number;span_ms number;zero_kg number;sample_no number;zero_text varchar2(30);
  measured_at timestamp with time zone;zero_at timestamp with time zone;now_at timestamp with time zone:=systimestamp;
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID') is not null then raise_application_error(-20886,'SCALE_CAPTURE_OUTSIDE_STOCK_TRANSACTION_REQUIRED');end if;
  if RRL_HAS_WRIGHT(p_actor,'store_scale_ingest')!=1 then raise_application_error(-20882,'SCALE_SENDER_FORBIDDEN');end if;
  if p_source is null or dbms_lob.getlength(p_source)>32000 then raise_application_error(-20881,'SCALE_PACKET_BOUND_32000');end if;
  j:=json_object_t.parse(p_source);v_device_id:=j.get_string('device_id');v_capture_id:=j.get_string('capture_id');v_load_op:=j.get_string('load_operation_id');v_store_addr:=j.get_string('store_address');
  if v_device_id is null or v_capture_id is null or v_load_op is null or v_store_addr is null then raise_application_error(-20886,'SCALE_SOURCE_IDENTIFIERS_REQUIRED');end if;
  select * into device from RRL_STORE_SCALE_DEVICE where DEVICE_ID=v_device_id for update;
  if device.SENDER_ID!=p_actor or device.STORE_ADDR!=v_store_addr then raise_application_error(-20882,'SCALE_DEVICE_SENDER_ADDRESS_MISMATCH');end if;
  identity_json.append(v_device_id);identity_json.append(v_capture_id);
  v_capture_key:=rawtohex(sys.dbms_crypto.hash(identity_json.to_clob,sys.dbms_crypto.hash_sh256));sha:=rawtohex(sys.dbms_crypto.hash(p_source,sys.dbms_crypto.hash_sh256));
  select count(*) into n from RRL_STORE_SCALE_CAPTURE where CAPTURE_KEY=v_capture_key;
  if n=1 then
   select * into existing from RRL_STORE_SCALE_CAPTURE where CAPTURE_KEY=v_capture_key;
   if existing.SOURCE_SHA256!=sha or dbms_lob.compare(existing.SOURCE_JSON,p_source)!=0 then raise_application_error(-20886,'SCALE_CAPTURE_PAYLOAD_CONFLICT');end if;
   p_result:=existing.RESULT_JSON;return;
  end if;
  if j.get_number('device_policy_version') is null or j.get_number('device_policy_version')!=device.POLICY_VERSION or j.get_string('calibration_ref') is null or j.get_string('calibration_ref')!=device.CALIBRATION_REF then raise_application_error(-20886,'SCALE_DEVICE_POLICY_CHANGED');end if;
  if device.ACTIVE_FLAG!=1 or device.CALIBRATED_UNTIL<now_at then raise_application_error(-20886,'SCALE_INACTIVE_OR_CALIBRATION_EXPIRED');end if;
  reading:=json_object_t.parse(RRL_SCALE_PACKET_READ.validate_json(p_source,device.CAPACITY_KG,device.RESOLUTION_KG));
  last_kg:=RRL_STOCK_MATH.quantity(reading.get_string('weight_kg'));
  min_kg:=RRL_STOCK_MATH.quantity(reading.get_string('sample_min_kg'));max_kg:=RRL_STOCK_MATH.quantity(reading.get_string('sample_max_kg'));
  sample_no:=reading.get_number('sample_count');span_ms:=reading.get_number('span_ms');
  measured_at:=RRL_SCALE_PACKET_READ.utc_stamp(reading.get_string('measured_at'));zero_at:=RRL_SCALE_PACKET_READ.utc_stamp(reading.get_string('zero_check_at'));
  select count(*) into n from RRL_TT_HU_LOAD_FACT lf where lf.LOAD_OPERATION_ID=v_load_op and lf.STATUS='DEPARTED'
   and exists(select 1 from RRL_STOCK_OPERATION op where op.OPERATION_ID=lf.LOAD_OPERATION_ID and op.STATE='APPLIED')
   and exists(select 1 from RRL_STOCK_OPERATION op where op.OPERATION_ID=lf.DEPARTURE_OPERATION_ID and op.STATE='APPLIED')
   and exists(select 1 from RRL_TT_HU_LOAD_ST st where st.LOAD_OPERATION_ID=lf.LOAD_OPERATION_ID and st.ACTIVE_FLAG=1 and st.DESTINATION_ADDR=v_store_addr)
   and not exists(select 1 from RRL_TT_HU_LOAD_ST st where st.LOAD_OPERATION_ID=lf.LOAD_OPERATION_ID and st.ACTIVE_FLAG=1 and (st.DESTINATION_ADDR is null or st.DESTINATION_ADDR!=v_store_addr));
  if n!=1 then raise_application_error(-20886,'SCALE_ACTUAL_DEPARTED_DESTINATION_REQUIRED');end if;
  result_json.put('capture_key',v_capture_key);result_json.put('device_id',v_device_id);result_json.put('capture_id',v_capture_id);result_json.put('load_operation_id',v_load_op);result_json.put('store_address',v_store_addr);
  result_json.put('gross_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(last_kg));result_json.put('device_policy_version',device.POLICY_VERSION);
  result_json.put('source_sha256',sha);result_json.put('measured_at',j.get_string('measured_at'));result_json.put('received_at',to_char(now_at,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
  result_json.put('calibration_ref',device.CALIBRATION_REF);result_json.put('resolution_kg',RRL_STOCK_PLAN_HELPER.decimal_text(device.RESOLUTION_KG));result_json.put('sample_count',sample_no);result_json.put('span_ms',span_ms);
  result_json.put('status','ARCHIVED');result_json.put('receipt_confirmed',false);p_result:=result_json.to_clob;
  dbms_session.set_context('RRL_STORE_SCALE_CTX','TX_ID',dbms_transaction.local_transaction_id(true));dbms_session.set_context('RRL_STORE_SCALE_CTX','CAPTURE_KEY',v_capture_key);
  insert into RRL_STORE_SCALE_CAPTURE(CAPTURE_KEY,DEVICE_ID,CAPTURE_ID,LOAD_OPERATION_ID,STORE_ADDR,DEVICE_POLICY_VERSION,DEVICE_CALIBRATION_REF,CAPACITY_KG,RESOLUTION_KG,GROSS_WEIGHT_KG,SAMPLE_MIN_KG,SAMPLE_MAX_KG,SAMPLE_COUNT,SPAN_MS,MEASURED_AT,ZERO_CHECK_AT,RECEIVED_AT,RECORDED_BY,SOURCE_SHA256,SOURCE_JSON,RESULT_JSON)
  values(v_capture_key,v_device_id,v_capture_id,v_load_op,v_store_addr,device.POLICY_VERSION,device.CALIBRATION_REF,device.CAPACITY_KG,device.RESOLUTION_KG,last_kg,min_kg,max_kg,sample_no,span_ms,measured_at,zero_at,now_at,p_actor,sha,p_source,p_result);
  clear_context;
 exception when no_data_found then clear_context;raise_application_error(-20886,'SCALE_EXPLICIT_DEVICE_REQUIRED');
 when others then clear_context;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STORE_UNLOAD_API as
 g_writing boolean:=false;
 function writing return boolean is begin return g_writing;end;
 procedure start_unloading(p_request clob,p_actor varchar2,p_result out clob)is
 d json_object_t:=json_object_t.parse(p_request);v json_object_t;j json_object_t:=json_object_t();
 op varchar2(100):=d.get_string('operation_id');load_op varchar2(100):=d.get_string('load_operation_id');addr_text varchar2(255):=d.get_string('store_address');
 expected varchar2(64):=d.get_string('expected_composition_signature');raw_domain clob;old_request clob;old_actor nvarchar2(50);n number;trip number;started timestamp with time zone;
 f json_array_t:=json_array_t();r json_array_t:=json_array_t();state varchar2(20);root_node json_object_t;scan_text varchar2(200):=d.get_string('scan_place');root_text varchar2(200);signature varchar2(64);savepoint_ready boolean:=false;plan_started boolean:=false;keys json_key_list:=d.get_keys;
 begin
  if op is null or not regexp_like(op,'^[A-Za-z0-9_.:-]+$')or length(op)>100 or load_op is null or addr_text is null or keys.count!=6
   or expected is null or not regexp_like(expected,'^[A-F0-9]{64}$')
   or d.get_boolean('before_cameras')is null or not d.get_boolean('before_cameras')
   then raise_application_error(-20886,'UNLOAD_START_INPUT_REQUIRED');end if;
  for i in 1..keys.count loop
   if keys(i)not in('operation_id','load_operation_id','store_address','expected_composition_signature','scan_place','before_cameras')
    then raise_application_error(-20886,'UNLOAD_START_UNKNOWN_FIELD');end if;
  end loop;
  RRL_STOCK_PLAN_HELPER.fence(f,'RELEASE','STOCK');RRL_STOCK_PLAN_HELPER.fence(f,'CONFIG','WAREHOUSE');
  RRL_STOCK_PLAN_HELPER.anchor(r,10,'OP',op);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',load_op);
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','STORE.RECEIPT.LOAD:'||load_op);
  RRL_STOCK_LOCK_API.begin_plan;plan_started:=true;RRL_STOCK_LOCK_API.acquire_policies(f.to_clob);RRL_STOCK_LOCK_API.acquire_resources(r.to_clob);
  savepoint store_unload_start;savepoint_ready:=true;
  select STATE into state from RRL_STOCK_RELEASE where RELEASE_ID=1;
  if state!='ACTIVE'then raise_application_error(-20860,'UNLOAD_START_RELEASE_CLOSED');end if;
  RRL_STOCK_STORE_RECEIPT_READ.describe_load(load_op,p_actor,addr_text,raw_domain);v:=json_object_t.parse(raw_domain);
  begin
   select REQUEST_JSON,ACTOR,RESULT_JSON into old_request,old_actor,p_result from RRL_STORE_UNLOAD_START where OPERATION_ID=op;
   select count(*)into n from dual where json_equal(old_request,p_request);
   if n!=1 or old_actor!=p_actor then raise_application_error(-20864,'UNLOAD_START_OPERATION_CONFLICT');end if;
   RRL_STOCK_LOCK_API.clear_plan;return;
  exception when no_data_found then null;end;
  if v.get_boolean('already_received')then raise_application_error(-20886,'UNLOAD_START_RECEIPT_ALREADY_COMPLETED');end if;
  if expected!=v.get_string('composition_signature')then raise_application_error(-20890,'CLOSURE_CHANGED: unload manifest');end if;
  root_node:=treat(v.get_object('snapshot').get_array('nodes').get(0)as json_object_t);
  if scan_text is null or(scan_text!=v.get_string('root_scan_identifier')and
    (root_node.get_string('kind')='CASE'or v.get_string('root_sscc')is null or scan_text!=v.get_string('root_sscc')))
   then raise_application_error(-20886,'UNLOAD_START_PHYSICAL_PLACE_SCAN_REQUIRED');end if;
  select count(*)into n from RRL_STORE_UNLOAD_START where LOAD_OPERATION_ID=load_op;
  if n!=0 then raise_application_error(-20886,'UNLOAD_START_EXISTS');end if;
  select TT_ID into trip from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=load_op for update;
  started:=systimestamp;root_text:=v.get_string('root');signature:=v.get_string('composition_signature');
  j.put('operation_id',op);j.put('load_operation_id',load_op);j.put('store_address',addr_text);j.put('root',root_text);j.put('trip_id',trip);
  j.put('started_at_instant',to_char(started,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
  j.put('time_source','SYSTEM_CAPTURED');j.put('status','STARTED');j.put('stock_changed',false);j.put('cost_posted',false);p_result:=j.to_clob;
  g_writing:=true;
  insert into RRL_STORE_UNLOAD_START(OPERATION_ID,LOAD_OPERATION_ID,STORE_ADDR,ROOT_KEY,COMPOSITION_SIGNATURE,ACTOR,STARTED_AT_INSTANT,REQUEST_JSON,RESULT_JSON)
   values(op,load_op,addr_text,root_text,signature,p_actor,started,p_request,p_result);
  g_writing:=false;RRL_STOCK_LOCK_API.clear_plan;
 exception when others then g_writing:=false;if savepoint_ready then rollback to store_unload_start;end if;if plan_started then RRL_STOCK_LOCK_API.clear_plan;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STORE_UNLOAD_CORE as
 g_writing boolean:=false;
 function writing return boolean is begin return g_writing;end;
 procedure validate_input(p_metadata json_object_t,p_domain json_object_t)is
 m json_object_t;s RRL_STORE_UNLOAD_START%rowtype;n number;root_node json_object_t;keys json_key_list;load_op varchar2(100):=p_domain.get_string('load_operation_id');
 method_value varchar2(20);difficulty boolean;loader boolean;start_op varchar2(100);
 begin
  select count(*)into n from RRL_STORE_UNLOAD_START where LOAD_OPERATION_ID=load_op;
  if not p_metadata.has('unloading')or p_metadata.get('unloading').is_null then
   if n!=0 then raise_application_error(-20886,'UNLOAD_FINISH_DETAILS_REQUIRED');end if;return;
  end if;
  m:=p_metadata.get_object('unloading');keys:=m.get_keys;
  if keys.count!=5 then raise_application_error(-20886,'UNLOAD_FINISH_FIELDS_REQUIRED');end if;
  for i in 1..keys.count loop
   if keys(i)not in('start_operation_id','method','rolling_difficult','loader_present','evidence_reference')
    then raise_application_error(-20886,'UNLOAD_FINISH_UNKNOWN_FIELD');end if;
  end loop;
  start_op:=m.get_string('start_operation_id');
  begin select *into s from RRL_STORE_UNLOAD_START where OPERATION_ID=start_op;
  exception when no_data_found then raise_application_error(-20886,'UNLOAD_SYSTEM_START_REQUIRED');end;
  if s.LOAD_OPERATION_ID!=load_op or s.STORE_ADDR!=p_domain.get_string('store_address')or s.ROOT_KEY!=p_domain.get_string('root')
   or s.COMPOSITION_SIGNATURE!=p_domain.get_string('composition_signature')
   then raise_application_error(-20886,'UNLOAD_ORIGINAL_SOURCE_REQUIRED');end if;
  method_value:=m.get_string('method');difficulty:=m.get_boolean('rolling_difficult');loader:=m.get_boolean('loader_present');
  if method_value is null or method_value not in('ROLL_CAGE','PALLET','MANUAL')or difficulty is null or loader is null
   or trim(m.get_string('evidence_reference'))is null or lengthb(m.get_string('evidence_reference'))>255
   then raise_application_error(-20886,'UNLOAD_ACTUAL_DETAILS_REQUIRED');end if;
  root_node:=treat(p_domain.get_object('snapshot').get_array('nodes').get(0)as json_object_t);
  if method_value='ROLL_CAGE'and(root_node.get_string('kind')!='CONTAINER'or root_node.get_string('type')!='ROLL_CAGE')
   then raise_application_error(-20886,'UNLOAD_ROLL_CAGE_SOURCE_REQUIRED');end if;
  if method_value='PALLET' then
   if nvl(root_node.get_string('kind'),'~')='CONTAINER'and nvl(root_node.get_string('type'),'~')='PALLET' then null;
   elsif nvl(root_node.get_string('kind'),'~')='STOCK' then
    -- Frozen physical loading proof, never infer pallet type from current SKU/store settings.
    select count(*)into n from RRL_TT_LOAD_FLOOR_FACT f
     join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=f.LOAD_OPERATION_ID
     join RRL_STOCK_OPERATION o on o.OPERATION_ID=l.LOAD_OPERATION_ID
     where f.LOAD_OPERATION_ID=load_op and f.TYPE_ORIGIN='ROOT_STOCK_TYPE'
      and l.ROOT_UID=s.ROOT_KEY and l.STATUS='DEPARTED'and o.STATE='APPLIED'
      and json_value(f.CONFIRMATION_JSON,'$.root')=l.ROOT_UID
      and json_value(f.CONFIRMATION_JSON,'$.type_origin')='ROOT_STOCK_TYPE'
      and json_value(f.CONFIRMATION_JSON,'$.pallet_type_id' returning number)=f.PALLET_TYPE_ID;
    if n!=1 then raise_application_error(-20886,'UNLOAD_PALLET_LOADING_PROOF_REQUIRED');end if;
   else raise_application_error(-20886,'UNLOAD_PALLET_SOURCE_REQUIRED');end if;
  end if;
  if difficulty and(method_value!='ROLL_CAGE'or not loader)then raise_application_error(-20886,'UNLOAD_DIFFICULT_ROLL_REQUIRES_LOADER');end if;
 end;
 procedure capture(p_request clob,p_actor varchar2)is
 d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');u json_object_t;
 op varchar2(100):=d.get_string('operation_id');source_op varchar2(100);method_value varchar2(20);reference_value varchar2(255);difficulty number;loader number;
 s RRL_STORE_UNLOAD_START%rowtype;receipt RRL_STORE_RECEIPT_FACT%rowtype;body clob;kind varchar2(80);state varchar2(20);
 begin
  if not m.has('unloading')or m.get('unloading').is_null then return;end if;
  if nvl(sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID'),'~')!=op or
   sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)
   then raise_application_error(-20863,'UNLOAD_FINISH_ROOT_REQUIRED');end if;
  select COMMAND_TYPE,STATE into kind,state from RRL_STOCK_OPERATION where OPERATION_ID=op;
  if kind!='STORE_RECEIPT'or state!='IN_FLIGHT'then raise_application_error(-20863,'UNLOAD_FINISH_RECEIPT_OWNER_REQUIRED');end if;
  u:=m.get_object('unloading');source_op:=u.get_string('start_operation_id');
  select *into s from RRL_STORE_UNLOAD_START where OPERATION_ID=source_op;
  select *into receipt from RRL_STORE_RECEIPT_FACT where OPERATION_ID=op;
  if receipt.LOAD_OPERATION_ID!=s.LOAD_OPERATION_ID or receipt.STORE_ADDR!=s.STORE_ADDR or receipt.RECEIVED_BY!=p_actor
   or receipt.RECEIVED_AT<s.STARTED_AT_INSTANT then raise_application_error(-20886,'UNLOAD_FINISH_ORIGINAL_RECEIPT_REQUIRED');end if;
  method_value:=u.get_string('method');reference_value:=u.get_string('evidence_reference');
  difficulty:=case when u.get_boolean('rolling_difficult')then 1 else 0 end;loader:=case when u.get_boolean('loader_present')then 1 else 0 end;
  body:=u.to_clob;g_writing:=true;
  insert into RRL_STORE_UNLOAD_FACT(RECEIPT_OPERATION_ID,START_OPERATION_ID,LOAD_OPERATION_ID,STORE_ADDR,METHOD,ROLLING_DIFFICULT,LOADER_PRESENT,EVIDENCE_REFERENCE,ACTOR,FINISHED_AT_INSTANT,PAYLOAD_JSON)
  values(op,source_op,s.LOAD_OPERATION_ID,s.STORE_ADDR,method_value,difficulty,loader,reference_value,p_actor,receipt.RECEIVED_AT,body);
  g_writing:=false;
 exception when others then g_writing:=false;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_STORE_WINDOW_RULES as
 -- Session-local bounded cache of timezone offsets by explicit zone/local date.
 -- It caches timezone rules only, never editable store configuration or resolved windows.
 type offsets_map is table of sys.odcinumberlist index by varchar2(100);
 g_offsets offsets_map;
 function instant(p_wall date,p_zone varchar2)return date is
  v_result date;v_count number;offsets sys.odcinumberlist;cache_key varchar2(100);
 begin
  cache_key:=p_zone||':'||to_char(trunc(p_wall),'YYYY-MM-DD');
  if not g_offsets.exists(cache_key)then
   if g_offsets.count>=256 then g_offsets.delete;end if;
   -- One set-based SQL (97 rows), once per zone/day, not 97 SQL calls per endpoint.
   select distinct cast(from_tz(cast(trunc(p_wall)+(level-49)/24 as timestamp),'UTC')at time zone(p_zone)as date)
    -(trunc(p_wall)+(level-49)/24) bulk collect into offsets from dual connect by level<=97;
   g_offsets(cache_key):=offsets;
  end if;
  offsets:=g_offsets(cache_key);
  select count(distinct candidate),min(candidate) into v_count,v_result from(
   select p_wall-column_value candidate from table(offsets))
   where cast(from_tz(cast(candidate as timestamp),'UTC')at time zone(p_zone)as date)=p_wall;
  if v_count!=1 then raise_application_error(-20886,'STORE_WINDOW_DST_AMBIGUOUS_OR_NONEXISTENT');end if;
  return v_result;
 end;
 procedure material(p_source clob,p_result out clob)is
  a json_array_t:=json_array_t();o json_object_t;rows_json json_array_t;item json_object_t;n number:=0;k number;
 begin
  for r in(select distinct address from json_table(p_source,'$.members[*]'columns(address varchar2(255)path '$.address'))order by address)loop
   n:=n+1;if n>200 then raise_application_error(-20886,'STORE_WINDOW_ADDRESS_BOUND_200');end if;
   o:=json_object_t();o.put('address',r.address);rows_json:=json_array_t();
   begin
    for h in(select PROFILE_VERSION,RECEIVING_WINDOW_MODE,TIMEZONE_REGION,MAX_VEHICLE_OUTER_HEIGHT_MM,MAX_VEHICLE_OUTER_LENGTH_MM
     from RRL_STORE_PROFILE where STORE_ADDR=r.address)loop
     o.put('profile_version',h.PROFILE_VERSION);o.put('mode',h.RECEIVING_WINDOW_MODE);o.put('time_zone',h.TIMEZONE_REGION);
     o.put('max_vehicle_outer_height_mm',h.MAX_VEHICLE_OUTER_HEIGHT_MM);o.put('max_vehicle_outer_length_mm',h.MAX_VEHICLE_OUTER_LENGTH_MM);
    end loop;
    if not o.has('profile_version')then o.put('profile_absent',true);o.put('mode','UNCONFIGURED');else o.put('profile_absent',false);end if;
    k:=0;for w in(select WEEKDAY,FROM_MINUTE,TO_MINUTE from RRL_STORE_RECEIVING_WINDOW where STORE_ADDR=r.address order by WEEKDAY,FROM_MINUTE,TO_MINUTE)loop
     k:=k+1;if k>56 then raise_application_error(-20886,'STORE_WEEKLY_INTERVAL_BOUND_56');end if;
     item:=json_object_t();item.put('weekday',w.WEEKDAY);item.put('from_minute',w.FROM_MINUTE);item.put('to_minute',w.TO_MINUTE);rows_json.append(item);
    end loop;
   end;
   o.put('windows',rows_json);a.append(o);
  end loop;p_result:=a.to_clob;
 end;
 procedure resolve(p_source clob,p_address varchar2,p_arrival date,p_zone varchar2,p_duration number,
  p_open out date,p_close out date,p_service out date,p_kind out varchar2,p_error out varchar2)is
  lo date;hi date;wf date;wt date;weekly_needed boolean:=false;members_count number:=0;
  b json_object_t:=json_object_t.parse(p_source);profiles json_array_t;profile json_object_t;found_count number:=0;
  zone_name varchar2(64);day_local date;arrival_utc date;opening_utc date;closing_utc date;candidate date;
  count_today number:=0;wire clob;weekday_no number;last_end number:=-1;interval_count number:=0;
 begin
  p_open:=null;p_close:=null;p_service:=null;p_error:=null;p_kind:='ST_MATERIALIZED';
  if p_arrival is null then p_error:='ROUTE_ARRIVAL_UNKNOWN';return;end if;
  if p_duration is null or p_duration<=0 or p_duration>1440 then p_error:='DESTINATION_RULE_INVALID';return;end if;
  for m in(select wf,wt from json_table(p_source,'$.members[*]'columns(a varchar2(255)path '$.address',wf varchar2(30)path '$.delivery_window_from',wt varchar2(30)path '$.delivery_window_to'))where a=p_address)loop
   members_count:=members_count+1;
   if m.wf is null and m.wt is null then weekly_needed:=true;
   elsif m.wf is null or m.wt is null then p_error:='DELIVERY_WINDOW_PARTIAL';return;
   else
    wf:=to_date(m.wf,'YYYY-MM-DD HH24:MI:SS');wt:=to_date(m.wt,'YYYY-MM-DD HH24:MI:SS');
    if wf>=wt then p_error:='DELIVERY_WINDOW_REVERSED_OR_EMPTY';return;end if;
    if lo is null or wf>lo then lo:=wf;end if;if hi is null or wt<hi then hi:=wt;end if;
   end if;
  end loop;
  if members_count=0 then p_error:='DELIVERY_MEMBERS_MISSING';return;end if;
  if lo is not null and lo>=hi then p_error:='DELIVERY_WINDOW_DISJOINT';return;end if;
  if not weekly_needed then p_open:=lo;p_close:=hi;p_service:=greatest(p_arrival,lo);return;end if;
  p_kind:=case when lo is null then 'STORE_WEEKLY'else 'ST_AND_STORE_WEEKLY'end;
  profiles:=b.get_array('store_window_profiles');
  if profiles is not null and profiles.get_size>0 then for i in 0..profiles.get_size-1 loop
   profile:=treat(profiles.get(i)as json_object_t);if profile.get_string('address')=p_address then found_count:=found_count+1;wire:=profile.to_clob;end if;
  end loop;end if;
  if found_count!=1 then p_error:='DELIVERY_WINDOW_UNCONFIGURED';return;end if;
  profile:=json_object_t.parse(wire);
  if profile.get_string('mode')!='WEEKLY' then p_error:='DELIVERY_WINDOW_UNCONFIGURED';return;end if;
  zone_name:=profile.get_string('time_zone');if zone_name is null then p_error:='STORE_TIMEZONE_REQUIRED';return;end if;
  arrival_utc:=instant(p_arrival,p_zone);
  select trunc(cast(from_tz(cast(arrival_utc as timestamp),'UTC')at time zone(zone_name)as date))into day_local from dual;
  weekday_no:=day_local-trunc(day_local,'IW')+1;
  -- Deliberately same service day: CLOSED is a refusal, never an implicit overnight reschedule.
  -- At most 8 intervals, one local day, no gap between intervals is treated as available.
  for w in(select f,t from json_table(wire,'$.windows[*]'columns(d number path '$.weekday',f number path '$.from_minute',t number path '$.to_minute'))where d=weekday_no order by f,t)loop
   count_today:=count_today+1;
   if count_today>8 or w.f is null or w.t is null or w.f<0 or w.t>1440 or w.f>=w.t or w.f!=trunc(w.f)or w.t!=trunc(w.t)or w.f<last_end then p_error:='STORE_WEEKLY_INTERVAL_INVALID';return;end if;
   last_end:=w.t;
   opening_utc:=instant(day_local+w.f/1440,zone_name);closing_utc:=instant(day_local+w.t/1440,zone_name);
   select cast(from_tz(cast(opening_utc as timestamp),'UTC')at time zone(p_zone)as date),cast(from_tz(cast(closing_utc as timestamp),'UTC')at time zone(p_zone)as date)into wf,wt from dual;
   if lo is not null then wf:=greatest(wf,lo);wt:=least(wt,hi);end if;
   candidate:=greatest(p_arrival,wf);
   if candidate+p_duration/1440<=wt and p_service is null then p_open:=wf;p_close:=wt;p_service:=candidate;end if;
  end loop;
  if count_today=0 then p_error:='STORE_CLOSED';elsif p_service is null then p_error:='STORE_NO_FEASIBLE_INTERVAL';end if;
 exception when others then
  if sqlcode=-20886 then p_error:=substr(sqlerrm,instr(sqlerrm,':')+2,150);return;end if;
  if sqlcode in(-1882,-1878,-1883,-1843,-1847,-1861,-1839)then p_error:='STORE_TIMEZONE_OR_WINDOW_INVALID';return;end if;
  raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_ST_DEFER_API as

 g_tx varchar2(100);

 function write_allowed return number is begin

  if g_tx is not null and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;

 end;

 procedure scope(p_ware number,p_actor varchar2,p_right varchar2)is n number;begin

  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,p_right)=1

   and(u.WARE_ID=p_ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');

  if n!=1 or p_ware is null then raise_application_error(-20882,'ST_DEFER_CURRENT_WARE_ACTOR_REQUIRED');end if;

 end;

 procedure access_st(p_st varchar2,p_actor varchar2,p_right varchar2,p_ware out number)is n number;begin

  select count(distinct WARE_ID),min(WARE_ID)into n,p_ware from RRL_SBORKA_PALLETS where ST_NUMBER=p_st;

  if n!=1 then raise_application_error(-20886,'ST_DEFER_ONE_CURRENT_WARE_REQUIRED');end if;

  select count(*)into n from RRL_SBORKA_PALLETS where ST_NUMBER=p_st and WARE_ID is null;

  if n>0 then raise_application_error(-20886,'ST_DEFER_NULL_WARE_REFUSED');end if;

  scope(p_ware,p_actor,p_right);

 end;

 procedure snapshot(p_st varchar2,p_actor varchar2,p_right varchar2,p_json out clob,p_hash out varchar2,p_ware out number,p_trip out number)is

  a json_array_t:=json_array_t();cargo json_array_t:=json_array_t();b json_object_t:=json_object_t();item json_object_t;v_count number:=0;v_cargo number:=0;v_trip_count number;v_ware_count number;

 begin

  select count(distinct WARE_ID),count(distinct nvl(TRANSTASK_ID,0)),min(WARE_ID),min(TRANSTASK_ID)

   into v_ware_count,v_trip_count,p_ware,p_trip from RRL_SBORKA_PALLETS where ST_NUMBER=p_st;

  if v_ware_count!=1 or v_trip_count!=1 or p_trip is null or p_trip<=0 then raise_application_error(-20886,'ST_DEFER_ONE_CURRENT_WARE_TRIP_REQUIRED');end if;

  access_st(p_st,p_actor,p_right,p_ware);

  for x in(select ID,PALLET_UID,WARE_ID,TRANSTASK_ID,CONDITION,ADDR,STDATE from RRL_SBORKA_PALLETS where ST_NUMBER=p_st order by ID fetch first 201 rows only)loop

   v_count:=v_count+1;if v_count>200 then raise_application_error(-20886,'ST_DEFER_MEMBER_BOUND_200');end if;

   item:=json_object_t();item.put('id',x.ID);item.put('pallet_identifier',x.PALLET_UID);item.put('warehouse_id',x.WARE_ID);

   item.put('trip_id',x.TRANSTASK_ID);item.put('condition',x.CONDITION);item.put('address',x.ADDR);item.put('st_date',to_char(x.STDATE,'YYYY-MM-DD HH24:MI:SS'));

   a.append(item);

  end loop;

  for x in(select r.ID,r.PALLET_UID,r.ARTICUL,r.EI,r.QUANTITY,r.PACK_COUNT,r.ORDER_WEIGHT,r.TAREWEIGHT,r.TARESIZE

   from RRL_SBORKA_PALLET_ROWS r join RRL_SBORKA_PALLETS p on p.PALLET_UID=r.PALLET_UID where p.ST_NUMBER=p_st

   order by r.PALLET_UID,r.ID fetch first 10001 rows only)loop

   v_cargo:=v_cargo+1;if v_cargo>10000 then raise_application_error(-20886,'ST_DEFER_CARGO_BOUND_10000');end if;

   item:=json_object_t();item.put('id',x.ID);item.put('pallet_identifier',x.PALLET_UID);item.put('articul',x.ARTICUL);item.put('unit_code',x.EI);

   item.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(x.QUANTITY));item.put('pack_count',RRL_STOCK_PLAN_HELPER.decimal_text(x.PACK_COUNT));

   item.put('weight',RRL_STOCK_PLAN_HELPER.decimal_text(x.ORDER_WEIGHT));item.put('pack_weight',RRL_STOCK_PLAN_HELPER.decimal_text(x.TAREWEIGHT));item.put('pack_size',RRL_STOCK_PLAN_HELPER.decimal_text(x.TARESIZE));

   cargo.append(item);

  end loop;

  b.put('cargo',cargo);

  b.put('st_number',p_st);b.put('warehouse_id',p_ware);b.put('source_trip_id',p_trip);b.put('members',a);

  for x in(select ID,CONDITION,TRANSPORT,SHIPMENT_DATE,SHIPMENT_TIME,DELETED,PAY_ORDER_ID from RRL_TRANSPORT_TASK where ID=p_trip)loop

   item:=json_object_t();item.put('id',x.ID);item.put('condition',x.CONDITION);item.put('vehicle',x.TRANSPORT);

   item.put('shipment_date',to_char(x.SHIPMENT_DATE,'YYYY-MM-DD'));item.put('shipment_time',to_char(x.SHIPMENT_TIME,'YYYY-MM-DD HH24:MI:SS'));

   item.put('deleted',x.DELETED);item.put('pay_order_id',x.PAY_ORDER_ID);b.put('source_trip',item);

  end loop;

  declare prepared json_object_t:=json_object_t.parse(RRL_ST_DEFER_PHYSICAL.snapshot(p_st,p_ware));begin if prepared.get_string('state')!='UNPICKED'then b.put('physical_preparation',prepared);end if;end;

  p_json:=b.to_clob;p_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_json,sys.dbms_crypto.hash_sh256)));

 end;

 procedure context(p_st varchar2,p_actor varchar2,p_result out clob)is

  src clob;hash varchar2(64);ware number;trip number;version_no number;b json_object_t;

 begin

  snapshot(p_st,p_actor,'transport_dispatch_view',src,hash,ware,trip);

  select nvl(max(VERSION_NO),0)into version_no from RRL_ST_DEFER_DECISION where ST_NUMBER=p_st;

  b:=json_object_t.parse(src);b.put('version',version_no);b.put('source_hash',hash);b.put('stock_changed',false);p_result:=b.to_clob;

 end;

 procedure history(p_st varchar2,p_actor varchar2,p_after number,p_result out clob)is

  ware number;a json_array_t:=json_array_t();b json_object_t:=json_object_t();item json_object_t;n number:=0;last_version number;more boolean:=false;

 begin

  access_st(p_st,p_actor,'transport_dispatch_view',ware);

  if p_after is null or p_after<0 or trunc(p_after)!=p_after then raise_application_error(-20886,'ST_DEFER_HISTORY_CURSOR_REQUIRED');end if;

  for x in(select VERSION_NO,RESULT_JSON from RRL_ST_DEFER_DECISION where ST_NUMBER=p_st and WARE_ID=ware and VERSION_NO>p_after order by VERSION_NO fetch first 51 rows only)loop

   n:=n+1;if n>50 then more:=true;exit;end if;

   item:=json_object_t.parse(x.RESULT_JSON);a.append(item);last_version:=x.VERSION_NO;

  end loop;

  b.put('st_number',p_st);b.put('warehouse_id',ware);b.put('rows',a);b.put('has_more',more);

  if more then b.put('next_after_version',last_version);else b.put_null('next_after_version');end if;

  b.put('stock_changed',false);p_result:=b.to_clob;

 end;

 procedure apply_decision(p_operation varchar2,p_actor varchar2,p_body clob,p_result out clob)is

  b json_object_t;src clob;hash varchar2(64);ware number;source_trip number;target_trip number;

  source_num varchar2(100);target_num varchar2(100);source_day date;target_day date;

  saved RRL_ST_DEFER_DECISION%rowtype;request_hash varchar2(64);version_no number;v_st varchar2(100);n number;

  v_meta boolean:=false;v_saved boolean:=false;answer varchar2(4000);assigned clob;sts json_array_t:=json_array_t();result json_object_t:=json_object_t();

 begin

  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_body is null or dbms_lob.getlength(p_body)>4000 then raise_application_error(-20886,'ST_DEFER_INPUT_BOUND');end if;

  b:=json_object_t.parse(p_body);v_st:=b.get_string('st_number');target_trip:=b.get_number('target_trip_id');

  if b.get_size!=6 or v_st is null or target_trip is null or target_trip<=0 or trunc(target_trip)!=target_trip

   or b.get_number('expected_version')is null or b.get_number('expected_version')<0 or trunc(b.get_number('expected_version'))!=b.get_number('expected_version')

   or b.get_string('source_hash')is null or b.get_string('reason')is null or length(trim(b.get_string('reason')))<8

   or b.get_string('reference')is null or length(trim(b.get_string('reference')))<8 then raise_application_error(-20886,'ST_DEFER_EXPLICIT_SOURCE_REASON_REQUIRED');end if;

  access_st(v_st,p_actor,'transport_dispatch_edit',ware);

  request_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));

  RRL_STOCK_METADATA_TX.begin_change(p_actor,'transport_dispatch_edit');v_meta:=true;savepoint RRL_ST_DEFER276;v_saved:=true;

  -- Current access is mandatory before replay; a saved replay does not regenerate physical facts.

  access_st(v_st,p_actor,'transport_dispatch_edit',ware);

  begin select *into saved from RRL_ST_DEFER_DECISION where OPERATION_ID=p_operation;

   if saved.ACTOR!=p_actor or saved.ST_NUMBER!=v_st or saved.REQUEST_HASH!=request_hash or dbms_lob.compare(saved.REQUEST_JSON,p_body)!=0 then raise_application_error(-20886,'ST_DEFER_OPERATION_PAYLOAD_CONFLICT');end if;

   scope(saved.WARE_ID,p_actor,'transport_dispatch_edit');p_result:=saved.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;

  exception when no_data_found then null;end;

  snapshot(v_st,p_actor,'transport_dispatch_edit',src,hash,ware,source_trip);

  if source_trip=target_trip then raise_application_error(-20886,'ST_DEFER_DIFFERENT_EXISTING_TRIP_REQUIRED');end if;

  select TRANSPORT,SHIPMENT_DATE into source_num,source_day from RRL_TRANSPORT_TASK where ID=source_trip;

  select TRANSPORT,SHIPMENT_DATE into target_num,target_day from RRL_TRANSPORT_TASK where ID=target_trip;

  for v in(select ID from RRL_TR_VEHICLE where NUM in(source_num,target_num)order by ID)loop

   select ID into n from RRL_TR_VEHICLE where ID=v.ID for update wait 3;

  end loop;

  for t in(select ID from RRL_TRANSPORT_TASK where ID in(source_trip,target_trip)order by ID)loop

   select ID into n from RRL_TRANSPORT_TASK where ID=t.ID for update wait 3;

   select count(*)into n from RRL_TRANSPORT_TASK where ID=t.ID and CONDITION='Спланирован'and nvl(DELETED,0)=0 and nvl(PAY_ORDER_ID,0)=0;

   if n!=1 then raise_application_error(-20886,'ST_DEFER_PLANNED_UNBILLED_TRIPS_REQUIRED');end if;

  end loop;

  select count(*)into n from RRL_TRANSPORT_TASK where (ID=source_trip and nvl(TRANSPORT,'~')!=nvl(source_num,'~'))or(ID=target_trip and nvl(TRANSPORT,'~')!=nvl(target_num,'~'));

  if n>0 then raise_application_error(-20886,'ST_DEFER_VEHICLE_CHANGED_RETRY');end if;

  select SHIPMENT_DATE into target_day from RRL_TRANSPORT_TASK where ID=target_trip;

  if target_day is null or source_day is null or trunc(target_day)<trunc(source_day)then raise_application_error(-20886,'ST_DEFER_TARGET_DAY_BEFORE_PROMISE');end if;

  n:=0;

  for x in(select ID from RRL_SBORKA_PALLETS where ST_NUMBER=v_st or TRANSTASK_ID=target_trip order by ID fetch first 401 rows only)loop

   n:=n+1;if n>400 then raise_application_error(-20886,'ST_DEFER_TOTAL_MEMBER_BOUND_400');end if;

   declare locked number;begin select ID into locked from RRL_SBORKA_PALLETS where ID=x.ID for update wait 3;end;

  end loop;

  snapshot(v_st,p_actor,'transport_dispatch_edit',src,hash,ware,source_trip);

  if hash!=b.get_string('source_hash')then raise_application_error(-20886,'ST_DEFER_SOURCE_CHANGED');end if;

  select nvl(max(VERSION_NO),0)into version_no from RRL_ST_DEFER_DECISION where ST_NUMBER=v_st;

  if version_no!=b.get_number('expected_version')then raise_application_error(-20886,'ST_DEFER_VERSION_CHANGED');end if;

  select count(*)into n from RRL_SBORKA_PALLETS p where p.ST_NUMBER=v_st and(

   nvl(p.CONDITION,0)=2 or exists(select 1 from RRL_TT_HU_LOAD_ST ls join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=ls.LOAD_OPERATION_ID where ls.SBORKA_PALLET_ID=p.ID and ls.ACTIVE_FLAG=1 and l.STATUS in('LOADED','DEPARTED'))

);

  if n>0 then raise_application_error(-20886,'ST_DEFER_UNLOADED_SUPPORTED_PHYSICAL_SOURCE_ONLY');end if;

  select count(*)into n from RRL_CASE_PICK_TASK c join RRL_SBORKA_PALLETS p on p.ID=c.LEGACY_SBORKA_PALLET_ID where p.ST_NUMBER=v_st;

  if n>0 then

   declare prep json_object_t:=json_object_t.parse(src).get_object('physical_preparation');begin

    if prep is null or nvl(prep.get_string('state'),'NONE')not in('PREPARED_CASE','PREPARED_CASES','PREPARED_HU','PREPARED_PLACES')then raise_application_error(-20886,'ST_DEFER_PREPARED_CASE_REQUIRED');end if;

   end;

  end if;

  select count(*)into n from RRL_SBORKA_PALLETS where ST_NUMBER=v_st and STDATE is not null and trunc(STDATE)>trunc(target_day);

  if n>0 then raise_application_error(-20886,'ST_DEFER_TARGET_DAY_BEFORE_ST_PROMISE');end if;

  answer:=RRL_TT_ADD_PALL(0,v_st);

  if lower(substr(nvl(answer,'OK'),1,3))='err'then raise_application_error(-20886,'ST_DEFER_ORIGINAL_UNASSIGN_FAILED');end if;

  sts.append(v_st);RRL_TRANSPORT_PLAN_API.assign_sts(target_trip,sts.to_clob,p_actor,assigned);

  n:=RRL_TT_REORDER_ADR(source_trip);

  result.put('operation_id',p_operation);result.put('st_number',v_st);result.put('version',version_no+1);result.put('warehouse_id',ware);

  result.put('source_trip_id',source_trip);result.put('target_trip_id',target_trip);result.put('source_hash',hash);result.put('source',json_object_t.parse(src));

  result.put('original_shipping_date',to_char(source_day,'YYYY-MM-DD'));result.put('target_shipping_date',to_char(target_day,'YYYY-MM-DD'));

  result.put('reason',b.get_string('reason'));result.put('reference',b.get_string('reference'));result.put('actor',p_actor);

  if json_object_t.parse(src).has('physical_preparation')then result.put('physical_preparation',json_object_t.parse(src).get_object('physical_preparation'));end if;

  result.put('assignment',json_object_t.parse(assigned));result.put('stock_changed',false);result.put('original_demand_changed',false);result.put('operational_admission',false);

  p_result:=result.to_clob;g_tx:=dbms_transaction.local_transaction_id(false);

  insert into RRL_ST_DEFER_DECISION(OPERATION_ID,ST_NUMBER,VERSION_NO,SOURCE_TT_ID,TARGET_TT_ID,WARE_ID,ACTOR,REQUEST_HASH,REQUEST_JSON,SOURCE_HASH,SOURCE_JSON,RESULT_JSON)

   values(p_operation,v_st,version_no+1,source_trip,target_trip,ware,p_actor,request_hash,p_body,hash,src,p_result);

  g_tx:=null;RRL_STOCK_METADATA_TX.end_change;

 exception when others then

  g_tx:=null;if v_saved then rollback to RRL_ST_DEFER276;end if;

  if v_meta then RRL_STOCK_METADATA_TX.end_change;end if;raise;

 end;

end;
/


CREATE OR REPLACE package body RRL_ST_DEFER_CASE_WAIT as

 function task_signature(t RRL_WAREHOUSE_TASK%rowtype)return varchar2 is v json_object_t:=json_object_t();begin

  v.put('status',t.STATUS);v.put('assigned',t.ASSIGNED_TO);v.put('resource',t.RESOURCE_ID);v.put('session',t.RESOURCE_SESSION_ID);v.put('equipment',t.EQUIPMENT_ID);

  v.put('started',to_char(t.STARTED_AT_INSTANT,'YYYY-MM-DD HH24:MI:SS.FF6TZH:TZM'));

  return lower(rawtohex(sys.dbms_crypto.hash(v.to_clob,sys.dbms_crypto.hash_sh256)));

 end;

 function single_snapshot(p_st varchar2,p_ware number,p_ignore_plan varchar2,p_case_id number,p_nested_root varchar2 default null)return clob is

  ct RRL_CASE_PICK_TASK%rowtype;ff RRL_CUSTOMER_ORDER_FULFILLMENT%rowtype;

  n number;h number;own_qty number;items json_array_t:=json_array_t();x json_object_t;r json_object_t:=json_object_t();wait_cell varchar2(50);

 begin

  select count(*)into n from RRL_SBORKA_PALLETS where ST_NUMBER=p_st and ID=(select LEGACY_SBORKA_PALLET_ID from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=p_case_id);

  if n!=1 then raise_application_error(-20886,'DEFER_CASE_SINGLE_ST_PLACE_REQUIRED');end if;

  select c.*into ct from RRL_CASE_PICK_TASK c join RRL_SBORKA_PALLETS p on p.ID=c.LEGACY_SBORKA_PALLET_ID where p.ST_NUMBER=p_st and c.CASE_PICK_TASK_ID=p_case_id;

  if ct.WARE_ID is null or ct.WARE_ID!=p_ware or ct.CURRENT_CELL is null or ct.SSCC is null

   or ct.STATUS not in('WAIT_CONTROL','CONTROLLED','READY_TO_SHIP')then raise_application_error(-20886,'DEFER_CASE_COMPLETED_OWN_CARRIER_REQUIRED');end if;

  select count(*)into n from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=ct.LEGACY_SBORKA_PALLET_ID;

  if n!=1 then raise_application_error(-20886,'DEFER_CASE_SINGLE_FULFILLMENT_REQUIRED');end if;

  select *into ff from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID=ct.LEGACY_SBORKA_PALLET_ID;

  if ff.STATUS!='PICKED'or ff.PICKED_CASE_TASK_ID is null or ff.PICKED_CASE_TASK_ID!=ct.CASE_PICK_TASK_ID

   or ff.CUSTOMER_ORDER_ID!=ct.CUSTOMER_ORDER_ID or ff.PICKED_CONTENT_VERSION is null or ff.PICKED_CONTENT_VERSION!=ct.CONTENT_VERSION

   then raise_application_error(-20886,'DEFER_CASE_CURRENT_PHYSICAL_FULFILLMENT_REQUIRED');end if;

  select count(*)into n from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=ct.CASE_PICK_TASK_ID and ACTIVE_FLAG=1;

  if n!=0 then
   if p_nested_root is null then raise_application_error(-20886,'DEFER_CASE_NESTED_SOURCE_REQUIRES_HU_PLAN');end if;
   declare v_parent_uid varchar2(200);next_uid varchar2(200);counted number;steps number:=0;begin
    select count(*),min(PARENT_UID)into counted,v_parent_uid from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=ct.CASE_PICK_TASK_ID and ACTIVE_FLAG=1;
    if counted!=1 then raise_application_error(-20886,'DEFER_CASE_ONE_REGISTERED_PARENT_REQUIRED');end if;
    loop
     steps:=steps+1;if steps>200 then raise_application_error(-20886,'DEFER_CASE_PARENT_CHAIN_BOUND_200');end if;
     select count(*),min(PARENT_UID)into counted,next_uid from RRL_WMS_HU_LINK where CHILD_PALLET_UID=v_parent_uid and ACTIVE_FLAG=1;
     exit when counted=0;
     if counted!=1 then raise_application_error(-20886,'DEFER_CASE_ONE_REGISTERED_PARENT_REQUIRED');end if;
     v_parent_uid:=next_uid;
    end loop;
    if v_parent_uid!=p_nested_root then raise_application_error(-20886,'DEFER_CASE_EXACT_TOP_ROOT_REQUIRED');end if;
   end;
  elsif p_nested_root is not null then raise_application_error(-20886,'DEFER_CASE_NESTED_MEMBER_REQUIRED');end if;

  select count(*)into n from RRL_WAREHOUSE_TASK w where w.STATUS not in('DONE','CANCELLED')

   and(w.UID_PALLET=ct.SSCC or(w.SOURCE_DOC_TYPE='ST_DEFER_CASE'and exists(select 1 from RRL_ST_DEFER_WAIT_PLAN cp where cp.TASK_ID=w.TASK_ID and cp.CASE_TASK_ID=ct.CASE_PICK_TASK_ID)))

   and(p_ignore_plan is null or not exists(select 1 from RRL_ST_DEFER_WAIT_PLAN p where p.TASK_ID=w.TASK_ID and p.PLAN_OPERATION_ID=p_ignore_plan));

  if n!=0 then raise_application_error(-20886,'DEFER_CASE_PHYSICAL_TASK_ALREADY_OPEN');end if;

  for l in(select h.LOT_UID,s.CELL,s.REMAIN,s.HARD_RESERVED_BASE,s.STOCK_VERSION,s.BASE_UOM,p.ARTICUL,h.CASE_PICK_LINE_ID

   from RRL_CASE_CARRIER_LOT h join RRL_REMAINS s on s.UID_POLETA=h.LOT_UID join RRL_PALLETS p on p.UID_PALLET=h.LOT_UID

   where h.CASE_PICK_TASK_ID=ct.CASE_PICK_TASK_ID and(s.REMAIN>0 or s.HARD_RESERVED_BASE>0)order by h.LOT_UID,s.CELL fetch first 201 rows only)loop

   if items.get_size>=200 then raise_application_error(-20881,'DEFER_CASE_LOT_BOUND_200');end if;

   if l.CELL!=ct.CURRENT_CELL or l.REMAIN<=0 or l.HARD_RESERVED_BASE!=l.REMAIN then raise_application_error(-20886,'DEFER_CASE_WHOLE_RESERVED_STOCK_REQUIRED');end if;

   select nvl(sum(BASE_QTY),0)into own_qty from RRL_STOCK_RESERVATION where UID_PALLET=l.LOT_UID and CELL=l.CELL

    and CUSTOMER_ORDER_ID=ct.CUSTOMER_ORDER_ID and RESERVATION_KIND='HARD'and STATUS in('ACTIVE','ALLOCATED','PICKING');

   if own_qty!=l.REMAIN then raise_application_error(-20886,'DEFER_CASE_EXACT_OWN_HARD_REQUIRED');end if;

   x:=json_object_t();x.put('uid',l.LOT_UID);x.put('cell',l.CELL);x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(l.REMAIN));

   x.put('version',l.STOCK_VERSION);x.put('base',l.BASE_UOM);x.put('article',l.ARTICUL);x.put('case_line',l.CASE_PICK_LINE_ID);items.append(x);

  end loop;

  if items.get_size=0 then raise_application_error(-20886,'DEFER_CASE_HAS_NO_PHYSICAL_STOCK');end if;

  select count(*)into n from RRL_CELLS where CELL=ct.CURRENT_CELL and WARE_ID=p_ware;

  if n!=1 then raise_application_error(-20886,'DEFER_CASE_SOURCE_WAREHOUSE_REQUIRED');end if;

  select max(DEFER_WAIT_CELL)into wait_cell from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=p_ware;

  r.put('state','PREPARED_CASE');r.put('case_task_id',ct.CASE_PICK_TASK_ID);r.put('st_member_id',ct.LEGACY_SBORKA_PALLET_ID);

  r.put('fulfillment_id',ff.FULFILLMENT_ID);r.put('pallet_identifier',ct.SSCC);r.put('cell',ct.CURRENT_CELL);

  r.put('content_version',ct.CONTENT_VERSION);r.put('stocks',items);r.put('physical_move_required',wait_cell is null or wait_cell!=ct.CURRENT_CELL);

  r.put('stock_changed',false);return r.to_clob;

 exception when no_data_found or too_many_rows then raise_application_error(-20886,'DEFER_CASE_SINGLE_REGISTERED_SOURCE_REQUIRED');

 end;

 function snapshot(p_st varchar2,p_ware number,p_ignore_plan varchar2 default null,p_case_id number default null,p_nested_root varchar2 default null)return clob is

  n number;case_id number;case_count number;total_lots number:=0;need_move boolean:=false;

  cases json_array_t:=json_array_t();child json_object_t;result json_object_t:=json_object_t();uid varchar2(200);

  type identifiers is table of pls_integer index by varchar2(200);seen identifiers;

 begin

  if p_case_id is not null then return single_snapshot(p_st,p_ware,p_ignore_plan,p_case_id,p_nested_root);end if;

  if p_nested_root is not null then raise_application_error(-20886,'DEFER_CASE_EXPLICIT_NESTED_MEMBER_REQUIRED');end if;
  select count(*)into n from RRL_SBORKA_PALLETS where ST_NUMBER=p_st;

  if n<1 or n>200 then raise_application_error(-20881,'DEFER_CASE_ST_MEMBER_BOUND_200');end if;

  for member in(select ID from RRL_SBORKA_PALLETS where ST_NUMBER=p_st order by ID)loop

   select count(*),min(CASE_PICK_TASK_ID)into case_count,case_id from RRL_CASE_PICK_TASK where LEGACY_SBORKA_PALLET_ID=member.ID;

   if case_count!=1 then raise_application_error(-20886,'DEFER_CASE_ALL_ST_MEMBERS_SINGLE_CASE_REQUIRED');end if;

   child:=json_object_t.parse(single_snapshot(p_st,p_ware,p_ignore_plan,case_id));

   total_lots:=total_lots+child.get_array('stocks').get_size;

   if total_lots>200 then raise_application_error(-20881,'DEFER_CASE_ST_TOTAL_LOT_BOUND_200');end if;

   uid:=child.get_string('pallet_identifier');if seen.exists(uid)then raise_application_error(-20886,'DEFER_CASE_DISTINCT_CARRIER_IDENTIFIERS_REQUIRED');end if;seen(uid):=1;

   if child.get_boolean('physical_move_required')then need_move:=true;end if;cases.append(child);

  end loop;

  if cases.get_size=1 then return treat(cases.get(0)as json_object_t).to_clob;end if;

  result.put('state','PREPARED_CASES');result.put('cases',cases);result.put('case_count',cases.get_size);result.put('lot_count',total_lots);

  result.put('physical_move_required',need_move);result.put('stock_changed',false);return result.to_clob;

 end;

 procedure assert_command(p_request clob,p_actor varchar2)is

  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');tid number;

  t RRL_WAREHOUSE_TASK%rowtype;p RRL_ST_DEFER_WAIT_PLAN%rowtype;

 begin

  tid:=m.get_number('physical_task_id');if tid is null then return;end if;

  select *into t from RRL_WAREHOUSE_TASK where TASK_ID=tid;

  select *into p from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=tid;

  RRL_WAREHOUSE_TASK_ACCESS.assert_scope(tid,p_actor);

  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'DEFER_CASE_CURRENT_EXECUTOR_REQUIRED');end if;

  if p.CASE_TASK_ID is null or p.CASE_TASK_ID!=d.get_object('source').get_number('case_task_id')

   or t.SOURCE_DOC_TYPE!='ST_DEFER_CASE'or t.TASK_TYPE!='PUTAWAY'or t.TASK_SOURCE!='MANUAL'

   or(t.SOURCE_TASK_ID is null or(t.SOURCE_TASK_ID!=p.CASE_TASK_ID and t.SOURCE_TASK_ID!=t.TASK_ID))or t.UID_PALLET!=p.UID_PALLET or t.FROM_CELL!=p.FROM_CELL or t.TO_CELL!=p.TARGET_CELL

   or t.QTY!=1 or t.UNIT_CODE!='CASE'or t.QTY_MODE!='PALLET'

   then raise_application_error(-20886,'DEFER_CASE_REGISTERED_WAITING_TASK_REQUIRED');end if;

  if t.ASSIGNED_TO is not null and t.ASSIGNED_TO!=p_actor then raise_application_error(-20882,'DEFER_CASE_ASSIGNED_EXECUTOR_REQUIRED');end if;

 end;

 procedure describe(p_request clob,p_actor varchar2,p_current out json_object_t)is

  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');tid number:=m.get_number('physical_task_id');

  p RRL_ST_DEFER_WAIT_PLAN%rowtype;t RRL_WAREHOUSE_TASK%rowtype;dec RRL_ST_DEFER_DECISION%rowtype;

  src clob;n number;target varchar2(50);stored json_object_t;stored_wire clob;frozen_members json_array_t;current_members json_array_t;

 begin

  assert_command(p_request,p_actor);

  if m.get_string('scanned_pallet')is null or m.get_string('scanned_pallet')!=m.get_string('scan_container')

   or m.get_string('scanned_from_cell')is null or m.get_string('fact_qty')is null or RRL_STOCK_MATH.quantity(m.get_string('fact_qty'))!=1

   or m.get_number('resource_id')is not null or m.get_number('resource_session_id')is not null or m.get_number('equipment_id')is not null

   or m.get_string('scan_draft_id')is not null or m.get_string('scanned_to_slot_code')is not null

   then raise_application_error(-20886,'DEFER_CASE_WHOLE_PLACE_SCANS_REQUIRED');end if;

  if m.has('unit_keys')then declare keys json_array_t:=m.get_array('unit_keys');begin

   if keys is not null and keys.get_size>0 then raise_application_error(-20886,'DEFER_CASE_WHOLE_CARRIER_NO_PARTIAL_UNIT_SELECTION');end if;

  end;end if;

  select *into p from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=tid;

  select *into t from RRL_WAREHOUSE_TASK where TASK_ID=tid;

  if m.get_string('scanned_from_cell')!=p.FROM_CELL then raise_application_error(-20886,'DEFER_CASE_ORIGINAL_SOURCE_SCAN_REQUIRED');end if;

  select d.*into dec from RRL_ST_DEFER_WAIT_RUN r join RRL_ST_DEFER_DECISION d on d.OPERATION_ID=r.DECISION_OPERATION_ID where r.OPERATION_ID=p.PLAN_OPERATION_ID;

  if t.STATUS not in('PLANNED','ASSIGNED','IN_PROGRESS')then raise_application_error(-20886,'DEFER_CASE_WAITING_TASK_OPEN_REQUIRED');end if;

  if t.FROM_WARE_ID!=dec.WARE_ID or t.TO_WARE_ID!=dec.WARE_ID or t.SOURCE_DOC_ID!=dec.VERSION_NO

   or t.FROM_CELL_SLOT_ID is not null or t.TO_CELL_SLOT_ID is not null or t.RESOURCE_ID is not null or t.RESOURCE_SESSION_ID is not null or t.EQUIPMENT_ID is not null

   then raise_application_error(-20886,'DEFER_CASE_ORDINARY_WAITING_TASK_REQUIRED');end if;

  select count(*)into n from RRL_ST_DEFER_DECISION where ST_NUMBER=dec.ST_NUMBER and VERSION_NO>dec.VERSION_NO;

  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_DECISION_SUPERSEDED');end if;

  select count(*)into n from RRL_SBORKA_PALLETS s where s.ST_NUMBER=dec.ST_NUMBER and(nvl(s.TRANSTASK_ID,-1)!=dec.TARGET_TT_ID or nvl(s.CONDITION,0)=2

   or exists(select 1 from RRL_TT_HU_LOAD_ST ls join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=ls.LOAD_OPERATION_ID

    where ls.SBORKA_PALLET_ID=s.ID and ls.ACTIVE_FLAG=1 and l.STATUS in('LOADED','DEPARTED')));

  if n!=0 then raise_application_error(-20886,'DEFER_CASE_ST_ASSIGNMENT_OR_LOAD_CHANGED');end if;

  select count(*)into n from RRL_TRANSPORT_TASK where ID=dec.TARGET_TT_ID and CONDITION='Спланирован'and nvl(DELETED,0)=0 and nvl(PAY_ORDER_ID,0)=0;

  if n!=1 then raise_application_error(-20886,'DEFER_WAIT_PLANNED_TARGET_TRIP_REQUIRED');end if;

  select DEFER_WAIT_CELL into target from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=dec.WARE_ID;

  if target is null or target!=p.TARGET_CELL or target!=m.get_string('target_cell')then raise_application_error(-20886,'DEFER_WAIT_TARGET_CONFIGURATION_CHANGED');end if;

  RRL_ST_DEFER_WAIT_CORE.check_target(target,dec.WARE_ID);

  select count(*)into n from RRL_CELLS where CELL=target and(nvl(LIMIT_HEIGHT,0)>0 or nvl(LIMIT_WEIGHT,0)>0);

  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_MEASURED_CAPACITY_PLAN_REQUIRED');end if;

  select count(*)into n from RRL_TOPOLOGY_CELL tc join RRL_WAREHOUSE_TOPOLOGY tp on tp.TOPOLOGY_ID=tc.TOPOLOGY_ID join RRL_TOPOLOGY_CELL_SLOT sl on sl.TOPOLOGY_CELL_ID=tc.TOPOLOGY_CELL_ID

   where tc.LEGACY_CELL_CODE=target and tc.WARE_ID=dec.WARE_ID and tc.ACTIVE=1 and sl.ACTIVE=1 and tp.STATUS='PUBLISHED';

  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_PHYSICAL_SLOT_PLAN_REQUIRED');end if;

  src:=snapshot(dec.ST_NUMBER,dec.WARE_ID,p.PLAN_OPERATION_ID,p.CASE_TASK_ID);

  stored:=json_object_t.parse(p.SOURCE_MEMBERS_JSON);
  if stored.has('cohort_manifest')then
   frozen_members:=stored.get_array('cohort_manifest');stored.remove('cohort_manifest');
   current_members:=RRL_ST_DEFER_PLACE_READ.manifest(dec.ST_NUMBER);
   if dbms_lob.compare(frozen_members.to_clob,current_members.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: deferred ST membership/cargo');end if;
  end if;
  stored_wire:=stored.to_clob;
  if dbms_lob.compare(src,stored_wire)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: deferred CASE source');end if;

  p_current:=json_object_t.parse(src);if frozen_members is not null then p_current.put('cohort_manifest',current_members);end if;p_current.put('decision',dec.OPERATION_ID);p_current.put('plan',p.PLAN_OPERATION_ID);

  p_current.put('target_trip',dec.TARGET_TT_ID);p_current.put('warehouse',dec.WARE_ID);p_current.put('task_signature',task_signature(t));

 end;

 procedure validate_move(p_request clob,p_actor varchar2,p_frozen json_object_t)is current_src json_object_t;copy_src json_object_t;begin

  describe(p_request,p_actor,current_src);

  if p_frozen is null then raise_application_error(-20886,'DEFER_CASE_ROOT_PLAN_REQUIRED');end if;

  copy_src:=json_object_t.parse(p_frozen.to_clob);copy_src.remove('sync_id');copy_src.remove('sync_key');

  if dbms_lob.compare(current_src.to_clob,copy_src.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: deferred CASE waiting source');end if;

 end;

 procedure plan_move(p_request clob,p_actor varchar2,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t)is

  d json_object_t:=json_object_t.parse(p_request);tid number:=d.get_object('metadata').get_number('physical_task_id');v json_object_t;v_sync_id number;v_sync_key varchar2(400);

 begin

  if tid is null then return;end if;describe(p_request,p_actor,v);

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_WAIT_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(tid));

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(tid));

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_WAIT_RUN',v.get_string('plan'));

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_DECISION',v.get_string('decision'));

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_RECEIPT_WARE_SETTINGS',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('warehouse')));

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('target_trip')));

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('st_member_id')));

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('fulfillment_id')));

  v_sync_key:='DEFER.CASE.WT:'||RRL_STOCK_PLAN_HELPER.decimal_text(tid);

  begin select SYNC_ID into v_sync_id from RRL_WAREHOUSE_TASK_SYNC where SYNC_KEY=v_sync_key;

  exception when no_data_found then select RRL_WH_TASK_SYNC_SQ.nextval into v_sync_id from dual;end;

  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_WAREHOUSE_TASK_SYNC',RRL_STOCK_PLAN_HELPER.decimal_text(v_sync_id));

  RRL_STOCK_PLAN_HELPER.anchor(p_resources,70,'UNIQUE','TASK.SYNC:'||v_sync_key);

  v.put('sync_id',v_sync_id);v.put('sync_key',v_sync_key);p_domain.put('deferred_case_waiting',v);

 end;

 procedure finish_move(p_request clob,p_actor varchar2,p_result in out clob)is

  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');tid number:=m.get_number('physical_task_id');

  frozen json_object_t;current_src json_object_t;wire clob;t RRL_WAREHOUSE_TASK%rowtype;j json_object_t:=json_object_t.parse(p_result);

  v_sync_id number;v_sync_key varchar2(400);op varchar2(100):=d.get_string('operation_id');new_version number;ff_id number;case_id number;lots json_array_t;lot json_object_t;lot_uid varchar2(200);lot_qty number;lot_base varchar2(20);

 begin

  if tid is null then return;end if;

  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=op or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is null

   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)then raise_application_error(-20886,'DEFER_CASE_ROOT_POSTING_REQUIRED');end if;

  select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=op;

  frozen:=json_object_t.parse(wire).get_object('domain').get_object('deferred_case_waiting');

  if frozen is null then raise_application_error(-20886,'DEFER_CASE_ROOT_PLAN_REQUIRED');end if;

  select *into t from RRL_WAREHOUSE_TASK where TASK_ID=tid;

  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(tid)));

  if task_signature(t)!=frozen.get_string('task_signature')then raise_application_error(-20890,'CLOSURE_CHANGED: deferred CASE task');end if;

  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(frozen.get_number('fulfillment_id'))));

  new_version:=j.get_number('content_version');ff_id:=frozen.get_number('fulfillment_id');case_id:=j.get_number('case_pick_task_id');

  select count(*)into v_sync_id from RRL_CUSTOMER_ORDER_FULFILLMENT

   where FULFILLMENT_ID=ff_id and STATUS='PICKED'and PICKED_CASE_TASK_ID=case_id and PICKED_CONTENT_VERSION=new_version;

  if v_sync_id!=1 then raise_application_error(-20886,'DEFER_CASE_FULFILLMENT_BINDING_CHANGED');end if;

  update RRL_WAREHOUSE_TASK set STATUS='DONE',FACT_QTY=1,TARGET_UID_PALLET=UID_PALLET,FINISHED_AT=systimestamp,ASSIGNED_TO=p_actor,

   COMPLETION_HASH=lower(rawtohex(sys.dbms_crypto.hash(p_request,sys.dbms_crypto.hash_sh256))),COMPLETION_JSON=p_request,LAST_ERROR=null where TASK_ID=tid;

  lots:=j.get_array('lots');

  for i in 0..lots.get_size-1 loop

   lot:=treat(lots.get(i)as json_object_t);lot_uid:=lot.get_string('uid');lot_qty:=RRL_STOCK_MATH.quantity(lot.get_string('quantity'));lot_base:=lot.get_string('base');

   insert into RRL_WAREHOUSE_TASK_STOCK_MOVE(STOCK_MOVE_ID,TASK_ID,TASK_SOURCE,TASK_TYPE,SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_TASK_ID,

    UID_PALLET,TARGET_UID_PALLET,FROM_CELL,TO_CELL,QTY,BASE_QTY,BASE_UOM,OPERATION_ID,CREATED_AT,CREATED_BY)

    values(RRL_WH_TASK_STOCK_MOVE_SQ.nextval,tid,t.TASK_SOURCE,t.TASK_TYPE,t.SOURCE_DOC_TYPE,t.SOURCE_DOC_ID,t.SOURCE_TASK_ID,

     lot_uid,lot_uid,t.FROM_CELL,t.TO_CELL,lot_qty,lot_qty,lot_base,op,systimestamp,p_actor);

  end loop;

  v_sync_id:=frozen.get_number('sync_id');v_sync_key:=frozen.get_string('sync_key');

  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_WAREHOUSE_TASK_SYNC',RRL_STOCK_PLAN_HELPER.decimal_text(v_sync_id)));

  insert into RRL_WAREHOUSE_TASK_SYNC(SYNC_ID,TASK_ID,TASK_SOURCE,TASK_TYPE,SOURCE_DOC_TYPE,SOURCE_DOC_ID,SOURCE_TASK_ID,SYNC_KEY,SYNC_STATUS,SYNC_ATTEMPT,CREATED_AT,UPDATED_AT,SYNCED_AT,UPDATED_BY)

   values(v_sync_id,tid,t.TASK_SOURCE,t.TASK_TYPE,t.SOURCE_DOC_TYPE,t.SOURCE_DOC_ID,t.SOURCE_TASK_ID,v_sync_key,'SYNCED',1,systimestamp,systimestamp,systimestamp,p_actor);

  j.put('task_id',tid);j.put('status','DONE');j.put('quantity','1');j.put('base_uom','CASE');j.put('pallet_identifier',t.UID_PALLET);j.put('remaining_quantity','0');

  p_result:=j.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_ST_DEFER_HU_WAIT as
 function snapshot_root(p_st varchar2,p_ware number,p_root varchar2,p_ignore_plan varchar2 default null)return clob is
  n number;root_uid varchar2(200);next_uid varchar2(200);counted number;steps number:=0;case_count number:=0;members number;
  ignore_task number;tree json_object_t;nodes json_array_t;node json_object_t;child json_object_t;cases json_array_t:=json_array_t();
  stocks json_array_t;lot json_object_t;wait_cell varchar2(50);outcome json_object_t:=json_object_t();total_lots number:=0;
  type lot_map is table of clob index by varchar2(200);expected lot_map;seen lot_map;lot_uid varchar2(200);
 begin
  root_uid:=p_root;
  if p_ignore_plan is not null then
   select count(*),min(TASK_ID)into counted,ignore_task from RRL_ST_DEFER_WAIT_PLAN
    where PLAN_OPERATION_ID=p_ignore_plan and UID_PALLET=root_uid and BASE_UOM='HU';
   if counted>1 then raise_application_error(-20886,'DEFER_HU_ONE_WAIT_TASK_REQUIRED');end if;
  end if;
  tree:=json_object_t.parse(RRL_STOCK_HU_READ.snapshot_json(root_uid,ignore_task));nodes:=tree.get_array('nodes');
  if tree.get_number('warehouse')!=p_ware or nodes is null or nodes.get_size<2 or nodes.get_size>200
   or tree.get_array('ancestors').get_size!=0 or treat(nodes.get(0)as json_object_t).get_string('kind')!='CONTAINER'
   then raise_application_error(-20886,'DEFER_HU_REGISTERED_OWN_TOP_TREE_REQUIRED');end if;
  select count(*)into members from RRL_SBORKA_PALLETS where ST_NUMBER=p_st;
  if members<1 or members>200 then raise_application_error(-20881,'DEFER_HU_ST_MEMBER_BOUND_200');end if;
  for i in 0..nodes.get_size-1 loop
   node:=treat(nodes.get(i)as json_object_t);
   if nvl(node.get_number('open_task_count'),0)>0 then raise_application_error(-20886,'DEFER_HU_OTHER_PHYSICAL_TASK_OPEN');end if;
   if node.get_string('kind')='CASE'then
    child:=json_object_t.parse(RRL_ST_DEFER_CASE_WAIT.snapshot(p_st,p_ware,p_ignore_plan,node.get_number('case_task_id'),root_uid));
    case_count:=case_count+1;cases.append(child);stocks:=child.get_array('stocks');
    for j in 0..stocks.get_size-1 loop
     lot:=treat(stocks.get(j)as json_object_t);lot_uid:=lot.get_string('uid');
     if expected.exists(lot_uid)then raise_application_error(-20886,'DEFER_HU_DISTINCT_CASE_LOTS_REQUIRED');end if;
     expected(lot_uid):=lot.to_clob;total_lots:=total_lots+1;
     if total_lots>200 then raise_application_error(-20881,'DEFER_HU_TOTAL_LOT_BOUND_200');end if;
    end loop;
   elsif node.get_string('kind')not in('CONTAINER','STOCK')then raise_application_error(-20886,'DEFER_HU_CASE_TREE_ONLY');end if;
  end loop;
  if case_count<1 or case_count>members then raise_application_error(-20886,'DEFER_HU_EXACT_ALL_ST_MEMBERS_IN_TOP_REQUIRED');end if;
  for i in 0..nodes.get_size-1 loop
   node:=treat(nodes.get(i)as json_object_t);
   if node.get_string('kind')='STOCK'then
    lot_uid:=node.get_string('uid');
    if not expected.exists(lot_uid)or seen.exists(lot_uid)then raise_application_error(-20886,'DEFER_HU_EXACT_OWN_CASE_LEAVES_REQUIRED');end if;
    lot:=json_object_t.parse(expected(lot_uid));seen(lot_uid):=lot.to_clob;
    if node.get_string('cell')!=lot.get_string('cell')or node.get_string('quantity')!=lot.get_string('quantity')
     or node.get_string('hard_quantity')!=lot.get_string('quantity')or node.get_string('base_uom')!=lot.get_string('base')
     or node.get_number('stock_version')!=lot.get_number('version')then raise_application_error(-20886,'DEFER_HU_EXACT_RESERVED_LEAF_REQUIRED');end if;
   end if;
  end loop;
  if seen.count!=total_lots or total_lots<1 then raise_application_error(-20886,'DEFER_HU_COMPLETE_CASE_STOCK_REQUIRED');end if;
  select DEFER_WAIT_CELL into wait_cell from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=p_ware;
  outcome.put('state','PREPARED_HU');outcome.put('root',root_uid);outcome.put('cell',tree.get_string('cell'));
  outcome.put('content_version',treat(nodes.get(0)as json_object_t).get_number('version'));
  outcome.put('tree',tree);outcome.put('cases',cases);outcome.put('case_count',case_count);outcome.put('lot_count',total_lots);
  outcome.put('physical_move_required',wait_cell is null or wait_cell!=tree.get_string('cell'));outcome.put('stock_changed',false);
  return outcome.to_clob;
 end;

 function snapshot(p_st varchar2,p_ware number,p_ignore_plan varchar2 default null)return clob is begin
  return RRL_ST_DEFER_PLACE_READ.collect(p_st,p_ware,p_ignore_plan);
 end;
 procedure describe(p_decision varchar2,p_actor varchar2,p_task number,p_value out json_object_t,p_root varchar2 default null,p_manifest boolean default true)is
  dec RRL_ST_DEFER_DECISION%rowtype;target varchar2(50);n number;source clob;plan RRL_ST_DEFER_WAIT_PLAN%rowtype;
  ignore_plan varchar2(100);own number;admin_flag number;v_root varchar2(200):=p_root;
 begin
  select *into dec from RRL_ST_DEFER_DECISION where OPERATION_ID=p_decision;
  begin select WARE_ID,case when upper(trim(USER_GROUP))='GLOBAL_ADMIN'then 1 else 0 end into own,admin_flag
   from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'warehouse_task_execute')=1;
  exception when no_data_found then raise_application_error(-20882,'DEFER_HU_CURRENT_WARE_ACTOR_REQUIRED');end;
  if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 or(admin_flag=0 and(own is null or own!=dec.WARE_ID))
   then raise_application_error(-20882,'DEFER_HU_CURRENT_WARE_ACTOR_REQUIRED');end if;
  select count(*)into n from RRL_ST_DEFER_DECISION where ST_NUMBER=dec.ST_NUMBER and VERSION_NO>dec.VERSION_NO;
  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_DECISION_SUPERSEDED');end if;
  select count(*)into n from RRL_SBORKA_PALLETS st where st.ST_NUMBER=dec.ST_NUMBER and(nvl(st.TRANSTASK_ID,-1)!=dec.TARGET_TT_ID or nvl(st.CONDITION,0)=2
   or exists(select 1 from RRL_TT_HU_LOAD_ST ls join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=ls.LOAD_OPERATION_ID where ls.SBORKA_PALLET_ID=st.ID and ls.ACTIVE_FLAG=1 and l.STATUS in('LOADED','DEPARTED')));
  if n!=0 then raise_application_error(-20886,'DEFER_HU_ST_ASSIGNMENT_OR_LOAD_CHANGED');end if;
  select count(*)into n from RRL_TRANSPORT_TASK where ID=dec.TARGET_TT_ID and CONDITION='Спланирован'and nvl(DELETED,0)=0 and nvl(PAY_ORDER_ID,0)=0;
  if n!=1 then raise_application_error(-20886,'DEFER_WAIT_PLANNED_TARGET_TRIP_REQUIRED');end if;
  select DEFER_WAIT_CELL into target from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=dec.WARE_ID;
  RRL_ST_DEFER_WAIT_CORE.check_target(target,dec.WARE_ID);
  select count(*)into n from RRL_CELLS where CELL=target and(nvl(LIMIT_HEIGHT,0)>0 or nvl(LIMIT_WEIGHT,0)>0);
  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_MEASURED_CAPACITY_PLAN_REQUIRED');end if;
  select count(*)into n from RRL_TOPOLOGY_CELL tc join RRL_WAREHOUSE_TOPOLOGY tp on tp.TOPOLOGY_ID=tc.TOPOLOGY_ID
   join RRL_TOPOLOGY_CELL_SLOT sl on sl.TOPOLOGY_CELL_ID=tc.TOPOLOGY_CELL_ID
   where tc.LEGACY_CELL_CODE=target and tc.WARE_ID=dec.WARE_ID and tc.ACTIVE=1 and sl.ACTIVE=1 and tp.STATUS='PUBLISHED';
  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_PHYSICAL_SLOT_PLAN_REQUIRED');end if;
  if p_task is not null then
   select *into plan from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=p_task;
   if plan.BASE_UOM!='HU'or plan.CASE_TASK_ID is not null then raise_application_error(-20886,'DEFER_HU_WAIT_PLAN_REQUIRED');end if;
   ignore_plan:=plan.PLAN_OPERATION_ID;v_root:=plan.UID_PALLET;
  end if;
  if v_root is null then source:=snapshot(dec.ST_NUMBER,dec.WARE_ID,ignore_plan);
  else source:=RRL_ST_DEFER_PLACE_READ.selected(dec.ST_NUMBER,dec.WARE_ID,v_root,ignore_plan);end if;
  if source is null then raise_application_error(-20886,'DEFER_HU_WHOLE_TREE_REQUIRED');end if;
  if p_task is not null and(dbms_lob.compare(source,plan.SOURCE_MEMBERS_JSON)!=0 or target!=plan.TARGET_CELL)
   then raise_application_error(-20890,'CLOSURE_CHANGED: deferred HU source');end if;
  p_value:=json_object_t.parse(source);
  if p_manifest then p_value.put('cohort_manifest',RRL_ST_DEFER_PLACE_READ.manifest(dec.ST_NUMBER));end if;p_value.put('decision_operation_id',dec.OPERATION_ID);p_value.put('st_number',dec.ST_NUMBER);
  p_value.put('warehouse',dec.WARE_ID);p_value.put('decision_version',dec.VERSION_NO);p_value.put('target_trip',dec.TARGET_TT_ID);p_value.put('target_cell',target);
 end;

 function shared_wait_target(p_request clob,p_task number,p_target varchar2,p_ware number)return boolean is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');value json_object_t;
  v_decision varchar2(100):=m.get_string('defer_decision_operation_id');v_count number;v_plan varchar2(100);
 begin
  if p_task is not null then
   select count(*),min(PLAN_OPERATION_ID)into v_count,v_plan from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=p_task and BASE_UOM='HU';
   if v_count=0 then return false;end if;
   select DECISION_OPERATION_ID into v_decision from RRL_ST_DEFER_WAIT_RUN where OPERATION_ID=v_plan;
  elsif v_decision is null then return false;
  end if;
  describe(v_decision,d.get_string('actor'),p_task,value,m.get_string('defer_requested_root'));
  if value.get_string('root')!=d.get_object('source').get_string('uid')
    or value.get_string('target_cell')!=p_target or value.get_number('warehouse')!=p_ware
    then raise_application_error(-20886,'DEFER_SHARED_WAIT_ROOT_TARGET_REQUIRED');end if;
  return true;
 end;

 procedure request_plan(p_operation varchar2,p_decision varchar2,p_actor varchar2,p_request out clob,p_root varchar2 default null)is
  dec RRL_ST_DEFER_DECISION%rowtype;value json_object_t;wire json_object_t:=json_object_t();src json_object_t:=json_object_t();meta json_object_t:=json_object_t();raw_source clob;
 begin
  p_request:=null;select *into dec from RRL_ST_DEFER_DECISION where OPERATION_ID=p_decision;
  if p_root is null then raw_source:=snapshot(dec.ST_NUMBER,dec.WARE_ID);
  else raw_source:=RRL_ST_DEFER_PLACE_READ.selected(dec.ST_NUMBER,dec.WARE_ID,p_root);end if;
  if raw_source is null then return;end if;value:=json_object_t.parse(raw_source);
  if value.get_string('state')='PREPARED_PLACES'then raise_application_error(-20886,'DEFER_WAIT_ROOT_SELECTION_REQUIRED');end if;
  if value.get_string('state')='PREPARED_CASE'then return;end if;
  describe(p_decision,p_actor,null,value,p_root);
  if value.get_string('cell')=value.get_string('target_cell')then return;end if;
  wire.put('contract_version',2);
  wire.put('operation_id',p_operation);wire.put('command_type','HU_PLAN_MOVE');wire.put('actor',p_actor);
  src.put('uid',value.get_string('root'));wire.put('source',src);wire.put('lines',json_array_t());wire.put('units',json_array_t());
  meta.put('expected_version',value.get_number('content_version'));meta.put('target_cell',value.get_string('target_cell'));
  if p_root is not null then meta.put('defer_requested_root',p_root);end if;
  meta.put('defer_decision_operation_id',p_decision);wire.put('metadata',meta);p_request:=wire.to_clob;
 end;

 procedure declare_plan(p_request clob,p_task number,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t)is
  d json_object_t:=json_object_t.parse(p_request);meta json_object_t:=d.get_object('metadata');value json_object_t;plan RRL_ST_DEFER_WAIT_PLAN%rowtype;
  decision varchar2(100):=meta.get_string('defer_decision_operation_id');planning boolean:=d.get_string('command_type')='HU_PLAN_MOVE';task_id number;
 begin
  if planning then
   if decision is null then return;end if;
   describe(decision,d.get_string('actor'),null,value,meta.get_string('defer_requested_root'));
   if value.get_string('state')='PREPARED_PLACES'then raise_application_error(-20886,'DEFER_WAIT_ROOT_SELECTION_REQUIRED');end if;
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_WAIT_RUN',d.get_string('operation_id'));
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_WAIT_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(p_task));
  else
   select count(*)into task_id from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=p_task and BASE_UOM='HU';
   if task_id=0 then return;end if;
   select *into plan from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=p_task;
   select r.DECISION_OPERATION_ID into decision from RRL_ST_DEFER_WAIT_RUN r where r.OPERATION_ID=plan.PLAN_OPERATION_ID;
   describe(decision,d.get_string('actor'),p_task,value);
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_WAIT_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(p_task));
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_WAIT_RUN',plan.PLAN_OPERATION_ID);
  end if;
  if value.get_string('root')!=p_domain.get_string('uid')or value.get_string('target_cell')!=p_domain.get_string('target')
   then raise_application_error(-20886,'DEFER_HU_ROOT_TARGET_REQUIRED');end if;
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_DECISION',decision);
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(value.get_number('target_trip')));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_RECEIPT_WARE_SETTINGS',RRL_STOCK_PLAN_HELPER.decimal_text(value.get_number('warehouse')));
  declare cases json_array_t:=value.get_array('cases');item json_object_t;begin
   for i in 0..cases.get_size-1 loop
    item:=treat(cases.get(i)as json_object_t);
    RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(item.get_number('st_member_id')));
    RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(item.get_number('fulfillment_id')));
   end loop;
  end;
  p_domain.put('defer_wait_hu',value);
 end;

 procedure validate_plan(p_request clob,p_actor varchar2,p_frozen json_object_t,p_task number default null)is
  current_value json_object_t;d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');
  cases json_array_t;item json_object_t;trip number;st number;v_st_number varchar2(100);v_case_json clob;row_busy exception;pragma exception_init(row_busy,-54);
 begin
  if p_frozen is null then return;end if;
  trip:=p_frozen.get_number('target_trip');
  select ID into trip from RRL_TRANSPORT_TASK where ID=trip for update nowait;
  cases:=p_frozen.get_array('cases');v_st_number:=p_frozen.get_string('st_number');v_case_json:=cases.to_clob;
  for x in(select s.ID from RRL_SBORKA_PALLETS s join json_table(v_case_json,'$[*]'columns(st_member_id number path '$.st_member_id'))j on j.st_member_id=s.ID
    where s.ST_NUMBER=v_st_number order by s.ID)loop
   select ID into st from RRL_SBORKA_PALLETS where ID=x.ID for update nowait;
  end loop;
  describe(p_frozen.get_string('decision_operation_id'),p_actor,p_task,current_value,p_frozen.get_string('root'),p_frozen.has('cohort_manifest'));
  if dbms_lob.compare(current_value.to_clob,p_frozen.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: deferred HU decision/source');end if;
  if d.get_string('command_type')!='HU_PLAN_MOVE'then
   if m.get_string('scanned_from_cell')is null or m.get_string('scanned_from_cell')!=current_value.get_string('cell')
    or m.get_string('scanned_to_cell')is null or m.get_string('scanned_to_cell')!=current_value.get_string('target_cell')
    or m.get_string('fact_qty')is null or RRL_STOCK_MATH.quantity(m.get_string('fact_qty'))!=1
    then raise_application_error(-20886,'DEFER_HU_WHOLE_TOP_SOURCE_TARGET_SCANS_REQUIRED');end if;
   if m.has('unit_keys')then declare keys json_array_t:=m.get_array('unit_keys');begin
    if keys is not null and keys.get_size>0 then raise_application_error(-20886,'DEFER_HU_NO_PARTIAL_UNIT_SELECTION');end if;
   end;end if;
  end if;
 exception when row_busy then raise_application_error(-20840,'LOCK_RETRY: deferred HU source rows busy');
 end;
end;
/


CREATE OR REPLACE package body RRL_ST_DEFER_PHYSICAL as

 function snapshot(p_st varchar2,p_ware number,p_ignore_plan varchar2 default null)return clob is

  n number;bad number;expected number;counted number:=0;wait_cell varchar2(50);needs_move boolean:=false;items json_array_t:=json_array_t();item json_object_t;result json_object_t:=json_object_t();

 begin

  select count(*)into bad from RRL_SBORKA_PALLETS p where p.ST_NUMBER=p_st and(

   exists(select 1 from RRL_INTERWARE_ONWARD_BIND b where b.ST_ID=p.ID)

   or exists(select 1 from RRL_IW_GROUP_ST_BIND b where b.ST_ID=p.ID)

   or exists(select 1 from RRL_IW_RECOVERY_ST_BIND b where b.ST_ID=p.ID));

  if bad!=0 then raise_application_error(-20886,'ST_DEFER_INTERWARE_REVISION_REQUIRED');end if;

  select count(*)into bad from RRL_CASE_PICK_TASK c join RRL_SBORKA_PALLETS p on p.ID=c.LEGACY_SBORKA_PALLET_ID

   where p.ST_NUMBER=p_st and exists(select 1 from RRL_CASE_CARRIER_LOT l join RRL_REMAINS r on r.UID_POLETA=l.LOT_UID where l.CASE_PICK_TASK_ID=c.CASE_PICK_TASK_ID and(r.REMAIN>0 or r.HARD_RESERVED_BASE>0));

  if bad>0 then
   declare hu_source clob;begin hu_source:=RRL_ST_DEFER_HU_WAIT.snapshot(p_st,p_ware,p_ignore_plan);
    if hu_source is not null then return hu_source;end if;
   end;
   return RRL_ST_DEFER_CASE_WAIT.snapshot(p_st,p_ware,p_ignore_plan);
  end if;

  select count(*),sum(case when nvl(f.FACT_QTY,0)>0 then 1 else 0 end)into expected,n

   from RRL_CUSTOMER_ORDER_FULFILLMENT f join RRL_SBORKA_PALLETS p on p.ID=f.LEGACY_SBORKA_PALLET_ID where p.ST_NUMBER=p_st;

  if nvl(n,0)=0 then result.put('state','UNPICKED');return result.to_clob;end if;

  if expected>200 then raise_application_error(-20881,'ST_DEFER_PREPARED_MEMBER_BOUND_200');end if;

  select count(*)into bad from RRL_CASE_PICK_TASK c join RRL_SBORKA_PALLETS p on p.ID=c.LEGACY_SBORKA_PALLET_ID where p.ST_NUMBER=p_st;

  if bad!=0 then raise_application_error(-20886,'ST_DEFER_PREPARED_CASE_DECISION_REQUIRED');end if;

  select max(DEFER_WAIT_CELL)into wait_cell from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=p_ware;

  for x in(select f.FULFILLMENT_ID,f.LEGACY_SBORKA_PALLET_ID,f.STATUS,f.FACT_QTY,f.FACT_UOM,f.PICKED_PALLET_UID,

    sum(f.FACT_QTY)over(partition by f.PICKED_PALLET_UID) LOT_FACT_QTY,f.PICKED_CASE_TASK_ID,f.PICKED_WAREHOUSE_TASK_ID,f.PICKED_OPERATION_ID,f.PICKED_STOCK_VERSION,

    t.STATUS TASK_STATUS,t.TASK_TYPE,t.TO_WARE_ID,t.TO_CELL PICKED_CELL,r.CELL TO_CELL,nvl(t.TARGET_UID_PALLET,t.UID_PALLET)TASK_UID,

    r.REMAIN,r.HARD_RESERVED_BASE,r.BASE_UOM,r.STOCK_VERSION,cell.WARE_ID CELL_WARE

   from RRL_CUSTOMER_ORDER_FULFILLMENT f join RRL_SBORKA_PALLETS p on p.ID=f.LEGACY_SBORKA_PALLET_ID

   left join RRL_WAREHOUSE_TASK t on t.TASK_ID=f.PICKED_WAREHOUSE_TASK_ID

   left join RRL_REMAINS r on r.UID_POLETA=f.PICKED_PALLET_UID and(r.REMAIN>0 or r.HARD_RESERVED_BASE>0)

   left join RRL_CELLS cell on cell.CELL=r.CELL where p.ST_NUMBER=p_st order by f.FULFILLMENT_ID)loop

   if x.STATUS!='PICKED'or nvl(x.FACT_QTY,0)<=0 or x.PICKED_CASE_TASK_ID is not null or x.PICKED_WAREHOUSE_TASK_ID is null

    or x.PICKED_OPERATION_ID is null or nvl(x.TASK_STATUS,'NONE')!='DONE'or nvl(x.TASK_TYPE,'NONE')!='PICKING_MOVE'

    or nvl(x.TO_WARE_ID,-1)!=p_ware or nvl(x.CELL_WARE,-1)!=p_ware or x.PICKED_PALLET_UID is null

    or nvl(x.TASK_UID,'NONE')!=x.PICKED_PALLET_UID or nvl(x.REMAIN,-1)!=x.LOT_FACT_QTY or nvl(x.HARD_RESERVED_BASE,-1)!=x.LOT_FACT_QTY

    or x.FACT_UOM is null or nvl(x.BASE_UOM,'NONE')!=x.FACT_UOM then raise_application_error(-20886,'ST_DEFER_WHOLE_PREPARED_STOCK_REQUIRED');end if;

   select count(*)into bad from RRL_WMS_HU_LINK h where h.ACTIVE_FLAG=1 and(h.CHILD_PALLET_UID=x.PICKED_PALLET_UID or h.PARENT_UID=x.PICKED_PALLET_UID);

   if bad!=0 then raise_application_error(-20886,'ST_DEFER_PREPARED_NESTED_DECISION_REQUIRED');end if;

   select count(*)into bad from RRL_WAREHOUSE_TASK w where w.STATUS not in('DONE','CANCELLED')and(w.UID_PALLET=x.PICKED_PALLET_UID or w.TARGET_UID_PALLET=x.PICKED_PALLET_UID) and(p_ignore_plan is null or not exists(select 1 from RRL_ST_DEFER_WAIT_PLAN wp where wp.TASK_ID=w.TASK_ID and wp.PLAN_OPERATION_ID=p_ignore_plan));

   if bad!=0 then raise_application_error(-20886,'ST_DEFER_PREPARED_PHYSICAL_TASK_OPEN');end if;

   if wait_cell is null or x.TO_CELL!=wait_cell then needs_move:=true;end if;

   item:=json_object_t();item.put('fulfillment_id',x.FULFILLMENT_ID);item.put('st_member_id',x.LEGACY_SBORKA_PALLET_ID);

   item.put('pallet_identifier',x.PICKED_PALLET_UID);item.put('cell',x.TO_CELL);item.put('original_picked_cell',x.PICKED_CELL);item.put('task_id',x.PICKED_WAREHOUSE_TASK_ID);

   item.put('picked_operation_id',x.PICKED_OPERATION_ID);item.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(x.FACT_QTY));

   item.put('pallet_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(x.LOT_FACT_QTY));item.put('base_uom',x.FACT_UOM);item.put('stock_version',x.STOCK_VERSION);item.put('picked_stock_version',x.PICKED_STOCK_VERSION);items.append(item);counted:=counted+1;

  end loop;

  if counted!=expected or counted<1 then raise_application_error(-20886,'ST_DEFER_EXACT_PREPARED_MEMBERS_REQUIRED');end if;

  select count(*)into bad from RRL_SBORKA_PALLETS p where p.ST_NUMBER=p_st and not exists(select 1 from RRL_CUSTOMER_ORDER_FULFILLMENT f where f.LEGACY_SBORKA_PALLET_ID=p.ID);

  if bad!=0 then raise_application_error(-20886,'ST_DEFER_MIXED_PREPARED_UNPICKED_REQUIRED');end if;

  result.put('state','PREPARED_WHOLE_STOCK');result.put('members',items);result.put('physical_move_required',needs_move);result.put('stock_changed',false);return result.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_ST_DEFER_PLACE_READ as
 function roots(p_st varchar2)return json_array_t is
  output json_array_t:=json_array_t();item json_object_t;v_case number;v_n number;v_parent varchar2(200);v_next varchar2(200);v_root varchar2(200);
  v_kind varchar2(20);v_steps number;v_members number:=0;
  type kind_map is table of varchar2(20)index by varchar2(200);seen kind_map;
 begin
  for member in(select ID from RRL_SBORKA_PALLETS where ST_NUMBER=p_st order by ID fetch first 201 rows only)loop
   v_members:=v_members+1;if v_members>200 then raise_application_error(-20881,'DEFER_PLACE_ST_MEMBER_BOUND_200');end if;
   select count(*),min(CASE_PICK_TASK_ID)into v_n,v_case from RRL_CASE_PICK_TASK where LEGACY_SBORKA_PALLET_ID=member.ID;
   if v_n!=1 then raise_application_error(-20886,'DEFER_PLACE_COMPLETED_CASE_MEMBERS_REQUIRED');end if;
   select count(*),min(PARENT_UID)into v_n,v_parent from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=v_case and ACTIVE_FLAG=1;
   if v_n>1 then raise_application_error(-20886,'DEFER_PLACE_ONE_PARENT_REQUIRED');end if;
   if v_n=0 then v_root:='CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(v_case);v_kind:='CASE';
   else
    v_kind:='HU';v_steps:=0;
    loop
     v_steps:=v_steps+1;if v_steps>200 then raise_application_error(-20886,'DEFER_PLACE_PARENT_BOUND_200');end if;
     select count(*),min(PARENT_UID)into v_n,v_next from RRL_WMS_HU_LINK where CHILD_PALLET_UID=v_parent and ACTIVE_FLAG=1;
     exit when v_n=0;
     if v_n!=1 then raise_application_error(-20886,'DEFER_PLACE_ONE_TOP_PARENT_REQUIRED');end if;v_parent:=v_next;
    end loop;
    v_root:=v_parent;
   end if;
   if seen.exists(v_root)then
    if seen(v_root)!=v_kind then raise_application_error(-20886,'DEFER_PLACE_ROOT_IDENTIFIER_AMBIGUOUS');end if;
   else
    seen(v_root):=v_kind;item:=json_object_t();item.put('root_identifier',v_root);item.put('place_kind',v_kind);
    if v_kind='CASE'then item.put('case_task_id',v_case);end if;output.append(item);
   end if;
  end loop;
  if v_members=0 then raise_application_error(-20886,'DEFER_PLACE_REGISTERED_ST_REQUIRED');end if;
  return output;
 end;

 function source_for(p_st varchar2,p_ware number,p_root json_object_t,p_ignore varchar2)return clob is
 begin
  if p_root.get_string('place_kind')='CASE'then
   return RRL_ST_DEFER_CASE_WAIT.snapshot(p_st,p_ware,p_ignore,p_root.get_number('case_task_id'));
  end if;
  return RRL_ST_DEFER_HU_WAIT.snapshot_root(p_st,p_ware,p_root.get_string('root_identifier'),p_ignore);
 end;

 function selected(p_st varchar2,p_ware number,p_root varchar2,p_ignore_plan varchar2 default null)return clob is
  items json_array_t:=roots(p_st);item json_object_t;
 begin
  if p_root is null or trim(p_root)!=p_root or length(p_root)>200 then raise_application_error(-20886,'DEFER_PLACE_ROOT_REQUIRED');end if;
  for i in 0..items.get_size-1 loop
   item:=treat(items.get(i)as json_object_t);
   if item.get_string('root_identifier')=p_root then return source_for(p_st,p_ware,item,p_ignore_plan);end if;
  end loop;
  raise_application_error(-20886,'DEFER_PLACE_ROOT_OUTSIDE_CURRENT_ST');
 end;

 function collect(p_st varchar2,p_ware number,p_ignore_plan varchar2 default null,p_display boolean default false)return clob is
  items json_array_t;item json_object_t;source json_object_t;outcome json_object_t:=json_object_t();v_nested number;
  v_cases number:=0;v_lots number:=0;v_members number;v_ignore varchar2(100);v_uid varchar2(200);v_case number;v_task number;v_count number;
  v_plan_source clob;v_saved json_object_t;v_target varchar2(50);v_open boolean;v_move boolean:=false;
 begin
  if not p_display then
   select count(*)into v_nested from RRL_WMS_HU_LINK h join RRL_CASE_PICK_TASK ct on ct.CASE_PICK_TASK_ID=h.CHILD_CASE_TASK_ID
    join RRL_SBORKA_PALLETS st on st.ID=ct.LEGACY_SBORKA_PALLET_ID where st.ST_NUMBER=p_st and h.ACTIVE_FLAG=1;
   if v_nested=0 then return null;end if;
  end if;
  items:=roots(p_st);
  for i in 0..items.get_size-1 loop
   item:=treat(items.get(i)as json_object_t);v_uid:=item.get_string('root_identifier');v_case:=item.get_number('case_task_id');
   v_ignore:=p_ignore_plan;v_task:=null;v_open:=false;
   if p_display then
    select count(*),min(p.PLAN_OPERATION_ID),min(p.TASK_ID)into v_count,v_ignore,v_task
     from RRL_ST_DEFER_WAIT_PLAN p join RRL_ST_DEFER_WAIT_RUN wr on wr.OPERATION_ID=p.PLAN_OPERATION_ID
     join RRL_ST_DEFER_DECISION d on d.OPERATION_ID=wr.DECISION_OPERATION_ID join RRL_WAREHOUSE_TASK t on t.TASK_ID=p.TASK_ID
     join RRL_RECEIPT_WARE_SETTINGS cfg on cfg.WARE_ID=d.WARE_ID
     where d.ST_NUMBER=p_st and d.VERSION_NO=(select max(VERSION_NO)from RRL_ST_DEFER_DECISION where ST_NUMBER=p_st)
      and t.STATUS not in('DONE','CANCELLED')and p.TARGET_CELL=cfg.DEFER_WAIT_CELL
      and((v_case is not null and p.CASE_TASK_ID=v_case)or(v_case is null and p.UID_PALLET=v_uid and p.BASE_UOM='HU'));
    if v_count>1 then v_ignore:=null;v_task:=null;end if;
   end if;
   begin
    source:=json_object_t.parse(source_for(p_st,p_ware,item,v_ignore));
    item.put('source',source);
    if p_display and v_task is not null then
     select SOURCE_MEMBERS_JSON into v_plan_source from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=v_task;
     v_saved:=json_object_t.parse(v_plan_source);v_saved.remove('cohort_manifest');v_plan_source:=v_saved.to_clob;
     if dbms_lob.compare(v_plan_source,source.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: current planned place');end if;
     item.put('planned_task_id',v_task);
    end if;
    if source.get_string('state')='PREPARED_CASE'then v_cases:=v_cases+1;v_lots:=v_lots+source.get_array('stocks').get_size;
    else v_cases:=v_cases+source.get_number('case_count');v_lots:=v_lots+source.get_number('lot_count');end if;
    if v_lots>200 then raise_application_error(-20881,'DEFER_PLACE_TOTAL_LOT_BOUND_200');end if;
    if source.get_boolean('physical_move_required')then v_move:=true;end if;
   exception when others then
    if not p_display then raise;end if;
    item.remove('source');item.put('blocked',true);item.put('reason_code',sqlcode);
   end;
   items.put(i,item,true);
  end loop;
  select count(*)into v_members from RRL_SBORKA_PALLETS where ST_NUMBER=p_st;
  if not p_display and v_cases!=v_members then raise_application_error(-20886,'DEFER_PLACE_EXACT_ST_COVERAGE_REQUIRED');end if;
  if not p_display and items.get_size=1 then return treat(items.get(0)as json_object_t).get_object('source').to_clob;end if;
  outcome.put('state','PREPARED_PLACES');outcome.put('places',items);outcome.put('case_count',v_cases);outcome.put('lot_count',v_lots);
  outcome.put('physical_move_required',v_move);outcome.put('stock_changed',false);return outcome.to_clob;
 end;

 function manifest(p_st varchar2)return json_array_t is
  values_json json_array_t:=json_array_t();item json_object_t;v_count number:=0;v_rows number:=0;cargo json_array_t;line json_object_t;
 begin
  for member in(select ID,PALLET_UID,WARE_ID,TRANSTASK_ID,CONDITION from RRL_SBORKA_PALLETS where ST_NUMBER=p_st order by ID fetch first 201 rows only)loop
   v_count:=v_count+1;if v_count>200 then raise_application_error(-20881,'DEFER_PLACE_MANIFEST_BOUND_200');end if;
   item:=json_object_t();item.put('id',member.ID);item.put('identifier',member.PALLET_UID);item.put('warehouse',member.WARE_ID);
   item.put('trip',member.TRANSTASK_ID);item.put('condition',member.CONDITION);cargo:=json_array_t();
   for row_item in(select ID,ARTICUL,EI,QUANTITY,PACK_COUNT,ORDER_WEIGHT from RRL_SBORKA_PALLET_ROWS where PALLET_UID=member.PALLET_UID order by ID fetch first 1001 rows only)loop
    v_rows:=v_rows+1;if v_rows>1000 then raise_application_error(-20881,'DEFER_PLACE_MANIFEST_CARGO_BOUND_1000');end if;
    line:=json_object_t();line.put('id',row_item.ID);line.put('article',row_item.ARTICUL);line.put('unit',row_item.EI);
    line.put('quantity',row_item.QUANTITY);line.put('packs',row_item.PACK_COUNT);line.put('weight',row_item.ORDER_WEIGHT);cargo.append(line);
   end loop;
   item.put('cargo',cargo);values_json.append(item);
  end loop;
  return values_json;
 end;
end;
/


CREATE OR REPLACE package body RRL_ST_DEFER_WAIT_API as

 g_tx varchar2(100);

 function write_allowed return number is

 begin return case when g_tx is not null and g_tx=dbms_transaction.local_transaction_id(false)then 1 else 0 end;end;

 procedure plan_waiting(p_operation varchar2,p_decision varchar2,p_actor varchar2,p_result out clob,p_root varchar2 default null)is

  decision RRL_ST_DEFER_DECISION%rowtype;existing RRL_ST_DEFER_WAIT_RUN%rowtype;request json_object_t:=json_object_t();

  request_body clob;source clob;hu_request clob;arr json_array_t;selected json_array_t;first_member json_object_t;v json_object_t;

  targets json_array_t:=json_array_t();skips json_array_t:=json_array_t();result json_object_t:=json_object_t();

  target varchar2(50);uid varchar2(50 char);task_id number;n number;qty number;unit varchar2(20);from_cell varchar2(50);

  type seen_set is table of pls_integer index by varchar2(200);seen seen_set;

  meta_started boolean:=false;saved boolean:=false;

 begin

  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')

   or p_decision is null or lengthb(p_decision)>100 then raise_application_error(-20881,'DEFER_WAIT_OPERATION_DECISION_REQUIRED');end if;

  select *into decision from RRL_ST_DEFER_DECISION where OPERATION_ID=p_decision;

  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(p_actor,'warehouse_task_edit')=1

   and(u.WARE_ID=decision.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');

  if n!=1 then raise_application_error(-20882,'DEFER_WAIT_CURRENT_WAREHOUSE_PLANNER_REQUIRED');end if;

  request.put('decision_operation_id',p_decision);request.put('actor',p_actor);if p_root is not null then request.put('root_identifier',p_root);end if;request_body:=request.to_clob;

  begin
   select *into existing from RRL_ST_DEFER_WAIT_RUN where OPERATION_ID=p_operation;
   if existing.ACTOR!=p_actor or dbms_lob.compare(existing.REQUEST_JSON,request_body)!=0 then raise_application_error(-20886,'DEFER_WAIT_OPERATION_PAYLOAD_CONFLICT');end if;
   select count(*)into n from RRL_ST_DEFER_WAIT_PLAN where PLAN_OPERATION_ID=p_operation and BASE_UOM='HU';
   if n>0 then
    if RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'DEFER_HU_CURRENT_EXECUTION_RIGHT_REQUIRED');end if;
    begin select RESULT_JSON into p_result from RRL_STOCK_OPERATION
     where OPERATION_ID=p_operation and COMMAND_TYPE='HU_PLAN_MOVE'and STATE='APPLIED'and ACTOR=p_actor;
    exception when no_data_found then raise_application_error(-20890,'DEFER_HU_APPLIED_ROOT_RESULT_REQUIRED');end;
   else p_result:=existing.RESULT_JSON;end if;
   return;
  exception when no_data_found then null;end;
  RRL_ST_DEFER_HU_WAIT.request_plan(p_operation,p_decision,p_actor,hu_request,p_root);
  if hu_request is not null then
   RRL_STOCK_POSTING_API.prepare_command(hu_request,p_actor,p_result,null);
   if p_result is null then RRL_STOCK_POSTING_API.execute_prepared(p_result);end if;
   return;
  end if;
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'warehouse_task_edit');meta_started:=true;savepoint RRL_DWAIT772;saved:=true;

  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(p_actor,'warehouse_task_edit')=1

   and(u.WARE_ID=decision.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');

  if n!=1 then raise_application_error(-20882,'DEFER_WAIT_CURRENT_WAREHOUSE_PLANNER_REQUIRED');end if;
  select count(*)into n from RRL_STOCK_OPERATION op where op.OPERATION_ID=p_operation
   and not exists(select 1 from RRL_ST_DEFER_WAIT_RUN run where run.OPERATION_ID=p_operation);
  if n>0 then raise_application_error(-20886,'DEFER_WAIT_OPERATION_PAYLOAD_CONFLICT');end if;


  begin

   select *into existing from RRL_ST_DEFER_WAIT_RUN where OPERATION_ID=p_operation;

   if existing.ACTOR!=p_actor or dbms_lob.compare(existing.REQUEST_JSON,request_body)!=0 then raise_application_error(-20886,'DEFER_WAIT_OPERATION_PAYLOAD_CONFLICT');end if;

   p_result:=existing.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;

  exception when no_data_found then null;end;

  select count(*)into n from RRL_ST_DEFER_DECISION where ST_NUMBER=decision.ST_NUMBER and VERSION_NO>decision.VERSION_NO;

  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_DECISION_SUPERSEDED');end if;

  select count(*)into n from RRL_SBORKA_PALLETS p where p.ST_NUMBER=decision.ST_NUMBER and(

   nvl(p.TRANSTASK_ID,-1)!=decision.TARGET_TT_ID or nvl(p.CONDITION,0)=2

   or exists(select 1 from RRL_TT_HU_LOAD_ST ls join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=ls.LOAD_OPERATION_ID

    where ls.SBORKA_PALLET_ID=p.ID and ls.ACTIVE_FLAG=1 and l.STATUS in('LOADED','DEPARTED')));

  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_ST_ASSIGNMENT_OR_LOAD_CHANGED');end if;

  select count(*)into n from RRL_TRANSPORT_TASK where ID=decision.TARGET_TT_ID and CONDITION='Спланирован'and nvl(DELETED,0)=0 and nvl(PAY_ORDER_ID,0)=0;

  if n!=1 then raise_application_error(-20886,'DEFER_WAIT_PLANNED_TARGET_TRIP_REQUIRED');end if;

  select DEFER_WAIT_CELL into target from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=decision.WARE_ID;

  if target is null then raise_application_error(-20886,'DEFER_WAIT_TARGET_CONFIGURATION_REQUIRED');end if;

  RRL_ST_DEFER_WAIT_CORE.check_target(target,decision.WARE_ID);

  select count(*)into n from RRL_CELLS where CELL=target and(nvl(LIMIT_HEIGHT,0)>0 or nvl(LIMIT_WEIGHT,0)>0);

  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_MEASURED_CAPACITY_PLAN_REQUIRED');end if;

  select count(*)into n from RRL_TOPOLOGY_CELL tc join RRL_WAREHOUSE_TOPOLOGY tp on tp.TOPOLOGY_ID=tc.TOPOLOGY_ID

   join RRL_TOPOLOGY_CELL_SLOT sl on sl.TOPOLOGY_CELL_ID=tc.TOPOLOGY_CELL_ID

   where tc.LEGACY_CELL_CODE=target and tc.WARE_ID=decision.WARE_ID and tc.ACTIVE=1 and sl.ACTIVE=1 and tp.STATUS='PUBLISHED';

  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_PHYSICAL_SLOT_PLAN_REQUIRED');end if;

  if p_root is null then source:=RRL_ST_DEFER_PHYSICAL.snapshot(decision.ST_NUMBER,decision.WARE_ID);
  else source:=RRL_ST_DEFER_PLACE_READ.selected(decision.ST_NUMBER,decision.WARE_ID,p_root);end if;
  if p_root is not null then result.put('root_identifier',p_root);end if;

  declare prep json_object_t:=json_object_t.parse(source);src_case number;case_uid varchar2(200);case_version number;

   cases json_array_t:=json_array_t();child json_object_t;case_body clob;

   type origin_map is table of clob index by varchar2(100);origins origin_map;origin_key varchar2(100);

  begin

   if prep.get_string('state')='PREPARED_HU'then
    if prep.get_string('cell')!=target then raise_application_error(-20886,'DEFER_HU_ROOT_PLANNING_REQUIRED');end if;
    skips.append(prep.get_string('root'));
    result.put('operation_id',p_operation);result.put('decision_operation_id',p_decision);result.put('st_number',decision.ST_NUMBER);
    result.put('warehouse_id',decision.WARE_ID);result.put('waiting_cell',target);result.put('tasks',targets);result.put('already_waiting',skips);
    result.put('stock_changed',false);result.put('physical_move_completed',false);p_result:=result.to_clob;
    g_tx:=dbms_transaction.local_transaction_id(true);
    insert into RRL_ST_DEFER_WAIT_RUN(OPERATION_ID,DECISION_OPERATION_ID,ACTOR,REQUEST_JSON,RESULT_JSON)
     values(p_operation,p_decision,p_actor,request_body,p_result);
    g_tx:=null;RRL_STOCK_METADATA_TX.end_change;return;
   end if;
   if prep.get_string('state')in('PREPARED_CASE','PREPARED_CASES')then

    if prep.get_string('state')='PREPARED_CASE'then cases.append(prep);else cases:=prep.get_array('cases');end if;

    if cases is null or cases.get_size<1 or cases.get_size>200 then raise_application_error(-20881,'DEFER_WAIT_CASE_MEMBER_BOUND_200');end if;

    for i in 0..cases.get_size-1 loop

     child:=treat(cases.get(i)as json_object_t);src_case:=child.get_number('case_task_id');from_cell:=child.get_string('cell');case_uid:=child.get_string('pallet_identifier');

     origin_key:=RRL_STOCK_PLAN_HELPER.decimal_text(src_case);origins(origin_key):=child.to_clob;

     if from_cell=target then skips.append(case_uid);

     else

      select RRL_WAREHOUSE_TASK_SQ.nextval into task_id from dual;

      v:=json_object_t();v.put('task_id',task_id);v.put('pallet_identifier',case_uid);v.put('case_pick_task_id',src_case);targets.append(v);

     end if;

    end loop;

    result.put('operation_id',p_operation);result.put('decision_operation_id',p_decision);result.put('st_number',decision.ST_NUMBER);

    result.put('warehouse_id',decision.WARE_ID);result.put('waiting_cell',target);result.put('tasks',targets);result.put('already_waiting',skips);

    result.put('stock_changed',false);result.put('physical_move_completed',false);p_result:=result.to_clob;

    g_tx:=dbms_transaction.local_transaction_id(true);

    insert into RRL_ST_DEFER_WAIT_RUN(OPERATION_ID,DECISION_OPERATION_ID,ACTOR,REQUEST_JSON,RESULT_JSON)values(p_operation,p_decision,p_actor,request_body,p_result);

    for i in 0..targets.get_size-1 loop

     v:=treat(targets.get(i)as json_object_t);task_id:=v.get_number('task_id');src_case:=v.get_number('case_pick_task_id');

     child:=json_object_t.parse(origins(RRL_STOCK_PLAN_HELPER.decimal_text(src_case)));

     child.put('cohort_manifest',RRL_ST_DEFER_PLACE_READ.manifest(decision.ST_NUMBER));
     from_cell:=child.get_string('cell');case_uid:=child.get_string('pallet_identifier');case_version:=child.get_number('content_version');case_body:=child.to_clob;

     insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,SOURCE_DOC_ID,UID_PALLET,

      FROM_CELL,TO_CELL,FROM_WARE_ID,TO_WARE_ID,QTY,UNIT_CODE,QTY_MODE,STATUS,CREATED_BY)

      values(task_id,'PUTAWAY','MANUAL',task_id,'ST_DEFER_CASE',decision.VERSION_NO,case_uid,from_cell,target,decision.WARE_ID,decision.WARE_ID,1,'CASE','PALLET','PLANNED',p_actor);

     insert into RRL_ST_DEFER_WAIT_PLAN(TASK_ID,PLAN_OPERATION_ID,UID_PALLET,FROM_CELL,TARGET_CELL,BASE_QTY,BASE_UOM,STOCK_VERSION,SOURCE_MEMBERS_JSON,CASE_TASK_ID)

      values(task_id,p_operation,case_uid,from_cell,target,1,'CASE',case_version,case_body,src_case);

    end loop;

    g_tx:=null;RRL_STOCK_METADATA_TX.end_change;return;

   end if;

  end;

  arr:=json_object_t.parse(source).get_array('members');

  if arr is null or arr.get_size=0 or arr.get_size>200 then raise_application_error(-20886,'DEFER_WAIT_PREPARED_SOURCE_REQUIRED');end if;

  g_tx:=dbms_transaction.local_transaction_id(true);

  -- The run row is inserted before FK-bound plans; the result is built from all original members.

  for i in 0..arr.get_size-1 loop

   v:=treat(arr.get(i)as json_object_t);uid:=v.get_string('pallet_identifier');

   if not seen.exists(uid)then

    seen(uid):=1;selected:=json_array_t.parse(RRL_ST_DEFER_WAIT_CORE.members(source,uid));

    first_member:=treat(selected.get(0)as json_object_t);from_cell:=first_member.get_string('cell');

    if from_cell=target then skips.append(uid);

    else select RRL_WAREHOUSE_TASK_SQ.nextval into task_id from dual;

     v:=json_object_t();v.put('task_id',task_id);v.put('pallet_identifier',uid);targets.append(v);

    end if;

   end if;

  end loop;

  result.put('operation_id',p_operation);result.put('decision_operation_id',p_decision);result.put('st_number',decision.ST_NUMBER);

  result.put('warehouse_id',decision.WARE_ID);result.put('waiting_cell',target);result.put('tasks',targets);result.put('already_waiting',skips);

  result.put('stock_changed',false);result.put('physical_move_completed',false);p_result:=result.to_clob;

  insert into RRL_ST_DEFER_WAIT_RUN(OPERATION_ID,DECISION_OPERATION_ID,ACTOR,REQUEST_JSON,RESULT_JSON)values(p_operation,p_decision,p_actor,request_body,p_result);

  for i in 0..targets.get_size-1 loop

   v:=treat(targets.get(i)as json_object_t);uid:=v.get_string('pallet_identifier');task_id:=v.get_number('task_id');

   selected:=json_array_t.parse(RRL_ST_DEFER_WAIT_CORE.members(source,uid));first_member:=treat(selected.get(0)as json_object_t);

   qty:=RRL_STOCK_MATH.quantity(first_member.get_string('pallet_quantity'));unit:=first_member.get_string('base_uom');from_cell:=first_member.get_string('cell');

   insert into RRL_WAREHOUSE_TASK(TASK_ID,TASK_TYPE,TASK_SOURCE,SOURCE_TASK_ID,SOURCE_DOC_TYPE,SOURCE_DOC_ID,UID_PALLET,

    FROM_CELL,TO_CELL,FROM_WARE_ID,TO_WARE_ID,QTY,UNIT_CODE,QTY_MODE,STATUS,CREATED_BY)

    values(task_id,'PUTAWAY','MANUAL',task_id,'ST_DEFER',decision.VERSION_NO,uid,from_cell,target,decision.WARE_ID,decision.WARE_ID,qty,unit,'PALLET','PLANNED',p_actor);

   declare members_body clob:=selected.to_clob;version_no number:=first_member.get_number('stock_version');

   begin insert into RRL_ST_DEFER_WAIT_PLAN(TASK_ID,PLAN_OPERATION_ID,UID_PALLET,FROM_CELL,TARGET_CELL,BASE_QTY,BASE_UOM,STOCK_VERSION,SOURCE_MEMBERS_JSON)

    values(task_id,p_operation,uid,from_cell,target,qty,unit,version_no,members_body);end;

  end loop;

  g_tx:=null;RRL_STOCK_METADATA_TX.end_change;

 exception when others then

  g_tx:=null;if saved then rollback to RRL_DWAIT772;end if;

  if meta_started then RRL_STOCK_METADATA_TX.end_change;end if;raise;

 end;


 procedure record_hu_plan(p_request clob,p_task number,p_frozen json_object_t,p_result in out clob)is
  d json_object_t:=json_object_t.parse(p_request);req json_object_t:=json_object_t();result json_object_t:=json_object_t.parse(p_result);
  value json_object_t;entry json_object_t:=json_object_t();tasks json_array_t:=json_array_t();source clob;decision varchar2(100);op varchar2(100);
  uid varchar2(200);from_cell varchar2(50);to_cell varchar2(50);version_no number;actor_name varchar2(100);req_clob clob;kind varchar2(80);state_name varchar2(20);
 begin
  op:=d.get_string('operation_id');decision:=p_frozen.get_string('decision_operation_id');uid:=p_frozen.get_string('root');
  from_cell:=p_frozen.get_string('cell');to_cell:=p_frozen.get_string('target_cell');version_no:=p_frozen.get_number('content_version');
  if op is null or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=op
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)then raise_application_error(-20863,'DEFER_HU_PLAN_ROOT_REQUIRED');end if;
  select COMMAND_TYPE,STATE into kind,state_name from RRL_STOCK_OPERATION where OPERATION_ID=op;
  if kind!='HU_PLAN_MOVE'or state_name!='IN_FLIGHT' then raise_application_error(-20863,'DEFER_HU_PLAN_ROOT_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_ST_DEFER_WAIT_RUN',op));
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_ST_DEFER_WAIT_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(p_task)));
  actor_name:=d.get_string('actor');
  req.put('decision_operation_id',decision);req.put('actor',d.get_string('actor'));
  if d.get_object('metadata').get_string('defer_requested_root')is not null then
   req.put('root_identifier',d.get_object('metadata').get_string('defer_requested_root'));
   result.put('root_identifier',d.get_object('metadata').get_string('defer_requested_root'));
  end if;
  entry.put('task_id',p_task);entry.put('pallet_identifier',uid);entry.put('unit_code','HU');tasks.append(entry);
  result.put('decision_operation_id',decision);result.put('st_number',p_frozen.get_string('st_number'));result.put('warehouse_id',p_frozen.get_number('warehouse'));
  result.put('waiting_cell',to_cell);result.put('tasks',tasks);result.put('already_waiting',json_array_t());
  result.put('stock_changed',false);result.put('physical_move_completed',false);p_result:=result.to_clob;
  value:=json_object_t.parse(p_frozen.to_clob);value.remove('decision_operation_id');value.remove('st_number');value.remove('warehouse');
  value.remove('decision_version');value.remove('target_trip');value.remove('target_cell');value.remove('cohort_manifest');source:=value.to_clob;
  req_clob:=req.to_clob;g_tx:=dbms_transaction.local_transaction_id(true);
  insert into RRL_ST_DEFER_WAIT_RUN(OPERATION_ID,DECISION_OPERATION_ID,ACTOR,REQUEST_JSON,RESULT_JSON)
   values(op,decision,actor_name,req_clob,p_result);
  insert into RRL_ST_DEFER_WAIT_PLAN(TASK_ID,PLAN_OPERATION_ID,UID_PALLET,FROM_CELL,TARGET_CELL,BASE_QTY,BASE_UOM,STOCK_VERSION,SOURCE_MEMBERS_JSON)
   values(p_task,op,uid,from_cell,to_cell,1,'HU',version_no,source);
  g_tx:=null;
 exception when others then g_tx:=null;raise;
 end;

 procedure read_places(p_decision varchar2,p_actor varchar2,p_result out clob)is
  dec RRL_ST_DEFER_DECISION%rowtype;v_n number;full_value json_object_t;items json_array_t;out_items json_array_t:=json_array_t();
  item json_object_t;value json_object_t;out_item json_object_t;summary json_object_t:=json_object_t();need_choice boolean:=false;has_hu boolean:=false;has_planned boolean:=false;
 begin
  select *into dec from RRL_ST_DEFER_DECISION where OPERATION_ID=p_decision;
  select count(*)into v_n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,'warehouse_task_view')=1
   and(u.WARE_ID=dec.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if v_n!=1 then raise_application_error(-20882,'DEFER_PLACE_CURRENT_WARE_VIEW_REQUIRED');end if;
  select count(*)into v_n from RRL_ST_DEFER_DECISION where ST_NUMBER=dec.ST_NUMBER and VERSION_NO>dec.VERSION_NO;
  if v_n>0 then summary.put('places',out_items);summary.put('selection_required',false);summary.put('unavailable_reason','DECISION_SUPERSEDED');p_result:=summary.to_clob;return;end if;
  begin
   full_value:=json_object_t.parse(RRL_ST_DEFER_PLACE_READ.collect(dec.ST_NUMBER,dec.WARE_ID,null,true));items:=full_value.get_array('places');
   for i in 0..items.get_size-1 loop
    item:=treat(items.get(i)as json_object_t);out_item:=json_object_t();
    out_item.put('root_identifier',item.get_string('root_identifier'));out_item.put('place_kind',item.get_string('place_kind'));
    if item.get_string('place_kind')='HU'then has_hu:=true;end if;
    if item.has('blocked')then out_item.put('available',false);out_item.put('reason','CURRENT_SOURCE_OR_OPEN_TASK_REQUIRES_REVIEW');
    else
     value:=item.get_object('source');out_item.put('cell',value.get_string('cell'));out_item.put('content_version',value.get_number('content_version'));
     out_item.put('move_required',value.get_boolean('physical_move_required'));out_item.put('available',true);
     if item.get_number('planned_task_id')is not null then
      out_item.put('planned_task_id',item.get_number('planned_task_id'));out_item.put('available',false);has_planned:=true;
     end if;
    end if;
    out_items.append(out_item);
   end loop;
   need_choice:=out_items.get_size>1 and(has_hu or has_planned);
  exception when others then
   if sqlcode not between -20999 and -20800 then raise;end if;
   summary.put('unavailable_reason','CURRENT_PREPARED_SOURCE_REQUIRES_REVIEW');
  end;
  summary.put('places',out_items);summary.put('selection_required',need_choice);p_result:=summary.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_ST_DEFER_WAIT_CORE as
 procedure check_target(p_cell varchar2,p_ware number)is n number;
 begin
  select count(*)into n from RRL_CELLS c where c.CELL=p_cell and c.WARE_ID=p_ware
   and nvl(c.OTBOR,0)=0 and nvl(c.IS_SYSTEM,0)=0 and c.EXPEDITION_GROUP is null
   and nvl(c.BLOCKED_FOR_ACCEPT,0)=0 and nvl(c.BLOCKED_FOR_REMAINS,0)=0 and nvl(c.BLOCKED_FOR_POPOLNENIE,0)=0
   and not exists(select 1 from RRL_TOPOLOGY_CELL tc where tc.WARE_ID=c.WARE_ID and tc.LEGACY_CELL_CODE=c.CELL
    and tc.ACTIVE=1 and tc.CELL_KIND in('TRANSPORT_STAGING','GATE','FILM_WRAP')
    and tc.TOPOLOGY_ID=(select max(TOPOLOGY_ID)from RRL_WAREHOUSE_TOPOLOGY where WARE_ID=c.WARE_ID and STATUS='PUBLISHED'));
  if n!=1 then raise_application_error(-20886,'DEFER_WAIT_CELL_SAME_WARE_OPEN_STORAGE_OUTSIDE_SHIPPING_REQUIRED');end if;
 end;
 function members(p_snapshot clob,p_uid varchar2)return clob is
  s json_object_t:=json_object_t.parse(p_snapshot);a json_array_t;out_a json_array_t:=json_array_t();v json_object_t;
 begin
  if s.get_string('state')!='PREPARED_WHOLE_STOCK' then raise_application_error(-20886,'DEFER_WAIT_PREPARED_SOURCE_REQUIRED');end if;
  a:=s.get_array('members');
  for i in 0..a.get_size-1 loop
   v:=treat(a.get(i)as json_object_t);
   if v.get_string('pallet_identifier')=p_uid then out_a.append(v);end if;
  end loop;
  if out_a.get_size=0 then raise_application_error(-20886,'DEFER_WAIT_PALLET_NOT_IN_SOURCE');end if;
  return out_a.to_clob;
 end;
 procedure describe_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_current out json_object_t)is
  plan RRL_ST_DEFER_WAIT_PLAN%rowtype;run RRL_ST_DEFER_WAIT_RUN%rowtype;decision RRL_ST_DEFER_DECISION%rowtype;
  n number;target varchar2(50);source clob;current_members clob;first_member json_object_t;arr json_array_t;
 begin
  select *into plan from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=p_task.TASK_ID;
  select *into run from RRL_ST_DEFER_WAIT_RUN where OPERATION_ID=plan.PLAN_OPERATION_ID;
  select *into decision from RRL_ST_DEFER_DECISION where OPERATION_ID=run.DECISION_OPERATION_ID;
  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0
   and RRL_HAS_WRIGHT(p_actor,'warehouse_task_execute')=1
   and(u.WARE_ID=decision.WARE_ID or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'DEFER_WAIT_CURRENT_WAREHOUSE_EXECUTOR_REQUIRED');end if;
  select count(*)into n from RRL_ST_DEFER_DECISION where ST_NUMBER=decision.ST_NUMBER and VERSION_NO>decision.VERSION_NO;
  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_DECISION_SUPERSEDED');end if;
  select count(*)into n from RRL_SBORKA_PALLETS p where p.ST_NUMBER=decision.ST_NUMBER and(
   nvl(p.TRANSTASK_ID,-1)!=decision.TARGET_TT_ID or nvl(p.CONDITION,0)=2
   or exists(select 1 from RRL_TT_HU_LOAD_ST ls join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=ls.LOAD_OPERATION_ID
    where ls.SBORKA_PALLET_ID=p.ID and ls.ACTIVE_FLAG=1 and l.STATUS in('LOADED','DEPARTED')));
  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_ST_ASSIGNMENT_OR_LOAD_CHANGED');end if;
  select count(*)into n from RRL_TRANSPORT_TASK where ID=decision.TARGET_TT_ID and CONDITION='Спланирован'and nvl(DELETED,0)=0 and nvl(PAY_ORDER_ID,0)=0;
  if n!=1 then raise_application_error(-20886,'DEFER_WAIT_PLANNED_TARGET_TRIP_REQUIRED');end if;
  select DEFER_WAIT_CELL into target from RRL_RECEIPT_WARE_SETTINGS where WARE_ID=decision.WARE_ID;
  if target is null or target!=plan.TARGET_CELL then raise_application_error(-20886,'DEFER_WAIT_TARGET_CONFIGURATION_CHANGED');end if;
  check_target(target,decision.WARE_ID);
  select count(*)into n from RRL_CELLS where CELL=target and(nvl(LIMIT_HEIGHT,0)>0 or nvl(LIMIT_WEIGHT,0)>0);
  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_MEASURED_CAPACITY_PLAN_REQUIRED');end if;
  select count(*)into n from RRL_TOPOLOGY_CELL tc join RRL_WAREHOUSE_TOPOLOGY tp on tp.TOPOLOGY_ID=tc.TOPOLOGY_ID
   join RRL_TOPOLOGY_CELL_SLOT sl on sl.TOPOLOGY_CELL_ID=tc.TOPOLOGY_CELL_ID
   where tc.LEGACY_CELL_CODE=target and tc.WARE_ID=decision.WARE_ID and tc.ACTIVE=1 and sl.ACTIVE=1 and tp.STATUS='PUBLISHED';
  if n!=0 then raise_application_error(-20886,'DEFER_WAIT_PHYSICAL_SLOT_PLAN_REQUIRED');end if;
  source:=RRL_ST_DEFER_PHYSICAL.snapshot(decision.ST_NUMBER,decision.WARE_ID,run.OPERATION_ID);
  current_members:=members(source,plan.UID_PALLET);
  if dbms_lob.compare(current_members,plan.SOURCE_MEMBERS_JSON)!=0 then raise_application_error(-20886,'DEFER_WAIT_PREPARED_SOURCE_CHANGED');end if;
  arr:=json_array_t.parse(current_members);first_member:=treat(arr.get(0)as json_object_t);
  if nvl(p_task.TASK_SOURCE,'~')!='MANUAL' or nvl(p_task.SOURCE_DOC_TYPE,'~')!='ST_DEFER' or nvl(p_task.TASK_TYPE,'~')!='PUTAWAY'
   or nvl(p_task.SOURCE_DOC_ID,-1)!=decision.VERSION_NO or nvl(p_task.SOURCE_TASK_ID,-1)!=p_task.TASK_ID
   or nvl(p_task.UID_PALLET,'~')!=plan.UID_PALLET or nvl(p_task.FROM_CELL,'~')!=plan.FROM_CELL or nvl(p_task.TO_CELL,'~')!=plan.TARGET_CELL
   or nvl(p_task.FROM_WARE_ID,-1)!=decision.WARE_ID or nvl(p_task.TO_WARE_ID,-1)!=decision.WARE_ID
   or nvl(p_task.QTY,-1)!=plan.BASE_QTY or nvl(p_task.UNIT_CODE,'~')!=plan.BASE_UOM or nvl(p_task.QTY_MODE,'~')!='PALLET'
   or p_task.FROM_CELL_SLOT_ID is not null or p_task.TO_CELL_SLOT_ID is not null
   then raise_application_error(-20886,'DEFER_WAIT_REGISTERED_TASK_REQUIRED');end if;
  if first_member.get_string('cell')!=plan.FROM_CELL or first_member.get_number('stock_version')!=plan.STOCK_VERSION
   or RRL_STOCK_MATH.quantity(first_member.get_string('pallet_quantity'))!=plan.BASE_QTY
   or first_member.get_string('base_uom')!=plan.BASE_UOM then raise_application_error(-20886,'DEFER_WAIT_ORIGINAL_WHOLE_PALLET_REQUIRED');end if;
  p_current:=json_object_t();p_current.put('decision',decision.OPERATION_ID);p_current.put('plan',run.OPERATION_ID);
  p_current.put('st_number',decision.ST_NUMBER);p_current.put('warehouse',decision.WARE_ID);
  p_current.put('target_trip',decision.TARGET_TT_ID);p_current.put('members',arr);p_current.put('target',target);
 exception when no_data_found then raise_application_error(-20886,'DEFER_WAIT_REGISTERED_SOURCE_REQUIRED');
 end;
 procedure plan_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_resources in out nocopy json_array_t,p_domain in out nocopy json_object_t)is
  v json_object_t;v_st varchar2(100);
 begin
  describe_task(p_task,p_actor,v);
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_WAIT_PLAN',RRL_STOCK_PLAN_HELPER.decimal_text(p_task.TASK_ID));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_WAIT_RUN',v.get_string('plan'));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_ST_DEFER_DECISION',v.get_string('decision'));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_RECEIPT_WARE_SETTINGS',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('warehouse')));
  RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_TRANSPORT_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('target_trip')));
  v_st:=v.get_string('st_number');
  for x in(select p.ID,f.FULFILLMENT_ID,f.PICKED_WAREHOUSE_TASK_ID from RRL_SBORKA_PALLETS p
   join RRL_CUSTOMER_ORDER_FULFILLMENT f on f.LEGACY_SBORKA_PALLET_ID=p.ID where p.ST_NUMBER=v_st)loop
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_SBORKA_PALLETS',RRL_STOCK_PLAN_HELPER.decimal_text(x.ID));
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(x.FULFILLMENT_ID));
   RRL_STOCK_PLAN_HELPER.row_key(p_resources,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(x.PICKED_WAREHOUSE_TASK_ID));
  end loop;
  p_domain.put('deferred_waiting',v);
 end;
 procedure validate_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_actor varchar2,p_frozen json_object_t)is v json_object_t;
 begin
  describe_task(p_task,p_actor,v);
  if p_frozen is null or dbms_lob.compare(v.to_clob,p_frozen.to_clob)!=0 then raise_application_error(-20890,'CLOSURE_CHANGED: deferred waiting source');end if;
 end;
 procedure complete_task(p_task RRL_WAREHOUSE_TASK%rowtype,p_quantity number,p_target_uid varchar2,p_actor varchar2)is
  n number;version_no number;plan RRL_ST_DEFER_WAIT_PLAN%rowtype;st varchar2(100);q number;h number;unit varchar2(20);
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is null then raise_application_error(-20886,'DEFER_WAIT_ROOT_POSTING_REQUIRED');end if;
  select *into plan from RRL_ST_DEFER_WAIT_PLAN where TASK_ID=p_task.TASK_ID;
  select d.ST_NUMBER into st from RRL_ST_DEFER_WAIT_RUN r join RRL_ST_DEFER_DECISION d on d.OPERATION_ID=r.DECISION_OPERATION_ID where r.OPERATION_ID=plan.PLAN_OPERATION_ID;
  if p_quantity!=plan.BASE_QTY or p_target_uid!=plan.UID_PALLET then raise_application_error(-20886,'DEFER_WAIT_WHOLE_PALLET_REQUIRED');end if;
  select count(*)into n from RRL_WAREHOUSE_TASK where TASK_ID=p_task.TASK_ID and STATUS='DONE'and FACT_QTY=plan.BASE_QTY;
  if n!=1 then raise_application_error(-20886,'DEFER_WAIT_DONE_TASK_REQUIRED');end if;
  select REMAIN,HARD_RESERVED_BASE,STOCK_VERSION,BASE_UOM into q,h,version_no,unit from RRL_REMAINS where UID_POLETA=p_target_uid and CELL=plan.TARGET_CELL;
  if q!=plan.BASE_QTY or h!=q or unit!=plan.BASE_UOM then raise_application_error(-20886,'DEFER_WAIT_MOVED_RESERVE_PROOF_REQUIRED');end if;
  for x in(select f.FULFILLMENT_ID from RRL_CUSTOMER_ORDER_FULFILLMENT f join RRL_SBORKA_PALLETS p on p.ID=f.LEGACY_SBORKA_PALLET_ID
   where p.ST_NUMBER=st and f.PICKED_PALLET_UID=p_target_uid and f.STATUS='PICKED')loop
   RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(x.FULFILLMENT_ID)));
  end loop;
  update RRL_CUSTOMER_ORDER_FULFILLMENT f set PICKED_STOCK_VERSION=version_no,UPDATED_AT=sysdate,UPDATED_BY=p_actor
   where f.PICKED_PALLET_UID=p_target_uid and f.STATUS='PICKED'and exists(select 1 from RRL_SBORKA_PALLETS p where p.ID=f.LEGACY_SBORKA_PALLET_ID and p.ST_NUMBER=st);
  if sql%rowcount=0 then raise_application_error(-20886,'DEFER_WAIT_FULFILLMENT_BINDING_REQUIRED');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_ST_LAYOUT_READ as
 function scope_order(p_order number,p_actor varchar2,p_permission varchar2 default 'customer_order_view')return number is w number;n number;
 begin
  if p_permission not in('customer_order_view','outgoing_pallet_edit')or p_permission is null then raise_application_error(-20882,'ST_LAYOUT_PERMISSION_REQUIRED');end if;
  select WARE_ID into w from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=p_order;
  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0 and RRL_HAS_WRIGHT(u.ID,p_permission)=1
   and(u.WARE_ID=w or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'ST_LAYOUT_CURRENT_WAREHOUSE_REQUIRED');end if;
  return w;
 exception when no_data_found then raise_application_error(-20887,'ST_LAYOUT_ORDER_NOT_FOUND');
 end;
 function snapshot(p_order number,p_row number,p_target number,p_actor varchar2)return clob is
  w number;n number;source_count number:=0;target_count number:=0;merge_id number;
  source_row RRL_SBORKA_PALLET_ROWS%rowtype;dest_row RRL_SBORKA_PALLET_ROWS%rowtype;
  src RRL_SBORKA_PALLETS%rowtype;dst RRL_SBORKA_PALLETS%rowtype;
  j json_object_t:=json_object_t();x json_object_t;before_rows json_array_t:=json_array_t();after_rows json_array_t:=json_array_t();
  members json_array_t:=json_array_t();trip RRL_TRANSPORT_TASK%rowtype;
  function row_json(r RRL_SBORKA_PALLET_ROWS%rowtype)return json_object_t is v json_object_t:=json_object_t();
  begin
   v.put('id',r.ID);v.put('pallet',r.PALLET_UID);v.put('article',r.ARTICUL);v.put('unit',r.EI);
   v.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(r.QUANTITY));
   v.put('weight',RRL_STOCK_PLAN_HELPER.decimal_text(r.ORDER_WEIGHT));
   v.put('packs',RRL_STOCK_PLAN_HELPER.decimal_text(r.PACK_COUNT));
   v.put('tare_weight',r.TAREWEIGHT);v.put('tare_size',r.TARESIZE);
   v.put('original_quantity',r.ORIGINAL_QUANTITY);v.put('original_weight',r.ORIGINAL_ORDER_WEIGHT);
   v.put('warehouse',r.WARE_ID);v.put('batch',r.PROD_BATCH_ID);v.put('sscc',r.SSCC);
   v.put('expiry',to_char(r.EXPIRY_DATE,'YYYY-MM-DD HH24:MI:SS'));v.put('trace_mode',r.CRPT_TRANSFER_MODE);
   return v;
  end;
 begin
  w:=scope_order(p_order,p_actor);
  select *into source_row from RRL_SBORKA_PALLET_ROWS where ID=p_row;
  select *into src from RRL_SBORKA_PALLETS where PALLET_UID=source_row.PALLET_UID;
  select *into dst from RRL_SBORKA_PALLETS where ID=p_target;
  if src.ID=dst.ID or src.WARE_ID!=w or dst.WARE_ID!=w or src.WARE_ID is null or dst.WARE_ID is null
   or src.ST_NUMBER is null or src.ST_NUMBER!=dst.ST_NUMBER or nvl(src.ADDR,chr(0))!=nvl(dst.ADDR,chr(0))
   or nvl(src.TRANSTASK_ID,0)!=nvl(dst.TRANSTASK_ID,0) then raise_application_error(-20886,'ST_LAYOUT_SAME_ORDER_TRIP_REQUIRED');end if;
  if nvl(src.CONDITION,0)>=2 or nvl(dst.CONDITION,0)>=2 or src.RETURN_SUPPLIER_ID is not null or dst.RETURN_SUPPLIER_ID is not null then
   raise_application_error(-20886,'ST_LAYOUT_UNSHIPPED_CUSTOMER_ST_REQUIRED');end if;
  for f in(select *from RRL_CUSTOMER_ORDER_FULFILLMENT where LEGACY_SBORKA_PALLET_ID in(src.ID,dst.ID)order by FULFILLMENT_ID)loop
   if f.CUSTOMER_ORDER_ID!=p_order or f.STATUS!='PLANNED'or f.STATUS is null or nvl(f.FACT_QTY,0)!=0
    or f.PICKED_CASE_TASK_ID is not null or f.PICKED_PALLET_UID is not null or f.PICKED_WAREHOUSE_TASK_ID is not null
    or f.PICKED_OPERATION_ID is not null or f.SHIPPED_OPERATION_ID is not null then raise_application_error(-20886,'ST_LAYOUT_UNBOUND_PLANNED_ONLY');end if;
   x:=json_object_t();x.put('id',f.FULFILLMENT_ID);x.put('shipment_id',f.LEGACY_SBORKA_PALLET_ID);x.put('pallet',f.PALLET_UID);members.append(x);
  end loop;
  if members.get_size!=2 then raise_application_error(-20886,'ST_LAYOUT_EXACT_FULFILLMENT_REQUIRED');end if;
  if nvl(src.TRANSTASK_ID,0)>0 then
   select *into trip from RRL_TRANSPORT_TASK where ID=src.TRANSTASK_ID;
   if nvl(trip.DELETED,0)!=0 or nvl(trip.PAY_ORDER_ID,0)!=0 or trip.CONDITION='Отгружен' then raise_application_error(-20886,'ST_LAYOUT_TRIP_CLOSED');end if;
   select count(*)into n from RRL_TT_HU_LOAD_FACT where TT_ID=src.TRANSTASK_ID and STATUS='DEPARTED';
   if n>0 then raise_application_error(-20886,'ST_LAYOUT_TRIP_DEPARTED');end if;
   j.put('trip_state',trip.CONDITION);j.put('trip_vehicle',trip.TRANSPORT);
  end if;
  select count(*)into n from RRL_TT_HU_LOAD_ST where SBORKA_PALLET_ID in(src.ID,dst.ID)and ACTIVE_FLAG=1;
  if n>0 then raise_application_error(-20886,'ST_LAYOUT_LOADED_PLACE');end if;
  select count(*),max(ID)into n,merge_id from RRL_SBORKA_PALLET_ROWS where PALLET_UID=dst.PALLET_UID and ARTICUL=source_row.ARTICUL;
  if n>1 then raise_application_error(-20887,'ST_LAYOUT_AMBIGUOUS_TARGET_ARTICLE');end if;
  if merge_id is not null then
   select *into dest_row from RRL_SBORKA_PALLET_ROWS where ID=merge_id;
   if nvl(dest_row.EI,chr(0))!=nvl(source_row.EI,chr(0))or nvl(dest_row.TAREWEIGHT,-1)!=nvl(source_row.TAREWEIGHT,-1)
    or nvl(dest_row.TARESIZE,-1)!=nvl(source_row.TARESIZE,-1)or nvl(dest_row.PROD_BATCH_ID,-1)!=nvl(source_row.PROD_BATCH_ID,-1)
    or nvl(dest_row.SSCC,chr(0))!=nvl(source_row.SSCC,chr(0))or nvl(dest_row.CRPT_TRANSFER_MODE,chr(0))!=nvl(source_row.CRPT_TRANSFER_MODE,chr(0))
    or nvl(dest_row.EXPIRY_DATE,date '1900-01-01')!=nvl(source_row.EXPIRY_DATE,date '1900-01-01')then
    raise_application_error(-20886,'ST_LAYOUT_ROW_METADATA_MISMATCH');end if;
  end if;
  for r in(select *from RRL_SBORKA_PALLET_ROWS where PALLET_UID in(src.PALLET_UID,dst.PALLET_UID)order by ID fetch first 201 rows only)loop
   if before_rows.get_size>=200 then raise_application_error(-20881,'ST_LAYOUT_ROW_BOUND_200');end if;
   if r.QUANTITY is null or r.QUANTITY<=0 or r.EI is null or r.ORDER_WEIGHT is null or r.ORDER_WEIGHT<=0
    or r.PACK_COUNT is null or r.PACK_COUNT<=0 or r.PACK_COUNT!=trunc(r.PACK_COUNT)or r.WARE_ID is null or r.WARE_ID!=w
    or nvl(r.SOBRANO,0)!=0 or r.PRIHOD_PALLET_UID is not null or r.TIME_OF_CHECKING is not null then
    raise_application_error(-20886,'ST_LAYOUT_UNEXECUTED_EXACT_ROWS_REQUIRED');end if;
   if r.PALLET_UID=src.PALLET_UID then source_count:=source_count+1;else target_count:=target_count+1;end if;
   x:=row_json(r);before_rows.append(x);
   if r.ID=p_row then
    if merge_id is null then x.put('pallet',dst.PALLET_UID);after_rows.append(x);end if;
   else
    if r.ID=merge_id then
     x.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(r.QUANTITY+source_row.QUANTITY));
     x.put('weight',RRL_STOCK_PLAN_HELPER.decimal_text(r.ORDER_WEIGHT+source_row.ORDER_WEIGHT));
     x.put('packs',RRL_STOCK_PLAN_HELPER.decimal_text(r.PACK_COUNT+source_row.PACK_COUNT));
     x.put('original_quantity',nvl(r.ORIGINAL_QUANTITY,0)+nvl(source_row.ORIGINAL_QUANTITY,0));
     x.put('original_weight',nvl(r.ORIGINAL_ORDER_WEIGHT,0)+nvl(source_row.ORIGINAL_ORDER_WEIGHT,0));
    end if;
    after_rows.append(x);
   end if;
  end loop;
  if source_count<2 or target_count<1 then raise_application_error(-20886,'ST_LAYOUT_KEEP_EXISTING_NONEMPTY_PLACES');end if;
  j.put('order_id',p_order);j.put('warehouse',w);j.put('row_id',p_row);j.put('target_shipment_id',dst.ID);
  j.put('source_shipment_id',src.ID);j.put('source_pallet',src.PALLET_UID);j.put('target_pallet',dst.PALLET_UID);
  j.put('st_number',src.ST_NUMBER);j.put('trip_id',src.TRANSTASK_ID);j.put('merge_row_id',merge_id);
  j.put('fulfillments',members);j.put('before',before_rows);j.put('after',after_rows);j.put('stock_changed',false);
  j.put('signature',rawtohex(sys.dbms_crypto.hash(j.to_clob,sys.dbms_crypto.hash_sh256)));
  return j.to_clob;
 exception when no_data_found then raise_application_error(-20887,'ST_LAYOUT_IDENTITY_MISSING');
  when too_many_rows then raise_application_error(-20887,'ST_LAYOUT_IDENTITY_AMBIGUOUS');
 end;
end;
/


CREATE OR REPLACE package body RRL_TARE_DAMAGE_TRACE as
 g_writing boolean:=false;
 function tracked_quantity(p_key raw)return number is n number;
 begin select nvl(sum(QUANTITY),0)into n from RRL_TARE_DAMAGE_POSITION where BALANCE_KEY=p_key;return n;end;
 function origin_exists(p_damage varchar2)return boolean is n number;
 begin select count(*)into n from RRL_TARE_DAMAGE_ORIGIN where DAMAGE_OPERATION_ID=p_damage;return n=1;end;
 function offer_origin(p_offer varchar2)return varchar2 is result varchar2(100);
 begin select DAMAGE_OPERATION_ID into result from RRL_TARE_DAMAGE_OFFER where OFFER_OPERATION_ID=p_offer;return result;
 exception when no_data_found then return null;end;
 procedure check_transfer(p_damage varchar2,p_key raw,p_quantity number,p_physical number)is n number;
 begin
  if p_damage is null then
   if p_quantity>p_physical-tracked_quantity(p_key)-RRL_TARE_PLANNING.held_quantity(p_key)then raise_application_error(-20886,'TARE_DAMAGE_ORIGIN_REQUIRED');end if;
  else
   begin select QUANTITY into n from RRL_TARE_DAMAGE_POSITION where DAMAGE_OPERATION_ID=p_damage and BALANCE_KEY=p_key;
   exception when no_data_found then raise_application_error(-20886,'TARE_DAMAGE_CURRENT_CUSTODY_REQUIRED');end;
   if p_quantity>n then raise_application_error(-20886,'TARE_DAMAGE_CURRENT_QUANTITY_EXCEEDED');end if;
  end if;
 end;
 procedure assert_internal is op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');k varchar2(80);state varchar2(20);
 begin
  if not g_writing or op is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)
   then raise_application_error(-20863,'TARE_DAMAGE_TRACE_ROOT_REQUIRED');end if;
  select COMMAND_TYPE,STATE into k,state from RRL_STOCK_OPERATION where OPERATION_ID=op;
  if state!='IN_FLIGHT'or k not in('TARE_DAMAGE','TARE_WRITE_OFF','TARE_OFFER','TARE_ACCEPT')
   then raise_application_error(-20863,'TARE_DAMAGE_TRACE_COMMAND_REQUIRED');end if;
 end;
 procedure register_damage(p_operation varchar2,p_key raw,p_quantity number)is
 begin
  RRL_TARE_ASSERT_WRITE('RRL_TARE_RESOLUTION',p_operation,'TARE_DAMAGE');
  g_writing:=true;
  insert into RRL_TARE_DAMAGE_ORIGIN(DAMAGE_OPERATION_ID,ORIGIN_BALANCE_KEY,QUANTITY)values(p_operation,p_key,p_quantity);
  insert into RRL_TARE_DAMAGE_POSITION(DAMAGE_OPERATION_ID,BALANCE_KEY,QUANTITY,VERSION_NO,LAST_OPERATION_ID)
   values(p_operation,p_key,p_quantity,1,p_operation);
  g_writing:=false;
 exception when others then g_writing:=false;raise;end;
 procedure record_offer(p_operation varchar2,p_damage varchar2)is
 begin
  if p_damage is null then return;end if;
  RRL_TARE_ASSERT_WRITE('RRL_TARE_OFFER',p_operation,'TARE_OFFER');
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TARE_RESOLUTION',p_damage));
  g_writing:=true;
  insert into RRL_TARE_DAMAGE_OFFER(OFFER_OPERATION_ID,DAMAGE_OPERATION_ID)values(p_operation,p_damage);
  g_writing:=false;
 exception when others then g_writing:=false;raise;end;
 procedure record_transfer(p_operation varchar2,p_damage varchar2,p_from raw,p_to raw,p_quantity number)is
 begin
  if p_damage is null then return;end if;
  RRL_TARE_ASSERT_WRITE('RRL_TARE_ACCEPT',p_operation,'TARE_ACCEPT');
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TARE_RESOLUTION',p_damage));
  g_writing:=true;
  update RRL_TARE_DAMAGE_POSITION set QUANTITY=QUANTITY-p_quantity,VERSION_NO=VERSION_NO+1,LAST_OPERATION_ID=p_operation
   where DAMAGE_OPERATION_ID=p_damage and BALANCE_KEY=p_from and QUANTITY>=p_quantity;
  if sql%rowcount!=1 then raise_application_error(-20886,'TARE_DAMAGE_CURRENT_QUANTITY_EXCEEDED');end if;
  merge into RRL_TARE_DAMAGE_POSITION p using(select p_damage D,p_to K from dual)s
   on(p.DAMAGE_OPERATION_ID=s.D and p.BALANCE_KEY=s.K)
   when matched then update set QUANTITY=QUANTITY+p_quantity,VERSION_NO=VERSION_NO+1,LAST_OPERATION_ID=p_operation
   when not matched then insert(DAMAGE_OPERATION_ID,BALANCE_KEY,QUANTITY,VERSION_NO,LAST_OPERATION_ID)values(p_damage,p_to,p_quantity,1,p_operation);
  insert into RRL_TARE_DAMAGE_MOVE(ACCEPT_OPERATION_ID,DAMAGE_OPERATION_ID,FROM_BALANCE_KEY,TO_BALANCE_KEY,QUANTITY)
   values(p_operation,p_damage,p_from,p_to,p_quantity);
  g_writing:=false;
 exception when others then g_writing:=false;raise;end;
 procedure record_writeoff(p_operation varchar2,p_damage varchar2,p_key raw,p_quantity number)is
 begin
  if not origin_exists(p_damage)then return;end if;
  RRL_TARE_ASSERT_WRITE('RRL_TARE_RESOLUTION',p_operation,'TARE_WRITE_OFF');
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TARE_RESOLUTION',p_damage));
  g_writing:=true;
  update RRL_TARE_DAMAGE_POSITION set QUANTITY=QUANTITY-p_quantity,VERSION_NO=VERSION_NO+1,LAST_OPERATION_ID=p_operation
   where DAMAGE_OPERATION_ID=p_damage and BALANCE_KEY=p_key and QUANTITY>=p_quantity;
  if sql%rowcount!=1 then raise_application_error(-20886,'TARE_DAMAGE_CURRENT_QUANTITY_EXCEEDED');end if;
  g_writing:=false;
 exception when others then g_writing:=false;raise;end;
end;
/


CREATE OR REPLACE package body RRL_TARE_LOAD_RECOVERY_API as
 procedure assert_scope(p_request clob,p_actor varchar2)is d json_object_t:=json_object_t.parse(p_request);m json_object_t;v json_object_t;book_id varchar2(100);ware number;
 begin
  if d.get_string('command_type')!='TARE_BOOK'then return;end if;m:=d.get_object('metadata');
  if not m.has('load_recovery')or m.get('load_recovery').is_null then return;end if;
  if RRL_HAS_WRIGHT(p_actor,'tare_plan')!=1 then raise_application_error(-20882,'TARE_RECOVERY_PLANNING_PERMISSION_REQUIRED');end if;
  v:=m.get_object('load_recovery');book_id:=v.get_string('original_booking_operation_id');
  select OWNER_WARE_ID into ware from RRL_TARE_BOOK where OPERATION_ID=book_id;
  RRL_TARE_PARTICIPANT.warehouse_actor(p_actor,ware);
 end;
 function describe_recovery(p_request clob,p_actor varchar2)return clob is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');s json_object_t:=d.get_object('source');v json_object_t;j json_object_t:=json_object_t();
  old_book RRL_TARE_BOOK%rowtype;load_fact RRL_TT_HU_LOAD_FACT%rowtype;old_offer RRL_TARE_OFFER%rowtype;back_offer RRL_TARE_OFFER%rowtype;back_accept RRL_TARE_ACCEPT%rowtype;old_accept RRL_TARE_ACCEPT%rowtype;ct RRL_CASE_PICK_TASK%rowtype;
  load_id varchar2(100);book_id varchar2(100);return_id varchar2(100);old_offer_id varchar2(100);case_id number;n number;wire clob;scan_value varchar2(200);original_version number;pp RRL_PALLETS%rowtype;root_uid varchar2(150);root_kind varchar2(20);cell_value varchar2(60);p_total number;h_total number;stock_version number;task_id number;wave_id number;ff_id number;order_id number;node json_object_t;tree json_object_t;
 begin
  assert_scope(p_request,p_actor);v:=m.get_object('load_recovery');load_id:=v.get_string('load_operation_id');book_id:=v.get_string('original_booking_operation_id');return_id:=v.get_string('return_offer_operation_id');
  select *into old_book from RRL_TARE_BOOK where OPERATION_ID=book_id;
  if old_book.STATUS!='TRANSFERRED'or old_book.PLACE_KIND not in('CASE','HU')or old_book.QUANTITY!=1 or s.get_string('place_kind')!=old_book.PLACE_KIND or s.get_string('place_id')!=old_book.PLACE_ID then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_TRANSFERRED_PLACE_REQUIRED');end if;
  select *into load_fact from RRL_TT_HU_LOAD_FACT where LOAD_OPERATION_ID=load_id;
  if load_fact.STATUS!='LOADED'or load_fact.DEPARTURE_OPERATION_ID is not null or load_fact.CUSTODY_RELEASE_OPERATION_ID is not null or old_book.OWNER_WARE_ID!=load_fact.WARE_ID or v.get_number('expected_load_version')is null or v.get_number('expected_load_version')!=load_fact.CONTENT_VERSION then raise_application_error(-20886,'TARE_RECOVERY_PREDEPARTURE_ORIGINAL_LOAD_REQUIRED');end if;
  select o.OPERATION_ID into old_offer_id from RRL_TARE_OFFER o join RRL_TARE_OFFER_BOOK b on b.OFFER_OPERATION_ID=o.OPERATION_ID join RRL_TARE_ACCEPT a on a.OFFER_OPERATION_ID=o.OPERATION_ID
   where b.LOAD_OPERATION_ID=load_id and b.BOOK_OPERATION_ID=book_id and a.OPERATION_ID=old_book.CLOSED_OPERATION_ID and a.ACCEPTED_QTY=o.QUANTITY;
  select *into old_offer from RRL_TARE_OFFER where OPERATION_ID=old_offer_id;
  select *into old_accept from RRL_TARE_ACCEPT where OPERATION_ID=old_book.CLOSED_OPERATION_ID;
  select *into back_offer from RRL_TARE_OFFER where OPERATION_ID=return_id;
  select *into back_accept from RRL_TARE_ACCEPT where OFFER_OPERATION_ID=return_id;
  if old_offer.FROM_KIND!='WAREHOUSE'or old_offer.TO_KIND!='VEHICLE'or old_offer.OWNER_WARE_ID!=load_fact.WARE_ID or old_offer.VEHICLE_ID!=load_fact.VEHICLE_ID or old_offer.TT_ID!=load_fact.TT_ID
   or back_offer.FROM_KIND!='VEHICLE'or back_offer.TO_KIND!='WAREHOUSE'or back_offer.FROM_BALANCE_KEY!=old_offer.TO_BALANCE_KEY or back_offer.TO_BALANCE_KEY!=old_book.BALANCE_KEY
   or back_offer.OWNER_WARE_ID!=old_book.OWNER_WARE_ID or back_offer.PALLET_TYPE_ID!=old_book.PALLET_TYPE_ID or back_offer.CONDITION_CODE!='GOOD'
   or back_offer.VEHICLE_ID!=load_fact.VEHICLE_ID or back_offer.TT_ID!=load_fact.TT_ID or back_offer.QUANTITY!=old_book.QUANTITY or back_accept.ACCEPTED_QTY!=old_book.QUANTITY or back_accept.SHORT_QTY!=0
   or back_offer.OFFERED_AT<old_accept.ACCEPTED_AT or back_accept.ACCEPTED_AT<back_offer.OFFERED_AT
   or back_accept.ACCEPTED_BY=back_offer.OFFERED_BY then raise_application_error(-20886,'TARE_RECOVERY_EXACT_ACCEPTED_VEHICLE_RETURN_REQUIRED');end if;
  if old_book.PLACE_KIND='CASE'then
  case_id:=to_number(old_book.PLACE_ID);select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=case_id;
  if ct.STATUS!='SHIPPED'or ct.SHIPPED_OPERATION!=load_id or ct.WARE_ID!=old_book.OWNER_WARE_ID or ct.PALLET_TYPE_ID!=old_book.PALLET_TYPE_ID then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_CASE_OWNER_REQUIRED');end if;
  wire:=load_fact.COMPOSITION_JSON;
  select count(*),max(S),max(V)into n,scan_value,original_version from json_table(wire,'$.nodes[*]'columns(K varchar2(20)path '$.kind',C number path '$.case_task_id',S varchar2(200)path '$.sscc',V number path '$.version'))where K='CASE'and C=case_id;
  if n!=1 or ct.CONTENT_VERSION!=original_version+1 or v.get_string('scan_place')is null or v.get_string('scan_place')!=scan_value then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_CASE_SCAN_EPOCH_REQUIRED');end if;
  else
   root_uid:=old_book.PLACE_ID;
   if load_fact.ROOT_UID is null or load_fact.ROOT_UID!=root_uid or load_fact.ROOT_CASE_TASK_ID is not null then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_WHOLE_ROOT_REQUIRED');end if;
   tree:=json_object_t.parse(load_fact.COMPOSITION_JSON);node:=treat(tree.get_array('nodes').get(0)as json_object_t);
   root_kind:=node.get_string('kind');original_version:=node.get_number('version');cell_value:=tree.get_string('cell');
   if node.get_string('uid')!=root_uid or root_kind not in('CONTAINER','STOCK')then raise_application_error(-20886,'TARE_RECOVERY_ARCHIVED_ROOT_KIND_REQUIRED');end if;
   scan_value:=nvl(node.get_string('sscc'),root_uid);
   if v.get_string('scan_place')is null or v.get_string('scan_place')!=scan_value then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_ROOT_SCAN_REQUIRED');end if;
   select *into pp from RRL_PALLETS where UID_PALLET=root_uid;
   if nvl(pp.HU_KIND,'STOCK')!=root_kind then raise_application_error(-20886,'TARE_RECOVERY_CURRENT_ROOT_KIND_REQUIRED');end if;
   select count(*)into n from RRL_WMS_HU_LINK where CHILD_PALLET_UID=root_uid and ACTIVE_FLAG=1;
   if n!=0 then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_ROOT_NOT_FREE');end if;
   if root_kind='CONTAINER'then
    if pp.HU_SHIPPED_OPERATION is null or pp.HU_SHIPPED_OPERATION!=load_id or pp.HU_CONTENT_VERSION!=original_version+1 or pp.HU_CURRENT_CELL is not null then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_CONTAINER_EPOCH_REQUIRED');end if;
   else
    select nvl(sum(REMAIN),0),nvl(sum(HARD_RESERVED_BASE),0)into p_total,h_total from RRL_REMAINS where UID_POLETA=root_uid;
    if p_total!=0 or h_total!=0 or pp.HU_CONTENT_VERSION!=original_version then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_FULLPAL_ZERO_EPOCH_REQUIRED');end if;
    select count(*),max(PICKED_WAREHOUSE_TASK_ID),max(FULFILLMENT_ID),max(CUSTOMER_ORDER_ID)into n,task_id,ff_id,order_id from RRL_CUSTOMER_ORDER_FULFILLMENT where PICKED_CASE_TASK_ID is null and PICKED_PALLET_UID=root_uid and STATUS='SHIPPED'and SHIPPED_OPERATION_ID=load_id;
    if n!=1 or task_id is null then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_FULLPAL_BIND_REQUIRED');end if;
    select count(*),max(SOURCE_DOC_ID)into n,wave_id from RRL_WAREHOUSE_TASK where TASK_ID=task_id and STATUS='DONE'and TASK_TYPE='PICKING_MOVE'and UID_PALLET=root_uid and SOURCE_DOC_TYPE='PICK_WAVE'and TO_WARE_ID=load_fact.WARE_ID;
    if n!=1 then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_FULLPAL_TASK_REQUIRED');end if;
    select count(*)into n from RRL_PICK_WAVE where PICK_WAVE_ID=wave_id and STATUS='LAUNCHED';
    if n!=1 then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_FULLPAL_WAVE_REQUIRED');end if;
    select STOCK_VERSION into stock_version from RRL_REMAINS where UID_POLETA=root_uid and CELL=cell_value;
   end if;
   select count(*)into n from RRL_CELLS where CELL=cell_value and WARE_ID=load_fact.WARE_ID;
   if n!=1 then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_ROOT_CELL_WARE_REQUIRED');end if;
   j.put('root_uid',root_uid);j.put('root_kind',root_kind);j.put('root_cell',cell_value);j.put('root_article',pp.ARTICUL);j.put('root_stock_version',stock_version);j.put('root_version',pp.HU_CONTENT_VERSION);
   j.put('fullpal_fulfillment_id',ff_id);j.put('fullpal_order_id',order_id);j.put('fullpal_task_id',task_id);j.put('fullpal_wave_id',wave_id);
  end if;
  j.put('place_kind',old_book.PLACE_KIND);j.put('place_id',old_book.PLACE_ID);
  select count(*)into n from RRL_TARE_LOAD_RECOVERY where ORIGINAL_BOOK_OPERATION_ID=book_id or RETURN_OFFER_OPERATION_ID=return_id or RETURN_ACCEPT_OPERATION_ID=back_accept.OPERATION_ID;
  if n!=0 then raise_application_error(-20886,'TARE_RECOVERY_SOURCE_ALREADY_USED');end if;
  j.put('load_operation_id',load_id);j.put('original_booking_operation_id',book_id);j.put('return_offer_operation_id',return_id);j.put('return_accept_operation_id',back_accept.OPERATION_ID);j.put('original_offer_operation_id',old_offer_id);
  j.put('warehouse_id',old_book.OWNER_WARE_ID);j.put('pallet_type_id',old_book.PALLET_TYPE_ID);j.put('case_id',case_id);j.put('case_version',ct.CONTENT_VERSION);j.put('balance_key',rawtohex(old_book.BALANCE_KEY));j.put('load_version',load_fact.CONTENT_VERSION);
  return j.to_clob;
 exception when no_data_found then raise_application_error(-20886,'TARE_RECOVERY_ORIGINAL_ACCEPTED_RETURN_REQUIRED');end;
 procedure declare_recovery(p_domain clob,p_operation varchar2,r in out nocopy json_array_t)is v json_object_t:=json_object_t.parse(p_domain);
 begin
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_LOAD_RECOVERY',p_operation);
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_BOOK',v.get_string('original_booking_operation_id'));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TT_HU_LOAD_FACT',v.get_string('load_operation_id'));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER',v.get_string('original_offer_operation_id'));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_OFFER',v.get_string('return_offer_operation_id'));
  RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_TARE_ACCEPT',v.get_string('return_accept_operation_id'));
  if v.get_string('place_kind')='CASE'then
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU','CASE:'||RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('case_id')));
  else
   RRL_STOCK_PLAN_HELPER.anchor(r,30,'HU',v.get_string('root_uid'));
   if v.get_number('fullpal_task_id')is not null then
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER_FULFILLMENT',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('fullpal_fulfillment_id')));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('fullpal_order_id')));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_WAREHOUSE_TASK',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('fullpal_task_id')));
    RRL_STOCK_PLAN_HELPER.row_key(r,'RRL_PICK_WAVE',RRL_STOCK_PLAN_HELPER.decimal_text(v.get_number('fullpal_wave_id')));
   end if;
  end if;
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TARE.RECOVER.BOOK:'||v.get_string('original_booking_operation_id'));
  RRL_STOCK_PLAN_HELPER.anchor(r,70,'UNIQUE','TARE.RECOVER.RETURN:'||v.get_string('return_offer_operation_id'));
 end;
 procedure record_recovery(p_domain clob,p_operation varchar2,p_actor varchar2)is
  v json_object_t:=json_object_t.parse(p_domain);load_id varchar2(100):=v.get_string('load_operation_id');book_id varchar2(100):=v.get_string('original_booking_operation_id');return_id varchar2(100):=v.get_string('return_offer_operation_id');accept_id varchar2(100):=v.get_string('return_accept_operation_id');ware number:=v.get_number('warehouse_id');typ number:=v.get_number('pallet_type_id');ct number:=v.get_number('case_id');root_id varchar2(150):=v.get_string('root_uid');
 begin
  insert into RRL_TARE_LOAD_RECOVERY(OPERATION_ID,LOAD_OPERATION_ID,ORIGINAL_BOOK_OPERATION_ID,RETURN_OFFER_OPERATION_ID,RETURN_ACCEPT_OPERATION_ID,WARE_ID,PALLET_TYPE_ID,CASE_PICK_TASK_ID,ROOT_UID,CREATED_BY)values(p_operation,load_id,book_id,return_id,accept_id,ware,typ,ct,root_id,p_actor);
 end;
end;
/


CREATE OR REPLACE package body RRL_TARE_PARTICIPANT as
 procedure warehouse_actor(p_actor varchar2,p_owner number) is n number;
 begin
 select count(*) into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and(upper(trim(USER_GROUP))='GLOBAL_ADMIN' or WARE_ID=p_owner);
 if n!=1 then raise_application_error(-20882,'TARE_WAREHOUSE_BINDING_REQUIRED');end if;
 end;
 procedure holder_actor(p_actor varchar2,p_kind varchar2,p_id varchar2,p_owner number,p_trip RRL_TRANSPORT_TASK%rowtype,p_right varchar2) is n number;
 begin
 if RRL_HAS_WRIGHT(p_actor,p_right)!=1 then raise_application_error(-20882,'TARE_PARTICIPANT_PERMISSION_REQUIRED');end if;
 if p_kind='WAREHOUSE' then warehouse_actor(p_actor,p_owner);
 elsif p_kind='VEHICLE' then
 select count(*) into n from RRL_TRANSPORT_DRIVER_USER b join RUSERS u on u.ID=b.USER_ID
 where b.DRIVER_ID=p_trip.VODITEL_ID and b.USER_ID=p_actor and b.ACTIVE=1 and nvl(u.DELETED,0)=0 and upper(trim(u.USER_GROUP))!='GLOBAL_ADMIN';
 if n!=1 then raise_application_error(-20882,'TARE_AUTHENTICATED_CURRENT_DRIVER_REQUIRED');end if;
 else RRL_STOCK_STORE_RECEIPT_READ.require_receiver(p_actor,p_id);end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_TARE_PLANNING as
 function held_quantity(p_key raw) return number is q number;loss number;
 begin select nvl(sum(QUANTITY),0) into q from RRL_TARE_BOOK where BALANCE_KEY=p_key and STATUS='HELD';select nvl(max(QUANTITY),0) into loss from RRL_TARE_LOSS_PENDING where BALANCE_KEY=p_key;return q+loss;end;
 procedure assert_available(p_key raw,p_physical number,p_required number) is
 begin if p_physical-held_quantity(p_key)<p_required then raise_application_error(-20886,'TARE_SOURCE_HELD_FOR_ASSEMBLY');end if;end;
 function case_booking(p_task number,p_ware number,p_type number) return varchar2 is
 n number;parent_uid varchar2(200);next_uid varchar2(200);depth number:=0;v_book varchar2(100);
 begin
 select count(*) into n from RRL_TARE_BOOK where PLACE_KIND='CASE' and PLACE_ID=to_char(p_task,'TM9') and OWNER_WARE_ID=p_ware and PALLET_TYPE_ID=p_type and STATUS='HELD';
 if n=1 then select OPERATION_ID into v_book from RRL_TARE_BOOK where PLACE_KIND='CASE' and PLACE_ID=to_char(p_task,'TM9') and OWNER_WARE_ID=p_ware and PALLET_TYPE_ID=p_type and STATUS='HELD';return v_book;end if;
 begin select PARENT_UID into parent_uid from RRL_WMS_HU_LINK where CHILD_CASE_TASK_ID=p_task and ACTIVE_FLAG=1;
 exception when no_data_found then return null;end;
 loop
 depth:=depth+1;if depth>100 then raise_application_error(-20881,'TARE_CONTAINER_PARENT_BOUND_100');end if;
 begin select PARENT_UID into next_uid from RRL_WMS_HU_LINK where CHILD_PALLET_UID=parent_uid and ACTIVE_FLAG=1;parent_uid:=next_uid;
 exception when no_data_found then exit;end;
 end loop;
 select count(*) into n from RRL_TARE_BOOK where PLACE_KIND='HU' and PLACE_ID=parent_uid and OWNER_WARE_ID=p_ware and PALLET_TYPE_ID=p_type and STATUS='HELD';
 if n!=1 then return null;end if;
 select OPERATION_ID into v_book from RRL_TARE_BOOK where PLACE_KIND='HU' and PLACE_ID=parent_uid and OWNER_WARE_ID=p_ware and PALLET_TYPE_ID=p_type and STATUS='HELD';return v_book;
 end;
 procedure require_case(p_task number,p_ware number,p_type number) is
 begin if case_booking(p_task,p_ware,p_type) is null then raise_application_error(-20886,'CASE_ASSEMBLY_GOOD_TARE_BOOK_REQUIRED');end if;end;
end;
/


CREATE OR REPLACE package body RRL_TASK_RESOURCE_POLICY as
 function context_json(p_task number,p_action varchar2,p_actor varchar2,p_assignee varchar2,
  p_resource number default null,p_session number default null,p_equipment number default null) return clob is
  t RRL_WAREHOUSE_TASK%rowtype;s RRL_RESOURCE_SESSION%rowtype;r RRL_RESOURCE%rowtype;e RRL_RESOURCE_EQUIPMENT%rowtype;
  sh RRL_RESOURCE_SHIFT%rowtype;v_other_status varchar2(40);j json_object_t:=json_object_t();v_resource number:=p_resource;v_session number:=p_session;v_equipment number:=p_equipment;
  v_started_begin timestamp with time zone;v_started_end timestamp with time zone;v_current_begin timestamp with time zone;v_current_end timestamp with time zone;
  v_finishing_step boolean:=false;v_target varchar2(100):=trim(p_assignee);v_n number;v_actor varchar2(100):=trim(p_actor);v_types varchar2(1000);
 begin
  if p_action is null or p_action not in('ASSIGN','START','COMPLETE','COMPLETE_DOCUMENT') or v_actor is null or v_target is null then
   raise_application_error(-20881,'TASK_ASSIGNMENT_INPUT_REQUIRED');end if;
  select * into t from RRL_WAREHOUSE_TASK where TASK_ID=p_task;
  RRL_WAREHOUSE_TASK_ACCESS.assert_scope(p_task,v_actor,v_target);
  if t.TASK_SOURCE='WAVE' and t.TASK_TYPE='PICKING_MOVE' and p_action in('START','COMPLETE') then RRL_STOCK_WAVE_READY.assert_released(t.SOURCE_DOC_ID);end if;
  if p_action='COMPLETE_DOCUMENT' then
   if t.TASK_SOURCE!='MES_RAW_SUPPLY' or RRL_HAS_WRIGHT(v_actor,'mes_raw_transfer_confirm')!=1 then
    raise_application_error(-20882,'MES_DOCUMENT_CONFIRM_FORBIDDEN');end if;
   if p_resource is not null or p_session is not null or p_equipment is not null then
    raise_application_error(-20881,'DOCUMENT_CONFIRM_HAS_NO_RESOURCE_SESSION');end if;
   j.put_null('resource_id');j.put_null('resource_session_id');j.put_null('equipment_id');return j.to_clob;
  end if;
  if RRL_HAS_WRIGHT(v_actor,'warehouse_task_execute')!=1 then raise_application_error(-20882,'TASK_EXECUTE_FORBIDDEN');end if;
  select count(*) into v_n from RUSERS where ID=v_target and nvl(DELETED,0)=0;
  if v_n!=1 or RRL_HAS_WRIGHT(v_target,'warehouse_task_execute')!=1 then
   raise_application_error(-20882,'TASK_ASSIGNEE_NOT_EXECUTOR');end if;
  if p_action='ASSIGN' and t.STATUS not in('PLANNED','ASSIGNED') then
   raise_application_error(-20886,'TASK_ASSIGN_STATE_CONFLICT');end if;
  if p_action='START' and t.STATUS not in('PLANNED','ASSIGNED','IN_PROGRESS') then
   raise_application_error(-20886,'TASK_START_STATE_CONFLICT');end if;
  if p_action='COMPLETE' and t.STATUS not in('PLANNED','ASSIGNED','IN_PROGRESS') then
   raise_application_error(-20886,'TASK_COMPLETE_STATE_CONFLICT');end if;
  if v_target!=v_actor then
   if p_action!='ASSIGN' or RRL_HAS_WRIGHT(v_actor,'resource_dispatch_manage')!=1 then
    raise_application_error(-20882,'TASK_DISPATCH_PERMISSION_REQUIRED');end if;
  end if;
  if t.ASSIGNED_TO is not null and t.ASSIGNED_TO!=v_target then
   if t.STATUS='IN_PROGRESS' and p_action!='COMPLETE' then
    raise_application_error(-20886,'FINISH_CURRENT_PHYSICAL_STEP_BEFORE_REASSIGN');end if;
   if RRL_HAS_WRIGHT(v_actor,'warehouse_task_force_assign')!=1 then
    raise_application_error(-20882,'TASK_FORCE_ASSIGN_PERMISSION_REQUIRED');end if;
  end if;
  if t.ASSIGNED_TO=v_target then
   v_resource:=nvl(v_resource,t.RESOURCE_ID);v_session:=nvl(v_session,t.RESOURCE_SESSION_ID);v_equipment:=nvl(v_equipment,t.EQUIPMENT_ID);
  end if;
  if p_action!='ASSIGN' and v_session is null and (v_resource is not null or v_equipment is not null) then raise_application_error(-20882,'TASK_RESOURCE_SESSION_REQUIRED');end if;
  if p_action!='ASSIGN' and v_session is null and t.TASK_TYPE in('PUTAWAY','REPLENISHMENT','PICKING_MOVE','FG_TO_STORAGE','RAW_TO_PRODUCTION')
   and RRL_HAS_WRIGHT(v_actor,'warehouse_task_force_assign')!=1 then raise_application_error(-20882,'TASK_MACHINE_SESSION_REQUIRED');end if;
  if p_action!='ASSIGN' then
   select count(*) into v_n from RRL_WAREHOUSE_TASK where ASSIGNED_TO=v_target and STATUS='IN_PROGRESS' and TASK_ID!=p_task;
   if v_n>0 then raise_application_error(-20886,'FINISH_OTHER_OPERATOR_PHYSICAL_STEP_FIRST');end if;
   select count(*) into v_n from RRL_CASE_PICK_TASK where ASSIGNED_TO=v_target and PICKED_QTY>0 and STATUS in('IN_PROGRESS','PARTIAL','WAIT_REPLENISHMENT');
   if v_n>0 then raise_application_error(-20886,'FINISH_OPERATOR_CASE_CARRIER_FIRST');end if;
  end if;
  if v_session is not null then
   select * into s from RRL_RESOURCE_SESSION where SESSION_ID=v_session;
   if s.OPERATOR_USER_ID is null or s.OPERATOR_USER_ID!=v_target then
    raise_application_error(-20882,'TASK_SESSION_OWNER_CONFLICT');end if;
   if s.STATUS is null or (p_action='ASSIGN' and s.STATUS not in('ACTIVE','PAUSED'))
     or (p_action!='ASSIGN' and s.STATUS!='ACTIVE') then raise_application_error(-20886,'TASK_SESSION_NOT_ACTIVE');end if;
   if (v_resource is not null and v_resource!=s.RESOURCE_ID) or
      (v_equipment is not null and (s.EQUIPMENT_ID is null or v_equipment!=s.EQUIPMENT_ID)) then
    raise_application_error(-20886,'TASK_SESSION_RESOURCE_IDENTITY_CONFLICT');end if;
   select * into sh from RRL_RESOURCE_SHIFT where SHIFT_ID=s.SHIFT_ID;
   select from_tz(cast(sh.START_AT as timestamp),nvl(t.STARTED_SHIFT_TIME_ZONE,sessiontimezone)),
          from_tz(cast(sh.FINISH_AT as timestamp),nvl(t.STARTED_SHIFT_TIME_ZONE,sessiontimezone)),
          from_tz(cast(sh.START_AT as timestamp),sessiontimezone),from_tz(cast(sh.FINISH_AT as timestamp),sessiontimezone)
    into v_started_begin,v_started_end,v_current_begin,v_current_end from dual;
   v_finishing_step:=p_action in('COMPLETE','COMPLETE_DOCUMENT') and t.STATUS='IN_PROGRESS'
    and t.RESOURCE_SESSION_ID=s.SESSION_ID and t.ASSIGNED_TO=v_target
    and t.STARTED_AT is not null and sh.START_AT is not null and sh.FINISH_AT is not null
    and ((t.STARTED_AT_INSTANT is not null and t.STARTED_SHIFT_TIME_ZONE is not null
     and t.STARTED_AT_INSTANT between v_started_begin and v_started_end)
     or (t.STARTED_AT_INSTANT is null and t.STARTED_AT between sh.START_AT and sh.FINISH_AT));
   if sh.STATUS is null or sh.STATUS not in('PLANNED','OPEN') or
     (p_action!='ASSIGN' and (sh.STATUS!='OPEN' or sh.START_AT is null or sh.FINISH_AT is null or (not v_finishing_step and (systimestamp<v_current_begin or systimestamp>v_current_end)))) then
    raise_application_error(-20886,'TASK_SHIFT_UNAVAILABLE');end if;
   if p_action!='ASSIGN' and s.CURRENT_TASK_ID is not null and s.CURRENT_TASK_ID!=p_task then
    begin select STATUS into v_other_status from RRL_WAREHOUSE_TASK where TASK_ID=s.CURRENT_TASK_ID;
    exception when no_data_found then v_other_status:='UNKNOWN';end;
    if v_other_status not in('DONE','CANCELLED') then raise_application_error(-20886,'FINISH_CURRENT_PHYSICAL_STEP_FIRST');end if;
   end if;
   if s.CURRENT_INVENTORY_TASK_ID is not null then
    select STATUS into v_other_status from RRL_INVENTORY_TASK where INVENTORY_TASK_ID=s.CURRENT_INVENTORY_TASK_ID;
    if v_other_status not in('DONE','CANCELLED') then raise_application_error(-20886,'FINISH_CURRENT_INVENTORY_STEP_FIRST');end if;
   end if;
   v_resource:=s.RESOURCE_ID;v_equipment:=s.EQUIPMENT_ID;
  end if;
  if v_resource is not null then
   select * into r from RRL_RESOURCE where RESOURCE_ID=v_resource;
   if nvl(r.ACTIVE,0)!=1 or r.STATUS is null or r.STATUS not in('AVAILABLE','IN_WORK','IDLE')
      or (r.USER_ID is not null and r.USER_ID!=v_target) then raise_application_error(-20886,'TASK_RESOURCE_UNAVAILABLE');end if;
   select DEFAULT_TASK_TYPES into v_types from RRL_RESOURCE_TYPE where RESOURCE_TYPE=r.RESOURCE_TYPE and ACTIVE=1;
   if v_types is null or instr(','||replace(v_types,' ','')||',',','||t.TASK_TYPE||',')=0 then
    raise_application_error(-20886,'TASK_RESOURCE_TYPE_UNSUITABLE');end if;
   select count(*) into v_n from RRL_RESOURCE_TASK_QUAL where RESOURCE_ID=v_resource and TASK_TYPE=t.TASK_TYPE
    and ACTIVE=1 and VALID_FROM<=systimestamp and (VALID_UNTIL is null or VALID_UNTIL>systimestamp);
   if v_n!=1 then raise_application_error(-20886,'TASK_RESOURCE_QUALIFICATION_REQUIRED');end if;
   if v_equipment is null and r.EQUIPMENT_ID is not null then raise_application_error(-20886,'TASK_RESOURCE_EQUIPMENT_REQUIRED');end if;
   if r.EQUIPMENT_ID is not null and r.EQUIPMENT_ID!=v_equipment then raise_application_error(-20886,'TASK_RESOURCE_EQUIPMENT_BINDING_CONFLICT');end if;
   if r.WARE_ID is not null and r.WARE_ID not in(nvl(t.FROM_WARE_ID,r.WARE_ID),nvl(t.TO_WARE_ID,r.WARE_ID)) then
    raise_application_error(-20886,'TASK_RESOURCE_WAREHOUSE_CONFLICT');end if;
  end if;
  if v_equipment is not null then
   select * into e from RRL_RESOURCE_EQUIPMENT where EQUIPMENT_ID=v_equipment;
   if nvl(e.ACTIVE,0)!=1 or e.SERVICE_STATUS is null or e.SERVICE_STATUS!='ACTIVE' then
    raise_application_error(-20886,'TASK_EQUIPMENT_UNAVAILABLE');end if;
   if e.WARE_ID is not null and e.WARE_ID not in(nvl(t.FROM_WARE_ID,e.WARE_ID),nvl(t.TO_WARE_ID,e.WARE_ID)) then
    raise_application_error(-20886,'TASK_EQUIPMENT_WAREHOUSE_CONFLICT');end if;
  end if;
  if p_action='START' and t.STATUS='IN_PROGRESS' and
   (nvl(t.ASSIGNED_TO,chr(0))!=v_target or nvl(t.RESOURCE_SESSION_ID,-1)!=nvl(v_session,-1)
    or nvl(t.RESOURCE_ID,-1)!=nvl(v_resource,-1) or nvl(t.EQUIPMENT_ID,-1)!=nvl(v_equipment,-1)) then
   raise_application_error(-20886,'TASK_START_ALREADY_IN_PROGRESS');end if;
  j.put('resource_id',v_resource);j.put('resource_session_id',v_session);j.put('equipment_id',v_equipment);
  j.put('finishing_started_step',case when v_finishing_step then 1 else 0 end);
  return j.to_clob;
 exception when no_data_found then raise_application_error(-20886,'TASK_RESOURCE_IDENTITY_NOT_FOUND');
 end;
end;
/


CREATE OR REPLACE package body RRL_TRACEABILITY_API as
  function add_trace_event(
    p_event_type       varchar2,
    p_entity_type      varchar2,
    p_entity_id        varchar2,
    p_source_system    varchar2 default null,
    p_correlation_id   varchar2 default null,
    p_idempotency_key  varchar2 default null,
    p_payload_json     clob default null,
    p_created_by       varchar2 default null
  ) return number is
    v_id number;
  begin
    if p_idempotency_key is not null then
      begin
        select TRACE_EVENT_ID into v_id
          from RRL_TRACE_EVENT
         where IDEMPOTENCY_KEY = p_idempotency_key;
        return v_id;
      exception
        when no_data_found then null;
      end;
    end if;

    select RRL_TRACE_EVENT_SQ.nextval into v_id from dual;

    insert into RRL_TRACE_EVENT (
      TRACE_EVENT_ID, EVENT_TYPE, ENTITY_TYPE, ENTITY_ID, SOURCE_SYSTEM,
      CORRELATION_ID, IDEMPOTENCY_KEY, PAYLOAD_JSON, CREATED_AT, CREATED_BY
    ) values (
      v_id, substr(upper(p_event_type), 1, 80), substr(upper(p_entity_type), 1, 50),
      substr(p_entity_id, 1, 100), substr(upper(p_source_system), 1, 30),
      substr(p_correlation_id, 1, 100), substr(p_idempotency_key, 1, 100),
      p_payload_json, sysdate, substr(p_created_by, 1, 50)
    );

    return v_id;
  end add_trace_event;

  function add_trace_edge(
    p_from_entity_type varchar2,
    p_from_entity_id   varchar2,
    p_to_entity_type   varchar2,
    p_to_entity_id     varchar2,
    p_edge_type        varchar2,
    p_quantity         number default null,
    p_unit_code        varchar2 default null,
    p_trace_event_id   number default null,
    p_created_by       varchar2 default null
  ) return number is
    v_id number;
  begin
    select RRL_TRACE_EDGE_SQ.nextval into v_id from dual;

    insert into RRL_TRACE_EDGE (
      TRACE_EDGE_ID, FROM_ENTITY_TYPE, FROM_ENTITY_ID, TO_ENTITY_TYPE, TO_ENTITY_ID,
      EDGE_TYPE, QUANTITY, UNIT_CODE, TRACE_EVENT_ID, CREATED_AT, CREATED_BY
    ) values (
      v_id, substr(upper(p_from_entity_type), 1, 50), substr(p_from_entity_id, 1, 100),
      substr(upper(p_to_entity_type), 1, 50), substr(p_to_entity_id, 1, 100),
      substr(upper(p_edge_type), 1, 50), p_quantity, substr(upper(p_unit_code), 1, 20),
      p_trace_event_id, sysdate, substr(p_created_by, 1, 50)
    );

    return v_id;
  end add_trace_edge;

  function enqueue_event(
    p_event_type       varchar2,
    p_aggregate_type   varchar2,
    p_aggregate_id     varchar2,
    p_idempotency_key  varchar2,
    p_payload_json     clob,
    p_target_system    varchar2 default null,
    p_correlation_id   varchar2 default null,
    p_max_try_count    number default 10
  ) return number is
    v_id number;
  begin
    begin
      select EVENT_OUTBOX_ID into v_id
        from RRL_EVENT_OUTBOX
       where IDEMPOTENCY_KEY = p_idempotency_key;
      return v_id;
    exception
      when no_data_found then null;
    end;

    select RRL_EVENT_OUTBOX_SQ.nextval into v_id from dual;

    insert into RRL_EVENT_OUTBOX (
      EVENT_OUTBOX_ID, EVENT_TYPE, AGGREGATE_TYPE, AGGREGATE_ID, TARGET_SYSTEM,
      CORRELATION_ID, IDEMPOTENCY_KEY, PAYLOAD_JSON, STATUS, TRY_COUNT,
      MAX_TRY_COUNT, CREATED_AT
    ) values (
      v_id, substr(upper(p_event_type), 1, 80), substr(upper(p_aggregate_type), 1, 50),
      substr(p_aggregate_id, 1, 100), substr(upper(p_target_system), 1, 30),
      substr(p_correlation_id, 1, 100), substr(p_idempotency_key, 1, 100),
      p_payload_json, 'PENDING', 0, nvl(p_max_try_count, 10), sysdate
    );

    return v_id;
  end enqueue_event;

  function lock_next_outbox(
    p_worker_id        varchar2,
    p_target_system    varchar2 default null
  ) return number is
    v_id number;
  begin
    select EVENT_OUTBOX_ID
      into v_id
      from RRL_EVENT_OUTBOX
     where EVENT_OUTBOX_ID = (
       select EVENT_OUTBOX_ID
         from (
           select EVENT_OUTBOX_ID
             from RRL_EVENT_OUTBOX
            where STATUS in ('PENDING', 'RETRY')
              and (NEXT_RETRY_AT is null or NEXT_RETRY_AT <= sysdate)
              and (p_target_system is null or TARGET_SYSTEM = upper(p_target_system))
            order by CREATED_AT, EVENT_OUTBOX_ID
         )
        where rownum = 1
     )
       for update skip locked;

    update RRL_EVENT_OUTBOX
       set STATUS = 'LOCKED',
           LOCKED_BY = substr(p_worker_id, 1, 100),
           LOCKED_AT = sysdate
     where EVENT_OUTBOX_ID = v_id;

    return v_id;
  exception
    when no_data_found then
      return null;
  end lock_next_outbox;

  procedure mark_outbox_done(
    p_event_outbox_id  number,
    p_status           varchar2 default 'DONE',
    p_error_text       varchar2 default null
  ) is
  begin
    update RRL_EVENT_OUTBOX
       set STATUS = substr(upper(nvl(p_status, 'DONE')), 1, 30),
           LAST_ERROR = substr(p_error_text, 1, 4000),
           SENT_AT = nvl(SENT_AT, sysdate),
           FINISHED_AT = sysdate,
           LOCKED_BY = null,
           LOCKED_AT = null
     where EVENT_OUTBOX_ID = p_event_outbox_id;
  end mark_outbox_done;

  procedure mark_outbox_error(
    p_event_outbox_id      number,
    p_error_text           varchar2,
    p_retry_delay_minutes  number default 5,
    p_dead_letter          number default 0
  ) is
  begin
    update RRL_EVENT_OUTBOX
       set TRY_COUNT = nvl(TRY_COUNT, 0) + 1,
           STATUS = case
                      when nvl(p_dead_letter, 0) = 1 then 'DEAD_LETTER'
                      when nvl(TRY_COUNT, 0) + 1 >= nvl(MAX_TRY_COUNT, 10) then 'DEAD_LETTER'
                      else 'RETRY'
                    end,
           NEXT_RETRY_AT = case
                             when nvl(p_dead_letter, 0) = 1 then null
                             when nvl(TRY_COUNT, 0) + 1 >= nvl(MAX_TRY_COUNT, 10) then null
                             else sysdate + (nvl(p_retry_delay_minutes, 5) / 1440)
                           end,
           LAST_ERROR = substr(p_error_text, 1, 4000),
           FINISHED_AT = case
                           when nvl(p_dead_letter, 0) = 1 then sysdate
                           when nvl(TRY_COUNT, 0) + 1 >= nvl(MAX_TRY_COUNT, 10) then sysdate
                           else FINISHED_AT
                         end,
           LOCKED_BY = null,
           LOCKED_AT = null
     where EVENT_OUTBOX_ID = p_event_outbox_id;
  end mark_outbox_error;

  function add_adapter_request(
    p_system_code          varchar2,
    p_request_kind         varchar2,
    p_event_outbox_id      number default null,
    p_business_key         varchar2 default null,
    p_cert_alias           varchar2 default null,
    p_cert_thumbprint      varchar2 default null,
    p_signature_status     varchar2 default null,
    p_request_json         clob default null,
    p_status               varchar2 default 'STARTED',
    p_try_no               number default 1
  ) return number is
    v_id number;
  begin
    select RRL_ADAPTER_REQUEST_LOG_SQ.nextval into v_id from dual;

    insert into RRL_ADAPTER_REQUEST_LOG (
      ADAPTER_REQUEST_ID, EVENT_OUTBOX_ID, SYSTEM_CODE, REQUEST_KIND, BUSINESS_KEY,
      CERT_ALIAS, CERT_THUMBPRINT, SIGNATURE_STATUS, REQUEST_JSON, STATUS,
      TRY_NO, CREATED_AT, SENT_AT
    ) values (
      v_id, p_event_outbox_id, substr(upper(p_system_code), 1, 20),
      substr(upper(p_request_kind), 1, 80), substr(p_business_key, 1, 200),
      substr(p_cert_alias, 1, 200), substr(p_cert_thumbprint, 1, 200),
      substr(upper(p_signature_status), 1, 30), p_request_json,
      substr(upper(nvl(p_status, 'STARTED')), 1, 30), nvl(p_try_no, 1), sysdate, sysdate
    );

    return v_id;
  end add_adapter_request;

  procedure update_adapter_request(
    p_adapter_request_id   number,
    p_response_json        clob default null,
    p_external_request_id  varchar2 default null,
    p_external_document_id varchar2 default null,
    p_external_status      varchar2 default null,
    p_http_status          number default null,
    p_status               varchar2 default 'DONE',
    p_error_code           varchar2 default null,
    p_error_text           varchar2 default null
  ) is
  begin
    update RRL_ADAPTER_REQUEST_LOG
       set RESPONSE_JSON = p_response_json,
           EXTERNAL_REQUEST_ID = substr(p_external_request_id, 1, 200),
           EXTERNAL_DOCUMENT_ID = substr(p_external_document_id, 1, 200),
           EXTERNAL_STATUS = substr(p_external_status, 1, 50),
           HTTP_STATUS = p_http_status,
           STATUS = substr(upper(nvl(p_status, 'DONE')), 1, 30),
           ERROR_CODE = substr(p_error_code, 1, 100),
           ERROR_TEXT = substr(p_error_text, 1, 4000),
           FINISHED_AT = sysdate
     where ADAPTER_REQUEST_ID = p_adapter_request_id;
  end update_adapter_request;

  function create_quality_hold(
    p_entity_type      varchar2,
    p_entity_id        varchar2,
    p_reason_code      varchar2 default null,
    p_reason_text      varchar2 default null,
    p_created_by       varchar2 default null
  ) return number is
    v_id number;
  begin
    select RRL_QUALITY_HOLD_SQ.nextval into v_id from dual;

    insert into RRL_QUALITY_HOLD (
      QUALITY_HOLD_ID, ENTITY_TYPE, ENTITY_ID, HOLD_STATUS, REASON_CODE,
      REASON_TEXT, CREATED_AT, CREATED_BY
    ) values (
      v_id, substr(upper(p_entity_type), 1, 50), substr(p_entity_id, 1, 100),
      'ACTIVE', substr(upper(p_reason_code), 1, 50), substr(p_reason_text, 1, 1000),
      sysdate, substr(p_created_by, 1, 50)
    );

    return v_id;
  end create_quality_hold;

  procedure release_quality_hold(
    p_quality_hold_id  number,
    p_released_by      varchar2 default null,
    p_release_reason   varchar2 default null
  ) is
  begin
    update RRL_QUALITY_HOLD
       set HOLD_STATUS = 'RELEASED',
           RELEASED_AT = sysdate,
           RELEASED_BY = substr(p_released_by, 1, 50),
           RELEASE_REASON = substr(p_release_reason, 1, 1000)
     where QUALITY_HOLD_ID = p_quality_hold_id
       and HOLD_STATUS = 'ACTIVE';
  end release_quality_hold;
end RRL_TRACEABILITY_API;
/


CREATE OR REPLACE package body RRL_TRACE_AGG_LIFECYCLE as
 g_writing boolean:=false;
 procedure assert_write is begin
 if not g_writing then raise_application_error(-20863,'TRACE_AGG_LIFECYCLE_OWNER_REQUIRED');end if;
 end;
 procedure assert_scan(p_system varchar2,p_profile varchar2,p_hash varchar2)is n number;begin
 select count(*)into n from RRL_TRACE_AGG_BLOCK where SYSTEM_CODE=p_system and PROFILE_CODE=p_profile and CODE_HASH=p_hash;
 if n!=0 then raise_application_error(-20886,'INTERWARE_LOCAL_AGGREGATION_INVALIDATED');end if;
 end;
 function invalidate(p_operation varchar2,p_request clob,p_actor varchar2)return clob is
 m json_object_t:=json_object_t.parse(p_request);result json_object_t:=json_object_t();
 v_system varchar2(40);v_profile varchar2(80);v_hash varchar2(64);v_origin varchar2(200);
 v_reason varchar2(30);v_reference varchar2(200);v_ware number;v_journal number;
 digest raw(32);old_digest raw(32);old_result clob;n number;body clob;blocked_wire clob;members_wire clob;expected_members number;v_manifest varchar2(100);v_node varchar2(100);blocked json_array_t;blocked_item json_object_t;
 begin
 RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
 if p_operation is null or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]{1,100}$')or p_actor is null or RRL_HAS_WRIGHT(p_actor,'trace_manifest_import')!=1 then raise_application_error(-20882,'TRACE_AGG_INVALIDATION_FORBIDDEN');end if;
 if m.get_size!=7 then raise_application_error(-20871,'TRACE_AGG_INVALIDATION_FIELDS');end if;
 v_system:=m.get_string('system_code');v_profile:=m.get_string('profile_code');v_hash:=m.get_string('code_hash');
 v_origin:=m.get_string('origin_pallet_identifier');v_ware:=m.get_number('warehouse_id');
 v_reason:=m.get_string('reason_code');v_reference:=m.get_string('document_reference');
 if v_system is null or v_profile is null or v_origin is null or v_ware is null or v_reason is null or v_reason not in('OPENED','REPACKED','DAMAGED','COMPOSITION_CHANGED')or trim(v_reference) is null or not regexp_like(v_hash,'^[a-f0-9]{64}$')or v_hash is null then raise_application_error(-20871,'TRACE_AGG_INVALIDATION_INVALID');end if;
 select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and(WARE_ID=v_ware or upper(trim(USER_GROUP))='GLOBAL_ADMIN');
 if n!=1 then raise_application_error(-20882,'TRACE_AGG_CURRENT_WARE_ACTOR_REQUIRED');end if;
 digest:=sys.dbms_crypto.hash(p_request||chr(10)||p_actor,sys.dbms_crypto.hash_sh256);
 begin select PAYLOAD_HASH,RESULT_JSON into old_digest,old_result from RRL_TRACE_AGG_INVALIDATION where OPERATION_ID=p_operation;
 if old_digest!=digest then raise_application_error(-20864,'TRACE_AGG_INVALIDATION_PAYLOAD_CONFLICT');end if;
 return old_result;exception when no_data_found then null;end;
 select count(*)into n from(
 select a.CODE_HASH from RRL_TRACE_SENDER_AGG a join RRL_TRACE_MANIFEST_USE u on u.MANIFEST_OPERATION_ID=a.MANIFEST_OPERATION_ID
 join RRL_STOCK_OPERATION op on op.OPERATION_ID=u.STOCK_OPERATION_ID and op.STATE='APPLIED'
 where u.UID_PALLET=v_origin and a.SYSTEM_CODE=v_system and a.PROFILE_CODE=v_profile and a.CODE_HASH=v_hash
 union all
 select a.CODE_HASH from RRL_SAP_TRACE_AGG a join RRL_SAP_PALLET_RECEIPT r on r.ORDER_ID=a.ORDER_ID and r.LINE_NUMBER=a.LINE_NUMBER
 join RRL_STOCK_OPERATION op on op.OPERATION_ID=r.STOCK_OPERATION_ID and op.STATE='APPLIED'and op.COMMAND_TYPE='SAP_RECEIPT'
 where r.UID_PALLET=v_origin and r.POSTED_BASE_QTY>0 and a.SYSTEM_CODE=v_system and a.PROFILE_CODE=v_profile and a.CODE_HASH=v_hash
 );
 if n!=1 then raise_application_error(-20886,'TRACE_AGG_REGISTERED_ORIGIN_REQUIRED');end if;
 begin
 select a.UNITS_JSON,a.MANIFEST_OPERATION_ID,a.AGGREGATION_ID into members_wire,v_manifest,v_node from RRL_TRACE_SENDER_AGG a join RRL_TRACE_MANIFEST_USE u on u.MANIFEST_OPERATION_ID=a.MANIFEST_OPERATION_ID
 where u.UID_PALLET=v_origin and a.SYSTEM_CODE=v_system and a.PROFILE_CODE=v_profile and a.CODE_HASH=v_hash;
 exception when no_data_found then
 select a.UNITS_JSON into members_wire from RRL_SAP_TRACE_AGG a join RRL_SAP_PALLET_RECEIPT r on r.ORDER_ID=a.ORDER_ID and r.LINE_NUMBER=a.LINE_NUMBER
 where r.UID_PALLET=v_origin and r.POSTED_BASE_QTY>0 and a.SYSTEM_CODE=v_system and a.PROFILE_CODE=v_profile and a.CODE_HASH=v_hash;
 end;
 expected_members:=json_array_t.parse(members_wire).get_size;
 if expected_members<1 or expected_members>10000 then raise_application_error(-20881,'TRACE_AGG_MEMBER_BOUND');end if;
 select count(*)into n from json_table(members_wire,'$[*]'columns(UNIT_ID varchar2(100)path '$.unit_id'))j
 join RRL_WMS_RECEIPT_UNIT u on u.UID_PALLET=v_origin and u.UNIT_ID=j.UNIT_ID
 join RRL_CELLS c on c.CELL=u.CURRENT_CELL and c.WARE_ID=v_ware
 where u.STOCK_STATUS='AVAILABLE'and u.HARD_RESERVATION_ID is null;
 if n!=expected_members then raise_application_error(-20886,'TRACE_AGG_ALL_FREE_MEMBERS_LOCAL_CUSTODY_REQUIRED');end if;
 select count(*)into n from RRL_TRACE_AGG_BLOCK where SYSTEM_CODE=v_system and PROFILE_CODE=v_profile and CODE_HASH=v_hash;
 if n!=0 then raise_application_error(-20886,'TRACE_AGG_ALREADY_INVALIDATED');end if;
 if v_manifest is not null then
 select json_arrayagg(json_object('code_hash'value x.CODE_HASH)returning clob)into blocked_wire from(
 select v_hash CODE_HASH from dual
 union
 select a.CODE_HASH from RRL_TRACE_SENDER_AGG a
 where a.MANIFEST_OPERATION_ID=v_manifest and a.SYSTEM_CODE=v_system and a.PROFILE_CODE=v_profile
 and a.AGGREGATION_ID in(
 select e.PARENT_ID from(
 select j.PARENT_ID,j.CHILD_ID from RRL_TRACE_SENDER_MANIFEST manifest
 cross join json_table(manifest.RAW_JSON,'$.aggregations[*]'columns(PARENT_ID varchar2(100)path '$.aggregation_id',
 nested path '$.children[*]'columns(CHILD_ID varchar2(100)path '$')))j
 where manifest.OPERATION_ID=v_manifest and j.CHILD_ID is not null)e
 start with e.CHILD_ID=v_node connect by nocycle prior e.PARENT_ID=e.CHILD_ID))x;
 else
 select json_arrayagg(json_object('code_hash'value x.CODE_HASH)returning clob)into blocked_wire from(
 select v_hash CODE_HASH from dual
 union
 select parent.CODE_HASH from RRL_SAP_TRACE_AGG parent join RRL_SAP_PALLET_RECEIPT rec on rec.ORDER_ID=parent.ORDER_ID and rec.LINE_NUMBER=parent.LINE_NUMBER
 join RRL_SAP_TRACE_AGG child on child.ORDER_ID=parent.ORDER_ID and child.LINE_NUMBER=parent.LINE_NUMBER and child.SYSTEM_CODE=parent.SYSTEM_CODE and child.PROFILE_CODE=parent.PROFILE_CODE
 where rec.UID_PALLET=v_origin and parent.SYSTEM_CODE=v_system and parent.PROFILE_CODE=v_profile and child.CODE_HASH=v_hash
 and child.AGG_LEVEL='BOX'and parent.AGG_LEVEL='PALLET'
 and not exists(select 1 from json_table(child.UNITS_JSON,'$[*]'columns(UNIT_ID varchar2(100)path '$.unit_id'))cu
 where not exists(select 1 from json_table(parent.UNITS_JSON,'$[*]'columns(UNIT_ID varchar2(100)path '$.unit_id'))pu where pu.UNIT_ID=cu.UNIT_ID)))x;
 end if;
 blocked:=json_array_t.parse(blocked_wire);
 if blocked.get_size<1 or blocked.get_size>1000 then raise_application_error(-20881,'TRACE_AGG_ANCESTOR_BOUND');end if;
 result.put('operation_id',p_operation);result.put('status','INVALIDATED_LOCAL');result.put('system_code',v_system);
 result.put('profile_code',v_profile);result.put('code_hash',v_hash);result.put('origin_pallet_identifier',v_origin);
 result.put('warehouse_id',v_ware);result.put('reason_code',v_reason);result.put('document_reference',v_reference);
 result.put('actor',p_actor);result.put('stock_changed',false);result.put('government_ack_created',false);
 result.put('blocked_aggregate_count',blocked.get_size);result.put('blocked_aggregates',blocked);body:=result.to_clob;
 v_journal:=RRL_REGULATORY_API.write_journal(p_system_code=>v_system,p_entity_type=>'LOCAL_AGGREGATION',p_entity_id=>v_hash,p_uid_pallet=>v_origin,
 p_operation_type=>'LOCAL_AGGREGATION_INVALIDATE',p_old_status=>'REGISTERED',p_new_status=>'INVALIDATED_LOCAL',
 p_document_id=>v_reference,p_external_operation_id=>p_operation,p_payload_json=>body,p_message=>v_reason,p_created_by=>p_actor);
 result.put('journal_id',v_journal);body:=result.to_clob;
 g_writing:=true;
 insert into RRL_TRACE_AGG_INVALIDATION(OPERATION_ID,PAYLOAD_HASH,SYSTEM_CODE,PROFILE_CODE,CODE_HASH,ORIGIN_UID,WARE_ID,REASON_CODE,DOCUMENT_REFERENCE,ACTOR,JOURNAL_ID,RESULT_JSON)
 values(p_operation,digest,v_system,v_profile,v_hash,v_origin,v_ware,v_reason,v_reference,p_actor,v_journal,body);
 for i in 0..blocked.get_size-1 loop
 blocked_item:=treat(blocked.get(i)as json_object_t);
 declare v_block_hash varchar2(64):=blocked_item.get_string('code_hash');begin
 insert into RRL_TRACE_AGG_BLOCK(SYSTEM_CODE,PROFILE_CODE,CODE_HASH,INVALIDATION_OPERATION_ID,ORIGIN_UID)
 select v_system,v_profile,v_block_hash,p_operation,v_origin from dual
 where not exists(select 1 from RRL_TRACE_AGG_BLOCK where SYSTEM_CODE=v_system and PROFILE_CODE=v_profile and CODE_HASH=v_block_hash);
 end;
 end loop;
 g_writing:=false;return body;
 exception when others then g_writing:=false;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_TRANSPORT_COST_API as

 g_write boolean:=false;g_tx varchar2(100);

 procedure assert_writing is begin

  if not g_write or g_tx is null or g_tx!=dbms_transaction.local_transaction_id then

   raise_application_error(-20863,'TRANSPORT_COST_OWNER_REQUIRED');end if;

 end;

 procedure access_scope(p_ware number,p_actor varchar2,p_right varchar2)is n number;begin

  select count(*)into n from RUSERS u join RRL_WARES w on w.ID=p_ware where u.ID=p_actor and nvl(u.DELETED,0)=0

   and(u.WARE_ID=p_ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,p_right)=1;

  if n!=1 then raise_application_error(-20882,'TRANSPORT_COST_CURRENT_WAREHOUSE_RIGHT_REQUIRED');end if;

 end;

 procedure build(p_trip number,p_ware number,p_price number,p_actor varchar2,p_result out clob)is

  source_wire clob;norm_wire clob;s json_object_t;norm json_object_t;rate_source json_object_t;profile json_object_t;

  result json_object_t:=json_object_t();lines json_array_t:=json_array_t();missing json_array_t:=json_array_t();

  v_depart varchar2(100);v_instant varchar2(100);v_class varchar2(40);v_type varchar2(255);v_company varchar2(255);v_region varchar2(4000);

  basis_value varchar2(20);n number;dest_count number;received_count number;loads number;point_count number;

  v_vehicle number;v_vehicle_number varchar2(255);qty_roll number:=0;qty_pallet number:=0;qty_manual number:=0;qty_loader number:=0;

  total number:=0;rate_vehicle number;rate_point number;rate_roll number;rate_pallet number;rate_manual number;rate_loader number;

  procedure need(reason varchar2) is j json_object_t:=json_object_t();begin j.put('reason',reason);missing.append(j);end;

  procedure add_line(code varchar2,quantity number,rate_value number,line_basis varchar2)is j json_object_t:=json_object_t();amount number;begin

   if quantity=0 then return;end if;

   if rate_value is null or rate_value<0 or rate_value>=1e18 then raise_application_error(-20886,'TRANSPORT_RATE_INVALID');end if;

   amount:=round(quantity*rate_value,2);total:=total+amount;

   j.put('cost_code',code);j.put('quantity',quantity);j.put('rate',RRL_STOCK_PLAN_HELPER.decimal_text(rate_value));

   j.put('amount',RRL_STOCK_PLAN_HELPER.decimal_text(amount));j.put('basis',line_basis);lines.append(j);

  end;

 begin

  access_scope(p_ware,p_actor,'transport_dispatch_view');

  begin select vs.SOURCE_JSON into source_wire from RRL_TT_VEHICLE_SOURCE vs

   join RRL_STOCK_OPERATION o on o.OPERATION_ID=vs.DEPARTURE_OPERATION_ID and o.STATE='APPLIED'where vs.TT_ID=p_trip;

  exception when no_data_found then raise_application_error(-20886,'TRANSPORT_DEPARTURE_SOURCE_REQUIRED');end;

  s:=json_object_t.parse(source_wire);v_depart:=s.get_string('departure_operation_id');v_instant:=s.get_string('departed_at_instant');

  v_vehicle:=s.get_number('vehicle_id');v_vehicle_number:=s.get_string('vehicle_number');v_vehicle:=s.get_number('vehicle_id');v_vehicle_number:=s.get_string('vehicle_number');v_type:=s.get_string('task_vehicle_type');v_company:=s.get_string('carrier_company');v_region:=s.get_string('legacy_region_key');

  if s.get_string('profile_state')!='READY' then raise_application_error(-20886,'TRANSPORT_VEHICLE_PROFILE_REQUIRED');end if;

  profile:=s.get_object('vehicle_profile');profile:=profile.get_object('profile');v_class:=profile.get_string('vehicle_size_class');

  select count(*)into loads from RRL_TT_HU_LOAD_FACT where TT_ID=p_trip and DEPARTURE_OPERATION_ID=v_depart;

  if loads not between 1 and 200 then raise_application_error(-20886,'TRANSPORT_LOAD_BOUND');end if;

  select count(*)into n from RRL_TT_HU_LOAD_FACT l join RRL_STOCK_OPERATION o on o.OPERATION_ID=l.LOAD_OPERATION_ID and o.STATE='APPLIED'

   where l.TT_ID=p_trip and l.DEPARTURE_OPERATION_ID=v_depart and l.WARE_ID=p_ware

   and l.VEHICLE_ID=v_vehicle and l.VEHICLE_NUMBER=v_vehicle_number;

  if n!=loads then raise_application_error(-20886,'TRANSPORT_SINGLE_WAREHOUSE_SOURCE_REQUIRED');end if;

  select count(*),count(distinct DESTINATION_ADDR)into dest_count,point_count from(

   select distinct m.LOAD_OPERATION_ID,m.DESTINATION_ADDR from RRL_TT_HU_LOAD_ST m join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=m.LOAD_OPERATION_ID

   where l.TT_ID=p_trip and l.DEPARTURE_OPERATION_ID=v_depart);

  if dest_count not between 1 and 200 then raise_application_error(-20886,'TRANSPORT_DESTINATION_BOUND');end if;

  select count(*)into n from RRL_TT_HU_LOAD_FACT l where l.TT_ID=p_trip and l.DEPARTURE_OPERATION_ID=v_depart and not exists(

   select 1 from RRL_TT_HU_LOAD_ST m where m.LOAD_OPERATION_ID=l.LOAD_OPERATION_ID and m.DESTINATION_ADDR is not null);

  if n!=0 then raise_application_error(-20886,'TRANSPORT_DESTINATION_SOURCE_REQUIRED');end if;

  select count(*)into received_count from RRL_STORE_RECEIPT_FACT r

   join RRL_STOCK_OPERATION o on o.OPERATION_ID=r.OPERATION_ID and o.STATE='APPLIED'

   join RRL_STORE_UNLOAD_FACT u on u.RECEIPT_OPERATION_ID=r.OPERATION_ID

   join RRL_STORE_UNLOAD_START us on us.OPERATION_ID=u.START_OPERATION_ID

   join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=r.LOAD_OPERATION_ID

   where l.TT_ID=p_trip and l.DEPARTURE_OPERATION_ID=v_depart and exists(

    select 1 from RRL_TT_HU_LOAD_ST m where m.LOAD_OPERATION_ID=r.LOAD_OPERATION_ID and m.DESTINATION_ADDR=r.STORE_ADDR);

  if received_count!=dest_count then need('ACTUAL_UNLOADING_REQUIRED');end if;

  begin select RESULT_JSON into norm_wire from RRL_TRANSPORT_NORM_HISTORY h

   where h.SOURCE_PRICE_ID=p_price and h.WARE_ID=p_ware

   and h.EFFECTIVE_FROM<=trunc(cast(to_timestamp_tz(v_instant,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM')at time zone h.TIME_ZONE as date))

   order by h.EFFECTIVE_FROM desc,h.VERSION_NO desc fetch first 1 rows only;

  exception when no_data_found then raise_application_error(-20886,'TRANSPORT_NORM_PERIOD_REQUIRED');end;

  norm:=json_object_t.parse(norm_wire);rate_source:=norm.get_object('source');

  if norm.get_string('vehicle_type')!=v_type or norm.get_string('vehicle_size_class')!=v_class then raise_application_error(-20886,'TRANSPORT_NORM_VEHICLE_MISMATCH');end if;

  if rate_source.get_string('company')!='DEFAULT'and(v_company is null or rate_source.get_string('company')!=v_company)

   or rate_source.get_string('price_name')!='['||v_type||']'and(v_region is null or rate_source.get_string('price_name')!=v_region)

   then raise_application_error(-20886,'TRANSPORT_NORM_ROUTE_MISMATCH');end if;

  basis_value:=norm.get_string('unload_charge_basis');

  if basis_value is null or basis_value not in('POINT','PLACE')or not norm.has('pallet_unload_rate')then need('EXPLICIT_UNLOAD_NORM_REQUIRED');end if;

  rate_vehicle:=to_number(rate_source.get_string('vehicle_rate'),'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');

  rate_point:=to_number(rate_source.get_string('point_rate'),'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');

  rate_roll:=to_number(norm.get_string('rolling_unload_rate'),'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');

  rate_manual:=to_number(norm.get_string('manual_unload_rate'),'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');

  rate_loader:=to_number(norm.get_string('loader_rate'),'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');

  rate_pallet:=to_number(norm.get_string('pallet_unload_rate'),'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');

  for r in(

   select GROUP_KEY,min(METHOD)METHOD,count(distinct METHOD)METHOD_COUNT,max(EXTRA_LOADER)EXTRA_LOADER from(

    select case when basis_value='POINT'then r.STORE_ADDR else r.LOAD_OPERATION_ID||chr(1)||r.STORE_ADDR end GROUP_KEY,

     u.METHOD,case when u.METHOD='ROLL_CAGE'and u.ROLLING_DIFFICULT=1 and u.LOADER_PRESENT=1 then 1 else 0 end EXTRA_LOADER

    from RRL_STORE_RECEIPT_FACT r join RRL_STORE_UNLOAD_FACT u on u.RECEIPT_OPERATION_ID=r.OPERATION_ID

    join RRL_STOCK_OPERATION o on o.OPERATION_ID=r.OPERATION_ID and o.STATE='APPLIED'

    join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=r.LOAD_OPERATION_ID

    where l.TT_ID=p_trip and l.DEPARTURE_OPERATION_ID=v_depart and exists(

     select 1 from RRL_TT_HU_LOAD_ST m where m.LOAD_OPERATION_ID=r.LOAD_OPERATION_ID and m.DESTINATION_ADDR=r.STORE_ADDR)

   )group by GROUP_KEY

  )loop

   if r.METHOD_COUNT!=1 then need('MIXED_METHOD_AT_POINT');

   elsif r.METHOD='PALLET'then qty_pallet:=qty_pallet+1;

   elsif r.METHOD='ROLL_CAGE'then qty_roll:=qty_roll+1;qty_loader:=qty_loader+r.EXTRA_LOADER;

   elsif r.METHOD='MANUAL'then qty_manual:=qty_manual+1;

   else need('UNSUPPORTED_UNLOAD_METHOD');end if;

  end loop;

  add_line('TRANSPORT_VEHICLE',1,rate_vehicle,'TRIP');add_line('TRANSPORT_POINT',point_count,rate_point,'POINT');

  if basis_value in('POINT','PLACE')then

   add_line('UNLOAD_PALLET',qty_pallet,rate_pallet,basis_value);add_line('UNLOAD_ROLL_CAGE',qty_roll,rate_roll,basis_value);

   add_line('UNLOAD_MANUAL',qty_manual,rate_manual,basis_value);add_line('UNLOAD_EXTRA_LOADER',qty_loader,rate_loader,basis_value);

  end if;

  result.put('trip_id',p_trip);result.put('warehouse_id',p_ware);result.put('currency',norm.get_string('currency'));

  result.put('departure',s);result.put('norm',norm);result.put('lines',lines);result.put('missing',missing);

  result.put('load_count',loads);result.put('destination_count',dest_count);result.put('complete',missing.get_size=0);

  if missing.get_size=0 then result.put('total',RRL_STOCK_PLAN_HELPER.decimal_text(total));else result.put_null('total');end if;

  result.put('amount_rounding','HALF_UP_2_PER_ARTICLE');result.put('cost_posted',false);result.put('stock_changed',false);

  result.put('carrier_invoice_changed',false);p_result:=result.to_clob;

 end;

 procedure preview(p_trip number,p_ware number,p_price number,p_actor varchar2,p_result out clob)is begin

  build(p_trip,p_ware,p_price,p_actor,p_result);

 end;

 procedure conduct(p_request clob,p_actor varchar2,p_result out clob)is

  d json_object_t:=json_object_t.parse(p_request);k json_key_list;op varchar2(100);trip number;ware number;price number;expected_norm_version number;currency_value varchar2(3);

  fingerprint raw(32);old_hash raw(32);old_result clob;wire clob;j json_object_t;norm json_object_t;s json_object_t;line json_object_t;

  arr json_array_t;v_depart varchar2(100);v_version number;v_currency varchar2(3);v_amount number;line_rate number;line_amount number;

  saved varchar2(100);payload clob;event_id varchar2(100);hash_values json_array_t:=json_array_t();hash_wire varchar2(4000);line_code varchar2(40);line_qty number;line_basis varchar2(20);

 begin

  savepoint transport_cost_conduct;

  k:=d.get_keys;if k.count!=6 then raise_application_error(-20886,'TRANSPORT_COST_EXACT_FIELDS_REQUIRED');end if;

  for i in 1..k.count loop if k(i)not in('operation_id','trip_id','warehouse_id','source_price_id','currency','expected_norm_version')then raise_application_error(-20886,'TRANSPORT_COST_UNKNOWN_FIELD');end if;end loop;

  op:=d.get_string('operation_id');trip:=d.get_number('trip_id');ware:=d.get_number('warehouse_id');price:=d.get_number('source_price_id');currency_value:=d.get_string('currency');expected_norm_version:=d.get_number('expected_norm_version');

  if op is null or lengthb(op)>100 or not regexp_like(op,'^[A-Za-z0-9_.:-]+$')or expected_norm_version is null or expected_norm_version<1 or expected_norm_version!=trunc(expected_norm_version)or trip is null or ware is null or price is null or expected_norm_version is null or expected_norm_version<1 or expected_norm_version!=trunc(expected_norm_version)or trip is null or ware is null or price is null or trip<1 or ware<1 or price<1 or trip!=trunc(trip)or ware!=trunc(ware)or price!=trunc(price) or trip!=trunc(trip)or ware!=trunc(ware)or price!=trunc(price) or currency_value is null or not regexp_like(currency_value,'^[A-Z]{3}$')

   then raise_application_error(-20886,'TRANSPORT_COST_REQUEST_INVALID');end if;

  access_scope(ware,p_actor,'calc_tt_price');access_scope(ware,p_actor,'transport_dispatch_view');

  hash_values.append(trip);hash_values.append(ware);hash_values.append(price);hash_values.append(expected_norm_version);hash_values.append(currency_value);hash_values.append(p_actor);

  hash_wire:=hash_values.to_string;fingerprint:=dbms_crypto.hash(utl_i18n.string_to_raw(hash_wire,'AL32UTF8'),dbms_crypto.hash_sh256);

  select to_char(ID)into saved from RRL_TRANSPORT_TASK where ID=trip for update;

  begin select PAYLOAD_HASH,RESULT_JSON into old_hash,old_result from RRL_LOGISTICS_COST_RUN where OPERATION_ID=op;

   if old_hash!=fingerprint then raise_application_error(-20867,'TRANSPORT_COST_OPERATION_CONFLICT');end if;p_result:=old_result;return;

  exception when no_data_found then null;end;

  select to_char(VERSION_NO)into saved from RRL_TRANSPORT_NORM_HEAD where SOURCE_PRICE_ID=price and WARE_ID=ware for update;

  build(trip,ware,price,p_actor,wire);j:=json_object_t.parse(wire);

  if not j.get_boolean('complete')then raise_application_error(-20886,'TRANSPORT_COST_SOURCES_INCOMPLETE');end if;

  v_currency:=j.get_string('currency');if currency_value!=v_currency then raise_application_error(-20886,'TRANSPORT_COST_CURRENCY_MISMATCH');end if;

  s:=j.get_object('departure');v_depart:=s.get_string('departure_operation_id');norm:=j.get_object('norm');v_version:=norm.get_number('version');

  if v_version!=expected_norm_version then raise_application_error(-20867,'TRANSPORT_NORM_VERSION_CONFLICT');end if;

  j.put('operation_id',op);j.put('cost_posted',true);j.put('status','CALCULATED');j.put('calculated_by',p_actor);j.put('cost_kind','TRANSPORT_Q26');

  p_result:=j.to_clob;g_tx:=dbms_transaction.local_transaction_id(true);g_write:=true;

  insert into RRL_LOGISTICS_COST_RUN(OPERATION_ID,PAYLOAD_HASH,TT_ID,WARE_ID,CURRENCY,ACTOR,RESULT_JSON)values(op,fingerprint,trip,ware,v_currency,p_actor,p_result);

  insert into RRL_TRANSPORT_COST_CLAIM(DEPARTURE_OPERATION_ID,OPERATION_ID,SOURCE_PRICE_ID,VERSION_NO)values(v_depart,op,price,v_version);

  arr:=j.get_array('lines');

  for i in 0..arr.get_size-1 loop

   line:=treat(arr.get(i)as json_object_t);line_rate:=to_number(line.get_string('rate'),'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');

   line_amount:=to_number(line.get_string('amount'),'9999999999999999999999999D99','NLS_NUMERIC_CHARACTERS=''.,''');

   line_code:=line.get_string('cost_code');line_qty:=line.get_number('quantity');line_basis:=line.get_string('basis');

   line_code:=line.get_string('cost_code');line_qty:=line.get_number('quantity');line_basis:=line.get_string('basis');

   insert into RRL_TRANSPORT_COST_DETAIL(OPERATION_ID,COST_CODE,QUANTITY,RATE_VALUE,AMOUNT,BASIS)

    values(op,line_code,line_qty,line_rate,line_amount,line_basis);

  end loop;

  event_id:='FIN:'||rawtohex(dbms_crypto.hash(utl_i18n.string_to_raw('TRANSPORT_COST_RECOGNIZED:'||op,'AL32UTF8'),dbms_crypto.hash_sh256));

  j.put('event_type','TRANSPORT_COST_RECOGNIZED');j.put('posting_semantics','MONETARY_RECOGNITION');j.put('external_sap_ack',false);payload:=j.to_clob;

  insert into RRL_SAP_RECEIPT_OUTBOX(EVENT_ID,EVENT_TYPE,PAYLOAD_JSON)values(event_id,'TRANSPORT_COST_RECOGNIZED',payload);

  g_write:=false;g_tx:=null;

 exception when others then g_write:=false;g_tx:=null;rollback to transport_cost_conduct;raise;

 end;

end;
/


CREATE OR REPLACE package body RRL_TRANSPORT_EDIT_API as
 procedure actor_allowed(p_actor varchar2)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'transport_dispatch_edit')=1;
  if n!=1 then raise_application_error(-20882,'TRANSPORT_CURRENT_DISPATCHER_REQUIRED');end if;
 end;
 procedure create_trip(p_type varchar2,p_day date,p_actor varchar2,p_trip out number)is begin
  actor_allowed(p_actor);
  if p_type is null or lengthb(p_type)>10 or p_day is null or p_day!=trunc(p_day)then raise_application_error(-20886,'TRANSPORT_TYPE_DAY_REQUIRED');end if;
  p_trip:=RRL_TRASPORT_TASK_ADD(p_type,p_day,p_actor);update RRL_TRANSPORT_TASK set USER_ID=p_actor,CONDITION='Спланирован' where ID=p_trip;
 end;
 procedure update_trip(p_trip number,p_actor varchar2,p_body clob,p_result out clob)is
  b json_object_t:=json_object_t.parse(p_body);old_trip RRL_TRANSPORT_TASK%rowtype;requested RRL_TRANSPORT_TASK%rowtype;
  before_num varchar2(50);new_num varchar2(50);old_vehicle number;new_vehicle number;v_id number;
  vehicle_ids json_array_t:=json_array_t();vehicles_text clob;sts json_array_t:=json_array_t();seen json_object_t:=json_object_t();
  v_count number:=0;v_actual_ware number;v_actual_st varchar2(100);v_global number;v_critical boolean;v_check clob;result json_object_t;
 begin
  actor_allowed(p_actor);
  select TRANSPORT into before_num from RRL_TRANSPORT_TASK where ID=p_trip;
  new_num:=case when b.has('transport')then b.get_string('transport')else before_num end;
  if before_num is not null then
   begin select ID into old_vehicle from RRL_TR_VEHICLE where NUM=before_num;exception when no_data_found then old_vehicle:=null;end;
  end if;
  if new_num is not null and b.has('transport')then select ID into new_vehicle from RRL_TR_VEHICLE where NUM=new_num;else new_vehicle:=old_vehicle;end if;
  if old_vehicle is not null then vehicle_ids.append(old_vehicle);end if;
  if new_vehicle is not null and nvl(old_vehicle,-1)!=new_vehicle then vehicle_ids.append(new_vehicle);end if;
  vehicles_text:=vehicle_ids.to_clob;
  for item in(select ID from json_table(vehicles_text,'$[*]'columns(ID number path '$'))order by ID)loop
   select ID into v_id from RRL_TR_VEHICLE where ID=item.ID for update;
  end loop;
  select *into old_trip from RRL_TRANSPORT_TASK where ID=p_trip for update;requested:=old_trip;
  if nvl(old_trip.TRANSPORT,'~')!=nvl(before_num,'~')then raise_application_error(-20886,'TRANSPORT_VEHICLE_CHANGED_RETRY');end if;
  if nvl(old_trip.DELETED,0)!=0 then raise_application_error(-20886,'TRANSPORT_ACTIVE_TRIP_REQUIRED');end if;
  requested.TRANSPORT:=new_num;
  if b.has('voditel_id')then
   requested.VODITEL_ID:=b.get_number('voditel_id');
   if requested.VODITEL_ID=0 then requested.VODITEL_ID:=null;end if;
   if requested.VODITEL_ID is not null then
    select count(*)into v_count from RRL_TR_VODITEL where ID=requested.VODITEL_ID and nvl(DELETED,0)=0;
    if v_count!=1 then raise_application_error(-20886,'TRANSPORT_CURRENT_DRIVER_REQUIRED');end if;
   end if;
  end if;
  if b.has('dock')then requested.DOCK:=b.get_string('dock');end if;
  if b.has('transtype')then requested.TRANSTYPE:=b.get_string('transtype');end if;
  if b.has('shipment_date')then requested.SHIPMENT_DATE:=to_date(b.get_string('shipment_date'),'YYYY-MM-DD');end if;
  if b.has('shipment_time')then requested.SHIPMENT_TIME:=to_date(b.get_string('shipment_time'),'HH24:MI');end if;
  if b.has('primechanie')then requested.PRIMECHANIE:=b.get_string('primechanie');end if;
  v_critical:=nvl(requested.TRANSPORT,'~')!=nvl(old_trip.TRANSPORT,'~')or nvl(requested.VODITEL_ID,-1)!=nvl(old_trip.VODITEL_ID,-1)
   or nvl(requested.DOCK,'~')!=nvl(old_trip.DOCK,'~')or nvl(requested.TRANSTYPE,'~')!=nvl(old_trip.TRANSTYPE,'~')
   or nvl(requested.SHIPMENT_DATE,date '1900-01-01')!=nvl(old_trip.SHIPMENT_DATE,date '1900-01-01')
   or nvl(requested.SHIPMENT_TIME,date '1900-01-01')!=nvl(old_trip.SHIPMENT_TIME,date '1900-01-01');
  if v_critical then
   if old_trip.CONDITION='Отгружен'or nvl(old_trip.PAY_ORDER_ID,0)>0 then raise_application_error(-20886,'TRANSPORT_PLAN_FROZEN');end if;
   select count(*)into v_count from RRL_TT_HU_LOAD_FACT where TT_ID=p_trip and STATUS in('LOADED','DEPARTED');
   if v_count>0 then raise_application_error(-20886,'TRIP_CONFIRMED_UNLOADING_REQUIRED_BEFORE_REASSIGNMENT');end if;
  end if;
  v_count:=0;
  for item in(select ID,ST_NUMBER,WARE_ID from RRL_SBORKA_PALLETS where TRANSTASK_ID=p_trip order by ID fetch first 201 rows only)loop
   v_count:=v_count+1;if v_count>200 then raise_application_error(-20886,'TRANSPORT_EDIT_SOURCE_BOUND_200');end if;
   select ID,WARE_ID,ST_NUMBER into v_id,v_actual_ware,v_actual_st from RRL_SBORKA_PALLETS where ID=item.ID for update;
   if v_actual_st!=item.ST_NUMBER then raise_application_error(-20886,'TRANSPORT_SOURCE_ST_CHANGED_RETRY');end if;
   RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,v_actual_ware);
   if not seen.has(item.ST_NUMBER)then seen.put(item.ST_NUMBER,true);sts.append(item.ST_NUMBER);end if;
  end loop;
  if v_count=0 and nvl(old_trip.USER_ID,'~')!=p_actor then
   select count(*)into v_global from RUSERS where ID=p_actor and upper(trim(USER_GROUP))='GLOBAL_ADMIN';
   if v_global!=1 then raise_application_error(-20882,'TRANSPORT_EMPTY_TRIP_OWNER_REQUIRED');end if;
  end if;
  if v_critical then
   RRL_TRANSPORT_PLAN_RULES.check_vehicle(new_vehicle,sts.to_clob,0,v_check);result:=json_object_t.parse(v_check);
  else result:=json_object_t();result.put('validation_status','UNCHANGED_PLAN');end if;
  update RRL_TRANSPORT_TASK set TRANSPORT=requested.TRANSPORT,VODITEL_ID=requested.VODITEL_ID,DOCK=requested.DOCK,
   TRANSTYPE=requested.TRANSTYPE,SHIPMENT_DATE=requested.SHIPMENT_DATE,SHIPMENT_TIME=requested.SHIPMENT_TIME,
   PRIMECHANIE=requested.PRIMECHANIE,USER_ID=p_actor where ID=p_trip;
  result.put('task_id',p_trip);result.put('stock_changed',false);p_result:=result.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_TRANSPORT_NORM_API as
 g_writing boolean:=false;
 function writing return boolean is begin return g_writing;end;
 function decimal_value(d json_object_t,k varchar2)return number is v varchar2(100):=d.get_string(k);begin
  if v is null or not regexp_like(v,'^[0-9]{1,18}([.][0-9]{1,9})?$')then raise_application_error(-20886,'TRANSPORT_NORM_EXACT_RATE_REQUIRED');end if;
  return to_number(v,'999999999999999999D999999999','NLS_NUMERIC_CHARACTERS=''.,''');
 end;
 procedure publish(p_request clob,p_actor varchar2,p_result out clob)is
 d json_object_t:=json_object_t.parse(p_request);source json_object_t:=json_object_t();result json_object_t:=json_object_t();
 op varchar2(100):=d.get_string('operation_id');price_id number:=d.get_number('source_price_id');ware number:=d.get_number('warehouse_id');
 version number:=d.get_number('expected_version');n number;current_version number;head_ware number;user_group_name varchar2(255);effective date;last_date date;region varchar2(64);tz_check varchar2(64);
 currency_value varchar2(3);vehicle_type varchar2(40);size_class varchar2(40);old_actor nvarchar2(50);old_request clob;source_body clob;price RRL_TRANSPORT_PRICE%rowtype;
 roll_rate number;manual_rate number;loader_rate number;pallet_rate number;unload_basis varchar2(16);keys json_key_list:=d.get_keys;k varchar2(100);
 begin
  savepoint transport_norm_publish;
  if op is null or length(op)>100 or not regexp_like(op,'^[A-Za-z0-9_.:-]+$')or
    price_id is null or price_id<1 or price_id!=trunc(price_id)or ware is null or ware<1 or
    version is null or version<0 or version!=trunc(version)then raise_application_error(-20886,'TRANSPORT_NORM_INPUT_REQUIRED');end if;
  if keys.count not in(14,16)then raise_application_error(-20886,'TRANSPORT_NORM_FIELDS_REQUIRED');end if;
  for i in 1..keys.count loop k:=keys(i);
   if k not in('operation_id','source_price_id','warehouse_id','currency','effective_from','timezone_region','vehicle_type','vehicle_size_class',
    'rolling_unload_rate','manual_unload_rate','loader_rate','expected_version','reason','decision_reference','unload_charge_basis','pallet_unload_rate')then raise_application_error(-20886,'TRANSPORT_NORM_UNKNOWN_FIELD');end if;
  end loop;
  -- Stable current actor/group/grant during row waits and saved-result replay.
  begin
   select USER_GROUP into user_group_name from RUSERS where ID=p_actor and nvl(DELETED,0)=0 for update;
  exception when no_data_found then raise_application_error(-20882,'TRANSPORT_NORM_CURRENT_FINANCE_REQUIRED');end;
  if upper(trim(user_group_name))!='GLOBAL_ADMIN'then
   n:=0;
   for grant_row in(select ID from RIGHTS where USER_GROUP=user_group_name and upper(trim(RIGHT1))='CREATE_TT_PRICE'order by ID for update)loop n:=n+1;end loop;
   if n=0 then raise_application_error(-20882,'TRANSPORT_NORM_CURRENT_FINANCE_REQUIRED');end if;
  end if;
  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0 and
   (u.WARE_ID=ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(p_actor,'create_tt_price')=1
   and 1=(select count(*)from RRL_WARES where ID=ware);
  if n!=1 then raise_application_error(-20882,'TRANSPORT_NORM_CURRENT_FINANCE_REQUIRED');end if;
  begin
   select REQUEST_JSON,ACTOR,RESULT_JSON into old_request,old_actor,p_result from RRL_TRANSPORT_NORM_HISTORY where OPERATION_ID=op;
   select count(*)into n from dual where json_equal(old_request,p_request);
   if n!=1 or old_actor!=p_actor then raise_application_error(-20864,'TRANSPORT_NORM_OPERATION_CONFLICT');end if;
   return;
  exception when no_data_found then null;end;
  currency_value:=d.get_string('currency');region:=d.get_string('timezone_region');vehicle_type:=d.get_string('vehicle_type');size_class:=d.get_string('vehicle_size_class');
  if currency_value is null or not regexp_like(currency_value,'^[A-Z]{3}$')or region is null or
   vehicle_type is null or size_class is null or length(size_class)>40 or
   trim(d.get_string('reason'))is null or lengthb(d.get_string('reason'))>1000 or
   trim(d.get_string('decision_reference'))is null or lengthb(d.get_string('decision_reference'))>255
   then raise_application_error(-20886,'TRANSPORT_NORM_CONTRACT_REQUIRED');end if;
  select to_char(systimestamp at time zone(region),'TZR')into tz_check from dual;
  effective:=to_date(d.get_string('effective_from'),'FXYYYY-MM-DD');
  select count(*)into n from RRL_TRANSPORT_TYPE where TRANSPORTTYPE=vehicle_type;
  if n!=1 then raise_application_error(-20886,'TRANSPORT_NORM_VEHICLE_TYPE_REQUIRED');end if;
  roll_rate:=decimal_value(d,'rolling_unload_rate');manual_rate:=decimal_value(d,'manual_unload_rate');loader_rate:=decimal_value(d,'loader_rate');
  -- Original rate row serialises publications and prevents a concurrent legacy edit.
  begin select *into price from RRL_TRANSPORT_PRICE where ID=price_id for update;
  exception when no_data_found then raise_application_error(-20886,'TRANSPORT_NORM_LEGACY_SOURCE_REQUIRED');end;
  -- Same-op sender may have waited for another transaction to commit.
  begin
   select REQUEST_JSON,ACTOR,RESULT_JSON into old_request,old_actor,p_result from RRL_TRANSPORT_NORM_HISTORY where OPERATION_ID=op;
   select count(*)into n from dual where json_equal(old_request,p_request);
   if n!=1 or old_actor!=p_actor then raise_application_error(-20864,'TRANSPORT_NORM_OPERATION_CONFLICT');end if;
   return;
  exception when no_data_found then null;end;
  unload_basis:=d.get_string('unload_charge_basis');
  if unload_basis is null or unload_basis not in('POINT','PLACE')then raise_application_error(-20886,'TRANSPORT_UNLOAD_BASIS_REQUIRED');end if;
  pallet_rate:=decimal_value(d,'pallet_unload_rate');
  if price.PRICE is null or price.PRICE<0 or price.PRICE_FOR_HOURS is null or price.PRICE_FOR_HOURS<0 or
   price.PRICE_FOR_ADDR is null or price.PRICE_FOR_ADDR<0 or price.PRICE>=1e18 or price.PRICE_FOR_HOURS>=1e18 or price.PRICE_FOR_ADDR>=1e18 or
   price.PRICE*1e9!=trunc(price.PRICE*1e9)or price.PRICE_FOR_HOURS*1e9!=trunc(price.PRICE_FOR_HOURS*1e9)or
   price.PRICE_FOR_ADDR*1e9!=trunc(price.PRICE_FOR_ADDR*1e9)or price.PRICE_NAME is null or price.COMPANY is null
   then raise_application_error(-20886,'TRANSPORT_NORM_LEGACY_SOURCE_INCOMPLETE');end if;
  if (price.TYPE_TR is not null and price.TYPE_TR!=vehicle_type)or
   substr(price.PRICE_NAME,1,length(vehicle_type)+2)!='['||vehicle_type||']'
   then raise_application_error(-20886,'TRANSPORT_NORM_LEGACY_TYPE_MISMATCH');end if;
  g_writing:=true;
  merge into RRL_TRANSPORT_NORM_HEAD h using(select price_id P,ware W from dual)s on(h.SOURCE_PRICE_ID=s.P)
   when not matched then insert(SOURCE_PRICE_ID,WARE_ID,VERSION_NO)values(s.P,s.W,0);
  select VERSION_NO,WARE_ID into current_version,head_ware from RRL_TRANSPORT_NORM_HEAD where SOURCE_PRICE_ID=price_id for update;
  if head_ware!=ware then raise_application_error(-20882,'TRANSPORT_NORM_SOURCE_WAREHOUSE_CONFLICT');end if;
  if current_version!=version then raise_application_error(-20867,'TRANSPORT_NORM_VERSION_CONFLICT');end if;
  select max(EFFECTIVE_FROM)into last_date from RRL_TRANSPORT_NORM_HISTORY where SOURCE_PRICE_ID=price_id;
  if effective<last_date then raise_application_error(-20886,'TRANSPORT_NORM_BACKDATED_REVISION_REFUSED');end if;
  source.put('id',price.ID);source.put('price_name',price.PRICE_NAME);source.put('company',price.COMPANY);source.put('vehicle_type',vehicle_type);
  source.put('vehicle_rate',RRL_STOCK_PLAN_HELPER.decimal_text(price.PRICE));source.put('hour_rate',RRL_STOCK_PLAN_HELPER.decimal_text(price.PRICE_FOR_HOURS));
  source.put('point_rate',RRL_STOCK_PLAN_HELPER.decimal_text(price.PRICE_FOR_ADDR));source.put('norm_hours',RRL_STOCK_PLAN_HELPER.decimal_text(price.NORM_HOURS));
  result.put('operation_id',op);result.put('source_price_id',price_id);result.put('warehouse_id',ware);result.put('version',version+1);
  result.put('currency',currency_value);result.put('effective_from',to_char(effective,'YYYY-MM-DD'));result.put('timezone_region',region);
  result.put('vehicle_type',vehicle_type);result.put('vehicle_size_class',size_class);result.put('source',source);
  result.put('rolling_unload_rate',RRL_STOCK_PLAN_HELPER.decimal_text(roll_rate));result.put('manual_unload_rate',RRL_STOCK_PLAN_HELPER.decimal_text(manual_rate));
  result.put('unload_charge_basis',unload_basis);result.put('pallet_unload_rate',RRL_STOCK_PLAN_HELPER.decimal_text(pallet_rate));
  result.put('loader_rate',RRL_STOCK_PLAN_HELPER.decimal_text(loader_rate));result.put('status','PUBLISHED');
  result.put('carrier_price_changed',false);result.put('stock_changed',false);result.put('cost_posted',false);
  p_result:=result.to_clob;source_body:=source.to_clob;
  update RRL_TRANSPORT_NORM_HEAD set VERSION_NO=version+1 where SOURCE_PRICE_ID=price_id;
  insert into RRL_TRANSPORT_NORM_HISTORY(SOURCE_PRICE_ID,VERSION_NO,OPERATION_ID,WARE_ID,ACTOR,EFFECTIVE_FROM,CURRENCY,TIME_ZONE,VEHICLE_TYPE,VEHICLE_SIZE_CLASS,REQUEST_JSON,SOURCE_JSON,RESULT_JSON)
  values(price_id,version+1,op,ware,p_actor,effective,currency_value,region,vehicle_type,size_class,p_request,source_body,p_result);
  g_writing:=false;
 exception
  when dup_val_on_index then
   g_writing:=false;rollback to transport_norm_publish;
   select REQUEST_JSON,ACTOR,RESULT_JSON into old_request,old_actor,p_result from RRL_TRANSPORT_NORM_HISTORY where OPERATION_ID=op;
   select count(*)into n from dual where json_equal(old_request,p_request);
   if n!=1 or old_actor!=p_actor then raise_application_error(-20864,'TRANSPORT_NORM_OPERATION_CONFLICT');end if;
  when too_many_rows then g_writing:=false;rollback to transport_norm_publish;raise_application_error(-20886,'TRANSPORT_NORM_LEGACY_SOURCE_AMBIGUOUS');
  when others then g_writing:=false;rollback to transport_norm_publish;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_TRANSPORT_PLAN_API as
 g_plan number;g_tx varchar2(100);
 function apply_write_allowed(p_plan number)return number is begin
  if g_plan=p_plan and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;end;
 procedure basic_actor(p_actor varchar2)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'transport_dispatch_edit')=1;
  if n!=1 then raise_application_error(-20882,'PLAN_ACTIVE_DISPATCHER_REQUIRED');end if;
 end;
 procedure lock_vehicle(p_id number)is v_id number;begin
  select ID into v_id from RRL_TR_VEHICLE where ID=p_id for update;
 end;
 procedure lock_trip(p_tt number,p_expected_vehicle varchar2)is v RRL_TRANSPORT_TASK%rowtype;begin
  select *into v from RRL_TRANSPORT_TASK where ID=p_tt for update;
  if nvl(v.DELETED,0)!=0 or v.CONDITION='Отгружен'or nvl(v.PAY_ORDER_ID,0)>0 then raise_application_error(-20886,'PLAN_ACTIVE_UNBILLED_TRIP_REQUIRED');end if;
  if nvl(v.TRANSPORT,'~')!=nvl(p_expected_vehicle,'~')then raise_application_error(-20886,'PLAN_VEHICLE_CHANGED_RETRY');end if;
 end;
 procedure write_members(p_tt number,p_sts json_array_t)is v_answer varchar2(4000);v_order number;v_number varchar2(100);begin
  for i in 0..p_sts.get_size-1 loop
   v_number:=p_sts.get_string(i);v_answer:=RRL_TT_ADD_PALL(p_tt,v_number);
   if lower(substr(nvl(v_answer,'OK'),1,3))='err'then raise_application_error(-20886,'PLAN_NATIVE_ST_WRITER_FAILED');end if;
  end loop;
  v_order:=RRL_TT_REORDER_ADR(p_tt);
 end;
 procedure assign_sts(p_tt number,p_sts clob,p_actor varchar2,p_result out clob)is
  v_num varchar2(100);v_vehicle number;v_requested json_array_t:=json_array_t.parse(p_sts);
  v_prospective json_array_t:=json_array_t();v_seen json_object_t:=json_object_t();v_count number:=0;v_old number;v_state number;v_check clob;v_out json_object_t;v_loaded number;v_preserved number:=0;v_writable json_array_t:=json_array_t();v_requested_state number;v_requested_unassigned number;v_condition varchar2(100);v_requested_number varchar2(100);
 begin
  basic_actor(p_actor);
  if v_requested.get_size not between 1 and 200 then raise_application_error(-20886,'PLAN_SELECT_1_200_STS');end if;
  select TRANSPORT into v_num from RRL_TRANSPORT_TASK where ID=p_tt;
  if v_num is not null then select ID into v_vehicle from RRL_TR_VEHICLE where NUM=v_num;lock_vehicle(v_vehicle);end if;
  lock_trip(p_tt,v_num);
  for item in(select ID,ST_NUMBER from(
   select ID,ST_NUMBER from RRL_SBORKA_PALLETS where TRANSTASK_ID=p_tt
   union
   select p.ID,p.ST_NUMBER from RRL_SBORKA_PALLETS p join
    json_table(p_sts,'$[*]'columns(ST_NUMBER varchar2(100)path '$'))j on j.ST_NUMBER=p.ST_NUMBER)
   order by ID fetch first 201 rows only)loop
   v_count:=v_count+1;if v_count>200 then raise_application_error(-20886,'PLAN_ROUTE_ACTUAL_ROW_BOUND_200');end if;
   select TRANSTASK_ID,CONDITION into v_old,v_state from RRL_SBORKA_PALLETS where ID=item.ID for update;
   if nvl(v_old,0)not in(0,p_tt)then raise_application_error(-20886,'PLAN_ST_FOREIGN_OR_SHIPPED');end if;
    if v_state=2 then
     select count(*)into v_loaded from RRL_TT_HU_LOAD_ST m join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=m.LOAD_OPERATION_ID join RRL_STOCK_OPERATION o on o.OPERATION_ID=l.LOAD_OPERATION_ID
      where m.SBORKA_PALLET_ID=item.ID and m.ACTIVE_FLAG=1 and l.TT_ID=p_tt and l.VEHICLE_ID=v_vehicle and l.VEHICLE_NUMBER=v_num and l.STATUS='LOADED'and l.CUSTODY_RELEASED_AT is null and o.STATE='APPLIED';
     select CONDITION into v_condition from RRL_TRANSPORT_TASK where ID=p_tt;
     if v_old is null or v_old!=p_tt or v_loaded!=1 or v_condition is null or v_condition!='Спланирован'then raise_application_error(-20886,'PLAN_ST_FOREIGN_OR_SHIPPED');end if;
     v_preserved:=v_preserved+1;
    end if;
   for ware in(select WARE_ID from RRL_SBORKA_PALLETS where ID=item.ID)loop RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,ware.WARE_ID);end loop;
   if not v_seen.has(item.ST_NUMBER)then v_prospective.append(item.ST_NUMBER);v_seen.put(item.ST_NUMBER,true);end if;
  end loop;
  for i in 0..v_requested.get_size-1 loop if not v_seen.has(v_requested.get_string(i))then raise_application_error(-20886,'PLAN_ST_NOT_FOUND');end if;end loop;
  RRL_TRANSPORT_PLAN_RULES.check_vehicle(v_vehicle,v_prospective.to_clob,0,v_check);
  for i in 0..v_requested.get_size-1 loop
    v_requested_number:=v_requested.get_string(i);
    select count(case when CONDITION=2 then 1 end),
           count(case when nvl(TRANSTASK_ID,0)!=p_tt then 1 end)
     into v_requested_state,v_requested_unassigned from RRL_SBORKA_PALLETS where ST_NUMBER=v_requested_number;
    if v_requested_state>0 then
     if v_requested_unassigned>0 then raise_application_error(-20886,'PLAN_PARTIALLY_LOADED_ST_FROZEN');end if;
     -- Keep every already assigned row of a partly loaded ST intact. The legacy writer addresses the whole ST.
    else v_writable.append(v_requested_number);end if;
   end loop;
   if v_writable.get_size>0 then write_members(p_tt,v_writable);end if;
   v_out:=json_object_t.parse(v_check);v_out.put('retained_loaded_sts',v_preserved);v_out.put('written_sts',v_writable.get_size);v_out.put('assigned',v_requested.get_size);p_result:=v_out.to_clob;
 end;
 procedure apply_plan(p_plan number,p_day date,p_dock varchar2,p_actor varchar2,p_result out clob)is
  v_saved RRL_PLANNER_APPLY_RESULT%rowtype;v_raw clob;v_hash varchar2(64);v_applied date;v_doc json_object_t;
  v_routes json_array_t;v_route json_object_t;v_stops json_array_t;v_all json_array_t:=json_array_t();
  v_vehicles json_array_t:=json_array_t();v_wares json_array_t:=json_array_t();v_seen_st json_object_t:=json_object_t();v_seen_vehicle json_object_t:=json_object_t();v_seen_ware json_object_t:=json_object_t();
  type ids is table of number index by pls_integer;v_trips ids;v_vehicle_ids ids;
  v_vehicle RRL_TR_VEHICLE%rowtype;v_number varchar2(100);v_actual_ware number;v_current number;v_state number;v_found json_object_t:=json_object_t();v_row_count number:=0;v_check clob;v_all_text clob;v_vehicle_text clob;v_row_text clob;v_rows json_array_t:=json_array_t();v_found_keys json_key_list;
  v_result json_object_t:=json_object_t();v_created json_array_t:=json_array_t();v_key varchar2(100);v_declared_num varchar2(100);
 begin
  g_plan:=null;g_tx:=null;basic_actor(p_actor);
  if p_day is null or p_day!=trunc(p_day)then raise_application_error(-20886,'PLAN_SHIPMENT_DAY_REQUIRED');end if;
  select PAYLOAD,APPLIED_AT into v_raw,v_applied from RRL_PLANNER_PLANS where ID=p_plan for update;
  if dbms_lob.getlength(v_raw)>4194304 then raise_application_error(-20886,'PLAN_SOURCE_BOUND_4MB');end if;
  v_hash:=lower(rawtohex(sys.dbms_crypto.hash(v_raw,sys.dbms_crypto.hash_sh256)));
  begin select *into v_saved from RRL_PLANNER_APPLY_RESULT where PLAN_ID=p_plan;
   if v_saved.SOURCE_HASH!=v_hash or v_saved.SHIPMENT_DATE!=p_day or nvl(v_saved.DOCK,'~')!=nvl(p_dock,'~')or v_saved.ACTOR!=p_actor then raise_application_error(-20886,'PLAN_APPLY_PAYLOAD_CONFLICT');end if;
   v_doc:=json_object_t.parse(v_saved.RESULT_JSON);v_wares:=v_doc.get_array('warehouse_ids');
   for i in 0..v_wares.get_size-1 loop RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,v_wares.get_number(i));end loop;
   p_result:=v_saved.RESULT_JSON;return;
  exception when no_data_found then null;end;
  if v_applied is not null then raise_application_error(-20886,'PLAN_LEGACY_APPLY_RECONCILIATION_REQUIRED');end if;
  v_doc:=json_object_t.parse(v_raw);v_routes:=v_doc.get_array('routes');
  if v_routes is null or v_routes.get_size not between 1 and 100 then raise_application_error(-20886,'PLAN_ROUTE_BOUND_1_100');end if;
  for i in 0..v_routes.get_size-1 loop
   v_route:=treat(v_routes.get(i)as json_object_t);v_vehicle_ids(i):=v_route.get_number('vehicle_id');v_key:=to_char(v_vehicle_ids(i),'TM9');
   if v_vehicle_ids(i)is null or v_vehicle_ids(i)<=0 or v_seen_vehicle.has(v_key)then raise_application_error(-20886,'PLAN_DISTINCT_CURRENT_VEHICLES_REQUIRED');end if;
   v_seen_vehicle.put(v_key,true);v_vehicles.append(v_vehicle_ids(i));v_stops:=v_route.get_array('stops');
   if v_stops is null or v_stops.get_size not between 1 and 200 then raise_application_error(-20886,'PLAN_ROUTE_ST_BOUND_1_200');end if;
   for j in 0..v_stops.get_size-1 loop
    v_number:=v_stops.get_string(j);
    if v_number is null or length(v_number)>100 or v_seen_st.has(v_number)then raise_application_error(-20886,'PLAN_DUPLICATE_OR_INVALID_ST');end if;
    v_seen_st.put(v_number,true);v_all.append(v_number);
   end loop;
  end loop;
  if v_all.get_size>2000 then raise_application_error(-20886,'PLAN_ST_BOUND_2000');end if;
  v_all_text:=v_all.to_clob;v_vehicle_text:=v_vehicles.to_clob;
  for item in(select ID from json_table(v_vehicle_text,'$[*]'columns(ID number path '$'))order by ID)loop lock_vehicle(item.ID);end loop;
  for item in(select ID,ST_NUMBER,WARE_ID from RRL_SBORKA_PALLETS where ST_NUMBER in
   (select ST_NUMBER from json_table(v_all_text,'$[*]'columns(ST_NUMBER varchar2(100)path '$')))order by ID fetch first 5001 rows only)loop
   v_row_count:=v_row_count+1;v_rows.append(item.ID);if v_row_count>5000 then raise_application_error(-20886,'PLAN_ACTUAL_ROWS_BOUND_5000');end if;
   -- Source discovery/recheck before creating TT; actual row locking happens below after new TT.
   select TRANSTASK_ID,CONDITION into v_current,v_state from RRL_SBORKA_PALLETS where ID=item.ID;
   if nvl(v_current,0)!=0 or v_state=2 then raise_application_error(-20886,'PLAN_ST_ALREADY_ASSIGNED_OR_SHIPPED');end if;
   RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,item.WARE_ID);v_found.put(item.ST_NUMBER,true);
   v_key:=to_char(item.WARE_ID,'TM9');if not v_seen_ware.has(v_key)then v_seen_ware.put(v_key,true);v_wares.append(item.WARE_ID);end if;
  end loop;
  v_found_keys:=v_found.get_keys;
  if v_found_keys.count!=v_all.get_size then raise_application_error(-20886,'PLAN_CURRENT_ST_SET_CHANGED');end if;
  for i in 0..v_routes.get_size-1 loop
   v_route:=treat(v_routes.get(i)as json_object_t);v_stops:=v_route.get_array('stops');
   select *into v_vehicle from RRL_TR_VEHICLE where ID=v_vehicle_ids(i);
   v_declared_num:=v_route.get_string('vehicle_num');
   if v_declared_num!=v_vehicle.NUM or v_declared_num is null then raise_application_error(-20886,'PLAN_VEHICLE_ID_PLATE_CONFLICT');end if;
   RRL_TRANSPORT_PLAN_RULES.check_vehicle(v_vehicle.ID,v_stops.to_clob,1,v_check);
   v_trips(i):=RRL_TRASPORT_TASK_ADD(v_vehicle.TR_TYPE,p_day,p_actor);
   update RRL_TRANSPORT_TASK set TRANSPORT=v_vehicle.NUM,DOCK=p_dock,USER_ID=p_actor where ID=v_trips(i);
   lock_trip(v_trips(i),v_vehicle.NUM);v_created.append(v_trips(i));
  end loop;
  v_row_text:=v_rows.to_clob;
  for item in(select ID from json_table(v_row_text,'$[*]'columns(ID number path '$'))order by ID)loop
   select TRANSTASK_ID,CONDITION,WARE_ID into v_current,v_state,v_actual_ware from RRL_SBORKA_PALLETS where ID=item.ID for update;
   RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,v_actual_ware);
   if nvl(v_current,0)!=0 or v_state=2 then raise_application_error(-20886,'PLAN_ST_CHANGED_DURING_APPLY');end if;
  end loop;
  for i in 0..v_routes.get_size-1 loop
   v_route:=treat(v_routes.get(i)as json_object_t);v_stops:=v_route.get_array('stops');
   RRL_TRANSPORT_PLAN_RULES.check_vehicle(v_vehicle_ids(i),v_stops.to_clob,1,v_check);write_members(v_trips(i),v_stops);
   for j in 0..v_stops.get_size-1 loop v_number:=v_stops.get_string(j);update RRL_SBORKA_PALLETS set ORD=j+1 where ST_NUMBER=v_number and TRANSTASK_ID=v_trips(i);end loop;
  end loop;
  select count(*)into v_current from RRL_SBORKA_PALLETS where ST_NUMBER in
   (select ST_NUMBER from json_table(v_all_text,'$[*]'columns(ST_NUMBER varchar2(100)path '$')));
  if v_current!=v_row_count then raise_application_error(-20886,'PLAN_SOURCE_ROWS_CHANGED_RETRY');end if;
  v_result.put('source_member_ids',v_rows);
  v_result.put('plan_id',p_plan);v_result.put('tasks_created',v_routes.get_size);v_result.put('created_task_ids',v_created);v_result.put('warehouse_ids',v_wares);
  v_result.put('validation_scope','DECLARED_CAPACITY_TYPE_HYDRO');v_result.put('physical_load_admission',false);
  v_result.put('stock_changed',false);v_result.put('driver_inferred_from_vehicle',false);v_result.put('application_status','APPLIED');p_result:=v_result.to_clob;
  g_plan:=p_plan;g_tx:=dbms_transaction.local_transaction_id(true);
  insert into RRL_PLANNER_APPLY_RESULT(PLAN_ID,SOURCE_HASH,SHIPMENT_DATE,DOCK,ACTOR,RESULT_JSON)values(p_plan,v_hash,p_day,p_dock,p_actor,p_result);
  update RRL_PLANNER_PLANS set APPLIED_AT=sysdate,STATUS='APPLIED'where ID=p_plan;g_plan:=null;g_tx:=null;
 exception when others then g_plan:=null;g_tx:=null;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_TRANSPORT_PLAN_RULES as

 procedure assert_actor(p_actor varchar2,p_ware number)is n number;begin

  select count(*)into n from RRL_WARES where ID=p_ware;

  if n!=1 then raise_application_error(-20886,'PLAN_CURRENT_WARE_REQUIRED');end if;

  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0

   and(u.WARE_ID=p_ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,'transport_dispatch_edit')=1;

  if n!=1 or p_ware is null then raise_application_error(-20882,'PLAN_CURRENT_WARE_ACTOR_REQUIRED');end if;

 end;

 procedure prepared_floor_counts(p_sts clob,p_counts out clob,p_unknown out number)is

  numbers json_array_t:=json_array_t.parse(p_sts);wire_counts json_array_t:=json_array_t();entry_value json_object_t;

  query_value varchar2(32767);cursor_no integer;query_result integer;rows_cursor sys_refcursor;

  uid_value varchar2(64);case_count number;type_count number;type_id number;active_value number;planned_count number;planned_type number;planned_active number;row_count number:=0;

  type count_map is table of number index by varchar2(100);counts count_map;key_value varchar2(100);st_value varchar2(100);el json_element_t;

 begin

  if numbers.get_size<1 or numbers.get_size>200 then raise_application_error(-20886,'PLAN_TARE_ST_BOUND_200');end if;

  query_value:='select /* PLAN_TARE_RECIPIENT1208 */ p.PALLET_UID,count(distinct c.CASE_PICK_TASK_ID),count(distinct c.PALLET_TYPE_ID),min(c.PALLET_TYPE_ID),min(t.ACTIVE),count(distinct rt.PALLET_TYPE_ID),min(rt.PALLET_TYPE_ID),min(pt.ACTIVE) from RRL_SBORKA_PALLETS p left join RRL_CASE_PICK_TASK c on c.LEGACY_SBORKA_PALLET_ID=p.ID and c.STATUS!=''CANCELLED'' left join RRL_PALLET_TYPE t on t.PALLET_TYPE_ID=c.PALLET_TYPE_ID left join RRL_CUSTOMER_ORDER_FULFILLMENT ff on ff.LEGACY_SBORKA_PALLET_ID=p.ID left join RRL_CUSTOMER_ORDER co on co.CUSTOMER_ORDER_ID=ff.CUSTOMER_ORDER_ID left join RRL_CUSTOMER_PALLET_TYPE_RULE rt on rt.CUSTOMER_PALLET_TYPE_RULE_ID=RRL_RECIPIENT_PALLET_POLICY.rule_id(co.CUSTOMER_ID,co.CUSTOMER_STORE_MAP_ID) left join RRL_PALLET_TYPE pt on pt.PALLET_TYPE_ID=rt.PALLET_TYPE_ID where p.ST_NUMBER in (';

  for i in 0..numbers.get_size-1 loop

   if i>0 then query_value:=query_value||',';end if;query_value:=query_value||':st'||to_char(i,'FM999');

  end loop;

  query_value:=query_value||') and not exists(select 1 from RRL_TT_HU_LOAD_ST m join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=m.LOAD_OPERATION_ID where m.SBORKA_PALLET_ID=p.ID and m.ACTIVE_FLAG=1 and l.STATUS=''LOADED'') group by p.PALLET_UID fetch first 5001 rows only';

  cursor_no:=dbms_sql.open_cursor;dbms_sql.parse(cursor_no,query_value,dbms_sql.native);

  for i in 0..numbers.get_size-1 loop

   el:=numbers.get(i);

   if not el.is_string then raise_application_error(-20886,'PLAN_TARE_ST_NUMBER_REQUIRED');end if;

   st_value:=numbers.get_string(i);

   if st_value is null or length(st_value)>100 then raise_application_error(-20886,'PLAN_TARE_ST_NUMBER_REQUIRED');end if;

   dbms_sql.bind_variable(cursor_no,':st'||to_char(i,'FM999'),st_value);

  end loop;

  query_result:=dbms_sql.execute(cursor_no);rows_cursor:=dbms_sql.to_refcursor(cursor_no);cursor_no:=null;p_unknown:=0;

  loop

   fetch rows_cursor into uid_value,case_count,type_count,type_id,active_value,planned_count,planned_type,planned_active;exit when rows_cursor%notfound;

   row_count:=row_count+1;

   if row_count>5000 then raise_application_error(-20886,'PLAN_TARE_PLACES_BOUND_5000');end if;

   if case_count=0 and planned_count=1 and planned_active=1 then type_id:=planned_type;type_count:=1;active_value:=1;case_count:=1;end if;

   if case_count=1 and type_count=1 and active_value=1 then

    key_value:=to_char(type_id,'TM9');

    if counts.exists(key_value)then counts(key_value):=counts(key_value)+1;else counts(key_value):=1;end if;

   else p_unknown:=p_unknown+1;end if;

  end loop;close rows_cursor;

  key_value:=counts.first;

  while key_value is not null loop

   entry_value:=json_object_t();entry_value.put('pallet_type_id',to_number(key_value));entry_value.put('places',counts(key_value));wire_counts.append(entry_value);

   key_value:=counts.next(key_value);

  end loop;p_counts:=wire_counts.to_clob;

 exception when others then

  if cursor_no is not null then if dbms_sql.is_open(cursor_no)then dbms_sql.close_cursor(cursor_no);end if;end if;

  if rows_cursor%isopen then close rows_cursor;end if;raise;

 end;

 procedure check_vehicle(p_vehicle_id number,p_sts clob,p_complete number,p_result out clob)is

  v RRL_TR_VEHICLE%rowtype;places number;weight number;unknown_weight number;strict_windows number;bad number;actual_places number;actual_weight number;actual_bad number;

  access_wire clob;access_result json_object_t;floor_value json_object_t;loaded_floor json_object_t;profile_value json_object_t;configured json_object_t;floor_counts clob;unknown_places number;

  result json_object_t:=json_object_t();warn json_array_t:=json_array_t();

 begin

  if p_vehicle_id is null then

   if p_complete=1 then raise_application_error(-20886,'PLAN_CURRENT_VEHICLE_REQUIRED');end if;

  result.put('validation_status','DRAFT_VEHICLE_REQUIRED');warn.append('Машина не назначена; вместимость и сроки не подтверждены');

   result.put('warnings',warn);p_result:=result.to_clob;return;

  end if;

  select *into v from RRL_TR_VEHICLE where ID=p_vehicle_id;

  if nvl(v.BLOCKED,0)!=0 or nvl(v.DELETED,0)!=0 or nvl(v.PALLETS,0)<=0 or nvl(v.MAX_WEIGHT_KG,0)<=0 or v.TR_TYPE is null then raise_application_error(-20886,'PLAN_ACTIVE_VEHICLE_CAPACITY_REQUIRED');end if;

  select count(distinct p.PALLET_UID),sum(r.ORDER_WEIGHT),

   sum(case when r.ID is null or r.ORDER_WEIGHT is null or r.ORDER_WEIGHT<=0 then 1 else 0 end)

   into places,weight,unknown_weight from RRL_SBORKA_PALLETS p

   left join RRL_SBORKA_PALLET_ROWS r on r.PALLET_UID=p.PALLET_UID

   where p.ST_NUMBER in(select ST_NUMBER from json_table(p_sts,'$[*]'columns(ST_NUMBER varchar2(100)path '$')))

    and not exists(select 1 from RRL_TT_HU_LOAD_ST m join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=m.LOAD_OPERATION_ID where m.SBORKA_PALLET_ID=p.ID and m.ACTIVE_FLAG=1 and l.STATUS='LOADED');

   select count(*),nvl(sum(l.GROSS_WEIGHT_KG),0),

    nvl(sum(case when l.GROSS_WEIGHT_KG is null or l.GROSS_WEIGHT_KG<=0 or o.STATE!='APPLIED' or o.STATE is null then 1 else 0 end),0)

    into actual_places,actual_weight,actual_bad from RRL_TT_HU_LOAD_FACT l

    left join RRL_STOCK_OPERATION o on o.OPERATION_ID=l.LOAD_OPERATION_ID

    where l.STATUS='LOADED'and l.LOAD_OPERATION_ID in(

     select m.LOAD_OPERATION_ID from RRL_TT_HU_LOAD_ST m join RRL_SBORKA_PALLETS p on p.ID=m.SBORKA_PALLET_ID

     where m.ACTIVE_FLAG=1 and p.ST_NUMBER in(select ST_NUMBER from json_table(p_sts,'$[*]'columns(ST_NUMBER varchar2(100)path '$')))

    );

   if actual_bad>0 then raise_application_error(-20886,'PLAN_LOADED_PHYSICAL_CAPACITY_PROOF_REQUIRED');end if;

   places:=nvl(places,0)+actual_places;weight:=nvl(weight,0)+actual_weight;unknown_weight:=nvl(unknown_weight,0);

   if weight>v.MAX_WEIGHT_KG then raise_application_error(-20886,'PLAN_WEIGHT_CAPACITY_EXCEEDED');end if;

  profile_value:=json_object_t.parse(RRL_VEHICLE_PROFILE_API.describe_profile(p_vehicle_id));

  floor_counts:='[]';unknown_places:=0;

  if profile_value.has('profile')then

   configured:=profile_value.get_object('profile');

   if configured.has('floor_capacity')then prepared_floor_counts(p_sts,floor_counts,unknown_places);

    loaded_floor:=json_object_t.parse(RRL_STOCK_LOAD_FLOOR.planning_counts(p_vehicle_id,p_sts,floor_counts,unknown_places));

    floor_counts:=loaded_floor.get_array('counts').to_clob;unknown_places:=loaded_floor.get_number('unconfirmed_places');end if;

  end if;

  floor_value:=json_object_t.parse(RRL_VEHICLE_PROFILE_API.check_floor_capacity(p_vehicle_id,floor_counts,unknown_places));

  if floor_value.get_string('status')='INCOMPATIBLE'then

   if p_complete=1 then raise_application_error(-20886,'PLAN_TARE_VARIANT_CAPACITY_EXCEEDED');end if;

   warn.append('Состав мест не соответствует ни одному нормативному сочетанию тары машины');

  elsif floor_value.get_string('status')not in('COMPATIBLE','NOT_CONFIGURED')then

   if p_complete=1 then raise_application_error(-20886,'PLAN_TARE_CURRENT_PLACE_TYPE_REQUIRED');end if;

   warn.append('Типы верхних мест или нормативный профиль тары требуют подтверждения');

  end if;

  if floor_value.get_string('status')='NOT_CONFIGURED'and places>v.PALLETS then raise_application_error(-20886,'PLAN_PALLET_CAPACITY_EXCEEDED');end if;

  if unknown_weight>0 then

   if p_complete=1 then raise_application_error(-20886,'PLAN_DECLARED_WEIGHT_REQUIRED');end if;

   warn.append('Плановая масса части товара отсутствует; окончательная готовность не подтверждена');

  elsif weight>v.MAX_WEIGHT_KG then raise_application_error(-20886,'PLAN_WEIGHT_CAPACITY_EXCEEDED');end if;

  select count(*)into bad from RRL_SBORKA_PALLETS p join RRL_ADDR a on a.ADDR=p.ADDR

   where p.ST_NUMBER in(select ST_NUMBER from json_table(p_sts,'$[*]'columns(ST_NUMBER varchar2(100)path '$')))

   and((a.TRANSPORT_TYPE is not null and trim(a.TRANSPORT_TYPE)not in('0',trim(v.TR_TYPE)))

    or(nvl(a.STOL,0)>0 and nvl(v.GIDROBORT,0)!=1));

  if bad>0 then raise_application_error(-20886,'PLAN_ADDRESS_VEHICLE_TYPE_OR_HYDRO_CONFLICT');end if;

  select count(*)into bad from RRL_SBORKA_PALLETS p join RRL_ADDR a on a.ADDR=p.ADDR

   where p.ST_NUMBER in(select ST_NUMBER from json_table(p_sts,'$[*]'columns(ST_NUMBER varchar2(100)path '$')))

   and a.MAX_VEHICLE_TONS is not null and v.MAX_WEIGHT_KG>1000*a.MAX_VEHICLE_TONS;

  if bad>0 then raise_application_error(-20886,'PLAN_ADDRESS_VEHICLE_LIMIT_EXCEEDED');end if;

  select count(*)into strict_windows from RRL_SBORKA_PALLETS p join RRL_ADDR a on a.ADDR=p.ADDR

   where p.ST_NUMBER in(select ST_NUMBER from json_table(p_sts,'$[*]'columns(ST_NUMBER varchar2(100)path '$')))and nvl(a.TW_STRICT,0)=1;

  if strict_windows>0 then

   if p_complete=1 then raise_application_error(-20886,'PLAN_STRICT_TIME_SCHEDULE_REQUIRED');end if;

   warn.append('Жёсткие временные окна требуют подтверждённого расписания');

  end if;

  RRL_STORE_ACCESS_RULES.check_sts(p_vehicle_id,p_sts,p_complete,access_wire);
  access_result:=json_object_t.parse(access_wire);result.put('store_access',access_result);
  if not access_result.get_boolean('complete')then warn.append('Для ограничений подъезда требуется актуальный профиль наружных габаритов автомобиля');end if;
  result.put('floor_capacity',floor_value);

  result.put('validation_status',case when warn.get_size=0 then 'CAPACITY_TYPE_CHECKED'else'DRAFT_INCOMPLETE'end);

  result.put('frozen_loaded_places',actual_places);result.put('frozen_loaded_weight_kg',to_char(actual_weight,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''));result.put('declared_places',places);result.put('declared_weight_kg',to_char(weight,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''));

  result.put('warnings',warn);result.put('physical_stock_changed',false);result.put('physical_load_admission',false);

  p_result:=result.to_clob;

 end;

end;
/


CREATE OR REPLACE package body RRL_TT_MEMBERSHIP_CTX_API as
 procedure begin_member(p_id number,p_trip number) is
 begin
  if sys_context('RRL_TT_MEMBERSHIP_CTX','ST_ID') is not null then raise_application_error(-20886,'NESTED_TRIP_MEMBERSHIP_WRITE');end if;
  dbms_session.set_context('RRL_TT_MEMBERSHIP_CTX','ST_ID',to_char(p_id,'TM9'));
  dbms_session.set_context('RRL_TT_MEMBERSHIP_CTX','TRIP_ID',to_char(nvl(p_trip,0),'TM9'));
  dbms_session.set_context('RRL_TT_MEMBERSHIP_CTX','TX_ID',dbms_transaction.local_transaction_id(false));
 end;
 procedure end_member is
 begin
  dbms_session.set_context('RRL_TT_MEMBERSHIP_CTX','ST_ID',null);
  dbms_session.set_context('RRL_TT_MEMBERSHIP_CTX','TRIP_ID',null);
  dbms_session.set_context('RRL_TT_MEMBERSHIP_CTX','TX_ID',null);
 end;
end;
/


CREATE OR REPLACE package body RRL_TT_OPERATION_PLAN_API as
 procedure store_fact(p_operation number,p_start date,p_finish date,p_note varchar2)is
 begin
  if p_start is not null and p_finish is not null and p_finish<p_start then raise_application_error(-20886,'OP_FACT_FINISH_BEFORE_START');end if;
  update RRL_TT_OPERATIONS set FACT_START=p_start,FACT_END=p_finish,NOTE=p_note where ID=p_operation;
 end;
 procedure assert_driver(p_driver number,p_actor varchar2)is n number;
 begin
  select count(*)into n from RRL_TRANSPORT_DRIVER_USER b join RUSERS u on u.ID=b.USER_ID
   join RRL_TR_VODITEL d on d.ID=b.DRIVER_ID
   where b.DRIVER_ID=p_driver and b.USER_ID=p_actor and b.ACTIVE=1 and nvl(u.DELETED,0)=0 and nvl(d.DELETED,0)=0;
  if n!=1 then raise_application_error(-20882,'DRIVER_CURRENT_ACCOUNT_BINDING_REQUIRED');end if;
 end;
 procedure actor_allowed(p_actor varchar2)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'transport_dispatch_edit')=1;
  if n!=1 then raise_application_error(-20882,'OP_PLAN_ACTIVE_DISPATCHER_REQUIRED');end if;
 end;
 procedure generate(p_trip number,p_actor varchar2,p_result out clob)is
  w RRL_TRANSPORT_TASK%rowtype;before_plate varchar2(50);v_vehicle number;v_locked number;
  v_route_drive number;v_route_back number;v_route_basis varchar2(50);
  v_count number:=0;v_global number;v_places number;v_time date;v_finish date;v_id number;
  chain json_array_t:=json_array_t.parse('["DOCK_ASSIGN","WAIT_LOAD","LOADING","CLOSE_GATE","DOCUMENTS","DEPART","DRIVE","UNLOAD","LOAD_RETURNS","DRIVE_BACK","RETURN_HANDOVER","CLEAN_RETURNS"]');
  chain_text clob;norms_text clob;norms json_array_t;norm_map json_object_t:=json_object_t();norm json_object_t;
  v_code varchar2(50);v_note RRL_TT_OPERATIONS.NOTE%type;v_duration number;v_per number;v_ordinal number;v_rows number;v_checks clob;
  sts json_array_t:=json_array_t();seen json_object_t:=json_object_t();result json_array_t:=json_array_t();item json_object_t;
 begin
  savepoint RRL_OP_PLAN141;actor_allowed(p_actor);
  select TRANSPORT into before_plate from RRL_TRANSPORT_TASK where ID=p_trip;
  if before_plate is not null then
   begin select ID into v_vehicle from RRL_TR_VEHICLE where NUM=before_plate;
    select ID into v_locked from RRL_TR_VEHICLE where ID=v_vehicle for update;
   exception when no_data_found then raise_application_error(-20886,'OP_PLAN_CURRENT_VEHICLE_REQUIRED');end;
  end if;
  select *into w from RRL_TRANSPORT_TASK where ID=p_trip for update;
  if nvl(w.TRANSPORT,'~')!=nvl(before_plate,'~')then raise_application_error(-20886,'OP_PLAN_VEHICLE_CHANGED_RETRY');end if;
  if nvl(w.DELETED,0)!=0 or w.CONDITION='Отгружен'or nvl(w.PAY_ORDER_ID,0)>0 then raise_application_error(-20886,'OP_PLAN_ACTIVE_UNBILLED_TRIP_REQUIRED');end if;
  select count(*)into v_count from RRL_TT_HU_LOAD_FACT where TT_ID=p_trip and STATUS in('LOADED','DEPARTED');
  if v_count>0 then raise_application_error(-20886,'OP_PLAN_PHYSICAL_TRIP_FROZEN');end if;
  v_count:=0;
  for source in(select ID,ST_NUMBER,WARE_ID from RRL_SBORKA_PALLETS where TRANSTASK_ID=p_trip order by ID fetch first 201 rows only)loop
   v_count:=v_count+1;if v_count>200 then raise_application_error(-20886,'OP_PLAN_SOURCE_BOUND_200');end if;
   if source.ST_NUMBER is null then raise_application_error(-20886,'OP_PLAN_SOURCE_ID_REQUIRED');end if;
   RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,source.WARE_ID);
   if not seen.has(source.ST_NUMBER)then seen.put(source.ST_NUMBER,true);sts.append(source.ST_NUMBER);end if;
  end loop;
  if v_count=0 and nvl(w.USER_ID,'~')!=p_actor then
   select count(*)into v_global from RUSERS where ID=p_actor and upper(trim(USER_GROUP))='GLOBAL_ADMIN';
   if v_global!=1 then raise_application_error(-20882,'OP_PLAN_EMPTY_TRIP_OWNER_REQUIRED');end if;
  end if;
  RRL_TRANSPORT_PLAN_RULES.check_vehicle(v_vehicle,sts.to_clob,0,v_checks);
  if w.SHIPMENT_DATE is null or w.SHIPMENT_TIME is null then raise_application_error(-20886,'OP_PLAN_EXPLICIT_TRIP_DATE_TIME_REQUIRED');end if;
  v_time:=trunc(w.SHIPMENT_DATE)+(w.SHIPMENT_TIME-trunc(w.SHIPMENT_TIME));
  select count(distinct PALLET_UID)into v_places from RRL_SBORKA_PALLETS where TRANSTASK_ID=p_trip;
  for old in(select ID,FACT_START,FACT_END from RRL_TT_OPERATIONS where TT_ID=p_trip order by ID for update)loop
   if old.FACT_START is not null or old.FACT_END is not null then raise_application_error(-20886,'OP_PLAN_EXECUTION_HISTORY_FROZEN');end if;
  end loop;
  chain_text:=chain.to_clob;
  select count(*)into v_count from RRL_TT_OPERATIONS where TT_ID=p_trip and OPERATION_CODE not in(select CODE from json_table(chain_text,'$[*]'columns(CODE varchar2(50)path '$')));
  if v_count>0 then raise_application_error(-20886,'OP_PLAN_CUSTOM_CHAIN_REVIEW_REQUIRED');end if;
  select count(*)into v_count from(select OPERATION_CODE from RRL_TT_OPERATIONS where TT_ID=p_trip group by OPERATION_CODE having count(*)>1);
  if v_count>0 then raise_application_error(-20886,'OP_PLAN_DUPLICATE_CHAIN_REVIEW_REQUIRED');end if;
  -- One statement snapshot for all configured norms. Explicit configured zero is preserved.
  select json_arrayagg(json_object('code' value OPERATION_CODE,'duration' value DURATION_MIN,'per' value PER_UNIT)order by OPERATION_CODE returning clob)
   into norms_text from RRL_TRANSPORT_NORMS where OPERATION_CODE in(select CODE from json_table(chain_text,'$[*]'columns(CODE varchar2(50)path '$')));
  if norms_text is null then raise_application_error(-20886,'OP_PLAN_NORMS_REQUIRED');end if;
  norms:=json_array_t.parse(norms_text);
  for i in 0..norms.get_size-1 loop norm:=treat(norms.get(i)as json_object_t);
   if norm_map.has(norm.get_string('code'))then raise_application_error(-20886,'OP_PLAN_NORM_DUPLICATE');end if;
   norm_map.put(norm.get_string('code'),norm);
  end loop;
  RRL_TT_ROUTE_SOURCE.durations(p_trip,p_actor,v_route_drive,v_route_back,v_route_basis);
  for i in 0..chain.get_size-1 loop
   v_code:=chain.get_string(i);v_ordinal:=i+1;
   if not norm_map.has(v_code)then raise_application_error(-20886,'OP_PLAN_NORM_MISSING:'||v_code);end if;
   norm:=norm_map.get_object(v_code);v_duration:=norm.get_number('duration');v_per:=norm.get_number('per');
   if v_duration is null or v_duration<0 or v_per is null or v_per not in(0,1)then raise_application_error(-20886,'OP_PLAN_NORM_INVALID:'||v_code);end if;
   if v_per=1 then v_duration:=v_duration*v_places;end if;
   if v_code='DRIVE'and v_route_drive is not null then v_duration:=v_route_drive;end if;
   if v_code='DRIVE_BACK'and v_route_back is not null then v_duration:=v_route_back;end if;
   v_finish:=v_time+round(v_duration*60)/86400;
   begin select ID into v_id from RRL_TT_OPERATIONS where TT_ID=p_trip and OPERATION_CODE=v_code;
    update RRL_TT_OPERATIONS set ORD=v_ordinal,DURATION_MIN=v_duration,PLAN_START=v_time,PLAN_END=v_finish where ID=v_id;
   exception when no_data_found then
    select SEQ_TT_OPERATIONS.nextval into v_id from dual;
    insert into RRL_TT_OPERATIONS(ID,TT_ID,OPERATION_CODE,ORD,DURATION_MIN,PLAN_START,PLAN_END)values(v_id,p_trip,v_code,v_ordinal,v_duration,v_time,v_finish);
   end;
   item:=json_object_t();item.put('op_id',v_id);item.put('tt_id',p_trip);item.put('operation_code',v_code);item.put('ord',v_ordinal);
   item.put('duration_min',v_duration);item.put('plan_start',to_char(v_time,'YYYY-MM-DD HH24:MI'));item.put('plan_end',to_char(v_finish,'YYYY-MM-DD HH24:MI'));
   item.put_null('fact_start');item.put_null('fact_end');item.put_null('delta_min');
   select NOTE into v_note from RRL_TT_OPERATIONS where ID=v_id;item.put('note',v_note);
   if v_code in('DRIVE','DRIVE_BACK')then item.put('planning_basis',v_route_basis);else item.put('planning_basis','CONFIGURED_NORMS_ESTIMATE');end if;item.put('time_window_admission',false);
   result.append(item);v_time:=v_finish;
  end loop;
  p_result:=result.to_clob;
 exception when others then rollback to RRL_OP_PLAN141;raise;
 end;
 procedure write_fact(p_operation number,p_actor varchar2,p_body clob,p_result out clob)is
  b json_object_t:=json_object_t.parse(p_body);before_trip number;w RRL_TRANSPORT_TASK%rowtype;o RRL_TT_OPERATIONS%rowtype;
  v_start date;v_finish date;v_note RRL_TT_OPERATIONS.NOTE%type;n number:=0;v_global number;result json_object_t:=json_object_t();
 begin
  savepoint RRL_OP_FACT141;actor_allowed(p_actor);
  select TT_ID into before_trip from RRL_TT_OPERATIONS where ID=p_operation;
  select *into w from RRL_TRANSPORT_TASK where ID=before_trip for update;
  if nvl(w.DELETED,0)!=0 then raise_application_error(-20886,'OP_FACT_ACTIVE_TRIP_REQUIRED');end if;
  for source in(select ID,WARE_ID from RRL_SBORKA_PALLETS where TRANSTASK_ID=before_trip order by ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20886,'OP_FACT_SOURCE_BOUND_200');end if;
   RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,source.WARE_ID);
  end loop;
  if n=0 and nvl(w.USER_ID,'~')!=p_actor then
   select count(*)into v_global from RUSERS where ID=p_actor and upper(trim(USER_GROUP))='GLOBAL_ADMIN';
   if v_global!=1 then raise_application_error(-20882,'OP_FACT_EMPTY_TRIP_OWNER_REQUIRED');end if;
  end if;
  select *into o from RRL_TT_OPERATIONS where ID=p_operation for update;
  if o.TT_ID!=before_trip then raise_application_error(-20886,'OP_FACT_SOURCE_CHANGED_RETRY');end if;
  v_start:=o.FACT_START;v_finish:=o.FACT_END;v_note:=o.NOTE;
  if b.has('fact_start')then v_start:=to_date(b.get_string('fact_start'),'FXYYYY-MM-DD HH24:MI');end if;
  if b.has('fact_end')then v_finish:=to_date(b.get_string('fact_end'),'FXYYYY-MM-DD HH24:MI');end if;
  if v_start is not null and v_finish is not null and v_finish<v_start then raise_application_error(-20886,'OP_FACT_FINISH_BEFORE_START');end if;
  if b.has('note')then v_note:=b.get_string('note');end if;
  store_fact(p_operation,v_start,v_finish,v_note);
  result.put('op_id',p_operation);result.put('updated',true);p_result:=result.to_clob;
 exception when others then rollback to RRL_OP_FACT141;raise;
 end;
 procedure mark_driver_fact(p_operation number,p_driver number,p_actor varchar2,p_action varchar2,p_result out clob)is
  before_trip number;b_user varchar2(50);b_active number;w RRL_TRANSPORT_TASK%rowtype;o RRL_TT_OPERATIONS%rowtype;
  v_now date:=sysdate;v_start date;v_finish date;changed boolean:=false;result json_object_t:=json_object_t();
 begin
  savepoint RRL_DRIVER_FACT1302;
  if p_action is null or p_action not in('START','DONE')then raise_application_error(-20886,'DRIVER_FACT_ACTION_INVALID');end if;
  assert_driver(p_driver,p_actor);
  select USER_ID,ACTIVE into b_user,b_active from RRL_TRANSPORT_DRIVER_USER where DRIVER_ID=p_driver for update nowait;
  assert_driver(p_driver,p_actor);
  select TT_ID into before_trip from RRL_TT_OPERATIONS where ID=p_operation;
  select *into w from RRL_TRANSPORT_TASK where ID=before_trip for update nowait;
  if w.VODITEL_ID is null or w.VODITEL_ID!=p_driver or nvl(w.DELETED,0)!=0 then raise_application_error(-20882,'DRIVER_TRIP_ASSIGNMENT_REQUIRED');end if;
  if nvl(w.PAY_ORDER_ID,0)>0 then raise_application_error(-20886,'DRIVER_INVOICED_TRIP_FROZEN');end if;
  select *into o from RRL_TT_OPERATIONS where ID=p_operation for update nowait;
  if o.TT_ID!=before_trip then raise_application_error(-20886,'DRIVER_OPERATION_TRIP_CHANGED');end if;
  v_start:=o.FACT_START;v_finish:=o.FACT_END;
  if p_action='START'and v_start is null then
   if v_finish is not null then raise_application_error(-20886,'DRIVER_FACT_STATE_CONFLICT');end if;
   v_start:=v_now;changed:=true;
  elsif p_action='DONE'and v_finish is null then
   if v_start is null then raise_application_error(-20886,'DRIVER_FACT_START_REQUIRED');end if;
   v_finish:=v_now;changed:=true;
  end if;
  assert_driver(p_driver,p_actor);
  if changed then store_fact(p_operation,v_start,v_finish,o.NOTE);end if;
  result.put('op_id',p_operation);result.put('trip_id',before_trip);result.put('driver_id',p_driver);
  if v_finish is not null then result.put('status','done');elsif v_start is not null then result.put('status','in_progress');else result.put('status','pending');end if;
  result.put('fact_start',to_char(v_start,'YYYY-MM-DD HH24:MI:SS'));result.put('fact_end',to_char(v_finish,'YYYY-MM-DD HH24:MI:SS'));
  result.put('changed',changed);result.put('clock_basis','EXISTING_DATABASE_LOCAL_DATE');
  result.put('stock_changed',false);p_result:=result.to_clob;
 exception when others then rollback to RRL_DRIVER_FACT1302;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_TT_ROUTE_API as
 g_operation varchar2(100);g_tx varchar2(100);
 function write_allowed(p_operation varchar2)return number is begin
  if g_operation=p_operation and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure context(p_trip number,p_actor varchar2,p_result out clob)is
  src clob;hash varchar2(64);v_version number;saved RRL_TT_ROUTE_INPUT%rowtype;b json_object_t:=json_object_t();
 begin
  RRL_TT_ROUTE_SOURCE.snapshot(p_trip,p_actor,src,hash);
  select nvl(max(VERSION_NO),0)into v_version from RRL_TT_ROUTE_INPUT where TT_ID=p_trip;
  b.put('trip_id',p_trip);b.put('source_hash',hash);b.put('version',v_version);b.put('source',json_object_t.parse(src));
  b.put('route_status','NO_INPUT');b.put('route_duration_verified',false);b.put('operational_admission',false);
  if v_version>0 then
   select *into saved from RRL_TT_ROUTE_INPUT where TT_ID=p_trip and VERSION_NO=v_version;
   b.put('last_input',json_object_t.parse(saved.RESULT_JSON));
   if saved.SOURCE_HASH=hash then b.put('route_status','CURRENT_DISPATCH_ESTIMATE');else b.put('route_status','SOURCE_CHANGED');end if;
  end if;
  p_result:=b.to_clob;
 end;
 procedure apply_input(p_operation varchar2,p_actor varchar2,p_body clob,p_result out clob)is
  b json_object_t;v_trip number;v_version number;v_req_hash varchar2(64);src clob;hash varchar2(64);
  w RRL_TRANSPORT_TASK%rowtype;saved RRL_TT_ROUTE_INPUT%rowtype;
  v_drive number;v_back number;v_ref nvarchar2(500);v_reason nvarchar2(500);
  v_before varchar2(50);v_vehicle number;v_locked number;n number;v_meta boolean:=false;
  result json_object_t:=json_object_t();ops clob;
 begin
  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_body is null or dbms_lob.getlength(p_body)>4000 then raise_application_error(-20886,'TT_ROUTE_INPUT_BOUND');end if;
  b:=json_object_t.parse(p_body);v_trip:=b.get_number('trip_id');
  RRL_TT_ROUTE_SOURCE.snapshot(v_trip,p_actor,src,hash);
  v_req_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'transport_dispatch_edit');v_meta:=true;savepoint RRL_TT_ROUTE259;
  select TRANSPORT into v_before from RRL_TRANSPORT_TASK where ID=v_trip;
  if v_before is null then raise_application_error(-20886,'TT_ROUTE_VEHICLE_REQUIRED');end if;
  select ID into v_vehicle from RRL_TR_VEHICLE where NUM=v_before;
  select ID into v_locked from RRL_TR_VEHICLE where ID=v_vehicle for update;
  select *into w from RRL_TRANSPORT_TASK where ID=v_trip for update;
  if nvl(w.TRANSPORT,'~')!=nvl(v_before,'~')then raise_application_error(-20886,'TT_ROUTE_VEHICLE_CHANGED_RETRY');end if;
  RRL_TT_ROUTE_SOURCE.snapshot(v_trip,p_actor,src,hash);
  begin
   select *into saved from RRL_TT_ROUTE_INPUT where OPERATION_ID=p_operation;
   if saved.ACTOR!=p_actor or saved.TT_ID!=v_trip or saved.REQUEST_HASH!=v_req_hash then raise_application_error(-20886,'TT_ROUTE_OPERATION_PAYLOAD_CONFLICT');end if;
   p_result:=saved.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;
  exception when no_data_found then null;end;
  select nvl(max(VERSION_NO),0)into v_version from RRL_TT_ROUTE_INPUT where TT_ID=v_trip;
  if b.get_number('expected_version')is null or b.get_number('expected_version')!=v_version or b.get_string('source_hash')is null or b.get_string('source_hash')!=hash then raise_application_error(-20886,'TT_ROUTE_SOURCE_CHANGED');end if;
  if nvl(w.DELETED,0)!=0 or w.CONDITION is null or w.CONDITION!='Спланирован'or nvl(w.PAY_ORDER_ID,0)>0 then raise_application_error(-20886,'TT_ROUTE_PLANNED_UNBILLED_REQUIRED');end if;
  v_drive:=b.get_number('drive_min');v_back:=b.get_number('drive_back_min');v_ref:=b.get_string('source_reference');v_reason:=b.get_string('reason');
  if v_drive is null or v_back is null or v_drive<=0 or v_drive>1440 or v_back<=0 or v_back>1440 or round(v_drive,2)!=v_drive or round(v_back,2)!=v_back or v_ref is null or length(trim(v_ref))<8 or v_reason is null or length(trim(v_reason))<8 then raise_application_error(-20886,'TT_ROUTE_EXPLICIT_ESTIMATE_REQUIRED');end if;
  select count(*)into n from RRL_TT_HU_LOAD_FACT where TT_ID=v_trip and STATUS in('LOADED','DEPARTED');
  if n>0 then raise_application_error(-20886,'TT_ROUTE_PHYSICAL_EXECUTION_FROZEN');end if;
  select count(*)into n from RRL_TT_OPERATIONS where TT_ID=v_trip and(FACT_START is not null or FACT_END is not null);
  if n>0 then raise_application_error(-20886,'TT_ROUTE_OPERATION_EXECUTION_FROZEN');end if;
  result.put('trip_id',v_trip);result.put('version',v_version+1);result.put('operation_id',p_operation);result.put('source_hash',hash);
  result.put('plan_source',json_object_t.parse(src));result.put('drive_min',v_drive);result.put('drive_back_min',v_back);
  result.put('source_reference',v_ref);result.put('reason',v_reason);result.put('actor',p_actor);
  result.put('basis','MANUAL_DISPATCH_ESTIMATE');result.put('route_duration_verified',false);result.put('operational_admission',false);
  p_result:=result.to_clob;g_operation:=p_operation;g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_TT_ROUTE_INPUT(TT_ID,VERSION_NO,OPERATION_ID,ACTOR,REQUEST_HASH,SOURCE_HASH,DRIVE_MIN,DRIVE_BACK_MIN,SOURCE_REFERENCE,REASON,RESULT_JSON)
   values(v_trip,v_version+1,p_operation,p_actor,v_req_hash,hash,v_drive,v_back,v_ref,v_reason,p_result);
  RRL_TT_OPERATION_PLAN_API.generate(v_trip,p_actor,ops);
  g_operation:=null;g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
 exception when others then
  if v_meta then rollback to RRL_TT_ROUTE259;end if;g_operation:=null;g_tx:=null;
  if v_meta then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_TT_ROUTE_SCHEDULE as
 procedure material(p_source clob,p_result out clob)is
  b json_object_t:=json_object_t.parse(p_source);r json_object_t:=json_object_t();origins json_array_t;
  stops json_array_t:=json_array_t();pairs json_array_t:=json_array_t();legs json_array_t:=json_array_t();o json_object_t;
  depot varchar2(255);prev varchar2(255);n number:=0;wire clob;last_ord number;valid boolean:=true;
 begin
  origins:=b.get_array('warehouse_origins');
  if origins is not null and origins.get_size=1 then
   o:=treat(origins.get(0)as json_object_t);
   if o.get_boolean('configured')then depot:=o.get_string('depot_address');end if;
  end if;
  prev:=depot;
  for s in(select address,min(route_ord)ord,count(*)cnt,count(route_ord)ord_count,min(route_ord)lo,max(route_ord)hi
   from json_table(p_source,'$.members[*]'columns(address varchar2(255)path '$.address',route_ord number path '$.route_ordinal'))
   group by address order by min(route_ord),address)loop
   n:=n+1;if n>200 then raise_application_error(-20886,'TT_ROUTE_STOP_BOUND_200');end if;
   if s.address is null or s.ord_count!=s.cnt or s.lo<0 or s.lo!=trunc(s.lo)or last_ord=s.ord then valid:=false;end if;
   last_ord:=s.ord;stops.append(s.address);o:=json_object_t();o.put('from_address',prev);o.put('to_address',s.address);pairs.append(o);prev:=s.address;
  end loop;
  o:=json_object_t();o.put('from_address',prev);o.put('to_address',depot);pairs.append(o);wire:=pairs.to_clob;
  for leg in(select /*+ leading(p m) use_nl(m) index(m PK_DIST_MATRIX) */ /* NI081_ROUTE_LEGS */ p.pos,p.a,p.b,m.DURATION_MIN,m.DURATION_BASIS,m.SOURCE,m.UPDATED_AT,
   case when m.UPDATED_AT>=sysdate-1 then 1 else 0 end fresh
   from json_table(wire,'$[*]'columns(pos for ordinality,a varchar2(255)path '$.from_address',b varchar2(255)path '$.to_address'))p
   left join RRL_ADDR_DISTANCE_MATRIX m on m.FROM_ADDR=p.a and m.TO_ADDR=p.b order by p.pos)loop
   o:=json_object_t();o.put('from_address',leg.a);o.put('to_address',leg.b);o.put('duration_min',leg.DURATION_MIN);
   o.put('duration_basis',leg.DURATION_BASIS);o.put('provider',leg.SOURCE);o.put('updated_at',to_char(leg.UPDATED_AT,'YYYY-MM-DD HH24:MI:SS'));o.put('fresh',leg.fresh=1);
   legs.append(o);
  end loop;
  r.put('policy_id','REV55_ROUTE_V6_120_15_540_ROAD24H');r.put('continuous_limit_min',120);r.put('minimum_break_min',15);r.put('drive_limit_min',540);
  r.put('maximum_cache_age_hours',24);r.put('depot_address',depot);r.put('stops',stops);r.put('legs',legs);r.put('order_valid',valid and n>0);p_result:=r.to_clob;
 end;
 procedure lock_material(p_source clob)is
  b json_object_t:=json_object_t.parse(p_source);m json_object_t;wire clob;dummy number;
 begin
  m:=b.get_object('route_material');wire:=m.to_clob;
  -- Same order for every approval; no lock in a rank earlier than CONFIG/TT.
  for r in(select a.rowid rid from RRL_ADDR a where nvl(a.DELETED3,0)=0 and a.ADDR in
   (select address from json_table(p_source,'$.members[*]'columns(address varchar2(255)path '$.address')))order by a.ADDR,a.rowid)loop
   select 1 into dummy from RRL_ADDR where rowid=r.rid for update wait 5;
  end loop;
  for r in(select distinct a,b from json_table(wire,'$.legs[*]'columns(a varchar2(255)path '$.from_address',b varchar2(255)path '$.to_address'))order by a,b)loop
   begin select 1 into dummy from RRL_ADDR_DISTANCE_MATRIX where FROM_ADDR=r.a and TO_ADDR=r.b for update wait 5;
   exception when no_data_found then raise_application_error(-20886,'TT_ROUTE_ROAD_MISSING');end;
  end loop;
 end;
 procedure assert_chain(p_segments clob,p_zone varchar2)is
  continuous number:=0;total number:=0;minutes number;a date;z date;part_end date;previous_end date;count_ops number:=0;
  type totals_t is table of number index by varchar2(10);totals totals_t;day_key varchar2(10);
 begin
  for op in(select code,a,z from json_table(p_segments,'$[*]'columns(code varchar2(50)path '$.code',a varchar2(60)path '$.start_at',z varchar2(60)path '$.finish_at'))order by to_timestamp_tz(a,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'),to_timestamp_tz(z,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'))loop
   count_ops:=count_ops+1;if count_ops>2000 then raise_application_error(-20886,'TT_TIME_DRIVER_OPERATION_BOUND_2000');end if;
   select cast(to_timestamp_tz(op.a,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM')at time zone (p_zone) as date),
    cast(to_timestamp_tz(op.z,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM')at time zone (p_zone) as date)into a,z from dual;
   if a is null or z is null or z<a or(previous_end is not null and a<previous_end)then raise_application_error(-20886,'TT_TIME_DRIVER_CHAIN_OVERLAP_OR_INVALID');end if;
   previous_end:=z;minutes:=(z-a)*1440;
   if op.code in('DRIVE','DRIVE_BACK','DRIVE_TO_CLIENT')then
    continuous:=continuous+minutes;
    if continuous>120.000001 then raise_application_error(-20886,'TT_TIME_DRIVER_CONTINUOUS_LIMIT');end if;
    while a<z loop
     part_end:=least(z,trunc(a)+1);day_key:=to_char(a,'YYYY-MM-DD');
     if not totals.exists(day_key)then totals(day_key):=0;end if;
     totals(day_key):=totals(day_key)+(part_end-a)*1440;
     if totals(day_key)>540.000001 then raise_application_error(-20886,'TT_TIME_DRIVER_DAY_LIMIT');end if;a:=part_end;
    end loop;
   elsif op.code='REST'and minutes>=15 then continuous:=0;end if;
  end loop;
 end;
 procedure calculate(p_source clob,p_zone varchar2,p_result out clob)is
  b json_object_t:=json_object_t.parse(p_source);m json_object_t;r json_object_t:=json_object_t();legs json_array_t;addresses json_array_t;
  segments json_array_t:=json_array_t();stops json_array_t:=json_array_t();issues json_array_t:=json_array_t();warnings json_array_t:=json_array_t();errors json_array_t;
  leg json_object_t;o json_object_t;clock_at date;departure date;finish_bound date;arrival date;service_at date;opening date;closing date;return_at date;
  address varchar2(255);window_kind varchar2(40);window_error varchar2(150);window_service date;norm number;strict number;cnt number;missing number;n number;continuous number:=0;total number:=0;late number;stnums json_array_t;
  function iso(p_date date)return varchar2 is begin
   return to_char(from_tz(cast(p_date as timestamp),p_zone),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');end;
  procedure issue(p_code varchar2)is x json_object_t:=json_object_t();begin x.put('code',p_code);x.put('address',address);issues.append(x);end;
  procedure segment(p_code varchar2,p_min number)is x json_object_t:=json_object_t();begin
   if p_min<=0 then return;end if;
   x.put('code',p_code);x.put('start_at',iso(clock_at));clock_at:=clock_at+p_min/1440;x.put('finish_at',iso(clock_at));
   x.put('duration_min',RRL_STOCK_PLAN_HELPER.decimal_text(p_min));x.put('address',address);segments.append(x);
  end;
  procedure drive(p_leg json_object_t)is remaining number;piece number;begin
   if p_leg.get_string('from_address')is null or p_leg.get_string('to_address')is null or p_leg.get_string('from_address')=p_leg.get_string('to_address')
    or nvl(p_leg.get_string('duration_basis'),'~')!='ROAD_PROFILE_ESTIMATE' or not p_leg.get_boolean('fresh')
    or p_leg.get_number('duration_min')is null or p_leg.get_number('duration_min')<=0 then
    issue('ROUTE_ROAD_MISSING_STALE_OR_UNSUPPORTED');clock_at:=null;return;end if;
   remaining:=p_leg.get_number('duration_min');total:=total+remaining;
   if total>540 then issue('DRIVER_TRIP_DRIVE_LIMIT');clock_at:=null;return;end if;
   if clock_at is null then return;end if;
   while remaining>0 loop
    if continuous>=120 then segment('REST',15);continuous:=0;end if;
    piece:=least(remaining,120-continuous);segment('DRIVE',piece);continuous:=continuous+piece;remaining:=remaining-piece;
   end loop;
  end;
 begin
  if p_zone is null or p_zone not in('UTC','Europe/Moscow','Asia/Tbilisi')then raise_application_error(-20886,'TT_TIME_EXPLICIT_REGION_REQUIRED');end if;
  m:=b.get_object('route_material');legs:=m.get_array('legs');addresses:=m.get_array('stops');
  if not m.get_boolean('order_valid')then issue('ROUTE_ORDER_INVALID');end if;
  if m.get_string('depot_address')is null then issue('WAREHOUSE_DEPOT_NOT_CONFIGURED');end if;
  select count(*),min(to_date(start_at,'YYYY-MM-DD HH24:MI:SS'))into n,departure
   from json_table(p_source,'$.operations[*]'columns(code varchar2(50)path '$.code',start_at varchar2(30)path '$.plan_start'))where code='DRIVE';
  select max(to_date(end_at,'YYYY-MM-DD HH24:MI:SS'))into finish_bound
   from json_table(p_source,'$.operations[*]'columns(code varchar2(50)path '$.code',end_at varchar2(30)path '$.plan_end'))where code='DRIVE_BACK';
  clock_at:=departure;if n!=1 or departure is null then issue('ROUTE_DEPARTURE_STAGE_UNKNOWN');clock_at:=null;end if;
  -- Preserve explicit pre-route duties/rest; no unknown gap is treated as rest.
  for op in(select code,a,z from json_table(p_source,'$.operations[*]'columns(code varchar2(50)path '$.code',a varchar2(30)path '$.plan_start',z varchar2(30)path '$.plan_end'))
   where to_date(z,'YYYY-MM-DD HH24:MI:SS')<=departure order by a,z)loop
   o:=json_object_t();o.put('code',op.code);o.put('start_at',iso(to_date(op.a,'YYYY-MM-DD HH24:MI:SS')));o.put('finish_at',iso(to_date(op.z,'YYYY-MM-DD HH24:MI:SS')));segments.append(o);
  end loop;
  if addresses.get_size>0 then for i in 0..addresses.get_size-1 loop
   address:=addresses.get_string(i);drive(treat(legs.get(i)as json_object_t));arrival:=clock_at;errors:=json_array_t();
   select count(*),min(norm),min(strict),min(address_count)into n,norm,strict,cnt
    from json_table(p_source,'$.destination_rules[*]'columns(a varchar2(255)path '$.address',norm number path '$.unload_norm_min',strict number path '$.window_strict',address_count number path '$.address_count'))where a=address;
   if n!=1 or cnt!=1 or norm is null or norm<=0 or norm>1440 or strict is null or strict not in(0,1)then issue('DESTINATION_RULE_INVALID');errors.append('DESTINATION_RULE_INVALID');clock_at:=null;end if;
   RRL_STORE_WINDOW_RULES.resolve(p_source,address,clock_at,p_zone,norm,opening,closing,window_service,window_kind,window_error);
   if window_error is not null then issue(window_error);errors.append(window_error);clock_at:=null;end if;
   if clock_at is not null and clock_at<window_service then segment('WAIT',(window_service-clock_at)*1440);end if;
   service_at:=clock_at;if clock_at is not null then segment('UNLOAD',norm);end if;late:=greatest(0,(clock_at-closing)*1440);
   if late>0 then
    if strict=1 then issue('DELIVERY_HARD_WINDOW_MISSED');errors.append('DELIVERY_HARD_WINDOW_MISSED');
    else o:=json_object_t();o.put('code','DELIVERY_SOFT_WINDOW_MISSED');o.put('address',address);warnings.append(o);errors.append('DELIVERY_SOFT_WINDOW_MISSED');end if;
   end if;
   stnums:=json_array_t();for st in(select distinct sn from json_table(p_source,'$.members[*]'columns(a varchar2(255)path '$.address',sn varchar2(255)path '$.st_number'))where a=address order by sn)loop stnums.append(st.sn);end loop;
   o:=json_object_t();o.put('address',address);o.put('st_numbers',stnums);o.put('window_from',iso(opening));o.put('window_to',iso(closing));o.put('arrival_at',iso(arrival));o.put('service_start_at',iso(service_at));o.put('service_finish_at',iso(clock_at));
   o.put('wait_min',RRL_STOCK_PLAN_HELPER.decimal_text((service_at-arrival)*1440));o.put('late_min',RRL_STOCK_PLAN_HELPER.decimal_text(late));o.put('unload_norm_min',RRL_STOCK_PLAN_HELPER.decimal_text(norm));o.put('window_strict',strict);o.put('window_source',window_kind);o.put('issues',errors);stops.append(o);
  end loop;end if;
  -- Retain the existing return-loading duty between last delivery and return drive.
  for op in(select code,duration_min from json_table(p_source,'$.operations[*]'columns(code varchar2(50)path '$.code',duration_min number path '$.duration_min',a varchar2(30)path '$.plan_start'))
   where to_date(a,'YYYY-MM-DD HH24:MI:SS')>=departure and to_date(a,'YYYY-MM-DD HH24:MI:SS')<finish_bound
   and code not in('DRIVE','UNLOAD','DRIVE_BACK')order by a)loop
   if op.code='LOAD_RETURNS'and op.duration_min>=0 then
    if clock_at is not null then segment(op.code,op.duration_min);end if;
   elsif op.code!='DEPART'then issue('ROUTE_OPERATION_MAPPING_REQUIRED');end if;
  end loop;
  address:=m.get_string('depot_address');drive(treat(legs.get(legs.get_size-1)as json_object_t));
  if clock_at is null then issue('ROUTE_RETURN_TIME_UNKNOWN');elsif finish_bound is null or clock_at>finish_bound then issue('ROUTE_EXCEEDS_PLANNED_RESOURCE_ENVELOPE');end if;
  return_at:=clock_at;
  if clock_at is not null and finish_bound>=clock_at then segment('WAIT',(finish_bound-clock_at)*1440);end if;
  for op in(select code,a,z from json_table(p_source,'$.operations[*]'columns(code varchar2(50)path '$.code',a varchar2(30)path '$.plan_start',z varchar2(30)path '$.plan_end'))
   where to_date(a,'YYYY-MM-DD HH24:MI:SS')>=finish_bound order by a,z)loop
   o:=json_object_t();o.put('code',op.code);o.put('start_at',iso(to_date(op.a,'YYYY-MM-DD HH24:MI:SS')));o.put('finish_at',iso(to_date(op.z,'YYYY-MM-DD HH24:MI:SS')));segments.append(o);
  end loop;
  r.put('segments',segments);r.put('stops',stops);r.put('return_at',iso(return_at));r.put('departure_at',iso(departure));r.put('issues',issues);r.put('warnings',warnings);r.put('drive_min',RRL_STOCK_PLAN_HELPER.decimal_text(total));
  r.put('status',case when issues.get_size=0 then 'NO_EARLIEST_WINDOW_VIOLATION'else 'INSUFFICIENT_EVIDENCE'end);r.put('policy_id',m.get_string('policy_id'));r.put('time_zone',p_zone);
  r.put('estimate_basis','NATIVE_DRIVE_REST_WAIT_UNLOAD');r.put('driver_breaks_included',true);r.put('legal_compliance_verified',false);r.put('operational_admission',false);r.put('destination_time_zones_verified',false);
  r.put('depot_address',m.get_string('depot_address'));r.put('depot_basis','CONFIGURED_WAREHOUSE_REFERENCE');r.put('read_only',true);r.put('stock_changed',false);p_result:=r.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_TT_ROUTE_SOURCE as
 procedure snapshot(p_trip number,p_actor varchar2,p_source out clob,p_hash out varchar2)is
  v_context clob;b json_object_t;s json_object_t;
 begin
  RRL_TT_TIME_API.context(p_trip,p_actor,v_context);
  b:=json_object_t.parse(v_context);s:=b.get_object('source');s.remove('operations');
  p_source:=s.to_clob;p_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_source,sys.dbms_crypto.hash_sh256)));
 end;
 procedure durations(p_trip number,p_actor varchar2,p_drive out number,p_back out number,p_basis out varchar2)is
  src clob;hash varchar2(64);saved RRL_TT_ROUTE_INPUT%rowtype;
 begin
  p_drive:=null;p_back:=null;p_basis:='CONFIGURED_NORMS_ESTIMATE';
  snapshot(p_trip,p_actor,src,hash);
  begin select *into saved from RRL_TT_ROUTE_INPUT where TT_ID=p_trip and VERSION_NO=(select max(VERSION_NO)from RRL_TT_ROUTE_INPUT where TT_ID=p_trip);
   if saved.SOURCE_HASH=hash then p_drive:=saved.DRIVE_MIN;p_back:=saved.DRIVE_BACK_MIN;p_basis:='MANUAL_DISPATCH_ESTIMATE';end if;
  exception when no_data_found then null;end;
 end;
end;
/


CREATE OR REPLACE PACKAGE BODY          "RRL_TT_TIME_API" as
 g_operation varchar2(100);g_tx varchar2(100);
 function write_allowed(p_operation varchar2)return number is begin
  if g_operation=p_operation and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure scope(p_trip number,p_actor varchar2)is w RRL_TRANSPORT_TASK%rowtype;n number:=0;allowed number;begin
  select count(*)into allowed from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'transport_dispatch_edit')=1;
  if allowed!=1 then raise_application_error(-20882,'TT_TIME_ACTIVE_DISPATCHER_REQUIRED');end if;
  select *into w from RRL_TRANSPORT_TASK where ID=p_trip;
  for member in(select ID,WARE_ID from RRL_SBORKA_PALLETS where TRANSTASK_ID=p_trip order by ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20886,'TT_TIME_MEMBER_BOUND_200');end if;
   RRL_TRANSPORT_PLAN_RULES.assert_actor(p_actor,member.WARE_ID);
  end loop;
  if n=0 and nvl(w.USER_ID,'~')!=p_actor then
   select count(*)into allowed from RUSERS where ID=p_actor and upper(trim(USER_GROUP))='GLOBAL_ADMIN';
   if allowed!=1 then raise_application_error(-20882,'TT_TIME_EMPTY_TRIP_OWNER_REQUIRED');end if;
  end if;
 end;
 procedure snapshot(p_trip number,p_source out clob,p_hash out varchar2)is
  w RRL_TRANSPORT_TASK%rowtype;b json_object_t:=json_object_t();a json_array_t:=json_array_t();o json_object_t;n number:=0;
 begin
  select *into w from RRL_TRANSPORT_TASK where ID=p_trip;
  b.put('trip_id',p_trip);b.put('vehicle_num',w.TRANSPORT);b.put('driver_id',w.VODITEL_ID);b.put('dock',w.DOCK);
  b.put('source_contract_version',7);b.put('transport_type',w.TRANSTYPE);
  b.put('shipment_date',to_char(w.SHIPMENT_DATE,'YYYY-MM-DD HH24:MI:SS'));b.put('shipment_time',to_char(w.SHIPMENT_TIME,'YYYY-MM-DD HH24:MI:SS'));
  for member in(select ID,ST_NUMBER,WARE_ID,CONDITION,PALLET_UID,ADDR,STDATE,ORD,ZONE_TIME_PLAN_IN,ZONE_TIME_PLAN_OUT from RRL_SBORKA_PALLETS where TRANSTASK_ID=p_trip order by ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20886,'TT_TIME_MEMBER_BOUND_200');end if;
   o:=json_object_t();o.put('id',member.ID);o.put('st_number',member.ST_NUMBER);o.put('warehouse_id',member.WARE_ID);
   o.put('pallet_identifier',member.PALLET_UID);o.put('address',member.ADDR);o.put('st_date',to_char(member.STDATE,'YYYY-MM-DD HH24:MI:SS'));o.put('route_ordinal',member.ORD);o.put('delivery_window_from',to_char(member.ZONE_TIME_PLAN_IN,'YYYY-MM-DD HH24:MI:SS'));o.put('delivery_window_to',to_char(member.ZONE_TIME_PLAN_OUT,'YYYY-MM-DD HH24:MI:SS'));a.append(o);
  end loop;
  b.put('members',a);a:=json_array_t();n:=0;
  for warehouse in(select distinct WARE_ID from RRL_SBORKA_PALLETS where TRANSTASK_ID=p_trip order by WARE_ID)loop
   declare origin_wire clob;begin
    RRL_WARE_DEPOT_API.material(warehouse.WARE_ID,origin_wire);a.append(json_object_t.parse(origin_wire));
   end;
  end loop;
  b.put('warehouse_origins',a);a:=json_array_t();
  n:=0;
  for destination in(select ADDR,count(*) ADDRESS_COUNT,min(UNLOAD_NORM_MIN) UNLOAD_NORM_MIN,min(TW_STRICT) TW_STRICT,min(SHIROTA) LATITUDE,min(DOLGOTA) LONGITUDE
    from RRL_ADDR where nvl(DELETED3,0)=0 and ADDR in(select ADDR from RRL_SBORKA_PALLETS where TRANSTASK_ID=p_trip)
    group by ADDR order by ADDR fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20886,'TT_TIME_DESTINATION_BOUND_200');end if;
   o:=json_object_t();o.put('address',destination.ADDR);o.put('address_count',destination.ADDRESS_COUNT);
   o.put('unload_norm_min',destination.UNLOAD_NORM_MIN);o.put('window_strict',destination.TW_STRICT);
   o.put('latitude',destination.LATITUDE);o.put('longitude',destination.LONGITUDE);a.append(o);
  end loop;
  b.put('destination_rules',a);a:=json_array_t();n:=0;
  declare profile_wire clob;vehicle_count number;vehicle_id number;vehicle_material json_object_t:=json_object_t();begin
   RRL_STORE_WINDOW_RULES.material(b.to_clob,profile_wire);b.put('store_window_profiles',json_array_t.parse(profile_wire));
   select count(*),min(ID)into vehicle_count,vehicle_id from RRL_TR_VEHICLE where upper(trim(NUM))=upper(trim(w.TRANSPORT))and nvl(DELETED,0)=0;
   vehicle_material.put('matching_vehicle_count',vehicle_count);
   if vehicle_count=1 then vehicle_material.put('current',json_object_t.parse(RRL_VEHICLE_PROFILE_API.describe_profile(vehicle_id)));
   else vehicle_material.put('state',case when vehicle_count=0 then 'ABSENT'else 'AMBIGUOUS'end);end if;
   b.put('vehicle_profile_material',vehicle_material);
  end;



  for line in(select r.ID,r.PALLET_UID,r.ARTICUL,r.QUANTITY,r.EI,r.ORDER_WEIGHT,r.TAREWEIGHT,r.TARESIZE,r.PACK_COUNT,r.DOCID,r.WARE_ID
   from RRL_SBORKA_PALLET_ROWS r where exists(select 1 from RRL_SBORKA_PALLETS member where member.TRANSTASK_ID=p_trip and member.PALLET_UID=r.PALLET_UID)
   order by r.ID fetch first 2001 rows only)loop
   n:=n+1;if n>2000 then raise_application_error(-20886,'TT_TIME_SOURCE_LINE_BOUND_2000');end if;
   o:=json_object_t();o.put('id',line.ID);o.put('pallet_identifier',line.PALLET_UID);o.put('article',line.ARTICUL);
   o.put('quantity',line.QUANTITY);o.put('unit',line.EI);o.put('order_weight',line.ORDER_WEIGHT);o.put('tare_weight',line.TAREWEIGHT);
   o.put('tare_size',line.TARESIZE);o.put('pack_count',line.PACK_COUNT);o.put('document_id',line.DOCID);o.put('warehouse_id',line.WARE_ID);a.append(o);
  end loop;
  b.put('source_lines',a);a:=json_array_t();n:=0;
  for op in(select *from RRL_TT_OPERATIONS where TT_ID=p_trip order by ORD,ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20886,'TT_TIME_OPERATION_BOUND_200');end if;
   o:=json_object_t();o.put('operation_id',op.ID);o.put('code',op.OPERATION_CODE);o.put('ordinal',op.ORD);o.put('duration_min',op.DURATION_MIN);
   o.put('plan_start',to_char(op.PLAN_START,'YYYY-MM-DD HH24:MI:SS'));o.put('plan_end',to_char(op.PLAN_END,'YYYY-MM-DD HH24:MI:SS'));
   a.append(o);
  end loop;
  b.put('operations',a);
  declare material_wire clob;begin RRL_TT_ROUTE_SCHEDULE.material(b.to_clob,material_wire);b.put('route_material',json_object_t.parse(material_wire));end;
  p_source:=b.to_clob;
  p_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_source,sys.dbms_crypto.hash_sh256)));
 end;
 procedure assert_published_resources(p_trip RRL_TRANSPORT_TASK%rowtype,p_start date,p_finish date,p_zone varchar2,p_schedule clob)is
  v_start timestamp with time zone;v_finish timestamp with time zone;
  v_other_start timestamp with time zone;v_other_finish timestamp with time zone;v_a timestamp with time zone;v_b timestamp with time zone;
  v_source clob;v_hash varchar2(64);v_n number:=0;v_ops number:=0;b json_object_t;ops json_array_t;o json_object_t;chain json_array_t;peer json_object_t;peer_ops json_array_t;
  begin_chain json_object_t:=json_object_t.parse(p_schedule);
 begin
  select from_tz(cast(p_start as timestamp),p_zone),from_tz(cast(p_finish as timestamp),p_zone)into v_start,v_finish from dual;
  chain:=begin_chain.get_array('segments');
  for other in(select t.ID,t.VODITEL_ID,a.SOURCE_HASH,a.RESULT_JSON
   from RRL_TRANSPORT_TASK t join RRL_TT_TIME_APPROVAL a on a.TT_ID=t.ID
   where t.ID!=p_trip.ID and nvl(t.DELETED,0)=0 and t.CONDITION='Спланирован'and nvl(t.PAY_ORDER_ID,0)=0
   and(t.TRANSPORT=p_trip.TRANSPORT or t.VODITEL_ID=p_trip.VODITEL_ID)
   and a.VERSION_NO=(select max(latest.VERSION_NO)from RRL_TT_TIME_APPROVAL latest where latest.TT_ID=t.ID)
   order by t.ID fetch first 201 rows only)loop
   v_n:=v_n+1;if v_n>200 then raise_application_error(-20886,'TT_TIME_RESOURCE_PLAN_BOUND_200');end if;
   snapshot(other.ID,v_source,v_hash);
   if v_hash=other.SOURCE_HASH then
    b:=json_object_t.parse(other.RESULT_JSON);ops:=b.get_array('operations');v_other_start:=null;v_other_finish:=null;
    if ops is null or ops.get_size not between 1 and 200 then raise_application_error(-20886,'TT_TIME_RESOURCE_PLAN_OPERATIONS_INVALID');end if;
    v_ops:=v_ops+ops.get_size;if v_ops>2000 then raise_application_error(-20886,'TT_TIME_RESOURCE_OPERATION_BOUND_2000');end if;
    for i in 0..ops.get_size-1 loop
     o:=treat(ops.get(i)as json_object_t);
     v_a:=to_timestamp_tz(o.get_string('start_at'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
     v_b:=to_timestamp_tz(o.get_string('finish_at'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
     if v_a is null or v_b is null or v_b<v_a then raise_application_error(-20886,'TT_TIME_RESOURCE_PLAN_INTERVAL_INVALID');end if;
     if v_other_start is null or v_a<v_other_start then v_other_start:=v_a;end if;
     if v_other_finish is null or v_b>v_other_finish then v_other_finish:=v_b;end if;
    end loop;
    if v_start<v_other_finish and v_finish>v_other_start then raise_application_error(-20886,'TT_TIME_APPROVED_RESOURCE_OVERLAP');end if;
    if other.VODITEL_ID=p_trip.VODITEL_ID and v_other_start<v_finish+interval '7' day and v_other_finish>v_start-interval '7' day then
     peer:=b.get_object('route_schedule');
     if peer is null then raise_application_error(-20886,'TT_TIME_DRIVER_PEER_V6_APPROVAL_REQUIRED');end if;
     peer_ops:=peer.get_array('segments');
     for i in 0..peer_ops.get_size-1 loop chain.append(peer_ops.get(i));end loop;
    end if;
   end if;
  end loop;
  RRL_TT_ROUTE_SCHEDULE.assert_chain(chain.to_clob,p_zone);
 end;
 procedure context(p_trip number,p_actor varchar2,p_result out clob)is
  src clob;hash varchar2(64);v_version number;saved RRL_TT_TIME_APPROVAL%rowtype;b json_object_t:=json_object_t();
 begin
  scope(p_trip,p_actor);snapshot(p_trip,src,hash);
  select nvl(max(VERSION_NO),0)into v_version from RRL_TT_TIME_APPROVAL where TT_ID=p_trip;
  b.put('trip_id',p_trip);b.put('source_hash',hash);b.put('version',v_version);b.put('source',json_object_t.parse(src));
  b.put('approval_status','NO_APPROVAL');b.put('operational_admission',false);
  if v_version>0 then
   select *into saved from RRL_TT_TIME_APPROVAL where TT_ID=p_trip and VERSION_NO=v_version;
   if not json_object_t.parse(saved.RESULT_JSON).has('source_contract_version')then b.put('approval_status','LEGACY_SOURCE_CONTRACT');
   elsif saved.SOURCE_HASH=hash then b.put('approval_status','APPROVED');else b.put('approval_status','SOURCE_CHANGED');end if;
   b.put('last_approval',json_object_t.parse(saved.RESULT_JSON));
  end if;
  p_result:=b.to_clob;
 end;
 procedure approve(p_operation varchar2,p_actor varchar2,p_body clob,p_result out clob)is
  b json_object_t;w RRL_TRANSPORT_TASK%rowtype;saved RRL_TT_TIME_APPROVAL%rowtype;
  v_trip number;v_version number;v_req_hash varchar2(64);v_source clob;v_source_hash varchar2(64);v_zone varchar2(50);v_reason nvarchar2(500);v_phase varchar2(40);
  v_metadata boolean:=false;n number;v_start date;v_finish date;v_aware clob;v_schedule clob;route_result json_object_t;route_issue json_object_t;result json_object_t:=json_object_t();
 begin
  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_body is null or dbms_lob.getlength(p_body)>2000 then raise_application_error(-20886,'TT_TIME_INPUT_BOUND');end if;
  b:=json_object_t.parse(p_body);v_trip:=b.get_number('trip_id');scope(v_trip,p_actor);
  v_req_hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'transport_dispatch_edit');v_metadata:=true;savepoint RRL_TT_TIME248;
  select *into w from RRL_TRANSPORT_TASK where ID=v_trip for update;scope(v_trip,p_actor);
  begin
   select *into saved from RRL_TT_TIME_APPROVAL where OPERATION_ID=p_operation;
   if saved.ACTOR!=p_actor or saved.TT_ID!=v_trip or saved.REQUEST_HASH!=v_req_hash then raise_application_error(-20886,'TT_TIME_OPERATION_PAYLOAD_CONFLICT');end if;
   p_result:=saved.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;
  exception when no_data_found then null;end;
  snapshot(v_trip,v_source,v_source_hash);
  RRL_TT_ROUTE_SCHEDULE.lock_material(v_source);
  snapshot(v_trip,v_source,v_source_hash);
  select nvl(max(VERSION_NO),0)into v_version from RRL_TT_TIME_APPROVAL where TT_ID=v_trip;
  if b.get_number('expected_version')is null or b.get_number('expected_version')!=v_version or b.get_string('source_hash')is null or b.get_string('source_hash')!=v_source_hash then raise_application_error(-20886,'TT_TIME_SOURCE_CHANGED');end if;
  if nvl(w.DELETED,0)!=0 or w.CONDITION is null or w.CONDITION!='Спланирован'or nvl(w.PAY_ORDER_ID,0)>0 or w.TRANSPORT is null or w.VODITEL_ID is null or w.VODITEL_ID<=0 then raise_application_error(-20886,'TT_TIME_CURRENT_PLANNED_VEHICLE_DRIVER_REQUIRED');end if;
  select count(*)into n from RRL_TT_HU_LOAD_FACT where TT_ID=v_trip and STATUS in('LOADED','DEPARTED');
  v_phase:=nvl(b.get_string('approval_phase'),'BEFORE_LOADING');
  if v_phase not in('BEFORE_LOADING','AFTER_LOADING_REVIEW')then raise_application_error(-20886,'TT_TIME_APPROVAL_PHASE_REQUIRED');end if;
  if n>0 then
   if v_phase!='AFTER_LOADING_REVIEW'then raise_application_error(-20886,'TT_TIME_PHYSICAL_EXECUTION_FROZEN');end if;
   select count(*)into n from RRL_SBORKA_PALLETS p where p.TRANSTASK_ID=v_trip
    and(nvl(p.CONDITION,-1)!=2 or(select count(*)from RRL_TT_HU_LOAD_ST m
      join RRL_TT_HU_LOAD_FACT l on l.LOAD_OPERATION_ID=m.LOAD_OPERATION_ID
      join RRL_STOCK_OPERATION op on op.OPERATION_ID=l.LOAD_OPERATION_ID
      join RRL_TR_VEHICLE vehicle on vehicle.ID=l.VEHICLE_ID and vehicle.NUM=w.TRANSPORT
      where m.SBORKA_PALLET_ID=p.ID and m.ACTIVE_FLAG=1 and l.TT_ID=v_trip
       and l.STATUS='LOADED'and l.VEHICLE_NUMBER=w.TRANSPORT and l.DOCK=w.DOCK
       and l.CUSTODY_RELEASED_AT is null and op.STATE='APPLIED')!=1);
   if n>0 then raise_application_error(-20886,'TT_TIME_ALL_CURRENT_MEMBERS_LOADED_PROOF_REQUIRED');end if;
   select count(*)into n from RRL_SBORKA_PALLETS where TRANSTASK_ID=v_trip;
   if n<1 then raise_application_error(-20886,'TT_TIME_CURRENT_MEMBERS_REQUIRED');end if;
  elsif v_phase='AFTER_LOADING_REVIEW'then raise_application_error(-20886,'TT_TIME_REVIEW_REQUIRES_ACTUAL_LOAD');end if;
  select count(*),min(PLAN_START),max(PLAN_END)into n,v_start,v_finish from RRL_TT_OPERATIONS where TT_ID=v_trip;
  if n<1 or n>200 or v_start is null or v_finish is null or v_finish<=v_start or v_finish-v_start>7 then raise_application_error(-20886,'TT_TIME_POSITIVE_BOUNDED_CHAIN_REQUIRED');end if;
  if w.SHIPMENT_DATE is null or w.SHIPMENT_TIME is null or v_start!=trunc(w.SHIPMENT_DATE)+(w.SHIPMENT_TIME-trunc(w.SHIPMENT_TIME))then raise_application_error(-20886,'TT_TIME_CHAIN_DEPARTURE_CHANGED');end if;
  select count(*)into n from RRL_TT_OPERATIONS where TT_ID=v_trip and(PLAN_START is null or PLAN_END is null or PLAN_END<PLAN_START or FACT_START is not null or FACT_END is not null);
  if n>0 then raise_application_error(-20886,'TT_TIME_VALID_UNSTARTED_CHAIN_REQUIRED');end if;
  v_zone:=b.get_string('time_zone');v_reason:=b.get_string('reason');
  if v_zone is null or v_zone not in('UTC','Europe/Moscow','Asia/Tbilisi')then raise_application_error(-20886,'TT_TIME_EXPLICIT_REGION_REQUIRED');end if;
  if v_reason is null or length(trim(v_reason))<8 then raise_application_error(-20886,'TT_TIME_REASON_REQUIRED');end if;
  RRL_TT_ROUTE_SCHEDULE.calculate(v_source,v_zone,v_schedule);route_result:=json_object_t.parse(v_schedule);
  if route_result.get_array('issues').get_size>0 then route_issue:=treat(route_result.get_array('issues').get(0)as json_object_t);raise_application_error(-20886,'TT_TIME_ROUTE_SCHEDULE_REJECTED:'||route_issue.get_string('code')||':'||route_issue.get_string('address'));end if;
  assert_published_resources(w,v_start,v_finish,v_zone,v_schedule);
  select json_arrayagg(json_object(
   'operation_id'value ID,'code'value OPERATION_CODE,'ordinal'value ORD,
   'start_at'value to_char(from_tz(cast(PLAN_START as timestamp),v_zone),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'),
   'finish_at'value to_char(from_tz(cast(PLAN_END as timestamp),v_zone),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM')
   returning clob)order by ORD,ID returning clob)into v_aware from RRL_TT_OPERATIONS where TT_ID=v_trip;
  result.put('trip_id',v_trip);result.put('version',v_version+1);result.put('operation_id',p_operation);result.put('source_hash',v_source_hash);
  result.put('time_zone',v_zone);result.put('reason',v_reason);result.put('actor',p_actor);
  result.put('approval_phase',v_phase);
  result.put('source_contract_version',7);result.put('plan_source',json_object_t.parse(v_source));
  result.put('operations',json_array_t.parse(v_aware));result.put('approval_basis','NATIVE_ROUTE_REST_V6_WITHIN_ORIGINAL_RESOURCE_ENVELOPE');result.put('route_schedule',route_result);
  result.put('operational_admission',false);result.put('stock_changed',false);
  p_result:=result.to_clob;g_operation:=p_operation;g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_TT_TIME_APPROVAL(TT_ID,VERSION_NO,OPERATION_ID,ACTOR,REQUEST_HASH,SOURCE_HASH,TIME_ZONE,REASON,RESULT_JSON)
   values(v_trip,v_version+1,p_operation,p_actor,v_req_hash,v_source_hash,v_zone,v_reason,p_result);
  g_operation:=null;g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
 exception when others then
  if v_metadata then rollback to RRL_TT_TIME248;end if;g_operation:=null;g_tx:=null;
  if v_metadata then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
end;
/


CREATE OR REPLACE PACKAGE BODY          "RRL_VEHICLE_PROFILE_API" as
 g_writing boolean:=false;g_tx varchar2(100);
 function base_json(v RRL_TR_VEHICLE%rowtype)return clob is j json_object_t:=json_object_t();
 begin
  j.put('vehicle_id',v.ID);j.put('vehicle_number',v.NUM);j.put('vehicle_type',v.TR_TYPE);
  j.put('pallet_capacity',RRL_STOCK_PLAN_HELPER.decimal_text(v.PALLETS));
  j.put('max_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(v.MAX_WEIGHT_KG));
  return j.to_clob;
 end;
 procedure assert_writing is
 begin
  if not g_writing or g_tx is null or g_tx!=dbms_transaction.local_transaction_id(false)
   then raise_application_error(-20863,'VEHICLE_PROFILE_OWNER_REQUIRED');end if;
 end;
 function source_hash(p_source clob)return varchar2 is
 begin return rawtohex(sys.dbms_crypto.hash(utl_i18n.string_to_raw(dbms_lob.substr(p_source,32767,1),'AL32UTF8'),sys.dbms_crypto.hash_sh256));end;
 function describe_profile(p_vehicle number)return clob is v RRL_TR_VEHICLE%rowtype;h RRL_VEHICLE_PROFILE_HIST%rowtype;
  j json_object_t:=json_object_t();saved_profile json_object_t;current_base clob;
 begin
  select *into v from RRL_TR_VEHICLE where ID=p_vehicle;
  current_base:=base_json(v);j.put('base_hash',source_hash(current_base));j.put('vehicle_id',p_vehicle);j.put('base',json_object_t.parse(current_base));
  begin
   select hist.*into h from RRL_VEHICLE_PROFILE_HIST hist join RRL_VEHICLE_PROFILE_HEAD head
    on head.VEHICLE_ID=hist.VEHICLE_ID and head.VERSION_NO=hist.VERSION_NO where head.VEHICLE_ID=p_vehicle;
   saved_profile:=json_object_t.parse(h.RESULT_JSON);
   saved_profile.put('outer_height_mm',h.OUTER_HEIGHT_MM);saved_profile.put('outer_length_mm',h.OUTER_LENGTH_MM);
   j.put('profile',saved_profile);j.put('version',h.VERSION_NO);
   if dbms_lob.compare(current_base,h.SOURCE_JSON)=0 then j.put('state','READY');else j.put('state','BASE_CHANGED');end if;
  exception when no_data_found then j.put('state','NOT_CONFIGURED');j.put('version',0);end;
  return j.to_clob;
 end;
 function validated_floor_variants(p_value json_element_t)return json_array_t is
  variants json_array_t;variant json_object_t;limits json_array_t;lim json_object_t;
  code_value varchar2(40);type_id number;places number;n number;keys json_key_list;
  el json_element_t;
  type seen_map is table of boolean index by varchar2(100);seen_codes seen_map;seen_types seen_map;
 begin
  if p_value is null or not p_value.is_array then raise_application_error(-20886,'VEHICLE_TARE_VARIANTS_ARRAY_REQUIRED');end if;
  variants:=treat(p_value as json_array_t);
  if variants.get_size<1 or variants.get_size>20 then raise_application_error(-20886,'VEHICLE_TARE_VARIANTS_BOUND_20');end if;
  for i in 0..variants.get_size-1 loop
   el:=variants.get(i);
   if not el.is_object then raise_application_error(-20886,'VEHICLE_TARE_VARIANT_OBJECT_REQUIRED');end if;
   variant:=treat(el as json_object_t);keys:=variant.get_keys;
   if keys.count!=2 or not variant.has('code')or not variant.has('limits')then
    raise_application_error(-20886,'VEHICLE_TARE_VARIANT_FIELDS_REQUIRED');end if;
   el:=variant.get('code');
   if not el.is_string then raise_application_error(-20886,'VEHICLE_TARE_VARIANT_CODE_REQUIRED');end if;
   code_value:=variant.get_string('code');
   if code_value is null or not regexp_like(code_value,'^[A-Za-z0-9_.:-]{1,40}$')then
    raise_application_error(-20886,'VEHICLE_TARE_VARIANT_CODE_REQUIRED');end if;
   if seen_codes.exists(code_value)then raise_application_error(-20886,'VEHICLE_TARE_VARIANT_CODE_DUPLICATE');end if;
   seen_codes(code_value):=true;seen_types.delete;
   el:=variant.get('limits');
   if not el.is_array then raise_application_error(-20886,'VEHICLE_TARE_LIMITS_ARRAY_REQUIRED');end if;
   limits:=treat(el as json_array_t);
   if limits.get_size<1 or limits.get_size>8 then raise_application_error(-20886,'VEHICLE_TARE_TYPES_BOUND_8');end if;
   for k in 0..limits.get_size-1 loop
    el:=limits.get(k);
    if not el.is_object then raise_application_error(-20886,'VEHICLE_TARE_LIMIT_OBJECT_REQUIRED');end if;
    lim:=treat(el as json_object_t);keys:=lim.get_keys;
    if keys.count!=2 or not lim.has('pallet_type_id')or not lim.has('max_places')then
     raise_application_error(-20886,'VEHICLE_TARE_LIMIT_FIELDS_REQUIRED');end if;
    el:=lim.get('pallet_type_id');
    if not el.is_number then raise_application_error(-20886,'VEHICLE_TARE_INTEGER_TYPE_REQUIRED');end if;
    el:=lim.get('max_places');
    if not el.is_number then raise_application_error(-20886,'VEHICLE_TARE_INTEGER_PLACES_REQUIRED');end if;
    type_id:=lim.get_number('pallet_type_id');places:=lim.get_number('max_places');
    if type_id is null or type_id<1 or type_id!=trunc(type_id)or places is null or places<1 or places>1000 or places!=trunc(places)then
     raise_application_error(-20886,'VEHICLE_TARE_POSITIVE_INTEGER_LIMIT_REQUIRED');end if;
    if seen_types.exists(to_char(type_id,'TM9'))then raise_application_error(-20886,'VEHICLE_TARE_TYPE_DUPLICATE');end if;
    seen_types(to_char(type_id,'TM9')):=true;
    select count(*)into n from RRL_PALLET_TYPE where PALLET_TYPE_ID=type_id and ACTIVE=1;
    if n!=1 then raise_application_error(-20886,'VEHICLE_TARE_ACTIVE_TYPE_REQUIRED');end if;
   end loop;
  end loop;
  return variants;
 end;
 function check_floor_capacity(p_vehicle number,p_counts clob,p_unknown number)return clob is
  profile_value json_object_t;configured json_object_t;matrix json_object_t;variant json_object_t;
  counts json_array_t;variants json_array_t;limits json_array_t;row_value json_object_t;matches json_array_t:=json_array_t();
  result json_object_t:=json_object_t();type_id number;amount number;ceiling number;fits boolean;active_count number;
  element_value json_element_t;keys json_key_list;
  type type_count_map is table of number index by varchar2(100);seen type_count_map;
 begin
  profile_value:=json_object_t.parse(describe_profile(p_vehicle));
  result.put('basis','EXPLICIT_FLOOR_VARIANTS');result.put('operational_admission',false);
  if not profile_value.has('profile')then result.put('status','NOT_CONFIGURED');return result.to_clob;end if;
  configured:=profile_value.get_object('profile');
  if not configured.has('floor_capacity')then result.put('status','NOT_CONFIGURED');return result.to_clob;end if;
  result.put('profile_version',profile_value.get_number('version'));
  if profile_value.get_string('state')!='READY'then result.put('status','PROFILE_CHANGED');return result.to_clob;end if;
  if p_unknown is null or p_unknown<0 or p_unknown>5000 or p_unknown!=trunc(p_unknown)then
   raise_application_error(-20886,'VEHICLE_TARE_UNKNOWN_COUNT_INVALID');end if;
  counts:=json_array_t.parse(p_counts);
  if counts.get_size>200 then raise_application_error(-20886,'VEHICLE_TARE_COUNTS_BOUND_200');end if;
  for i in 0..counts.get_size-1 loop
   element_value:=counts.get(i);
   if not element_value.is_object then raise_application_error(-20886,'VEHICLE_TARE_COUNT_OBJECT_REQUIRED');end if;
   row_value:=treat(element_value as json_object_t);keys:=row_value.get_keys;
   if keys.count!=2 or not row_value.has('pallet_type_id')or not row_value.has('places')then
    raise_application_error(-20886,'VEHICLE_TARE_COUNT_FIELDS_REQUIRED');end if;
   element_value:=row_value.get('pallet_type_id');
   if not element_value.is_number then raise_application_error(-20886,'VEHICLE_TARE_COUNT_INTEGER_REQUIRED');end if;
   element_value:=row_value.get('places');
   if not element_value.is_number then raise_application_error(-20886,'VEHICLE_TARE_COUNT_INTEGER_REQUIRED');end if;
   type_id:=row_value.get_number('pallet_type_id');amount:=row_value.get_number('places');
   if type_id is null or type_id<1 or type_id!=trunc(type_id)or amount is null or amount<1 or amount>5000 or amount!=trunc(amount)then
    raise_application_error(-20886,'VEHICLE_TARE_COUNT_POSITIVE_INTEGER_REQUIRED');end if;
   if seen.exists(to_char(type_id,'TM9'))then raise_application_error(-20886,'VEHICLE_TARE_COUNT_TYPE_DUPLICATE');end if;
   seen(to_char(type_id,'TM9')):=amount;
   select count(*)into active_count from RRL_PALLET_TYPE where PALLET_TYPE_ID=type_id and ACTIVE=1;
   if active_count!=1 then raise_application_error(-20886,'VEHICLE_TARE_ACTIVE_TYPE_REQUIRED');end if;
  end loop;
  result.put('counts',counts);result.put('unconfirmed_places',p_unknown);
  if p_unknown>0 then result.put('status','TARE_TYPE_UNCONFIRMED');return result.to_clob;end if;
  matrix:=configured.get_object('floor_capacity');variants:=matrix.get_array('variants');
  for i in 0..variants.get_size-1 loop
   variant:=treat(variants.get(i) as json_object_t);limits:=variant.get_array('limits');fits:=true;
   for j in 0..counts.get_size-1 loop
    row_value:=treat(counts.get(j) as json_object_t);type_id:=row_value.get_number('pallet_type_id');amount:=row_value.get_number('places');ceiling:=0;
    for k in 0..limits.get_size-1 loop
     row_value:=treat(limits.get(k) as json_object_t);
     if row_value.get_number('pallet_type_id')=type_id then ceiling:=row_value.get_number('max_places');end if;
    end loop;
    if amount>ceiling then fits:=false;end if;
   end loop;
   if fits then matches.append(variant.get_string('code'));end if;
  end loop;
  result.put('matching_variants',matches);
  if matches.get_size>0 then result.put('status','COMPATIBLE');else result.put('status','INCOMPATIBLE');end if;
  return result.to_clob;
 end;
 procedure resolve_outer_dimensions(d json_object_t,p_vehicle number,p_version number,
  p_cargo_height number,p_cargo_length number,p_height out number,p_length out number)is
  element_value json_element_t;
  procedure read_dimension(p_name varchar2,p_value in out number)is
  begin
   if not d.has(p_name)then return;end if;
   element_value:=d.get(p_name);
   if element_value.is_null then p_value:=null;return;end if;
   if not element_value.is_number then raise_application_error(-20886,'VEHICLE_OUTER_INTEGER_MM_REQUIRED');end if;
   p_value:=d.get_number(p_name);
   if p_value is null or p_value<1 or p_value>1000000 or p_value!=trunc(p_value)
    then raise_application_error(-20886,'VEHICLE_OUTER_INTEGER_MM_REQUIRED');end if;
  end;
 begin
  p_height:=null;p_length:=null;
  if p_version>0 then
   select OUTER_HEIGHT_MM,OUTER_LENGTH_MM into p_height,p_length
    from RRL_VEHICLE_PROFILE_HIST where VEHICLE_ID=p_vehicle and VERSION_NO=p_version;
  end if;
  read_dimension('outer_height_mm',p_height);read_dimension('outer_length_mm',p_length);
  if p_height<p_cargo_height or p_length<p_cargo_length
   then raise_application_error(-20886,'VEHICLE_OUTER_SMALLER_THAN_CARGO');end if;
 end;
 procedure configure(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t:=json_object_t.parse(p_request);v RRL_TR_VEHICLE%rowtype;j json_object_t:=json_object_t();
  op varchar2(100):=d.get_string('operation_id');vid number:=d.get_number('vehicle_id');expected number:=d.get_number('expected_version');
  size_class varchar2(32767):=trim(d.get_string('vehicle_size_class'));reason_value varchar2(32767):=trim(d.get_string('reason'));
  reference_value varchar2(32767):=trim(d.get_string('evidence_reference'));
  len_mm number:=d.get_number('cargo_length_mm');width_mm number:=d.get_number('cargo_width_mm');height_mm number:=d.get_number('cargo_height_mm');
  floor_value json_object_t;floor_variants json_array_t;outer_height number;outer_length number;
  thermal_min varchar2(100);thermal_max varchar2(100);thermal_lo number;thermal_hi number;thermal json_object_t;thermal_min_element json_element_t;thermal_max_element json_element_t;
  expected_hash varchar2(32767):=d.get_string('expected_source_hash');current_version number;old_request clob;old_actor nvarchar2(50);source_value clob;n number;entered boolean:=false;savepoint_ready boolean:=false;keys json_key_list;
 begin
  keys:=d.get_keys;
  if keys.count not between 10 and 15 or op is null or lengthb(op)>100 or not regexp_like(op,'^[A-Za-z0-9_.:-]+$')
   or expected_hash is null or not regexp_like(expected_hash,'^[0-9A-F]{64}$')
   or vid is null or vid<1 or vid!=trunc(vid)or expected is null or expected<0 or expected!=trunc(expected)
   or size_class is null or lengthb(size_class)>40 or reason_value is null or lengthb(reason_value)>2000
   or reference_value is null or lengthb(reference_value)>255
   or len_mm is null or len_mm<1 or len_mm>1000000 or len_mm!=trunc(len_mm)
   or width_mm is null or width_mm<1 or width_mm>1000000 or width_mm!=trunc(width_mm)
   or height_mm is null or height_mm<1 or height_mm>1000000 or height_mm!=trunc(height_mm)
   then raise_application_error(-20886,'VEHICLE_PROFILE_EXPLICIT_FIELDS_REQUIRED');end if;
  for k in 1..keys.count loop
   if keys(k) not in('operation_id','vehicle_id','expected_version','expected_source_hash','vehicle_size_class','cargo_length_mm','cargo_width_mm','cargo_height_mm','reason','evidence_reference','temp_min_c','temp_max_c','floor_variants','outer_height_mm','outer_length_mm')
    then raise_application_error(-20886,'VEHICLE_PROFILE_UNKNOWN_FIELD');end if;
  end loop;
  if d.has('temp_min_c') or d.has('temp_max_c') then
   if not d.has('temp_min_c') or not d.has('temp_max_c')
    then raise_application_error(-20886,'VEHICLE_THERMAL_BOTH_BOUNDS_REQUIRED');end if;
   thermal_min_element:=d.get('temp_min_c');thermal_max_element:=d.get('temp_max_c');
   if not thermal_min_element.is_string or not thermal_max_element.is_string
    then raise_application_error(-20886,'VEHICLE_THERMAL_DECIMAL_TEXT_REQUIRED');end if;
   thermal_min:=d.get_string('temp_min_c');thermal_max:=d.get_string('temp_max_c');
   if thermal_min is null or thermal_max is null
    or not regexp_like(thermal_min,'^-?[0-9]{1,6}(\.[0-9]{1,3})?$')
    or not regexp_like(thermal_max,'^-?[0-9]{1,6}(\.[0-9]{1,3})?$')
    then raise_application_error(-20886,'VEHICLE_THERMAL_DECIMAL_TEXT_REQUIRED');end if;
   thermal_lo:=to_number(thermal_min,'999999D999','NLS_NUMERIC_CHARACTERS=''.,''');
   thermal_hi:=to_number(thermal_max,'999999D999','NLS_NUMERIC_CHARACTERS=''.,''');
   if thermal_lo>thermal_hi then raise_application_error(-20886,'VEHICLE_THERMAL_RANGE_INVALID');end if;
  end if;
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'transport_fleet_edit')=1;
  if n!=1 then raise_application_error(-20882,'VEHICLE_PROFILE_FLEET_AUTHORITY_REQUIRED');end if;
  RRL_STOCK_CONFIG_API.begin_change(p_actor,'transport_fleet_edit');entered:=true;
  savepoint vehicle_profile_effect;savepoint_ready:=true;
  begin
   select REQUEST_JSON,ACTOR,RESULT_JSON into old_request,old_actor,p_result from RRL_VEHICLE_PROFILE_HIST where OPERATION_ID=op;
   select count(*)into n from dual where json_equal(old_request,p_request);
   if n!=1 or old_actor!=p_actor then raise_application_error(-20864,'VEHICLE_PROFILE_OPERATION_CONFLICT');end if;
   RRL_STOCK_CONFIG_API.end_change;entered:=false;return;
  exception when no_data_found then null;end;
  select *into v from RRL_TR_VEHICLE where ID=vid for update;
  if nvl(v.DELETED,0)!=0 or v.NUM is null or v.TR_TYPE is null or v.PALLETS is null or v.MAX_WEIGHT_KG is null
   then raise_application_error(-20886,'VEHICLE_PROFILE_EXISTING_BASE_REQUIRED');end if;
  source_value:=base_json(v);
  if source_hash(source_value)!=expected_hash then raise_application_error(-20890,'VEHICLE_PROFILE_BASE_CHANGED');end if;
  g_tx:=dbms_transaction.local_transaction_id(false);g_writing:=true;
  merge into RRL_VEHICLE_PROFILE_HEAD h using(select vid ID from dual)s on(h.VEHICLE_ID=s.ID)
   when not matched then insert(VEHICLE_ID,VERSION_NO)values(vid,0);
  select VERSION_NO into current_version from RRL_VEHICLE_PROFILE_HEAD where VEHICLE_ID=vid for update;
  if current_version!=expected then raise_application_error(-20886,'VEHICLE_PROFILE_VERSION_CONFLICT');end if;
  if d.has('floor_variants')then floor_variants:=validated_floor_variants(d.get('floor_variants'));end if;
  resolve_outer_dimensions(d,vid,current_version,height_mm,len_mm,outer_height,outer_length);
  current_version:=current_version+1;
  j.put('operation_id',op);j.put('vehicle_id',vid);j.put('version',current_version);j.put('vehicle_size_class',size_class);
  j.put('cargo_length_mm',len_mm);j.put('cargo_width_mm',width_mm);j.put('cargo_height_mm',height_mm);
  j.put('outer_height_mm',outer_height);j.put('outer_length_mm',outer_length);
  j.put('source',json_object_t.parse(source_value));j.put('actor',p_actor);j.put('evidence_reference',reference_value);
  if thermal_min is not null then
   thermal:=json_object_t();thermal.put('temp_min_c',RRL_STOCK_PLAN_HELPER.decimal_text(thermal_lo));
   thermal.put('temp_max_c',RRL_STOCK_PLAN_HELPER.decimal_text(thermal_hi));
   thermal.put('basis','FLEET_DECLARED_CAPABILITY');thermal.put('evidence_reference',reference_value);
   thermal.put('measurement_verified',false);j.put('temperature_capability',thermal);
  end if;
  if floor_variants is not null then
   floor_value:=json_object_t();floor_value.put('variants',floor_variants);
   floor_value.put('basis','FLEET_DECLARED_FLOOR_VARIANTS');floor_value.put('evidence_reference',reference_value);
   j.put('floor_capacity',floor_value);
  end if;
  j.put('status','CONFIGURED');j.put('stock_changed',false);p_result:=j.to_clob;
  insert into RRL_VEHICLE_PROFILE_HIST(VEHICLE_ID,VERSION_NO,OPERATION_ID,ACTOR,VEHICLE_SIZE_CLASS,CARGO_LENGTH_MM,CARGO_WIDTH_MM,CARGO_HEIGHT_MM,OUTER_HEIGHT_MM,OUTER_LENGTH_MM,SOURCE_JSON,REQUEST_JSON,RESULT_JSON)
   values(vid,current_version,op,p_actor,size_class,len_mm,width_mm,height_mm,outer_height,outer_length,source_value,p_request,p_result);
  update RRL_VEHICLE_PROFILE_HEAD set VERSION_NO=current_version where VEHICLE_ID=vid;
  g_writing:=false;g_tx:=null;RRL_STOCK_CONFIG_API.end_change;entered:=false;
 exception when others then
  g_writing:=false;g_tx:=null;
  if savepoint_ready then rollback to vehicle_profile_effect;end if;
  if entered then RRL_STOCK_CONFIG_API.end_change;end if;
  raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_VEH_DEPART_SOURCE as
 g_writing boolean:=false;
 procedure assert_writing is op varchar2(100):=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID');k varchar2(80);state varchar2(20);
 begin
  if not g_writing or op is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)
   then raise_application_error(-20863,'VEHICLE_SOURCE_ROOT_REQUIRED');end if;
  select COMMAND_TYPE,STATE into k,state from RRL_STOCK_OPERATION where OPERATION_ID=op;
  if k!='TRIP_DEPART'or state!='IN_FLIGHT'then raise_application_error(-20863,'VEHICLE_SOURCE_DEPART_REQUIRED');end if;
 end;
 procedure capture_source(p_operation varchar2,p_trip number,p_vehicle number,p_instant timestamp with time zone)is
  tt RRL_TRANSPORT_TASK%rowtype;veh RRL_TR_VEHICLE%rowtype;wire clob;domain_value json_object_t;
  profile json_object_t;j json_object_t:=json_object_t();source_state varchar2(24);profile_version number;
  source_wire clob;carrier varchar2(255);region_value varchar2(4000);n number;
 begin
  if p_operation!=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')then raise_application_error(-20863,'VEHICLE_SOURCE_OPERATION_REQUIRED');end if;
  g_writing:=true;assert_writing;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_TT_VEHICLE_SOURCE',RRL_STOCK_PLAN_HELPER.decimal_text(p_trip)));
  select RESOLVED_PLAN_JSON into wire from RRL_STOCK_OPERATION where OPERATION_ID=p_operation;
  domain_value:=json_object_t.parse(wire).get_object('domain');
  if domain_value.get_number('trip')!=p_trip or domain_value.get_number('vehicle_id')!=p_vehicle
   then raise_application_error(-20863,'VEHICLE_SOURCE_ORIGINAL_PLAN_REQUIRED');end if;
  select *into tt from RRL_TRANSPORT_TASK where ID=p_trip;select *into veh from RRL_TR_VEHICLE where ID=p_vehicle;
  select DOVERENNOST_OT into carrier from RRL_TR_VODITEL where ID=tt.VODITEL_ID and nvl(DELETED,0)=0;
  select count(*)into n from RRL_TT_HU_LOAD_FACT where TT_ID=p_trip and DEPARTURE_OPERATION_ID=p_operation
   and STATUS='DEPARTED'and DEPARTED_AT=p_instant;
  if n!=domain_value.get_array('loads').get_size or n<1 then raise_application_error(-20863,'VEHICLE_SOURCE_ORIGINAL_DEPARTURE_CLOCK');end if;
  profile:=json_object_t.parse(RRL_VEHICLE_PROFILE_API.describe_profile(p_vehicle));
  source_state:=profile.get_string('state');profile_version:=profile.get_number('version');if profile_version=0 then profile_version:=null;end if;
  region_value:=RRL_GET_TT_PRICE_ID(p_trip);
  j.put('departure_operation_id',p_operation);j.put('trip_id',p_trip);j.put('warehouse_id',domain_value.get_number('warehouse'));
  j.put('vehicle_id',p_vehicle);j.put('vehicle_number',veh.NUM);j.put('task_vehicle_type',tt.TRANSTYPE);
  j.put('driver_id',tt.VODITEL_ID);j.put('carrier_company',carrier);j.put('legacy_region_key',region_value);
  j.put('profile_state',source_state);j.put('vehicle_profile',profile);
  j.put('departed_at_instant',to_char(p_instant,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
  source_wire:=j.to_clob;
  insert into RRL_TT_VEHICLE_SOURCE(TT_ID,DEPARTURE_OPERATION_ID,VEHICLE_ID,PROFILE_VERSION,SOURCE_STATE,SOURCE_JSON,CAPTURED_AT)
   values(p_trip,p_operation,p_vehicle,profile_version,source_state,source_wire,p_instant);
  g_writing:=false;
 exception when others then g_writing:=false;raise;end;
end;
/


CREATE OR REPLACE package body RRL_WAREHOUSE_MAP_API as
  function count_validation_errors(
    p_canvas_id     number,
    p_pick_route_id number
  ) return number is
    v_errors number := 0;
    v_route_topology_id number;
  begin
    select v_errors + count(*) into v_errors
      from RRL_WAREHOUSE_MAP_CAMERA
     where CANVAS_ID = p_canvas_id
       and ACTIVE = 1
       and (WIDTH_M <= 0 or DEPTH_M <= 0 or HEIGHT_M <= 0 or DEFAULT_PASSAGE_WIDTH_M <= 0);

    select v_errors + count(*) into v_errors
      from RRL_WAREHOUSE_MAP_PASSAGE
     where CANVAS_ID = p_canvas_id
       and ACTIVE = 1
       and WIDTH_M <= 0;

    select v_errors + count(*) into v_errors
      from (
        select CANVAS_ID, upper(CAMERA_CODE)
          from RRL_WAREHOUSE_MAP_CAMERA
         where CANVAS_ID = p_canvas_id
           and ACTIVE = 1
         group by CANVAS_ID, upper(CAMERA_CODE)
        having count(*) > 1
      );

    if p_pick_route_id is not null then
      begin
        select TOPOLOGY_ID into v_route_topology_id
          from RRL_PICK_ROUTE
         where PICK_ROUTE_ID = p_pick_route_id;
      exception
        when no_data_found then
          v_errors := v_errors + 1;
          v_route_topology_id := null;
      end;

      select v_errors + count(*) into v_errors
        from (
          select PICK_ROUTE_ID, PICK_SEQUENCE
            from RRL_PICK_ROUTE_CELL
           where PICK_ROUTE_ID = p_pick_route_id
             and ACTIVE = 1
           group by PICK_ROUTE_ID, PICK_SEQUENCE
          having count(*) > 1
        );

      select v_errors + count(*) into v_errors
        from (
          select PICK_ROUTE_ID, TOPOLOGY_CELL_ID
            from RRL_PICK_ROUTE_CELL
           where PICK_ROUTE_ID = p_pick_route_id
             and TOPOLOGY_CELL_ID is not null
             and ACTIVE = 1
           group by PICK_ROUTE_ID, TOPOLOGY_CELL_ID
          having count(*) > 1
        );

      select v_errors + count(*) into v_errors
        from (
          select PICK_ROUTE_ID, CELL_SLOT_ID
            from RRL_PICK_ROUTE_CELL
           where PICK_ROUTE_ID = p_pick_route_id
             and CELL_SLOT_ID is not null
             and ACTIVE = 1
           group by PICK_ROUTE_ID, CELL_SLOT_ID
          having count(*) > 1
        );

      select v_errors + count(*) into v_errors
        from RRL_PICK_ROUTE_CELL rc
        join RRL_TOPOLOGY_CELL_SLOT s
          on s.CELL_SLOT_ID = rc.CELL_SLOT_ID
       where rc.PICK_ROUTE_ID = p_pick_route_id
         and rc.ACTIVE = 1
         and s.SLOT_KIND <> 'PICK_FACE_SLOT';

      select v_errors + count(*) into v_errors
        from RRL_PICK_ROUTE_CELL rc
        join RRL_TOPOLOGY_CELL c
          on c.TOPOLOGY_CELL_ID = rc.TOPOLOGY_CELL_ID
       where rc.PICK_ROUTE_ID = p_pick_route_id
         and rc.ACTIVE = 1
         and c.CELL_KIND not in ('PICK_FACE', 'FRACTIONAL_PICK_FACE');

      select v_errors + count(*) into v_errors
        from RRL_PICK_ROUTE_CELL rc
       where rc.PICK_ROUTE_ID = p_pick_route_id
         and rc.ACTIVE = 1
         and rc.TOPOLOGY_CELL_ID is null
         and rc.CELL_SLOT_ID is null;
    end if;

    return v_errors;
  end count_validation_errors;

  function VALIDATE_DRAFT(
    p_canvas_id     number,
    p_pick_route_id number default null
  ) return clob is
    v_canvas_count number;
    v_errors number;
    v_route_rows number := 0;
    v_storage_slot_rows number := 0;
    v_non_pick_cell_rows number := 0;
  begin
    select count(*) into v_canvas_count
      from RRL_WAREHOUSE_MAP_CANVAS
     where CANVAS_ID = p_canvas_id
       and ACTIVE = 1;
    if v_canvas_count = 0 then
      return '{"valid":false,"error_count":1,"errors":["canvas_not_found"]}';
    end if;

    if p_pick_route_id is not null then
      select count(*) into v_route_rows
        from RRL_PICK_ROUTE_CELL
       where PICK_ROUTE_ID = p_pick_route_id
         and ACTIVE = 1;

      select count(*) into v_storage_slot_rows
        from RRL_PICK_ROUTE_CELL rc
        join RRL_TOPOLOGY_CELL_SLOT s
          on s.CELL_SLOT_ID = rc.CELL_SLOT_ID
       where rc.PICK_ROUTE_ID = p_pick_route_id
         and rc.ACTIVE = 1
         and s.SLOT_KIND <> 'PICK_FACE_SLOT';

      select count(*) into v_non_pick_cell_rows
        from RRL_PICK_ROUTE_CELL rc
        join RRL_TOPOLOGY_CELL c
          on c.TOPOLOGY_CELL_ID = rc.TOPOLOGY_CELL_ID
       where rc.PICK_ROUTE_ID = p_pick_route_id
         and rc.ACTIVE = 1
         and c.CELL_KIND not in ('PICK_FACE', 'FRACTIONAL_PICK_FACE');
    end if;

    v_errors := count_validation_errors(p_canvas_id, p_pick_route_id);
    return '{"valid":' || case when v_errors = 0 then 'true' else 'false' end ||
           ',"error_count":' || to_char(v_errors) ||
           ',"route_row_count":' || to_char(v_route_rows) ||
           ',"storage_slot_route_rows":' || to_char(v_storage_slot_rows) ||
           ',"non_pick_cell_route_rows":' || to_char(v_non_pick_cell_rows) ||
           '}';
  end VALIDATE_DRAFT;

  procedure PUBLISH_DRAFT(
    p_canvas_id     number,
    p_pick_route_id number default null,
    p_published_by  varchar2 default null
  ) is
    v_errors number;
    v_topology_id number;
  begin
    v_errors := count_validation_errors(p_canvas_id, p_pick_route_id);
    if v_errors > 0 then
      raise_application_error(-20420, 'Warehouse map draft validation failed: ' || to_char(v_errors));
    end if;

    update RRL_WAREHOUSE_MAP_CANVAS
       set STATUS = 'PUBLISHED',
           PUBLISHED_AT = sysdate,
           PUBLISHED_BY = substr(nvl(p_published_by, user), 1, 50),
           UPDATED_AT = sysdate,
           UPDATED_BY = substr(nvl(p_published_by, user), 1, 50)
     where CANVAS_ID = p_canvas_id
       and ACTIVE = 1;

    if sql%rowcount = 0 then
      raise_application_error(-20421, 'Canvas not found or inactive');
    end if;

    if p_pick_route_id is not null then
      select TOPOLOGY_ID into v_topology_id
        from RRL_PICK_ROUTE
       where PICK_ROUTE_ID = p_pick_route_id;

      update RRL_PICK_ROUTE
         set STATUS = 'ARCHIVED',
             ACTIVE = 0,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(nvl(p_published_by, user), 1, 50)
       where TOPOLOGY_ID = v_topology_id
         and ROUTE_KIND = 'PICK'
         and PICK_ROUTE_ID <> p_pick_route_id
         and ACTIVE = 1
         and STATUS <> 'ARCHIVED';

      update RRL_PICK_ROUTE
         set STATUS = 'PUBLISHED',
             ACTIVE = 1,
             UPDATED_AT = sysdate,
             UPDATED_BY = substr(nvl(p_published_by, user), 1, 50)
       where PICK_ROUTE_ID = p_pick_route_id;
    end if;
  end PUBLISH_DRAFT;
end RRL_WAREHOUSE_MAP_API;
/


CREATE OR REPLACE package body RRL_WAREHOUSE_TASK_ACCESS as
 procedure assert_scope(p_task number,p_actor varchar2,p_assignee varchar2 default null) is
  v_from number;v_to number;v_ware number;v_group varchar2(100);
  procedure check_user(p_user varchar2) is
  begin
   if trim(p_user) is null then raise_application_error(-20882,'TASK_ACTIVE_USER_REQUIRED');end if;
   begin
    select WARE_ID,USER_GROUP into v_ware,v_group from RUSERS
     where ID=p_user and nvl(DELETED,0)=0;
   exception when no_data_found then raise_application_error(-20882,'TASK_ACTIVE_USER_REQUIRED');end;
   if upper(trim(v_group))='GLOBAL_ADMIN' then return;end if;
   if v_ware is null or (nvl(v_from,-1)!=v_ware and nvl(v_to,-1)!=v_ware) then
    raise_application_error(-20882,'TASK_USER_WAREHOUSE_FORBIDDEN');end if;
  end;
 begin
  select FROM_WARE_ID,TO_WARE_ID into v_from,v_to from RRL_WAREHOUSE_TASK where TASK_ID=p_task;
  check_user(p_actor);
  if p_assignee is not null and p_assignee!=p_actor then check_user(p_assignee);end if;
 end;
 procedure assert_completion(p_request clob,p_actor varchar2) is
  v_doc json_object_t:=json_object_t.parse(p_request);v_source json_object_t;v_meta json_object_t;
  v_task number;v_permission varchar2(100):='warehouse_task_execute';v_task_source varchar2(40);
 begin
  v_source:=v_doc.get_object('source');v_task:=v_source.get_number('task_id');
  assert_scope(v_task,p_actor);
  v_meta:=v_doc.get_object('metadata');
  if v_meta.get_number('document_confirmation')=1 then
   select TASK_SOURCE into v_task_source from RRL_WAREHOUSE_TASK where TASK_ID=v_task;
   if v_task_source!='MES_RAW_SUPPLY' or v_task_source is null then
    raise_application_error(-20882,'MES_DOCUMENT_CONFIRM_FORBIDDEN');end if;
   v_permission:='mes_raw_transfer_confirm';
  end if;
  if RRL_HAS_WRIGHT(p_actor,v_permission)!=1 then
   raise_application_error(-20882,'TASK_CURRENT_EXECUTE_FORBIDDEN');end if;
 end;
end;
/


CREATE OR REPLACE package body RRL_WARE_DEPOT_API as
 g_tx varchar2(100);
 function write_allowed return number is begin
  if g_tx is not null and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure scope(p_ware number,p_actor varchar2)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and RRL_HAS_WRIGHT(ID,'warehouse_settings_edit')=1
   and(WARE_ID=p_ware or upper(trim(USER_GROUP))='GLOBAL_ADMIN');
  if n!=1 then raise_application_error(-20882,'WARE_DEPOT_CURRENT_WARE_ACTOR_REQUIRED');end if;
  select count(*)into n from RRL_WARES where ID=p_ware;
  if n!=1 then raise_application_error(-20886,'WARE_DEPOT_WAREHOUSE_NOT_UNIQUE');end if;
 end;
 procedure material(p_ware number,p_result out clob)is
  b json_object_t:=json_object_t();v_version number;v_addr varchar2(200);n number;lat number;lon number;
 begin
  select nvl(max(VERSION_NO),0)into v_version from RRL_WARE_DEPOT_HISTORY where WARE_ID=p_ware;
  if v_version>0 then select DEPOT_ADDR into v_addr from RRL_WARE_DEPOT_HISTORY where WARE_ID=p_ware and VERSION_NO=v_version;end if;
  b.put('warehouse_id',p_ware);b.put('version',v_version);b.put('depot_address',v_addr);
  if v_addr is not null then
   select count(*),min(SHIROTA),min(DOLGOTA)into n,lat,lon from RRL_ADDR where ADDR=v_addr and nvl(DELETED3,0)=0;
  else n:=0;end if;
  if n=1 and lat is not null and lon is not null and lat!=0 and lon!=0 and lat between -90 and 90 and lon between -180 and 180 then
   b.put('latitude',lat);b.put('longitude',lon);b.put('configured',true);b.put('status','CONFIGURED_REFERENCE');
  else
   b.put_null('latitude');b.put_null('longitude');b.put('configured',false);b.put('status',case when v_addr is null then 'NOT_CONFIGURED'else 'ADDRESS_GEOMETRY_UNKNOWN'end);
  end if;
  b.put('physical_site_verified',false);p_result:=b.to_clob;
 end;
 procedure context(p_ware number,p_actor varchar2,p_result out clob)is begin scope(p_ware,p_actor);material(p_ware,p_result);end;
 procedure apply_setting(p_operation varchar2,p_actor varchar2,p_body clob,p_result out clob)is
  b json_object_t;ware number;v_version number;v_addr varchar2(1000);v_reason varchar2(2000);hash varchar2(64);n number;
  saved RRL_WARE_DEPOT_HISTORY%rowtype;entered boolean:=false;sp boolean:=false;answer json_object_t;
 begin
  if p_operation is null or lengthb(p_operation)>100 or not regexp_like(p_operation,'^[A-Za-z0-9_.:-]+$')or p_body is null or dbms_lob.getlength(p_body)>4000 then raise_application_error(-20886,'WARE_DEPOT_REQUEST_BOUND');end if;
  b:=json_object_t.parse(p_body);ware:=b.get_number('warehouse_id');v_addr:=b.get_string('depot_address');v_reason:=b.get_string('reason');
  if b.get_size!=4 or ware is null or ware<=0 or trunc(ware)!=ware or b.get_number('expected_version')is null or b.get_number('expected_version')<0 or trunc(b.get_number('expected_version'))!=b.get_number('expected_version')
   or trim(v_reason)is null or length(trim(v_reason))<8 or length(v_reason)>500 or lengthb(v_addr)>200 then raise_application_error(-20886,'WARE_DEPOT_EXPLICIT_REQUEST_REQUIRED');end if;
  scope(ware,p_actor);hash:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'warehouse_settings_edit');entered:=true;savepoint WARE_DEPOT285;sp:=true;scope(ware,p_actor);
  begin select *into saved from RRL_WARE_DEPOT_HISTORY where OPERATION_ID=p_operation;
   if saved.WARE_ID!=ware or saved.ACTOR!=p_actor or saved.REQUEST_HASH!=hash or dbms_lob.compare(saved.REQUEST_JSON,p_body)!=0 then raise_application_error(-20886,'WARE_DEPOT_OPERATION_PAYLOAD_CONFLICT');end if;
   p_result:=saved.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;
  exception when no_data_found then null;end;
  select nvl(max(VERSION_NO),0)into v_version from RRL_WARE_DEPOT_HISTORY where WARE_ID=ware;
  if v_version!=b.get_number('expected_version')then raise_application_error(-20886,'WARE_DEPOT_VERSION_CHANGED');end if;
  if v_addr is not null then
   select count(*)into n from RRL_ADDR where ADDR=v_addr and nvl(DELETED3,0)=0 and SHIROTA between -90 and 90 and DOLGOTA between -180 and 180 and SHIROTA!=0 and DOLGOTA!=0;
   if n!=1 then raise_application_error(-20886,'WARE_DEPOT_EXISTING_GEOCODED_ADDRESS_REQUIRED');end if;
  end if;
  answer:=json_object_t();answer.put('operation_id',p_operation);answer.put('warehouse_id',ware);answer.put('version',v_version+1);
  answer.put('depot_address',v_addr);answer.put('reason',v_reason);answer.put('actor',p_actor);answer.put('stock_changed',false);answer.put('physical_site_verified',false);
  p_result:=answer.to_clob;g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_WARE_DEPOT_HISTORY(OPERATION_ID,WARE_ID,VERSION_NO,DEPOT_ADDR,ACTOR,REASON_TEXT,REQUEST_HASH,REQUEST_JSON,RESULT_JSON)
   values(p_operation,ware,v_version+1,v_addr,p_actor,v_reason,hash,p_body,p_result);
  g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
 exception when others then g_tx:=null;if sp then rollback to WARE_DEPOT285;end if;if entered then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_WAVE_EXEC_ACCESS as

 procedure assert_scope(p_wave number,p_actor varchar2,p_permission varchar2)is

  ware number;actor_ware number;grp varchar2(100);

 begin

  if p_permission not in('pick_wave_view','pick_wave_launch','pick_wave_cancel') or p_permission is null then

   raise_application_error(-20882,'WAVE_CURRENT_PERMISSION_REQUIRED');end if;

  begin select WARE_ID into ware from RRL_PICK_WAVE where PICK_WAVE_ID=p_wave;

  exception when no_data_found then raise_application_error(-20886,'WAVE_IDENTITY_MISSING');end;

  begin select WARE_ID,USER_GROUP into actor_ware,grp from RUSERS where ID=p_actor and nvl(DELETED,0)=0;

  exception when no_data_found then raise_application_error(-20882,'WAVE_ACTIVE_ACTOR_REQUIRED');end;

  if nvl(upper(trim(grp)),'-')!='GLOBAL_ADMIN' and (ware is null or actor_ware is null or actor_ware!=ware)then

   raise_application_error(-20882,'WAVE_CURRENT_WARE_FORBIDDEN');end if;

  if RRL_HAS_WRIGHT(p_actor,p_permission)!=1 then raise_application_error(-20882,'WAVE_CURRENT_ACTION_FORBIDDEN');end if;

 end;

 procedure assert_command(p_request clob,p_actor varchar2)is

  d json_object_t:=json_object_t.parse(p_request);wave number;v_disposition varchar2(100);

 begin

  if d.get_string('command_type')not in('WAVE_EXECUTION_FINISH','WAVE_PICK_RELEASE')then return;end if;

  wave:=d.get_object('source').get_number('wave_id');

  assert_scope(wave,p_actor,'pick_wave_launch');
  if d.get_string('command_type')='WAVE_PICK_RELEASE'then return;end if;

  v_disposition:=d.get_object('metadata').get_string('disposition');

  if v_disposition is not null then

   if v_disposition not in('RETURNED_TO_PLANNING','PARTIAL_SHIPPED_RETURNED')then raise_application_error(-20881,'WAVE_DISPOSITION_UNSUPPORTED');end if;

   assert_scope(wave,p_actor,'pick_wave_cancel');

   if trim(d.get_object('metadata').get_string('reason')) is null then

    raise_application_error(-20881,'WAVE_DEFER_REASON_REQUIRED');end if;

  end if;

 end;

 function decision_snapshot(p_wave number,p_allow_done number)return clob is

  j json_object_t:=json_object_t();demands json_array_t:=json_array_t();x json_object_t;

  n number;v_count number:=0;ware number;st varchar2(40);reason varchar2(100);blocked number:=0;

  procedure deny(p_reason varchar2)is begin if reason is null then reason:=p_reason;end if;blocked:=blocked+1;end;

 begin

  select WARE_ID,STATUS into ware,st from RRL_PICK_WAVE where PICK_WAVE_ID=p_wave;

  if st!='LAUNCHED'then deny('WAVE_DEFER_REQUIRES_LAUNCHED');end if;

  select count(*)into n from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=wt.PICK_TASK_ID

   where wt.PICK_WAVE_ID=p_wave;

  if n=0 or n>200 then deny('WAVE_DEFER_TASK_BOUND_1_200');end if;

  select count(*)into n from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=wt.PICK_TASK_ID

   where wt.PICK_WAVE_ID=p_wave and (pt.STATUS is null or pt.STATUS not in('CANCELLED','DONE')or(p_allow_done=0 and pt.STATUS='DONE'));

  if n>0 then deny('WAVE_DEFER_PICKING_NOT_CANCELLED');end if;

  select count(*)into n from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=wt.PICK_TASK_ID

   where wt.PICK_WAVE_ID=p_wave and pt.STATUS='CANCELLED';

  if n=0 then deny('WAVE_DEFER_CANCELLED_DEMAND_REQUIRED');end if;

  if p_allow_done=1 then

   select count(*)into n from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt on pt.PICK_TASK_ID=wt.PICK_TASK_ID

    where wt.PICK_WAVE_ID=p_wave and pt.STATUS='DONE';

   if n=0 then deny('WAVE_MIXED_COMPLETED_TASK_REQUIRED');end if;

  end if;

  select count(*)into n from RRL_CASE_PICK_TASK ct where ct.PICK_WAVE_ID=p_wave

   and (ct.STATUS is null or ct.STATUS not in('CANCELLED','SHIPPED')or(p_allow_done=0 and ct.STATUS='SHIPPED')

    or(ct.STATUS='CANCELLED'and(ct.SHIPPED_OPERATION is not null

     or exists(select 1 from RRL_CASE_CARRIER_LOT h where h.CASE_PICK_TASK_ID=ct.CASE_PICK_TASK_ID))));

  if n>0 then deny('WAVE_DEFER_CASE_NOT_RETURNED');end if;

  select count(*)into n from RRL_TARE_BOOK b where b.STATUS='HELD'and b.PLACE_KIND='CASE'

   and exists(select 1 from RRL_CASE_PICK_TASK ct where ct.PICK_WAVE_ID=p_wave and to_char(ct.CASE_PICK_TASK_ID,'TM9')=b.PLACE_ID);

  if n>0 then deny('WAVE_DEFER_TARE_BOOK_REMAINS');end if;

  select count(*)into n from RRL_WAREHOUSE_TASK where TASK_SOURCE='WAVE'and SOURCE_DOC_ID=p_wave

   and (STATUS is null or STATUS not in('DONE','CANCELLED') or (STATUS='DONE'and nvl(TASK_TYPE,'-')!='REPLENISHMENT'

    and not(p_allow_done=1 and TASK_TYPE='PICKING_MOVE'and exists(select 1 from RRL_PICK_WAVE_TASK wt join RRL_PICK_TASK pt

     on pt.PICK_TASK_ID=wt.PICK_TASK_ID where wt.PICK_WAVE_ID=p_wave and wt.PICK_WAVE_TASK_ID=RRL_WAREHOUSE_TASK.SOURCE_TASK_ID and pt.STATUS='DONE'))));

  if n>0 then deny('WAVE_DEFER_PHYSICAL_TASK_PENDING');end if;

  select count(*)into n from RRL_PICK_WAVE_REPLENISH_TASK where PICK_WAVE_ID=p_wave

   and (STATUS is null or STATUS not in('DONE','CANCELLED'));

  if n>0 then deny('WAVE_DEFER_REPLENISHMENT_PENDING');end if;

  select count(*)into n from RRL_STOCK_RESERVATION where SOURCE_DOC_TYPE='PICK_WAVE'and SOURCE_DOC_ID=p_wave

   and STATUS in('ACTIVE','ALLOCATED','PICKING')and RESERVATION_KIND='HARD'and BASE_QTY>0;

  if n>0 then deny('WAVE_DEFER_ACTIVE_HARD_REMAINS');end if;

  for r in(select pl.PICK_PLAN_LINE_ID,pl.PICK_PLAN_ID,pl.REQUESTED_QTY,cr.CUSTOMER_ORDER_ROW_ID,

    cr.CUSTOMER_ORDER_ID,cr.ARTICUL,cr.ORDER_QTY,cr.UNIT_CODE,cr.STATUS ROW_STATUS,co.STATUS ORDER_STATUS,

    nvl(cr.WARE_ID,co.WARE_ID)ROW_WARE

    from RRL_PICK_WAVE_ORDER wo join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_ID=wo.PICK_PLAN_ID

    join RRL_CUSTOMER_ORDER_ROW cr on cr.CUSTOMER_ORDER_ROW_ID=pl.CUSTOMER_ORDER_ROW_ID

    join RRL_CUSTOMER_ORDER co on co.CUSTOMER_ORDER_ID=cr.CUSTOMER_ORDER_ID

    where wo.PICK_WAVE_ID=p_wave and exists(select 1 from RRL_PICK_TASK pt where pt.PICK_PLAN_LINE_ID=pl.PICK_PLAN_LINE_ID and pt.STATUS='CANCELLED')

    order by pl.PICK_PLAN_LINE_ID fetch first 201 rows only)loop

   v_count:=v_count+1;if v_count>200 then raise_application_error(-20881,'WAVE_DEFER_DEMAND_BOUND_200');end if;

   if r.ROW_WARE!=ware or r.ROW_WARE is null or r.ORDER_QTY<=0 or r.ORDER_QTY is null

    or r.ROW_STATUS not in('OPEN','PLANNED_FULL','PLANNED_PARTIAL','NO_STOCK') or r.ROW_STATUS is null

    or r.ORDER_STATUS not in('IMPORTED','OPEN','PLANNED_FULL','PLANNED_PARTIAL','NO_STOCK')or r.ORDER_STATUS is null

    then deny('WAVE_DEFER_ORIGINAL_DEMAND_NOT_OPEN');end if;

   x:=json_object_t();x.put('pick_plan_id',r.PICK_PLAN_ID);x.put('pick_plan_line_id',r.PICK_PLAN_LINE_ID);

   x.put('order_id',r.CUSTOMER_ORDER_ID);x.put('order_line_id',r.CUSTOMER_ORDER_ROW_ID);

   x.put('article',r.ARTICUL);x.put('order_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(r.ORDER_QTY));x.put('unit',r.UNIT_CODE);

   x.put('current_planning',json_object_t.parse(RRL_STOCK_POOL_READ.line_snapshot_json(r.CUSTOMER_ORDER_ROW_ID)));x.put('row_status',r.ROW_STATUS);x.put('order_status',r.ORDER_STATUS);x.put('warehouse',r.ROW_WARE);demands.append(x);

  end loop;

  select count(*)into n from RRL_PICK_WAVE_ORDER wo join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_ID=wo.PICK_PLAN_ID where wo.PICK_WAVE_ID=p_wave

   and exists(select 1 from RRL_PICK_TASK pt where pt.PICK_PLAN_LINE_ID=pl.PICK_PLAN_LINE_ID and pt.STATUS='CANCELLED');

  if v_count=0 or v_count!=n then deny('WAVE_DEFER_ORIGINAL_DEMAND_MISSING');end if;

  select count(*)into n from RRL_CUSTOMER_ORDER_FULFILLMENT ff where exists(

   select 1 from RRL_PICK_WAVE_ORDER wo where wo.PICK_WAVE_ID=p_wave and wo.CUSTOMER_ORDER_ID=ff.CUSTOMER_ORDER_ID)

   and (ff.SHIPPED_OPERATION_ID is not null or ff.PICKED_CASE_TASK_ID is not null or ff.PICKED_WAREHOUSE_TASK_ID is not null or nvl(ff.FACT_QTY,0)>0)

   and (p_allow_done=0 or exists(select 1 from RRL_CASE_PICK_TASK ct where ct.PICK_WAVE_ID=p_wave

     and ct.STATUS='CANCELLED'and ct.CASE_PICK_TASK_ID=ff.PICKED_CASE_TASK_ID));

  if n>0 then deny('WAVE_DEFER_CURRENT_FULFILLMENT_REQUIRES_RECONCILIATION');end if;

  j.put('wave_id',p_wave);j.put('eligible',blocked=0);j.put('blocking_count',blocked);j.put('reason',reason);

  j.put('demands',demands);j.put('quantity_semantics','ORIGINAL_ORDER_DEMAND_NOT_DELIVERED');

  return j.to_clob;

 end;

 function deferred_snapshot_json(p_wave number)return clob is begin return decision_snapshot(p_wave,0);end;

 function mixed_snapshot_json(p_wave number)return clob is begin return decision_snapshot(p_wave,1);end;



end;
/


CREATE OR REPLACE package body RRL_WAVE_TIME_API as
 g_operation varchar2(100);g_tx varchar2(100);
 function write_allowed(p_operation varchar2)return number is begin
  if g_operation=p_operation and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure actor_allowed(p_actor varchar2,p_ware number,p_right varchar2)is n number;begin
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and
   (WARE_ID=p_ware or upper(trim(USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(ID,p_right)=1;
  if n!=1 then raise_application_error(-20882,'WAVE_TIME_CURRENT_WARE_RIGHT_REQUIRED');end if;
 end;
 function token(p_wave RRL_PICK_WAVE%rowtype,p_version number)return varchar2 is v_text varchar2(4000);v_hash varchar2(64);begin
  v_text:=p_wave.PICK_WAVE_ID||'|'||p_wave.WARE_ID||'|'||p_wave.ROUTE_ID||'|'||p_wave.DOCK_ID||'|'||p_wave.STATUS||'|'||
   to_char(p_wave.PLANNED_START_AT,'YYYYMMDDHH24MISS')||'|'||to_char(p_wave.PLANNED_FINISH_AT,'YYYYMMDDHH24MISS')||'|'||
   to_char(p_wave.UPDATED_AT,'YYYYMMDDHH24MISS')||'|'||p_version;
  select lower(rawtohex(standard_hash(v_text,'SHA256')))into v_hash from dual;return v_hash;
 end;
 procedure context(p_wave number,p_actor varchar2,p_result out clob)is
  w RRL_PICK_WAVE%rowtype;v_version number;p RRL_WAVE_TIME_PLAN%rowtype;b json_object_t:=json_object_t();
 begin
  select *into w from RRL_PICK_WAVE where PICK_WAVE_ID=p_wave;
  actor_allowed(p_actor,w.WARE_ID,'pick_wave_view');
  select nvl(max(VERSION_NO),0)into v_version from RRL_WAVE_TIME_PLAN where WAVE_ID=p_wave;
  b.put('wave_id',p_wave);b.put('warehouse_id',w.WARE_ID);b.put('wave_status',w.STATUS);b.put('version',v_version);
  b.put('source_token',token(w,v_version));b.put('plan_status','NO_APPROVED_PLAN');
  if v_version>0 then
   select *into p from RRL_WAVE_TIME_PLAN where WAVE_ID=p_wave and VERSION_NO=v_version;
   if w.WARE_ID=p.WARE_ID and nvl(w.ROUTE_ID,-1)=nvl(p.ROUTE_ID,-1)and nvl(w.DOCK_ID,-1)=nvl(p.DOCK_ID,-1)
     and w.PLANNED_START_AT=p.LEGACY_START_AT and w.PLANNED_FINISH_AT=p.LEGACY_FINISH_AT then
    b.put('plan_status','APPROVED');b.put('time_zone',p.TIME_ZONE);
    b.put('start_at',to_char(p.START_AT at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
    b.put('finish_at',to_char(p.FINISH_AT at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
   else b.put('plan_status','LEGACY_PLAN_CHANGED');end if;
  end if;
  p_result:=b.to_clob;
 end;
 procedure approve(p_operation varchar2,p_actor varchar2,p_body clob,p_result out clob)is
  b json_object_t;w RRL_PICK_WAVE%rowtype;saved RRL_WAVE_TIME_PLAN%rowtype;
  v_wave number;v_version number;v_hash varchar2(64);v_text varchar2(4000);v_zone varchar2(50);
  v_start timestamp with time zone;v_finish timestamp with time zone;v_legacy_start date;v_legacy_finish date;
  n number;result json_object_t:=json_object_t();v_reason varchar2(1000);v_metadata boolean:=false;
 begin
  if p_operation is null or lengthb(p_operation)>100 or p_body is null or dbms_lob.getlength(p_body)>2000 then raise_application_error(-20886,'WAVE_TIME_INPUT_BOUND');end if;
  b:=json_object_t.parse(p_body);v_wave:=b.get_number('wave_id');
  select *into w from RRL_PICK_WAVE where PICK_WAVE_ID=v_wave;actor_allowed(p_actor,w.WARE_ID,'pick_wave_launch');
  v_text:=dbms_lob.substr(p_body,2000,1);select lower(rawtohex(standard_hash(v_text,'SHA256')))into v_hash from dual;
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'pick_wave_launch');v_metadata:=true; savepoint RRL_WAVE_TIME140;
  select *into w from RRL_PICK_WAVE where PICK_WAVE_ID=v_wave for update;actor_allowed(p_actor,w.WARE_ID,'pick_wave_launch');
  begin
   select *into saved from RRL_WAVE_TIME_PLAN where OPERATION_ID=p_operation;
   if saved.ACTOR!=p_actor or saved.REQUEST_HASH!=v_hash or saved.WAVE_ID!=v_wave or saved.WARE_ID!=w.WARE_ID then raise_application_error(-20886,'WAVE_TIME_OPERATION_PAYLOAD_CONFLICT');end if;
   p_result:=saved.RESULT_JSON;RRL_STOCK_METADATA_TX.end_change;return;
  exception when no_data_found then null;end;
  select nvl(max(VERSION_NO),0)into v_version from RRL_WAVE_TIME_PLAN where WAVE_ID=v_wave;
  if b.get_number('expected_version') is null or b.get_string('source_token') is null or b.get_number('expected_version')!=v_version or b.get_string('source_token')!=token(w,v_version)then raise_application_error(-20886,'WAVE_TIME_SOURCE_CHANGED');end if;
  if w.STATUS in('DONE','CANCELLED')then raise_application_error(-20886,'WAVE_TIME_ACTIVE_PLAN_REQUIRED');end if;
  select count(*)into n from RRL_CASE_PICK_TASK where PICK_WAVE_ID=v_wave and STATUS in('IN_PROGRESS','PARTIAL');
  if n>0 then raise_application_error(-20886,'WAVE_TIME_EXECUTION_ALREADY_STARTED');end if;
  select count(*)into n from RRL_WAREHOUSE_TASK where TASK_SOURCE='WAVE'and SOURCE_DOC_ID=v_wave and STATUS='IN_PROGRESS';
  if n>0 then raise_application_error(-20886,'WAVE_TIME_EXECUTION_ALREADY_STARTED');end if;
  v_zone:=b.get_string('time_zone');
  if v_zone not in('UTC','Europe/Moscow','Asia/Tbilisi')or v_zone is null then raise_application_error(-20886,'WAVE_TIME_EXPLICIT_REGION_REQUIRED');end if;
  v_start:=to_timestamp_tz(b.get_string('start_at'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
  v_finish:=to_timestamp_tz(b.get_string('finish_at'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
  if v_start is null or v_finish is null or v_finish<=v_start or v_finish-v_start>interval '1'day then raise_application_error(-20886,'WAVE_TIME_POSITIVE_MAX24H_REQUIRED');end if;
  v_reason:=b.get_string('reason');if v_reason is null or length(v_reason)<8 or lengthb(v_reason)>1000 then raise_application_error(-20886,'WAVE_TIME_APPROVAL_REASON_REQUIRED');end if;
  select cast(v_start at time zone (v_zone) as date),cast(v_finish at time zone (v_zone) as date)into v_legacy_start,v_legacy_finish from dual;
  update RRL_PICK_WAVE set PLANNED_START_AT=v_legacy_start,PLANNED_FINISH_AT=v_legacy_finish,UPDATED_AT=sysdate,UPDATED_BY=p_actor where PICK_WAVE_ID=v_wave;
  result.put('wave_id',v_wave);result.put('warehouse_id',w.WARE_ID);result.put('version',v_version+1);
  result.put('operation_id',p_operation);result.put('plan_status','APPROVED');result.put('time_zone',v_zone);
  result.put('start_at',b.get_string('start_at'));result.put('finish_at',b.get_string('finish_at'));
  result.put('stock_changed',false);result.put('task_assignments_changed',false);result.put('capacity_certified',false);
  p_result:=result.to_clob;g_operation:=p_operation;g_tx:=dbms_transaction.local_transaction_id(false);
  insert into RRL_WAVE_TIME_PLAN(WAVE_ID,VERSION_NO,OPERATION_ID,ACTOR,REQUEST_HASH,WARE_ID,ROUTE_ID,DOCK_ID,START_AT,FINISH_AT,TIME_ZONE,LEGACY_START_AT,LEGACY_FINISH_AT,REASON,RESULT_JSON)
   values(v_wave,v_version+1,p_operation,p_actor,v_hash,w.WARE_ID,w.ROUTE_ID,w.DOCK_ID,v_start,v_finish,v_zone,v_legacy_start,v_legacy_finish,v_reason,p_result);
  g_operation:=null;g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
 exception when others then
  if v_metadata then rollback to RRL_WAVE_TIME140;end if;g_operation:=null;g_tx:=null;
  if v_metadata then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_WEIGHT_BOX_CAPACITY as
 function enabled(p_article varchar2)return number is n number;begin
  select nvl(max(SERIALIZED_WEIGHT_BOXES),0)into n from RRL_SKU_RECEIPT_POLICY where ARTICUL=p_article;return n;
 end;
 function kg_volume_upper_bound(p_cell varchar2,p_article varchar2)return number is n number;bad number;ratio number;lot_count number;
 begin
  select count(*)into lot_count from(select r.UID_POLETA from RRL_REMAINS r join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA
   join RRL_CELLS c on c.CELL=r.CELL where p.ARTICUL=p_article and r.REMAIN>0
    and c.WARE_ID=(select WARE_ID from RRL_CELLS where CELL=p_cell)and rownum<=201);
  if lot_count>200 then raise_application_error(-20881,'WEIGHT_BOX_CAPACITY_LOT_BOUND_200');end if;
  select count(*),nvl(sum(case when BOX_VOLUME_M3 is null or BOX_VOLUME_M3<=0 or BASE_QTY is null or BASE_QTY<=0 or BASE_UOM is null or BASE_UOM!='KG'then 1 else 0 end),0),max(BOX_VOLUME_M3/nullif(BASE_QTY,0))
   into n,bad,ratio from(select u.BOX_VOLUME_M3,u.BASE_QTY,u.BASE_UOM
    from RRL_REMAINS r join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA join RRL_CELLS c on c.CELL=r.CELL
    join RRL_WMS_RECEIPT_UNIT u on u.CURRENT_UID=r.UID_POLETA and u.CURRENT_CELL=r.CELL and u.STOCK_STATUS!='ISSUED'
    where p.ARTICUL=p_article and r.REMAIN>0 and c.WARE_ID=(select WARE_ID from RRL_CELLS where CELL=p_cell)and rownum<=10001);
  if n>10000 then raise_application_error(-20881,'WEIGHT_BOX_CAPACITY_UNIT_BOUND_10000');end if;
  if n=0 or bad>0 or ratio is null or ratio<=0 then raise_application_error(-20887,'WEIGHT_BOX_ACTUAL_VOLUME_EVIDENCE_REQUIRED');end if;
  return ratio;
 end;
 function physical_volume(p_uid varchar2,p_cell varchar2,p_quantity number,p_exact number default 1)return number is
  n number;bad number;qty number;volume number;
 begin
  if p_quantity=0 then return 0;end if;
  select count(*),nvl(sum(BASE_QTY),0),nvl(sum(BOX_VOLUME_M3),0),
    nvl(sum(case when BOX_VOLUME_M3 is null or BOX_VOLUME_M3<=0 or BASE_QTY is null or BASE_UOM is null or BASE_UOM!='KG'then 1 else 0 end),0)
   into n,qty,volume,bad from(select BASE_QTY,BASE_UOM,BOX_VOLUME_M3 from RRL_WMS_RECEIPT_UNIT
    where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS!='ISSUED'and rownum<=10001);
  if n>10000 then raise_application_error(-20881,'WEIGHT_BOX_CAPACITY_UNIT_BOUND_10000');end if;
  if n=0 or bad>0 or (p_exact=1 and qty!=p_quantity)or qty<p_quantity then raise_application_error(-20887,'WEIGHT_BOX_VOLUME_COMPOSITION_MUST_COVER_KG');end if;
  -- A partial arrival charges the full source-box volume conservatively; never split a box volume by average mass.
  return volume;
 end;
 function reservation_volume(p_reservation number,p_quantity number)return number is n number;bad number;qty number;volume number;
 begin
  if p_quantity=0 then return 0;end if;
  select count(*),nvl(sum(u.BASE_QTY),0),nvl(sum(u.BOX_VOLUME_M3),0),
   nvl(sum(case when u.BOX_VOLUME_M3 is null or u.BOX_VOLUME_M3<=0 or u.BASE_QTY is null or u.BASE_UOM is null or u.BASE_UOM!='KG'then 1 else 0 end),0)
   into n,qty,volume,bad from(select BASE_QTY,BASE_UOM,BOX_VOLUME_M3 from RRL_WMS_RECEIPT_UNIT u
    where u.HARD_RESERVATION_ID=p_reservation and u.STOCK_STATUS!='ISSUED'and rownum<=10001)u;
  if n>10000 then raise_application_error(-20881,'WEIGHT_BOX_CAPACITY_UNIT_BOUND_10000');end if;
  if n=0 or bad>0 or qty<p_quantity then raise_application_error(-20887,'WEIGHT_BOX_RESERVED_VOLUME_MUST_COVER_ARRIVAL_KG');end if;
  return volume;
 end;
end;
/


CREATE OR REPLACE package body RRL_WEIGHT_BOX_CHOICE_API as
 procedure clear_context is begin
  dbms_session.set_context('RRL_WEIGHT_CHOICE_CTX','TX_ID',null);
  dbms_session.set_context('RRL_WEIGHT_CHOICE_CTX','CHOICE_ID',null);
  dbms_session.set_context('RRL_WEIGHT_CHOICE_CTX','PHASE',null);
  dbms_session.set_context('RRL_WEIGHT_CHOICE_CTX','ACTOR',null);
 end;
 procedure enter_context(p_choice varchar2,p_phase varchar2,p_actor varchar2)is
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is not null or RRL_HAS_WRIGHT(p_actor,'case_pick_short_approve')!=1
   then raise_application_error(-20863,'WEIGHT_CHOICE_BUSINESS_METADATA_OWNER_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),6);
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_STOCK_POLICY_GUARD','WAREHOUSE.METADATA'));
  dbms_session.set_context('RRL_WEIGHT_CHOICE_CTX','TX_ID',dbms_transaction.local_transaction_id(true));
  dbms_session.set_context('RRL_WEIGHT_CHOICE_CTX','ACTOR',p_actor);
  dbms_session.set_context('RRL_WEIGHT_CHOICE_CTX','CHOICE_ID',p_choice);
  dbms_session.set_context('RRL_WEIGHT_CHOICE_CTX','PHASE',p_phase);
 end;
 procedure approve_request(p_request clob,p_actor varchar2,p_result out clob)is
  d json_object_t;source_json json_object_t;box_json json_object_t;candidate json_object_t;label_json json_object_t;
  boxes json_array_t;result_json json_object_t:=json_object_t();
  old RRL_PICK_WEIGHT_CHOICE%rowtype;
  choice_value varchar2(100);key_value varchar2(64);mode_value varchar2(24);reason_value varchar2(4000);
  row_id number;order_id number;ware number;article varchar2(160);uid varchar2(150);cell_value varchar2(60);stock_version number;
  mass number;version number;pct number;requested number;remaining number;signature_value varchar2(64);n number;
  source_wire clob;result_wire clob;
 begin
  if p_request is null or dbms_lob.getlength(p_request)>16000 then raise_application_error(-20881,'WEIGHT_CHOICE_REQUEST_BOUND');end if;
  d:=json_object_t.parse(p_request);choice_value:=d.get_string('choice_id');row_id:=d.get_number('customer_order_row_id');
  if choice_value is null or length(choice_value)>100 or not regexp_like(choice_value,'^[A-Za-z0-9_.:-]+$')
   or row_id is null or row_id<1 or row_id!=trunc(row_id)then raise_application_error(-20881,'WEIGHT_CHOICE_IDENTITY_REQUIRED');end if;
  select CUSTOMER_ORDER_ID,ARTICUL into order_id,article from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ROW_ID=row_id;
  RRL_PICK_PLAN_ACCESS.assert_scope(order_id,p_actor,'case_pick_short_approve');
  select WARE_ID into ware from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=order_id;
  select count(*)into n from RRL_PICK_WEIGHT_CHOICE where CHOICE_ID=choice_value;
  if n>0 then
   select *into old from RRL_PICK_WEIGHT_CHOICE where CHOICE_ID=choice_value;
   if old.APPROVED_BY!=p_actor or old.CUSTOMER_ORDER_ROW_ID!=row_id or dbms_lob.compare(old.REQUEST_JSON,p_request)!=0
    then raise_application_error(-20873,'WEIGHT_CHOICE_ID_CONTENT_CONFLICT');end if;
   if old.WARE_ID!=ware then raise_application_error(-20882,'WEIGHT_CHOICE_ORIGINAL_WARE_CHANGED');end if;
   p_result:=old.RESULT_JSON;return;
  end if;
  source_wire:=RRL_WEIGHT_BOX_PLANNING_READ.snapshot_json(row_id,p_actor,'case_pick_short_approve');source_json:=json_object_t.parse(source_wire);
  signature_value:=source_json.get_string('source_signature');
  if d.get_string('source_signature')is null or d.get_string('source_signature')!=signature_value
   then raise_application_error(-20886,'WEIGHT_CHOICE_CURRENT_SOURCE_CHANGED');end if;
  remaining:=RRL_STOCK_MATH.quantity(source_json.get_string('remaining_row_quantity'));
  key_value:=d.get_string('physical_unit_key');boxes:=source_json.get_array('boxes');n:=0;
  for i in 0..boxes.get_size-1 loop
   candidate:=treat(boxes.get(i)as json_object_t);
   if candidate.get_string('physical_unit_key')=key_value then box_json:=candidate;n:=n+1;end if;
  end loop;
  if n!=1 or box_json is null then raise_application_error(-20886,'WEIGHT_CHOICE_CURRENT_AVAILABLE_BOX_REQUIRED');end if;
  if not box_json.get_boolean('measurements_ready')then raise_application_error(-20886,'WEIGHT_CHOICE_PHYSICAL_MEASUREMENTS_REQUIRED');end if;
  label_json:=json_object_t.parse(RRL_WEIGHT_BOX_READ.decode_json(d.get_string('weighted_box_barcode')));
  RRL_WEIGHT_BOX_READ.assert_sku(article,label_json.get_string('gtin'));
  mass:=RRL_STOCK_MATH.quantity(box_json.get_string('net_weight_kg'));
  if label_json.get_string('identity')!=box_json.get_string('unit_id') or RRL_STOCK_MATH.quantity(label_json.get_string('net_weight_kg'))!=mass
   then raise_application_error(-20886,'WEIGHT_CHOICE_SAME_SCANNED_WHOLE_BOX_REQUIRED');end if;
  mode_value:=d.get_string('choice_mode');reason_value:=d.get_string('reason');
  if reason_value is null or length(trim(reason_value))<3 or length(reason_value)>1000 then raise_application_error(-20886,'WEIGHT_CHOICE_REASON_REQUIRED');end if;
  if mode_value is null or mode_value not in('WITHIN_TOLERANCE','LAST_WHOLE_BOX')
   or(mode_value='WITHIN_TOLERANCE'and not box_json.get_boolean('within_tolerance'))
   or(mode_value='LAST_WHOLE_BOX'and not box_json.get_boolean('exception_required'))
   then raise_application_error(-20886,'WEIGHT_CHOICE_MATCHING_EXPLICIT_DECISION_REQUIRED');end if;
  uid:=box_json.get_string('pallet_identifier');cell_value:=box_json.get_string('source_cell');stock_version:=box_json.get_number('stock_version');
  version:=source_json.get_number('policy_version');pct:=source_json.get_number('tolerance_pct');
  requested:=RRL_STOCK_MATH.quantity(source_json.get_string('requested_order_quantity'));
  result_json.put('choice_id',choice_value);result_json.put('customer_order_row_id',row_id);result_json.put('physical_unit_key',key_value);
  result_json.put('pallet_identifier',uid);result_json.put('source_cell',cell_value);result_json.put('selected_net_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(mass));
  result_json.put('original_order_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(requested));
  result_json.put('choice_mode',mode_value);result_json.put('status','ACCEPTED');result_json.put('stock_changed',false);result_json.put('plan_created',false);result_json.put('no_split',true);
  result_wire:=result_json.to_clob;
  enter_context(choice_value,'APPROVE',p_actor);
  insert into RRL_PICK_WEIGHT_CHOICE(CHOICE_ID,CUSTOMER_ORDER_ROW_ID,CUSTOMER_ORDER_ID,WARE_ID,ARTICLE,PHYSICAL_UNIT_KEY,SOURCE_UID,SOURCE_CELL,STOCK_VERSION,
   NET_WEIGHT_KG,POLICY_VERSION,TOLERANCE_PCT,ORIGINAL_ORDER_KG,ORIGINAL_REMAINING_KG,CHOICE_MODE,APPROVED_BY,REASON_TEXT,SOURCE_SIGNATURE,SOURCE_JSON,REQUEST_JSON,RESULT_JSON)
   values(choice_value,row_id,order_id,ware,article,key_value,uid,cell_value,stock_version,mass,version,pct,requested,remaining,mode_value,p_actor,reason_value,signature_value,source_wire,p_request,result_wire);
  clear_context;p_result:=result_wire;
 exception when others then clear_context;raise;
 end;
 procedure cancel_choice(p_choice varchar2,p_actor varchar2,p_reason varchar2,p_result out clob)is
  old RRL_PICK_WEIGHT_CHOICE%rowtype;result_json json_object_t:=json_object_t();active_tasks number;
 begin
  select *into old from RRL_PICK_WEIGHT_CHOICE where CHOICE_ID=p_choice for update;
  RRL_PICK_PLAN_ACCESS.assert_scope(old.CUSTOMER_ORDER_ID,p_actor,'case_pick_short_approve');
  if old.STATUS='USED'then
   select count(*)into active_tasks from RRL_PICK_TASK where PICK_PLAN_LINE_ID=old.PICK_PLAN_LINE_ID and STATUS not in('CANCELLED','FAILED');
   if active_tasks>0 then raise_application_error(-20886,'WEIGHT_CHOICE_CANCEL_ASSOCIATED_PLAN_FIRST');end if;
  end if;
  if old.STATUS='CANCELLED'then
   if old.CANCELLED_BY!=p_actor or old.CANCEL_REASON!=p_reason then raise_application_error(-20873,'WEIGHT_CHOICE_CANCEL_CONTENT_CONFLICT');end if;
  else
   if p_reason is null or length(trim(p_reason))<3 or length(p_reason)>1000 then raise_application_error(-20886,'WEIGHT_CHOICE_CANCEL_REASON_REQUIRED');end if;
   enter_context(p_choice,'CANCEL',p_actor);
   update RRL_PICK_WEIGHT_CHOICE set STATUS='CANCELLED',CANCELLED_BY=p_actor,CANCELLED_AT=systimestamp,CANCEL_REASON=p_reason where CHOICE_ID=p_choice;
   clear_context;
  end if;
  result_json.put('choice_id',p_choice);result_json.put('status','CANCELLED');result_json.put('stock_changed',false);p_result:=result_json.to_clob;
 exception when others then clear_context;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_WEIGHT_BOX_PLANNING_READ as
 function snapshot_json(p_row number,p_actor varchar2,p_permission varchar2 default 'pick_plan_create')return clob is
  o RRL_CUSTOMER_ORDER_ROW%rowtype;ware number;version number;pct number;marked number;serial_flag number;
  demand json_object_t;part json_object_t;result_json json_object_t:=json_object_t();item json_object_t;
  boxes json_array_t:=json_array_t();requested number:=0;actual number:=0;remaining number;soft_qty number;projected number;
  lower_qty number;upper_qty number;rows_count number:=0;stocks_count number:=0;more_boxes boolean:=false;state_value varchar2(20);
 begin
  if p_row is null or p_row<1 or p_row!=trunc(p_row)then raise_application_error(-20881,'WEIGHT_BOX_ORDER_ROW_REQUIRED');end if;
  select *into o from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ROW_ID=p_row;
  if p_permission is null or p_permission not in('pick_plan_create','case_pick_short_approve')then raise_application_error(-20882,'WEIGHT_BOX_PREVIEW_PERMISSION_REQUIRED');end if;
  RRL_PICK_PLAN_ACCESS.assert_scope(o.CUSTOMER_ORDER_ID,p_actor,p_permission);
  select WARE_ID into ware from RRL_CUSTOMER_ORDER where CUSTOMER_ORDER_ID=o.CUSTOMER_ORDER_ID;
  select STATE into state_value from RRL_STOCK_RELEASE where RELEASE_ID=1;
  if state_value is null or state_value!='ACTIVE'then raise_application_error(-20860,'WEIGHT_BOX_PLANNING_ACTIVE_REQUIRED');end if;
  select POLICY_VERSION,ORDER_WEIGHT_TOLERANCE_PCT,MARKING_REQUIRED,SERIALIZED_WEIGHT_BOXES into version,pct,marked,serial_flag
   from RRL_SKU_RECEIPT_POLICY where ARTICUL=o.ARTICUL;
  if serial_flag!=1 then raise_application_error(-20886,'WEIGHT_BOX_PLANNING_SERIALIZED_SKU_REQUIRED');end if;
  RRL_WEIGHT_BOX_READ.assert_sku(o.ARTICUL,null);
  demand:=json_object_t.parse(RRL_STOCK_POOL_READ.line_snapshot_json(p_row));
  if not demand.get_boolean('open')or demand.get_string('unit')!='KG' or demand.get_number('warehouse')!=ware then raise_application_error(-20886,'WEIGHT_BOX_OPEN_CURRENT_KG_ORDER_REQUIRED');end if;
  remaining:=case when demand.get_string('quantity')='0'then 0 else RRL_STOCK_MATH.quantity(demand.get_string('quantity'))end;
  select nvl(sum(pr.RESERVED_QTY),0)into soft_qty from RRL_PICK_RESERVATION pr
   join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=pr.PICK_PLAN_LINE_ID join RRL_PICK_PLAN pp on pp.PICK_PLAN_ID=pl.PICK_PLAN_ID
   where pl.CUSTOMER_ORDER_ROW_ID=p_row and pr.RESERVATION_STATUS='ACTIVE'and pr.RESERVATION_LEVEL='SOFT'
    and pp.STATUS in('DRAFT','PLANNED_FULL','PLANNED_PARTIAL');
  remaining:=greatest(remaining-soft_qty,0);
  for cr in(select CUSTOMER_ORDER_ROW_ID from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ID=o.CUSTOMER_ORDER_ID and ARTICUL=o.ARTICUL
   and STATUS not in('CANCELLED','REJECTED')order by CUSTOMER_ORDER_ROW_ID fetch first 201 rows only)loop
   rows_count:=rows_count+1;if rows_count>200 then raise_application_error(-20881,'WEIGHT_BOX_ORDER_ROWS_BOUND');end if;
   part:=json_object_t.parse(RRL_STOCK_POOL_READ.line_snapshot_json(cr.CUSTOMER_ORDER_ROW_ID));
   if part.get_string('unit')!='KG'or part.get_number('warehouse')!=ware then raise_application_error(-20886,'WEIGHT_BOX_ORDER_SKU_KG_SOURCE_REQUIRED');end if;
   requested:=requested+RRL_STOCK_MATH.quantity(part.get_string('requested_base_quantity'));
   if part.get_string('picked_quantity')!='0'then actual:=actual+RRL_STOCK_MATH.quantity(part.get_string('picked_quantity'));end if;
  end loop;
  lower_qty:=requested*(1-pct/100);upper_qty:=requested*(1+pct/100);
  if remaining>0 then
   for lot in(select r.UID_POLETA,r.CELL,r.REMAIN,r.HARD_RESERVED_BASE,r.STOCK_VERSION,p.EXPIRY_DATE
    from RRL_REMAINS r join RRL_PALLETS p on p.UID_PALLET=r.UID_POLETA join RRL_CELLS c on c.CELL=r.CELL
    where p.ARTICUL=o.ARTICUL and c.WARE_ID=ware and r.BASE_UOM='KG'and r.REMAIN-r.HARD_RESERVED_BASE>0
     and RRL_STOCK_ELIGIBILITY.reason(r.UID_POLETA,r.CELL,ware,0,null,null,'ALLOCATE',null,o.ARTICUL)is null
    order by p.EXPIRY_DATE nulls last,r.UID_POLETA,r.CELL fetch first 201 rows only)loop
    stocks_count:=stocks_count+1;if stocks_count>200 then more_boxes:=true;exit;end if;
    for unit_row in(select PHYSICAL_UNIT_KEY,BASE_QTY,GROSS_WEIGHT_KG,BOX_VOLUME_M3,MEASUREMENT_REFERENCE,WEIGHT_LABEL_SCAN,UNIT_ID
     from RRL_WMS_RECEIPT_UNIT where CURRENT_UID=lot.UID_POLETA and CURRENT_CELL=lot.CELL
      and STOCK_STATUS='AVAILABLE'and HARD_RESERVATION_ID is null and BASE_UOM='KG'and BASE_QTY>0
      and BASE_QTY<=lot.REMAIN-lot.HARD_RESERVED_BASE
     order by PHYSICAL_UNIT_KEY fetch first 101 rows only)loop
     if boxes.get_size=100 then more_boxes:=true;exit;end if;
     projected:=actual+unit_row.BASE_QTY;
     item:=json_object_t();item.put('physical_unit_key',unit_row.PHYSICAL_UNIT_KEY);item.put('unit_id',unit_row.UNIT_ID);
     item.put('pallet_identifier',lot.UID_POLETA);item.put('source_cell',lot.CELL);item.put('stock_version',lot.STOCK_VERSION);
     item.put('net_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(unit_row.BASE_QTY));
     item.put('gross_weight_kg',case when unit_row.GROSS_WEIGHT_KG is null then null else RRL_STOCK_PLAN_HELPER.decimal_text(unit_row.GROSS_WEIGHT_KG)end);
     item.put('volume_m3',case when unit_row.BOX_VOLUME_M3 is null then null else RRL_STOCK_PLAN_HELPER.decimal_text(unit_row.BOX_VOLUME_M3)end);
     item.put('weighted_box_barcode',unit_row.WEIGHT_LABEL_SCAN);item.put('measurement_reference',unit_row.MEASUREMENT_REFERENCE);
     item.put('projected_order_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(projected));
     item.put('within_tolerance',projected>=lower_qty and projected<=upper_qty);
     item.put('exception_required',projected<lower_qty or projected>upper_qty);
     item.put('measurements_ready',unit_row.GROSS_WEIGHT_KG is not null and unit_row.GROSS_WEIGHT_KG>=unit_row.BASE_QTY
      and unit_row.BOX_VOLUME_M3 is not null and unit_row.BOX_VOLUME_M3>0 and unit_row.MEASUREMENT_REFERENCE is not null and unit_row.WEIGHT_LABEL_SCAN is not null);
     boxes.append(item);
    end loop;
    exit when more_boxes;
   end loop;
  end if;
  result_json.put('customer_order_row_id',p_row);result_json.put('customer_order_id',o.CUSTOMER_ORDER_ID);
  result_json.put('article',o.ARTICUL);result_json.put('warehouse_id',ware);result_json.put('policy_version',version);
  result_json.put('tolerance_pct',RRL_STOCK_PLAN_HELPER.decimal_text(pct));result_json.put('unit','KG');
  result_json.put('requested_order_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(requested));result_json.put('picked_order_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(actual));
  result_json.put('remaining_row_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(remaining));result_json.put('active_soft_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(soft_qty));
  result_json.put('marking_required',marked=1);result_json.put('no_split',true);result_json.put('boxes',boxes);result_json.put('has_more',more_boxes);
  result_json.put('choice_saved',false);result_json.put('approval_required',true);
  result_json.put('source_signature',rawtohex(sys.dbms_crypto.hash(result_json.to_clob,sys.dbms_crypto.hash_sh256)));
  return result_json.to_clob;
 exception when no_data_found or too_many_rows then raise_application_error(-20886,'WEIGHT_BOX_CURRENT_ORDER_OR_POLICY_NOT_UNIQUE');
 end;
end;
/


CREATE OR REPLACE package body RRL_WEIGHT_BOX_READ as
 procedure assert_sku(p_article varchar2,p_gtin varchar2 default null)is n number;begin
  select count(*)into n from RRL_ARTICULS a where a.ACTICUL=p_article and a.TYPE_W in(2,3,5,6,7)
   and exists(select 1 from RRL_STOCK_UOM_CONVERSION u where u.ARTICUL=a.ACTICUL and u.BASE_UOM='KG'and u.INPUT_UOM='KG'and u.NUMERATOR=1 and u.DENOMINATOR=1)
   and(p_gtin is null
    or (regexp_like(a.BARCODE_SHT,'^([0-9]{8}|[0-9]{12}|[0-9]{13}|[0-9]{14})$','c')and p_gtin=lpad(a.BARCODE_SHT,14,'0'))
    or (regexp_like(a.BARCODE_KOR,'^([0-9]{8}|[0-9]{12}|[0-9]{13}|[0-9]{14})$','c')and p_gtin=lpad(a.BARCODE_KOR,14,'0'))
    or (regexp_like(a.BARCODE_BL,'^([0-9]{8}|[0-9]{12}|[0-9]{13}|[0-9]{14})$','c')and p_gtin=lpad(a.BARCODE_BL,14,'0')));
  if n!=1 then raise_application_error(-20886,'WEIGHT_BOX_CURRENT_KG_SKU_AND_GTIN_REQUIRED');end if;
 end;
 function decode_json(p_scan varchar2)return clob is
  v varchar2(512);pos number:=1;stop number;data_start number;ai varchar2(512);data_value varchar2(512);fixed_size number;
  gtin varchar2(14);serial varchar2(20);mass number;digits number;sum_check number:=0;human boolean;seen json_object_t:=json_object_t();j json_object_t:=json_object_t();
 begin
  if p_scan is null or lengthb(p_scan)>512 or instr(p_scan,chr(0))>0 then raise_application_error(-20886,'WEIGHT_BOX_SCAN_BOUND_512');end if;
  v:=p_scan;
  if substr(v,1,3)in(']C1',']d2')then v:=substr(v,4);end if;human:=substr(v,1,1)='(';
  while pos<=length(v)loop
   if seen.get_size>=3 then raise_application_error(-20886,'WEIGHT_BOX_ONLY_AI01_310N_21_SUPPORTED');end if;
   if human then
    if substr(v,pos,1)!='('then raise_application_error(-20886,'WEIGHT_BOX_HRI_AI_REQUIRED');end if;
    stop:=instr(v,')',pos);if stop=0 then raise_application_error(-20886,'WEIGHT_BOX_HRI_AI_REQUIRED');end if;
    ai:=substr(v,pos+1,stop-pos-1);data_start:=stop+1;stop:=instr(v,'(',data_start);
    if stop=0 then stop:=length(v)+1;end if;data_value:=substr(v,data_start,stop-data_start);pos:=stop;
   else
    ai:=case when substr(v,pos,3)='310'then substr(v,pos,4)else substr(v,pos,2)end;pos:=pos+length(ai);
    fixed_size:=case when ai='01'then 14 when regexp_like(ai,'^310[0-5]$','c')then 6 end;
    if fixed_size is not null then data_value:=substr(v,pos,fixed_size);pos:=pos+fixed_size;
    elsif ai='21'then
     stop:=instr(v,chr(29),pos);if stop=0 then stop:=length(v)+1;end if;
     data_value:=substr(v,pos,stop-pos);pos:=stop;
    else raise_application_error(-20886,'WEIGHT_BOX_UNSUPPORTED_AI');end if;
    if substr(v,pos,1)=chr(29)then pos:=pos+1;end if;
   end if;
   if seen.has(ai)then raise_application_error(-20886,'WEIGHT_BOX_DUPLICATE_AI');end if;seen.put(ai,true);
   if ai='01'then
    if gtin is not null or not regexp_like(data_value,'^[0-9]{14}$','c')then raise_application_error(-20886,'WEIGHT_BOX_GTIN14_REQUIRED');end if;gtin:=data_value;
   elsif regexp_like(ai,'^310[0-5]$','c')then
    if mass is not null or not regexp_like(data_value,'^[0-9]{6}$','c')then raise_application_error(-20886,'WEIGHT_BOX_ONE_NET_KG_REQUIRED');end if;
    digits:=to_number(substr(ai,4,1));mass:=to_number(data_value)/power(10,digits);
    if mass<=0 then raise_application_error(-20886,'WEIGHT_BOX_POSITIVE_NET_KG_REQUIRED');end if;
   elsif ai='21'then
    if serial is not null or data_value is null or lengthb(data_value)>20 then raise_application_error(-20886,'WEIGHT_BOX_UNIQUE_SERIAL_REQUIRED');end if;
    for i in 1..length(data_value)loop if ascii(substr(data_value,i,1))<33 or ascii(substr(data_value,i,1))>126 then raise_application_error(-20886,'WEIGHT_BOX_SERIAL_ASCII_REQUIRED');end if;end loop;
    serial:=data_value;
   else raise_application_error(-20886,'WEIGHT_BOX_ONLY_AI01_310N_21_SUPPORTED');end if;
  end loop;
  if gtin is null or serial is null or mass is null then raise_application_error(-20886,'WEIGHT_BOX_GTIN_WEIGHT_SERIAL_REQUIRED');end if;
  for i in 1..13 loop sum_check:=sum_check+to_number(substr(gtin,i,1))*case when mod(i,2)=1 then 3 else 1 end;end loop;
  if to_number(substr(gtin,14,1))!=mod(10-mod(sum_check,10),10)then raise_application_error(-20886,'WEIGHT_BOX_GTIN_CHECK_DIGIT_INVALID');end if;
  j.put('raw_scan',p_scan);j.put('gtin',gtin);j.put('serial',serial);j.put('identity','01'||gtin||'21'||serial);j.put('net_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(mass));j.put('physical_box_count',1);j.put('weight_source','GS1_LABEL_NET_KG');j.put('government_confirmation',false);return j.to_clob;
 end;
end;
/


CREATE OR REPLACE package body RRL_WEIGHT_CHOICE_DEMAND_READ as
 procedure adjustments(p_line number,p_unallocated number,p_pending out number,p_waived out number)is
  c RRL_PICK_WEIGHT_CHOICE%rowtype;o RRL_CUSTOMER_ORDER_ROW%rowtype;
  n number;requested number:=0;actual number:=0;own_actual number:=0;own_requested number:=0;
  num number;den number;scale number;mass number;tasks number:=0;done_tasks number:=0;pending_tasks number:=0;
  selected_actual number:=0;soft_qty number:=0;physical_proof number:=0;source_json json_object_t;original_actual number;
 begin
  p_pending:=0;p_waived:=0;
  if p_unallocated<=0 then return;end if;
  select count(*)into n from RRL_PICK_WEIGHT_CHOICE
   where case when STATUS in('ACCEPTED','USED')then CUSTOMER_ORDER_ROW_ID end=p_line and STATUS='USED';
  if n=0 then return;end if;
  if n!=1 then raise_application_error(-20887,'WEIGHT_CHOICE_DEMAND_SINGLE_ACTIVE_ROW_REQUIRED');end if;
  select *into c from RRL_PICK_WEIGHT_CHOICE
   where case when STATUS in('ACCEPTED','USED')then CUSTOMER_ORDER_ROW_ID end=p_line and STATUS='USED';
  select *into o from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ROW_ID=p_line;
  if o.STATUS in('CANCELLED','REJECTED')or o.CUSTOMER_ORDER_ID!=c.CUSTOMER_ORDER_ID or o.ARTICUL!=c.ARTICLE then return;end if;
  n:=0;
  for cr in(select CUSTOMER_ORDER_ROW_ID,ORDER_QTY,UNIT_CODE from RRL_CUSTOMER_ORDER_ROW
   where CUSTOMER_ORDER_ID=o.CUSTOMER_ORDER_ID and ARTICUL=o.ARTICUL and STATUS not in('CANCELLED','REJECTED')
   order by CUSTOMER_ORDER_ROW_ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20881,'WEIGHT_CHOICE_DEMAND_ROWS_BOUND');end if;
   select NUMERATOR,DENOMINATOR,BASE_SCALE into num,den,scale from RRL_STOCK_UOM_CONVERSION
    where ARTICUL=o.ARTICUL and INPUT_UOM=cr.UNIT_CODE and BASE_UOM='KG'order by POLICY_VERSION desc fetch first 1 row only;
   mass:=RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(cr.ORDER_QTY),num,den,scale);
   requested:=requested+mass;if cr.CUSTOMER_ORDER_ROW_ID=p_line then own_requested:=mass;end if;
  end loop;
  if requested!=c.ORIGINAL_ORDER_KG then return;end if;
  n:=0;
  for pt in(select pt.PICK_TASK_ID,pt.STATUS,pt.FACT_QTY,pt.QTY,pt.PICK_PLAN_LINE_ID,pl.CUSTOMER_ORDER_ROW_ID
   from RRL_PICK_TASK pt join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=pt.PICK_PLAN_LINE_ID
   join RRL_CUSTOMER_ORDER_ROW cr on cr.CUSTOMER_ORDER_ROW_ID=pl.CUSTOMER_ORDER_ROW_ID
   where cr.CUSTOMER_ORDER_ID=o.CUSTOMER_ORDER_ID and cr.ARTICUL=o.ARTICUL and cr.STATUS not in('CANCELLED','REJECTED')
   order by pt.PICK_TASK_ID fetch first 2001 rows only)loop
   n:=n+1;if n>2000 then raise_application_error(-20881,'WEIGHT_CHOICE_DEMAND_TASKS_BOUND');end if;
   if pt.STATUS in('IN_PROGRESS','DONE')then
    actual:=actual+nvl(pt.FACT_QTY,0);
    if pt.CUSTOMER_ORDER_ROW_ID=p_line then own_actual:=own_actual+nvl(pt.FACT_QTY,0);end if;
   end if;
   if pt.PICK_PLAN_LINE_ID=c.PICK_PLAN_LINE_ID and pt.STATUS not in('CANCELLED','FAILED')then
    tasks:=tasks+1;if pt.QTY!=c.NET_WEIGHT_KG then return;end if;
    if pt.STATUS='DONE'then done_tasks:=done_tasks+1;selected_actual:=selected_actual+nvl(pt.FACT_QTY,0);
    elsif pt.STATUS in('NEW','ASSIGNED','IN_PROGRESS')then pending_tasks:=pending_tasks+1;end if;
   end if;
  end loop;
  if tasks!=1 then return;end if;
  source_json:=json_object_t.parse(c.SOURCE_JSON);
  if source_json.get_string('picked_order_quantity')='0'then original_actual:=0;else original_actual:=RRL_STOCK_MATH.quantity(source_json.get_string('picked_order_quantity'));end if;
  if done_tasks=1 and selected_actual=c.NET_WEIGHT_KG and actual=original_actual+c.NET_WEIGHT_KG then
   select count(*)into physical_proof from RRL_CASE_PICK_LINE l join RRL_CASE_PICK_TASK ct on ct.CASE_PICK_TASK_ID=l.CASE_PICK_TASK_ID
    join RRL_WMS_RECEIPT_UNIT u on u.PHYSICAL_UNIT_KEY=c.PHYSICAL_UNIT_KEY
    where l.PICK_PLAN_LINE_ID=c.PICK_PLAN_LINE_ID and l.PICKED_QTY=c.NET_WEIGHT_KG and ct.STATUS!='CANCELLED'
     and u.BASE_QTY=c.NET_WEIGHT_KG;
   if physical_proof=1 and(c.CHOICE_MODE='LAST_WHOLE_BOX'or
    (actual>=requested*(1-c.TOLERANCE_PCT/100)and actual<=requested*(1+c.TOLERANCE_PCT/100)))then
    p_waived:=least(p_unallocated,greatest(own_requested-own_actual,0));
   end if;
  elsif pending_tasks=1 then
   select nvl(sum(RESERVED_QTY),0)into soft_qty from RRL_PICK_RESERVATION
    where PICK_PLAN_LINE_ID=c.PICK_PLAN_LINE_ID and RESERVATION_STATUS='ACTIVE'and RESERVATION_LEVEL='SOFT';
   select count(*)into physical_proof from RRL_WMS_RECEIPT_UNIT u join RRL_STOCK_RESERVATION sr on sr.RESERVATION_ID=u.HARD_RESERVATION_ID
    where u.PHYSICAL_UNIT_KEY=c.PHYSICAL_UNIT_KEY and u.BASE_QTY=c.NET_WEIGHT_KG
     and sr.PICK_PLAN_LINE_ID=c.PICK_PLAN_LINE_ID and sr.RESERVATION_KIND='HARD'and sr.STATUS in('ACTIVE','ALLOCATED','PICKING');
   if soft_qty=c.NET_WEIGHT_KG or physical_proof=1 then p_pending:=p_unallocated;end if;
  end if;
 exception when no_data_found then raise_application_error(-20868,'WEIGHT_CHOICE_CURRENT_ORDER_OR_KG_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_WEIGHT_CHOICE_UNIT_READ as
 function selected_units(p_task number,p_uid varchar2,p_cell varchar2,p_qty number)return clob is
  c RRL_PICK_WEIGHT_CHOICE%rowtype;u RRL_WMS_RECEIPT_UNIT%rowtype;
  n number;line_id number;policy_version number;serialized number;available_qty number;a json_array_t:=json_array_t();
 begin
  if p_task is null then return null;end if;
  select PICK_PLAN_LINE_ID into line_id from RRL_PICK_TASK where PICK_TASK_ID=p_task;
  select count(*)into n from RRL_PICK_WEIGHT_CHOICE where PICK_PLAN_LINE_ID=line_id and STATUS='USED';
  if n=0 then return null;end if;
  if n!=1 then raise_application_error(-20886,'WEIGHT_CHOICE_SINGLE_BOUND_UNIT_REQUIRED');end if;
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null
   or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)
   then raise_application_error(-20863,'WEIGHT_CHOICE_NATIVE_POSTING_CONTEXT_REQUIRED');end if;
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',p_uid));
  select *into c from RRL_PICK_WEIGHT_CHOICE where PICK_PLAN_LINE_ID=line_id and STATUS='USED';
  select POLICY_VERSION,SERIALIZED_WEIGHT_BOXES into policy_version,serialized from RRL_SKU_RECEIPT_POLICY where ARTICUL=c.ARTICLE;
  if serialized!=1 or policy_version!=c.POLICY_VERSION then raise_application_error(-20886,'WEIGHT_CHOICE_CURRENT_SKU_POLICY_CHANGED');end if;
  select *into u from RRL_WMS_RECEIPT_UNIT where PHYSICAL_UNIT_KEY=c.PHYSICAL_UNIT_KEY;
  if u.CURRENT_UID!=p_uid or u.CURRENT_CELL!=p_cell or u.STOCK_STATUS!='AVAILABLE'or u.HARD_RESERVATION_ID is not null
   or u.BASE_QTY!=c.NET_WEIGHT_KG then raise_application_error(-20886,'WEIGHT_CHOICE_SELECTED_UNIT_UNAVAILABLE');end if;
  if p_qty=c.NET_WEIGHT_KG then a.append(c.PHYSICAL_UNIT_KEY);return a.to_clob;end if;
  -- A source full-pallet reservation may include the chosen box together with every other free box.
  -- Smaller partial substitutions must never silently replace the approved physical key.
  select nvl(sum(BASE_QTY),0)into available_qty from RRL_WMS_RECEIPT_UNIT
   where CURRENT_UID=p_uid and CURRENT_CELL=p_cell and STOCK_STATUS='AVAILABLE'and HARD_RESERVATION_ID is null;
  if p_qty>c.NET_WEIGHT_KG and p_qty=available_qty then return null;end if;
  raise_application_error(-20886,'WEIGHT_CHOICE_EXACT_BOX_OR_WHOLE_SOURCE_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_WEIGHT_DEVIATION_READ as
 function waived_line(p_line number)return number is
  o RRL_CUSTOMER_ORDER_ROW%rowtype;
  requested number:=0;actual number:=0;own_requested number:=0;own_actual number:=0;waived number:=0;mass number;
  num number;den number;scale number;n number:=0;decisions number:=0;
 begin
  select *into o from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ROW_ID=p_line;
  select count(*)into n from RRL_CASE_PICK_SHORT sh join RRL_CASE_PICK_LINE l on l.CASE_PICK_LINE_ID=sh.CASE_PICK_LINE_ID
   join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=l.PICK_PLAN_LINE_ID
   join RRL_PICK_TASK pt on pt.PICK_TASK_ID=l.PICK_TASK_ID
   where pl.CUSTOMER_ORDER_ROW_ID=p_line and sh.STATUS='ACCEPTED'and sh.WEIGHT_DECISION_OPERATION is not null
    and l.STATUS='SHORT_PICKED'and pt.STATUS='DONE';
  if n=0 then return 0;end if;
  if o.STATUS in('CANCELLED','REJECTED')then return 0;end if;
  n:=0;
  for cr in(select CUSTOMER_ORDER_ROW_ID,ORDER_QTY,UNIT_CODE from RRL_CUSTOMER_ORDER_ROW
   where CUSTOMER_ORDER_ID=o.CUSTOMER_ORDER_ID and ARTICUL=o.ARTICUL and STATUS not in('CANCELLED','REJECTED')
   order by CUSTOMER_ORDER_ROW_ID fetch first 201 rows only)loop
   n:=n+1;if n>200 then raise_application_error(-20881,'WEIGHT_WAIVER_ORDER_ROWS_BOUND');end if;
   select NUMERATOR,DENOMINATOR,BASE_SCALE into num,den,scale from RRL_STOCK_UOM_CONVERSION
    where ARTICUL=o.ARTICUL and INPUT_UOM=cr.UNIT_CODE and BASE_UOM='KG'
    order by POLICY_VERSION desc fetch first 1 row only;
   mass:=RRL_STOCK_MATH.convert_exact(RRL_STOCK_PLAN_HELPER.decimal_text(cr.ORDER_QTY),num,den,scale);
   requested:=requested+mass;if cr.CUSTOMER_ORDER_ROW_ID=p_line then own_requested:=mass;end if;
  end loop;
  n:=0;
  for pt in(select pt.PICK_TASK_ID,pt.FACT_QTY,pl.CUSTOMER_ORDER_ROW_ID from RRL_PICK_TASK pt
   join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=pt.PICK_PLAN_LINE_ID
   join RRL_CUSTOMER_ORDER_ROW cr on cr.CUSTOMER_ORDER_ROW_ID=pl.CUSTOMER_ORDER_ROW_ID
   where cr.CUSTOMER_ORDER_ID=o.CUSTOMER_ORDER_ID and cr.ARTICUL=o.ARTICUL
    and cr.STATUS not in('CANCELLED','REJECTED')and pt.STATUS in('IN_PROGRESS','DONE')
   order by pt.PICK_TASK_ID fetch first 2001 rows only)loop
   n:=n+1;if n>2000 then raise_application_error(-20881,'WEIGHT_WAIVER_PICK_TASKS_BOUND');end if;
   if nvl(pt.FACT_QTY,0)<0 then raise_application_error(-20887,'WEIGHT_WAIVER_INVALID_PICK_FACT');end if;
   actual:=actual+nvl(pt.FACT_QTY,0);if pt.CUSTOMER_ORDER_ROW_ID=p_line then own_actual:=own_actual+nvl(pt.FACT_QTY,0);end if;
  end loop;
  for sh in(select sh.SHORT_QTY,sh.WEIGHT_TOLERANCE_PCT,sh.WEIGHT_ORDER_REQUESTED_KG
   from RRL_CASE_PICK_SHORT sh join RRL_CASE_PICK_LINE l on l.CASE_PICK_LINE_ID=sh.CASE_PICK_LINE_ID
   join RRL_CASE_PICK_TASK ct on ct.CASE_PICK_TASK_ID=l.CASE_PICK_TASK_ID
   join RRL_PICK_PLAN_LINE pl on pl.PICK_PLAN_LINE_ID=l.PICK_PLAN_LINE_ID
   join RRL_PICK_TASK pt on pt.PICK_TASK_ID=l.PICK_TASK_ID
   join RRL_STOCK_OPERATION op on op.OPERATION_ID=sh.WEIGHT_DECISION_OPERATION
   where pl.CUSTOMER_ORDER_ROW_ID=p_line and sh.STATUS='ACCEPTED'and l.STATUS='SHORT_PICKED'
    and pt.STATUS='DONE'and ct.STATUS!='CANCELLED'and op.STATE='APPLIED'and op.COMMAND_TYPE='CASE_SHORT_APPROVE'
   order by sh.CASE_PICK_SHORT_ID fetch first 201 rows only)loop
   decisions:=decisions+1;if decisions>200 then raise_application_error(-20881,'WEIGHT_WAIVER_DECISIONS_BOUND');end if;
   if requested=sh.WEIGHT_ORDER_REQUESTED_KG and actual>0
    and actual>=requested*(1-sh.WEIGHT_TOLERANCE_PCT/100)
    and actual<=requested*(1+sh.WEIGHT_TOLERANCE_PCT/100)
    then waived:=waived+sh.SHORT_QTY;end if;
  end loop;
  return least(waived,greatest(own_requested-own_actual,0));
 exception when no_data_found then raise_application_error(-20868,'WEIGHT_WAIVER_CURRENT_ORDER_OR_KG_POLICY_REQUIRED');
 end;
end;
/


CREATE OR REPLACE package body RRL_WEIGHT_PLAN_BIND as
 procedure assert_admission(p_order number,p_actor varchar2)is
 begin
  RRL_PICK_PLAN_ACCESS.assert_scope(p_order,p_actor);
  RRL_STOCK_LOCK_API.assert_policy(RRL_STOCK_LOCK_API.resource_key('CONFIG','WAREHOUSE'),4);
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CUSTOMER_ORDER',RRL_STOCK_PLAN_HELPER.decimal_text(p_order)));
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is not null then raise_application_error(-20863,'WEIGHT_PLAN_EXISTING_METADATA_OWNER_REQUIRED');end if;
 end;
 procedure clear_context is begin
  dbms_session.set_context('RRL_WEIGHT_PLAN_CTX','TX_ID',null);dbms_session.set_context('RRL_WEIGHT_PLAN_CTX','CHOICE_ID',null);
  dbms_session.set_context('RRL_WEIGHT_PLAN_CTX','ACTOR',null);
 end;
 function bound_plan(p_order number,p_strategy varchar2,p_actor varchar2)return number is
  n number;plan_id number;strategy_value varchar2(30);choices number;used_choices number;valid_choices number;
 begin
  assert_admission(p_order,p_actor);
  select count(*),nvl(sum(case when STATUS='USED'then 1 else 0 end),0)into choices,used_choices from RRL_PICK_WEIGHT_CHOICE
   where CUSTOMER_ORDER_ID=p_order and STATUS in('ACCEPTED','USED');
  if used_choices=0 then return 0;end if;
  if used_choices!=choices then return 0;end if;
  select count(distinct c.PICK_PLAN_ID),max(c.PICK_PLAN_ID),max(p.PLAN_STRATEGY),count(*)into n,plan_id,strategy_value,valid_choices
   from RRL_PICK_WEIGHT_CHOICE c join RRL_PICK_PLAN p on p.PICK_PLAN_ID=c.PICK_PLAN_ID
   where c.CUSTOMER_ORDER_ID=p_order and c.STATUS='USED'and p.STATUS in('DRAFT','PLANNED_FULL','PLANNED_PARTIAL','RELEASED','DONE')
    and exists(select 1 from RRL_PICK_TASK pt where pt.PICK_PLAN_LINE_ID=c.PICK_PLAN_LINE_ID and pt.STATUS not in('CANCELLED','FAILED'));
  if n!=1 or valid_choices!=used_choices then raise_application_error(-20886,'WEIGHT_PLAN_RETIRE_PREVIOUS_CHOICE_BEFORE_REPLANNING');end if;
  if strategy_value!=p_strategy then raise_application_error(-20873,'WEIGHT_PLAN_EXISTING_STRATEGY_CONTENT_CONFLICT');end if;
  return plan_id;
 end;
 function target_json(p_row number,p_actor varchar2)return clob is
  c RRL_PICK_WEIGHT_CHOICE%rowtype;source_wire clob;j json_object_t;result_json json_object_t:=json_object_t();
  order_id number;ware number;n number;
 begin
  select CUSTOMER_ORDER_ID into order_id from RRL_CUSTOMER_ORDER_ROW where CUSTOMER_ORDER_ROW_ID=p_row;
  assert_admission(order_id,p_actor);
  select count(*)into n from RRL_PICK_WEIGHT_CHOICE where case when STATUS in('ACCEPTED','USED')then CUSTOMER_ORDER_ROW_ID end=p_row;
  if n=0 then return null;end if;
  if n!=1 then raise_application_error(-20886,'WEIGHT_PLAN_ACTIVE_CHOICE_NOT_UNIQUE');end if;
  select *into c from RRL_PICK_WEIGHT_CHOICE where case when STATUS in('ACCEPTED','USED')then CUSTOMER_ORDER_ROW_ID end=p_row;
  if c.STATUS='USED'then
   select count(*)into n from RRL_PICK_PLAN p where p.PICK_PLAN_ID=c.PICK_PLAN_ID
    and p.STATUS in('DRAFT','PLANNED_FULL','PLANNED_PARTIAL','RELEASED','DONE')
    and exists(select 1 from RRL_PICK_TASK pt where pt.PICK_PLAN_LINE_ID=c.PICK_PLAN_LINE_ID and pt.STATUS not in('CANCELLED','FAILED'));
   if n!=1 then raise_application_error(-20886,'WEIGHT_PLAN_RETIRE_RETURNED_CHOICE_BEFORE_REPLANNING');end if;
   result_json.put('already_planned',true);return result_json.to_clob;
  end if;
  RRL_STOCK_LOCK_API.assert_held(20,RRL_STOCK_LOCK_API.resource_key('ROW','RRL_CUSTOMER_ORDER_ROW',RRL_STOCK_PLAN_HELPER.decimal_text(p_row)));
  RRL_STOCK_LOCK_API.assert_held(50,RRL_STOCK_LOCK_API.resource_key('STOCK',c.SOURCE_UID));
  source_wire:=RRL_WEIGHT_BOX_PLANNING_READ.snapshot_json(p_row,p_actor);j:=json_object_t.parse(source_wire);
  if j.get_string('source_signature')!=c.SOURCE_SIGNATURE or j.get_number('warehouse_id')!=c.WARE_ID
   or j.get_number('policy_version')!=c.POLICY_VERSION then raise_application_error(-20886,'WEIGHT_PLAN_APPROVED_SOURCE_CHANGED');end if;
  result_json.put('choice_id',c.CHOICE_ID);result_json.put('source_uid',c.SOURCE_UID);result_json.put('source_cell',c.SOURCE_CELL);
  result_json.put('physical_unit_key',c.PHYSICAL_UNIT_KEY);result_json.put('quantity',RRL_STOCK_PLAN_HELPER.decimal_text(c.NET_WEIGHT_KG));
  result_json.put('choice_mode',c.CHOICE_MODE);result_json.put('original_quantity',RRL_STOCK_PLAN_HELPER.decimal_text(c.ORIGINAL_REMAINING_KG));
  return result_json.to_clob;
 end;
 procedure finish_bind(p_choice varchar2,p_plan number,p_line number,p_actor varchar2)is
  c RRL_PICK_WEIGHT_CHOICE%rowtype;n number;planned number;soft_qty number;wire clob;
 begin
  select *into c from RRL_PICK_WEIGHT_CHOICE where CHOICE_ID=p_choice;
  assert_admission(c.CUSTOMER_ORDER_ID,p_actor);
  if c.STATUS!='ACCEPTED'then raise_application_error(-20886,'WEIGHT_PLAN_CHOICE_BIND_ONCE_REQUIRED');end if;
  select count(*),max(PLANNED_QTY)into n,planned from RRL_PICK_PLAN_LINE
   where PICK_PLAN_LINE_ID=p_line and PICK_PLAN_ID=p_plan and CUSTOMER_ORDER_ROW_ID=c.CUSTOMER_ORDER_ROW_ID and ARTICUL=c.ARTICLE;
  if n!=1 or planned!=c.NET_WEIGHT_KG then raise_application_error(-20887,'WEIGHT_PLAN_EXACT_SELECTED_QUANTITY_REQUIRED');end if;
  select count(*),nvl(sum(RESERVED_QTY),0)into n,soft_qty from RRL_PICK_RESERVATION
   where PICK_PLAN_LINE_ID=p_line and PICK_PLAN_ID=p_plan and PALLET_UID=c.SOURCE_UID and SOURCE_CELL_CODE=c.SOURCE_CELL
    and RESERVATION_LEVEL='SOFT'and RESERVATION_STATUS='ACTIVE';
  if n!=1 or soft_qty!=c.NET_WEIGHT_KG then raise_application_error(-20887,'WEIGHT_PLAN_EXACT_SOURCE_SOFT_REQUIRED');end if;
  dbms_session.set_context('RRL_WEIGHT_PLAN_CTX','TX_ID',dbms_transaction.local_transaction_id(false));
  dbms_session.set_context('RRL_WEIGHT_PLAN_CTX','CHOICE_ID',p_choice);dbms_session.set_context('RRL_WEIGHT_PLAN_CTX','ACTOR',p_actor);
  update RRL_PICK_WEIGHT_CHOICE set STATUS='USED',PICK_PLAN_ID=p_plan,PICK_PLAN_LINE_ID=p_line,USED_AT=systimestamp where CHOICE_ID=p_choice;
  clear_context;
 exception when others then clear_context;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_WH_FINAL_SCALE_ADMISSION as
 function required(p_domain clob)return number is
  d json_object_t:=json_object_t.parse(p_domain);task_no number:=d.get_number('case_task');n number;
 begin
  if task_no is null then return 0;end if;
  select case when p.FINAL_WEIGHT_REQUIRED=1 and upper(p.LOAD_UNIT_CLASS)='CONTAINER'then 1 else 0 end into n
   from RRL_CASE_PICK_TASK c join RRL_PALLET_TYPE p on p.PALLET_TYPE_ID=c.PALLET_TYPE_ID where c.CASE_PICK_TASK_ID=task_no;
  return n;
 end;
 procedure assert_capture(p_request clob,p_domain clob)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');dom json_object_t:=json_object_t.parse(p_domain);
  capture RRL_WH_SCALE_CAPTURE%rowtype;tare RRL_WH_SCALE_CAPTURE%rowtype;dev RRL_WH_SCALE_DEVICE%rowtype;ct RRL_CASE_PICK_TASK%rowtype;
  key_value varchar2(64);signature_value varchar2(64);task_no number;n number;gross number;wood number;needed number;kind varchar2(20):=m.get_string('quality_kind');
 begin
  if kind not in('WEIGHT','WEIGHT2')then
   if m.has('final_scale_capture')then raise_application_error(-20886,'FINAL_SCALE_WEIGHT_CONTROL_REQUIRED');end if;return;
  end if;
  needed:=required(p_domain);
  if needed=0 and not m.has('final_scale_capture')then return;end if;
  key_value:=m.get_string('final_scale_capture');
  if key_value is null or not regexp_like(key_value,'^[A-F0-9]{64}$')then raise_application_error(-20886,'SMALL_BOX_FINAL_SCALE_CAPTURE_REQUIRED');end if;
  select *into capture from RRL_WH_SCALE_CAPTURE where CAPTURE_KEY=key_value;
  task_no:=dom.get_number('case_task');
  select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_no;
  select *into dev from RRL_WH_SCALE_DEVICE where DEVICE_ID=capture.DEVICE_ID;
  if capture.CAPTURE_PURPOSE!='FINAL_GROSS' or capture.TARE_CAPTURE_KEY is null or capture.MEASUREMENT_BASIS!='GROSS'
   or capture.CASE_PICK_TASK_ID!=ct.CASE_PICK_TASK_ID or capture.WARE_ID!=ct.WARE_ID or capture.CARRIER_IDENTIFIER!=ct.SSCC
   or capture.CASE_CONTENT_VERSION!=ct.CONTENT_VERSION or capture.PALLET_TYPE_ID!=ct.PALLET_TYPE_ID
   or ct.CONTENT_VERSION!=dom.get_number('case_version')or ct.LEGACY_SBORKA_PALLET_ID!=dom.get_number('document_id')
   or ct.STATUS not in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP') then raise_application_error(-20886,'FINAL_SCALE_CURRENT_CASE_CHANGED');end if;
  signature_value:=RRL_STOCK_QC_GATE.signature_for_plan(p_domain);
  if capture.COMPOSITION_SIGNATURE!=signature_value then raise_application_error(-20886,'FINAL_SCALE_CURRENT_COMPOSITION_CHANGED');end if;
  if dev.ACTIVE_FLAG!=1 or dev.POLICY_VERSION!=capture.DEVICE_POLICY_VERSION or dev.WARE_ID!=capture.WARE_ID
   or dev.POST_CELL!=capture.POST_CELL or dev.DEVICE_MODE!=capture.DEVICE_MODE or dev.MEASUREMENT_BASIS!='GROSS'
   or dev.CALIBRATION_REF!=capture.CALIBRATION_REF or dev.CALIBRATED_UNTIL<systimestamp
   or capture.MEASURED_AT<systimestamp-numtodsinterval(120,'SECOND')or capture.MEASURED_AT>systimestamp+numtodsinterval(2,'SECOND')
   then raise_application_error(-20886,'FINAL_SCALE_CURRENT_FRESH_DEVICE_REQUIRED');end if;
  select count(*)into n from RUSERS where ID=dev.SENDER_ID and ID=capture.RECORDED_BY and nvl(DELETED,0)=0 and WARE_ID=ct.WARE_ID
   and upper(trim(USER_GROUP))!='GLOBAL_ADMIN'and RRL_HAS_WRIGHT(ID,'warehouse_scale_ingest')=1;
  if n!=1 then raise_application_error(-20882,'FINAL_SCALE_CURRENT_SENDER_REQUIRED');end if;
  select *into tare from RRL_WH_SCALE_CAPTURE where CAPTURE_KEY=capture.TARE_CAPTURE_KEY;
  if tare.CAPTURE_PURPOSE!='EMPTY_TARE' or tare.CASE_PICK_TASK_ID!=ct.CASE_PICK_TASK_ID or tare.CARRIER_IDENTIFIER!=ct.SSCC
   or tare.WARE_ID!=capture.WARE_ID or tare.POST_CELL!=capture.POST_CELL or tare.DEVICE_ID!=capture.DEVICE_ID or tare.DEVICE_MODE!=capture.DEVICE_MODE
   or tare.PALLET_TYPE_ID!=ct.PALLET_TYPE_ID or tare.MEASURED_AT>capture.MEASURED_AT
   or tare.MEASURED_AT<capture.MEASURED_AT-numtodsinterval(24,'HOUR')or tare.WEIGHT_KG>=capture.WEIGHT_KG
   then raise_application_error(-20886,'FINAL_SCALE_SAME_EMPTY_TARE_REQUIRED');end if;
  gross:=RRL_STOCK_MATH.quantity(m.get_string('gross_weight'));
  wood:=case when regexp_like(m.get_string('wood_weight'),'^0([.]0{1,9})?$')then 0 else RRL_STOCK_MATH.quantity(m.get_string('wood_weight'))end;
  if gross!=capture.WEIGHT_KG or wood!=tare.WEIGHT_KG then raise_application_error(-20886,'FINAL_SCALE_ORIGINAL_GROSS_TARE_REQUIRED');end if;
  select count(*)into n from RRL_WH_FINAL_SCALE_USE where CAPTURE_KEY=key_value;
  if n>0 then raise_application_error(-20886,'FINAL_SCALE_CAPTURE_ALREADY_USED');end if;
 exception when no_data_found or too_many_rows then raise_application_error(-20886,'FINAL_SCALE_CURRENT_SOURCE_REQUIRED');
 end;
 procedure claim_capture(p_request clob,p_domain clob,p_operation varchar2)is
  d json_object_t:=json_object_t.parse(p_request);m json_object_t:=d.get_object('metadata');dom json_object_t:=json_object_t.parse(p_domain);
  key_value varchar2(64);tare_key varchar2(64);task_no number;version_no number;signature_value varchar2(64);actor_value varchar2(50);signature_version number;
 begin
  if not m.has('final_scale_capture')then return;end if;
  assert_capture(p_request,p_domain);key_value:=m.get_string('final_scale_capture');
  RRL_STOCK_LOCK_API.assert_held(70,RRL_STOCK_LOCK_API.resource_key('UNIQUE','WH.FINAL.SCALE.USE:'||key_value));
  if sys_context('RRL_STOCK_WRITE_CTX','TX_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is null or sys_context('RRL_STOCK_WRITE_CTX','TX_ID')!=dbms_transaction.local_transaction_id(false)
   or sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')!=p_operation then raise_application_error(-20863,'FINAL_SCALE_CURRENT_STOCK_OWNER_REQUIRED');end if;
  select TARE_CAPTURE_KEY into tare_key from RRL_WH_SCALE_CAPTURE where CAPTURE_KEY=key_value;
  task_no:=dom.get_number('case_task');version_no:=dom.get_number('case_version');signature_value:=RRL_STOCK_QC_GATE.signature_for_plan(p_domain);actor_value:=d.get_string('actor');
  signature_version:=RRL_STOCK_QC_GATE.signature_version_for_plan(p_domain);
  insert into RRL_WH_FINAL_SCALE_USE(CAPTURE_KEY,STOCK_OPERATION_ID,TARE_CAPTURE_KEY,CASE_PICK_TASK_ID,CASE_CONTENT_VERSION,COMPOSITION_SIGNATURE,ACTOR,SIGNATURE_VERSION)
   values(key_value,p_operation,tare_key,task_no,version_no,signature_value,actor_value,signature_version);
 end;
 function approved(p_domain clob,p_operation varchar2)return number is
  dom json_object_t:=json_object_t.parse(p_domain);task_no number:=dom.get_number('case_task');version_no number:=dom.get_number('case_version');
  signature_value varchar2(64);n number;tx_id_value varchar2(100);current_signature_version number;
 begin
  tx_id_value:=dbms_transaction.local_transaction_id(false);current_signature_version:=RRL_STOCK_QC_GATE.signature_version_for_plan(p_domain);
  if required(p_domain)=0 then return 1;end if;
  if p_operation is null then return 0;end if;signature_value:=RRL_STOCK_QC_GATE.signature_for_plan(p_domain);
  select count(*)into n from RRL_WH_FINAL_SCALE_USE u join RRL_WH_SCALE_CAPTURE c on c.CAPTURE_KEY=u.CAPTURE_KEY
   join RRL_STOCK_OPERATION o on o.OPERATION_ID=u.STOCK_OPERATION_ID
   where u.STOCK_OPERATION_ID=p_operation and u.CASE_PICK_TASK_ID=task_no and u.CASE_CONTENT_VERSION<=version_no and u.SIGNATURE_VERSION=current_signature_version and u.COMPOSITION_SIGNATURE=signature_value
    and c.CAPTURE_PURPOSE='FINAL_GROSS' and c.COMPOSITION_SIGNATURE=signature_value and c.TARE_CAPTURE_KEY=u.TARE_CAPTURE_KEY
    and(o.STATE='APPLIED'or(o.OPERATION_ID=sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')
     and sys_context('RRL_STOCK_WRITE_CTX','TX_ID')=tx_id_value));
  return case when n=1 then 1 else 0 end;
 end;
 function preserve_case(p_task number)return number is
  required_flag number;identifier varchar2(150);qc json_object_t;
 begin
  select case when p.FINAL_WEIGHT_REQUIRED=1 and upper(p.LOAD_UNIT_CLASS)='CONTAINER'then 1 else 0 end,s.PALLET_UID into required_flag,identifier
   from RRL_CASE_PICK_TASK c join RRL_PALLET_TYPE p on p.PALLET_TYPE_ID=c.PALLET_TYPE_ID left join RRL_SBORKA_PALLETS s on s.ID=c.LEGACY_SBORKA_PALLET_ID
   where c.CASE_PICK_TASK_ID=p_task;
  if required_flag=0 or identifier is null then return 0;end if;
  qc:=json_object_t.parse(RRL_STOCK_QC_GATE.status_json(identifier));
  return case when qc.get_boolean('ready')then 1 else 0 end;
 end;

 function mass_json(p_task number)return clob is
  identifier varchar2(150);qc_op varchar2(100);carrier varchar2(150);current_version number;needed number;
  qc json_object_t;proof json_object_t;result_json json_object_t:=json_object_t();wire clob;capture_key varchar2(64);measured_version number;signature_value varchar2(64);
 begin
  select case when p.FINAL_WEIGHT_REQUIRED=1 and upper(p.LOAD_UNIT_CLASS)='CONTAINER'then 1 else 0 end,s.PALLET_UID,s.WEIGHT_QC_OPERATION_ID,c.SSCC,c.CONTENT_VERSION
   into needed,identifier,qc_op,carrier,current_version from RRL_CASE_PICK_TASK c join RRL_PALLET_TYPE p on p.PALLET_TYPE_ID=c.PALLET_TYPE_ID
   left join RRL_SBORKA_PALLETS s on s.ID=c.LEGACY_SBORKA_PALLET_ID where c.CASE_PICK_TASK_ID=p_task;
  if needed=0 or identifier is null or qc_op is null then return null;end if;
  qc:=json_object_t.parse(RRL_STOCK_QC_GATE.status_json(identifier));
  if not qc.get_boolean('ready')then return null;end if;
  signature_value:=qc.get_string('composition_signature');
  select c.RESULT_JSON,c.CAPTURE_KEY,u.CASE_CONTENT_VERSION into wire,capture_key,measured_version
   from RRL_WH_FINAL_SCALE_USE u join RRL_WH_SCALE_CAPTURE c on c.CAPTURE_KEY=u.CAPTURE_KEY
   where u.STOCK_OPERATION_ID=qc_op and u.CASE_PICK_TASK_ID=p_task and u.SIGNATURE_VERSION=3 and u.COMPOSITION_SIGNATURE=signature_value;
  proof:=json_object_t.parse(wire);
  result_json.put('case_task_id',p_task);result_json.put('case_content_version',current_version);result_json.put('measured_content_version',measured_version);
  result_json.put('sscc',carrier);result_json.put('capture_key',capture_key);result_json.put('qc_operation_id',qc_op);
  result_json.put('gross_weight_kg',proof.get_string('weight_kg'));result_json.put('tare_weight_kg',proof.get_string('tare_weight_kg'));result_json.put('net_weight_kg',proof.get_string('net_weight_kg'));
  result_json.put('device_mode',proof.get_string('device_mode'));result_json.put('composition_signature',signature_value);result_json.put('signature_version',3);
  result_json.put('origin','WAREHOUSE_SCALE_QC');result_json.put('measurement_ref','WH.SCALE:'||capture_key);
  return result_json.to_clob;
 exception when no_data_found then return null;
 end;

end;
/


CREATE OR REPLACE package body RRL_WH_SCALE_API as
 procedure clear_context is begin
  dbms_session.set_context('RRL_WH_SCALE_CTX','TX_ID',null);dbms_session.set_context('RRL_WH_SCALE_CTX','CAPTURE_KEY',null);
 end;

 procedure capture_final(p_source clob,p_actor varchar2,p_device RRL_WH_SCALE_DEVICE%rowtype,p_key varchar2,p_hash varchar2,p_result out clob)is
  j json_object_t:=json_object_t.parse(p_source);reading json_object_t;r json_object_t:=json_object_t();qc json_object_t;
  ct RRL_CASE_PICK_TASK%rowtype;typ RRL_PALLET_TYPE%rowtype;tare RRL_WH_SCALE_CAPTURE%rowtype;
  task_no number;purpose_value varchar2(12);weight_value number;measured timestamp with time zone;signature_value varchar2(64);tare_key varchar2(64);identifier varchar2(150);capture_id_scalar varchar2(100);
 begin
  capture_id_scalar:=j.get_string('capture_id');purpose_value:=j.get_string('purpose');task_no:=j.get_number('case_task_id');
  if purpose_value is null or purpose_value not in('EMPTY_TARE','FINAL_GROSS')or p_device.MEASUREMENT_BASIS!='GROSS'then raise_application_error(-20886,'FINAL_SCALE_EXPLICIT_GROSS_PURPOSE_REQUIRED');end if;
  select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_no;
  select *into typ from RRL_PALLET_TYPE where PALLET_TYPE_ID=ct.PALLET_TYPE_ID;
  if typ.FINAL_WEIGHT_REQUIRED!=1 or upper(typ.LOAD_UNIT_CLASS)!='CONTAINER' or ct.WARE_ID!=p_device.WARE_ID
   or j.get_number('expected_content_version')is null or j.get_number('expected_content_version')!=ct.CONTENT_VERSION
   or j.get_string('scan_container')is null or j.get_string('scan_container')!=ct.SSCC then raise_application_error(-20886,'FINAL_SCALE_CURRENT_SMALL_CASE_REQUIRED');end if;
  RRL_CASE_SSCC_API.assert_ready(task_no);
  reading:=json_object_t.parse(RRL_SCALE_PACKET_READ.validate_json(p_source,p_device.CAPACITY_KG,p_device.RESOLUTION_KG,'GROSS','weight_kg'));
  weight_value:=RRL_STOCK_MATH.quantity(reading.get_string('weight_kg'));measured:=RRL_SCALE_PACKET_READ.utc_stamp(j.get_string('measured_at'));
  if purpose_value='EMPTY_TARE'then
   if ct.STATUS not in('NEW','ASSIGNED','IN_PROGRESS')or nvl(ct.PICKED_QTY,0)!=0 or j.has('tare_capture_key')then raise_application_error(-20886,'EMPTY_CASE_TARE_BEFORE_FIRST_PICK_REQUIRED');end if;
  else
   if ct.STATUS not in('WAIT_CONTROL','CONTROL_IN_PROGRESS','CONTROLLED','READY_TO_SHIP')or nvl(ct.PICKED_QTY,0)<=0 or ct.LEGACY_SBORKA_PALLET_ID is null then raise_application_error(-20886,'FINAL_SCALE_CLOSED_BOUND_CASE_REQUIRED');end if;
   tare_key:=j.get_string('tare_capture_key');
   if tare_key is null then raise_application_error(-20886,'FINAL_SCALE_MEASURED_EMPTY_TARE_REQUIRED');end if;
   select *into tare from RRL_WH_SCALE_CAPTURE where CAPTURE_KEY=tare_key;
   if tare.CAPTURE_PURPOSE!='EMPTY_TARE' or tare.CASE_PICK_TASK_ID!=task_no or tare.CARRIER_IDENTIFIER!=ct.SSCC
    or tare.PALLET_TYPE_ID!=ct.PALLET_TYPE_ID
    or tare.DEVICE_ID!=p_device.DEVICE_ID or tare.WARE_ID!=p_device.WARE_ID or tare.POST_CELL!=p_device.POST_CELL
    or tare.DEVICE_MODE!=p_device.DEVICE_MODE or tare.MEASUREMENT_BASIS!='GROSS' or tare.MEASURED_AT>measured
    or tare.MEASURED_AT<measured-numtodsinterval(24,'HOUR')or tare.WEIGHT_KG>=weight_value
    then raise_application_error(-20886,'FINAL_SCALE_CURRENT_SAME_CASE_TARE_REQUIRED');end if;
   select PALLET_UID into identifier from RRL_SBORKA_PALLETS where ID=ct.LEGACY_SBORKA_PALLET_ID;
   qc:=json_object_t.parse(RRL_STOCK_QC_GATE.status_json(identifier));signature_value:=qc.get_string('composition_signature');
   if signature_value is null then raise_application_error(-20886,'FINAL_SCALE_CURRENT_COMPOSITION_REQUIRED');end if;
   r.put('tare_capture_key',tare_key);r.put('tare_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(tare.WEIGHT_KG));
   r.put('net_weight_kg',RRL_STOCK_PLAN_HELPER.decimal_text(weight_value-tare.WEIGHT_KG));r.put('composition_signature',signature_value);r.put('composition_signature_version',qc.get_number('composition_signature_version'));
  end if;
  r.put('capture_key',p_key);r.put('device_id',p_device.DEVICE_ID);r.put('capture_id',j.get_string('capture_id'));
  r.put('warehouse_id',ct.WARE_ID);r.put('post_cell',p_device.POST_CELL);r.put('device_mode',p_device.DEVICE_MODE);
  r.put('purpose',purpose_value);r.put('case_task_id',task_no);r.put('case_content_version',ct.CONTENT_VERSION);
  r.put('scan_container',ct.SSCC);r.put('pallet_type_id',ct.PALLET_TYPE_ID);r.put('type_version',typ.TYPE_VERSION);
  r.put('basis','GROSS');r.put('weight_kg',reading.get_string('weight_kg'));r.put('device_policy_version',p_device.POLICY_VERSION);
  r.put('calibration_ref',p_device.CALIBRATION_REF);r.put('resolution_kg',RRL_STOCK_PLAN_HELPER.decimal_text(p_device.RESOLUTION_KG));
  r.put('source_sha256',p_hash);r.put('measured_at',j.get_string('measured_at'));r.put('sample_count',reading.get_number('sample_count'));r.put('span_ms',reading.get_number('span_ms'));
  r.put('status','ARCHIVED');r.put('stock_posted',false);p_result:=r.to_clob;
  dbms_session.set_context('RRL_WH_SCALE_CTX','TX_ID',dbms_transaction.local_transaction_id(true));dbms_session.set_context('RRL_WH_SCALE_CTX','CAPTURE_KEY',p_key);
  insert into RRL_WH_SCALE_CAPTURE(CAPTURE_KEY,DEVICE_ID,CAPTURE_ID,WARE_ID,POST_CELL,CASE_PICK_TASK_ID,CASE_CONTENT_VERSION,CARRIER_IDENTIFIER,
   DEVICE_POLICY_VERSION,DEVICE_MODE,MEASUREMENT_BASIS,WEIGHT_KG,RESOLUTION_KG,CALIBRATION_REF,MEASURED_AT,RECORDED_BY,SOURCE_SHA256,SOURCE_JSON,RESULT_JSON,
   CAPTURE_PURPOSE,TARE_CAPTURE_KEY,PALLET_TYPE_ID,TYPE_VERSION,COMPOSITION_SIGNATURE)
  values(p_key,p_device.DEVICE_ID,capture_id_scalar,ct.WARE_ID,p_device.POST_CELL,task_no,ct.CONTENT_VERSION,ct.SSCC,
   p_device.POLICY_VERSION,p_device.DEVICE_MODE,'GROSS',weight_value,p_device.RESOLUTION_KG,p_device.CALIBRATION_REF,measured,p_actor,p_hash,p_source,p_result,
   purpose_value,tare_key,ct.PALLET_TYPE_ID,typ.TYPE_VERSION,signature_value);
  clear_context;
 end;
 procedure capture(p_source clob,p_actor varchar2,p_result out clob)is
  j json_object_t;reading json_object_t;result_json json_object_t:=json_object_t();identity_json json_array_t:=json_array_t();
  device RRL_WH_SCALE_DEVICE%rowtype;existing RRL_WH_SCALE_CAPTURE%rowtype;ct RRL_CASE_PICK_TASK%rowtype;l RRL_CASE_PICK_LINE%rowtype;
  device_id_value varchar2(100);capture_id_value varchar2(100);capture_key_value varchar2(64);hash_value varchar2(64);
  task_id number;line_id number;n number;scanned_product varchar2(512);measured_weight number;measured_at timestamp with time zone;now_at timestamp with time zone:=systimestamp;
 begin
  if sys_context('RRL_STOCK_WRITE_CTX','OPERATION_ID')is not null then raise_application_error(-20886,'SCALE_CAPTURE_OUTSIDE_STOCK_TRANSACTION_REQUIRED');end if;
  if RRL_HAS_WRIGHT(p_actor,'warehouse_scale_ingest')!=1 then raise_application_error(-20882,'WAREHOUSE_SCALE_SENDER_FORBIDDEN');end if;
  if p_source is null or dbms_lob.getlength(p_source)>32000 then raise_application_error(-20881,'SCALE_PACKET_BOUND_32000');end if;
  j:=json_object_t.parse(p_source);device_id_value:=j.get_string('device_id');capture_id_value:=j.get_string('capture_id');
  if device_id_value is null or capture_id_value is null then raise_application_error(-20886,'SCALE_SOURCE_IDENTIFIERS_REQUIRED');end if;
  select *into device from RRL_WH_SCALE_DEVICE where DEVICE_ID=device_id_value for update;
  select count(*)into n from RUSERS where ID=p_actor and nvl(DELETED,0)=0 and WARE_ID=device.WARE_ID and upper(trim(USER_GROUP))!='GLOBAL_ADMIN';
  if n!=1 or device.SENDER_ID!=p_actor then raise_application_error(-20882,'WAREHOUSE_SCALE_CURRENT_SENDER_WARE_REQUIRED');end if;
  identity_json.append(device_id_value);identity_json.append(capture_id_value);
  capture_key_value:=rawtohex(sys.dbms_crypto.hash(identity_json.to_clob,sys.dbms_crypto.hash_sh256));hash_value:=rawtohex(sys.dbms_crypto.hash(p_source,sys.dbms_crypto.hash_sh256));
  select count(*)into n from RRL_WH_SCALE_CAPTURE where CAPTURE_KEY=capture_key_value;
  if n=1 then
   select *into existing from RRL_WH_SCALE_CAPTURE where CAPTURE_KEY=capture_key_value;
   if existing.SOURCE_SHA256!=hash_value or dbms_lob.compare(existing.SOURCE_JSON,p_source)!=0 then raise_application_error(-20886,'SCALE_CAPTURE_PAYLOAD_CONFLICT');end if;
   if existing.WARE_ID!=device.WARE_ID or existing.POST_CELL!=device.POST_CELL then raise_application_error(-20882,'WAREHOUSE_SCALE_ORIGINAL_SCOPE_CHANGED');end if;
   select count(*)into n from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=existing.CASE_PICK_TASK_ID and WARE_ID=device.WARE_ID;
   if n!=1 then raise_application_error(-20882,'WAREHOUSE_SCALE_CURRENT_CASE_WARE_REQUIRED');end if;
   p_result:=existing.RESULT_JSON;return;
  end if;
  if j.get_number('device_policy_version')is null or j.get_number('device_policy_version')!=device.POLICY_VERSION
   or j.get_string('calibration_ref')is null or j.get_string('calibration_ref')!=device.CALIBRATION_REF then raise_application_error(-20886,'SCALE_DEVICE_POLICY_CHANGED');end if;
  if device.ACTIVE_FLAG!=1 or device.CALIBRATED_UNTIL<now_at then raise_application_error(-20886,'SCALE_INACTIVE_OR_CALIBRATION_EXPIRED');end if;
  if j.get_string('post_cell')is null or j.get_string('post_cell')!=device.POST_CELL then raise_application_error(-20886,'WAREHOUSE_SCALE_POST_SCAN_REQUIRED');end if;
  if j.has('purpose')then capture_final(p_source,p_actor,device,capture_key_value,hash_value,p_result);return;end if;
  task_id:=j.get_number('case_task_id');line_id:=j.get_number('case_line_id');
  select *into ct from RRL_CASE_PICK_TASK where CASE_PICK_TASK_ID=task_id;
  select *into l from RRL_CASE_PICK_LINE where CASE_PICK_LINE_ID=line_id and CASE_PICK_TASK_ID=task_id;
  if ct.WARE_ID is null or l.ARTICUL is null or l.CELL_CODE is null or ct.WARE_ID!=device.WARE_ID or ct.STATUS not in('IN_PROGRESS','PARTIAL','WAIT_REPLENISHMENT')
   or ct.STATUS is null or j.get_number('expected_content_version')is null or ct.CONTENT_VERSION!=j.get_number('expected_content_version')
   or j.get_string('scan_source_cell')is null or j.get_string('scan_source_cell')!=l.CELL_CODE
   or j.get_string('scan_container')is null or j.get_string('scan_container')!=ct.SSCC then raise_application_error(-20886,'WAREHOUSE_SCALE_CURRENT_CASE_SOURCE_REQUIRED');end if;
  scanned_product:=j.get_string('scan_product');
  select count(*)into n from RRL_ARTICULS where ACTICUL=l.ARTICUL and TYPE_W in(2,3,5,6,7);
  if n!=1 then raise_application_error(-20886,'WAREHOUSE_SCALE_WEIGHTED_SKU_REQUIRED');end if;
  if RRL_WEIGHT_BOX_CAPACITY.enabled(l.ARTICUL)=1 then
   if device.MEASUREMENT_BASIS!='GROSS'then raise_application_error(-20886,'SEALED_WEIGHT_BOX_GROSS_CAPTURE_REQUIRED');end if;
   declare b json_object_t:=json_object_t.parse(RRL_WEIGHT_BOX_READ.decode_json(scanned_product));begin RRL_WEIGHT_BOX_READ.assert_sku(l.ARTICUL,b.get_string('gtin'));end;
  else
   select count(*)into n from RRL_ARTICULS where ACTICUL=l.ARTICUL and scanned_product in(ACTICUL,BARCODE_SHT,BARCODE_KOR,BARCODE_BL);
   if n!=1 or device.MEASUREMENT_BASIS!='NET'then raise_application_error(-20886,'LOOSE_WEIGHT_NET_PRODUCT_CAPTURE_REQUIRED');end if;
   select greatest(nvl((select MARKING_REQUIRED from RRL_SKU_RECEIPT_POLICY where ARTICUL=l.ARTICUL),0),
    nvl((select CRPT_REQUIRED from RRL_FINISHED_GOODS_SKU where ARTICUL=l.ARTICUL),0),
    case when exists(select 1 from RRL_SKU_RECEIPT_PROFILE where ARTICUL=l.ARTICUL)then 1 else 0 end)into n from dual;
   if n!=0 then raise_application_error(-20886,'MARKED_UNIT_OPENING_NOT_AUTHORIZED');end if;
  end if;
  reading:=json_object_t.parse(RRL_SCALE_PACKET_READ.validate_json(p_source,device.CAPACITY_KG,device.RESOLUTION_KG,device.MEASUREMENT_BASIS,'weight_kg'));
  measured_weight:=RRL_STOCK_MATH.quantity(reading.get_string('weight_kg'));measured_at:=RRL_SCALE_PACKET_READ.utc_stamp(reading.get_string('measured_at'));
  result_json.put('capture_key',capture_key_value);result_json.put('device_id',device_id_value);result_json.put('capture_id',capture_id_value);
  result_json.put('warehouse_id',device.WARE_ID);result_json.put('post_cell',device.POST_CELL);result_json.put('device_mode',device.DEVICE_MODE);
  result_json.put('case_task_id',task_id);result_json.put('case_line_id',line_id);result_json.put('case_content_version',ct.CONTENT_VERSION);
  result_json.put('article',l.ARTICUL);result_json.put('scan_source_cell',l.CELL_CODE);result_json.put('scan_container',ct.SSCC);result_json.put('scan_product',scanned_product);
  result_json.put('basis',device.MEASUREMENT_BASIS);result_json.put('weight_kg',reading.get_string('weight_kg'));result_json.put('device_policy_version',device.POLICY_VERSION);
  result_json.put('calibration_ref',device.CALIBRATION_REF);result_json.put('resolution_kg',RRL_STOCK_PLAN_HELPER.decimal_text(device.RESOLUTION_KG));
  result_json.put('source_sha256',hash_value);result_json.put('measured_at',j.get_string('measured_at'));result_json.put('received_at',to_char(now_at,'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'));
  result_json.put('sample_count',reading.get_number('sample_count'));result_json.put('span_ms',reading.get_number('span_ms'));
  result_json.put('status','ARCHIVED');result_json.put('stock_posted',false);p_result:=result_json.to_clob;
  dbms_session.set_context('RRL_WH_SCALE_CTX','TX_ID',dbms_transaction.local_transaction_id(true));dbms_session.set_context('RRL_WH_SCALE_CTX','CAPTURE_KEY',capture_key_value);
  insert into RRL_WH_SCALE_CAPTURE(CAPTURE_KEY,DEVICE_ID,CAPTURE_ID,WARE_ID,POST_CELL,CASE_PICK_TASK_ID,CASE_PICK_LINE_ID,CASE_CONTENT_VERSION,ARTICLE,SOURCE_CELL,CARRIER_IDENTIFIER,SCANNED_PRODUCT,
   DEVICE_POLICY_VERSION,DEVICE_MODE,MEASUREMENT_BASIS,WEIGHT_KG,RESOLUTION_KG,CALIBRATION_REF,MEASURED_AT,RECEIVED_AT,RECORDED_BY,SOURCE_SHA256,SOURCE_JSON,RESULT_JSON)
   values(capture_key_value,device_id_value,capture_id_value,device.WARE_ID,device.POST_CELL,task_id,line_id,ct.CONTENT_VERSION,l.ARTICUL,l.CELL_CODE,ct.SSCC,scanned_product,
    device.POLICY_VERSION,device.DEVICE_MODE,device.MEASUREMENT_BASIS,measured_weight,device.RESOLUTION_KG,device.CALIBRATION_REF,measured_at,now_at,p_actor,hash_value,p_source,p_result);
  clear_context;
 exception when no_data_found then clear_context;raise_application_error(-20886,'WAREHOUSE_SCALE_DEVICE_AND_CASE_SOURCE_REQUIRED');
 when others then clear_context;raise;
 end;
end;
/


CREATE OR REPLACE package body RRL_WORKLOAD_CONFIG_API as
 g_operation varchar2(100);g_tx varchar2(100);
 function write_allowed(p_operation varchar2)return number is begin
  if p_operation=g_operation and g_tx=dbms_transaction.local_transaction_id(false)then return 1;end if;return 0;
 end;
 procedure scoped_actor(p_ware number,p_actor varchar2)is n number;begin
  select count(*)into n from RRL_WARES where ID=p_ware;
  if n!=1 or p_ware is null or p_ware<=0 then raise_application_error(-20886,'WORKLOAD_WARE_REQUIRED');end if;
  select count(*)into n from RUSERS u where u.ID=p_actor and nvl(u.DELETED,0)=0
   and(u.WARE_ID=p_ware or upper(trim(u.USER_GROUP))='GLOBAL_ADMIN')and RRL_HAS_WRIGHT(u.ID,'resource_shift_edit')=1;
  if n!=1 then raise_application_error(-20882,'WORKLOAD_CURRENT_WARE_ACTOR_REQUIRED');end if;
 end;
 procedure store_norm(p_ware number,p_actor varchar2,b json_object_t,r in out json_object_t)is
  v_article varchar2(160):=b.get_string('article');base varchar2(20):=b.get_string('base_uom');
  site varchar2(50):=b.get_string('site_code');rate number;active_flag number;old_version number;n number;reason_text nvarchar2(500);
 begin
  rate:=RRL_STOCK_MATH.quantity(b.get_string('base_per_hour'));reason_text:=b.get_string('reason');
  if rate<=0 or length(reason_text)<3 or site is null or v_article is null or base is null then raise_application_error(-20886,'WORKLOAD_NORM_FIELDS_REQUIRED');end if;
  select count(*)into n from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article and INPUT_UOM=base and BASE_UOM=base and NUMERATOR=1 and DENOMINATOR=1
   and POLICY_VERSION=(select max(POLICY_VERSION)from RRL_STOCK_UOM_CONVERSION where ARTICUL=v_article);
  if n!=1 then raise_application_error(-20886,'WORKLOAD_CURRENT_BASE_POLICY_REQUIRED');end if;
  select nvl(max(VERSION_NO),0)into old_version from RRL_WORKLOAD_NORM where WARE_ID=p_ware and SITE_CODE=site and ARTICLE=v_article and BASE_UOM=base;
  if nvl(b.get_number('expected_version'),-1)!=old_version then raise_application_error(-20886,'WORKLOAD_NORM_VERSION_CHANGED');end if;
  active_flag:=case when b.get_boolean('active')then 1 else 0 end;
  insert into RRL_WORKLOAD_NORM(WARE_ID,SITE_CODE,ARTICLE,BASE_UOM,VERSION_NO,BASE_PER_HOUR,ACTIVE,REASON,OPERATION_ID,CREATED_BY)
   values(p_ware,site,v_article,base,old_version+1,rate,active_flag,reason_text,g_operation,p_actor);
  r.put('version',old_version+1);r.put('article',v_article);r.put('base_uom',base);r.put('base_per_hour',to_char(rate,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''));
 end;
 procedure store_attendance(p_ware number,b json_object_t,r in out json_object_t)is
  v_resource number:=b.get_number('resource_id');person nvarchar2(50);n number;
  site varchar2(50):=b.get_string('site_code');v_start timestamp with time zone;v_finish timestamp with time zone;reason_text nvarchar2(500);
 begin
  v_start:=to_timestamp_tz(b.get_string('start_at'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
  v_finish:=to_timestamp_tz(b.get_string('finish_at'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
  reason_text:=b.get_string('reason');
  if v_finish<=v_start or v_finish>v_start+interval '24'hour or site is null or length(reason_text)<3 then raise_application_error(-20886,'WORKLOAD_ATTENDANCE_FIELDS_REQUIRED');end if;
  select u.ID into person from RRL_RESOURCE r join RUSERS u on u.ID=r.USER_ID
   join RRL_RESOURCE_TYPE t on t.RESOURCE_TYPE=r.RESOURCE_TYPE
   where r.RESOURCE_ID=v_resource and r.WARE_ID=p_ware and r.ACTIVE=1 and t.ACTIVE=1 and nvl(u.DELETED,0)=0 and u.WARE_ID=p_ware and RRL_HAS_WRIGHT(u.ID,'case_pick_execute')=1
   and instr(','||replace(t.DEFAULT_TASK_TYPES,' ','')||',',',CASE_PICK,')>0;
  select count(*)into n from RRL_RESOURCE_TASK_QUAL where RESOURCE_ID=v_resource and TASK_TYPE='CASE_PICK'and ACTIVE=1
   and VALID_FROM<=systimestamp and VALID_UNTIL is null;
  if n!=1 then raise_application_error(-20886,'WORKLOAD_CASE_QUALIFICATION_REQUIRED');end if;
  select count(*)into n from RRL_WORKLOAD_ATTENDANCE a where a.PERSON_ID=person
   and(a.WARE_ID!=p_ware or a.SITE_CODE!=site)and a.START_AT<v_finish and a.FINISH_AT>v_start
   and not exists(select 1 from RRL_WORKLOAD_ATTEND_CANCEL c where c.PLAN_OPERATION_ID=a.PLAN_OPERATION_ID);
  if n>0 then raise_application_error(-20886,'WORKLOAD_PERSON_OVERLAPPING_OTHER_SITE');end if;
  insert into RRL_WORKLOAD_ATTENDANCE values(g_operation,p_ware,site,v_resource,person,v_start,v_finish,'CASE_PICK',reason_text);
  r.put('resource_id',v_resource);r.put('person_id',person);r.put('plan_operation_id',g_operation);
 end;
 procedure cancel_attendance(p_ware number,b json_object_t,r in out json_object_t)is
  plan_id varchar2(100):=b.get_string('plan_operation_id');n number;reason_text nvarchar2(500):=b.get_string('reason');
 begin
  select count(*)into n from RRL_WORKLOAD_ATTENDANCE where PLAN_OPERATION_ID=plan_id and WARE_ID=p_ware;
  if n!=1 or length(reason_text)<3 then raise_application_error(-20886,'WORKLOAD_OWN_ATTENDANCE_REQUIRED');end if;
  select count(*)into n from RRL_WORKLOAD_ATTEND_CANCEL where PLAN_OPERATION_ID=plan_id;
  if n!=0 then raise_application_error(-20886,'WORKLOAD_ATTENDANCE_ALREADY_CANCELLED');end if;
  insert into RRL_WORKLOAD_ATTEND_CANCEL values(plan_id,g_operation,reason_text);r.put('plan_operation_id',plan_id);r.put('cancelled',true);
 end;
 procedure replace_attendance(p_ware number,b json_object_t,r in out json_object_t)is
  v_old varchar2(100):=b.get_string('plan_operation_id');
  v_new_start timestamp with time zone;v_ware number;
 begin
  if v_old is null or length(b.get_string('reason'))<8 then
   raise_application_error(-20886,'WORKLOAD_REPLACEMENT_SOURCE_REASON_REQUIRED');end if;
  select WARE_ID into v_ware from RRL_WORKLOAD_ATTENDANCE where PLAN_OPERATION_ID=v_old for update;
  if v_ware!=p_ware then raise_application_error(-20882,'WORKLOAD_REPLACEMENT_SOURCE_WARE_FORBIDDEN');end if;
  v_new_start:=to_timestamp_tz(b.get_string('start_at'),'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM');
  if v_new_start<=systimestamp then raise_application_error(-20886,'WORKLOAD_REPLACEMENT_FUTURE_INTERVAL_REQUIRED');end if;
  cancel_attendance(p_ware,b,r);
  store_attendance(p_ware,b,r);
  r.remove('cancelled');r.put('replaced_plan_operation_id',v_old);
  r.put('actual_presence_created',false);r.put('task_assignments_changed',false);
 end;
 procedure store_scope(p_ware number,p_actor varchar2,b json_object_t,r in out json_object_t)is
  v_scope varchar2(30):=b.get_string('work_scope');v_site varchar2(50):=b.get_string('site_code');
  v_reason nvarchar2(500):=b.get_string('reason');v_active number;v_version number;n number;
 begin
  if v_scope is null or v_scope not in('CASE_DISPATCH','FULLPAL_DISPATCH','OUTBOUND_WORKLOAD')
   or trim(v_site)is null or length(trim(v_reason))<3 or b.get_boolean('active')is null then
   raise_application_error(-20886,'WORKLOAD_SCOPE_FIELDS_REQUIRED');end if;
  v_active:=case when b.get_boolean('active')then 1 else 0 end;
  select nvl(max(VERSION_NO),0)into v_version from RRL_WORKLOAD_SCOPE_SITE where WARE_ID=p_ware and WORK_SCOPE=v_scope;
  if nvl(b.get_number('expected_version'),-1)!=v_version then raise_application_error(-20886,'WORKLOAD_SCOPE_VERSION_CHANGED');end if;
  if v_active=1 then
   select count(*)into n from RRL_WORKLOAD_NORM x where x.WARE_ID=p_ware and x.SITE_CODE=v_site and x.ACTIVE=1
    and x.VERSION_NO=(select max(y.VERSION_NO)from RRL_WORKLOAD_NORM y where y.WARE_ID=x.WARE_ID and y.SITE_CODE=x.SITE_CODE and y.ARTICLE=x.ARTICLE and y.BASE_UOM=x.BASE_UOM);
   if n=0 then raise_application_error(-20886,'WORKLOAD_SCOPE_ACTIVE_SITE_NORM_REQUIRED');end if;
  end if;
  insert into RRL_WORKLOAD_SCOPE_SITE(WARE_ID,WORK_SCOPE,SITE_CODE,VERSION_NO,ACTIVE,REASON,OPERATION_ID,CREATED_BY)
   values(p_ware,v_scope,v_site,v_version+1,v_active,v_reason,g_operation,p_actor);
  r.put('work_scope',v_scope);r.put('site_code',v_site);r.put('version',v_version+1);r.put('active',v_active=1);
  r.put('actual_presence_created',false);r.put('task_assignments_changed',false);
 end;
 procedure execute_command(p_operation varchar2,p_actor varchar2,p_action varchar2,p_body clob,p_result out clob)is
  b json_object_t;result json_object_t:=json_object_t();ware number;digest varchar2(64);old_hash varchar2(64);old_actor nvarchar2(50);old_action varchar2(20);old_result clob;entered boolean:=false;v_saved boolean:=false;
 begin
  g_operation:=null;g_tx:=null;b:=json_object_t.parse(p_body);ware:=b.get_number('warehouse_id');scoped_actor(ware,p_actor);
  if p_operation is null or length(p_operation)not between 1 and 100 or p_action not in('NORM','ATTENDANCE','CANCEL_ATTENDANCE','REPLACE_ATTENDANCE','FORECAST_SCOPE')then raise_application_error(-20886,'WORKLOAD_COMMAND_REQUIRED');end if;
  digest:=lower(rawtohex(sys.dbms_crypto.hash(p_body,sys.dbms_crypto.hash_sh256)));
  RRL_STOCK_METADATA_TX.begin_change(p_actor,'resource_shift_edit');entered:=true;
  savepoint RRL_WORKLOAD150;v_saved:=true;scoped_actor(ware,p_actor);
  begin select REQUEST_HASH,ACTOR,ACTION_KIND,RESULT_JSON into old_hash,old_actor,old_action,old_result from RRL_WORKLOAD_OPERATION where OPERATION_ID=p_operation;
   if old_hash!=digest or old_actor!=p_actor or old_action!=p_action then raise_application_error(-20886,'WORKLOAD_OPERATION_PAYLOAD_CONFLICT');end if;
   p_result:=old_result;RRL_STOCK_METADATA_TX.end_change;return;
  exception when no_data_found then null;end;
  g_operation:=p_operation;g_tx:=dbms_transaction.local_transaction_id(true);
  result.put('operation_id',p_operation);result.put('warehouse_id',ware);result.put('action',p_action);result.put('stock_changed',false);
  p_result:=result.to_clob;
  insert into RRL_WORKLOAD_OPERATION(OPERATION_ID,WARE_ID,ACTION_KIND,ACTOR,REQUEST_HASH,RESULT_JSON)values(p_operation,ware,p_action,p_actor,digest,p_result);
  if p_action='FORECAST_SCOPE'then store_scope(ware,p_actor,b,result);elsif p_action='NORM'then store_norm(ware,p_actor,b,result);elsif p_action='ATTENDANCE'then store_attendance(ware,b,result);elsif p_action='REPLACE_ATTENDANCE'then replace_attendance(ware,b,result);else cancel_attendance(ware,b,result);end if;
  p_result:=result.to_clob;update RRL_WORKLOAD_OPERATION set RESULT_JSON=p_result where OPERATION_ID=p_operation;
  g_operation:=null;g_tx:=null;RRL_STOCK_METADATA_TX.end_change;
 exception when others then if v_saved then rollback to RRL_WORKLOAD150;end if;g_operation:=null;g_tx:=null;if entered then RRL_STOCK_METADATA_TX.end_change;end if;raise;
 end;
end;
/


CREATE OR REPLACE package body STORE_ADRESSES is
  function Update_cell(
    CELL1 varchar2,
    OTBOR1 integer,
    BLOCKED_FOR_REMAINS1 integer,
    BLOCKED_FOR_POPOLNENIE1 integer,
    X1 integer,
    Y1 integer,
    Z1 integer,
    BLOCKED_FOR_ACCEPT1 integer,
    WARE_ID1 integer,
    LIMIT_WEIGHT1 number,
    LIMIT_HEIGHT1 number,
    Y_VISOTA1 number,
    CELL_WEIGHT1 number,
    CELL_HEIGHT1 number,
    PICK_ORDER1 integer,
    LAST_USER_ID1 varchar2
  ) return int is
  begin
    merge into RRL_CELLS d
    using (select CELL1 CELL from dual) s
    on (d.CELL = s.CELL)
    when matched then update set
      d.OTBOR = OTBOR1,
      d.BLOCKED_FOR_REMAINS = BLOCKED_FOR_REMAINS1,
      d.BLOCKED_FOR_POPOLNENIE = BLOCKED_FOR_POPOLNENIE1,
      d.X = X1,
      d.Y = Y1,
      d.Z = Z1,
      d.BLOCKED_FOR_ACCEPT = BLOCKED_FOR_ACCEPT1,
      d.WARE_ID = WARE_ID1,
      d.LIMIT_WEIGHT = LIMIT_WEIGHT1,
      d.LIMIT_HEIGHT = LIMIT_HEIGHT1,
      d.Y_VISOTA = Y_VISOTA1,
      d.CELL_WEIGHT = CELL_WEIGHT1,
      d.CELL_HEIGHT = CELL_HEIGHT1,
      d.PICK_ORDER = PICK_ORDER1,
      d.LAST_USER_ID = LAST_USER_ID1,
      d.LAST_TIME_OF_UPDATE = sysdate
    when not matched then insert (
      CELL, OTBOR, BLOCKED_FOR_REMAINS, BLOCKED_FOR_POPOLNENIE,
      X, Y, Z, BLOCKED_FOR_ACCEPT, WARE_ID, LIMIT_WEIGHT, LIMIT_HEIGHT, Y_VISOTA,
      CELL_WEIGHT, CELL_HEIGHT, PICK_ORDER, LAST_USER_ID, LAST_TIME_OF_UPDATE
    ) values (
      CELL1, OTBOR1, BLOCKED_FOR_REMAINS1, BLOCKED_FOR_POPOLNENIE1,
      X1, Y1, Z1, BLOCKED_FOR_ACCEPT1, WARE_ID1, LIMIT_WEIGHT1, LIMIT_HEIGHT1, Y_VISOTA1,
      CELL_WEIGHT1, CELL_HEIGHT1, PICK_ORDER1, LAST_USER_ID1, sysdate
    );

    return 1;
  exception
    when others then return 0;
  end;
end STORE_ADRESSES;
/


CREATE OR REPLACE package body TRANSPORT_PLN is
  function get_time(reg_f varchar2, rai_f varchar2, reg_2 varchar2, rai_2 varchar2) return int is
    ret number;
  begin
    select nvl(time1, 0) into ret from RRL_TRP_MATRIX
     where REG_F = get_time.reg_f and RAI_F = get_time.rai_f and REG_2 = get_time.reg_2 and RAI_2 = get_time.rai_2;
    return ret;
  exception
    when no_data_found then return 0;
  end;

  function get_distance(reg_f varchar2, rai_f varchar2, reg_2 varchar2, rai_2 varchar2) return int is
    ret number;
  begin
    select nvl(dist, 0) into ret from RRL_TRP_MATRIX
     where REG_F = get_distance.reg_f and RAI_F = get_distance.rai_f and REG_2 = get_distance.reg_2 and RAI_2 = get_distance.rai_2;
    return ret;
  exception
    when no_data_found then return 0;
  end;

  function get_time_m(AddrFrom varchar2, AddrTo varchar2) return number is
    ret number;
  begin
    select nvl(time1, 0) into ret from RRL_TRP_ADDR_MATRIX
     where ADDR_FROM = get_time_m.AddrFrom and ADDR_TO = get_time_m.AddrTo;
    return ret;
  exception
    when no_data_found then return 0;
  end;

  function get_dist_m(AddrFrom varchar2, AddrTo varchar2) return number is
    ret number;
  begin
    select nvl(dist, 0) into ret from RRL_TRP_ADDR_MATRIX
     where ADDR_FROM = get_dist_m.AddrFrom and ADDR_TO = get_dist_m.AddrTo;
    return ret;
  exception
    when no_data_found then return 0;
  end;

  function set_time(reg_f varchar2, rai_f varchar2, reg_2 varchar2, rai_2 varchar2, time1 number) return int is
  begin
    merge into RRL_TRP_MATRIX d
    using (select reg_f REG_F, rai_f RAI_F, reg_2 REG_2, rai_2 RAI_2, time1 TIME1 from dual) s
    on (d.REG_F = s.REG_F and d.RAI_F = s.RAI_F and d.REG_2 = s.REG_2 and d.RAI_2 = s.RAI_2)
    when matched then update set d.TIME1 = s.TIME1
    when not matched then insert (REG_F, RAI_F, REG_2, RAI_2, TIME1) values (s.REG_F, s.RAI_F, s.REG_2, s.RAI_2, s.TIME1);
    return 1;
  end;

  function set_distance(reg_f varchar2, rai_f varchar2, reg_2 varchar2, rai_2 varchar2, dist number) return int is
  begin
    merge into RRL_TRP_MATRIX d
    using (select reg_f REG_F, rai_f RAI_F, reg_2 REG_2, rai_2 RAI_2, dist DIST from dual) s
    on (d.REG_F = s.REG_F and d.RAI_F = s.RAI_F and d.REG_2 = s.REG_2 and d.RAI_2 = s.RAI_2)
    when matched then update set d.DIST = s.DIST
    when not matched then insert (REG_F, RAI_F, REG_2, RAI_2, DIST) values (s.REG_F, s.RAI_F, s.REG_2, s.RAI_2, s.DIST);
    return 1;
  end;

  function set_time_m(AddrFrom varchar2, AddrTo varchar2, time1 number) return int is
  begin
    merge into RRL_TRP_ADDR_MATRIX d
    using (select AddrFrom ADDR_FROM, AddrTo ADDR_TO, time1 TIME1 from dual) s
    on (d.ADDR_FROM = s.ADDR_FROM and d.ADDR_TO = s.ADDR_TO)
    when matched then update set d.TIME1 = s.TIME1
    when not matched then insert (ADDR_FROM, ADDR_TO, TIME1) values (s.ADDR_FROM, s.ADDR_TO, s.TIME1);
    return 1;
  end;

  function set_distance_m(AddrFrom varchar2, AddrTo varchar2, dist1 number) return int is
  begin
    merge into RRL_TRP_ADDR_MATRIX d
    using (select AddrFrom ADDR_FROM, AddrTo ADDR_TO, dist1 DIST from dual) s
    on (d.ADDR_FROM = s.ADDR_FROM and d.ADDR_TO = s.ADDR_TO)
    when matched then update set d.DIST = s.DIST
    when not matched then insert (ADDR_FROM, ADDR_TO, DIST) values (s.ADDR_FROM, s.ADDR_TO, s.DIST);
    return 1;
  end;

  function is_tt_just_out_go(tt_id int) return int is
    cond1 varchar2(100);
  begin
    select condition into cond1 from RRL_TRANSPORT_TASK where id = tt_id;
    if cond1 = unistr('\0412\042B\041F\0423\0429\0415\041D') then return 1; end if;
    return 0;
  exception
    when no_data_found then return -1;
  end;

  function upd_tt_perdiction(tt_id int) return int is
  begin
    update RRL_TRANSPORT_TASK
       set planned_delivery_date = nvl(shipment_date, sysdate) + (nvl(hours, 0) / 24)
     where id = tt_id;
    if sql%rowcount = 0 then return 0; end if;
    return 1;
  end;

  function set_mail_sended(tt_id int) return int is
  begin
    update RRL_TRANSPORT_TASK set mail_sended = 1 where id = tt_id;
    if sql%rowcount = 0 then return 0; end if;
    return 1;
  end;

  function set_tt_closed(tt_id int) return int is
  begin
    update RRL_TRANSPORT_TASK
       set condition = unistr('\0412\042B\041F\0423\0429\0415\041D')
     where id = tt_id;
    if sql%rowcount = 0 then return 0; end if;
    return 1;
  end;
end TRANSPORT_PLN;
/


CREATE OR REPLACE package body TRANSPORT_TASK is

function PRINT_PALLET_WEIGHT( PALLET_UID2 varchar2 ) return varchar2 is
  ret number;
  ware_id1 int;
  count_kor1 int;
  count_rs int;
  articul1 varchar2(255);
  sum_q number;
begin
  select round(TRIAL_WEIGHT, 2), pts.ware_id
    into ret, ware_id1
    from rrl_sborka_pallets pts
   where pts.pallet_uid = PALLET_UID2;

  if ret > 0 then
    return to_char(ret);
  end if;

  if ware_id1 = 5 then
    select sum(rs.pack_count)
      into count_kor1
      from rrl_sborka_pallet_rows rs
     where rs.pallet_uid = PALLET_UID2;
    return to_char(count_kor1) || ' Р С”Р С•РЎР‚.';
  end if;

  select count(rs.id), sum(rs.pack_count), sum(rs.quantity)
    into count_rs, count_kor1, sum_q
    from rrl_sborka_pallet_rows rs
   where rs.pallet_uid = PALLET_UID2;

  if count_rs = 1 then
    select rs.articul
      into articul1
      from rrl_sborka_pallet_rows rs
     where rs.pallet_uid = PALLET_UID2;
    if articul1 = 'Р Тђ0000012233' then
      return to_char(count_kor1) || ' Р С”Р С•РЎР‚.';
    end if;
  end if;

  return to_char(ret);
exception
  when no_data_found then
    return '-';
end;

function can_print( tt_id int, user_id1 varchar2 ) return varchar2 is
  ml int;
  cnt_pt int;
begin
  select type1.min_pallet_load
    into ml
    from rrl_transport_task tt, rrl_tr_vehicle veh, rrl_transport_type type1
   where tt.id = tt_id
     and veh.num = tt.transport
     and veh.tr_type = type1.transporttype;

  select count(pts.pallet_uid)
    into cnt_pt
    from rrl_sborka_pallets pts
   where pts.transtask_id = tt_id;

  if cnt_pt < ml then
    if rrl_has_wright(user_id1, 'SEND_EMPTY_TRUCK') = 1 then
      return 'ok';
    end if;
    return 'Р СњР ВµР Т‘Р С•РЎРѓРЎвЂљР В°РЎвЂљР С•РЎвЂЎР Р…Р В°РЎРЏ Р В·Р В°Р С–РЎР‚РЎС“Р В·Р С”Р В° Р СР В°РЎР‚РЎв‚¬РЎР‚РЎС“РЎвЂљР В°: ' || to_char(cnt_pt) || ' < ' || to_char(ml);
  end if;

  return 'ok';
exception
  when no_data_found then
    return 'ok';
  when others then
    return 'ok';
end;

function pallet_count( tt_id int ) return number is
  tmp number;
begin
  select count(pts.id)
    into tmp
    from rrl_sborka_pallets pts
   where pts.transtask_id = tt_id;
  return tmp;
exception
  when no_data_found then
    return 0;
end;

function stoim_pall_sb( pall_uid1 varchar2 ) return number is
  price1 number;
  total1 number;
  stoim_of_current_row number;
  cursor ss is
    select * from rrl_sborka_pallet_rows rs where rs.pallet_uid = pall_uid1;
begin
  total1 := 0;
  for r in ss loop
    stoim_of_current_row := 0;
    if r.prihod_pallet_uid is not null then
      begin
        select pts.price into price1 from rrl_pallets pts where pts.uid_pallet = r.prihod_pallet_uid;
        stoim_of_current_row := r.quantity * price1;
      exception
        when no_data_found then
          null;
      end;
    end if;

    if stoim_of_current_row = 0 then
      begin
        select art.last_price into price1 from rrl_articuls art where art.acticul = r.articul;
        stoim_of_current_row := r.quantity * price1;
      exception
        when no_data_found then
          stoim_of_current_row := 1;
      end;
    end if;

    total1 := total1 + stoim_of_current_row;
  end loop;
  return total1;
end;

function stoim_tt( tt_id int ) return number is
  total1 number;
begin
  select sum(stoim_pall_sb(pts.pallet_uid))
    into total1
    from rrl_sborka_pallets pts
   where pts.transtask_id = tt_id;
  return total1;
end;

function tt_wares( tt_id int ) return varchar2 is
  tmp varchar2(1024);
  cursor sss is
    select distinct RRL_SKLADNAME_BY_ID(pts.ware_id) g
      from rrl_sborka_pallets pts
     where pts.transtask_id = tt_id;
begin
  tmp := '';
  for i in sss loop
    tmp := tmp || to_char(i.g) || ' ';
  end loop;
  return tmp;
exception
  when no_data_found then
    return '';
  when others then
    return tmp;
end;

function test1 return int is
  curr_pr number;
  cursor arts is select acticul from rrl_articuls;
begin
  for a in arts loop
    begin
      select price
        into curr_pr
        from (
          select pts.articul, pts.price
            from rrl_pallets pts
           where pts.articul = a.acticul
             and price > 0
           order by pts.creation_date desc
        )
       where rownum <= 1;
      update rrl_articuls set last_price = curr_pr where acticul = a.acticul;
    exception
      when no_data_found then
        null;
    end;
  end loop;
  return 1;
end;

function TT_READY_PERC( IDTT int ) return number is
  tmpVar number;
  itogo int;
  sobrano int;
begin
  tmpVar := 0;
  select count(ID) into itogo from RABAEV.RRL_SBORKA_PALLETS where TRANSTASK_ID = IDTT;
  select count(ID)
    into sobrano
    from RABAEV.RRL_SBORKA_PALLETS P
   where TRANSTASK_ID = IDTT
     and (P.prooved = 1 or P.prooved_by_scan = 1 or P.condition = 2);
  if itogo = 0 then
    return 0;
  end if;
  tmpVar := sobrano / itogo;
  return tmpVar;
exception
  when no_data_found then
    return -1;
end;

function TT_UNREADY_COUNT( IDTT int ) return number is
  tmpVar number;
  itogo int;
  sobrano int;
begin
  tmpVar := 0;
  select count(ID) into itogo from RABAEV.RRL_SBORKA_PALLETS where TRANSTASK_ID = IDTT;
  select count(ID)
    into sobrano
    from RABAEV.RRL_SBORKA_PALLETS P
   where TRANSTASK_ID = IDTT
     and (P.prooved = 1 or P.prooved_by_scan = 1 or P.condition = 2);
  tmpVar := itogo - sobrano;
  return tmpVar;
exception
  when no_data_found then
    return -1;
end;

function tt_unready_wares( tt_id int ) return varchar2 is
  tmp varchar2(1024);
  cursor sss is
    select RRL_SKLADNAME_BY_ID(pts.ware_id) g, count(pts.pallet_uid) cnt
      from rrl_sborka_pallets pts
     where pts.transtask_id = tt_id
       and not (prooved = 1 or prooved_by_scan = 1 or condition = 2)
     group by RRL_SKLADNAME_BY_ID(pts.ware_id);
begin
  tmp := '';
  for i in sss loop
    tmp := tmp || to_char(i.g) || '=[' || to_char(i.cnt) || '] ';
  end loop;
  return tmp;
exception
  when no_data_found then
    return '!';
  when others then
    return tmp;
end;

function TT_VODITEL_TEL( VODITEL_ID1 int ) return varchar2 is
  tmpVar varchar2(255);
begin
  select VV.Tel into tmpVar from RABAEV.RRL_TR_VODITEL VV where ID = VODITEL_ID1;
  return tmpVar;
exception
  when no_data_found then
    return '';
end;

function TT_REORDER_ADR( IDTT int ) return number is
begin
  return RABAEV.RRL_TT_REORDER_ADR(IDTT);
exception
  when no_data_found then
    return 0;
end TT_REORDER_ADR;

function RRL_PALLETS_STR( ST_NUMBER1 varchar2 ) return varchar2 is
  tmp varchar2(4000);
  cnt number;
begin
  tmp := '';
  for r in (
    select distinct pallet_number
      from rrl_sborka_pallets
     where st_number = ST_NUMBER1
       and pallet_number is not null
     order by pallet_number
  ) loop
    if length(tmp) > 0 then
      tmp := tmp || ',';
    end if;
    tmp := tmp || to_char(r.pallet_number);
  end loop;

  if tmp is not null and length(tmp) > 0 then
    return tmp;
  end if;

  select count(pallet_uid)
    into cnt
    from rrl_sborka_pallets
   where st_number = ST_NUMBER1;

  return to_char(cnt);
exception
  when no_data_found then
    return '';
end;

function RRL_TT_PALLETS_STR( IDTT int ) return varchar2 is
begin
  return to_char(RABAEV.RRL_TT_PALLETS(IDTT));
exception
  when no_data_found then
    return '0';
end;

function TT_TIME_OF_OTG( IDTT int ) return date is
  ret date;
begin
  select cast(max(h.event_time) as date)
    into ret
    from RRL_TRANSPORT_TASK_HISTORY h
   where h.ttask_id = IDTT
     and h.operation = 'VERIFY_SECURITY';
  return ret;
exception
  when no_data_found then
    return null;
end;

function SERVICE_LEVEL_OTG( IDTT int ) return number is
  fact_time date;
  plan_time date;
begin
  fact_time := TT_TIME_OF_OTG(IDTT);
  select shipment_time into plan_time from RRL_TRANSPORT_TASK where ID = IDTT;

  if fact_time is null or plan_time is null then
    return null;
  end if;

  return round((fact_time - plan_time) * 24 * 60);
exception
  when no_data_found then
    return null;
end;

function VODITEL_GET_INN( VOD_ID int ) return varchar2 is
  ret varchar2(20);
begin
  select inn into ret from RRL_TR_VODITEL_EXT where vod_id = VOD_ID;
  return ret;
exception
  when no_data_found then
    return '';
end;

function VODITEL_GET_TABEL_NUMB( VOD_ID int ) return varchar2 is
  ret varchar2(50);
begin
  select tabel_no into ret from RRL_TR_VODITEL_EXT where vod_id = VOD_ID;
  return ret;
exception
  when no_data_found then
    return '';
end;

function VODITEL_SET_TABEL_NUMB( vod_id int, tabel_numb1 varchar2, inn1 varchar2 ) return int is
  vod_exists int;
begin
  select count(*) into vod_exists from RRL_TR_VODITEL where ID = vod_id;
  if vod_exists = 0 then
    return -1;
  end if;

  merge into RRL_TR_VODITEL_EXT dst
  using (
    select vod_id as vod_id, tabel_numb1 as tabel_no, inn1 as inn from dual
  ) src
  on (dst.vod_id = src.vod_id)
  when matched then
    update set dst.tabel_no = src.tabel_no,
               dst.inn = src.inn,
               dst.last_upd = sysdate
  when not matched then
    insert (vod_id, tabel_no, inn, last_upd)
    values (src.vod_id, src.tabel_no, src.inn, sysdate);

  return 1;
exception
  when others then
    return -2;
end;

begin
  null;
end TRANSPORT_TASK;
/

